	@Transactional
	public void updateFormId(Integer oldFormId, Integer newFormId) {
		//校验新旧FormID是否属于同一个版式(FormKey)
		if (!checkFormId(oldFormId, newFormId)) {
			throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "请检查【原板式ID】和【新板式ID】是否属于同一个版式");
		}
		// contract_city_company_info 表中 form_id 和 second_form_id 两个字段都会存储模板，因此更新 form_id 时需要同时更新这两个字段
		contractCityCompanyInfoService.updateFormId(oldFormId, newFormId);
		contractCityCompanyInfoService.updateSecondFormId(oldFormId, newFormId);
		contractCityCompanyInfoService.updateThirdFormId(oldFormId, newFormId);
		//协议平台配置表对应配置增加
		List<ContractProtocolConfig> newContractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(newFormId);
		if (newContractProtocolConfig.size() > 0) {
			LOGGER.info("协议平台配置表对应配置已存在，无需增加，newFormId:{}", newFormId);
			return;
		}
		List<ContractProtocolConfig> oldContractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(oldFormId);
		if (oldContractProtocolConfig.isEmpty()) {
			return;
		}
		oldContractProtocolConfig.forEach(config -> {
			config.setFormId(newFormId);
			config.setId(null);
		});
		//检查formKey与formId是否匹配
		checkContractProtocolConfig(oldContractProtocolConfig);
		contractProtocolConfigService.insertBatch(oldContractProtocolConfig);
	}

	public List<OptionVo> getCityList() {
		List<OptionVo> optionVoList = new LinkedList<>();
		CityEnum.getMap().forEach((gbCode, cityName) -> {
			optionVoList.add(OptionVo.builder()
				.value(gbCode)
				.label(cityName).build());
		});
		return optionVoList;
	}

	public List<OptionVo> getContractTypeList() {
		List<OptionVo> optionVoList = new LinkedList<>();
		ContractTypeEnum.getMap().forEach((type, typeName) -> {
			optionVoList.add(OptionVo.builder()
				.value(type.intValue())
				.label(typeName).build());
		});
		return optionVoList;
	}

	public List<OptionVo> getContractTypeList(Byte businessType) {
		List<OptionVo> optionVoList = new LinkedList<>();
		List<ContractTypeEnum> contractListByBusinessType = contractApolloConfig.getContractTypeListByBusinessType(businessType);
		contractListByBusinessType.forEach(contractTypeEnum -> optionVoList.add(OptionVo.builder()
			.value(contractTypeEnum.getCode().intValue())
			.label(contractTypeEnum.getName()).build()));
		return optionVoList;
	}

	@Transactional
	public void createConfig(CityCreateConfigReq request, String ucId, String userName) {
		Byte processMode = null;
		if (request.getProcessMode() != null) {
			processMode = request.getProcessMode();
		}
		List<ContractCityCompanyInfo> configList = contractCityCompanyInfoService.getConfig(
			request.getGbCode(),
			request.getCompanyCode(),
			request.getBusinessType(),
			request.getContractType().byteValue(),
			request.getSignChannelType(), null, processMode);

		configList.forEach(config -> {
			if (config.getGbCode() != CityEnum.CESHICHENG.getGbCode() && config.getUserSignType().contains(request.getUserSignType()) && config.getProcessMode().equals(request.getProcessMode())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前用户签约方式已经存在");
			}
		});

		//校验参数
		checkParams(request);

		ContractCityCompanyInfo config = new ContractCityCompanyInfo();
		BeanUtils.copyProperties(request, config, "showPlatform");
		//复制配置复用新建接口，主键不为空会导致新建时主键冲突
		config.setId(null);
		config.setShowPlatform(String.join(",", request.getShowPlatform()));
		dealDefaultConfig(config, request);
		contractCityCompanyInfoService.insert(config);
		//批量更新审批配置
		updateAuditConfig(config, request.isAuditConfigUnified());
		sendConfigMessage(request.getGbCode(), request.getCompanyCode(), request.getBusinessType(), ConfigOperationTypeEnum.CREATE.getCode(), Long.valueOf(ucId), JsonUtil.toJsonString(request));
	}

	@Transactional
	public void updateConfig(CityCreateConfigReq request, String ucId, String userName) {
		Byte processMode = null;
		if (request.getProcessMode() != null) {
			processMode = request.getProcessMode();
		}
		List<ContractCityCompanyInfo> configList = contractCityCompanyInfoService.getConfig(
			request.getGbCode(),
			request.getCompanyCode(),
			request.getBusinessType(),
			request.getContractType().byteValue(),
			request.getSignChannelType(), null, processMode);

		configList.forEach(config -> {
			if (config.getGbCode() != CityEnum.CESHICHENG.getGbCode() && config.getUserSignType().contains(request.getUserSignType()) && !config.getId().equals(request.getId()) && config.getProcessMode().equals(request.getProcessMode())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前用户签约方式已经存在");
			}
		});

		//校验参数
		checkParams(request);
		//协议平台配置表字段同步增加
		addProtocolConfig(request);

		ContractCityCompanyInfo config = new ContractCityCompanyInfo();
		BeanUtils.copyProperties(request, config, "showPlatform");
		dealDefaultConfig(config, request);
		config.setShowPlatform(String.join(",", request.getShowPlatform()));
		if (StringUtils.isBlank(config.getSecondFormKey()) && (config.getSecondFormId() == null || config.getSecondFormId() == 0)) {
			contractCityCompanyInfoService.clearSecondFormKeyAndId(config.getId());
		}
		if (StringUtils.isBlank(config.getThirdFormKey()) && (config.getThirdFormId() == null || config.getThirdFormId() == 0)) {
			contractCityCompanyInfoService.clearThirdFormKeyAndId(config.getId());
		}
		contractCityCompanyInfoService.update(config);
		dealMergeLaunchType(config);
		//批量更新审批配置
		updateAuditConfig(config, request.isAuditConfigUnified());
		sendConfigMessage(request.getGbCode(), request.getCompanyCode(), request.getBusinessType(), ConfigOperationTypeEnum.UPDATE.getCode(), Long.valueOf(ucId), JsonUtil.toJsonString(request));
	}

	/**
	 * version,processMode默认值处理
	 *
	 * @param config
	 * @param request
	 */
	private void dealDefaultConfig(ContractCityCompanyInfo config, CityCreateConfigReq request) {
		//预发环境测试城市版本号由于存在多个，不做版本号处理，数据插入时处理
		if (request.getGbCode().equals(CityEnum.CESHICHENG.getGbCode())) {
			return;
		}
		config.setVersion(1);
		if ((CityEnum.BEIJING.getGbCode() != request.getGbCode() || BusinessTypeEnum.REFORM_ALL.getCode().equals(config.getBusinessType())) && ProcessModeEnum.模式2_5.getMode().equals(request.getProcessMode())) {
			//非北京地区，模式2.5版本号为2,后续迭代配置平台，支持版本自定义
			config.setVersion(2);
		}
		if (request.getProcessMode() == null) {
			config.setProcessMode(ProcessModeEnum.模式2_0.getMode());
			if (CityEnum.BEIJING.getGbCode() == request.getGbCode()) {
				//北京默认为2.5
				config.setProcessMode(ProcessModeEnum.模式2_5.getMode());
			}
		}
		//2.5模式下，合同类型为正式合同或者变更合同，其配置的合并发起类型为7,8
		if (ProcessModeEnum.模式2_5.getMode().equals(config.getProcessMode())
			&& Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PACKAGE_CHANGE.getCode()).contains(Byte.valueOf(String.valueOf(config.getContractType())))) {
			//2.5版本合并发起类型为7,8
			config.setMergeLaunchType("7,8");
		} else {
			config.setMergeLaunchType("");
		}
	}

	public void dealMergeLaunchType(ContractCityCompanyInfo config) {
		//测试城市不处理
		if (config.getGbCode().equals(CityEnum.CESHICHENG.getGbCode())) {
			return;
		}
		contractCityCompanyInfoService.updateMergeLaunchType(config);
	}


