	private void addProtocolConfigToDB(String formKey, Integer oldFormId, Integer newFormId) {
		List<ContractProtocolConfig> contractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(newFormId);
		if (!contractProtocolConfig.isEmpty()) {
			LOGGER.info("协议平台配置表对应配置已存在，无需增加，newFormId:{}", newFormId);
			return;
		}
		List<ContractProtocolConfig> oldContractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(oldFormId);
		// 旧版式的协议字段为空，不需要继承（secondForm 场景下，初始版式为空）
		if (oldContractProtocolConfig.isEmpty()) {
			return;
		}
		// 如果新的 formKey、formId 为空，不需要继承协议字段（secondForm 场景下，可能会给这两个字段置空）
		if (StringUtils.isBlank(formKey) || newFormId == null || newFormId == 0) {
			return;
		}
		oldContractProtocolConfig.forEach(config -> {
			config.setFormId(newFormId);
			config.setFormKey(formKey);
			config.setId(null);
		});
		contractProtocolConfigService.insertBatch(oldContractProtocolConfig);
	}

	private void checkParams(CityCreateConfigReq request) {
		//校验分公司是否注册
		if (!freeformService.checkCompanyRegister(request.getSealCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "该分公司统一社会信用编码没有在协议平台注册, 请注册后再操作");
		}

		// 校验认购合同、设计合同字段配置必填
		if ((ContractTypeEnum.SUBSCRIBE.getCode().equals(request.getContractType().byteValue()) || ContractTypeEnum.DESIGN.getCode().equals(request.getContractType().byteValue()))
			&& StringUtils.isBlank(request.getFieldsMap())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "字段配置不能为空");
		}
		// 校验 formId、formKey 是否匹配
		checkFormKeyAndFormId(request.getFormKey(), request.getFormId());
		// 校验 secondFormId、secondFormKey 是否匹配
		checkFormKeyAndFormId(request.getSecondFormKey(), request.getSecondFormId());
		// 校验 thirdFormId、thirdFormKey 是否匹配
		checkFormKeyAndFormId(request.getThirdFormKey(), request.getThirdFormId());

		// 先判断当前业务场景下，secondForm 是否有意义（是否存在对应类型）
//		boolean secondFormTypeExist = FormTypeEnum.isSecondFormTypeExist(request.getBusinessType(), request.getProcessMode());
//		if (!secondFormTypeExist) {
//			// 如果当前场景下，没有 secondForm 对应的类型，则不需要存储
//			request.setSecondFormId(null);
//			request.setSecondFormKey(null);
//		} else {
//			if (StringUtils.isNotBlank(request.getSecondFormKey()) || (request.getSecondFormId() != null && request.getSecondFormId() != 0)) {
//				// 校验 secondFormId、secondFormKey 是否匹配
//				checkFormKeyAndFormId(request.getSecondFormKey(), request.getSecondFormId());
//			}
//		}
		byte auditType = request.getAuditType().byteValue();
		boolean containsBeforeOrAfter =
			AuditTypeEnum.BEFORE_SIGN.getCode().equals(auditType) || AuditTypeEnum.AFTER.getCode().equals(auditType);
		// 设计合同+整装+2.5流程，可能有设计费审核，不兼容签前审核或签后
		if (designFeeAuditService.isDesignSceneAndHouse(request.getContractType().byteValue(), request.getBusinessType())
			&& ProcessModeEnum.模式2_5.getMode().equals(request.getProcessMode())
			&& containsBeforeOrAfter) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "设计合同整装2.5场景,不支持签前审核/签后审核");
		}
		// 选择签前审核/签后审核时，校验审核配置不能为空
		List<Byte> notCheckAuditType = Arrays.asList(ContractTypeEnum.PACKAGE_CHANGE.getCode(), ContractTypeEnum.SUPPLEMENT.getCode(), ContractTypeEnum.SETTLEMENT.getCode());
		if (containsBeforeOrAfter && !notCheckAuditType.contains(request.getContractType().byteValue())) {
			String auditConfig = request.getAuditConfig();
			if (StringUtils.isBlank(auditConfig)) {
				throw new NrsBusinessException("已选择签前审核/签后审核，审核配置不能为空");
			}
			List<AuditConfigDTO> auditConfigDTOS;
			try {
				auditConfigDTOS = JsonUtil.toObject(auditConfig, new TypeReference<List<AuditConfigDTO>>() {
				});
			} catch (Exception e) {
				throw new NrsBusinessException("审核配置 JSON 解析异常，请检查格式!");
			}
			if (auditConfigDTOS.isEmpty()) {
				throw new NrsBusinessException("已选择签前审核/签后审核，审核配置不能为空");
			}
		}
	}

