	public void updateComboConfigAll(ContractComboCreateConfigReq request) {

		comboInfoPreCheck(request);

		ContractComboInfo contractComboInfo = contractComboInfoService.getLatestContractComboInfo(request.getComboCode(), request.getContractFormType());
		if (ObjectUtils.isEmpty(contractComboInfo)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "未找到改套餐材料配置信息");
		}
		contractComboInfo.setComboCode(request.getComboCode());
		contractComboInfo.setContractFormType(request.getContractFormType());
		contractComboInfo.setComboName(request.getComboName());
		ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();

		parallelTaskService.addNewTask(parallelTasksContext, () -> {
			LOGGER.info("开始处理精装细则");
			//处理精装细则
			if (Objects.nonNull(request.getDecorateRulePdf()) && !request.getDecorateRulePdf().isEmpty()) {
