			} else {
				contractComboInfo.setMaterialList(request.getMaterialList());
				List<String> imageUrlList = StringUtils.isNotBlank(request.getMaterialList()) ? Arrays.asList(request.getMaterialList().split(",")) : null;
				contractComboInfo.setMaterialListPdfUrl(imageToPdfAndUpload(imageUrlList));
			}
			LOGGER.info("处理材料配送清单完成");
		});
		parallelTaskService.execTasks(parallelTasksContext);
		parallelTaskService.awaitTasksResult(parallelTasksContext);

		contractComboInfo.setMaterialListContractTypes(StringUtils.join(request.getMaterialListContractTypes(), ","));
		contractComboInfo.setDecorateRuleContractTypes(StringUtils.join(request.getDecorateRuleContractTypes(), ","));
		contractComboInfo.setBudgetDescContractTypes(StringUtils.join(request.getBudgetDescContractTypes(), ","));
