	/**
	 * 校验配置完整度
	 *
	 * @param gbCode
	 * @param companyCode
	 * @param businessType
	 * @return
	 */
	public Boolean checkConfigComplete(Integer gbCode, String companyCode, Byte businessType) {
		List<ContractCityCompanyInfo> configList = contractCityCompanyInfoService.getConfig(gbCode, companyCode, businessType);
		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			return configList.size() >= 9;
		} else if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
			return configList.size() >= 7;
		} else if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			return configList.size() >= 1;
		} else if (BusinessTypeEnum.PART_DECORATE.getCode().equals(businessType)) {
			return configList.size() >= 9;
		}
		return false;
	}

