	public PageInfo<ContractAttachConfigInfo> searchContractAttachConfig(Integer gbCode, String companyCode, Byte contractFormType, Integer pageSize, Integer currentPage) {
		List<ContractAttachConfigInfo> resultList = new ArrayList<>();
		Example example = new Example(ContractAttachConfig.class);
		Example.Criteria criteria = example.createCriteria();
		criteria.andEqualTo(ContractAttach.Fields.delStatus, CommonEnum.NO.getCode());
		if (gbCode != null) {
			criteria.andEqualTo("gbCode", gbCode);
		}
		if (StringUtils.isNotBlank(companyCode)) {
			criteria.andEqualTo("companyCode", companyCode);
		}
		if (contractFormType != null) {
			criteria.andEqualTo("contractFormType", contractFormType);
		}
		// 这里查询后在 groupingBy 时，Map 的 key 需要设置为 "gbCode&companyCode&合同模式"
		List<ContractAttachConfig> contractAttachConfigList = contractAttachConfigService.getContractAttachConfigByExample(example);
		//contractAttachConfigList 按gbCode,companyCode分组
		Map<String, List<ContractAttachConfig>> collectMap = contractAttachConfigList.stream().collect(Collectors.groupingBy(item -> item.getGbCode() + "&" + item.getCompanyCode() + "&" + item.getContractFormType()));
		//遍历collectMap
		for (Map.Entry<String, List<ContractAttachConfig>> entry : collectMap.entrySet()) {
			String[] split = entry.getKey().split("&");
			Integer gbCodeTemp = Integer.valueOf(split[0]);
			String companyCodeTemp = split.length > 1 ? split[1] : "";
			Byte contractFormTypeTemp = Byte.valueOf(split[2]);
			List<ContractAttachConfig> contractAttachConfigTemp = contractAttachConfigService.getContractAttachConfig(gbCodeTemp, companyCodeTemp, contractFormTypeTemp);

			String servicePromise = contractAttachConfigTemp.stream().filter(item -> ContractAttachTypeEnum.SERVICE_PROMISE.getCode().equals(item.getAttachType()))
				.map(ContractAttachConfig::getImageUrl)
				.collect(Collectors.joining(","));
			List<String> servicePromiseContractTypes = contractAttachConfigTemp.stream().filter(item -> ContractAttachTypeEnum.SERVICE_PROMISE.getCode().equals(item.getAttachType()))
				.map(ContractAttachConfig::getContractTypes)
				.findFirst().map(contractTypes -> Arrays.asList(contractTypes.split(",")))
				.orElse(Collections.emptyList());

			String valuationExplanation = contractAttachConfigTemp.stream().filter(item -> ContractAttachTypeEnum.VALUATION_EXPLANATION.getCode().equals(item.getAttachType()))
				.map(ContractAttachConfig::getImageUrl)
				.collect(Collectors.joining(","));
			String personalSignNotification = contractAttachConfigTemp.stream().filter(item -> ContractAttachTypeEnum.PERSONAL_SIGN_NOTIFICATION.getCode().equals(item.getAttachType()))
				.map(ContractAttachConfig::getImageUrl)
				.collect(Collectors.joining(","));
			String categoryInformation = contractAttachConfigTemp.stream().filter(item -> ContractAttachTypeEnum.CATEGORY_INFORMATION.getCode().equals(item.getAttachType()))
				.map(ContractAttachConfig::getImageUrl)
				.collect(Collectors.joining(","));
			String groupCategoryInformation = contractAttachConfigTemp.stream().filter(item -> ContractAttachTypeEnum.GROUP_CATEGORY_INFORMATION.getCode().equals(item.getAttachType()))
				.map(ContractAttachConfig::getImageUrl)
				.collect(Collectors.joining(","));
			String installationAndDelivery = contractAttachConfigTemp.stream().filter(item -> ContractAttachTypeEnum.INSTALLATION_AND_DELIVERY.getCode().equals(item.getAttachType()))
				.map(ContractAttachConfig::getImageUrl)
				.collect(Collectors.joining(","));
			String durationDescriptionAttach = contractAttachConfigTemp.stream().filter(item -> ContractAttachTypeEnum.DURATION_DESCRIPTION_ATTACH.getCode().equals(item.getAttachType()))
				.map(ContractAttachConfig::getImageUrl)
				.collect(Collectors.joining(","));


			resultList.add(ContractAttachConfigInfo.builder()
				.id(contractAttachConfigTemp.get(0).getId())
				.gbCode(gbCodeTemp)
				.gbName(CityEnum.getNameByCode(gbCodeTemp))
				.companyCode(companyCodeTemp)
				.contractFormType(contractFormTypeTemp)
				.contractFormTypeName(ContractFormTypeEnum.getTypeByCode(contractFormTypeTemp))
				.servicePromise(servicePromise)
				.servicePromiseContractTypes(servicePromiseContractTypes)
				.valuationExplanation(valuationExplanation)
				.personalSignNotification(personalSignNotification)
				.categoryInformation(categoryInformation)
				.groupCategoryInformation(groupCategoryInformation)
				.installationAndDelivery(installationAndDelivery)
				.durationDescriptionAttach(durationDescriptionAttach)
				.createUserId(contractAttachConfigTemp.get(0).getCreateUserId())
				.ctime(contractAttachConfigTemp.get(0).getCtime())
				.build());
		}
		// 按id倒序
		resultList.sort(Comparator.comparing(ContractAttachConfigInfo::getId).reversed());
		// 手动分页
		int total = resultList.size();
		List<ContractAttachConfigInfo> pagedRecords = PageUtil.paginateList(resultList, pageSize, currentPage);
		// 创建 PageInfo 对象
		PageInfo<ContractAttachConfigInfo> pageInfo = new PageInfo<>(pagedRecords);
		pageInfo.setTotal(total);
		pageInfo.setPageSize(pageSize);
		pageInfo.setPageNum(currentPage);
		return pageInfo;
	}


