	public void buildContractAttachConfigList(List<String> urlList, List<String> contractTypes, Integer gbCode, String companyCode, Byte contractFormType, ContractAttachTypeEnum contractAttachTypeEnum, String ucid, List<ContractAttachConfig> result) {
		if (CollectionUtils.isEmpty(urlList)) {
			return;
		}

		String attachContractTypes = CollectionUtils.isEmpty(contractTypes) ? "" : String.join(",", contractTypes);
		for (String url : urlList) {
			result.add(ContractAttachConfig.builder()
				.gbCode(gbCode)
				.companyCode(companyCode)
				.contractFormType(contractFormType)
				.contractTypes(attachContractTypes)
				.attachType(contractAttachTypeEnum.getCode())
				.imageUrl(url)
				.createUserId(ucid)
				.updateUserId(ucid)
				.ctime(new Date())
				.mtime(new Date())
				.delStatus(CommonEnum.NO.getCode())
				.build());
		}
	}


	/**
	 * @param paramPdfUrl 参数中原始pdf的url
	 */
	public PdfToImageAndUploadDTO pdfToImageAndUpload(String paramPdfUrl) {
		checkUrl(paramPdfUrl);
		LOGGER.info("pdf校验通过 ：{}", paramPdfUrl);
		List<String> pdfToImageList = pdfToImageService.pdf2ImagePublicParallel(paramPdfUrl);
		File file = null;
		String tempPath = UUID.randomUUID() + ".pdf";
		try {
			file = contractPdfFileHandleService.downloadFileFromUrl(paramPdfUrl, tempPath);
			String[] urlString = paramPdfUrl.split("\\?");
			String[] strings = urlString[0].split("/");
			String fileObjectKey = s3Service.md5FileName(org.springframework.util.StringUtils.stripFilenameExtension(strings[strings.length - 1])) + ".pdf";
			String reUploadPdfPath = s3Service.uploadPublic(Files.readAllBytes(file.toPath()), fileObjectKey);
			return PdfToImageAndUploadDTO.builder()
				.imageUrlList(pdfToImageList)
				.reUploadPdfPath(reUploadPdfPath)
				.build();
		} catch (IOException e) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "pdf转图片失败");
		} finally {
			// 删除临时文件
			ContractPdfFileHandleService.cleanUp(Collections.singletonList(tempPath));
		}
	}

	private void checkUrl(String paramPdfUrl) {
		if (StringUtils.isBlank(contractApolloConfig.getCheckUrl())) {
			return;
		}
		if (!paramPdfUrl.startsWith(contractApolloConfig.getCheckUrl())) {
			throw new IllegalArgumentException("pdfUrl不合法:" + paramPdfUrl);
		}
	}


	/**
	 * 根据pdfUrl获取pdf文件大小
	 *
	 * @param pdfUrl 示例：http://storage.lianjia.com/nrs-sales-project-public/f5716db0ce319789c76373a09c0c42331736153462989.pdf
	 * @return
	 */
	public BigDecimal getPdfSize(String pdfUrl) {
		if (StringUtils.isBlank(pdfUrl)) {
			return new BigDecimal(0);
		}
		long fileSizeByUrl = 0;
		try {
			fileSizeByUrl = IOUtils.getFileSizeByUrl(pdfUrl);
		} catch (IOException e) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "根据pdfUrl获取pdf文件大小失败");
		}
		// 将文件大小转换为KB并保留两位小数
		return new BigDecimal(fileSizeByUrl)
			.divide(new BigDecimal(1024), 2, RoundingMode.HALF_UP);
	}

	/**
	 * 图片转pdf并上传s3
	 *
	 * @param imageUrlList 图片url列表
	 * @return pdf文件url
	 */
	public String imageToPdfAndUpload(List<String> imageUrlList) {
		if (CollectionUtils.isEmpty(imageUrlList)) {
			return "";
		}
		String tempPath = UUID.randomUUID() + ".pdf";
		try {
			ContractPdfFileHandleService.createPdfFromImages(tempPath, imageUrlList);
			String fileObjectKey = s3Service.md5FileName(UUID.randomUUID().toString()) + ".pdf";
			return s3Service.uploadPublic(Files.readAllBytes(Paths.get(tempPath)), fileObjectKey);
		} catch (IOException e) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "图片转pdf并上传s3失败");
		} finally {
			// 删除临时文件
			ContractPdfFileHandleService.cleanUp(Collections.singletonList(tempPath));
		}
	}


