@Transactional
public void updateFormId(Integer oldFormId, Integer newFormId) {
	//校验新旧FormID是否属于同一个版式(FormKey)
	if (!checkFormId(oldFormId, newFormId)) {
		throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "请检查【原板式ID】和【新板式ID】是否属于同一个版式");
	}
	// contract_city_company_info 表中 form_id 和 second_form_id 两个字段都会存储模板，因此更新 form_id 时需要同时更新这两个字段
	contractCityCompanyInfoService.updateFormId(oldFormId, newFormId);
	contractCityCompanyInfoService.updateSecondFormId(oldFormId, newFormId);
	contractCityCompanyInfoService.updateThirdFormId(oldFormId, newFormId);
	//协议平台配置表对应配置增加
	List<ContractProtocolConfig> newContractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(newFormId);
	if (newContractProtocolConfig.size() > 0) {
		LOGGER.info("协议平台配置表对应配置已存在，无需增加，newFormId:{}", newFormId);
		return;
	}
	List<ContractProtocolConfig> oldContractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(oldFormId);
	if (oldContractProtocolConfig.isEmpty()) {
		return;
	}
	oldContractProtocolConfig.forEach(config -> {
		config.setFormId(newFormId);
		config.setId(null);
	});
	//检查formKey与formId是否匹配
	checkContractProtocolConfig(oldContractProtocolConfig);
	contractProtocolConfigService.insertBatch(oldContractProtocolConfig);
}

