		}
	});

	//校验参数
	checkParams(request);

	ContractCityCompanyInfo config = new ContractCityCompanyInfo();
	BeanUtils.copyProperties(request, config, "showPlatform");
	//复制配置复用新建接口，主键不为空会导致新建时主键冲突
	config.setId(null);
	config.setShowPlatform(String.join(",", request.getShowPlatform()));
	dealDefaultConfig(config, request);
	contractCityCompanyInfoService.insert(config);
	//批量更新审批配置
	updateAuditConfig(config, request.isAuditConfigUnified());
	sendConfigMessage(request.getGbCode(), request.getCompanyCode(), request.getBusinessType(), ConfigOperationTypeEnum.CREATE.getCode(), Long.valueOf(ucId), JsonUtil.toJsonString(request));
}

