	private void addProtocolConfig(CityCreateConfigReq request) {
		Integer contractType = request.getContractType();
		if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType.byteValue())
			|| ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contractType.byteValue())) {
			return;
		}
		//id不为空，表示修改
		if (request.getId() != null) {
			String formKey = request.getFormKey();
			String secondFormKey = request.getSecondFormKey();
			String thirdFormKey = request.getThirdFormKey();
			ContractCityCompanyInfo oldConfig = contractCityCompanyInfoService.getConfig(request.getId());
			addProtocolConfigToDB(formKey, oldConfig.getFormId(), request.getFormId());
			addProtocolConfigToDB(secondFormKey, oldConfig.getSecondFormId(), request.getSecondFormId());
			addProtocolConfigToDB(thirdFormKey, oldConfig.getThirdFormId(), request.getThirdFormId());
			LOGGER.info("协议平台配置表对应配置已增加，newFormId:{}, newSecondFormId:{}, newThirdFormId:{}", request.getFormId(), request.getSecondFormId(), request.getThirdFormId());
		} else {
			// todo zqy 待优化：感觉不会走到这个分支，上线一段时间，如果查不到这条日志，可以将 else 分支移除
			LOGGER.info("addProtocolConfig() 的 else 分支是否走到");
			HashSet<Integer> formIds = new HashSet<>();
			formIds.add(request.getFormId());
			if (request.getSecondFormId() != null && request.getSecondFormId() != 0) {
				formIds.add(request.getSecondFormId());
			}
			if (request.getThirdFormId() != null && request.getThirdFormId() != 0) {
				formIds.add(request.getThirdFormId());
			}
			for (Integer formId : formIds) {
				List<ContractProtocolConfig> contractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(formId);
				if (contractProtocolConfig.isEmpty()) {
					LOGGER.error("河图合同配置新增，填写的formId未在协议平台配置表中配置，formId:{}", formId);
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "填写的formId:" + formId + "未在协议平台配置表中配置");
				}
			}
//			Integer formId = request.getFormId();
//			List<ContractProtocolConfig> contractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(formId);
//			if(contractProtocolConfig.isEmpty()) {
//				LOGGER.error("河图合同配置新增，填写的formId未在协议平台配置表中配置，formId:{}", formId);
//				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "填写的formId未在协议平台配置表中配置");
//			}
//			Integer secondFormId = request.getSecondFormId();
//			if (secondFormId != null && secondFormId != 0) {
//				List<ContractProtocolConfig> secondContractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(secondFormId);
//				if(secondContractProtocolConfig.isEmpty()) {
//					LOGGER.error("河图合同配置新增，填写的formId未在协议平台配置表中配置，secondFormId:{}", secondFormId);
//					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "填写的secondFormId未在协议平台配置表中配置");
//				}
//			}
		}
	}

private void addProtocolConfigToDB(String formKey, Integer oldFormId, Integer newFormId) {
	List<ContractProtocolConfig> contractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(newFormId);
	if (!contractProtocolConfig.isEmpty()) {
		LOGGER.info("协议平台配置表对应配置已存在，无需增加，newFormId:{}", newFormId);
		return;
	}
	List<ContractProtocolConfig> oldContractProtocolConfig = contractProtocolConfigService.getContractProtocolConfig(oldFormId);
	// 旧版式的协议字段为空，不需要继承（secondForm 场景下，初始版式为空）
	if (oldContractProtocolConfig.isEmpty()) {
		return;
	}
	// 如果新的 formKey、formId 为空，不需要继承协议字段（secondForm 场景下，可能会给这两个字段置空）
	if (StringUtils.isBlank(formKey) || newFormId == null || newFormId == 0) {
		return;
	}
	oldContractProtocolConfig.forEach(config -> {
		config.setFormId(newFormId);
		config.setFormKey(formKey);
		config.setId(null);
	});
	contractProtocolConfigService.insertBatch(oldContractProtocolConfig);
}

