public Page<CityConfigVo> getConfigList(Integer gbCode, Integer contractType, Integer businessType, String companyCode, String formKey, Integer formId, Integer pageSize, Integer currentPage, Integer processMode) {
	Example example = new Example(ContractCityCompanyInfo.class);
	Example.Criteria createCriteria = example.createCriteria().andEqualTo("delStatus", CommonEnum.NO.getCode());
	if (Objects.nonNull(gbCode)) {
		createCriteria.andEqualTo("gbCode", gbCode);
	}
	if (Objects.nonNull(contractType)) {
		createCriteria.andEqualTo("contractType", contractType);
	}
	if (Objects.nonNull(businessType)) {
		createCriteria.andEqualTo("businessType", businessType);
	}
	if (StringUtils.isNotBlank(companyCode)) {
		createCriteria.andEqualTo("companyCode", companyCode);
	}
	/**
	 * 根据 formKey、formId 召回符合条件的 secondForm、thirdForm
	 * where gbcode = :gbcode and (form_key = :form_key or second_form_key = :form_key or third_form_key = :form_key) and (form_id = :form_id or second_form_id = :form_id or third_form_id = :form_id)
	 */
	if (StringUtils.isNotBlank(formKey)) {
		example.and(example.createCriteria()
			.orEqualTo("formKey", formKey)
			.orEqualTo("secondFormKey", formKey)
			.orEqualTo("thirdFormKey", formKey)
		);
	}
	if (Objects.nonNull(formId)) {
		example.and(example.createCriteria()
			.orEqualTo("formId", formId)
			.orEqualTo("secondFormId", formId)
			.orEqualTo("thirdFormId", formId)
		);
	}
	if (Objects.nonNull(processMode)) {
		createCriteria.andEqualTo("processMode", processMode);
	}
	PageInfo<ContractCityCompanyInfo> pageInfo = contractCityCompanyInfoService.selectPageAndCountByExample(example, currentPage, pageSize);

	List<CityConfigVo> voList = new LinkedList<>();
	for (ContractCityCompanyInfo cityCompanyInfo : pageInfo.getList()) {
		List<String> userSignTypeTextList = new LinkedList<>();
		String[] userSignTypeList = cityCompanyInfo.getUserSignType().split(",");
		for (int i = 0; i < userSignTypeList.length; i++) {
			userSignTypeTextList.add(UserSignTypeEnum.getNameByCode(Byte.valueOf(userSignTypeList[i])));
		}

		CityConfigVo configVo = new CityConfigVo();
		BeanUtils.copyProperties(cityCompanyInfo, configVo);
		configVo.setAuditTypeText(AuditTypeEnum.getNameByCode(cityCompanyInfo.getAuditType().byteValue()));
		configVo.setContractTypeText(ContractTypeEnum.getNameByContractTypeAndBusinessType(cityCompanyInfo.getContractType().byteValue(), cityCompanyInfo.getBusinessType()));
		configVo.setUserSignTypeText(String.join(",", userSignTypeTextList));
		configVo.setGbName(CityEnum.getNameByCode(cityCompanyInfo.getGbCode()));
		configVo.setShowPlatform(Arrays.asList(cityCompanyInfo.getShowPlatform().split(",")));
		configVo.setShowPlatformText(cityCompanyInfo.getShowPlatform());
		configVo.setSignChannelType(cityCompanyInfo.getSignChannelType());
		configVo.setSignChannelTypeText(SignChannelTypeEnum.getNameByCode(cityCompanyInfo.getSignChannelType()));
		configVo.setAuditConfig(configVo.getAuditConfig());
		configVo.setBusinessType(cityCompanyInfo.getBusinessType().intValue());
		configVo.setBusinessTypeText(BusinessTypeEnum.getNameByCode(cityCompanyInfo.getBusinessType()));
		configVo.setProcessMode(cityCompanyInfo.getProcessMode());
		configVo.setProcessModeText(ProcessModeEnum.getDescByMode(cityCompanyInfo.getProcessMode()));
		configVo.setVersion(cityCompanyInfo.getVersion());
		voList.add(configVo);
	}
	Page<CityConfigVo> result = new Page<>();
	result.setCurrentPage(currentPage);
	result.setPageSize(pageSize);
	result.setTotal(pageInfo.getTotal());
	result.setTotalPage(pageInfo.getPages());
	result.setList(voList);
	return result;
}

