public void createComboConfig(ContractComboCreateConfigReq request) {
	request.setComboCode(request.getComboCode().trim());
	List<ContractComboInfo> contractComboInfos = contractComboInfoService.getContractComboInfo(request.getComboCode(), request.getContractFormType());
	if(CollectionUtils.isNotEmpty(contractComboInfos)){
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前套餐材料配置已经存在");
	}

	comboInfoPreCheck(request);

	ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		//转换pdf
		if (Objects.nonNull(request.getDecorateRulePdf()) && !request.getDecorateRulePdf().isEmpty()) {
			PdfToImageAndUploadDTO pdfToImageAndUploadDTO = pdfToImageAndUpload(request.getDecorateRulePdf().get(0));
			request.setDecorateRule(StringUtils.join(pdfToImageAndUploadDTO.getImageUrlList(), ","));
			request.setDecorateRulePdf(Lists.newArrayList(pdfToImageAndUploadDTO.getReUploadPdfPath()));
		}
	});
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		if (Objects.nonNull(request.getBudgetDescPdf()) && !request.getBudgetDescPdf().isEmpty()) {
			PdfToImageAndUploadDTO pdfToImageAndUploadDTO = pdfToImageAndUpload(request.getBudgetDescPdf().get(0));
			request.setBudgetDesc(StringUtils.join(pdfToImageAndUploadDTO.getImageUrlList(), ","));
			request.setBudgetDescPdf(Lists.newArrayList(pdfToImageAndUploadDTO.getReUploadPdfPath()));
		}
	});
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		if (Objects.nonNull(request.getMaterialListPdf()) && !request.getMaterialListPdf().isEmpty()) {
			PdfToImageAndUploadDTO pdfToImageAndUploadDTO = pdfToImageAndUpload(request.getMaterialListPdf().get(0));
			request.setMaterialList(StringUtils.join(pdfToImageAndUploadDTO.getImageUrlList(), ","));
			request.setMaterialListPdf(Lists.newArrayList(pdfToImageAndUploadDTO.getReUploadPdfPath()));
		}
	});
	parallelTaskService.execTasks(parallelTasksContext);
	parallelTaskService.awaitTasksResult(parallelTasksContext);

	ContractComboInfo contractComboInfo = ContractComboInfo.builder()
		.comboCode(request.getComboCode())
		.contractFormType(request.getContractFormType())
		.comboName(request.getComboName())
		.budgetDesc(request.getBudgetDesc())
		.decorateRule(request.getDecorateRule())
		.materialList(request.getMaterialList())
		.decorateRuleContractTypes(StringUtils.join(request.getDecorateRuleContractTypes(), ","))
		.budgetDescContractTypes(StringUtils.join(request.getBudgetDescContractTypes(), ","))
		.materialListContractTypes(StringUtils.join(request.getMaterialListContractTypes(), ","))

		.decorateRulePdfUrl(CollectionUtils.isNotEmpty(request.getDecorateRulePdf()) ? request.getDecorateRulePdf().get(0) : "")
		.budgetDescPdfUrl(CollectionUtils.isNotEmpty(request.getBudgetDescPdf()) ? request.getBudgetDescPdf().get(0) : "")
		.materialListPdfUrl(CollectionUtils.isNotEmpty(request.getMaterialListPdf()) ? request.getMaterialListPdf().get(0) : "")

		.decorateRulePdfSize(CollectionUtils.isNotEmpty(request.getDecorateRulePdf()) ? getPdfSize(request.getDecorateRulePdf().get(0)) : BigDecimal.ZERO)
		.budgetDescPdfSize(CollectionUtils.isNotEmpty(request.getBudgetDescPdf()) ? getPdfSize(request.getBudgetDescPdf().get(0)) : BigDecimal.ZERO)
		.materialListPdfSize(CollectionUtils.isNotEmpty(request.getMaterialListPdf()) ? getPdfSize(request.getMaterialListPdf().get(0)) : BigDecimal.ZERO)

		.budgetDesc(request.getBudgetDesc())
		.createUserId(getHetuCreateUcId())
		.delStatus(CommonEnum.NO.getCode()).build();
	contractComboInfoService.insert(contractComboInfo);
	// 异步生成材料配送清单 pdf
	CompletableFuture.runAsync(RunnableWrapper.of(() -> {
		try {
			comboInfoMaterialGenerator.generateAndReplaceMaterialList(Collections.singletonList(request.getComboCode()));
		} catch (Exception e) {
			LOGGER.info("套餐创建 - 生成材料配送清单失败，不阻塞主流程. comboCodes: {}", request.getComboCode(), e);
		}
	}));
}

