public void updateComboConfigAll(ContractComboCreateConfigReq request) {

	comboInfoPreCheck(request);

	ContractComboInfo contractComboInfo = contractComboInfoService.getLatestContractComboInfo(request.getComboCode(), request.getContractFormType());
	if (ObjectUtils.isEmpty(contractComboInfo)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "未找到改套餐材料配置信息");
	}
	contractComboInfo.setComboCode(request.getComboCode());
	contractComboInfo.setContractFormType(request.getContractFormType());
	contractComboInfo.setComboName(request.getComboName());
	ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();

	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		LOGGER.info("开始处理精装细则");
		//处理精装细则
		if (Objects.nonNull(request.getDecorateRulePdf()) && !request.getDecorateRulePdf().isEmpty()) {
			PdfToImageAndUploadDTO pdfToImageAndUploadDTO = pdfToImageAndUpload(request.getDecorateRulePdf().get(0));
			contractComboInfo.setDecorateRule(StringUtils.join(pdfToImageAndUploadDTO.getImageUrlList(), ","));
			contractComboInfo.setDecorateRulePdfUrl(pdfToImageAndUploadDTO.getReUploadPdfPath());
		} else {
			contractComboInfo.setDecorateRule(request.getDecorateRule());
			List<String> imageUrlList = StringUtils.isNotBlank(request.getDecorateRule()) ? Arrays.asList(request.getDecorateRule().split(",")) : null;
			contractComboInfo.setDecorateRulePdfUrl(imageToPdfAndUpload(imageUrlList));
		}
		LOGGER.info("处理精装细则完成");
	});

	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		LOGGER.info("开始处理预算编制说明");
		//处理预算编制说明
		if (Objects.nonNull(request.getBudgetDescPdf()) && !request.getBudgetDescPdf().isEmpty()) {
			PdfToImageAndUploadDTO pdfToImageAndUploadDTO = pdfToImageAndUpload(request.getBudgetDescPdf().get(0));
			contractComboInfo.setBudgetDesc(StringUtils.join(pdfToImageAndUploadDTO.getImageUrlList(), ","));
			contractComboInfo.setBudgetDescPdfUrl(pdfToImageAndUploadDTO.getReUploadPdfPath());
		} else {
			contractComboInfo.setBudgetDesc(request.getBudgetDesc());
			List<String> imageUrlList = StringUtils.isNotBlank(request.getBudgetDesc()) ? Arrays.asList(request.getBudgetDesc().split(",")) : null;
			contractComboInfo.setBudgetDescPdfUrl(imageToPdfAndUpload(imageUrlList));
		}
		LOGGER.info("处理预算编制说明完成");
	});

	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		LOGGER.info("开始处理材料配送清单");
		//处理材料配送清单
		if (Objects.nonNull(request.getMaterialListPdf()) && !request.getMaterialListPdf().isEmpty()) {
			PdfToImageAndUploadDTO pdfToImageAndUploadDTO = pdfToImageAndUpload(request.getMaterialListPdf().get(0));
			contractComboInfo.setMaterialList(StringUtils.join(pdfToImageAndUploadDTO.getImageUrlList(), ","));
			contractComboInfo.setMaterialListPdfUrl(pdfToImageAndUploadDTO.getReUploadPdfPath());
		} else {
			contractComboInfo.setMaterialList(request.getMaterialList());
			List<String> imageUrlList = StringUtils.isNotBlank(request.getMaterialList()) ? Arrays.asList(request.getMaterialList().split(",")) : null;
			contractComboInfo.setMaterialListPdfUrl(imageToPdfAndUpload(imageUrlList));
		}
		LOGGER.info("处理材料配送清单完成");
	});
	parallelTaskService.execTasks(parallelTasksContext);
	parallelTaskService.awaitTasksResult(parallelTasksContext);

	contractComboInfo.setMaterialListContractTypes(StringUtils.join(request.getMaterialListContractTypes(), ","));
	contractComboInfo.setDecorateRuleContractTypes(StringUtils.join(request.getDecorateRuleContractTypes(), ","));
	contractComboInfo.setBudgetDescContractTypes(StringUtils.join(request.getBudgetDescContractTypes(), ","));
	contractComboInfo.setDecorateRulePdfSize(StringUtils.isNotBlank(contractComboInfo.getDecorateRulePdfUrl()) ? getPdfSize(contractComboInfo.getDecorateRulePdfUrl()) : BigDecimal.ZERO);
	contractComboInfo.setBudgetDescPdfSize(StringUtils.isNotBlank(contractComboInfo.getBudgetDescPdfUrl()) ? getPdfSize(contractComboInfo.getBudgetDescPdfUrl()) : BigDecimal.ZERO);
	contractComboInfo.setMaterialListPdfSize(StringUtils.isNotBlank(contractComboInfo.getMaterialListPdfUrl()) ? getPdfSize(contractComboInfo.getMaterialListPdfUrl()) : BigDecimal.ZERO);
	contractComboInfo.setMtime(new Date());
	contractComboInfo.setCtime(new Date());
	contractComboInfo.setCreateUserId(getHetuCreateUcId());
	contractComboInfo.setId(null);
	contractComboInfoService.insertUnchecked(contractComboInfo);
}

