public PageInfo<ContractComboConfigVO> getComboInfoList(String comboCode, Byte contractFormType, String comboName, Integer pageSize, Integer currentPage) {
	Example example = new Example(ContractComboInfo.class);
	Example.Criteria createCriteria = example.createCriteria().andEqualTo("delStatus", CommonEnum.NO.getCode());
	if (StringUtils.isNotBlank(comboCode)) {
		createCriteria.andEqualTo("comboCode", comboCode);
	}
	if (contractFormType != null) {
		createCriteria.andEqualTo("contractFormType", contractFormType);
	}
	if (StringUtils.isNotBlank(comboName)) {
		createCriteria.andLike("comboName", String.format("%%%s%%", comboName));
	}
	// 获取所有符合条件的 comboCode 列表
	List<ContractComboInfo> allRecords = contractComboInfoService.selectByExample(example);
	Map<String, ContractComboInfo> latestRecordsMap = new HashMap<>();

	// 找到每个 comboCode + contractFormType 最新的一条记录
	for (ContractComboInfo record : allRecords) {
		String code = record.getComboCode() + "&" + record.getContractFormType();
		if (!latestRecordsMap.containsKey(code) || record.getCtime().after(latestRecordsMap.get(code).getCtime())) {
			latestRecordsMap.put(code, record);
		}
	}
	// 将最新的记录转换为列表
	List<ContractComboInfo> latestRecords = new ArrayList<>(latestRecordsMap.values());

	// 手动分页
	int total = latestRecords.size();
	int fromIndex = (currentPage - 1) * pageSize;
	int toIndex = Math.min(fromIndex + pageSize, total);
	List<ContractComboInfo> pagedRecords = latestRecords.subList(fromIndex, toIndex);

	// 创建 PageInfo 对象
	PageInfo<ContractComboConfigVO> pageInfo = new PageInfo<>(convertContractComboConfigVO(pagedRecords));
	pageInfo.setTotal(total);
	pageInfo.setPageSize(pageSize);
	pageInfo.setPageNum(currentPage);

	return pageInfo;
}

