public void checkFormKeyAndFormId(String formKey, Integer formId) {
	// 如果 formKey、formId 都为空，则不校验
	if (StringUtils.isBlank(formKey) && (formId == null || formId == 0)) {
		return;
	}
	if (formId == null) {
		String msg = "formKey和formId不匹配，请检查：formKey:".concat(formKey).concat(",formId：null");
		throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), msg);
	}
	CustomForm customForm = freeformService.queryCustomForm(formId);
	if (customForm == null) {
		String msg = "通过formId未获取到版式信息,请检查：formId:".concat(formId.toString());
		throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), msg);
	}
	if (!customForm.getFormKey().equals(formKey)) {
		String msg = "formKey和formId不匹配，请检查：formKey:".concat(formKey).concat(",formId:").concat(formId.toString());
		throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), msg);
	}
}

public boolean checkFormId(Integer oldFormId, Integer newFormId) {
	CustomForm customFormOld = freeformService.queryCustomForm(oldFormId);
	if (customFormOld == null) {
		String msg = "通过formId未获取到版式信息，请检查：formId:".concat(oldFormId.toString());
		throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), msg);
	}

	CustomForm customFormNew = freeformService.queryCustomForm(newFormId);
	if (customFormNew == null) {
		String msg = "通过formId未获取到版式信息，请检查：formId:".concat(newFormId.toString());
		throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), msg);
	}
	return customFormOld.getFormKey().equals(customFormNew.getFormKey());
}

