public void updateContractAttachConfig(ContractAttachConfigReq request) {
	Integer gbCode = request.getGbCode();
	String companyCode = StringUtils.isBlank(request.getCompanyCode()) ? "" : request.getCompanyCode();
	Byte contractFormType = request.getContractFormType();
	String ucId = getHetuCreateUcId();
	if (CollectionUtils.isEmpty(request.getServicePromisePdf())
		&& CollectionUtils.isEmpty(request.getValuationExplanationPdf())
		&& CollectionUtils.isEmpty(request.getPersonalSignNotificationPdf())
		&& CollectionUtils.isEmpty(request.getCategoryInformationPdf())
		&& CollectionUtils.isEmpty(request.getGroupCategoryInformationPdf())
		&& CollectionUtils.isEmpty(request.getInstallationAndDeliveryPdf())
		&& CollectionUtils.isEmpty(request.getDurationDescriptionAttachPdf())
		&& StringUtils.isBlank(request.getServicePromise())
		&& StringUtils.isBlank(request.getValuationExplanation())
		&& StringUtils.isBlank(request.getPersonalSignNotification())
		&& StringUtils.isBlank(request.getCategoryInformation())
		&& StringUtils.isBlank(request.getGroupCategoryInformation())
		&& StringUtils.isBlank(request.getInstallationAndDelivery())
		&& StringUtils.isBlank(request.getDurationDescriptionAttach())
	) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请至少上传一种附件");
	}
	//用户pdf上传后转的附件配置信息
	List<ContractAttachConfig> servicePromise = new ArrayList<>();
	List<ContractAttachConfig> valuationExplanation = new ArrayList<>();
	List<ContractAttachConfig> personalSignNotification = new ArrayList<>();
	List<ContractAttachConfig> categoryInformation = new ArrayList<>();
	List<ContractAttachConfig> groupCategoryInformation = new ArrayList<>();
	List<ContractAttachConfig> installationAndDelivery = new ArrayList<>();
	List<ContractAttachConfig> durationDescriptionAttach = new ArrayList<>();

	ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();

	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		if (CollectionUtils.isNotEmpty(request.getServicePromisePdf())) {
			List<String> urlList = pdfToImageService.pdf2ImagePublicParallel(request.getServicePromisePdf().get(0));
			buildContractAttachConfigList(urlList, request.getServicePromiseContractTypes(), gbCode, companyCode, contractFormType, ContractAttachTypeEnum.SERVICE_PROMISE,ucId,  servicePromise);
		}
	});
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		if (CollectionUtils.isNotEmpty(request.getValuationExplanationPdf())) {
			List<String> urlList = pdfToImageService.pdf2ImagePublicParallel(request.getValuationExplanationPdf().get(0));
			buildContractAttachConfigList(urlList, null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.VALUATION_EXPLANATION,ucId,  valuationExplanation);
		}
	});
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		if (CollectionUtils.isNotEmpty(request.getPersonalSignNotificationPdf())) {
			List<String> urlList = pdfToImageService.pdf2ImagePublicParallel(request.getPersonalSignNotificationPdf().get(0));
			buildContractAttachConfigList(urlList, null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.PERSONAL_SIGN_NOTIFICATION,ucId,  personalSignNotification);
		}
	});
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		if (CollectionUtils.isNotEmpty(request.getCategoryInformationPdf())) {
			List<String> urlList = pdfToImageService.pdf2ImagePublicParallel(request.getCategoryInformationPdf().get(0));
			buildContractAttachConfigList(urlList, null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.CATEGORY_INFORMATION,ucId,  categoryInformation);
		}
	});

	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		if (CollectionUtils.isNotEmpty(request.getGroupCategoryInformationPdf())) {
			List<String> urlList = pdfToImageService.pdf2ImagePublicParallel(request.getGroupCategoryInformationPdf().get(0));
			buildContractAttachConfigList(urlList, null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.GROUP_CATEGORY_INFORMATION,ucId,  groupCategoryInformation);
		}
	});
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		if (CollectionUtils.isNotEmpty(request.getInstallationAndDeliveryPdf())) {
			List<String> urlList = pdfToImageService.pdf2ImagePublicParallel(request.getInstallationAndDeliveryPdf().get(0));
			buildContractAttachConfigList(urlList, null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.INSTALLATION_AND_DELIVERY,ucId,  installationAndDelivery);
		}
	});
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		if (CollectionUtils.isNotEmpty(request.getDurationDescriptionAttachPdf())) {
			List<String> urlList = pdfToImageService.pdf2ImagePublicParallel(request.getDurationDescriptionAttachPdf().get(0));
			buildContractAttachConfigList(urlList, null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.DURATION_DESCRIPTION_ATTACH,ucId,  durationDescriptionAttach);
		}
	});
	parallelTaskService.execTasks(parallelTasksContext);
	parallelTaskService.awaitTasksResult(parallelTasksContext);

	//如果同时存在pdf和图片url，优先取pdf转的图片信息
	if (CollectionUtils.isEmpty(servicePromise)&&StringUtils.isNotBlank(request.getServicePromise())){
		buildContractAttachConfigList(Arrays.asList(request.getServicePromise().split(",")), request.getServicePromiseContractTypes(), gbCode, companyCode, contractFormType, ContractAttachTypeEnum.SERVICE_PROMISE, getHetuCreateUcId(), servicePromise);
	}
	if (CollectionUtils.isEmpty(valuationExplanation) && StringUtils.isNotBlank(request.getValuationExplanation())) {
		buildContractAttachConfigList(Arrays.asList(request.getValuationExplanation().split(",")), null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.VALUATION_EXPLANATION, getHetuCreateUcId(), valuationExplanation);
	}
	if (CollectionUtils.isEmpty(personalSignNotification)&&StringUtils.isNotBlank(request.getPersonalSignNotification())){
		buildContractAttachConfigList(Arrays.asList(request.getPersonalSignNotification().split(",")), null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.PERSONAL_SIGN_NOTIFICATION, getHetuCreateUcId(), personalSignNotification);
	}
	if (CollectionUtils.isEmpty(categoryInformation)&&StringUtils.isNotBlank(request.getCategoryInformation())){
		buildContractAttachConfigList(Arrays.asList(request.getCategoryInformation().split(",")), null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.CATEGORY_INFORMATION, getHetuCreateUcId(), categoryInformation);
	}

	if (CollectionUtils.isEmpty(groupCategoryInformation)&&StringUtils.isNotBlank(request.getGroupCategoryInformation())){
		buildContractAttachConfigList(Arrays.asList(request.getGroupCategoryInformation().split(",")), null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.GROUP_CATEGORY_INFORMATION, getHetuCreateUcId(), groupCategoryInformation);
	}
	if (CollectionUtils.isEmpty(installationAndDelivery)&&StringUtils.isNotBlank(request.getInstallationAndDelivery())){
		buildContractAttachConfigList(Arrays.asList(request.getInstallationAndDelivery().split(",")), null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.INSTALLATION_AND_DELIVERY, getHetuCreateUcId(), installationAndDelivery);
	}
	if (CollectionUtils.isEmpty(durationDescriptionAttach)&&StringUtils.isNotBlank(request.getDurationDescriptionAttach())){
		buildContractAttachConfigList(Arrays.asList(request.getDurationDescriptionAttach().split(",")), null, gbCode, companyCode, contractFormType, ContractAttachTypeEnum.DURATION_DESCRIPTION_ATTACH, getHetuCreateUcId(), durationDescriptionAttach);
	}

	List<ContractAttachConfig> addAttachConfigList = new ArrayList<>();
	addAttachConfigList.addAll(servicePromise);
	addAttachConfigList.addAll(valuationExplanation);
	addAttachConfigList.addAll(personalSignNotification);
	addAttachConfigList.addAll(categoryInformation);
	addAttachConfigList.addAll(groupCategoryInformation);
	addAttachConfigList.addAll(installationAndDelivery);
	addAttachConfigList.addAll(durationDescriptionAttach);
	//更新数据库数据
	adminServiceSelf.updateContractAttachConfigDB(addAttachConfigList, gbCode, companyCode, contractFormType);

}

