public BigDecimal getPdfSize(String pdfUrl) {
	if (StringUtils.isBlank(pdfUrl)) {
		return new BigDecimal(0);
	}
	long fileSizeByUrl = 0;
	try {
		fileSizeByUrl = IOUtils.getFileSizeByUrl(pdfUrl);
	} catch (IOException e) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "根据pdfUrl获取pdf文件大小失败");
	}
	// 将文件大小转换为KB并保留两位小数
	return new BigDecimal(fileSizeByUrl)
		.divide(new BigDecimal(1024), 2, RoundingMode.HALF_UP);
}

