@Slf4j
@Service
public class ChangeContractService {
	public static final String HAVE_AGENT = "haveAgent";
	@Resource
	ContractService contractService;
	@Resource
	ContractLogService contractLogService;
	@Resource
	ContractFieldService contractFieldService;
	@Resource
	ContractUserService contractUserService;
	@Resource
	ContractFieldChangeRecordService contractFieldChangeRecordService;
	@Resource
	QuotationFeignService quotationFeignService;
	@Resource
	ContractStatusLogService contractStatusLogService;
	@Resource
	BpmService bpmService;
	@Resource
	CommonContractService commonContractService;
	@Resource
	private ContractApolloConfig contractApolloConfig;
	@Resource
	private HomeAndPcCommonService homeAndPcCommonService;
	@Resource
	private ProjectInfoReadService projectInfoReadService;
	@Resource
	private ChangeOrderReadService changeOrderReadService;
	@Resource
	private ContractNodeService contractNodeService;
	@Resource
	private PcContractService pcContractService;
	@Resource
	private EventService eventService;
	@Resource
	private ContractAttachService contractAttachService;
	@Resource
	private CustomerFeignService customerFeignService;
	@Resource
	private ChangeOrderService changeOrderService;
	@Resource
	private ContractBusinessService contractBusinessService;
	@Resource
	private PdfToImageService pdfToImageService;
	@Resource
	private CommonBusinessService commonBusinessService;
	@Resource
	private ComboInfoService comboInfoService;
	@Resource
	private CipherService cipherService;
	@Resource
	private FundBaseService fundBaseService;
	@Resource
	private FundInfoService fundInfoService;
	@Resource
	private AthenaRpc athenaRpc;
	@Resource
	private ContractMaterialService contractMaterialService;
	@Resource
	private ContractCollectionPlanRecordService contractCollectionPlanRecordService;
	@Resource
	private ChangeContractKeyConfig changeContractKeyConfig;
	@Resource
	private QuotationRelationCommonService quotationRelationCommonService;
	@ApolloJsonValue("${sign.change.collectionPlan.orderId:[]}")
	private List<String> collectionPlanChangeOrderIds;

	/**
	 * 删除合同
	 *
	 * @param contractCode
	 * @return
	 */
	public Boolean deleteContract(String contractCode, Long operateUserId) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同不存在，请检查合同编号或联系客服");
		}

		if (contract.getStatus().equals(ContractStatusEnum.FINISH.getCode()) || contract.getStatus().equals(ContractStatusEnum.USER_CONFIRMED.getCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同已完成，不可删除");
		}
		String userName = homeAndPcCommonService.getOperatorName(operateUserId);
		contract.setDelStatus(CommonEnum.YES.getCode());
		quotationRelationCommonService.cancelContractRelations(contractCode);
		contractService.softDeleteById(contract.getId());
		contractLogService.createLog(contractCode, LogTypeEnum.DELETE.getCode(), LogTypeEnum.DELETE.getName(), "", operateUserId.toString(), userName);
		return true;
	}

	/**
	 * 字段详情
	 *
	 * @param contractCode
	 * @param projectOrderId
	 * @param changeOrderId
	 * @return
	 */
	public ChangeContractDetailResp fieldsDetail(String contractCode, String projectOrderId, String changeOrderId, Byte userSignType) {
		checkCanCreateOrEdit(changeOrderId);
		Contract currentContract = null;
		Contract prevContract = null;

		if (StringUtils.isNotBlank(contractCode)) {
			currentContract = contractService.getByContractCode(contractCode);
			prevContract = contractService.getChangePrevEffectContract(currentContract.getId(), currentContract.getProjectOrderId());
			changeOrderId = currentContract.getChangeOrderId();
			projectOrderId = currentContract.getProjectOrderId();
		} else {
			prevContract = contractService.getChangePrevEffectContractByPid(projectOrderId);
			currentContract = contractService.getValidChangeContract(projectOrderId, changeOrderId);
		}
		if (Objects.isNull(prevContract)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少上一份有效的合同");
		}

		List<ContractField> contractFieldList = null;
		if (Objects.nonNull(currentContract)) {
			contractFieldList = contractFieldService.getListByContractCode(currentContract.getContractCode());
		}

		//是否保存了签约主体
		boolean isObjectSaved = Objects.nonNull(currentContract);
		//是否保存了签约内容
		boolean isContentSaved = Objects.nonNull(contractFieldList) && contractFieldList.size() > 5;

		//合同内容
		ChangeContractDetailResp result = initChangeContractDetail(prevContract, currentContract, isObjectSaved, isContentSaved);
		//补充报价信息
		if (Objects.isNull(currentContract) || ContractStatusEnum.DRAFT.getCode().equals(currentContract.getStatus())) {
			fillPlanInfo(result, projectOrderId, changeOrderId);
		}
		//上一份合同
		fillPrevContract(result, prevContract);
		//补充变更范围
		fillChangeDetail(result, changeOrderId);

		if (Objects.isNull(result.getUserSignType())) {
			result.setUserSignType(userSignType);
		}
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		result.setBusinessType(commonContractService.getBusinessType(projectInfoDTO));

		//原合同为公对公 or 变更了主体，只能是线下签约
		if (!isContentSaved && (result.getChangeDetail().getIsChangeContractObjectType() || ContractObjectTypeEnum.COMPANY.getCode().equals(result.getPrevContract().getSignTypeInfo().getContractObjectType()))) {
			if (Objects.isNull(result.getSignTypeInfo())) {
				result.setSignTypeInfo(ZqSignTypeDTO.builder().signChannelType(SignChannelTypeEnum.OFFLINE.getCode()).build());
			} else {
				result.getSignTypeInfo().setSignChannelType(SignChannelTypeEnum.OFFLINE.getCode());
			}
		}
		//收款计划查询
		if (currentContract != null && StringUtils.isNotBlank(currentContract.getContractCode())) {
			CollectionPlanConfigInfo collectionPlanConfigInfo = null;
			try {
				collectionPlanConfigInfo = commonContractService.queryCollectionPlanByContract(currentContract);
				if (collectionPlanConfigInfo != null) {
					//获取最新的合同款金额
					BigDecimal contractPriceNow = athenaRpc.queryPlanInfo(projectOrderId).getPlanInfo().getContractPriceTotal();
					collectionPlanConfigInfo = fundBaseService.calculateCollectionPlan(collectionPlanConfigInfo, contractPriceNow);
				}
			} catch (Exception e) {
				LOGGER.error("变更合同字段详情接口获取收款计划失败,contractCode:{}", currentContract.getContractCode());
			}
			result.setCollectionPlanConfigInfo(collectionPlanConfigInfo);
		}
		return result;
	}

	/**
	 * 使用contract初始化详情
	 *
	 * @param prevContract
	 * @param currentContract
	 * @param
	 * @return
	 */
	private ChangeContractDetailResp initChangeContractDetail(Contract prevContract, Contract currentContract, Boolean isObjectSaved, Boolean isContentSaved) {
		ChangeContractDetailResp result = new ChangeContractDetailResp();

		//基本初始值，没有变更主体的时候
		result.setStatus(ContractStatusEnum.DRAFT.getCode());
		result.setContractStatus(ContractStatusEnum.DRAFT.getCode());
		result.setContractStatusText(ContractStatusEnum.DRAFT.getName());
		result.setType(ContractTypeEnum.PACKAGE_CHANGE.getCode());

		//优先使用草稿的数据
		if (Objects.nonNull(currentContract)) {
			ZqContractDetailResp currentResult = pcContractService.getZqContractDetail(currentContract.getProjectOrderId(), currentContract.getType(), currentContract.getContractCode(), false);
			BeanUtils.copyProperties(currentResult, result);
		}

		//使用上一份合同的数据: 只要内容没有修改，一定是要用到上一份合同来填充内容的。主体要不要填充要看isObjectSaved
		if (!isContentSaved) {
			ZqContractDetailResp prevResult = pcContractService.getZqContractDetail(prevContract.getProjectOrderId(), prevContract.getType(), prevContract.getContractCode(), false);
			if (!isObjectSaved) {
				//个人/公对公 线上/线下 线下合同列表
				result.setSignTypeInfo(prevResult.getSignTypeInfo());
				//公司名称-code  业主信息
				result.setSignInfo(prevResult.getSignInfo());
			}

			//填充内容
			result.setCustomerName(prevResult.getCustomerName());
			result.setAddress(prevResult.getAddress());
			result.setProjectInfo(prevResult.getProjectInfo());
			result.setPromiseInfo(prevResult.getPromiseInfo());
			result.setCenterControlType(prevResult.getCenterControlType());
			result.setConstructSchedule(prevResult.getConstructSchedule());
			result.setQuotation(prevResult.getQuotation());
			result.setGuaranteeInfo(prevResult.getGuaranteeInfo());
			result.setContractAttachList(prevResult.getContractAttachList());
		}

		return result;
	}

	private void fillPlanInfo(ChangeContractDetailResp result, String contractProjectOrderId, String changeOrderId) {

