	/**
	 * 对比合同整体
	 *
	 * @param prevExpandInfo
	 * @param currentExpandInfo
	 * @return
	 */
	private List<FieldDiffDTO> compareContract(Contract currentContract, FormalContractExpandInfoDTO prevExpandInfo, FormalContractExpandInfoDTO currentExpandInfo, String projectOrderId) {
		List<FieldDiffDTO> result = new LinkedList<>();
		// 加解密
		//加密
		encryptExpandInfo(prevExpandInfo);
		encryptExpandInfo(currentExpandInfo);
		//签约主体
		result.addAll(compareContractSignObject(prevExpandInfo, currentExpandInfo));
		//业主信息
		result.addAll(compareContractCustomer(prevExpandInfo, currentExpandInfo));
		//代理人
		result.addAll(compareContractAgent(prevExpandInfo, currentExpandInfo));
		//法人信息
		result.addAll(compareContractLegalUser(prevExpandInfo, currentExpandInfo));
		//户型结构
		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(currentContract.getBusinessType())) {
			result.addAll(compareContractCnt(prevExpandInfo, currentExpandInfo));
		}
		//其他 - 房屋类型、装修类型等
		result.addAll(compareContractOther(prevExpandInfo, currentExpandInfo));
		//甲供材料
		result.addAll(compareContractMaterial(prevExpandInfo.getMaterialList(), currentExpandInfo.getMaterialList()));
		//比较收款计划
		result.addAll(compareCollectionPlan(prevExpandInfo.getCollectionPlanConfigInfo(), currentExpandInfo.getCollectionPlanConfigInfo(), projectOrderId, null));
		return result;
	}


	public List<FieldDiffDTO> compareCollectionPlan(CollectionPlanConfigInfo prevCollectionPlan, CollectionPlanConfigInfo curCollectionPlan, String projectOrderId, Byte businessType) {
		List<FieldDiffDTO> result = new LinkedList<>();
		//判断两收款计划是否相同
		boolean isDiff = prevCollectionPlan.diff(curCollectionPlan);
		if (!isDiff || collectionPlanChangeOrderIds.contains(projectOrderId)) {
			boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, ContractTypeEnum.PACKAGE_CHANGE.getCode());
			List<String> pre;
			List<String> cur = new ArrayList<>();
			if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) || processV25) {
				pre = prevCollectionPlan.getContent().stream().map(m -> m.getLastPayNode().concat("，").concat(m.getPrice().toPlainString()).concat("元")).collect(Collectors.toList());
				cur = curCollectionPlan.getContent().stream().map(m -> m.getLastPayNode().concat("，").concat(m.getPrice().toPlainString()).concat("元")).collect(Collectors.toList());
				result.add(FieldDiffDTO.builder()
					.fieldKey("collectionPlanConfigInfo")
					.fieldName("收款计划")
					.oldValue(String.join("\n", pre))
					.newValue(String.join("\n", cur))
					.build());
			} else {
				pre = prevCollectionPlan.getContent().stream().map(CollectionPlanItem::itemSimpleShow).collect(Collectors.toList());
				cur = curCollectionPlan.getContent().stream().map(CollectionPlanItem::itemSimpleShow).collect(Collectors.toList());
				result.add(FieldDiffDTO.builder()
					.fieldKey("collectionPlan")
					.fieldName("收款计划")
					.oldValue(String.join("\n", pre))
					.newValue(String.join("\n", cur))
					.build());
			}

		}
		return result;
	}

	public void encryptExpandInfo(FormalContractExpandInfoDTO expandInfoDTO) {
		List<String> collect = Stream.of(expandInfoDTO.getOwnerPhone(), expandInfoDTO.getOwnerCertificateNo(), expandInfoDTO.getAgentPhone(), expandInfoDTO.getAgentCertificateNo(),
				expandInfoDTO.getCompanyAgentPhone(), expandInfoDTO.getCompanyAgentCertificateNo(), expandInfoDTO.getLegalPhone(), expandInfoDTO.getLegalCertificateNo())
			.filter(StringUtils::isNotBlank).distinct().collect(Collectors.toList());
		Map<String, String> encryptMap = cipherService.encrypt(collect);

		expandInfoDTO.setOwnerPhone(encryptMap.getOrDefault(expandInfoDTO.getOwnerPhone(), expandInfoDTO.getOwnerPhone()));
		expandInfoDTO.setOwnerCertificateNo(encryptMap.getOrDefault(expandInfoDTO.getOwnerCertificateNo(), expandInfoDTO.getOwnerCertificateNo()));
		expandInfoDTO.setAgentPhone(encryptMap.getOrDefault(expandInfoDTO.getAgentPhone(), expandInfoDTO.getAgentPhone()));
		expandInfoDTO.setAgentCertificateNo(encryptMap.getOrDefault(expandInfoDTO.getAgentCertificateNo(), expandInfoDTO.getAgentCertificateNo()));
		expandInfoDTO.setCompanyAgentPhone(encryptMap.getOrDefault(expandInfoDTO.getCompanyAgentPhone(), expandInfoDTO.getCompanyAgentPhone()));
		expandInfoDTO.setCompanyAgentCertificateNo(encryptMap.getOrDefault(expandInfoDTO.getCompanyAgentCertificateNo(), expandInfoDTO.getCompanyAgentCertificateNo()));
		expandInfoDTO.setLegalPhone(encryptMap.getOrDefault(expandInfoDTO.getLegalPhone(), expandInfoDTO.getLegalPhone()));
		expandInfoDTO.setLegalCertificateNo(encryptMap.getOrDefault(expandInfoDTO.getLegalCertificateNo(), expandInfoDTO.getLegalCertificateNo()));
	}

	/**
	 * 对比签约主体a
	 *
	 * @param prevExpandInfo
	 * @param currentExpandInfo
	 * @return
	 */
	public List<FieldDiffDTO> compareContractSignObject(FormalContractExpandInfoDTO prevExpandInfo, FormalContractExpandInfoDTO currentExpandInfo) {
		List<FieldDiffDTO> result = new LinkedList<>();
		if (!Objects.equals(prevExpandInfo.getContractObjectType(), currentExpandInfo.getContractObjectType())) {
			result.add(FieldDiffDTO.builder()
				.fieldKey("contractObjectType")
				.fieldName("主体类型")
				.oldValue(ContractObjectTypeEnum.getNameByCode(prevExpandInfo.getContractObjectType()))
				.newValue(ContractObjectTypeEnum.getNameByCode(currentExpandInfo.getContractObjectType()))
				.build()
			);
		}
		if (!Objects.equals(prevExpandInfo.getSignChannelType(), currentExpandInfo.getSignChannelType())) {
			result.add(FieldDiffDTO.builder()
				.fieldKey("signChannelType")
				.fieldName("签约形式")
				.oldValue(SignChannelTypeEnum.getNameByCode(prevExpandInfo.getSignChannelType()))
				.newValue(SignChannelTypeEnum.getNameByCode(currentExpandInfo.getSignChannelType()))
				.build()
			);
		}
		if (!Objects.equals(prevExpandInfo.getUserSignType(), currentExpandInfo.getUserSignType())) {
			result.add(FieldDiffDTO.builder()
				.fieldKey("userSignType")
				.fieldName("签署方式")
				.oldValue(UserSignTypeEnum.getNameForDiffByCode(prevExpandInfo.getUserSignType()))
				.newValue(UserSignTypeEnum.getNameForDiffByCode(currentExpandInfo.getUserSignType()))
				.build()
			);
		}

		if (!Objects.equals(prevExpandInfo.getAttachFileType(), currentExpandInfo.getAttachFileType())) {
			result.add(FieldDiffDTO.builder()
				.fieldKey("attachFileType")
				.fieldName("上传合同类型")
				.oldValue(FileTypeEnum.getFileTypeNameByKey(prevExpandInfo.getAttachFileType()))
				.newValue(FileTypeEnum.getFileTypeNameByKey(currentExpandInfo.getAttachFileType()))
				.build()
			);
		}

		List<File> preAttachUrl = prevExpandInfo.getAttachUrl().stream().map(item -> {
			item.setType(prevExpandInfo.getAttachFileType());
			return item;
		}).collect(Collectors.toList());
		List<File> curAttachUrl = currentExpandInfo.getAttachUrl().stream().map(item -> {
			item.setType(currentExpandInfo.getAttachFileType());
			return item;
		}).collect(Collectors.toList());
		List<String> preAttachUrlList = preAttachUrl.stream().map(File::getUrl).collect(Collectors.toList());
		List<String> curAttachUrlList = curAttachUrl.stream().map(File::getUrl).collect(Collectors.toList());
		//线下合同是否相同
		boolean attachUrlEqual = preAttachUrlList.containsAll(curAttachUrlList) && curAttachUrlList.containsAll(preAttachUrlList);
		//线下合同不相同并且至少有一个不为空
		if (!attachUrlEqual && (CollectionUtils.isNotEmpty(preAttachUrl) || CollectionUtils.isNotEmpty(curAttachUrl))) {
			result.add(FieldDiffDTO.builder()
				.fieldKey("attachUrl")
				.fieldName("上传全套盖章合同")
				.oldValue(JSON.toJSONString(prevExpandInfo.getAttachUrl()))
				.newValue(JSON.toJSONString(currentExpandInfo.getAttachUrl()))
				.build()
			);
		}

		if (!Objects.equals(prevExpandInfo.getUserSignTime(), currentExpandInfo.getUserSignTime())) {
