	/**
	 * 对比甲供材料
	 *
	 * @param prevMaterialList
	 * @param currentMaterialList
	 * @return
	 */
	public List<FieldDiffDTO> compareContractMaterial(List<MaterialItemVo> prevMaterialList, List<MaterialItemVo> currentMaterialList) {
		List<FieldDiffDTO> result = new LinkedList<>();

		boolean isDiff = false;
		if (prevMaterialList.size() != currentMaterialList.size()) {
			isDiff = true;
		} else {
			//数量一致的话，对比里面的明细
			Map<Integer, MaterialItemVo> prevMaterialMap = prevMaterialList.stream().collect(Collectors.toMap(MaterialItemVo::getValue, e -> e, (v1, v2) -> v2));
			for (MaterialItemVo materialItemVo : currentMaterialList) {
				if (!prevMaterialMap.containsKey(materialItemVo.getValue())) {
					isDiff = true;
					break;
				}
				MaterialItemVo prevMaterial = prevMaterialMap.get(materialItemVo.getValue());
				if (!Objects.equals(prevMaterial.getUnit(), materialItemVo.getUnit())
					|| !Objects.equals(prevMaterial.getDescription(), materialItemVo.getDescription())) {
					isDiff = true;
					break;
				}
			}
		}

		if (isDiff) {
			result.add(FieldDiffDTO.builder()
				.fieldKey("materialList")
				.fieldName("甲供材料")
				.oldValue(buildMaterialString(prevMaterialList))
				.newValue(buildMaterialString(currentMaterialList))
				.build()
			);
		}
		return result;
	}

