	private String buildMaterialString(List<MaterialItemVo> materialList) {
		List<String> materialStringList = new LinkedList<>();
		for (MaterialItemVo materialItemVo : materialList) {
			materialStringList.add(materialItemVo.getDescription());
		}
		return String.join("\n", materialStringList);
	}


