	/**
	 * 获取合同的差异结果-带分类信息(只包括两部分主体、内容)
	 *
	 * @param projectOrderId
	 * @param orderChangeId
	 * @return
	 */
	public ContractDiffResultDTO getContractDiffWithSection(String projectOrderId, String orderChangeId) {
		Contract contract = contractService.getChangeContract(projectOrderId, orderChangeId);
		if (Objects.isNull(contract)) {
			return null;
		}
		ContractDiffResultDTO contractDiffResultDTO = getContractDiffWithSection(contract.getContractCode());
		Boolean isChangePrice = changePriceScope(orderChangeId);
		Boolean isChangeDiscount = changeDiscountScope(orderChangeId);
		if (isChangePrice || isChangeDiscount) {
			CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectOrderId);
			QuotationDiffResultDTO quotationDiffResultDTO = quotationFeignService.queryQuotationDiffResult(coordinationProjectOrder.getProjectOrderId(), orderChangeId);
			Map<String, FieldDiffDTO> map = quotationFeignService.getQutationDiffMap(quotationDiffResultDTO);
			if (Objects.nonNull(map.get(QuotationDiffFieldEnum.CONTRACT_PRICE.getKey()))) {
				contractDiffResultDTO.getContentDiff().add(map.get(QuotationDiffFieldEnum.CONTRACT_PRICE.getKey()));
			}
		}
		return contractDiffResultDTO;
	}

	/**
	 * 获取合同的差异结果-带分类信息(只包括两部分主体、内容)
	 *
	 * @param contractCode
	 * @return
	 */
	public ContractDiffResultDTO getContractDiffWithSection(String contractCode) {
		ContractDiffResultDTO diffResultDTO = new ContractDiffResultDTO();
		List<FieldDiffDTO> signObjectDiff = new LinkedList<>();
		List<FieldDiffDTO> contentDiff = new LinkedList<>();

		List<ContractFieldChangeRecord> recordList = getContractDiff(contractCode);
		List<String> signObjectFields = Arrays.asList("contractObjectType", "ownerName", "ownerPhone", "ownerCertificateType", "ownerCertificateNo", "signChannelType", "companyName", "companyCreditCode");
		for (ContractFieldChangeRecord changeRecord : recordList) {
			String fieldKey = changeRecord.getFieldKey();
			FieldDiffDTO diffDTO = FieldDiffDTO.builder()
				.fieldKey(changeRecord.getFieldKey())
				.fieldName(changeRecord.getFieldName())
				.oldValue(changeRecord.getOldValue())
				.newValue(changeRecord.getNewValue())
				.build();
			if (signObjectFields.contains(fieldKey)) {
				signObjectDiff.add(diffDTO);
			} else {
				contentDiff.add(diffDTO);
			}
		}

		diffResultDTO.setSignObjectDiff(signObjectDiff);
		diffResultDTO.setContentDiff(contentDiff);
		return diffResultDTO;
	}


