	private List<ContractNode> getNodeListInfos(List<String> changeContractCodeList) {
		List<Byte> nodeTypeList = Lists.newArrayList();
		nodeTypeList.add(NodeTypeEnum.SUBMIT.getCode());
		nodeTypeList.add(NodeTypeEnum.USER_CONFIRM.getCode());
		nodeTypeList.add(NodeTypeEnum.COMPANY_SIGN.getCode());
