	/**
	 * @param contract
	 * @param contractNodeInfoList
	 * @return
	 * @desc 获取合同节点相关时间
	 */
	private List<ChangeContractListVo.ChangeContractListItemInfo> getContractInfoText(Contract contract, List<ContractNode> contractNodeInfoList) {
		Byte signChannelType = contract.getSignChannelType();
		String signChannelTypeDesc = SignChannelTypeEnum.getNameByCode(signChannelType);
		List<ChangeContractListVo.ChangeContractListItemInfo> contractInfoText = new ArrayList<>();
		ChangeContractListVo.ChangeContractListItemInfo changeContractListItemInfos = new ChangeContractListVo.ChangeContractListItemInfo("签约方式", signChannelTypeDesc);
		contractInfoText.add(changeContractListItemInfos);

		for (ContractNode contractNode : contractNodeInfoList) {
			if (!contract.getContractCode().equals(contractNode.getContractCode())) {
				continue;
			}
			String time = DateUtils.getFormatDateStr(new Date(contractNode.getFireTime()), DateUtils.DATE_SLASH);
			if (contractNode.getNodeType().equals(NodeTypeEnum.SUBMIT.getCode())) {
				ChangeContractListVo.ChangeContractListItemInfo changeContractSubmitInfo = new ChangeContractListVo.ChangeContractListItemInfo("生成时间", time);
				contractInfoText.add(changeContractSubmitInfo);
			}

			if (contractNode.getNodeType().equals(NodeTypeEnum.USER_CONFIRM.getCode())) {
				ChangeContractListVo.ChangeContractListItemInfo changeContractConfirmInfo = new ChangeContractListVo.ChangeContractListItemInfo("确认时间", time);
				contractInfoText.add(changeContractConfirmInfo);
			}

			if (contractNode.getNodeType().equals(NodeTypeEnum.COMPANY_SIGN.getCode())) {
				ChangeContractListVo.ChangeContractListItemInfo changeContractCompanySignInfo = new ChangeContractListVo.ChangeContractListItemInfo("签署时间", time);
				contractInfoText.add(changeContractCompanySignInfo);
			}
		}

		return contractInfoText;
	}

	/**
