	private String saveContractDraft(ZqContractReq body, Long createUserId) {
		Contract contract;
		homeAndPcCommonService.checkUnique(body.getProjectOrderId(), body.getChangeOrderId(), body.getContractCode(), body.getType());
		String contractCode = body.getContractCode();
		String userName = homeAndPcCommonService.getOperatorName(createUserId);
		if (StringUtils.isNotBlank(contractCode)) {
			pcContractService.deleteContractInfo(contractCode, false);
			quotationRelationCommonService.cancelContractRelations(contractCode);
		}
		contract = pcContractService.queryOrBuildContract(body, createUserId, userName);

		PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(body.getProjectOrderId(), body.getChangeOrderId());
		contract.setAmount(planAllDTO.getPlanInfo().getContractPriceTotal());
		contract.setStatus(ContractStatusEnum.DRAFT.getCode());
		//保存contract
		pcContractService.saveOrUpdateContract(contract);
		contractCode = contract.getContractCode();
		pcContractService.saveContractField(contractCode, body, createUserId, userName);
		pcContractService.saveContractUser(contractCode, body, createUserId, userName);
		pcContractService.saveContractAttach(contractCode, body, createUserId, userName);
		pcContractService.saveContractMaterial(contractCode, body, createUserId, userName);
		pcContractService.updateOrSaveContractNode(contractCode, body);
		contractDraftCollectionPlanSave(contractCode, body.getProjectOrderId(), body.getCollectionPlanInfo());
		//存合同对应变更计划
		return contract.getContractCode();
	}

	//变更合同的草稿关于收款计划快照保存
	private void contractDraftCollectionPlanSave(String contractCode, String projectOrderId, CollectionPlanConfigInfo collectionPlanInfo) {
		CollectionPlanConfigInfo collectionPlanConfigInfoForRecord;
		if (collectionPlanInfo != null) {
			collectionPlanConfigInfoForRecord = collectionPlanInfo;
		} else {
			//如果传入的收款计划为空，说明这次没有收款计划变更，当前合同要记录的收款计划其实是当前款项上保存的最新的收款计划
			FundInfo fundInfo = fundInfoService.getFundByOrderIdAndFundType(projectOrderId, FundTypeEnum.PROJECT_CHARGE.getValue());
			CollectionPlanConfigInfo collectionPlanInfoFromFund = JSON.parseObject(fundInfo.getCollectionPlan(), CollectionPlanConfigInfo.class);
			//获取最新的合同款金额
			BigDecimal contractPrice = athenaRpc.queryPlanInfo(projectOrderId).getPlanInfo().getContractPriceTotal();
			//计算收款计划每阶段金额
			collectionPlanConfigInfoForRecord = fundBaseService.calculateCollectionPlan(collectionPlanInfoFromFund, contractPrice);
		}
		//保存收款计划快照到【合同收款计划记录表】
		contractCollectionPlanRecordService.insertOrUpdate(ContractCollectionPlanRecord.builder()
			.collectionPlan(JSON.toJSONString(collectionPlanConfigInfoForRecord))
			.contractCode(contractCode)
			.build());
	}


	//只读字段（签约主体， 未写入pdf的字段，计划开工日期，优惠活动，优惠信息（不改报价的时候只读），线下合同（原合同为线下签约的））
	private ZqContractReq buildChangeContractDraft(ZqContractReq body) {
		if (StringUtils.isBlank(body.getChangeOrderId())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "变更单号不可为null");
		}
		List<Contract> draftChangeContracts = contractService.getDraftChangeContract(body.getProjectOrderId());
		if (CollectionUtils.isNotEmpty(draftChangeContracts)) {
			body.setContractCode(draftChangeContracts.get(0).getContractCode());
		}
		String projectOrderId = body.getProjectOrderId();
		Contract preEffectiveContract = contractService.getChangePrevEffectContractByPid(projectOrderId);

		ZqContractReq draft = new ZqContractReq();
		BeanUtils.copyProperties(body, draft);
		//上一份有效合同内容
		ZqContractDetailResp preDetail = pcContractService.getZqContractDetail(body.getProjectOrderId(), body.getType(), preEffectiveContract.getContractCode(), false);

		draft.setSignTypeInfo(preDetail.getSignTypeInfo());
		Byte signChannelType = body.getSignTypeInfo().getSignChannelType();
		Byte userSignType = body.getUserSignType();
		//如果是线下合同，强制把签署方式设置为正式签署
		if (SignChannelTypeEnum.OFFLINE.getCode().equals(signChannelType)) {
			userSignType = UserSignTypeEnum.SIGN.getCode();
		}
		draft.getSignTypeInfo().setSignChannelType(signChannelType);
		draft.getSignTypeInfo().setAttachUrl(body.getSignTypeInfo().getAttachUrl());
		draft.setUserSignType(userSignType);
		draft.setSignInfo(preDetail.getSignInfo());

		//可编辑的部分取最新值
		//主体部分 判断是否变更主体
		if (changeSignObjectScope(body.getChangeOrderId())) {
			ContractSignObjectDTO contractSignObjectDTO = getSignObject(body.getProjectOrderId(), body.getContractCode(), body.getChangeOrderId());
			Byte contractObjectType = contractSignObjectDTO.getContractObjectType();
			draft.getSignTypeInfo().setContractObjectType(contractObjectType);
			if (ContractObjectTypeEnum.PERSON.getCode().equals(contractObjectType)) {
				draft.getSignInfo().setOwnerName(contractSignObjectDTO.getOwnerName());
				draft.getSignInfo().setOwnerPhone(contractSignObjectDTO.getOwnerPhone());
				draft.getSignInfo().setOwnerCertificateNo(contractSignObjectDTO.getOwnerCertificateNo());
				draft.getSignInfo().setOwnerCertificateType(contractSignObjectDTO.getOwnerCertificateType());
				draft.getSignInfo().setOwnerAddress(contractSignObjectDTO.getOwnerAddress());
			} else {
				draft.getSignInfo().setCompanyCreditCode(contractSignObjectDTO.getCompanyCreditCode());
				draft.getSignInfo().setCompanyName(contractSignObjectDTO.getCompanyName());
			}
		}
		//内容部分
		//签约信息
		draft.getSignInfo().setHaveAgent(body.getSignInfo().getHaveAgent());
		draft.getSignInfo().setAgentName(body.getSignInfo().getAgentName());
		draft.getSignInfo().setAgentPhone(body.getSignInfo().getAgentPhone());
		draft.getSignInfo().setAgentCertificateNo(body.getSignInfo().getAgentCertificateNo());
		draft.getSignInfo().setAgentCertificateType(body.getSignInfo().getAgentCertificateType());

		draft.getSignInfo().setCompanyAgentName(body.getSignInfo().getCompanyAgentName());
		draft.getSignInfo().setCompanyAgentPhone(body.getSignInfo().getCompanyAgentPhone());
		draft.getSignInfo().setCompanyAgentCertificateNo(body.getSignInfo().getCompanyAgentCertificateNo());
		draft.getSignInfo().setCompanyAgentCertificateType(body.getSignInfo().getCompanyAgentCertificateType());

		//项目信息
		draft.setProjectInfo(preDetail.getProjectInfo());
		draft.getProjectInfo().setParlorCnt(body.getProjectInfo().getParlorCnt());
		draft.getProjectInfo().setRoomCnt(body.getProjectInfo().getRoomCnt());
		draft.getProjectInfo().setCookroomCnt(body.getProjectInfo().getCookroomCnt());
		draft.getProjectInfo().setToiletCnt(body.getProjectInfo().getToiletCnt());
		draft.getProjectInfo().setBalconyCnt(body.getProjectInfo().getBalconyCnt());
		draft.getProjectInfo().setStorageCnt(body.getProjectInfo().getStorageCnt());
		draft.getProjectInfo().setArea(body.getProjectInfo().getArea());
		draft.getProjectInfo().setStructure(body.getProjectInfo().getStructure());
		draft.getProjectInfo().setCertificateAddress(body.getProjectInfo().getCertificateAddress());
		draft.getProjectInfo().setPartRoomRange(body.getProjectInfo().getPartRoomRange());
		//承包约定
		draft.setPromiseInfo(preDetail.getPromiseInfo());
		if (Objects.nonNull(body.getPromiseInfo())) {
			draft.getPromiseInfo().setProjectContractModeCode(body.getPromiseInfo().getProjectContractModeCode());
			draft.getPromiseInfo().setProjectContractModeName(ProjectContractModeEnum.getNameByCode((body.getPromiseInfo().getProjectContractModeCode())));
			draft.getPromiseInfo().setDisputeDealMode(body.getPromiseInfo().getDisputeDealMode());
			draft.getPromiseInfo().setTaxRate(body.getPromiseInfo().getTaxRate());
			if (Objects.nonNull(body.getPromiseInfo().getMaterialList())) {
				draft.getPromiseInfo().setMaterialList(body.getPromiseInfo().getMaterialList());
			}
		}
		//工期
		draft.setConstructSchedule(preDetail.getConstructSchedule());
		return draft;
	}


