	public Boolean isChangeAgent(String contractCode, String projectOrderId) {
		Contract latestContract = contractService.getChangePrevEffectContractByPid(projectOrderId);
		ContractUser currentAgentUser = contractUserService.getUserByContractCodeAndType(contractCode, UserTypeEnum.AGENT.getCode());
		ContractUser prevAgentUser = contractUserService.getUserByContractCodeAndType(latestContract.getContractCode(), UserTypeEnum.AGENT.getCode());

		//相等都是null
		if (Objects.equals(currentAgentUser, prevAgentUser)) {
			return false;
		}

		//不相等有一个为null
		if (Objects.isNull(currentAgentUser) || Objects.isNull(prevAgentUser)) {
			return true;
		}

		return !Objects.equals(currentAgentUser.getCertificateType(), prevAgentUser.getCertificateType())
			|| !Objects.equals(currentAgentUser.getCertificateNo(), prevAgentUser.getCertificateNo())
			|| !Objects.equals(currentAgentUser.getName(), prevAgentUser.getName());
	}

	/**
	 * 比较项目信息
	 */
	public List<FieldDiffDTO> compareProjectInfo(FormalContractExpandInfoDTO prevExpandInfo, FormalContractExpandInfoDTO currentExpandInfo) {
		List<FieldDiffDTO> result = new LinkedList<>();
