public ChangeContractDetailResp fieldsDetail(String contractCode, String projectOrderId, String changeOrderId, Byte userSignType) {
	checkCanCreateOrEdit(changeOrderId);
	Contract currentContract = null;
	Contract prevContract = null;

	if (StringUtils.isNotBlank(contractCode)) {
		currentContract = contractService.getByContractCode(contractCode);
		prevContract = contractService.getChangePrevEffectContract(currentContract.getId(), currentContract.getProjectOrderId());
		changeOrderId = currentContract.getChangeOrderId();
		projectOrderId = currentContract.getProjectOrderId();
	} else {
		prevContract = contractService.getChangePrevEffectContractByPid(projectOrderId);
		currentContract = contractService.getValidChangeContract(projectOrderId, changeOrderId);
	}
	if (Objects.isNull(prevContract)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少上一份有效的合同");
	}

	List<ContractField> contractFieldList = null;
	if (Objects.nonNull(currentContract)) {
		contractFieldList = contractFieldService.getListByContractCode(currentContract.getContractCode());
	}

	//是否保存了签约主体
	boolean isObjectSaved = Objects.nonNull(currentContract);
	//是否保存了签约内容
	boolean isContentSaved = Objects.nonNull(contractFieldList) && contractFieldList.size() > 5;

	//合同内容
	ChangeContractDetailResp result = initChangeContractDetail(prevContract, currentContract, isObjectSaved, isContentSaved);
	//补充报价信息
	if (Objects.isNull(currentContract) || ContractStatusEnum.DRAFT.getCode().equals(currentContract.getStatus())) {
		fillPlanInfo(result, projectOrderId, changeOrderId);
	}
	//上一份合同
	fillPrevContract(result, prevContract);
	//补充变更范围
	fillChangeDetail(result, changeOrderId);

	if (Objects.isNull(result.getUserSignType())) {
		result.setUserSignType(userSignType);
	}
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
	result.setBusinessType(commonContractService.getBusinessType(projectInfoDTO));

	//原合同为公对公 or 变更了主体，只能是线下签约
	if (!isContentSaved && (result.getChangeDetail().getIsChangeContractObjectType() || ContractObjectTypeEnum.COMPANY.getCode().equals(result.getPrevContract().getSignTypeInfo().getContractObjectType()))) {
		if (Objects.isNull(result.getSignTypeInfo())) {
			result.setSignTypeInfo(ZqSignTypeDTO.builder().signChannelType(SignChannelTypeEnum.OFFLINE.getCode()).build());
		} else {
			result.getSignTypeInfo().setSignChannelType(SignChannelTypeEnum.OFFLINE.getCode());
		}
	}
	//收款计划查询
	if (currentContract != null && StringUtils.isNotBlank(currentContract.getContractCode())) {
		CollectionPlanConfigInfo collectionPlanConfigInfo = null;
		try {
			collectionPlanConfigInfo = commonContractService.queryCollectionPlanByContract(currentContract);
			if (collectionPlanConfigInfo != null) {
				//获取最新的合同款金额
				BigDecimal contractPriceNow = athenaRpc.queryPlanInfo(projectOrderId).getPlanInfo().getContractPriceTotal();
				collectionPlanConfigInfo = fundBaseService.calculateCollectionPlan(collectionPlanConfigInfo, contractPriceNow);
			}
		} catch (Exception e) {
			LOGGER.error("变更合同字段详情接口获取收款计划失败,contractCode:{}", currentContract.getContractCode());
		}
		result.setCollectionPlanConfigInfo(collectionPlanConfigInfo);
	}
	return result;
}

