private ChangeContractDetailResp initChangeContractDetail(Contract prevContract, Contract currentContract, Boolean isObjectSaved, Boolean isContentSaved) {
	ChangeContractDetailResp result = new ChangeContractDetailResp();

	//基本初始值，没有变更主体的时候
	result.setStatus(ContractStatusEnum.DRAFT.getCode());
	result.setContractStatus(ContractStatusEnum.DRAFT.getCode());
	result.setContractStatusText(ContractStatusEnum.DRAFT.getName());
	result.setType(ContractTypeEnum.PACKAGE_CHANGE.getCode());

	//优先使用草稿的数据
	if (Objects.nonNull(currentContract)) {
		ZqContractDetailResp currentResult = pcContractService.getZqContractDetail(currentContract.getProjectOrderId(), currentContract.getType(), currentContract.getContractCode(), false);
		BeanUtils.copyProperties(currentResult, result);
	}

	//使用上一份合同的数据: 只要内容没有修改，一定是要用到上一份合同来填充内容的。主体要不要填充要看isObjectSaved
	if (!isContentSaved) {
		ZqContractDetailResp prevResult = pcContractService.getZqContractDetail(prevContract.getProjectOrderId(), prevContract.getType(), prevContract.getContractCode(), false);
		if (!isObjectSaved) {
			//个人/公对公 线上/线下 线下合同列表
			result.setSignTypeInfo(prevResult.getSignTypeInfo());
			//公司名称-code  业主信息
			result.setSignInfo(prevResult.getSignInfo());
		}

		//填充内容
		result.setCustomerName(prevResult.getCustomerName());
		result.setAddress(prevResult.getAddress());
		result.setProjectInfo(prevResult.getProjectInfo());
		result.setPromiseInfo(prevResult.getPromiseInfo());
		result.setCenterControlType(prevResult.getCenterControlType());
		result.setConstructSchedule(prevResult.getConstructSchedule());
		result.setQuotation(prevResult.getQuotation());
		result.setGuaranteeInfo(prevResult.getGuaranteeInfo());
		result.setContractAttachList(prevResult.getContractAttachList());
	}

	return result;
}

