private void fillPlanInfo(ChangeContractDetailResp result, String contractProjectOrderId, String changeOrderId) {

	//补充优惠
	PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(contractProjectOrderId, changeOrderId);
	if (Objects.isNull(planAllDTO)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少最新的报价信息");
	}
	BigDecimal discountAmount = null;
	String discountDesc = "";
	List<ZqDiscountVo.CouponDTO> couponDTOList = new LinkedList<>();
	ZqDiscountVo.ActivityDTO activityDTO = null;
	String quotePdfUrl = null;
	String downloadQuotePdfUrl = null;
	for (CouponDTO couponDTO : planAllDTO.getCouponList()) {
		if (CouponTypeEnum.DIRECT_COUPON.getCode().equals(couponDTO.getCouponType())) {
			discountAmount = couponDTO.getLapseAmount();
			discountDesc = couponDTO.getRemark();
		}
	}
	for (PlanAttachmentDTO planAttachmentDTO : planAllDTO.getPlanAttachmentList()) {
		if (Objects.equals(50, planAttachmentDTO.getFileType())) {
			quotePdfUrl = planAttachmentDTO.getMultimediaPreviewUrl();
			downloadQuotePdfUrl = planAttachmentDTO.getFileUrl();
			break;
		}
	}
	if (Objects.nonNull(planAllDTO.getActivityList()) && !planAllDTO.getActivityList().isEmpty()) {
		ActivityDTO activity = planAllDTO.getActivityList().get(0);
		activityDTO = ZqDiscountVo.ActivityDTO.builder()
			.activityCode(activity.getActivityCode())
			.activityName(activity.getActivityName())
			.activityDesc(activity.getActivityDesc())
			.activityStartTime(activity.getActivityStartTimeStr())
			.activityEndTime(activity.getActivityEndTimeStr()).build();
	}
	String houseLayoutInfoStr = "";
	HouseLayoutInfoDTO houseLayoutInfoDTO = planAllDTO.getReconstructionHouseLayout();
	if (Objects.nonNull(houseLayoutInfoDTO)) {
		Integer livingRoomNum = Objects.isNull(houseLayoutInfoDTO.getLivingRoomNum()) ? 0 : houseLayoutInfoDTO.getLivingRoomNum();
		Integer bedroomNum = Objects.isNull(houseLayoutInfoDTO.getBedroomNum()) ? 0 : houseLayoutInfoDTO.getBedroomNum();
		Integer kitchenNum = Objects.isNull(houseLayoutInfoDTO.getKitchenNum()) ? 0 : houseLayoutInfoDTO.getKitchenNum();
		Integer toiletNum = Objects.isNull(houseLayoutInfoDTO.getToiletNum()) ? 0 : houseLayoutInfoDTO.getToiletNum();
		Integer balconyNum = Objects.isNull(houseLayoutInfoDTO.getBalconyNum()) ? 0 : houseLayoutInfoDTO.getBalconyNum();
		Integer storeroomNum = Objects.isNull(houseLayoutInfoDTO.getStoreroomNum()) ? 0 : houseLayoutInfoDTO.getStoreroomNum();
		houseLayoutInfoStr = MessageFormat.format("{0}室{1}厅{2}厨{3}卫{4}阳台{5}储物间", bedroomNum, livingRoomNum,
			kitchenNum, toiletNum, balconyNum, storeroomNum);
	}
	result.setQuotation(QuotationInfoVo.builder()
		//当前方法无使用
		.comboCode(planAllDTO.getPlanInfo().getComboCode())
		.comboName(planAllDTO.getPlanInfo().getComboName())
		.pricingArea(planAllDTO.getPlanInfo().getPricingArea())
		.quotePrice(planAllDTO.getPlanInfo().getQuotePrice())
		.contractPrice(planAllDTO.getPlanInfo().getContractPriceTotal())
		.remark(planAllDTO.getPlanInfo().getRemark())
		.fileUrl(downloadQuotePdfUrl)
		.filePrevUrl(quotePdfUrl)
		.houseLayout(houseLayoutInfoStr)
		.discountAmount(discountAmount).build());
	result.setPlanAllInfo(new ContractPlanAllDTO(planAllDTO));
}

private void fillPrevContract(ChangeContractDetailResp result, Contract prevContract) {
	List<ContractField> prevContractFieldList = contractFieldService.getListByContractCode(prevContract.getContractCode());
	List<ContractAttach> attachList = contractAttachService.getListByContractCode(prevContract.getContractCode(), AttachTypeEnum.OFFLINE_CONTRACT.getCode());
	Map<String, Object> prevContractFieldMap = prevContractFieldList.stream().collect(Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue, (v1, v2) -> v2));
	Byte contractObjectType = prevContractFieldMap.containsKey("contractObjectType") ? Byte.parseByte(prevContractFieldMap.get("contractObjectType").toString()) : null;

	List<String> attachUrlList = attachList.stream().map(ContractAttach::getUrl).collect(Collectors.toList());
	ZqSignTypeDTO prevSignTypeDTO = ZqSignTypeDTO.builder()
		.signChannelType(prevContract.getSignChannelType())
		.contractObjectType(contractObjectType)
		.attachUrl(attachUrlList)
		.attachFileType(contractBusinessService.getAttachFileKey(attachUrlList))
		.build();

	ChangeContractDetailResp.PrevContractInfo prevContractInfo = new ChangeContractDetailResp.PrevContractInfo();
	prevContractInfo.setSignTypeInfo(prevSignTypeDTO);
	result.setPrevContract(prevContractInfo);
}

