private FormalContractExpandInfoDTO getContractDetail(Contract contract, Boolean isCurrentShow) {
	FormalContractExpandInfoDTO infoDTO = new FormalContractExpandInfoDTO();
	//字段
	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contract.getContractCode());
	Map<String, String> fieldsMap = contractFieldList.stream().collect(Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue, (v1, v2) -> v2));
	//用户
	List<ContractUser> contractUserList = contractUserService.getListByContractCode(contract.getContractCode());
	Map<Byte, ContractUser> userMap = contractUserList.stream().collect(Collectors.toMap(ContractUser::getRoleType, Function.identity(), (v1, v2) -> v2));
	ContractUser owner = userMap.getOrDefault(RoleTypeEnum.OWNER.getCode(), null);
	ContractUser agent = userMap.getOrDefault(RoleTypeEnum.AGENT.getCode(), null);
	ContractUser companyAgent = userMap.getOrDefault(RoleTypeEnum.COMPANY_AGENT.getCode(), null);
	ContractUser legal = userMap.getOrDefault(RoleTypeEnum.LEGAL.getCode(), null);
	if (legal != null && IsSignEnum.YES.getCode().equals(legal.getIsSign())) {
		companyAgent = null;
	}
	//报价
	PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(contract.getProjectOrderId(), contract.getChangeOrderId());
	//甲供材料
	List<ContractMaterial> contractMaterialList = contractMaterialService.getListByContractCode(contract.getContractCode());

	//1.签约主体
	infoDTO.setContractObjectType(Byte.parseByte(fieldsMap.getOrDefault("contractObjectType", "0")));
	infoDTO.setSignChannelType(contract.getSignChannelType());


	//2.客户信息
	if (Objects.nonNull(owner)) {
		infoDTO.setOwnerName(owner.getName());
		infoDTO.setOwnerPhone(owner.getPhone());
		infoDTO.setOwnerCertificateType(owner.getCertificateType());
		infoDTO.setOwnerCertificateNo(owner.getCertificateNo());
	}
	infoDTO.setOwnerAddress(fieldsMap.getOrDefault("ownerAddress", ""));

	//3.代理人信息
	infoDTO.setHasAgent(Byte.parseByte(fieldsMap.getOrDefault(HAVE_AGENT, "0")));
	if (Objects.nonNull(agent)) {
		infoDTO.setAgentName(agent.getName());
		infoDTO.setAgentPhone(agent.getPhone());
		infoDTO.setAgentCertificateType(agent.getCertificateType());
		infoDTO.setAgentCertificateNo(agent.getCertificateNo());
	}

	//法人信息
	//法人信息
	Byte signRole = Byte.parseByte(fieldsMap.getOrDefault("signRole", "0"));
	if (signRole.equals(RoleTypeEnum.OWNER.getCode()) || signRole.equals(RoleTypeEnum.AGENT.getCode())) {
		//如果签约人角色是业主或者代理人，无需diff展示
		signRole = null;
	}
	infoDTO.setSignRole(signRole);
	if (Objects.nonNull(legal)) {
		infoDTO.setLegalName(legal.getName());
		infoDTO.setLegalPhone(legal.getPhone());
		infoDTO.setLegalCertificateType(legal.getCertificateType());
		infoDTO.setLegalCertificateNo(legal.getCertificateNo());
	}

	//4.公司信息
	infoDTO.setCompanyName(fieldsMap.getOrDefault("companyName", ""));
	infoDTO.setCompanyCreditCode(fieldsMap.getOrDefault("companyCreditCode", ""));
	infoDTO.setRegisteredAddress(fieldsMap.getOrDefault("registeredAddress", ""));
	if (Objects.nonNull(companyAgent)) {
		infoDTO.setCompanyAgentName(companyAgent.getName());
		infoDTO.setCompanyAgentPhone(companyAgent.getPhone());
		infoDTO.setCompanyAgentCertificateType(companyAgent.getCertificateType());
		infoDTO.setCompanyAgentCertificateNo(companyAgent.getCertificateNo());
	}


	//5.户型结构
	infoDTO.setParlorCnt(Integer.parseInt(fieldsMap.getOrDefault("parlorCnt", "0")));
	infoDTO.setRoomCnt(Integer.parseInt(fieldsMap.getOrDefault("roomCnt", "0")));
	infoDTO.setCookroomCnt(Integer.parseInt(fieldsMap.getOrDefault("cookroomCnt", "0")));
	infoDTO.setToiletCnt(Integer.parseInt(fieldsMap.getOrDefault("toiletCnt", "0")));
	infoDTO.setBalconyCnt(Integer.parseInt(fieldsMap.getOrDefault("balconyCnt", "0")));
	infoDTO.setStorageCnt(Integer.parseInt(fieldsMap.getOrDefault("storageCnt", "0")));
	infoDTO.setArea(fieldsMap.getOrDefault("area", ""));
	infoDTO.setInsideArea(fieldsMap.getOrDefault("insideArea", ""));
	infoDTO.setStructure(Integer.parseInt(fieldsMap.getOrDefault("structure", "0")));
	infoDTO.setCertificateAddress(isCurrentShow ? getCertificateAddress(fieldsMap) : fieldsMap.getOrDefault("certificateAddress", getCertificateAddress(fieldsMap)));

	//6.其他相关
	infoDTO.setProjectContractModeCode(Integer.parseInt(fieldsMap.getOrDefault("projectContractModeCode", "0")));
	infoDTO.setProjectContractModeName(fieldsMap.getOrDefault("projectContractModeName", ""));
	infoDTO.setPartRoomRange(fieldsMap.getOrDefault("partRoomRange", ""));
	infoDTO.setTaxRate(Integer.parseInt(fieldsMap.getOrDefault("taxRate", "0")));
	infoDTO.setDisputeDealMode(Integer.parseInt(fieldsMap.getOrDefault("disputeDealMode", "0")));
	infoDTO.setWaterProofGuaranteeYearEnum(Integer.parseInt(fieldsMap.getOrDefault("waterProofGuaranteeYearEnum", "0")));
	infoDTO.setOtherGuaranteeYearEnum(Integer.parseInt(fieldsMap.getOrDefault("otherGuaranteeYearEnum", "0")));

	//7.报价
	BigDecimal discountAmount = null;
	String quotePdfUrl = null;
	for (CouponDTO couponDTO : planAllDTO.getCouponList()) {
		if (CouponTypeEnum.DIRECT_COUPON.getCode().equals(couponDTO.getCouponType())) {
			discountAmount = couponDTO.getLapseAmount();
			break;
		}
	}
	for (PlanAttachmentDTO planAttachmentDTO : planAllDTO.getPlanAttachmentList()) {
		if (Objects.equals(50, planAttachmentDTO.getFileType())) {
			quotePdfUrl = planAttachmentDTO.getMultimediaPreviewUrl();
			break;
		}
	}

	//8.甲供材料清单
	List<MaterialItemVo> materialItemVoList = new LinkedList<>();
	for (ContractMaterial contractMaterial : contractMaterialList) {
		materialItemVoList.add(MaterialItemVo.builder()
			.count(contractMaterial.getCount())
			.description(contractMaterial.getDescription())
			.unit(contractMaterial.getUnit())
			.value(contractMaterial.getValue())
			.build());
	}
	infoDTO.setMaterialList(materialItemVoList);

	//9.设计费
	Integer needDesignerAmount = Integer.valueOf(fieldsMap.getOrDefault("needDesignerAmount", "0"));
	if (needDesignerAmount.equals(CommonEnum.YES.getCode().intValue())) {
		infoDTO.setAfterDiscountDesignerAmount(new BigDecimal(fieldsMap.getOrDefault("afterDiscountDesignerAmount", "0")));
	}


	infoDTO.setDiscountAmount(discountAmount);
	infoDTO.setQuotePdfUrl(quotePdfUrl);
	infoDTO.setContractAmount(planAllDTO.getPlanInfo().getContractPriceTotal());
	infoDTO.setComboCode(planAllDTO.getPlanInfo().getComboCode());
	infoDTO.setComboName(planAllDTO.getPlanInfo().getComboName());
	//收款计划
	infoDTO.setCollectionPlanConfigInfo(commonContractService.queryCollectionPlanByContract(contract));
	return infoDTO;
}

