private List<FieldDiffDTO> compareContract(Contract currentContract, FormalContractExpandInfoDTO prevExpandInfo, FormalContractExpandInfoDTO currentExpandInfo, String projectOrderId) {
	List<FieldDiffDTO> result = new LinkedList<>();
	// 加解密
	//加密
	encryptExpandInfo(prevExpandInfo);
	encryptExpandInfo(currentExpandInfo);
	//签约主体
	result.addAll(compareContractSignObject(prevExpandInfo, currentExpandInfo));
	//业主信息
	result.addAll(compareContractCustomer(prevExpandInfo, currentExpandInfo));
	//代理人
	result.addAll(compareContractAgent(prevExpandInfo, currentExpandInfo));
	//法人信息
	result.addAll(compareContractLegalUser(prevExpandInfo, currentExpandInfo));
	//户型结构
	if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(currentContract.getBusinessType())) {
		result.addAll(compareContractCnt(prevExpandInfo, currentExpandInfo));
	}
	//其他 - 房屋类型、装修类型等
	result.addAll(compareContractOther(prevExpandInfo, currentExpandInfo));
	//甲供材料
	result.addAll(compareContractMaterial(prevExpandInfo.getMaterialList(), currentExpandInfo.getMaterialList()));
	//比较收款计划
	result.addAll(compareCollectionPlan(prevExpandInfo.getCollectionPlanConfigInfo(), currentExpandInfo.getCollectionPlanConfigInfo(), projectOrderId, null));
	return result;
}

