public List<FieldDiffDTO> compareCollectionPlan(CollectionPlanConfigInfo prevCollectionPlan, CollectionPlanConfigInfo curCollectionPlan, String projectOrderId, Byte businessType) {
	List<FieldDiffDTO> result = new LinkedList<>();
	//判断两收款计划是否相同
	boolean isDiff = prevCollectionPlan.diff(curCollectionPlan);
	if (!isDiff || collectionPlanChangeOrderIds.contains(projectOrderId)) {
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, ContractTypeEnum.PACKAGE_CHANGE.getCode());
		List<String> pre;
		List<String> cur = new ArrayList<>();
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) || processV25) {
			pre = prevCollectionPlan.getContent().stream().map(m -> m.getLastPayNode().concat("，").concat(m.getPrice().toPlainString()).concat("元")).collect(Collectors.toList());
			cur = curCollectionPlan.getContent().stream().map(m -> m.getLastPayNode().concat("，").concat(m.getPrice().toPlainString()).concat("元")).collect(Collectors.toList());
			result.add(FieldDiffDTO.builder()
				.fieldKey("collectionPlanConfigInfo")
				.fieldName("收款计划")
				.oldValue(String.join("\n", pre))
				.newValue(String.join("\n", cur))
				.build());
		} else {
			pre = prevCollectionPlan.getContent().stream().map(CollectionPlanItem::itemSimpleShow).collect(Collectors.toList());
			cur = curCollectionPlan.getContent().stream().map(CollectionPlanItem::itemSimpleShow).collect(Collectors.toList());
			result.add(FieldDiffDTO.builder()
				.fieldKey("collectionPlan")
				.fieldName("收款计划")
				.oldValue(String.join("\n", pre))
				.newValue(String.join("\n", cur))
				.build());
		}

	}
	return result;
}

public void encryptExpandInfo(FormalContractExpandInfoDTO expandInfoDTO) {
	List<String> collect = Stream.of(expandInfoDTO.getOwnerPhone(), expandInfoDTO.getOwnerCertificateNo(), expandInfoDTO.getAgentPhone(), expandInfoDTO.getAgentCertificateNo(),
			expandInfoDTO.getCompanyAgentPhone(), expandInfoDTO.getCompanyAgentCertificateNo(), expandInfoDTO.getLegalPhone(), expandInfoDTO.getLegalCertificateNo())
		.filter(StringUtils::isNotBlank).distinct().collect(Collectors.toList());
	Map<String, String> encryptMap = cipherService.encrypt(collect);

	expandInfoDTO.setOwnerPhone(encryptMap.getOrDefault(expandInfoDTO.getOwnerPhone(), expandInfoDTO.getOwnerPhone()));
	expandInfoDTO.setOwnerCertificateNo(encryptMap.getOrDefault(expandInfoDTO.getOwnerCertificateNo(), expandInfoDTO.getOwnerCertificateNo()));
	expandInfoDTO.setAgentPhone(encryptMap.getOrDefault(expandInfoDTO.getAgentPhone(), expandInfoDTO.getAgentPhone()));
	expandInfoDTO.setAgentCertificateNo(encryptMap.getOrDefault(expandInfoDTO.getAgentCertificateNo(), expandInfoDTO.getAgentCertificateNo()));
	expandInfoDTO.setCompanyAgentPhone(encryptMap.getOrDefault(expandInfoDTO.getCompanyAgentPhone(), expandInfoDTO.getCompanyAgentPhone()));
	expandInfoDTO.setCompanyAgentCertificateNo(encryptMap.getOrDefault(expandInfoDTO.getCompanyAgentCertificateNo(), expandInfoDTO.getCompanyAgentCertificateNo()));
	expandInfoDTO.setLegalPhone(encryptMap.getOrDefault(expandInfoDTO.getLegalPhone(), expandInfoDTO.getLegalPhone()));
	expandInfoDTO.setLegalCertificateNo(encryptMap.getOrDefault(expandInfoDTO.getLegalCertificateNo(), expandInfoDTO.getLegalCertificateNo()));
}

private List<FieldDiffDTO> compareContractSignObject(ContractSignObjectDTO preSignObject, ContractSignObjectDTO currentSignObject) {
