public ContractDiffDTO getAllContractDiffWithSection(String projectOrderId, String changOrderId, List<ContractFieldChangeRecord> recordList) {
	ContractDiffDTO contractDiffDTO = new ContractDiffDTO();
	List<FieldDiffDTO> signObjectDiff = new LinkedList<>();
	List<FieldDiffDTO> contentDiff = new LinkedList<>();
	List<FieldDiffDTO> discountDiff = new LinkedList<>();

	List<String> signObjectFields = Arrays.asList("contractObjectType", "ownerName", "ownerPhone", "ownerCertificateType", "ownerCertificateNo", "signChannelType", "companyName", "companyCreditCode");
	for (ContractFieldChangeRecord changeRecord : recordList) {
		String fieldKey = changeRecord.getFieldKey();
		FieldDiffDTO diffDTO = FieldDiffDTO.builder()
			.fieldKey(changeRecord.getFieldKey())
			.fieldName(changeRecord.getFieldName())
			.oldValue(changeRecord.getOldValue())
			.newValue(changeRecord.getNewValue())
			.build();
		if (signObjectFields.contains(fieldKey)) {
			signObjectDiff.add(diffDTO);
		} else {
			contentDiff.add(diffDTO);
		}
	}
	Boolean isChangePrice = changePriceScope(changOrderId);
	Boolean isChangeDiscount = changeDiscountScope(changOrderId);
	if (isChangePrice || isChangeDiscount) {
		CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectOrderId);
		QuotationDiffResultDTO quotationDiffResultDTO = quotationFeignService.queryQuotationDiffResult(coordinationProjectOrder.getProjectOrderId(), changOrderId);
		Map<String, FieldDiffDTO> map = quotationFeignService.getQutationDiffMap(quotationDiffResultDTO);
		if (Objects.nonNull(map.get(QuotationDiffFieldEnum.CONTRACT_PRICE.getKey()))) {
			contentDiff.add(map.get(QuotationDiffFieldEnum.CONTRACT_PRICE.getKey()));
		}
		if (Objects.nonNull(map.get(QuotationDiffFieldEnum.COMBO_NAME.getKey()))) {
			contentDiff.add(map.get(QuotationDiffFieldEnum.COMBO_NAME.getKey()));
		}
		if (Objects.nonNull(map.get(QuotationDiffFieldEnum.ACTIVITY_CODE.getKey()))) {
			discountDiff.add(map.get(QuotationDiffFieldEnum.ACTIVITY_CODE.getKey()));
		}
		if (Objects.nonNull(map.get(QuotationDiffFieldEnum.ACTIVITY_NAME.getKey()))) {
			discountDiff.add(map.get(QuotationDiffFieldEnum.ACTIVITY_NAME.getKey()));
		}
		if (Objects.nonNull(map.get(QuotationDiffFieldEnum.SIGN_DIRECT_REDUCTION_COUPON.getKey()))) {
			discountDiff.add(map.get(QuotationDiffFieldEnum.SIGN_DIRECT_REDUCTION_COUPON.getKey()));
		}
		if (Objects.nonNull(map.get(QuotationDiffFieldEnum.OTHER_COUPON.getKey()))) {
			discountDiff.add(map.get(QuotationDiffFieldEnum.OTHER_COUPON.getKey()));
		}
		if (Objects.nonNull(map.get(QuotationDiffFieldEnum.TICKET_PACKAGE_COUPON.getKey()))) {
			discountDiff.add(map.get(QuotationDiffFieldEnum.TICKET_PACKAGE_COUPON.getKey()));
		}
	}

	contractDiffDTO.setSignObjectDiff(signObjectDiff);
	contractDiffDTO.setContentDiff(contentDiff);
	contractDiffDTO.setDiscountDiff(discountDiff);
	return contractDiffDTO;
}

