public ChangeContractListVo getChangContractList(String projectOrderId) {
	ChangeContractListVo vo = new ChangeContractListVo();
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
	if (Objects.isNull(projectInfoDTO)) {
		LOGGER.warn("获取变更合同列表失败,查询不到项目信息 projectOrderId:{}", projectOrderId);
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取变更合同列表失败,查询不到项目信息-[签约]");
	}
	byte businessType = commonContractService.getBusinessType(projectInfoDTO);
	vo.setAddress(homeAndPcCommonService.getAddress(projectInfoDTO));
	vo.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));
	//获取变更协议列表
	List<Contract> changeContractlist = contractService.getBaseContractInfoByOrderBy(businessType, projectOrderId, ContractTypeEnum.PACKAGE_CHANGE.getCode(), "ctime");
	if (changeContractlist.size() == 0) {
		return vo;
	}
	//获取变更原因列表
	List<ChangeOrderBaseInfoDTO> changeOrderReadList = changeOrderReadService.getBaseInfoListByProjectOrderId(projectOrderId);
	//获取全部合同编码
	List<String> changeContractCodeList = changeContractlist.stream().map(Contract::getContractCode).collect(Collectors.toList());
	//获取全部合同节点信息
	List<ContractNode> nodeListInfos = getNodeListInfos(changeContractCodeList);

	List<ChangeContractListVo.ChangeContractListItemVo> changeContractListItemVos = new LinkedList<>();
	//获取不到，直接返回空
	for (Contract contract : changeContractlist) {
		ChangeContractListVo.ChangeContractListItemVo changeContractVo = new ChangeContractListVo.ChangeContractListItemVo(ContractTypeEnum.PACKAGE_CHANGE);
		//团装已取消的变更合同不展示
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType()) && ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())) {
			continue;
		}
		changeContractVo.setStatus(contract.getStatus());
		changeContractVo.setStatusText(ContractStatusEnum.getNameByCode(contract.getStatus()));
		changeContractVo.setChangeRangeName(getChangeRangeNames(contract, changeOrderReadList));
		changeContractVo.setButtonList(getChangeContractButtonList(contract));
		changeContractVo.setContractInfoText(getContractInfoText(contract, nodeListInfos));
		changeContractVo.setContractCode(contract.getContractCode());
		changeContractVo.setContractNo(contract.getContractNo());
		changeContractVo.setBusinessType(contract.getBusinessType());
		changeContractVo.setProjectOrderId(contract.getProjectOrderId());
		changeContractVo.setChangeOrderId(contract.getChangeOrderId());
		changeContractVo.setUserConfirmStatus(contract.getUserConfirmStatus());
		changeContractVo.setUserSignStatus(contract.getUserSignStatus());
		String bpmUrl = pcContractService.getBpmUrl(contract.getBmpNo());
		changeContractVo.setBmpNo(contract.getBmpNo());
		changeContractVo.setBmpUrl(bpmUrl);
		changeContractVo.setSignChannelType(contract.getSignChannelType());
		changeContractVo.setUserSignType(contract.getUserSignType());
		changeContractVo.setAuditType(contract.getAuditType());
		changeContractVo.setIcon("https://img.ljcdn.com/utopia-file/833f38a3-4410-4b81-9240-df81e166bc28.png");
		changeContractVo.setBpmUrl("");
		changeContractVo.setContractUrl(homeAndPcCommonService.getContractUrl(contract));
		changeContractVo.setAttachUrl(homeAndPcCommonService.getAttachUrl(contract));
		if ((!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) && (StringUtils.isNotBlank(changeContractVo.getContractUrl()) || CollectionUtils.isNotEmpty(changeContractVo.getAttachUrl()))) {
			changeContractVo.getButtonList().add(new ButtonItemVo(PcButtonEnum.PREVIEW));
		}
		changeContractListItemVos.add(changeContractVo);
	}
	vo.setChangeContractListItemVos(changeContractListItemVos);

	return vo;
}

