	Contract currentContract = null;
	Contract prevContract = null;
	currentContract = StringUtils.isNotBlank(contractCode) ? contractService.getByContractCode(contractCode) : contractService.getChangeContract(projectOrderId, changeOrderId);
	if (Objects.nonNull(currentContract)) {
		prevContract = contractService.getChangePrevEffectContract(currentContract.getId(), currentContract.getProjectOrderId());
		changeOrderId = currentContract.getChangeOrderId();
	} else {
		prevContract = contractService.getChangePrevEffectContractByPid(projectOrderId);
	}
	ContractSignObjectDTO contractSignObjectDTO = new ContractSignObjectDTO();

	contractSignObjectDTO.setProjectOrderId(projectOrderId);
	contractSignObjectDTO.setChangeOrderId(changeOrderId);
	contractSignObjectDTO.setType(ContractTypeEnum.PACKAGE_CHANGE.getCode());
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
	contractSignObjectDTO.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));
	contractSignObjectDTO.setAddress(homeAndPcCommonService.getAddress(projectInfoDTO));
	contractSignObjectDTO.setStatus(Objects.nonNull(currentContract) ? currentContract.getStatus() : ContractStatusEnum.DRAFT.getCode());
	contractSignObjectDTO.setContractCode(Objects.nonNull(currentContract) ? currentContract.getContractCode() : null);
	if (StringUtils.isNotBlank(changeOrderId)) {
		contractSignObjectDTO.setIsChangeQuotation(changePriceScope(changeOrderId));
	}

	String initContractCode = Objects.nonNull(currentContract) ? currentContract.getContractCode() : prevContract.getContractCode();

	//客户信息
	ContractUser owner = contractUserService.getUserByContractCodeAndType(initContractCode, RoleTypeEnum.OWNER.getCode());
	if (Objects.nonNull(owner)) {
		contractSignObjectDTO.setOwnerCertificateNo(cipherService.decrypt(owner.getCertificateNo()));
		contractSignObjectDTO.setOwnerCertificateType(owner.getCertificateType());
		contractSignObjectDTO.setOwnerPhone(cipherService.decrypt(owner.getPhone()));
		contractSignObjectDTO.setOwnerName(owner.getName());
	}

	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(initContractCode);
	Map<String, String> map = Maps.newHashMap();
	contractFieldList.forEach(contractField -> map.put(contractField.getFieldKey(), contractField.getFieldValue()));
	String ownerAddress = StringUtils.isBlank(map.get("ownerAddress")) ? "" : map.get("ownerAddress");
	contractSignObjectDTO.setOwnerAddress(ownerAddress);
	//企业名称
	String companyName = StringUtils.isBlank(map.get("companyName")) ? "" : map.get("companyName");
	contractSignObjectDTO.setCompanyName(companyName);
	//统一社会信用代码
	String companyCreditCode = StringUtils.isBlank(map.get("companyCreditCode")) ? "" : map.get("companyCreditCode");
	contractSignObjectDTO.setCompanyCreditCode(companyCreditCode);

	//主体类型
	Byte contractObjectType = StringUtils.isBlank(map.get("contractObjectType")) ? null : Byte.valueOf(map.get("contractObjectType"));

	contractSignObjectDTO.setContractObjectType(contractObjectType);

	return contractSignObjectDTO;

}

public String saveSignObject(ContractSignObjectDTO body, Long ucId) {
	checkCanCreateOrEdit(body.getChangeOrderId());
	//校验唯一性
	homeAndPcCommonService.checkUnique(body.getProjectOrderId(), body.getChangeOrderId(), body.getContractCode(), body.getType());
	//计算是否有主体变更
	Contract preContract = contractService.getChangePrevEffectContractByPid(body.getProjectOrderId());
	ContractSignObjectDTO preSignObject = getSignObject(preContract.getProjectOrderId(), preContract.getContractCode(), preContract.getChangeOrderId());
	List<FieldDiffDTO> signObjectDiff = compareContractSignObject(preSignObject, body);
	if (CollectionUtils.isEmpty(signObjectDiff)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "主体未发生变更，请检查填写信息是否正确");
	}


	//变更合同草稿
	List<Contract> draftChangeContracts = contractService.getDraftChangeContract(body.getProjectOrderId());
	if (CollectionUtils.isNotEmpty(draftChangeContracts)) {
		body.setContractCode(draftChangeContracts.get(0).getContractCode());
	}
	Contract changeContract = queryOrBuildChangeContract(body, ucId);
	//新增或者更新变更合同
	pcContractService.saveOrUpdateContract(changeContract);
	List<ContractField> contractFields = new ArrayList<>();
	Date date = new Date();
	//处理变更合同主体信息
	if (ContractObjectTypeEnum.PERSON.getCode().equals(body.getContractObjectType())) {
		//个人合同
		ContractUser ownerUser = ContractUser.builder().contractCode(changeContract.getContractCode())
			.certificateNo(body.getOwnerCertificateNo()).certificateType(body.getOwnerCertificateType())
			.roleType(RoleTypeEnum.OWNER.getCode()).name(StringUtils.trim(body.getOwnerName())).phone(body.getOwnerPhone())
			.delStatus((byte) 0)
			.build();
		//保存或者更新变更签约主体
		ContractUser dbOwner = contractUserService.getUserByContractCodeAndType(ownerUser.getContractCode(), RoleTypeEnum.OWNER.getCode());
		if (Objects.isNull(dbOwner)) {
			//新增客户信息
			contractUserService.insert(ownerUser);
		} else {
			ownerUser.setId(dbOwner.getId());
			//更新客户信息
			contractUserService.update(ownerUser);
		}
		ContractField ownerAddressField = ContractField.builder()
			.contractCode(changeContract.getContractCode())
			.fieldKey("ownerAddress")
			.fieldValue(body.getOwnerAddress())
			.delStatus((byte) 0)
			.createUserId(String.valueOf(ucId))
			.createUserName(homeAndPcCommonService.getOperatorName(ucId))
			.modifyUserId(String.valueOf(ucId))
			.modifyUserName(homeAndPcCommonService.getOperatorName(ucId))
			.ctime(date)
			.mtime(date)
			.build();
		contractFields.add(ownerAddressField);
	} else {
		//公对公
		//变更合同企业信息
		ContractField companyNameField = ContractField.builder()
			.contractCode(changeContract.getContractCode())
			.fieldKey("companyName")
			.fieldValue(String.valueOf(body.getCompanyName()))
			.delStatus((byte) 0)
			.createUserId(String.valueOf(ucId))
			.createUserName(homeAndPcCommonService.getOperatorName(ucId))
			.modifyUserId(String.valueOf(ucId))
			.modifyUserName(homeAndPcCommonService.getOperatorName(ucId))
			.ctime(date)
			.mtime(date)
			.build();
		contractFields.add(companyNameField);
		ContractField companyCreditCodeField = ContractField.builder()
			.contractCode(changeContract.getContractCode())
			.fieldKey("companyCreditCode")
			.fieldValue(String.valueOf(body.getCompanyCreditCode()))
			.delStatus((byte) 0)
			.createUserId(String.valueOf(ucId))
			.createUserName(homeAndPcCommonService.getOperatorName(ucId))
			.modifyUserId(String.valueOf(ucId))
			.modifyUserName(homeAndPcCommonService.getOperatorName(ucId))
			.ctime(date)
			.mtime(date)
			.build();
		contractFields.add(companyCreditCodeField);
	}
	//变更合同签约主体类型
	ContractField contractObjectTypeField = ContractField.builder()
		.contractCode(changeContract.getContractCode())
		.fieldKey("contractObjectType")
		.fieldValue(String.valueOf(body.getContractObjectType()))
		.delStatus((byte) 0)
		.createUserId(String.valueOf(ucId))
		.createUserName(homeAndPcCommonService.getOperatorName(ucId))
		.modifyUserId(String.valueOf(ucId))
		.modifyUserName(homeAndPcCommonService.getOperatorName(ucId))
		.ctime(date)
		.mtime(date)
		.build();
	contractFields.add(contractObjectTypeField);
	contractFieldService.deleteByContractCodeAndKeys(changeContract.getContractCode(), contractFields.stream().map(ContractField::getFieldKey).collect(Collectors.toList()));
	contractFieldService.saveBatch(contractFields);
	return changeContract.getContractCode();
}

public List<FieldDiffDTO> compareDesignAmount(FormalContractExpandInfoDTO prevExpandInfo, FormalContractExpandInfoDTO currentExpandInfo) {
	List<FieldDiffDTO> result = new LinkedList<>();
	if (!Objects.equals(prevExpandInfo.getPreDiscountDesignerAmount(), currentExpandInfo.getPreDiscountDesignerAmount())) {
		result.add(FieldDiffDTO.builder()
			.fieldKey("preDiscountDesignerAmount")
			.fieldName("设计服务费（优惠前）")
			.oldValue(prevExpandInfo.getPreDiscountDesignerAmount() != null ? prevExpandInfo.getPreDiscountDesignerAmount().toString() : null)
			.newValue(currentExpandInfo.getPreDiscountDesignerAmount().toString())
			.build()
		);
	}
	if (!Objects.equals(prevExpandInfo.getAfterDiscountDesignerAmount(), currentExpandInfo.getAfterDiscountDesignerAmount())) {
		result.add(FieldDiffDTO.builder()
			.fieldKey("afterDiscountDesignerAmount")
			.fieldName("设计费金额")
			.oldValue(prevExpandInfo.getAfterDiscountDesignerAmount().toString())
			.newValue(currentExpandInfo.getAfterDiscountDesignerAmount().toString())
			.build()
		);
	}

	if (!Objects.equals(prevExpandInfo.getDesignerLevelName(), currentExpandInfo.getDesignerLevelName())) {
		result.add(FieldDiffDTO.builder()
			.fieldKey("designerLevelName")
			.fieldName("设计师级别")
			.oldValue(prevExpandInfo.getDesignerLevelName())
			.newValue(currentExpandInfo.getDesignerLevelName())
			.build()
		);
	}
	return result;
}

