private Contract queryOrBuildChangeContract(ContractSignObjectDTO body, Long userId) {
	String contractCode = body.getContractCode();
	String projectOrderId = body.getProjectOrderId();
	Contract sourceContract = null;
	sourceContract = StringUtils.isNotBlank(contractCode) ? contractService.getByContractCode(contractCode) : contractService.getChangePrevEffectContractByPid(projectOrderId);
	Contract changeContract = null;
	String operatorName = homeAndPcCommonService.getOperatorName(userId);
	if (StringUtils.isNotBlank(contractCode)) {
		//更新变更合同
		Contract updateContract = new Contract();
		updateContract.setId(sourceContract.getId());
		updateContract.setUserSignType(body.getUserSignType());
		updateContract.setMtime(new Date());
		updateContract.setModifyUserId(String.valueOf(userId));
		updateContract.setModifyUserName(operatorName);
		updateContract.setContractCode(sourceContract.getContractCode());
		changeContract = updateContract;
	} else {
		//新增变更合同
		Contract insertContract = Contract.builder()
			.contractCode(RandomCodeUtils.generateContractCode())
			.contractNo(RandomCodeUtils.generateContractNo())
			.changeOrderId(body.getChangeOrderId())
			.status(ContractStatusEnum.DRAFT.getCode())
			.userSignType(body.getUserSignType())
			.type(body.getType())
			.gbCode(sourceContract.getGbCode())
			.companyCode(sourceContract.getCompanyCode())
			.signChannelType(sourceContract.getSignChannelType())
			.projectOrderId(sourceContract.getProjectOrderId())
			.businessType(sourceContract.getBusinessType())
			.auditType(AuditTypeEnum.BEFORE_SIGN.getCode())
			.amount(sourceContract.getAmount())
			.createUserId(String.valueOf(userId))
			.createUserName(operatorName)
			.modifyUserId(String.valueOf(userId))
			.modifyUserName(operatorName)
			.build();

		changeContract = insertContract;

	}
	return changeContract;
}

	public ChangeContractDetailVo getChangeContractDetail(String contractCode, String projectOrderId, String changeOrderId) {
		ChangeContractDetailVo changeContractDetailVo = new ChangeContractDetailVo();
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		if (Objects.isNull(projectInfoDTO)) {
			LOGGER.warn("获取变更合同详情失败,查询不到项目信息 projectOrderId:{}", projectOrderId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取变更合同详情失败,查询不到项目信息-[签约]");
		}
		byte businessType = commonContractService.getBusinessType(projectInfoDTO);
		changeContractDetailVo.setAddress(homeAndPcCommonService.getAddress(projectInfoDTO));
		changeContractDetailVo.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));

		//获取合同信息
		Contract changeContractDetail = null;
		if (StringUtils.isNotEmpty(contractCode)) {
			changeContractDetail = contractService.getByContractCode(contractCode);
		} else {
			changeContractDetail = contractService.getChangeBaseContractInfo(projectOrderId, changeOrderId);
		}

		if (Objects.isNull(changeContractDetail)) {
			LOGGER.warn("获取变更合同详情为空,查询不到合同信息 contractCode:{} projectOrderId:{} changeOrderId:{}", contractCode, projectOrderId, changeOrderId);

			return changeContractDetailVo;
		}
		changeContractDetailVo.setContractCode(changeContractDetail.getContractCode());
		changeContractDetailVo.setType(changeContractDetail.getType());
		changeContractDetailVo.setTypeText(ContractTypeEnum.getNameByContractTypeAndBusinessType(changeContractDetail.getType(), changeContractDetail.getBusinessType()));
		changeContractDetailVo.setStatus(changeContractDetail.getStatus());
		changeContractDetailVo.setStatusText(ContractStatusEnum.getNameByCode(changeContractDetail.getStatus()));
		changeContractDetailVo.setUserSignType(changeContractDetail.getUserSignType());
		changeContractDetailVo.setUserConfirmStatus(changeContractDetail.getUserConfirmStatus());
		changeContractDetailVo.setUserSignStatus(changeContractDetail.getUserSignStatus());
		changeContractDetailVo.setSignChannelType(changeContractDetail.getSignChannelType());
		changeContractDetailVo.setContractUrl(homeAndPcCommonService.getContractUrl(changeContractDetail));
		changeContractDetailVo.setAttachUrl(homeAndPcCommonService.getAttachUrl(changeContractDetail));
		changeContractDetailVo.setAttachFileType(contractBusinessService.getAttachFileKey(changeContractDetailVo.getAttachUrl()));
		String bpmUrl = pcContractService.getBpmUrl(changeContractDetail.getBmpNo());
		changeContractDetailVo.setBpmNo(changeContractDetail.getBmpNo());
		changeContractDetailVo.setBpmUrl(bpmUrl);
		changeContractDetailVo.setContractNo(changeContractDetail.getContractNo());
		changeContractDetailVo.setProjectOrderId(changeContractDetail.getProjectOrderId());
		changeContractDetailVo.setChangeOrderId(changeContractDetail.getChangeOrderId());

//		FieldDiffWithSectionDTO fieldDiffWithSectionResult = getContractDiffWithSectionForPc(changeContractDetail.getContractCode());
		ContractDiffDTO contractDiffDTO = getAllContractDiffWithSection(projectOrderId, changeContractDetail.getChangeOrderId(), changeContractDetail.getContractCode());
		changeContractDetailVo.setSignObjectDiff(contractDiffDTO.getSignObjectDiff());
		changeContractDetailVo.setContentDiff(contractDiffDTO.getContentDiff());
		changeContractDetailVo.setQuoteDiff(new ArrayList());
		changeContractDetailVo.setDiscountDiff(contractDiffDTO.getDiscountDiff());
		if (changeContractDetail.getStatus().equals(ContractStatusEnum.PENDING_USER_SIGN.getCode()) ||
			changeContractDetail.getStatus().equals(ContractStatusEnum.PENDING_USER_CONFIRM.getCode())) {//待签署或者待确认状态，才会有签署信息
			ZqSignInfoDTO changeSignInfoDTO = getChangeContractSignInfoDTO(changeContractDetail.getContractCode());
			changeContractDetailVo.setChangeSignInfoDTO(changeSignInfoDTO);
			Contract zqContract = contractService.queryContractInfo(businessType, projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode());
			if (!StringUtils.isEmpty(zqContract.getContractCode())) {
				ZqSignInfoDTO zqSignInfoDTO = getChangeContractSignInfoDTO(zqContract.getContractCode());
				changeContractDetailVo.setZqSignInfoDTO(zqSignInfoDTO);
			}
		}

		//获取取消前的一个状态(只有取消状态才去获取)
		if (changeContractDetail.getStatus().equals(ContractStatusEnum.CANCEL.getCode())) {
			ContractStatusLog contractStatusInfo = contractStatusLogService.getContractStatusInfo(
				changeContractDetail.getContractCode(),
				ContractStatusEnum.CANCEL.getCode()
			);

			if (!Objects.isNull(contractStatusInfo) &&
				contractStatusInfo.getTargetStatus().equals(ContractStatusEnum.CANCEL.getCode())) {
				changeContractDetailVo.setPreStatus(contractStatusInfo.getSourceStatus());
			}
		}

		if (hasChangeRangeByScopeId(changeContractDetail.getProjectOrderId(),
			changeContractDetail.getChangeOrderId(),
			ChangeScopeEnum.CHANGE_PRICE.getId())) {//如果有报价，才会返回报价URL
			//获取正式的
			PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(changeContractDetail.getProjectOrderId(), changeContractDetail.getChangeOrderId());
			for (PlanAttachmentDTO planAttachmentDTO : planAllDTO.getPlanAttachmentList()) {
				if (Objects.equals(50, planAttachmentDTO.getFileType())) {
					changeContractDetailVo.setQuotePdfUrl(planAttachmentDTO.getMultimediaPreviewUrl());
					break;
				}
			}
		}

		return changeContractDetailVo;
	}

