public ZqSignInfoDTO getChangeContractSignInfoDTO(String contractCode) {
	// 1.合同字段信息
	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contractCode);
	Map<String, Object> map = Maps.newHashMap();
	contractFieldList.forEach(contractField -> map.put(contractField.getFieldKey(), contractField.getFieldValue()));

	List<ContractUser> contractUserList = contractUserService.getListByContractCode(contractCode);
	ZqSignInfoDTO zqSignInfoDto = ZqSignInfoDTO.builder().build();
	contractUserList.forEach(contractUser -> {
		if (contractUser.getRoleType().equals(UserTypeEnum.OWNER.getCode())) {
			zqSignInfoDto.setOwnerName(contractUser.getName());
			zqSignInfoDto.setOwnerPhone(PhoneHandler.getHidePhone(contractUser.getPhone()));
		}
		if (contractUser.getRoleType().equals(UserTypeEnum.AGENT.getCode())) {
			zqSignInfoDto.setHaveAgent(HaveAgentEnum.YES.getCode());
			zqSignInfoDto.setAgentName(contractUser.getName());
			zqSignInfoDto.setAgentPhone(PhoneHandler.getHidePhone(contractUser.getPhone()));
		}
		if (contractUser.getRoleType().equals(UserTypeEnum.COMPANY_AGENT.getCode())) {
			zqSignInfoDto.setCompanyAgentName(contractUser.getName());
			zqSignInfoDto.setCompanyAgentPhone(PhoneHandler.getHidePhone(contractUser.getPhone()));
		}
		if (CommonEnum.YES.getCode().equals(contractUser.getIsSign())) {
			zqSignInfoDto.setSignatoryRoleType(contractUser.getRoleType());
			zqSignInfoDto.setSignatoryName(contractUser.getName());
			zqSignInfoDto.setSignatoryPhone(PhoneHandler.getHidePhone(contractUser.getPhone()));

		}
	});

	Byte haveAgent = Objects.isNull(map.get(HAVE_AGENT)) ? null : Byte.valueOf(map.get(HAVE_AGENT).toString());
	zqSignInfoDto.setHaveAgent(haveAgent);
	zqSignInfoDto.setCompanyName(Objects.isNull(map.get("companyName")) ? "" : map.get("companyName").toString());
	String companyCreditCode = Objects.isNull(map.get("companyCreditCode")) ? "" : map.get("companyCreditCode").toString();
	zqSignInfoDto.setCompanyCreditCode(companyCreditCode);

	return zqSignInfoDto;
}

public FieldDiffWithSectionDTO getContractDiffWithSectionForPc(String contractCode) {
	FieldDiffWithSectionDTO fieldDiffWithSectionDTO = new FieldDiffWithSectionDTO();
	//获取合同变更字段信息
	List<ContractFieldChangeRecord> contractFieldChangeRecordList = getContractDiff(contractCode);
	if (contractFieldChangeRecordList.size() == 0) {
		return fieldDiffWithSectionDTO;
	}
	//获取字段区域信息
	String changeContractFieldSectionApollo = contractApolloConfig.getChangeContractFieldSection();
	List<FieldDiffWithSectionApolloDTO> columnListApolloInfo = JsonUtil.toObject(changeContractFieldSectionApollo, new TypeReference<List<FieldDiffWithSectionApolloDTO>>() {
	});
	if (columnListApolloInfo.size() == 0) {
		return fieldDiffWithSectionDTO;
	}
	List<FieldDiffDTO> signObjectDiff = new ArrayList<>();
	List<FieldDiffDTO> contentDiff = new ArrayList<>();
	List<FieldDiffDTO> quoteDiff = new ArrayList<>();

	for (ContractFieldChangeRecord contractFieldChangeRecord : contractFieldChangeRecordList) {
		//数据库变更字段列表
		String dbFieldKey = contractFieldChangeRecord.getFieldKey();
		//是否归类
		Boolean isConfigField = false;
		//基础数据
		FieldDiffDTO fieldDiffDTO = new FieldDiffDTO();
		fieldDiffDTO.setFieldKey(contractFieldChangeRecord.getFieldKey());
		fieldDiffDTO.setFieldName(contractFieldChangeRecord.getFieldName());
		fieldDiffDTO.setNewValue(contractFieldChangeRecord.getNewValue());
		fieldDiffDTO.setOldValue(contractFieldChangeRecord.getOldValue());

		for (FieldDiffWithSectionApolloDTO fieldDiffWithSectionApolloDTO : columnListApolloInfo) {
			//apollo配置的区域
			String sectionApollo = fieldDiffWithSectionApolloDTO.getSection();
			//apollo配置的区域字段
			List<String> sectionFieldApollo = fieldDiffWithSectionApolloDTO.getField();
			//如果有配置，则入到对应的区域
			if (sectionFieldApollo.contains(dbFieldKey)) {
				if (sectionApollo.equals("signObjectDiff")) {
					signObjectDiff.add(fieldDiffDTO);
					isConfigField = true;
					break;
				}

				if (sectionApollo.equals("contentDiff")) {
					contentDiff.add(fieldDiffDTO);
					isConfigField = true;
					break;
				}
			}
		}
		//未归类的全部归到内容里
		if (!isConfigField) {
			contentDiff.add(fieldDiffDTO);
		}
	}
	fieldDiffWithSectionDTO.setSignObjectDiff(signObjectDiff);
	fieldDiffWithSectionDTO.setContentDiff(contentDiff);


	return fieldDiffWithSectionDTO;
}

public Boolean applyStamp(String contractCode) {

	Contract contract = contractService.getByContractCode(contractCode);
	if (Objects.isNull(contract)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "申请用章，合同不存在-[签约]");
	}
	if (!contract.getStatus().equals(ContractStatusEnum.USER_CONFIRMED.getCode())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "非待业主确认下，不可以申请用章-[签约]");
	}
	//更新合同信息
	contract.setUserSignType(UserSignTypeEnum.SIGN.getCode());
	contract.setStatus(ContractStatusEnum.PENDING_USER_SIGN.getCode());
	contractService.update(contract);
	//记录日志&发送事件
	Map<String, String> logContent = new HashMap<>();
	contractLogService.createLog(contractCode, LogTypeEnum.APPLY_SEAL.getCode(), LogTypeEnum.APPLY_SEAL.getName(), logContent.toString());
	contractLogService.createLog(contractCode, LogTypeEnum.STATUS_CHANGE.getCode(), LogTypeEnum.STATUS_CHANGE.getName(), contract.getStatus().toString());
	eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_APPLY_SEAL, contractCode);

	return true;
}

