public void confirmChangeContract(String contractCode, Long userId) {

	Contract contract = contractService.getByContractCode(contractCode);
	String projectOrderId = contract.getProjectOrderId();
	String changeOrderId = contract.getChangeOrderId();
	checkCanCreateOrEdit(changeOrderId);
	homeAndPcCommonService.checkUnique(projectOrderId, contract.getChangeOrderId(), contractCode, ContractTypeEnum.PACKAGE_CHANGE.getCode());
	Map<String, String> fieldKeyValueMap = pcContractService.getContractFieldKeyValueMap(contractCode);
	//生成pdf
	if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
		ChangeContractFreeformDTO freeformDTO = buildChangeContractFreeformDTO(contractCode);
		ObjectMapper objectMapper = new ObjectMapper();
		Map<String, Object> map = objectMapper.convertValue(freeformDTO, Map.class);
		contractBusinessService.generatePdf(contract, map);
	}

	//客源回写信息
	LOGGER.info("合同提交 客源回写信息 saveCollectionPlanInfo projectOrderId:{}", projectOrderId);
	rewriteCustomer(projectOrderId, contractCode, fieldKeyValueMap);

	//设置用户可见
	boolean userCanSee = SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType()) || !AuditTypeEnum.BEFORE_SIGN.getCode().equals(contract.getAuditType());
	contract.setUserQueryStatus(userCanSee ? UserQueryStatusEnum.VALID.getCode() : UserQueryStatusEnum.INVALID.getCode());

	contract.setStatus(homeAndPcCommonService.getContractSubmitStatus(contract));
	contract.setModifyUserId(String.valueOf(userId));
	String userName = homeAndPcCommonService.getOperatorName(userId);
	contract.setModifyUserName(userName);
	contractService.update(contract);
	//发送事件
	pcContractService.doAfterSubmit(contract);


}

public ChangeOrderInfoDTO getChangeRangeNamesAndReason(Contract contract) {
	ChangeOrderInfoDTO changeOrderInfoDTO = new ChangeOrderInfoDTO();
	String contractChangeOrderId = contract.getChangeOrderId();
	String contractProjectOrderId = contract.getProjectOrderId();
	if (StringUtil.isEmpty(contractProjectOrderId) ||
		StringUtil.isEmpty(contractChangeOrderId)) {

		return changeOrderInfoDTO;
	}

	//获取变更原因列表
	List<ChangeOrderBaseInfoDTO> changeOrderReadInfo = changeOrderReadService.getBaseInfoListByProjectOrderId(contractProjectOrderId);
	if (Objects.isNull(changeOrderReadInfo)) {
		return changeOrderInfoDTO;
	}

	for (ChangeOrderBaseInfoDTO changeOrderBaseInfoDTO : changeOrderReadInfo) {
		if (contractChangeOrderId.equals(changeOrderBaseInfoDTO.getChangeOrderId())) {
			changeOrderInfoDTO.setProjectOrderId(contractProjectOrderId);
			changeOrderInfoDTO.setChangeOrderId(contractChangeOrderId);
			changeOrderInfoDTO.setChangeReason(changeOrderBaseInfoDTO.getChangeReason());
			List<ChangeScopeDTO> changeScopes = changeOrderBaseInfoDTO.getChangeScope();
			List<String> scopeDescList = changeScopes.stream().map(ChangeScopeDTO::getScopeDesc).collect(Collectors.toList());
			String changeScopeDesc = "";
			if (!scopeDescList.isEmpty()) {
				changeScopeDesc = StringUtils.join(scopeDescList.toArray(), "、");
			}
			changeOrderInfoDTO.setChangeScopeDesc(changeScopeDesc);
		}
	}

	return changeOrderInfoDTO;
}

