public ContractPreviewVo preview(String contractCode) {
	ContractPreviewVo contractPreviewVo = new ContractPreviewVo();

	Contract contract = contractService.getByContractCode(contractCode);
	if (Objects.isNull(contract)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "未查询到该合同");
	}
	contractPreviewVo.setSignChannelType(contract.getSignChannelType());
	contractPreviewVo.setContractCode(contractCode);
	String pdfUrl = "";
	List<String> attachUrl = new ArrayList<>();
	if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
		//线下签约
		List<ContractAttach> offlineAttachs = contractAttachService.getListByContractCode(contractCode, AttachTypeEnum.OFFLINE_CONTRACT.getCode());
		attachUrl = offlineAttachs.stream().map(ContractAttach::getUrl).collect(Collectors.toList());
	} else if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
		//线上签约，如果是草稿状态，实时生成
		ChangeContractFreeformDTO freeformDTO = buildChangeContractFreeformDTO(contractCode);
		LOGGER.info(freeformDTO.getDynamicChangeContent());
		ObjectMapper objectMapper = new ObjectMapper();
		Map<String, Object> map = objectMapper.convertValue(freeformDTO, Map.class);
		pdfUrl = contractBusinessService.generatePdf(contract, map);
	} else {
		//线上签约非草稿态
		pdfUrl = homeAndPcCommonService.getContractUrl(contract);
	}
	contractPreviewVo.setAttachUrl(attachUrl);
	contractPreviewVo.setAttachFileType(contractBusinessService.getAttachFileKey(attachUrl));
	contractPreviewVo.setContractUrl(pdfUrl);
	return contractPreviewVo;

}

