public void undoContract(String contractCode, Long createUserId, String bpmNo) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (Objects.isNull(contract)) {
		LOGGER.warn("变更合同撤销失败,未查询到该变更合同 contractCode:{} createUserId:{}", contractCode, createUserId);
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "变更合同撤销失败，未查询到该变更合同-[签约]");
	}
	Integer status = contract.getStatus();
	//需要正式签署的合同，并且状态已经到已签署，不能撤销
	if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
		if (CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus()) || CommonEnum.YES.getCode().equals(contract.getUserSignStatus())) {
			LOGGER.warn("变更合同撤销失败,用户已经确认或签署 contractCode:{} createUserId:{}", contractCode, createUserId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "变更合同撤销失败,该变更合同客户已经确认或签署-[签约]");
		}
	}
	if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
		LOGGER.warn("变更合同撤销失败,变更合同为草稿，无需撤销 contractCode:{} createUserId:{}", contractCode, createUserId);
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前变更合同为草稿，无需撤销-[签约]");
	}
	if (ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
		LOGGER.warn("变更合同撤销失败,变更合同已完成 contractCode:{} createUserId:{}", contractCode, createUserId);
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前变更合同已完成，无需撤销-[签约]");
	}

	// 取消关联合同
	if (StringUtils.isNotBlank(contract.getRelateContractCode())) {
		homeAndPcCommonService.unlinkAccreditAndMainContract(contract);
	}

	Contract authAgentContract = homeAndPcCommonService.getRelateContractByType(contract, ContractTypeEnum.AUTH_AGENT.getCode());
	if (authAgentContract != null) {
		homeAndPcCommonService.undoAuthAgentContract(authAgentContract);
	}

	//撤回状态并且更新用户状态
	contract.setStatus(ContractStatusEnum.DRAFT.getCode());
	contract.setUserQueryStatus(UserQueryStatusEnum.INVALID.getCode());
	contract.setUserConfirmStatus(CommonEnum.NO.getCode());
	contract.setUserSignStatus(CommonEnum.NO.getCode());
	contract.setRelateContractCode("");
	contract.setModifyUserId(String.valueOf(createUserId));
	String userName = homeAndPcCommonService.getOperatorName(createUserId);
	contract.setModifyUserName(userName);
	//pdf key
	contract.setPreviewKey("");
	contract.setUserSignedKey("");
	contract.setBothSignedKey("");
	contract.setRelateContractCode("");
	contract.setMtime(new Date());
	int updateResult = contractService.updateUnchecked(contract);
	if (updateResult <= 0) {
		LOGGER.warn("变更合同撤销失败 contractCode:{} createUserId:{}", contractCode, createUserId);
		throw new ContractException("变更合同撤销失败, contractCode:" + contractCode);
	}

	if (ContractStatusEnum.AUDITING.getCode().equals(status)) {
		String userSystemCode = contractBusinessService.getUserSystemCode(String.valueOf(createUserId));
		try {
			LOGGER.info("变更合同撤销 取消bpm审批 bpmNo:{} contractCode:{} createUserId:{}", contract.getBmpNo(), contractCode, createUserId);
			bpmService.processCancel(contract.getBmpNo(), userSystemCode);
		} catch (Exception e) {
			LOGGER.error("撤销变更合同，撤销bpm审核失败:{},{}", contract.getBmpNo(), e);
		}
	}
	//日志
	contractLogService.createLog(contractCode, LogTypeEnum.STATUS_CHANGE.getCode(), LogTypeEnum.STATUS_CHANGE.getName(), contract.getStatus().toString(), String.valueOf(createUserId), userName);
	contractLogService.createLog(contractCode, LogTypeEnum.UNDO_CONTRACT.getCode(), LogTypeEnum.UNDO_CONTRACT.getName(), bpmNo, String.valueOf(createUserId), userName);
	eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_RECALL, contractCode);
}

