		FormInstanceDto formInstanceDto = freeformApiFacade.getFormInstance(contract.getPlatformInstanceId());
		Map<String, Object> formData = formInstanceDto.getCformData();

		String dynamicChangeContent = formData.get("dynamicChangeContent").toString();
		ChangeContractFreeformDTO.DynamicChangeContent changeContent = JsonUtil.toObject(dynamicChangeContent, new TypeReference<ChangeContractFreeformDTO.DynamicChangeContent>() {});
		List<ChangeContractFreeformDTO.Photo> budgetUrl = changeContent.getBudgetUrl();
		for (ChangeContractFreeformDTO.Photo photo : budgetUrl) {
			//https://ods.lianjia.com/nrs-sales-project/1675064432417-454397153152016384-E68AA5E4BBB7E58D95%280%29.png?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Date=20230130T074153Z&X-Amz-SignedHeaders=host&X-Amz-Expires=604799&X-Amz-Credential=R1POUB6VC4EB2I8H6N6R%2F20230130%2Fcn-north-1%2Fs3%2Faws4_request&X-Amz-Signature=2999e50f3072a5721808b0f176a38fa9a19d987b8bf26e84b83293d27dc2993d
