	/**
	 * 运营后台后门接口：手动触发审批通过，小工具机器人可直接通过审批，无需调用后台接口。
	 *
	 * <p><b>注意：</b>本接口仅按 {@code auditType} 分支处理状态流转（BEFORE_SIGN / AFTER / 线下），
	 * 对 {@code auditType=NONE} 的场景（如设计费专项审核）不生效</p>
	 */
	public Object auditPass(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (!ContractStatusEnum.AUDITING.getCode().equals(contract.getStatus())) {
			return false;
		}

		boolean isOnLine = contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode());
		contract.setUserQueryStatus(UserQueryStatusEnum.VALID.getCode());
		Integer updateStatus = null;
		if (isOnLine) {
			if (contract.getAuditType().equals(AuditTypeEnum.BEFORE_SIGN.getCode())) {//签前,更新为待用户签署
				updateStatus = ContractStatusEnum.PENDING_USER_SIGN.getCode();
				Byte userSignType = contract.getUserSignType();//签署方式
				if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType()) && userSignType.equals(UserSignTypeEnum.CONFIRM.getCode())) {//变更类协议,且是确认类
					updateStatus = ContractStatusEnum.PENDING_USER_CONFIRM.getCode();//状态变更为待确认
				}
			}
			if (contract.getAuditType().equals(AuditTypeEnum.AFTER.getCode())) {//签后,更新为待盖公司章
				updateStatus = ContractStatusEnum.PENDING_COMPANY_SIGN.getCode();
			}
		} else {//如果是线下，那么直接变更到已签署
			updateStatus = ContractStatusEnum.FINISH.getCode();
			//记录日志&时间&消息
			contractLogService.createLog(contract.getContractCode(), LogTypeEnum.FINISH.getCode(), LogTypeEnum.FINISH.getName());
			contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.FINISH.getCode());
			eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_FINISH, contract.getContractCode());
		}

		byte logType = LogTypeEnum.AUDIT_PASS.getCode();
		byte nodeStatus = NodeTypeEnum.LATEST_AUDIT_PASS.getCode();
		byte contractAuditStatus = ContractAuditStatusEnum.CONTRACT_AUDIT_PASS.getCode();

		contract.setStatus(updateStatus);
		contractService.updateUnchecked(contract);
		contractLogService.createLog(contract.getContractCode(), logType, LogTypeEnum.getNameByCode(logType), assembleRemarkInfo(contract.getBmpNo()));
		//合同节点日志
		contractNodeService.updateOrCreate(contract.getContractCode(), nodeStatus);
		//新增记录
		contractAuditService.createContractAuditRecord(contract.getContractCode(), contract.getBmpNo(), contractAuditStatus, ContractAuditSceneEnum.DEFAULT, contract.getCreateUserId(), contract.getCreateUserName());
		eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_AUDIT_PASS, contract.getContractCode());
		return true;
	}

	public String assembleRemarkInfo(String bpmNo) {
		ContractLogRemarkDto remark = ContractLogRemarkDto.builder().bpmNo(bpmNo).build();

		return JsonUtil.toJsonString(remark);
	}

	/**
	 * 配置层初始化，增加证件类型
	 */
	public Object initCertificateTypeConfig() {
		List<Long> result = new LinkedList<>();

		List<ContractCityCompanyInfo> configList = contractCityCompanyInfoService.selectAll();
		List<Byte> typeList = Arrays.asList(ContractTypeEnum.SUBSCRIBE.getCode(), ContractTypeEnum.DESIGN.getCode());
		for (ContractCityCompanyInfo config : configList) {
			if (!typeList.contains(config.getContractType().byteValue()) || !config.getUserSignType().contains(UserSignTypeEnum.SIGN.getCode().toString())) {
				continue;
			}

			List<FieldsMapDTO> fieldList = JsonUtil.toObject(config.getFieldsMap(), new TypeReference<List<FieldsMapDTO>>() {});
			if (Objects.isNull(fieldList) || fieldList.isEmpty()) {
				continue;
			}

			boolean hasCertificateType = false;
			for (FieldsMapDTO fieldsMapDTO : fieldList) {
				if ("certificateType".equals(fieldsMapDTO.getFields())) {
					hasCertificateType = true;
					break;
				}
			}

			if (hasCertificateType) {
				continue;
			}

			fieldList.add(FieldsMapDTO.builder().fields("certificateType").required(1).build());
			config.setFieldsMap(JsonUtil.toJsonString(fieldList));
			contractCityCompanyInfoService.update(config);
			result.add(config.getId());
		}

		return result;
	}

	public Object initPdfCountAndImage(Integer latestId) {
		Map<String, Object> result = new HashMap<>();
		List<String> successList = new LinkedList<>();
		Map<String, Object> failList = new HashMap<>();
		int pageSize = 200;
		do {
			List<Contract> contractList = contractService.getContractList(latestId, pageSize);
			for (Contract contract : contractList) {
				latestId = contract.getId().intValue();
				if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
					//跳过已经处理过的
					List<ContractPdfImage> pdfImageList = contractPdfImageService.getListByPdfKey(contractBusinessService.getContractLatestPdfKey(contract));
					if (contract.getPdfPageCount() > 0 && !pdfImageList.isEmpty()) {
						continue;
					}

					try {
						contractBusinessService.contractPdfToImage(contract.getContractCode());
						contractBusinessService.initContractPdfCount(contract.getContractCode());
						successList.add(contract.getContractCode());
					} catch (Exception e) {
						failList.put(contract.getContractCode(), e.getMessage());
					}
					LOGGER.info("init contractCode:"+contract.getContractCode());
				}
			}
			if (contractList.size() != pageSize) {
				break;
			}
		} while (true);

		initPdfImageThreadPool.shutdown();

		result.put("success", successList);
		result.put("fail", failList);
		return result;
	}

	public Object initPdfCountAndImage(String contractCode) {
		contractBusinessService.initContractPdfCount(contractCode);
		contractBusinessService.contractPdfToImage(contractCode);
		return null;
	}
}

