public Object auditPass(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (!ContractStatusEnum.AUDITING.getCode().equals(contract.getStatus())) {
		return false;
	}

	boolean isOnLine = contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode());
	contract.setUserQueryStatus(UserQueryStatusEnum.VALID.getCode());
	Integer updateStatus = null;
	if (isOnLine) {
		if (contract.getAuditType().equals(AuditTypeEnum.BEFORE_SIGN.getCode())) {//签前,更新为待用户签署
			updateStatus = ContractStatusEnum.PENDING_USER_SIGN.getCode();
			Byte userSignType = contract.getUserSignType();//签署方式
			if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType()) && userSignType.equals(UserSignTypeEnum.CONFIRM.getCode())) {//变更类协议,且是确认类
				updateStatus = ContractStatusEnum.PENDING_USER_CONFIRM.getCode();//状态变更为待确认
			}
		}
		if (contract.getAuditType().equals(AuditTypeEnum.AFTER.getCode())) {//签后,更新为待盖公司章
			updateStatus = ContractStatusEnum.PENDING_COMPANY_SIGN.getCode();
		}
	} else {//如果是线下，那么直接变更到已签署
		updateStatus = ContractStatusEnum.FINISH.getCode();
		//记录日志&时间&消息
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.FINISH.getCode(), LogTypeEnum.FINISH.getName());
		contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.FINISH.getCode());
		eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_FINISH, contract.getContractCode());
	}

	byte logType = LogTypeEnum.AUDIT_PASS.getCode();
	byte nodeStatus = NodeTypeEnum.LATEST_AUDIT_PASS.getCode();
	byte contractAuditStatus = ContractAuditStatusEnum.CONTRACT_AUDIT_PASS.getCode();

	contract.setStatus(updateStatus);
	contractService.updateUnchecked(contract);
	contractLogService.createLog(contract.getContractCode(), logType, LogTypeEnum.getNameByCode(logType), assembleRemarkInfo(contract.getBmpNo()));
	//合同节点日志
	contractNodeService.updateOrCreate(contract.getContractCode(), nodeStatus);
	//新增记录
	contractAuditService.createContractAuditRecord(contract.getContractCode(), contract.getBmpNo(), contractAuditStatus, ContractAuditSceneEnum.DEFAULT, contract.getCreateUserId(), contract.getCreateUserName());
	eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_AUDIT_PASS, contract.getContractCode());
	return true;
}

