public Object initCertificateTypeConfig() {
	List<Long> result = new LinkedList<>();

	List<ContractCityCompanyInfo> configList = contractCityCompanyInfoService.selectAll();
	List<Byte> typeList = Arrays.asList(ContractTypeEnum.SUBSCRIBE.getCode(), ContractTypeEnum.DESIGN.getCode());
	for (ContractCityCompanyInfo config : configList) {
		if (!typeList.contains(config.getContractType().byteValue()) || !config.getUserSignType().contains(UserSignTypeEnum.SIGN.getCode().toString())) {
			continue;
		}

		List<FieldsMapDTO> fieldList = JsonUtil.toObject(config.getFieldsMap(), new TypeReference<List<FieldsMapDTO>>() {});
		if (Objects.isNull(fieldList) || fieldList.isEmpty()) {
			continue;
		}

		boolean hasCertificateType = false;
		for (FieldsMapDTO fieldsMapDTO : fieldList) {
			if ("certificateType".equals(fieldsMapDTO.getFields())) {
				hasCertificateType = true;
				break;
			}
		}

		if (hasCertificateType) {
			continue;
		}

		fieldList.add(FieldsMapDTO.builder().fields("certificateType").required(1).build());
		config.setFieldsMap(JsonUtil.toJsonString(fieldList));
		contractCityCompanyInfoService.update(config);
		result.add(config.getId());
	}

	return result;
}

