		for (Contract contract : contractList) {
			ContractBaseDTO contractBase = ContractBaseDTO.builder()
				.businessType(contract.getBusinessType())
				.contractCode(contract.getContractCode())
				.changeOrderId(contract.getChangeOrderId())
				.contractUrl(s3Service.generateUrl(contractBusinessService.getContractLatestPdfKey(contract), 1800))
				.projectOrderId(contract.getProjectOrderId())
				.status(contract.getStatus())
				.isEffective(ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus())
					|| (!ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus()) && CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus())))
				.type(contract.getType())
				.amount(contract.getAmount())
				.signChannelType(contract.getSignChannelType())
				.companyCode(contract.getCompanyCode())
				.billCodeList(quotationRelationCommonService.getBillCodeListByContractCode(contract.getContractCode()))
