		List<Contract> baseBatchContractInfo = contractService.getBatchBaseContractInfo(businessType, projectOrderArrIds, contractType, true);
		if (baseBatchContractInfo.isEmpty()) {
			return contractNodeSimpleDto;
		}

		//获取合同编号
		List<String> baseContractCodes = baseBatchContractInfo.stream().map(Contract::getContractCode).collect(Collectors.toList());
		List<ContractNode> contractNodeInfoList = contractNodeService.getListByContractCodes(baseContractCodes);
		Map<String, String> contractCodeMap = Maps.newHashMap();
		baseBatchContractInfo.forEach(baseContractInfo -> contractCodeMap.put(baseContractInfo.getContractCode(), baseContractInfo.getProjectOrderId()));

		contractNodeInfoList.forEach(contractNodeInfo -> {
			if (contractCodeMap.containsKey(contractNodeInfo.getContractCode())) {
