					.contractCode(contractNodeInfo.getContractCode())
					.nodeType(contractNodeInfo.getNodeType())
					.fireTime(contractNodeInfo.getFireTime())
					.projectOrderId(contractCodeMap.get(contractNodeInfo.getContractCode()))
					.build();
				contractNodeSimpleDto.add(contractNodeSimpleInfo);
			}
		});

		return contractNodeSimpleDto;
