	/**
	 * 组装合同的基础信息：主表基本信息、字段信息、节点信息、签约用户信息
	 *
	 * @param contractList
	 * @param infoTypes
	 * @return
	 */
	public List<ContractAllDTO> formatAllContract(List<Contract> contractList, List<String> infoTypes) {
		List<ContractAllDTO> result = new ArrayList<>();
		if (CollectionUtils.isEmpty(contractList)) {
			return result;
		}
		for (Contract contract : contractList) {
			result.add(ContractAllDTO.builder()
				.id(contract.getId())
				.businessType(contract.getBusinessType())
				.contractCode(contract.getContractCode())
				.projectOrderId(contract.getProjectOrderId())
				.changeOrderId(contract.getChangeOrderId())
				.status(contract.getStatus())
				.type(contract.getType())
				.gbCode(contract.getGbCode())
				.cityName(CityEnum.getNameByCode(contract.getGbCode()))
				.amount(contract.getAmount())
				.userConfirmStatus(contract.getUserConfirmStatus())
				.companyCode(contract.getCompanyCode())
				.userSignStatus(contract.getUserSignStatus())
				.signChannelType(contract.getSignChannelType())
				.billCodeList(ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()) ? quotationRelationCommonService.getBillCodeListByContractCode(contract.getContractCode()) : null)
				.build());
		}
		if (infoTypes.contains(InfoTypeEnum.NODE.getCode())) {
			addNodeInfo(result);
		}
		if (infoTypes.contains(InfoTypeEnum.FIELD.getCode())) {
			addFieldInfo(result);
		}
		if (infoTypes.contains(InfoTypeEnum.USER.getCode())) {
			addUser(result);
		}
		return result;
	}

	private void addNodeInfo(List<ContractAllDTO> result) {
		if (result.isEmpty()) {
			return;
		}

		List<String> contractCodeList = result.stream().map(ContractAllDTO::getContractCode).collect(Collectors.toList());
		List<ContractNode> nodeList = contractNodeService.getListByContractCodes(contractCodeList);
		Map<String, List<ContractNode>> nodeMap = new HashMap<>();
		for (ContractNode node : nodeList) {
			if (!nodeMap.containsKey(node.getContractCode())) {
				nodeMap.put(node.getContractCode(), new LinkedList<>());
			}
			nodeMap.get(node.getContractCode()).add(node);
		}

		for (ContractAllDTO contractAllDTO : result) {
			List<ContractNodeSimpleDto> resultNodeList = new LinkedList<>();
			if (nodeMap.containsKey(contractAllDTO.getContractCode())) {
				List<ContractNode> contractNodeList = nodeMap.get(contractAllDTO.getContractCode());
				for (ContractNode node : contractNodeList) {
					ContractNodeSimpleDto simpleDto = new ContractNodeSimpleDto();
					BeanUtils.copyProperties(node, simpleDto);
					resultNodeList.add(simpleDto);
				}

				//补充用户确认/签署时间
				ContractNode userConfirmSignTime = getUserConfirmSignMixTime(contractNodeList);
				if (Objects.nonNull(userConfirmSignTime)) {
					ContractNodeSimpleDto simpleDto = new ContractNodeSimpleDto();
					BeanUtils.copyProperties(userConfirmSignTime, simpleDto);
					simpleDto.setNodeType(NodeTypeEnum.USER_CONFIRM_SIGN_MIX_TIME.getCode());
					resultNodeList.add(simpleDto);
				}
			}
			contractAllDTO.setNodeList(resultNodeList);
		}
	}

	/**
	 * 获取用户确认/签署时间
	 *
	 * @param nodeList
	 * @return
	 */
	public ContractNode getUserConfirmSignMixTime(List<ContractNode> nodeList) {
		ContractNode confirmNode = null;
		ContractNode signNode = null;
		for (ContractNode node : nodeList) {
			if (NodeTypeEnum.USER_CONFIRM.getCode().equals(node.getNodeType())) {
				confirmNode = node;
			} else if (NodeTypeEnum.USER_SIGN.getCode().equals(node.getNodeType())) {
				signNode = node;
			}
		}

		return Objects.isNull(confirmNode) ? signNode : confirmNode;
	}

