	/**
	 * 仅限合同使用
	 *
	 * @param projectInfoDTO
	 * @return
	 */
	public Byte getBusinessType(ProjectInfoDTO projectInfoDTO) {
		//团装
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(projectInfoDTO.getDecorateBusinessType())) {
			return BusinessTypeEnum.GROUP_DECORATE.getCode();
		}
		//家装or局装
		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(projectInfoDTO.getDecorateBusinessType())) {
			if (Objects.isNull(projectInfoDTO.getCustomerCommission())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取业务类型错误，commission为空");
			}
			//局装 - 局装局改才认为是局装
			if (CommissionDecorateTypeEnum.PART_DECORATE.getCode().equals(projectInfoDTO.getCustomerCommission().getDecorateType())) {
				return BusinessTypeEnum.PART_DECORATE.getCode();
			} else if (CommissionDecorateTypeEnum.RENOVATE.getCode().equals(projectInfoDTO.getCustomerCommission().getDecorateType())) {
				return BusinessTypeEnum.REFORM_ALL.getCode();
			}
			return BusinessTypeEnum.HOUSE_CERTIFICATE.getCode();
		}
		if (ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(projectInfoDTO.getDecorateBusinessType())) {
			CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrderNotNull(projectInfoDTO.getProjectOrderId());
			//2.5搭售场景取对应硬装业务类型，2.0和纯零售取整装
			if (coordinationProjectOrder.hasDecorateProjectOrder() && commonBusinessService.isProcessV25New(coordinationProjectOrder.getDecorateProjectOrder().getProjectOrderId())) {
				String decorateProjectOrderId = coordinationProjectOrder.getDecorateProjectOrder().getProjectOrderId();
				ProjectInfoDTO projectInfo = projectInfoReadService.getByProjectOrderId(decorateProjectOrderId);
				return getBusinessType(projectInfo);
			}
			return BusinessTypeEnum.HOUSE_CERTIFICATE.getCode();
		}


		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "未知的业务类型");
	}

