	public List<ContractTypeListVo.ContractShowListItem> getContractShowListItem(Contract contract, List<ContractNode> contractNodeInfoList) {
		Byte signChannelType = contract.getSignChannelType();
		String signChannelTypeDesc = SignChannelTypeEnum.getNameByCode(signChannelType);
		List<ContractTypeListVo.ContractShowListItem> contractInfoText = new ArrayList<>();
		ContractTypeListVo.ContractShowListItem showListItem = new ContractTypeListVo.ContractShowListItem("签约方式", signChannelTypeDesc);
		contractInfoText.add(showListItem);

		for (ContractNode contractNode : contractNodeInfoList) {
			if (!contract.getContractCode().equals(contractNode.getContractCode())) {
				continue;
			}
			String time = DateUtils.getFormatDateStr(new Date(contractNode.getFireTime()), DateUtils.DATE_SLASH);
			if (contractNode.getNodeType().equals(NodeTypeEnum.SUBMIT.getCode())) {
				contractInfoText.add(new ContractTypeListVo.ContractShowListItem("生成时间", time));
			}

			if (contractNode.getNodeType().equals(NodeTypeEnum.USER_CONFIRM.getCode())) {
				contractInfoText.add(new ContractTypeListVo.ContractShowListItem("确认时间", time));
			}

			if (contractNode.getNodeType().equals(NodeTypeEnum.USER_SIGN.getCode())) {
				contractInfoText.add(new ContractTypeListVo.ContractShowListItem("签署时间", time));
			}
		}

		return contractInfoText;
	}

