	/**
	 * 合同完成处理
	 *
	 * @param contractCode 合同code
	 */
	@Retryable(value = Exception.class, maxAttempts = 2, backoff = @Backoff(value = 1000, multiplier = 1))
	public void contractFinishHandler(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (contract == null) {
			return;
		}

		// 已签署/已确认才可以作废历史合同
		if (!contract.getStatus().equals(ContractStatusEnum.FINISH.getCode())
			&& !contract.getStatus().equals(ContractStatusEnum.USER_CONFIRMED.getCode())) {
			return;
		}

		// 创建款项
		if (!ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			fundBaseService.createFund(contract.getProjectOrderId());
		}

		// 作废原来的合同
		cancelHistoryContracts(contract);
		// 同步资金模型
		syncNerveCenter(contract);

		//更新个性化首期款应收金额和状态
		fundBaseService.updateFundByRelateContract(contract);

		// 发送备件上传提醒
		if (ContractTypeEnum.ADVANCE.getCode().equals(contract.getType())) {
			attachCommonService.sendUploadAttachIMCardTips(contract.getProjectOrderId());
		}

		// 首期款合同签署后推送B支付金额
		if (ContractTypeEnum.ADVANCE.getCode().equals(contract.getType())) {
			ContractField advanceToBAmountField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(),
				ContractProjectInfoReq.Fields.advanceToBAmount);
			if (advanceToBAmountField != null && StringUtils.isNotBlank(advanceToBAmountField.getFieldValue())) {
				BigDecimal advanceToBAmount = new BigDecimal(advanceToBAmountField.getFieldValue());
				if (advanceToBAmount.compareTo(BigDecimal.ZERO) > 0) {
					Map<String, Object> nodeKeyData = new HashMap<>();
					nodeKeyData.put("advanceToBAmount", advanceToBAmount);
					projectNodeRecordWriteService.insertNodeRecord(contract.getProjectOrderId(),
						ProjectNodeEnum.ADVANCE_PUSH_B_AMOUNT,
						ProjectNodeStatusEnum.DONE,
						nodeKeyData);
				}
			}
		}
	}

