	public void sendOfflineContractSmsRemind(Contract contract) {
		//团装不发送短信
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType())) {
			return;
		}
		MiniPayChannelAppNameEnum miniPayChannelAppNameEnum = commonBusinessService.getMiniProgramType(contract.getProjectOrderId());
