	 */
	public BusinessSnapshotDTO getBusinessSnapshotDTO(Contract contract, ProjectInfoDTO projectInfoDTO, List<ContractUser> contractUsers) {
		BusinessSnapshotDTO businessSnapshotDTO = BusinessSnapshotDTO.builder()
			.projectOrderId(contract.getProjectOrderId())
			.projectAddress(homeAndPcCommonService.getResblockAddress(projectInfoDTO))
