	/**
	 * APP端需要单独拼接前缀
	 *
	 * @param platform
	 * @param fileType
	 * @param sourceUrl
	 * @return
	 */
	public String getUrlByPlatForm(String platform, String fileType, String sourceUrl) {
		if (HeaderPlatFormEnum.APP.getCode().equals(platform)) {
			if ("pdf".equals(fileType)) {
				return "lianjiabeike://dc/decorate/filebrowse?url=" + CommonUtil.urlEncode(CommonUtil.decode(sourceUrl)) + "&is_pdf=true";
			} else if ("schema".equals(fileType)) {
				return "lianjiabeike://dc/webbrowser?url=" + CommonUtil.urlEncode(sourceUrl);
			} else {
				throw new NrsBusinessException("暂不支持此种文件类型" + fileType);
