	public WxContractShareInfo createWxContractShareUrl(String contractCode, Integer brandId) {
		try {
			Contract contract = contractService.getByContractCode(contractCode);
			if (contract == null) {
				throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "当前合同不存在", Level.WARN);
			}
			//校验合同是否可以分享
			contractUnifyService.checkCanShare(contractCode);

			//通用合同分享调整链接
			//获取链接url
			String url = String.format(contractApolloConfig.getContractSignMpPagePathUrl(), contractCode);
			LOGGER.info("合同分享链接url:{}", url);
			//获取短链接
			String pagePath = String.format(contractApolloConfig.getContractSignMpPagePathNew(), URLEncoder.encode(url, "UTF-8"));
			LOGGER.info("合同分享链接:{}", pagePath);
			//合并发起合同分享链接
			String mergePagePath = contractApolloConfig.getContractMergeSignMpPagePath().concat("contractCode=").concat(contractCode).concat("&projectOrderId=").concat(contract.getProjectOrderId()).concat("&from=wxShare");
			LOGGER.info("合同分享链接mergePagePath:{}", mergePagePath);
			//合同是否包含关联合同，有关联合同为true，没有为false
			Boolean mergeLaunch = false;
			List<ContractRelation> relationList = contractRelationService.getRelationList(contractCode);
			if (!CollectionUtils.isEmpty(relationList)) {
				pagePath = mergePagePath + "&signSceneType=" + SignSceneTypeEnum.FORMAL.getCode();
				mergeLaunch = true;
			}
			ContractRelation byRelateContractCode = contractRelationService.getByRelateContractCode(contractCode);
			if (byRelateContractCode != null && !ContractTypeEnum.AUTH_AGENT.getCode().equals(contract.getType())) {
				pagePath = mergePagePath + "&signSceneType=" + SignSceneTypeEnum.FORMAL.getCode();
				mergeLaunch = true;
				contract = contractService.getByContractCode(byRelateContractCode.getContractCode());
			}
			//B+C协同发起个性化合同是协同发起时的分享链接，也就是当时的B合同的分享链接
			if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
				//不是变更发起的公对公个性化合同，不是单独发起的个性化合同，则为协同发起的个性化合同
				if (StringUtils.isBlank(contract.getChangeOrderId()) && !homeAndPcCommonService.isMultipleQuotePersonalContract(contract)) {
					Contract packageFormalContract = contractService.getLatestContract(contract.getProjectOrderId(), ContractTypeEnum.PACKAGE_FORMAL.getCode());
					if (packageFormalContract == null) {
						throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "当前合同不存在", Level.WARN);
					}
					contract = packageFormalContract;
					pagePath = mergePagePath + "&signSceneType=" + SignSceneTypeEnum.FORMAL.getCode();
					mergeLaunch = true;
				}
				if (homeAndPcCommonService.isMultipleQuotePersonalContract(contract)) {
					//多报价单个性化合同
					pagePath = mergePagePath + "&signSceneType=" + SignSceneTypeEnum.PERSONAL.getCode();
					mergeLaunch = true;
				}
			}

			List<ContractUser> contractUsers = contractUserService.getListByContractCode(contractCode);
			//获取手机签署手机号
			String phone = contractUsers.stream()
				.filter(contractUser -> IsSignEnum.YES.getCode().equals(contractUser.getIsSign()))
				.findFirst()
				.orElse(ContractUser.builder().phone("").build())
				.getPhone();
			String name = contractUsers.stream()
				.filter(contractUser -> IsSignEnum.YES.getCode().equals(contractUser.getIsSign()))
				.findFirst()
				.orElse(ContractUser.builder().name("").build())
				.getName();


			if (contractApolloConfig.isSupportWatchVideo(contract.getBusinessType(), contract.getGbCode())) {
				boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
				//判断是否需要看视频
				if (contractVideoService.needWatchVideo(contract, processV25)
					&& (ContractStatusEnum.PENDING_USER_CONFIRM.getCode().equals(contract.getStatus())
					|| ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus()))) {
					String signPhone = cipherService.decrypt(phone);

					// 手机号注销获取不到ucId降级
					MemberDetailDTO memberDetailDTO = null;
					try {
						memberDetailDTO = memberRpc.getClientUcIdByPhone(Long.parseLong(signPhone));
					} catch (Exception e) {
						LOGGER.info("手机号请求member获取ucId失败", e);
					}
					Integer watchStatus = null;
					if (memberDetailDTO == null) {
						//手机号注销或者没有注册,判断为没看过视频
						watchStatus = WatchStatusEnum.NOT_FINISH.getCode();
					} else {
						String ucId = memberDetailDTO.getId().toString();
						watchStatus = contractVideoService.getWatchStatusNew(contract, ucId);
					}

					if (WatchStatusEnum.NOT_FINISH.getCode().equals(watchStatus)) {
						// 需要观看视频
						String videoPagePath = contractApolloConfig.getVideoPagePath().concat("projectOrderId=")
							.concat(contract.getProjectOrderId()).concat("&contractCode=").concat(contractCode)
							.concat("&from=wxShare").concat("&mergeLaunch=").concat(mergeLaunch.toString());
						Integer signSceneType = homeAndPcCommonService.isMultipleQuotePersonalContract(contract) ? SignSceneTypeEnum.PERSONAL.getCode() : SignSceneTypeEnum.FORMAL.getCode();
						videoPagePath = videoPagePath + "&signSceneType=" + signSceneType;
						pagePath = videoPagePath;
					}
				}
			}

			String pageTitle = "分享合同";
			LOGGER.info("分享合同链接：{}", pagePath);
			WxShareInfo wxShareUrl = wxShortUrlService.createWxShareUrl(WxShareUrlParam.builder()
				.brandId(brandId)
				.pagePath(pagePath)
				.pageTitle(pageTitle)
				.projectOrderId(contract.getProjectOrderId())
				.build());
			return WxContractShareInfo.builder()
				.url(wxShareUrl.getUrl())
				.phone(phone)
				.signatoryName(name)
				.build();
		} catch (Exception e) {
			LOGGER.warn("获取合同分享链接失败", e);
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), e.getMessage(), Level.WARN);
		}
	}


	/**
	 * 正签&变更合同推送大表数据
	 */
	public void contractDataPushBigTable(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (contract == null) {
			return;
		}
		//只处理正签&变更合同
		List<Byte> dealContractTypes = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PACKAGE_CHANGE.getCode());
		if (!dealContractTypes.contains(contract.getType())) {
			return;
		}
		//构造基础参数
		ProjectInfo projectInfo = this.projectInfoService.getByProjectOrderId(contract.getProjectOrderId());
		ProjectParams.DecorationProjectUpsert params = ProjectParams.DecorationProjectUpsert.builder()
			.projectSystem(ProjectSystem.HOME2.getCode())
			.projectClass(NerveCenterTransfer.decorateTypeToProjectClass(projectInfo.getDecorateType()))
			.outOrderNo(projectInfo.getProjectOrderId())
			.build();
		params.setOperatorUcid(Long.valueOf(contract.getCreateUserId()));
		params.setOperatorName(serviceId);
		params.setServiceId(serviceId);
		params.setCustCode(projectInfo.getCustomerCommissionCode());

		formalContractPushBigTableParamFill(contract, params);
		changeContractPushBigTableParamFill(contract, params);

		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contract.getContractCode());
		Map<String, String> fieldMap = contractFieldList.stream().collect(Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue, (v1, v2) -> v2));

		//获取工程承包方式&税率,没有默认为没有承包方式
		int taxRate = Integer.parseInt(fieldMap.getOrDefault("taxRate", "0"));
		int projectContractModeCode = Integer.parseInt(fieldMap.getOrDefault("projectContractModeCode", "0"));
		params.setQuotationTxRate(new BigDecimal(taxRate).divide(new BigDecimal("100")));
		params.setMaterialAndLaborSupportType(projectContractModeCode);
		//推大表
		nerveCenterRpc.upsertDecorationProject(contract.getProjectOrderId(), params);
		LOGGER.info("正签&变更合同推送大表数据完成，contractCode：{}，contractType:{}", contract.getContractCode(), contract.getType());
	}

	/**
	 * 推送大表数据正签合同参数补充
	 */
	private void formalContractPushBigTableParamFill(Contract contract, ProjectParams.DecorationProjectUpsert params) {
		if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
			return;
		}
		BigDecimal amount = contract.getAmount();
		//正签合同金额
		params.setContractAmount(amount);
		//正签合同时间
		ContractNode contractNode = contractNodeService.getListByContractCode(contract.getContractCode()).stream().filter(item -> item.getNodeType().equals(NodeTypeEnum.FINISH.getCode())).findFirst().orElse(null);
		//LocalDateTime 设置为当前时间
		LocalDateTime signDateTime = LocalDateTime.now();
		if (!Objects.isNull(contractNode)) {
			signDateTime = LocalDateTime.ofInstant(Instant.ofEpochMilli(contractNode.getFireTime()), ZoneId.systemDefault());
		}
		params.setContractDate(signDateTime);
	}


	/**
	 * 推送大表数据变更合同参数补充
	 */
	private void changeContractPushBigTableParamFill(Contract contract, ProjectParams.DecorationProjectUpsert params) {
		if (!ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType())) {
			return;
		}
		//设计师kehr组织信息
		params.setProjectOrgs(changeOrderWriteService.designerKeHr(contract.getProjectOrderId()));
	}


	/**
	 * 获取计算预估合同额使用的面积类型
	 *
	 * @return
	 */
	public Integer getExpectAmountUseAreaType(String projectOrderId) {
		ProjectOrganizationDTO projectInfo = projectReadService.getProjectOrganizationByProjectOrderId(
			projectOrderId);
		Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
		Integer gbCode = projectInfo.getGbCode();
		String companyCode = projectInfo.getCompanyCode();
		companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectOrderId, gbCode, companyCode, ContractTypeEnum.ADVANCE.getCode());
		String convertProjectOrderId = commonBusinessService.convertProjectOrderId(projectOrderId, ContractTypeEnum.ADVANCE.getCode());
		ContractVersionConfig contractConfigAllVersion = contractConfigVersionService.getContractConfigAllVersion(convertProjectOrderId);
		//字段配置信息
		List<ContractFieldConfig> fieldConfigs = contractUnifyService.getFieldConfigAdapt(projectOrderId, gbCode, companyCode, businessType, ContractTypeEnum.ADVANCE.getCode(), contractConfigAllVersion.getFieldConfigVersion());
		ContractFieldConfig valuationAreaField = fieldConfigs.stream().filter(fieldConfig -> fieldConfig.getFieldKey().equals("valuationArea")).findFirst().orElse(null);
		ContractFieldConfig pricingAreaField = fieldConfigs.stream().filter(fieldConfig -> fieldConfig.getFieldKey().equals("pricingArea")).findFirst().orElse(null);
		if (valuationAreaField != null) {
			return AreaEnum.VALUATION_AREA.getAreaType();
		}
		if (pricingAreaField != null) {
			return AreaEnum.PRICING_AREA.getAreaType();
		}
		return AreaEnum.BUILDING_AREA.getAreaType();
	}

	public ExpectContractAmountComputeInfo getExpectAmountUseAreaInfo(String projectOrderId) {
		Integer expectAmountUseAreaType = getExpectAmountUseAreaType(projectOrderId);
		Contract contract = contractService.getLatestUserSignContract(projectOrderId, ContractTypeEnum.ADVANCE.getCode());
		if (contract == null) {
			LOGGER.error("未找到预估合同,projectOrderId:{}", projectOrderId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "未找到预估合同");
		}
		ContractField contractField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), AreaEnum.getFieldKeyByAreaType(expectAmountUseAreaType));
		if (contractField == null || StringUtils.isBlank(contractField.getFieldValue())) {
			LOGGER.error("未找到预估合同面积信息,projectOrderId:{},contractCode:{}", projectOrderId, contract.getContractCode());
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "未找到预估合同面积信息");
		}
		return ExpectContractAmountComputeInfo.builder()
			.areaType(expectAmountUseAreaType)
			.areaValue(contractField.getFieldValue())
			.build();
	}

	/**
	 * 测试城市映射真实城市
	 *
	 * @return
	 */
	public Integer getCityMapping(Integer gbCode, String projectOrderId) {
		if (!(CityEnum.CESHICHENG.getGbCode() == gbCode)) {
			return gbCode;
		}
		ProjectInfo projectInfo = projectInfoService.getByProjectOrderId(projectOrderId);
		String convertProjectOrderId = commonBusinessService.convertProjectOrderId(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		ContractVersionConfig contractConfigAllVersion = contractConfigVersionService.getContractConfigAllVersion(convertProjectOrderId);
		String companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectOrderId, projectInfo.getGbcode(), projectInfo.getCompanyCode(), ContractTypeEnum.PACKAGE_FORMAL.getCode());
