	/**
	 * 查询项目指定完成态合同、指定字段信息
	 */
	public List<ContractFieldQueryResp> queryContractFieldInfo(ContractFieldQueryParam queryParam) {
		//查询最新完成态的合同
		Contract contract = contractService.getLatestContract(queryParam.getProjectOrderId(), queryParam.getContractTypeList());
		if (contract == null) {
			LOGGER.warn("查询项目指定合同、指定字段信息未找到合同，queryParam:{}", JSON.toJSONString(queryParam));
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "查询项目指定合同、指定字段信息未找到合同", Level.WARN);
		}
		//查询合同字段信息
		Map<String, String> fieldMap = contractFieldService.getFieldMap(contract.getContractCode());
		//处理查询字段
		List<ContractFieldQueryResp> result = new ArrayList<>();
		List<ContractFieldQueryEnum> contractFieldQueryEnumList = queryParam.getQueryFields();
		for (ContractFieldQueryEnum queryEnum : contractFieldQueryEnumList) {
			FieldHandleStrategy fieldHandleStrategy = fieldHandleStrategyFactory.getFieldHandleStrategy(queryEnum);
			ContractFieldQueryResp queryResp = fieldHandleStrategy.handleField(queryEnum.getFieldKey(), fieldMap.getOrDefault(queryEnum.getFieldKey(), null));
			result.add(queryResp);
		}
		return result;
	}

