	/**
	 * 解约协议签署完成处理
	 * 如果是通过合并发起的方式发起的解约协议签署完成，需要发送【项目解约协议签署完成消息】
	 *
	 * @param contractCode
	 */
	public void terminalContractFinishDeal(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (!ContractTypeEnum.TERMINAL.getCode().equals(contract.getType())) {
			return;
		}
		ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contractCode);
		if (contractRelation == null) {
			LOGGER.info("解约协议签署完成处理，未找到合同关联关系，不需要发送【项目解约协议签署完成消息】,contractCode:{}", contractCode);
			return;
		}
		//发送对应消息
		TerminalContractFinishEvent event = TerminalContractFinishEvent.builder()
			.projectOrderId(contract.getProjectOrderId())
			.contractCode(contractCode)
			.build();
		eventService.publish(event, EventType.TERMINAL_CONTRACT_FINISH, contract.getContractCode());
	}

