	/**
	 * 构建合并发解约协议对应退单DTO
	 *
	 * @param projectOrderId
	 */
	public CancelOrderBaseInfoDTO buildMergeLaunchCancelOrderDTO(String projectOrderId) {
		List<FundAmountDTO> fundAmountList = new ArrayList<>();
		List<FundInfo> fundInfoList = fundInfoService.getFundInfoByProjectOrderIdAndFundTypeList(projectOrderId, FundTypeEnum.CANCEL_FUND_TYPE);
		for (FundInfo fundInfo : fundInfoList) {
			BigDecimal deductibleAmount = FundTypeEnum.DEPOSIT.getValue().equals(fundInfo.getFundType()) ? fundInfo.getPaidAmount().subtract(fundInfo.getDeductedAmount()) : BigDecimal.ZERO;
			FundAmountDTO fundAmountDTO = FundAmountDTO.builder()
				.fundType(fundInfo.getFundType())
				.fundName(fundInfo.getFundName())
				.fundStatus(fundInfo.getFundStatus())
				.fundStatusDesc(FundStatusEnum.getEnumDescByCode(fundInfo.getFundStatus()))
				.oldDueAmount(fundInfo.getFundAmount())
				.dueAmount(BigDecimal.ZERO)
				.paidAmount(fundInfo.getPaidAmount())
				.tobePaidAmount(BigDecimal.ZERO.subtract(fundInfo.getPaidAmount()))
				.deductibleAmount(deductibleAmount)
				.build();
			fundAmountList.add(fundAmountDTO);
		}
		CancelOrderCalcResDTO cancelOrderCalcResDTO = cancelOrderService.calcFundAmount(fundAmountList);

		LaunchRefundReqDTO refundReqDTO = LaunchRefundReqDTO.builder()
			.refundChannel(RefundChannelEnum.REFUND_TO_WALLET.getCode())
			.build();
		return CancelOrderBaseInfoDTO.builder()
			.cancelOrderAmount(cancelOrderCalcResDTO.getTotalAmount())
			.fundAmountList(fundAmountList)
			.refundInfo(JSON.toJSONString(refundReqDTO))
			.build();
	}


