	/**
	 * 备件校验结果记录
	 */
	public void verifyContractAttach(Contract contract) {
		if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType()) && !ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType())) {
			return;
		}

		List<ContractAttach> attachTypes = contractAttachService.getListByContractCode(contract.getContractCode(), AttachTypeEnum.HOUSE_CERTIFICATE.getCode());
		List<String> documentCodes = attachTypes.stream().map(ContractAttach::getDocumentCode).distinct().collect(Collectors.toList());
		if (CollectionUtils.isEmpty(documentCodes)) {
			return;
		}

		List<CertificateVerifyResponseDTO> certificateVerifyResponseDTOS = certificateRpc.certificateVerify(CertificateVerifyByCodeRequestDTO.builder()
			.ucId(Long.parseLong(contract.getModifyUserId()))
			.projectOrderId(contract.getProjectOrderId())
			.documentCodeList(documentCodes)
			.certificateType(CertificateTypeEnum.FANG_CHAN_ZHENG_MING.getCertificateId())
			.build());

		for (ContractAttach attachType : attachTypes) {
			String documentCode = attachType.getDocumentCode();
			CertificateVerifyResponseDTO certificateVerifyResult = certificateVerifyResponseDTOS.stream().filter(certificateVerifyResponseDTO -> StringUtils.equals(documentCode, certificateVerifyResponseDTO.getDocumentCode()))
				.findFirst().orElse(null);

			if (certificateVerifyResult == null) {
				continue;
			}

			Integer veracity;
			if (certificateVerifyResult.getResult()) {
				veracity = ContractAttachVeracityEnum.PASS.getCode();
			} else {
				veracity = ContractAttachVeracityEnum.FAIL.getCode();
			}

			contractAttachService.update(ContractAttach.builder().id(attachType.getId()).veracity(veracity).build());
		}

	}

	/**
	 * 选择首选合同
	 * 优先选择type=3（首期款），其次选择type=6（正签合同）
	 * 其它选择type=1定金，type = 2设计合同
	 *
	 * @param contractList 合同列表
	 * @return 首选合同，如果没有符合条件的合同则返回null
	 */
	public Contract selectPreferredContract(List<Contract> contractList) {
		if (CollectionUtils.isEmpty(contractList)) {
			return null; // 如果合同列表为空，返回null
		}

		// 使用单次流操作，优先选择type=3，其次type=6
		return contractList.stream()
			.min(Comparator.comparingInt(Contract::getType)) // 按类型升序排序，优先选择type=3
			.orElse(null); // 如果没有符合条件的合同，返回null
	}

	/**
	 * 获取订单号到合同编码的映射。
	 *
	 * <p>该方法处理项目订单关系列表，生成订单号到合同编码的映射。具体处理逻辑如下：</p>
	 * <ul>
	 *   <li>对于首期款订单，直接从项目订单关系中提取订单号和合同编码的映射。</li>
	 *   <li>对于报价单订单，首先提取所有相关的报价单编码，然后通过报价单编码获取对应的合同编码，
	 *       最后将订单号与合同编码进行映射。</li>
	 * </ul>
	 *
	 * @param projectOrderRelations 项目订单关系列表
	 * @return 订单号到合同编码的映射，如果输入列表为空，则返回空的映射
	 */
	private Map<String, String> getCompositeOrderToContractCodes(List<ProjectOrderRelation> projectOrderRelations) {
		// 检查输入列表是否为空，如果为空则返回一个新的空映射
		if (CollectionUtils.isEmpty(projectOrderRelations)) {
			return Maps.newHashMap();
		}

		// 初始化一个映射，用于存储订单号到合同代码的映射
		Map<String, String> orderNoToContractCodeMap = Maps.newHashMap();

		// 处理首期款订单直接关联的合同
		// 遍历项目订单关系列表，过滤出关系类型为首期款订单的项
		projectOrderRelations.stream()
			.filter(relation -> ProjectOrderRelationTypeEnum.DOWN_PAYMENT_ORDER.getCode().equals(relation.getRelationType()))
			.forEach(relation -> {
				// 将订单号和合同代码放入映射中
				if (StringUtils.isNotBlank(relation.getContractCode())) {
					orderNoToContractCodeMap.put(relation.getOrderNo(), relation.getContractCode());
				}
			});

		// 处理报价单关联的合同
		// 从项目订单关系中提取所有报价单类型订单的账单代码
		List<String> billCodes = projectOrderRelations.stream()
			.filter(t -> ProjectOrderRelationTypeEnum.QUOTATION_ORDER.getCode().equals(t.getRelationType()))
			.map(ProjectOrderRelation::getBillCode)
			.filter(StringUtils::isNotBlank)
			.collect(Collectors.toList());

		// 如果账单代码列表不为空，继续处理
		if (!CollectionUtils.isEmpty(billCodes)) {
			// 根据账单代码和关系状态获取相关的合同关系
			List<ContractQuotationRelation> billContractRelations = contractQuotationRelationService.getByBillCodesAndStatus(
				billCodes,
				RelationStatusEnum.RELATED.getCode()
			);
			if (CollectionUtils.isEmpty(billContractRelations)) {
				return orderNoToContractCodeMap; // 如果没有相关的合同关系，直接返回当前映射
			}

			// 创建一个映射，将账单代码与合同代码关联
			Map<String, String> billCodeToContractCodeMap = billContractRelations.stream()
				.collect(Collectors.toMap(
					ContractQuotationRelation::getBillCode, // 账单代码作为键
					ContractQuotationRelation::getContractCode, // 合同代码作为值
					(first, second) -> first // 如果有重复的键，保留第一个值
				));

			// 再次遍历项目订单关系，处理报价单类型订单
			projectOrderRelations.stream()
				.filter(t -> ProjectOrderRelationTypeEnum.QUOTATION_ORDER.getCode().equals(t.getRelationType()))
				.forEach(relation -> {
					// 从账单代码到合同代码的映射中获取合同代码
					String contractCode = billCodeToContractCodeMap.get(relation.getBillCode());
					// 如果合同代码不为空，将订单号和合同代码放入映射中
					if (StringUtils.isNotBlank(contractCode)) {
						orderNoToContractCodeMap.put(relation.getOrderNo(), contractCode);
					}
				});
		}

		// 返回最终构建的订单号到合同代码的映射
		return orderNoToContractCodeMap;
	}

	/**
	 * 根据复合订单号列表查询合同甲方信息
	 *
	 * @param compositeOrderNoList 复合订单号列表
	 * @return 复合订单号到合同甲方的映射
	 */
	public List<ContractPartyADTO> queryContractPartyAByCompositeOrderNos(List<String> compositeOrderNoList) {
		List<ProjectOrderRelation> projectOrderRelations = getQuotationProjectOrderRelations(compositeOrderNoList, Arrays.asList(
			ProjectOrderRelationTypeEnum.QUOTATION_ORDER.getCode(),
			ProjectOrderRelationTypeEnum.DOWN_PAYMENT_ORDER.getCode()
		));
		if (CollectionUtils.isEmpty(projectOrderRelations)) {
			LOGGER.info("查询订单关联关系为空，compositeOrderNoList:{}", compositeOrderNoList);
			return Collections.emptyList();
		}
		List<ContractPartyADTO> res = new ArrayList<>();

		Map<String, String> compositeOrderToContractCodes = getCompositeOrderToContractCodes(projectOrderRelations);
		List<String> contractCodes = new ArrayList<>(compositeOrderToContractCodes.values());
		if (CollectionUtils.isEmpty(contractCodes)) {
			LOGGER.info("查询订单关联合同编码为空，compositeOrderNoList:{}", compositeOrderNoList);
			return Collections.emptyList();
		}
		Map<String, Contract> codeToContract = getCodeToContractFilterFinishMap(contractCodes);
		Map<String, ContractFieldForCodeDTO> contractField = getContractFieldForCode(contractCodes);
		LOGGER.info("查询订单关联合同信息，projectOrderRelations:{},compositeOrderToContractCodes:{},codeToContract:{},contractField:{}"
			, JSON.toJSONString(projectOrderRelations), JSON.toJSONString(compositeOrderToContractCodes)
			, JSON.toJSONString(codeToContract), JSON.toJSONString(contractField));
		for (String compositeOrderNo : compositeOrderNoList) {
			//orderNo->contractCode
			String contractCode = compositeOrderToContractCodes.get(compositeOrderNo);
			if (StringUtils.isBlank(contractCode)) {
				LOGGER.info("查询订单关联合同为空，compositeOrderNo:{}", compositeOrderNo);
				continue;
			}
			Contract contract = codeToContract.get(contractCode);
			ContractFieldForCodeDTO contractFieldForCodeDTO = contractField.get(contractCode);


			if (contract == null || contractFieldForCodeDTO == null || StringUtils.isEmpty(contractFieldForCodeDTO.getContractPartyA())) {
				LOGGER.info("查询合同信息为空，compositeOrderNo:{}", compositeOrderNo);
				continue;
			}
			String contractPartyA = contractFieldForCodeDTO.getContractPartyA();

			res.add(ContractPartyADTO.builder()
				.compositeOrderNo(compositeOrderNo)
				.contractCode(contract.getContractCode())
				.contractPartyA(contractPartyA)
				.build());
		}
		return res;
	}

	/**
	 * 获取合同编码到合同甲方的映射
	 *
	 * @param contractCodes 合同编码列表
	 * @return 合同编码到合同甲方的映射
	 */
	private Map<String, ContractFieldForCodeDTO> getContractFieldForCode(List<String> contractCodes) {
		Map<String, ContractFieldForCodeDTO> contractMap = new HashMap<>();
		List<ContractField> contractFields = contractFieldService.getListByContractCodes(contractCodes);
		if (CollectionUtils.isEmpty(contractFields)) {
			return Collections.emptyMap();
		}
		List<String> fieldKeyNames = Arrays.asList(FieldEnum.CONTRACT_OBJECT_TYPE.getKey(), FieldEnum.OWNER_NAME.getKey(), FieldEnum.COMPANY_NAME.getKey());
		List<ContractField> contractFieldList = contractFieldService.getValueByContractCodeAndFieldKey(contractCodes, fieldKeyNames);
		Map<String, List<ContractField>> contractFieldGroupByCode = contractFieldList.stream()
			.collect(Collectors.groupingBy(ContractField::getContractCode));
		for (String contractCode : contractCodes) {
			List<ContractField> contractCodeToContractFields = contractFieldGroupByCode.get(contractCode);
			Map<String, String> feildMap = contractCodeToContractFields.stream()
				.collect(Collectors.toMap(
					ContractField::getFieldKey,
					ContractField::getFieldValue,
					(first, second) -> first
				));
			String contractObjectType = feildMap.getOrDefault(FieldEnum.CONTRACT_OBJECT_TYPE.getKey(), ContractObjectTypeEnum.PERSON.getCode().toString());
			String contractName = contractObjectType.equals(ContractObjectTypeEnum.PERSON.getCode().toString()) ?
				feildMap.get(FieldEnum.OWNER_NAME.getKey()) :
				feildMap.get(FieldEnum.COMPANY_NAME.getKey());
			if (StringUtils.isNotBlank(contractName)) {
				ContractFieldForCodeDTO contractFieldForCodeDTO = new ContractFieldForCodeDTO();
				contractFieldForCodeDTO.setContractPartyA(contractName);
				contractFieldForCodeDTO.setContractObjectType(Byte.valueOf(contractObjectType));
				contractMap.put(contractCode, contractFieldForCodeDTO);
			}
		}
		return contractMap;
	}

	private @NotNull Map<String, Contract> getCodeToContractFilterFinishMap(List<String> contractCodes) {
		List<Contract> contractList = contractService.getListByContractCodes(contractCodes, false);

		return contractList.stream()
			.filter(contract -> ContractStatusEnum.USER_CONFIRMED.getCode().equals(contract.getStatus())
				|| ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())
				|| (ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus())
				&& CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus())))
			.collect(Collectors.toMap(
				Contract::getContractCode,
				Function.identity(),
				(first, second) -> first
			));
	}

	/**
	 * 根据家装订单号获取已完成的个人合同甲方信息
	 *
	 * @param homeOrder 家装订单号
	 * @return 个人合同甲方信息列表
	 */
	public List<PersonalContractPartyADTO> getCompletedPersonalContractsByHomeOrder(String homeOrder) {
		List<PersonalContractPartyADTO> res = new ArrayList<>();
		String convertProjectOrderId = getRelateProjectId(homeOrder);
		if (StringUtils.isBlank(convertProjectOrderId)) {
			return res;
		}
		List<Contract> personalContractList = contractService.getLatestUserSignContractByContractTypes(convertProjectOrderId, Collections.singletonList(ContractTypeEnum.PERSONAL.getCode()));
		if (CollectionUtils.isEmpty(personalContractList)) {
			return res;
		}
		List<String> contractCodes = personalContractList.stream().map(Contract::getContractCode).collect(Collectors.toList());
		Map<String, ContractFieldForCodeDTO> contractField = getContractFieldForCode(contractCodes);
		for (Contract contract : personalContractList) {
			ContractFieldForCodeDTO contractFieldForCodeDTO = contractField.get(contract.getContractCode());
			if (contractFieldForCodeDTO == null || StringUtils.isEmpty(contractFieldForCodeDTO.getContractPartyA())) {
				continue;
			}
			res.add(PersonalContractPartyADTO.builder()
				.contractCode(contract.getContractCode())
				.contractPartyA(contractFieldForCodeDTO.getContractPartyA())
				.contractObjectType(contractFieldForCodeDTO.getContractObjectType())
				.companyCode(contract.getCompanyCode())
				.gbCode(contract.getGbCode())
				.build());
		}
		return res;
	}

	/**
	 * 项目单号兼容：搭售/整装场景获取整装项目单号、纯零售场景获取主单号
	 */
	public String getRelateProjectId(String homeOrder) {
		CoordinationProjectInfo coordinationProjectInfo = commonBusinessService.getCoordinationProjectOrderNotNull(homeOrder);
		if (ObjectUtil.isEmpty(coordinationProjectInfo) || CollectionUtil.isEmpty(coordinationProjectInfo.getCoordinationProjectRelationList())) {
			return homeOrder;
		}
		if (ObjectUtil.isEmpty(coordinationProjectInfo.getDecorateProjectOrder()) && ObjectUtil.isEmpty(coordinationProjectInfo.getRetailProjectOrder())) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), String.format("项目单号信息不存在,项目单号：%s", homeOrder), Level.ERROR);
		}
		CoordinationProjectRelationInfo decorateProjectOrder = coordinationProjectInfo.getDecorateProjectOrder();
		if (ObjectUtil.isNotEmpty(decorateProjectOrder)) {
			return decorateProjectOrder.getProjectOrderId();
		}
		return homeOrder;
	}

	/**
	 * 发送合同提醒支付延时消息
	 *
	 * @param contractCode
	 */
	public void triggerContractRemindPayDelayMessage(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (ObjectUtil.isEmpty(contract)) {
			LOGGER.error("合同不存在，contractCode:{}", contractCode);
			return;
		}
		// 仅处理正签合同、首期款合同
		if (contract == null
			|| (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType()) && !ContractTypeEnum.ADVANCE.getCode().equals(contract.getType()))) {
			return;
		}
		// 判断是否2.5订单
		boolean processV25New = commonBusinessService.isProcessV25New(contract.getProjectOrderId());
		if (!processV25New) {
			// 非2.5订单不处理
			return;
		}
		// 查询项目信息
		ProjectInfoDTO projectInfo = projectInfoReadService.getByProjectOrderId(contract.getProjectOrderId());
		if (projectInfo == null) {
			LOGGER.error("项目不存在，projectOrderId:{}", contract.getProjectOrderId());
			return;
		}
		Byte businessType = getBusinessType(projectInfo);
		if (!BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			// 非整装订单不处理
			return;
		}
		// 发送延时队列消息
		ContractRemindPayDelayMessage contractRemindPayDelayMessage = ContractRemindPayDelayMessage.builder()
			.projectOrderId(contract.getProjectOrderId())
			.occurTime(new Date())
			.build();
		// 发送消息到延时队列
		rocketMqService.sendDelayMessage(contract.getProjectOrderId(), JSON.toJSONString(contractRemindPayDelayMessage), RocketmqDelayLevelEnum.LEVEL_18.getLevel(), ReceiptCIService.contractRemindPayDelayMessage);
	}

	/**
	 * 基于合同code查询正签合同所需的字段
	 */
	public List<ContractFieldQueryResp> queryContractFieldByContractCode(String contractCode, String ucid) {
		checkUserRolePermission(ucid);
		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contractCode);
		if (CollectionUtils.isEmpty(contractFieldList)) {
			return Collections.emptyList();
		}
		List<ContractFieldQueryResp> res = new ArrayList<>();
		Byte contractObjectType = contractFieldList.stream().filter(item -> FieldEnum.CONTRACT_OBJECT_TYPE.getKey().equals(item.getFieldKey()))
			.map(ContractField::getFieldValue)
			.filter(StringUtils::isNotBlank)
			.map(Byte::valueOf)
			.findFirst()
			.orElse(ContractObjectTypeEnum.PERSON.getCode());
		// 获取字段表信息
		for (ContractField contractField : contractFieldList) {
			if (ObjectUtil.isNotEmpty(contractField.getFieldValue())
				&& ContractFieldEnum.CONTRACT_FIELD_LIST.contains(contractField.getFieldKey())) {
				// 个人签约不返回对公字段
				if ((ContractObjectTypeEnum.PERSON.getCode().equals(contractObjectType)
					&& ContractFieldEnum.COMPANY_SIGN_FIELD_LIST.contains(contractField.getFieldKey()))
					|| (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)
					&& ContractFieldEnum.PERSONAL_SIGN_FIELD_LIST.contains(contractField.getFieldKey()))) {
					continue;
				}
				// 手机号只展示前三位和后四位
				if (ContractFieldEnum.PHONE_FIELD_LIST.contains(contractField.getFieldKey())) {
					String phone = cipherService.decrypt(contractField.getFieldValue());
					if (phone.length() >= 7) {
						contractField.setFieldValue(phone.substring(0, 3) + "****" + phone.substring(phone.length() - 4));
					} else {
						contractField.setFieldValue("****");
					}
				}
				// 身份证号只展示前三位和后三位
				if (ContractFieldEnum.CERTIFICATE_NO_FIELD_LIST.contains(contractField.getFieldKey())) {
					String certificateNo = cipherService.decrypt(contractField.getFieldValue());
					if (certificateNo.length() >= 6) {
						contractField.setFieldValue(certificateNo.substring(0, 3) + "****" + certificateNo.substring(certificateNo.length() - 3));
					} else {
						contractField.setFieldValue("****");
					}
				}
				ContractFieldQueryResp contractFieldQueryResp = ContractFieldQueryResp.builder()
					.fieldKey(contractField.getFieldKey())
					.fieldValue(contractField.getFieldValue())
					.fieldName(ContractFieldEnum.getFieldNameByKey(contractField.getFieldKey()))
					.fieldType(ContractFieldEnum.getFieldTypeByKey(contractField.getFieldKey()))
					.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.getFieldTypeByKey(contractField.getFieldKey())))
					.build();
				res.add(contractFieldQueryResp);
			}
		}
		//构建非字段表的信息
		Contract contract = contractService.getByContractCode(contractCode);
		//构建合同总金额字段
		ContractFieldQueryResp contractPriceTotal = ContractFieldQueryResp.builder()
			.fieldKey(ContractFieldEnum.CONTRACT_PRICE_TOTAL.getFieldKey())
			.fieldValue(contract.getAmount().toString())
			.fieldName(ContractFieldEnum.CONTRACT_PRICE_TOTAL.getFieldName())
			.fieldType(ContractFieldEnum.CONTRACT_PRICE_TOTAL.getFieldType())
			.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.CONTRACT_PRICE_TOTAL.getFieldType()))
			.build();
		res.add(contractPriceTotal);
		// 获取收款计划
		try {
			String collectionPlan = obtainCollectionPlan(contractCode);
			ContractFieldQueryResp collectionPlanInfo = ContractFieldQueryResp.builder()
				.fieldKey(ContractFieldEnum.COLLECTION_PLAN_CONFIG_INFO.getFieldKey())
				.fieldValue(collectionPlan)
				.fieldName(ContractFieldEnum.COLLECTION_PLAN_CONFIG_INFO.getFieldName())
				.fieldType(ContractFieldEnum.COLLECTION_PLAN_CONFIG_INFO.getFieldType())
				.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.COLLECTION_PLAN_CONFIG_INFO.getFieldType()))
				.build();
			res.add(collectionPlanInfo);
		} catch (Exception e) {
			LOGGER.warn("【合同问答】查询收款计划异常，contractCode:{}", contractCode, e);
		}
		try {
			//个性化金额
			List<ContractRelation> relationList = contractRelationService.getRelationList(contractCode);
			if (CollectionUtil.isNotEmpty(relationList)) {
				List<String> contractCodes = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
				List<Contract> contractList = contractService.getListByContractCodesAndStatus(contractCodes, ContractStatusEnum.inPositiveStatus);
				if (CollectionUtil.isNotEmpty(contractList)) {
					BigDecimal personalAmount;
					personalAmount = contractList.stream().filter(item -> ContractTypeEnum.PERSONAL.getCode().equals(item.getType()))
						.map(Contract::getAmount)
						.filter(Objects::nonNull)
						.reduce(BigDecimal::add)
						.orElse(BigDecimal.ZERO);
					ContractFieldQueryResp personalAmountField = ContractFieldQueryResp.builder()
						.fieldKey(ContractFieldEnum.PERSONAL_TOTAL_PRICE.getFieldKey())
						.fieldValue(personalAmount.toString())
						.fieldName(ContractFieldEnum.PERSONAL_TOTAL_PRICE.getFieldName())
						.fieldType(ContractFieldEnum.PERSONAL_TOTAL_PRICE.getFieldType())
						.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.PERSONAL_TOTAL_PRICE.getFieldType()))
						.build();
					res.add(personalAmountField);
				}
			}
		} catch (Exception e) {
			LOGGER.warn("【合同问答】查询个性化金额异常，contractCode:{}", contractCode, e);
		}
		//乙方分公司姓名
		String companyCode = contract.getCompanyCode();
		try {
			MdmDTO mdmDTO = mdmRpc.obtainMdmByMdmCode(companyCode);
			ContractFieldQueryResp partyBCompanyName = ContractFieldQueryResp.builder()
				.fieldKey(ContractFieldEnum.UNITED_COMPANY_NAME.getFieldKey())
				.fieldValue(mdmDTO.getCompanyName())
				.fieldName(ContractFieldEnum.UNITED_COMPANY_NAME.getFieldName())
				.fieldType(ContractFieldEnum.UNITED_COMPANY_NAME.getFieldType())
				.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.UNITED_COMPANY_NAME.getFieldType()))
				.build();
			res.add(partyBCompanyName);
		} catch (Exception e) {
			LOGGER.warn("【合同问答】查询分公司信息异常，companyCode:{}", companyCode, e);
		}
		try {
			// 签约人信息
			ContractUser signUser = contractUserService.getSignerByContractCode(contractCode);
			if (signUser != null) {
				ContractFieldQueryResp signerName = ContractFieldQueryResp.builder()
					.fieldKey(ContractFieldEnum.CONTRACT_SIGN_NAME.getFieldKey())
					.fieldValue(signUser.getName())
					.fieldName(ContractFieldEnum.CONTRACT_SIGN_NAME.getFieldName())
					.fieldType(ContractFieldEnum.CONTRACT_SIGN_NAME.getFieldType())
					.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.CONTRACT_SIGN_NAME.getFieldType()))
					.build();
				res.add(signerName);
				String signPhone = cipherService.decrypt(signUser.getPhone());
				ContractFieldQueryResp signerPhone = ContractFieldQueryResp.builder()
					.fieldKey(ContractFieldEnum.CONTRACT_SIGN_PHONE.getFieldKey())
					.fieldValue(ObjectUtil.isNotEmpty(signPhone) && signPhone.length() >= 7 ? signPhone.substring(0, 3) + "****" + signPhone.substring(signPhone.length() - 4) : "****")
					.fieldName(ContractFieldEnum.CONTRACT_SIGN_PHONE.getFieldName())
					.fieldType(ContractFieldEnum.CONTRACT_SIGN_PHONE.getFieldType())
					.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.CONTRACT_SIGN_PHONE.getFieldType()))
					.build();
				res.add(signerPhone);
			}
		} catch (Exception e) {
			LOGGER.warn("【合同问答】查询签约人信息异常，contractCode:{}", contractCode, e);
		}
		// 中控接口超时等异常不影响整体返回
		try {
			ContractSourceDataBO contractSourceDataBO = homeOrderDataConversionService.contractSourceDate(contract.getProjectOrderId(), contract.getChangeOrderId());
			PlanAllDTO planAllDTO = contractSourceDataBO.getPlanAllDTO();
			String comboName = planAllDTO.getPlanInfo().getComboName();
			ContractFieldQueryResp combo = ContractFieldQueryResp.builder()
				.fieldKey(ContractFieldEnum.COMBO_NAME.getFieldKey())
				.fieldValue(comboName)
				.fieldName(ContractFieldEnum.COMBO_NAME.getFieldName())
				.fieldType(ContractFieldEnum.COMBO_NAME.getFieldType())
				.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.COMBO_NAME.getFieldType()))
				.build();
			res.add(combo);
			BigDecimal quotePrice = planAllDTO.getPlanInfo().getQuotePrice();
			ContractFieldQueryResp quote = ContractFieldQueryResp.builder()
				.fieldKey(ContractFieldEnum.QUOTE_PRICE.getFieldKey())
				.fieldValue(quotePrice == null ? null : quotePrice.toString())
				.fieldName(ContractFieldEnum.QUOTE_PRICE.getFieldName())
				.fieldType(ContractFieldEnum.QUOTE_PRICE.getFieldType())
				.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.QUOTE_PRICE.getFieldType()))
				.build();
			res.add(quote);
			BigDecimal pricingArea = planAllDTO.getPlanInfo().getPricingArea();
			ContractFieldQueryResp area = ContractFieldQueryResp.builder()
				.fieldKey(ContractFieldEnum.PRICING_AREA.getFieldKey())
				.fieldValue(pricingArea == null ? null : pricingArea.toString())
				.fieldName(ContractFieldEnum.PRICING_AREA.getFieldName())
				.fieldType(ContractFieldEnum.PRICING_AREA.getFieldType())
				.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.PRICING_AREA.getFieldType()))
				.build();
			res.add(area);
			//改后户型
			String houseLayoutAfter = planAllDTO.getReconstructionHouseLayout().getHouseLayoutDesc();
			ContractFieldQueryResp houseLayout = ContractFieldQueryResp.builder()
				.fieldKey(ContractFieldEnum.HOUSE_LAYOUT.getFieldKey())
				.fieldValue(houseLayoutAfter)
				.fieldName(ContractFieldEnum.HOUSE_LAYOUT.getFieldName())
				.fieldType(ContractFieldEnum.HOUSE_LAYOUT.getFieldType())
				.fieldTypeDesc(ContractFieldClassEnum.getDescByType(ContractFieldEnum.HOUSE_LAYOUT.getFieldType()))
				.build();
			res.add(houseLayout);
		} catch (Exception e) {
			LOGGER.warn("【合同问答】查询报价信息异常，contractCode:{}", contractCode, e);
		}
		return res;
	}

