	/**
	 * 校验用户角色是否存在权限
	 */
	public void checkUserRolePermission(String ucid) {
		List<RoleInfo> rolePermissionInfos = permissionRpc.queryRolesInfoByUcid(ucid);
		if (CollectionUtils.isEmpty(rolePermissionInfos)) {
			LOGGER.error("用户角色信息不存在，ucid:{}", ucid);
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "用户角色信息不存在", Level.WARN);
		}
		for (RoleInfo rolePermissionInfo : rolePermissionInfos) {
			Map<String, Object> perms = permissionRpc.getPerms(rolePermissionInfo.getId());
			if (perms == null || perms.isEmpty()) {
				continue;
			}
			if (perms.containsKey("crm-home2.0-view-contract-mob")) {
				return;
			}
		}
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "用户无权限操作", Level.WARN);
	}

