public BaseContractDto convert(Map<String, Object> contractFieldMap) {
	String contractTypeString = contractFieldMap.getOrDefault("type", "0").toString();
	Byte contractType = Byte.valueOf(contractTypeString);
	if (0 == contractType) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "contractType为空。");
	}
	String contractFieldMapString = JsonUtil.toJsonString(contractFieldMap);
	if (ContractTypeEnum.SUBSCRIBE.getCode().equals(contractType)) {
		return JsonUtil.toObject(contractFieldMapString, SubscribeContractDto.class);
	}
	if (ContractTypeEnum.DESIGN.getCode().equals(contractType)) {
		return JsonUtil.toObject(contractFieldMapString, DesignerContractDto.class);
	}
	if (ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
		return JsonUtil.toObject(contractFieldMapString, TerminalContractDto.class);
	}
	throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "不支持的contractType转换。");
}

