	String zqContractProjectDtoString = JsonUtil.toJsonString(map);
	ZqContractProjectDTO zqContractProjectDto = JsonUtil.toObject(zqContractProjectDtoString, ZqContractProjectDTO.class);
	Integer houseBuildType = zqContractProjectDto.getHouseBuildType();
	Integer houseType = zqContractProjectDto.getHouseType();
	Integer decorateForm = zqContractProjectDto.getDecorateForm();
	Integer structure = zqContractProjectDto.getStructure();
	if (Objects.nonNull(houseBuildType) && Objects.nonNull(HouseBuildTypeEnum.getEnumByCode(houseBuildType))) {
		zqContractProjectDto.setHouseBuildTypeDesc(HouseBuildTypeEnum.getEnumByCode(houseBuildType).getDesc());
	}
	if (Objects.nonNull(houseType) && Objects.nonNull(HouseTypeEnum.getEnumByCode(houseType))) {
		zqContractProjectDto.setHouseTypeDesc(HouseTypeEnum.getEnumByCode(houseType).getDesc());
