public List<ContractNodeSimpleDto> getBaseBatchContractNodeInfo(Byte businessType, String projectOrderIds, Byte contractType) {
	List<ContractNodeSimpleDto> contractNodeSimpleDto = new ArrayList<>();
	List<String> projectOrderArrIds = Arrays.asList(projectOrderIds.split(","));
	if (projectOrderArrIds.isEmpty() || (projectOrderArrIds.size() > 100)) {
		LOGGER.info("批量获取节点信息，项目单号不能为0或超100 projectOrderIds:{} ", projectOrderIds);
		return contractNodeSimpleDto;
	}
	List<Contract> baseBatchContractInfo = contractService.getBatchBaseContractInfo(businessType, projectOrderArrIds, contractType, true);
	if (baseBatchContractInfo.isEmpty()) {
		return contractNodeSimpleDto;
	}

	//获取合同编号
	List<String> baseContractCodes = baseBatchContractInfo.stream().map(Contract::getContractCode).collect(Collectors.toList());
	List<ContractNode> contractNodeInfoList = contractNodeService.getListByContractCodes(baseContractCodes);
	Map<String, String> contractCodeMap = Maps.newHashMap();
	baseBatchContractInfo.forEach(baseContractInfo -> contractCodeMap.put(baseContractInfo.getContractCode(), baseContractInfo.getProjectOrderId()));

	contractNodeInfoList.forEach(contractNodeInfo -> {
		if (contractCodeMap.containsKey(contractNodeInfo.getContractCode())) {
			ContractNodeSimpleDto contractNodeSimpleInfo = ContractNodeSimpleDto.builder()
				.contractCode(contractNodeInfo.getContractCode())
				.nodeType(contractNodeInfo.getNodeType())
				.fireTime(contractNodeInfo.getFireTime())
				.projectOrderId(contractCodeMap.get(contractNodeInfo.getContractCode()))
				.build();
			contractNodeSimpleDto.add(contractNodeSimpleInfo);
		}
	});

	return contractNodeSimpleDto;
}

