			fieldMap.put(contractField.getContractCode(), new LinkedList<>());
		}
		fieldMap.get(contractField.getContractCode()).add(contractField);
	}

	for (ContractAllDTO contractAllDTO : result) {
		List<ContractFieldDTO> contractFieldDTOList = new LinkedList<>();
		if (fieldMap.containsKey(contractAllDTO.getContractCode())) {
			List<ContractField> contractFields = fieldMap.get(contractAllDTO.getContractCode());
