@Deprecated
public void cancelBillCodeRelation(String projectOrderId, Long operatorUcid, String billCode) {
	List<Contract> contractList = quotationRelationCommonService.getContractByBillCode(billCode);
	if (CollectionUtil.isEmpty(contractList)) {
		return;
	}
	for (Contract contract : contractList) {
		if (ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus()) || ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus()) || (ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus()) && CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus()))) {
			LOGGER.info("合同{}，状态不允许取消关联", contract.getContractCode());
			return;
		}
	}

	for (Contract contract : contractList) {
		List<ContractQuotationRelation> contractQuotationRelationList = contractQuotationRelationService.getByContractCode(contract.getContractCode(), RelationStatusEnum.RELATED.getCode());
		if (CollectionUtil.isEmpty(contractQuotationRelationList)) {
			LOGGER.info("合同{}，无关联报价单", contract.getContractCode());
			return;
		}
		if (contractQuotationRelationList.size() == 1 && ObjectUtil.equal(contractQuotationRelationList.get(0).getBillCode(), billCode)) {
			quotationRelationCommonService.cancelContractRelations(contract.getContractCode());
			cancelCurrentContract(contract, operatorUcid, true);
		} else {
			//解除合同和报价单的关联关系，回退合同状态到草稿
			contractQuotationRelationService.cancelRelationsByBillCodes(contract.getContractCode(), Collections.singletonList(billCode));
			if (!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())
				&& !(ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus()) && CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus()))
				&& !ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus())) {
				homeAndPcCommonService.undoContract(contract, operatorUcid);
			}
		}
	}
}

