public void sendContractSmsRemind(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (contract == null) {
		return;
	}
	if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
		//线下合同短信提醒
		sendOfflineContractSmsRemind(contract);
	} else {
		//线上合同短信提醒
		sendOnlineContractSmsRemind(contract);
	}

}

public void sendOnlineContractSmsRemind(Contract contract) {
	//判断是否整装交易治理开城
	if (!BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(contract.getBusinessType())) {
		return;
	}

	MiniPayChannelAppNameEnum miniPayChannelAppNameEnum = commonBusinessService.getMiniProgramType(contract.getProjectOrderId());
	//获取项目信息
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(contract.getProjectOrderId());
	//获取手机号信息
	List<ContractUser> contractUsers = contractUserService.getListByContractCode(contract.getContractCode());
	ContractUser contractUser = contractUsers.stream().filter(m -> IsSignEnum.YES.getCode().equals(m.getIsSign())).findFirst().orElse(null);
	if (ObjectUtil.isNull(contractUser)) {
		throw new NrsBusinessException("【短信提醒】支付成功发送短信提醒失败，原因：获取签约人信息失败");
	}
	String phone = cipherService.decrypt(contractUser.getPhone());
	if (ObjectUtil.isEmpty(phone)) {
		throw new NrsBusinessException("【短信提醒】支付成功发送短信提醒失败，原因：获取手机号失败");
	}
	//获取短信模板
	String onlineContractSMSTemplate = apolloConfigService.getOnlineContractSMSTemplate(contract);
	if (ObjectUtil.isEmpty(onlineContractSMSTemplate)) {
		LOGGER.info("【短信提醒】未匹配到短信模版，不发送短信，contractCode:{}", contract.getContractCode());
		return;
	}
	//构建短信动态字段内容
	Map<String, String> content = getOnlineContractSMSContent(contract, projectInfoDTO, miniPayChannelAppNameEnum);
	//构建短信内容
	ReminderContextDTO reminderContextDTO = ReminderContextDTO.builder()
		.phone(phone)
		.content(content)
		.template(onlineContractSMSTemplate)
		.source(Constant.DOMAIN_EVENT_SERVER_NAME)
		.build();
	//获取发送短信时项目快照信息
	BusinessSnapshotDTO businessSnapshotDTO = getBusinessSnapshotDTO(contract, projectInfoDTO, contractUsers);
	//发送短信
	PaySignReminderCreateReqDTO paySignReminderCreateReqDTO = PaySignReminderCreateReqDTO.builder()
		.projectOrderId(contract.getProjectOrderId())
		.reminderType(ReminderTypeEnum.SMS.getValue())
		.scenarioType(ReminderScenarioTypeEnum.ONLINE_CONTRACT_SIGN.getValue())
		.reminderContext(JSON.toJSONString(reminderContextDTO))
		.businessSnapshot(JSON.toJSONString(businessSnapshotDTO))
		.reminderTime(new Date())
		.build();
	LOGGER.info("【短信提醒】线上合同发送短信提醒，请求参数：{}", JSON.toJSONString(paySignReminderCreateReqDTO));
	payServiceRpc.sendSmsMessage(paySignReminderCreateReqDTO);
	LOGGER.info("【短信提醒】线上合同发送短信提醒成功");
}

public void sendOfflineContractSmsRemind(Contract contract) {
	//团装不发送短信
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType())) {
		return;
	}
	MiniPayChannelAppNameEnum miniPayChannelAppNameEnum = commonBusinessService.getMiniProgramType(contract.getProjectOrderId());
	//1.0订单不发送短信
	if (ObjectUtil.isNull(miniPayChannelAppNameEnum)) {
		return;
	}
	//获取项目信息
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(contract.getProjectOrderId());

	//获取手机号信息
	List<ContractUser> contractUsers = contractUserService.getListByContractCode(contract.getContractCode());
	ContractUser contractUser = contractUsers.stream().filter(m -> IsSignEnum.YES.getCode().equals(m.getIsSign())).findFirst().orElse(null);
	if (ObjectUtil.isNull(contractUser)) {
		return;
	}
	String phone = cipherService.decrypt(contractUser.getPhone());
	if (ObjectUtil.isEmpty(phone)) {
		return;
	}
	//获取短信模板
	String offlineContractSMSTemplate = apolloConfigService.getOfflineContractSMSTemplate(contract, miniPayChannelAppNameEnum);
	//获取短链
	String urlLink = payServiceRpc.getUrlLink(ReminderScenarioTypeEnum.OFFLINE_CONTRACT.getValue(), miniPayChannelAppNameEnum.getMiniProgramType(), contract.getProjectOrderId());
	//获取短信动态字段
	Map<String, String> content = getOfflineContractSMSContent(contract, projectInfoDTO, urlLink);
	//构建短信内容
	ReminderContextDTO reminderContextDTO = ReminderContextDTO.builder()
		.phone(phone)
		.content(content)
		.template(offlineContractSMSTemplate)
		.source(Constant.DOMAIN_EVENT_SERVER_NAME)
		.build();
	//获取发送短信时项目快照信息
	BusinessSnapshotDTO businessSnapshotDTO = getBusinessSnapshotDTO(contract, projectInfoDTO, contractUsers);
	//发送短信
	PaySignReminderCreateReqDTO paySignReminderCreateReqDTO = PaySignReminderCreateReqDTO.builder()
		.projectOrderId(contract.getProjectOrderId())
		.reminderType(ReminderTypeEnum.SMS.getValue())
		.scenarioType(ReminderScenarioTypeEnum.OFFLINE_CONTRACT.getValue())
		.reminderContext(JSON.toJSONString(reminderContextDTO))
		.businessSnapshot(JSON.toJSONString(businessSnapshotDTO))
		.reminderTime(new Date())
		.build();
	LOGGER.info("【短信提醒】线下合同发送短信提醒，请求参数：{}", JSON.toJSONString(paySignReminderCreateReqDTO));
	payServiceRpc.sendSmsMessage(paySignReminderCreateReqDTO);
	LOGGER.info("【短信提醒】线下合同发送短信提醒成功");
}

private Map<String, String> getOfflineContractSMSContent(Contract contract, ProjectInfoDTO projectInfoDTO, String urlLink) {
