public void sendUploadAttachSmsRemind(String projectOrderId) {
	try {
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
		if (projectInfoDTO == null || ObjectUtil.isEmpty(projectInfoDTO.getCustomer())) {
			return;
		}

		Byte businessType = getBusinessType(projectInfoDTO);
		if (!BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType) || ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(projectInfoDTO.getDecorateBusinessType())) {
			return;
		}

		//幂等校验，已成功发送的短信不再重复发送
		List<PaySignReminderDTO> smsRecord = payServiceRpc.getSmsRecord(projectOrderId, ReminderScenarioTypeEnum.CONTRACT_ATTACH_UPLOAD.getValue());
		if (CollectionUtil.isNotEmpty(smsRecord) && smsRecord.stream().anyMatch(sms -> !SmsStatusEnum.DEFAULT.getCode().equals(sms.getSendStatus()) && !SmsStatusEnum.FAIL.getCode().equals(sms.getSendStatus()))) {
			LOGGER.info("项目单号：{}，备件上传短信提醒已发送，直接返回", projectOrderId);
			return;
		}

		// 获取客源手机号
		String phone = projectInfoDTO.getCustomer().getPhone();
		if (StringUtils.isBlank(phone)) {
			LOGGER.warn("项目单号：{}，未找到客户手机号，无法发送备件上传短信提醒", projectOrderId);
			return;
		}
		//获取短信模版
		String template = apolloConfigService.obtainAttachUploadSMSTemplate();
		//获取品牌
		MiniPayChannelAppNameEnum miniPayChannelAppNameEnum = commonBusinessService.getMiniProgramType(projectOrderId);
		//构建短信动态信息
		Map<String, String> content = new HashMap<>();
		content.put("appnamei", miniPayChannelAppNameEnum.getDesc());
		content.put("appnameii", miniPayChannelAppNameEnum.getDesc());
		content.put("appnameiii", miniPayChannelAppNameEnum.getDesc());
		//构建短信内容
		ReminderContextDTO reminderContextDTO = ReminderContextDTO.builder()
			.phone(phone)
			.content(content)
			.template(template)
			.source(Constant.DOMAIN_EVENT_SERVER_NAME)
			.build();
		//获取发送短信时项目快照信息
		BusinessSnapshotDTO businessSnapshotDTO = BusinessSnapshotDTO.builder()
			.projectOrderId(projectOrderId)
			.projectAddress(homeAndPcCommonService.getResblockAddress(projectInfoDTO))
			.scenarioType(ReminderScenarioTypeEnum.CONTRACT_ATTACH_UPLOAD.getValue())
			.reminderTime(new Date())
			.build();
		//构建发送短信请求
		PaySignReminderCreateReqDTO paySignReminderCreateReqDTO = PaySignReminderCreateReqDTO.builder()
			.projectOrderId(projectOrderId)
			.reminderType(ReminderTypeEnum.SMS.getValue())
			.scenarioType(ReminderScenarioTypeEnum.CONTRACT_ATTACH_UPLOAD.getValue())
			.reminderContext(JSON.toJSONString(reminderContextDTO))
			.businessSnapshot(JSON.toJSONString(businessSnapshotDTO))
			.reminderTime(new Date())
			.build();
		LOGGER.info("【短信提醒】发送备件上传短信提醒，请求参数：{}", JSON.toJSONString(paySignReminderCreateReqDTO));
		payServiceRpc.sendSmsMessage(paySignReminderCreateReqDTO);
		LOGGER.info("【短信提醒】发送备件上传短信提醒成功，项目单号：{}", projectOrderId);
	} catch (Exception e) {
		LOGGER.error("【短信提醒】发送备件上传短信提醒失败，项目单号：{}，异常信息：{}", projectOrderId, e.getMessage(), e);
	}
}

private void syncNerveCenter(Contract contract) {
	if (contract == null) {
		return;
	}

	// 仅处理定金合同及首期款合同
	if (!ContractTypeEnum.NEED_SYNC_NERVECENTER_LIST.contains(contract.getType())) {
		return;
	}

	// 将定金应收金额设置为认购合同的合同金额
	if (ContractTypeEnum.SUBSCRIBE.getCode().equals(contract.getType())) {
		ProjectBillFeeItemEntity projectBillFeeItemEntity = nerveProjectBillRpc.queryFeeItem(contract.getProjectOrderId(), FundTypeEnum.DEPOSIT.getValue());
		Long expectAmount = Optional.ofNullable(projectBillFeeItemEntity).map(ProjectBillFeeItemEntity::getExpectAmount).orElse(0L);
		Long contractAmount = AmountUtil.convertToLong(contract.getAmount());
		Long changeAmount = contractAmount - expectAmount;
		nerveProjectBillRpc.adjustExpectAmount(contract.getContractCode(), contract.getProjectOrderId(), FundTypeEnum.DEPOSIT.getValue(), changeAmount, new Date());
	}

	// 将工程款应收金额设置为首期款合同的预估合同金额
	if (ContractTypeEnum.ADVANCE.getCode().equals(contract.getType())) {
		ProjectBillFeeItemEntity projectBillFeeItemEntity = nerveProjectBillRpc.queryFeeItem(contract.getProjectOrderId(), FundTypeEnum.PROJECT_CHARGE.getValue());
		Long expectAmount = Optional.ofNullable(projectBillFeeItemEntity).map(ProjectBillFeeItemEntity::getExpectAmount).orElse(0L);
		List<ContractField> contractFields = contractFieldService.getListByContractCode(contract.getContractCode());
		Long contractAmount = contractFields.stream()
			.filter(contractField -> Objects.equals(contractField.getFieldKey(), ContractProjectInfoReq.Fields.expectContractAmount))
			.map(contractField -> AmountUtil.convertToLong(new BigDecimal(contractField.getFieldValue())))
			.findFirst().orElse(null);
		if (contractAmount == null) {
			LOGGER.error("定金、首期款合同签约完成同步资金模型异常，合同code:{}，未找到预估合同金额", contract.getContractCode());
			return;
		}
		Long changeAmount = contractAmount - expectAmount;
		nerveProjectBillRpc.adjustExpectAmount(contract.getContractCode(),
			contract.getProjectOrderId(),
			FundTypeEnum.PROJECT_CHARGE.getValue(),
			changeAmount,
			new Date(),
			FeeItemSourceType.预估.getCode(),
			contract.getProjectOrderId(),
			Long.valueOf(contract.getCreateUserId()),
			contract.getCreateUserName());
	}
	//将设计费金额设置为设计合同约定金额/设计变更合同金额
	if (ContractTypeEnum.DESIGN.getCode().equals(contract.getType()) || ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contract.getType())) {
		//1.0订单不做处理
		List<ProjectVersionDTO> projectVersionDTOS = projectInfoReadService.batchProjectVersion(Collections.singletonList(contract.getProjectOrderId()));
		if (CollectionUtils.isEmpty(projectVersionDTOS) || ProjectVersionEnum.V1.getVersion().equals(projectVersionDTOS.get(0).getProjectVersion())) {
			return;
		}
		ProjectBillFeeItemEntity projectBillFeeItemEntity = nerveProjectBillRpc.queryFeeItem(contract.getProjectOrderId(), FundTypeEnum.DESIGN_CHARGE.getValue());
		//当前设计费应收
		Long expectAmount = Optional.ofNullable(projectBillFeeItemEntity).map(ProjectBillFeeItemEntity::getExpectAmount).orElse(0L);
		//设计合同/设计变更合同金额
		Long contractAmount = AmountUtil.convertToLong(contract.getAmount());
		Long changeAmount = contractAmount - expectAmount;
		LOGGER.info("【设计/设计变更合同】同步设计合同金额，原本设计费应收金额：{}，更新后设计合同金额：{}，变更金额：{}", expectAmount, contractAmount, changeAmount);
		nerveProjectBillRpc.adjustExpectAmount(contract.getContractCode(),
			contract.getProjectOrderId(),
			FundTypeEnum.DESIGN_CHARGE.getValue(),
			changeAmount,
			new Date(),
			null,
			contract.getProjectOrderId(),
			Long.valueOf(contract.getCreateUserId()),
			contract.getCreateUserName());

	}
	//正签金额判断是否约定设计费
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType()) || ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType())) {
		List<ContractField> fieldList = contractFieldService.getListByContractCode(contract.getContractCode());
		boolean mergeLaunchDesignContract = contractUnifyService.isMergeLaunchDesignContract(contract.getProjectOrderId());
		ContractField contractField = fieldList.stream().filter(m -> "needDesignerAmount".equals(m.getFieldKey())).findFirst().orElse(null);
		if (!mergeLaunchDesignContract && contractField != null && "1".equals(contractField.getFieldValue())) {
			ContractField afterDiscountDesignerAmount = fieldList.stream().filter(m -> "afterDiscountDesignerAmount".equals(m.getFieldKey())).findFirst().orElse(null);
			//设计费应收
			ProjectBillFeeItemEntity projectBillFeeItemEntity = nerveProjectBillRpc.queryFeeItem(contract.getProjectOrderId(), FundTypeEnum.DESIGN_CHARGE.getValue());
			Long expectAmount = Optional.ofNullable(projectBillFeeItemEntity).map(ProjectBillFeeItemEntity::getExpectAmount).orElse(0L);
			//正签约定的设计费金额
			Long contractAmount = ObjectUtil.isEmpty(afterDiscountDesignerAmount) ? expectAmount : AmountUtil.convertToLong(new BigDecimal(afterDiscountDesignerAmount.getFieldValue()));
			Long changeAmount = contractAmount - expectAmount;
			LOGGER.info("【正签/正签变更合同】同步设计费合同金额，原本设计费应收金额：{}，更新后设计费合同金额：{}，变更金额：{}", expectAmount, contractAmount, changeAmount);
			nerveProjectBillRpc.adjustExpectAmount(contract.getContractCode(),
				contract.getProjectOrderId(),
				FundTypeEnum.DESIGN_CHARGE.getValue(),
				changeAmount,
				new Date(),
				null,
				contract.getProjectOrderId(),
				Long.valueOf(contract.getCreateUserId()),
				contract.getCreateUserName());
		}
	}
}

public void cancelHistoryContracts(Contract contract) {
	if (contract == null) {
		return;
	}

	// 协议确认方式签署状态不处理
	if (UserSignTypeEnum.CONFIRM.getCode().equals(contract.getUserSignType()) && ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
		return;
	}

	// 作废历史合同
	if (ContractTypeEnum.isCancelHistoryContract(contract.getType())) {
		cancelOtherContracts(contract);
	}
}

public void cancelOtherContracts(Contract currentContract) {
	List<Contract> contractList = contractService.getContractList(currentContract.getProjectOrderId(), currentContract.getType());
	List<Contract> needCancelContract = contractList.stream()
		.filter(contract -> !contract.getContractCode().equals(currentContract.getContractCode()))
		.filter(contract -> !ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus()))
		.collect(Collectors.toList());
	for (Contract contract : needCancelContract) {
		//先取消关联关系在删除合同
		quotationRelationCommonService.cancelContractRelations(contract.getContractCode());
		contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.CANCEL.getCode());
		contractService.updateContractStatus(contract.getContractCode(), ContractStatusEnum.CANCEL.getCode());
		eventService.publish(getContractEvent(contract), com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_CANCEL);
	}
}

@Transactional
public void cancelCurrentContract(Contract contract, Long operatorUcid, boolean cancelRelateContract) {
	contractLogService.createLog(contract.getContractCode(), LogTypeEnum.CANCEL.getCode(), "作废合同，合同取消");
	contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.CANCEL.getCode());
	contractService.updateContractStatus(contract.getContractCode(), ContractStatusEnum.CANCEL.getCode());
	ContractEvent contractEvent = getContractEvent(contract);
	eventService.publish(contractEvent, com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_CANCEL);
	// 线下合同需要中止在途的BPM审批
	if (ContractStatusEnum.AUDITING.getCode().equals(contract.getStatus())) {
		String userSystemCode = contractBusinessService.getUserSystemCode(String.valueOf(operatorUcid));
		try {
			LOGGER.info("作废合同 取消bpm审批 bpmNo:{} contractCode:{}", contract.getBmpNo(), contract.getContractCode());
			bpmService.processCancel(contract.getBmpNo(), userSystemCode);
		} catch (Exception e) {
			LOGGER.error("作废合同，撤销bpm审核失败:{}", contract.getBmpNo(), e);
		}
	}

	// 需要同时取消关联合同（授权协议书）
	if (cancelRelateContract && StringUtils.isNotBlank(contract.getRelateContractCode())) {
		Contract relateContract = contractService.getByContractCode(contract.getRelateContractCode());
		if (relateContract != null) {
			cancelCurrentContract(relateContract, operatorUcid, false);
		}
	}
	// C合同取消,需要取消关联的报价单信息
	quotationRelationCommonService.cancelContractRelations(contract.getContractCode());
	//合同关联关系删除
	ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
	if (contractRelation != null) {
		contractRelationService.deleteRelationByContractCodes(Collections.singletonList(contract.getContractCode()));
	}
}

