public void userSignKeyTimeSyncNerveCenter(Contract contract) {
	if (contract == null) {
		return;
	}

	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
		return;
	}

	List<ContractNode> contractNodeList = contractNodeService.getByContractCodeAndType(contract.getContractCode(), NodeTypeEnum.USER_SIGN.getCode());
	if (contractNodeList.isEmpty()) {
		LOGGER.warn("用户首次签署正签合同时间同步订单模型，获取用户签署节点为空，合同信息：{}", JSON.toJSONString(contract));
		return;
	}

	ContractNode contractNode = contractNodeList.get(0);

	// 线下合同取已签署节点的创建时间（线下合同提交时间）、线上合同取节点发生时间
	long userSignTimeMills = System.currentTimeMillis();
	if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
		userSignTimeMills = contractNode.getFireTime();
	}
	if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
		userSignTimeMills = contractNode.getCtime().getTime();
	}

	ProjectEntities.ProjectAll projectAll = nerveCenterRpc.infoByOutOrderNo(contract.getProjectOrderId());
	if (projectAll == null) {
		LOGGER.error("用户首次签署正签合同时间同步订单模型失败，查询模型返回为空，合同信息：{}", JSON.toJSONString(contract));
		return;
	}

	ProjectInfo projectInfo = projectInfoService.getByProjectOrderId(contract.getProjectOrderId());
	List<ProjectKeyTimeEntity> projectKeyTimeEntities = Optional.ofNullable(projectAll.getProject()).map(ProjectEntity::getProjectKeyTimeEntities).orElse(new ArrayList<>());
	boolean isUserFirstSign = projectKeyTimeEntities.stream().noneMatch(keyTime -> ProjectKeyTimeEnum.用户首次签署正签合同时间.getCode() == keyTime.getKeyTimeCode());

	LocalDateTime userSignTime = LocalDateTime.ofInstant(Instant.ofEpochMilli(userSignTimeMills), ZoneId.systemDefault());
	if (isUserFirstSign) {
		ProjectParams.ProjectKeyTimeUpsert keyTimeUpsert = ProjectParams.ProjectKeyTimeUpsert.builder()
			.outOrderType(Project.HOME2)
			.projectClass(NerveCenterTransfer.decorateTypeToProjectClass(contract.getBusinessType()))
			.outOrderNo(projectInfo.getProjectOrderId())
			.operatorUcid(0L)
			.operatorName(KeUtils.getAppName())
			.serviceId(KeUtils.getAppName())
			.keyTime(userSignTime)
			.keyTimeCode(ProjectKeyTimeEnum.用户首次签署正签合同时间.getCode())
			.build();
		bigTableKeyTimeSignedDataPusher.doPush(contract.getProjectOrderId(), keyTimeUpsert);
	}

	ProjectParams.ProjectKeyTimeUpsert keyTimeUpsert = ProjectParams.ProjectKeyTimeUpsert.builder()
		.outOrderType(Project.HOME2)
		.projectClass(NerveCenterTransfer.decorateTypeToProjectClass(contract.getBusinessType()))
		.outOrderNo(projectInfo.getProjectOrderId())
		.operatorUcid(0L)
		.operatorName(KeUtils.getAppName())
		.serviceId(KeUtils.getAppName())
		.keyTime(userSignTime)
		.keyTimeCode(ProjectKeyTimeEnum.用户最新签署正签合同时间.getCode())
		.build();
	bigTableKeyTimeSignedDataPusher.doPush(contract.getProjectOrderId(), keyTimeUpsert);
}

