public Integer computeFormalContractMode() {
	ContractReqDTO contractReq = ContractContextHandler.getContractReq();
	Byte businessType = ContractContextHandler.getContext().getBusinessType();
	ContractBaseInfoReq contractBaseInfo = contractReq.getContractBaseInfo();
	ContractSignInfoReq signInfo = contractReq.getSignInfo();
	ProjectInfoDTO projectInfo = ContractContextHandler.getProjectInfo();
	ProjectCustomerHouseDTO customerHouse = projectInfo.getCustomerHouse();

	Byte contractType = contractBaseInfo.getContractType();
	String projectOrderId = contractBaseInfo.getProjectOrderId();
	Integer gbCode = customerHouse.getGbCode();

	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return null;
	}

	//获取非草稿有效合同状态的个性合同
	Contract personalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode()).stream().filter(item -> ContractStatusEnum.validStatusWithoutDraft.contains(item.getStatus())).findFirst().orElse(null);

	// 检查各种条件
	boolean processV25 = ContractContextHandler.getContext().isProcessV25();
	boolean personObjectType = ContractObjectTypeEnum.PERSON.getCode().equals(signInfo.getContractObjectType());
	boolean onlineSignChannel = SignChannelTypeEnum.ONLINE.getCode().equals(signInfo.getSignChannelType());
	boolean haveOnePersonalQuote = haveMultiplePersonalQuoteSize(ContractContextHandler.getContractSourceDataBO()) == 1;
	boolean noSignPersonalContract = personalContract == null;
	boolean supportFullService = contractApolloConfig.getFullServiceOpenCityList().contains(gbCode);


	Integer contractMode = null;
	// 判断是否满足所有条件
	LOGGER.info("计算合同模式开始,projectOrderId:{},processV25:{},personObjectType:{},onlineSignChannel:{},haveOnePersonalQuote:{},noSignPersonalContract:{},supportFullService:{},businessType:{}",
		projectOrderId, processV25, personObjectType, onlineSignChannel, haveOnePersonalQuote, noSignPersonalContract, supportFullService, businessType);
	if (processV25 && personObjectType && onlineSignChannel && haveOnePersonalQuote && noSignPersonalContract && supportFullService && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
		contractMode = ContractModeEnum.FULL_SERVICE.getCode();
	}
	LOGGER.info("计算合同模式完成,projectOrderId:{},contractMode:{}", projectOrderId, contractMode);
	return contractMode;
}

