public List<Integer> getFullServiceSignRelateFundTypes(String projectOrderId) {
	List<Contract> contractList = contractService.getContractList(projectOrderId);
	contractList = contractList.stream().filter(contract -> ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus()))
		.collect(Collectors.toList());
	if (CollectionUtils.isEmpty(contractList)) {
		return Collections.emptyList();
	}

	// 获取全案合同
	List<String> contractCodes = contractList.stream().map(Contract::getContractCode).collect(Collectors.toList());
	List<ContractField> contractFieldList = contractFieldService.getListByContractCodes(contractCodes);
	List<String> fullServiceContractCodes = contractFieldList.stream().filter(contractField -> contractField.getFieldKey().equals("contractMode") && contractField.getFieldValue().equals(ContractModeEnum.FULL_SERVICE.getCode().toString()))
		.map(ContractField::getContractCode).collect(Collectors.toList());

	List<Integer> fundTypes = new ArrayList<>();
	for (String fullServiceContractCode : fullServiceContractCodes) {
		Contract fullServiceContract = contractList.stream().filter(contract -> contract.getContractCode().equals(fullServiceContractCode)).findFirst().get();

		// 工程款
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(fullServiceContract.getType())) {
			fundTypes.add(FundTypeEnum.PROJECT_CHARGE.getValue());

			// 设计费
			boolean needDesignerAmount = contractFieldList.stream().anyMatch(contractField -> contractField.getFieldKey().equals("needDesignerAmount") && contractField.getFieldValue().equals(CommonEnum.YES.getCode().toString()));
			if (needDesignerAmount) {
				fundTypes.add(FundTypeEnum.DESIGN_CHARGE.getValue());
			}
		} else {
			FundTypeEnum fundTypeEnum = FundRelateContractMapping.obtainFundTypeEnumByContractType(fullServiceContract.getType());
			if (fundTypeEnum != null) {
				fundTypes.add(fundTypeEnum.getValue());
			}
		}

		// 个性化合同款
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(fullServiceContract.getType())) {
			fundTypes.addAll(FundTypeEnum.CONTRACT_FUND_TYPES);
		}

	}
	return fundTypes;
}

