public List<RelateContract> getRelateContract(String contractCode) {
	List<ContractRelation> relationList = contractRelationService.getRelationList(contractCode);
	ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contractCode);
	if (contractRelation != null) {
		relationList.add(contractRelation);
	}
	if (CollectionUtils.isEmpty(relationList)) {
		return Collections.emptyList();
	}
	List<String> contractCodeList = relationList.stream()
		.flatMap(relation -> Stream.of(relation.getRelateContractCode(), relation.getContractCode()))
		.filter(item -> !item.equals(contractCode))
		.collect(Collectors.toList());
	List<Contract> contractList = contractService.getListByContractCodes(contractCodeList, false);

	return contractList.stream()
		.map(contract -> RelateContract.builder()
			.contractUrl(homeAndPcCommonService.getContractUrl(contract))
			.contractType(contract.getType())
			.attachUrl(homeAndPcCommonService.getAttachUrl(contract))
			.contractCode(contract.getContractCode())
			.status(contract.getStatus())
			.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
			.statusText(ContractStatusEnum.getNameByCode(contract.getStatus()))
			.build())
		.collect(Collectors.toList());
}

