public void dealContract(String projectOrderId) {
	List<Contract> contractList = contractService.getContractList(projectOrderId);
	//首期款/正签合同
	List<Byte> deleteContactType = new ArrayList<>();
	deleteContactType.add(ContractTypeEnum.ADVANCE.getCode());
	deleteContactType.add(ContractTypeEnum.PACKAGE_FORMAL.getCode());

	List<Contract> decorateDeleteContractList = contractList.stream()
		.filter(contract -> deleteContactType.contains(contract.getType()))
		.collect(Collectors.toList());

	if (CollectionUtils.isEmpty(decorateDeleteContractList)) {
		return;
	}

	//check合同状态
	checkContractStatus(decorateDeleteContractList);

	//非2.5版本的订单，需删除合同
	for (Contract contract : decorateDeleteContractList) {
		if (ContractTypeEnum.ADVANCE.getCode().equals(contract.getType()) || ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
			undoAndDeleteContract(contract);
		}
	}
}

private void undoAndDeleteContract(Contract contract) {
	// 合同撤回
	if (ContractStatusEnum.inProgressStatusWithoutDraft.contains(contract.getStatus())) {
		homeAndPcCommonService.undoContract(contract, Long.parseLong(contract.getCreateUserId()));
	}

	List<ContractRelation> relationList = contractRelationService.getRelationList(contract.getContractCode());
	if (!CollectionUtils.isEmpty(relationList)) {
		for (ContractRelation contractRelation : relationList) {
			contractService.deleteSoftByContractCode(contractRelation.getContractCode());
		}
	}

	contractService.deleteSoftByContractCode(contract.getContractCode());
	quotationRelationCommonService.cancelContractRelations(contract.getContractCode());
	LOGGER.info("订单装修类型发生变化，删除{}合同完成，projectOrderId:{}，contractCode:{}", ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()), contract.getProjectOrderId(), contract.getContractCode());
}

private void checkContractStatus(List<Contract> contractList) {
	List<Integer> limitContractStatusList = ContractStatusEnum.SIGNED_STATUS_LIST;
	List<String> contractCodes = contractList.stream().map(Contract::getContractCode).collect(Collectors.toList());
	List<String> contractUserConfirm = contractBusinessService.isContractUserConfirm(contractCodes);

	for (Contract contract : contractList) {
		if (limitContractStatusList.contains(contract.getStatus()) || contractUserConfirm.contains(contract.getContractCode())) {
			throw new NrsBusinessException("订单装修类型发生变化，合同状态不符合处理条件");
		}
	}
}

public BillInfo getBillCodeAndHavePersonalQuote(String projectOrderId) {
	LOGGER.info("日志检测日志检测");
	BillInfo billInfo = new BillInfo();
	if (StringUtils.isBlank(projectOrderId)) {
		billInfo.setHavePersonalQuote(false);
		return billInfo;
	}
	Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId);
	ContractSourceDataBO contractSourceDataBO = homeOrderDataConversionService.contractSourceDateNoThrow(projectOrderId, null);
	PlanAllDTO planAllDTO = contractSourceDataBO.getPlanAllDTO();
	if (planAllDTO == null || planAllDTO.getBudgetBillDTO() == null) {
		billInfo.setHavePersonalQuote(false);
		return billInfo;
	}
	boolean havePersonalQuote = havePersonalQuote(contractSourceDataBO, businessType, processV25);
	String billCode = planAllDTO.getBudgetBillDTO().getBillCode();
	billInfo.setBillCode(billCode);
	billInfo.setHavePersonalQuote(havePersonalQuote);
	DesignFeeInfo designFeeInfo = contractSourceDataBO.getDesignFeeInfo();
	billInfo.setHaveDesignQuote(ObjectUtil.isNotEmpty(designFeeInfo) && DesignFeeSourceEnum.报价.getCode().equals(designFeeInfo.getSource()) && BigDecimal.ZERO.compareTo(designFeeInfo.getAfterDiscountDesignAmount()) != 0);
	billInfo.setCompanyCode(planAllDTO.getPlanInfo().getOrganizationCode());
	if (processV25 && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
		List<ContractSourceDataBO.PersonalContractData> personalContractDataList = contractSourceDataBO.getPersonalContractDataList();
		if (CollectionUtil.isNotEmpty(personalContractDataList)) {
			billInfo.setCompanyCode(personalContractDataList.get(0).getOrganizationCode());
		}
	}
	return billInfo;
}

