public List<PersonalContractDTO> queryPersonalContractByCompositeOrderNos(List<String> compositeOrderNos) {
	if (CollectionUtils.isEmpty(compositeOrderNos)) {
		return Collections.emptyList();
	}

	List<PersonalContractDTO> personalContractDTOList = new ArrayList<>();
	for (String compositeOrderNo : compositeOrderNos) {
		// 1. 查询组合单对应的 S 单号列表
		List<String> subOrderNos = subOrderFeignService.querySubOrderNosByCompositeOrderNo(compositeOrderNo);
		if (CollectionUtils.isEmpty(subOrderNos)) {
			LOGGER.info("查询组合单对应S单为空，compositeOrderNo:{}", compositeOrderNo);
			continue;
		}

		// 2. 遍历 S 单，找到第一个有合同关联的
		ContractQuotationRelation targetRelation = null;
		String targetSubOrderNo = null;
		for (String subOrderNo : subOrderNos) {
			List<ContractQuotationRelation> relations = contractQuotationRelationService.getByBillCodesAndStatus(
				Collections.singletonList(subOrderNo),
				RelationStatusEnum.RELATED.getCode(),
				BindTypeEnum.SUB_ORDER.getCode()
			);
			if (CollectionUtil.isNotEmpty(relations)) {
				targetRelation = relations.get(0);
				targetSubOrderNo = subOrderNo;
				break;
			}
		}

		if (targetRelation == null) {
			LOGGER.info("查询S单合同关联关系为空，compositeOrderNo:{}", compositeOrderNo);
			continue;
		}

		// 3. 查询合同和签约人
		String contractCode = targetRelation.getContractCode();
		Contract contract = contractService.getByContractCode(contractCode);
		if (contract == null || !ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			LOGGER.info("查询合同为空或非销售合同，compositeOrderNo:{},contractCode:{}", compositeOrderNo, contractCode);
			continue;
		}

		List<ContractUser> contractUsers = contractUserService.getListByContractCodes(Collections.singletonList(contractCode));
		ContractUser signUser = contractUsers.stream()
			.filter(u -> IsSignEnum.YES.getCode().equals(u.getIsSign()))
			.findFirst()
			.orElse(null);
		if (signUser == null) {
			LOGGER.info("查询签约人信息为空，compositeOrderNo:{},contractCode:{}", compositeOrderNo, contractCode);
			continue;
		}

		// 4. 查询合同扩展字段
		List<ContractField> contractFields = contractFieldService.getValueByContractCodeAndFieldKey(
			Collections.singletonList(contractCode), "contractObjectType"
		);
		Byte contractObjectType = null;
		if (CollectionUtil.isNotEmpty(contractFields)) {
			contractObjectType = Byte.valueOf(contractFields.get(0).getFieldValue());
		}

		// 5. 组装 DTO
		PersonalContractDTO.ContractBaseInfoDTO contractBaseInfoDTO = new PersonalContractDTO.ContractBaseInfoDTO();
		BeanUtils.copyProperties(contract, contractBaseInfoDTO);
		contractBaseInfoDTO.setContractObjectType(contractObjectType);

		PersonalContractDTO.ContractUserInfoDTO contractUserInfoDTO = new PersonalContractDTO.ContractUserInfoDTO();
		BeanUtils.copyProperties(signUser, contractUserInfoDTO);

		PersonalContractDTO personalContractDTO = PersonalContractDTO.builder()
			.compositeOrderNo(compositeOrderNo)
			.subOrderNo(targetSubOrderNo)
			.contractCode(contractCode)
			.contractBaseInfo(contractBaseInfoDTO)
			.contractUserInfo(contractUserInfoDTO)
			.build();
		personalContractDTOList.add(personalContractDTO);
	}
	return personalContractDTOList;
}

private Map<String, Byte> getCodeToFieldContract(List<String> contractCodes) {
	if (contractCodes == null || contractCodes.isEmpty()) {
		return new HashMap<>(); // 返回一个空的不可变 Map
	}

	List<ContractField> contractFields = contractFieldService.getValueByContractCodeAndFieldKey(contractCodes, "contractObjectType");

	// 使用流 API 将 List 转换为 Map，过滤掉空值，并去重
	return contractFields.stream()
		.filter(Objects::nonNull) // 过滤掉 null 的 ContractField
		.filter(contractField -> contractField.getContractCode() != null) // 过滤掉 contractCode 为 null 的 ContractField
		.collect(Collectors.toMap(
			ContractField::getContractCode, // 以 contractCode 作为键
			contractField -> Byte.valueOf(contractField.getFieldValue()), // 以 ContractField 作为值
			(existing, replacement) -> existing // 如果有重复的键，保留现有的值
		));
}

