public List<ContractUser> queryAuthedAgentInfoList(String projectOrderId) {
	// C端授权代理人手机号
	ContractUser userAuthAgent = attachCommonService.getAttachCustomerAuthAgentInfo(projectOrderId);

	List<Contract> authAgentContractList = contractService.getContractList(projectOrderId, ContractTypeEnum.AUTH_AGENT.getCode(), ContractStatusEnum.SIGNED_STATUS_LIST);
	List<ContractUser> authedAgentUsers = contractUserService.getListByContractCodesAndType(
		authAgentContractList.stream().map(Contract::getContractCode).collect(Collectors.toList()), RoleTypeEnum.AGENT.getCode());

	if (CollectionUtils.isEmpty(authedAgentUsers)) {
		authedAgentUsers = new ArrayList<>();
	}

	if (userAuthAgent != null) {
		authedAgentUsers.add(userAuthAgent);
	}

	if (CollectionUtils.isEmpty(authedAgentUsers)) {
		return authedAgentUsers;
	}


	List<String> decryptList = new ArrayList<>();
	for (ContractUser authedAgentUser : authedAgentUsers) {
		decryptList.add(authedAgentUser.getPhone());
		decryptList.add(authedAgentUser.getCertificateNo());
	}

	// 解密
	Map<String, String> decrypt = cipherService.decrypt(decryptList.stream().filter(StringUtils::isNotBlank).distinct().collect(Collectors.toList()));
	for (ContractUser authedAgentUser : authedAgentUsers) {
		if (authedAgentUser.getPhone() != null) {
			authedAgentUser.setPhone(decrypt.get(authedAgentUser.getPhone()));
		}
		if (authedAgentUser.getCertificateNo() != null) {
			authedAgentUser.setCertificateNo(decrypt.get(authedAgentUser.getCertificateNo()));
		}
	}

	return authedAgentUsers;
}

public void groupChangeToRiskAudit(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (contract == null) {
		LOGGER.warn("合同不存在，contractCode:{}", contractCode);
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "合同不存在", Level.WARN);
	}
	List<Byte> dealContractTypeList = Arrays.asList(ContractTypeEnum.PERSONAL.getCode(), ContractTypeEnum.PACKAGE_FORMAL.getCode());
	//仅处理团装2.5的销售合同、正签合同
	if (!dealContractTypeList.contains(contract.getType())
		|| !BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType())
		|| !commonBusinessService.isProcessV25New(contract.getProjectOrderId())) {
		return;
	}
	List<HomeOrderAttachmentEntity> orderAttachmentEntityList = homeOrderOperationCheckService.queryOrderAttachmentByHomeOrderNo(contract.getProjectOrderId());
	HomeOrderAttachmentEntity homeOrderAttachmentEntity = null;
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
		homeOrderAttachmentEntity = orderAttachmentEntityList.stream()
			.filter(item -> Integer.valueOf(item.getAttachmentType()).equals(PlanAttachment.报价单))
			.filter(item -> NrsOrderKindEnum.PROJECT_CHANGE_NO.getCode().equals(item.getBizType().intValue()))
			.findFirst().orElse(null);
		if (homeOrderAttachmentEntity == null) {
			LOGGER.info("团装正签合同未找到未找到变更报价单，无需处理，projectOrderId:{},contractCode:{}", contract.getProjectOrderId(), contract.getContractCode());
			return;
		}
	}
	if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
		homeOrderAttachmentEntity = orderAttachmentEntityList.stream()
			.filter(item -> Integer.valueOf(item.getAttachmentType()).equals(PlanAttachment.套外个性化报价单))
			.filter(item -> NrsOrderKindEnum.PROJECT_CHANGE_NO.getCode().equals(item.getBizType().intValue()))
			.findFirst().orElse(null);
		if (homeOrderAttachmentEntity == null) {
			LOGGER.info("团装销售合同未找到未找到变更报价单，无需处理，projectOrderId:{},contractCode:{}", contract.getProjectOrderId(), contract.getContractCode());
			return;
		}
		/**
		 * 判断该主体是否已经发起过销售合同，如果发起过则不再调用
		 * 背景：团装场景只有一个主体，如果有变更报价单，则表明变更流程需要签销售合同，此时只有该主体下的第一份销售合同才会调用变更接口流转状态，避免多次调用导致变更流程状态异常。
		 */
		if (hasOtherValidPersonalContractsForCompany(contract)) {
			LOGGER.info("该主体已存在其他销售合同，跳过处理，projectOrderId:{}, companyCode:{}, contractCode:{}",
				contract.getProjectOrderId(), contract.getCompanyCode(), contract.getContractCode());
			return;
		}
	}
	if (homeOrderAttachmentEntity == null) {
		return;
	}
	HeaderParam headerParams = new HeaderParam();
	headerParams.setOperatorUcId(contract.getModifyUserId());
	headerParams.setOperatorName(contract.getModifyUserName());
	headerParams.setRoleId("");
	atomChangeRpc.submitSubProcessToChange(contract.getProjectOrderId(), homeOrderAttachmentEntity.getBizCode(), contract.getContractCode(), headerParams);
	atomChangeRpc.submitChangeToRiskAudit(contract.getProjectOrderId(), homeOrderAttachmentEntity.getBizCode(), headerParams);
	LOGGER.info("团装变更推送到风控审核，projectOrderId:{},contractCode:{},变更单号:{}", contract.getProjectOrderId(), contract.getContractCode(), homeOrderAttachmentEntity.getBizCode());
}

private boolean hasOtherValidPersonalContractsForCompany(Contract contract) {
	List<Contract> existContracts = contractService.getContractList(
		contract.getProjectOrderId(),
		ContractTypeEnum.PERSONAL.getCode(),
		contract.getCompanyCode()
	);
	// 过滤掉当前合同和已取消的合同，判断是否还存在其他有效销售合同
	long otherContractCount = existContracts.stream()
		.filter(c -> !c.getContractCode().equals(contract.getContractCode()))
		.filter(c -> !ContractStatusEnum.CANCEL.getCode().equals(c.getStatus()))
		.count();
	return otherContractCount > 0;
}

