private List<ContractBaseDTO> getContractListByChangeOrder(String projectOrderId, String changeOrderId) {
	Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
		List<Byte> contractTypeList = new ArrayList<>();
		List<HomeOrderAttachmentEntity> orderAttachmentEntityList = homeOrderOperationCheckService.queryOrderAttachmentByHomeOrderNo(projectOrderId)
			.stream()
			.filter(item -> NrsOrderKindEnum.PROJECT_CHANGE_NO.getCode().equals(item.getBizType().intValue()))
			.filter(item -> ObjectUtil.equal(item.getBizCode(), changeOrderId))
			.collect(Collectors.toList());

		for (HomeOrderAttachmentEntity homeOrderAttachmentEntity : orderAttachmentEntityList) {
			if (Integer.valueOf(homeOrderAttachmentEntity.getAttachmentType()).equals(PlanAttachment.报价单)) {
				contractTypeList.add(ContractTypeEnum.PACKAGE_FORMAL.getCode());
			}
			if (Integer.valueOf(homeOrderAttachmentEntity.getAttachmentType()).equals(PlanAttachment.套外个性化报价单)) {
				contractTypeList.add(ContractTypeEnum.PERSONAL.getCode());
			}
		}
		if (CollectionUtils.isEmpty(contractTypeList)) {
			return new ArrayList<>();
		}
		List<Contract> contractList = contractService.getContractList(projectOrderId, contractTypeList);
		return formatContractBaseDTO(contractList);
	}
	List<Contract> contractList = contractService.getChangeContractList(projectOrderId, changeOrderId);
	return formatContractBaseDTO(contractList);
}

