public String obtainCollectionPlan(String contractCode) {
	ContractCollectionPlanRecord contractCollectionPlanRecord = contractCollectionPlanRecordService.getByContractCode(contractCode);
	if (ObjectUtil.isEmpty(contractCollectionPlanRecord) || ObjectUtil.isEmpty(contractCollectionPlanRecord.getCollectionPlan())) {
		throw new NrsBusinessException("【合同讲解脚本】收款计划获取失败，请检查合同数据", Level.ERROR);
	}

	CollectionPlanConfigInfo collectionPlanConfigInfo = JSON.parseObject(contractCollectionPlanRecord.getCollectionPlan(), CollectionPlanConfigInfo.class);
	if (ObjectUtil.isEmpty(collectionPlanConfigInfo) || CollectionUtil.isEmpty(collectionPlanConfigInfo.getContent())) {
		throw new NrsBusinessException("【合同讲解脚本】收款计划获取失败，请检查合同数据", Level.ERROR);
	}
	List<CollectionPlanItem> content = collectionPlanConfigInfo.getContent();
	StringBuilder payPlanBufferNew = new StringBuilder();
	Contract contract = contractService.getByContractCode(contractCode);
	if (ObjectUtil.isEmpty(contract)) {
		throw new NrsBusinessException("【合同讲解脚本】收款计划获取失败，合同信息不存在，请检查合同数据", Level.ERROR);
	}
	BigDecimal contractAmount = contract.getAmount();
	boolean processV25 = commonBusinessService.isProcessV25New(contract.getProjectOrderId());
	for (int i = 0; i < content.size(); i++) {
		CollectionPlanItem item = content.get(i);
		BigDecimal itemAmount = Objects.nonNull(item.getPrice()) && BigDecimal.ZERO.compareTo(item.getPrice()) != 0
			? item.getPrice()
			: contractAmount.multiply(item.getRate()).setScale(2, RoundingMode.HALF_UP);

		if (i == 0 && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType()) && processV25) {
			payPlanBufferNew.append(MessageFormat.format(PAY_PLAN_FORMAT_NEW
				, item.getLastPayNode(),
				item.getRate().multiply(new BigDecimal(100)).toString(),
				(new MoneyConvertUtil(itemAmount.toString())).convert().concat("（¥:").concat(itemAmount.toString()).concat("）")
			)).append("其中合同总金额的20%部分作为定金").append("\n");
		} else {
			payPlanBufferNew.append(MessageFormat.format(PAY_PLAN_FORMAT_NEW
				, item.getLastPayNode(),
				item.getRate().multiply(new BigDecimal(100)).toString(),
				(new MoneyConvertUtil(itemAmount.toString())).convert().concat("（¥:").concat(itemAmount.toString()).concat("）")
			)).append("\n");
		}
	}
	return payPlanBufferNew.toString();
}

public Boolean contractAgentOpen(String businessId) {
	try {
		if (StringUtils.isBlank(businessId)) {
			return false;
		}
		String homeOrderNo = homeOrderQueryService.getHomeOrderNoByBizNo(businessId);
		HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(homeOrderNo, Collections.singletonList(HomeModelDefEnum.CUSTOMER_HOUSE.toString()));
		CommissionDecorateTypeEnum commissionDecorateTypeEnum = CommissionDecorateTypeEnum.getEnumByCode(homeProject.getDecorateType());
		BusinessTypeEnum businessTypeEnum = BusinessTypeEnum.getEnumByDecorateType(CommissionDecorateTypeEnum.getEnumByCode(homeProject.getDecorateType()));
		if (!BusinessTypeEnum.HOUSE_CERTIFICATE.equals(businessTypeEnum) || CommissionDecorateTypeEnum.RETAIL.equals(commissionDecorateTypeEnum)) {
			return false;
		}
		SubProject highPriorityProject = homeProject.getHighPriorityProject();
		if (!ProjectModeEnum.PROCESS_V2_5.getCode().equals(highPriorityProject.getProjectMode())) {
			return false;
		}
		Integer gbCode = highPriorityProject.getCustomer().getHouseModule().getGbCode();
		return contractApolloConfig.openContractAgent(gbCode);
	} catch (Exception e) {
		LOGGER.error("【合同问答】基于业务单号获取agent开城逻辑异常，businessId:{}", businessId, e);
		return false;
	}

}

public Contract getLatestEffectiveDesignFeeContract(String projectOrderId) {
	// 获取最新的设计合同或设计变更合同
	Contract latestDesignContract = contractService.getLatestContract(projectOrderId, ContractTypeEnum.DESIGN_FEE_DESIGN_TYPES);
	// 查询正签合同/正签变更合同
	Contract packageFormalContract = contractService.getLatestContract(projectOrderId, ContractTypeEnum.DESIGN_FEE_PACKAGE_TYPES);
	// 所有合同不存在则返回为空
	if (latestDesignContract == null && packageFormalContract == null) {
		return null;
	}
	// 判断是否正签合同中约定设计费
	boolean isDesignFeeInPackageFormal = Boolean.FALSE;
	boolean mergeLaunchDesignContract = contractUnifyService.isMergeLaunchDesignContract(projectOrderId);
	if (packageFormalContract != null && !mergeLaunchDesignContract) {
		Map<String, String> packageFormalFieldMap = contractFieldService.getFieldMap(packageFormalContract.getContractCode());
		String needDesignerAmount = packageFormalFieldMap.getOrDefault("needDesignerAmount", "0");
		isDesignFeeInPackageFormal = "1".equals(needDesignerAmount);
	}
	// 正签未约定，则获取设计合同中约定信息
	if (!isDesignFeeInPackageFormal) {
		return latestDesignContract;
	}
	if (latestDesignContract == null) {
		return packageFormalContract;
	}
	// 正签约定设计费，且设计合同存在，则比较两者的签约时间，返回最新的合同
	Date latestDesignContractSignTime = syncTagService.getContractLatesFieTimeForSignNodeList(latestDesignContract.getContractCode());
	Date packageFormalContractSignTime = syncTagService.getContractLatesFieTimeForSignNodeList(packageFormalContract.getContractCode());
	if (latestDesignContractSignTime == null) {
		return packageFormalContract;
	}
	if (packageFormalContractSignTime == null) {
		return latestDesignContract;
	}
	return latestDesignContractSignTime.after(packageFormalContractSignTime) ? latestDesignContract : packageFormalContract;
}

public ProjectContractLatestInfoModel getDesignFeeInfo(Contract contract) {
	if (contract == null) {
		return null;
	}
	ProjectContractLatestInfoModel model = new ProjectContractLatestInfoModel();
	Map<String, String> fieldMap = contractFieldService.getFieldMap(contract.getContractCode());
	String preDiscountDesignerAmount = fieldMap.getOrDefault("preDiscountDesignerAmount", null);
	String afterDiscountDesignerAmount = fieldMap.getOrDefault("afterDiscountDesignerAmount", null);
	String designContractAmountSource = fieldMap.getOrDefault("designContractAmountSource", DesignFeeSourceEnum.合同.getCode().toString());
	String valuationArea = fieldMap.getOrDefault("valuationArea", null);
	String valuationAreaFromQuote = fieldMap.getOrDefault("valuationAreaFromQuote", null);
	String houseBuildType = fieldMap.getOrDefault("houseBuildType", null);
	String designerPsLevelName = fieldMap.getOrDefault("designerPsLevelName", null);
	model.setPreDiscountDesignerAmount(ObjectUtil.isNotEmpty(preDiscountDesignerAmount) ? new BigDecimal(preDiscountDesignerAmount) : null);
	model.setAfterDiscountDesignerAmount(ObjectUtil.isNotEmpty(afterDiscountDesignerAmount) ? new BigDecimal(afterDiscountDesignerAmount) : null);
	model.setDesignFeeSource(ObjectUtil.isNotEmpty(designContractAmountSource) ? Integer.valueOf(designContractAmountSource) : null);
	model.setDesignFeeArea(ObjectUtil.isNotEmpty(valuationArea) ? new BigDecimal(valuationArea) : null);
	model.setDesignFeeAreaFromQuote(ObjectUtil.isNotEmpty(valuationAreaFromQuote) ? new BigDecimal(valuationAreaFromQuote) : null);
	model.setHouseBuildTypeFromContract(ObjectUtil.isNotEmpty(houseBuildType) ? Integer.valueOf(houseBuildType) : null);
	model.setDesignerLevel(designerPsLevelName);
	model.setProjectOrderId(contract.getProjectOrderId());
	if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType()) || ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contract.getType())) {
		// 设计变更和设计合同默认设计费来源于合同
		model.setDesignFeeSource(DesignFeeSourceEnum.合同.getCode());
	}
	return model;
}

