@Service
@Slf4j
public class ContactFieldDealDataService {

	@Resource
	private ContractFieldMapper mapper;

	@Resource
	private ContractFieldShardingMapper shardingMapper;

	@Resource
	private ContractFieldServiceImpl contractFieldService;

	@Resource
	private ContractService contractService;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Resource
	private StringRedisTemplate stringRedisTemplate;

	/**
	 * 根据合同code获取旧表数据
	 *
	 * @param contractCode 合同编码
	 * @return 合同字段列表
	 */
	private List<ContractField> getOldTableData(String contractCode) {
		Example example = new Example(ContractField.class);
		example.createCriteria()
			.andEqualTo("contractCode", contractCode)
			.andEqualTo("delStatus", CommonEnum.NO);
		return mapper.selectByExample(example);
	}

	/**
	 * 根据合同code获取新表数据
	 *
	 * @param contractCode 合同编码
	 * @return 合同字段分表列表
	 */
	private List<ContractFieldSharding> getNewTableData(String contractCode) {
		Example example = new Example(ContractFieldSharding.class);
		example.createCriteria()
			.andEqualTo("contractCode", contractCode)
			.andEqualTo("delStatus", CommonEnum.NO);
		return shardingMapper.selectByExample(example);
	}

	/**
	 * 批量保存合同字段数据到新表
	 *
	 * @param contractFieldList 合同字段列表
	 */
	private void batchSaveToNewTableData(List<ContractField> contractFieldList) {
		if (CollectionUtil.isEmpty(contractFieldList)) {
			return;
		}
		List<ContractFieldSharding> contractFieldShardingList = contractFieldService.covertToContractFieldShardingList(contractFieldList);
		shardingMapper.insertList(contractFieldShardingList);
	}

	/**
	 * 根据合同code删除新表数据
	 *
	 * @param contractCode
	 */
	private void deleteNewTableDataByContractCode(String contractCode) {
		Example exampleSharding = new Example(ContractFieldSharding.class);
		Example.Criteria criteriaSharding = exampleSharding.createCriteria();
		criteriaSharding.andEqualTo("contractCode", contractCode);
		shardingMapper.deleteByExample(exampleSharding);
	}


	/**
	 * 单个合同将旧表数据迁移到新表
	 */
	public void oldDataToNewDataByContractCode(Contract contract) {
		String contractCode = contract.getContractCode();
		List<ContractFieldSharding> newTableData = getNewTableData(contractCode);
		if (CollectionUtil.isNotEmpty(newTableData)) {
			LOGGER.info("合同字段分表数据已存在，删除重新插入，合同编码: {}", contractCode);
			deleteNewTableDataByContractCode(contractCode);
		}
		List<ContractField> oldTableData = getOldTableData(contractCode);
		batchSaveToNewTableData(oldTableData);
		LOGGER.info("合同字段分表数据迁移成功，id:{}，合同编码: {}",contract.getId(), contractCode);
	}

	/**
	 * 根据合同id范围将旧表数据迁移到新表
	 *
	 * @param startId 开始id
	 * @param endId   结束id
	 */
	public void oldDataToNewDataByIdRange(Integer startId, Integer endId) {
		LOGGER.info("合同字段分表数据迁移开始，startId:{},endId:{}", startId, endId);
		long start = System.currentTimeMillis();
		int count = 0;
		while (startId <= endId) {
			Contract contract = contractService.selectByPk(startId);
			if (contract == null) {
				startId++;
				continue;
			}
			if (!contractApolloConfig.getContractFieldInterruptDataMigration()) {
				LOGGER.info("合同字段中断数据迁移开关关闭，中断刷数");
				return;
			}
			try {
				oldDataToNewDataByContractCode(contract);
				startId++;
				count++;
				//redis存储支付信息
				try {
					stringRedisTemplate.opsForValue().set(Constant.contract_contractField_dataMigration_index, String.valueOf(startId), 100, TimeUnit.DAYS);
				} catch (Exception e) {
					LOGGER.info("合同字段分表数据迁移过程中，redis存储支付信息失败，合同编码: {}, 错误信息: {}", contract.getContractCode(), e.getMessage());
				}
				// 每处理 100 条，休眠 1 秒
				if (count % 100 == 0) {
					Thread.sleep(100);
				}
			} catch (InterruptedException ie) {
				Thread.currentThread().interrupt();
				startId++;
				LOGGER.warn("线程被中断", ie);
			} catch (Exception e) {
				LOGGER.error("合同字段分表数据迁移失败，合同编码: {}, 错误信息: {}", contract.getContractCode(), e.getMessage());
				startId++; // 避免异常卡死，继续处理下一条
			}
		}
		LOGGER.info("合同字段分表数据迁移完成，处理数据量:{},耗时: {} ms", count, System.currentTimeMillis() - start);
	}

	/**
	 * 单合同校验新表旧表数据一致性
	 */
	public String checkDataConsistencyByContractCode(String contractCode) {
		boolean errorFlag = false;
		List<ContractField> oldTableData = getOldTableData(contractCode);
		List<ContractFieldSharding> newTableData = getNewTableData(contractCode);
		Map<String, ContractField> oldMap = oldTableData.stream()
			.collect(Collectors.toMap(ContractField::getFieldKey, f -> f, (a, b) -> a));

		Map<String, ContractFieldSharding> newMap = newTableData.stream()
			.collect(Collectors.toMap(ContractFieldSharding::getFieldKey, f -> f, (a, b) -> a));

		Set<String> allFieldKeys = new HashSet<>();
		allFieldKeys.addAll(oldMap.keySet());
		allFieldKeys.addAll(newMap.keySet());

		for (String fieldKey : allFieldKeys) {
			ContractField oldField = oldMap.get(fieldKey);
			ContractFieldSharding newField = newMap.get(fieldKey);

			if (oldField == null) {
				LOGGER.info("[合同字段差异] contractCode={} 字段缺失于旧表: fieldKey={}, newValue={}", contractCode, fieldKey, newField.getFieldValue());
				errorFlag = true;
				continue;
			}

			if (newField == null) {
				LOGGER.info("[合同字段差异] contractCode={} 字段缺失于新表: fieldKey={}, oldValue={}", contractCode, fieldKey, oldField.getFieldValue());
				errorFlag = true;
				continue;
			}

			if (!Objects.equals(oldField.getFieldValue(), newField.getFieldValue())) {
				LOGGER.info("[合同字段值不一致] contractCode={} fieldKey={} oldValue={} newValue={}",
					contractCode, fieldKey, oldField.getFieldValue(), newField.getFieldValue());
				errorFlag = true;
			}
		}
		if (oldTableData.size() != newTableData.size()) {
			LOGGER.info("[合同字段数量不一致] contractCode={} 旧表数量={} 新表数量={}", contractCode, oldTableData.size(), newTableData.size());
		}
		LOGGER.info("[合同字段值比对完成] contractCode={} 字段数(旧表={}, 新表={})", contractCode, oldTableData.size(), newTableData.size());
		return errorFlag ? contractCode : "";
	}

	/**
	 * 根据合同id范围校验新表旧表数据一致性
	 */
	public void checkDataConsistencyByIdRange(Integer startId, Integer endId) {
		int count = 0;
		long start = System.currentTimeMillis();
		List<String> errorContractCodes = new ArrayList<>();
		while (startId <= endId) {
			Contract contract = contractService.selectByPk(startId);
			if (contract == null) {
				startId++;
				continue;
			}
			try {
				String errorContractCode = checkDataConsistencyByContractCode(contract.getContractCode());
				if (StringUtils.isNotBlank(errorContractCode)) {
					errorContractCodes.add(errorContractCode);
				}
				count++;
				startId++;
				// 每处理 100 条，休眠 1 秒
				if (count % 100 == 0) {
					Thread.sleep(10);
				}
			} catch (InterruptedException ie) {
				Thread.currentThread().interrupt();
				startId++;
				LOGGER.warn("线程被中断", ie);
			} catch (Exception e) {
				LOGGER.error("校验新表旧表数据一致性失败，合同编码: {}, 错误信息: {}", contract.getContractCode(), e.getMessage());
				startId++; // 避免异常卡死，继续处理下一条
			}
		}
