public void oldDataToNewDataByContractCode(Contract contract) {
	String contractCode = contract.getContractCode();
	List<ContractFieldSharding> newTableData = getNewTableData(contractCode);
	if (CollectionUtil.isNotEmpty(newTableData)) {
		LOGGER.info("合同字段分表数据已存在，删除重新插入，合同编码: {}", contractCode);
		deleteNewTableDataByContractCode(contractCode);
	}
	List<ContractField> oldTableData = getOldTableData(contractCode);
	batchSaveToNewTableData(oldTableData);
	LOGGER.info("合同字段分表数据迁移成功，id:{}，合同编码: {}",contract.getId(), contractCode);
}

public void oldDataToNewDataByIdRange(Integer startId, Integer endId) {
	LOGGER.info("合同字段分表数据迁移开始，startId:{},endId:{}", startId, endId);
	long start = System.currentTimeMillis();
	int count = 0;
	while (startId <= endId) {
		Contract contract = contractService.selectByPk(startId);
		if (contract == null) {
			startId++;
			continue;
		}
		if (!contractApolloConfig.getContractFieldInterruptDataMigration()) {
			LOGGER.info("合同字段中断数据迁移开关关闭，中断刷数");
			return;
		}
		try {
			oldDataToNewDataByContractCode(contract);
			startId++;
			count++;
			//redis存储支付信息
			try {
				stringRedisTemplate.opsForValue().set(Constant.contract_contractField_dataMigration_index, String.valueOf(startId), 100, TimeUnit.DAYS);
			} catch (Exception e) {
				LOGGER.info("合同字段分表数据迁移过程中，redis存储支付信息失败，合同编码: {}, 错误信息: {}", contract.getContractCode(), e.getMessage());
			}
			// 每处理 100 条，休眠 1 秒
			if (count % 100 == 0) {
				Thread.sleep(100);
			}
		} catch (InterruptedException ie) {
			Thread.currentThread().interrupt();
			startId++;
			LOGGER.warn("线程被中断", ie);
		} catch (Exception e) {
			LOGGER.error("合同字段分表数据迁移失败，合同编码: {}, 错误信息: {}", contract.getContractCode(), e.getMessage());
			startId++; // 避免异常卡死，继续处理下一条
		}
	}
	LOGGER.info("合同字段分表数据迁移完成，处理数据量:{},耗时: {} ms", count, System.currentTimeMillis() - start);
}

