public String checkDataConsistencyByContractCode(String contractCode) {
	boolean errorFlag = false;
	List<ContractField> oldTableData = getOldTableData(contractCode);
	List<ContractFieldSharding> newTableData = getNewTableData(contractCode);
	Map<String, ContractField> oldMap = oldTableData.stream()
		.collect(Collectors.toMap(ContractField::getFieldKey, f -> f, (a, b) -> a));

	Map<String, ContractFieldSharding> newMap = newTableData.stream()
		.collect(Collectors.toMap(ContractFieldSharding::getFieldKey, f -> f, (a, b) -> a));

	Set<String> allFieldKeys = new HashSet<>();
	allFieldKeys.addAll(oldMap.keySet());
	allFieldKeys.addAll(newMap.keySet());

	for (String fieldKey : allFieldKeys) {
		ContractField oldField = oldMap.get(fieldKey);
		ContractFieldSharding newField = newMap.get(fieldKey);

		if (oldField == null) {
			LOGGER.info("[合同字段差异] contractCode={} 字段缺失于旧表: fieldKey={}, newValue={}", contractCode, fieldKey, newField.getFieldValue());
			errorFlag = true;
			continue;
		}

		if (newField == null) {
			LOGGER.info("[合同字段差异] contractCode={} 字段缺失于新表: fieldKey={}, oldValue={}", contractCode, fieldKey, oldField.getFieldValue());
			errorFlag = true;
			continue;
		}

		if (!Objects.equals(oldField.getFieldValue(), newField.getFieldValue())) {
			LOGGER.info("[合同字段值不一致] contractCode={} fieldKey={} oldValue={} newValue={}",
				contractCode, fieldKey, oldField.getFieldValue(), newField.getFieldValue());
			errorFlag = true;
		}
	}
	if (oldTableData.size() != newTableData.size()) {
		LOGGER.info("[合同字段数量不一致] contractCode={} 旧表数量={} 新表数量={}", contractCode, oldTableData.size(), newTableData.size());
	}
	LOGGER.info("[合同字段值比对完成] contractCode={} 字段数(旧表={}, 新表={})", contractCode, oldTableData.size(), newTableData.size());
	return errorFlag ? contractCode : "";
}

public void checkDataConsistencyByIdRange(Integer startId, Integer endId) {
	int count = 0;
	long start = System.currentTimeMillis();
	List<String> errorContractCodes = new ArrayList<>();
	while (startId <= endId) {
		Contract contract = contractService.selectByPk(startId);
		if (contract == null) {
			startId++;
			continue;
		}
		try {
			String errorContractCode = checkDataConsistencyByContractCode(contract.getContractCode());
			if (StringUtils.isNotBlank(errorContractCode)) {
				errorContractCodes.add(errorContractCode);
			}
			count++;
			startId++;
			// 每处理 100 条，休眠 1 秒
			if (count % 100 == 0) {
				Thread.sleep(10);
			}
		} catch (InterruptedException ie) {
			Thread.currentThread().interrupt();
			startId++;
			LOGGER.warn("线程被中断", ie);
		} catch (Exception e) {
			LOGGER.error("校验新表旧表数据一致性失败，合同编码: {}, 错误信息: {}", contract.getContractCode(), e.getMessage());
			startId++; // 避免异常卡死，继续处理下一条
		}
	}
	LOGGER.info("根据合同id范围校验新表旧表数据一致性完成，errorContractCodes:{},处理数据量:{},耗时: {} ms", errorContractCodes, count, System.currentTimeMillis() - start);
}

