@Service
@Slf4j
public class ContractAgentService {

	@Resource
	private StringRedisTemplate stringRedisTemplate;

	@Resource
	private ContractScriptService contractScriptService;

	@Resource
	private VoiceExplainRecordService voiceExplainRecordService;

	@Resource
	private S3Service s3Service;


	private static final String CONTRACT_SCRIPT_KEY_PREFIX = "nrs:contract:script:";

	/**
	 * 生成脚本任务
	 */
	public Boolean generateContractScript(String contractCode) {
		// 获取redis key
		String redisKey = CONTRACT_SCRIPT_KEY_PREFIX + contractCode;
		// 判断是否存在在途任务
		Boolean hasKey = stringRedisTemplate.hasKey(redisKey);
		if (Boolean.TRUE.equals(hasKey)) {
			LOGGER.info("合同讲解脚本生成任务已在进行中，contractCode: {}", contractCode);
		}
		// 异步请求生成脚本任务
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				//生成合同讲解脚本
				stringRedisTemplate.opsForValue().set(redisKey, "1", 90, TimeUnit.SECONDS);
				contractScriptService.asyncGenerateContractScript(contractCode);
			} catch (Exception e) {
				LOGGER.error("合同讲解脚本生成失败", e);
				// 删除在途任务标记
				stringRedisTemplate.delete(redisKey);
			} finally {
				// 删除在途任务标记
				stringRedisTemplate.delete(redisKey);
			}
		}));
		return true;
	}

	/**
	 * 轮询脚本生成状态
	 */
	public Boolean getContractScriptStatus(String contractCode) {
		// 获取redis key
		String redisKey = CONTRACT_SCRIPT_KEY_PREFIX + contractCode;
		// 判断是否存在在途任务
		Boolean hasKey = stringRedisTemplate.hasKey(redisKey);
		if (Boolean.TRUE.equals(hasKey)) {
			// 任务在途
			return false;
		}
		// 查询脚本信息
		List<VoiceExplainRecord> voiceExplainRecords = voiceExplainRecordService.getByContractCode(contractCode);
		return CollectionUtil.isNotEmpty(voiceExplainRecords);
	}

	/**
	 * 获取合同讲解脚本内容
	 */
	public List<ContractScriptModuleDTO> getContractScriptContent(String contractCode) {
		try {
			// 查询模块配置
			List<ContractScriptModule> moduleList = contractScriptService.getScriptModuleConfig(contractCode, ScriptSceneTypeEnum.CONTRACT_EXPLANATION.getCode());
			Map<Integer, ContractScriptModule> moduleMap = moduleList.stream().collect(Collectors.toMap(ContractScriptModule::getModuleType, m -> m, (m1, m2) -> m1));
			// 查询脚本讲解内容
			List<VoiceExplainRecord> voiceExplainRecordList = voiceExplainRecordService.getByContractCode(contractCode);
			// 遍历讲解脚本，并根据moduleType分组
			Map<Integer, List<VoiceExplainRecord>> recordMap = new HashMap<>();
			Map<Integer, List<String>> originalTextMap = new HashMap<>();
			Map<String, Object> extInfoMap = new HashMap<>();
			for (VoiceExplainRecord voiceExplainRecord : voiceExplainRecordList) {
				voiceExplainRecord.setBusinessContent(s3Service.generateUrl(voiceExplainRecord.getBusinessContent(), 604800));
				Integer moduleType = voiceExplainRecord.getModuleType();
				if (!recordMap.containsKey(moduleType)) {
					recordMap.put(moduleType, new ArrayList<>());
				}
				recordMap.get(moduleType).add(voiceExplainRecord);
				// 获取动态字段变量值,还原成map格式
				String extInfo = voiceExplainRecord.getExtInfo();
				ObjectMapper objectMapper = new ObjectMapper();
				if (ObjectUtil.isNotEmpty(extInfo)) {
					Map<String, Object> map = objectMapper.readValue(extInfo,
						new TypeReference<Map<String, Object>>() {});
					extInfoMap.putAll(map);
				}
			}
			// 组装返回结果
			List<ContractScriptModuleDTO> resultList = new ArrayList<>();
			for (Map.Entry<Integer, List<VoiceExplainRecord>> entry : recordMap.entrySet()) {
				Integer moduleType = entry.getKey();
				ContractScriptModule module = moduleMap.get(moduleType);
				if (ObjectUtil.isNull(module)) {
					throw new NrsBusinessException("合同讲解脚本模块配置不存在，moduleType: " + moduleType);
				}
				ScriptModuleTypeEnum moduleEnum = ScriptModuleTypeEnum.getByCode(moduleType);
				List<VoiceExplainRecord> records = entry.getValue();
				ContractScriptModuleDTO contractScriptModuleDTO = new ContractScriptModuleDTO();
				contractScriptModuleDTO.setModuleType(module.getModuleType());
				contractScriptModuleDTO.setModuleIcon(moduleEnum.getIcon());
				contractScriptModuleDTO.setModuleName(module.getModuleName());
				contractScriptModuleDTO.setModuleOrder(module.getModuleOrder());
				contractScriptModuleDTO.setSceneType(module.getSceneType());
				List<String> originalTextList;
				if (originalTextMap.containsKey(moduleType)) {
					originalTextList = originalTextMap.get(moduleType);
				} else {
					originalTextList = JSON.parseArray(module.getOriginalText(), String.class);
					// 替换动态字段变量
					originalTextList = contractScriptService.replacePlaceholdersInOriginalTexts(originalTextList, extInfoMap);
					originalTextMap.put(moduleType, originalTextList);
				}
				// 替换动态字段变量
				contractScriptModuleDTO.setOriginalTextList(originalTextList);
				// 按照字段顺序和SDK结构构建数据
				ContractScriptTreeVO contractScriptTreeVO = contractScriptService.getContractScriptTree(records);
				contractScriptModuleDTO.setAutoOption(contractScriptTreeVO);
				resultList.add(contractScriptModuleDTO);
			}
			// 将模块按顺序排序
			resultList.sort(Comparator.comparing(ContractScriptModuleDTO::getModuleOrder));
			return resultList;
		} catch (Exception e) {
			LOGGER.error("获取合同讲解脚本内容失败，contractCode: {}", contractCode, e);
			throw new NrsBusinessException("获取合同讲解脚本内容失败，请稍后重试");
		}
	}

	/**
	 * 获取合同问答标注关键信息
	 */
	public List<ContractScriptModuleDTO> getContractQaHighlight(String contractCode) {
		try {
			List<ContractScriptModule> scriptModuleConfig = contractScriptService.getScriptModuleConfig(contractCode, ScriptSceneTypeEnum.CONTRACT_QA.getCode());
			// 获取动态字段并替换
			Set<String> feildNames = scriptModuleConfig.stream()
				.map(ContractScriptModule::getDynamicFields)
				.filter(ObjectUtil::isNotEmpty)
				.flatMap(s -> Arrays.stream(s.split(",")))
				.filter(str -> !str.trim().isEmpty())
				.collect(Collectors.toSet());
			// 根据字段值获取动态方法
			Map<String, Object> scriptDynamicFieldBs = contractScriptService.getDynamicFieldValue(contractCode, feildNames);
			// 组装返回结果
			List<ContractScriptModuleDTO> resultList = new ArrayList<>();
			// 替换模块配置中的动态变量
			for (ContractScriptModule module : scriptModuleConfig) {
				String originalText = module.getOriginalText();
				List<String> originalTextList = new ArrayList<>();
				if (ObjectUtil.isNotEmpty(originalText)) {
					originalTextList = JSON.parseArray(originalText, String.class);
					// 替换动态字段变量
					originalTextList = contractScriptService.replacePlaceholdersInOriginalTexts(originalTextList, scriptDynamicFieldBs);
				}
				ContractScriptModuleDTO dto = ContractScriptModuleDTO.builder()
					.moduleType(module.getModuleType())
					.moduleName(module.getModuleName())
					.moduleIcon(ScriptModuleTypeEnum.getByCode(module.getModuleType()).getIcon())
					.moduleOrder(module.getModuleOrder())
					.sceneType(module.getSceneType())
					.originalTextList(originalTextList)
					.build();
				resultList.add(dto);
			}
			// 将模块按顺序排序
			if (CollectionUtils.isNotEmpty(resultList)) {
				resultList.sort(Comparator.comparing(ContractScriptModuleDTO::getModuleOrder));
				return resultList;
			}
			return Collections.emptyList();

		} catch (Exception e) {
			LOGGER.error("获取合同问答标注关键信息失败，contractCode: {}", contractCode, e);
			return Collections.emptyList();
		}
	}

}

