	/**
	 * 为了小程序，需要转换一下host
	 *
	 * @param url
	 * @return
	 */
	public static String translateSignUrl(String url) {
		try {
			HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
			connection.setInstanceFollowRedirects(false);
			connection.setConnectTimeout(2000);
			return connection.getHeaderField("Location").replace("https://openapi.bestsign.cn", "https://wx107.bestsign.cn");
		} catch (Exception e) {
			LOGGER.error("转换手签url失败：{}, {}", url, e.getMessage());
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "转换链接失败");
		}
	}

	/**
	 * 获取用户合同分组信息
	 *
	 * @param ucId
	 * @param projectOrderId
	 * @return
	 */
	public ContractListGroup getContractListGroup(Long ucId, String projectOrderId) {
		ContractListGroup resGroup = new ContractListGroup();
		List<ContractListGroup.ContractGroup> groupList = new ArrayList<>();
		//并行请求整装和零售合同分类
		String appId = HeaderContext.getContext().getAppId();
		CompletableFuture<ContractListVo> decorateFuture = CompletableFuture.supplyAsync(() -> getUserContractList(ucId, projectOrderId, appId), parallelRequestExecutor);
		CompletableFuture<Page<ContractDetailDTO>> retailFuture = CompletableFuture.supplyAsync(() -> orderServiceRpc.retailContractListByUcid(ucId), parallelRequestExecutor);

		ContractListVo decorateContractListVo = null;
		try {
			decorateContractListVo = decorateFuture.get();
		} catch (NrsBusinessException e) {
			throw e;
		} catch (Exception e) {
			LOGGER.error("获取整装合同类型列表失败projectOrderId:{},ucid:{}", projectOrderId, ucId, e);
			throw new NrsBusinessException("获取合同类型列表失败，请刷新或联系客服");
		}

		Page<ContractDetailDTO> retailContractDetailDTO = null;
		try {
			retailContractDetailDTO = retailFuture.get();
		} catch (NrsBusinessException e) {
			throw e;
		} catch (Exception e) {
			LOGGER.error("获取零售合同类型列表失败,兼容只展示整装合同列表projectOrderId:{},ucid:{}", projectOrderId, ucId, e);
		}

		if (CollectionUtils.isNotEmpty(decorateContractListVo.getList())) {
			ContractListGroup.ContractGroup decorateGroup = ContractListGroup.ContractGroup.builder()
				.key(ContractGroupEnum.DECORATE_AND_PERSONALIZE.getKey())
				.title(ContractGroupEnum.DECORATE_AND_PERSONALIZE.getTitle())
				.build();
			groupList.add(decorateGroup);
		}

		if (retailContractDetailDTO != null && CollectionUtils.isNotEmpty(retailContractDetailDTO.getList())) {
			ContractListGroup.ContractGroup retailGroup = ContractListGroup.ContractGroup.builder()
				.key(ContractGroupEnum.RETAIL.getKey())
				.title(ContractGroupEnum.RETAIL.getTitle())
				.build();
			groupList.add(retailGroup);
		}
		resGroup.setGroupList(groupList);
		resGroup.setProjectOrderId(projectOrderId);
		resGroup.setPhone(getPhone(ucId));
		resGroup.setAddress(getAddress(projectOrderId));
		return resGroup;
	}

	/**
	 * 获取用户合同列表
	 *
	 * @param groupKey
	 * @param ucId
	 * @param projectOrderId
	 * @param currentPage
	 * @param pageSize
	 * @return
	 */
	public ContractListPageVo getUserContractListPage(String groupKey, Long ucId, String projectOrderId, Integer currentPage, Integer pageSize) {
		if (ContractGroupEnum.DECORATE_AND_PERSONALIZE.getKey().equals(groupKey)) {
			//整装&整装搭售
			String appId = HeaderContext.getContext().getAppId();
			ContractListVo decorateContractList = getUserContractList(ucId, projectOrderId, appId);
			Map<Integer, List<ContractListVo.ContractItemVo>> groupInfo = decorateContractList.getGroupInfo();
			List<ContractListVo.ContractItemVo> contractItemVoList = ObjectUtil.isEmpty(decorateContractList) || CollectionUtil.isEmpty(decorateContractList.getList()) ? new ArrayList<>() : decorateContractList.getList();
			List<ContractListVo.ContractItemVo> decorateContractListPage = PageUtil.paginateList(contractItemVoList, pageSize, currentPage);
			ContractListPageVo contractListPageVo = new ContractListPageVo(currentPage, pageSize, decorateContractListPage.size(), decorateContractListPage);
			contractListPageVo.setGroupInfo(groupInfo);
			return contractListPageVo;
		} else if (ContractGroupEnum.RETAIL.getKey().equals(groupKey)) {
			//零售
			Page<ContractListVo.ContractItemVo> retailContractList = contractOrderCenterRpc.queryCustomerContractListForMp(ucId, currentPage, pageSize);
			return new ContractListPageVo(retailContractList.getCurrentPage(), retailContractList.getPageSize(), retailContractList.getTotal(), retailContractList.getList());
		}
		return null;
	}

