	/**
	 * 获取用户签约时间
	 *
	 * @param contractCode
	 * @return
	 */
	public Date getUserSignTime(String contractCode) {
		List<ContractNode> contractNodes = contractNodeService.getListByContractCode(contractCode);
		ContractNode contractNode = contractNodes.stream().filter(node ->
			node.getNodeType().equals(NodeTypeEnum.USER_CONFIRM.getCode()) || node.getNodeType().equals(NodeTypeEnum.USER_SIGN.getCode())
