	/**
	 * c端获取合同详情
	 *
	 * @param ucId
	 * @param contractCode
	 * @return
	 */
	public ContractDetailVo getContractDetail(Long ucId, String contractCode) {
		ContractDetailVo result = new ContractDetailVo();
		ContractUser contractUser = contractUserService.getSignerByContractCode(contractCode);
		if (Objects.isNull(contractUser)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人-[签约]");
		}
		//加解密
		String contractUserPhone = cipherService.decrypt(contractUser.getPhone());
		result.setSignerPhone(contractUserPhone.replaceAll("(\\d{3})\\d{4}(\\d{4})", "$1****$2"));
		// 获取合同信息
		Contract contract = contractService.getByContractCode(contractCode);
		if (contract == null) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "当前合同不存在，请联系服务者确认操作是否正确", Level.WARN);
		}
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
		result.setFormalMergeLaunch(processV25);
		//获取用户信息
		CUserDTO userDTO = userFeignService.getUserInfo(ucId.toString());
		String loginPhone = cipherService.decrypt(userDTO.getPhone());
		//校验登录人和签约人是否一致
		if (!loginPhone.equals(contractUserPhone)) {
			result.setAuthCode(AuthCodeEnum.USER_NOT_SAME.getCode());
			result.setAuthError(UserNotSameError.builder()
				.signerPhone(StringUtils.isBlank(contractUserPhone) ? "" : contractUserPhone.substring(contractUserPhone.length() - 4))
				.loginPhone(StringUtils.isBlank(loginPhone) ? "" : loginPhone.substring(loginPhone.length() - 4))
				.helpUrl(userNameNotSameHelpUrl) //都是一个链接，不再区分
				.build());
			return result;
		}

		BeanUtils.copyProperties(contract, result);
		result.setAiAssistantOpen(contractScriptService.aiAssistantOpen(contract));
		result.setNeedRealNameVerifyInConfirm(needRealNameVerifyInConfirmForC(contract));
		result.setStatusText(ContractStatusEnum.getNameByCode(contract.getStatus()));
		result.setTypeText(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()));
		result.setUserSignStatus(contract.getUserSignStatus());
		result.setUserConfirmStatus(contract.getUserConfirmStatus());
		result.setPdfPageCount(contract.getPdfPageCount());
		result.setGbcode(contract.getGbCode());
		if (ContractTypeEnum.getRelateContractTypes().contains(contract.getType())) {
			List<Byte> contractTypeList = new ArrayList<>(ContractTypeEnum.getRelateContractTypes());
			//获取线上合同url信息&关联合同线上url信息
			List<ContractOnlineVo> contractOnlineUrl = homeAndPcCommonService.getContractOnlineUrlForC(contract, contractTypeList);
			result.setContractUrlList(contractOnlineUrl.stream()
				.filter(contractOnlineVo -> !ContractTypeEnum.AUTH_AGENT.getCode().equals(contractOnlineVo.getContractType())).collect(Collectors.toList()));
			//获取线下合同url信息&关联合同线下url信息
			result.setAttachUrlList(homeAndPcCommonService.getContractOfflineUrl(contract, contractTypeList));
		}
		//单独发起销售合同场景，返回所有当前项目在销售合同
		if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()) && homeAndPcCommonService.isMultipleQuotePersonalContract(contract)) {
			List<Contract> allPersonalContract = contractMpService.getPersonalContract(contract.getProjectOrderId(), HeaderContext.getUserId().toString(),ContractStatusEnum.validStatusWithoutDraft);
			List<ContractOnlineVo> contractOnlineVoList = coverContractListToContractOnlineVoList(allPersonalContract);
			List<ContractOfflineVo> contractOfflineVoList = coverContractListToContractOfflineVoList(allPersonalContract);
			result.setContractUrlList(contractOnlineVoList);
			result.setAttachUrlList(contractOfflineVoList);
		}

		//线上补充pdf url
		if (contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode())) {
			result.setContractUrl(s3Service.generateUrl(getContractLatestPdfKey(contract), 1800));
		} else {
			//线下补充图片
			List<ContractAttach> attachList = contractAttachService.getListByContractCode(contractCode, AttachTypeEnum.OFFLINE_CONTRACT.getCode());
			result.setAttachUrl(attachList.stream().map(ContractAttach::getUrl).collect(Collectors.toList()));
			result.setAttachFileType(getAttachFileKey(result.getAttachUrl()));
		}
		result.setSignChannelType(contract.getSignChannelType());
		result.setBusinessType(contract.getBusinessType());
		result.setProcessV25(processV25);
		result.setUserSignType(contract.getUserSignType());
		result.setContractMode(commonContractService.getContractModeByContractCode(contractCode));

		boolean canUseFaceAuth = faceAuthService.canUseFaceAuth(Collections.singletonList(contractCode), contractUser);
		if (canUseFaceAuth) {
			// 判断是否已认证通过
			String phone = contractUser.getPhone();
			String certificateNo = contractUser.getCertificateNo();
			boolean authedUser = contractUserService.getAuthedUser(phone, certificateNo);
			if (authedUser) {
				result.setAuthCode(AuthCodeEnum.SUCCESS.getCode());
			} else {
				boolean authResult = faceAuthService.getAuthResult(contractCode);
				if (authResult) {
					String bizFlowNo = contractRedisRepoService.getFaceAuthBizFlowNo(contractCode);
					// 记录认证结果
					contractUser.setIsAuth(CommonEnum.YES.getCode());
					contractUser.setAuthChannelNo(bizFlowNo);
					contractUserService.update(contractUser);
				}
				result.setAuthCode(authResult ? AuthCodeEnum.SUCCESS.getCode() : AuthCodeEnum.NOT_FACE_AUTH.getCode());
			}
			return result;
		}

		//查询实名认证信息
		UserInfo authUserInfo = userPlatformFeignService.getUserInfoByUcId(ucId);
		//实名结果校验
		if (Objects.isNull(authUserInfo) || AuthStatusEnum.INVALID.getCode().equals(authUserInfo.getStatus())) {
			result.setAuthCode(AuthCodeEnum.NOT_REAL_AUTH.getCode());
			return result;
		}
		result.setAuthCode(AuthCodeEnum.SUCCESS.getCode());
		result.setStatus(contract.getStatus());

		return result;
	}

	public List<ContractOnlineVo> coverContractListToContractOnlineVoList(List<Contract> contractList) {
		List<ContractOnlineVo> contractOnlineVoList = new ArrayList<>();
		for (Contract contract : contractList) {
			if (contract.getSignChannelType().equals(SignChannelTypeEnum.OFFLINE.getCode()) || !ContractStatusEnum.inPositiveStatus.contains(contract.getStatus())) {
				continue;
			}
			String contractUrl = homeAndPcCommonService.getContractUrl(contract);
			ContractOnlineVo build = ContractOnlineVo.builder()
				.contractType(contract.getType())
				.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
				.shortName(ContractTypeEnum.getShortName(contract.getType()))
				.contractCode(contract.getContractCode())
				.pdfPageCount(contract.getPdfPageCount())
				.contractUrl(contractUrl)
				.status(contract.getStatus())
				.build();
			contractOnlineVoList.add(build);
		}
		return contractOnlineVoList;
	}


	public List<ContractOfflineVo> coverContractListToContractOfflineVoList(List<Contract> contractList){
		List<ContractOfflineVo> contractOfflineVoList = new ArrayList<>();
		for (Contract contract : contractList) {
			if (contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode()) || !ContractStatusEnum.inPositiveStatus.contains(contract.getStatus())) {
				continue;
			}
			List<String> attachUrl = homeAndPcCommonService.getAttachUrl(contract);
			ContractOfflineVo build = ContractOfflineVo.builder()
				.contractType(contract.getType())
				.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
				.contractCode(contract.getContractCode())
				.shortName(ContractTypeEnum.getShortName(contract.getType()))
				.attachUrl(attachUrl)
				.status(contract.getStatus())
				.attachFileType(getAttachFileKey(attachUrl))
				.build();
			contractOfflineVoList.add(build);
		}
		return contractOfflineVoList;
	}


	/**
	 * 获取线上合同PDF某一页对应的图片
	 *
	 * @param contractCode
	 * @param page
	 * @param ucId
	 * @return
	 */
	public ContractPdfImageVo getContractPageImage(String contractCode, Integer page, Long ucId) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在-[签约]");
		}

		ContractUser contractUser = contractUserService.getSignerByContractCode(contractCode);
		if (Objects.isNull(contractUser)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人-[签约]");
		}

		//加解密
		String contractUserPhone = cipherService.decrypt(contractUser.getPhone());
		//获取用户信息
		CUserDTO userDTO = userFeignService.getUserInfo(ucId.toString());
		String loginPhone = cipherService.decrypt(userDTO.getPhone());
		//校验登录人和签约人是否一致
		if (!loginPhone.equals(contractUserPhone)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "非签约人，无权限访问");
		}

		//校验页数合法
		if (page > contract.getPdfPageCount()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "无效页数");
		}

		//目前只支持线上的
		if (!SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "非线上合同，无效请求");
		}

		String latestPdfKey = getContractLatestPdfKey(contract);
		ContractPdfImage contractPdfImage = contractPdfImageService.getByPdfKeyAndPage(latestPdfKey, page);

		ContractPdfImageVo result = new ContractPdfImageVo();
		//图片还没有，需要去兜底处理
		if (Objects.isNull(contractPdfImage)) {
			result.setStatus(PdfImageStatusEnum.DOING.getCode().intValue());
			//开启一个线程处理
			CompletableFuture.runAsync(() -> {
				if (ContractTypeEnum.DRAWING.getCode().equals(contract.getType())) {
					LOGGER.info("C端查看合同未找到图片，contractCode:{}", contractCode);
					//2025-04-02，图纸合同去除兜底转图片功能，避免服务器崩溃
					return;
				}
				contractPdfToImage(contractCode);
			});
			return result;
		}

		result.setStatus(PdfImageStatusEnum.OK.getCode().intValue());
		result.setImageUrl(s3Service.generateUrl(contractPdfImage.getImageKey(), 1800));
		return result;
	}

	/**
	 * 获取手签url
	 */
	public ContractSignUrlVo getContractSignUrl(String contractCode, String returnUrl) {
		List<String> contractCodeList = Arrays.asList(contractCode.split(","));
		List<ContractUser> signerList = contractUserService.getSignerByContractCodes(contractCodeList);
		if (CollectionUtils.isEmpty(signerList)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人-[签约]");
		}
		ContractUser signer = signerList.get(0);
		CUserDTO userDTO = userFeignService.getUserInfo(HeaderContext.getUserId().toString());
		String phone = cipherService.decrypt(userDTO.getPhone());
		Contract contract = contractService.getByContractCode(contractCode);
		String signerPhone = cipherService.decrypt(signer.getPhone());
		String loginPhone = cipherService.decrypt(userDTO.getPhone());
		//校验登录人和签约人是否一致
		if (!signerPhone.equals(phone)) {
			ContractSignUrlVo result = new ContractSignUrlVo();
			result.setAuthCode(AuthCodeEnum.USER_NOT_SAME.getCode());
			result.setAuthError(UserNotSameError.builder()
				.signerPhone(ObjectUtil.isNotEmpty(signerPhone) ? signerPhone.substring(signerPhone.length() - 4) : "")
				.loginPhone(ObjectUtil.isNotEmpty(signerPhone) ? loginPhone.substring(loginPhone.length() - 4) : "")
				.helpUrl(userNameNotSameHelpUrl) //都是一个链接，不再区分
				.build());
			return result;
		}

		// 触发风控
		HeaderParam headerParam = HeaderContext.getContext();
		CompletableFuture.runAsync(RunnableWrapper.of(() -> riskService.triggerRisk(RiskSceneEnum.USER_SIGN.getCode(), RiskTypeEnum.OFFLINE.getCode(), contract.getProjectOrderId()
			, RiskStandContext.builder().contractCode(contractCode).openId(headerParam.getOpenId()).customerPhone(signer.getPhone()).build(), headerParam.getOperatorUcId())));

		if (contractCodeList.size() > 1) {
			return contractMpService.getBatchContractSignUrl(contractCodeList, signerList, returnUrl);
		}

		// 解约协议团转非团场景拦截：合并发起的解约协议不能单独签署
		if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType())) {
			List<ContractRelation> relationList = contractRelationService.getRelationListByRelateContractCodes(Collections.singletonList(contractCode));
			if (CollectionUtils.isNotEmpty(relationList)) {
				List<String> relatedContractCodes = relationList.stream()
					.map(ContractRelation::getContractCode)
					.collect(Collectors.toList());
				List<Contract> pendingSignContracts = contractService.getListByContractCodesAndStatusAndTypes(
					relatedContractCodes,
					Collections.singletonList(ContractStatusEnum.PENDING_USER_SIGN.getCode()),
					Collections.singletonList(ContractTypeEnum.PACKAGE_FORMAL.getCode())
				);
				if (CollectionUtils.isNotEmpty(pendingSignContracts)) {
					throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "当前客源需要同步发起老客源解约及新客源正签，请使用一键签署功能");
				}
			}
		}

		if (ContractTypeEnum.getAuthSignContractTypes().contains(contract.getType())) {
			return accreditFetchAuthUrl(contract, returnUrl);
		} else {
			return commonFetchSignUrl(contract, signer, signerPhone, returnUrl);
		}
	}

	/**
	 * 授权协议书获取授权链接
	 *
	 * @param contract 授权协议合同信息
	 * @return 返回手签url信息
	 */
	private ContractSignUrlVo accreditFetchAuthUrl(Contract contract, String returnUrl) {
		// 获取授权协议书的法人
		ContractUser legalUser = contractUserService.getLatestUserByRole(contract.getContractCode(), RoleTypeEnum.LEGAL.getCode());
		// 获取授权协议书关联合同的签约人，主合同可能会有多个但是签约人都相同，选第一个即可，这个签约人就是授权协议的代理人
		Contract mainContract = contractService.getRelContractByAccreditContractCode(contract.getContractCode());
		if (mainContract == null) {
			LOGGER.error("授权协议书获取签署URL失败，未找到关联主合同,accreditContractCode：{}", contract.getContractCode());
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(),
				String.format("授权协议书获取签署URL失败，未找到关联主合同,accreditContractCode:%s", contract.getContractCode()), Level.ERROR);
		}
		ContractUser mainContractSignUser = contractUserService.getSignerByContractCode(mainContract.getContractCode());

		Map<String, String> fieldMap = contractFieldService.getFieldMap(contract.getContractCode());
		String companyName = fieldMap.get("companyName");
		String companyCreditCode = fieldMap.get("companyCreditCode");
		CertificateTypeEnum legalCertificateTypeEnum = CertificateTypeEnum.getEnumByCode(legalUser.getCertificateType());
		CertificateTypeEnum agentCertificateTypeEnum = CertificateTypeEnum.getEnumByCode(mainContractSignUser.getCertificateType());

		// 敏感数据解密
		List<String> cipherTextList = Stream.of(legalUser.getCertificateNo(), legalUser.getPhone(), mainContractSignUser.getCertificateNo())
			.distinct().collect(Collectors.toList());
		Map<String, String> plainTextMap = cipherService.decrypt(cipherTextList);
		String flowId = String.valueOf(IdGenerator.snowflakeId());

		SignResultVo signResultVo = contractSignResult(contract.getContractCode());
		if (SignResultEnum.SUCCESS.getCode().equals(signResultVo.getSignStatus())) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "已授权成功，请刷新页面", Level.WARN);
		}

		String companySignUrl = stringRedisTemplate.opsForValue().get(Constant.ACCREDIT_FETCH_AUTH_URL + contract.getContractCode());
		if (StringUtils.isBlank(companySignUrl)) {
			CompanySignParam param = new CompanySignParam();
			param.setInstanceId(contract.getPlatformInstanceId());
			param.setFlowId(flowId);
			param.setCompanyName(companyName);
			param.setCreditCode(companyCreditCode);
			param.setRoleTypeList(Collections.singletonList("signUser"));
			param.setLegalName(legalUser.getName());
			param.setLegalPhone(plainTextMap.get(legalUser.getPhone()));
			param.setLegalCardType(legalCertificateTypeEnum.getPlatformCode());
			param.setLegalCardCode(plainTextMap.get(legalUser.getCertificateNo()));
			param.setAgentName(mainContractSignUser.getName());
			param.setAgentCardType(agentCertificateTypeEnum.getPlatformCode());
			param.setAgentCardCode(plainTextMap.get(mainContractSignUser.getCertificateNo()));
			param.setReturnUrl(returnUrl);
			param.setIsShowHandwrittenTime(String.valueOf(1));
			companySignUrl = translateSignUrlForAccreditAuth(freeformService.getCompanySignUrl(param));
			// 缓存授权链接
			stringRedisTemplate.opsForValue().set(Constant.ACCREDIT_FETCH_AUTH_URL + contract.getContractCode(), companySignUrl, 50, TimeUnit.MINUTES);
			// 存储flowId
			contractFieldService.updateOrCreateFieldValue(contract.getContractCode(), "flowId", flowId);
		}

		ContractSignUrlVo result = new ContractSignUrlVo();
		result.setAuthCode(AuthCodeEnum.SUCCESS.getCode());
		result.setContractUrl(companySignUrl);
		return result;
	}

	/**
	 * 获取合同签署链接
	 *
	 * @param contract    合同信息
	 * @param signer      签约人
	 * @param signerPhone 签约手机号
	 * @param returnUrl   签署完成后跳转的页面
	 * @return 返回手签url信息
	 */
	private ContractSignUrlVo commonFetchSignUrl(Contract contract, ContractUser signer, String signerPhone, String returnUrl) {
		//校验签约信息
		ContractSignUrlVo contractSignUrlVo = checkSignInfo(Collections.singletonList(contract.getContractCode()), Collections.singletonList(signer));
		if (contractSignUrlVo != null) {
			return contractSignUrlVo;
		}
		String signUrlKey = Constant.SINGLE_SIGN_URL_PRE.concat(contract.getPlatformInstanceId() + "");
		//查询缓存
		String cacheData = stringRedisTemplate.opsForValue().get(signUrlKey);
		if (StringUtils.isNotBlank(cacheData)) {
			LOGGER.info("单个获取合同签署url命中缓存数据，signUrlKey：{}", signUrlKey);
			return ContractSignUrlVo.builder()
				.authCode(AuthCodeEnum.SUCCESS.getCode())
				.contractUrl(cacheData).build();
		}
		ContractField contractObjectTypeField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), ContractSignInfoReq.Fields.contractObjectType);
		//主体类型 1个人 2公对公
		Byte contractObjectType = contractObjectTypeField == null ? null : Byte.valueOf(contractObjectTypeField.getFieldValue());
		CertificateTypeEnum certificateTypeEnum = CertificateTypeEnum.getEnumByCode(signer.getCertificateType());
		String signerCertificateNo = cipherService.decrypt(signer.getCertificateNo());

		//注册个人信息
		registerUserSeal(signer.getName(), signerPhone, certificateTypeEnum.getPlatformCode(), signerCertificateNo);

		boolean addWaterMark = CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus());
		//获取手签url
		String url;
		try {
			//如果是公对公线上签约
			if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType()) && ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
				url = translateSignUrl(getCompanySignUrl(contract, signerPhone, certificateTypeEnum.getPlatformCode().intValue(), signerCertificateNo, returnUrl, addWaterMark));
			} else {
				String signRoleType = getSignRoleType(contract.getPlatformInstanceId());
				url = translateSignUrl(freeformService.getSignUrl(contract.getPlatformInstanceId(), signerPhone, certificateTypeEnum.getPlatformCode().intValue(), signerCertificateNo, returnUrl, addWaterMark, signRoleType));
			}
		} catch (Exception e) {
			contractLogService.createLog(contract.getContractCode(), LogTypeEnum.GET_SIGN_URL_ERROR.getCode(), LogTypeEnum.GET_SIGN_URL_ERROR.getName(), "", "", "用户");
			LOGGER.error("获取手签链接失败，contractCode:{},contractType:{},errorMessage:{}", contract.getContractCode(), contract.getType(), e.getMessage(), e);
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "获取手签失败，请稍后重试", Level.WARN);
		}
		stringRedisTemplate.opsForValue().set(signUrlKey, url, 1, TimeUnit.MINUTES);
		ContractSignUrlVo result = new ContractSignUrlVo();
		result.setAuthCode(AuthCodeEnum.SUCCESS.getCode());
		result.setContractUrl(url);
		return result;
	}

	/**
	 * 检查签约合同信息
	 */
	public ContractSignUrlVo checkSignInfo(List<String> contractCodeList, List<ContractUser> signerList) {
		if (CollectionUtils.isEmpty(signerList)) {
			throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "签约人信息不存在，请检查", Level.WARN);
		}
		if (signerList.stream().map(ContractUser::getPhone).collect(Collectors.toSet()).size() > 1) {
			throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "合同签署人不一致，请检查", Level.WARN);
		}

		ContractUser signer = signerList.get(0);
		boolean canUseFaceAuth = faceAuthService.canUseFaceAuth(contractCodeList, signer);
		if (canUseFaceAuth) {
			// 判断是否已认证通过
			String phone = signer.getPhone();
			String certificateNo = signer.getCertificateNo();
			boolean authedUser = contractUserService.getAuthedUser(phone, certificateNo);
			if (!authedUser) {
				ContractSignUrlVo result = new ContractSignUrlVo();
				result.setAuthCode(AuthCodeEnum.NOT_FACE_AUTH.getCode());
				result.setAuthErrorMsg("为保障签约流程安全，需要您完成实名认证。");
				return result;
			}
		} else {
			//查询实名认证信息
			UserInfo authUserInfo = userPlatformFeignService.getUserInfoByUcId(HeaderContext.getUserId());
			//实名结果校验
			if (Objects.isNull(authUserInfo) || AuthStatusEnum.INVALID.getCode().equals(authUserInfo.getStatus())) {
				ContractSignUrlVo result = new ContractSignUrlVo();
				result.setAuthCode(AuthCodeEnum.NOT_REAL_AUTH.getCode());
				result.setAuthErrorMsg("为保障签约流程安全，需要您完成实名认证。实名认证服务由家家支付提供，收集信息仅用于身份验证用途，将全程保障您的个人信息安全。");
				return result;
			}
			//校验实名认证类型
			CertificateTypeEnum certificateTypeEnum = CertificateTypeEnum.getEnumByCode(signer.getCertificateType());
			if (!Objects.equals(certificateTypeEnum.getRealNameCode(), authUserInfo.getIdType())) {
				ContractSignUrlVo result = new ContractSignUrlVo();
				result.setAuthCode(AuthCodeEnum.CERTIFICATE_TYPE_NOT_SAME.getCode());
				result.setAuthError(CertificateTypeNotSameError.builder()
					.authCertificateType(CertificateTypeEnum.getNameByRealNameCode(authUserInfo.getIdType()))
					.signerCertificateType(certificateTypeEnum.getName())
					.helpUrl(certificateTypeNotSameHelpUrl)
					.build());
				result.setAuthErrorMsg("请使用身份证或者护照进行实名认证-[签约]");
				return result;
			}

			//校验信息一致性
			if (!authUserInfo.getName().equals(signer.getName())) {
				String errorMsg = String.format("账号实名信息:%s\n签约人信息:%s\n两者姓名需一致，请用【%s】信息重新实名或设计师修改签约人为【%s】",
					authUserInfo.getName(),
					signer.getName(),
					signer.getName(),
					authUserInfo.getName());
				ContractSignUrlVo result = new ContractSignUrlVo();
				result.setAuthCode(AuthCodeEnum.USER_NAME_NOT_SAME.getCode());
				result.setAuthError(UserNameNotSameError.builder()
					.signerName(signer.getName())
					.authName(authUserInfo.getName())
					.helpUrl(userNameNotSameHelpUrl)
					.build());
				result.setAuthErrorMsg(errorMsg);
				return result;
			}

			String signerCertificateNo = cipherService.decrypt(signer.getCertificateNo());
			if (!ObjectUtil.equal(authUserInfo.getIdNumber(), signerCertificateNo)) {
				String signerIdNumber = signerCertificateNo.substring(signerCertificateNo.length() - 4);
				String authIdNumber = authUserInfo.getIdNumber().substring(authUserInfo.getIdNumber().length() - 4);
				String errorMsg = String.format("账号实名信息:证件号:****%s%n签约人信息:证件号:****%s%n两者证件号需一致，请用【%s】信息重新实名或设计师修改签约人为【%s】",
					authIdNumber, signerIdNumber, signerIdNumber, authIdNumber);
				ContractSignUrlVo result = new ContractSignUrlVo();
				result.setAuthCode(AuthCodeEnum.USER_ID_NUMBER_NOT_SAME.getCode());
				result.setAuthError(UserIdNumberNotSameError.builder()
					.helpUrl(userIdNumberNotSameHelpUrl)
					.authIdNumber(authIdNumber)
					.signerIdNumber(signerIdNumber)
					.build());
				result.setAuthErrorMsg(errorMsg);
				return result;
			}
		}

		return null;
	}

	/**
	 * 签约弹窗提示
	 */
	public Boolean contractSignTip(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract) || commonBusinessService.isPROCESS_V2_0_GROUP(contract.getProjectOrderId())) {
			return false;
		}
		List<Integer> popupOpenCitys = apolloConfigService.getPopupOpenCitys();
		if (CollectionUtils.isEmpty(popupOpenCitys) || !popupOpenCitys.contains(contract.getGbCode())) {
			return false;
		}

		//1.0不弹窗
		List<ProjectVersionDTO> projectVersionDTOS = projectInfoReadService.batchProjectVersion(Collections.singletonList(contract.getProjectOrderId()));
		if (CollectionUtils.isEmpty(projectVersionDTOS) || projectVersionDTOS.get(0).getProjectVersion().equals(ProjectVersionEnum.V1.getVersion())) {
			return false;
		}

		// 线上签约弹窗提醒
		CompletableFuture.runAsync(() -> {
			try {
				saveBusinessSnapshot(contract);
			} catch (Exception e) {
				LOGGER.error("线上签约弹窗提醒异常,Contract:{}", JSON.toJSONString(contract), e);
			}
		});
		return true;
	}

