	/**
	 * 获取公对公手签url
	 */
	private String getCompanySignUrl(Contract contract, String phone, Integer certificateType, String certificateNo, String returnUrl, Boolean addWaterMark) {
		ContractField companyCreditCodeField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), ContractSignInfoReq.Fields.companyCreditCode);
		if (companyCreditCodeField == null || StringUtils.isBlank(companyCreditCodeField.getFieldValue())) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "公对公合同公司信用代码不能为空");
		}
		if (StringUtils.isBlank(contract.getRelateContractCode())) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "公对公合同关联授权协议书为空");
		}
		ContractField companySignUrlField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), "companySignUrl");
		if (companySignUrlField != null) {
			long betweenMinute = DateUtil.between(companySignUrlField.getMtime(), new Date(), DateUnit.MINUTE);
			LOGGER.info("公对公合同法人授权签署署链接已获取分钟数，betweenMinute:{}", betweenMinute);
			if (betweenMinute > 7 * 24 * 60) {
				//如果公对公合同法人授权签署署链接已过期，则将授权链接字段删除，后面重新获取
				contractFieldService.deleteByContractCodeAndKeys(companySignUrlField.getContractCode(), Collections.singletonList("companySignUrl"));
				LOGGER.info("公对公合同法人授权签署链接已过期，重新获取,contractCode:{},companySignUrlFieldId:{}", contract.getContractCode(), companySignUrlField.getId());
			} else {
				return companySignUrlField.getFieldValue();
			}
		}
		ContractField flowIdField = contractFieldService.getByContractCodeAndKey(contract.getRelateContractCode(), "flowId");
		if (flowIdField == null || StringUtils.isBlank(flowIdField.getFieldValue())) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "公对公合同授权协议书流程id为空");
		}
		List<SealSigParameter> parameterList = new LinkedList<>();
		SealSigParameter parameter = new SealSigParameter();
		parameter.setRoleType("companySignUser");//待配置
		parameter.setSignType(SealTypeEnum.COMPANY.getName());
		parameter.setCodeType(SealCodeTypeEnum.CREDITCODE.getCodeType());
		//统一社会信用代码
		parameter.setCreditCode(companyCreditCodeField.getFieldValue());
		parameter.setSignatureType(String.valueOf(SignatureTypeEnum.CONTRACT.getType()));
		parameter.setCardType(certificateType);
		parameter.setCardCode(certificateNo);
		parameter.setFlowId(flowIdField.getFieldValue());
		parameterList.add(parameter);

		ManualSealCommonParameter param = new ManualSealCommonParameter();
		param.setInstanceId(contract.getPlatformInstanceId());
		param.setVcodeMobile(phone);
		param.setAddWaterMark(addWaterMark);
		param.setReturnUrl(returnUrl);
		param.setSealSigList(parameterList);
		param.setUseAgentSign(true);
		param.setAccreditOTU(false);//flowId可以重复使用
		param.setIsShowHandwrittenTime(String.valueOf(1));

		LOGGER.info("获取公对公手签url入参:{}", JsonUtil.toJsonString(param));
		long startTime = DateUtils.getCurrentTimeStamp();
		ResultWithTraceId<String> result = freeformApiFacade.fetchManualSignUrl(param);
		long endTime = DateUtils.getCurrentTimeStamp();
		LOGGER.info("获取公对公手签url请求协议平台耗时:getSignUrl, cost:{}", endTime - startTime);
		LOGGER.info("获取公对公获取手签url返回:{}", result);
		if (result.getCode() != 1) {
			LOGGER.error("获取公对公获取手签url失败，入参:{}, 返回值:{}", param, result);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取手签url失败");
		}
		String url = result.getResult().toString();
		//将获取到的url设置到合同字段中
		contractFieldService.updateOrCreateFieldValue(contract.getContractCode(), "companySignUrl", url);
		return url;
	}

