	 *
	 * @param contractCode 合同单号
	 * @param ucId         用户ucId
	 * @param returnUrl    实名之后回调的url
	 * @return
	 */
	public AuthUrlVo authUrl(@Nullable String contractCode, Long ucId, String returnUrl) {
		AuthUrlVo result = new AuthUrlVo();

		// 人脸识别
		if (StringUtils.isNotBlank(contractCode)) {
			List<String> contractCodeList = Arrays.asList(contractCode.split(","));
			List<ContractUser> signerList = contractUserService.getSignerByContractCodes(contractCodeList);
			ContractUser signer = signerList.get(0);
			boolean canUseFaceAuth = faceAuthService.canUseFaceAuth(contractCodeList, signer);
			if (canUseFaceAuth) {
				// 判断是否已认证通过
				String phone = signer.getPhone();
				String certificateNo = signer.getCertificateNo();
				String name = signer.getName();
				boolean authedUser = contractUserService.getAuthedUser(phone, certificateNo);
				if (authedUser) {
					throw new NrsBusinessException("您已完成实名认证，请勿重复操作", Level.WARN);
				} else {
					String faceAuthUrl = faceAuthService.getFaceAuthUrl(contractCode, name, certificateNo, phone, returnUrl);
