		result.setToken(authPrepareDTO.getToken());
		return result;
	}

	public SignResultVo contractSignResult(String contractCode) {
		SignResultVo result = SignResultVo.builder().signStatus(SignResultEnum.DOING.getCode()).build();
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同不存在，请检查合同编号或联系客服");
		}

		ContractUser signer = contractUserService.getSignerByContractCode(contractCode);
		if (!contract.getUserSignType().equals(UserSignTypeEnum.SIGN.getCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "查询签约结果失败，当前合同不需要签署-[签约]");
		}

		//查询contract自身存储的状态
		if (contract.getUserSignStatus().equals(CommonEnum.YES.getCode())) {
			result.setSignStatus(SignResultEnum.SUCCESS.getCode());
			return result;
		}

		if (!ContractStatusEnum.allowSignStatus.contains(contract.getStatus())) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "当前合同被撤回导致无法继续签约，请联系设计师重新发起签约", Level.WARN);
		}

		//调用协议平台查询结果
		String signResult;
		if (ContractTypeEnum.getAuthSignContractTypes().contains(contract.getType())) {
			signResult = getCompanyContractSignResult(contract);
			if (StringUtils.isBlank(signResult)) {
				return result;
			}
			contract.setUserSignStatus(CommonEnum.YES.getCode());
		} else {
			signResult = getContractSignResult(contract, signer);
			contract.setUserSignStatus(CommonEnum.YES.getCode());
		}

		if (Strings.isNullOrEmpty(signResult)) {
			result.setSignStatus(SignResultEnum.FAIL.getCode());
			return result;
		}
		String pdfUrl = s3Service.upload(signResult);
		//签署成功
		signSuccess(contract, signer, pdfUrl);
		result.setSignStatus(SignResultEnum.SUCCESS.getCode());
		return result;
	}

	/**
	 * 获取合同手签结果详情信息
	 */
	public ContractSignBaseInfoVo getContractSignBaseInfo(Long ucId, String contractCode) {
		//兼容合并签署
		List<String> contractCodeList = Arrays.asList(contractCode.split(","));
		String finalContractCode = contractCodeList.get(contractCodeList.size() - 1);
		ContractUser contractUser = contractUserService.getSignerByContractCode(finalContractCode);
		if (Objects.isNull(contractUser)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人-[签约]");
		}
		//加解密
		String contractUserPhone = cipherService.decrypt(contractUser.getPhone());
		//获取用户信息
		CUserDTO userDTO = userFeignService.getUserInfo(ucId.toString());
		String loginPhone = cipherService.decrypt(userDTO.getPhone());
		//校验登录人和签约人是否一致
		if (!loginPhone.equals(contractUserPhone)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "非签约人，无权限访问");
		}
		//获取合同详情
		List<Contract> contractList = contractService.getListByContractCodes(contractCodeList, false);
		Contract contract = contractList.stream()
			.filter(c -> c.getContractCode().equals(finalContractCode))
			.findFirst()
			.orElse(null);
		//获取项目信息
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(contract.getProjectOrderId());
		Integer contractTradeType = ContractTradeTypeEnum.PAY.getValue();
		BigDecimal contractAmount = null;
		Integer contractMode = commonContractService.getContractModeByContractCode(finalContractCode);
		//获取合同金额信息
		if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType())) {
			CancelOrderBaseInfoDTO lastRecordByProjectOrderId = cancelOrderService.getLastRecordByProjectOrderId(contract.getProjectOrderId());
			BigDecimal cancelAmount = ObjectUtil.isEmpty(lastRecordByProjectOrderId) ? BigDecimal.ZERO : lastRecordByProjectOrderId.getCancelOrderAmount();
			if (cancelAmount.compareTo(BigDecimal.ZERO) < 0) {
				contractTradeType = ContractTradeTypeEnum.REFUND.getValue();
				contractAmount = cancelAmount.abs().setScale(2, RoundingMode.HALF_UP);
			} else if (cancelAmount.compareTo(BigDecimal.ZERO) > 0) {
				contractAmount = cancelAmount.setScale(2, RoundingMode.HALF_UP);
			}
		} else if (ContractTypeEnum.ACCREDIT.getCode().equals(contract.getType()) || ContractTypeEnum.DRAWING.getCode().equals(contract.getType())) {
			contractAmount = null;
		} else {
			contractAmount = contract.getAmount().setScale(2, RoundingMode.HALF_UP);
		}
		List<ContractOnlineVo> contractOnlineVoList = new ArrayList<>();
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
		if (ContractTypeEnum.getRelateContractTypes().contains(contract.getType()) && processV25) {
			List<Byte> contractTypeList = new ArrayList<>(ContractTypeEnum.getRelateContractTypes());
			//获取线上合同url信息&关联合同线上url信息
			contractOnlineVoList = homeAndPcCommonService.getContractOnlineUrlForC(contract, contractTypeList);
		}
		//单独发起销售合同场景，返回所有当前项目在待签署的销售合同
		if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()) && homeAndPcCommonService.isMultipleQuotePersonalContract(contract)) {
			List<Contract> waitSignedPersonalContract = contractMpService.getPersonalContract(contract.getProjectOrderId(), HeaderContext.getUserId().toString(),ContractStatusEnum.validStatusWithoutDraft);
			contractOnlineVoList = coverContractListToContractOnlineVoList(waitSignedPersonalContract);
		}
		//获取主订单类型
		CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(contract.getProjectOrderId());

		return ContractSignBaseInfoVo.builder()
			.projectOrderId(contract.getProjectOrderId())
			.siteAddress(homeAndPcCommonService.getSafeAddress(projectInfoDTO))
			.type(contract.getType())
			.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
			.contractUrl(homeAndPcCommonService.getContractUrl(contract))
			.contractOnlineVoList(contractOnlineVoList)
			.contractTradeType(contractTradeType)
			.status(contract.getStatus())
			.allowJumpEscrowOpenAccount(buildJumpEscrowOpenAccount(contractList))
			.contractAmount(contractAmount)
			.contractMode(contractMode)
			.fundBaseInfoList(getSignFundBaseInfo(contractMode, contractCodeList, contract.getProjectOrderId()))
			.oneKeySignOpen(commonContractService.oneKeySignOpen(contract))
			.vipSchema("")
			.homeWorkflowType(ObjectUtil.isEmpty(coordinationProjectOrder) ? null : coordinationProjectOrder.getHomeWorkflowType())
			.build();
	}

	private boolean buildJumpEscrowOpenAccount(List<Contract> contractList) {
		Set<Byte> allowJumpEscrowOpen = new HashSet<>(ContractTypeEnum.allowJumpEscrowOpen());
		boolean supportContractType = contractList.stream().anyMatch(c -> allowJumpEscrowOpen.contains(c.getType()));
		if (!supportContractType) {
			return false;
		}
		String projectOrderId = contractList.get(0).getProjectOrderId();
		FundEscrowInfoDTO escrowInfoDTO = fundEscrowService.getFundEscrowEntryInfoByProjectOrderId(projectOrderId);
		return Optional.ofNullable(escrowInfoDTO)
			.filter(escrow -> FundEscrowStatusEnum.WAIT_OPEN_ACCOUNT.getCode().equals(escrow.getStatus()))
			.isPresent();
	}

	/**
	 * 获取签署完成款项金额列表,仅全案、批量签署返回
	 */
	private List<FundBaseInfo> getSignFundBaseInfo(Integer contractMode, List<String> contractCodeList, String projectOrderId) {
		if (CollectionUtils.isEmpty(contractCodeList)) {
			return new ArrayList<>();
		}
		//全案
		if (ContractModeEnum.FULL_SERVICE.getCode().equals(contractMode)) {
			return contractMpService.getFundBaseInfo(projectOrderId);
		}
		List<FundBaseInfo> fundBaseInfos = new ArrayList<>();
		//批量签署
		if (contractCodeList.size() > 1) {
			List<Contract> contractList = contractService.getListByContractCodes(contractCodeList, false);
			Contract formalContract = contractList.stream().filter(contract -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())).findFirst().orElse(null);
			Contract personalContract = contractList.stream().filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())).findFirst().orElse(null);
			if (formalContract != null) {
				fundBaseInfos.add(FundBaseInfo.builder()
					.fundName("工程款")
					.amount(formalContract.getAmount())
					.build());
			}
			if (personalContract != null) {
				BigDecimal personalContractAmount = contractList.stream().filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))
					.map(Contract::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
				fundBaseInfos.add(FundBaseInfo.builder()
					.fundName("其他款项（定软电等）")
					.amount(personalContractAmount)
					.build());
			}
		} else {
			//单个合同签署，只返回当前合同的金额信息
			Contract contract = contractService.getByContractCode(contractCodeList.get(0));
			if (contract == null) {
				return fundBaseInfos;
			}
			if (ContractTypeEnum.ADVANCE.getCode().equals(contract.getType())) {
				ContractField field = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), "expectContractAmount");
				fundBaseInfos.add(FundBaseInfo.builder()
					.fundName("首期款合同金额")
					.amount(contract.getAmount())
					.build());
				if (field != null) {
					fundBaseInfos.add(FundBaseInfo.builder()
						.fundName("预估合同金额")
						.amount(new BigDecimal(field.getFieldValue()))
						.build());
				}
			} else {
				fundBaseInfos.add(FundBaseInfo.builder()
					.fundName("合同金额")
					.amount(contract.getAmount())
					.build());
			}
		}
		return fundBaseInfos;
	}


	public void signSuccess(Contract contract, ContractUser signer, String pdfUrl) {
		contract.setUserSignedKey(pdfUrl);
		if (contract.getBusinessType().equals(BusinessTypeEnum.GROUP_DECORATE.getCode())
			&& ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())
			&& commonContractService.mergeLaunchContract(contract.getContractCode())) {
			//团装2.5&关联正签发起的销售合同，合同状态流转到待提交审核
			contract.setStatus(ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode());
		} else if (isFinishAfterSign(contract) || isFinishAfterChangeContractSign(contract)) {
			//合并发的合同，发起时已盖章，用户签署完成后合同状态设置为已签署
			contract.setStatus(ContractStatusEnum.FINISH.getCode());
			contract.setBothSignedKey(pdfUrl);
			LOGGER.info("签署完成，合同状态设置为完成,contractCode:{}", contract.getContractCode());
		} else if (AuditTypeEnum.AFTER.getCode().equals(contract.getAuditType())) {
			contract.setStatus(ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode());
		} else {
			contract.setStatus(ContractStatusEnum.PENDING_COMPANY_SIGN.getCode());
		}

		contractService.update(contract);


		String hidePhone = StrUtil.hide(signer.getPhone(), 0, signer.getPhone().length() - 4);
		//记录日志&发送消息
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.USER_SIGN.getCode(), LogTypeEnum.USER_SIGN.getName(), "", "", "用户".concat(hidePhone));
		contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.USER_SIGN.getCode());
		// 如果是授权协议书 则记录关联合同的授权节点
		if (ContractTypeEnum.ACCREDIT.getCode().equals(contract.getType()) && StringUtils.isNotBlank(contract.getRelateContractCode())) {
			contractNodeService.updateOrCreate(contract.getRelateContractCode(), NodeTypeEnum.AUTH.getCode());
		}

		String operatorUcId = HeaderContext.getContext().getOperatorUcId();
		String operatorName = "";
		try {
			if (StringUtils.isNotBlank(operatorUcId)) {
				UserInfo userInfo = userPlatformFeignService.getUserInfoByUcId(Long.valueOf(operatorUcId));
				operatorName = userInfo.getName();
			}
		} catch (Exception e) {
			LOGGER.info("查询用户姓名失败 operatorUcId:{}", operatorUcId);
		}

		eventService.publish(commonContractService.getContractEvent(contract, operatorUcId, operatorName), EventType.CONTRACT_USER_SIGN, contract.getContractCode());

		if (contract.getStatus().equals(ContractStatusEnum.FINISH.getCode())) {
			contractLogService.createLog(contract.getContractCode(), LogTypeEnum.FINISH.getCode(), LogTypeEnum.FINISH.getName());
			contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.FINISH.getCode());
			eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_FINISH, contract.getContractCode());
		}
	}

