	/**
	 * 正向签约合同是否签完合同直接结束
	 *
	 * @return
	 */
	private boolean isFinishAfterSign(Contract contract) {
		//不需要公司盖章的合同类型(图纸合同)
		if (ContractTypeEnum.noNeedCompanySignAfterType().contains(contract.getType())) {
			return true;
		}
		List<Byte> contractTypes = ContractTypeEnum.companySignAfterSubmitType();

		//个性化主材合同如果之前是协议确认的，用户签署完成后不直接完结
		if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			List<ContractNode> userConfirmNodeList = contractNodeService.getListByContractCodesAndType(Collections.singletonList(contract.getContractCode()), Collections.singletonList(NodeTypeEnum.USER_CONFIRM.getCode()));
			if (CollectionUtils.isNotEmpty(userConfirmNodeList)) {
				return false;
			}
		}
		//UserSignTypeEnum.SIGN.getCode().equals(contract.getUserSignType())
		//判断是否属于【提交合同后有盖章的合同类型】
		if (!contractTypes.contains(contract.getType())) {
			return false;
		}
		//属于【提交合同后有盖章的合同类型】&【是合并发起模式的合同】，由于发起时已盖章，用户签署完成直接结束
		return commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType()) && BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType());
	}

	/**
	 * 变更合同是否签完合同直接结束
	 *
	 * @param contract
	 * @return
	 */
	private boolean isFinishAfterChangeContractSign(Contract contract) {
		if (!ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType())) {
			return false;
		}
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType()) && BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType());
		if (!processV25) {
			return false;
		}
		//套餐变更协议只有施工图纸的时候,签完合同直接结束,不需要盖章
		ChangeContractFreeformDTO changeContractFreeformDTO = changeContractUnifyService.buildChangeContractFreeformDTO(contract.getContractCode(),
			contract.getProjectOrderId(),
			contract.getChangeOrderId(), true);
		ChangeContractFreeformDTO.DynamicChangeContent dynamicChangeContentDTO = JSON.parseObject(changeContractFreeformDTO.getDynamicChangeContent(),
			ChangeContractFreeformDTO.DynamicChangeContent.class);
		//报价、优惠、精装细则、甲供材料、内容都未变更，基础图纸存在值
		return CollectionUtils.isEmpty(dynamicChangeContentDTO.getBudgetUrl())
			&& dynamicChangeContentDTO.getIsChangeDiscount().equals(Boolean.FALSE)
			&& dynamicChangeContentDTO.getIsDecorateRuleUrl().equals(Boolean.FALSE)
			&& dynamicChangeContentDTO.getIsMaterialList().equals(Boolean.FALSE)
			&& CollectionUtils.isEmpty(dynamicChangeContentDTO.getChangeData())
			&& CollectionUtils.isNotEmpty(dynamicChangeContentDTO.getBaseConstructionDrawUrl());
	}

	/**
	 * 获取合同最新的pdf文件key
	 *
	 * @param contract
	 * @return
	 */
	public String getContractLatestPdfKey(Contract contract) {
		//线下签约不需要pdf
		if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
			return "";
		}
		//如果三方合同存在直接返回三方合同
		if (StringUtils.isNotBlank(contract.getThirdSignedKey())) {
			return contract.getThirdSignedKey();
		}
		return Strings.isNullOrEmpty(contract.getBothSignedKey())
			? (Strings.isNullOrEmpty(contract.getUserSignedKey()) ? contract.getPreviewKey() : contract.getUserSignedKey())
			: contract.getBothSignedKey();
	}

	/**
	 * @param confirmReq
	 * @return
	 * @desc C端用户合同确认
	 */
	public Boolean confirm(ConfirmReq confirmReq) {
		LOGGER.info("C端用户合同确认,请求参数:{}", JSON.toJSONString(confirmReq));
		Contract contractInfo = contractService.getByContractCode(confirmReq.getContractCode());
		if (Objects.isNull(contractInfo)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PERMISSION_DENIED, "该合同编号不存在");
		}

		if (ContractStatusEnum.USER_CONFIRMED.getCode().equals(contractInfo.getStatus())) {
			return true;
		}

		//待业主确认状态才可发送
		if (!contractInfo.getStatus().equals(ContractStatusEnum.PENDING_USER_CONFIRM.getCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PERMISSION_DENIED, "只有待业主确认状态才可以发起确认");
		}

		ContractUser contractUser = contractUserService.getSignerByContractCode(contractInfo.getContractCode());

		if (Objects.isNull(contractUser) || contractUser.getPhone().isEmpty()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人联系方式-[phone]");
		}
		//先进行状态设置，后再进行pdf生成，切勿移动代码顺序
		//加解密
		String customerPhone = cipherService.decrypt(contractUser.getPhone());
		verifyVCode(customerPhone, confirmReq.getSmsCode());
		contractInfo.setStatus(ContractStatusEnum.USER_CONFIRMED.getCode());
		contractInfo.setUserConfirmStatus(CommonEnum.YES.getCode());
		contractInfo.setUserQueryStatus(CommonEnum.YES.getCode());
		Long userConfirmTime = System.currentTimeMillis();
		//协议确认类加水印
		if (contractInfo.getUserSignType().equals(UserSignTypeEnum.CONFIRM.getCode())) {
			String userConfirmTimeStr = DateUtils.getFormatDateStr(new Date(userConfirmTime), DateUtils.DATE_TIME);
			String markText = String.format("本内容于%s以数据电文方式经客户确认予以生效。如客户需要签章的，可对本内容予以再次确认，生效时间仍以数据电文确认时间为准。", userConfirmTimeStr);
			FormInstanceDto param = freeformApiFacade.getFormInstance(contractInfo.getPlatformInstanceId());
			generatePdfAddWaterMark(contractInfo, param.getCformData(), true, markText);
		}
		contractService.update(contractInfo);
		contractLogService.createLog(contractInfo.getContractCode(), LogTypeEnum.USER_CONFIRM.getCode(), LogTypeEnum.USER_CONFIRM.getName(), "", "", "用户");
		contractNodeService.updateOrCreate(contractInfo.getContractCode(), NodeTypeEnum.USER_CONFIRM.getCode(), userConfirmTime);
		String operatorUcId = HeaderContext.getContext().getOperatorUcId();
		String operatorName = "";
		try {
			if (StringUtils.isNotBlank(operatorUcId)) {
				UserInfo userInfo = userPlatformFeignService.getUserInfoByUcId(Long.valueOf(operatorUcId));
				operatorName = userInfo.getName();
			}
		} catch (Exception e) {
			LOGGER.info("查询用户姓名失败 operatorUcId:{}", operatorUcId);
		}
		eventService.publish(commonContractService.getContractEvent(contractInfo, operatorUcId, operatorName), EventType.CONTRACT_USER_CONFIRM, contractInfo.getContractCode());

		//触发风控
		HeaderParam headerParam = HeaderContext.getContext();
		CompletableFuture.runAsync(RunnableWrapper.of(() -> riskService.triggerRisk(RiskSceneEnum.USER_SIGN.getCode(), RiskTypeEnum.OFFLINE.getCode(), contractInfo.getProjectOrderId()
			, RiskStandContext.builder().contractCode(contractInfo.getContractCode()).customerPhone(contractUser.getPhone()).openId(headerParam.getOpenId()).build(), headerParam.getOperatorUcId())));
		return true;
	}

	public void verifyVCode(String phone, String verfiyCode) {
		if (KeUtils.isTestEnvironment() && "123456".equals(verfiyCode)) {
			return;
		}
		String key = Constant.VCODE_PREFIX + phone;
		String vCode = redisTemplate.opsForValue().get(key);
		if (StringUtils.isBlank(vCode)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请重新获取验证码");
		}

		if (!verfiyCode.equals(vCode)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "验证码错误");
		}
	}

