	/**
	 * 同步公司盖章
	 */
	public Boolean companySealSync(Contract contract) {
		RLock lock = redissonClient.getLock("contract_company_seal:" + contract.getContractCode());
		try {
			if (!lock.tryLock(0L, 30L, TimeUnit.SECONDS)) {
				LOGGER.info("盖公司章，抢占锁未成功: {}", contract.getContractCode());
				return false;
			}
		} catch (Exception e) {
			LOGGER.info("盖公司章，抢占锁未成功: {}", contract.getContractCode(), e);
			return false;
		}

		ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfig(contract);
		if (Objects.isNull(config)) {
			lock.unlock();
			contractLogService.createLog(contract.getContractCode(), LogTypeEnum.COMPANY_SIGN_FAIL.getCode(), "盖章失败，缺少公司章信息");
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "盖公司章失败，缺少公司章配置信息-[签约]");
		}

		boolean addWaterMark = CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus());
		try {

			List<ContractCompany> companyListByCode = contractCompanyService.getCompanyListByCode(contract.getContractCode());
			String pdfUrl;
			if (CollectionUtils.isEmpty(companyListByCode)) {
				pdfUrl = freeformService.companySeal(contract.getPlatformInstanceId(), config.getSealCode(), Long.valueOf(contract.getCreateUserId()), addWaterMark, SignatureTypeEnum.CONTRACT.getType());
			} else {
				pdfUrl = freeformService.multiCompanySeal(contract.getPlatformInstanceId(), companyListByCode, Long.valueOf(contract.getCreateUserId()), addWaterMark, contract.getType());
			}

			String fileKey = s3Service.upload(pdfUrl);
			contract.setBothSignedKey(fileKey);
			contract.setStatus(computeStatusAfterCompanySeal(contract));
			contract.setUserQueryStatus(UserQueryStatusEnum.VALID.getCode());
		} catch (Exception e) {
			lock.unlock();
			//重新获取合同状态，如果已经不是待盖公司章状态，则无需记录失败日志
			if (!ContractStatusEnum.PENDING_COMPANY_SIGN.getCode().equals(contractService.getByContractCode(contract.getContractCode()).getStatus())) {
				LOGGER.info("当前合同状态已不是待盖公司章，无需记录失败记录，contractCode:{}", contract.getContractCode());
				return false;
			}
			contractLogService.createLog(contract.getContractCode(), LogTypeEnum.COMPANY_SIGN_FAIL.getCode(), "合同较大盖公司章失败，系统自动重试中，预计5-10分钟可盖完");
			LOGGER.info("盖公司章失败，协议平台盖章or上传s3失败-[签约],{},{}", contract.getContractCode(), ExceptionUtils.getStackTrace(e));
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "盖公司章失败，协议平台盖章or上传s3失败-[签约]");
		}
		//更新合同信息前再次查询合同信息，检查合同当前状态是否还是待盖公司章，如果不是，则不更新合同信息
		if (!ContractStatusEnum.PENDING_COMPANY_SIGN.getCode().equals(contractService.getByContractCode(contract.getContractCode()).getStatus())) {
			LOGGER.info("当前合同状态已不是待盖公司章，不更新合同信息，contractCode:{}", contract.getContractCode());
			return false;
		}
		contractService.update(contract);

		// 更新主体盖章信息
		List<ContractCompany> contractCompanyList = contractCompanyService.getCompanyListByCode(contract.getContractCode());
		if (CollectionUtils.isNotEmpty(contractCompanyList)) {
			List<Long> ids = contractCompanyList.stream()
				.filter(contractCompany -> SealStatusEnum.WAIT_SEAL.getCode().equals(contractCompany.getSealStatus()))
				.map(ContractCompany::getId)
				.collect(Collectors.toList());

			contractCompanyService.updateSealStatus(ids, SealStatusEnum.SUCCESS.getCode());
		}

		//记录日志&时间&消息
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.COMPANY_SIGN.getCode(), LogTypeEnum.COMPANY_SIGN.getName(), "", "", "系统");
		contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.COMPANY_SIGN.getCode());
		eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_COMPANY_SIGN, contract.getContractCode());

		if (contract.getStatus().equals(ContractStatusEnum.FINISH.getCode())) {
			contractLogService.createLog(contract.getContractCode(), LogTypeEnum.FINISH.getCode(), LogTypeEnum.FINISH.getName());
			contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.FINISH.getCode());
			eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_FINISH, contract.getContractCode());
		}
		lock.unlock();
		return true;
	}

	/**
	 * 异步公司盖章
	 */
	public Boolean companySealAsync(Contract contract) {
		LOGGER.info("公司盖章,合同信息:{}", JSON.toJSONString(contract));
		RLock lock = lockService.lockElseThrow("contract_company_seal:" + contract.getContractCode(), 10000);

		// 先查询是否已经申请盖章
		CompanySealAsyncResultDTO companySealAsyncResultDTO = contractRedisService.getCompanySealResult(contract.getContractCode());
		if (companySealAsyncResultDTO != null && contract.getPlatformInstanceId().equals(companySealAsyncResultDTO.getInstanceId())) {
			// 判断下时间 如果盖章太久未回调就报警(10min)
			if (System.currentTimeMillis() - companySealAsyncResultDTO.getApplySealTime() > 600000) {
				LOGGER.error("公司盖章超时,合同信息:{}", JSON.toJSONString(contract));
			}

			// 主动查询盖章结果补偿
			String companySealUrl = freeformService.queryContractSealResult(contract.getPlatformInstanceId(), companySealAsyncResultDTO.getFreeFormQueryKey());
			if (StringUtils.isNotBlank(companySealUrl)) {
				updateCompanySealResult(contract);
				return true;
			}

			lock.unlock();
			LOGGER.info("已经申请盖章，不再重复申请,{}", contract.getContractCode());
			return true;
		}

		ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfig(contract);
		if (Objects.isNull(config)) {
			lock.unlock();
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "盖公司章失败，缺少公司章配置信息-[签约]");
		}

		boolean addWaterMark = CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus());

		List<ContractCompany> companyListByCode = contractCompanyService.getCompanyListByCode(contract.getContractCode());
		Long freeFormQueryKey;
		if (CollectionUtils.isEmpty(companyListByCode)) {
			freeFormQueryKey = freeformService.companySealAsync(contract.getPlatformInstanceId(), config.getSealCode(),
				Long.valueOf(contract.getCreateUserId()), addWaterMark, SignatureTypeEnum.CONTRACT.getType());
		} else {
			freeFormQueryKey = freeformService.multiCompanySealAsync(contract.getPlatformInstanceId(), companyListByCode,
				Long.valueOf(contract.getCreateUserId()), addWaterMark, contract.getType());
		}

		companySealAsyncResultDTO = CompanySealAsyncResultDTO.builder()
			.instanceId(contract.getPlatformInstanceId())
			.freeFormQueryKey(freeFormQueryKey)
			.applySealTime(System.currentTimeMillis())
			.role(KeUtils.getSwimLane().orElse(null))
			.build();
		contractRedisService.saveCompanySealResult(contract.getContractCode(), companySealAsyncResultDTO);

		lock.unlock();
		return true;
	}

	/**
	 * 更新盖章结果
	 */
	public void updateCompanySealResult(Contract contract) {
		// 如果状态不是待盖公司章则不处理
		if (!ContractStatusEnum.PENDING_COMPANY_SIGN.getCode().equals(contract.getStatus())) {
			LOGGER.info("更新盖章结果，合同状态不是待盖公司章不处理");
			return;
		}

		// 请求协议平台查询盖章结果
		CompanySealAsyncResultDTO companySealAsyncResultDTO = contractRedisService.getCompanySealResult(contract.getContractCode());
		String companySealUrl = freeformService.queryContractSealResult(contract.getPlatformInstanceId(), companySealAsyncResultDTO.getFreeFormQueryKey());

		if (StringUtils.isBlank(companySealUrl)) {
			throw new NrsBusinessException("获取查询异步盖章结果失败");
		}
		String fileKey = s3Service.upload(companySealUrl);
		//更新数据
		((ContractBusinessService) AopContext.currentProxy()).updateCompanySealResultDB(contract, fileKey);
	}

	@Transactional
	public void updateCompanySealResultDB(Contract contract, String fileKey) {
		contract.setBothSignedKey(fileKey);
		contract.setStatus(computeStatusAfterCompanySeal(contract));
		contract.setUserQueryStatus(UserQueryStatusEnum.VALID.getCode());
		contractService.update(contract);

		// 更新主体盖章信息
		List<ContractCompany> contractCompanyList = contractCompanyService.getCompanyListByCode(contract.getContractCode());
		if (CollectionUtils.isNotEmpty(contractCompanyList)) {
			List<Long> ids = contractCompanyList.stream()
				.filter(contractCompany -> SealStatusEnum.WAIT_SEAL.getCode().equals(contractCompany.getSealStatus()))
				.map(ContractCompany::getId)
				.collect(Collectors.toList());

			contractCompanyService.updateSealStatus(ids, SealStatusEnum.SUCCESS.getCode());
		}


		contractRedisService.removeCompanySealResult(contract.getContractCode());

		//记录日志&时间&消息
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.COMPANY_SIGN.getCode(), LogTypeEnum.COMPANY_SIGN.getName(), "", "", "系统");
		contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.COMPANY_SIGN.getCode());
		eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_COMPANY_SIGN, contract.getContractCode());

		if (contract.getStatus().equals(ContractStatusEnum.FINISH.getCode())) {
			contractLogService.createLog(contract.getContractCode(), LogTypeEnum.FINISH.getCode(), LogTypeEnum.FINISH.getName());
			contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.FINISH.getCode());
			eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_FINISH, contract.getContractCode());
		}
		LOGGER.info("异步盖章结果数据更新完成，contractCode:{}", contract.getContractCode());
	}


	/**
	 * 计算盖章完成后的合同状态
	 */
	private Integer computeStatusAfterCompanySeal(Contract contract) {
		// 三方盖章的合同状态为待三方盖章
		if (ContractTypeEnum.NEED_THIRD_PARTY_SEAL_LIST.contains(contract.getType())) {
			return ContractStatusEnum.PENDING_THIRD_PARTY_SEAL.getCode();
		}
		// 不是2.5版本的合同，盖章后状态为已签署
		boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType()) && BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType());
		if (!houseProcessV25) {
			return ContractStatusEnum.FINISH.getCode();
		}

		//个性化主材合同如果之前是协议确认的，通过申请用章的方式后面流转到待盖章，盖章完成后流转到完结态
		if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			List<ContractNode> userConfirmNodeList = contractNodeService.getListByContractCodesAndType(Collections.singletonList(contract.getContractCode()), Collections.singletonList(NodeTypeEnum.USER_CONFIRM.getCode()));
			if (CollectionUtils.isNotEmpty(userConfirmNodeList)) {
				return ContractStatusEnum.FINISH.getCode();
			}
		}

		//合同提交后就盖章的，协议确认盖章后状态为待确认 盖章完后的状态为待签署
		if (ContractTypeEnum.companySignAfterSubmitType().contains(contract.getType())) {
			if (UserSignTypeEnum.CONFIRM.getCode().equals(contract.getUserSignType())) {
				return ContractStatusEnum.PENDING_USER_CONFIRM.getCode();
			}
			return ContractStatusEnum.PENDING_USER_SIGN.getCode();
		}
		return ContractStatusEnum.FINISH.getCode();
	}


	/**
	 * 注册个人章
	 *
	 * @param contractCode
	 */
	public void registerSignUser(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract)) {
			return;
		}

		ContractUser signer = contractUserService.getSignerByContractCode(contractCode);
		if (Objects.isNull(signer) || StringUtils.isBlank(signer.getCertificateNo()) || StringUtils.isBlank(signer.getPhone()) || StringUtils.isBlank(signer.getName())) {
			return;
		}

		CertificateTypeEnum certificateTypeEnum = CertificateTypeEnum.getEnumByCode(signer.getCertificateType());
		if (Objects.isNull(certificateTypeEnum)) {
			return;
		}

		//提前注册个人章，报错的话，也不用管，真正签署的时候，会再注册一遍
		try {
			// 加解密
			String singerPhone = cipherService.decrypt(signer.getPhone());
			String singerCertificateNo = cipherService.decrypt(signer.getCertificateNo());
			registerUserSeal(signer.getName(), singerPhone, certificateTypeEnum.getPlatformCode(), singerCertificateNo);
		} catch (Exception ignore) {
		}
	}

