	public String generatePdf(Contract contract, Map<String, Object> formData) {
		ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfigByContractType(contract);
		if (Objects.isNull(config) || Objects.isNull(config.getFormId()) || Objects.isNull(config.getFormKey())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同配置缺少对应的协议平台板式key/id");
		}

		LOGGER.info("生成pdf入参:{} {}", contract.getContractNo(), JsonUtil.toJsonString(formData));

		String formKey = config.getFormKey();
		Integer formId = config.getFormId();
		Long createUserId = Long.valueOf(contract.getCreateUserId());

		if (StringUtils.isBlank(contract.getContractNo())) {
			contract.setContractNo(RandomCodeUtils.generateContractNo());
		}

		//创建实例
		contract.setPlatformInstanceId(freeformService.createInstance(formKey, createUserId));
		//提交表单
		freeformService.submit(contract.getPlatformInstanceId(), contract.getContractNo(), createUserId, formData);
		Boolean addWaterMark = false;
		String markText = "";
		//生成pdf
		AttachmentInfo pdfInfo = freeformService.createPdf(contract.getPlatformInstanceId(), createUserId, formId.longValue(), null, addWaterMark, markText);
		contract.setPreviewKey(s3Service.upload(pdfInfo.getUrl()));
		contract.setPdfPageCount(pdfInfo.getPdfPageCount());

		LOGGER.info("生成pdf结果:{}", pdfInfo.getUrl());

		return s3Service.generateUrl(contract.getPreviewKey(), 1800);
	}


