	/**
	 * 获取优惠列表 - 有顺序-礼品赠送 > 其他
	 *
	 * @param planAllDTO
	 * @return
	 */
	public List<String> getCouponRemarkList(PlanAllDTO planAllDTO) {
		List<String> couponRemarkList = new LinkedList<>();
		List<String> giftCouponRemarkList = new LinkedList<>();
		List<String> otherCouponRemarkList = new LinkedList<>();
		List<String> materialCouponRemarkList = new LinkedList<>();
		String packageCouponContent = null;

		if (CollectionUtils.isNotEmpty(planAllDTO.getCouponList())) {
			for (CouponDTO couponDTO : planAllDTO.getCouponList()) {
				if (CouponTypeEnum.GIFT_COUPON.getCode().equals(couponDTO.getCouponType())) {
					giftCouponRemarkList.add(couponDTO.getRemark());
				} else if (CouponTypeEnum.OTHER_COUPON.getCode().equals(couponDTO.getCouponType())) {
					otherCouponRemarkList.add(couponDTO.getRemark());
				} else if (CouponTypeEnum.TICKET_PACKAGE_COUPON.getCode().equals(couponDTO.getCouponType())) {
					packageCouponContent = Optional.ofNullable(couponDTO.getPackageDTO()).map(TicketPackageConfigDTO::getPackageContent).orElse(null);
				} else if (CouponTypeEnum.MATERIAL_UPGRADE_COUPON.getCode().equals(couponDTO.getCouponType())) {
					materialCouponRemarkList.add(couponDTO.getRemark());
				}
			}
		}

		//顺序券包内容>礼品赠送>材料升级>其他优惠
		int i = 1;
		if (StringUtils.isNotBlank(packageCouponContent)) {
			couponRemarkList.add(String.format("%d、%s", i++, packageCouponContent));
		}
		for (String remark : giftCouponRemarkList) {
			couponRemarkList.add(String.format("%d、%s", i++, remark));
		}
		for (String remark : materialCouponRemarkList) {
			couponRemarkList.add(String.format("%d、%s", i++, remark));
		}
		for (String remark : otherCouponRemarkList) {
			couponRemarkList.add(String.format("%d、%s", i++, remark));
		}

		return couponRemarkList;
	}

