	/**
	 * 处理合同最新的pdf到图片
	 *
	 * @param contractCode
	 */
	public void contractPdfToImage(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract)) {
			return;
		}
		if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			return;
		}

		//只处理线上的合同
		if (!SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
			return;
		}

		RLock lock = redissonClient.getLock("dela_contract_pdf_to_image:" + contract.getContractCode());
		try {
			if (!lock.tryLock(0L, 120L, TimeUnit.SECONDS)) {
				LOGGER.info("合同pdf转图片，抢占锁未成功: {}", contract.getContractCode());
				return;
			}
		} catch (Exception e) {
			LOGGER.info("合同pdf转图片，抢占锁未成功: {}", contract.getContractCode());
			return;
		}

		try {
			String latestPdfKey = getContractLatestPdfKey(contract);
			dealContractPdfToImage(latestPdfKey);
		} catch (Exception e) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "转换pdf失败" + e.getMessage());
		} finally {
			lock.unlock();
		}
	}

	/**
	 * 处理pdfKey 到图片
	 *
	 * @param pdfKey
	 */
	private void dealContractPdfToImage(String pdfKey) {
		//不存在pdfKey，不处理
		if (StringUtils.isBlank(pdfKey)) {
			return;
		}
		String pdfUrl = s3Service.generateUrl(pdfKey, 3600);
		List<String> imageFileKeys;
		//临时开关，上线后无问题删除
		if (contractApolloConfig.getPdfToImageUseNew()) {
			imageFileKeys = pdfToImageService.pdf2ImageOptimized(pdfUrl);
		} else {
			imageFileKeys = pdfToImageService.pdf2ImageParallel(pdfUrl);
		}
		//先删除之前pdfKey到图片的结果
		contractPdfImageService.deleteImagesByPdfKey(pdfKey);

		for (int i = 0; i < imageFileKeys.size(); i++) {
			contractPdfImageService.create(pdfKey, i + 1, imageFileKeys.get(i));
		}
	}

	/**
	 * 初始化pdf页数
	 *
	 * @param contractCode
	 */
	public void initContractPdfCount(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract)) {
			return;
		}
		if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			return;
		}

		//只处理线上的合同
		if (!SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
			return;
		}

		String latestPdfKey = getContractLatestPdfKey(contract);
		String pdfUrl = s3Service.generateUrl(latestPdfKey, 3600);

		try {
			byte[] fileContent = pdfToImageService.read(pdfUrl);
			PDDocument document = PDDocument.load(fileContent);
			contract.setPdfPageCount(document.getNumberOfPages());
			contractService.update(contract);
		} catch (IOException e) {
			LOGGER.error("初始化PDF页数，读取文件失败" + contractCode);
		}
	}

