	/**
	 * 档案袋获取所有用户已经签署的合同
	 * 需支持展示全量类型合同,仅合同签约人能查看到对应合同
	 * 合同状态均为签署完成的合同
	 *
	 * @param ucId
	 * @param projectOrderId
	 * @return
	 */
	public FileFolderSignedContractDTO getUserSignedContractList(Long ucId, String projectOrderId) {
		FileFolderSignedContractDTO result = FileFolderSignedContractDTO.builder()
			.title("装修合同")
			.list(new ArrayList<>())
			.build();
		//获取当前用户的所有合同
		CUserDTO userDTO = userFeignService.getUserInfo(ucId.toString());
		String phone = cipherService.decrypt(userDTO.getPhone());
		List<String> contractCodeList = contractUserService.getContractCodeListBySignerPhone(cipherService.encrypt(phone));
		// 获取合同列表中所有纯零售的合同
		List<String> retailContractCodeList = getRetailContractList(contractCodeList);
		if (CollectionUtil.isEmpty(contractCodeList)) {
			return result;
		}
		//获取当前项目的合同
		List<String> contractCodesByProjectOrderId = contractService.getContractList(projectOrderId).stream().map(Contract::getContractCode).collect(Collectors.toList());
		contractCodeList.retainAll(contractCodesByProjectOrderId);
		//补充纯零售合同
		contractCodeList.addAll(retailContractCodeList);
		//获取所有已签署的合同
		List<Contract> contractList = contractService.getListByContractCodesAndStatus(contractCodeList, ContractStatusEnum.SIGNED_STATUS_LIST);
		if (CollectionUtil.isEmpty(contractList)) {
			return result;
		}
		//组装返回值
		List<FileFolderSignedContractDTO.Contract> list = new ArrayList<>();
		for (Contract contract : contractList) {
			String fileType = "";
			List<String> schema = new ArrayList<>();
			if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
				String onlineUrl = s3Service.generateUrl(getContractLatestPdfKey(contract), 1800);
				//线上签署，不生成PDF的无协议变更，不展示
				if (StringUtils.isBlank(onlineUrl)) {
					continue;
				} else {
					fileType = "pdf";
					schema.add(onlineUrl);
				}
			} else {
				//线下合同可能有多个图片/PDF
				List<ContractAttach> attachList = contractAttachService.getListByContractCode(contract.getContractCode(), AttachTypeEnum.OFFLINE_CONTRACT.getCode());
				fileType = getAttachFileKey(attachList.get(0).getUrl());
				schema = attachList.stream().map(ContractAttach::getUrl).collect(Collectors.toList());
			}
			FileFolderSignedContractDTO.Contract resContract = FileFolderSignedContractDTO.Contract.builder()
				.contractCode(contract.getContractCode())
				.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
				.type(contract.getType())
				.finishTime(getUserSignTime(contract.getContractCode()) == null ? null : DateUtils.getDateStr(getUserSignTime(contract.getContractCode())))
				.previewUrl(ContractTypeEnum.getCoverImageByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
				.fileType(fileType)
				.schema(schema)
				.build();
			list.add(resContract);
		}
		result.setList(list);
		return result;
	}

	/**
	 * 获取合同中纯零售的合同
	 *
	 * @param contractCodeList
	 * @return
	 */
	public List<String> getRetailContractList(List<String> contractCodeList) {
		//兼容合同量特别大的场景
		List<Contract> contractList = contractService.getListByContractCodesAndStatus(contractCodeList, ContractStatusEnum.inPositiveStatus);
		if (CollectionUtil.isEmpty(contractList)) {
			return new ArrayList<>();
		}
		contractList = contractList.subList(0, Math.min(contractList.size(), 100));
		List<String> retailContractCodeList = new ArrayList<>();
		List<String> projectOrderIdList = contractList.stream().map(Contract::getProjectOrderId).collect(Collectors.toList());
		Map<String, CoordinationProjectInfo> coordinationProjectInfoMap = commonBusinessService.batchCoordinationProjectOrder(projectOrderIdList);

		for (Contract contract : contractList) {
			CoordinationProjectInfo coordinationProjectInfo = coordinationProjectInfoMap.get(contract.getProjectOrderId());
			if (ObjectUtil.isNotEmpty(coordinationProjectInfo) && HomeWorkflowTypeEnum.RETAIL.getType().equals(coordinationProjectInfo.getHomeWorkflowType())) {
				// 纯零售项目默认展示
				retailContractCodeList.add(contract.getContractCode());
			}
		}
		return retailContractCodeList;
	}


	public boolean checkCompanyInfo(String companyName, String companyCreditCode, String legalName, Byte signChannelType) {
		if ("北区测试公司".equals(companyName) || Boolean.FALSE.equals(contractApolloConfig.getCompanyInfoCheck())) {
			return true;
		}
		CompanyBaseInfoResDTO companyBaseInfo = commonBusinessService.getCompanyBaseInfo(companyName);

		if (companyBaseInfo == null) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "根据统一社会信用代码未查询到公司信息，请重新核对信息");
		}

		if (!companyName.equals(companyBaseInfo.getCompanyName()) || !companyCreditCode.equals(companyBaseInfo.getTaxNumber())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "企业名称与统一社会信用代码无法匹配，请修改");
		}

		//对公合同&线上签署校验：法定代表人姓名与企业名称是否匹配
		if (SignChannelTypeEnum.ONLINE.getCode().equals(signChannelType) && !Objects.equals(legalName, companyBaseInfo.getLegalName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "企业名称与法定代表人姓名无法匹配，请修改");
		}

		return true;
	}

	/**
	 * 计算组的总体签署状态
	 */
	public Integer computeGroupSignStatus(List<Contract> contractList, List<Byte> groupTypeList, Boolean mergeLaunchDesignContract) {
		contractList = contractList.stream().filter(contract -> ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus())).filter(m -> {
			if (ContractTypeEnum.PERSONAL.getCode().equals(m.getType())) {
				return !homeAndPcCommonService.isMultipleQuotePersonalContract(m) && ObjectUtil.isEmpty(m.getChangeOrderId());
			} else if (ContractTypeEnum.DESIGN.getCode().equals(m.getType())) {
				return mergeLaunchDesignContract;
			}
			return true;
		}).collect(Collectors.toList());
		for (Byte type : groupTypeList) {
			Contract contract = contractList.stream().filter(item -> type.equals(item.getType())).findFirst().orElse(null);
			if (contract == null) {
				continue;
			}
			if (!ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
				return contract.getStatus();
			}
		}
		return ContractStatusEnum.FINISH.getCode();
	}


	/**
	 * 根据合同code获取所有关联的合同列表，包含自己
	 * 举例：
	 * 如果是正签合同，返回正签合同和正签合同合并发起的其他合同(图纸合同、销售合同等)
	 * 如果是图纸合同，返回正签合同和销售合同(如有)
	 *
	 * @param contractCode
	 * @return
	 */
	public List<Contract> getRelationContract(String contractCode) {
		Set<String> contractCodeList = new HashSet<>();
		//以主合同获取关联合同
		contractCodeList.addAll(getRelationContractCodeByContractCode(contractCode));
		//以从合同获取关联合同
		contractCodeList.addAll(getRelationContractCodeByRelationContractCode(contractCode));
		if (org.springframework.util.CollectionUtils.isEmpty(contractCodeList)) {
			return new ArrayList<>();
		}
		return contractService.getListByContractCodes(new ArrayList<>(contractCodeList), false);
	}

