	/**
	 * 解约协议获取最新正向合同的信息
	 *
	 * @param projectOrderId  项目订单ID
	 * @param isIncludeChange 是否包含变更合同
	 * @return
	 */
	public Contract getTerminalUseContractInfo(String projectOrderId, boolean isIncludeChange) {
		// 获取符合签署状态的合同
		List<Contract> contractList = contractService.getContractList(projectOrderId).stream()
			.filter(item -> ContractStatusEnum.personalFinishSignStatus.contains(item.getStatus()))
			.collect(Collectors.toList());
		// 根据是否包含变更合同进行过滤
		contractList = isIncludeChange ? contractList : contractList.stream().filter(item -> !Objects.equals(item.getType(), ContractTypeEnum.PACKAGE_CHANGE.getCode())).collect(Collectors.toList());
		// 将合同按类型存入 Map
		Map<Byte, Contract> contractMap = contractList.stream()
			.collect(Collectors.toMap(Contract::getType, Function.identity(), (a, b) -> a));

		// 按优先级依次获取合同
		return Optional.ofNullable(contractMap.get(ContractTypeEnum.PACKAGE_CHANGE.getCode()))
			.orElseGet(() -> Optional.ofNullable(contractMap.get(ContractTypeEnum.PACKAGE_FORMAL.getCode()))
				.orElse(contractMap.get(ContractTypeEnum.ADVANCE.getCode())));
	}

	/**
	 * 判断是否需要发起关联订单的解约协议
	 * 1.获取上一个订单号
	 * 2.获取上一个订单号的解约协议合同列表
	 * 3.如果不存在有效的解约协议，则需要发起解约协议
	 *
	 * @param projectOrderId 项目订单ID
	 * @return 是否需要发起解约协议
	 */
	public boolean needLaunchRelationTerminalContract(String projectOrderId) {
		String previousOrderNo = commonBusinessService.getPreviousOrderNo(projectOrderId);
		if (StringUtils.isBlank(previousOrderNo)) {
			return Boolean.FALSE;
		}
		//获取上一个订单的正签合同，如果没有正签合同，则不需要发起解约协议
		Contract formalContract = contractService.getLatestContract(previousOrderNo, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		if (formalContract == null || !ContractStatusEnum.SIGNED_STATUS_LIST.contains(formalContract.getStatus())) {
			return Boolean.FALSE;
		}
		List<Contract> terminalContractList = contractService.getContractList(previousOrderNo, ContractTypeEnum.TERMINAL.getCode())
			.stream()
			.filter(contract -> ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus()))
			.filter(contract -> ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus()) || contract.getUserConfirmStatus().equals(CommonEnum.YES.getCode()) || contract.getUserSignStatus().equals(CommonEnum.YES.getCode()))
			.collect(Collectors.toList());
		if (CollectionUtils.isNotEmpty(terminalContractList)) {
			return Boolean.FALSE;
		}
		return Boolean.TRUE;
	}


	/**
	 * 判断是否需要发起关联订单的解约协议or已通过合并发起解约协议
	 *
	 * @param projectOrderId 项目订单ID
	 * @return 是否需要发起解约协议 or 是否已通过合并发起解约协议
	 */
	public boolean needLaunchOrLaunchedTerminalContract(String projectOrderId) {
		Contract formalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode())
			.stream().findFirst().orElse(null);
		if (formalContract != null && ContractStatusEnum.validStatusWithoutDraft.contains(formalContract.getStatus())) {
			List<ContractRelation> relationList = contractRelationService.getRelationList(formalContract.getContractCode());
			if (CollectionUtils.isEmpty(relationList)) {
				return Boolean.FALSE;
			}
			List<String> relateContractCodeList = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
			List<Contract> relateContractList = contractService.getListByContractCodes(relateContractCodeList, false);
			List<Contract> terminalContractList = relateContractList.stream().filter(item -> ContractTypeEnum.TERMINAL.getCode().equals(item.getType())).collect(Collectors.toList());
			return CollectionUtils.isNotEmpty(terminalContractList);
		}
		return needLaunchRelationTerminalContract(projectOrderId);
	}

