	/**
	 * 报价单列表转换为报价单信息列表
	 * @param billCodeList
	 * @param billCodeInfoList
	 * @return
	 */
	public List<BillCodeInfo> converBillCodeListToBillCodeInfoList(List<String> billCodeList, List<BillCodeInfo> billCodeInfoList, String projectOrderId, byte contractType) {
		List<Byte> needAdapterCompanyCodeType = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PERSONAL.getCode());
		if (!needAdapterCompanyCodeType.contains(contractType)) {
			if (CollectionUtil.isNotEmpty(billCodeInfoList)) {
				return billCodeInfoList;
			} else if (CollectionUtil.isNotEmpty(billCodeList)) {
				return billCodeList.stream().map(billCode -> BillCodeInfo.builder().billCode(billCode).companyCode("").build()).collect(Collectors.toList());
			} else {
				return new ArrayList<>();
			}
		}
		if (CollectionUtil.isNotEmpty(billCodeInfoList)) {
			//判断billCodeInfoList中的companyCode是否存在空值
			boolean hasEmptyCompanyCode = billCodeInfoList.stream().anyMatch(billCodeInfo -> org.apache.commons.lang3.StringUtils.isBlank(billCodeInfo.getCompanyCode()));
			if (!hasEmptyCompanyCode) {
				//不存在空值，直接返回
				return billCodeInfoList;
			}
			//订单正签报价单号列表
			List<String> formalBillCodeList = contractDependentDataService.getFormalBillCodeList(projectOrderId);
			//过滤掉正签报价单，剩余存在空的companyCode,需要进行补全
			List<String> cooperBillCodeList = billCodeInfoList.stream()
				.map(BillCodeInfo::getBillCode)
				.filter(billCode -> !formalBillCodeList.contains(billCode)).collect(Collectors.toList());
			List<ContractSourceDataBO.PersonalContractData> personalContractData = contractDependentDataService.buildCooperPersonalContractData(cooperBillCodeList, projectOrderId);
			Map<String, String> billCodeCompanyCodeMap = personalContractData.stream().collect(Collectors.toMap(ContractSourceDataBO.PersonalContractData::getBillCode, ContractSourceDataBO.PersonalContractData::getOrganizationCode, (k1, k2) -> k1));
			for (BillCodeInfo billCodeInfo : billCodeInfoList) {
				if (org.apache.commons.lang3.StringUtils.isBlank(billCodeInfo.getCompanyCode())) {
					billCodeInfo.setCompanyCode(billCodeCompanyCodeMap.get(billCodeInfo.getBillCode()));
				}
			}
			LOGGER.info("参数补全companyCode后，billCodeInfoList:{}", billCodeInfoList);
			return billCodeInfoList;
		}
		//将billCodeList转换为billCodeInfoList，注意一个billCode可能对应多个主体
		List<BillCodeInfo> resultList = new ArrayList<>();
		if (CollectionUtil.isNotEmpty(billCodeList)) {
			//订单正签报价单号列表
			List<String> formalBillCodeList = contractDependentDataService.getFormalBillCodeList(projectOrderId);
			List<String> cooperBillCodeList = billCodeList.stream().filter(billCode -> !formalBillCodeList.contains(billCode)).collect(Collectors.toList());

			List<ContractSourceDataBO.PersonalContractData> personalContractData = contractDependentDataService.buildCooperPersonalContractData(cooperBillCodeList, projectOrderId);
			Map<String, List<ContractSourceDataBO.PersonalContractData>> personalContractDataMap =
				personalContractData.stream()
					.collect(Collectors.groupingBy(ContractSourceDataBO.PersonalContractData::getBillCode));

			for (String billCode : billCodeList) {
				if (personalContractDataMap.containsKey(billCode)) {
					List<ContractSourceDataBO.PersonalContractData> personalContractDataList = personalContractDataMap.get(billCode);
					for (ContractSourceDataBO.PersonalContractData personalContractDataItem : personalContractDataList) {
						resultList.add(BillCodeInfo.builder().billCode(billCode).companyCode(personalContractDataItem.getOrganizationCode()).build());
					}
				} else {
					resultList.add(BillCodeInfo.builder().billCode(billCode).companyCode("").build());
				}
			}
		}
		LOGGER.info("参数补全companyCode后，billCodeInfoList:{}", resultList);
		return resultList;
	}

	/**
	 * 首次创建合同时，需要返回前端变更单对应的所有主体信息。
	 * 如果前端已经传入了 changeOrderInfo，则表明是编辑场景，后续获取数据需要以前端传入的为主
	 * case: changeOrderId - 主体1、主体2
	 * 创建时，返回changeOrderId-主体1、主体2
	 * 编辑合同1时，前端会传入changeOrderId-主体1，此时调用主订单查询个性化报价数据，要过滤出主体 1 的数据。
	 * 编辑合同2同理，前端传入changeOrderId-主体2，要过滤出主体 2 的数据。
	 */
	public List<ChangeOrderInfo> convertChangeOrderNoToInfoList(String changeOrderId, List<ChangeOrderInfo> changeOrderInfoList, String projectOrderId, byte contractType) {
		// 只有销售合同需要适配主体
		if (!ContractTypeEnum.PERSONAL.getCode().equals(contractType) || StringUtils.isBlank(changeOrderId)) {
			return Collections.emptyList();
		}
		if (CollectionUtils.isNotEmpty(changeOrderInfoList)) {
			return changeOrderInfoList;
		}

		PersonalContractDataParam param = PersonalContractDataParam.builder()
			.projectOrderId(projectOrderId)
			.changeOrderId(changeOrderId)
			.build();
		ContractSourceDataBO contractSourceDataBO = QueryHelper.unwrap(p -> homeOrderDataConversionService.contractPersonalDataV2(p), param, "contractPersonalDataV2");
		List<ContractSourceDataBO.PersonalContractData> personalContractDataList = contractSourceDataBO.getPersonalContractDataList();
		if (CollectionUtils.isEmpty(personalContractDataList)) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "个性化合同报价信息为空");
		}

		return personalContractDataList.stream()
			.map(personalContractData -> ChangeOrderInfo.builder().changeOrderId(personalContractData.getChangeOrderId()).companyCode(personalContractData.getOrganizationCode()).build())
			.collect(Collectors.toList());
	}

