	 * 获取订单销售合同主体签约信息
	 *
	 * @param projectOrderId   订单号
	 * @param companyCodeList  主体编码列表
	 * @return 主体签约信息列表
	 */
	public List<ContractSubjectSignInfo> getOrderPersonalContractSubjectSignInfo(String projectOrderId, List<String> companyCodeList) {
		if (CollectionUtils.isEmpty(companyCodeList)) {
			return Collections.emptyList();
		}

		// 查询有效合同（已签署 || 未作废且已确认）
		List<Contract> signedContractList = contractService
			.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode())
			.stream()
			.filter(contract -> ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus())
				|| (!ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())
				&& CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus())))
			.collect(Collectors.toList());

		// 把所有已签署合同涉及的 companyCode 汇总
		Set<String> signedCompanyCodes = signedContractList.stream()
			.map(Contract::getCompanyCode)
			.collect(Collectors.toSet());

		// 返回主体签署情况
		return companyCodeList.stream()
			.map(companyCode -> new ContractSubjectSignInfo(companyCode, signedCompanyCodes.contains(companyCode)))
			.collect(Collectors.toList());
	}


