	/**
	 * 根据版式id获取手签角色类型,仅支持个人签约场景
	 */
	public String getSignRoleType(Long instanceId) {
		try {
			// 根据实例id获取对应合同
			Contract contract = contractService.getContractByInstanceId(instanceId);

			// 提前获取配置对象，避免多次调用
			JiaFangAgentSupportConfig supportConfig = contractApolloConfig.getJiaFangAgentSupportConfig();

			// 合并多个配置检查，使用短路逻辑快速返回
			if (!isContractSupported(contract, supportConfig)) {
				return FreeFormRoleTypeEnum.SIGN_USER.getCode();
			}

			//白名单中的项目id始终走旧逻辑，使用甲方签章，不使用代理人签章,返回signUser
			if(supportConfig.inWhiteProjectOrderId(contract.getProjectOrderId())){
				return FreeFormRoleTypeEnum.SIGN_USER.getCode();
			}


			// 非2.5订单不支持，返回signUser
			if (!commonBusinessService.isProcessV25New(contract.getProjectOrderId())) {
				return FreeFormRoleTypeEnum.SIGN_USER.getCode();
			}

			// 获取合同签约人并检查角色类型
			ContractUser signer = contractUserService.getSignerByContractCode(contract.getContractCode());
			if (!RoleTypeEnum.AGENT.getCode().equals(signer.getRoleType())) {
				return FreeFormRoleTypeEnum.SIGN_USER.getCode();
			}

			// 校验签章规则配置
			return validateSealConfig(instanceId);

		} catch (Exception e) {
			LOGGER.error("根据版式id获取手签角色类型异常，兜底返回signUser, instanceId:{}, error:{}",
				instanceId, e.getMessage(), e);
		}
		return FreeFormRoleTypeEnum.SIGN_USER.getCode();
	}

	/**
	 * 检查合同是否满足支持条件
	 */
	private boolean isContractSupported(Contract contract, JiaFangAgentSupportConfig supportConfig) {
		// 使用短路逻辑，按照最可能失败的条件排序
		return supportConfig.getSupportContractTypeList().contains(contract.getType())
			&& supportConfig.getSupportBusinessTypeList().contains(contract.getBusinessType())
			&& supportConfig.inOpenCity(contract.getGbCode());
	}

	/**
	 * 校验签章配置
	 */
	private String validateSealConfig(Long instanceId) {
		Long formId = freeformService.getFormIdByInstanceId(instanceId);
		List<SealNewRuleParam> sealNewRule = freeformService.queryNewSealConfigs(formId);

		String jiaFangAgentSealKeyword = baseContractPdfCreateService.getJiaFangAgentSealKeyword(
			sealNewRule,
			formId
		);

		if (StringUtils.isBlank(jiaFangAgentSealKeyword)) {
			LOGGER.error("根据版式id获取手签角色类型，签章规则中没有配置甲方代理人印章关键字,兜底返回signUser，instanceId:{}, formId:{}",
				instanceId, formId);
			return FreeFormRoleTypeEnum.SIGN_USER.getCode();
		}

		return FreeFormRoleTypeEnum.SIGN_AGENT.getCode();
	}

	/**
	 * 正签合同是否使用新页面流程
	 */
	public boolean formalUseNewProcess(Byte businessType, boolean processV25, Integer gbCode) {
