	/**
	 * 判断合同套餐是否为大B承担或B+C混合套餐
	 *
	 * @param comboDTOS      合同套餐信息
	 * @param projectOrderId 订单号
	 * @return true-是大B承担或B+C混合套餐，false-不是大B承担或B+C混合套餐
	 */
	public boolean isBOrBCCombo(List<ComboDTO> comboDTOS, String projectOrderId) {
		if (CollectionUtils.isEmpty(comboDTOS)) {
			Map<String, String> comboParams = new HashMap<>(4);
			comboParams.put("homeOrderNo", projectOrderId);
			comboParams.put(HomeModelSupportParamEnum.comboTypeList.name(), "1");
			comboParams.put(HomeModelSupportParamEnum.previewTimeCode.name(), "1");

			Map<String, Map<String, String>> moduleParams =
				Collections.singletonMap(HomeModelDefEnum.COST_CONTROL_BUDGET_STANDARD_COMBO.name(), comboParams);

			HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(projectOrderId, moduleParams);

			comboDTOS = Optional.ofNullable(homeProject)
				.map(HomeProject::getMainOrder)
				.map(MainOrder::getCostControl)
				.map(MainOrderModel.CostControl::getBudgetStandardComboModule)
				.map(BudgetStandardComboModule::getComboDTOList)
				.orElse(Collections.emptyList());
		}
        if (CollectionUtils.isEmpty(comboDTOS)) {
			LOGGER.info("合同套餐信息，未获取到套餐信息，默认返回false，projectOrderId{}", projectOrderId);
			return false;
		}
		//大B开发商承担类型列表【1-小C客户承担；2-大B开发商；3-B+C混合】
		List<Integer> BPurchaseTypeList = Arrays.asList(2, 3);
		ComboDTO comboDTO = comboDTOS.stream().filter(item -> BPurchaseTypeList.contains(item.getPurchaseType())).findAny().orElse(null);
		boolean isBOrBCCombo = comboDTO != null;
		LOGGER.info("合同套餐信息，套餐是否为【B、B+C】套餐：{},projectOrderId{}", isBOrBCCombo, projectOrderId);
		return isBOrBCCombo;
	}

	/**
	 * 根据报价单号判断个性化报价中是否包含 C 承担的报价
	 *
	 * @param projectOrderId 订单号
	 * @param billCode       报价单号
	 */
	public boolean getPersonalBillHasCPart(String projectOrderId, String billCode) {

		// 1. 查询个性化报价明细
		ComboQuotationListDTO quotationDTO = queryQuotationDTO(projectOrderId, billCode);
		if (quotationDTO == null) {
			return false;
		}

		// 2. 判断套餐或单品是否包含 C 部分报价
		return hasCPartInCombo(quotationDTO.getComboList()) || hasCPartInSingle(quotationDTO.getQuotationList());
	}


	/**
	 * 根据报价单号列表 判断个性化报价中是否包含 B 供应商承担的报价
	 *
	 * @param projectOrderId 订单号
	 * @param billCodeList   报价单号列表
	 */
	/**
	 * 根据报价单号列表判断个性化报价中是否包含 B 供应商承担的报价
	 */
	public boolean getPersonalBillListHasBPart(String projectOrderId, List<String> billCodeList) {
		if (CollectionUtils.isEmpty(billCodeList)) {
			return false;
		}

		for (String billCode : billCodeList) {
			ComboQuotationListDTO quotationDTO = queryQuotationDTO(projectOrderId, billCode);
			if (quotationDTO == null) {
				continue;
			}

			if (hasBPartQuotation(quotationDTO)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * 判断单个个性化报价是否包含 B 方承担部分
	 */
	private boolean hasBPartQuotation(ComboQuotationListDTO quotationDTO) {
		return hasBPartInCombo(quotationDTO.getComboList())
			|| hasBPartInSingle(quotationDTO.getQuotationList());
	}

	/** 查询个性化报价明细 DTO */
	private ComboQuotationListDTO queryQuotationDTO(String projectOrderId, String billCode) {
		Map<String, Map<String, String>> moduleParams = new HashMap<>();

		Map<String, String> quotationParams = new HashMap<>();
		quotationParams.put("homeOrderNo", projectOrderId);
		quotationParams.put(HomeModelSupportParamEnum.billCode.name(), billCode);

		moduleParams.put(HomeModelDefEnum.COST_CONTROL_QUOTATION_LIST.name(), quotationParams);

		HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(projectOrderId, moduleParams);

		return Optional.ofNullable(homeProject)
			.map(HomeProject::getMainOrder)
			.map(MainOrder::getCostControl)
			.map(MainOrderModel.CostControl::getQuotationModule)
			.map(QuotationModule::getPersonalQuotation)
			.orElse(null);
	}

	/**
	 * 判断产品的 purchaseType 是否属于 C 承担
	 */
	private boolean isCPart(Integer purchaseType) {
		if (purchaseType == null) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "报价单中存在未设置purchaseType，无法判断是否为C部分报价");
		}
		return purchaseType.equals(PurchaseTypeEnum.客户承担成本.getCode());
	}

	/**
	 * 判断产品的 purchaseType 是否属于 B 承担
	 */
	private boolean isBPart(Integer purchaseType) {
		if (purchaseType == null) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "报价单中存在未设置purchaseType，无法判断是否为B部分报价");
		}
		return Arrays.asList(PurchaseTypeEnum.开发商承担成本.getCode(), PurchaseTypeEnum.开发商客户混合承担成本.getCode()).contains(purchaseType);
	}



	/** 套餐中是否有 C 部分报价 */
	private boolean hasCPartInCombo(List<ComboQuotationDTO> comboList) {
		if (CollectionUtils.isEmpty(comboList)) {
			return false;
		}
		return comboList.stream()
			.filter(c -> CollectionUtils.isNotEmpty(c.getQuotationProductList()))
			.flatMap(c -> c.getQuotationProductList().stream())
			.anyMatch(p -> isCPart(p.getPurchaseType()));
	}

	/** 单品中是否有 C 部分报价 */
	private boolean hasCPartInSingle(List<QuotationProductDTO> products) {
		if (CollectionUtils.isEmpty(products)) {
			return false;
		}
		return products.stream()
			.anyMatch(p -> isCPart(p.getPurchaseType()));
	}

	/** 套餐中是否有 B 部分报价 */
	private boolean hasBPartInCombo(List<ComboQuotationDTO> comboList) {
		if (CollectionUtils.isEmpty(comboList)) {
			return false;
		}
		return comboList.stream()
			.filter(c -> CollectionUtils.isNotEmpty(c.getQuotationProductList()))
			.flatMap(c -> c.getQuotationProductList().stream())
			.anyMatch(p -> isBPart(p.getPurchaseType()));
	}

	/** 单品中是否有 B 部分报价 */
	private boolean hasBPartInSingle(List<QuotationProductDTO> products) {
		if (CollectionUtils.isEmpty(products)) {
			return false;
		}
		return products.stream()
			.anyMatch(p -> isBPart(p.getPurchaseType()));
	}

	/**
	 * 获取正式套餐合同关联的其他正式报价报出的合同类型
	 * 目前包含：正式套餐合同、设计合同
	 * @param homeOrderNo
	 * @return
	 */
	public List<Byte> getFormalWithBindingExtraContractTypes(String homeOrderNo) {
		Contract contract = contractService.getContractInfo(homeOrderNo, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		if (contract == null) {
			return Collections.emptyList();
		}

		// 如果是正式套餐合同
		List<ContractRelation> relationList = contractRelationService.getRelationList(contract.getContractCode());
		if (CollectionUtils.isEmpty(relationList)) {
			// 没有关联合同，只返回正签合同类型
			return Collections.singletonList(ContractTypeEnum.PACKAGE_FORMAL.getCode());
		}
		// 获取关联的合同编号列表
		List<String> relateContractCodeList = relationList.stream()
			.map(ContractRelation::getRelateContractCode)
			.collect(Collectors.toList());
		// 查询关联合同详情
		List<Contract> relateContractList = contractService.getListByContractCodes(relateContractCodeList, false);
		// 检查是否包含设计合同
		boolean hasDesignContract = relateContractList.stream()
			.anyMatch(c -> ContractTypeEnum.DESIGN.getCode().equals(c.getType()));

		if (hasDesignContract) {
			// 包含设计合同，返回[设计合同, 正签合同]
			return Arrays.asList(ContractTypeEnum.DESIGN.getCode(), ContractTypeEnum.PACKAGE_FORMAL.getCode());
		}
		// 不包含设计合同，只返回正签合同类型
		return Collections.singletonList(ContractTypeEnum.PACKAGE_FORMAL.getCode());
	}


	/**
	 * 销售合同是否关联正签合同，且正签合同状态为盖章中、待签署状态
	 * @param relateContractCodes
	 * @return
	 */

	public Boolean getIsRelateSignedFormalContract(List<String> relateContractCodes) {
		// 如果是正式套餐合同
		List<ContractRelation> relationList = contractRelationService.getRelationListByRelateContractCodes(relateContractCodes);
		if (CollectionUtils.isEmpty(relationList)) {
			LOGGER.info("getIsRelateSignedFormalContract 没有关联主合同 relateContractCodes:{}", relateContractCodes);
			return Boolean.FALSE;
		}
		// 获取关联的合同编号列表
		List<String> contractCodeList = relationList.stream()
			.map(ContractRelation::getContractCode)
			.distinct()
			.collect(Collectors.toList());
		// 查询关联合同详情
		List<Contract> contractList = contractService.getListByContractCodes(contractCodeList, false);
		LOGGER.info("getIsRelateSignedFormalContract 没有关联主合同 contractCodeList:{} contractList:{}", contractCodeList, JSON.toJSON(contractList));

		List<Integer> SIGNED_STATUS_LIST = Arrays.asList(
			ContractStatusEnum.PENDING_USER_SIGN.getCode(),
			ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode(),
			ContractStatusEnum.AUDITING.getCode(),
			ContractStatusEnum.PENDING_COMPANY_SIGN.getCode(),
			ContractStatusEnum.FINISH.getCode()
		);

		return contractList.stream()
			.anyMatch(c -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(c.getType()) && SIGNED_STATUS_LIST.contains(c.getStatus()));
	}


