	public void recordFormalBudgetDesignNode(String homeOrderNo) {
		LOGGER.info("checkThenInsertFormalBudgetDesignNode:订单{}检查是否需要插入正式合同以及关联设计费合同均签署节点", homeOrderNo);
		//1.先查询出签约的正式合同
		Contract signFormalContract = contractService.getLatestUserSignContract(homeOrderNo, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		if (signFormalContract == null) {
			LOGGER.info("checkThenInsertFormalBudgetDesignNode:订单{}没有签约的正式合同", homeOrderNo);
			return;
		}
		//2.查询是否有报价来源的合同
		List<Byte> formalWithBindingExtraContractTypes = getFormalWithBindingExtraContractTypes(homeOrderNo);
		boolean isAllSigned = true;
		if (formalWithBindingExtraContractTypes.size() > 1) {
			Contract signDesignContract = contractService.getLatestUserSignContract(homeOrderNo, ContractTypeEnum.DESIGN.getCode());
			isAllSigned = signDesignContract != null;
		}
		//3.如果正式合同和设计合同都签约了，则插入节点
		if (isAllSigned) {
			projectNodeRecordWriteService.insertNodeRecord(homeOrderNo, ProjectNodeEnum.FORMAL_BUDGET_DESIGN_CONTRACT_SIGN, ProjectNodeStatusEnum.DONE, null);
			LOGGER.info("checkThenInsertFormalBudgetDesignNode:订单{}正式合同和设计合同都签约了，插入正式预算设计节点", homeOrderNo);
		} else {
			LOGGER.info("checkThenInsertFormalBudgetDesignNode:订单{}正式合同和设计合同没有都签约了，isAllSigned={}", homeOrderNo, isAllSigned);
		}
	}


	public void recordDesignFeeChangeNode(String contractCode, Date operationTime) {
		LOGGER.info("recordDesignFeeChangeNode:合同{}检查是否需要插入设计费变更节点", contractCode);
		Contract contract = contractService.getByContractCode(contractCode);
		if (contract == null || !ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus())) {
			LOGGER.info("recordDesignFeeChangeNode:合同{}不存在或者合同非签署状态", contractCode);
			return;
		}
		if (!ContractTypeEnum.DESIGN_FEE_RELATED_CONTRACT_LIST.contains(contract.getType())) {
			LOGGER.info("recordDesignFeeChangeNode:合同{}不是设计费用有关合同", contractCode);
			return;
		}
		Map<String, String> fieldMap = contractFieldService.getFieldMap(contractCode);
		String afterDiscountDesignerAmount = fieldMap.get("afterDiscountDesignerAmount");
		String preDiscountDesignerAmount = fieldMap.get("preDiscountDesignerAmount");
		String designerLevelName = fieldMap.get("designerLevelName");

		int needDesignerAmount = Integer.parseInt(fieldMap.getOrDefault("needDesignerAmount", "0"));
		//正式合同和正式套餐变更合同需要先判断是否变更了设计费
		if ((ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType()) || ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType()))
			&& CommonEnum.NO.getCode().intValue() == needDesignerAmount) {
			LOGGER.info("recordDesignFeeChangeNode:订单{}正式合同或正式套餐变更合同，且不变更设计费，不插入设计费变更节点", contract.getProjectOrderId());
			return;
		}
		HomeWorkNodeCreateReq homeWorkNodeCreateReq = new HomeWorkNodeCreateReq();
		homeWorkNodeCreateReq.setKeyNode(HomeWorkNodeEnum.DESIGN_FEE_CHANGE.getCode());
		homeWorkNodeCreateReq.setNodeCategory(HomeWorkNodeEnum.DESIGN_FEE_CHANGE.getParent().getCode());
		homeWorkNodeCreateReq.setObjectId(contract.getProjectOrderId());
		homeWorkNodeCreateReq.setObjectType(HomeWorkObjectTypEnum.DECORATION_PROJECT_CODE.getCode());
		homeWorkNodeCreateReq.setOperationTime(operationTime==null?new Date():operationTime);
		homeWorkNodeCreateReq.setServiceId(ServiceIdEnum.NRS_SALES_PROJECT.getServiceId());
		Map<String, Object> extInfo = new HashMap<>();
		extInfo.put("afterDiscountDesignerAmount", afterDiscountDesignerAmount);
		extInfo.put("preDiscountDesignerAmount", preDiscountDesignerAmount);
		extInfo.put("designerLevelName", designerLevelName);
		extInfo.put("contractCode", contractCode);
		homeWorkNodeCreateReq.setWorkNodeExt(extInfo);
		homeManagementFeign.createHomeWorkNode(homeWorkNodeCreateReq);
		LOGGER.info("recordDesignFeeChangeNode:订单{}插入设计费变更节点", contract.getProjectOrderId());
	}

	private Integer setStatusByConfirmsAndSignType(List<Byte> confirmTypes, Contract contractInfo) {
		Integer updateStatus;
		updateStatus = ContractStatusEnum.PENDING_USER_SIGN.getCode();
		Byte userSignType = contractInfo.getUserSignType();//签署方式
		// 协议确认类合同，合同状态更新为待用户确认
		if (UserSignTypeEnum.CONFIRM.getCode().equals(userSignType) && confirmTypes.contains(contractInfo.getType())) {
			updateStatus = ContractStatusEnum.PENDING_USER_CONFIRM.getCode();
		}
		return updateStatus;
	}
}

