public ContractListGroup getContractListGroup(Long ucId, String projectOrderId) {
	ContractListGroup resGroup = new ContractListGroup();
	List<ContractListGroup.ContractGroup> groupList = new ArrayList<>();
	//并行请求整装和零售合同分类
	String appId = HeaderContext.getContext().getAppId();
	CompletableFuture<ContractListVo> decorateFuture = CompletableFuture.supplyAsync(() -> getUserContractList(ucId, projectOrderId, appId), parallelRequestExecutor);
	CompletableFuture<Page<ContractDetailDTO>> retailFuture = CompletableFuture.supplyAsync(() -> orderServiceRpc.retailContractListByUcid(ucId), parallelRequestExecutor);

	ContractListVo decorateContractListVo = null;
	try {
		decorateContractListVo = decorateFuture.get();
	} catch (NrsBusinessException e) {
		throw e;
	} catch (Exception e) {
		LOGGER.error("获取整装合同类型列表失败projectOrderId:{},ucid:{}", projectOrderId, ucId, e);
		throw new NrsBusinessException("获取合同类型列表失败，请刷新或联系客服");
	}

	Page<ContractDetailDTO> retailContractDetailDTO = null;
	try {
		retailContractDetailDTO = retailFuture.get();
	} catch (NrsBusinessException e) {
		throw e;
	} catch (Exception e) {
		LOGGER.error("获取零售合同类型列表失败,兼容只展示整装合同列表projectOrderId:{},ucid:{}", projectOrderId, ucId, e);
	}

	if (CollectionUtils.isNotEmpty(decorateContractListVo.getList())) {
		ContractListGroup.ContractGroup decorateGroup = ContractListGroup.ContractGroup.builder()
			.key(ContractGroupEnum.DECORATE_AND_PERSONALIZE.getKey())
			.title(ContractGroupEnum.DECORATE_AND_PERSONALIZE.getTitle())
			.build();
		groupList.add(decorateGroup);
	}

	if (retailContractDetailDTO != null && CollectionUtils.isNotEmpty(retailContractDetailDTO.getList())) {
		ContractListGroup.ContractGroup retailGroup = ContractListGroup.ContractGroup.builder()
			.key(ContractGroupEnum.RETAIL.getKey())
			.title(ContractGroupEnum.RETAIL.getTitle())
			.build();
		groupList.add(retailGroup);
	}
	resGroup.setGroupList(groupList);
	resGroup.setProjectOrderId(projectOrderId);
	resGroup.setPhone(getPhone(ucId));
	resGroup.setAddress(getAddress(projectOrderId));
	return resGroup;
}

