private ContractListVo.ContractItemVo obtainMergeStatus(ContractListVo.ContractItemVo contractItemVo, Map<ContractShowGroupEnum, Boolean> needMergeShowMap, Map<Integer, Integer> groupIndexMap, List<Contract> contractList, Boolean mergeLaunchDesignContract) {
	for (Map.Entry<ContractShowGroupEnum, Boolean> entry : needMergeShowMap.entrySet()) {
		ContractShowGroupEnum group = entry.getKey();
		List<Byte> contractTypeList = group.getContractList();
		Integer groupSignStatus = computeGroupSignStatus(contractList, contractTypeList, mergeLaunchDesignContract);
		Boolean needMergeShow = entry.getValue();
		if (contractTypeList.contains(contractItemVo.getType())) {
			contractItemVo.setIsMerge(needMergeShow);
			contractItemVo.setMergeGroup(group.getCode());
			contractItemVo.setMergeTitle(group.getMainTitle());
			contractItemVo.setMergeSubTitle(group.getSubTitle());
			contractItemVo.setDisplayOrder(groupIndexMap.get(group.getCode()));
			contractItemVo.setGroupSignStatus(groupSignStatus);
			contractItemVo.setGroupSignStatusText(ContractStatusEnum.getShowNameByCode(groupSignStatus));
			groupIndexMap.put(group.getCode(), groupIndexMap.get(group.getCode()) + 1);
		}
	}
	return contractItemVo;

}

public List<ContractListVo.ContractItemVo> sortContractVoList(List<ContractListVo.ContractItemVo> contractItemVoList) {
	List<ContractListVo.ContractItemVo> mergeList = contractItemVoList.stream().filter(item -> Boolean.TRUE.equals((item.getIsMerge()))).collect(Collectors.toList());
	List<ContractListVo.ContractItemVo> noMergeList = contractItemVoList.stream().filter(item -> !Boolean.TRUE.equals((item.getIsMerge()))).collect(Collectors.toList());
	List<Byte> orderContractTypes = ContractTypeEnum.getRelateContractTypes();
	mergeList = mergeList.stream().sorted(Comparator.comparingInt(o -> orderContractTypes.indexOf(o.getType()))).collect(Collectors.toList());
	int displayOrder = 1;
	for (ContractListVo.ContractItemVo contractItemVo : mergeList) {
		contractItemVo.setDisplayOrder(displayOrder);
		displayOrder++;
	}
	mergeList.addAll(noMergeList);
	return mergeList;
}

private List<ContractShowGroupEnum> getGroupList(List<Contract> contractList) {
	if (CollectionUtils.isEmpty(contractList)) {
		return Collections.singletonList(ContractShowGroupEnum.GROUP_0);
	}
	List<ContractShowGroupEnum> groupList = new ArrayList<>();
	Contract contract = contractList.get(0);
	String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(contract.getProjectOrderId());
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(convertProjectOrderId);
	if (processV25) {
		Byte businessType = commonBusinessService.getBusinessType(convertProjectOrderId);
		if (BusinessTypeEnum.getHouseCertificate25ModeList().contains(businessType)) {
			Contract formalContract = contractList.stream().filter(m -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(m.getType())).findFirst().orElse(null);
			if (formalContract != null && ContractModeEnum.FULL_SERVICE.getCode().equals(commonContractService.getContractModeByContractCode(formalContract.getContractCode()))) {
				groupList.add(ContractShowGroupEnum.GROUP_3);
				return groupList;
			}
			//翻新全案场景，图纸合同可能有也可能没有，取决于是否有图纸上传, 如果仅只有正签合同，则使用默认分组
			if (formalContract != null) {
				List<ContractRelation> relationList = contractRelationService.getRelationList(formalContract.getContractCode());
				if (CollectionUtils.isEmpty(relationList)) {
					groupList.add(ContractShowGroupEnum.GROUP_0);
					return groupList;
				}
			}
			Contract personalContract = contractList.stream().filter(m -> m.getType().equals(ContractTypeEnum.PERSONAL.getCode())).filter(m -> !homeAndPcCommonService.isMultipleQuotePersonalContract(m) && StrUtil.isBlank(m.getChangeOrderId())).findFirst().orElse(null);
			if (ObjectUtil.isNotEmpty(personalContract)) {
				groupList.add(ContractShowGroupEnum.GROUP_1);
			} else {
				groupList.add(ContractShowGroupEnum.GROUP_2);
			}
			return groupList;
		}
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			Contract personalContract = contractList.stream().filter(m -> m.getType().equals(ContractTypeEnum.PERSONAL.getCode())).filter(m -> !homeAndPcCommonService.isMultipleQuotePersonalContract(m) && StrUtil.isBlank(m.getChangeOrderId())).findFirst().orElse(null);
			if (personalContract != null) {
				groupList.add(ContractShowGroupEnum.GROUP_4);
				return groupList;
			}
		}
	}
	return Collections.singletonList(ContractShowGroupEnum.GROUP_0);
}

private Map<ContractShowGroupEnum, Boolean> needMergeShow(List<Contract> contractList, List<ContractShowGroupEnum> groupList) {
	Map<ContractShowGroupEnum, Boolean> needMergeShowMap = new HashMap<>(groupList.size());
	for (ContractShowGroupEnum group : groupList) {
		for (Contract contract : contractList) {
			if (group.getContractList().contains(contract.getType())) {
				needMergeShowMap.put(group, true);
			}
		}

	}
	return needMergeShowMap;
}

private boolean needPay(String projectOrderId, Byte contractType, Integer contractStatus, ProjectInfoDTO projectInfo) {
	if (!ContractStatusEnum.SIGNED_STATUS_LIST.contains(contractStatus)) {
		return false;
	}
	//个性化合同需要单独处理
	if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
		List<ListFundAmountItemDTO> listFundAmountItemDTOS = orderCenterRpc.listFundAmountByProjectOrderNo(projectInfo.getProjectOrderId(), null);
		BigDecimal tobePaidAmount = listFundAmountItemDTOS.stream().map(ListFundAmountItemDTO::getToPayAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
		return tobePaidAmount.compareTo(BigDecimal.ZERO) > 0;
	}
	FundTypeEnum fundTypeEnum = FundRelateContractMapping.obtainFundTypeEnumByContractType(contractType);
	if (fundTypeEnum == null) {
		return false;
	}
	FundInfo fundInfo = fundInfoService.getFundByOrderIdAndFundType(projectOrderId, fundTypeEnum.getValue());
	if (fundInfo == null) {
		return false;
	}
	return fundInfo.getFundAmount().compareTo(fundInfo.getPaidAmount()) > 0;
}

private void formatList(List<ContractListVo.ContractItemVo> itemVos) {
	if (Objects.isNull(itemVos) || itemVos.isEmpty()) {
		return;
	}
	List<String> contractCodes = itemVos.stream().map(ContractListVo.ContractItemVo::getContractCode).collect(Collectors.toList());
	List<Byte> nodeTypeList = Arrays.asList(NodeTypeEnum.USER_CONFIRM.getCode(), NodeTypeEnum.USER_SIGN.getCode());

	//按钮
	List<Integer> seeStatusList = Arrays.asList(ContractStatusEnum.FINISH.getCode(),
		ContractStatusEnum.USER_CONFIRMED.getCode(),
		ContractStatusEnum.AUDITING.getCode(),
		ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode(),
		ContractStatusEnum.PENDING_COMPANY_SIGN.getCode(),
		//已作废的合同肯定确认/签署完成，展示查看按钮，已作废的合同仅为：重签的认购、整装首期款合同、木作首期款合同、家电软装首期款合同
		ContractStatusEnum.CANCEL.getCode());
	List<Integer> confirmStatusList = Collections.singletonList(ContractStatusEnum.PENDING_USER_CONFIRM.getCode());
	List<Integer> signStatusList = Collections.singletonList(ContractStatusEnum.PENDING_USER_SIGN.getCode());

	//状态
	List<Integer> auditStatusList = Arrays.asList(ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode(), ContractStatusEnum.AUDITING.getCode());

	//时间
	List<ContractNode> nodeList = contractNodeService.getListByContractCodesAndType(contractCodes, nodeTypeList);
	Map<String, List<ContractNode>> nodeMapList = new HashMap<>();
	for (ContractNode node : nodeList) {
		if (!nodeMapList.containsKey(node.getContractCode())) {
			List<ContractNode> nodes = new LinkedList<>();
			nodeMapList.put(node.getContractCode(), nodes);
		}

		nodeMapList.get(node.getContractCode()).add(node);
	}

	for (ContractListVo.ContractItemVo vo : itemVos) {
		List<ButtonItemVo> buttonList = new LinkedList<>();
		if (seeStatusList.contains(vo.getStatus().intValue())) {
			buttonList.add(ButtonItemVo.builder().type(CButtonEnum.SEE.getType()).name(CButtonEnum.SEE.getName()).schema(buildDetailUrl(vo.getContractCode())).build());
		}
		if (confirmStatusList.contains(vo.getStatus().intValue())) {
			buttonList.add(ButtonItemVo.builder().type(CButtonEnum.CONFIRM.getType()).name(CButtonEnum.CONFIRM.getName()).schema(buildDetailUrl(vo.getContractCode())).build());
		}
		if (signStatusList.contains(vo.getStatus().intValue())) {
			buttonList.add(ButtonItemVo.builder().type(CButtonEnum.CONFIRM.getType()).name(CButtonEnum.CONFIRM.getName()).schema(buildDetailUrl(vo.getContractCode())).build());
		}
		if (vo.getPayStatus() && toPay) {
			buttonList.add(ButtonItemVo.builder().type(CButtonEnum.PAY.getType()).name(CButtonEnum.PAY.getName()).schema(buildPayUrl(vo.getProjectOrderId(), vo.getType())).build());
		}
		vo.setButtonList(buttonList);

		//状态归类, 5.待提交审核 6.审核中 7.待盖公司章 -> 审核中
		if (auditStatusList.contains(vo.getStatus().intValue())) {
			vo.setStatusText(ContractStatusEnum.AUDITING.getName());
		}

		//时间
		List<ContractListVo.TextItem> textItems = new LinkedList<>();
		if (nodeMapList.containsKey(vo.getContractCode())) {
			for (ContractNode node : nodeMapList.get(vo.getContractCode())) {
				String nodeName = NodeTypeEnum.getNameByCode(node.getNodeType());
				String time = DateUtils.getFormatDateStr(new Date(node.getFireTime()), DateUtils.DATE);
				ContractListVo.TextItem textItem = ContractListVo.TextItem.builder().key(nodeName).name(time).build();
				textItems.add(textItem);
			}
		}
		vo.setTextList(textItems);

	}

	//时间

}

