public List<ContractOnlineVo> coverContractListToContractOnlineVoList(List<Contract> contractList) {
	List<ContractOnlineVo> contractOnlineVoList = new ArrayList<>();
	for (Contract contract : contractList) {
		if (contract.getSignChannelType().equals(SignChannelTypeEnum.OFFLINE.getCode()) || !ContractStatusEnum.inPositiveStatus.contains(contract.getStatus())) {
			continue;
		}
		String contractUrl = homeAndPcCommonService.getContractUrl(contract);
		ContractOnlineVo build = ContractOnlineVo.builder()
			.contractType(contract.getType())
			.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
			.shortName(ContractTypeEnum.getShortName(contract.getType()))
			.contractCode(contract.getContractCode())
			.pdfPageCount(contract.getPdfPageCount())
			.contractUrl(contractUrl)
			.status(contract.getStatus())
			.build();
		contractOnlineVoList.add(build);
	}
	return contractOnlineVoList;
}

