public ContractPdfImageVo getContractPageImage(String contractCode, Integer page, Long ucId) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (Objects.isNull(contract)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在-[签约]");
	}

	ContractUser contractUser = contractUserService.getSignerByContractCode(contractCode);
	if (Objects.isNull(contractUser)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人-[签约]");
	}

	//加解密
	String contractUserPhone = cipherService.decrypt(contractUser.getPhone());
	//获取用户信息
	CUserDTO userDTO = userFeignService.getUserInfo(ucId.toString());
	String loginPhone = cipherService.decrypt(userDTO.getPhone());
	//校验登录人和签约人是否一致
	if (!loginPhone.equals(contractUserPhone)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "非签约人，无权限访问");
	}

	//校验页数合法
	if (page > contract.getPdfPageCount()) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "无效页数");
	}

	//目前只支持线上的
	if (!SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "非线上合同，无效请求");
	}

	String latestPdfKey = getContractLatestPdfKey(contract);
	ContractPdfImage contractPdfImage = contractPdfImageService.getByPdfKeyAndPage(latestPdfKey, page);

	ContractPdfImageVo result = new ContractPdfImageVo();
	//图片还没有，需要去兜底处理
	if (Objects.isNull(contractPdfImage)) {
		result.setStatus(PdfImageStatusEnum.DOING.getCode().intValue());
		//开启一个线程处理
		CompletableFuture.runAsync(() -> {
			if (ContractTypeEnum.DRAWING.getCode().equals(contract.getType())) {
				LOGGER.info("C端查看合同未找到图片，contractCode:{}", contractCode);
				//2025-04-02，图纸合同去除兜底转图片功能，避免服务器崩溃
				return;
			}
			contractPdfToImage(contractCode);
		});
		return result;
	}

	result.setStatus(PdfImageStatusEnum.OK.getCode().intValue());
	result.setImageUrl(s3Service.generateUrl(contractPdfImage.getImageKey(), 1800));
	return result;
}

