public ContractSignUrlVo getContractSignUrl(String contractCode, String returnUrl) {
	List<String> contractCodeList = Arrays.asList(contractCode.split(","));
	List<ContractUser> signerList = contractUserService.getSignerByContractCodes(contractCodeList);
	if (CollectionUtils.isEmpty(signerList)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人-[签约]");
	}
	ContractUser signer = signerList.get(0);
	CUserDTO userDTO = userFeignService.getUserInfo(HeaderContext.getUserId().toString());
	String phone = cipherService.decrypt(userDTO.getPhone());
	Contract contract = contractService.getByContractCode(contractCode);
	String signerPhone = cipherService.decrypt(signer.getPhone());
	String loginPhone = cipherService.decrypt(userDTO.getPhone());
	//校验登录人和签约人是否一致
	if (!signerPhone.equals(phone)) {
		ContractSignUrlVo result = new ContractSignUrlVo();
		result.setAuthCode(AuthCodeEnum.USER_NOT_SAME.getCode());
		result.setAuthError(UserNotSameError.builder()
			.signerPhone(ObjectUtil.isNotEmpty(signerPhone) ? signerPhone.substring(signerPhone.length() - 4) : "")
			.loginPhone(ObjectUtil.isNotEmpty(signerPhone) ? loginPhone.substring(loginPhone.length() - 4) : "")
			.helpUrl(userNameNotSameHelpUrl) //都是一个链接，不再区分
			.build());
		return result;
	}

	// 触发风控
	HeaderParam headerParam = HeaderContext.getContext();
	CompletableFuture.runAsync(RunnableWrapper.of(() -> riskService.triggerRisk(RiskSceneEnum.USER_SIGN.getCode(), RiskTypeEnum.OFFLINE.getCode(), contract.getProjectOrderId()
		, RiskStandContext.builder().contractCode(contractCode).openId(headerParam.getOpenId()).customerPhone(signer.getPhone()).build(), headerParam.getOperatorUcId())));

	if (contractCodeList.size() > 1) {
		return contractMpService.getBatchContractSignUrl(contractCodeList, signerList, returnUrl);
	}

	// 解约协议团转非团场景拦截：合并发起的解约协议不能单独签署
	if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType())) {
		List<ContractRelation> relationList = contractRelationService.getRelationListByRelateContractCodes(Collections.singletonList(contractCode));
		if (CollectionUtils.isNotEmpty(relationList)) {
			List<String> relatedContractCodes = relationList.stream()
				.map(ContractRelation::getContractCode)
				.collect(Collectors.toList());
			List<Contract> pendingSignContracts = contractService.getListByContractCodesAndStatusAndTypes(
				relatedContractCodes,
				Collections.singletonList(ContractStatusEnum.PENDING_USER_SIGN.getCode()),
				Collections.singletonList(ContractTypeEnum.PACKAGE_FORMAL.getCode())
			);
			if (CollectionUtils.isNotEmpty(pendingSignContracts)) {
				throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "当前客源需要同步发起老客源解约及新客源正签，请使用一键签署功能");
			}
		}
	}

	if (ContractTypeEnum.getAuthSignContractTypes().contains(contract.getType())) {
		return accreditFetchAuthUrl(contract, returnUrl);
	} else {
		return commonFetchSignUrl(contract, signer, signerPhone, returnUrl);
	}
}

private ContractSignUrlVo accreditFetchAuthUrl(Contract contract, String returnUrl) {
	// 获取授权协议书的法人
	ContractUser legalUser = contractUserService.getLatestUserByRole(contract.getContractCode(), RoleTypeEnum.LEGAL.getCode());
	// 获取授权协议书关联合同的签约人，主合同可能会有多个但是签约人都相同，选第一个即可，这个签约人就是授权协议的代理人
	Contract mainContract = contractService.getRelContractByAccreditContractCode(contract.getContractCode());
	if (mainContract == null) {
		LOGGER.error("授权协议书获取签署URL失败，未找到关联主合同,accreditContractCode：{}", contract.getContractCode());
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(),
			String.format("授权协议书获取签署URL失败，未找到关联主合同,accreditContractCode:%s", contract.getContractCode()), Level.ERROR);
	}
	ContractUser mainContractSignUser = contractUserService.getSignerByContractCode(mainContract.getContractCode());

	Map<String, String> fieldMap = contractFieldService.getFieldMap(contract.getContractCode());
	String companyName = fieldMap.get("companyName");
	String companyCreditCode = fieldMap.get("companyCreditCode");
	CertificateTypeEnum legalCertificateTypeEnum = CertificateTypeEnum.getEnumByCode(legalUser.getCertificateType());
	CertificateTypeEnum agentCertificateTypeEnum = CertificateTypeEnum.getEnumByCode(mainContractSignUser.getCertificateType());

	// 敏感数据解密
	List<String> cipherTextList = Stream.of(legalUser.getCertificateNo(), legalUser.getPhone(), mainContractSignUser.getCertificateNo())
		.distinct().collect(Collectors.toList());
	Map<String, String> plainTextMap = cipherService.decrypt(cipherTextList);
	String flowId = String.valueOf(IdGenerator.snowflakeId());

	SignResultVo signResultVo = contractSignResult(contract.getContractCode());
	if (SignResultEnum.SUCCESS.getCode().equals(signResultVo.getSignStatus())) {
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "已授权成功，请刷新页面", Level.WARN);
	}

	String companySignUrl = stringRedisTemplate.opsForValue().get(Constant.ACCREDIT_FETCH_AUTH_URL + contract.getContractCode());
	if (StringUtils.isBlank(companySignUrl)) {
		CompanySignParam param = new CompanySignParam();
		param.setInstanceId(contract.getPlatformInstanceId());
		param.setFlowId(flowId);
		param.setCompanyName(companyName);
		param.setCreditCode(companyCreditCode);
		param.setRoleTypeList(Collections.singletonList("signUser"));
		param.setLegalName(legalUser.getName());
		param.setLegalPhone(plainTextMap.get(legalUser.getPhone()));
		param.setLegalCardType(legalCertificateTypeEnum.getPlatformCode());
		param.setLegalCardCode(plainTextMap.get(legalUser.getCertificateNo()));
		param.setAgentName(mainContractSignUser.getName());
		param.setAgentCardType(agentCertificateTypeEnum.getPlatformCode());
		param.setAgentCardCode(plainTextMap.get(mainContractSignUser.getCertificateNo()));
		param.setReturnUrl(returnUrl);
		param.setIsShowHandwrittenTime(String.valueOf(1));
		companySignUrl = translateSignUrlForAccreditAuth(freeformService.getCompanySignUrl(param));
		// 缓存授权链接
		stringRedisTemplate.opsForValue().set(Constant.ACCREDIT_FETCH_AUTH_URL + contract.getContractCode(), companySignUrl, 50, TimeUnit.MINUTES);
		// 存储flowId
		contractFieldService.updateOrCreateFieldValue(contract.getContractCode(), "flowId", flowId);
	}

	ContractSignUrlVo result = new ContractSignUrlVo();
	result.setAuthCode(AuthCodeEnum.SUCCESS.getCode());
	result.setContractUrl(companySignUrl);
	return result;
}

