private ContractSignUrlVo commonFetchSignUrl(Contract contract, ContractUser signer, String signerPhone, String returnUrl) {
	//校验签约信息
	ContractSignUrlVo contractSignUrlVo = checkSignInfo(Collections.singletonList(contract.getContractCode()), Collections.singletonList(signer));
	if (contractSignUrlVo != null) {
		return contractSignUrlVo;
	}
	String signUrlKey = Constant.SINGLE_SIGN_URL_PRE.concat(contract.getPlatformInstanceId() + "");
	//查询缓存
	String cacheData = stringRedisTemplate.opsForValue().get(signUrlKey);
	if (StringUtils.isNotBlank(cacheData)) {
		LOGGER.info("单个获取合同签署url命中缓存数据，signUrlKey：{}", signUrlKey);
		return ContractSignUrlVo.builder()
			.authCode(AuthCodeEnum.SUCCESS.getCode())
			.contractUrl(cacheData).build();
	}
	ContractField contractObjectTypeField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), ContractSignInfoReq.Fields.contractObjectType);
	//主体类型 1个人 2公对公
	Byte contractObjectType = contractObjectTypeField == null ? null : Byte.valueOf(contractObjectTypeField.getFieldValue());
	CertificateTypeEnum certificateTypeEnum = CertificateTypeEnum.getEnumByCode(signer.getCertificateType());
	String signerCertificateNo = cipherService.decrypt(signer.getCertificateNo());

	//注册个人信息
	registerUserSeal(signer.getName(), signerPhone, certificateTypeEnum.getPlatformCode(), signerCertificateNo);

	boolean addWaterMark = CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus());
	//获取手签url
	String url;
	try {
		//如果是公对公线上签约
		if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType()) && ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
			url = translateSignUrl(getCompanySignUrl(contract, signerPhone, certificateTypeEnum.getPlatformCode().intValue(), signerCertificateNo, returnUrl, addWaterMark));
		} else {
			String signRoleType = getSignRoleType(contract.getPlatformInstanceId());
			url = translateSignUrl(freeformService.getSignUrl(contract.getPlatformInstanceId(), signerPhone, certificateTypeEnum.getPlatformCode().intValue(), signerCertificateNo, returnUrl, addWaterMark, signRoleType));
		}
	} catch (Exception e) {
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.GET_SIGN_URL_ERROR.getCode(), LogTypeEnum.GET_SIGN_URL_ERROR.getName(), "", "", "用户");
		LOGGER.error("获取手签链接失败，contractCode:{},contractType:{},errorMessage:{}", contract.getContractCode(), contract.getType(), e.getMessage(), e);
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "获取手签失败，请稍后重试", Level.WARN);
	}
	stringRedisTemplate.opsForValue().set(signUrlKey, url, 1, TimeUnit.MINUTES);
	ContractSignUrlVo result = new ContractSignUrlVo();
	result.setAuthCode(AuthCodeEnum.SUCCESS.getCode());
	result.setContractUrl(url);
	return result;
}

