public ContractSignUrlVo checkSignInfo(List<String> contractCodeList, List<ContractUser> signerList) {
	if (CollectionUtils.isEmpty(signerList)) {
		throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "签约人信息不存在，请检查", Level.WARN);
	}
	if (signerList.stream().map(ContractUser::getPhone).collect(Collectors.toSet()).size() > 1) {
		throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "合同签署人不一致，请检查", Level.WARN);
	}

	ContractUser signer = signerList.get(0);
	boolean canUseFaceAuth = faceAuthService.canUseFaceAuth(contractCodeList, signer);
	if (canUseFaceAuth) {
		// 判断是否已认证通过
		String phone = signer.getPhone();
		String certificateNo = signer.getCertificateNo();
		boolean authedUser = contractUserService.getAuthedUser(phone, certificateNo);
		if (!authedUser) {
			ContractSignUrlVo result = new ContractSignUrlVo();
			result.setAuthCode(AuthCodeEnum.NOT_FACE_AUTH.getCode());
			result.setAuthErrorMsg("为保障签约流程安全，需要您完成实名认证。");
			return result;
		}
	} else {
		//查询实名认证信息
		UserInfo authUserInfo = userPlatformFeignService.getUserInfoByUcId(HeaderContext.getUserId());
		//实名结果校验
		if (Objects.isNull(authUserInfo) || AuthStatusEnum.INVALID.getCode().equals(authUserInfo.getStatus())) {
			ContractSignUrlVo result = new ContractSignUrlVo();
			result.setAuthCode(AuthCodeEnum.NOT_REAL_AUTH.getCode());
			result.setAuthErrorMsg("为保障签约流程安全，需要您完成实名认证。实名认证服务由家家支付提供，收集信息仅用于身份验证用途，将全程保障您的个人信息安全。");
			return result;
		}
		//校验实名认证类型
		CertificateTypeEnum certificateTypeEnum = CertificateTypeEnum.getEnumByCode(signer.getCertificateType());
		if (!Objects.equals(certificateTypeEnum.getRealNameCode(), authUserInfo.getIdType())) {
			ContractSignUrlVo result = new ContractSignUrlVo();
			result.setAuthCode(AuthCodeEnum.CERTIFICATE_TYPE_NOT_SAME.getCode());
			result.setAuthError(CertificateTypeNotSameError.builder()
				.authCertificateType(CertificateTypeEnum.getNameByRealNameCode(authUserInfo.getIdType()))
				.signerCertificateType(certificateTypeEnum.getName())
				.helpUrl(certificateTypeNotSameHelpUrl)
				.build());
			result.setAuthErrorMsg("请使用身份证或者护照进行实名认证-[签约]");
			return result;
		}

		//校验信息一致性
		if (!authUserInfo.getName().equals(signer.getName())) {
			String errorMsg = String.format("账号实名信息:%s\n签约人信息:%s\n两者姓名需一致，请用【%s】信息重新实名或设计师修改签约人为【%s】",
				authUserInfo.getName(),
				signer.getName(),
				signer.getName(),
				authUserInfo.getName());
			ContractSignUrlVo result = new ContractSignUrlVo();
			result.setAuthCode(AuthCodeEnum.USER_NAME_NOT_SAME.getCode());
			result.setAuthError(UserNameNotSameError.builder()
				.signerName(signer.getName())
				.authName(authUserInfo.getName())
				.helpUrl(userNameNotSameHelpUrl)
				.build());
			result.setAuthErrorMsg(errorMsg);
			return result;
		}

		String signerCertificateNo = cipherService.decrypt(signer.getCertificateNo());
		if (!ObjectUtil.equal(authUserInfo.getIdNumber(), signerCertificateNo)) {
			String signerIdNumber = signerCertificateNo.substring(signerCertificateNo.length() - 4);
			String authIdNumber = authUserInfo.getIdNumber().substring(authUserInfo.getIdNumber().length() - 4);
			String errorMsg = String.format("账号实名信息:证件号:****%s%n签约人信息:证件号:****%s%n两者证件号需一致，请用【%s】信息重新实名或设计师修改签约人为【%s】",
				authIdNumber, signerIdNumber, signerIdNumber, authIdNumber);
			ContractSignUrlVo result = new ContractSignUrlVo();
			result.setAuthCode(AuthCodeEnum.USER_ID_NUMBER_NOT_SAME.getCode());
			result.setAuthError(UserIdNumberNotSameError.builder()
				.helpUrl(userIdNumberNotSameHelpUrl)
				.authIdNumber(authIdNumber)
				.signerIdNumber(signerIdNumber)
				.build());
			result.setAuthErrorMsg(errorMsg);
			return result;
		}
	}

	return null;
}

public Boolean contractSignTip(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (Objects.isNull(contract) || commonBusinessService.isPROCESS_V2_0_GROUP(contract.getProjectOrderId())) {
		return false;
	}
	List<Integer> popupOpenCitys = apolloConfigService.getPopupOpenCitys();
	if (CollectionUtils.isEmpty(popupOpenCitys) || !popupOpenCitys.contains(contract.getGbCode())) {
		return false;
	}

	//1.0不弹窗
	List<ProjectVersionDTO> projectVersionDTOS = projectInfoReadService.batchProjectVersion(Collections.singletonList(contract.getProjectOrderId()));
	if (CollectionUtils.isEmpty(projectVersionDTOS) || projectVersionDTOS.get(0).getProjectVersion().equals(ProjectVersionEnum.V1.getVersion())) {
		return false;
	}

	// 线上签约弹窗提醒
	CompletableFuture.runAsync(() -> {
		try {
			saveBusinessSnapshot(contract);
		} catch (Exception e) {
			LOGGER.error("线上签约弹窗提醒异常,Contract:{}", JSON.toJSONString(contract), e);
		}
	});
	return true;
}

private void saveBusinessSnapshot(Contract contract) {
	//获取项目信息
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(contract.getProjectOrderId());
	//构建快照信息
	BusinessSnapshotDTO businessSnapshotDTO = BusinessSnapshotDTO.builder()
		.projectOrderId(contract.getProjectOrderId())
		.projectAddress(homeAndPcCommonService.getResblockAddress(projectInfoDTO))
		.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
		.reminderTime(new Date())
		.build();

	//获取手机号信息
	List<ContractUser> contractUsers = contractUserService.getListByContractCode(contract.getContractCode());
	businessSnapshotDTO = commonContractService.buildSignUserInfo(businessSnapshotDTO, contractUsers, contract, projectInfoDTO);
	//记录弹窗提醒
	payServiceRpc.sendSmsMessage(PaySignReminderCreateReqDTO.builder()
		.projectOrderId(contract.getProjectOrderId())
		.reminderType(ReminderTypeEnum.SIGN_POPUP.getValue())
		.businessSnapshot(JSON.toJSONString(businessSnapshotDTO))
		.reminderTime(businessSnapshotDTO.getReminderTime())
		.build());
}

private String getCompanySignUrl(Contract contract, String phone, Integer certificateType, String certificateNo, String returnUrl, Boolean addWaterMark) {
	ContractField companyCreditCodeField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), ContractSignInfoReq.Fields.companyCreditCode);
	if (companyCreditCodeField == null || StringUtils.isBlank(companyCreditCodeField.getFieldValue())) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "公对公合同公司信用代码不能为空");
	}
	if (StringUtils.isBlank(contract.getRelateContractCode())) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "公对公合同关联授权协议书为空");
	}
	ContractField companySignUrlField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), "companySignUrl");
	if (companySignUrlField != null) {
		long betweenMinute = DateUtil.between(companySignUrlField.getMtime(), new Date(), DateUnit.MINUTE);
		LOGGER.info("公对公合同法人授权签署署链接已获取分钟数，betweenMinute:{}", betweenMinute);
		if (betweenMinute > 7 * 24 * 60) {
			//如果公对公合同法人授权签署署链接已过期，则将授权链接字段删除，后面重新获取
			contractFieldService.deleteByContractCodeAndKeys(companySignUrlField.getContractCode(), Collections.singletonList("companySignUrl"));
			LOGGER.info("公对公合同法人授权签署链接已过期，重新获取,contractCode:{},companySignUrlFieldId:{}", contract.getContractCode(), companySignUrlField.getId());
		} else {
			return companySignUrlField.getFieldValue();
		}
	}
	ContractField flowIdField = contractFieldService.getByContractCodeAndKey(contract.getRelateContractCode(), "flowId");
	if (flowIdField == null || StringUtils.isBlank(flowIdField.getFieldValue())) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "公对公合同授权协议书流程id为空");
	}
	List<SealSigParameter> parameterList = new LinkedList<>();
	SealSigParameter parameter = new SealSigParameter();
	parameter.setRoleType("companySignUser");//待配置
	parameter.setSignType(SealTypeEnum.COMPANY.getName());
	parameter.setCodeType(SealCodeTypeEnum.CREDITCODE.getCodeType());
	//统一社会信用代码
	parameter.setCreditCode(companyCreditCodeField.getFieldValue());
	parameter.setSignatureType(String.valueOf(SignatureTypeEnum.CONTRACT.getType()));
	parameter.setCardType(certificateType);
	parameter.setCardCode(certificateNo);
	parameter.setFlowId(flowIdField.getFieldValue());
	parameterList.add(parameter);

	ManualSealCommonParameter param = new ManualSealCommonParameter();
	param.setInstanceId(contract.getPlatformInstanceId());
	param.setVcodeMobile(phone);
	param.setAddWaterMark(addWaterMark);
	param.setReturnUrl(returnUrl);
	param.setSealSigList(parameterList);
	param.setUseAgentSign(true);
	param.setAccreditOTU(false);//flowId可以重复使用
	param.setIsShowHandwrittenTime(String.valueOf(1));

	LOGGER.info("获取公对公手签url入参:{}", JsonUtil.toJsonString(param));
	long startTime = DateUtils.getCurrentTimeStamp();
	ResultWithTraceId<String> result = freeformApiFacade.fetchManualSignUrl(param);
	long endTime = DateUtils.getCurrentTimeStamp();
	LOGGER.info("获取公对公手签url请求协议平台耗时:getSignUrl, cost:{}", endTime - startTime);
	LOGGER.info("获取公对公获取手签url返回:{}", result);
	if (result.getCode() != 1) {
		LOGGER.error("获取公对公获取手签url失败，入参:{}, 返回值:{}", param, result);
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取手签url失败");
	}
	String url = result.getResult().toString();
	//将获取到的url设置到合同字段中
	contractFieldService.updateOrCreateFieldValue(contract.getContractCode(), "companySignUrl", url);
	return url;
}

