public void dealContractForBpm(String contractCode) {
	if (StringUtils.isBlank(contractCode)) {
		return;
	}
	String lockKey = Constant.APPLY_BPM_PREFIX + contractCode;
	boolean isLock = lockService.isLock(lockKey);
	if (isLock) {
		LOGGER.info("合同发起审批，锁被占，已经在处理：" + lockKey);
		return;
	}

	lockService.lockElseThrow(lockKey, () -> {
		dealContractForBpmDetail(contractCode);
		return null;
	}, 0);
}

public void dealContractForBpmDetail(String contractCode) {
	LOGGER.info("contract_apply_bpm: {}", contractCode);
	Contract contractInfo = contractService.getByContractCode(contractCode);
	if (Objects.isNull(contractInfo) || !contractInfo.getStatus().equals(ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode())) {
		LOGGER.info("合同发起审批，状态不是待发起审批：{}", JsonUtil.toJsonString(contractInfo));
		return;
	}
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(contractInfo.getProjectOrderId(), ContractTypeEnum.PACKAGE_FORMAL.getCode());
	// 如果是2.5整装单子，B合同变更无需bpm审核，仅风控审核，流转至审核中状态
	boolean houseProcessV25 = processV25 && BusinessTypeEnum.getHouseCertificate25ModeList().contains(contractInfo.getBusinessType());
	if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractInfo.getType()) && houseProcessV25) {
		contractService.updateContractStatus(contractCode, ContractStatusEnum.AUDITING.getCode());
		return;
	}

	//2.5团装， 只有所有关联合同都是待提交审核状态才发起审批
	if (processV25 && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contractInfo.getBusinessType())) {
		List<RelateContract> relateContract = homeAndPcCommonService.getRelateContractList(contractInfo);
		if (CollectionUtils.isNotEmpty(relateContract)) {
			List<RelateContract> inProgressRelateContract = relateContract.stream()
				.filter(item -> ContractStatusEnum.inProgressStatusWithoutDraft.contains(item.getStatus()))
				.filter(item -> !ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode().equals(item.getStatus()))
				.collect(Collectors.toList());
			if (CollectionUtils.isNotEmpty(inProgressRelateContract)) {
				LOGGER.info("合同发起审批时，判断不能不发起审批，原因：存在非【待提交审核】的未终态的关联合同：{}", JsonUtil.toJsonString(inProgressRelateContract));
				return;
			}
			//找到正签合同
			RelateContract packageFormalContract = relateContract.stream().filter(item -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(item.getContractType())).findFirst().orElse(null);
			if (packageFormalContract == null) {
				LOGGER.error("团装2.5合同发起审批时，判断不能不发起审批，原因：未找到正签合同，projectOrderId:{}", contractInfo.getProjectOrderId());
				return;
			}
			//以主合同触发审批
			contractInfo = contractService.getByContractCode(packageFormalContract.getContractCode());
		}
	}


	//校验备件齐全
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractInfo.getType())) {
		boolean uploadStatus = pcContractService.checkAttach(contractInfo.getContractCode());
		if (!uploadStatus) {
			LOGGER.info("合同发起审批，附件不齐全：" + contractCode);
			return;
		}
	}

	ProjectInfoDTO projectInfo = projectInfoReadService.getByProjectOrderIdWithoutCache(contractInfo.getProjectOrderId());
	String customerName = projectInfo.getCustomer().getName();
	String projectAddress = homeAndPcCommonService.getAddress(projectInfo);
	//报价类型
	String quotationType = "-";
	//销售服务主体
	String companyName = "";
	//个性化合同需要获取销售服务主体
	if (ContractTypeEnum.PERSONAL.getCode().equals(contractInfo.getType())) {
		CompanyInfoDTO companyInfoDTO = commonContractService.getCompanyInfo(contractInfo.getCompanyCode());
		companyName = companyInfoDTO.getCompanyName();

	}
	//获取报价类型，如果调用失败，不影响发起bpm
	try {
		PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(contractInfo.getProjectOrderId(), contractInfo.getChangeOrderId());
		if (Objects.nonNull(planAllDTO) && Objects.nonNull(PlanBillTypeEnum.getEnumByCode(planAllDTO.getPlanInfo().getPlanType()))) {
			LOGGER.info("获取报价类型:{}", JsonUtil.toJsonString(planAllDTO.getPlanInfo()));
			quotationType = PlanBillTypeEnum.getEnumByCode(planAllDTO.getPlanInfo().getPlanType()).getName();
		}
	} catch (Exception e) {
		LOGGER.info("获取报价类型异常:{}", e.getMessage());
	}

	List<ContractRelation> relationContractList = contractRelationService.getRelationList(contractInfo.getContractCode());
	String pdfKey = s3Service.generateUrl(getContractLatestPdfKey(contractInfo), 604800);


	List<String> attachmentUrls = new LinkedList<>();
	attachmentUrls.add(pdfKey);
	ChangeOrderInfoDTO changeRangeNamesAndReason = new ChangeOrderInfoDTO();
	if (contractInfo.getType().equals(ContractTypeEnum.PACKAGE_CHANGE.getCode())) {
		changeRangeNamesAndReason = changeContractService.getChangeRangeNamesAndReason(contractInfo);
	}
	if (contractInfo.getType().equals(ContractTypeEnum.PERSONAL.getCode())) {
		//个性化合同取线下合同链接
		List<File> offlineContractByCode = getOfflineContractByCode(contractInfo.getContractCode());
		attachmentUrls = offlineContractByCode.stream().map(File::getUrl).collect(Collectors.toList());
	}

	for (ContractRelation contractRelation : relationContractList) {
		Contract contract = contractService.getByContractCode(contractRelation.getRelateContractCode());
		String pdfKeyTemp = s3Service.generateUrl(getContractLatestPdfKey(contract), 604800);
		attachmentUrls.add(pdfKeyTemp);
	}

	Byte businessType = payConfigService.getBusinessTypeByProjectType(projectInfo.getDecorateBusinessType(), projectInfo.getDecorateType());
	IBusinessesService iBusinessesService = businessServiceStrategy.obtainBusinessService(String.valueOf(businessType));
	iBusinessesService.obtainAttachments(contractInfo.getProjectOrderId(), contractInfo.getContractCode(), attachmentUrls);

	ProcessInstanceDetailResponse processInstanceDetailResponse = null;
	ContractAuditSceneEnum bpmScene = null;
	if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractInfo.getType())
		|| ContractTypeEnum.SETTLEMENT.getCode().equals(contractInfo.getType())
	) {
		// 补充协议或和解协议，走单独的 bpm 审批流发起
		processInstanceDetailResponse = supplementBpmService.applySupplementBpm(contractInfo);
		bpmScene = ContractAuditSceneEnum.DEFAULT;
	} else if (designFeeAuditService.isDesignScene(contractInfo.getType())) {
		// 设计合同超底场景，走设计费专项审批流
		if (designFeeAuditService.isDesignFeeExceedBottom(contractInfo)){
			processInstanceDetailResponse = designFeeAuditService.applyDesignFeeAuditBpm(contractInfo);
			bpmScene = ContractAuditSceneEnum.DESIGN_FEE;
		}
	} else {
		// 其他所有合同，走通用审批流
		processInstanceDetailResponse = applyContractBpm(contractInfo, customerName, projectAddress, attachmentUrls, changeRangeNamesAndReason, quotationType, companyName);
		bpmScene = ContractAuditSceneEnum.DEFAULT;
	}

	LOGGER.info("[contract_bpm_listener] - contractCode: {}, processInstanceDetailResponse: {}", contractInfo.getContractCode(), JSON.toJSONString(processInstanceDetailResponse));
	if (processInstanceDetailResponse == null || processInstanceDetailResponse.getData() == null) {
		LOGGER.error("[contract_bpm_listener] - " + JSON.toJSONString(processInstanceDetailResponse));
		throw new NrsBusinessException("[contract_bpm_listener] - bpm发起异常，返回数据为空");
	}

	String processInstId = processInstanceDetailResponse.getData().getProcess().getId();
	if (StringUtils.isEmpty(processInstId)) {
		LOGGER.error("[contract_bpm_listener] - processInstId is null：{}", contractInfo.getContractCode());
		throw new NrsBusinessException("bpm发起异常，返回数据为空");
	}

	//更新状态
	contractService.updateContractStatusAndBpmNo(contractInfo.getContractCode(), ContractStatusEnum.AUDITING.getCode().intValue(), processInstId);
	//新增记录
	contractAuditService.createContractAuditRecord(contractInfo.getContractCode(), processInstId, ContractAuditStatusEnum.CONTRACT_SUBMIT_AUDIT.getCode().byteValue(), bpmScene, contractInfo.getModifyUserId(), contractInfo.getCreateUserName());
	//合同日志
	contractLogService.createLog(contractInfo.getContractCode(), LogTypeEnum.SUBMIT_AUDIT.getCode(), LogTypeEnum.SUBMIT_AUDIT.getName(), assembleRemarkInfo(processInstId), contractInfo.getModifyUserId(), contractInfo.getModifyUserName());
	//合同节点日志
	contractNodeService.updateOrCreate(contractInfo.getContractCode(), NodeTypeEnum.LATEST_AUDIT_CREATE.getCode());
	//发送消息事件
	ContractEvent.ContractExtendInfo extendInfo = new ContractEvent.ContractExtendInfo();
	extendInfo.setBmpNo(processInstId);

	for (ContractRelation contractRelation : relationContractList) {
		Contract contract = contractService.getByContractCode(contractRelation.getRelateContractCode());
		//更新状态
		contractService.updateContractStatus(contract.getContractCode(), ContractStatusEnum.AUDITING.getCode());
		//新增记录
		contractAuditService.createContractAuditRecord(contract.getContractCode(), processInstId, ContractAuditStatusEnum.CONTRACT_SUBMIT_AUDIT.getCode().byteValue(), bpmScene, contractInfo.getModifyUserId(), contractInfo.getCreateUserName());
		//合同日志
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.SUBMIT_AUDIT.getCode(), LogTypeEnum.SUBMIT_AUDIT.getName(), assembleRemarkInfo(processInstId), contractInfo.getModifyUserId(), contractInfo.getModifyUserName());
		//合同节点日志
		contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.LATEST_AUDIT_CREATE.getCode());
	}

	eventService.publish(commonContractService.getContractEvent(contractInfo, extendInfo), EventType.CONTRACT_AUDIT_SUBMIT, contractInfo.getContractCode());
}

private ProcessInstanceDetailResponse applyContractBpm(Contract contractInfo, String customerName, String projectAddress, List<String> attachmentUrls, ChangeOrderInfoDTO changeRangeNamesAndReason, String quotationType, String companyName) {
	//获取审批人&校验审批人状态(审批人不能为空，且审批人状态为正常)
	BpmProcessVars vars = getBpmProcessVars(contractInfo);
	checkBpmApprover(vars, contractInfo);

	JSONObject record = new JSONObject();
	record.put("contractType", ContractTypeEnum.getNameByContractTypeAndBusinessType(contractInfo.getType(), contractInfo.getBusinessType()));
	record.put("projectOrderId", contractInfo.getProjectOrderId());
	record.put("customerName", customerName);
	record.put("projectAddress", projectAddress);
	record.put("contractAmount", contractInfo.getAmount().toString());
	record.put("attachmentUrls", JSON.toJSONString(attachmentUrls));
	record.put("changeRangeName", changeRangeNamesAndReason.getChangeScopeDesc());
	record.put("changeReason", changeRangeNamesAndReason.getChangeReason());
	//报价类型
	record.put("quotationType", quotationType);
	record.put("companyName", companyName);
	LOGGER.info("[contract_bpm_listener] - record bpm params：" + JSON.toJSONString(record) + "; contractCode=" + contractInfo.getContractCode());
	String userSystemId = StringUtils.isEmpty(contractInfo.getModifyUserId()) ? contractInfo.getCreateUserId() : contractInfo.getModifyUserId();
	// 发起人为空，直接返回
	if (StringUtils.isEmpty(userSystemId)) {
		LOGGER.error("[contract_bpm_listener] - 提审人不可为空[BPM]：contractCode:{}; modifyUserId:{}; createUserId:{}", contractInfo.getContractCode(), contractInfo.getModifyUserId(), contractInfo.getCreateUserId());
		return null;
	}

	BpmRequestDTO<Object, Object> requestDTO = BpmRequestDTO.builder()
		.processDefId(contractApolloConfig.getProcessDefId())
		.userSystemCode(getUserSystemCode(userSystemId))
		.boName(contractApolloConfig.getBoName())
		.processBusinessKey(IdGenerator.getContractBpmGeneratorId())
		.vars(vars)
		.recordData(record)
		.build();

	return bpmService.applyBpm(requestDTO);
}

private void checkBpmApprover(BpmProcessVars vars, Contract contractInfo) {
	if (Objects.isNull(vars)) {
		LOGGER.error("[contract_bpm_listener] - 节点人员信息不能为空[BPM], contractInfo:{}", contractInfo);
		throw new NrsBusinessException("[contract_bpm_listener] - 节点人员信息不能为空[BPM]");
	}
	ApproverInfo approverInfo = new ApproverInfo();
	BeanUtils.copyProperties(vars, approverInfo);
	if (approverInfo.isAllNodesEmpty()) {
		LOGGER.error("[contract_bpm_listener] - 节点人员配置信息都为空, contractInfo:{}", contractInfo);
		throw new NrsBusinessException("[contract_bpm_listener] - 节点人员信息不能为空[BPM]");
	}
	try {
		baseAuditChannel.checkUserState(approverInfo);
	} catch (Exception e) {
		LOGGER.error("[contract_bpm_listener] - 节点人员信息校验失败, contractInfo:{}", contractInfo, e);
		throw new NrsBusinessException("[contract_bpm_listener] - 节点人员信息校验失败");
	}
}

public BpmProcessVars getBpmProcessVars(Contract contract) {
	ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfig(contract);
	String projectOrderId = contract.getProjectOrderId();
	if (Objects.isNull(config)) {
		//因为pc只配置了一层，需要兼容一下
		List<ContractCityCompanyInfo> configList = contractCityCompanyConfigService.getConfig(projectOrderId, contract.getGbCode(), contract.getCompanyCode(), contract.getBusinessType(), contract.getType());
		config = configList.get(0);
	}
	List<AuditConfigDTO> auditConfigDTOList = contractCityCompanyInfoService.getAuditConfig(config);
	ProjectServerParam projectServerParam = new ProjectServerParam();
	projectServerParam.setProjectOrderId(Long.valueOf(contract.getProjectOrderId()));
	ResultDTO<List<ProjectServerInfoDTO>> projectOrderData = projectOrderQueryService.queryProjectServerInfo(projectServerParam);
	if (!projectOrderData.isSuccess()) {
		LOGGER.error("合同ID：{}; 施工侧请求异常或者数据为空; 订单id{}; 信息{};[BPM]", contract.getContractCode(), contract.getProjectOrderId(), projectOrderData.getMessage());
		return null;
	}
	List<ProjectServerInfoDTO> projectOrderList = projectOrderData.getData();
	Map<String, ProjectServerInfoDTO> serverMap = projectOrderData.getData().stream().collect(Collectors.toMap(ProjectServerInfoDTO::getType, Function.identity(), (k1, k2) -> k2));

	BpmProcessVars vars = BpmProcessVars.builder().build();

	//配置为空的话，走之前的老逻辑
	if (Objects.isNull(auditConfigDTOList)) {
		SystemsCodesDto systemsCodes = getNodesInfos(projectOrderList);
		if (systemsCodes.getGroupLeaderId().isEmpty() || systemsCodes.getBudgeterId().isEmpty()) {
			LOGGER.error("合同ID：{}; 施工侧请求异常或者数据为空; 订单id{}; 经营部经理系统号ID：{}; 预算员工系统号Id{}; 都不能为空[BPM]",
				contract.getContractCode(), projectOrderId, systemsCodes.getGroupLeaderId(), systemsCodes.getBudgeterId());
			return null;
		}
		vars.setFixedNodes1(systemsCodes.getGroupLeaderId());
		vars.setFixedNodes2(systemsCodes.getBudgeterId());
	} else {
		//新逻辑按照配置处理
		for (int i = 0; i < auditConfigDTOList.size(); i++) {
			AuditConfigDTO auditConfigDTO = auditConfigDTOList.get(i);
			String userCode = "";
			if (AuditConfigNodeTypeEnum.CONST.getCode().equals(auditConfigDTO.getNodeType())) {
				userCode = auditConfigDTO.getNodeValue();
			} else if (AuditConfigNodeTypeEnum.ROLE.getCode().equals(auditConfigDTO.getNodeType())) {
				if (!serverMap.containsKey(auditConfigDTO.getNodeValue())) {
					LOGGER.error("发起合同审批失败，获取不到服务者角色:{},contractCode:{}", auditConfigDTO.getNodeValue(), contract.getContractCode());
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "发起审批失败，获取不到服务者角色:" + auditConfigDTO.getNodeValue());
				}
				userCode = getUserSystemCode(serverMap.get(auditConfigDTO.getNodeValue()).getUcId().toString());
			}

			switch (i) {
				case 0:
					vars.setFixedNodes1(userCode);
					break;
				case 1:
					vars.setFixedNodes2(userCode);
					break;
				case 2:
					vars.setFixedNodes3(userCode);
					break;
				case 3:
					vars.setFixedNodes4(userCode);
					break;
				case 4:
					vars.setFixedNodes5(userCode);
					break;
				case 5:
					vars.setFixedNodes6(userCode);
					break;
				default:
					break;
			}
		}
	}

	return vars;
}

public SystemsCodesDto getNodesInfos(List<ProjectServerInfoDTO> projectOrderList) {
	String groupLeaderId = "";//展厅经理-经营部经理
	String budgeterId = "";//预算员
	for (ProjectServerInfoDTO projectServerInfoDTO : projectOrderList) {
		String type = projectServerInfoDTO.getType();
		Long ucid = projectServerInfoDTO.getUcId();
		if (ucid.equals(0L)) {
			continue;
		}
		if (type.equals(ServerTypeEnum.GROUP_LEADER.getType())) {
			groupLeaderId = ucid.toString();
		}
		if (type.equals(ServerTypeEnum.BUDGETER.getType())) {
			budgeterId = ucid.toString();
		}
	}

	if (groupLeaderId.isEmpty() || budgeterId.isEmpty()) {
		LOGGER.error("经营部经理ID：{}; 预算员工Id{}; 都不能为空[BPM]", groupLeaderId, budgeterId);
		return null;
	}

	List<String> ucids = new LinkedList<>();
	ucids.add(groupLeaderId);
	ucids.add(budgeterId);
	// 请求member获取系统号
	List<UserRepresentationDTO> userRepresentationDTOList = memberApi.batchQueryUserByUcId(ucids);
	if (userRepresentationDTOList.isEmpty()) {
		new NrsBusinessException("请求Member服务获取系统号失败，接口返回数据：" + JSON.toJSONString(userRepresentationDTOList));
	}
	SystemsCodesDto systemsCodes = new SystemsCodesDto();
	for (UserRepresentationDTO userRepresentationDTO : userRepresentationDTOList) {
		userRepresentationDTO.getIdentities().get("user_code");
		if (userRepresentationDTO.getId().equals(groupLeaderId)) {
			systemsCodes.setGroupLeaderId(userRepresentationDTO.getIdentities().get("user_code"));
		}
		if (userRepresentationDTO.getId().equals(budgeterId)) {
			systemsCodes.setBudgeterId(userRepresentationDTO.getIdentities().get("user_code"));
		}
	}

	return systemsCodes;
}

public String getUserSystemCode(String ucid) {
	// 请求member获取系统号
	List<UserRepresentationDTO> userRepresentationDTOList = memberApi.batchQueryUserByUcId(Collections.singletonList(ucid));
	String userSystemCode = Optional.ofNullable(userRepresentationDTOList)
		.map(Collection::stream)
		.map(Stream::findFirst)
		.map(Optional::get)
		.map(UserRepresentationDTO::getIdentities)
		.map(identities -> identities.get("user_code"))
		.orElseThrow(() -> new NrsBusinessException("请求Member服务获取系统号失败，接口返回数据：" + JSON.toJSONString(userRepresentationDTOList)));

	return userSystemCode;
}

@SneakyThrows
@Transactional
public void dealContractResultForBpm(ProcessEventModel processEventModel, BpmStatusEnum bpmStatusEnum, ContractAuditSceneEnum auditScene) {
	String processInstId = processEventModel.getProcessInstId();
	boolean auditResult = BpmStatusEnum.getBooleanResult(bpmStatusEnum);
	boolean terminateResult = BpmStatusEnum.getTerminateBooleanResult(bpmStatusEnum);
	Contract contractInfo = contractService.getContractInfoByProcessInstId(processInstId);

	if (Objects.isNull(contractInfo) || !contractInfo.getStatus().equals(ContractStatusEnum.AUDITING.getCode())) {
		return;
	}

	Integer updateStatus = -1;
	Byte logType = -1;
	Byte nodeStatus = -1;
	Byte contractAuditStatus = -1;
	Boolean isOnLine = contractInfo.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode());
	List<ContractRelation> relationContractList = contractRelationService.getRelationList(contractInfo.getContractCode());
	if (auditResult) {//通过
		contractInfo.setUserQueryStatus(UserQueryStatusEnum.VALID.getCode());
		if (Boolean.TRUE.equals(isOnLine)) {
			if (contractInfo.getAuditType().equals(AuditTypeEnum.BEFORE_SIGN.getCode())) {//签前,更新为待用户签署
				// 需要确认的合同类型
				List<Byte> confirmTypes = Arrays.asList(
					// 套餐变更协议
					ContractTypeEnum.PACKAGE_CHANGE.getCode(),
					// 补充协议
					ContractTypeEnum.SUPPLEMENT.getCode(),
					// 和解协议
					ContractTypeEnum.SETTLEMENT.getCode()
				);
				updateStatus = setStatusByConfirmsAndSignType(confirmTypes, contractInfo);
			} else if (contractInfo.getAuditType().equals(AuditTypeEnum.AFTER.getCode())) {
				// 签后,更新为待盖公司章
				updateStatus = ContractStatusEnum.PENDING_COMPANY_SIGN.getCode();
			} else if (contractInfo.getAuditType().equals(AuditTypeEnum.NONE.getCode())
			&& designFeeAuditService.isDesignFeeExceedBottom(contractInfo)) {
				// 需要确认的合同类型
				List<Byte> confirmTypes = Arrays.asList(
					// 设计协议
					ContractTypeEnum.DESIGN.getCode(),
					// 设计变更协议
					ContractTypeEnum.DESIGN_CHANGE.getCode()
				);
				// 如果是不需要审核，且是设计费超底场景，那么设置逻辑和签前保持一致
				updateStatus = setStatusByConfirmsAndSignType(confirmTypes, contractInfo);
			}
		} else {//如果是线下，那么直接变更到已签署
			updateStatus = ContractStatusEnum.FINISH.getCode();
			//记录日志&时间&消息
			contractLogService.createLog(contractInfo.getContractCode(), LogTypeEnum.FINISH.getCode(), LogTypeEnum.FINISH.getName());
			contractNodeService.updateOrCreate(contractInfo.getContractCode(), NodeTypeEnum.FINISH.getCode());
			eventService.publish(commonContractService.getContractEvent(contractInfo), EventType.CONTRACT_FINISH, contractInfo.getContractCode());
		}

		logType = LogTypeEnum.AUDIT_PASS.getCode();
		nodeStatus = NodeTypeEnum.LATEST_AUDIT_PASS.getCode();
		contractAuditStatus = ContractAuditStatusEnum.CONTRACT_AUDIT_PASS.getCode().byteValue();
	}
	if (terminateResult) {//审批驳回
		List<Byte> auditRejectTypes = Arrays.asList(ContractTypeEnum.PERSONAL.getCode(), ContractTypeEnum.SUPPLEMENT.getCode());
		if (auditRejectTypes.contains(contractInfo.getType())) {
			// 销售合同、补充协议审批驳回后
			updateStatus = ContractStatusEnum.AUDIT_REJECT.getCode();
		} else {
			updateStatus = ContractStatusEnum.DRAFT.getCode();
		}
		logType = LogTypeEnum.AUDIT_REJECT.getCode();
		nodeStatus = NodeTypeEnum.LATEST_AUDIT_REJECT.getCode();
		contractAuditStatus = ContractAuditStatusEnum.CONTRACT_AUDIT_REJECT.getCode().byteValue();

		//回滚用户状态
		contractInfo.setUserSignStatus(CommonEnum.NO.getCode());
		contractInfo.setUserConfirmStatus(CommonEnum.NO.getCode());
		//pdf key
		contractInfo.setUserSignedKey("");
		contractInfo.setBothSignedKey("");
		//解除绑定关系
		if (ContractTypeEnum.PERSONAL.getCode().equals(contractInfo.getType())) {
			quotationRelationCommonService.cancelContractRelations(contractInfo.getContractCode());
		}
		if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractInfo.getType())) {
			// 对公场景：补充协议驳回后，解除与授权协议的关联关系
			contractInfo.setRelateContractCode("");
			int deleted = contractRelationService.deleteRelationByContractCodes(Lists.newArrayList(contractInfo.getContractCode()));
			if (deleted > 0) {
				LOGGER.info("合同审核驳回 删除补充协议关联关系 contractCode:{}", contractInfo.getContractCode());
			}
		}
	}
	contractInfo.setStatus(updateStatus);
	contractInfo.setMtime(new Date());
	contractService.updateUnchecked(contractInfo);
	contractLogService.createLog(contractInfo.getContractCode(), logType, LogTypeEnum.getNameByCode(logType), assembleRemarkInfo(processInstId), "", "审核相关人员");
	//合同节点日志
	contractNodeService.updateOrCreate(contractInfo.getContractCode(), nodeStatus);
	//新增记录
	contractAuditService.createContractAuditRecord(contractInfo.getContractCode(), processInstId, contractAuditStatus, auditScene, contractInfo.getCreateUserId(), contractInfo.getCreateUserName());

	if (auditResult) {//通过
		eventService.publish(commonContractService.getContractEvent(contractInfo), EventType.CONTRACT_AUDIT_PASS, contractInfo.getContractCode());
	}
	if (terminateResult) {//驳回
		eventService.publish(commonContractService.getContractEvent(contractInfo), EventType.CONTRACT_AUDIT_REJECT, contractInfo.getContractCode());
	}

	for (ContractRelation contractRelation : relationContractList) {
		Contract contract = contractService.getByContractCode(contractRelation.getRelateContractCode());
		if (auditResult) {
			contract.setUserQueryStatus(UserQueryStatusEnum.VALID.getCode());
		}
		contract.setStatus(updateStatus);
		contract.setMtime(new Date());
		contractService.updateUnchecked(contract);
		contractLogService.createLog(contract.getContractCode(), logType, LogTypeEnum.getNameByCode(logType), assembleRemarkInfo(processInstId), "", "审核相关人员");
		//合同节点日志
		contractNodeService.updateOrCreate(contract.getContractCode(), nodeStatus);

		if (auditResult) {//通过
			eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_AUDIT_PASS, contract.getContractCode());
			if (ContractStatusEnum.FINISH.getCode().equals(updateStatus)) {
				//记录日志&时间&消息
				contractLogService.createLog(contract.getContractCode(), LogTypeEnum.FINISH.getCode(), LogTypeEnum.FINISH.getName());
				contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.FINISH.getCode());
				eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_FINISH, contract.getContractCode());
			}
		}
		if (terminateResult) {//驳回
			eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_AUDIT_REJECT, contract.getContractCode());
		}
	}

}

public String generatePdf(Contract contract, Map<String, Object> formData) {
	ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfigByContractType(contract);
	if (Objects.isNull(config) || Objects.isNull(config.getFormId()) || Objects.isNull(config.getFormKey())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同配置缺少对应的协议平台板式key/id");
	}

	LOGGER.info("生成pdf入参:{} {}", contract.getContractNo(), JsonUtil.toJsonString(formData));

	String formKey = config.getFormKey();
	Integer formId = config.getFormId();
	Long createUserId = Long.valueOf(contract.getCreateUserId());

	if (StringUtils.isBlank(contract.getContractNo())) {
		contract.setContractNo(RandomCodeUtils.generateContractNo());
	}

	//创建实例
	contract.setPlatformInstanceId(freeformService.createInstance(formKey, createUserId));
	//提交表单
	freeformService.submit(contract.getPlatformInstanceId(), contract.getContractNo(), createUserId, formData);
	Boolean addWaterMark = false;
	String markText = "";
	//生成pdf
	AttachmentInfo pdfInfo = freeformService.createPdf(contract.getPlatformInstanceId(), createUserId, formId.longValue(), null, addWaterMark, markText);
	contract.setPreviewKey(s3Service.upload(pdfInfo.getUrl()));
	contract.setPdfPageCount(pdfInfo.getPdfPageCount());

	LOGGER.info("生成pdf结果:{}", pdfInfo.getUrl());

	return s3Service.generateUrl(contract.getPreviewKey(), 1800);
}

