public boolean checkCompanyInfo(String companyName, String companyCreditCode, String legalName, Byte signChannelType) {
	if ("北区测试公司".equals(companyName) || Boolean.FALSE.equals(contractApolloConfig.getCompanyInfoCheck())) {
		return true;
	}
	CompanyBaseInfoResDTO companyBaseInfo = commonBusinessService.getCompanyBaseInfo(companyName);

	if (companyBaseInfo == null) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "根据统一社会信用代码未查询到公司信息，请重新核对信息");
	}

	if (!companyName.equals(companyBaseInfo.getCompanyName()) || !companyCreditCode.equals(companyBaseInfo.getTaxNumber())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "企业名称与统一社会信用代码无法匹配，请修改");
	}

	//对公合同&线上签署校验：法定代表人姓名与企业名称是否匹配
	if (SignChannelTypeEnum.ONLINE.getCode().equals(signChannelType) && !Objects.equals(legalName, companyBaseInfo.getLegalName())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "企业名称与法定代表人姓名无法匹配，请修改");
	}

	return true;
}

public Integer computeGroupSignStatus(List<Contract> contractList, List<Byte> groupTypeList, Boolean mergeLaunchDesignContract) {
	contractList = contractList.stream().filter(contract -> ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus())).filter(m -> {
		if (ContractTypeEnum.PERSONAL.getCode().equals(m.getType())) {
			return !homeAndPcCommonService.isMultipleQuotePersonalContract(m) && ObjectUtil.isEmpty(m.getChangeOrderId());
		} else if (ContractTypeEnum.DESIGN.getCode().equals(m.getType())) {
			return mergeLaunchDesignContract;
		}
		return true;
	}).collect(Collectors.toList());
	for (Byte type : groupTypeList) {
		Contract contract = contractList.stream().filter(item -> type.equals(item.getType())).findFirst().orElse(null);
		if (contract == null) {
			continue;
		}
		if (!ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
			return contract.getStatus();
		}
	}
	return ContractStatusEnum.FINISH.getCode();
}

public List<Contract> getRelationContract(String contractCode) {
