public boolean isSealTaskAllowed(String contractCode) {
	try {
		//获取合同最近一次的发起时间
		ContractNode contractNode = contractNodeService.getListByContractCode(contractCode).stream().filter(item -> item.getNodeType().equals(NodeTypeEnum.SUBMIT.getCode())).max(Comparator.comparing(ContractNode::getCtime)).orElse(null);
		//计算合同最近一次的发起时间距离当前时间的时间差
		long calculated = System.currentTimeMillis() - contractNode.getFireTime();
		return calculated <= 60 * 1000 * 2;
	} catch (Exception e) {
		LOGGER.error("contractCode:{},计算合同最近一次的发起时间距离当前时间的时间差发生异常:{}", contractCode, e.getMessage());
		return false;
	}
}

