public ContractSignUrlVo getContractRealNameVerifyInfo(String contractCode){
	// 获取合同信息
	Contract contract = contractService.getByContractCode(contractCode);
	if (contract == null) {
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "当前合同不存在，请联系服务者确认操作是否正确", Level.WARN);
	}
	ContractUser signer = contractUserService.getSignerByContractCode(contractCode);
	if (signer == null) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人-[签约]");
