	public ContractCityCompanyInfo getConfigByContractType(Contract contract) {
		//「资金存管协议」：如果只有四方协议，则将四方配置在数据库；如果三方、四方共存，则将三方协议配置在数据库，四方配置在 apollo。取得时候，会先从数据库取，如果 apollo 存在，则使用 apollo 的覆盖
		//「其他类型合同」：从数据库获取对应合同模板
		// 先从数据库查出合同模板
		ContractCityCompanyInfo config = getConfig(contract);
		// zqy 日志-测试用
		LOGGER.info("获取合同模板，第一次从数据库查询 config: {}", config);

		// 正签和销售合同，在团装 2.5 场景下， 需要根据支付模式的不同来获取对应的合同模板
		String projectOrderId = contract.getProjectOrderId();
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contract.getType());
		Byte businessType = contract.getBusinessType();
		List<Byte> groupV25ContractType = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PERSONAL.getCode());
		List<Byte> houseContractType = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.ADVANCE.getCode(), ContractTypeEnum.PERSONAL.getCode());

		// 如果合同类型为「资金存管协议」&&「开启零售存管」，判断 Apollo 是否存在「四方协议」，如果存在，则使用 Apollo 配置的模板协议
		if (ContractTypeEnum.FUND_ESCROW.getCode().equals(contract.getType())) {

			// zqy 日志-测试用
			LOGGER.info("「零售存管」:资金存管获取「三方协议」或「四方协议」, contractType: {}, gbCode: {}, companyCode: {}, businessType: {}", contract.getType(), contract.getGbCode(), contract.getCompanyCode(), contract.getBusinessType());

			// 判断是否开启「零售存管」
			List<ContractCompanyAspectInfo> contractCompanyList = ContractContextHandler.getContext().getContractCompanyList();
			Optional<ContractCompanyAspectInfo> retailContractCompanyAspectInfoOpt = Optional.ofNullable(contractCompanyList)
				.orElse(Collections.emptyList())
				.stream()
				.filter(contractCompanyAspectInfo -> ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(contractCompanyAspectInfo.getDecorateBusinessType()))
				.findFirst();

			// 未开启「零售存管」，返回从数据库里获取的模板协议
			if (!retailContractCompanyAspectInfoOpt.isPresent()) {
				return config;
			}

			// 开启「零售存管」，从 apollo 取四方协议
			Integer gbCode = contract.getGbCode();
			String companyCode = contract.getCompanyCode();
			// 遍历查找对应的四方协议, 查询维度: gbCode、companyCode、businessType
			Optional<FourPartyProtocolConfig> fourPartyProtocolOpt = contractApolloConfig.getFourPartyProtocols().stream()
				.filter(fourPartyProtocolConfig -> gbCode.equals(fourPartyProtocolConfig.getGbCode()) && companyCode.equals(fourPartyProtocolConfig.getCompanyCode()) && businessType.equals(fourPartyProtocolConfig.getBusinessType()))
				.findFirst();
			LOGGER.info("「零售存管」：apollo 配置信息:{}", contractApolloConfig.getFourPartyProtocols());
			// apollo 配置的四方协议不存在，则返回从数据库里获取的模板协议
			if (!fourPartyProtocolOpt.isPresent()) {
				return config;
			}
			FourPartyProtocolConfig fourPartyProtocolConfig = fourPartyProtocolOpt.get();
			config.setFormId(fourPartyProtocolConfig.getFormId());
			config.setFormKey(fourPartyProtocolConfig.getFormKey());
			// zqy 日志-测试用
			LOGGER.info("开启了「零售存管」,config: {}", config);
		} else if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25 && groupV25ContractType.contains(contract.getType())) {
			// 团装 2.5 场景下，需要处理（正签||销售）合同，判断是否需要取支付模式 B+C 的合同模板
			boolean bOrBCPaymentType = commonBusinessService.isBOrBCPaymentType(projectOrderId);
			// 团装 2.5 场景 && 支付模式为（B || B+C），则合同模板需要取 secondFormId、secondFormKey
			if (bOrBCPaymentType) {
				// 判断 secondFormId、secondFormKey 是否存在，如果不存在对应模板，则直接抛出异常
				if (config.getSecondFormId() == null || config.getSecondFormId() == 0 || StringUtils.isEmpty(config.getSecondFormKey())) {
					throw new NrsBusinessException(ResultCodeEnum.ERROR_NO_DATA.getCode(), String.format("团装 2.5 场景下对应的合同模板为空, 城市:%s,分公司:%s, 业务类型:%s", contract.getGbCode(), contract.getCompanyCode(), businessType), Level.ERROR);
				}
				LOGGER.info("团装 2.5 下的 B/B+C 支付模式使用 secondFormId: {}、secondFormKey: {} 的合同模板, projectOrderId: {}", config.getSecondFormId(), config.getSecondFormKey(), projectOrderId);
				config.setFormId(config.getSecondFormId());
				config.setFormKey(config.getSecondFormKey());
			}
		} else if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType) && processV25 && houseContractType.contains(contract.getType())) {
			if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
				boolean bOrBCCombo = contractBusinessService.isBOrBCCombo(ContractContextHandler.getContext().getComboDTOList(), projectOrderId);
				if (bOrBCCombo) {
					if (isFormEmpty(config.getSecondFormKey(), config.getSecondFormId())) {
						throw new NrsBusinessException(ResultCodeEnum.ERROR_NO_DATA.getCode(), String.format("整装场景，正签合同下对应的B+C合同模板为空, 城市:%s,分公司:%s, 业务类型:%s", contract.getGbCode(), contract.getCompanyCode(), businessType), Level.ERROR);
					}
					config.setFormId(config.getSecondFormId());
					config.setFormKey(config.getSecondFormKey());
					LOGGER.info("整装场景下，正签合同B+C套餐，使用B+C合同模式 secondFormId: {}、secondFormKey: {} 的合同模板, projectOrderId: {}", config.getSecondFormId(), config.getSecondFormKey(), projectOrderId);
					return config;
				}
			}
			if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
				// 根据单据号判断是否存在 B 部分的品
				BindOrderInfoGroup group = getBindOrderGroupByContract(contract);
				boolean hasBPart = group.getBindOrderInfos().stream()
					.anyMatch(bindOrderInfo -> contractSigningSourceRouter.route(bindOrderInfo.getBindType()).hasBPart(bindOrderInfo));
				LOGGER.info("整装场景下，销售合同判断个性化报价单中是否包含B部分, projectOrderId: {}, bindOrderInfos: {}, personalBillListHasBPart: {}", projectOrderId, JSON.toJSONString(group.getBindOrderInfos()), hasBPart);
				if (hasBPart) {
					if (isFormEmpty(config.getSecondFormKey(), config.getSecondFormId())) {
						throw new NrsBusinessException(ResultCodeEnum.ERROR_NO_DATA.getCode(), String.format("整装场景，销售合同下对应的B+C合同模板为空, 城市:%s,分公司:%s, 业务类型:%s", contract.getGbCode(), contract.getCompanyCode(), businessType), Level.ERROR);
					}
					config.setFormId(config.getSecondFormId());
					config.setFormKey(config.getSecondFormKey());
					return config;
				}
			}
			if (ContractTypeEnum.ADVANCE.getCode().equals(contract.getType())) {
				// 非预报价场景才判断B+C套餐版式
				if (!contractUnifyService.advanceSupportPreQuotation(projectOrderId, ContractTypeEnum.ADVANCE.getCode())) {
					// getConfigByContractType() 方法进入的时机不止生成合同，还有用户协议确认，所以从上下文数据域取数据会空指针
					// 用户协议确认场景下，上下文数据域未初始化，使用 Optional 避免空指针
					String packageId = Optional.ofNullable(ContractContextHandler.getContext())
							.map(ContractContext::getContractReq)
							.map(ContractReqDTO::getProjectInfo)
							.map(ContractProjectInfoReq::getPackageId)
							.orElse(null);
					Integer purchaseType = Optional.ofNullable(ContractContextHandler.getContext())
							.map(ContractContext::getContractReq)
							.map(ContractReqDTO::getProjectInfo)
							.map(ContractProjectInfoReq::getPurchaseType)
							.orElse(null);
					// 数据域没获取到，说明不是发起合同的入口，而是用户协议确认的入口，需要兼容从 contract_field 表获取
					if (StringUtils.isBlank(packageId)) {
						ContractField packageIdField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), ContractProjectInfoReq.Fields.packageId);
						if (packageIdField != null && StringUtils.isNotBlank(packageIdField.getFieldValue())) {
							packageId = packageIdField.getFieldValue();
							LOGGER.info("用户协议确认场景进入，从合同字段表获取 packageId: {}", packageId);
						}
					}
					// 数据域没获取到，说明不是发起合同的入口，而是用户协议确认的入口，需要兼容从 contract_field 表获取
					if (purchaseType == null) {
						ContractField purchaseTypeField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), ContractProjectInfoReq.Fields.purchaseType);
						if (purchaseTypeField != null && StringUtils.isNotBlank(purchaseTypeField.getFieldValue())) {
							purchaseType = Integer.valueOf(purchaseTypeField.getFieldValue());
							LOGGER.info("用户协议确认场景进入，从合同字段表获取 purchaseType: {}", purchaseType);
						}
					}
					if (PurchaseTypeEnum.B.getCode().equals(purchaseType) || PurchaseTypeEnum.BC.getCode().equals(purchaseType)) {
						if (isFormEmpty(config.getSecondFormKey(), config.getSecondFormId())) {
							throw new NrsBusinessException(ResultCodeEnum.ERROR_NO_DATA.getCode(), String.format("整装场景，首期款合同下对应的B+C合同模板为空, 城市:%s,分公司:%s, 业务类型:%s", contract.getGbCode(), contract.getCompanyCode(), businessType), Level.ERROR);
						}
						config.setFormId(config.getSecondFormId());
						config.setFormKey(config.getSecondFormKey());
						LOGGER.info("整装场景下，首期款合同B+C套餐，使用B+C合同模板 secondFormId: {}、secondFormKey: {}, projectOrderId: {}", config.getSecondFormId(), config.getSecondFormKey(), projectOrderId);
						return config;
					}
				}
			}
			NewHousingProjectModule newHousingProjectModule=commonBusinessService.getNewHousingProjectInfoByProjectOrderId(projectOrderId);
			LOGGER.info("判断是否获取开渠合同模板, 业务类型:{}, contractType: {}, 是否存在新房项目: {}, projectOrderId: {}", businessType, contract.getType(), newHousingProjectModule != null, projectOrderId);
			// 如果不属于上面情况【正签合同套餐不是B、B+C套餐】，【销售合同新房项目支付方式不是B、B+C】
			// 并且存在新房项目，获取开渠合同模板 thirdFormKey
			if (FormTypeEnum.isUseThirdForm(businessType, contract.getType(), newHousingProjectModule, processV25)) {
				if (isFormEmpty(config.getThirdFormKey(), config.getThirdFormId())) {
					throw new NrsBusinessException(ResultCodeEnum.ERROR_NO_DATA.getCode(), String.format("整装场景下对应的合同模板为空, 城市:%s,分公司:%s, 业务类型:%s", contract.getGbCode(), contract.getCompanyCode(), businessType), Level.ERROR);
				}
				LOGGER.info("整装场景下，开渠客源使用 thirdFormId: {}、thirdFormKey: {} 的合同模板, projectOrderId: {}", config.getThirdFormId(), config.getThirdFormKey(), projectOrderId);
				config.setFormId(config.getThirdFormId());
				config.setFormKey(config.getThirdFormKey());
			}
		}
		return config;
	}

	public  List<String> getBillCodeListSafe(Contract contract) {
		//协议确认场景，需要从合同报价关联关系表获取报价单列表
		if (ContractStatusEnum.USER_CONFIRMED.getCode().equals(contract.getStatus())) {
			List<String> billCodeList = quotationRelationCommonService.getBillCodeListByContractCode(contract.getContractCode());
			if (CollectionUtils.isEmpty(billCodeList)) {
				return Collections.emptyList();
			}
			return billCodeList;
		}
		ContractContext context = ContractContextHandler.getContext();
		if (context == null) {
			return Collections.emptyList();
		}

		ContractReqDTO req = context.getContractReq();
		if (req == null || req.getBusinessInfo() == null) {
			return Collections.emptyList();
		}

		List<BillCodeInfo> billCodeInfoList = req.getBusinessInfo().getBillCodeInfoList();
		if (CollectionUtils.isEmpty(billCodeInfoList)) {
			return Collections.emptyList();
		}
		return billCodeInfoList.stream()
			.map(BillCodeInfo::getBillCode)
			.collect(Collectors.toList());
	}

	/**
	 * 获取合同绑定的单据
	 */
	public BindOrderInfoGroup getBindOrderGroupByContract(Contract contract) {

		// 申请用章场景，入参没有单据号，需要从数据库拿
		if (ContractStatusEnum.USER_CONFIRMED.getCode().equals(contract.getStatus())) {
			return quotationRelationCommonService.getBindOrderInfoGroupByContractCode(contract.getContractCode());
		}

		// 其他场景，直接从入参拿单据号
		ContractContext context = ContractContextHandler.getContext();
		if (context == null) {
			return BindOrderInfoGroup.builder().build();
		}

		ContractReqDTO req = context.getContractReq();
		if (req == null || req.getBusinessInfo() == null) {
			return BindOrderInfoGroup.builder().build();
		}

		List<BillCodeInfo> billCodeInfoList = req.getBusinessInfo().getBillCodeInfoList();
		List<SubOrderInfo> subOrderInfoList = req.getBusinessInfo().getSubOrderInfoList();
		List<ChangeOrderInfo> changeOrderInfoList = req.getBusinessInfo().getChangeOrderInfoList();
		return BindOrderInfoGroup.convert(contract.getProjectOrderId(), subOrderInfoList, billCodeInfoList, changeOrderInfoList);
	}


	public List<String> getCompanyCodeByContractType(ProjectInfo projectInfo, Byte contractType) {
		Integer gbCode = commonBusinessService.getGbCode(projectInfo.getProjectOrderId());
		Byte businessType = commonBusinessService.getBusinessType(projectInfo.getProjectOrderId());
		//查询对应订单的配置
		List<ContractCityCompanyInfo> configList = getConfig(projectInfo.getProjectOrderId(), gbCode, businessType, contractType);
		if (CollectionUtil.isEmpty(configList)) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "未配置分公司主体信息，请提交工单反馈", Level.WARN);
		}
		List<String> companyCodeList = configList.stream().filter(ObjectUtil::isNotEmpty).map(ContractCityCompanyInfo::getCompanyCode).collect(Collectors.toList());
		if (companyCodeList.contains(contractApolloConfig.getCompanyCodeMode2_5())) {
			String companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectInfo.getProjectOrderId());

			//移除csmock
			if (StringUtils.isNotBlank(companyCode)) {
				companyCodeList.add(companyCode);
			}
			companyCodeList.remove(contractApolloConfig.getCompanyCodeMode2_5());
		}
		return companyCodeList;
	}

	/**
	 * 判断合同模板是否为空，如果 formKey 和 formId 任一为空，则需要拦截签约发起
	 */
	public boolean isFormEmpty(String formKey, Integer formId) {
		return formId == null || formId == 0 || StringUtils.isEmpty(formKey);
	}


}

public ContractCityCompanyInfo getConfig(String projectOrderId, Integer gbCode, String companyCode, Byte businessType, Byte contractType, Byte signChannelType, Byte userSignType) {
	String convertProjectOrderId = commonBusinessService.convertProjectOrderId(projectOrderId, contractType);
	Integer version = contractConfigVersionService.getCityCompanyInfoVersion(convertProjectOrderId);
	companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectOrderId, gbCode, companyCode, contractType);
	return contractCityCompanyInfoService.getConfig(gbCode, companyCode, businessType, contractType, signChannelType, userSignType, version);
}

public ContractCityCompanyInfo getConfigByContractType(Contract contract) {
	//「资金存管协议」：如果只有四方协议，则将四方配置在数据库；如果三方、四方共存，则将三方协议配置在数据库，四方配置在 apollo。取得时候，会先从数据库取，如果 apollo 存在，则使用 apollo 的覆盖
	//「其他类型合同」：从数据库获取对应合同模板
	// 先从数据库查出合同模板
	ContractCityCompanyInfo config = getConfig(contract);
	// zqy 日志-测试用
	LOGGER.info("获取合同模板，第一次从数据库查询 config: {}", config);

	// 正签和销售合同，在团装 2.5 场景下， 需要根据支付模式的不同来获取对应的合同模板
	String projectOrderId = contract.getProjectOrderId();
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contract.getType());
	Byte businessType = contract.getBusinessType();
	List<Byte> groupV25ContractType = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PERSONAL.getCode());
	List<Byte> houseContractType = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.ADVANCE.getCode(), ContractTypeEnum.PERSONAL.getCode());

	// 如果合同类型为「资金存管协议」&&「开启零售存管」，判断 Apollo 是否存在「四方协议」，如果存在，则使用 Apollo 配置的模板协议
	if (ContractTypeEnum.FUND_ESCROW.getCode().equals(contract.getType())) {

		// zqy 日志-测试用
		LOGGER.info("「零售存管」:资金存管获取「三方协议」或「四方协议」, contractType: {}, gbCode: {}, companyCode: {}, businessType: {}", contract.getType(), contract.getGbCode(), contract.getCompanyCode(), contract.getBusinessType());

		// 判断是否开启「零售存管」
		List<ContractCompanyAspectInfo> contractCompanyList = ContractContextHandler.getContext().getContractCompanyList();
		Optional<ContractCompanyAspectInfo> retailContractCompanyAspectInfoOpt = Optional.ofNullable(contractCompanyList)
			.orElse(Collections.emptyList())
			.stream()
			.filter(contractCompanyAspectInfo -> ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(contractCompanyAspectInfo.getDecorateBusinessType()))
			.findFirst();

		// 未开启「零售存管」，返回从数据库里获取的模板协议
		if (!retailContractCompanyAspectInfoOpt.isPresent()) {
			return config;
		}

		// 开启「零售存管」，从 apollo 取四方协议
		Integer gbCode = contract.getGbCode();
		String companyCode = contract.getCompanyCode();
		// 遍历查找对应的四方协议, 查询维度: gbCode、companyCode、businessType
		Optional<FourPartyProtocolConfig> fourPartyProtocolOpt = contractApolloConfig.getFourPartyProtocols().stream()
			.filter(fourPartyProtocolConfig -> gbCode.equals(fourPartyProtocolConfig.getGbCode()) && companyCode.equals(fourPartyProtocolConfig.getCompanyCode()) && businessType.equals(fourPartyProtocolConfig.getBusinessType()))
			.findFirst();
		LOGGER.info("「零售存管」：apollo 配置信息:{}", contractApolloConfig.getFourPartyProtocols());
		// apollo 配置的四方协议不存在，则返回从数据库里获取的模板协议
		if (!fourPartyProtocolOpt.isPresent()) {
			return config;
		}
		FourPartyProtocolConfig fourPartyProtocolConfig = fourPartyProtocolOpt.get();
		config.setFormId(fourPartyProtocolConfig.getFormId());
		config.setFormKey(fourPartyProtocolConfig.getFormKey());
		// zqy 日志-测试用
		LOGGER.info("开启了「零售存管」,config: {}", config);
	} else if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25 && groupV25ContractType.contains(contract.getType())) {
		// 团装 2.5 场景下，需要处理（正签||销售）合同，判断是否需要取支付模式 B+C 的合同模板
		boolean bOrBCPaymentType = commonBusinessService.isBOrBCPaymentType(projectOrderId);
		// 团装 2.5 场景 && 支付模式为（B || B+C），则合同模板需要取 secondFormId、secondFormKey
		if (bOrBCPaymentType) {
			// 判断 secondFormId、secondFormKey 是否存在，如果不存在对应模板，则直接抛出异常
			if (config.getSecondFormId() == null || config.getSecondFormId() == 0 || StringUtils.isEmpty(config.getSecondFormKey())) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_NO_DATA.getCode(), String.format("团装 2.5 场景下对应的合同模板为空, 城市:%s,分公司:%s, 业务类型:%s", contract.getGbCode(), contract.getCompanyCode(), businessType), Level.ERROR);
			}
			LOGGER.info("团装 2.5 下的 B/B+C 支付模式使用 secondFormId: {}、secondFormKey: {} 的合同模板, projectOrderId: {}", config.getSecondFormId(), config.getSecondFormKey(), projectOrderId);
			config.setFormId(config.getSecondFormId());
			config.setFormKey(config.getSecondFormKey());
		}
	} else if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType) && processV25 && houseContractType.contains(contract.getType())) {
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
			boolean bOrBCCombo = contractBusinessService.isBOrBCCombo(ContractContextHandler.getContext().getComboDTOList(), projectOrderId);
			if (bOrBCCombo) {
				if (isFormEmpty(config.getSecondFormKey(), config.getSecondFormId())) {
					throw new NrsBusinessException(ResultCodeEnum.ERROR_NO_DATA.getCode(), String.format("整装场景，正签合同下对应的B+C合同模板为空, 城市:%s,分公司:%s, 业务类型:%s", contract.getGbCode(), contract.getCompanyCode(), businessType), Level.ERROR);
				}
				config.setFormId(config.getSecondFormId());
				config.setFormKey(config.getSecondFormKey());
				LOGGER.info("整装场景下，正签合同B+C套餐，使用B+C合同模式 secondFormId: {}、secondFormKey: {} 的合同模板, projectOrderId: {}", config.getSecondFormId(), config.getSecondFormKey(), projectOrderId);
				return config;
			}
		}
		if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			// 根据单据号判断是否存在 B 部分的品
			BindOrderInfoGroup group = getBindOrderGroupByContract(contract);
			boolean hasBPart = group.getBindOrderInfos().stream()
				.anyMatch(bindOrderInfo -> contractSigningSourceRouter.route(bindOrderInfo.getBindType()).hasBPart(bindOrderInfo));
			LOGGER.info("整装场景下，销售合同判断个性化报价单中是否包含B部分, projectOrderId: {}, bindOrderInfos: {}, personalBillListHasBPart: {}", projectOrderId, JSON.toJSONString(group.getBindOrderInfos()), hasBPart);
			if (hasBPart) {
				if (isFormEmpty(config.getSecondFormKey(), config.getSecondFormId())) {
					throw new NrsBusinessException(ResultCodeEnum.ERROR_NO_DATA.getCode(), String.format("整装场景，销售合同下对应的B+C合同模板为空, 城市:%s,分公司:%s, 业务类型:%s", contract.getGbCode(), contract.getCompanyCode(), businessType), Level.ERROR);
				}
				config.setFormId(config.getSecondFormId());
				config.setFormKey(config.getSecondFormKey());
				return config;
			}
		}
		if (ContractTypeEnum.ADVANCE.getCode().equals(contract.getType())) {
			// 非预报价场景才判断B+C套餐版式
			if (!contractUnifyService.advanceSupportPreQuotation(projectOrderId, ContractTypeEnum.ADVANCE.getCode())) {
				// getConfigByContractType() 方法进入的时机不止生成合同，还有用户协议确认，所以从上下文数据域取数据会空指针
				// 用户协议确认场景下，上下文数据域未初始化，使用 Optional 避免空指针
				String packageId = Optional.ofNullable(ContractContextHandler.getContext())
						.map(ContractContext::getContractReq)
						.map(ContractReqDTO::getProjectInfo)
						.map(ContractProjectInfoReq::getPackageId)
						.orElse(null);
				Integer purchaseType = Optional.ofNullable(ContractContextHandler.getContext())
						.map(ContractContext::getContractReq)
						.map(ContractReqDTO::getProjectInfo)
						.map(ContractProjectInfoReq::getPurchaseType)
						.orElse(null);
				// 数据域没获取到，说明不是发起合同的入口，而是用户协议确认的入口，需要兼容从 contract_field 表获取
				if (StringUtils.isBlank(packageId)) {
					ContractField packageIdField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), ContractProjectInfoReq.Fields.packageId);
					if (packageIdField != null && StringUtils.isNotBlank(packageIdField.getFieldValue())) {
						packageId = packageIdField.getFieldValue();
						LOGGER.info("用户协议确认场景进入，从合同字段表获取 packageId: {}", packageId);
					}
				}
				// 数据域没获取到，说明不是发起合同的入口，而是用户协议确认的入口，需要兼容从 contract_field 表获取
				if (purchaseType == null) {
					ContractField purchaseTypeField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), ContractProjectInfoReq.Fields.purchaseType);
					if (purchaseTypeField != null && StringUtils.isNotBlank(purchaseTypeField.getFieldValue())) {
						purchaseType = Integer.valueOf(purchaseTypeField.getFieldValue());
						LOGGER.info("用户协议确认场景进入，从合同字段表获取 purchaseType: {}", purchaseType);
					}
				}
				if (PurchaseTypeEnum.B.getCode().equals(purchaseType) || PurchaseTypeEnum.BC.getCode().equals(purchaseType)) {
					if (isFormEmpty(config.getSecondFormKey(), config.getSecondFormId())) {
						throw new NrsBusinessException(ResultCodeEnum.ERROR_NO_DATA.getCode(), String.format("整装场景，首期款合同下对应的B+C合同模板为空, 城市:%s,分公司:%s, 业务类型:%s", contract.getGbCode(), contract.getCompanyCode(), businessType), Level.ERROR);
					}
					config.setFormId(config.getSecondFormId());
					config.setFormKey(config.getSecondFormKey());
					LOGGER.info("整装场景下，首期款合同B+C套餐，使用B+C合同模板 secondFormId: {}、secondFormKey: {}, projectOrderId: {}", config.getSecondFormId(), config.getSecondFormKey(), projectOrderId);
					return config;
				}
			}
		}
		NewHousingProjectModule newHousingProjectModule=commonBusinessService.getNewHousingProjectInfoByProjectOrderId(projectOrderId);
		LOGGER.info("判断是否获取开渠合同模板, 业务类型:{}, contractType: {}, 是否存在新房项目: {}, projectOrderId: {}", businessType, contract.getType(), newHousingProjectModule != null, projectOrderId);
		// 如果不属于上面情况【正签合同套餐不是B、B+C套餐】，【销售合同新房项目支付方式不是B、B+C】
		// 并且存在新房项目，获取开渠合同模板 thirdFormKey
		if (FormTypeEnum.isUseThirdForm(businessType, contract.getType(), newHousingProjectModule, processV25)) {
			if (isFormEmpty(config.getThirdFormKey(), config.getThirdFormId())) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_NO_DATA.getCode(), String.format("整装场景下对应的合同模板为空, 城市:%s,分公司:%s, 业务类型:%s", contract.getGbCode(), contract.getCompanyCode(), businessType), Level.ERROR);
			}
			LOGGER.info("整装场景下，开渠客源使用 thirdFormId: {}、thirdFormKey: {} 的合同模板, projectOrderId: {}", config.getThirdFormId(), config.getThirdFormKey(), projectOrderId);
			config.setFormId(config.getThirdFormId());
			config.setFormKey(config.getThirdFormKey());
		}
	}
	return config;
}

public  List<String> getBillCodeListSafe(Contract contract) {
	//协议确认场景，需要从合同报价关联关系表获取报价单列表
	if (ContractStatusEnum.USER_CONFIRMED.getCode().equals(contract.getStatus())) {
		List<String> billCodeList = quotationRelationCommonService.getBillCodeListByContractCode(contract.getContractCode());
		if (CollectionUtils.isEmpty(billCodeList)) {
			return Collections.emptyList();
		}
		return billCodeList;
	}
	ContractContext context = ContractContextHandler.getContext();
	if (context == null) {
		return Collections.emptyList();
	}

	ContractReqDTO req = context.getContractReq();
	if (req == null || req.getBusinessInfo() == null) {
		return Collections.emptyList();
	}

	List<BillCodeInfo> billCodeInfoList = req.getBusinessInfo().getBillCodeInfoList();
	if (CollectionUtils.isEmpty(billCodeInfoList)) {
		return Collections.emptyList();
	}
	return billCodeInfoList.stream()
		.map(BillCodeInfo::getBillCode)
		.collect(Collectors.toList());
}

public BindOrderInfoGroup getBindOrderGroupByContract(Contract contract) {

	// 申请用章场景，入参没有单据号，需要从数据库拿
	if (ContractStatusEnum.USER_CONFIRMED.getCode().equals(contract.getStatus())) {
		return quotationRelationCommonService.getBindOrderInfoGroupByContractCode(contract.getContractCode());
	}

	// 其他场景，直接从入参拿单据号
	ContractContext context = ContractContextHandler.getContext();
	if (context == null) {
		return BindOrderInfoGroup.builder().build();
	}

	ContractReqDTO req = context.getContractReq();
	if (req == null || req.getBusinessInfo() == null) {
		return BindOrderInfoGroup.builder().build();
	}

	List<BillCodeInfo> billCodeInfoList = req.getBusinessInfo().getBillCodeInfoList();
	List<SubOrderInfo> subOrderInfoList = req.getBusinessInfo().getSubOrderInfoList();
	List<ChangeOrderInfo> changeOrderInfoList = req.getBusinessInfo().getChangeOrderInfoList();
	return BindOrderInfoGroup.convert(contract.getProjectOrderId(), subOrderInfoList, billCodeInfoList, changeOrderInfoList);
}

public List<String> getCompanyCodeByContractType(ProjectInfo projectInfo, Byte contractType) {
	Integer gbCode = commonBusinessService.getGbCode(projectInfo.getProjectOrderId());
	Byte businessType = commonBusinessService.getBusinessType(projectInfo.getProjectOrderId());
	//查询对应订单的配置
	List<ContractCityCompanyInfo> configList = getConfig(projectInfo.getProjectOrderId(), gbCode, businessType, contractType);
	if (CollectionUtil.isEmpty(configList)) {
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "未配置分公司主体信息，请提交工单反馈", Level.WARN);
	}
	List<String> companyCodeList = configList.stream().filter(ObjectUtil::isNotEmpty).map(ContractCityCompanyInfo::getCompanyCode).collect(Collectors.toList());
	if (companyCodeList.contains(contractApolloConfig.getCompanyCodeMode2_5())) {
		String companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectInfo.getProjectOrderId());

		//移除csmock
		if (StringUtils.isNotBlank(companyCode)) {
			companyCodeList.add(companyCode);
		}
		companyCodeList.remove(contractApolloConfig.getCompanyCodeMode2_5());
	}
	return companyCodeList;
}

public boolean isFormEmpty(String formKey, Integer formId) {
	return formId == null || formId == 0 || StringUtils.isEmpty(formKey);
}

