	public boolean checkInWhiteList(String projectOrderId, ContractConfigRuleDTO contractConfigRule, ContractPreCheckBo contractPreCheckBo, String decorateCommissionCode) {
		Set<String> buildingIdSet = new HashSet<>(contractConfigRule.getBuildingIdWhiteList());
		Set<String> resblockIdSet = new HashSet<>(contractConfigRule.getResblockIdWhiteList());
		String buildingId = null;
		String resblockId = null;
		if (Objects.nonNull(contractPreCheckBo)
			&& Objects.nonNull(contractPreCheckBo.getBuildingId())
			&& Objects.nonNull(contractPreCheckBo.getResblockId())) {
			buildingId = contractPreCheckBo.getBuildingId().toString();
			resblockId = contractPreCheckBo.getResblockId().toString();
		} else {
			CommissionDataDTO commissionData = customerRpc.getCustomerCommissionByCode(decorateCommissionCode);
			if (Objects.nonNull(commissionData) && Objects.nonNull(commissionData.getCustomerHouse())
				&& Objects.nonNull(commissionData.getCustomerHouse().getBuildingId()) && Objects.nonNull(commissionData.getCustomerHouse().getResblockId())) {
				buildingId = commissionData.getCustomerHouse().getBuildingId().toString();
				resblockId = commissionData.getCustomerHouse().getResblockId().toString();
