@Service
@Slf4j
public class ContractConfigVersionService {

	@Resource
	private ContractCityCompanyInfoService contractCityCompanyInfoService;

	@Resource
	private ProjectConfigSnapService projectConfigSnapService;

	@Resource
	private CommonBusinessService commonBusinessService;

	@Resource
	private ProjectInfoReadService projectInfoReadService;

	@Resource
	private ContractModuleConfigService contractModuleConfigService;

	@Resource
	private ContractFieldConfigService contractFieldConfigService;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Resource
	private CommonContractService commonContractService;

	@Resource
	private LockService lockService;

	private final static Integer DEFAULT_CONTRACT_CITY_COMPANY_INFO_VERSION = 1;
	private final static Integer DEFAULT_CONTRACT_MODULE_VERSION = 1;
	private final static Integer DEFAULT_CONTRACT_FIELD_VERSION = 1;
	public static final String DEFAULT_CONTRACT_VERSION = "1_1_1";

	/**
	 * 获取城市分公司信息配置表配置版本
	 *
	 * @param projectOrderId
	 * @return
	 */
	public Integer getCityCompanyInfoVersion(String projectOrderId) {
		return getContractConfigAllVersion(projectOrderId).getCityCompanyInfoConfigVersion();
	}

	/**
	 * 获取合同模块配置版本
	 *
	 * @param projectOrderId
	 * @return
	 */
	public Integer getModuleConfigVersion(String projectOrderId) {
		return getContractConfigAllVersion(projectOrderId).getModuleConfigVersion();
	}

	/**
	 * 获取合同字段配置版本
	 *
	 * @param projectOrderId
	 * @return
	 */
	public Integer getFieldConfigVersion(String projectOrderId) {
		return getContractConfigAllVersion(projectOrderId).getFieldConfigVersion();
	}

	public ContractVersionConfig getContractConfigAllVersion(String projectOrderId) {
		/**
		 * 快照配置表中的配置顺序为：城市分公司信息配置表版本+ 合同模块表版本 + 合同字段表版本
		 * 1. 从快照配置表中获取对应的版本数据
		 * 2、如果快照配置表中没有数据，则获取对应最新的数据的版本,并保存到快照配置表中
		 */
		ProjectConfigSnap projectConfigSnap = projectConfigSnapService.getConfigByProjectOrderId(projectOrderId);
		if (projectConfigSnap == null || StringUtils.isBlank(projectConfigSnap.getContractConfigId())) {
			String contractVersionConfigStr = getContractVersionInfoAndUpdateSnap(projectOrderId);
			return ContractVersionConfig.getContractVersionConfig(contractVersionConfigStr);
		}
		return ContractVersionConfig.getContractVersionConfig(projectConfigSnap.getContractConfigId());
	}

	/**
	 * 纯查询合同配置信息
	 * 1. 从快照配置表中获取对应的版本数据
	 * 2、如果快照配置表中没有数据，则获取对应最新的数据的版本
	 * @param projectOrderId
	 * @return
	 */
	public ContractVersionConfig queryContractConfigAllVersion(String projectOrderId) {
		ProjectConfigSnap projectConfigSnap = projectConfigSnapService.getConfigByProjectOrderId(projectOrderId);
		if (projectConfigSnap == null || StringUtils.isBlank(projectConfigSnap.getContractConfigId())) {
			String contractVersionConfigStr = getLatestVersion(projectOrderId);
			//当前场景只有两个版本，做个报警监控
			return ContractVersionConfig.getContractVersionConfig(contractVersionConfigStr);
		}
		return ContractVersionConfig.getContractVersionConfig(projectConfigSnap.getContractConfigId());
	}

	public String getLatestVersion(String projectOrderId) {
		CoordinationProjectInfo coordinationProjectInfo = commonBusinessService.getCoordinationProjectOrderNotNull(projectOrderId);
		CoordinationProjectRelationInfo retailProjectOrder = coordinationProjectInfo.getRetailProjectOrder(projectOrderId);
		ProjectInfoDTO projectInfoDTO;
		if (retailProjectOrder != null && StringUtils.isBlank(retailProjectOrder.getCustomerCommissionCode())) {
			// 搭售场景下有零售项目但是没有零售客源需要使用整装的项目查询
			projectInfoDTO = projectInfoReadService.getByProjectOrderId(coordinationProjectInfo.getDecorateProjectOrder().getProjectOrderId());

			//局装2.0搭零售2.5，如果零售订单还没有零售客源编码，零售订单的合同快照版本不能使用整装项目信息来获取合同版本，局装是2.0会获取到1_1_1版本，导致报错。
			//这种特殊场景先返回2_2_2版本
			if (BusinessTypeEnum.PART_DECORATE.getCode().equals(commonBusinessService.getBusinessType(projectInfoDTO))
				&& ObjectUtil.equal(projectOrderId, retailProjectOrder.getProjectOrderId())) {
				LOGGER.error("【无需关注，仅提醒】局装2.0搭零售2.5，零售订单没有零售客源编码，零售订单的合同快照版本取2_2_2,projectOrderId:{}", projectOrderId);
				return "2_2_2";
			}
		} else {
			projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
		}

		//城市分公司信息配置表版本
		Integer contractCityCompanyInfoLatestVersion = getContractCityCompanyInfoLatestVersion(projectInfoDTO);
		//合同模块表版本
		Integer contractModuleConfigLatestVersion = getContractModuleConfigLatestVersion(projectInfoDTO);
		//合同字段表版本
		Integer contractFieldConfigLatestVersion = getContractFieldConfigLatestVersion(projectInfoDTO);
		return ContractVersionConfig.toContractVersionConfigStr(contractCityCompanyInfoLatestVersion, contractModuleConfigLatestVersion, contractFieldConfigLatestVersion);
	}


	/**
	 * 获取合同城市分公司配置表最新版本
	 */
	private Integer getContractCityCompanyInfoLatestVersion(ProjectInfoDTO projectInfoDTO) {
		String projectOrderId = projectInfoDTO.getProjectOrderId();
		if (!commonBusinessService.isPROCESS_V2_5(projectOrderId)) {
			LOGGER.info("获取合同城市分公司配置表最新版本,非2.5订单，返回默认版本:1，projectOrderId:{}", projectOrderId);
			return DEFAULT_CONTRACT_CITY_COMPANY_INFO_VERSION;
		}
		String companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(),
			projectInfoDTO.getCustomerCommission().getCompanyCode(), ContractTypeEnum.PACKAGE_FORMAL.getCode());

		if (StringUtils.isBlank(companyCode)) {
			LOGGER.info("合同城市分公司配置表为不存在配置数据,分公司为空，projectOrderId:{}，companyCode:{}", projectOrderId, companyCode);
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "查询合同城市分公司配置表失败，分公司为空，请检查配置或联系客服", Level.WARN);
		}

		ContractCityCompanyInfo latestContractCityCompanyInfo = contractCityCompanyInfoService.getLatestConfig(projectInfoDTO.getCustomerHouse().getGbCode(), companyCode, commonContractService.getBusinessType(projectInfoDTO));
		if (latestContractCityCompanyInfo == null) {
			LOGGER.error("合同城市分公司配置表为不存在配置数据，projectOrderId:{}，companyCode:{}", projectOrderId, companyCode);
			String errMsg = String.format("合同城市分公司配置表无数据，城市：%s，分公司：%s，请检查配置或联系客服", projectInfoDTO.getCustomerHouse().getGbCode(), companyCode);
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), errMsg, Level.WARN);
		}
		LOGGER.info("获取城市分公司配置表最新版本:{}，projectOrderId:{}", latestContractCityCompanyInfo.getVersion(), projectOrderId);
		return latestContractCityCompanyInfo.getVersion();
	}

	/**
	 * 获取合同模块配置表最新版本
	 */
	private Integer getContractModuleConfigLatestVersion(ProjectInfoDTO projectInfoDTO) {
		String projectOrderId = projectInfoDTO.getProjectOrderId();
		if (!commonBusinessService.isPROCESS_V2_5(projectOrderId)) {
			LOGGER.info("获取合同模块配置表最新版本,非2.5订单，返回默认版本:1，projectOrderId:{}", projectOrderId);
			return DEFAULT_CONTRACT_MODULE_VERSION;
		}
