	/**
	 * 获取最新的合同版本信息并更新快照配置
	 */
	public String getContractVersionInfoAndUpdateSnap(String projectOrderId){
		String contractVersionConfigStr = getLatestVersion(projectOrderId);
		//当前场景只有两个版本，做个报警监控
		List<String> contractVersionlList = Arrays.asList(DEFAULT_CONTRACT_VERSION, "2_2_2", "2_3_3");
		if (!contractVersionlList.contains(contractVersionConfigStr)) {
			LOGGER.error("合同配置版本异常，projectOrderId:{}，配置快照：{}", projectOrderId, contractVersionConfigStr);
			throw new NrsBusinessException("合同配置版本出现异常，工程师紧急排查中");
		}

		CoordinationProjectInfo coordinationProjectInfo = commonBusinessService.getCoordinationProjectOrderNotNull(projectOrderId);
		CoordinationProjectRelationInfo retailProjectOrder = coordinationProjectInfo.getRetailProjectOrder(projectOrderId);
		ProjectInfoDTO projectInfoDTO;
		if (retailProjectOrder != null && StringUtils.isBlank(retailProjectOrder.getCustomerCommissionCode())) {
			// 搭售场景下有零售项目但是没有零售客源需要使用整装的项目查询
			projectInfoDTO = projectInfoReadService.getByProjectOrderId(coordinationProjectInfo.getDecorateProjectOrder().getProjectOrderId());
		} else {
			projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
		}

		Byte businessType = commonBusinessService.getBusinessType(projectInfoDTO);
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId);
		// 2.5 && 非北京 & 非首期合同支持预报价开城：写死2_2_2, 其他正常返回最新
		if (processV25 && CityEnum.BEIJING.getGbCode() != (projectInfoDTO.getCustomerHouse().getGbCode())
			&& (!contractApolloConfig.getAdvanceSupportPreQuotationOpenCity().contains(projectInfoDTO.getCustomerHouse().getGbCode()) && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType))) {
			contractVersionConfigStr = "2_2_2";
		}
		//非测试城市、北京的2.5单子版本不会是1_1_1，增加判断，防止漏配合同导致的错误问题
		if (DEFAULT_CONTRACT_VERSION.equals(contractVersionConfigStr) && processV25) {
			if (!Arrays.asList(CityEnum.BEIJING.getGbCode(), CityEnum.CESHICHENG.getGbCode()).contains(projectInfoDTO.getCustomerHouse().getGbCode())) {
				LOGGER.error("合同配置版本异常，检查对应2.5订单合同配置版本是否缺少，projectOrderId:{},city:{}，配置快照：{}", projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), contractVersionConfigStr);
				throw new NrsBusinessException("合同配置版本出现异常，工程师紧急排查中");
			}
		}
		String finalContractVersionConfigStr = contractVersionConfigStr;
		lockService.lockElseThrow(LockService.PROJECT_ORDER_ID + projectOrderId, () -> {
			projectConfigSnapService.updateSnapContractIdConfig(projectOrderId, finalContractVersionConfigStr);
			return null;
		});
		LOGGER.info("合同配置快照保存完成，projectOrderId:{}，配置快照：{}", projectOrderId, contractVersionConfigStr);
		return  contractVersionConfigStr;
	}

	/**
	 * 清除快照中的合同配置版本信息
	 *
	 * @param projectOrderId
	 */
	public void clearContractConfigVersionSnap(String projectOrderId) {
		projectConfigSnapService.clearSnapContractIdConfig(projectOrderId);
		LOGGER.info("清除合同配置快照完成，projectOrderId:{}", projectOrderId);
	}
}

