public ContractVersionConfig getContractConfigAllVersion(String projectOrderId) {
	/**
	 * 快照配置表中的配置顺序为：城市分公司信息配置表版本+ 合同模块表版本 + 合同字段表版本
	 * 1. 从快照配置表中获取对应的版本数据
	 * 2、如果快照配置表中没有数据，则获取对应最新的数据的版本,并保存到快照配置表中
	 */
	ProjectConfigSnap projectConfigSnap = projectConfigSnapService.getConfigByProjectOrderId(projectOrderId);
	if (projectConfigSnap == null || StringUtils.isBlank(projectConfigSnap.getContractConfigId())) {
		String contractVersionConfigStr = getContractVersionInfoAndUpdateSnap(projectOrderId);
		return ContractVersionConfig.getContractVersionConfig(contractVersionConfigStr);
	}
	return ContractVersionConfig.getContractVersionConfig(projectConfigSnap.getContractConfigId());
}

