public String getLatestVersion(String projectOrderId) {
	CoordinationProjectInfo coordinationProjectInfo = commonBusinessService.getCoordinationProjectOrderNotNull(projectOrderId);
	CoordinationProjectRelationInfo retailProjectOrder = coordinationProjectInfo.getRetailProjectOrder(projectOrderId);
	ProjectInfoDTO projectInfoDTO;
	if (retailProjectOrder != null && StringUtils.isBlank(retailProjectOrder.getCustomerCommissionCode())) {
		// 搭售场景下有零售项目但是没有零售客源需要使用整装的项目查询
		projectInfoDTO = projectInfoReadService.getByProjectOrderId(coordinationProjectInfo.getDecorateProjectOrder().getProjectOrderId());

		//局装2.0搭零售2.5，如果零售订单还没有零售客源编码，零售订单的合同快照版本不能使用整装项目信息来获取合同版本，局装是2.0会获取到1_1_1版本，导致报错。
		//这种特殊场景先返回2_2_2版本
		if (BusinessTypeEnum.PART_DECORATE.getCode().equals(commonBusinessService.getBusinessType(projectInfoDTO))
			&& ObjectUtil.equal(projectOrderId, retailProjectOrder.getProjectOrderId())) {
			LOGGER.error("【无需关注，仅提醒】局装2.0搭零售2.5，零售订单没有零售客源编码，零售订单的合同快照版本取2_2_2,projectOrderId:{}", projectOrderId);
			return "2_2_2";
		}
	} else {
		projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
	}

	//城市分公司信息配置表版本
	Integer contractCityCompanyInfoLatestVersion = getContractCityCompanyInfoLatestVersion(projectInfoDTO);
	//合同模块表版本
	Integer contractModuleConfigLatestVersion = getContractModuleConfigLatestVersion(projectInfoDTO);
	//合同字段表版本
	Integer contractFieldConfigLatestVersion = getContractFieldConfigLatestVersion(projectInfoDTO);
	return ContractVersionConfig.toContractVersionConfigStr(contractCityCompanyInfoLatestVersion, contractModuleConfigLatestVersion, contractFieldConfigLatestVersion);
}

