@Service
@Slf4j
public class ContractCustomConfigService {

	@Resource
	private ParallelTaskService parallelTaskService;

	@Resource
	PdfToImageService pdfToImageService;

	@Resource
	ContractCustomAttachConfigRepository contractCustomAttachConfigService;

	/**
	 * 获取河图创建人ucid
	 */
	public String getHetuCreateUcId() {
		HttpServletRequest request = ((ServletRequestAttributes) RequestContextHolder.getRequestAttributes()).getRequest();
		return request.getHeader("ucid");
	}

	public PageInfo<ContractCustomAttachConfigInfo> getConfigList(Integer gbCode, String companyCode, Byte businessType, Byte contractFormType, Integer pageSize, Integer currentPage) {
		ContractCustomAttachConfig queryParam = ContractCustomAttachConfig.builder()
			.businessType(businessType)
			.gbCode(gbCode)
			.companyCode(companyCode)
			.contractFormType(contractFormType).build();
		// 1. 根据条件查询列表
		PageInfo<ContractCustomAttachConfig> pageInfo = contractCustomAttachConfigService.getContractCustomAttachByPage(queryParam, currentPage, pageSize);
		PageInfo<ContractCustomAttachConfigInfo> result = new PageInfo<>();
		BeanUtils.copyProperties(pageInfo, result, "list");

		List<ContractCustomAttachConfigInfo> resultList = pageInfo.getList().stream()
			.map(this::convertToConfigInfo)
			.collect(Collectors.toList());

		result.setList(resultList);
		return result;

	}

	private ContractCustomAttachConfigInfo convertToConfigInfo(ContractCustomAttachConfig config) {
		ContractCustomAttachConfigInfo configInfo = new ContractCustomAttachConfigInfo();
		BeanUtils.copyProperties(config, configInfo);

		configInfo.setGbName(CityEnum.getNameByCode(config.getGbCode()));
		configInfo.setBusinessTypeName(BusinessTypeEnum.getNameByCode(config.getBusinessType()));
		configInfo.setContractFormTypeName(ContractFormTypeEnum.getTypeByCode(config.getContractFormType()));

		return configInfo;
	}

	/**
	 * 执行 PDF 转 Image 的并行任务
	 * @return Map<PDF_URL, IMAGE_URL>
	 */
	private Map<String, String> executePdfToImageConversion(String... pdfUrls) {
		Map<String, AtomicReference<String>> refMap = new HashMap<>();
		ParallelTasksContext context = parallelTaskService.newParallelTasks();

		for (String url : pdfUrls) {
			// 过滤空URL，避免无效任务
			if (StringUtils.isBlank(url)) continue;

			// 避免重复提交相同的URL任务
			if (refMap.containsKey(url)) continue;

			AtomicReference<String> resultRef = new AtomicReference<>("");
			refMap.put(url, resultRef);

			parallelTaskService.addNewTask(context, () -> {
				try {
					List<String> images = pdfToImageService.pdf2ImagePublicParallel(url);
					if (CollectionUtils.isNotEmpty(images)) {
						resultRef.set(String.join(",", images));
					}
				} catch (Exception e) {
					// 仅记录日志，不阻断流程，Result保持为空字符串
					LOGGER.error("PDF转图片失败, url:{}", url, e);
				}
			});
		}

		if (!refMap.isEmpty()) {
			parallelTaskService.execTasks(context);
			parallelTaskService.awaitTasksResult(context);
		}

		// 将 AtomicReference 的结果解包为普通 Map
		return refMap.entrySet().stream()
			.collect(Collectors.toMap(Map.Entry::getKey, e -> e.getValue().get()));
	}


	public void createContractCustomAttachConfig(ContractCustomAttachConfigReq request) {

		String ucId = getHetuCreateUcId();

		// 1. 预处理：获取值，默认为 ""
		String advancePdfUrl = getFirstOrEmpty(request.getAdvancePdfUrls());
		String packageFormalPdfUrl = getFirstOrEmpty(request.getPackageFormalPdfUrls());
		String personalPdfUrl = getFirstOrEmpty(request.getPersonalPdfUrls());

		// 2. 校验：isAllBlank 可以同时处理 null 和 ""
		if (StringUtils.isAllBlank(advancePdfUrl, packageFormalPdfUrl, personalPdfUrl)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请至少上传一种附件");
		}

		// 2. 业务校验：检查配置是否已存在
		checkDuplicateConfig(request);

		// 3. 并行处理：PDF 转图片
		Map<String, String> imgUrlMap = executePdfToImageConversion(advancePdfUrl, packageFormalPdfUrl, personalPdfUrl);

		// 4. 数据组装与保存
		ContractCustomAttachConfig config = ContractCustomAttachConfig.builder()
			// 维度信息
			.gbCode(request.getGbCode())
			.companyCode(request.getCompanyCode())
			.businessType(request.getBusinessType())
			.contractFormType(request.getContractFormType())

