private Map<String, String> executePdfToImageConversion(String... pdfUrls) {
	Map<String, AtomicReference<String>> refMap = new HashMap<>();
	ParallelTasksContext context = parallelTaskService.newParallelTasks();

	for (String url : pdfUrls) {
		// 过滤空URL，避免无效任务
		if (StringUtils.isBlank(url)) continue;

		// 避免重复提交相同的URL任务
		if (refMap.containsKey(url)) continue;

		AtomicReference<String> resultRef = new AtomicReference<>("");
		refMap.put(url, resultRef);

		parallelTaskService.addNewTask(context, () -> {
			try {
				List<String> images = pdfToImageService.pdf2ImagePublicParallel(url);
				if (CollectionUtils.isNotEmpty(images)) {
					resultRef.set(String.join(",", images));
				}
			} catch (Exception e) {
				// 仅记录日志，不阻断流程，Result保持为空字符串
				LOGGER.error("PDF转图片失败, url:{}", url, e);
			}
		});
	}

	if (!refMap.isEmpty()) {
		parallelTaskService.execTasks(context);
		parallelTaskService.awaitTasksResult(context);
	}

	// 将 AtomicReference 的结果解包为普通 Map
	return refMap.entrySet().stream()
		.collect(Collectors.toMap(Map.Entry::getKey, e -> e.getValue().get()));
}

public void createContractCustomAttachConfig(ContractCustomAttachConfigReq request) {

	String ucId = getHetuCreateUcId();

	// 1. 预处理：获取值，默认为 ""
