		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请至少上传一种附件");
	}

	// 2. 业务校验：检查配置是否已存在
	checkDuplicateConfig(request);

	// 3. 并行处理：PDF 转图片
	Map<String, String> imgUrlMap = executePdfToImageConversion(advancePdfUrl, packageFormalPdfUrl, personalPdfUrl);

	// 4. 数据组装与保存
	ContractCustomAttachConfig config = ContractCustomAttachConfig.builder()
		// 维度信息
		.gbCode(request.getGbCode())
		.companyCode(request.getCompanyCode())
		.businessType(request.getBusinessType())
		.contractFormType(request.getContractFormType())

		// 原始 PDF (使用最开始提取的变量)
		.advancePdfUrl(advancePdfUrl)
		.packageFormalPdfUrl(packageFormalPdfUrl)
		.personalPdfUrl(personalPdfUrl)

		// 转换后的 Image (从 Ref 获取，默认为空串)
		.advanceImageUrl(imgUrlMap.getOrDefault(advancePdfUrl, ""))
		.packageFormalImageUrl(imgUrlMap.getOrDefault(packageFormalPdfUrl, ""))
		.personalImageUrl(imgUrlMap.getOrDefault(personalPdfUrl, ""))

		// 基础字段
		.createUserId(ucId)
		.updateUserId(ucId)
		.delStatus(CommonEnum.NO.getCode())
		.ctime(new Date())
		.mtime(new Date())
		.build();

	contractCustomAttachConfigService.insert(config);
}

