@Service
@Slf4j
public class ContractInspectService {

	@Resource
	private ContractService contractService;
	@Resource
	private ContractCollectionPlanRecordService contractCollectionPlanRecordService;
	@Resource
	private QuotationFeignService quotationFeignService;
	@Resource
	private PcContractService pcContractService;

	/**
	 * 数据巡检分页获取合同信息
	 * @param currentPage 当前页
	 * @param pageSize 页大小
	 * @return 巡检数据业务对象
	 */
	public List<ContractInspectionBo> contractDataInspectPageList(Integer currentPage, Integer pageSize) {
		Example example = new Example(Contract.class);
		example.createCriteria()
			.andNotEqualTo(Contract.Fields.gbCode, 666666)
			.andNotEqualTo(Contract.Fields.gbCode, 110000)
			.andNotEqualTo(Contract.Fields.status, ContractStatusEnum.CANCEL.getCode())
			.andNotEqualTo(Contract.Fields.status, ContractStatusEnum.DRAFT.getCode());
		PageInfo<Contract> contractPageInfo = contractService.selectPageAndCountByExample(example, currentPage, pageSize);


		List<ContractInspectionBo> inspectData = new ArrayList<>(pageSize);
		// 报价信息(正签、变更)
		Map<String, PlanAllDTO> packagelMap = new HashMap<>();

		for (Contract contract : contractPageInfo.getList()) {
			try {
				if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
					PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(contract.getProjectOrderId(), null);
					packagelMap.put(contract.getContractCode(), planAllDTO);
				} else if(ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType())) {
					PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(contract.getProjectOrderId(), contract.getChangeOrderId());
					packagelMap.put(contract.getContractCode(), planAllDTO);
				}
			} catch (Exception e) {
				LOGGER.info("签约数据巡检查询报价失败，单号：{}", contract.getProjectOrderId(), e);
			}
		}

		// 获取收款计划信息
		List<String> contractCodeList = contractPageInfo.getList().stream().map(Contract::getContractCode).collect(Collectors.toList());
		Map<String, ContractCollectionPlanRecord> planRecordMap = contractCollectionPlanRecordService.selectByExample(Example.builder(ContractCollectionPlanRecord.class)
				.andWhere(Sqls.custom().andIn(ContractCollectionPlanRecord.Fields.contractCode, contractCodeList)).build())
			.stream().collect(Collectors.toMap(ContractCollectionPlanRecord::getContractCode, Function.identity(), (oldVal, newVal) -> newVal));

		for (Contract contract : contractPageInfo.getList()) {
			PlanAllDTO planAllDTO = packagelMap.get(contract.getContractCode());
			ContractInspectionBo contractInspectionBo = ContractInspectionBo.builder()
				.contractBusinessType(contract.getBusinessType().intValue())
				.contractCreateTime(contract.getCtime().getTime())
				.contractCode(contract.getContractCode())
				.contractType(contract.getType())
				.contractAmount(contract.getAmount())
				.contractStatus(contract.getStatus())
				.contractPriceTotal(planAllDTO != null ? planAllDTO.getPlanInfo().getContractPriceTotal() : BigDecimal.ZERO)
				.build();

			try {
				ContractCollectionPlanRecord contractCollectionPlanRecord = planRecordMap.get(contract.getContractCode());
				if (contractCollectionPlanRecord != null) {
					CollectionPlanConfigInfo collectionPlanConfigInfo = JSON.parseObject(contractCollectionPlanRecord.getCollectionPlan(), CollectionPlanConfigInfo.class);
					Optional<BigDecimal> planTotalRate = collectionPlanConfigInfo.getContent().stream().map(CollectionPlanItem::getRate).reduce(BigDecimal::add);
					Optional<BigDecimal> planTotalPrice = collectionPlanConfigInfo.getContent().stream().map(CollectionPlanItem::getPrice).reduce(BigDecimal::add);
					contractInspectionBo.setPlanTotalPrice(planTotalPrice.orElse(BigDecimal.ZERO));
					contractInspectionBo.setPlanTotalRate(planTotalRate.orElse(BigDecimal.ZERO));
				}

				// 正签合同获取备件信息
				if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
					boolean uploadStatus = pcContractService.checkAttach(contract.getContractCode());
					contractInspectionBo.setHasAttachInfo(uploadStatus);
				}
			} catch (Exception e) {
				LOGGER.info("签约数据巡检组装信息失败，单号：{}", contract.getProjectOrderId(), e);
			}

			inspectData.add(contractInspectionBo);
		}

		return inspectData;
	}

	/**
	 * Excel结果集构造函数
	 * @param result 巡检结果
	 * @param contractInspectionBo 巡检数据业务对象
	 * @return Excel结果集表头
	 */
	public ContractInspectionResultBo buildResult(String result, ContractInspectionBo contractInspectionBo) {
		ContractInspectionResultBo resultBo = new ContractInspectionResultBo();
		resultBo.setBizNo(contractInspectionBo.getContractCode());
		resultBo.setInspectionResult(result);
		resultBo.setInspectionTime(DateUtils.getDateTimeStr(new Date()));
		return resultBo;
	}
}

