	private List<ContractSummaryInfo.ContractItemVo> getSummaryContractList(String projectOrderId, List<Contract> relateContract) {
		List<ContractSummaryInfo.ContractItemVo> result = new ArrayList<>();
		int signOrder = 1;
		for (Contract contract : relateContract) {
			if (ContractTypeEnum.AUTH_AGENT.getCode().equals(contract.getType())) {
				continue;
			}
			ContractField goodsInfo = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), "goodsInfo");
			ContractSummaryInfo.ContractItemVo build = ContractSummaryInfo.ContractItemVo.builder()
				.contractCode(contract.getContractCode())
				.type(contract.getType())
				.typeText(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
				.shortName(ContractTypeEnum.getShortName(contract.getType()))
				.status(contract.getStatus())
				.signChannelType(contract.getSignChannelType())
				.statusText(ContractStatusEnum.getNameByCode(contract.getStatus()))
				.signOrder(signOrder)
				.schema(contractBusinessService.buildDetailUrl(contract.getContractCode()))
				.contractUrl(homeAndPcCommonService.getContractUrl(contract))
				.goodsInfo(ObjectUtil.isNotEmpty(goodsInfo) ? goodsInfo.getFieldValue() : null)
				.build();
			if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType()) && !projectOrderId.equals(contract.getProjectOrderId())) {
				build.setTypeText("原服务解约协议");
			}
			// 补充协议未审核完成（用户查询状态不可见），不允许一键签署
			if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contract.getType()) && contract.getUserQueryStatus().equals(UserQueryStatusEnum.INVALID.getCode())) {
				continue;
			}
			result.add(build);
			signOrder++;
		}
		return result;
	}


	/**
	 * 批量获取合同签署url
	 */
	public ContractSignUrlVo getBatchContractSignUrl(List<String> contractCodeList, List<ContractUser> signerList, String returnUrl) {
		//签约信息校验
		ContractSignUrlVo contractSignUrlVo = contractBusinessService.checkSignInfo(contractCodeList, signerList);
		if (contractSignUrlVo != null) {
			return contractSignUrlVo;
		}
		List<ContractUser> companyUserList = signerList.stream().filter(item -> Arrays.asList(UserTypeEnum.COMPANY_AGENT.getCode(), UserTypeEnum.LEGAL.getCode()).contains(item.getRoleType())).collect(Collectors.toList());
		if (CollectionUtils.isNotEmpty(companyUserList)) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "对公签约不支持批量签署", Level.ERROR);
		}
		List<Contract> contractList = contractService.getListByContractCodes(contractCodeList, false);

		for (Contract contract : contractList) {
			Contract authAgentContract = homeAndPcCommonService.getRelateContractByType(contract, ContractTypeEnum.AUTH_AGENT.getCode());
			if (authAgentContract != null && !ContractStatusEnum.SIGNED_STATUS_LIST.contains(authAgentContract.getStatus())) {
				throw new NrsBusinessException("请先邀请产权人完成代理人授权", Level.WARN);
			}
		}

		List<Contract> pendingCompanySignContract = contractList.stream().filter(contract -> ContractStatusEnum.PENDING_COMPANY_SIGN.getCode().equals(contract.getStatus())).collect(Collectors.toList());
		if (CollectionUtils.isNotEmpty(pendingCompanySignContract)) {
			String pendingCompanySignContractName = pendingCompanySignContract.stream().map(item -> ContractTypeEnum.getNameByContractTypeAndBusinessType(item.getType(), item.getBusinessType())).collect(Collectors.joining(","));
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), pendingCompanySignContractName + "正在盖章中，请稍后...", Level.WARN);
		}
		List<Contract> noPendingUserSignContract = contractList.stream().filter(contract -> !ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus())).collect(Collectors.toList());
		if (CollectionUtils.isNotEmpty(noPendingUserSignContract)) {
			String noPendingUserSignContractName = noPendingUserSignContract.stream().map(item -> ContractTypeEnum.getNameByContractTypeAndBusinessType(item.getType(), item.getBusinessType())).collect(Collectors.joining(","));
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), noPendingUserSignContractName + "不是待签署状态，请检查...", Level.WARN);
		}


		List<Long> instanceIds = contractList.stream().map(Contract::getPlatformInstanceId).sorted().collect(Collectors.toList());
		String signUrlKey = Constant.BATH_SIGN_URL_PRE.concat(StringUtils.join(instanceIds, ","));
		//查询缓存
		String cacheData = stringRedisTemplate.opsForValue().get(signUrlKey);
		if (StringUtils.isNotBlank(cacheData)) {
			LOGGER.info("批量获取合同签署url命中缓存数据，signUrlKey：{}", signUrlKey);
			return ContractSignUrlVo.builder()
				.authCode(AuthCodeEnum.SUCCESS.getCode())
				.contractUrl(cacheData).build();
		}
		ContractUser signer = signerList.get(0);
		//注册个人信息
		registerUserSeal(signer);

		String signerPhone = cipherService.decrypt(signer.getPhone());
		CertificateTypeEnum certificateTypeEnum = CertificateTypeEnum.getEnumByCode(signer.getCertificateType());
		String signerCertificateNo = cipherService.decrypt(signer.getCertificateNo());
		String bathSignUrl = null;
		try {
			//创建合同目录
			String catalogName = Constant.SIGN_APPLICATION_NAME.concat(RandomCodeUtils.generateId());
			freeformService.createContractCatalog(catalogName);
			//添加合同到合同目录
			freeformService.addContractToCatalog(instanceIds, catalogName);
			Map<Long, String> signUserRoleTypeMap = new HashMap<>();
			for (Long instanceId : instanceIds) {
				signUserRoleTypeMap.put(instanceId, contractBusinessService.getSignRoleType(instanceId));
			}
			bathSignUrl = freeformService.getBathSignUrl(ContractBathSignUrlParam.builder()
				.instanceIds(instanceIds)
				.signUserRoleTypeMap(signUserRoleTypeMap)
				.phone(signerPhone)
				.certificateType(certificateTypeEnum.getPlatformCode().intValue())
				.certificateNo(signerCertificateNo)
				.returnUrl(returnUrl)
				.addWaterMark(false)
				.catalogName(catalogName)
				.build());
		} catch (Exception e) {
			//记录获取手签链接失败
			contractCodeList.forEach(contractCode -> contractLogService.createLog(contractCode, LogTypeEnum.GET_SIGN_URL_ERROR.getCode(), LogTypeEnum.GET_SIGN_URL_ERROR.getName(), "", "", "用户"));
			LOGGER.error("批量获取手签链接失败，contractCode:{},errorMessage:{}", contractCodeList, e.getMessage(), e);
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "获取手签失败，请稍后重试", Level.WARN);
		}
		bathSignUrl = contractBusinessService.translateBatchSignUrl(bathSignUrl);
		stringRedisTemplate.opsForValue().set(signUrlKey, bathSignUrl, 2, TimeUnit.DAYS);
		ContractSignUrlVo result = new ContractSignUrlVo();
		result.setAuthCode(AuthCodeEnum.SUCCESS.getCode());
		result.setContractUrl(bathSignUrl);
		return result;

	}


	private void registerUserSeal(ContractUser signer) {
		String signerPhone = cipherService.decrypt(signer.getPhone());
		CertificateTypeEnum certificateTypeEnum = CertificateTypeEnum.getEnumByCode(signer.getCertificateType());
		String signerCertificateNo = cipherService.decrypt(signer.getCertificateNo());
		//注册个人信息
		contractBusinessService.registerUserSeal(signer.getName(), signerPhone, certificateTypeEnum.getPlatformCode(), signerCertificateNo);

	}

	/**
	 * 合同批量获取签署结果
	 */
	public SignResultVo contractBatchSignResult(List<String> contractCodeList) {
		SignResultVo result = SignResultVo.builder().signStatus(SignResultEnum.DOING.getCode()).build();
		List<Contract> contractList = contractService.getListByContractCodes(contractCodeList, false);
		//无需签署的合同
		List<Contract> noNeedSignContract = contractList.stream().filter(contract -> !UserSignTypeEnum.SIGN.getCode().equals(contract.getUserSignType())).collect(Collectors.toList());
		if (CollectionUtils.isNotEmpty(noNeedSignContract)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "存在无需签署的合同，请检查");
		}
		//未签署的合同
		List<Contract> noSignContract = contractList.stream().filter(item -> !CommonEnum.YES.getCode().equals(item.getUserSignStatus())).collect(Collectors.toList());
		if (CollectionUtils.isEmpty(noSignContract)) {
			result.setSignStatus(SignResultEnum.SUCCESS.getCode());
			return result;
		}
		//不允许签署的合同
		List<Contract> noAllowSignContract = contractList.stream().filter(item -> !ContractStatusEnum.allowSignStatus.contains(item.getStatus())).collect(Collectors.toList());
		if (CollectionUtils.isNotEmpty(noAllowSignContract)) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "当前合同被撤回导致无法继续签约，请联系设计师重新发起签约", Level.WARN);
		}
		List<ContractUser> contractUserList = contractUserService.getSignerByContractCodes(contractCodeList);
		if (contractUserList.stream().map(ContractUser::getPhone).collect(Collectors.toSet()).size() > 1) {
			throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "合同签署人不一致，请检查", Level.WARN);
		}
		ContractUser signer = contractUserList.get(0);
		//调用协议平台查询结果
		List<Long> instanceIds = contractList.stream().map(Contract::getPlatformInstanceId).collect(Collectors.toList());
		//已经协议确认的实例id
		List<Long> userConfirmInstanceIdList = contractList.stream().filter(item -> CommonEnum.YES.getCode().equals(item.getUserConfirmStatus())).map(Contract::getPlatformInstanceId).collect(Collectors.toList());
		CertificateTypeEnum certificateTypeEnum = CertificateTypeEnum.getEnumByCode(signer.getCertificateType());
		String signerCertificateNo = cipherService.decrypt(signer.getCertificateNo());
		List<com.lianjia.freeform.model.vo.SignResultVo> freeFormSignResult = freeformService.getBatchContractSignResult(instanceIds, certificateTypeEnum.getPlatformCode().intValue(), signerCertificateNo,userConfirmInstanceIdList);
		if (CollectionUtils.isEmpty(freeFormSignResult)) {
			return result;
		}
		//签署成功的合同
		Map<Long, com.lianjia.freeform.model.vo.SignResultVo> successSignResultMap = freeFormSignResult.stream().filter(item -> item.getSigned().equals(Boolean.TRUE)).collect(Collectors.toMap(com.lianjia.freeform.model.vo.SignResultVo::getInstanceId, item -> item));
		//签署失败的合同
		Map<Long, com.lianjia.freeform.model.vo.SignResultVo> failSignResultMap = freeFormSignResult.stream().filter(item -> !item.getSigned().equals(Boolean.TRUE)).collect(Collectors.toMap(com.lianjia.freeform.model.vo.SignResultVo::getInstanceId, item -> item));
		Map<Long, String> uploadPdfUrlMap;
		try {
			uploadPdfUrlMap = uploadPdf(successSignResultMap);
		} catch (Exception e) {
			//观察一段时间，如有异常，会自动重试
			LOGGER.error("批量获取手签结果，上传合同到s3失败", e);
			return result;
		}
		List<Contract> successSignContractList = contractList.stream().filter(item -> successSignResultMap.containsKey(item.getPlatformInstanceId())).collect(Collectors.toList());
		//更新合同数据
		contractMpServiceSelf.updateSignStatus(successSignContractList, uploadPdfUrlMap, signer);
		if (!failSignResultMap.isEmpty()) {
			result.setSignStatus(SignResultEnum.FAIL.getCode());
			return result;
		}
		result.setSignStatus(SignResultEnum.SUCCESS.getCode());
		return result;
	}

	//上传pdf
	private Map<Long, String> uploadPdf(Map<Long, com.lianjia.freeform.model.vo.SignResultVo> successSignResultMap) {
		Map<Long, String> uploadPdfUrlMap = new ConcurrentHashMap<>();
		List<CompletableFuture<Void>> futures = new ArrayList<>();

		successSignResultMap.forEach((instanceId, signResult) -> {
			//多线程进行上传合同到s3
			CompletableFuture<Void> pdfFuture = CompletableFuture.runAsync(RunnableWrapper.of(() -> {
				LOGGER.info("批量获取手签结果，上传合同到s3开始，instanceId:{}", instanceId);
				String pdfUrl = s3Service.upload(signResult.getS3Url());
				uploadPdfUrlMap.put(instanceId, pdfUrl);
				LOGGER.info("批量获取手签结果，上传合同到s3完成，instanceId:{}", instanceId);
			}), parallelRequestExecutor);
			futures.add(pdfFuture);
		});
		CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
		return uploadPdfUrlMap;
	}


	@Transactional
	public void updateSignStatus(List<Contract> successSignContractList, Map<Long, String> uploadPdfUrlMap, ContractUser signer) {
		for (Contract contract : successSignContractList) {
			String pdfUrl = uploadPdfUrlMap.get(contract.getPlatformInstanceId());
			contract.setUserSignStatus(CommonEnum.YES.getCode());
			contractBusinessService.signSuccess(contract, signer, pdfUrl);
		}
	}


}

public ContractSummaryInfo getContractSummaryInfo(String projectOrderId, Integer signSceneType) {
	if (SignSceneTypeEnum.PERSONAL.getCode().equals(signSceneType)) {
		return getContractSummaryInfoForPersonalScene(projectOrderId);
	}
	return getContractSummaryInfoForFormalScene(projectOrderId);
}

public ContractSummaryInfo getContractSummaryInfoForFormalScene(String projectOrderId) {
	List<Contract> contractList = contractService.getContractList(projectOrderId).stream().filter(contract -> ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus())).collect(Collectors.toList());
	Contract formalContract = contractList.stream().filter(contract -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())).findFirst().orElse(null);
	if (formalContract == null) {
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "请检查是否已发起合同签约", Level.WARN);
	}
	ContractSummaryInfo checkAuth = checkAuth(formalContract, HeaderContext.getUserId());
	if (!AuthCodeEnum.SUCCESS.getCode().equals(checkAuth.getAuthCode())) {
		return checkAuth;
	}
	List<Contract> relateContract = getRelateContract(contractList);
	Integer contractMode = getContractMode(contractList);
	List<ContractSummaryInfo.ContractItemVo> summaryContractList = getSummaryContractList(projectOrderId, relateContract);
	//第一个未签署的合同，用于一键签署页面跳转
	ContractSummaryInfo.ContractItemVo firstNoSignContract = summaryContractList.stream().filter(item -> ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(item.getStatus())).findFirst().orElse(null);
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId);
	Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
	Byte contractObjectType = contractFieldService.getContractObjectType(formalContract.getContractCode());

	ContractSummaryInfo contractSummaryInfo = ContractSummaryInfo.builder()
		.title(getSummaryTitle(relateContract, contractMode, processV25, businessType))
		.oneKeySignOpen(commonContractService.oneKeySignOpen(formalContract))
		.contractList(summaryContractList)
		.processV25(commonBusinessService.isPROCESS_V2_5(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode()))
		.oneKeySignSchema(buildOneKeySignSchema(firstNoSignContract))
		.businessType(businessType)
		.aiAssistantOpen(contractScriptService.aiAssistantOpen(formalContract))
		.contractObjectType(contractObjectType)
		.build();
	if (processV25 && (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) || BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType))) {
		return contractSummaryInfo;
	}
	contractSummaryInfo.setTradeInfo(getTradeInfo(projectOrderId, contractList, relateContract));
	contractSummaryInfo.setServiceDescriptionList(getServiceDescriptionList(relateContract));
	return contractSummaryInfo;
}

public ContractSummaryInfo getContractSummaryInfoForPersonalScene(String projectOrderId){
	boolean processV25 = commonBusinessService.isProcessV25New(projectOrderId);
	Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
	ContractSummaryInfo contractSummaryInfo = ContractSummaryInfo.builder()
		.title("销售合同")
		.contractList(new ArrayList<>())
		.processV25(processV25)
		.businessType(businessType)
		.build();
	List<Contract> personalContract = getPersonalContract(projectOrderId, HeaderContext.getUserId().toString(),ContractStatusEnum.validStatusWithoutDraft);
	List<ContractSummaryInfo.ContractItemVo> summaryContractList = getSummaryContractList(projectOrderId, personalContract);
	if(CollectionUtils.isEmpty(summaryContractList)){
		return contractSummaryInfo;
	}
	List<Contract> waitSignContractList = personalContract.stream()
		.filter(contract -> ContractStatusEnum.allowSignStatus.contains(contract.getStatus())).collect(Collectors.toList());
	boolean oneKeySignOpen = waitSignContractList.stream()
		.allMatch(contract -> commonContractService.oneKeySignOpen(contract));
	contractSummaryInfo.setContractList(summaryContractList);
	contractSummaryInfo.setOneKeySignOpen(oneKeySignOpen);
	contractSummaryInfo.setOneKeySignSchema(oneKeySignOpen && CollectionUtils.isNotEmpty(waitSignContractList) ? buildOneKeySignSchema(waitSignContractList.get(0).getContractCode()) : null);
	return contractSummaryInfo;
}

public List<Contract> getPersonalContract(String projectOrderId, String ucId,List<Integer> contractStatusList) {
	List<Contract> contractList = contractService.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode());
	List<Contract> allowSignContractList = contractList.stream()
		.filter(item -> contractStatusList.contains(item.getStatus()))
		.filter(item -> homeAndPcCommonService.isMultipleQuotePersonalContract(item))
		.collect(Collectors.toList());
	if (CollectionUtils.isEmpty(allowSignContractList)) {
		return new ArrayList<>();
	}
	List<String> allowSignContractCodeList = allowSignContractList.stream().map(Contract::getContractCode).collect(Collectors.toList());
	List<ContractUser> signerList = contractUserService.getSignerByContractCodes(allowSignContractCodeList);
	//获取用户信息
	CUserDTO userDTO = userFeignService.getUserInfo(ucId);
	String loginPhone = cipherService.decrypt(userDTO.getPhone());
	//当前登录人对应合同code列表
	List<String> loginContractCodeList = signerList.stream().filter(item -> ObjectUtil.equal(cipherService.decrypt(item.getPhone()), loginPhone) && ObjectUtil.equal(item.getIsSign(), CommonEnum.YES.getCode()))
		.map(ContractUser::getContractCode).collect(Collectors.toList());
	if (CollectionUtils.isEmpty(loginContractCodeList)) {
		return new ArrayList<>();
	}
	return contractService.getListByContractCodes(loginContractCodeList, false);
}

private ContractSummaryInfo checkAuth(Contract contract, Long ucId) {
	ContractSummaryInfo result = new ContractSummaryInfo();
	ContractUser contractUser = contractUserService.getSignerByContractCode(contract.getContractCode());
	if (Objects.isNull(contractUser)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人-[签约]");
	}
	//加解密
	String contractUserPhone = cipherService.decrypt(contractUser.getPhone());
	//获取用户信息
	CUserDTO userDTO = userFeignService.getUserInfo(ucId.toString());
	String loginPhone = cipherService.decrypt(userDTO.getPhone());
	//校验登录人和签约人是否一致
	if (!loginPhone.equals(contractUserPhone)) {
		result.setAuthCode(AuthCodeEnum.USER_NOT_SAME.getCode());
		result.setAuthError(UserNotSameError.builder()
			.signerPhone(StringUtils.isBlank(contractUserPhone) ? "" : contractUserPhone.substring(contractUserPhone.length() - 4))
			.loginPhone(StringUtils.isBlank(loginPhone) ? "" : loginPhone.substring(loginPhone.length() - 4))
			.helpUrl(contractApolloConfig.getUserNameNotSameHelpUrl())
			.build());
		return result;
	}
	result.setAuthCode(AuthCodeEnum.SUCCESS.getCode());
	return result;
}

private String getSummaryTitle(List<Contract> relateContract, Integer contractMode, boolean processV25, Byte businessType) {
	Contract formalContract = relateContract.stream().filter(contract -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())).findFirst().orElse(null);
	Contract personalContract = relateContract.stream().filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())).findFirst().orElse(null);
	if (formalContract == null) {
		return null;
	}
	if (BusinessTypeEnum.getHouseCertificate25ModeList().contains(businessType)) {
		if (ContractModeEnum.FULL_SERVICE.getCode().equals(contractMode)) {
			return "整装全案合同";
		}
		if (personalContract != null) {
			return "正式套餐合同/图纸/销售合同";
		}
		return "正式套餐合同/图纸";
	}
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
		if (processV25 && personalContract != null) {
			return ContractTypeEnum.getNameByContractTypeAndBusinessType(ContractTypeEnum.PACKAGE_FORMAL.getCode(), businessType) + "及其关联合同";
		}
		return ContractTypeEnum.getNameByContractTypeAndBusinessType(ContractTypeEnum.PACKAGE_FORMAL.getCode(), businessType) + "及其关联合同";
	}
	return "";
}

