private List<FundBaseInfo> getFundBaseInfo(List<Contract> contractList, List<Contract> relateContract) {
	List<FundBaseInfo> fundBaseInfos = new ArrayList<>();
	Contract formalContract = contractList.stream().filter(contract -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())).findFirst().orElse(null);
	Contract designContract = contractList.stream().filter(contract -> Arrays.asList(ContractTypeEnum.DESIGN.getCode(), ContractTypeEnum.DESIGN_CHANGE.getCode()).contains(contract.getType())).max(Comparator.comparing(Contract::getId)).orElse(null);
	List<Contract> personalContractList = relateContract.stream().filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())).collect(Collectors.toList());
	//是否正签约定设计费
	boolean needDesignerAmount = false;
	if (formalContract != null) {
		fundBaseInfos.add(FundBaseInfo.builder()
			.fundName("工程款")
			.amount(formalContract.getAmount())
			.build());
		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(formalContract.getContractCode());
		// 设计费
		needDesignerAmount = contractFieldList.stream().anyMatch(contractField -> contractField.getFieldKey().equals("needDesignerAmount") && contractField.getFieldValue().equals(CommonEnum.YES.getCode().toString()));
		ContractField afterDiscountDesignerAmount = contractFieldList.stream().filter(m -> "afterDiscountDesignerAmount".equals(m.getFieldKey())).findFirst().orElse(null);
		if (needDesignerAmount && afterDiscountDesignerAmount != null && StringUtils.isNotBlank(afterDiscountDesignerAmount.getFieldValue())) {
			fundBaseInfos.add(FundBaseInfo.builder()
				.fundName("设计费")
				.amount(new BigDecimal(afterDiscountDesignerAmount.getFieldValue()))
				.build());
		}
	}
	if (designContract != null && (!needDesignerAmount)) {
		fundBaseInfos.add(FundBaseInfo.builder()
			.fundName("设计费")
			.amount(designContract.getAmount())
			.build());
	}
	if (CollectionUtils.isNotEmpty(personalContractList)) {
		//合同金额累加
		BigDecimal reduceAmount = personalContractList.stream().map(Contract::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
		fundBaseInfos.add(FundBaseInfo.builder()
			.fundName("其他款项（定软电等）")
			.amount(reduceAmount)
			.build());
	}
	return fundBaseInfos;
}

