@Service
@Slf4j
public class ContractPdfFileHandleService {

	/**
	 * 支持中文的字体路径
	 */
	public static final String fontPath = "static/ms-song.ttf";

	@Resource(name = "pdfHandleExecutor")
	private Executor pdfExecutor;

	@Resource
	private S3Service s3Service;

	/**
	 * 批量 PDF 添加文字
	 */
	public List<String> batchAddFooter(List<String> inputPdfs, String footerText, float positionXRatio, float positionYRatio) {
		LOGGER.info("批量pdf文件增加盖章关键字开始");
		long start = System.currentTimeMillis();
		List<CompletableFuture<Void>> futures = new ArrayList<>();
		List<String> modifiedPdfs = new ArrayList<>();
		Map<String, String> modifiedPdfsMap = new HashMap<>();
		UUID uuid = UUID.randomUUID();
		for (int i = 0; i < inputPdfs.size(); i++) {
			String modifiedPdf = "modified_" + uuid + "_" + (i + 1) + ".pdf";
			int finalI = i;
			CompletableFuture<Void> pdfFuture = CompletableFuture.runAsync(() -> {
				try {
					addFooter(inputPdfs.get(finalI), modifiedPdf, footerText, positionXRatio, positionYRatio);
					modifiedPdfsMap.put(inputPdfs.get(finalI), modifiedPdf);
				} catch (Exception e) {
					LOGGER.error("添加文字失败，url:{}，原因: {}", inputPdfs.get(finalI), e.getMessage(), e);
					throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "pdf添加盖章关键字失败", Level.WARN);
				}
			}, pdfExecutor);
			futures.add(pdfFuture);
		}
		CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
		inputPdfs.forEach(pdf -> modifiedPdfs.add(modifiedPdfsMap.get(pdf)));
		LOGGER.info("批量pdf文件增加盖章关键字结束, 耗时: {}ms", System.currentTimeMillis() - start);
		return modifiedPdfs;
	}

	public List<String> addFooterForListInput(List<String> inputPdfs, List<AddFooterTextInfo> addFooterTextInfoList) {
		LOGGER.info("遍历pdf文件增加盖章关键字开始");
		long start = System.currentTimeMillis();
		List<String> modifiedPdfs = new ArrayList<>();
		for (String inputPdf : inputPdfs) {
			String modifiedPdf = "modified_" + UUID.randomUUID() + ".pdf";
			try {
				addFooter(inputPdf, modifiedPdf, addFooterTextInfoList, true);
				modifiedPdfs.add(modifiedPdf);
			} catch (Exception e) {
				LOGGER.error("pdf添加盖章关键字失败, url: {}, 原因: {}", inputPdf, e.getMessage(), e);
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "pdf添加盖章关键字失败", Level.WARN);
			}
		}
		LOGGER.info("遍历pdf文件增加盖章关键字结束, 耗时: {}ms", System.currentTimeMillis() - start);
		return modifiedPdfs;
	}

	/**
	 * 在 PDF 底部添加页脚文字并进行压缩
	 *
	 * @param src        原始 PDF 文件路径
	 * @param dest       输出 PDF 文件路径
	 * @param footerText 页脚文字
	 * @throws IOException 如果发生文件操作错误
	 */
	public void addFooter(String src, String dest, String footerText, float positionXRatio, float positionYRatio) throws IOException {
		// 加载字体，启用子集嵌入
		PdfFont font = PdfFontFactory.createFont(fontPath, PdfEncodings.IDENTITY_H, PdfFontFactory.EmbeddingStrategy.PREFER_NOT_EMBEDDED, true);

		// 设置压缩属性
		PdfWriter writer = new PdfWriter(dest, new WriterProperties().setCompressionLevel(CompressionConstants.BEST_COMPRESSION));
		PdfDocument pdfDoc = new PdfDocument(new PdfReader(src), writer);

		int totalPages = pdfDoc.getNumberOfPages();

		// 遍历每页，添加文字
		for (int i = 1; i <= totalPages; i++) {
			PdfPage page = pdfDoc.getPage(i);
			Rectangle pageSize = page.getPageSize();
			float x = pageSize.getWidth() * positionXRatio;
			float y = pageSize.getHeight() * positionYRatio;

			PdfCanvas canvas = new PdfCanvas(page);
			canvas.beginText()
				.setFontAndSize(font, 12)
				.moveText(x, y)
				.showText(footerText)
				.endText();

			// 压缩每页内容流
			PdfStream stream = page.getContentStream(0);
			stream.setCompressionLevel(CompressionConstants.BEST_COMPRESSION);
		}

		pdfDoc.close();
	}

	/**
	 * 批量压缩PDF
	 */
	public List<String> batchCompressPdf(List<String> inputPdfs, float dpi) {
		LOGGER.info("批量pdf文件压缩开始，dpi: {}", dpi);
		long start = System.currentTimeMillis();
		List<CompletableFuture<Void>> futures = new ArrayList<>();
		List<String> compressPdfs = new ArrayList<>();
		Map<String, String> compressPdfsMap = new HashMap<>();
		UUID uuid = UUID.randomUUID();
		for (int i = 0; i < inputPdfs.size(); i++) {
			String compressPdf = "compress_" + uuid + "_" + (i + 1) + ".pdf";
			int finalI = i;
			CompletableFuture<Void> pdfFuture = CompletableFuture.runAsync(() -> {
				try {
					compressPDF(inputPdfs.get(finalI), compressPdf, dpi);
				} catch (IOException e) {
					LOGGER.info("url:{},压缩失败,原因：{}", inputPdfs.get(finalI), e.getMessage());
					throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "图纸压缩失败", Level.WARN);
				}
				compressPdfsMap.put(inputPdfs.get(finalI), compressPdf);
			}, pdfExecutor);
			futures.add(pdfFuture);
		}
		CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
		inputPdfs.forEach(pdf -> compressPdfs.add(compressPdfsMap.get(pdf)));
		LOGGER.info("批量pdf文件压缩完成，耗时：{}ms", System.currentTimeMillis() - start);
		return compressPdfs;
	}

	/**
	 * 压缩 PDF 文件，支持本地文件或 URL。
	 *
	 * @param inputPathOrUrl 原始 PDF 文件路径或 URL
	 * @param outputPath     压缩后的 PDF 文件路径
	 * @param dpi            渲染的分辨率（数值越低，文件压缩越大）
	 * @throws IOException 如果发生文件操作错误
	 */
	public void compressPDF(String inputPathOrUrl, String outputPath, float dpi) throws IOException {
		File tempDir = new File(UUID.randomUUID().toString());
		if (!tempDir.exists() && !tempDir.mkdirs()) {
			throw new IOException("无法创建临时目录");
		}

		File tempInputFile = null;
		boolean isUrl = inputPathOrUrl.startsWith("http://") || inputPathOrUrl.startsWith("https://");

		try {
			// 下载网络文件到临时文件（如果是 URL）
			if (isUrl) {
				tempInputFile = downloadFileFromUrl(inputPathOrUrl, "await_compress_" + UUID.randomUUID().toString().concat(".pdf"));
				inputPathOrUrl = tempInputFile.getAbsolutePath();
			}

			// 加载 PDF 文件
			try (PDDocument document = PDDocument.load(new File(inputPathOrUrl))) {
				PDFRenderer renderer = new PDFRenderer(document);
				PDDocument compressedDoc = new PDDocument();

				// 遍历每一页，将其转换为压缩后的图像
				for (int i = 0; i < document.getNumberOfPages(); i++) {
					PDRectangle mediaBox = document.getPage(i).getMediaBox();
					float width = mediaBox.getWidth();
					float height = mediaBox.getHeight();
					BufferedImage image = renderer.renderImageWithDPI(i, dpi); // 使用指定 DPI 渲染页面
					PDPage page = new PDPage(new PDRectangle(width, height));
					compressedDoc.addPage(page);

					// 写入临时图像文件并获取文件对象
					File tempImageFile = writeTempImage(image, tempDir, i);

					// 将渲染的图像嵌入新的 PDF
					PDImageXObject pdImage = PDImageXObject.createFromFileByContent(tempImageFile, compressedDoc);
					try (PDPageContentStream contentStream = new PDPageContentStream(compressedDoc, page)) {
						contentStream.drawImage(pdImage, 0, 0, page.getMediaBox().getWidth(), page.getMediaBox().getHeight());
					}
				}

				// 保存压缩后的 PDF
				compressedDoc.save(outputPath);
				compressedDoc.close();
			}
		} finally {
			// 清理临时文件
			deleteDirectory(tempDir);
			if (tempInputFile != null && isFileOrDirectory(tempInputFile) && !tempInputFile.delete()) {
				LOGGER.error("无法删除临时输入文件: {}", tempInputFile.getAbsolutePath());
			}
		}
	}

	private static boolean isFileOrDirectory(File file) {
		return file.isFile() || file.isDirectory();
	}

	/**
	 * 从 URL 下载文件到本地
	 *
	 * @param fileUrl  文件的 URL
	 * @param fileName 本地保存的文件名
	 * @return 本地文件对象
	 * @throws IOException 如果下载失败
	 */
	@Retryable(
		value = {IOException.class}, // 需要重试的异常类型
		maxAttempts = 3, // 最大重试次数
		backoff = @Backoff(delay = 100) // 重试间隔时间
	)
	public File downloadFileFromUrl(String fileUrl, String fileName) throws IOException {
		try {
			URL url = new URL(fileUrl);
			HttpURLConnection connection = (HttpURLConnection) url.openConnection();
			connection.setRequestMethod("GET");
			connection.setConnectTimeout(5000);
			connection.setReadTimeout(5000);

			try (InputStream inputStream = connection.getInputStream();
				 FileOutputStream outputStream = new FileOutputStream(fileName)) {
				byte[] buffer = new byte[1024];
				int bytesRead;
				while ((bytesRead = inputStream.read(buffer)) != -1) {
					outputStream.write(buffer, 0, bytesRead);
				}
			}
		} catch (Exception e) {
			LOGGER.info("从URL下载文件到本地失败: {}", fileUrl);
			throw e;
		}
		return new File(fileName);
	}

	/**
	 * 写入临时图像文件
	 *
	 * @param image   图像数据
	 * @param tempDir 临时目录
	 * @param index   页码
	 * @return 临时图像文件
	 * @throws IOException 如果发生写入错误
	 */
	public static File writeTempImage(BufferedImage image, File tempDir, int index) throws IOException {
		File tempImageFile = new File(tempDir, "temp_page_" + index + ".jpg");
		ImageIO.write(image, "jpg", tempImageFile);
		return tempImageFile;
	}

	/**
	 * 删除目录及其下的所有文件
	 *
	 * @param directory 目录文件
	 */
	public static void deleteDirectory(File directory) {
		if (directory.exists()) {
			File[] files = directory.listFiles();
			if (files != null) {
				for (File file : files) {
					if (file.isDirectory()) {
						deleteDirectory(file);
					} else {
						if (!file.delete()) {
							LOGGER.error("无法删除文件: {}", file.getAbsolutePath());
						}
					}
				}
			}
			if (!directory.delete()) {
				LOGGER.error("无法删除目录: {}", directory.getAbsolutePath());
			}
		}
	}

	// 合并 PDF 文件
	public static void mergePdfs(List<String> pdfPaths, String dest) throws IOException {
		LOGGER.info("pdf文件合并开始，pdfPaths:{}", pdfPaths);
		long start = System.currentTimeMillis();
		PdfDocument mergedDoc = new PdfDocument(new PdfWriter(dest));
		for (String pdfPath : pdfPaths) {
			PdfDocument pdf = new PdfDocument(new PdfReader(pdfPath));
			pdf.copyPagesTo(1, pdf.getNumberOfPages(), mergedDoc);
			pdf.close();
		}
		mergedDoc.close();
		LOGGER.info("pdf文件合并结束,耗时：{}ms", System.currentTimeMillis() - start);
	}

	public static Integer getPdfCount(String pdfFilePath) {
		try (PdfReader reader = new PdfReader(pdfFilePath);
			 PdfDocument pdfDocument = new PdfDocument(reader)) {
			return pdfDocument.getNumberOfPages();
		} catch (IOException e) {
			LOGGER.error("获取PDF页数失败,pdfFilePath:{}", pdfFilePath, e);
			throw new RuntimeException("获取PDF页数失败");
		}
	}

	/**
	 * 将多张图片生成A4大小PDF，每张图片单独占一页
	 *
	 * @param destPath  PDF 文件路径
	 * @param imageUrls 图片链接列表
	 * @throws IOException 如果读取图片或写入 PDF 文件失败
	 */
	public static void createPdfFromImages(String destPath, List<String> imageUrls) throws IOException {
		// 初始化 PDF 文档
		PdfWriter writer = new PdfWriter(destPath);
		PdfDocument pdf = new PdfDocument(writer);
		Document document = new Document(pdf);

		for (String imageUrl : imageUrls) {
			try {
				// 加载图片
				ImageData imageData = ImageDataFactory.create(imageUrl);
				Image image = new Image(imageData);
				// 设置页面大小 A4大小595 × 842
				PageSize pageSize = new PageSize(595, 842);
				pdf.addNewPage(pageSize);
				document.setMargins(0, 0, 0, 0);

				// 添加图片到当前页面
				document.add(image);
			} catch (Exception e) {
				LOGGER.error("将多张图片生成A4大小PDF失败: {}, 错误信息: {}", imageUrl, e.getMessage());
				throw e;
			}
		}
		// 关闭文档
		document.close();
	}

	/**
	 * 图片转pdf并上传s3
	 */
	public String imageToPdfAndUpload(List<String> imageUrlList) {
		if (CollectionUtils.isEmpty(imageUrlList)) {
			return "";
		}
		String tempPath = UUID.randomUUID() + ".pdf";
		try {
			ContractPdfFileHandleService.createPdfFromImages(tempPath, imageUrlList);
			String fileObjectKey = s3Service.md5FileName(UUID.randomUUID().toString()) + ".pdf";
			return s3Service.uploadPublic(Files.readAllBytes(Paths.get(tempPath)), fileObjectKey);
		} catch (IOException e) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "图片转pdf并上传s3失败");
		} finally {
			// 删除临时文件
			ContractPdfFileHandleService.cleanUp(Collections.singletonList(tempPath));
		}
	}

	public static void addFooter(String src, String dest, List<AddFooterTextInfo> addFooterTextInfoList, boolean addToAllPages) throws IOException {
		// 加载字体，启用子集嵌入
		PdfFont font = PdfFontFactory.createFont(fontPath, PdfEncodings.IDENTITY_H, PdfFontFactory.EmbeddingStrategy.PREFER_NOT_EMBEDDED, true);

		// 设置压缩属性
		PdfWriter writer = new PdfWriter(dest, new WriterProperties().setCompressionLevel(CompressionConstants.BEST_COMPRESSION));
		PdfDocument pdfDoc = new PdfDocument(new PdfReader(src), writer);

		// 获取需要处理的页数
		int totalPages = pdfDoc.getNumberOfPages();
		List<PdfPage> pagesToProcess = new ArrayList<>();

		if (addToAllPages) {
			// 选择所有页面
			for (int i = 1; i <= totalPages; i++) {
				pagesToProcess.add(pdfDoc.getPage(i));
			}
		} else {
			// 仅选择最后一页
			pagesToProcess.add(pdfDoc.getLastPage());
		}

		// 逐页添加文字
		for (PdfPage page : pagesToProcess) {
			Rectangle pageSize = page.getPageSize();
			PdfCanvas canvas = new PdfCanvas(page);

			for (AddFooterTextInfo addFooterTextInfo : addFooterTextInfoList) {
				float x = pageSize.getWidth() * addFooterTextInfo.getPositionXRatio();
				float y = pageSize.getHeight() * addFooterTextInfo.getPositionYRatio();
				canvas.beginText()
					.setFontAndSize(font, 12)
					.moveText(x, y)
					.showText(addFooterTextInfo.getText())
					.endText();
			}

			// 压缩每页内容流
			PdfStream stream = page.getContentStream(0);
			stream.setCompressionLevel(CompressionConstants.BEST_COMPRESSION);
		}
		pdfDoc.close();
	}


	/**
	 * 删除文件
	 *
	 * @param pathStrList
	 */
	public static void cleanUp(List<String> pathStrList) {
		for (String pathStr : pathStrList) {
			try {
				Path path = Paths.get(pathStr);
				if (path.toFile().exists()) {
					Files.delete(path);
				}
			} catch (Exception e) {
				LOGGER.info("删除文件失败: {},错误信息：{}", pathStr, e.getMessage());
			}
		}
	}


}

