	if (addToAllPages) {
		// 选择所有页面
		for (int i = 1; i <= totalPages; i++) {
			pagesToProcess.add(pdfDoc.getPage(i));
		}
	} else {
		// 仅选择最后一页
		pagesToProcess.add(pdfDoc.getLastPage());
	}

	// 逐页添加文字
	for (PdfPage page : pagesToProcess) {
		Rectangle pageSize = page.getPageSize();
		PdfCanvas canvas = new PdfCanvas(page);

		for (AddFooterTextInfo addFooterTextInfo : addFooterTextInfoList) {
			float x = pageSize.getWidth() * addFooterTextInfo.getPositionXRatio();
			float y = pageSize.getHeight() * addFooterTextInfo.getPositionYRatio();
			canvas.beginText()
				.setFontAndSize(font, 12)
				.moveText(x, y)
				.showText(addFooterTextInfo.getText())
				.endText();
		}

		// 压缩每页内容流
		PdfStream stream = page.getContentStream(0);
		stream.setCompressionLevel(CompressionConstants.BEST_COMPRESSION);
	}
	pdfDoc.close();
}

public List<String> batchCompressPdf(List<String> inputPdfs, float dpi) {
	LOGGER.info("批量pdf文件压缩开始，dpi: {}", dpi);
	long start = System.currentTimeMillis();
	List<CompletableFuture<Void>> futures = new ArrayList<>();
	List<String> compressPdfs = new ArrayList<>();
	Map<String, String> compressPdfsMap = new HashMap<>();
	UUID uuid = UUID.randomUUID();
	for (int i = 0; i < inputPdfs.size(); i++) {
		String compressPdf = "compress_" + uuid + "_" + (i + 1) + ".pdf";
		int finalI = i;
		CompletableFuture<Void> pdfFuture = CompletableFuture.runAsync(() -> {
			try {
				compressPDF(inputPdfs.get(finalI), compressPdf, dpi);
			} catch (IOException e) {
				LOGGER.info("url:{},压缩失败,原因：{}", inputPdfs.get(finalI), e.getMessage());
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "图纸压缩失败", Level.WARN);
			}
			compressPdfsMap.put(inputPdfs.get(finalI), compressPdf);
		}, pdfExecutor);
		futures.add(pdfFuture);
	}
	CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
	inputPdfs.forEach(pdf -> compressPdfs.add(compressPdfsMap.get(pdf)));
	LOGGER.info("批量pdf文件压缩完成，耗时：{}ms", System.currentTimeMillis() - start);
	return compressPdfs;
}

public void compressPDF(String inputPathOrUrl, String outputPath, float dpi) throws IOException {
	File tempDir = new File(UUID.randomUUID().toString());
	if (!tempDir.exists() && !tempDir.mkdirs()) {
		throw new IOException("无法创建临时目录");
	}

	File tempInputFile = null;
	boolean isUrl = inputPathOrUrl.startsWith("http://") || inputPathOrUrl.startsWith("https://");

	try {
		// 下载网络文件到临时文件（如果是 URL）
		if (isUrl) {
			tempInputFile = downloadFileFromUrl(inputPathOrUrl, "await_compress_" + UUID.randomUUID().toString().concat(".pdf"));
			inputPathOrUrl = tempInputFile.getAbsolutePath();
		}

		// 加载 PDF 文件
		try (PDDocument document = PDDocument.load(new File(inputPathOrUrl))) {
			PDFRenderer renderer = new PDFRenderer(document);
			PDDocument compressedDoc = new PDDocument();

			// 遍历每一页，将其转换为压缩后的图像
			for (int i = 0; i < document.getNumberOfPages(); i++) {
				PDRectangle mediaBox = document.getPage(i).getMediaBox();
				float width = mediaBox.getWidth();
				float height = mediaBox.getHeight();
				BufferedImage image = renderer.renderImageWithDPI(i, dpi); // 使用指定 DPI 渲染页面
				PDPage page = new PDPage(new PDRectangle(width, height));
				compressedDoc.addPage(page);

				// 写入临时图像文件并获取文件对象
				File tempImageFile = writeTempImage(image, tempDir, i);

				// 将渲染的图像嵌入新的 PDF
				PDImageXObject pdImage = PDImageXObject.createFromFileByContent(tempImageFile, compressedDoc);
				try (PDPageContentStream contentStream = new PDPageContentStream(compressedDoc, page)) {
					contentStream.drawImage(pdImage, 0, 0, page.getMediaBox().getWidth(), page.getMediaBox().getHeight());
				}
			}

			// 保存压缩后的 PDF
			compressedDoc.save(outputPath);
			compressedDoc.close();
		}
	} finally {
		// 清理临时文件
		deleteDirectory(tempDir);
		if (tempInputFile != null && isFileOrDirectory(tempInputFile) && !tempInputFile.delete()) {
			LOGGER.error("无法删除临时输入文件: {}", tempInputFile.getAbsolutePath());
		}
	}
}

