public static void mergePdfs(List<String> pdfPaths, String dest) throws IOException {
	LOGGER.info("pdf文件合并开始，pdfPaths:{}", pdfPaths);
	long start = System.currentTimeMillis();
	PdfDocument mergedDoc = new PdfDocument(new PdfWriter(dest));
	for (String pdfPath : pdfPaths) {
		PdfDocument pdf = new PdfDocument(new PdfReader(pdfPath));
		pdf.copyPagesTo(1, pdf.getNumberOfPages(), mergedDoc);
		pdf.close();
	}
	mergedDoc.close();
	LOGGER.info("pdf文件合并结束,耗时：{}ms", System.currentTimeMillis() - start);
}

public static Integer getPdfCount(String pdfFilePath) {
