public static void createPdfFromImages(String destPath, List<String> imageUrls) throws IOException {
	// 初始化 PDF 文档
	PdfWriter writer = new PdfWriter(destPath);
	PdfDocument pdf = new PdfDocument(writer);
	Document document = new Document(pdf);

	for (String imageUrl : imageUrls) {
		try {
			// 加载图片
			ImageData imageData = ImageDataFactory.create(imageUrl);
			Image image = new Image(imageData);
			// 设置页面大小 A4大小595 × 842
			PageSize pageSize = new PageSize(595, 842);
			pdf.addNewPage(pageSize);
			document.setMargins(0, 0, 0, 0);

			// 添加图片到当前页面
			document.add(image);
		} catch (Exception e) {
			LOGGER.error("将多张图片生成A4大小PDF失败: {}, 错误信息: {}", imageUrl, e.getMessage());
			throw e;
		}
	}
	// 关闭文档
	document.close();
}

