public static void cleanUp(List<String> pathStrList) {
	for (String pathStr : pathStrList) {
		try {
			Path path = Paths.get(pathStr);
			if (path.toFile().exists()) {
				Files.delete(path);
			}
		} catch (Exception e) {
			LOGGER.info("删除文件失败: {},错误信息：{}", pathStr, e.getMessage());
		}
	}
}

