	@Resource
	private TTSService ttsService;

	@Resource
	private ContractUserService contractUserService;

	@Resource
	private UserFeignService userFeignService;

	@Resource
	private CipherService cipherService;

	@Resource
	private ScriptDynamicFieldService scriptDynamicFieldService;

	@Resource(name = "contractExplainExecutor")
	private Executor contractExplainExecutor;

	@Resource
	private OrderStandardQueryRpc orderStandardQueryRpc;

	@Resource
	private ContractUnifyService contractUnifyService;


	/**
	 * 异步生成合同讲解脚本
	 */
	@Retryable(value = Exception.class, maxAttempts = 3, backoff = @Backoff(value = 500, multiplier = 1))
	public void asyncGenerateContractScript(String contractCode) {
		// 记录开始时间
		long startTime = System.currentTimeMillis();
		// 判断是否存在已生成的讲解脚本，有则不再生成
		List<VoiceExplainRecord> voiceExplainRecords = voiceExplainRecordService.getByContractCode(contractCode);
		if (CollectionUtil.isNotEmpty(voiceExplainRecords)) {
			LOGGER.info("合同讲解脚本已存在，contractCode: {}", contractCode);
			return;
		}
		// 生成合同讲解脚本
		LOGGER.info("开始生成合同讲解脚本，contractCode: {}", contractCode);
		// 获取合同城市和formKey
		Contract contract = contractService.getByContractCode(contractCode);
		if (ObjectUtil.isEmpty(contract)) {
			LOGGER.warn("合同信息不存在，contractCode: {}", contractCode);
			return;
		}
		// 判断是否开城
		if (!aiAssistantOpen(contract) || !ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
			LOGGER.info("合同智能体讲解未开城，contractCode: {}", contractCode);
			return;
		}
		// 查询脚本配置
		if (ObjectUtil.isEmpty(contract.getPlatformInstanceId())) {
			throw new NrsBusinessException("合同平台实例ID不能为空，contractCode: " + contractCode);
		}
		String formKey = freeformService.getFormKeyByInstanceId(contract.getPlatformInstanceId());
		if (ObjectUtil.isEmpty(formKey)) {
			throw new NrsBusinessException("合同平台实例ID对应的formKey不存在，instanceId: " + contract.getPlatformInstanceId());
		}
		List<ContractScriptModule> moduleList = getScriptModuleConfig(contractCode, ScriptSceneTypeEnum.CONTRACT_EXPLANATION.getCode());
		if (CollectionUtil.isEmpty(moduleList)) {
			LOGGER.warn("合同脚本配置不存在，contractCode: {}", contractCode);
			return;
		}
		// 获取动态字段配置
		Map<Long, ContractScriptModule> moduleMap = moduleList.stream()
			.collect(Collectors.toMap(ContractScriptModule::getId, m -> m, (m1, m2) -> m1));
		List<ContractScriptExplain> scriptExplains = contractScriptExplainService.getByModuleConfigIds(new ArrayList<>(moduleMap.keySet()));
		Set<String> feildNames = scriptExplains.stream()
			.map(ContractScriptExplain::getDynamicFields)
			.filter(ObjectUtil::isNotEmpty)
			.flatMap(s -> Arrays.stream(s.split(",")))
			.filter(str -> !str.trim().isEmpty())
			.collect(Collectors.toSet());
		// 根据字段值获取动态方法
		Map<String, Object> scriptDynamicFieldBs = new HashMap<>();
		if (CollectionUtils.isNotEmpty(feildNames)) {
			scriptDynamicFieldBs = getDynamicFieldValue(contractCode, feildNames);
			// 生成脚本
			scriptExplains = replacePlaceholdersInScripts(scriptExplains, scriptDynamicFieldBs);
		}

		// 使用线程安全的集合存储结果
		List<VoiceExplainRecord> existingRecords = new CopyOnWriteArrayList<>();
		// 保存所有提交的任务，用于后续等待
		List<CompletableFuture<Void>> futures = new ArrayList<>();

		for (ContractScriptExplain explain : scriptExplains) {
			// 提交任务并保存返回的CompletableFuture
			Map<String, Object> finalScriptDynamicFieldBs = scriptDynamicFieldBs;
			CompletableFuture<Void> future = CompletableFuture.runAsync(RunnableWrapper.of(() -> generateAndSaveVoiceExplain(existingRecords, explain, contractCode, moduleMap, finalScriptDynamicFieldBs)), contractExplainExecutor);
			futures.add(future);
		}
		// 等待所有音频生成任务完成
		try {
			CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
		} catch (Exception e) {
			throw new NrsBusinessException("合同讲解脚本生成异常,请重试");
		}

		// 启动事务，批量保存
		transactionTemplate.execute(status -> {
			voiceExplainRecordService.insertBatch(existingRecords);
			return null;
		});
		// 记录结束时间
		long endTime = System.currentTimeMillis();
		LOGGER.info("合同讲解脚本生成耗时: {} ms, contractCode: {}", (endTime - startTime), contractCode);
		LOGGER.info("合同讲解脚本生成完成，contractCode: {}", contractCode);
	}

	/**
	 * 获取动态字段返回值
	 */
	public Map<String, Object> getDynamicFieldValue(String contractCode, Set<String> feildNames) {
		if (CollectionUtils.isEmpty(feildNames)) {
			return Collections.emptyMap();
		}
		List<ScriptDynamicField> scriptDynamicFieldList = scriptDynamicFieldService.getScriptDynamicFieldList(new ArrayList<>(feildNames));
		Set<String> methodNames = scriptDynamicFieldList.stream().map(ScriptDynamicField::getReflectMethod).collect(Collectors.toSet());
		return contractScriptCreateService.getScriptDynamicFieldBs(contractCode, methodNames);
	}

	/**
	 * 持久化数据并进行转义
	 */
	private void generateAndSaveVoiceExplain(List<VoiceExplainRecord> existingRecords, ContractScriptExplain explain, String contractCode, Map<Long, ContractScriptModule> moduleMap, Map<String, Object> scriptDynamicFieldBs) {
		try {
			ContractScriptModule contractScriptModule = moduleMap.get(explain.getModuleConfigId());
			// 初始化方法
			VoiceExplainRecord record = VoiceExplainRecord.builder()
				.businessCode(contractCode)
				.type(VoiceExplainTypeEnum.CONTRACT_EXPLAIN.getCode())
				.moduleType(contractScriptModule.getModuleType())
				.segmentOrder(explain.getExplainOrder())
				.delStatus((byte)0)
				.ctime(new Date())
				.mtime(new Date())
				.build();
			//获取动态字段
			Set<String> scriptDynamicFieldSet = Arrays.stream(explain.getDynamicFields().split(",")).map(String::trim).collect(Collectors.toSet());
			Map<String, Object> dynamicFieldValues = new HashMap<>();
			for (String field : scriptDynamicFieldSet) {
				if (scriptDynamicFieldBs.containsKey(field)) {
					dynamicFieldValues.put(field, scriptDynamicFieldBs.get(field));
				}
			}
			record.setExtInfo(CollectionUtil.isEmpty(dynamicFieldValues) ? "" : JSON.toJSONString(dynamicFieldValues));
			// 调用tts服务生成音频
			AudioDTO audioDTO = ttsService.normalTextToVoice(explain.getScriptText());
			record.setBusinessContent(audioDTO.getAudioUrl());
			record.setRelatedContent(JSON.toJSONString(audioDTO.getSubtitles()));
			existingRecords.add(record);
		} catch (Exception e) {
			LOGGER.error("合同讲解脚本生成异常,请重试, explainId: {}, contractCode: {}", explain.getId(), contractCode, e);
			throw new NrsBusinessException("合同讲解脚本生成异常,请重试");
		}

	}

	/**
	 * 根据合同code获取脚本配置
	 */
	public List<ContractScriptModule> getScriptModuleConfig(String contractCode, Integer sceneType) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (ObjectUtil.isEmpty(contract)) {
			LOGGER.warn("合同信息不存在，contractCode: {}", contractCode);
			return Collections.emptyList();
		}
		// 查询脚本配置
		if (ObjectUtil.isEmpty(contract.getPlatformInstanceId())) {
			throw new NrsBusinessException("合同平台实例ID不能为空，contractCode: " + contractCode);
		}
		String formKey = freeformService.getFormKeyByInstanceId(contract.getPlatformInstanceId());
		if (ObjectUtil.isEmpty(formKey)) {
			throw new NrsBusinessException("合同平台实例ID对应的formKey不存在，instanceId: " + contract.getPlatformInstanceId());
		}
		return getScriptModuleConfig(contract.getGbCode(), formKey, sceneType);

	}


	/**
	 * 获取脚本配置
	 */
	private List<ContractScriptModule> getScriptModuleConfig(Integer gbCode, String formKey, Integer sceneType) {
		List<ContractScriptModule> moduleList = contractScriptModuleService.getByGbCodeAndFormKey(gbCode, formKey, sceneType);
		if (CollectionUtil.isEmpty(moduleList)) {
			moduleList = contractScriptModuleService.getByFormKey(formKey, sceneType);
		}
		return moduleList;
	}

	/**
	 * 将脚本中的占位符替换为实际值
	 */
	public List<ContractScriptExplain> replacePlaceholdersInScripts(List<ContractScriptExplain> scriptExplains, Map<String, Object> dynamicFieldValues) {
		// 入参为空时直接返回，避免空指针
		if (CollectionUtil.isEmpty(scriptExplains) || CollectionUtil.isEmpty(dynamicFieldValues)) {
			return scriptExplains;
		}


		// 遍历处理每个脚本对象
		for (ContractScriptExplain explain : scriptExplains) {
			String scriptText = explain.getScriptText();
			if (StrUtil.isBlank(scriptText)) {
				continue; // 跳过空文本
			}
			// 替换占位符
			String replacedText = replaceDynamicFields(scriptText, dynamicFieldValues);
			explain.setScriptText(replacedText);
		}
		return scriptExplains;
	}

	/**
	 * 动态字段值替换
	 */
	public String replaceDynamicFields(String text, Map<String, Object> dynamicFieldValues) {
		if (StrUtil.isBlank(text) || CollectionUtil.isEmpty(dynamicFieldValues)) {
			return text;
		}
		// 编译正则表达式：匹配${{xxx}}格式的占位符，捕获中间的字段名
		Pattern pattern = Pattern.compile("\\$\\{\\{(\\w+)\\}\\}");
		Matcher matcher = pattern.matcher(text);
		StringBuffer replacedText = new StringBuffer();

		while (matcher.find()) {
			String fieldName = matcher.group(1);
			// 获取字段值并转为字符串
			Object fieldValue = dynamicFieldValues.get(fieldName);
			String valueStr = Objects.toString(fieldValue, "");
			// 整体替换当前占位符（包含${{}}）
			matcher.appendReplacement(replacedText, Matcher.quoteReplacement(valueStr));
		}
		matcher.appendTail(replacedText);
		return replacedText.toString();
	}

	/**
	 * 替换原文列表中的动态字段
	 */
	public List<String> replacePlaceholdersInOriginalTexts(List<String> originalTexts, Map<String, Object> dynamicFieldValues) {
		if (CollectionUtil.isEmpty(originalTexts) || CollectionUtil.isEmpty(dynamicFieldValues)) {
			return originalTexts;
		}
		return originalTexts.stream()
			.map(text -> replaceDynamicFields(text, dynamicFieldValues))
			.collect(Collectors.toList());
	}



	/**
	 * 判断是否智能体讲解开城
	 */
	public Boolean aiAssistantOpen(Contract contract) {
		try {
			boolean processV25New = commonbusinessService.isProcessV25New(contract.getProjectOrderId());
			// 非v2.5及以上版本不支持智能体讲解
			if (!processV25New) {
				return false;
			}
			// 仅开放正签合同
			HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(contract.getProjectOrderId(), Arrays.asList(HomeModelDefEnum.CUSTOMER_ORGANIZATION.toString(), HomeModelDefEnum.CUSTOMER_NEW_HOUSING_PROJECT.name()));
			if (ObjectUtil.isEmpty(homeProject) || ObjectUtil.isEmpty(homeProject.getDecorateType())) {
				return false;
			}
			BusinessTypeEnum businessTypeEnum = BusinessTypeEnum.getEnumByDecorateType(CommissionDecorateTypeEnum.getEnumByCode(homeProject.getDecorateType()));
			if (ObjectUtil.isEmpty(businessTypeEnum)) {
				return false;
			}
			if (!BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessTypeEnum.getCode())) {
				return false;
			}
			// 黑名单不使用讲解
			if (contractApolloConfig.blackContractExplain(contract.getProjectOrderId())) {
				return false;
			}

			// 线下签约不支持智能体讲解
			if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
				return false;
			}
			boolean developerChannel = contractUnifyService.isDeveloperChannel(contract.getProjectOrderId());
			if (developerChannel) {
				return false;
			}
			// 使用Optional包裹整个链式调用过程
			NewHousingProjectModule newHousingProjectModule = Optional.ofNullable(homeProject)
				.map(HomeProject::getHighPriorityProject)
				.map(SubProject::getCustomer)
				.map(SubProjectModel.Customer::getNewHousingProjectModule)
				.orElse(null);
			if (ObjectUtil.isNotEmpty(newHousingProjectModule)) {
				return false;
			}
			//经营部开城
			String businessDepartmentId = homeProject.getByProjectKind(ProjectKindEnum.YING_ZHUANG_XIANG_MU.getType()).getCustomer().getOrganizationModule().getBusinessDepartmentId();
			if (contractApolloConfig.openBusinessDepartment(businessDepartmentId)) {
				return true;
			}
			// 开关未开启不支持智能体讲解
			return contractApolloConfig.openContractExplain(contract.getGbCode());
		} catch (Exception e) {
			LOGGER.error("合同智能体讲解开城异常，contractCode: {}", contract.getContractCode(), e);
			return false;
		}

	}

	/**
	 * @return 树状结构根节点（segmentOrder最小的在最外层），无数据时返回null
	 */
	public ContractScriptTreeVO getContractScriptTree(List<VoiceExplainRecord> records) {
		// 步骤1：查询当前合同对应的有效VoiceExplainRecord列表（按你的实际查询逻辑调整）
		if (CollectionUtil.isEmpty(records)) {
			return null;
		}

		// 步骤2：按segmentOrder升序排序（确保最小序号在最外层）
		List<VoiceExplainRecord> sortedRecords = records.stream()
			.sorted(Comparator.comparingInt(VoiceExplainRecord::getSegmentOrder))
			.collect(Collectors.toList());

		// 步骤3：转换为ContractScriptTreeVO列表（仅处理核心字段映射）
		List<ContractScriptTreeVO> voList = sortedRecords.stream()
			.map(this::convertToTreeVO)
			.collect(Collectors.toList());

		// 步骤4：构建树状结构（autoOption关联下一级，最后一个节点设为null）
		buildTreeHierarchy(voList);

		// 步骤5：返回根节点（最外层节点，即segmentOrder最小的VO）
		return voList.get(0);
	}


	/**
	 * 内部辅助方法：单个VoiceExplainRecord转换为ContractScriptTreeVO（仅处理核心字段）
	 */
	private ContractScriptTreeVO convertToTreeVO(VoiceExplainRecord record) {
		// 1. 解析relatedContent为List<SubtitleDTO>
		List<SubtitleDTO> subtitleList = JSON.parseArray(record.getRelatedContent(), SubtitleDTO.class);
		// 2. 构建VO（仅赋值核心字段，其他字段按你已定义的默认值或业务逻辑处理）
		ContractScriptTreeVO treeVO = new ContractScriptTreeVO();
		treeVO.setDigitManUrl(record.getBusinessContent()); // businessContent填充到digitManUrl
		treeVO.setSubtitleTextList(subtitleList); // relatedContent解析为字幕列表

		// 其他字段若需默认值或空值，无需额外处理（按你已定义的VO逻辑）
		return treeVO;
	}


	/**
	 * 内部辅助方法：构建树状层级（autoOption关联下一级）
	 */
	private void buildTreeHierarchy(List<ContractScriptTreeVO> voList) {
		if (CollectionUtil.isEmpty(voList) || voList.size() == 1) {
			return; // 只有1个节点时，无需关联
		}

		// 遍历关联：当前节点的autoOption指向后一个节点，最后一个节点设为null
		for (int i = 0; i < voList.size() - 1; i++) {
			ContractScriptTreeVO currentVO = voList.get(i);
			ContractScriptTreeVO nextVO = voList.get(i + 1);
			currentVO.setAutoOption(nextVO);
		}
		// 确保最后一个节点的autoOption为null，避免内存溢出或循环引用
		voList.get(voList.size() - 1).setAutoOption(null);
	}

