public List<ContractScriptExplain> replacePlaceholdersInScripts(List<ContractScriptExplain> scriptExplains, Map<String, Object> dynamicFieldValues) {
	// 入参为空时直接返回，避免空指针
	if (CollectionUtil.isEmpty(scriptExplains) || CollectionUtil.isEmpty(dynamicFieldValues)) {
		return scriptExplains;
	}


	// 遍历处理每个脚本对象
	for (ContractScriptExplain explain : scriptExplains) {
		String scriptText = explain.getScriptText();
		if (StrUtil.isBlank(scriptText)) {
			continue; // 跳过空文本
		}
		// 替换占位符
		String replacedText = replaceDynamicFields(scriptText, dynamicFieldValues);
		explain.setScriptText(replacedText);
	}
	return scriptExplains;
}

public String replaceDynamicFields(String text, Map<String, Object> dynamicFieldValues) {
	if (StrUtil.isBlank(text) || CollectionUtil.isEmpty(dynamicFieldValues)) {
		return text;
	}
	// 编译正则表达式：匹配${{xxx}}格式的占位符，捕获中间的字段名
	Pattern pattern = Pattern.compile("\\$\\{\\{(\\w+)\\}\\}");
	Matcher matcher = pattern.matcher(text);
	StringBuffer replacedText = new StringBuffer();

	while (matcher.find()) {
		String fieldName = matcher.group(1);
		// 获取字段值并转为字符串
		Object fieldValue = dynamicFieldValues.get(fieldName);
		String valueStr = Objects.toString(fieldValue, "");
		// 整体替换当前占位符（包含${{}}）
		matcher.appendReplacement(replacedText, Matcher.quoteReplacement(valueStr));
	}
	matcher.appendTail(replacedText);
	return replacedText.toString();
}

public List<String> replacePlaceholdersInOriginalTexts(List<String> originalTexts, Map<String, Object> dynamicFieldValues) {
	if (CollectionUtil.isEmpty(originalTexts) || CollectionUtil.isEmpty(dynamicFieldValues)) {
		return originalTexts;
	}
	return originalTexts.stream()
		.map(text -> replaceDynamicFields(text, dynamicFieldValues))
		.collect(Collectors.toList());
}

public Boolean aiAssistantOpen(Contract contract) {
	try {
		boolean processV25New = commonbusinessService.isProcessV25New(contract.getProjectOrderId());
		// 非v2.5及以上版本不支持智能体讲解
		if (!processV25New) {
			return false;
		}
		// 仅开放正签合同
		HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(contract.getProjectOrderId(), Arrays.asList(HomeModelDefEnum.CUSTOMER_ORGANIZATION.toString(), HomeModelDefEnum.CUSTOMER_NEW_HOUSING_PROJECT.name()));
		if (ObjectUtil.isEmpty(homeProject) || ObjectUtil.isEmpty(homeProject.getDecorateType())) {
			return false;
		}
		BusinessTypeEnum businessTypeEnum = BusinessTypeEnum.getEnumByDecorateType(CommissionDecorateTypeEnum.getEnumByCode(homeProject.getDecorateType()));
		if (ObjectUtil.isEmpty(businessTypeEnum)) {
			return false;
		}
		if (!BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessTypeEnum.getCode())) {
			return false;
		}
		// 黑名单不使用讲解
		if (contractApolloConfig.blackContractExplain(contract.getProjectOrderId())) {
			return false;
		}

		// 线下签约不支持智能体讲解
		if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
			return false;
		}
		boolean developerChannel = contractUnifyService.isDeveloperChannel(contract.getProjectOrderId());
		if (developerChannel) {
			return false;
		}
		// 使用Optional包裹整个链式调用过程
		NewHousingProjectModule newHousingProjectModule = Optional.ofNullable(homeProject)
			.map(HomeProject::getHighPriorityProject)
			.map(SubProject::getCustomer)
			.map(SubProjectModel.Customer::getNewHousingProjectModule)
			.orElse(null);
		if (ObjectUtil.isNotEmpty(newHousingProjectModule)) {
			return false;
		}
		//经营部开城
		String businessDepartmentId = homeProject.getByProjectKind(ProjectKindEnum.YING_ZHUANG_XIANG_MU.getType()).getCustomer().getOrganizationModule().getBusinessDepartmentId();
		if (contractApolloConfig.openBusinessDepartment(businessDepartmentId)) {
			return true;
		}
		// 开关未开启不支持智能体讲解
		return contractApolloConfig.openContractExplain(contract.getGbCode());
	} catch (Exception e) {
		LOGGER.error("合同智能体讲解开城异常，contractCode: {}", contract.getContractCode(), e);
		return false;
	}

}

