	public void invalidCustomerTransfer(String projectOrderId) {
		LOGGER.info("签约无效客源home1.0刷2.5，项目id:{}", projectOrderId);
		List<Contract> contractList = contractService.getContractList(projectOrderId);
		LOGGER.info("签约无效客源home1.0刷2.5，合同信息:{}", JSON.toJSONString(contractList));

		// 没有合同则无需处理
		if (CollectionUtils.isEmpty(contractList)) {
			return;
		}

		if (contractList.size() > 1) {
			throw new NrsBusinessException("合同数量有误");
		}

		Contract contract = contractList.get(0);
		if (!ContractTypeEnum.DESIGN.getCode().equals(contract.getType())) {
			throw new NrsBusinessException("合同类型有误");
		}

		// 软删合同
		contractService.softDeleteById(contract.getId());
		quotationRelationCommonService.cancelContractRelations(contract.getContractCode());
	}

