	/**
	 * 参数为projectOrderIdList,导出签约人ucid
	 * @param file
	 * @return
	 */
	@Async
	public String importOrderExportSignUser(MultipartFile file) throws InterruptedException {
		//读入excel文件excelFile,解析表格的第一列,转换为数组信息,数组为List<String>
		List<String> projectOrderIdList = new ArrayList<>();
		try {
			InputStream inputStream = file.getInputStream();
			Workbook workbook = WorkbookFactory.create(inputStream);
			Sheet sheet = workbook.getSheetAt(0); // 获取第一个工作表
			for (Row row : sheet) {
				Cell cell = row.getCell(0); // 获取第一列的单元格
				if (cell != null) {
					projectOrderIdList.add(cell.toString()); // 将单元格的值添加到列表中
				}
			}
			workbook.close();
			inputStream.close();
		} catch (Exception e) {
			LOGGER.error("导数据脚本解析表格出错,{}", e.getMessage());
			return "导数据脚本解析表格出错";
		}
		if (CollectionUtils.isEmpty(projectOrderIdList)) {
			throw new NrsBusinessException("导入的项目id为空");
		}

		//将projectOrderIdList进行分组，每组50个projectOrderId
		List<List<String>> projectOrderIdGroupList = ListUtils.partition(projectOrderIdList, 50);

		List<ContractUserDTO> contractUserList = new ArrayList<>();
		for (List<String> projectOrderIds : projectOrderIdGroupList) {
			//获取项目下所有已签署的正签合同
			List<Contract> contractList = contractService.getBatchBaseContractInfo(new ArrayList<>(),projectOrderIds,
				Collections.singletonList(ContractTypeEnum.PACKAGE_FORMAL.getCode()), true);
			List<Contract> contractSignList = contractList.stream()
				.filter(contract -> ContractStatusEnum.USER_CONFIRMED.getCode().equals(contract.getStatus()) || ContractStatusEnum.FINISH.getCode().equals(contract.getStatus()) ||
					(ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus()) && CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus())))
				.collect(Collectors.toList());
			if (CollectionUtils.isEmpty(contractSignList)) {
				contractUserList.addAll(projectOrderIds.stream().map(projectOrderId -> ContractUserDTO.builder().projectOrderId(projectOrderId).emptyMsg("正签合同未生成")
					.build()).collect(Collectors.toList()));
				continue;
			}
			//获取合同下的签署人
			List<ContractUser> userList = contractUserService.getListByContractCodes(contractSignList.stream().map(Contract::getContractCode).collect(Collectors.toList()));
			List<ContractUser> signerList = userList.stream().filter(user -> CommonEnum.YES.getCode().equals(user.getIsSign())).collect(Collectors.toList());
			List<String> phones = signerList.stream().map(ContractUser::getPhone).distinct().collect(Collectors.toList());
			Map<String, String> phoneMap = new HashMap<>();
			Map<String, String> ucidMap = new HashMap<>();
			//根据手机号获取用户ID
			try {
				//<密文, 明文>
				phoneMap = cipherService.decrypt(phones);
				//<phone明文, ucid>
				ucidMap = memberRpc.queryUcIdByPhoneBatch(new ArrayList<>(phoneMap.values()));
			} catch (Exception e) {
				String msg = e.getMessage().substring(0, Math.min(e.getMessage().length(), 100));
				LOGGER.error("根据手机号获取用户ID异常,{}", msg);
				contractUserList.addAll(projectOrderIds.stream().map(projectOrderId -> ContractUserDTO.builder().projectOrderId(projectOrderId).emptyMsg(msg)
					.build()).collect(Collectors.toList()));
			}
			//结果数据组装&异常处理
			for (String projectOrderId : projectOrderIds) {
				ContractUserDTO contractUserDTO = new ContractUserDTO();
				contractUserDTO.setProjectOrderId(projectOrderId);
				Contract contract = contractSignList.stream().filter(c -> projectOrderId.equals(c.getProjectOrderId())).findFirst().orElse(null);
				if (contract == null) {
					contractUserDTO.setEmptyMsg("正签合同未生成");
					contractUserList.add(contractUserDTO);
					continue;
				}
				ContractUser signer = signerList.stream().filter(user -> contract.getContractCode().equals(user.getContractCode())).findFirst().orElse(null);
				if (signer == null) {
					contractUserDTO.setEmptyMsg("合同未签署");
					contractUserList.add(contractUserDTO);
					continue;
				}
				String phone = signer.getPhone();
				String decryptPhone = phoneMap.get(phone);
				String ucid = ucidMap.get(decryptPhone);
				if (StringUtils.isBlank(ucid)) {
					contractUserDTO.setEmptyMsg("根据手机号获取用户ID为空");
					contractUserList.add(contractUserDTO);
					continue;
				}
				contractUserDTO.setUcid(ucid);
				contractUserList.add(contractUserDTO);
			}
			//每50个查询sleep 10ms
			TimeUnit.MILLISECONDS.sleep(10L);
		}
		MockMultipartFile multipartFile = ModelSwitchExcelUtil.export("签约人ucid", contractUserList, ContractUserDTO.class, SIGN_USER_EXCEL_HEAD);
		FileInfoDTO fileInfoDTO = s3Service.multiPartUploadFile(multipartFile);
		LOGGER.info("导出签约人ucid表格链接：{}", fileInfoDTO.getFilePrevUrl());
		return fileInfoDTO.getFilePrevUrl();
	}


	public void dealHistoryContractRelation(DealHistoryContractParam dealHistoryContractParam) throws InterruptedException {
		if(CollectionUtils.isNotEmpty(dealHistoryContractParam.getProjectOrderIds())){
			for (String projectOrderId : dealHistoryContractParam.getProjectOrderIds()) {
				dealHistoryContractRelation(projectOrderId);
			}
			return;
		}
		Long startId = dealHistoryContractParam.getStartId() == null ? 1 : dealHistoryContractParam.getStartId();
		Long endId = dealHistoryContractParam.getEndId() == null ? 1 : dealHistoryContractParam.getEndId();
		while (startId <= endId) {
			PageInfo<Contract> contractPageInfo = contractService.selectPageByExample(Example.builder(Contract.class)
				.andWhere(Sqls.custom().andGreaterThanOrEqualTo(BaseModel.Fields.id, startId)
					.andLessThanOrEqualTo(BaseModel.Fields.id, endId)
					.andEqualTo(Contract.Fields.type, ContractTypeEnum.DRAWING.getCode())
					.andIn(Contract.Fields.status, ContractStatusEnum.validStatusWithoutDraft)
					.andEqualTo(Contract.Fields.delStatus, CommonEnum.NO.getCode())
				)
				.build(), 1, 100);
			List<Contract> contractList = contractPageInfo.getList();
			LOGGER.info("处理历史合并发起合同关联关系,startId:{},endId:{},size:{}", startId, endId, contractList.size());
			if (contractList.isEmpty()) {
				break;
			}
			for (Contract contract : contractList) {
				dealHistoryContractRelation(contract.getProjectOrderId());
			}
			Thread.sleep(100L);
			startId = contractList.get(contractList.size() - 1).getId() + 1L;
		}
	}

	/**
	 * 处理历史合并发起合同关联关系
	 */
	public void dealHistoryContractRelation(String projectOrderId) {
		try {
			List<String> relationContractCode = new ArrayList<>();
			Contract formalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode()).stream().filter(item -> ContractStatusEnum.validStatusWithoutDraft.contains(item.getStatus())).findFirst().orElse(null);
			Contract drawingContract = contractService.getContractList(projectOrderId, ContractTypeEnum.DRAWING.getCode()).stream().filter(item -> ContractStatusEnum.validStatusWithoutDraft.contains(item.getStatus())).findFirst().orElse(null);
			if (formalContract == null || drawingContract == null) {
				LOGGER.info("处理历史合并发起合同关联关系，正签合同或图纸合同不存在，projectOrderId:{}", projectOrderId);
				return;
			}
			relationContractCode.add(drawingContract.getContractCode());
			Contract personalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode()).stream().filter(item -> ContractStatusEnum.validStatusWithoutDraft.contains(item.getStatus()))
				.filter(item -> StringUtils.isBlank(item.getChangeOrderId()))
				.findFirst().orElse(null);
			if (personalContract != null) {
				//获取是否为协同发起个性化合同
				boolean multipleQuotePersonalContract = homeAndPcCommonService.isMultipleQuotePersonalContract(personalContract);
				if (!multipleQuotePersonalContract) {
					//非协同发起个性化合同则为合并发起的个性化主材合同
					relationContractCode.add(personalContract.getContractCode());
				}
			}
			contractSubmitService.bindContractRelation(formalContract, relationContractCode, ContractRelationEnum.MERGE_LAUNCH);
		} catch (Exception e) {
			LOGGER.info("处理历史合并发起合同关联关系发生异常，projectOrderId:{}", projectOrderId);
		}
	}

	public void checkAllFormConfig(){
		//已经检查过的formId
		Map<Integer,Object> checkedFormIdMap = new HashMap<>();
		Long startId =0L;
		Long endId = Long.MAX_VALUE;
		while (startId <= endId) {
			PageInfo<ContractCityCompanyInfo> configPageInfo = contractCityCompanyInfoService.selectPageByExample(Example.builder(ContractCityCompanyInfo.class)
				.andWhere(Sqls.custom().andGreaterThanOrEqualTo(BaseModel.Fields.id, startId)
					.andLessThanOrEqualTo(BaseModel.Fields.id, endId)
					.andEqualTo(Contract.Fields.delStatus, CommonEnum.NO.getCode())
				)
				.build(), 1, 100);
			List<ContractCityCompanyInfo> configList = configPageInfo.getList();
			LOGGER.info("检查formId配置信息,startId:{},endId:{},size:{}", startId, endId, configList.size());
			if (configList.isEmpty()) {
				break;
			}
			for (ContractCityCompanyInfo contractCityCompanyInfo : configList) {
				if (ContractTypeEnum.NO_CHECK_FORM_FIELD_LIST.contains(Byte.valueOf(String.valueOf(contractCityCompanyInfo.getContractType())))) {
					continue;
				}
				if (!checkedFormIdMap.containsKey(contractCityCompanyInfo.getFormId())) {
					Set<String> deficiencyFields = commonContractService.getFreeformDeficiencyFields(Long.valueOf(contractCityCompanyInfo.getFormId()));
					if (CollectionUtils.isNotEmpty(deficiencyFields)) {
						LOGGER.error("检查formId字段配置信息发现异常，formId:{},缺失字段:{}", contractCityCompanyInfo.getFormId(), deficiencyFields);
					}
					checkedFormIdMap.put(contractCityCompanyInfo.getFormId(), null);
				}
				if (!checkedFormIdMap.containsKey(contractCityCompanyInfo.getSecondFormId()) && isNotZero(contractCityCompanyInfo.getSecondFormId())) {
					Set<String> deficiencyFields = commonContractService.getFreeformDeficiencyFields(Long.valueOf(contractCityCompanyInfo.getSecondFormId()));
					if (CollectionUtils.isNotEmpty(deficiencyFields)) {
						LOGGER.error("检查secondFormId字段配置信息发现异常，secondFormId:{},缺失字段:{}", contractCityCompanyInfo.getSecondFormId(), deficiencyFields);
					}
					checkedFormIdMap.put(contractCityCompanyInfo.getSecondFormId(), null);
				}
				if (!checkedFormIdMap.containsKey(contractCityCompanyInfo.getThirdFormId())&& isNotZero(contractCityCompanyInfo.getThirdFormId())) {
					Set<String> deficiencyFields = commonContractService.getFreeformDeficiencyFields(Long.valueOf(contractCityCompanyInfo.getThirdFormId()));
					if (CollectionUtils.isNotEmpty(deficiencyFields)) {
						LOGGER.error("检查thirdFormId字段配置信息发现异常，thirdFormId:{},缺失字段:{}", contractCityCompanyInfo.getThirdFormId(), deficiencyFields);
					}
					checkedFormIdMap.put(contractCityCompanyInfo.getThirdFormId(), null);
				}

			}
			startId = configList.get(configList.size() - 1).getId() + 1L;
		}
	}

