	/**
	 * 刷历史数据，增加解约协议配置、增加线下、协议确认的配置信息
	 */
	public void addTerminalConfig(String gbCodes) {
		//查出所有城市下面的解约协议合同配置、正式签署的。补全其对应的协议确认、线下签署配置
		List<ContractCityCompanyInfo> configList = contractCityCompanyInfoService.getConfigByContractType(ContractTypeEnum.TERMINAL.getCode());
		List<ContractCityCompanyInfo> onlineSignConfigList = configList.stream().filter(item -> SignChannelTypeEnum.ONLINE.getCode().equals(item.getSignChannelType()))
			.filter(item -> UserSignTypeEnum.SIGN.getCode().equals(Byte.valueOf(item.getUserSignType())))
			.collect(Collectors.toList());
		if (StringUtils.isNotBlank(gbCodes)) {
			List<Integer> gbCodeList = Arrays.stream(gbCodes.split(",")).map(Integer::parseInt).collect(Collectors.toList());
			onlineSignConfigList = onlineSignConfigList.stream().filter(item -> gbCodeList.contains(item.getGbCode())).collect(Collectors.toList());
		}
		List<ContractCityCompanyInfo> addConfigList = new ArrayList<>();
		for (ContractCityCompanyInfo info : onlineSignConfigList) {
			//正式签署 SignChannelTypeEnum 1，UserSignTypeEnum 2
			//协议确认 SignChannelTypeEnum 1，UserSignTypeEnum 1
			//线下签约 SignChannelTypeEnum 2，UserSignTypeEnum 2
			//判断对应的协议确认、线下签署是否存在不存在则新增
			ContractCityCompanyInfo 协议确认 = contractCityCompanyInfoService.getConfig(info.getGbCode(), info.getCompanyCode(), info.getBusinessType(), info.getContractType().byteValue(), SignChannelTypeEnum.ONLINE.getCode(), UserSignTypeEnum.CONFIRM.getCode(), info.getVersion());
			if (协议确认 != null) {
				LOGGER.info("协议确认配置已存在,gbCode:{},companyCode:{},businessType:{},contractType:{},version:{}", info.getGbCode(), info.getCompanyCode(), info.getBusinessType(), info.getContractType(), info.getVersion());
			}else{
				协议确认 = new ContractCityCompanyInfo();
				BeanUtils.copyProperties(info, 协议确认);
				协议确认.setId(null);
				协议确认.setSignChannelType(SignChannelTypeEnum.ONLINE.getCode());
				协议确认.setUserSignType(UserSignTypeEnum.CONFIRM.getCode().toString());
				协议确认.setCtime(new Date());
				协议确认.setMtime(new Date());
				addConfigList.add(协议确认);
			}
			ContractCityCompanyInfo 线下签署 = contractCityCompanyInfoService.getConfig(info.getGbCode(), info.getCompanyCode(), info.getBusinessType(), info.getContractType().byteValue(), SignChannelTypeEnum.OFFLINE.getCode(), UserSignTypeEnum.SIGN.getCode(), info.getVersion());
			if (线下签署 != null) {
				LOGGER.info("线下签署配置已存在,gbCode:{},companyCode:{},businessType:{},contractType:{},version:{}", info.getGbCode(), info.getCompanyCode(), info.getBusinessType(), info.getContractType(), info.getVersion());
			}else{
				线下签署 = new ContractCityCompanyInfo();
				BeanUtils.copyProperties(info, 线下签署);
				线下签署.setId(null);
				线下签署.setSignChannelType(SignChannelTypeEnum.OFFLINE.getCode());
				线下签署.setUserSignType(UserSignTypeEnum.SIGN.getCode().toString());
				线下签署.setCtime(new Date());
				线下签署.setMtime(new Date());
				addConfigList.add(线下签署);
			}
		}
		if (CollectionUtils.isNotEmpty(addConfigList)) {
			LOGGER.info("需要新增的配置信息:{}", JSON.toJSONString(addConfigList));
			contractCityCompanyInfoService.insertBatch(addConfigList);
		}

	}

	public void checkDrawingAreaSize(List<String> projectOrderIds) {
		for (String projectOrderId : projectOrderIds) {
			DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = atomDrawingRpc.listDrawings(projectOrderId);
			if (deliverDrawingDTO == null || org.springframework.util.CollectionUtils.isEmpty(deliverDrawingDTO.getDrawingDetailDTOList())) {
