	public void insertThirdForm(ThirdFormReq req) {
		Integer gbCode = req.getGbCode();
		String companyCode = req.getCompanyCode();
		Byte contractType = req.getContractType();

		if (gbCode == null || contractType == null) {
			throw new NrsBusinessException("gbCode 或 contractType 不能为空！");
		}

		Byte businessType = BusinessTypeEnum.HOUSE_CERTIFICATE.getCode();
		Byte processMode = ProcessModeEnum.模式2_5.getMode();

		/**
		 * 整装 2.5 场景下，gb_code、contract_type 必传，并筛选出 third_form_key = '' and third_form_id = 0 的数据。
		 * companyCode 如果不传，则更新整装 2.5 场景下所有的 thirdFormKey、thirdFormId。
		 */
		Example example = new Example(ContractCityCompanyInfo.class);
		Example.Criteria createCriteria = example.createCriteria()
			.andEqualTo("businessType", businessType)
			.andEqualTo("processMode", processMode)
			.andEqualTo("gbCode", gbCode)
			.andEqualTo("contractType", contractType);

		if (StringUtils.isNotBlank(companyCode)) {
			createCriteria.andEqualTo("companyCode", companyCode);
		}

		ContractCityCompanyInfo toUpdate = ContractCityCompanyInfo.builder()
			.thirdFormId(req.getThirdFormId())
			.thirdFormKey(req.getThirdFormKey())
			.build();
		contractCityCompanyInfoService.updateByExample(toUpdate, example);
	}

