	/**
	 * 套餐待刷的数据：全量数据
	 * 开渠数据插入方式（2 种）：
	 * 1、手动插入：同一个 comboCode 下，会插入一条新数据，ctime 是最新的
	 * 2、脚本刷数：同一个【comboCode + ctime】下，会拷贝一份数据
	 * 幂等校验：根据 comboCode + ctime 进行幂等校验，
	 */
	@Transactional
	public Integer copyComboInfoV2() {
		int result = 0;
		Example example = new Example(ContractComboInfo.class);
		example.createCriteria()
			.andEqualTo("contractFormType", ContractFormTypeEnum.NORMAL_HOUSE.getCode());
		example.orderBy("id").asc();
		int pageNum = 1;
		int pageSize = 50;
		while (true) {
			List<ContractComboInfo> toAddDataList = new ArrayList<>();
			// 1、分页查询，根据 id 升序查（保证查询稳定）
			List<ContractComboInfo> pageConfig = contractComboInfoService.selectPageByExample(example, pageNum, pageSize).getList();
			if (CollectionUtils.isEmpty(pageConfig)) {
				LOGGER.info("【套餐】分页处理结束, pageNum: {}, pageSize: {}, 处理数据总条数: {}", pageNum, pageSize, result);
				return result;
			}
			List<Long> updatedIds = new ArrayList<>();
			// 2、遍历待处理数据
			for (ContractComboInfo oldData : pageConfig) {
				// 2.1、重复插入校验：只能校验出通过脚本重复刷的数据，如果手动添加不同数据，则校验不出
				List<ContractComboInfo> contractComboInfos = contractComboInfoService.select(ContractComboInfo.builder()
					.ctime(oldData.getCtime())
					.comboCode(oldData.getComboCode())
					.comboName(oldData.getComboName())
					.createUserId("1000000030973949")
					.contractFormType(ContractFormTypeEnum.DEVELOPER_CHANNEL.getCode())
					.build());

				// 2.2、如果当前这条数据已经拷贝过一份了，则不重复拷贝
				if (CollectionUtils.isNotEmpty(contractComboInfos)) {
					LOGGER.info("【套餐】存在重复开渠配置，id: {}, comboCode: {}, comboName: {}, ctime: {}", oldData.getId(), oldData.getComboCode(), oldData.getComboName(), oldData.getCtime());
					continue;
				}

				// 2.3、深拷贝一份，插入新数据
				ContractComboInfo toAddData = JSON.parseObject(JSON.toJSONString(oldData), ContractComboInfo.class);
				toAddData.setId(null);
				toAddData.setMtime(new Date());
				toAddData.setCreateUserId("1000000030973949");
				toAddData.setContractFormType(ContractFormTypeEnum.DEVELOPER_CHANNEL.getCode());
				toAddDataList.add(toAddData);
				// 2.4 记录需要处理的处理
				updatedIds.add(oldData.getId());
			}

			// 3、记录处理数据总量
			result += toAddDataList.size();
			LOGGER.info("【套餐】拷贝数据, pageNum: {}, pageSize: {}, 当前批次处理条数: {}, 当前批次处理数据: {}", pageNum, pageSize, updatedIds.size(), JSON.toJSONString(updatedIds));
			if (CollectionUtils.isNotEmpty(toAddDataList)) {
				// 4、数据为空，批量插入会抛出异常
				contractComboInfoService.insertBatch(toAddDataList);
			}
			pageNum ++;
		}
	}

