	/**
	 * 协议模版配置拷贝
	 * @param sourceFormId 源formId
	 * @param targetFormId 目标formId
	 */
	@Transactional
	public void protocolConfigCopy(Integer sourceFormId, Integer targetFormId) {
		CustomForm sourceCustomForm = validateAndGetCustomForm(sourceFormId, "源");
		CustomForm targetCustomForm = validateAndGetCustomForm(targetFormId, "目标");

		List<ContractProtocolConfig> sourceConfigs = contractProtocolConfigService.getContractProtocolConfig(sourceCustomForm.getFormKey(), sourceFormId);
		if (CollectionUtils.isEmpty(sourceConfigs)) {
			throw new NrsBusinessException("未查询到对应的源协议模版配置，formId：" + sourceFormId, Level.WARN);
		}

		int deletedCount = contractProtocolConfigService.deleteByFormId(targetFormId);
		LOGGER.info("协议模版配置拷贝，删除目标协议模版下的配置完成，formId：{}，deletedCount：{}", targetFormId, deletedCount);

		for (ContractProtocolConfig config : sourceConfigs) {
			config.setId(null);
			config.setFormKey(targetCustomForm.getFormKey());
			config.setFormId(targetFormId);
		}
		contractProtocolConfigService.insertBatch(sourceConfigs);
		LOGGER.info("协议模版配置拷贝完成，sourceFormId：{}，targetFormId：{}，拷贝数据量：{}", sourceFormId, targetFormId, sourceConfigs.size());
		LOGGER.info("协议模版配置拷贝完成，sourceFormId：{}，targetFormId：{}，sourceConfigs：{}", sourceFormId, targetFormId, JSON.toJSONString(sourceConfigs));
	}

	private CustomForm validateAndGetCustomForm(Integer formId, String type) {
		CustomForm customForm = freeformService.queryCustomForm(formId);
		if (customForm == null) {
			throw new NrsBusinessException("未查询到对应的" + type + "协议模版配置，formId：" + formId, Level.WARN);
		}
		return customForm;
	}

	/**
	 * 处理套餐配置数据
	 * @param comboCodes 可选的套餐编码列表，如果传入则只处理指定的comboCode，否则处理所有
	 */
	public void generateComboMaterial(List<String> comboCodes) {
		Map<String, MaterialPdfData> result = new HashMap<>();
		// 确定要处理的 comboCode 列表
		List<String> targetComboCodes;
		if (CollectionUtils.isNotEmpty(comboCodes)) {
			targetComboCodes = comboCodes;
			LOGGER.info("处理套餐配置数据-使用传入的comboCode, 数量:{}", targetComboCodes.size());
		} else {
			targetComboCodes = contractComboInfoService.getAllDistinctComboCodes();
			LOGGER.info("处理套餐配置数据-从数据库查询所有comboCode, 数量:{}", targetComboCodes.size());
		}

		// 初始化数据时，逐条进行处理
		for (String comboCode : targetComboCodes) {
			try {
				result.put(comboCode, MaterialPdfData.builder().comboCode(comboCode).build());
				Map<String, MaterialPdfData> materialPdfData =
					comboInfoMaterialGenerator.generateAndReplaceMaterialList(Collections.singletonList(comboCode));
				result.putAll(materialPdfData);
			} catch (Exception e) {
				LOGGER.info("材料配送清单生成失败, comboCode: {}", comboCode, e);
			}
		}
		LOGGER.info("系统自动生成材料配送清单, 生成结果: {}", JSON.toJSONString(result));

		// 导出 excel 文件
		String s3Url = exportExcel(result);
		LOGGER.info("excel 文件上传 url: {}", s3Url);
	}

	public String exportExcel(Map<String, MaterialPdfData> result) {
		List<MaterialPdfDataExcelDTO> excelData = result.values().stream()
			.map(materialPdfData ->
				MaterialPdfDataExcelDTO.builder()
				.comboCode(materialPdfData.getComboCode())
				.materialPdfUrl(materialPdfData.getMaterialPdfUrl())
				.materialImageUrls(materialPdfData.getMaterialImageUrls())
				.build()
			).collect(Collectors.toList());
		String fileName = "material_list" + System.currentTimeMillis() + Constant.FILE_SUFFIX_XLSX;
		ByteArrayOutputStream excelFile = new ByteArrayOutputStream();
		ExcelUtils.download(excelFile, MaterialPdfDataExcelDTO.class, excelData, fileName);
		return s3Service.uploadPublic(excelFile.toByteArray(), fileName);
	}

