	/**
	 * 导出撤销合同结果Excel
	 */
	private String exportUndoContractResult(List<UndoContractExportDTO> exportDTOList) {
		// 按订单号升序排序
		exportDTOList.sort(
			Comparator.comparing(UndoContractExportDTO::getProjectOrderId, Comparator.nullsLast(String::compareTo)));
		// 生成excel文件
		String fileName = "undo_contract_result_" + System.currentTimeMillis()
				+ Constant.FILE_SUFFIX_XLSX;
		ByteArrayOutputStream excelFile = new ByteArrayOutputStream();
		ExcelUtils.download(excelFile, UndoContractExportDTO.class, exportDTOList, fileName);
		// 上传S3并返回URL
		return s3Service.uploadPublic(excelFile.toByteArray(), fileName);
	}


	public void changeBinding(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		// 协同报价单换绑至 S 单
		quotationRelationCommonService.convertChangeToSubOrder(contract, contract.getChangeOrderId());

		// 变更单换绑至 S 单
		quotationRelationCommonService.convertCooperBillToSubOrderByContract(contract);

		List<String> billCodes = contractQuotationRelationService.getByContractCode(contractCode, RelationStatusEnum.RELATED.getCode())
			.stream()
			.filter(relation -> BindTypeEnum.BILL_CODE.getCode().equals(relation.getBindType()))
			.map(ContractQuotationRelation::getBillCode)
			.collect(Collectors.toList());

		List<BudgetBillDTO.BillDTO> bills = atomBudgetRpc.queryBillsByBillCodes(billCodes);

		// 基础报价单号
		String standardBillCode = bills.stream().filter(bill -> GeneralBillTypeEnum.BUDGET_STANDARD.getCode().equals(bill.getBillType())).map(BudgetBillDTO.BillDTO::getBillCode).findFirst().orElse("");
		quotationRelationCommonService.convertStandardBillToSubOrder(contract, standardBillCode);
	}

	/**
	 * 刷数：修复 contract_quotation_relation 的报价单换绑关系
	 * 将报价单（基础报价单/协同报价单）换绑为对应的 S 单
	 *
	 * @param startId      起始ID，可选。用于小范围验证，配合 endId 使用
	 * @param endId        结束ID，可选。用于小范围验证，配合 startId 使用
	 */
	public void repairContractQuotationRelation(Long startId, Long endId) {
		// 全量模式（支持按 ID 范围过滤）
		repairAll(startId, endId);
	}

	/**
	 * 全量刷数
	 *
	 * @param startId 起始ID，null 表示从第一条开始
	 * @param endId   结束ID，null 表示处理到最后一条
	 */
	private void repairAll(Long startId, Long endId) {
		LOGGER.info("[刷数]开始刷数，startId={}, endId={}", startId, endId);
		int pageNum = 1;
		int pageSize = 50;
		long totalProcessed = 0;
		while (true) {
			Example example = new Example(ContractQuotationRelation.class);
			Example.Criteria criteria = example.createCriteria()
				.andEqualTo("status", RelationStatusEnum.RELATED.getCode())
				.andEqualTo("bindType", BindTypeEnum.BILL_CODE.getCode())
				.andEqualTo("delStatus", 0);
			// 支持按 ID 范围过滤
			if (startId != null) {
				criteria.andGreaterThanOrEqualTo("id", startId);
			}
			if (endId != null) {
				criteria.andLessThanOrEqualTo("id", endId);
			}
			example.orderBy("id").asc();

			PageInfo<ContractQuotationRelation> pageInfo = contractQuotationRelationService.selectPageByExample(example, pageNum, pageSize);
			List<ContractQuotationRelation> relations = pageInfo.getList();

			if (CollectionUtils.isEmpty(relations)) {
				LOGGER.info("[刷数]全量刷数结束，pageNum={}, 总处理条数={}", pageNum, totalProcessed);
				break;
			}

			LOGGER.info("[刷数]处理第{}页，数据条数={}", pageNum, relations.size());

			// 过滤非销售合同的关联关系
			List<ContractQuotationRelation> personalRelations = filterPersonalContractRelations(relations);
			if (CollectionUtils.isEmpty(personalRelations)) {
				LOGGER.info("[刷数]当前批次无销售合同关联关系，跳过，pageNum={}", pageNum);
				pageNum++;
				continue;
			}

			long processed = processRelationsBatch(personalRelations);
			totalProcessed += processed;

			try {
				Thread.sleep(200L);
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				break;
			}
			pageNum++;
		}
		LOGGER.info("[刷数]全量刷数完成，总处理条数={}", totalProcessed);
	}

	/**
	 * 过滤出销售合同的关联关系
	 *
	 * @param relations 关联关系列表
	 * @return 销售合同的关联关系列表
	 */
	private List<ContractQuotationRelation> filterPersonalContractRelations(List<ContractQuotationRelation> relations) {
		// 批量查询合同
		List<String> contractCodes = relations.stream()
			.map(ContractQuotationRelation::getContractCode)
			.distinct()
			.collect(Collectors.toList());
		List<Contract> contracts = contractService.getListByContractCodes(contractCodes, true);

		// 构建销售合同编码集合
		Set<String> personalContractCodes = contracts.stream()
			.filter(c -> ContractTypeEnum.PERSONAL.getCode().equals(c.getType()))
			.map(Contract::getContractCode)
			.collect(Collectors.toSet());

		// 过滤出销售合同的关联关系
		return relations.stream()
			.filter(r -> personalContractCodes.contains(r.getContractCode()))
			.collect(Collectors.toList());
	}

	/**
	 * 批量处理关联关系（公共方法）
	 * <p>
	 * 该方法被 repairSingleContract 和 repairAll 共同调用，用于处理报价单换绑逻辑。
	 *
	 * @param relations 关联关系列表
	 * @return 成功处理的条数
	 */
	private long processRelationsBatch(List<ContractQuotationRelation> relations) {
		// 批量查询合同（调用方已确保只传入销售合同的关联关系）
		List<String> contractCodes = relations.stream()
			.map(ContractQuotationRelation::getContractCode)
			.distinct()
			.collect(Collectors.toList());
		List<Contract> contracts = contractService.getListByContractCodes(contractCodes, false);
		Map<String, Contract> contractMap = contracts.stream()
			.collect(Collectors.toMap(Contract::getContractCode, c -> c, (a, b) -> a));

		// 批量查询报价单
		List<String> billCodes = relations.stream()
			.map(ContractQuotationRelation::getBillCode)
			.collect(Collectors.toList());
		Map<String, BudgetBillDTO.BillDTO> billMap = new HashMap<>();
		if (!billCodes.isEmpty()) {
			List<BudgetBillDTO.BillDTO> bills = atomBudgetRpc.queryBillsByBillCodes(billCodes);
			billMap = bills.stream().collect(Collectors.toMap(BudgetBillDTO.BillDTO::getBillCode, b -> b, (a, b) -> a));
		}

		long processed = 0;
		// 遍历处理
		for (ContractQuotationRelation relation : relations) {
			Contract contract = contractMap.get(relation.getContractCode());
			if (contract == null) {
				continue;
			}
			try {
				BudgetBillDTO.BillDTO bill = billMap.get(relation.getBillCode());
				if (bill == null) {
					LOGGER.warn("[刷数]报价单不存在，跳过，billCode={}", relation.getBillCode());
					continue;
				}
				processSingleRelation(contract, relation, bill);
				processed++;
			} catch (Exception e) {
				LOGGER.error("[刷数]处理异常，contractCode={}, billCode={}", relation.getContractCode(), relation.getBillCode(), e);
			}
		}
		return processed;
	}

	/**
	 * 处理单条关联关系
	 */
	private void processSingleRelation(Contract contract, ContractQuotationRelation relation, BudgetBillDTO.BillDTO bill) {
		List<Integer> cooperBillTypes = Arrays.asList(
			GeneralBillTypeEnum.BUDGET_COOPER.getCode(),
			GeneralBillTypeEnum.BUDGET_GROUP.getCode()
		);

		if (cooperBillTypes.contains(bill.getBillType())) {
			// 协同报价单/团装报价单 → 解绑报价单，绑定 S 单
			try {
				quotationRelationCommonService.convertCooperBillToSubOrderByContract(contract);
				LOGGER.info("[刷数]协同报价单换绑成功，contractCode={}, billCode={}", contract.getContractCode(), relation.getBillCode());
			} catch (Exception e) {
				LOGGER.error("[刷数]协同报价单换绑失败，contractCode={}, billCode={}", contract.getContractCode(), relation.getBillCode(), e);
			}
		} else if (GeneralBillTypeEnum.BUDGET_STANDARD.getCode().equals(bill.getBillType())) {
			// 基础报价单 → 保留报价单，新增绑定 S 单
			try {
				quotationRelationCommonService.convertStandardBillToSubOrder(contract, relation.getBillCode());
				LOGGER.info("[刷数]基础报价单换绑成功，contractCode={}, billCode={}", contract.getContractCode(), relation.getBillCode());
			} catch (Exception e) {
				LOGGER.error("[刷数]基础报价单换绑失败，contractCode={}, billCode={}", contract.getContractCode(), relation.getBillCode(), e);
			}
		} else {
			LOGGER.warn("[刷数]不支持的报价单类型，跳过，billCode={}, billType={}", relation.getBillCode(), bill.getBillType());
		}
	}

	public Map<String, Map<String, Object>> checkBindingByOrderId(String projectOrderId) {
		Map<String, Map<String, Object>> result = new LinkedHashMap<>();

		List<Contract> validPersonalContracts = contractService.getContractList(projectOrderId).stream()
			.filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))
			.filter(contract -> ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus()))
			.collect(Collectors.toList());

		if (CollectionUtils.isEmpty(validPersonalContracts)) {
			result.put("info", Collections.singletonMap("info", "订单下无有效销售合同"));
			return result;
		}

		for (Contract contract : validPersonalContracts) {
			BillCheckContext context = getBillCheckContext(contract.getContractCode());
			Map<String, Object> contractResult = checkContractBinding(
				projectOrderId, contract.getCompanyCode(), context
			);
			result.put(contract.getContractCode(), contractResult);
		}

		return result;
	}

	/**
	 * 校验单个合同的绑定情况
	 */
	private Map<String, Object> checkContractBinding(String projectOrderId, String companyCode,
													  BillCheckContext context) {
		Map<String, Object> contractResult = new LinkedHashMap<>();

		// 1. 校验基础报价单
		List<Map<String, Object>> standardResults = checkBills(
			projectOrderId, companyCode, context.getValidStandardBillCodes(),
			context.getBoundSubOrderNos(), "基础报价单号", null
		);
		contractResult.put("基础报价单校验", standardResults);

		// 2. 校验变更单
		List<Map<String, Object>> changeOrderResults = checkChangeOrders(
			projectOrderId, companyCode, context.getValidChangeOrderIds(),
			context.getBoundSubOrderNos()
		);
		contractResult.put("变更单校验", changeOrderResults);

		// 3. 校验协同报价单
		List<Map<String, Object>> cooperResults = checkCooperBills(
			projectOrderId, companyCode, context.getValidCooperBillCodes(),
			context.getBillMap(), context.getBoundSubOrderNos()
		);
		contractResult.put("协同报价单校验", cooperResults);

		// 4. 汇总结果
		boolean allCorrect = allCheckPassed(standardResults)
			&& allCheckPassed(changeOrderResults)
			&& allCheckPassed(cooperResults);
		contractResult.put("校验结果", allCorrect ? "正确" : "错误");

		return contractResult;
	}

	/**
	 * 校验基础报价单/协同报价单的绑定情况
	 */
	private List<Map<String, Object>> checkBills(String projectOrderId, String companyCode,
												  List<String> billCodes, Set<String> boundSubOrderNos,
												  String billTypeKey,
												  Map<String, BudgetBillDTO.BillDTO> billMap) {
		List<Map<String, Object>> results = new ArrayList<>();
		for (String billCode : billCodes) {
			Set<String> expectedSubOrders = querySubOrdersByBillCode(projectOrderId, billCode, companyCode);
			Map<String, Object> checkResult = checkAndBuildResult(billCode, billTypeKey, expectedSubOrders, boundSubOrderNos);
			results.add(checkResult);
		}
		return results;
	}

	/**
	 * 校验变更单的绑定情况
	 */
	private List<Map<String, Object>> checkChangeOrders(String projectOrderId, String companyCode,
														 List<String> changeOrderIds, Set<String> boundSubOrderNos) {
		List<Map<String, Object>> results = new ArrayList<>();
		for (String changeOrderId : changeOrderIds) {
			Set<String> expectedSubOrders = querySubOrdersByChangeOrderId(projectOrderId, changeOrderId, companyCode);
			Map<String, Object> checkResult = checkAndBuildResult(changeOrderId, "变更单号", expectedSubOrders, boundSubOrderNos);
			results.add(checkResult);
		}
		return results;
	}

	/**
	 * 校验协同报价单的绑定情况（包含额外字段）
	 */
	private List<Map<String, Object>> checkCooperBills(String projectOrderId, String companyCode,
														List<String> billCodes,
														Map<String, BudgetBillDTO.BillDTO> billMap,
														Set<String> boundSubOrderNos) {
		List<Map<String, Object>> results = new ArrayList<>();
		for (String billCode : billCodes) {
			BudgetBillDTO.BillDTO bill = billMap.get(billCode);
			Set<String> expectedSubOrders = querySubOrdersByBillCode(projectOrderId, billCode, companyCode);
			boolean alreadyBound = expectedSubOrders.stream().anyMatch(boundSubOrderNos::contains);

			Map<String, Object> checkResult = checkAndBuildResult(billCode, "协同报价单号", expectedSubOrders, boundSubOrderNos);
			checkResult.put("报价单状态", bill.getStatus());
			checkResult.put("是否已换绑S单", alreadyBound);
			results.add(checkResult);
		}
		return results;
	}

	/**
	 * 判断所有校验是否通过
	 */
	private boolean allCheckPassed(List<Map<String, Object>> checkResults) {
		return checkResults.stream()
			.allMatch(r -> (Boolean) r.get("是否正确"));
	}

	/**
	 * 查询报价单对应的S单（主体与合同一致）
	 */
	private Set<String> querySubOrdersByBillCode(String projectOrderId, String billCode, String companyCode) {
