	/**
	 * 构建单据校验结果
	 *
	 * @param billCode 单据编号
	 * @param billTypeKey 单据类型 key（如"基础报价单号"、"变更单号"）
	 * @param expectedSubOrders 该单据对应的所有 S 单
	 * @param boundSubOrders 当前合同已绑定的 S 单集合
	 * @return 校验结果 Map
	 */
	private Map<String, Object> checkAndBuildResult(String billCode, String billTypeKey,
		Set<String> expectedSubOrders, Set<String> boundSubOrders) {
		// 计算应该换绑、已换绑、漏换绑
		Set<String> actualBound = new HashSet<>(boundSubOrders);
		actualBound.retainAll(expectedSubOrders);
		Set<String> missing = new HashSet<>(expectedSubOrders);
		missing.removeAll(boundSubOrders);

		Map<String, Object> result = new LinkedHashMap<>();
		result.put(billTypeKey, billCode);
		result.put("应该换绑S单", new ArrayList<>(expectedSubOrders));
		result.put("已换绑S单", new ArrayList<>(actualBound));
		result.put("漏换绑S单", new ArrayList<>(missing));
		result.put("是否正确", missing.isEmpty());
		return result;
	}

	/**
	 * 判断报价单状态是否有效（可参与校验）
	 *
	 * @param billStatus 报价单状态
	 * @return true=有效，false=无效
	 */
	private boolean isBillStatusValid(Integer billStatus) {
		if (billStatus == null) {
			return false;
		}
		return !GeneralBillStatusEnum.IN_ADJUST.getCode().equals(billStatus)
			&& !GeneralBillStatusEnum.DELETED.getCode().equals(billStatus)
			&& !GeneralBillStatusEnum.CANCELED.getCode().equals(billStatus);
	}

	/**
	 * 基于合同号获取需要校验换绑的单据信息
	 *
	 * @param contractCode 合同号
	 * @return 包含有效单据信息的对象
	 */
	private BillCheckContext getBillCheckContext(String contractCode) {
		// 已关联的关联关系（status=1）
		List<ContractQuotationRelation> relatedRelations = contractQuotationRelationService
			.getByContractCode(contractCode, RelationStatusEnum.RELATED.getCode(), null);
		// 已取消关联的关联关系（status=2）
		List<ContractQuotationRelation> canceledRelations = contractQuotationRelationService
			.getByContractCode(contractCode, RelationStatusEnum.CANCEL_RELATED.getCode(), null);

		// 合并所有关联关系
		List<ContractQuotationRelation> allRelations = new ArrayList<>(relatedRelations);
		allRelations.addAll(canceledRelations);

		// 当前合同已绑定的 S 单编号集合
		Set<String> boundSubOrderNos = relatedRelations.stream()
			.filter(r -> BindTypeEnum.SUB_ORDER.getCode().equals(r.getBindType()))
			.map(ContractQuotationRelation::getBillCode)
			.collect(Collectors.toSet());

		// 协同报价单类型
		List<Integer> cooperBillTypes = Arrays.asList(GeneralBillTypeEnum.BUDGET_COOPER.getCode(), GeneralBillTypeEnum.BUDGET_GROUP.getCode());

		// 查询报价单详情
		Set<String> allBillCodes = allRelations.stream()
			.filter(r -> BindTypeEnum.BILL_CODE.getCode().equals(r.getBindType()))
			.map(ContractQuotationRelation::getBillCode)
			.collect(Collectors.toSet());
		Map<String, BudgetBillDTO.BillDTO> billMap;
		if (!allBillCodes.isEmpty()) {
			List<BudgetBillDTO.BillDTO> bills = atomBudgetRpc.queryBillsByBillCodes(new ArrayList<>(allBillCodes));
			billMap = bills.stream().collect(Collectors.toMap(BudgetBillDTO.BillDTO::getBillCode, b -> b, (a, b) -> a));
		} else {
			billMap = Collections.emptyMap();
		}

		// 有效基础报价单：从关联表拿到 status=1 的，且类型为基础报价单
		List<String> validStandardBillCodes = relatedRelations.stream()
			.filter(r -> BindTypeEnum.BILL_CODE.getCode().equals(r.getBindType()))
			.map(ContractQuotationRelation::getBillCode)
			.filter(billCode -> {
				BudgetBillDTO.BillDTO bill = billMap.get(billCode);
				return bill != null && GeneralBillTypeEnum.BUDGET_STANDARD.getCode().equals(bill.getBillType());
			})
			.collect(Collectors.toList());

		// 有效协同报价单：从关联表拿到 status=1 或 2 的，且状态有效，且类型为协同报价单
		List<String> validCooperBillCodes = allRelations.stream()
			.filter(r -> BindTypeEnum.BILL_CODE.getCode().equals(r.getBindType()))
			.map(ContractQuotationRelation::getBillCode)
			.filter(billCode -> {
				BudgetBillDTO.BillDTO bill = billMap.get(billCode);
				if (bill == null || !cooperBillTypes.contains(bill.getBillType())) {
					return false;
				}
				// 状态有效：非 IN_ADJUST、DELETED、CANCELED
				return isBillStatusValid(bill.getStatus());
			})
			.distinct()
			.collect(Collectors.toList());

		// 有效变更单：从关联表拿到 status=1 的，bind_type 为变更单类型
		List<String> validChangeOrderIds = relatedRelations.stream()
			.filter(r -> BindTypeEnum.CHANGE_ORDER.getCode().equals(r.getBindType()))
			.map(ContractQuotationRelation::getBillCode)
			.collect(Collectors.toList());

		// 构建返回对象
		BillCheckContext context = new BillCheckContext();
		context.setBoundSubOrderNos(boundSubOrderNos);
		context.setBillMap(billMap);
		context.setValidStandardBillCodes(validStandardBillCodes);
		context.setValidCooperBillCodes(validCooperBillCodes);
		context.setValidChangeOrderIds(validChangeOrderIds);
		return context;
	}

	/**
	 * 单据校验上下文
	 */
	private static class BillCheckContext {
		private Set<String> boundSubOrderNos;
		private Map<String, BudgetBillDTO.BillDTO> billMap;
		private List<String> validStandardBillCodes;
		private List<String> validCooperBillCodes;
		private List<String> validChangeOrderIds;

		public Set<String> getBoundSubOrderNos() {
			return boundSubOrderNos;
		}

		public void setBoundSubOrderNos(Set<String> boundSubOrderNos) {
			this.boundSubOrderNos = boundSubOrderNos;
		}

		public Map<String, BudgetBillDTO.BillDTO> getBillMap() {
			return billMap;
		}

		public void setBillMap(Map<String, BudgetBillDTO.BillDTO> billMap) {
			this.billMap = billMap;
		}

		public List<String> getValidStandardBillCodes() {
			return validStandardBillCodes;
		}

		public void setValidStandardBillCodes(List<String> validStandardBillCodes) {
			this.validStandardBillCodes = validStandardBillCodes;
		}

		public List<String> getValidCooperBillCodes() {
			return validCooperBillCodes;
		}

		public void setValidCooperBillCodes(List<String> validCooperBillCodes) {
			this.validCooperBillCodes = validCooperBillCodes;
		}

		public List<String> getValidChangeOrderIds() {
			return validChangeOrderIds;
		}

		public void setValidChangeOrderIds(List<String> validChangeOrderIds) {
			this.validChangeOrderIds = validChangeOrderIds;
		}
	}

