public void addPersonalizedContract(Integer gbCode) {
	List<ContractCityCompanyInfo> insertList = new ArrayList<>();
	List<ContractCityCompanyInfo> configList = contractCityCompanyInfoService.getConfigByContractTypes(ContractTypeEnum.PERSONALIZED_CONTRACT);
	//过滤出协议确认的配置
	configList = configList.stream().filter(item -> UserSignTypeEnum.CONFIRM.getCode().equals(item.getSignChannelType())).collect(Collectors.toList());
	if (gbCode != null) {
		configList = configList.stream().filter(item -> gbCode.equals(item.getGbCode())).collect(Collectors.toList());
	}
	for (ContractCityCompanyInfo item : configList) {
		ContractCityCompanyInfo config = contractCityCompanyInfoService.getConfig(item.getGbCode(), item.getCompanyCode(), item.getBusinessType(), Byte.valueOf(String.valueOf(item.getContractType())), item.getSignChannelType(),UserSignTypeEnum.SIGN.getCode(), item.getVersion());
		if (config != null) {
			continue;
		}
		item.setUserSignType(String.valueOf(UserSignTypeEnum.SIGN.getCode()));
		item.setId(null);
		item.setCtime(new Date());
		item.setMtime(new Date());
		insertList.add(item);
	}
	if (CollectionUtils.isNotEmpty(insertList)) {
		contractCityCompanyInfoService.insertBatch(insertList);
		LOGGER.info("新增个性化合同配置成功，size:{},insertList:{}", insertList.size(),insertList);
	}
}

public Boolean toolGenerataAccredit(String contractCode) {
	Contract mainContract = contractService.getByContractCode(contractCode);
	// 对公线上签署生成授权协议书
	String lockKey = "generate_accredit:" + LockService.PROJECT_ORDER_ID + mainContract.getProjectOrderId();
	CompletableFuture.runAsync(RunnableWrapper.of(() -> {
