public Map<String, Double> getDrawingSize(List<String> projectOrderIds) {
	Map<String, Double> drawingContractSizeMap = new HashMap<>();
	for (String projectOrderId : projectOrderIds) {
		try {
			DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = atomDrawingRpc.listDrawings(projectOrderId);
			if (deliverDrawingDTO == null || org.springframework.util.CollectionUtils.isEmpty(deliverDrawingDTO.getDrawingDetailDTOList())) {
				LOGGER.info("计算图纸大小，项目订单:{}未获取到图纸信息", projectOrderId);
				continue;
			}
			List<String> pdfUrls = deliverDrawingDTO.getDrawingDetailDTOList().stream()
				.filter(item -> ObjectUtil.equals(item.getBillType(),PlanAttachment.基础图纸))
				.filter(item -> ObjectUtil.equals(item.getExtensionType(),DrawingEnum.ConstructionFileExtensionEnum.PDF.getCode()))
				.map(DrawingDTO.DrawingDetailDTO::getUrl)
				.collect(Collectors.toList());
			double spaceSizeMB = (double) IOUtils.calculateTotalFileSizeByUrl(pdfUrls) / 1024;
			//spaceSizeMB只保留两位小数
			spaceSizeMB = BigDecimal.valueOf(spaceSizeMB).setScale(2, RoundingMode.HALF_UP).doubleValue();
			drawingContractSizeMap.put(projectOrderId, spaceSizeMB);
		} catch (Exception e) {
			LOGGER.info("计算图纸大小，项目订单:{}异常", projectOrderId, e);
		}
	}
	LOGGER.info("计算图纸大小,图纸大小:{}", drawingContractSizeMap);
	return drawingContractSizeMap;
}

public Map<String, Double> getBudgetSize(List<String> projectOrderIds) {
	Map<String, Double> budgetSizeMap = new HashMap<>();
	for (String projectOrderId : projectOrderIds) {
		try {
			PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(projectOrderId, "");
			PlanAttachmentDTO attachmentDTO = planAllDTO.getPlanAttachmentList().stream().filter(planAttachmentDTO -> planAttachmentDTO.getFileType().equals(PlanAttachment.报价单))
				.findFirst()
				.orElse(null);
			if (attachmentDTO == null) {
				LOGGER.info("计算报价单大小，项目订单:{}未获取到报价单信息", projectOrderId);
				continue;
			}
			String budgetUrl = attachmentDTO.getFileUrl();
			long fileSizeByDownload = IOUtils.getFileSizeByDownload(budgetUrl);

			double spaceSizeKB = (double) fileSizeByDownload / 1024;
			//spaceSizeMB只保留两位小数
			spaceSizeKB = BigDecimal.valueOf(spaceSizeKB).setScale(2, RoundingMode.HALF_UP).doubleValue();
			budgetSizeMap.put(projectOrderId, spaceSizeKB);
		} catch (Exception e) {
			LOGGER.info("计算报价单大小，项目订单:{}异常", projectOrderId, e);
		}
	}
	LOGGER.info("计算报价单大小,报价单大小:{}", budgetSizeMap);
	return budgetSizeMap;
}

