public String getSignTime2_5(String projectOrderId, String billCode, String companyCode) {
	//任意一个参数为空则返回空字符串
	if (StringUtils.isBlank(projectOrderId) || StringUtils.isBlank(billCode) || StringUtils.isBlank(companyCode)) {
		return "";
	}
	List<Byte> nodeTypes = new ArrayList<>();
	nodeTypes.add(NodeTypeEnum.USER_CONFIRM.getCode());
	nodeTypes.add(NodeTypeEnum.FINISH.getCode());
	List<String> billCodes = new ArrayList<>();
	billCodes.add(billCode);
	List<ContractQuotationRelation> contractQuotationRelationList = contractQuotationRelationService.getByBillCodesAndStatus(billCodes, RelationStatusEnum.RELATED.getCode());
	if (CollectionUtils.isNotEmpty(contractQuotationRelationList)) {
		String contractCode = contractQuotationRelationList.get(0).getContractCode();
		List<ContractNode> nodeList = contractNodeService.getListByContractCode(contractCode);
		List<ContractNode> signNodeList = nodeList.stream().filter(item -> nodeTypes.contains(item.getNodeType())).collect(Collectors.toList());
		//signNodeList中优先取出用户确认节点的时间，如果没有则取出完成节点的时间
		if (CollectionUtils.isNotEmpty(signNodeList)) {
			ContractNode signNode = signNodeList.stream().filter(item -> NodeTypeEnum.USER_CONFIRM.getCode().equals(item.getNodeType())).findFirst().orElse(null);
			if (signNode == null) {
				signNode = signNodeList.stream().filter(item -> NodeTypeEnum.FINISH.getCode().equals(item.getNodeType())).findFirst().orElse(null);
			}
			if (signNode != null) {
				//返回时间字符串
				return cn.hutool.core.date.DateUtil.format(signNode.getCtime(), "yyyy-MM-dd HH:mm:ss");
			}
			return "";
		} else {
			return "";
		}
	}

	List<Contract> contractList = contractService.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode());
	contractList = contractList.stream().filter(contract -> ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus()))
		//状态是已完结or之前确认过
		.filter(contract -> ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus()) || contract.getUserConfirmStatus().equals(CommonEnum.YES.getCode()))
		.filter(contract -> contract.getCompanyCode().equals(companyCode))
		.collect(Collectors.toList());
	if (CollectionUtils.isEmpty(contractList)) {
		return "";
	}
	//contractList按Id排序，小的在前
	contractList.sort(Comparator.comparing(Contract::getId));
	Contract contract = contractList.get(0);
	List<ContractNode> nodeList = contractNodeService.getListByContractCode(contract.getContractCode());
	List<ContractNode> signNodeList = nodeList.stream().filter(item -> nodeTypes.contains(item.getNodeType())).collect(Collectors.toList());
	//signNodeList中优先取出用户确认节点的时间，如果没有则取出完成节点的时间
	if (CollectionUtils.isNotEmpty(signNodeList)) {
		ContractNode signNode = signNodeList.stream().filter(item -> NodeTypeEnum.USER_CONFIRM.getCode().equals(item.getNodeType())).findFirst().orElse(null);
		if (signNode == null) {
			signNode = signNodeList.stream().filter(item -> NodeTypeEnum.FINISH.getCode().equals(item.getNodeType())).findFirst().orElse(null);
		}
		if (signNode != null) {
			//返回时间字符串
			return cn.hutool.core.date.DateUtil.format(signNode.getCtime(), "yyyy-MM-dd HH:mm:ss");
		}
		return "";
	} else {
		return "";
	}
}

