public void addDeveloperConfig(FundItemConfig fundItemConfig, List<Long> updatedIds) {
	// 1、获取配置的 config_data 列
	FundConfigInfo fundConfigInfo = JSON.parseObject(fundItemConfig.getConfigData(), FundConfigInfo.class);
	// 2、获取 config_data 列中的收款计划
	List<CollectionPlanConfigInfo> collectionPlanConfigInfos = fundConfigInfo.getCollectionPlanConfigInfos();
	if (CollectionUtils.isEmpty(collectionPlanConfigInfos)) {
		return;
	}

	int devCnt = 0;
	CollectionPlanConfigInfo toAddConfig = null;
	// 3、找到首开尾收款计划，并记录开渠收款计划的个数
	for (CollectionPlanConfigInfo config : collectionPlanConfigInfos) {
		// 3.1、获取收款计划模式，如果为空，则认为是自定义模式
		Integer mode = config.getCollectionPlanMode();
		if (mode == null) {
			mode = CollectionPlanModeEnum.FIXED_RATE.getValue();
		}
		if (CollectionPlanModeEnum.getFirstOpenTailMode().contains(mode)) {
			// 3.2、找到首开尾模式的收款计划（深拷贝一份数据）
			toAddConfig = JSON.parseObject(JSON.toJSONString(config), CollectionPlanConfigInfo.class);
		} else if (CollectionPlanModeEnum.getDeveloperChannelMode().contains(mode)) {
			// 3.3、记录开渠模式收款计划个数
			devCnt ++;
		}
	}
	// 4、首开尾收款计划不存在，则不需要拷贝
	if (toAddConfig == null) {
		LOGGER.info("【收款计划】首开尾收款计划不存在，跳过该配置，fund_item_config ID:{}", fundItemConfig.getId());
		return;
	}
	// 5、开渠去收款计划已经存在，则不重复拷贝
	if (devCnt > 0) {
		LOGGER.info("【收款计划】开渠模式收款计划已存在，不能重复拷贝，fund_item_config ID:{}", fundItemConfig.getId());
		return;
	}
	// 6、拷贝后的数据，将模式设置为「开渠模式」
	toAddConfig.setCollectionPlanId(String.valueOf(IdGenerator.snowflakeId()));
	toAddConfig.setCollectionPlanMode(CollectionPlanModeEnum.DEVELOPER_CHANNEL_FLEX_RATE_FLEX_AMOUNT.getValue());

	// 7、将开渠模式收款计划，添加到收款计划列表
	collectionPlanConfigInfos.add(toAddConfig);
	String configData = JSON.toJSONString(fundConfigInfo);
	LOGGER.info("【收款计划】fund_item_config ID: {}, 更新前数据：{}", fundItemConfig.getId(), fundItemConfig.getConfigData());
	fundItemConfig.setConfigData(configData);
	fundItemConfig.setUpdater("1000000030973949");
	fundItemConfig.setUpdateTime(new Date());
	LOGGER.info("【收款计划】fund_item_config ID: {}, 待更新数据：{}", fundItemConfig.getId(), configData);
	updatedIds.add(fundItemConfig.getId());
	fundItemConfigService.update(fundItemConfig);
}

public List<Long> checkCollectionPlan() {
	// 1、获取 fund_item_config 表中，根据 gbcode、company_code、business_type、fund_type 分组后，每组的最新一条数据
	List<Long> toCopyDataIds = fundItemConfigService.selectToCopyDataV2();
	if (CollectionUtils.isEmpty(toCopyDataIds)) {
		return Collections.emptyList();
	}
	int batch = 50;
	List<Long> result = new ArrayList<>();
	// 2、批处理，每批处理 50 个（避免 List 查出数据过多，内存占用过大）
	for (int i = 0; i < toCopyDataIds.size(); i += batch) {
		int end = Math.min(i + batch, toCopyDataIds.size());
		// 3、每次取 50 个元素，subList 截取区间为左闭右开 [fromIndex, toIndex)
		List<Long> toUpdateIds = toCopyDataIds.subList(i, end);
		LOGGER.info("【收款计划】区间范围: [{}, {}), 待处理 ID: {}", i, end, JSON.toJSONString(toUpdateIds));
		Example example = new Example(FundItemConfig.class);
		example.createCriteria().andIn("id", toUpdateIds);
		// 4、查询当前批次 ID 对应的数据
		List<FundItemConfig> oldData = fundItemConfigService.selectByExample(example);
		if (CollectionUtils.isEmpty(oldData)) {
			continue;
		}
		for (FundItemConfig fundItemConfig : oldData) {
			Long id = fundItemConfig.getId();
			FundConfigInfo fundConfigIno = JSON.parseObject(fundItemConfig.getConfigData(), FundConfigInfo.class);
			List<CollectionPlanConfigInfo> collectionPlanConfigInfos = fundConfigIno.getCollectionPlanConfigInfos();

			CollectionPlanConfigInfo firstCollection = null;
			CollectionPlanConfigInfo devCollection = null;
			for (CollectionPlanConfigInfo collectionPlanConfigInfo : collectionPlanConfigInfos) {
				if (CollectionPlanModeEnum.getFirstOpenTailMode().contains(collectionPlanConfigInfo.getCollectionPlanMode())) {
					firstCollection = collectionPlanConfigInfo;
				} else if (CollectionPlanModeEnum.getDeveloperChannelMode().contains(collectionPlanConfigInfo.getCollectionPlanMode())) {
					devCollection = collectionPlanConfigInfo;
				}
			}
			if (firstCollection == null && devCollection == null) continue;
			if (firstCollection != null && devCollection == null) {
				result.add(id);
				continue;
			}
			if (firstCollection == null && devCollection != null) {
				LOGGER.info("特殊情况: {}", id);
				result.add(id);
				continue;
			}
			if (!check(firstCollection, devCollection)) {
				result.add(id);
			}
		}
		LOGGER.info("【收款计划】拷贝数据 ids: {}", JSON.toJSONString(result));
	}
	return result;
}

private boolean check(CollectionPlanConfigInfo firstCollection, CollectionPlanConfigInfo devCollection) {
	return !ObjectUtil.notEqual(firstCollection.getContent(), devCollection.getContent());
}

