public String applyStampStatusRevert(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	Byte userSignType = contract.getUserSignType();
	Integer status = contract.getStatus();
	// 如果合同不是正式签署，则不回退
	if (!UserSignTypeEnum.SIGN.getCode().equals(userSignType)) {
		throw new NrsBusinessException("合同不是正式签署(正式签署 userSignType = 2)");
	}
	if (!ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(status)) {
		throw new NrsBusinessException("合同状态不是待签署(待签署 status = 4)");
	}
	contract.setStatus(ContractStatusEnum.USER_CONFIRMED.getCode());
	contract.setUserSignType(UserSignTypeEnum.CONFIRM.getCode());
	contractService.update(contract);
	return "更新成功, contractCode:" + contract.getContractCode();
}

