public void protocolConfigCopy(Integer sourceFormId, Integer targetFormId) {
	CustomForm sourceCustomForm = validateAndGetCustomForm(sourceFormId, "源");
	CustomForm targetCustomForm = validateAndGetCustomForm(targetFormId, "目标");

	List<ContractProtocolConfig> sourceConfigs = contractProtocolConfigService.getContractProtocolConfig(sourceCustomForm.getFormKey(), sourceFormId);
	if (CollectionUtils.isEmpty(sourceConfigs)) {
		throw new NrsBusinessException("未查询到对应的源协议模版配置，formId：" + sourceFormId, Level.WARN);
	}

	int deletedCount = contractProtocolConfigService.deleteByFormId(targetFormId);
	LOGGER.info("协议模版配置拷贝，删除目标协议模版下的配置完成，formId：{}，deletedCount：{}", targetFormId, deletedCount);

	for (ContractProtocolConfig config : sourceConfigs) {
		config.setId(null);
		config.setFormKey(targetCustomForm.getFormKey());
		config.setFormId(targetFormId);
	}
	contractProtocolConfigService.insertBatch(sourceConfigs);
	LOGGER.info("协议模版配置拷贝完成，sourceFormId：{}，targetFormId：{}，拷贝数据量：{}", sourceFormId, targetFormId, sourceConfigs.size());
	LOGGER.info("协议模版配置拷贝完成，sourceFormId：{}，targetFormId：{}，sourceConfigs：{}", sourceFormId, targetFormId, JSON.toJSONString(sourceConfigs));
}

