public void generateComboMaterial(List<String> comboCodes) {
	Map<String, MaterialPdfData> result = new HashMap<>();
	// 确定要处理的 comboCode 列表
	List<String> targetComboCodes;
	if (CollectionUtils.isNotEmpty(comboCodes)) {
		targetComboCodes = comboCodes;
		LOGGER.info("处理套餐配置数据-使用传入的comboCode, 数量:{}", targetComboCodes.size());
	} else {
		targetComboCodes = contractComboInfoService.getAllDistinctComboCodes();
		LOGGER.info("处理套餐配置数据-从数据库查询所有comboCode, 数量:{}", targetComboCodes.size());
	}

	// 初始化数据时，逐条进行处理
	for (String comboCode : targetComboCodes) {
		try {
			result.put(comboCode, MaterialPdfData.builder().comboCode(comboCode).build());
			Map<String, MaterialPdfData> materialPdfData =
				comboInfoMaterialGenerator.generateAndReplaceMaterialList(Collections.singletonList(comboCode));
			result.putAll(materialPdfData);
		} catch (Exception e) {
			LOGGER.info("材料配送清单生成失败, comboCode: {}", comboCode, e);
		}
	}
	LOGGER.info("系统自动生成材料配送清单, 生成结果: {}", JSON.toJSONString(result));

	// 导出 excel 文件
	String s3Url = exportExcel(result);
	LOGGER.info("excel 文件上传 url: {}", s3Url);
}

public String exportExcel(Map<String, MaterialPdfData> result) {
	List<MaterialPdfDataExcelDTO> excelData = result.values().stream()
		.map(materialPdfData ->
			MaterialPdfDataExcelDTO.builder()
			.comboCode(materialPdfData.getComboCode())
			.materialPdfUrl(materialPdfData.getMaterialPdfUrl())
			.materialImageUrls(materialPdfData.getMaterialImageUrls())
			.build()
		).collect(Collectors.toList());
	String fileName = "material_list" + System.currentTimeMillis() + Constant.FILE_SUFFIX_XLSX;
	ByteArrayOutputStream excelFile = new ByteArrayOutputStream();
	ExcelUtils.download(excelFile, MaterialPdfDataExcelDTO.class, excelData, fileName);
	return s3Service.uploadPublic(excelFile.toByteArray(), fileName);
}

