public void updateContractTaxRate(MultipartFile excelFile, Integer operationType) {
	// 校验operationType
	if (operationType == null || (operationType != 1 && operationType != 2)) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(),
			"操作类型不正确，仅支持：1-修改，2-回滚", Level.WARN);
	}

	// 解析并校验Excel文件
	List<ContractCodeImportDTO> importDTOList = parseAndValidateExcel(excelFile);

	LOGGER.info("修改合同税率和承包模式任务开始，导入数量: {}, 操作类型: {}", importDTOList.size(), operationType);

	// 异步执行任务
	CompletableFuture.runAsync(RunnableWrapper.of(() -> {
		try {
			doUpdateContractTaxRate(importDTOList, operationType);
		} catch (Exception e) {
			LOGGER.error("修改合同税率和承包模式任务执行异常", e);
		}
	}));
}

