private List<ContractCodeImportDTO> parseAndValidateExcel(MultipartFile excelFile) {
	// 校验file类型和格式
	String originalFilename = excelFile.getOriginalFilename();
	if (originalFilename == null || (!originalFilename.endsWith(Constant.FILE_SUFFIX_XLSX)
		&& !originalFilename.endsWith(Constant.FILE_SUFFIX_XLS))) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "文件格式不正确，请上传Excel文件",
			Level.WARN);
	}

	// 解析excel
	List<ContractCodeImportDTO> importDTOList = new ArrayList<>();
	try (InputStream inputStream = excelFile.getInputStream()) {
		EasyExcel.read(inputStream, ContractCodeImportDTO.class,
			new EasyExcelContractCodeParseListener(importDTOList)).sheet().doRead();
	} catch (Exception e) {
		LOGGER.error("解析Excel文件失败", e);
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(),
			"解析Excel文件失败：" + e.getMessage(), Level.WARN);
	}
	if (CollectionUtils.isEmpty(importDTOList)) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "Excel文件内容为空", Level.WARN);
	}
	return importDTOList;
}

private void doUpdateContractTaxRate(List<ContractCodeImportDTO> importDTOList, Integer operationType) {
	LOGGER.info("修改合同税率和承包模式任务开始执行");
	long startTime = System.currentTimeMillis();

	// 构造要写入的excelDTO集合
	List<ContractTaxRateUpdateExportDTO> exportDTOList = new ArrayList<>();
	int totalSuccessCount = 0;
	int batchSize = 100;

	// 分批处理，每批100条
	List<List<ContractCodeImportDTO>> batchList = ListUtils.partition(importDTOList, batchSize);
	for (int i = 0; i < batchList.size(); i++) {
		List<ContractCodeImportDTO> batch = batchList.get(i);
		LOGGER.info("修改合同税率和承包模式，开始处理第{}批，共{}批，本批数量: {}", i + 1, batchList.size(),
			batch.size());

		// 处理当前批次
		BatchExportResult<ContractTaxRateUpdateExportDTO> result = processBatchUpdateTaxRate(batch, operationType);
		exportDTOList.addAll(result.getExportDTOList());
		totalSuccessCount += result.getSuccessCount();

		LOGGER.info("修改合同税率和承包模式，第{}批处理完成，本批成功: {}，本批失败: {}",
			i + 1, result.getSuccessCount(), result.getFailCount());
	}

	// 按订单号升序排序后写入excel
	try {
		String excelUrl = exportContractTaxRateUpdateResult(exportDTOList);
		long costTime = System.currentTimeMillis() - startTime;
		LOGGER.info(
			"修改合同税率和承包模式任务完成，耗时: {}ms，总批数: {}，总数: {}，总成功: {}，总失败: {}，结果Excel URL: {}",
			costTime, batchList.size(), importDTOList.size(), totalSuccessCount,
			importDTOList.size() - totalSuccessCount, excelUrl);
	} catch (Exception e) {
		LOGGER.error("修改合同税率和承包模式，导出Excel失败", e);
	}
}

