private static class TaxRateValidationContext {
	String contractCode;
	String excelProjectOrderId;
	Contract contract;
	Map<String, String> fieldMap;
	Long signTime;
	boolean isValid = true;
}

ContractToolService.java::ContractToolSe.source_code:
private boolean validateRequiredFieldsForTaxRate(TaxRateValidationContext ctx, Map<String, Contract> contractMap,
	Map<String, Map<String, String>> contractFieldMap, List<ContractTaxRateUpdateExportDTO> exportDTOList) {
	// 校验合同号不为空
	if (StringUtils.isBlank(ctx.contractCode)) {
		exportDTOList.add(buildUnknownContractTaxRateExportDTO(ctx.excelProjectOrderId, ctx.contractCode, "合同号为空"));
		ctx.isValid = false;
		return false;
	}

	// 校验合同存在
	ctx.contract = contractMap.get(ctx.contractCode);
	if (ctx.contract == null) {
		exportDTOList.add(buildUnknownContractTaxRateExportDTO(ctx.excelProjectOrderId, ctx.contractCode, "合同号在系统中不存在"));
		ctx.isValid = false;
		return false;
	}

	// 校验合同订单号不为空
	if (StringUtils.isBlank(ctx.contract.getProjectOrderId())) {
		exportDTOList.add(buildContractTaxRateUpdateExportDTO(ctx.contract, null, "否",
			"合同订单号为空", null, null, ctx.excelProjectOrderId));
		ctx.isValid = false;
		return false;
	}

	// 校验订单号一致
	if (StringUtils.isNotBlank(ctx.excelProjectOrderId)
		&& !ctx.excelProjectOrderId.equals(ctx.contract.getProjectOrderId())) {
		exportDTOList.add(buildContractTaxRateUpdateExportDTO(ctx.contract, null, "否",
			"导入订单号与合同实际订单号不一致", null, null, ctx.excelProjectOrderId));
		ctx.isValid = false;
		return false;
	}

	// 获取字段Map（后续校验需要使用）
	ctx.fieldMap = contractFieldMap.get(ctx.contractCode);

	return true;
}

private boolean validateContractTypeForTaxRate(TaxRateValidationContext ctx,
	List<ContractTaxRateUpdateExportDTO> exportDTOList) {
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(ctx.contract.getType())
		&& !ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(ctx.contract.getType())) {
		exportDTOList.add(buildContractTaxRateUpdateExportDTO(ctx.contract, ctx.fieldMap, "否",
			"仅支持正签或变更合同", null, null, ctx.excelProjectOrderId));
		ctx.isValid = false;
		return false;
	}
	return true;
}

private boolean validateContractStatusForTaxRate(TaxRateValidationContext ctx,
	List<ContractTaxRateUpdateExportDTO> exportDTOList) {
	if (!ContractStatusEnum.FINISH.getCode().equals(ctx.contract.getStatus())) {
		exportDTOList.add(buildContractTaxRateUpdateExportDTO(ctx.contract, ctx.fieldMap, "否",
			"状态需为已签署", null, null, ctx.excelProjectOrderId));
		ctx.isValid = false;
		return false;
	}
	return true;
}

private boolean validateSignTime(TaxRateValidationContext ctx,
	List<ContractTaxRateUpdateExportDTO> exportDTOList) {
	if (ctx.signTime != null) {
		java.util.Calendar cal = java.util.Calendar.getInstance();
		cal.setTimeInMillis(ctx.signTime);
		if (cal.get(java.util.Calendar.YEAR) < 2026) {
			exportDTOList.add(buildContractTaxRateUpdateExportDTO(ctx.contract, ctx.fieldMap, "否",
				"正签签署时间在2026年之前", null, null, ctx.excelProjectOrderId));
			ctx.isValid = false;
			return false;
		}
	}
	return true;
}

private boolean validateTaxRate(TaxRateValidationContext ctx, String expectedTaxRate, Integer operationType,
	List<ContractTaxRateUpdateExportDTO> exportDTOList) {
	String taxRate = ctx.fieldMap != null ? ctx.fieldMap.get(ContractFieldEnum.TAX_RATE.getFieldKey()) : null;
	if (!expectedTaxRate.equals(taxRate)) {
		String failReason = Integer.valueOf(1).equals(operationType) ? "修改操作要求税率必须为3" : "回滚操作要求税率必须为9";
		exportDTOList.add(buildContractTaxRateUpdateExportDTO(ctx.contract, ctx.fieldMap, "否",
			failReason, null, null, ctx.excelProjectOrderId));
		ctx.isValid = false;
		return false;
	}
	return true;
}

private boolean validateProjectContractModeCode(TaxRateValidationContext ctx, String expectedModeCode,
	Integer operationType, List<ContractTaxRateUpdateExportDTO> exportDTOList) {
	String modeCode = ctx.fieldMap != null
		? ctx.fieldMap.get(ContractFieldEnum.PROJECT_CONTRACT_MODE_CODE.getFieldKey()) : null;
	if (!expectedModeCode.equals(modeCode)) {
		String failReason = Integer.valueOf(1).equals(operationType) ? "修改操作要求承包模式必须为2"
			: "回滚操作要求承包模式必须为4";
		exportDTOList.add(buildContractTaxRateUpdateExportDTO(ctx.contract, ctx.fieldMap, "否",
			failReason, null, null, ctx.excelProjectOrderId));
		ctx.isValid = false;
		return false;
	}
	return true;
}

private BatchExportResult<ContractTaxRateUpdateExportDTO> processBatchUpdateTaxRate(
	List<ContractCodeImportDTO> batch, Integer operationType) {
	List<ContractTaxRateUpdateExportDTO> exportDTOList = new ArrayList<>();
	int successCount = 0;
	int failCount = 0;

	// 用dto集合里的合同号集合去查合同
	List<String> contractCodeList = batch.stream()
		.map(ContractCodeImportDTO::getContractCode)
		.filter(StringUtils::isNotBlank)
		.collect(Collectors.toList());
	List<Contract> contractList = CollectionUtils.isEmpty(contractCodeList) ? new ArrayList<>()
		: contractService.getListByContractCodes(contractCodeList, false);

	// 构建合同Map
	Map<String, Contract> contractMap = contractList.stream()
		.collect(Collectors.toMap(Contract::getContractCode, c -> c, (v1, v2) -> v1));

	// 查询合同字段
	Map<String, Map<String, String>> contractFieldMap = new HashMap<>();
	if (CollectionUtils.isNotEmpty(contractList)) {
		List<String> existContractCodeList = contractList.stream()
			.map(Contract::getContractCode)
			.collect(Collectors.toList());
		List<String> fieldKeys = Arrays.asList(ContractFieldEnum.TAX_RATE.getFieldKey(),
			ContractFieldEnum.PROJECT_CONTRACT_MODE_CODE.getFieldKey());
		List<ContractField> contractFields =
			contractFieldService.getValueByContractCodeAndFieldKey(existContractCodeList, fieldKeys);
		if (CollectionUtils.isNotEmpty(contractFields)) {
			contractFieldMap = contractFields.stream()
				.collect(Collectors.groupingBy(ContractField::getContractCode,
					Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue, (v1, v2) -> v1)));
		}
	}

	// 查询正签签署时间
	Map<String, Long> projectOrderSignTimeMap = new HashMap<>();
	List<Contract> formalContractList = contractList.stream()
		.filter(c -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(c.getType()))
		.collect(Collectors.toList());
	if (CollectionUtils.isNotEmpty(formalContractList)) {
		List<String> formalContractCodes = formalContractList.stream()
			.map(Contract::getContractCode)
			.collect(Collectors.toList());
		List<ContractNode> contractNodes = contractNodeService.getListByContractCodesAndType(formalContractCodes,
			Collections.singletonList((byte) 7));
		for (ContractNode node : contractNodes) {
			formalContractList.stream()
				.filter(c -> c.getContractCode().equals(node.getContractCode()))
				.findFirst()
				.ifPresent(c -> projectOrderSignTimeMap.putIfAbsent(c.getProjectOrderId(), node.getFireTime()));
		}
	}

	// 校验通过的合同号集合
	List<String> validContractCodeList = new ArrayList<>();
	String expectedTaxRate = Integer.valueOf(1).equals(operationType) ? "3" : "9";
	String expectedModeCode = Integer.valueOf(1).equals(operationType)
		? String.valueOf(ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS.getCode())
		: String.valueOf(ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS_V2.getCode());

	// 遍历当前批次进行校验
	for (ContractCodeImportDTO importDTO : batch) {
		TaxRateValidationContext ctx = new TaxRateValidationContext();
		ctx.contractCode = importDTO.getContractCode();
		ctx.excelProjectOrderId = importDTO.getProjectOrderId();

		// 校验必要字段（合同号、合同存在、订单号）
		if (ctx.isValid && !validateRequiredFieldsForTaxRate(ctx, contractMap, contractFieldMap, exportDTOList)) {
			failCount++;
		}
		// 设置签署时间
		if (ctx.isValid) {
			ctx.signTime = projectOrderSignTimeMap.get(ctx.contract.getProjectOrderId());
		}
		// 校验合同类型
		if (ctx.isValid && !validateContractTypeForTaxRate(ctx, exportDTOList)) {
			failCount++;
		}
		// 校验合同状态
		if (ctx.isValid && !validateContractStatusForTaxRate(ctx, exportDTOList)) {
			failCount++;
		}
		// 校验签署时间
		if (ctx.isValid && !validateSignTime(ctx, exportDTOList)) {
			failCount++;
		}
		// 校验税率
		if (ctx.isValid && !validateTaxRate(ctx, expectedTaxRate, operationType, exportDTOList)) {
			failCount++;
		}
		// 校验承包模式
		if (ctx.isValid && !validateProjectContractModeCode(ctx, expectedModeCode, operationType, exportDTOList)) {
			failCount++;
		}
		if (ctx.isValid) {
			validContractCodeList.add(ctx.contractCode);
		}
	}

	// 执行更新
	if (CollectionUtils.isNotEmpty(validContractCodeList)) {
		String newTaxRate = Integer.valueOf(1).equals(operationType) ? "9" : "3";
		String newProjectContractModeCode = Integer.valueOf(1).equals(operationType)
			? String.valueOf(ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS_V2.getCode())
			: String.valueOf(ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS.getCode());

		for (String contractCode : validContractCodeList) {
			Contract contract = contractMap.get(contractCode);
			// 从batch中找到对应的projectOrderId（优先用Excel中的）
			String excelProjectOrderId = batch.stream()
				.filter(dto -> contractCode.equals(dto.getContractCode()))
				.map(ContractCodeImportDTO::getProjectOrderId)
				.filter(StringUtils::isNotBlank)
				.findFirst()
				.orElse(null);
			try {
				contractFieldService.updateContractField(contractCode, ContractFieldEnum.TAX_RATE.getFieldKey(),
					newTaxRate);
				contractFieldService.updateContractField(contractCode,
					ContractFieldEnum.PROJECT_CONTRACT_MODE_CODE.getFieldKey(), newProjectContractModeCode);
				exportDTOList.add(
					buildContractTaxRateUpdateExportDTO(contract, contractFieldMap.get(contractCode), "是", null,
						newTaxRate, newProjectContractModeCode, excelProjectOrderId));
				successCount++;
			} catch (Exception e) {
				LOGGER.error("修改合同税率和承包模式失败，contractCode: {}", contractCode, e);
				exportDTOList.add(
					buildContractTaxRateUpdateExportDTO(contract, contractFieldMap.get(contractCode), "否",
						"更新失败：" + e.getMessage(), null, null, excelProjectOrderId));
				failCount++;
			}
		}
	}

	return new BatchExportResult<>(exportDTOList, successCount, failCount);
}

private ContractTaxRateUpdateExportDTO buildUnknownContractTaxRateExportDTO(String projectOrderId,
	String contractCode, String failReason) {
	return ContractTaxRateUpdateExportDTO.builder()
		.projectOrderId(projectOrderId)
		.contractCode(contractCode)
		.contractType("未知")
		.contractStatus("未知")
		.isUpdateSuccess("否")
		.failReason(failReason)
		.operateTime(DateUtil.now())
		.build();
}

private ContractTaxRateUpdateExportDTO buildContractTaxRateUpdateExportDTO(Contract contract,
	Map<String, String> fieldMap,
	String isUpdateSuccess, String failReason,
	String taxRateAfter, String projectContractModeCodeAfter, String excelProjectOrderId) {
	String taxRateBefore = fieldMap != null ? fieldMap.get(ContractFieldEnum.TAX_RATE.getFieldKey()) : null;
	String projectContractModeCodeBefore =
		fieldMap != null ? fieldMap.get(ContractFieldEnum.PROJECT_CONTRACT_MODE_CODE.getFieldKey()) : null;

	// 优先使用导入时的订单号，如果为空则使用合同中的订单号
	String projectOrderId = StringUtils.isNotBlank(excelProjectOrderId) ? excelProjectOrderId : contract.getProjectOrderId();

	return ContractTaxRateUpdateExportDTO.builder()
		.projectOrderId(projectOrderId)
		.contractCode(contract.getContractCode())
		.contractType(ContractTypeEnum.getNameByCode(contract.getType()))
		.contractStatus(ContractStatusEnum.getMap().get(contract.getStatus()))
		.taxRateBefore(taxRateBefore)
		.projectContractModeCodeBefore(projectContractModeCodeBefore)
		.isUpdateSuccess(isUpdateSuccess)
		.failReason(failReason)
		.taxRateAfter(taxRateAfter)
		.projectContractModeCodeAfter(projectContractModeCodeAfter)
		.operateTime(DateUtil.now())
		.build();
}

private String exportContractTaxRateUpdateResult(List<ContractTaxRateUpdateExportDTO> exportDTOList) {
	// 按订单号升序排序
	exportDTOList.sort(Comparator.comparing(ContractTaxRateUpdateExportDTO::getProjectOrderId,
		Comparator.nullsLast(String::compareTo)));
	// 生成excel文件
	String fileName = "update_contract_tax_rate_result_" + System.currentTimeMillis()
			+ Constant.FILE_SUFFIX_XLSX;
	ByteArrayOutputStream excelFile = new ByteArrayOutputStream();
	ExcelUtils.download(excelFile, ContractTaxRateUpdateExportDTO.class, exportDTOList, fileName);
	// 上传S3并返回URL
	return s3Service.uploadPublic(excelFile.toByteArray(), fileName);
}

public void undoFormalContract(MultipartFile excelFile) {
	// 解析并校验Excel文件
	List<ContractCodeImportDTO> importDTOList = parseAndValidateExcel(excelFile);

	LOGGER.info("撤回待签署正签合同任务开始，导入数量: {}", importDTOList.size());

	// 异步执行任务
	CompletableFuture.runAsync(RunnableWrapper.of(() -> {
		try {
			doUndoFormalContract(importDTOList);
		} catch (Exception e) {
			LOGGER.error("撤回待签署正签合同任务执行异常", e);
		}
	}));
}

private void doUndoFormalContract(List<ContractCodeImportDTO> importDTOList) {
	LOGGER.info("撤回待签署正签合同任务开始执行");
	long startTime = System.currentTimeMillis();

	// 构造要写入的excelDTO集合
	List<UndoContractExportDTO> exportDTOList = new ArrayList<>();
	int totalSuccessCount = 0;
	int batchSize = 100;

	// 分批处理，每批100条
	List<List<ContractCodeImportDTO>> batchList = ListUtils.partition(importDTOList, batchSize);
	for (int i = 0; i < batchList.size(); i++) {
		List<ContractCodeImportDTO> batch = batchList.get(i);
		LOGGER.info("撤回待签署正签合同，开始处理第{}批，共{}批，本批数量: {}", i + 1, batchList.size(), batch.size());

		// 处理当前批次
		BatchExportResult<UndoContractExportDTO> result = processBatchUndoFormalContract(batch);
		exportDTOList.addAll(result.getExportDTOList());
		totalSuccessCount += result.getSuccessCount();

		LOGGER.info("撤回待签署正签合同，第{}批处理完成，本批成功: {}，本批失败: {}",
			i + 1, result.getSuccessCount(), result.getFailCount());
	}

	// 按订单号升序排序后写入excel
	try {
		String excelUrl = exportUndoContractResult(exportDTOList);
		long costTime = System.currentTimeMillis() - startTime;
		LOGGER.info(
			"撤回待签署正签合同任务完成，耗时: {}ms，总批数: {}，总数: {}，总成功: {}，总失败: {}，结果Excel URL: {}",
			costTime, batchList.size(), importDTOList.size(), totalSuccessCount,
			importDTOList.size() - totalSuccessCount, excelUrl);
	} catch (Exception e) {
		LOGGER.error("撤回待签署正签合同，导出Excel失败", e);
	}
}

private BatchExportResult<UndoContractExportDTO> processBatchUndoFormalContract(List<ContractCodeImportDTO> batch) {
	List<UndoContractExportDTO> exportDTOList = new ArrayList<>();
	int successCount = 0;
	int failCount = 0;

	// 用dto集合里的合同号集合去查合同
	List<String> contractCodeList = batch.stream()
		.map(ContractCodeImportDTO::getContractCode)
		.filter(StringUtils::isNotBlank)
		.collect(Collectors.toList());
	List<Contract> contractList = CollectionUtils.isEmpty(contractCodeList) ? new ArrayList<>()
		: contractService.getListByContractCodes(contractCodeList, false);

	// 构建合同Map
	Map<String, Contract> contractMap = contractList.stream()
		.collect(Collectors.toMap(Contract::getContractCode, contract -> contract, (v1, v2) -> v1));

	// 查询合同字段（税率）
	Map<String, Map<String, String>> contractFieldMap = new HashMap<>();
	if (CollectionUtils.isNotEmpty(contractList)) {
		List<String> existContractCodeList = contractList.stream()
			.map(Contract::getContractCode)
			.collect(Collectors.toList());
		List<String> fieldKeys = Collections.singletonList(ContractFieldEnum.TAX_RATE.getFieldKey());
		List<ContractField> contractFields =
			contractFieldService.getValueByContractCodeAndFieldKey(existContractCodeList, fieldKeys);
		if (CollectionUtils.isNotEmpty(contractFields)) {
			contractFieldMap = contractFields.stream()
				.collect(Collectors.groupingBy(ContractField::getContractCode,
					Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue, (v1, v2) -> v1)));
		}
	}

	// 校验通过的合同号集合
	List<String> validContractCodeList = new ArrayList<>();

	// 遍历当前批次进行校验
	for (ContractCodeImportDTO importDTO : batch) {
		UndoContractValidationContext ctx = new UndoContractValidationContext();
		ctx.contractCode = importDTO.getContractCode();
		ctx.excelProjectOrderId = importDTO.getProjectOrderId();
		// 校验必要字段（合同号、合同存在、订单号）
		if (ctx.isValid && !validateRequiredFieldsForUndo(ctx, contractMap, contractFieldMap, exportDTOList)) {
			failCount++;
		}
		// 校验合同类型
		if (ctx.isValid && !validateContractTypeForUndo(ctx, exportDTOList)) {
			failCount++;
		}
		// 校验合同状态
		if (ctx.isValid && !validateContractStatusForUndo(ctx, exportDTOList)) {
			failCount++;
		}
		// 校验税率必须为3
		if (ctx.isValid && !validateTaxRateForUndo(ctx, exportDTOList)) {
			failCount++;
		}
		if (ctx.isValid) {
			validContractCodeList.add(ctx.contractCode);
		}
	}

	// 执行撤回
	if (CollectionUtils.isNotEmpty(validContractCodeList)) {
		for (String contractCode : validContractCodeList) {
			Contract contract = contractMap.get(contractCode);
			// 从batch中找到对应的projectOrderId（优先用Excel中的）
			String excelProjectOrderId = batch.stream()
				.filter(dto -> contractCode.equals(dto.getContractCode()))
				.map(ContractCodeImportDTO::getProjectOrderId)
				.filter(StringUtils::isNotBlank)
				.findFirst()
				.orElse(null);
			try {
				homeAndPcCommonService.undoContract(contractCode, Long.valueOf(Constant.SYSTEM_CREATE_UCID));
				exportDTOList.add(buildUndoContractExportDTO(contract, excelProjectOrderId, "是", null));
				successCount++;
			} catch (Exception e) {
				LOGGER.error("撤回待签署正签合同失败，contractCode: {}", contractCode, e);
				exportDTOList.add(
					buildUndoContractExportDTO(contract, excelProjectOrderId, "否", "撤回失败：" + e.getMessage()));
				failCount++;
			}
		}
	}

	return new BatchExportResult<>(exportDTOList, successCount, failCount);
}

