private boolean validateRequiredFieldsForUndo(UndoContractValidationContext ctx, Map<String, Contract> contractMap,
	Map<String, Map<String, String>> contractFieldMap, List<UndoContractExportDTO> exportDTOList) {
	// 校验合同号不为空
	if (StringUtils.isBlank(ctx.contractCode)) {
		exportDTOList.add(buildUnknownUndoContractExportDTO(ctx.excelProjectOrderId, ctx.contractCode, "合同号为空"));
		ctx.isValid = false;
		return false;
	}

	// 校验合同存在
	ctx.contract = contractMap.get(ctx.contractCode);
	if (ctx.contract == null) {
		exportDTOList.add(buildUnknownUndoContractExportDTO(ctx.excelProjectOrderId, ctx.contractCode, "未找到对应的合同"));
		ctx.isValid = false;
		return false;
	}

	// 校验合同订单号不为空
	if (StringUtils.isBlank(ctx.contract.getProjectOrderId())) {
		exportDTOList.add(buildUndoContractExportDTO(ctx.contract, ctx.excelProjectOrderId, "否", "合同订单号为空"));
		ctx.isValid = false;
		return false;
	}

	// 校验订单号一致
	if (StringUtils.isNotBlank(ctx.excelProjectOrderId)
		&& !ctx.excelProjectOrderId.equals(ctx.contract.getProjectOrderId())) {
		exportDTOList.add(buildUndoContractExportDTO(ctx.contract, ctx.excelProjectOrderId, "否", "查出来的订单号和excel不一致"));
		ctx.isValid = false;
		return false;
	}

	// 获取字段Map（后续校验需要使用）
	ctx.fieldMap = contractFieldMap.get(ctx.contractCode);

	return true;
}

private boolean validateContractTypeForUndo(UndoContractValidationContext ctx,
	List<UndoContractExportDTO> exportDTOList) {
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(ctx.contract.getType())) {
		exportDTOList.add(buildUndoContractExportDTO(ctx.contract, ctx.excelProjectOrderId, "否", "仅支持正签合同"));
		ctx.isValid = false;
		return false;
	}
	return true;
}

private boolean validateContractStatusForUndo(UndoContractValidationContext ctx,
	List<UndoContractExportDTO> exportDTOList) {
	if (!ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(ctx.contract.getStatus())) {
		exportDTOList.add(buildUndoContractExportDTO(ctx.contract, ctx.excelProjectOrderId, "否", "仅支持待签署状态的合同"));
		ctx.isValid = false;
		return false;
	}
	return true;
}

private boolean validateTaxRateForUndo(UndoContractValidationContext ctx,
	List<UndoContractExportDTO> exportDTOList) {
	String taxRate = ctx.fieldMap != null ? ctx.fieldMap.get(ContractFieldEnum.TAX_RATE.getFieldKey()) : null;
	if (!"3".equals(taxRate)) {
		exportDTOList.add(buildUndoContractExportDTO(ctx.contract, ctx.excelProjectOrderId, "否", "税率必须为3"));
		ctx.isValid = false;
		return false;
	}
	return true;
}

private UndoContractExportDTO buildUnknownUndoContractExportDTO(String projectOrderId, String contractCode,
	String failReason) {
	return UndoContractExportDTO.builder()
		.projectOrderId(projectOrderId)
		.contractCode(contractCode)
		.contractType("未知")
		.contractStatus("未知")
		.isUndoSuccess("否")
		.failReason(failReason)
