private void repairAll(Long startId, Long endId) {
	LOGGER.info("[刷数]开始刷数，startId={}, endId={}", startId, endId);
	int pageNum = 1;
	int pageSize = 50;
	long totalProcessed = 0;
	while (true) {
		Example example = new Example(ContractQuotationRelation.class);
		Example.Criteria criteria = example.createCriteria()
			.andEqualTo("status", RelationStatusEnum.RELATED.getCode())
			.andEqualTo("bindType", BindTypeEnum.BILL_CODE.getCode())
			.andEqualTo("delStatus", 0);
		// 支持按 ID 范围过滤
		if (startId != null) {
			criteria.andGreaterThanOrEqualTo("id", startId);
		}
		if (endId != null) {
			criteria.andLessThanOrEqualTo("id", endId);
		}
		example.orderBy("id").asc();

		PageInfo<ContractQuotationRelation> pageInfo = contractQuotationRelationService.selectPageByExample(example, pageNum, pageSize);
		List<ContractQuotationRelation> relations = pageInfo.getList();

		if (CollectionUtils.isEmpty(relations)) {
			LOGGER.info("[刷数]全量刷数结束，pageNum={}, 总处理条数={}", pageNum, totalProcessed);
			break;
		}

		LOGGER.info("[刷数]处理第{}页，数据条数={}", pageNum, relations.size());

		// 过滤非销售合同的关联关系
		List<ContractQuotationRelation> personalRelations = filterPersonalContractRelations(relations);
		if (CollectionUtils.isEmpty(personalRelations)) {
			LOGGER.info("[刷数]当前批次无销售合同关联关系，跳过，pageNum={}", pageNum);
			pageNum++;
			continue;
		}

		long processed = processRelationsBatch(personalRelations);
		totalProcessed += processed;

		try {
			Thread.sleep(200L);
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			break;
		}
		pageNum++;
	}
	LOGGER.info("[刷数]全量刷数完成，总处理条数={}", totalProcessed);
}

