private long processRelationsBatch(List<ContractQuotationRelation> relations) {
	// 批量查询合同（调用方已确保只传入销售合同的关联关系）
	List<String> contractCodes = relations.stream()
		.map(ContractQuotationRelation::getContractCode)
		.distinct()
		.collect(Collectors.toList());
	List<Contract> contracts = contractService.getListByContractCodes(contractCodes, false);
	Map<String, Contract> contractMap = contracts.stream()
		.collect(Collectors.toMap(Contract::getContractCode, c -> c, (a, b) -> a));

	// 批量查询报价单
	List<String> billCodes = relations.stream()
		.map(ContractQuotationRelation::getBillCode)
		.collect(Collectors.toList());
	Map<String, BudgetBillDTO.BillDTO> billMap = new HashMap<>();
	if (!billCodes.isEmpty()) {
		List<BudgetBillDTO.BillDTO> bills = atomBudgetRpc.queryBillsByBillCodes(billCodes);
		billMap = bills.stream().collect(Collectors.toMap(BudgetBillDTO.BillDTO::getBillCode, b -> b, (a, b) -> a));
	}

	long processed = 0;
	// 遍历处理
	for (ContractQuotationRelation relation : relations) {
		Contract contract = contractMap.get(relation.getContractCode());
		if (contract == null) {
			continue;
		}
		try {
			BudgetBillDTO.BillDTO bill = billMap.get(relation.getBillCode());
			if (bill == null) {
				LOGGER.warn("[刷数]报价单不存在，跳过，billCode={}", relation.getBillCode());
				continue;
			}
			processSingleRelation(contract, relation, bill);
			processed++;
		} catch (Exception e) {
			LOGGER.error("[刷数]处理异常，contractCode={}, billCode={}", relation.getContractCode(), relation.getBillCode(), e);
		}
	}
	return processed;
}

