private void processSingleRelation(Contract contract, ContractQuotationRelation relation, BudgetBillDTO.BillDTO bill) {
	List<Integer> cooperBillTypes = Arrays.asList(
		GeneralBillTypeEnum.BUDGET_COOPER.getCode(),
		GeneralBillTypeEnum.BUDGET_GROUP.getCode()
	);

	if (cooperBillTypes.contains(bill.getBillType())) {
		// 协同报价单/团装报价单 → 解绑报价单，绑定 S 单
		try {
			quotationRelationCommonService.convertCooperBillToSubOrderByContract(contract);
			LOGGER.info("[刷数]协同报价单换绑成功，contractCode={}, billCode={}", contract.getContractCode(), relation.getBillCode());
		} catch (Exception e) {
			LOGGER.error("[刷数]协同报价单换绑失败，contractCode={}, billCode={}", contract.getContractCode(), relation.getBillCode(), e);
		}
	} else if (GeneralBillTypeEnum.BUDGET_STANDARD.getCode().equals(bill.getBillType())) {
		// 基础报价单 → 保留报价单，新增绑定 S 单
		try {
			quotationRelationCommonService.convertStandardBillToSubOrder(contract, relation.getBillCode());
			LOGGER.info("[刷数]基础报价单换绑成功，contractCode={}, billCode={}", contract.getContractCode(), relation.getBillCode());
		} catch (Exception e) {
			LOGGER.error("[刷数]基础报价单换绑失败，contractCode={}, billCode={}", contract.getContractCode(), relation.getBillCode(), e);
		}
	} else {
		LOGGER.warn("[刷数]不支持的报价单类型，跳过，billCode={}, billType={}", relation.getBillCode(), bill.getBillType());
	}
}

public Map<String, Map<String, Object>> checkBindingByOrderId(String projectOrderId) {
	Map<String, Map<String, Object>> result = new LinkedHashMap<>();

	List<Contract> validPersonalContracts = contractService.getContractList(projectOrderId).stream()
		.filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))
		.filter(contract -> ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus()))
		.collect(Collectors.toList());

	if (CollectionUtils.isEmpty(validPersonalContracts)) {
		result.put("info", Collections.singletonMap("info", "订单下无有效销售合同"));
		return result;
	}

	for (Contract contract : validPersonalContracts) {
		BillCheckContext context = getBillCheckContext(contract.getContractCode());
		Map<String, Object> contractResult = checkContractBinding(
			projectOrderId, contract.getCompanyCode(), context
		);
		result.put(contract.getContractCode(), contractResult);
	}

	return result;
}

private Map<String, Object> checkContractBinding(String projectOrderId, String companyCode,
												  BillCheckContext context) {
	Map<String, Object> contractResult = new LinkedHashMap<>();

	// 1. 校验基础报价单
	List<Map<String, Object>> standardResults = checkBills(
		projectOrderId, companyCode, context.getValidStandardBillCodes(),
		context.getBoundSubOrderNos(), "基础报价单号", null
	);
	contractResult.put("基础报价单校验", standardResults);

	// 2. 校验变更单
	List<Map<String, Object>> changeOrderResults = checkChangeOrders(
		projectOrderId, companyCode, context.getValidChangeOrderIds(),
		context.getBoundSubOrderNos()
	);
	contractResult.put("变更单校验", changeOrderResults);

	// 3. 校验协同报价单
	List<Map<String, Object>> cooperResults = checkCooperBills(
		projectOrderId, companyCode, context.getValidCooperBillCodes(),
		context.getBillMap(), context.getBoundSubOrderNos()
	);
	contractResult.put("协同报价单校验", cooperResults);

	// 4. 汇总结果
	boolean allCorrect = allCheckPassed(standardResults)
		&& allCheckPassed(changeOrderResults)
		&& allCheckPassed(cooperResults);
	contractResult.put("校验结果", allCorrect ? "正确" : "错误");

	return contractResult;
}

private List<Map<String, Object>> checkBills(String projectOrderId, String companyCode,
											  List<String> billCodes, Set<String> boundSubOrderNos,
											  String billTypeKey,
											  Map<String, BudgetBillDTO.BillDTO> billMap) {
	List<Map<String, Object>> results = new ArrayList<>();
	for (String billCode : billCodes) {
		Set<String> expectedSubOrders = querySubOrdersByBillCode(projectOrderId, billCode, companyCode);
		Map<String, Object> checkResult = checkAndBuildResult(billCode, billTypeKey, expectedSubOrders, boundSubOrderNos);
		results.add(checkResult);
	}
	return results;
}

private List<Map<String, Object>> checkChangeOrders(String projectOrderId, String companyCode,
													 List<String> changeOrderIds, Set<String> boundSubOrderNos) {
	List<Map<String, Object>> results = new ArrayList<>();
	for (String changeOrderId : changeOrderIds) {
		Set<String> expectedSubOrders = querySubOrdersByChangeOrderId(projectOrderId, changeOrderId, companyCode);
		Map<String, Object> checkResult = checkAndBuildResult(changeOrderId, "变更单号", expectedSubOrders, boundSubOrderNos);
		results.add(checkResult);
	}
	return results;
}

private List<Map<String, Object>> checkCooperBills(String projectOrderId, String companyCode,
													List<String> billCodes,
													Map<String, BudgetBillDTO.BillDTO> billMap,
													Set<String> boundSubOrderNos) {
	List<Map<String, Object>> results = new ArrayList<>();
	for (String billCode : billCodes) {
		BudgetBillDTO.BillDTO bill = billMap.get(billCode);
		Set<String> expectedSubOrders = querySubOrdersByBillCode(projectOrderId, billCode, companyCode);
		boolean alreadyBound = expectedSubOrders.stream().anyMatch(boundSubOrderNos::contains);

		Map<String, Object> checkResult = checkAndBuildResult(billCode, "协同报价单号", expectedSubOrders, boundSubOrderNos);
		checkResult.put("报价单状态", bill.getStatus());
		checkResult.put("是否已换绑S单", alreadyBound);
		results.add(checkResult);
	}
	return results;
}

private boolean allCheckPassed(List<Map<String, Object>> checkResults) {
	return checkResults.stream()
		.allMatch(r -> (Boolean) r.get("是否正确"));
}

private Set<String> querySubOrdersByBillCode(String projectOrderId, String billCode, String companyCode) {
	return subOrderFeignService.queryValidBaseInfoByHomeOrderNo(projectOrderId, billCode, null)
		.stream()
		.filter(dto -> companyCode.equals(dto.getMdmCode()))
		.map(com.ke.utopia.nrs.orderservice.read.dto.suborder.SubOrderBaseInfoDTO::getOrderNo)
		.collect(Collectors.toSet());
}

private Set<String> querySubOrdersByChangeOrderId(String projectOrderId, String changeOrderId, String companyCode) {
	return subOrderFeignService.queryValidBaseInfoByHomeOrderNo(projectOrderId, null, changeOrderId)
		.stream()
		.filter(dto -> companyCode.equals(dto.getMdmCode()))
		.map(com.ke.utopia.nrs.orderservice.read.dto.suborder.SubOrderBaseInfoDTO::getOrderNo)
		.collect(Collectors.toSet());
}

private Map<String, Object> checkAndBuildResult(String billCode, String billTypeKey,
	Set<String> expectedSubOrders, Set<String> boundSubOrders) {
	// 计算应该换绑、已换绑、漏换绑
	Set<String> actualBound = new HashSet<>(boundSubOrders);
	actualBound.retainAll(expectedSubOrders);
	Set<String> missing = new HashSet<>(expectedSubOrders);
	missing.removeAll(boundSubOrders);

	Map<String, Object> result = new LinkedHashMap<>();
	result.put(billTypeKey, billCode);
	result.put("应该换绑S单", new ArrayList<>(expectedSubOrders));
	result.put("已换绑S单", new ArrayList<>(actualBound));
	result.put("漏换绑S单", new ArrayList<>(missing));
	result.put("是否正确", missing.isEmpty());
	return result;
}

private boolean isBillStatusValid(Integer billStatus) {
	if (billStatus == null) {
		return false;
	}
	return !GeneralBillStatusEnum.IN_ADJUST.getCode().equals(billStatus)
		&& !GeneralBillStatusEnum.DELETED.getCode().equals(billStatus)
		&& !GeneralBillStatusEnum.CANCELED.getCode().equals(billStatus);
}

