@Service
@Slf4j
public class ContractVideoService {
	@Resource
	private CommonBusinessService commonBusinessService;
	@Resource
	private ContractService contractService;

	@Resource
	private ContractLogService contractLogService;

	@Resource
	private UserFeignService userFeignService;

	@Resource
	private CipherService cipherService;

	@Resource
	private ContractUserService contractUserService;

	@Resource
	private ContractApolloConfig contractApolloConfig;
	@Resource
	private ContractRelationService contractRelationService;
	@Resource
	private ContractUnifyService contractUnifyService;

	/**
	 * 获取视频初始化信息
	 *
	 * @param contractCode
	 * @return
	 */
	public ContractVideoDTO getContractVideo(String contractCode) {
		// 权限校验
		ContractUser contractUser = contractUserService.getSignerByContractCode(contractCode);
		if (contractUser == null) {
			throw new NrsBusinessException("签约用户不存在", Level.WARN);
		}
		String signPhone = cipherService.decrypt(contractUser.getPhone());
		CUserDTO userDTO = userFeignService.getUserInfo(HeaderContext.getUserId().toString());
		if (!userDTO.getPhone().equals(signPhone)) {
			ContractVideoDTO result = new ContractVideoDTO();
			result.setAuthCode(AuthCodeEnum.USER_NOT_SAME.getCode());
			result.setAuthError(UserNotSameError.builder()
				.signerPhone(StringUtils.isBlank(signPhone) ? "" : signPhone.substring(signPhone.length() - 4))
				.loginPhone(StringUtils.isBlank(userDTO.getPhone()) ? "" : userDTO.getPhone().substring(userDTO.getPhone().length() - 4))
				.helpUrl(contractApolloConfig.getUserNameNotSameHelpUrl())
				.build());
			return result;
		}

		Contract contract = contractService.getByContractCode(contractCode);
		if (contract == null) {
			throw new NrsBusinessException("当前合同不存在，请确认操作是否正确", Level.WARN);
		}
		Byte contractType = contract.getType();
		String videoSkipUrl = "";
		MiniPayChannelAppNameEnum miniPayChannelAppNameEnum = commonBusinessService
			.getMiniProgramType(contract.getProjectOrderId());
		boolean isDeveloperChannel = contractUnifyService.isDeveloperChannel(contract.getProjectOrderId());
		// 获取签约视频链接
		videoSkipUrl = getVideoSkipUrlNew(contract, miniPayChannelAppNameEnum, isDeveloperChannel);
		//获取合同，如果存在关联合同则获取主合同
		ContractRelation byRelateContractCode = contractRelationService.getByRelateContractCode(contractCode);
		if (byRelateContractCode != null && !ContractTypeEnum.AUTH_AGENT.getCode().equals(contractType)) {
			contract = contractService.getByContractCode(byRelateContractCode.getContractCode());
		}

		boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contractType);

		// 按城市配置是否可跳过
		Boolean canSkipWatch = getCanSkipWatch(contract.getType(), contract.getBusinessType(), contract.getGbCode(), processV25);

		Integer watchStatus = WatchStatusEnum.FINISH.getCode();//默认不需要观看
		String signSchema = "";
		if (needWatchVideo(contract, processV25)) {
			// 观看状态
			watchStatus = getWatchStatusNew(contract, HeaderContext.getUserId().toString());
			signSchema = contractApolloConfig.getSignSchema().concat(contract.getContractCode());
		}
		String noticeToCustomerUrl = "";
		// 团装 2.5 返回对客告知书
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType()) && processV25) {
			noticeToCustomerUrl = contractApolloConfig.getNoticeToCustomersConfigByGbCode(contract.getGbCode());
		} else if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(contract.getBusinessType()) && processV25) {
			noticeToCustomerUrl = contractApolloConfig.getHouseNoticeToCustomersConfigByGbCode(contract.getGbCode(), isDeveloperChannel);
		}
		boolean supportWatchVideo = contractApolloConfig.isSupportWatchVideo(contract.getBusinessType(), contract.getGbCode());
		if (supportWatchVideo && StringUtils.isBlank(videoSkipUrl)) {
			LOGGER.error("获取视频跳转地址失败，contractCode: {}, businessType: {}, gbCode: {}",
				contractCode, contract.getBusinessType(), contract.getGbCode());
		}
		return ContractVideoDTO.builder().contractCode(contractCode).contractType(contractType)
			.videoDesc(contractApolloConfig.getVideoDesc()).coverImage(contractApolloConfig.getCoverImage())
			.videoSkipUrl(videoSkipUrl).canSkipWatch(canSkipWatch).watchStatus(watchStatus).signSchema(signSchema)
			.isSupportWatchVideo(supportWatchVideo)
			.noticeToCustomerUrl(noticeToCustomerUrl)
			.build();
	}

	/**
	 * 获取视频跳转地址，装修类型+小程序类型+是否开渠+合同类型+城市维度签约视频配置
	 * @param contract
	 * @param miniPayChannelAppNameEnum
	 * @param isDeveloperChannel
	 * @return
	 */
	public String getVideoSkipUrlNew(Contract contract, MiniPayChannelAppNameEnum miniPayChannelAppNameEnum, boolean isDeveloperChannel) {
		Byte businessType = contract.getBusinessType();
		Byte contractType = contract.getType();
		Integer gbCode = contract.getGbCode();

		String videoSkipUrlByCity = contractApolloConfig.getVideoSkipUrlByCity(gbCode, businessType, contractType, miniPayChannelAppNameEnum.getMiniProgramType(), isDeveloperChannel);
		if (StringUtils.isBlank(videoSkipUrlByCity)) {
			videoSkipUrlByCity = contractApolloConfig.getVideoSkipUrl(businessType, miniPayChannelAppNameEnum.getMiniProgramType(), isDeveloperChannel);
		}

		return videoSkipUrlByCity;
	}

	/**
	 * 根据业务类型+2.5+合同类型，判断是否需要观看视频
	 * (整装 && (正签合同 || 首期款合同)) || (团装 2.5 & &(正签合同 || 销售合同))
	 *
	 * @param contract
	 * @param processV25
	 * @return
	 */
	public boolean needWatchVideo(Contract contract, Boolean processV25) {
		Byte businessType = contract.getBusinessType();
		Byte contractType = contract.getType();

		boolean isHouse = BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType);
		boolean isGroupV25 = BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25;

		boolean isPackageFormal = ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType);
		boolean isAdvance = ContractTypeEnum.ADVANCE.getCode().equals(contractType);
		boolean isPersonal = ContractTypeEnum.PERSONAL.getCode().equals(contractType);

		return (isHouse && (isPackageFormal || isAdvance))
			|| (isGroupV25 && (isPackageFormal || isPersonal));
	}

	/**
	 * 根据业务类型 + 合同类型，查看当前项目下，对应视频的观看状态
	 * 团装 2.5：（正签合同||销售合同）看过，则视频观看状态为 FINISH
	 * 整装 2.5：（正签合同||首期款合同）看过， 则视频观看状态为 FINISH
	 *
	 * @param contract
	 * @param processV25
	 * @param createUserId
	 * @return
	 */
	public Integer getWatchStatus(Contract contract, Boolean processV25, String createUserId) {
		Byte businessType = contract.getBusinessType();
		String projectOrderId = contract.getProjectOrderId();
		Integer watchStatus = WatchStatusEnum.NOT_FINISH.getCode();
		List<Contract> contractList = new ArrayList<>();

		// 团装 2.5：判断当前项目下的（正签合同 || 销售合同）是否已经观看
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25) {
			contractList = contractService.getContractList(projectOrderId,
				Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PERSONAL.getCode()));
		} else if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			// 整装：判断当前项目下的（首期款合同 || 正签合同）是否已经观看
			contractList = contractService.getContractList(projectOrderId,
				Arrays.asList(ContractTypeEnum.ADVANCE.getCode(), ContractTypeEnum.PACKAGE_FORMAL.getCode()));
		}

		if (CollectionUtils.isEmpty(contractList)) {
			// 不存在需要观看的合同类型，无需观看
			watchStatus = WatchStatusEnum.FINISH.getCode();
		} else {
			List<String> contractCodes = contractList.stream().map(Contract::getContractCode)
				.collect(Collectors.toList());
			List<ContractLog> contractLogList = contractLogService.getLogByCodeAndCreateUserId(contractCodes,
				LogTypeEnum.WATCH_VEDIO.getCode(), createUserId);
			if (!CollectionUtils.isEmpty(contractLogList)) {
				// 如果需要观看视频的合同已经存在观看记录，则不需要再次观看
				watchStatus = WatchStatusEnum.FINISH.getCode();
			}
		}
		return watchStatus;
	}

	/**
	 * 现有观看状态判定逻辑是按项目维度，页面观看完视频前端会上报观看完成状态，记录到合同log表，如果存在观看记录后续则无需再次观看签约视频。
	 * 由于新增了合同类型配置维度，不同合同类型签约视频会存在差异，是否观看完成的判断逻辑，细化到视频链接维度
	 *
	 * 1、查询项目合同
	 * 2、根据合同查询观看记录
	 * 3、如果合同中，存在观看记录，并且配置视频链接相同则视为已观看完成
	 */
	public Integer getWatchStatusNew(Contract contract, String createUserId) {
		MiniPayChannelAppNameEnum miniProgramType = commonBusinessService.getMiniProgramType(contract.getGbCode());
		boolean developerChannel = contractUnifyService.isDeveloperChannel(contract.getProjectOrderId());
		return getWatchStatusNew(contract, miniProgramType, developerChannel, createUserId);
	}

	public Integer getWatchStatusNew(Contract contract, MiniPayChannelAppNameEnum miniPayChannelAppNameEnum, boolean isDeveloperChannel, String createUserId) {
		String projectOrderId = contract.getProjectOrderId();
		List<Contract> contractList = contractService.getContractList(projectOrderId);
		List<String> contractCodes = contractList.stream()
			.map(Contract::getContractCode)
			.collect(Collectors.toList());
		contractCodes.add(contract.getContractCode());

		List<ContractLog> contractLogList = contractLogService.getLogByCodeAndCreateUserId(contractCodes,
			LogTypeEnum.WATCH_VEDIO.getCode(), createUserId);
		if (CollectionUtils.isEmpty(contractLogList)) {
			return WatchStatusEnum.NOT_FINISH.getCode();
		}

		// 已观看合同类型
		Set<String> watchedVideoUrl = new HashSet<>();
		for (ContractLog contractLog : contractLogList) {
			String contractCode = contractLog.getContractCode();
			contractList.stream().filter(c -> c.getContractCode().equals(contractCode))
				.findFirst()
				.ifPresent(c -> {
					String videoUrl = getVideoSkipUrlNew(c, miniPayChannelAppNameEnum, isDeveloperChannel);
					if (StringUtils.isNotBlank(videoUrl)) {
						watchedVideoUrl.add(videoUrl);
					}
				});
		}

		String videoUrl = getVideoSkipUrlNew(contract, miniPayChannelAppNameEnum, isDeveloperChannel);
		return watchedVideoUrl.contains(videoUrl) ? WatchStatusEnum.FINISH.getCode() : WatchStatusEnum.NOT_FINISH.getCode();
	}

	private Boolean getCanSkipWatch(Byte contractType, Byte businessType, Integer gbCode, boolean processV25) {
		// 团装 2.5 && （正签 || 销售）
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25) {
			// 默认不跳过
			boolean canSkipWatch = false;
			// contractType 为查询维度，获取需要跳过的城市
			VideoGroupV25SkipCityConfig skipCityConfig = contractApolloConfig.getVideoGroupV25SkipCityConfig().stream()
				.filter(config -> config.getContractType().equals(contractType))
				.findFirst().orElse(null);
			if (skipCityConfig != null && skipCityConfig.isSkip(gbCode)) {
				canSkipWatch = true;
			}
			return canSkipWatch;
		} else if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			// 整装
			// 默认跳过
			boolean canSkipWatch = true;
			List<Integer> noSkipCities = getNoSkipCities(contractType);
			if (!CollectionUtils.isEmpty(noSkipCities) && noSkipCities.contains(gbCode)) {
				canSkipWatch = false;
			}
			return canSkipWatch;
		}
		// 未指定其获取规则，返回 null
		return false;
	}

	/**
	 * @Title: getNoSkipCities
	 * @Description: 获取不跳过视频的城市
	 * @author: xueyaowei
	 */
	private List<Integer> getNoSkipCities(Byte type) {

		if (ContractTypeEnum.ADVANCE.getCode().equals(type)) {
			//首期合同
			return StringUtils.isEmpty(contractApolloConfig.getAdvanceNoSkipCity()) ? new ArrayList<>()
				: Arrays.stream(contractApolloConfig.getAdvanceNoSkipCity().split(",")).map(Integer::parseInt)
				.collect(Collectors.toList());
		} else if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(type)) {
			//正式合同
			return StringUtils.isEmpty(contractApolloConfig.getPackageFormalNoSkipCity()) ? new ArrayList<>()
				: Arrays.stream(contractApolloConfig.getPackageFormalNoSkipCity().split(",")).map(Integer::parseInt)
				.collect(Collectors.toList());
		} else {
			return new ArrayList<>();
		}
	}

	/**
	 * 提交视频观看完成
	 *
	 * @param contractCode
	 */
	@Transactional
	public ContractVideoWatchDTO submitVideo(String contractCode) {

		// 权限校验
		ContractUser contractUser = contractUserService.getSignerByContractCode(contractCode);
		if (contractUser == null) {
			throw new NrsBusinessException("签约用户不存在", Level.WARN);
		}
		String signPhone = cipherService.decrypt(contractUser.getPhone());
		CUserDTO userDTO = userFeignService.getUserInfo(HeaderContext.getUserId().toString());

		// 查询当前项目下此用户是否观看过视频
		if (userDTO.getPhone().equals(signPhone)) {
			Contract contract = contractService.getByContractCode(contractCode);
			if (contract == null) {
				throw new NrsBusinessException("查询不到合同", Level.WARN);
			}

			ContractRelation byRelateContractCode = contractRelationService.getByRelateContractCode(contractCode);
			if (byRelateContractCode != null) {
				contract = contractService.getByContractCode(byRelateContractCode.getContractCode());
			}

			Integer watchStatus = WatchStatusEnum.FINISH.getCode();// 默认不需要观看
			boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
			if (needWatchVideo(contract, processV25)) {
				watchStatus = getWatchStatusNew(contract, HeaderContext.getUserId().toString());
			}
			if (WatchStatusEnum.NOT_FINISH.getCode().equals(watchStatus)) {
				// 没有观看完则插入log
				contractLogService.createLog(contract.getContractCode(), LogTypeEnum.WATCH_VEDIO.getCode(),
					LogTypeEnum.WATCH_VEDIO.getName(), "", HeaderContext.getUserId().toString(),
					HeaderContext.getContext().getOperatorName() == null ? ""
						: HeaderContext.getContext().getOperatorName());
				return ContractVideoWatchDTO.builder().watchStatus(WatchStatusEnum.FINISH.getCode()).build();
			}
			return ContractVideoWatchDTO.builder().watchStatus(watchStatus).build();
		}
		throw new NrsBusinessException("登录用户和签约用户不一致", Level.WARN);
	}
}

