public ContractVideoDTO getContractVideo(String contractCode) {
	// 权限校验
	ContractUser contractUser = contractUserService.getSignerByContractCode(contractCode);
	if (contractUser == null) {
		throw new NrsBusinessException("签约用户不存在", Level.WARN);
	}
	String signPhone = cipherService.decrypt(contractUser.getPhone());
	CUserDTO userDTO = userFeignService.getUserInfo(HeaderContext.getUserId().toString());
	if (!userDTO.getPhone().equals(signPhone)) {
		ContractVideoDTO result = new ContractVideoDTO();
		result.setAuthCode(AuthCodeEnum.USER_NOT_SAME.getCode());
		result.setAuthError(UserNotSameError.builder()
			.signerPhone(StringUtils.isBlank(signPhone) ? "" : signPhone.substring(signPhone.length() - 4))
			.loginPhone(StringUtils.isBlank(userDTO.getPhone()) ? "" : userDTO.getPhone().substring(userDTO.getPhone().length() - 4))
			.helpUrl(contractApolloConfig.getUserNameNotSameHelpUrl())
			.build());
		return result;
	}

	Contract contract = contractService.getByContractCode(contractCode);
	if (contract == null) {
		throw new NrsBusinessException("当前合同不存在，请确认操作是否正确", Level.WARN);
	}
	Byte contractType = contract.getType();
	String videoSkipUrl = "";
	MiniPayChannelAppNameEnum miniPayChannelAppNameEnum = commonBusinessService
		.getMiniProgramType(contract.getProjectOrderId());
	boolean isDeveloperChannel = contractUnifyService.isDeveloperChannel(contract.getProjectOrderId());
	// 获取签约视频链接
	videoSkipUrl = getVideoSkipUrlNew(contract, miniPayChannelAppNameEnum, isDeveloperChannel);
	//获取合同，如果存在关联合同则获取主合同
	ContractRelation byRelateContractCode = contractRelationService.getByRelateContractCode(contractCode);
	if (byRelateContractCode != null && !ContractTypeEnum.AUTH_AGENT.getCode().equals(contractType)) {
		contract = contractService.getByContractCode(byRelateContractCode.getContractCode());
	}

	boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contractType);

	// 按城市配置是否可跳过
	Boolean canSkipWatch = getCanSkipWatch(contract.getType(), contract.getBusinessType(), contract.getGbCode(), processV25);

	Integer watchStatus = WatchStatusEnum.FINISH.getCode();//默认不需要观看
	String signSchema = "";
	if (needWatchVideo(contract, processV25)) {
		// 观看状态
		watchStatus = getWatchStatusNew(contract, HeaderContext.getUserId().toString());
		signSchema = contractApolloConfig.getSignSchema().concat(contract.getContractCode());
	}
	String noticeToCustomerUrl = "";
	// 团装 2.5 返回对客告知书
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType()) && processV25) {
		noticeToCustomerUrl = contractApolloConfig.getNoticeToCustomersConfigByGbCode(contract.getGbCode());
	} else if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(contract.getBusinessType()) && processV25) {
		noticeToCustomerUrl = contractApolloConfig.getHouseNoticeToCustomersConfigByGbCode(contract.getGbCode(), isDeveloperChannel);
	}
	boolean supportWatchVideo = contractApolloConfig.isSupportWatchVideo(contract.getBusinessType(), contract.getGbCode());
	if (supportWatchVideo && StringUtils.isBlank(videoSkipUrl)) {
		LOGGER.error("获取视频跳转地址失败，contractCode: {}, businessType: {}, gbCode: {}",
			contractCode, contract.getBusinessType(), contract.getGbCode());
	}
	return ContractVideoDTO.builder().contractCode(contractCode).contractType(contractType)
		.videoDesc(contractApolloConfig.getVideoDesc()).coverImage(contractApolloConfig.getCoverImage())
		.videoSkipUrl(videoSkipUrl).canSkipWatch(canSkipWatch).watchStatus(watchStatus).signSchema(signSchema)
		.isSupportWatchVideo(supportWatchVideo)
		.noticeToCustomerUrl(noticeToCustomerUrl)
		.build();
}

