public boolean needWatchVideo(Contract contract, Boolean processV25) {
	Byte businessType = contract.getBusinessType();
	Byte contractType = contract.getType();

	boolean isHouse = BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType);
	boolean isGroupV25 = BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25;

	boolean isPackageFormal = ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType);
	boolean isAdvance = ContractTypeEnum.ADVANCE.getCode().equals(contractType);
	boolean isPersonal = ContractTypeEnum.PERSONAL.getCode().equals(contractType);

	return (isHouse && (isPackageFormal || isAdvance))
		|| (isGroupV25 && (isPackageFormal || isPersonal));
}

