public Integer getWatchStatus(Contract contract, Boolean processV25, String createUserId) {
	Byte businessType = contract.getBusinessType();
	String projectOrderId = contract.getProjectOrderId();
	Integer watchStatus = WatchStatusEnum.NOT_FINISH.getCode();
	List<Contract> contractList = new ArrayList<>();

	// 团装 2.5：判断当前项目下的（正签合同 || 销售合同）是否已经观看
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25) {
		contractList = contractService.getContractList(projectOrderId,
			Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PERSONAL.getCode()));
	} else if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
		// 整装：判断当前项目下的（首期款合同 || 正签合同）是否已经观看
		contractList = contractService.getContractList(projectOrderId,
			Arrays.asList(ContractTypeEnum.ADVANCE.getCode(), ContractTypeEnum.PACKAGE_FORMAL.getCode()));
	}

	if (CollectionUtils.isEmpty(contractList)) {
		// 不存在需要观看的合同类型，无需观看
		watchStatus = WatchStatusEnum.FINISH.getCode();
	} else {
		List<String> contractCodes = contractList.stream().map(Contract::getContractCode)
			.collect(Collectors.toList());
		List<ContractLog> contractLogList = contractLogService.getLogByCodeAndCreateUserId(contractCodes,
			LogTypeEnum.WATCH_VEDIO.getCode(), createUserId);
		if (!CollectionUtils.isEmpty(contractLogList)) {
			// 如果需要观看视频的合同已经存在观看记录，则不需要再次观看
			watchStatus = WatchStatusEnum.FINISH.getCode();
		}
	}
	return watchStatus;
}

