public Integer getWatchStatusNew(Contract contract, MiniPayChannelAppNameEnum miniPayChannelAppNameEnum, boolean isDeveloperChannel, String createUserId) {
	String projectOrderId = contract.getProjectOrderId();
	List<Contract> contractList = contractService.getContractList(projectOrderId);
	List<String> contractCodes = contractList.stream()
		.map(Contract::getContractCode)
		.collect(Collectors.toList());
	contractCodes.add(contract.getContractCode());

	List<ContractLog> contractLogList = contractLogService.getLogByCodeAndCreateUserId(contractCodes,
		LogTypeEnum.WATCH_VEDIO.getCode(), createUserId);
	if (CollectionUtils.isEmpty(contractLogList)) {
		return WatchStatusEnum.NOT_FINISH.getCode();
	}

	// 已观看合同类型
	Set<String> watchedVideoUrl = new HashSet<>();
	for (ContractLog contractLog : contractLogList) {
		String contractCode = contractLog.getContractCode();
		contractList.stream().filter(c -> c.getContractCode().equals(contractCode))
			.findFirst()
			.ifPresent(c -> {
				String videoUrl = getVideoSkipUrlNew(c, miniPayChannelAppNameEnum, isDeveloperChannel);
				if (StringUtils.isNotBlank(videoUrl)) {
					watchedVideoUrl.add(videoUrl);
				}
			});
	}

	String videoUrl = getVideoSkipUrlNew(contract, miniPayChannelAppNameEnum, isDeveloperChannel);
	return watchedVideoUrl.contains(videoUrl) ? WatchStatusEnum.FINISH.getCode() : WatchStatusEnum.NOT_FINISH.getCode();
}

private Boolean getCanSkipWatch(Byte contractType, Byte businessType, Integer gbCode, boolean processV25) {
	// 团装 2.5 && （正签 || 销售）
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25) {
		// 默认不跳过
		boolean canSkipWatch = false;
		// contractType 为查询维度，获取需要跳过的城市
		VideoGroupV25SkipCityConfig skipCityConfig = contractApolloConfig.getVideoGroupV25SkipCityConfig().stream()
			.filter(config -> config.getContractType().equals(contractType))
			.findFirst().orElse(null);
		if (skipCityConfig != null && skipCityConfig.isSkip(gbCode)) {
			canSkipWatch = true;
		}
		return canSkipWatch;
	} else if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
		// 整装
		// 默认跳过
		boolean canSkipWatch = true;
		List<Integer> noSkipCities = getNoSkipCities(contractType);
		if (!CollectionUtils.isEmpty(noSkipCities) && noSkipCities.contains(gbCode)) {
			canSkipWatch = false;
		}
		return canSkipWatch;
	}
	// 未指定其获取规则，返回 null
	return false;
}

private List<Integer> getNoSkipCities(Byte type) {

	if (ContractTypeEnum.ADVANCE.getCode().equals(type)) {
		//首期合同
		return StringUtils.isEmpty(contractApolloConfig.getAdvanceNoSkipCity()) ? new ArrayList<>()
			: Arrays.stream(contractApolloConfig.getAdvanceNoSkipCity().split(",")).map(Integer::parseInt)
			.collect(Collectors.toList());
	} else if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(type)) {
		//正式合同
		return StringUtils.isEmpty(contractApolloConfig.getPackageFormalNoSkipCity()) ? new ArrayList<>()
			: Arrays.stream(contractApolloConfig.getPackageFormalNoSkipCity().split(",")).map(Integer::parseInt)
			.collect(Collectors.toList());
	} else {
		return new ArrayList<>();
	}
}

