@Transactional
public ContractVideoWatchDTO submitVideo(String contractCode) {

	// 权限校验
	ContractUser contractUser = contractUserService.getSignerByContractCode(contractCode);
	if (contractUser == null) {
		throw new NrsBusinessException("签约用户不存在", Level.WARN);
	}
	String signPhone = cipherService.decrypt(contractUser.getPhone());
	CUserDTO userDTO = userFeignService.getUserInfo(HeaderContext.getUserId().toString());

	// 查询当前项目下此用户是否观看过视频
	if (userDTO.getPhone().equals(signPhone)) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (contract == null) {
			throw new NrsBusinessException("查询不到合同", Level.WARN);
		}

		ContractRelation byRelateContractCode = contractRelationService.getByRelateContractCode(contractCode);
		if (byRelateContractCode != null) {
			contract = contractService.getByContractCode(byRelateContractCode.getContractCode());
		}

		Integer watchStatus = WatchStatusEnum.FINISH.getCode();// 默认不需要观看
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
		if (needWatchVideo(contract, processV25)) {
			watchStatus = getWatchStatusNew(contract, HeaderContext.getUserId().toString());
		}
		if (WatchStatusEnum.NOT_FINISH.getCode().equals(watchStatus)) {
			// 没有观看完则插入log
			contractLogService.createLog(contract.getContractCode(), LogTypeEnum.WATCH_VEDIO.getCode(),
				LogTypeEnum.WATCH_VEDIO.getName(), "", HeaderContext.getUserId().toString(),
				HeaderContext.getContext().getOperatorName() == null ? ""
					: HeaderContext.getContext().getOperatorName());
			return ContractVideoWatchDTO.builder().watchStatus(WatchStatusEnum.FINISH.getCode()).build();
		}
		return ContractVideoWatchDTO.builder().watchStatus(watchStatus).build();
	}
	throw new NrsBusinessException("登录用户和签约用户不一致", Level.WARN);
}

