@Service
@Slf4j
public class DesignFeeAuditBpmService {

    @Resource
    private CeresRpc ceresRpc;

    @Resource
    private ContractApolloConfig contractApolloConfig;

    @Resource
    private MemberRpc memberRpc;

    @Resource
    private BpmService bpmService;

    @Resource
    private BaseAuditChannel baseAuditChannel;

    @Resource
    private ContractFieldService contractFieldService;

    @Resource
    private ProjectInfoReadService projectInfoReadService;

    @Resource
    private HomeAndPcCommonService homeAndPcCommonService;

    /**
     * 发起设计费审核 BPM 审批流
     *
     * @param dto 审核发起参数
     * @return BPM 流程实例详情
     */
    public ProcessInstanceDetailResponse applyDesignFeeAuditBpm(DesignFeeAuditApplyDTO dto) {
        // 构建 bpm 审批发起请求参数
        BpmRequestDTO<Object, Object> requestDTO = buildBpmApplyRequest(dto);
        LOGGER.info("[design_fee_audit] bpm 审批发起请求参数, contractCode={}, requestDTO={}",
                dto.getContractCode(), JSON.toJSONString(requestDTO));
        // 发起 bpm 审批流
		ProcessInstanceDetailResponse processInstanceDetailResponse;
		try {
			processInstanceDetailResponse = bpmService.applyBpm(requestDTO);
		} catch (Exception e) {
			LOGGER.error("[design_fee_audit] 发起设计费审批 BPM 流程异常, contractCode={}", dto.getContractCode(), e);
			throw new NrsBusinessException("发起设计费审批bpm发起异常，返回processInstId为空");
		}
		LOGGER.info("发起设计费审批---返回值>>>:{}", JSON.toJSONString(processInstanceDetailResponse));
		if (processInstanceDetailResponse == null || processInstanceDetailResponse.getData() == null) {
			throw new NrsBusinessException("发起设计费审批bpm发起异常，返回数据为空");
		}
		return processInstanceDetailResponse;
    }

    /**
     * 构建 bpm 审批发起请求参数
     */
    private BpmRequestDTO<Object, Object> buildBpmApplyRequest(DesignFeeAuditApplyDTO dto) {
		// 发起人为项目上的设计师，取设计师 ucid 转换为系统号和姓名
		Long designerUcId = baseAuditChannel.queryProjectDesignerUcId(dto.getProjectOrderId());
		String designerUcIdStr = String.valueOf(designerUcId);
		String applyUserCode = memberRpc.getUserSystemCode(designerUcIdStr);
		JSONObject record = buildRecordData(dto, memberRpc.getUserName(designerUcIdStr), applyUserCode);

        Map<String, String> vars = Maps.newHashMap();

        return BpmRequestDTO.builder()
                .processDefId(contractApolloConfig.getDesignFeeAuditBpmProcessDefId())
                .userSystemCode(applyUserCode)
                .boName(contractApolloConfig.getDesignFeeAuditBpmBoName())
                .processBusinessKey(IdGenerator.getContractBpmGeneratorId())
                .vars(vars)
                .recordData(record)
                .build();
    }

    /**
     * 构建 BPM 表单数据
     */
    private JSONObject buildRecordData(DesignFeeAuditApplyDTO dto, String applyUserName, String systemCode) {
        JSONObject record = new JSONObject();
        String projectOrderId = dto.getProjectOrderId();
        String contractCode = dto.getContractCode();
		// 申请人（APPLY_USER）：项目设计师姓名拼接(系统号)
		String applyUser = StringUtils.isNotBlank(applyUserName)
				? applyUserName + "(" + systemCode + ")"
				: systemCode;
		record.put("APPLY_USER", applyUser);
        // 项目 id（PROJECT_ORDER_ID）
        record.put("PROJECT_ORDER_ID", projectOrderId);
        // 申请日期（APPLY_TIME）：当前发起时刻
        record.put("APPLY_TIME", new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date()));
        // 从项目信息获取客户姓名、项目地址、分公司信息
        try {
            ProjectInfoDTO projectInfo = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
            if (projectInfo != null) {
                // 客户姓名（CUSTOMER_NAME）
                Optional.ofNullable(projectInfo.getCustomer())
                        .map(c -> c.getName())
                        .ifPresent(name -> record.put("CUSTOMER_NAME", name));
                // 项目地址（PROJECT_ADDRESS）
                String projectAddress = homeAndPcCommonService.getAddress(projectInfo);
                if (StringUtils.isNotBlank(projectAddress)) {
                    record.put("PROJECT_ADDRESS", projectAddress);
                }
                // 分公司信息（BILL_ORGANIZATION / BILL_ORGANIZATION_CODE）
                ProjectCustomerCommissionDTO commission = projectInfo.getCustomerCommission();
                if (commission != null) {
                    String companyCode = commission.getCompanyCode();
                    String companyName = commission.getCompanyName();
                    if (StringUtils.isNotBlank(companyCode)) {
                        record.put("BILL_ORGANIZATION_CODE", companyCode);
                    }
                    if (StringUtils.isNotBlank(companyName) && StringUtils.isNotBlank(companyCode)) {
                        // 分公司全称后面拼接 MDM id
                        record.put("BILL_ORGANIZATION", companyName + companyCode);
                    }
                }
            }
        } catch (Exception e) {
            LOGGER.error("[design_fee_audit] 获取项目信息失败，BPM 表单字段不完整, projectOrderId={}", projectOrderId, e);
        }

        // 从 contract_field 获取设计费相关字段
        try {
            Map<String, String> fieldMap = contractFieldService.getFieldMap(contractCode);

            // 设计费优惠前应收（DESIGN_FEE_BEFORE_COUPON）
            String preDiscountStr = fieldMap.get("preDiscountDesignerAmount");
            BigDecimal preDiscount = null;
            if (StringUtils.isNotBlank(preDiscountStr)) {
                preDiscount = new BigDecimal(preDiscountStr).setScale(2, RoundingMode.HALF_UP);
                record.put("DESIGN_FEE_BEFORE_COUPON", preDiscount.toPlainString());
            }
            // 设计费优惠后应收（DESIGN_FEE_AFTER_COUPON）
            String afterDiscountStr = fieldMap.get("afterDiscountDesignerAmount");
            BigDecimal afterDiscount = null;
            if (StringUtils.isNotBlank(afterDiscountStr)) {
                afterDiscount = new BigDecimal(afterDiscountStr).setScale(2, RoundingMode.HALF_UP);
                record.put("DESIGN_FEE_AFTER_COUPON", afterDiscount.toPlainString());
            }
            // 设计费应收折扣率（DESIGN_FEE_DISCOUNT_RATE）：after/pre*100，保留2位小数，加%
            if (preDiscount != null && afterDiscount != null
                    && preDiscount.compareTo(BigDecimal.ZERO) != 0) {
				// 核心修改：100 → 10，计算结果直接从 83.38 变为 8.33
				BigDecimal discountRate = afterDiscount
					.divide(preDiscount, 4, RoundingMode.HALF_UP)
					.multiply(new BigDecimal("10"))
					.setScale(2, RoundingMode.HALF_UP);
				record.put("DESIGN_FEE_DISCOUNT_RATE", discountRate.toPlainString());
            }
            // 折扣率计算口径（DISCOUNT_RATE_CAL_CALIBER）：固定文案
            record.put("DISCOUNT_RATE_CAL_CALIBER", "折扣=设计费优惠后应收/设计费优惠前应收*10");
            // 申请原因（AUDITREMARK）：优惠备注
            String auditReason = fieldMap.get("auditReason");
            if (StringUtils.isNotBlank(auditReason)) {
                record.put("AUDITREMARK", auditReason);
            } else {
				LOGGER.warn("[design_fee_audit] 申请原因字段为空, contractCode:{}", contractCode);
				record.put("AUDITREMARK", "系统自动发起审核，未填写申请原因");
			}
        } catch (Exception e) {
            LOGGER.error("[design_fee_audit] 获取 contract_field 失败，设计费核心字段不完整, contractCode={}", contractCode, e);
        }

        return record;
    }
}

    public ProcessInstanceDetailResponse applyDesignFeeAuditBpm(DesignFeeAuditApplyDTO dto) {
        // 构建 bpm 审批发起请求参数
        BpmRequestDTO<Object, Object> requestDTO = buildBpmApplyRequest(dto);
        LOGGER.info("[design_fee_audit] bpm 审批发起请求参数, contractCode={}, requestDTO={}",
                dto.getContractCode(), JSON.toJSONString(requestDTO));
        // 发起 bpm 审批流
		ProcessInstanceDetailResponse processInstanceDetailResponse;
		try {
			processInstanceDetailResponse = bpmService.applyBpm(requestDTO);
		} catch (Exception e) {
			LOGGER.error("[design_fee_audit] 发起设计费审批 BPM 流程异常, contractCode={}", dto.getContractCode(), e);
			throw new NrsBusinessException("发起设计费审批bpm发起异常，返回processInstId为空");
		}
		LOGGER.info("发起设计费审批---返回值>>>:{}", JSON.toJSONString(processInstanceDetailResponse));
		if (processInstanceDetailResponse == null || processInstanceDetailResponse.getData() == null) {
			throw new NrsBusinessException("发起设计费审批bpm发起异常，返回数据为空");
		}
		return processInstanceDetailResponse;
    }

