@Slf4j
@Service
public class DesignFeeAuditService {

	private static final List<Byte> DESIGN_TYPES = Arrays.asList(
		ContractTypeEnum.DESIGN.getCode(),
		ContractTypeEnum.DESIGN_CHANGE.getCode()
	);

	private static final String FIELD_KEY_PRE_DISCOUNT = "preDiscountDesignerAmount";
	private static final String FIELD_KEY_AFTER_DISCOUNT = "afterDiscountDesignerAmount";

	@Resource
	private ContractFieldService contractFieldService;

	@Resource
	private DesignFeeAuditBpmService designFeeAuditBpmService;

	@Resource
	private AuditCheckStrategyFactory auditCheckStrategyFactory;

	@Resource
	private CommonBusinessService commonBusinessService;

	@Resource
	private ContractUnifyService contractUnifyService;


	/**
	 * 判断合同类型是否属于设计+整装场景(合同类型+整装+2.5流程)
	 *
	 * @param contractType 合同类型，来自 {@link ContractTypeEnum}
	 * @param businessType 业务类型，来自 {@link BusinessTypeEnum}
	 */
	public boolean isDesignSceneAndHouse(Byte contractType, Byte businessType) {
		return isDesignScene(contractType) && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType);
	}

	/**
	 * 判断合同类型是否属于设计场景
	 *
	 * @param contractType 合同类型，来自 {@link ContractTypeEnum}
	 */
	public boolean isDesignScene(Byte contractType) {
		return DESIGN_TYPES.contains(contractType);
	}

	/**
	 * 提交合同时判断是否需要走设计费专项审批
	 *
	 * @param contract 合同实体，调用方保证非 null
	 * @return true 表示设计合同且超底，需要走设计费专项审批流
	 */
	public boolean isDesignFeeExceedBottomOnSubmit(Contract contract) {
		// 有上下文的从上下文取费用并校验，没上下文的走 DB 校验
		List<Byte> hasContextTypes = Arrays.asList(
			ContractTypeEnum.DESIGN.getCode());
		if (hasContextTypes.contains(contract.getType())) {
			// 请求上下文取优惠前后费用
			ContractReqDTO contractReq = ContractContextHandler.getContractReq();
			if(contractReq == null || contractReq.getProjectInfo() == null) {
				LOGGER.info("[design_fee_audit] designFeeAuditCheck contractReq is null, contractCode:{}", contract.getContractCode());
				return false;
			}
			ContractProjectInfoReq projectInfo = contractReq.getProjectInfo();
			DesignQuoteFeeDTO designQuoteFeeDTO = ContractContextHandler.getContext().getDesignQuoteFeeDTO();

			// 是否包含合并发起的C合同/需要合并发起C合同
			MiniPayChannelAppNameEnum miniProgramType = commonBusinessService.getMiniProgramType(contract.getProjectOrderId());
			boolean isMergeDesignContract = contractUnifyService.designFeeFromQuote(contract.getProjectOrderId())
				&& ObjectUtil.isNotEmpty(designQuoteFeeDTO)
				&& designQuoteFeeDTO.isHaveDesignQuote()
				&& MiniPayChannelAppNameEnum.被窝.equals(miniProgramType);

			AuditCheckDTO dto = buildDto(contract.getContractCode(), contract.getType(), contract.getProjectOrderId(),
				projectInfo.getPreDiscountDesignerAmount(), projectInfo.getAfterDiscountDesignerAmount(), contract.getBusinessType());
			dto.setMergeDesignContract(isMergeDesignContract);
			return auditCheckStrategyFactory.routeAndValidate(dto);
		} else {
			return isDesignFeeExceedBottom(contract);
		}
	}

	/**
	 * 判断合同是否属于设计费超底场景（设计合同类型 + 实时校验超底），仅读 DB。
	 *
	 * @param contract 合同实体，调用方保证非 null
	 * @return true 表示设计合同且超底，false 表示不满足条件
	 */
	public boolean isDesignFeeExceedBottom(Contract contract) {
		AuditCheckDTO dto = buildCheckDtoFromDb(contract);
		return auditCheckStrategyFactory.routeAndValidate(dto);
	}

	/**
	 * 从合同构建设计费校验 DTO，仅读 DB。
	 *
	 * @param contract 合同实体，调用方保证非 null 且类型已确认
	 * @return DTO，DB 无值时返回 null
	 */
	public AuditCheckDTO buildCheckDtoFromDb(Contract contract) {
		String contractCode = contract.getContractCode();
		List<ContractField> fieldList = contractFieldService.getValueByContractCodeAndFieldKey(
			Collections.singletonList(contractCode),
			Arrays.asList(FIELD_KEY_PRE_DISCOUNT, FIELD_KEY_AFTER_DISCOUNT));
		Map<String, String> fieldMap = fieldList.stream()
			.collect(Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue, (a, b) -> a));

		String preVal = fieldMap.get(FIELD_KEY_PRE_DISCOUNT);
		String afterVal = fieldMap.get(FIELD_KEY_AFTER_DISCOUNT);
		if (StringUtils.isBlank(preVal) || StringUtils.isBlank(afterVal)) {
			LOGGER.info("[design_fee_audit] buildCheckDtoFromDb 费用字段未入库, contractCode:{}", contractCode);
			return null;
		}

		try {
			return buildDto(contractCode, contract.getType(), contract.getProjectOrderId(),
				new BigDecimal(preVal), new BigDecimal(afterVal), contract.getBusinessType());
		} catch (NumberFormatException e) {
			LOGGER.warn("[design_fee_audit] buildCheckDtoFromDb 费用字段格式异常, contractCode:{}", contractCode);
			return null;
		}
	}

	/**
	 * 从前端校验请求构建设计费校验 DTO（前端校验接口专用）。
	 *
	 * <p>费用字段必须使用前端传参（用户正在填写，需实时校验）。
	 * {@code contractType} 和 {@code projectOrderId}：有草稿时取 DB 值（防篡改），无草稿时取前端传参。</p>
	 *
	 * @param req              前端传入的校验请求，调用方保证非 null
	 * @param existingContract 已有草稿合同，无草稿时传 null
	 * @return DTO
	 */
	public AuditCheckDTO buildCheckDtoFromReq(ContractCheckAuditWindowReqDTO req, Contract existingContract) {
		Byte contractType = existingContract != null ? existingContract.getType() : req.getContractType();
		String projectOrderId = existingContract != null ? existingContract.getProjectOrderId() : req.getProjectOrderId();
		String contractCode = existingContract != null ? existingContract.getContractCode()
			: StringUtils.defaultString(req.getContractCode(), "");

		return buildDto(contractCode, contractType, projectOrderId,
			req.getPreDiscountDesignerAmount(), req.getAfterDiscountDesignerAmount(), req.getBusinessType());
	}


	/**
	 * 发起设计费审核 BPM 审批流，返回流程实例详情供调用方做状态流转。
	 *
	 * @param contract 合同实体
	 * @return BPM 流程实例详情
	 */
	public ProcessInstanceDetailResponse applyDesignFeeAuditBpm(Contract contract) {
		DesignFeeAuditApplyDTO applyDTO = DesignFeeAuditApplyDTO.builder()
			.contractCode(contract.getContractCode())
			.projectOrderId(contract.getProjectOrderId())
			.build();
		return designFeeAuditBpmService.applyDesignFeeAuditBpm(applyDTO);
	}

	private AuditCheckDTO buildDto(String contractCode, Byte contractType, String projectOrderId,
			BigDecimal preDiscount, BigDecimal afterDiscount, Byte businessType) {
		return AuditCheckDTO.builder()
			.contractCode(contractCode)
			.contractType(contractType)
			.businessType(businessType)
			.projectOrderId(projectOrderId)
			.preDiscountDesignerAmount(preDiscount)
			.afterDiscountDesignerAmount(afterDiscount)
			.build();
	}
}

