@Service
@Slf4j
public class FaceAuthService {

	@Resource
	private ContractService contractService;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Resource
	private ProjectInfoReadService projectInfoReadService;

	@Resource
	private AuthFeign authFeign;

	@Resource
	private ContractRedisRepoService contractRedisRepoService;

	@Resource
	private CipherService cipherService;

	@Resource
	private CommonBusinessService commonBusinessService;

	@Resource
	private HomeAndPcCommonService homeAndPcCommonService;

	@Resource
	private ContractRelationService contractRelationService;

	public boolean canUseFaceAuth(List<String> contractCodeList, ContractUser signer) {
		List<Contract> contractList = contractService.getListByContractCodes(contractCodeList, true);
		if (CollectionUtils.isEmpty(contractList)) {
			return false;
		}

		Contract contract = contractList.get(0);
		ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
		if (contractRelation != null) {
			contract = contractService.getByContractCode(contractRelation.getContractCode());
		}

		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(contract.getProjectOrderId());
		if (projectInfoDTO == null) {
			return false;
		}

		Integer gbCode = projectInfoDTO.getCustomerHouse().getGbCode();

		// 项目白名单
		if (contractApolloConfig.getFaceAuthWhiteLists().contains(contract.getProjectOrderId())) {
			return false;
		}

		// 整装单子生效
		Byte businessType = commonBusinessService.getBusinessType(contract.getProjectOrderId());
		if (!BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			return false;
		}

		// 2.5单子生效
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
		if (!processV25) {
			return false;
		}

		// 非身份证不支持人脸认证
		if (!CertificateTypeEnum.ID.getCode().equals(signer.getCertificateType())) {
			return false;
		}

		// 非正式签署不支持人脸认证
		if (!UserSignTypeEnum.SIGN.getCode().equals(contract.getUserSignType())) {
			return false;
		}

		// 开城城市 && 已配置的合同类型
		return contractApolloConfig.getFaceAuthOpenCity().contains(gbCode) &&
			contractApolloConfig.getFaceAuthContractTypes().contains(contract.getType());
	}

	public String getFaceAuthUrl(String contractCode, String name, String certNo, String phone, String returnUrl) {
		Map<String, String> decrypt = cipherService.decrypt(Arrays.asList(certNo, phone));

		// 三密解密
		certNo = decrypt.getOrDefault(certNo, certNo);
		phone = decrypt.getOrDefault(phone, phone);
		// 信息加密
		try {
			certNo = AuthDESTools.encrypt(certNo);
			name = AuthDESTools.encrypt(name);
			phone = AuthDESTools.encrypt(phone);
		} catch (Exception e) {
			LOGGER.error("加密失败 name:{}, certNo:{}", name, certNo, e);
			throw new NrsBusinessException("获取人脸认证链接异常，请稍后重试或联系客服");
		}

		// 预下单
		FaceAuthPrepareParam faceAuthPrepareParam = FaceAuthPrepareParam.builder()
			.bizCode(contractApolloConfig.getFaceAuthBizCode())
			.product("unifiedAuth")
			.client("H5")
			.userName(name)
			.certType("01")
			.certNo(certNo)
			.phone(phone)
			.returnUrl(returnUrl)
			.build();
		AuthResultDTO<FaceAuthPrepareResult> authResultDTO = authFeign.authPrepare(faceAuthPrepareParam);
		if (authResultDTO != null && authResultDTO.isSuccess()) {
			// 记录业务流水号
			String bizFlowNo = authResultDTO.getData().getBizFlowNo();
			contractRedisRepoService.saveFaceAuthBizFlowNo(contractCode, bizFlowNo);

			return authResultDTO.getData().getScheme().getUnifiedAuth();
		}

		throw new NrsBusinessException("获取人脸认证链接异常，请稍后重试或联系客服");
	}

	public boolean getAuthResult(String contractCode) {
		// 结果查询
		String bizFlowNo = contractRedisRepoService.getFaceAuthBizFlowNo(contractCode);
		if (StringUtils.isEmpty(bizFlowNo)) {
			return false;
		}

		AuthResultDTO<FaceAuthQueryResult> authResultDTO = authFeign.authQuery(contractApolloConfig.getFaceAuthBizCode(), bizFlowNo);
		if (authResultDTO != null && authResultDTO.isSuccess()) {
			return "30".equals(authResultDTO.getData().getStatus());
		}

		return false;
	}
}

