	AuthResultDTO<FaceAuthQueryResult> authResultDTO = authFeign.authQuery(contractApolloConfig.getFaceAuthBizCode(), bizFlowNo);
	if (authResultDTO != null && authResultDTO.isSuccess()) {
		return "30".equals(authResultDTO.getData().getStatus());
	}

	return false;
}

