@Service
@Slf4j
public class FormalReSignService {

	@Resource
	private CommonBusinessService commonBusinessService;

	@Resource
	private ContractService contractService;

	@Resource
	private ContractNodeService contractNodeService;

	@Resource
	private HomeAndPcCommonService commonService;

	/**
	 * 获取2.0->2.5场景正签合同重签相关信息
	 */
	public ContractProcessModeChangeInfo getContractProcessModeChangeInfo(String projectOrderId) {
		ContractProcessModeChangeInfo contractProcessModeChangeInfo = new ContractProcessModeChangeInfo();
		HomeTagModel homeTagModel = commonBusinessService.getChangeProcessModeInfo(projectOrderId);
		boolean changeInTheProcessMode = commonBusinessService.changeInTheProcessMode(homeTagModel);
		if (!changeInTheProcessMode) {
			return contractProcessModeChangeInfo;
		}
		//获取所有正签合同列表
		List<Contract> formalContractList = contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		if (formalContractList.isEmpty()) {
			return contractProcessModeChangeInfo;
		}
		boolean haveHistoricalContract = haveHistoricalContract(formalContractList, homeTagModel);
		return ContractProcessModeChangeInfo.builder()
			.haveHistoricalContract(haveHistoricalContract)
			.isCancelHistoricalContract(isCancelHistoricalContract(formalContractList))
			.newContractLaunch(newContractLaunch(formalContractList, homeTagModel))
			.historicalContractLink(haveHistoricalContract ? historicalContractLink(formalContractList) : null)
			.build();
	}

	public ContractTypeListVo.FormalReSignInfo getFormalReSignInfo(ContractProcessModeChangeInfo contractProcessModeChangeInfo) {
		//2.5模式下是否有已完成的正签2.0合同
		boolean haveFinishFormalContract = contractProcessModeChangeInfo.isHaveHistoricalContract() && !contractProcessModeChangeInfo.isCancelHistoricalContract();
		//2.5模式下是否展示旧的正签2.0合同信息（pc）
		boolean showOldFormalContract = !contractProcessModeChangeInfo.isNewContractLaunch();
		//2.5模式下旧的已完成的正签2.0合同链接（pc）
		String oldFormalContractUrl = contractProcessModeChangeInfo.getHistoricalContractLink();
		return ContractTypeListVo.FormalReSignInfo.builder()
			.showOldFormalContract(showOldFormalContract)
			.oldFormalContractUrl(oldFormalContractUrl)
			.haveFinishFormalContract(haveFinishFormalContract)
			.build();
	}

	/**
	 * 是否可以创建新正签合同
	 */
	public boolean newFormalContractCanLaunch(ContractProcessModeChangeInfo contractProcessModeChangeInfo){
		//有已完结的2.0正签合同&&之前的2.0正签合同未取消
		return contractProcessModeChangeInfo.isHaveHistoricalContract() && !contractProcessModeChangeInfo.isCancelHistoricalContract();
	}


	/**
	 * 当前正签合同是否能发起，唯一性校验
	 */
	public boolean formalContractUnique(List<Contract> contractList){
		String projectOrderId = contractList.get(0).getProjectOrderId();
		contractList = contractList.stream().filter(contract -> !ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())).collect(Collectors.toList());
		ContractProcessModeChangeInfo contractProcessModeChangeInfo = getContractProcessModeChangeInfo(projectOrderId);
		//2.5模式下没有已完结的正签2.0合同
		if (!contractProcessModeChangeInfo.isHaveHistoricalContract()){
			return false;
		}
		if (contractProcessModeChangeInfo.isNewContractLaunch()){
			return false;
		}
		//只有一份正签合同&&已完结，则当前合同为2.0正签合同
		if (contractList.size() == 1 && contractList.get(0).getStatus().equals(ContractStatusEnum.FINISH.getCode())) {
			return true;
		}
		//存在两份合同，则一份2.0的已完结(已作废)正签合同，一份2.5正签合同
        return contractList.size() == 2;
    }


	/**
	 * 是否存在已完结的2.0正式套餐合同(包括已签署、已取消)
	 */
	private boolean haveHistoricalContract(List<Contract> formalContractList, HomeTagModel homeTagModel) {
		HomeTagModel.IHomeModeTag switchTag = homeTagModel.getModeTags().stream().filter(tag -> tag.getModeKey().equals("project_model_switch_tag")).findFirst().orElse(null);
		if (switchTag == null) {
			return false;
		}
		List<Integer> finishAndCancelStatus = Arrays.asList(ContractStatusEnum.FINISH.getCode(), ContractStatusEnum.CANCEL.getCode());
		Contract finshContract = formalContractList.stream().filter(contract -> finishAndCancelStatus.contains(contract.getStatus())).findFirst().orElse(null);
		if (finshContract == null) {
			return false;
		}
		if (finshContract.getStatus().equals(ContractStatusEnum.CANCEL.getCode())) {
			return true;
		}
		//获取刷数时间
		Date changeTime = switchTag.getMtime();
		//获取正签合同最近一次的发起时间
		ContractNode contractNode = contractNodeService.getListByContractCode(finshContract.getContractCode()).stream().filter(item -> item.getNodeType().equals(NodeTypeEnum.SUBMIT.getCode())).max(Comparator.comparing(ContractNode::getCtime)).orElse(null);
		if (contractNode == null) {
			LOGGER.error("正签合同{}没有发起节点", finshContract.getContractCode());
			return false;
		}
		//如何正签合同是刷数前发起的，说明是2.0的正签合同
        return changeTime.after(contractNode.getCtime());
    }

	/**
	 * 历史正签合同是否已经作废
	 */
	private boolean isCancelHistoricalContract(List<Contract> formalContractList) {
		Contract cancelContract = formalContractList.stream().filter(contract -> ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())).findFirst().orElse(null);
		if (cancelContract == null) {
			return false;
		}
		return cancelContract.getStatus().equals(ContractStatusEnum.CANCEL.getCode());
	}


	/**
	 * 2.5模式下2.5合同是否已发起
	 */
	private boolean newContractLaunch(List<Contract> formalContractList, HomeTagModel homeTagModel) {
		Contract launchContract = formalContractList.stream().filter(contract -> !ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())).findFirst().orElse(null);
		if (launchContract == null) {
			return false;
		}
		HomeTagModel.IHomeModeTag switchTag = homeTagModel.getModeTags().stream().filter(tag -> tag.getModeKey().equals("project_model_switch_tag")).findFirst().orElse(null);
		if (switchTag == null) {
			return false;
		}
		//获取正签合同最近一次的发起时间
		ContractNode contractNode = contractNodeService.getListByContractCode(launchContract.getContractCode()).stream().filter(item -> item.getNodeType().equals(NodeTypeEnum.SUBMIT.getCode())).max(Comparator.comparing(ContractNode::getCtime)).orElse(null);
		if (contractNode == null) {
			return false;
		}
		//如何正签合同的发起时间在刷数之后，说明是2.5的正签合同，判断合同状态是否为已发起
		if (contractNode.getCtime().after(switchTag.getMtime())) {
			return launchContract.getStatus() > ContractStatusEnum.DRAFT.getCode();
		}
		return false;
	}

	/**
	 * 历史正签完结合同链接
	 */
	private String historicalContractLink(List<Contract> formalContractList){
		if (CollectionUtils.isEmpty(formalContractList)) {
			return "";
		}
		formalContractList = formalContractList.stream().sorted(Comparator.comparing(Contract::getId)).collect(Collectors.toList());
		return commonService.getContractUrl(formalContractList.get(0));
	}




}

