@Service
@Slf4j
public class FreeformService {

	@Resource
	private FreeformApiFacade freeformApiFacade;

	@Resource
	private SealRoleTypeConfig sealRoleTypeConfig;

	@Resource
	private ContractCompanyInfoService contractCompanyInfoService;

	@ApolloJsonValue("${pdf_common_config}")
	private FreeformConfig freeformConfig;

	/**
	 * 创建协议平台实例
	 * @param formKey 板式类型
	 * @return
	 */
	public Long createInstance(String formKey, Long createUcId) {
		String pdfCommonConfig = ApolloUtil.getString(ApolloKeyEnum.NAMESPACE_CONTRACT.getCode(), ApolloKeyEnum.PDF_COMMON_DATA,"");
		JSONObject pdfCommonJson = JSONObject.parseObject(pdfCommonConfig);

		FormInstanceDto.NewInstanceArguments param = new FormInstanceDto.NewInstanceArguments();
		param.setCreator(createUcId);
		param.setFormKey(formKey);
		param.setApplication(pdfCommonJson.getString("application"));
		param.setCityCode(pdfCommonJson.getString("gbCode"));
		param.setCompany(pdfCommonJson.getString("company"));
		param.setCurrentOrg(pdfCommonJson.getString("currentOrg"));

		try {
			LOGGER.info("创建合同实例入参:{}", JsonUtil.toJsonString(param));
			long startTime = DateUtils.getCurrentTimeStamp();
			Long instanceId = freeformApiFacade.insertForm(param);
			long endTime = DateUtils.getCurrentTimeStamp();
			LOGGER.info("请求协议平台耗时:submit, cost:{}", endTime-startTime);
			LOGGER.info("创建合同实例出参:{}", instanceId);
			return instanceId;
		} catch (Exception e) {
			LOGGER.error("创建合同实例失败:", e);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "创建合同实例失败-[签约]");
		}
	}

	/**
	 * 提交表单
	 * @param instanceId
	 * @param contractNo
	 * @param createUcId
	 * @param formData
	 */
	public void submit(Long instanceId, String contractNo, Long createUcId, Map<String, Object> formData) {
		LOGGER.info("请求协议平台查询实例id,入参为：{}", instanceId);
		FormInstanceDto param = freeformApiFacade.getFormInstance(instanceId);
		LOGGER.info("请求协议平台查询实例id,出差为：{}", JSON.toJSONString(param));
		param.setCN(contractNo);
		param.setCreator(createUcId);
		param.setSaveOrSubmit(2);
		param.setCformData(formData);

		LOGGER.info("提交合同实例入参:{}", JsonUtil.toJsonString(param));
		try {
			long startTime = DateUtils.getCurrentTimeStamp();
			freeformApiFacade.submitForm(param, createUcId, param.getCurrentOrg());
			long endTime = DateUtils.getCurrentTimeStamp();
			LOGGER.info("请求协议平台耗时:submit, cost:{}", endTime-startTime);
		} catch (Exception e) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "创建合同提交表单数据失败-[签约]");
		}
	}

	/**
	 * 创建PDF
	 * @param instanceId 协议平台实例ID
	 * @param createUcId 创建人
	 * @param formId 板式id
	 * @param formData 表单字段，如果为空，会使用之前的内筒
	 * @param markText 水印文案
	 * @param addWaterMark 是否加水印
	 * @return
	 */
	public AttachmentInfo createPdf(Long instanceId, Long createUcId, Long formId, Map<String, Object> formData, Boolean addWaterMark, String markText) {
		GenPdfCommonParameter param = new GenPdfCommonParameter();
		param.setInstanceId(instanceId);
		param.setUserId(createUcId);
		param.setFormId(formId);
		if (addWaterMark) {
			param.setAddWaterMark(true);
			param.setMarkText(markText);
		}

		if (!Objects.isNull(formData)) {
			CFormData cFormData = new CFormData();
			cFormData.setCformData(formData);
			param.setFormData(cFormData);
		}

		try {
			LOGGER.info("生成合同PDF入参:{}", JsonUtil.toJsonString(param));
			long startTime = DateUtils.getCurrentTimeStamp();
			Result<AttachmentInfo> result = freeformApiFacade.generatePdfCommonWithParameter(param);
			long endTime = DateUtils.getCurrentTimeStamp();
			LOGGER.info("请求协议平台耗时:createPdf, cost:{}", endTime-startTime);
			LOGGER.info("生成合同PDF出参:{}", JSON.toJSONString(result));
			return result.getResult();
		} catch (Exception e) {
			LOGGER.error("创建合同生成PDF失败-[签约],{}", e.getMessage(),e);
			throw new NrsBusinessException(ResponseCodeEnum.PDF_CREATE_ERROR.getCode(),ResponseCodeEnum.PDF_CREATE_ERROR.getMsg());
		}
	}

	/**
	 * 盖公司章
	 * @param instanceId 实例id
	 * @param companyCode 公司信用编码
	 * @param ucId 合同创建人
	 * @param addWaterMark 是否添加水印
	 * @param signatureType 签章类型
	 * @return
	 */
	public String companySeal(Long instanceId, String companyCode, Long ucId, Boolean addWaterMark, Integer signatureType) {
		ContractSealCommonParameter param = new ContractSealCommonParameter();
		SealSigParameter sealSigner = new SealSigParameter();

		sealSigner.setRoleType("decoration_company");
		sealSigner.setSignType("COMPANY");
		sealSigner.setSignatureType(String.valueOf(signatureType));
		// 没传默认为1   1:使用公司编码    2:使用统一社会信用代码
		sealSigner.setCodeType(SealCodeTypeEnum.CREDITCODE.getCodeType());
		sealSigner.setCreditCode(companyCode);

		param.setSealSigList(Collections.singletonList(sealSigner));
		param.setInstanceId(instanceId);
		param.setAddWaterMark(addWaterMark);
		param.setUcId(ucId);
		//收据不显示盖章时间
		param.setIsShowHandwrittenTime(signatureType.equals(SignatureTypeEnum.FINANCE.getType()) ? "0" : "1");

		try {
			LOGGER.info("盖公司章PDF入参:{}", JsonUtil.toJsonString(param));
			long startTime = DateUtils.getCurrentTimeStamp();
			ResultWithTraceId<String> result = freeformApiFacade.contractSealV2(param);
			long endTime = DateUtils.getCurrentTimeStamp();
			LOGGER.info("请求协议平台耗时:companySeal, cost:{}", endTime-startTime);
			LOGGER.info("盖公司章PDF出参:{}", result);
			return result.getResult().toString();
		} catch (Exception e) {
			LOGGER.info("盖公司章异常:{}", e.getMessage(), e);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "盖公司章失败");
		}
	}

	/**
	 * 多主体盖公司章
	 */
	public String multiCompanySeal(Long instanceId, List<ContractCompany> contractCompanyList, Long ucId, Boolean addWaterMark, Byte contractType) {
		ContractSealCommonParameter param = new ContractSealCommonParameter();

		if (CollectionUtils.isEmpty(contractCompanyList)) {
			throw new NrsBusinessException("多主体异步盖公司章无公司主体信息");
		}

		List<String> companyCodes = contractCompanyList.stream().map(ContractCompany::getCompanyCode).collect(Collectors.toList());
		List<ContractCompanyInfo> contractCompanyInfos = contractCompanyInfoService.getByCompanyCodes(companyCodes);
		Map<String, ContractCompanyInfo> merchantBaseDTOMap = contractCompanyInfos.stream().collect(Collectors.toMap(ContractCompanyInfo::getCompanyCode, m -> m, (v1, v2) -> v2));

		List<SealSigParameter> sealSigList = new ArrayList<>();
		for (ContractCompany contractCompany : contractCompanyList) {
			ContractCompanyInfo contractCompanyInfo = merchantBaseDTOMap.get(contractCompany.getCompanyCode());
			if (contractCompanyInfo == null) {
				throw new NrsBusinessException(contractCompany.getCompanyCode() + "存管协议盖章分公司信息未配置");
			}

			SealSigParameter sealSigner = new SealSigParameter();
			sealSigner.setRoleType(sealRoleTypeConfig.getSealRoleType(contractType, contractCompany.getDecorateBusinessType()));
			sealSigner.setSignType("COMPANY");
			sealSigner.setSignatureType(contractCompany.getSignatureType().toString());
			sealSigner.setCodeType(SealCodeTypeEnum.CREDITCODE.getCodeType());
			sealSigner.setCreditCode(contractCompanyInfo.getCompanySealCode());
			sealSigList.add(sealSigner);
		}
		param.setSealSigList(sealSigList);

		param.setInstanceId(instanceId);
		param.setAddWaterMark(addWaterMark);
		param.setUcId(ucId);
		//显示盖章时间
		param.setIsShowHandwrittenTime("1");

		try {
			LOGGER.info("多主体盖公司章PDF入参:{}", JsonUtil.toJsonString(param));
			long startTime = DateUtils.getCurrentTimeStamp();
			ResultWithTraceId<String> result = freeformApiFacade.contractSealV2(param);
			long endTime = DateUtils.getCurrentTimeStamp();
			LOGGER.info("请求协议平台耗时:companySeal, cost:{}", endTime-startTime);
			LOGGER.info("多主体盖公司章PDF出参:{}", result);
			return result.getResult().toString();
		} catch (Exception e) {
			LOGGER.info("多主体盖公司章异常:{}", e.getMessage(), e);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "盖公司章失败");
		}
	}

	/**
	 * 异步盖公司章
	 * @param instanceId 实例id
	 * @param companyCode 公司信用编码
	 * @param ucId 合同创建人
	 * @param addWaterMark 是否添加水印
	 * @param signatureType 签章类型
	 * @return freeFormQueryKey 查询标识
	 */
