	/**
	 * 批量获取手签链接（由于协议平台不支持，目前对公签约不支持批量获取）
	 */
	public String getBathSignUrl(ContractBathSignUrlParam bathSignUrlParam) {
		ContractSealManualParameter param = new ContractSealManualParameter();
		//合同目录
		param.setCatalogName(bathSignUrlParam.getCatalogName());
		//手机号
		param.setVcodeMobile(bathSignUrlParam.getPhone());
		//回调url
		param.setReturnUrl(bathSignUrlParam.getReturnUrl());
		//系统名
		param.setApplication(Constant.SIGN_APPLICATION_NAME);
		//手签类型（1 用户手签 2.企业手签）
		param.setSealType((byte) 1);

		List<ContractSealCommonParameter> contractSealParamList = new ArrayList<>();

		for (Long instanceId : bathSignUrlParam.getInstanceIds()) {
			ContractSealCommonParameter contractSealParam = new ContractSealCommonParameter();
			contractSealParam.setUcId(HeaderContext.getUserId());
			contractSealParam.setInstanceId(instanceId);
			contractSealParam.setAddWaterMark(bathSignUrlParam.getAddWaterMark());

			List<SealSigParameter> sealSigList = new ArrayList<>();
			SealSigParameter sealSigParameter = new SealSigParameter();
			sealSigParameter.setRoleType(bathSignUrlParam.getSignUserRoleTypeMap().get(instanceId));
			//个人：PERSON   对公：COMPANY
			sealSigParameter.setSignType("PERSON");
			sealSigParameter.setSignatureType("0");
			//证件类型，枚举中取值
			sealSigParameter.setCardType(bathSignUrlParam.getCertificateType());
			//证件号
			sealSigParameter.setCardCode(bathSignUrlParam.getCertificateNo());

			sealSigList.add(sealSigParameter);
			contractSealParam.setSealSigList(sealSigList);
			contractSealParamList.add(contractSealParam);
		}
		param.setCreateSignRequestList(contractSealParamList);
		long startTime = DateUtils.getCurrentTimeStamp();
		LOGGER.info("批量获取手签链接，入参:{}", JSON.toJSONString(param));
		ResultWithTraceId<String> result = freeformApiFacade.contractSealManual(param);
		long endTime = DateUtils.getCurrentTimeStamp();
		LOGGER.info("批量获取手签链接，返回值:{}，耗时：{}", JSON.toJSONString(result), endTime - startTime);
		if (result.getCode() != 1) {
			LOGGER.error("批量获取手签链接失败，入参:{}, 返回值:{}", param, result);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "批量获取手签链接失败");
		}
		return result.getResult().toString();
	}

