	/**
	 * 获取企业实名是否成功
	 * @param legalCertificateNo 法定代表人的证件号
	 * @param creditCode	统一社会信用代码
	 * @return
	 */
	public Boolean getCompanyAuthenticationRes(String legalCertificateNo, String creditCode) {
		CompanyAccreditInfo accreditRes = getCompanyRealNameInfoWithCache(creditCode);
		//返回值为null，说明实名授权不存在或授权不成功
		if (accreditRes == null) {
			return false;
		}
		if (accreditRes.getAuthStatus() == null || accreditRes.getAuthStatus() != 1) {
			return false;
		}
		return StringUtils.isNotBlank(accreditRes.getLegalCardCode()) && accreditRes.getLegalCardCode().equals(legalCertificateNo);
	}

