public List<SignResultVo> getBatchContractSignResult(List<Long> instanceIds, Integer certificateType, String certificateNo,List<Long> userConfirmInstanceIdList) {
	List<CheckSignParameter> parameterList = new ArrayList<>();
	for (Long instanceId : instanceIds) {
		CheckSignParameter parameter = new CheckSignParameter();
		parameter.setInstanceId(instanceId);
		parameter.setCardType(certificateType);
		parameter.setCardCode(certificateNo);
		Boolean addWaterMark = userConfirmInstanceIdList.contains(instanceId);
		parameter.setAddWaterMark(addWaterMark);
		parameterList.add(parameter);
	}
	long startTime = DateUtils.getCurrentTimeStamp();
	LOGGER.info("批量查询手签签署结果入参:{}", JsonUtil.toJsonString(parameterList));
	ResultWithTraceId<List<SignResultVo>> result = freeformApiFacade.contractManualCheckV2(parameterList);
	long endTime = DateUtils.getCurrentTimeStamp();
	LOGGER.info("批量查询手签签署结果出参:{}，耗时：{}", JSON.toJSONString(result), endTime - startTime);
	List<SignResultVo> data = (List<SignResultVo>) result.getResult();
	if (result.getCode().equals(1) && CollectionUtils.isNotEmpty(data)) {
		return (List<SignResultVo>) result.getResult();
	}
	return Lists.newArrayList();
}

