	//合同url
	public String getContractUrl(Contract contract) {
		if (contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode())) {
			return s3Service.generateUrl(contractBusinessService.getContractLatestPdfKey(contract), 7200);
		}
		return "";
	}

	//附件
	public List<String> getAttachUrl(Contract contract) {
		if (contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode())) {
			return new ArrayList<>();
		}
		List<ContractAttach> attachList = contractAttachService.getListByContractCode(contract.getContractCode(), AttachTypeEnum.OFFLINE_CONTRACT.getCode());
		return attachList.stream().map(ContractAttach::getUrl).collect(Collectors.toList());
	}

	/**
	 * 获取预览合同url（线上合同是pdfUrl、线下合同是附件）
	 *
	 * @return
	 */
	public ContractPreviewVo getContractPreviewUrl(Contract contract) {
		List<String> attachUrlList = new ArrayList<>();
		String attachFileType;
		if (contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode())) {
			attachUrlList.add(getContractUrl(contract));
			attachFileType = FileTypeEnum.IMAGE.getKey();
		} else {
			attachUrlList.addAll(getAttachUrl(contract));
			attachFileType = contractBusinessService.getAttachFileKey(attachUrlList);
		}

		return ContractPreviewVo.builder()
			.contractCode(contract.getContractCode())
			.signChannelType(contract.getSignChannelType())
			.contractUrl(getContractUrl(contract))
			.attachUrl(attachUrlList)
			.attachFileType(attachFileType)
			.build();
	}

