	public List<OptionsVo> getBrandListByContractType(Integer contractType, String companyCode) {
		//改换成按照款项查类目有问题，因为类目可能是子类目，不是父类目
		List<OptionsVo> optionsVos = contractApolloConfig.getBrandInfoList(contractType, companyCode).stream()
			.filter(BrandConfigInfo::getIsShow)
			.map(OptionsVo::new)
			.collect(Collectors.toList());
		if (CollectionUtils.isEmpty(optionsVos)) {
			return optionsVos;
		}
		List<String> brandCodes = optionsVos.stream().map(t -> (String) t.getValue()).collect(Collectors.toList());
		List<FrontCategoryDto> frontCategoryDtos = frontCategoryRpc.queryByCateIds(brandCodes);
		if (CollectionUtils.isEmpty(frontCategoryDtos)) {
			if (contractType != null && !ContractTypeEnum.K_PACKAGE_CONTRACT.contains(Byte.valueOf(contractType.toString()))) {
				LOGGER.error("获取供应链前台类目为空，请检查类目配置");
			}
			return optionsVos;
		}
		Map<String, String> categoryIdForNameMap = frontCategoryDtos.stream().collect(Collectors.toMap(FrontCategoryDto::getFrontCategoryId, FrontCategoryDto::getFrontCategoryName));
		for (OptionsVo one : optionsVos) {
			one.setLabel(categoryIdForNameMap.getOrDefault(one.getValue(), one.getLabel()));
		}
		return optionsVos;
	}

