	/**
	 * 获取合同提交之后的状态
	 *
	 * @param contract
	 * @return
	 */
	public Integer getContractSubmitStatus(Contract contract) {
		// 设计合同、设计变更场景：设计费超底时，提交后状态流转到「待提交审核」
		if (designFeeAuditService.isDesignFeeExceedBottomOnSubmit(contract)) {
			return ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode();
		}
		//线上or线下
		if (contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode())) {
			if (contract.getAuditType().equals(AuditTypeEnum.BEFORE_SIGN.getCode())) {
				return ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode();
			} else {
				//签署方式
				if (contract.getUserSignType().equals(UserSignTypeEnum.SIGN.getCode())) {
					return ContractStatusEnum.PENDING_USER_SIGN.getCode();
				} else {
					return ContractStatusEnum.PENDING_USER_CONFIRM.getCode();
				}
			}
		} else {
			//线下
			if (contract.getAuditType().equals(AuditTypeEnum.NONE.getCode())) {
				return ContractStatusEnum.FINISH.getCode();
			} else {
				return ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode();
			}
		}
	}


	@Transactional
	public void undoContract(String contractCode, Long createUserId) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract)) {
			LOGGER.warn("合同撤销失败,未查询到该合同 contractCode:{} createUserId:{}", contractCode, createUserId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同撤销失败，未查询到该合同-[签约]");
		}

		// 先撤销当前主合同关联的授权协议  &&  再撤销当前主合同
		if (StringUtils.isNotBlank(contract.getRelateContractCode())) {
			((HomeAndPcCommonService) AopContext.currentProxy()).unlinkAccreditAndMainContract(contract);
		}
		undoContract(contract, createUserId);

		// 撤销关联合同  && 撤销关联的授权协议
		List<ContractRelation> relationList = contractRelationService.getRelationList(contract.getContractCode());
		for (ContractRelation contractRelation : relationList) {
			try {
				Contract relateContract = contractService.getByContractCode(contractRelation.getRelateContractCode());
				//合并模式下发起的解约协议如果已签署，主合同撤销，解约协议不撤销
				if (ContractTypeEnum.TERMINAL.getCode().equals(relateContract.getType()) && ContractStatusEnum.inEndStatus(relateContract.getStatus())) {
					contractRelationService.deleteRelationByContractCodes(Lists.newArrayList(relateContract.getContractCode()));
					LOGGER.info("合并模式下发起的解约协议已签署，主合同撤销，解约协议不撤销 contractCode:{}", relateContract.getContractCode());
					continue;
				}
				if (StringUtils.isNotBlank(relateContract.getRelateContractCode())) {
					((HomeAndPcCommonService) AopContext.currentProxy()).unlinkAccreditAndMainContract(relateContract);
				}
				if (ContractTypeEnum.AUTH_AGENT.getCode().equals(relateContract.getType())) {
					((HomeAndPcCommonService) AopContext.currentProxy()).undoAuthAgentContract(relateContract);
				} else {
					undoContract(relateContract, createUserId);
				}
			} catch (Exception e) {
				LOGGER.error("合并发起模式同步撤销关联合同发生异常，{}，{}", contractCode, e.getMessage());
			}
		}
	}

	/**
	 * 一个授权协议可能关联多个主合同，如果授权协议关联的多个主合同都撤销，则撤销授权协议，否则仅解除主合同和授权协议的关联关系
	 *
	 * @param mainContract
	 */
	@Transactional
	public void unlinkAccreditAndMainContract(Contract mainContract) {
		List<Contract> mainContractList = contractService.getMainContractListByAccreditContractCode(mainContract.getRelateContractCode());
		mainContractList = mainContractList.stream()
			.filter(item -> ContractStatusEnum.inPositiveStatus.contains(item.getStatus()))
			.collect(Collectors.toList());
		if (CollectionUtils.isEmpty(mainContractList)) {
			return;
		}
		if (mainContractList.size() == 1) {
			Contract relateContract = contractService.getByContractCode(mainContract.getRelateContractCode());
			contractService.updateContractStatus(relateContract.getContractCode(), ContractStatusEnum.CANCEL.getCode());
		}
		// 解除关联关系
		contractService.updateRelatedContractCode(Collections.singletonList(mainContract.getContractCode()), "");
	}

	@Transactional
	public void undoAuthAgentContract(Contract authAgentContract) {
		// 更新合同状态
		contractService.updateContractStatus(authAgentContract.getContractCode(), ContractStatusEnum.CANCEL.getCode());
		// 解除关联关系
		contractRelationService.deleteRelationByContractCodes(Collections.singletonList(authAgentContract.getContractCode()));
	}


	public void undoContract(Contract contract, Long createUserId) {
		Integer status = contract.getStatus();
		//需要正式签署的合同，并且状态已经到已签署，不能撤销(施工图纸合同除外)

		if (UserSignTypeEnum.SIGN.getCode().equals(contract.getUserSignType()) && ContractStatusEnum.FINISH.getCode().equals(status)
			&& !ContractTypeEnum.getSingedCanUndoTypes().contains(contract.getType())
		) {
			LOGGER.warn("合同撤销失败,状态已经到已完成 contractCode:{} createUserId:{}", contract.getContractCode(), createUserId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同撤销失败,该合同已签署-[签约]");
		}
		if (ContractStatusEnum.USER_CONFIRMED.getCode().equals(status)) {
			LOGGER.warn("合同撤销失败,该合同已完成确认 contractCode:{} createUserId:{}", contract.getContractCode(), createUserId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同撤销失败,该合同已确认");
		}
		if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			LOGGER.warn("合同撤销失败,合同为草稿，无需撤销 contractCode:{} createUserId:{}", contract.getContractCode(), createUserId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同为草稿，无需撤销-[签约]");
		}
		if (ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(status) && CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus())) {
			LOGGER.warn("合同撤销失败,该合同已完成确认 contractCode:{} createUserId:{}", contract.getContractCode(), createUserId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同撤销失败,该合同已确认");
		}

		//公对公签约，合同撤销同步删除保存的签署链接
		contractFieldService.deleteByContractCodeAndKeys(contract.getContractCode(), Collections.singletonList("companySignUrl"));
		//首期款&&正签合同需撤销产能预占
		rollBackQuotaByUndoContract(contract);

		//撤回状态并且更新用户状态
		contract.setStatus(ContractStatusEnum.DRAFT.getCode());
		contract.setUserQueryStatus(UserQueryStatusEnum.INVALID.getCode());
		contract.setUserConfirmStatus(CommonEnum.NO.getCode());
		contract.setUserSignStatus(CommonEnum.NO.getCode());
		contract.setModifyUserId(String.valueOf(createUserId));
		contract.setPreviewKey("");
		contract.setUserSignedKey("");
		contract.setBothSignedKey("");
		contract.setRelateContractCode("");
		String userName = getOperatorName(createUserId);
		contract.setModifyUserName(userName);
		contract.setUserQueryStatus(UserQueryStatusEnum.INVALID.getCode());
		contract.setMtime(new Date());
		int updateResult = contractService.updateUnchecked(contract);
		if (updateResult <= 0) {
			LOGGER.warn("合同撤销失败 contractCode:{} createUserId:{}", contract.getContractCode(), createUserId);
			throw new ContractException("合同撤销失败, ContractCode:" + contract.getContractCode());
		}

		if (ContractStatusEnum.AUDITING.getCode().equals(status)) {
			String userSystemCode = contractBusinessService.getUserSystemCode(String.valueOf(createUserId));
			try {
				LOGGER.info("合同撤销 取消bpm审批 bpmNo:{} contractCode:{} createUserId:{}", contract.getBmpNo(), contract.getContractCode(), createUserId);
				bpmService.processCancel(contract.getBmpNo(), userSystemCode);
			} catch (Exception e) {
			}
		}

		//如果解约协议是合并发起的，撤销时需要删除关联关系，避免与退单流程冲突
		if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType())) {
			int deleted = contractRelationService.deleteRelationByContractCodes(Lists.newArrayList(contract.getContractCode()));
			if (deleted > 0) {
				LOGGER.info("合同撤销 删除解约协议关联关系 contractCode:{} createUserId:{}", contract.getContractCode(), createUserId);
			}
		}

		//日志
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.STATUS_CHANGE.getCode(), LogTypeEnum.STATUS_CHANGE.getName(), contract.getStatus().toString(), String.valueOf(createUserId), userName);
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.UNDO_CONTRACT.getCode(), LogTypeEnum.UNDO_CONTRACT.getName(), "", HeaderContext.getContext().getOperatorUcId(), HeaderContext.getContext().getOperatorName());
		eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_RECALL, contract.getContractCode());
		LOGGER.info("合同撤销成功 contractCode:{} createUserId:{}", contract.getContractCode(), createUserId);
	}

	/**
	 * 撤销合同时，回退产能预占
	 */
	private void rollBackQuotaByUndoContract(Contract contract) {
		List<Byte> contractTypeList = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.ADVANCE.getCode());
		if (!contractTypeList.contains(contract.getType())) {
			return;
		}
		quotaCalenderFeignService.rollbackQuota(contract.getProjectOrderId());
		LOGGER.info("产能预占撤销成功 projectOrderId:{}，contractCode:{}，contractType:{}", contract.getProjectOrderId(), contract.getContractCode(), contract.getType());
	}

	/**
	 * @param projectOrderId
	 * @param isDetail       用于兼容历史数据，详情页展示所有套餐
	 * @return
	 */
	public List<Object> getPackageList(String projectOrderId, boolean isDetail) {
		List<Object> result = new LinkedList<>();
		String companyCode = contractBusinessService.getCompanyCode(projectOrderId);
		String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(projectOrderId);
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(convertProjectOrderId);
		List<ComboBaseDTO> packageList;
		if (contractApolloConfig.getComboListInfoQueryUseNew()) {
			ProjectInfo projectInfo = projectInfoService.getByProjectOrderId(convertProjectOrderId);
			Integer organizationMode = processV25 ? OrganizationModeEnum.模式25.getMode() : OrganizationModeEnum.模式20.getMode();
			packageList = atomBudgetRpc.getListCombo(convertProjectOrderId, companyCode, organizationMode, projectInfo.getDecorateType());
		} else {
			Integer organizationMode = processV25 ? OrganizationModeEnum.模式25.getMode() : null;
			//旧版获取套餐列表方法，上线观察几天无问题后可删除
			packageList = oldGetPackageList(companyCode, organizationMode, processV25, convertProjectOrderId);
		}
		for (ComboBaseDTO comboBaseDTO : packageList) {
			Map<String, Object> packageInfo = new HashMap<>();
			packageInfo.put("label", comboBaseDTO.getComboName());
			packageInfo.put("value", comboBaseDTO.getComboCode());
			result.add(packageInfo);
		}

		return result;
	}

	/**
	 * 旧版获取套餐列表方法，上线观察几天无问题后可删除，上线时间：2026-01-21
	 */
	private List<ComboBaseDTO> oldGetPackageList(String companyCode, Integer organizationMode, boolean processV25, String projectOrderId) {
		List<ComboBaseDTO> packageList = quotationFeignService.getPackageList(companyCode, organizationMode);
		//获取订单设计师信息
		ProjectServerInfoDTO designerInfo = baseAuditChannel.queryProjectDesignerInfo(projectOrderId);
		//如果有设计师信息，则需要区分标装和非标装
		if (designerInfo != null) {
			boolean standardProductConsultant = commonBusinessService.isStandardProductConsultant(projectOrderId, processV25, designerInfo.getUcId());
			LOGGER.info("设计师信息 projectOrderId:{} ucId:{} 是否为标装:{}", projectOrderId, designerInfo.getUcId(), standardProductConsultant);
			//如果是标装，则只过滤出标装套餐
			if (standardProductConsultant) {
				packageList = packageList.stream().filter(item -> ObjectUtil.equal(item.getComboCategoryCode(), CommonConstant.标装套餐类别)).collect(Collectors.toList());
			} else {
				//如果是非标装，则过滤出非标装套餐
				packageList = packageList.stream().filter(item -> !ObjectUtil.equal(item.getComboCategoryCode(), CommonConstant.标装套餐类别)).collect(Collectors.toList());
			}
		}
		//获取订单业务类型
		ProjectInfo projectInfo = projectInfoService.getByProjectOrderId(projectOrderId);
		//获取业务类型
		if (ObjectUtil.isNotEmpty(projectInfo)) {
			Byte decorateType = projectInfo.getDecorateType();
			BusinessTypeEnum businessTypeEnum = BusinessTypeEnum.getEnumByDecorateType(CommissionDecorateTypeEnum.getEnumByCode(decorateType));
			packageList = packageList.stream().filter(item -> ObjectUtil.equal(BusinessTypeEnum.getEnumByDecorateType(CommissionDecorateTypeEnum.getEnumByCode(item.getCommissionDecorateType())), businessTypeEnum)).collect(Collectors.toList());
		}
		return packageList;
	}

	public Boolean checkCanCreate(String projectOrderId, Byte contractType, Byte userSignType) {
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		if (Objects.isNull(projectInfoDTO)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少项目订单信息");
		}

		//正签合同校验装修类型是不是【其他】
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			Byte decorateType = projectInfoDTO.getCustomerCommission().getDecorateType();
			if (CommissionDecorateTypeEnum.OTHERS.getCode().equals(decorateType)) {
				throw new NrsBusinessException(ResponseCodeEnum.DECORATE_TYPE_OTHER.getCode(), "装修类型不能为其他");
			}
		}
		String companyCode = projectInfoDTO.getCustomerCommission().getCompanyCode();
		if (Objects.isNull(companyCode)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目上缺少分公司信息");
		}

		//查找人员依赖
		ProjectServerParam param = ProjectServerParam.builder().projectOrderId(Long.valueOf(projectOrderId)).build();
		ResultDTO<List<ProjectServerInfoDTO>> projectOrderResult = projectOrderQueryService.queryProjectServerInfo(param);
		if (!projectOrderResult.isSuccess()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "查询项目人员信息失败");
		}
		if (Objects.isNull(projectOrderResult.getData()) || projectOrderResult.getData().isEmpty()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目人员信息为空，请添加相关信息");
		}

		List<String> userList = projectOrderResult.getData().stream().map(ProjectServerInfoDTO::getType).collect(Collectors.toList());
		List<ContractCityCompanyInfo> config = contractCityCompanyConfigService.getConfig(projectOrderId,
			projectInfoDTO.getCustomerHouse().getGbCode(), companyCode,
			commonContractService.getBusinessType(projectInfoDTO),
			contractType
		);
		if (Objects.isNull(config)) {
			String errorMsg = String.format("城市:%s,分公司:%s缺少合同配置", projectInfoDTO.getCustomerHouse().getGbCode(), companyCode);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, errorMsg);
		}

		Byte businessType = commonContractService.getBusinessType(projectInfoDTO);

		//限制销售项目状态
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			if (!OrderStatusEnum.WAITING_SIGN.getCode().equals(projectInfoDTO.getProjectOrderStatus())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目还没有报价，请先完成报价");
			}
		}

		//简单合同(解约协议/认购/设计) 走统一的方法处理
		List<Byte> normalContractTypeList = Arrays.asList(ContractTypeEnum.SUBSCRIBE.getCode(), ContractTypeEnum.DESIGN.getCode(), ContractTypeEnum.TERMINAL.getCode());
		if (normalContractTypeList.contains(contractType)) {
			BaseContractDto baseContractDto = BaseContractDto.builder()
				.projectOrderId(projectOrderId)
				.type(contractType)
				.userSignType(userSignType)
				.build();
			ContractHandlerInterface contractHandler = contractHandlerFactory.getHandler(baseContractDto);
			return contractHandler.checkCanCreate(baseContractDto);
		}

		if (BusinessTypeEnum.getHouseCertificate25ModeList().contains(businessType) || BusinessTypeEnum.PART_DECORATE.getCode().equals(businessType)) {
			houseCertificateCheck(contractType, userList);
		} else if (commonBusinessService.isPROCESS_V2_0_GROUP(projectOrderId)) {
			groupDecorateCheck(config.get(0), userList);
		}

		return true;
	}

	private List<String> getUserList(String projectOrderId) {
		List<MaintainUserModule.IMaintainerUserDTO> maintainUserList = orderStandardQueryRpc.queryMaintainerUserList(projectOrderId);
		if (CollectionUtils.isEmpty(maintainUserList)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目人员信息为空，请添加相关信息");
		}
		return maintainUserList.stream()
			.map(MaintainUserModule.IMaintainerUserDTO::getMaintainRole)
			.collect(Collectors.toList());
	}


	public Boolean houseCertificateCheck(Byte contractType, List<String> serverList) {
		//仅认购合同不校验设计师
		List<Byte> noCheckDesignerContractType = Collections.singletonList(ContractTypeEnum.SUBSCRIBE.getCode());
		if (!noCheckDesignerContractType.contains(contractType)) {
			if (!serverList.contains(ServerTypeEnum.DESIGNER.getType())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目缺少设计师信息");
			}
		}

		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			if (!serverList.contains(ServerTypeEnum.BUDGETER.getType())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目缺少预算员信息");
			}

			if (!serverList.contains(ServerTypeEnum.GROUP_LEADER.getType())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目缺少经营部经理信息");
			}
		}

		return true;
	}

	public Boolean groupDecorateCheck(ContractCityCompanyInfo config, List<String> serverList) {
		if (!Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PACKAGE_CHANGE.getCode()).contains(config.getContractType().byteValue())) {
			return true;
		}
		//校验角色信息
		List<AuditConfigDTO> auditConfigDTOList = contractCityCompanyInfoService.getAuditConfig(config);
		if (Objects.isNull(auditConfigDTOList) || auditConfigDTOList.isEmpty()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少合同审批人配置");
		}
		for (AuditConfigDTO auditConfigDTO : auditConfigDTOList) {
			if (AuditConfigNodeTypeEnum.ROLE.getCode().equals(auditConfigDTO.getNodeType()) && !serverList.contains(auditConfigDTO.getNodeValue())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少服务者信息：" + auditConfigDTO.getNodeValue());
			}
		}

		return true;
	}

	/**
	 * 删除合同
	 *
	 * @param contractCode
	 * @param ucId
	 * @return
	 */
	@Transactional(rollbackFor = Exception.class)
	public Boolean deleteContract(String contractCode, Long ucId) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract)) {
			return true;
		}
		if (!contract.getStatus().equals(ContractStatusEnum.DRAFT.getCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同不处于起草中，不可删除");
		}
		//获取主合同的关联合同
		List<ContractRelation> relationList = contractRelationService.getRelationList(contractCode);
		List<String> relationContractCodes = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
		if (!CollectionUtils.isEmpty(relationContractCodes)) {
			List<Contract> relationContractList = contractService.getListByContractCodes(relationContractCodes, false);
			//逐个校验，判断关联合同是否也是草稿中，否则不允许删除
			for (Contract relationContract : relationContractList) {
				if (!relationContract.getStatus().equals(ContractStatusEnum.DRAFT.getCode())) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, String.format("关联合同:%s不处于起草中，不可删除", ContractTypeEnum.getEnumByCode(contract.getType()).getName()));
				}
				quotationRelationCommonService.cancelContractRelations(relationContract.getContractCode());
			}
		}
		//删除关联报价单(必须在删除主表之前)
		quotationRelationCommonService.cancelContractRelations(contractCode);
		//删除主表
		List<String> deleteContractCodes = new ArrayList<>();
		deleteContractCodes.add(contractCode);
		deleteContractCodes.addAll(relationContractCodes);
		contractService.deleteSoftByContractCodes(deleteContractCodes);
		//删除日志
		String operatorName = getOperatorName(ucId);
		List<ContractLog> contractLogList = new ArrayList<>();
		for (String deleteContractCode : deleteContractCodes) {
			contractLogList.add(ContractLog.builder()
				.contractCode(deleteContractCode)
				.type(LogTypeEnum.DELETE.getCode())
				.content(LogTypeEnum.DELETE.getName())
				.remark("")
				.delStatus(CommonEnum.NO.getCode())
				.createUserId(ucId.toString())
				.createUserName(operatorName)
				.ctime(new Date())
				.mtime(new Date())
				.modifyUserId(ucId.toString())
				.modifyUserName(operatorName)
				.build());
		}
		contractLogService.insertBatch(contractLogList);
		return true;
	}


