	/**
	 * C 端获取线上合同url信息(如果有关联合同则一并获取)：
	 */
	public List<ContractOnlineVo> getContractOnlineUrlForC(Contract contract, List<Byte> contractTypeList) {
		List<ContractOnlineVo> contractOnlineUrl = getContractOnlineUrl(contract, contractTypeList);
		List<Integer> auditingStatus = Arrays.asList(ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode(), ContractStatusEnum.AUDITING.getCode());
		// 关联的补充协议，如果审核未通过，C 端不展示
		contractOnlineUrl.removeIf(contractVo ->
			ContractTypeEnum.SUPPLEMENT.getCode().equals(contractVo.getContractType()) && auditingStatus.contains(contractVo.getStatus())
		);
		return contractOnlineUrl;
	}


	/**
	 * 获取线上合同url信息(如果有关联合同则一并获取)
	 */
	public List<ContractOnlineVo> getContractOnlineUrl(Contract contract, List<Byte> contractTypeList) {
		if (contract.getSignChannelType().equals(SignChannelTypeEnum.OFFLINE.getCode()) || !ContractStatusEnum.inPositiveStatus.contains(contract.getStatus())) {
			return new ArrayList<>();
		}
		//单独发起的销售合同
		if(isMultipleQuotePersonalContract(contract)){
			//获取关联合同code，从redis缓存中
			List<Contract> togetherLaunchPersonalContracts = contractBusinessService.getTogetherLaunchPersonalContract(contract);
			List<ContractOnlineVo> result = new ArrayList<>();
			togetherLaunchPersonalContracts.forEach(c -> {
				String contractUrl = getContractUrl(c);
				ContractOnlineVo build = ContractOnlineVo.builder()
						.contractType(c.getType())
						.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(c.getType(), c.getBusinessType()))
						.shortName(ContractTypeEnum.getShortName(c.getType()))
						.contractCode(c.getContractCode())
						.pdfPageCount(c.getPdfPageCount())
						.contractUrl(contractUrl)
						.status(c.getStatus())
						.build();
				result.add(build);
			});
			return result;
		}
		List<ContractOnlineVo> result = new ArrayList<>();
		List<Contract> reContractList = getRelateContract(contract, contractTypeList);
		// 获取正签合同
		Contract zqContract = reContractList.stream()
			.filter(c -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(c.getType()))
			.findFirst().orElse(null);
		String projectOrderId = contract.getProjectOrderId();
		if (ObjectUtil.isNotEmpty(zqContract)) {
			projectOrderId = zqContract.getProjectOrderId();
		}
		for (Contract contractTemp : reContractList) {
			String contractUrl = getContractUrl(contractTemp);
			ContractOnlineVo build = ContractOnlineVo.builder()
				.contractType(contractTemp.getType())
				.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contractTemp.getType(), contractTemp.getBusinessType()))
				.shortName(ContractTypeEnum.getShortName(contractTemp.getType()))
				.contractCode(contractTemp.getContractCode())
				.pdfPageCount(contractTemp.getPdfPageCount())
				.contractUrl(contractUrl)
				.status(contractTemp.getStatus())
				.build();
			if (ContractTypeEnum.TERMINAL.getCode().equals(contractTemp.getType()) && !projectOrderId.equals(contractTemp.getProjectOrderId())) {
				build.setContractName("原服务解约协议");
				build.setShortName("原服务解约协议");
			}
			result.add(build);
		}
		return result;
	}

	/**
	 * 获取关联合同（包括自己），使用contractTypeList排序合同
	 */
	public List<Contract> getRelateContract(Contract contract, List<Byte> contractTypeList) {
		List<ContractRelation> relationList = contractRelationService.getRelationList(contract.getContractCode());
		List<Contract> relateContractList = contractService.getListByContractCodes(relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList()), false);
		if (CollectionUtils.isNotEmpty(relateContractList)) {
			relateContractList.add(contract);
			// 按照指定顺序排序
			relateContractList = relateContractList.stream().sorted(Comparator.comparingInt(o -> contractTypeList.indexOf(o.getType()))).collect(Collectors.toList());
			return relateContractList;
		}

		ContractRelation byRelateContractCode = contractRelationService.getByRelateContractCode(contract.getContractCode());
		if (ObjectUtil.isEmpty(byRelateContractCode)) {
			return new ArrayList<>();
		}
		List<ContractRelation> byRelationList = contractRelationService.getRelationList(byRelateContractCode.getContractCode());
		if (CollectionUtils.isEmpty(byRelationList)) {
			return new ArrayList<>();
		} else {
			Contract zqContract = contractService.getByContractCode(byRelateContractCode.getContractCode());
			List<Contract> listByContractCodes = contractService.getListByContractCodes(byRelationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList()), false);
			listByContractCodes.add(zqContract);
			// 按照指定顺序排序
			listByContractCodes = listByContractCodes.stream().sorted(Comparator.comparingInt(o -> contractTypeList.indexOf(o.getType()))).collect(Collectors.toList());
			return listByContractCodes;
		}
	}

	/**
	 * 获取所有跟自己有关系的合同：关联的其他合同、被关联的合同、自己
	 *
	 * @param contract
	 * @param contractTypeList
	 * @return
	 */
	public List<Contract> getAllRelateContract(Contract contract, List<Byte> contractTypeList) {
		//关联的其他合同
		List<ContractRelation> relationList = contractRelationService.getRelationList(contract.getContractCode());
		//获取主合同
		ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
		if (ObjectUtil.isEmpty(contractRelation) && CollectionUtil.isEmpty(relationList)) {
			// 不存在关联关系，不返回
			return new ArrayList<>();
		}
		List<String> allRelateContractCodes = new ArrayList<>();
		if (CollectionUtil.isEmpty(relationList)) {
			//被关联合同场景
			relationList = contractRelationService.getRelationList(contractRelation.getContractCode());
		}
		allRelateContractCodes = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
		allRelateContractCodes.add(ObjectUtil.isEmpty(contractRelation) ? contract.getContractCode() : contractRelation.getContractCode());
		List<Contract> relateContractList = contractService.getListByContractCodes(allRelateContractCodes, false);
		if (CollectionUtils.isEmpty(relateContractList)) {
			return new ArrayList<>();
		} else {
			// 按照指定顺序排序
			relateContractList = relateContractList.stream().sorted(Comparator.comparingInt(o -> contractTypeList.indexOf(o.getType()))).collect(Collectors.toList());
			return relateContractList;
		}
	}

	/**
	 * 获取关联合同
