	public Contract getRelateContractByType(Contract contract, Byte contractType) {
		//关联的其他合同
		List<ContractRelation> relationList = contractRelationService.getRelationList(contract.getContractCode());
		List<String> allRelateContractCodes = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
