	/**
	 * 获取线下合同url信息(如果有关联合同则一并获取)
	 */
	public List<ContractOfflineVo> getContractOfflineUrl(Contract contract, List<Byte> contractTypeList) {
		if (contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode()) || !ContractStatusEnum.inPositiveStatus.contains(contract.getStatus())) {
			return new ArrayList<>();
		}
		List<ContractOfflineVo> result = new ArrayList<>();
		//单独发起的销售合同
		if(isMultipleQuotePersonalContract(contract)){
			//获取关联合同code，从redis缓存中
			List<Contract> togetherLaunchPersonalContracts = contractBusinessService.getTogetherLaunchPersonalContract(contract);
			togetherLaunchPersonalContracts.forEach(c -> {
				List<String> attachUrl = getAttachUrl(c);
				ContractOfflineVo build = ContractOfflineVo.builder()
					.contractType(c.getType())
					.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(c.getType(), c.getBusinessType()))
					.contractCode(c.getContractCode())
					.shortName(ContractTypeEnum.getShortName(c.getType()))
					.attachUrl(attachUrl)
					.status(c.getStatus())
					.attachFileType(contractBusinessService.getAttachFileKey(attachUrl))
					.build();
				result.add(build);
			});
			return result;
		}
		List<Contract> reContractList = getRelateContract(contract, contractTypeList);
		// 获取正签合同
		Contract zqContract = reContractList.stream()
			.filter(c -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(c.getType()))
			.findFirst().orElse(null);
		String projectOrderId = contract.getProjectOrderId();
		if (ObjectUtil.isNotEmpty(zqContract)) {
			projectOrderId = zqContract.getProjectOrderId();
		}
		for (Contract contractTemp : reContractList) {
			List<String> attachUrl = getAttachUrl(contractTemp);
			ContractOfflineVo build = ContractOfflineVo.builder()
				.contractType(contractTemp.getType())
				.contractCode(contractTemp.getContractCode())
				.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contractTemp.getType(), contractTemp.getBusinessType()))
				.shortName(ContractTypeEnum.getShortName(contractTemp.getType()))
				.attachUrl(attachUrl)
				.status(contractTemp.getStatus())
				.attachFileType(contractBusinessService.getAttachFileKey(attachUrl))
				.build();
			if (ContractTypeEnum.TERMINAL.getCode().equals(contractTemp.getType()) && !projectOrderId.equals(contractTemp.getProjectOrderId())) {
				build.setContractName("原服务解约协议");
				build.setShortName("原服务解约协议");
			}
			result.add(build);
		}
		return result;
	}


	/**
	 * 获取个性化首期款金额
	 */
	public PersonalAdvanceAmountResDTO getPersonalAdvanceAmount(PersonalAdvanceAmountReqDTO req) {
		Integer fundType = FundRelateContractMapping.obtainFundTypeByContractType(req.getContractType());
		FundInfo fundInfo = fundService.getFundByOrderIdAndFundType(req.getProjectOrderId(), fundType);

		BigDecimal paidAmount = fundInfo == null ? BigDecimal.ZERO : fundInfo.getPaidAmount();
		BigDecimal quoteTotalAmount = BigDecimal.ZERO;
		BigDecimal dueAmount = BigDecimal.ZERO;
		Byte contractType = req.getContractType();
		List<BrandDTO> brandList = Optional.ofNullable(req.getBrandList()).orElse(new ArrayList<>());
		handleBrand(brandList, contractType);
		//计算总金额
		for (BrandDTO brandInfo : brandList) {
			BigDecimal quoteAmount = Optional.ofNullable(brandInfo.getQuoteAmount()).orElse(BigDecimal.ZERO);
			BigDecimal singleDueAmount = Optional.ofNullable(brandInfo.getDueAmount()).orElse(BigDecimal.ZERO);
			quoteTotalAmount = quoteTotalAmount.add(quoteAmount);
			dueAmount = dueAmount.add(singleDueAmount);
		}
		return PersonalAdvanceAmountResDTO.builder()
			.quoteTotalAmount(AmountUtil.getShowAmount(quoteTotalAmount))
			.dueTotalAmount(AmountUtil.getShowAmount(dueAmount))
			.paidAmount(AmountUtil.getShowAmount(paidAmount))
			.tobePaidAmount(AmountUtil.getShowAmount(dueAmount.subtract(paidAmount)))
			.brandList(brandList)
			.build();
	}

	private void handleBrand(List<BrandDTO> brandList, Byte contractType) {
		if (!ContractTypeEnum.K_PACKAGE_CONTRACT.contains(contractType)) {
			return;
		}
		for (BrandDTO brandInfo : brandList) {
			if (StringUtils.isBlank(brandInfo.getBrandCode())) {
				continue;
			}
			BigDecimal comboPrice = quotationFeignService.getComboPrice(Long.valueOf(brandInfo.getBrandCode()));
			brandInfo.setDueAmount(comboPrice);
			brandInfo.setQuoteAmount(comboPrice);
		}
	}

	/**
	 * 判断合同是否为协同报价发起的个性化合同
	 */
	public boolean isMultipleQuotePersonalContract(Contract contract) {
		if (contract == null) {
			return false;
		}
		if (!ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			return false;
		}
		//获取合同的关联合同
		ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
		//变更单号为空且关联合同为空则为单独发起C合同
		return ObjectUtil.isEmpty(contractRelation);
	}

	/**
	 * 判断合同是否为合并发起的个性化合同
	 */
	public boolean isMergeQuotePersonalContract(Contract contract) {
		if (contract == null) {
			return false;
		}
		if (!ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			return false;
		}
		//获取合同的关联合同
		ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
		//变更单号为空且关联合同不为空则为合并发起C合同
		return ObjectUtil.isEmpty(contract.getChangeOrderId()) && ObjectUtil.isNotEmpty(contractRelation);
	}

	/**
	 * 判断是否法定代表人待授权认证
	 */
	public Boolean isWaitAuth(Contract contract) {
		// 线上签约 && 正式签署
		boolean waitSign = SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType()) && ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus());
		if (!waitSign) {
			return false;
		}

		// 公对公签署
		Byte contractObjectType = contractFieldService.getContractObjectType(contract.getContractCode());
		if (!ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
			return false;
		}

		// 获取授权协议书签署状态
		String relateContractCode = contract.getRelateContractCode();
		if (org.apache.commons.lang3.StringUtils.isBlank(relateContractCode)) {
			return false;
		}
		Contract relateContract = contractService.getByContractCode(relateContractCode);

		// 关联合同属于授权协议书，并且状态待签署返回待授权认证
		return relateContract != null && ContractTypeEnum.ACCREDIT.getCode().equals(relateContract.getType()) && ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(relateContract.getStatus());
	}

	/**
	 * 获取授权认证状态
	 *
	 * @param accreditContractCode
	 * @return
	 */
	public Integer getAuthStatus(String accreditContractCode) {
		// 获取授权协议书签署状态
		if (StringUtils.isBlank(accreditContractCode)) {
			return ContractAuthStatusEnum.NO_NEED_AUTHENTICATED.getCode();
		}
		Contract accreditContract = contractService.getByContractCode(accreditContractCode);
		if (accreditContract == null || !ContractTypeEnum.ACCREDIT.getCode().equals(accreditContract.getType())) {
			return ContractAuthStatusEnum.NO_NEED_AUTHENTICATED.getCode();
		}
		//认证状态
		ContractUser legalUser = contractUserService.getLatestUserByRole(accreditContract.getContractCode(), RoleTypeEnum.LEGAL.getCode());
		if (legalUser == null) {
			LOGGER.error("授权协议无法人信息，无法获取认证状态，对应授权协议{}", accreditContract.getContractCode());
			return ContractAuthStatusEnum.NO_NEED_AUTHENTICATED.getCode();
		}
		ContractField creditCodeField = contractFieldService.getByContractCodeAndKey(accreditContract.getContractCode(), "companyCreditCode");
		if (creditCodeField == null || StringUtils.isBlank(creditCodeField.getFieldValue())) {
			LOGGER.error("授权协议无统一社会信用代码，无法获取认证状态，对应授权协议{}", accreditContract.getContractCode());
			return ContractAuthStatusEnum.NO_NEED_AUTHENTICATED.getCode();
		}
		//认证状态
		List<String> cipherTextList = Stream.of(legalUser.getCertificateNo()).collect(Collectors.toList());
		Map<String, String> plainTextMap = cipherService.decrypt(cipherTextList);
		Boolean authenticationStatus = freeformService.getCompanyAuthenticationRes(plainTextMap.get(legalUser.getCertificateNo()), creditCodeField.getFieldValue());
		//授权状态
		Boolean authorizationStatus = ContractStatusEnum.SIGNED_STATUS_LIST.contains(accreditContract.getStatus());
		//组合认证授权状态
		return ContractAuthStatusEnum.getAuthStatus(authenticationStatus, authorizationStatus);
	}

	/**
	 * 获取合同列表标签信息
	 */
	@Deprecated
	public List<ContractListVo.ContractListItemInfo> getContractInfoText(Contract contract, List<Contract> contractList) {
		List<ContractListVo.ContractListItemInfo> infoText = new ArrayList<>();
		// 下发展示授权协议书授权状态
		Contract drawingContract = contractList.stream().filter(c -> ContractTypeEnum.DRAWING.getCode().equals(c.getType())).findAny().orElse(null);
		boolean showAuthStatus = ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus());
		if (showAuthStatus) {
			String contractName = ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType());
			Contract accreditContract = contractList.stream().filter(c -> ContractTypeEnum.ACCREDIT.getCode().equals(c.getType()) && contract.getRelateContractCode().equals(c.getContractCode())).findFirst().orElse(null);
			// 处理正式套餐及图纸需要展示两个合同的授权状态
			String keyName = drawingContract != null && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType()) ? contractName + "授权状态" : "授权状态";
			ContractListVo.ContractListItemInfo contractAuthStatusInfo = getContractListItemAuthInfo(accreditContract, contract, contractList, keyName);
			if (contractAuthStatusInfo != null) {
				infoText.add(contractAuthStatusInfo);
			}

			if (drawingContract != null && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
				Contract drawingAccreditContract = contractList.stream().filter(c -> ContractTypeEnum.ACCREDIT.getCode().equals(c.getType()) && drawingContract.getRelateContractCode().equals(c.getContractCode())).findFirst().orElse(null);
				ContractListVo.ContractListItemInfo drawingAuthStatusInfo = getContractListItemAuthInfo(drawingAccreditContract, contract, contractList, ContractTypeEnum.DRAWING.getName() + "授权状态");
				if (drawingAuthStatusInfo != null) {
					infoText.add(drawingAuthStatusInfo);
				}
			}
		}

		return infoText;
	}

	@Deprecated
	private ContractListVo.ContractListItemInfo getContractListItemAuthInfo(Contract accreditContract, Contract contract, List<Contract> contractList, String keyName) {
		if (accreditContract == null) {
			return null;
		}

		if (ContractStatusEnum.inEndStatus(accreditContract.getStatus())) {
			// 存在授权节点，展示授权状态
			return new ContractListVo.ContractListItemInfo("auth", keyName, "已授权");
		} else if (org.apache.commons.lang3.StringUtils.isNotBlank(contract.getRelateContractCode()) &&
			contractList.stream().anyMatch(c -> contract.getRelateContractCode().equals(c.getContractCode()))) {
			// 不存在授权节点，并且有关联合同，关联合同是授权协议书则展示未授权状态
			return new ContractListVo.ContractListItemInfo("auth", keyName, "未授权");
		}

		return null;
	}


