public Map<String, List<OptionsVo>> getStandardOptionsBatch(List<String> dictKeys, @Nullable Integer contractType, String companyCode, boolean attachOcrOpenCity) {
	Map<String, List<OptionsVo>> map = new HashMap<>();
	for (String key : dictKeys) {
		switch (key) {
			case "personRoleType":
				map.put(key, Arrays.stream(PersonRoleTypeEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "commonYesOrNo":
				map.put(key, Arrays.stream(CommonYesOrNoEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "haveAgent":
				if (attachOcrOpenCity) {
					map.put(key, Arrays.stream(HaveAgentEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				} else {
					List<OptionsVo> optionsVos = new ArrayList<>();
					for (HaveAgentEnum haveAgentEnum : HaveAgentEnum.values()) {
						OptionsVo optionsVo = new OptionsVo(haveAgentEnum);
						if (haveAgentEnum.getCode().equals(HaveAgentEnum.YES.getCode())) {
							optionsVo.setLabel("有");
						} else if (haveAgentEnum.getCode().equals(HaveAgentEnum.NO.getCode())) {
							optionsVo.setLabel("无");
						}
						optionsVos.add(optionsVo);
					}
					map.put(key, optionsVos);
				}
				break;
			case "certificateType":
				map.put(key, Arrays.stream(CertificateTypeEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "houseType":
				map.put(key, Arrays.stream(HouseTypeEnum.values()).filter(houseTypeEnum -> !houseTypeEnum.getCode().equals(0)).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "houseBuildType":
				map.put(key, getHouseBuildTypeOptions().stream().filter(houseBuildTypeEnum -> !houseBuildTypeEnum.getCode().equals(0)).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "structure":
				map.put(key, Arrays.stream(StructureEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "designServiceCustomStatus":
				map.put(key, Arrays.stream(DesignServiceCustomStatusEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "designerLevel":
			case "designerLevelName":
				map.put(key, Arrays.stream(DesignerLevelEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "projectContractMode":
				map.put(key, ProjectContractModeEnum.getOrderEnumList().stream().map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "disputeDealMode":
				map.put(key, Arrays.stream(DisputeDealModeEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "waterProofGuaranteeYearEnum":
				map.put(key, Arrays.stream(WaterProofGuaranteeYearEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "totalDuration":
				map.put(key, Arrays.stream(TotalDurationEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "beforeDeliveryDaysToWork":
				map.put(key, Arrays.stream(BeforeDeliveryDaysToWorkEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "otherGuaranteeYearEnum":
				map.put(key, Arrays.stream(OtherGuaranteeYearEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "materialType":
				map.put(key, contractApolloConfig.getStringMaterialTypes());
				break;
			case "contractObjectType":
				map.put(key, Arrays.stream(ContractObjectTypeEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "signChannelType":
				map.put(key, Arrays.stream(SignChannelTypeEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "userSignType":
				map.put(key, Arrays.stream(UserSignTypeEnum.values()).filter(userSignTypeEnum -> userSignTypeEnum.getCode() != 0).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "contractObjectChange":
				map.put(key, Arrays.stream(ContractObjectChangeEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "fileType":
				map.put(key, FileTypeEnum.getFileTypeList().stream().map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "constructionDrawMode":
				map.put(key, Arrays.stream(ConstructionDrawModeEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "brandList":
				map.put(key, getBrandListByContractType(contractType, companyCode));
				break;
			case "signRole":
				map.put(key, Arrays.stream(RoleTypeEnum.values())
					.filter(roleTypeEnum -> RoleTypeEnum.COMPANY_AGENT.equals(roleTypeEnum) || RoleTypeEnum.LEGAL.equals(roleTypeEnum))
					.sorted(Comparator.comparing(RoleTypeEnum::getCode).reversed())
					.map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "legalCertificateType":
				// 法人证件类型只能使用身份证
				map.put(key, Arrays.stream(CertificateTypeEnum.values())
					.map(certificateTypeEnum -> {
						OptionsVo optionsVo = new OptionsVo(certificateTypeEnum);
						if (!CertificateTypeEnum.ID.equals(certificateTypeEnum)) {
							optionsVo.setDisabled(true);
						}
						return optionsVo;
					}).collect(Collectors.toList()));
				break;
			case "haveHouseProve":
				if (attachOcrOpenCity) {
					if (Boolean.TRUE.equals(contractApolloConfig.getSpecialHouseEnabled())) {
						map.put(key, HaveHouseProveEnum.getAllAttachOpenList().stream().map(OptionsVo::new).collect(Collectors.toList()));
					} else {
						map.put(key, HaveHouseProveEnum.getAttachOpenList().stream().map(OptionsVo::new).collect(Collectors.toList()));
					}
				} else {
					List<OptionsVo> optionsVoList = HaveHouseProveEnum.getHistoryList().stream().map(OptionsVo::new).collect(Collectors.toList());
					for (OptionsVo optionsVo : optionsVoList) {
						if (HaveHouseProveEnum.NO.getCode().equals(optionsVo.getValue())) {
							optionsVo.setDisabled(true);
						}
					}
					map.put(key, optionsVoList);
				}
				break;
			case "entrustSignType":
				map.put(key, Arrays.stream(EntrustSignTypeEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "launchSupplementType":
				map.put(key, Arrays.stream(LaunchSupplementTypeEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			case "supplementItemType":
				map.put(key, Arrays.stream(SupplementItemTypeEnum.values()).map(OptionsVo::new).collect(Collectors.toList()));
				break;
			default:
				break;
		}
	}
	return map;
}

