	if (CollectionUtils.isEmpty(contractList)) {
		return;
	}
	LOGGER.info("check unique result:{},{}", contractList.size(), JsonUtil.toJsonString(contractList));

	if (contractList.size() > 1) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "已有多分其他在途合同,不可重复创建-[签约]");
