	}
}

public ComboPriceInfo getExpectContractAmount(String projectOrderId, String comboCode, Integer houseType, String area, String valuationArea, BigDecimal advanceRate) {
	if (StringUtils.isNotBlank(projectOrderId)) {
		Integer expectAmountUseAreaType = commonContractService.getExpectAmountUseAreaType(projectOrderId);
		if (AreaEnum.VALUATION_AREA.getAreaType().equals(expectAmountUseAreaType)) {
			area = valuationArea;
		}
	}
	if (comboCode == null || StringUtils.isBlank(area)) {
		return null;
	}
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
	if (projectInfoDTO == null) {
		return null;
	}
	if (CityEnum.BEIJING.getGbCode() == projectInfoDTO.getCustomerHouse().getGbCode() && houseType == null) {
		return null; // 查询套餐时北京的houseType不能为空
	}
	BigDecimal calcExpectContractAmount;
	BigDecimal minDiscountAmount;
	BigDecimal advanceToBAmount;
	Integer purchaseType;
	try {
		ComboPriceDTO comboPriceDTO = atomBudgetRpc.calcExpectContractAmount(comboCode, houseType, area);
		if (comboPriceDTO == null || comboPriceDTO.getComboBaseTotalAmountWithManageFeeAfterDiscount() == null || comboPriceDTO.getComboBaseTotalAmountWithManageFeeAfterDiscount().compareTo(BigDecimal.ZERO) <= 0 || comboPriceDTO.getComboBaseTotalAmountAfterManageFee() == null) {
			LOGGER.info("查询预估合同金额异常：返回：{},套餐code：{}，房屋类型：{},建筑面积：{}", JSON.toJSONString(comboPriceDTO), comboCode, houseType, area);
			throw new NrsBusinessException("套餐缺少配置，请联系报价工作人员");
		}
		// toC 字段计算：comboBaseTotalAmountAfterManageFee - comboBaseTotalAmountToB
		BigDecimal toBAmount = comboPriceDTO.getComboBaseTotalAmountToB() != null ? comboPriceDTO.getComboBaseTotalAmountToB() : BigDecimal.ZERO;
		BigDecimal toCAmount = comboPriceDTO.getComboBaseTotalAmountAfterManageFee().subtract(toBAmount);
		if (toCAmount.compareTo(BigDecimal.ZERO) < 0) {
			LOGGER.info("开发商赠送金额超过硬装报价单总额，projectOrderId:{}, comboCode:{}, toBAmount:{}, comboBaseTotalAmountAfterManageFee:{}, toCAmount:{}", projectOrderId, comboCode, toBAmount, comboPriceDTO.getComboBaseTotalAmountAfterManageFee(), toCAmount);
			throw new NrsBusinessException(String.format("开发商赠送金额（¥%s）超过硬装报价单总额（¥%s），请反馈产品研发套餐配置计价规则是否存在问题", toBAmount.toPlainString(), comboPriceDTO.getComboBaseTotalAmountAfterManageFee().toPlainString()));
		}
		LOGGER.info("查询预估合同金额：projectOrderId:{}, comboCode:{}, houseType:{}, area:{}, comboBaseTotalAmountAfterManageFee:{}, comboBaseTotalAmountToB:{}, toCAmount:{}, comboBaseTotalAmountWithManageFeeAfterDiscount:{}",
			projectOrderId, comboCode, houseType, area,
			comboPriceDTO.getComboBaseTotalAmountAfterManageFee(), comboPriceDTO.getComboBaseTotalAmountToB(),
			toCAmount, comboPriceDTO.getComboBaseTotalAmountWithManageFeeAfterDiscount());
		calcExpectContractAmount = toCAmount;
		minDiscountAmount = comboPriceDTO.getComboBaseTotalAmountWithManageFeeAfterDiscount().subtract(toBAmount);
		advanceToBAmount = toBAmount;
		purchaseType = comboPriceDTO.getPurchaseType();

	} catch (Exception e) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_INVOKE.getCode(), "套餐缺少配置，请联系报价工作人员", Level.WARN);
	}


	return ComboPriceInfo.builder()
		.expectContractAmount(calcExpectContractAmount)
		.minDiscountAmount(minDiscountAmount)
		.minAdvanceAmount(calcExpectContractAmount.multiply(advanceRate != null ? advanceRate : new BigDecimal("0.2")).setScale(2, RoundingMode.UP))
		.advanceToBAmount(advanceToBAmount)
		.purchaseType(purchaseType)
		.build();
}

