public BigDecimal calculateAmount(BigDecimal amount, BigDecimal rate) {
	if (amount == null || rate == null) {
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "参数不能为空", Level.WARN);
	}
	if (amount.compareTo(BigDecimal.ZERO) < 0 || rate.compareTo(BigDecimal.ZERO) < 0 || rate.compareTo(BigDecimal.ONE) > 0) {
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "金额不能小于0， 0<=比例<=1", Level.WARN);
	}
	return amount.multiply(rate).setScale(2, RoundingMode.UP);
}

public boolean havePersonalQuote(String projectOrderId, boolean havePersonalQuote) {
	// 已存在非草稿态且是有效状态C合同 正签合同不返回个性化报价
	List<Contract> contractList = contractService.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode());
	Contract personalContract = contractList.stream().filter(item -> ContractStatusEnum.validStatusWithoutDraft.contains(item.getStatus())).filter(m -> StringUtils.isBlank(m.getChangeOrderId()) && !isMultipleQuotePersonalContract(m)).findFirst().orElse(null);
	if (personalContract != null) {
		//存在合并发的C合同
		return true;
	}
	//团装2.5不存在先C后B场景
	return havePersonalQuote;
}

public QuotationInfoDTO getQuotationInfoByProjectOrderId(String projectOrderId) {
	if (StringUtils.isBlank(projectOrderId)) {
		//零售项目不需要，无需返回
		return QuotationInfoDTO.builder().build();
	}
	QuotationInfoDTO quotationInfoDTO = new QuotationInfoDTO();
	//获取项目信息
	CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectOrderId);
	if (coordinationProjectOrder == null || !coordinationProjectOrder.hasDecorateProjectOrder()) {
		return quotationInfoDTO;
	}
	BillInfo billInfo = commonContractService.getBillCodeAndHavePersonalQuote(projectOrderId);
	quotationInfoDTO.setBillCode(billInfo.getBillCode());
	// 是否包含合并发起的C合同/需要合并发起C合同
	quotationInfoDTO.setNeedMergePersonalContract(havePersonalQuote(projectOrderId, billInfo));
	MiniPayChannelAppNameEnum miniProgramType = commonBusinessService.getMiniProgramType(projectOrderId);
	quotationInfoDTO.setMergeDesignContract(contractUnifyService.designFeeFromQuote(projectOrderId) && billInfo.isHaveDesignQuote() && MiniPayChannelAppNameEnum.被窝.equals(miniProgramType));
	// 是否需要同步发起关联订单团装解约协议
	quotationInfoDTO.setNeedLaunchRelationTerminalContract(contractBusinessService.needLaunchOrLaunchedTerminalContract(projectOrderId));
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(coordinationProjectOrder.getDecorateProjectOrder().getProjectOrderId());
	Byte businessType = commonContractService.getBusinessType(projectInfoDTO);
	// 文案下发
	quotationInfoDTO.setRelationTerminalContractText(BusinessTypeEnum.getTerminalTipByBusinessType(businessType));
	return quotationInfoDTO;
}

public QuotationInfoDTO getQuotationInfoByBillCode(String projectOrderId, String billCode) {
	if (StringUtils.isBlank(projectOrderId) || StringUtils.isBlank(billCode)) {
		//零售项目不需要，无需返回
		return QuotationInfoDTO.builder().build();
	}
	QuotationInfoDTO quotationInfoDTO = new QuotationInfoDTO();
	//获取项目信息
	CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectOrderId);
	if (coordinationProjectOrder == null || !coordinationProjectOrder.hasDecorateProjectOrder()) {
		return quotationInfoDTO;
	}
	List<HomeOrderAttachmentEntity> personOrderAttachmentList = homeOrderOperationCheckService.queryOrderAttachmentByBizCode(billCode).stream().filter(item -> Integer.valueOf(item.getAttachmentType()).equals(PlanAttachment.套外个性化报价单)).collect(Collectors.toList());
	boolean havePersonalQuote = CollectionUtil.isNotEmpty(personOrderAttachmentList);
	quotationInfoDTO.setNeedMergePersonalContract(havePersonalQuote(projectOrderId, havePersonalQuote));
	quotationInfoDTO.setBillCode(billCode);
	return quotationInfoDTO;
}

public void reportContractSignAddress(ContractLocationReqDTO contractLocationReqDTO) {
	/**
	 * 1、构建地址参数并上报
	 */
	if (ObjectUtil.isEmpty(contractLocationReqDTO) || StringUtils.isBlank(contractLocationReqDTO.getContractCode())) {
		throw new NrsBusinessException("合同地址上报参数缺失", Level.WARN);
	}
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(contractLocationReqDTO.getProjectOrderId());
	if (ObjectUtil.isEmpty(projectInfoDTO) || ObjectUtil.isEmpty(projectInfoDTO.getCustomerHouse()) || ObjectUtil.isEmpty(projectInfoDTO.getCustomerHouse().getGbCode())) {
		throw new NrsBusinessException(String.format("项目信息不存在, projectOrderId:%s", contractLocationReqDTO.getProjectOrderId()), Level.ERROR);
	}
	Byte businessType = commonContractService.getBusinessType(projectInfoDTO);
	if (!ContractTypeEnum.getContractSignAddressList().contains(contractLocationReqDTO.getContractType()) || BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
		return;
	}
	List<ContractLocation> contractLocationList = new ArrayList<>();
	for (SignStoreTypeEnum signStoreTypeEnum : SignStoreTypeEnum.values()) {
		ContractLocation contractLocation = ContractLocation.builder()
			.contractCode(contractLocationReqDTO.getContractCode())
			.projectOrderId(contractLocationReqDTO.getProjectOrderId())
			.contractType(contractLocationReqDTO.getContractType())
			.sourceType(contractLocationReqDTO.getSourceType())
			.gbCode(projectInfoDTO.getCustomerHouse().getGbCode())
			.notLocationType(contractLocationReqDTO.getLocationFlag() ? LocationFailReasonEnum.LOCATION.getValue() : ObjectUtil.isEmpty(contractLocationReqDTO.getFailReasonType()) ? LocationFailReasonEnum.UNKNOWN_ERROR.getValue() : contractLocationReqDTO.getFailReasonType())
			.latitude(ObjectUtil.isEmpty(contractLocationReqDTO.getLatitude()) ? BigDecimal.ZERO : new BigDecimal(contractLocationReqDTO.getLatitude().trim()))
			.longitude(ObjectUtil.isEmpty(contractLocationReqDTO.getLongitude()) ? BigDecimal.ZERO : new BigDecimal(contractLocationReqDTO.getLongitude().trim()))
			.recordTime(new Date())
			.distance(BigDecimal.ZERO)
			.storeId("")
			.storeName("")
			.ctime(new Date())
			.mtime(new Date())
			.delStatus((byte) 0)
			.recordType(contractLocationReqDTO.getLocationFlag() ? LocationRecordTypeEnum.DEFAULT.getValue() : LocationRecordTypeEnum.NO_LOCATION.getValue())
			.storeType(signStoreTypeEnum.getValue())
			.build();
		contractLocationList.add(contractLocation);
	}
	contractLocationService.insertBatch(contractLocationList);
	/**
	 * 2.异步进行数据计算补充，执行异常需打印error日志
	 */
	String operatorUcId = HeaderContext.getContext().getOperatorUcId();
	CompletableFuture.runAsync(RunnableWrapper.of(() -> {
		try {
			//计算地址距离并补充数据
			calculateDistanceAndReport(contractLocationList, contractLocationReqDTO, projectInfoDTO.getCustomerHouse().getGbCode(), operatorUcId);
		} catch (Exception e) {
			LOGGER.error("计算地址距离异常", e);
		}
	}));
}

public void calculateDistanceAndReport(List<ContractLocation> contractLocationList, ContractLocationReqDTO contractLocationReqDTO, Integer orderGbCode, String operatorUcId) {
	if (CollectionUtil.isEmpty(contractLocationList)) {
		return;
	}
	// 获取城市code
	Integer gbCode = CityEnum.getCodeByName(contractLocationReqDTO.getCityName());
	if (ObjectUtil.isEmpty(gbCode)) {
		LOGGER.warn("城市名称不存在,项目单号:{}", contractLocationReqDTO.getProjectOrderId());
		gbCode = orderGbCode;
		contractLocationReqDTO.setCityName(CityEnum.getNameByCode(orderGbCode));
	}
	if (SignLocationSourceTypeEnum.PC.getValue().equals(contractLocationReqDTO.getSourceType())
		|| SignLocationSourceTypeEnum.PC_CLIENT.getValue().equals(contractLocationReqDTO.getSourceType())) {
		List<Long> idLIst = contractLocationList.stream().map(ContractLocation::getId).collect(Collectors.toList());
		//PC端上报的数据需通过延时队列进行处理
		ContractLocationDelayMessage contractLocationDelayMessage = ContractLocationDelayMessage.builder()
			.projectOrderId(contractLocationReqDTO.getProjectOrderId())
			.gbCode(gbCode)
			.idList(idLIst)
			.ucId(operatorUcId)
			.latitude(contractLocationReqDTO.getLatitude())
			.longitude(contractLocationReqDTO.getLongitude())
			.operateTime(contractLocationList.get(0).getRecordTime())
			.build();
		//发送延时消息
		rocketMqService.sendDelayMessage(contractLocationReqDTO.getContractCode(), JSON.toJSONString(contractLocationDelayMessage), RocketmqDelayLevelEnum.LEVEL_14.getLevel(), ReceiptCIService.contractLocationCalculationDelayMessage);
		return;
	} else if (!contractLocationReqDTO.getLocationFlag()) {
		// HOME端和C端不上传地理位置不需要进行计算
		return;
	}
	//更新门店距离信息
	recordStoreDistanceInfo(contractLocationList, gbCode, contractLocationReqDTO.getProjectOrderId());

}

public void recordStoreDistanceInfo(List<ContractLocation> contractLocationList, Integer gbCode, String projectOrderId) {
	// 并行查询城市所有门店和签约中心的地址
	Callable<List<StoreLocationDTO>> storeCallable = new CallableWrapper<>(() -> decorRpc.getStoreList(gbCode));
	CompletableFuture<List<StoreLocationDTO>> storeListFuture = CompletableFuture.supplyAsync(() -> {
		try {
			return storeCallable.call();
		} catch (Exception e) {
			LOGGER.error("获取门店地址异常,项目:{}", projectOrderId, e);
			return new ArrayList<>();
		}
	});
	Callable<List<SignCenterLocationDTO>> customerRelationListCallable = new CallableWrapper<>(() -> signCenterRpc.getCustomerRelationList(SignCenterLocationReqDTO.builder().cityCodes(Collections.singletonList(gbCode.toString())).build()));
	CompletableFuture<List<SignCenterLocationDTO>> customerRelationListFuture = CompletableFuture.supplyAsync(() -> {
		try {
			return customerRelationListCallable.call();
		} catch (Exception e) {
			LOGGER.error("获取签约中心地址异常,项目:{}", projectOrderId, e);
			return new ArrayList<>();
		}
	});
	// 获取门店和签约中心地址
	List<StoreLocationDTO> storeList = storeListFuture.join();
	List<SignCenterLocationDTO> customerRelationList = customerRelationListFuture.join();
	//获取距离限制
	BigDecimal signDistanceLimit = contractApolloConfig.getSignDistanceLimit(gbCode);
	if (ObjectUtil.isEmpty(signDistanceLimit)) {
		throw new NrsBusinessException(String.format("签约距离限制未配置, gbCode:%s", gbCode), Level.ERROR);
	}
	// 获取门店记录和签约中心记录
	for (ContractLocation contractLocation : contractLocationList) {
		contractLocation.setRecordType(LocationRecordTypeEnum.NO_STORE.getValue());
		if (SignStoreTypeEnum.STORE.getValue().equals(contractLocation.getStoreType())) {
			buildStoreDistanceInfo(contractLocation, signDistanceLimit, storeList);
		} else if (SignStoreTypeEnum.SIGN_CENTER.getValue().equals(contractLocation.getStoreType())) {
			buildSignCenterDistanceInfo(contractLocation, signDistanceLimit, customerRelationList);
		}
	}
	//更新距离信息
	transactionTemplate.execute(template -> {
		for (ContractLocation contractLocation : contractLocationList) {
			contractLocation.setMtime(new Date());
			contractLocationService.update(contractLocation);
		}
		return null;
	});
}

public BigDecimal haversine(BigDecimal lon1, BigDecimal lat1, BigDecimal lon2, BigDecimal lat2) {
	// 经纬度校验：经度-180~180，纬度-90~90
	if (ObjectUtil.isEmpty(lon1) || ObjectUtil.isEmpty(lat1) || ObjectUtil.isEmpty(lon2) || ObjectUtil.isEmpty(lat2)) {
		return BigDecimal.ZERO;
	}
	if (lon1.compareTo(new BigDecimal("-180")) < 0 || lon1.compareTo(new BigDecimal("180")) > 0
		|| lat1.compareTo(new BigDecimal("-90")) < 0 || lat1.compareTo(new BigDecimal("90")) > 0
		|| lon2.compareTo(new BigDecimal("-180")) < 0 || lon2.compareTo(new BigDecimal("180")) > 0
		|| lat2.compareTo(new BigDecimal("-90")) < 0 || lat2.compareTo(new BigDecimal("90")) > 0) {
		return BigDecimal.valueOf(10000000000000L);
	}

	GlobalCoordinates source = new GlobalCoordinates(lat1.doubleValue(), lon1.doubleValue());
	GlobalCoordinates target = new GlobalCoordinates(lat2.doubleValue(), lon2.doubleValue());
	GeodeticCurve geoCurve = new GeodeticCalculator().calculateGeodeticCurve(Ellipsoid.WGS84, source, target);
	double ellipsoidalDistance = geoCurve.getEllipsoidalDistance();
	LOGGER.info("两点之间的距离是：" + ellipsoidalDistance + "米");
	//距离转化为km并保留两位小数
	return BigDecimal.valueOf(ellipsoidalDistance).divide(BigDecimal.valueOf(1000), 2, RoundingMode.HALF_UP);
}

public void buildStoreDistanceInfo(ContractLocation contractLocation, BigDecimal signDistanceLimit, List<StoreLocationDTO> storeList) {
	if (CollectionUtil.isEmpty(storeList)) {
		return;
	}
	BigDecimal minDistance = BigDecimal.valueOf(100000000L);
	// 计算门店和签约地点距离
	for (StoreLocationDTO storeLocationDTO : storeList) {
		BigDecimal distance = haversine(new BigDecimal(storeLocationDTO.getLongitude()), new BigDecimal(storeLocationDTO.getLatitude()), contractLocation.getLongitude(), contractLocation.getLatitude());
		if (distance.compareTo(BigDecimal.ZERO) > 0 && distance.compareTo(minDistance) < 0 && distance.compareTo(signDistanceLimit) <= 0) {
			minDistance = distance;
			contractLocation.setStoreId(storeLocationDTO.getStoreId().toString());
			contractLocation.setStoreName(storeLocationDTO.getStoreName());
			contractLocation.setDistance(minDistance);
			contractLocation.setRecordType(LocationRecordTypeEnum.HAVE_STORE.getValue());
		}
	}
}

public void buildSignCenterDistanceInfo(ContractLocation contractLocation, BigDecimal signDistanceLimit, List<SignCenterLocationDTO> customerRelationList) {
	if (CollectionUtil.isEmpty(customerRelationList)) {
		return;
	}
	BigDecimal minDistance = BigDecimal.valueOf(100000000L);
	// 计算门店和签约地点距离
	for (SignCenterLocationDTO signCenterLocationDTO : customerRelationList) {
		String coordinate = signCenterLocationDTO.getCoordinate();
		if (StrUtil.isBlank(coordinate)) {
			continue;
		}
		//按照逗号分隔经纬度
		String[] split = coordinate.split(",");
		if (split.length != 2) {
			continue;
		}
		BigDecimal longitude = new BigDecimal(split[0].trim());
		BigDecimal latitude = new BigDecimal(split[1].trim());
		BigDecimal distance = haversine(longitude, latitude, contractLocation.getLongitude(), contractLocation.getLatitude());
		if (distance.compareTo(BigDecimal.ZERO) > 0 && distance.compareTo(minDistance) < 0 && distance.compareTo(signDistanceLimit) <= 0) {
			minDistance = distance;
			contractLocation.setStoreId(signCenterLocationDTO.getPlaceCode());
			contractLocation.setStoreName(signCenterLocationDTO.getPlaceName());
			contractLocation.setDistance(distance);
			contractLocation.setRecordType(LocationRecordTypeEnum.HAVE_STORE.getValue());
		}
	}
}

public ShareCheckDTO getShareUrl(String contractCode, boolean processV25) {
	if (StringUtils.isBlank(contractCode)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同编号不能为空");
	}
	Contract contract = contractService.getByContractCode(contractCode);
	//通用合同分享跳转链接
	//获取链接url
	String url = String.format(contractApolloConfig.getContractSignMpPagePathShortUrl(), contractApolloConfig.getJingGongHost(), contractCode);
	LOGGER.info("合同分享链接url:{}", url);
	String miniPath = null;
	String wxPath = null;
	try {
		wxPath = String.format(contractApolloConfig.getContractSignMpPagePathNew(), URLEncoder.encode(url, "UTF-8"));
		miniPath = String.format(contractApolloConfig.getContractSignWxPagePathNew(), URLEncoder.encode(url, "UTF-8"));
	} catch (UnsupportedEncodingException e) {
		wxPath = contractApolloConfig.getContractListSignMpPagePath().concat("&projectOrderId=").concat(contract.getProjectOrderId()).concat("&from=wxShare");
		miniPath = contractApolloConfig.getContractListSignWxPagePath().concat("&projectOrderId=").concat(contract.getProjectOrderId()).concat("&from=wxShare");
	}
	LOGGER.info("微信合同分享链接:{}", wxPath);
	LOGGER.info("企微合同分享链接:{}", miniPath);

	List<Contract> relationContractList = contractBusinessService.getRelationContract(contractCode);
	//合并发起合同分享链接
	String mergePagePathWx = contractApolloConfig.getContractMergeSignMpPagePath().concat("contractCode=").concat(contractCode).concat("&projectOrderId=").concat(contract.getProjectOrderId()).concat("&from=wxShare");
	String mergePagePathMini = contractApolloConfig.getContractMergeSignWxPagePath().concat("contractCode=").concat(contractCode).concat("&projectOrderId=").concat(contract.getProjectOrderId()).concat("&from=wxShare");
	LOGGER.info("合同分享链接mergePagePath:{}", mergePagePathWx);
	//合同是否包含关联合同，有关联合同为true，没有为false
	Boolean mergeLaunch = false;
	LOGGER.info("关联合同列表:{}", relationContractList);
	if (CollectionUtil.isNotEmpty(relationContractList)) {
		wxPath = mergePagePathWx + "&signSceneType=" + SignSceneTypeEnum.FORMAL.getCode();
		miniPath = mergePagePathMini + "&signSceneType=" + SignSceneTypeEnum.FORMAL.getCode();
		mergeLaunch = true;
	}

	ContractRelation byRelateContractCode = contractRelationService.getByRelateContractCode(contractCode);
	if (byRelateContractCode != null && !ContractTypeEnum.AUTH_AGENT.getCode().equals(contract.getType())) {
		wxPath = mergePagePathWx + "&signSceneType=" + SignSceneTypeEnum.FORMAL.getCode();
		miniPath = mergePagePathMini + "&signSceneType=" + SignSceneTypeEnum.FORMAL.getCode();
		mergeLaunch = true;
		contract = contractService.getByContractCode(byRelateContractCode.getContractCode());
	}
	//B+C协同发起个性化合同是协同发起时的分享链接，也就是当时的B合同的分享链接
	if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
		//不是变更发起的公对公个性化合同，不是单独发起的个性化合同，则为协同发起的个性化合同
		if (StringUtils.isBlank(contract.getChangeOrderId()) && !isMultipleQuotePersonalContract(contract)) {
			Contract packageFormalContract = contractService.getLatestContract(contract.getProjectOrderId(), ContractTypeEnum.PACKAGE_FORMAL.getCode());
			if (packageFormalContract == null) {
				throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "当前合同不存在", Level.WARN);
			}
			contract = packageFormalContract;
			wxPath = mergePagePathWx + "&signSceneType=" + SignSceneTypeEnum.FORMAL.getCode();
			miniPath = mergePagePathMini + "&signSceneType=" + SignSceneTypeEnum.FORMAL.getCode();
			mergeLaunch = true;
		}
		if (isMultipleQuotePersonalContract(contract)) {
			//多报价单个性化合同
			wxPath = mergePagePathWx+ "&signSceneType=" + SignSceneTypeEnum.PERSONAL.getCode();
			miniPath = mergePagePathMini + "&signSceneType=" + SignSceneTypeEnum.PERSONAL.getCode();
			mergeLaunch = true;
		}
	}

	List<ContractUser> contractUsers = contractUserService.getListByContractCode(contractCode);
	//获取手机签署手机号
	String phone = contractUsers.stream()
		.filter(contractUser -> IsSignEnum.YES.getCode().equals(contractUser.getIsSign()))
		.findFirst()
		.orElse(ContractUser.builder().phone("").build())
		.getPhone();

	if (contractApolloConfig.isSupportWatchVideo(contract.getBusinessType(), contract.getGbCode())) {
		//判断是否需要看视频
		if (contractVideoService.needWatchVideo(contract, processV25)
			&& (ContractStatusEnum.PENDING_USER_CONFIRM.getCode().equals(contract.getStatus())
			|| ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus()))) {
			String signPhone = cipherService.decrypt(phone);

			// 手机号注销获取不到ucId降级
			MemberDetailDTO memberDetailDTO = null;
			try {
				memberDetailDTO = memberRpc.getClientUcIdByPhone(Long.parseLong(signPhone));
			} catch (Exception e) {
				LOGGER.info("手机号请求member获取ucId失败", e);
			}
			Integer watchStatus = null;
			if (memberDetailDTO == null) {
				//手机号注销或者没有注册,判断为没看过视频
				watchStatus = WatchStatusEnum.NOT_FINISH.getCode();
			} else {
				String ucId = memberDetailDTO.getId().toString();
				watchStatus = contractVideoService.getWatchStatusNew(contract, ucId);
			}

			if (WatchStatusEnum.NOT_FINISH.getCode().equals(watchStatus)) {
				// 需要观看视频
				String miniVideoPagePath = contractApolloConfig.getVideoPagePath().concat("projectOrderId=")
					.concat(contract.getProjectOrderId()).concat("&contractCode=").concat(contractCode)
					.concat("&from=wxShare").concat("&mergeLaunch=").concat(mergeLaunch.toString());
				String wxVideoPagePath = contractApolloConfig.getVideoPagePathWx().concat("projectOrderId=")
					.concat(contract.getProjectOrderId()).concat("&contractCode=").concat(contractCode)
					.concat("&from=wxShare").concat("&mergeLaunch=").concat(mergeLaunch.toString());
				Integer signSceneType = isMultipleQuotePersonalContract(contract) ? SignSceneTypeEnum.PERSONAL.getCode() : SignSceneTypeEnum.FORMAL.getCode();
				wxPath = miniVideoPagePath + "&signSceneType=" + signSceneType;
				miniPath = wxVideoPagePath + "&signSceneType=" + signSceneType;
			}
		}
	}
	return ShareCheckDTO.builder()
		.canShare(true)
		.wxPath(wxPath)
		.miniPath(miniPath)
		.build();
}

