		return ProjectInfoDTO.builder()
			.decorateBusinessType(BusinessTypeEnum.HOUSE_CERTIFICATE.getCode())
			.customer(customerDTO)
			.customerHouse(customerHouseDTO)
			.customerCommission(customerCommissionDTO)
			.build();
	}

	private List<ContractListVo.ContractListItemVo> sortContractListItemVo(List<ContractListVo.ContractListItemVo> contractItemVoList, String projectOrderId, byte businessType) {
		ContractProcessModeChangeInfo processModeChangeInfo = formalReSignService.getContractProcessModeChangeInfo(projectOrderId);
		List<ContractListVo.ContractListItemVo> formalContractList = contractItemVoList.stream().filter(vo -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(vo.getType())).collect(Collectors.toList());
		//只有一份正签合同&&是2.0时签订的正签合同，不需要排序处理
		if (formalContractList.size() == 1 && processModeChangeInfo.isHaveHistoricalContract()) {
			return contractItemVoList;
		}
		//合并发起的施工图纸合同不返回
		final List<ContractListVo.ContractListItemVo> filteredContractItemVoList = contractItemVoList.stream()
			.filter(item -> !Objects.equals(item.getType(), ContractTypeEnum.DRAWING.getCode())).collect(Collectors.toList());
		//正签-草稿-合同顺序为【正签-个性化】在一起的
		ContractListVo.ContractListItemVo formalContract = filteredContractItemVoList.stream()
			.filter(item -> item.getType().equals(ContractTypeEnum.PACKAGE_FORMAL.getCode())).findFirst().orElse(null);
		int formalIndex = IntStream.range(0, filteredContractItemVoList.size())
			.filter(i -> Objects.equals(filteredContractItemVoList.get(i).getType(), ContractTypeEnum.PACKAGE_FORMAL.getCode()))
			.findFirst()
			.orElse(-1);
		int personalIndex = IntStream.range(0, filteredContractItemVoList.size())
			.filter(i -> Objects.equals(filteredContractItemVoList.get(i).getType(), ContractTypeEnum.PERSONAL.getCode()))
			.filter(i -> ObjectUtil.isNotEmpty(filteredContractItemVoList.get(i).getPrimaryRelatedContractCode()))
			.findFirst()
			.orElse(-1);
		// 查找与正签合同关联的设计合同
		int designIndex = IntStream.range(0, filteredContractItemVoList.size())
				.filter(i -> Objects.equals(filteredContractItemVoList.get(i).getType(), ContractTypeEnum.DESIGN.getCode()))
				.filter(i -> ObjectUtil.isNotEmpty(filteredContractItemVoList.get(i).getPrimaryRelatedContractCode())
					&& formalContract != null && filteredContractItemVoList.get(i).getPrimaryRelatedContractCode().equals(formalContract.getContractCode()))
				.findFirst()
				.orElse(-1);
		Integer contractMode = formalContract != null ? commonContractService.getContractModeByContractCode(formalContract.getContractCode()) : null;
		//合同名字处理，合并发起的&存在正式套餐合同：正式套餐合同后面加"及图纸"
		if (formalIndex != -1) {
			String typeName = filteredContractItemVoList.get(formalIndex).getTypeName();
			if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
				typeName = ContractModeEnum.FULL_SERVICE.getCode().equals(contractMode) ? typeName.concat("图纸及附件") : typeName.concat("及图纸");
			}
			if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
				boolean hasUploadFormalDrawing = contractBusinessService.hasUploadFormalDrawing(true, businessType, projectOrderId);
				typeName = hasUploadFormalDrawing ? typeName.concat("及图纸") : typeName;
			}
			filteredContractItemVoList.get(formalIndex).setTypeName(typeName);
		}

		// 优化后的排序逻辑：先处理个性化合同，再处理设计合同
		if (formalIndex != -1 && personalIndex != -1) {
			//如果存在个性化合同， 将个性化合同插入到正签的合同后一位
			ContractListVo.ContractListItemVo personalContractVo = filteredContractItemVoList.remove(personalIndex);
			if (personalIndex > formalIndex) {
				filteredContractItemVoList.add(formalIndex + 1, personalContractVo);
			} else {
				filteredContractItemVoList.add(formalIndex, personalContractVo);
			}
			// 调整设计合同索引：如果设计合同在个性化合同之后，索引需要减1
			if (designIndex != -1 && designIndex > personalIndex) {
				designIndex--;
			}
		}

		// 处理设计合同排序：将设计合同放到正签合同或个性化合同后一位
		if (formalIndex != -1 && designIndex != -1) {
			ContractListVo.ContractListItemVo designContractVo = filteredContractItemVoList.remove(designIndex);
			// 重新查找正签合同和个性化合同的位置（因为之前的操作可能改变了位置）
			int newFormalIndex = IntStream.range(0, filteredContractItemVoList.size())
				.filter(i -> Objects.equals(filteredContractItemVoList.get(i).getType(), ContractTypeEnum.PACKAGE_FORMAL.getCode()))
				.findFirst()
				.orElse(-1);
			int newPersonalIndex = IntStream.range(0, filteredContractItemVoList.size())
				.filter(i -> Objects.equals(filteredContractItemVoList.get(i).getType(), ContractTypeEnum.PERSONAL.getCode()))
				.filter(i -> ObjectUtil.isNotEmpty(filteredContractItemVoList.get(i).getPrimaryRelatedContractCode()))
				.findFirst()
				.orElse(-1);

			// 确定插入位置：如果有个性化合同，放到个性化合同后面；否则放到正签合同后面
			int insertPosition;
			if (newPersonalIndex != -1) {
				// 有个性化合同，插入到个性化合同后一位
				insertPosition = newPersonalIndex + 1;
			} else {
				// 没有个性化合同，插入到正签合同后一位
				insertPosition = newFormalIndex + 1;
			}
			filteredContractItemVoList.add(insertPosition, designContractVo);
		}

		return filteredContractItemVoList;
	}

	/**
	 * 个性化合同是否和正签合同关联
	 */
	public boolean isPersonalContractRelatedFormalContract(ContractListVo.ContractListItemVo formalContract, ContractListVo.ContractListItemVo personalContract) {
		if (formalContract == null || personalContract == null) {
			return false;
		}
		//正签合同的合同编号
		List<ContractRelation> relationList = contractRelationService.getRelationList(formalContract.getContractCode());
		if (CollectionUtils.isEmpty(relationList)) {
			return false;
		}
		for (ContractRelation relation : relationList) {
			if (relation.getRelateContractCode().equals(personalContract.getContractCode())) {
				return true;
			}
		}
		return false;
	}

	/**
	 * 合同列表项信息
	 *
	 * @param contract
	 * @param authStatus
	 * @return
	 */
	private List<ContractListVo.ContractListItemInfo> getContractListItemInfos(Contract contract, Integer authStatus) {
		// 合同金额、编号
		List<ContractListVo.ContractListItemInfo> contractListItemInfos = new LinkedList<>();
		ContractListVo.ContractListItemInfo amountInfo = new ContractListVo.ContractListItemInfo("amount",
			"合同金额", String.valueOf(contract.getAmount()));
		contractListItemInfos.add(amountInfo);
		ContractListVo.ContractListItemInfo contractNoInfo = new ContractListVo.ContractListItemInfo("contractNo",
			"编号", String.valueOf(contract.getContractNo()));
		contractListItemInfos.add(contractNoInfo);
		// 发起时间、确认时间、签约时间
		List<ContractNode> contractNodes = contractNodeService.getListByContractCode(contract.getContractCode());
		Map<Byte, ContractNode> contractNodeMap = contractNodes.stream().collect(Collectors.toMap(ContractNode::getNodeType, Function.identity(), (v1, v2) -> v2));
		contractNodeMap.forEach((nodeType, contractNode) -> {
			if (nodeType == NodeTypeEnum.SUBMIT.getCode().byteValue() ||
				nodeType == NodeTypeEnum.USER_CONFIRM.getCode().byteValue() ||
				nodeType == NodeTypeEnum.USER_SIGN.getCode().byteValue()) {
				String time = DateUtils.getDateTimeStr(new Date(contractNode.getFireTime()));
				switch (Objects.requireNonNull(NodeTypeEnum.getNodeTypeEnumByCode(contractNode.getNodeType()))) {
					case SUBMIT:
						ContractListVo.ContractListItemInfo submitTimeInfo = new ContractListVo.ContractListItemInfo(
							"submitTime", "发起时间", time);
						contractListItemInfos.add(submitTimeInfo);
						break;
					case USER_CONFIRM:
						ContractListVo.ContractListItemInfo commitTimeInfo = new ContractListVo.ContractListItemInfo(
							"commitTime", "确认时间", time);
						contractListItemInfos.add(commitTimeInfo);
						break;
					case USER_SIGN:
						ContractListVo.ContractListItemInfo signTimeInfo = new ContractListVo.ContractListItemInfo(
							"signTime", "签署时间", time);
						contractListItemInfos.add(signTimeInfo);
						break;
					default:
						break;
				}
			}
		});
		// 关联变更单号
		if (ObjectUtil.isNotEmpty(contract.getChangeOrderId()) && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType()) && commonBusinessService.isPROCESS_V2_0_GROUP(contract.getProjectOrderId())) {
			ContractListVo.ContractListItemInfo changeOrderIdInfo = new ContractListVo.ContractListItemInfo("changeOrderId",
				"关联变更单号", contract.getChangeOrderId());
			contractListItemInfos.add(changeOrderIdInfo);
		}
		// 认证状态、授权状态
		if (ContractAuthStatusEnum.getNeedAuthStatus().contains(authStatus)) {
			ContractListVo.ContractListItemInfo authenticationInfo = new ContractListVo.ContractListItemInfo("authenticationStatus", "认证状态", Boolean.TRUE.equals(ContractAuthStatusEnum.isAuthentication(authStatus)) ? "已认证" : "未认证");
			contractListItemInfos.add(authenticationInfo);
			ContractListVo.ContractListItemInfo authorizationInfo = new ContractListVo.ContractListItemInfo("authorizationStatus", "授权状态", Boolean.TRUE.equals(ContractAuthStatusEnum.isAuthorized(authStatus)) ? "已授权" : "未授权");
			contractListItemInfos.add(authorizationInfo);
		}

		// 产权人授权状态
		Contract authAgentContract = homeAndPcCommonService.getRelateContractByType(contract, ContractTypeEnum.AUTH_AGENT.getCode());
		if (authAgentContract != null) {
			ContractListVo.ContractListItemInfo authorizationInfo = new ContractListVo.ContractListItemInfo("authAgentStatus",
				"产权人授权状态", ContractStatusEnum.SIGNED_STATUS_LIST.contains(authAgentContract.getStatus()) ? "已授权" : "未授权");
			contractListItemInfos.add(authorizationInfo);
		}

		return contractListItemInfos;
	}

