	private List<ButtonItemVo> getButtonListByConfig(Contract contract, List<String> attachUrlList, @Nullable List<Contract> contractList, List<ContractNode> userConfirmNodeList, Set<String> terminalContractCode) {
		boolean beijingOldOrder = projectInfoReadService.judgeIfBeijingOldOrder(Collections.singletonList(contract.getProjectOrderId()));
		boolean multipleQuotePersonalContract = homeAndPcCommonService.isMultipleQuotePersonalContract(contract);
		boolean hasContractAgreement = contract.getPlatformInstanceId() > 0 || !attachUrlList.isEmpty();
		// 补充协议单独发起
		boolean supplementSubmitAlone = homeAndPcCommonService.supplementSubmitAlone(contract);
		// 判断设计合同是否是合并发起
		boolean designContractSubmitAlone = homeAndPcCommonService.designContractSubmitAlone(contract);
		// 匹配参数
		ContractListButtonExecParam execParams = ContractListButtonExecParam.builder()
			.contractCode(contract.getContractCode())
			.contractType(contract.getType())
			.contractStatus(contract.getStatus())
			.contractList(contractList)
			.userConfirmNodeList(userConfirmNodeList)
			.bpmNo(contract.getBmpNo())
			.changeOrderId(contract.getChangeOrderId())
			.beijingOldOrder(beijingOldOrder)
			.multipleQuotePersonalContract(multipleQuotePersonalContract)
			.terminalContractCode(terminalContractCode)
			.hasContractAgreement(hasContractAgreement)
			.supplementSubmitAlone(supplementSubmitAlone)
			.designContractSubmitAlone(designContractSubmitAlone)
			.build();
		List<ButtonItemVo> homeContractListButton = buttonConfigService.getHomeContractListButton(execParams);

		// 特殊规则：已作废合同预览并分享展示为预览合同
		if (ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())) {
			homeContractListButton = homeContractListButton.stream().map(m -> {
				if (HomeButtonEnum.PREVIEW.getType().equals(m.getType())) {
					m.setName("预览合同");
				}
				return m;
			}).collect(Collectors.toList());
		}

		//生成中的合同不展示按钮
		if (!contractApolloConfig.getContractSubmitSync() && ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())
			&& lockService.isLocked(LockConstant.getContractLaunchingKey(contract.getProjectOrderId(), contract.getType()))) {
			return new ArrayList<>();
		}


		return homeContractListButton;
	}

	private List<String> getCanChangeContractCodeList(List<Contract> contractList) {
		if (CollectionUtil.isEmpty(contractList)) {
			return new ArrayList<>();
		}
		List<String> contractCodeList = new ArrayList<>();
		//是否展示去变更按钮
		Boolean canChange = Boolean.TRUE;
		for (Contract contract : contractList) {
			if (ContractTypeEnum.showChangeContractList().contains(contract.getType())) {
				//存在进行中的设计合同/设计变更合同，不展示去变更按钮
				if (ContractStatusEnum.isInProgressStatus(contract.getStatus())) {
					return new ArrayList<>();
				}
				//存在已完成的设计合同、设计变更合同，只有最新的设计合同/设计变更合同展示去变更按钮
				if ((ContractStatusEnum.FINISH.getCode().equals(contract.getStatus()) || ContractStatusEnum.USER_CONFIRMED.getCode().equals(contract.getStatus())) && canChange) {
					contractCodeList.add(contract.getContractCode());
					canChange = Boolean.FALSE;
				}
			}
		}
		return contractCodeList;
	}

	/**
	 * @param
	 * @param commissionCode
	 * @return
	 */
	public List<ContractTypeListVo.ContractTypeListItemVo> getRetailTypeList(String commissionCode, List<Byte> contractTypeList, Integer sceneType) {
		if (ObjectUtil.isEmpty(sceneType)) {
			sceneType = ContractShowSceneTypeEnum.ALL_AND_RETAIL.getCode();
		}
		List<ContractTypeListVo.ContractTypeListItemVo> resRetailTypeList = new ArrayList<>();
		if (StringUtils.isBlank(commissionCode)) {
			return resRetailTypeList;
		}
		// 查询零售项目
		ProjectInfo projectInfo = projectInfoService.getByCustomerCommissionCode(commissionCode);
		//不是纯零售不展示销售合同&销售变更补充协议typeList,直接返回空
		if (ObjectUtil.isNotEmpty(projectInfo)
			&& (commonBusinessService.isPROCESS_V2_5(projectInfo.getProjectOrderId()) || !ContractShowSceneTypeEnum.ALL_AND_RETAIL.getCode().equals(sceneType))) {
			return resRetailTypeList;
		}
		//纯零售默认常驻展示销售合同&销售变更补充协议typeList
		ContractTypeListVo.ContractTypeListItemVo retailContract = ContractTypeListVo.ContractTypeListItemVo.builder()
			.type(ContractTypeEnum.RETAIL.getCode())
			.typeName(ContractTypeEnum.RETAIL.getName())
			.desc(ContractTypeEnum.RETAIL.getDesc())
			.extraDesc(ContractTypeEnum.RETAIL.getExtraDesc())
			.build();
		resRetailTypeList.add(retailContract);
		ContractTypeListVo.ContractTypeListItemVo retailChangeContract = ContractTypeListVo.ContractTypeListItemVo.builder()
			.type(ContractTypeEnum.RETAIL_CHANGE.getCode())
			.typeName(ContractTypeEnum.RETAIL_CHANGE.getName())
			.desc(ContractTypeEnum.RETAIL_CHANGE.getDesc())
			.extraDesc(ContractTypeEnum.RETAIL_CHANGE.getExtraDesc())
			.build();
		resRetailTypeList.add(retailChangeContract);
		if (CollectionUtils.isNotEmpty(contractTypeList)) {
			return resRetailTypeList.stream().filter(item -> contractTypeList.contains(item.getType())).collect(Collectors.toList());
		}
		return resRetailTypeList;
	}


	/**
	 * 并行请求整装和零售订单类型列表
	 *
	 * @param projectOrderId
	 * @param commissionCode
	 * @return
	 */
	public ContractTypeListVo getContractTypeList(String projectOrderId, String commissionCode, String contractTypeList, Integer sceneType) {
		List<Byte> contractTypeListByte = new ArrayList<>();
		if (!StringUtils.isBlank(contractTypeList)) {
			contractTypeListByte = Arrays.stream(contractTypeList.split(",")).map(Byte::parseByte).collect(Collectors.toList());
		}
		List<Byte> finalContractTypeListByte = contractTypeListByte;
		CompletableFuture<ContractTypeListVo> decorateFuture = CompletableFuture.supplyAsync(() -> getDecorateContractTypeList(projectOrderId, commissionCode, finalContractTypeListByte, sceneType), parallelRequestExecutor);
		CompletableFuture<List<ContractTypeListVo.ContractTypeListItemVo>> retailFuture = CompletableFuture.supplyAsync(() -> getRetailTypeList(commissionCode, finalContractTypeListByte, sceneType), parallelRequestExecutor);

		try {
			ContractTypeListVo contractTypeListVo =  decorateFuture.thenCombine(retailFuture, (decorate, retail) -> {
				if (CollectionUtils.isEmpty(decorate.getContractTypeListItemVos())) {
					decorate.setContractTypeListItemVos(retail);
				} else {
					decorate.getContractTypeListItemVos().addAll(retail);
				}
				return decorate;
			}).join();
			contractTypeListVo.setContractAgentOpen(commonContractService.contractAgentOpen(projectOrderId));
			return contractTypeListVo;
		} catch (CompletionException e) {
			Throwable cause = e.getCause();
			LOGGER.error("获取合同类型列表失败projectOrderId:{},commissionCode:{} ", projectOrderId, commissionCode, e);
			if (cause instanceof NrsBusinessException) {
				throw (NrsBusinessException) cause;
			} else {
				throw new NrsBusinessException("获取合同类型列表失败，请刷新或联系客服", Level.ERROR);
			}
		} catch (NrsBusinessException e) {
			throw e;
		} catch (Exception e) {
			LOGGER.error("获取合同类型列表失败projectOrderId:{},commissionCode:{} ", projectOrderId, commissionCode, e);
			throw new NrsBusinessException("获取合同类型列表失败，请刷新或联系客服", Level.ERROR);
		}
	}

	/**
	 * 整装合同类型列表
	 *
	 * @param projectOrderId
	 * @param commissionCode
	 * @return
	 */
	public ContractTypeListVo getDecorateContractTypeList(String projectOrderId, String commissionCode, List<Byte> contractTypeList, Integer sceneType) {
		if (ObjectUtil.isEmpty(sceneType)) {
			sceneType = ContractShowSceneTypeEnum.ALL_AND_RETAIL.getCode();
		}
		ContractTypeListVo vo = new ContractTypeListVo();
		ProjectInfoDTO projectInfoDTO = getProjectInfo(projectOrderId, commissionCode);
		if (projectInfoDTO == null) {
			return vo;
		}
		byte businessType = commonBusinessService.getBusinessType(projectOrderId);
		vo.setAddress(homeAndPcCommonService.getSafeAddress(projectInfoDTO));
		vo.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));
		vo.setCompanyCode(projectInfoDTO.getCustomerCommission().getCompanyCode());
		vo.setGbCode(projectInfoDTO.getCustomerHouse().getGbCode());
		vo.setBusinessType(businessType);
		if (ObjectUtil.isEmpty(vo.getCompanyCode())) {
			throw new NrsBusinessException("订单未分配分公司，获取合同列表失败", Level.WARN);
		}
		List<ContractTypeListVo.ContractTypeListItemVo> contractTypeListItemVos = new LinkedList<>();
		if (ObjectUtil.isEmpty(projectInfoDTO.getProjectOrderId())) {
			return vo;
		}
		CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectInfoDTO.getProjectOrderId());
		projectOrderId = coordinationProjectOrder.getProjectOrderId();
		if (StringUtils.isBlank(projectOrderId)) {
			return vo;
		}

		//读取分公司配置
		List<ContractCityCompanyInfo> companyConfig = getCreatableContractList(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), projectInfoDTO.getCustomerCommission().getCompanyCode(), businessType);
		ContractProcessModeChangeInfo contractProcessModeChangeInfo = formalReSignService.getContractProcessModeChangeInfo(projectOrderId);
		String convertProjectOrderId = null;
		if (HomeWorkflowTypeEnum.RETAIL.getType().equals(coordinationProjectOrder.getHomeWorkflowType())) {
			convertProjectOrderId = coordinationProjectOrder.getRetailProjectOrder().getProjectOrderId();
		} else {
			convertProjectOrderId = coordinationProjectOrder.getDecorateProjectOrder().getProjectOrderId();
		}
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(convertProjectOrderId);
		vo.setProcessV25(processV25);
		vo.setSupportFullServiceSign(commonContractService.supportFullServiceSign(projectInfoDTO.getCustomerHouse().getGbCode(),businessType));
		vo.setFormalUseNewProcess(contractBusinessService.formalUseNewProcess(businessType, processV25, projectInfoDTO.getCustomerHouse().getGbCode()));
		//从Apollo获取home端可以创建的列表和不可创建的列表
		List<Byte> createContractList = contractApolloConfig.createContractList(convertProjectOrderId, businessType, AppIdEnum.HOME.getAppId(), projectInfoDTO.getCustomerHouse().getGbCode());
		List<Byte> cannotCreateContractList = contractApolloConfig.cannotCreateContractList(convertProjectOrderId, businessType, AppIdEnum.HOME.getAppId(), projectInfoDTO.getCustomerHouse().getGbCode());

		//支持线下的合同类型
		List<Integer> offlineContractType = new ArrayList<>();
		//线上支持的类型
		Map<Integer, List<Byte>> onlineContractTypeMap = new HashMap<>();
		for (ContractCityCompanyInfo contractCityCompanyInfo : companyConfig) {
			if (SignChannelTypeEnum.ONLINE.getCode().equals(contractCityCompanyInfo.getSignChannelType())) {
				if (!onlineContractTypeMap.containsKey(contractCityCompanyInfo.getContractType())) {
					onlineContractTypeMap.put(contractCityCompanyInfo.getContractType(), new LinkedList<>());
				}
				List<Byte> userSignTypes = Arrays.stream(contractCityCompanyInfo.getUserSignType().split(",")).map(Byte::parseByte).collect(Collectors.toList());
				onlineContractTypeMap.get(contractCityCompanyInfo.getContractType()).addAll(userSignTypes);
			} else if (SignChannelTypeEnum.OFFLINE.getCode().equals(contractCityCompanyInfo.getSignChannelType())) {
				offlineContractType.add(contractCityCompanyInfo.getContractType());
			}
		}

		// 支持创建的合同列表
		List<Byte> contractTypeEnums = new ArrayList<>();
		// 根据场景下发不同的合同
		if (ContractShowSceneTypeEnum.ALL_AND_RETAIL.getCode().equals(sceneType) || ContractShowSceneTypeEnum.ALL.getCode().equals(sceneType)) {
			if (coordinationProjectOrder.hasDecorateProjectOrder()) {
				contractTypeEnums = Arrays.stream(ContractTypeEnum.values())
					.sorted(Comparator.comparing(ContractTypeEnum::getOrder)).map(ContractTypeEnum::getCode).collect(Collectors.toList());
			} else {
				//纯零售仅返回个性化相关的合同
				contractTypeEnums = ContractTypeEnum.getPersonalizedRelevantContractList();
			}
		} else if (ContractShowSceneTypeEnum.WHOLE.getCode().equals(sceneType)) {
			if (coordinationProjectOrder.hasDecorateProjectOrder()) {
				contractTypeEnums = ContractTypeEnum.WHOLE_CONTRACT;
			} else {
				contractTypeEnums = new ArrayList<>();
			}
		} else if (ContractShowSceneTypeEnum.RETAIL.getCode().equals(sceneType)) {
			contractTypeEnums = ContractTypeEnum.getPersonalizedRelevantContractList();
		}
		// 过滤指定创建的合同
		if (CollectionUtils.isNotEmpty(contractTypeList)) {
			contractTypeEnums = contractTypeEnums.stream().filter(contractTypeList::contains).collect(Collectors.toList());
		}
		for (Byte contractType : contractTypeEnums) {
			ContractTypeEnum contractTypeEnum = ContractTypeEnum.getEnumByCode(contractType);
			ContractTypeListVo.ContractTypeListItemVo contractTypeListItemVo = null;
			List<Contract> contractList = contractService.getContractList(projectOrderId, contractTypeEnum.getCode()).stream()
				.filter(item -> ContractStatusEnum.inPositiveStatus.contains(item.getStatus()))
				.collect(Collectors.toList());
			//可创建的合同类型
			if (createContractList.contains(contractTypeEnum.getCode())) {
				contractTypeListItemVo = new ContractTypeListVo.ContractTypeListItemVo(contractTypeEnum, businessType);
				if (CollectionUtils.isNotEmpty(contractList)) {
					contractTypeListItemVo.setState(ContractShowEnum.CREATED.getCode());
					contractTypeListItemVo.setStateText(ContractShowEnum.CREATED.getName());
				} else {
					// 初始化创建按钮
					initContractCreateState(contractTypeListItemVo, onlineContractTypeMap, contractTypeEnum, offlineContractType);
				}
				//C合同始终支持创建,通过Apollo开关实现上线兼容
				if (ContractTypeEnum.PERSONAL.getCode().equals(contractType) && contractApolloConfig.getCheckPersonalContract()) {
					initContractCreateState(contractTypeListItemVo, onlineContractTypeMap, contractTypeEnum, offlineContractType);
					contractTypeListItemVo.setStateText("");
				}
				// 补充协议按钮
				if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractType)) {
					// 如果补充协议未开城，则不展示补充协议卡片
					if (Boolean.FALSE.equals(contractUnifyService.supplementIsOpen(convertProjectOrderId))) {
						continue;
					}
					// 开城后，恒展示【去创建】按钮
					initContractCreateState(contractTypeListItemVo, onlineContractTypeMap, contractTypeEnum, offlineContractType);
				}
				// 和解协议按钮
				if (ContractTypeEnum.SETTLEMENT.getCode().equals(contractType)) {
					if (Boolean.FALSE.equals(contractUnifyService.settlementIsOpen(convertProjectOrderId))) {
						// 如果和解协议未开城，则不展示和解协议卡片
						continue;
					}
					// 开城后，恒展示【去创建】按钮
					initContractCreateState(contractTypeListItemVo, onlineContractTypeMap, contractTypeEnum, offlineContractType);
				}
			}
			//不可创建的合同类型
			if (cannotCreateContractList.contains(contractTypeEnum.getCode())) {
				contractTypeListItemVo = new ContractTypeListVo.ContractTypeListItemVo(contractTypeEnum, businessType);
				contractTypeListItemVo.setState(ContractShowEnum.CANNOT_CREATE.getCode());
				//对于变更合同:不是团装,下发stateText
				if (BusinessTypeEnum.GROUP_DECORATE.getCode() != businessType && contractTypeEnum.getCode().equals(ContractTypeEnum.PACKAGE_CHANGE.getCode())) {
					contractTypeListItemVo.setStateText(contractTypeEnum.getRefuseCreateTipH5());
				}
				contractTypeListItemVo.setExtraDesc(ContractTypeEnum.getExtraDescByContractTypeAndBusinessType(contractTypeEnum.getCode(), businessType));
			}
			if (ObjectUtil.isEmpty(contractTypeListItemVo)) {
				continue;
			}
			//2.5正式套餐合同名字处理
			if (vo.isProcessV25() && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
				contractTypeListItemVo.setTypeName(contractTypeListItemVo.getTypeName().concat("及图纸"));
			}
			//2.5正式套餐合同名字处理
			if (vo.isProcessV25() && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
				boolean hasUploadFormalDrawing = contractBusinessService.hasUploadFormalDrawing(true, businessType, projectOrderId);
				String typeName = hasUploadFormalDrawing ? contractTypeListItemVo.getTypeName().concat("及图纸") : contractTypeListItemVo.getTypeName();
				contractTypeListItemVo.setTypeName(typeName);
			}
			if (ObjectUtil.isNotEmpty(contractTypeListItemVo)) {
				contractTypeListItemVos.add(contractTypeListItemVo);
			}
			//2.0->2.5历史正式套餐合同处理
			if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractTypeEnum.getCode()) && contractTypeListItemVo != null
				&& ContractShowEnum.CREATED.getCode().equals(contractTypeListItemVo.getState())
				&& formalReSignService.newFormalContractCanLaunch(contractProcessModeChangeInfo)) {
				initContractCreateState(contractTypeListItemVo, onlineContractTypeMap, contractTypeEnum, offlineContractType);
			}
		}
		vo.setContractTypeListItemVos(contractTypeListItemVos);
		vo.setFormalReSignInfo(formalReSignService.getFormalReSignInfo(contractProcessModeChangeInfo));
		return vo;
	}

	/**
	 * 初始化创建按钮
	 */
	private void initContractCreateState(ContractTypeListVo.ContractTypeListItemVo contractTypeListItemVo, Map<Integer, List<Byte>> onlineContractTypeMap, ContractTypeEnum contractTypeEnum, List<Integer> offlineContractType) {
		contractTypeListItemVo.setState(ContractShowEnum.CREATE.getCode());
		contractTypeListItemVo.setSupportUserSignType(onlineContractTypeMap.getOrDefault(contractTypeEnum.getCode().intValue(), null));
		contractTypeListItemVo.setSupportSignChannelType(getContractTypeSupportSignChannelList(contractTypeEnum.getCode(), offlineContractType, onlineContractTypeMap));
		contractTypeListItemVo.setButtonList(Lists.newArrayList(new ButtonItemVo(HomeButtonEnum.CREATE)));
	}

	/**
	 * 查询配置获取可创建的合同列表
	 */
	private List<ContractCityCompanyInfo> getCreatableContractList(String projectOrderId, Integer gbCode, String companyCode, Byte businessType) {
		companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectOrderId, gbCode, companyCode, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		List<ContractCityCompanyInfo> companyConfig = contractCityCompanyConfigService.getConfig(projectOrderId, gbCode, companyCode, businessType);
		// 兼容北京1.0设计合同
		if (CityEnum.BEIJING.getGbCode() == gbCode) {
			List<ProjectVersionDTO> projectVersionDTOS = projectInfoReadService.batchProjectVersion(Collections.singletonList(projectOrderId));
			boolean isBeijingDesignContract = projectVersionDTOS.stream().anyMatch(version -> ProjectVersionEnum.V1.getVersion().equals(version.getProjectVersion()));
			if (isBeijingDesignContract) {
				companyConfig = companyConfig.stream()
					.filter(config -> ContractTypeEnum.DESIGN.getCode().intValue() == config.getContractType()).collect(Collectors.toList());
			}
		}

		return companyConfig;
	}

	private List<Byte> getContractTypeSupportSignChannelList(Byte contractType, List<Integer> offlineContractType, Map<Integer, List<Byte>> onlineContractTypeMap) {
		List<Byte> channelList = new LinkedList<>();
		if (onlineContractTypeMap.containsKey(contractType.intValue())) {
			channelList.add(SignChannelTypeEnum.ONLINE.getCode());
		}
		if (offlineContractType.contains(contractType.intValue())) {
			channelList.add(SignChannelTypeEnum.OFFLINE.getCode());
		}
		return channelList;
	}

	public Map<String, Object> contractFormField(String contractCode, String projectOrderId, Byte type, Byte signChannelType, Byte userSignType, String sourceType) {
		//处理线下模式的case
		if (signChannelType.equals(SignChannelTypeEnum.OFFLINE.getCode())) {
			userSignType = UserSignTypeEnum.DEFAULT.getCode();
		}
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		if (Objects.isNull(projectInfoDTO)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取合同类型列表失败,查询不到项目信息-[签约]");
		}
		LOGGER.info("获取项目信息：{}", projectInfoDTO);
		int gbCode = projectInfoDTO.getCustomerHouse().getGbCode();
		String companyCode = projectInfoDTO.getCustomerCommission().getCompanyCode();
		byte businessType = commonContractService.getBusinessType(projectInfoDTO);

		if (StringUtils.isBlank(companyCode)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目缺少分公司信息信息-[签约]");
		}

		//获取到该版本合同字段
		ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfig(
			projectOrderId,
			gbCode,
			companyCode,
			businessType,
			type,
			signChannelType,
			userSignType
		);

		if (Objects.isNull(config)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同缺少配置信息");
		}

		List<FieldsMapDTO> fieldList = JsonUtil.toObject(config.getFieldsMap(), new TypeReference<List<FieldsMapDTO>>() {
		});
		if (Objects.isNull(fieldList) || fieldList.isEmpty()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同缺少字段配置");
		}
		List<String> fieldsKey = fieldList.stream().map(FieldsMapDTO::getFields).collect(Collectors.toList());

		//填充默认值
		ServiceProviderDTO designer = fieldsKey.contains("designerUcId") || fieldsKey.contains("designerName") ? commonContractService.getDesignerInfo(projectOrderId) : null;
		if ((fieldsKey.contains("designerUcId") || fieldsKey.contains("designerName")) && designer == null) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "服务团队缺少设计师信息，请先分配设计师");
		}

		Map<String, Object> fieldMap = getDefaultValue(projectInfoDTO, fieldList, designer);

		//新建的情况下给默认值
		if (StringUtils.isBlank(contractCode)) {
			BaseContractDto baseContractDto = BaseContractDto.builder()
				.projectOrderId(projectOrderId)
				.type(type)
				.userSignType(userSignType)
				.signChannelType(signChannelType)
				.build();
			ContractHandlerInterface contractHandler = contractHandlerFactory.getHandler(baseContractDto);
			contractHandler.fillDefaultValue(projectOrderId, fieldMap);
		}

		//如果存在该合同，用数据库覆盖默认数据，回填
		if (StringUtils.isNotBlank(contractCode)) {
			Contract dbContract = contractService.getByContractCode(contractCode);
			//校验companyCode是否一致
			if (StringUtils.isNotBlank(dbContract.getCompanyCode()) && !dbContract.getCompanyCode().equals(projectInfoDTO.getCustomerCommission().getCompanyCode())) {
				String errMsg = String.format("合同前后分公司有变化，请作废重新发起，之前:%s, 现在:%s", dbContract.getCompanyCode(), projectInfoDTO.getCustomerCommission().getCompanyCode());
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, errMsg);
			}
			BaseContractDto baseContractDto = contractHandlerFactory.parseDbField(type, contractFieldService.getListByContractCode(contractCode));
			ObjectMapper objectMapper = new ObjectMapper();
			Map<String, Object> formatFieldMap = objectMapper.convertValue(baseContractDto, Map.class);

			//db数据覆盖默认数据
			for (String dbKey : formatFieldMap.keySet()) {
				if (fieldMap.containsKey(dbKey)) {
					fieldMap.put(dbKey, formatFieldMap.get(dbKey));
				}
			}

			//补充金额
			if (fieldMap.containsKey("amount")) {
				fieldMap.put("amount", dbContract.getAmount());
			}

			//补充线下图片
			if (fieldMap.containsKey(FieldEnum.ATTACH.getKey())) {
				fieldMap.put(FieldEnum.ATTACH.getKey(), contractAttachService.getListByContractCode(contractCode, AttachTypeEnum.OFFLINE_CONTRACT.getCode()).stream().map(ContractAttach::getUrl).collect(Collectors.toList()));
			}
		}

		// 加解密
		if ("edit".equals(sourceType) || "add".equals(sourceType)) {
			if (fieldMap.containsKey(FieldEnum.IDNO.getKey())) {
				fieldMap.put(FieldEnum.IDNO.getKey(), cipherService.decrypt((String) fieldMap.get(FieldEnum.IDNO.getKey())));
			}
			if (fieldMap.containsKey(FieldEnum.PHONE.getKey())) {
				fieldMap.put(FieldEnum.PHONE.getKey(), cipherService.decrypt((String) fieldMap.get(FieldEnum.PHONE.getKey())));
			}

		}

		//返回一些前端埋点用到的信息
		Map<String, Object> projectInfo = new HashMap<>();
		projectInfo.put(FieldEnum.COMPANY_CODE.getKey(), companyCode);
		projectInfo.put(FieldEnum.GBCODE.getKey(), projectInfoDTO.getCustomerHouse().getGbCode());
		projectInfo.put(FieldEnum.BUSINESS_TYPE.getKey(), businessType);
		fieldMap.put("projectInfo", projectInfo);
		return fieldMap;
	}

