	private Map<String, Object> getDefaultValue(ProjectInfoDTO projectInfoDTO, List<FieldsMapDTO> fieldList, ServiceProviderDTO designer) {
		//客户信息
		ProjectCustomerDTO customerSourceDataDTO = projectInfoDTO.getCustomer();
		//房屋信息
		ProjectCustomerHouseDTO customerHouseSourceDataDTO = projectInfoDTO.getCustomerHouse();
		ProjectCustomerCommissionDTO commissionDTO = projectInfoDTO.getCustomerCommission();


		Map<String, Object> map = new HashMap<>();
		for (FieldsMapDTO fieldsMapItemDto : fieldList) {
			String field = fieldsMapItemDto.getFields();
			map.put(field, null);
			switch (field) {
				case "name":
					map.put(field, customerSourceDataDTO.getName());
					break;
				case "phone":
//					map.put(field, customerSourceDataDTO.getPhone());
					break;
				case "gbCode":
					map.put(field, customerHouseSourceDataDTO.getGbCode());
					break;
				case "gbName":
					map.put(field, CityEnum.getNameByCode(customerHouseSourceDataDTO.getGbCode()));
					break;
				case "resblockId":
					map.put(field, customerHouseSourceDataDTO.getResblockId());
					break;
				case "resblockName":
					map.put(field, customerHouseSourceDataDTO.getResblockName());
					break;
				case "buildingId":
					map.put(field, customerHouseSourceDataDTO.getBuildingId());
					break;
				case "buildingName":
					map.put(field, customerHouseSourceDataDTO.getBuildingName());
					break;
				case "unitId":
					map.put(field, customerHouseSourceDataDTO.getUnitId());
					break;
				case "unitName":
					map.put(field, customerHouseSourceDataDTO.getUnitName());
					break;
				case "floorId":
					map.put(field, customerHouseSourceDataDTO.getFloorId());
					break;
				case "floorName":
					map.put(field, customerHouseSourceDataDTO.getFloorName());
					break;
				case "houseId":
					map.put(field, customerHouseSourceDataDTO.getHouseId());
					break;
				case "houseName":
					map.put(field, customerHouseSourceDataDTO.getHouseName());
					break;
				case "parlorCnt":
					map.put(field, customerHouseSourceDataDTO.getParlorCnt());
					break;
				case "roomCnt":
					map.put(field, customerHouseSourceDataDTO.getRoomCnt());
					break;
				case "cookroomCnt":
					map.put(field, customerHouseSourceDataDTO.getCookroomCnt());
					break;
				case "toiletCnt":
					map.put(field, customerHouseSourceDataDTO.getToiletCnt());
					break;
				case "area":
					map.put(field, customerHouseSourceDataDTO.getArea());
					break;
				case "designerUcId":
					map.put(field, designer.getUcId() % 100000000);
					break;
				case "designerName":
					map.put(field, designer.getName());
					break;
				case "houseType":
					map.put(field, customerHouseSourceDataDTO.getHouseType());
					break;
				case "houseTypeDesc":
					map.put(field, customerHouseSourceDataDTO.getHouseTypeDesc());
					break;
				case "houseBuildType":
					map.put(field, customerHouseSourceDataDTO.getHouseBuildType());
					break;
				case "houseBuildTypeDesc":
					map.put(field, customerHouseSourceDataDTO.getHouseBuildTypeDesc());
					break;
				case "decorateForm":
//					map.put(field, customerHouseSourceDataDTO.getDecorateType());
					map.put("decorateFormLevel1", commissionDTO.getDecorateType());
					map.put("decorateFormLevel1Text", commissionDTO.getDecorateTypeDesc());
					map.put("decorateFormLevel2", commissionDTO.getDecorateId());
					map.put("decorateFormLevel2Text", commissionDTO.getDecorateIdDesc());
					break;
				case "decorateFormDesc":
					map.put(field, customerHouseSourceDataDTO.getDecorateTypeDesc());
					break;
				default:
					break;

			}

		}
		return map;
	}

