public ContractListGroup getContractListGroup(String projectOrderId, String commissionCode, Integer fromPage) {
	ContractListGroup resGroup = new ContractListGroup();
	List<ContractListGroup.ContractGroup> groupList = new ArrayList<>();
	//并行请求整装和零售是否有合同,有合同则展示对应分组信息
	CompletableFuture<ContractListVo> decorateFuture = CompletableFuture.supplyAsync(() -> getContractList(projectOrderId, commissionCode, new ArrayList<>()), parallelRequestExecutor);
	CompletableFuture<Page<ContractDetailDTO>> retailFuture = CompletableFuture.supplyAsync(() -> {
		//如果从零售订单详情页跳转过来,则不展示零售合同分组
		if (SkipContractListSourceEnum.RETAIL_ORDER_DETAIL.getCode().equals(fromPage)) {
			return null;
		}
		//获取零售分组信息,如果有DF则直接根据DF查分组,没有DF则需要根据projectOrderId查出DE再根据DE查出所有DFs再去订单服务查
		if (StringUtils.isNotBlank(projectOrderId) && StringUtils.isBlank(commissionCode)) {
			ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
			return orderServiceRpc.retailContractListByCustomerCommissionCode(projectInfoDTO.getCustomerCommission().getCustomerCommissionCode());
		}
		return orderServiceRpc.retailContractListByDfs(Collections.singletonList(commissionCode));
	}, parallelRequestExecutor);

	ContractListVo decorateContractListVo = null;
	try {
		decorateContractListVo = decorateFuture.get();
	} catch (Exception e) {
		LOGGER.error("获取整装合同类型列表失败projectOrderId:{},commissionCode:{} ", projectOrderId, commissionCode, e);
		throw new NrsBusinessException("获取合同类型列表失败，请刷新或联系客服", Level.ERROR);
	}

	Page<ContractDetailDTO> retailContractDetailDTO = null;
	try {
		retailContractDetailDTO = retailFuture.get();
	} catch (Exception e) {
		LOGGER.error("获取零售合同类型列表失败,兼容只展示整装合同列表projectOrderId:{},commissionCode:{} ", projectOrderId, commissionCode, e);
	}

	if (CollectionUtils.isNotEmpty(decorateContractListVo.getContractListItemVos())) {
		ContractListGroup.ContractGroup decorateGroup = ContractListGroup.ContractGroup.builder()
			.key(ContractGroupEnum.DECORATE_AND_PERSONALIZE.getKey())
			.title(ContractGroupEnum.DECORATE_AND_PERSONALIZE.getTitle())
			.build();
		groupList.add(decorateGroup);
	}
	if (retailContractDetailDTO != null && CollectionUtils.isNotEmpty(retailContractDetailDTO.getList())) {
		ContractListGroup.ContractGroup retailGroup = ContractListGroup.ContractGroup.builder()
			.key(ContractGroupEnum.RETAIL.getKey())
			.title(ContractGroupEnum.RETAIL.getTitle())
			.build();
		groupList.add(retailGroup);
	}
	resGroup.setProjectOrderId(projectOrderId);
	resGroup.setGroupList(groupList);
	return resGroup;
}

