public ContractListPageVo getContractListPage(String groupKey, String projectOrderId, String commissionCode, Integer currentPage, Integer pageSize, String filterContractTypeList) {
	List<Byte> filterContractTypeListByte = new ArrayList<>();
	if (!StringUtils.isBlank(filterContractTypeList)) {
		filterContractTypeListByte = Arrays.stream(filterContractTypeList.split(",")).map(Byte::parseByte).collect(Collectors.toList());
	}
	if (ContractGroupEnum.DECORATE_AND_PERSONALIZE.getKey().equals(groupKey)) {
		//整装&整装搭售合同列表
		ContractListVo decorateContractList = getContractList(projectOrderId, commissionCode, filterContractTypeListByte);
		List<ContractListVo.ContractListItemVo> decorateContractListPage = PageUtil.paginateList(decorateContractList.getContractListItemVos(), pageSize, currentPage);
		return new ContractListPageVo(currentPage, pageSize, (long) decorateContractListPage.size(), decorateContractListPage);
	} else if (ContractGroupEnum.RETAIL.getKey().equals(groupKey)) {
		//零售合同列表
		Page<com.ke.utopia.nrs.ordercenter.dto.contract.project.ContractListVo> retailContractList;
		// 如果只传项目单号没传客源code，需要根据项目单号查询客源code
		if (StringUtils.isNotBlank(projectOrderId) && StringUtils.isBlank(commissionCode)) {
			ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
			retailContractList = contractOrderCenterRpc.queryCustomerContractListForHome(projectInfoDTO.getCustomerCommission().getCustomerCommissionCode(), currentPage, pageSize);
		} else {
			retailContractList = contractOrderCenterRpc.queryCustomerContractListForHome(Collections.singletonList(commissionCode), currentPage, pageSize);
		}
		if (retailContractList == null || CollectionUtils.isEmpty(retailContractList.getList())) {
			return new ContractListPageVo(currentPage, pageSize, 0L, new ArrayList<>());
		}
		List<com.ke.utopia.nrs.ordercenter.dto.contract.project.ContractListVo> retailContractListVo = retailContractList.getList();
		List<Byte> finalFilterContractTypeListByte = filterContractTypeListByte;
		if (CollectionUtils.isNotEmpty(filterContractTypeListByte)) {
			//根据合同类型过滤
			retailContractListVo = retailContractList.getList().stream().filter(contractVoForHome -> finalFilterContractTypeListByte.contains(contractVoForHome.getType())).collect(Collectors.toList());
		}
		List<ContractListVo.ContractListItemVo> contractList = retailContractListVo.stream().map(contractVoForHome -> {
			ContractListVo.ContractListItemVo contractListItemVo = new ContractListVo.ContractListItemVo();
			BeanUtils.copyProperties(contractVoForHome, contractListItemVo);
			if (contractVoForHome.getTipsInfo() != null) {
				ContractListVo.TipsInfo tipsInfo = new ContractListVo.TipsInfo();
				BeanUtils.copyProperties(contractVoForHome.getTipsInfo(), tipsInfo);
				contractListItemVo.setTipsInfo(tipsInfo);
			}
			return contractListItemVo;
		}).collect(Collectors.toList());
		return new ContractListPageVo(currentPage, pageSize, (long) contractList.size(), contractList);
	}
	return null;
}

