public ContractListVo getContractList(String projectOrderId, String customerCommissionCode, List<Byte> filterContractTypeList) {
	ContractListVo contractListVo = ContractListVo.builder().contractListItemVos(new ArrayList<>()).build();
	//如果项目id为空，零售客源code不为空，则根据零售客源code找到对应的项目信息
	ProjectInfoDTO projectInfoDTO = getProjectInfo(projectOrderId, customerCommissionCode);
	if (projectInfoDTO == null || StringUtils.isBlank(projectInfoDTO.getProjectOrderId())) {
		return contractListVo;
	}
	// 查询协同项目和整装存在个性化合同不返回billCode和havePersonalQuote
	CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectInfoDTO.getProjectOrderId());
	projectOrderId = coordinationProjectOrder.getProjectOrderId();
	String convertProjectOrderId = projectInfoDTO.getProjectOrderId();
	byte businessType = commonContractService.getBusinessType(projectInfoDTO);
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(convertProjectOrderId);
	contractListVo.setAddress(homeAndPcCommonService.getSafeAddress(projectInfoDTO));
	contractListVo.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));
	contractListVo.setBusinessType(businessType);
	List<Contract> contractList = contractService.getContractList(coordinationProjectOrder.getProjectOrderId());
	List<Contract> previousOrderContractList = commonContractService.getPreviousOrderContractList(coordinationProjectOrder.getProjectOrderId());
	contractList.addAll(previousOrderContractList);
	contractListVo.setProcessV25(processV25);

	if (contractList.isEmpty()) {
		return contractListVo;
	}
	List<String> contractCodes = contractList.stream().map(Contract::getContractCode).collect(Collectors.toList());
	List<CancelOrderBaseInfoDTO> cancelOrderBaseInfoDTOS = cancelOrderRecordService.getListByProjectOrderId(projectOrderId);
	//key：合同code，value：关联退单流程版本
	Map<String, Integer> cancelOrderMap = cancelOrderBaseInfoDTOS.stream().collect(Collectors.toMap(CancelOrderBaseInfoDTO::getContractCode, CancelOrderBaseInfoDTO::getFlowVersion, (k1, k2) -> k1));
	Set<String> terminalContractCode = cancelOrderMap.keySet();
	//用户确认节点列表
	List<ContractNode> userConfirmNodeList = contractNodeService.getListByContractCodesAndType(contractCodes, Collections.singletonList(NodeTypeEnum.USER_CONFIRM.getCode()));
	if (CollectionUtils.isNotEmpty(filterContractTypeList)) {
		contractList = contractList.stream().filter(contract -> filterContractTypeList.contains(contract.getType())).collect(Collectors.toList());
	}
	List<ContractListVo.ContractListItemVo> contractItemVoList = new LinkedList<>();


	ParallelTasksContext parallelQueryAuditProcessInfoTask = parallelTaskService.newParallelTasks();
	for (Contract contract : contractList) {
		//已取消的团装合同不展示
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType()) && ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus()) && ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType())) {
			continue;
		}
		// 已作废的个性化合同合同不展示
		if (ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus()) && ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			continue;
		}
		// 过滤不可查看合同
		if (ContractTypeEnum.getNoVisibleContractTypes().contains(contract.getType())) {
			continue;
		}
		String bpmUrl = pcContractService.getBpmUrl(contract.getBmpNo());
		List<String> attachUrlList = commonService.getAttachUrl(contract);

		ContractField goodsInfo = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), "goodsInfo");
		//合同列表项
		Integer authStatus = homeAndPcCommonService.getAuthStatus(contract.getRelateContractCode());
		//绑定单据列表
		BindOrderInfoGroup group = quotationRelationCommonService.getBindOrderInfoGroupByContractCode(contract.getContractCode());
		ContractListVo.ContractListItemVo vo = ContractListVo.ContractListItemVo.builder()
			.id(contract.getId())
			.contractCode(contract.getContractCode())
			.projectOrderId(contract.getProjectOrderId())
			.changeOrderId(contract.getChangeOrderId())
			.type(contract.getType())
			.typeName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
			.status(contract.getStatus())
			.statusText(homeAndPcCommonService.getContractStateText(contract))
			.signChannelType(contract.getSignChannelType())
			.userSignType(contract.getUserSignType())
			.userConfirmStatus(contract.getUserConfirmStatus())
			.infoList(getContractListItemInfos(contract, authStatus))
			.buttonList(getButtonList(contract, attachUrlList, contractList, userConfirmNodeList, terminalContractCode))
			.bpmNo(contract.getBmpNo())
			.bpmUrl(bpmUrl)
			.contractUrl(commonService.getContractUrl(contract))
			.attachUrl(attachUrlList)
			.waitAuth(homeAndPcCommonService.isWaitAuth(contract))
			.authStatus(authStatus)
			.errorMessage(homeAndPcCommonService.getContractErrorMessage(contract))
			.estimatedLaunchTime(ContractTypeEnum.getEnumByCode(contract.getType()).getEstimatedLaunchTime())
			.contractMode(commonContractService.getContractModeByContractCode(contract.getContractCode()))
			.billCodeList(BillCodeInfo.getBillCodeList(group.getBillCodeInfos()))
			.billCodeInfoList(group.getBillCodeInfos())
			.subOrderInfoList(group.getSubOrderInfos())
			.changeOrderInfoList(group.getChangeOrderInfos())
			.goodsInfo(ObjectUtil.isNotEmpty(goodsInfo) ? goodsInfo.getFieldValue() : null)
			.flowVersion(ContractTypeEnum.TERMINAL.getCode().equals(contract.getType()) ? cancelOrderMap.getOrDefault(contract.getContractCode(), CancelOrderVersionEnum.ONE.getValue()) : null)
			.build();
		vo.setAttachFileType(contractBusinessService.getAttachFileKey(vo.getAttachUrl()));
		//原服务解约协议名称需特殊展示
		if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType()) && !projectOrderId.equals(contract.getProjectOrderId())) {
			vo.setTypeName("原服务解约协议");
		}

		//关联合同处理 B合同与C合同
		if (processV25 && (contract.getType().equals(ContractTypeEnum.PACKAGE_FORMAL.getCode())
			|| contract.getType().equals(ContractTypeEnum.PERSONAL.getCode())
			|| ContractTypeEnum.DESIGN.getCode().equals(contract.getType()))) {
			List<RelateContract> relateContractList = homeAndPcCommonService.getRelateContractList(contract);
			vo.setRelateContracts(relateContractList);
			ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
			vo.setPrimaryRelatedContractCode(contractRelation != null ? contractRelation.getContractCode() : null);
		}
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
			vo.setUploadStatus(pcContractService.checkAttach(contract.getContractCode()));
			vo.setUserSignStatus(contract.getUserSignStatus());
			if (processV25 && BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType())) {
				vo.setProjectChangeNo(homeAndPcCommonService.getProjectChangeNo(projectOrderId));
			}
			if (!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
				vo.setAuditStatus(pcContractService.getLastAuditInfo(contract.getContractCode()) == null ? null : pcContractService.getLastAuditInfo(contract.getContractCode()).getAuditStatus());
			}

			// 组装风控审核信息
			parallelTaskService.addNewTask(parallelQueryAuditProcessInfoTask, () ->
				vo.setProcessInfo(contractDetailService.buildProcessInfoDetail(contract)));
			parallelTaskService.execTasks(parallelQueryAuditProcessInfoTask);
		}
		if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			ContractRelation relateContractCode = contractRelationService.getByRelateContractCode(contract.getContractCode());
			vo.setMergeLaunch(relateContractCode != null);
		}
		contractItemVoList.add(vo);
	}
	if (processV25) {
		contractItemVoList = sortContractListItemVo(contractItemVoList, projectOrderId, businessType);
	}

	// 等待并行结果
	parallelTaskService.awaitTasksResult(parallelQueryAuditProcessInfoTask);

	contractListVo.setContractListItemVos(contractItemVoList);
	return contractListVo;
}

