private ProjectInfoDTO getProjectInfo(String projectOrderId, String commissionCode) {
	ProjectInfoDTO projectInfoDTO = null;
	if (StringUtils.isBlank(projectOrderId) && StringUtils.isNotBlank(commissionCode)) {
		CustomerInfo customerInfo = customerRpc.getDecorateCodeByCustomerCode(commissionCode);
		String decorateCodeByCustomerCode = customerInfo.getCustomerCommission().getDecorateCommissionCode();
		if (StringUtils.isNotBlank(decorateCodeByCustomerCode)) {
			projectInfoDTO = projectInfoReadService.getByCustomerCommissionCode(decorateCodeByCustomerCode);
		} else {
			// 查询零售客源
			projectInfoDTO = buildProjectInfoByFurnitureCommissionCode(commissionCode);
			ProjectInfo byCustomerCommissionCode = projectInfoService.getByCustomerCommissionCode(commissionCode);
			if (ObjectUtil.isNotEmpty(projectInfoDTO) && ObjectUtil.isNotEmpty(byCustomerCommissionCode)) {
				projectInfoDTO.setProjectOrderId(byCustomerCommissionCode.getProjectOrderId());
			}
		}
		//else 为纯零售，不返回项目信息
	} else {
		projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
	}
	return projectInfoDTO;
}

