public ContractTypeListVo getContractTypeList(String projectOrderId, String commissionCode, String contractTypeList, Integer sceneType) {
	List<Byte> contractTypeListByte = new ArrayList<>();
	if (!StringUtils.isBlank(contractTypeList)) {
		contractTypeListByte = Arrays.stream(contractTypeList.split(",")).map(Byte::parseByte).collect(Collectors.toList());
	}
	List<Byte> finalContractTypeListByte = contractTypeListByte;
	CompletableFuture<ContractTypeListVo> decorateFuture = CompletableFuture.supplyAsync(() -> getDecorateContractTypeList(projectOrderId, commissionCode, finalContractTypeListByte, sceneType), parallelRequestExecutor);
	CompletableFuture<List<ContractTypeListVo.ContractTypeListItemVo>> retailFuture = CompletableFuture.supplyAsync(() -> getRetailTypeList(commissionCode, finalContractTypeListByte, sceneType), parallelRequestExecutor);

	try {
		ContractTypeListVo contractTypeListVo =  decorateFuture.thenCombine(retailFuture, (decorate, retail) -> {
			if (CollectionUtils.isEmpty(decorate.getContractTypeListItemVos())) {
				decorate.setContractTypeListItemVos(retail);
			} else {
				decorate.getContractTypeListItemVos().addAll(retail);
			}
			return decorate;
		}).join();
		contractTypeListVo.setContractAgentOpen(commonContractService.contractAgentOpen(projectOrderId));
		return contractTypeListVo;
	} catch (CompletionException e) {
		Throwable cause = e.getCause();
		LOGGER.error("获取合同类型列表失败projectOrderId:{},commissionCode:{} ", projectOrderId, commissionCode, e);
		if (cause instanceof NrsBusinessException) {
			throw (NrsBusinessException) cause;
		} else {
			throw new NrsBusinessException("获取合同类型列表失败，请刷新或联系客服", Level.ERROR);
		}
	} catch (NrsBusinessException e) {
		throw e;
	} catch (Exception e) {
		LOGGER.error("获取合同类型列表失败projectOrderId:{},commissionCode:{} ", projectOrderId, commissionCode, e);
		throw new NrsBusinessException("获取合同类型列表失败，请刷新或联系客服", Level.ERROR);
	}
}

