public ContractTypeListVo getDecorateContractTypeList(String projectOrderId, String commissionCode, List<Byte> contractTypeList, Integer sceneType) {
	if (ObjectUtil.isEmpty(sceneType)) {
		sceneType = ContractShowSceneTypeEnum.ALL_AND_RETAIL.getCode();
	}
	ContractTypeListVo vo = new ContractTypeListVo();
	ProjectInfoDTO projectInfoDTO = getProjectInfo(projectOrderId, commissionCode);
	if (projectInfoDTO == null) {
		return vo;
	}
	byte businessType = commonBusinessService.getBusinessType(projectOrderId);
	vo.setAddress(homeAndPcCommonService.getSafeAddress(projectInfoDTO));
	vo.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));
	vo.setCompanyCode(projectInfoDTO.getCustomerCommission().getCompanyCode());
	vo.setGbCode(projectInfoDTO.getCustomerHouse().getGbCode());
	vo.setBusinessType(businessType);
	if (ObjectUtil.isEmpty(vo.getCompanyCode())) {
		throw new NrsBusinessException("订单未分配分公司，获取合同列表失败", Level.WARN);
	}
	List<ContractTypeListVo.ContractTypeListItemVo> contractTypeListItemVos = new LinkedList<>();
	if (ObjectUtil.isEmpty(projectInfoDTO.getProjectOrderId())) {
		return vo;
	}
	CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectInfoDTO.getProjectOrderId());
	projectOrderId = coordinationProjectOrder.getProjectOrderId();
	if (StringUtils.isBlank(projectOrderId)) {
		return vo;
	}

	//读取分公司配置
	List<ContractCityCompanyInfo> companyConfig = getCreatableContractList(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), projectInfoDTO.getCustomerCommission().getCompanyCode(), businessType);
	ContractProcessModeChangeInfo contractProcessModeChangeInfo = formalReSignService.getContractProcessModeChangeInfo(projectOrderId);
	String convertProjectOrderId = null;
	if (HomeWorkflowTypeEnum.RETAIL.getType().equals(coordinationProjectOrder.getHomeWorkflowType())) {
		convertProjectOrderId = coordinationProjectOrder.getRetailProjectOrder().getProjectOrderId();
	} else {
		convertProjectOrderId = coordinationProjectOrder.getDecorateProjectOrder().getProjectOrderId();
	}
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(convertProjectOrderId);
	vo.setProcessV25(processV25);
	vo.setSupportFullServiceSign(commonContractService.supportFullServiceSign(projectInfoDTO.getCustomerHouse().getGbCode(),businessType));
	vo.setFormalUseNewProcess(contractBusinessService.formalUseNewProcess(businessType, processV25, projectInfoDTO.getCustomerHouse().getGbCode()));
	//从Apollo获取home端可以创建的列表和不可创建的列表
	List<Byte> createContractList = contractApolloConfig.createContractList(convertProjectOrderId, businessType, AppIdEnum.HOME.getAppId(), projectInfoDTO.getCustomerHouse().getGbCode());
	List<Byte> cannotCreateContractList = contractApolloConfig.cannotCreateContractList(convertProjectOrderId, businessType, AppIdEnum.HOME.getAppId(), projectInfoDTO.getCustomerHouse().getGbCode());

	//支持线下的合同类型
	List<Integer> offlineContractType = new ArrayList<>();
	//线上支持的类型
	Map<Integer, List<Byte>> onlineContractTypeMap = new HashMap<>();
	for (ContractCityCompanyInfo contractCityCompanyInfo : companyConfig) {
		if (SignChannelTypeEnum.ONLINE.getCode().equals(contractCityCompanyInfo.getSignChannelType())) {
			if (!onlineContractTypeMap.containsKey(contractCityCompanyInfo.getContractType())) {
				onlineContractTypeMap.put(contractCityCompanyInfo.getContractType(), new LinkedList<>());
			}
			List<Byte> userSignTypes = Arrays.stream(contractCityCompanyInfo.getUserSignType().split(",")).map(Byte::parseByte).collect(Collectors.toList());
			onlineContractTypeMap.get(contractCityCompanyInfo.getContractType()).addAll(userSignTypes);
		} else if (SignChannelTypeEnum.OFFLINE.getCode().equals(contractCityCompanyInfo.getSignChannelType())) {
			offlineContractType.add(contractCityCompanyInfo.getContractType());
		}
	}

	// 支持创建的合同列表
	List<Byte> contractTypeEnums = new ArrayList<>();
	// 根据场景下发不同的合同
	if (ContractShowSceneTypeEnum.ALL_AND_RETAIL.getCode().equals(sceneType) || ContractShowSceneTypeEnum.ALL.getCode().equals(sceneType)) {
		if (coordinationProjectOrder.hasDecorateProjectOrder()) {
			contractTypeEnums = Arrays.stream(ContractTypeEnum.values())
				.sorted(Comparator.comparing(ContractTypeEnum::getOrder)).map(ContractTypeEnum::getCode).collect(Collectors.toList());
		} else {
			//纯零售仅返回个性化相关的合同
			contractTypeEnums = ContractTypeEnum.getPersonalizedRelevantContractList();
		}
	} else if (ContractShowSceneTypeEnum.WHOLE.getCode().equals(sceneType)) {
		if (coordinationProjectOrder.hasDecorateProjectOrder()) {
			contractTypeEnums = ContractTypeEnum.WHOLE_CONTRACT;
		} else {
			contractTypeEnums = new ArrayList<>();
		}
	} else if (ContractShowSceneTypeEnum.RETAIL.getCode().equals(sceneType)) {
		contractTypeEnums = ContractTypeEnum.getPersonalizedRelevantContractList();
	}
	// 过滤指定创建的合同
	if (CollectionUtils.isNotEmpty(contractTypeList)) {
		contractTypeEnums = contractTypeEnums.stream().filter(contractTypeList::contains).collect(Collectors.toList());
	}
	for (Byte contractType : contractTypeEnums) {
		ContractTypeEnum contractTypeEnum = ContractTypeEnum.getEnumByCode(contractType);
		ContractTypeListVo.ContractTypeListItemVo contractTypeListItemVo = null;
		List<Contract> contractList = contractService.getContractList(projectOrderId, contractTypeEnum.getCode()).stream()
			.filter(item -> ContractStatusEnum.inPositiveStatus.contains(item.getStatus()))
			.collect(Collectors.toList());
		//可创建的合同类型
		if (createContractList.contains(contractTypeEnum.getCode())) {
			contractTypeListItemVo = new ContractTypeListVo.ContractTypeListItemVo(contractTypeEnum, businessType);
			if (CollectionUtils.isNotEmpty(contractList)) {
				contractTypeListItemVo.setState(ContractShowEnum.CREATED.getCode());
				contractTypeListItemVo.setStateText(ContractShowEnum.CREATED.getName());
			} else {
				// 初始化创建按钮
				initContractCreateState(contractTypeListItemVo, onlineContractTypeMap, contractTypeEnum, offlineContractType);
			}
			//C合同始终支持创建,通过Apollo开关实现上线兼容
			if (ContractTypeEnum.PERSONAL.getCode().equals(contractType) && contractApolloConfig.getCheckPersonalContract()) {
				initContractCreateState(contractTypeListItemVo, onlineContractTypeMap, contractTypeEnum, offlineContractType);
				contractTypeListItemVo.setStateText("");
			}
			// 补充协议按钮
			if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractType)) {
				// 如果补充协议未开城，则不展示补充协议卡片
				if (Boolean.FALSE.equals(contractUnifyService.supplementIsOpen(convertProjectOrderId))) {
					continue;
				}
				// 开城后，恒展示【去创建】按钮
				initContractCreateState(contractTypeListItemVo, onlineContractTypeMap, contractTypeEnum, offlineContractType);
			}
			// 和解协议按钮
			if (ContractTypeEnum.SETTLEMENT.getCode().equals(contractType)) {
				if (Boolean.FALSE.equals(contractUnifyService.settlementIsOpen(convertProjectOrderId))) {
					// 如果和解协议未开城，则不展示和解协议卡片
					continue;
				}
				// 开城后，恒展示【去创建】按钮
				initContractCreateState(contractTypeListItemVo, onlineContractTypeMap, contractTypeEnum, offlineContractType);
			}
		}
		//不可创建的合同类型
		if (cannotCreateContractList.contains(contractTypeEnum.getCode())) {
			contractTypeListItemVo = new ContractTypeListVo.ContractTypeListItemVo(contractTypeEnum, businessType);
			contractTypeListItemVo.setState(ContractShowEnum.CANNOT_CREATE.getCode());
			//对于变更合同:不是团装,下发stateText
			if (BusinessTypeEnum.GROUP_DECORATE.getCode() != businessType && contractTypeEnum.getCode().equals(ContractTypeEnum.PACKAGE_CHANGE.getCode())) {
				contractTypeListItemVo.setStateText(contractTypeEnum.getRefuseCreateTipH5());
			}
			contractTypeListItemVo.setExtraDesc(ContractTypeEnum.getExtraDescByContractTypeAndBusinessType(contractTypeEnum.getCode(), businessType));
		}
		if (ObjectUtil.isEmpty(contractTypeListItemVo)) {
			continue;
		}
		//2.5正式套餐合同名字处理
		if (vo.isProcessV25() && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			contractTypeListItemVo.setTypeName(contractTypeListItemVo.getTypeName().concat("及图纸"));
		}
		//2.5正式套餐合同名字处理
		if (vo.isProcessV25() && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
			boolean hasUploadFormalDrawing = contractBusinessService.hasUploadFormalDrawing(true, businessType, projectOrderId);
			String typeName = hasUploadFormalDrawing ? contractTypeListItemVo.getTypeName().concat("及图纸") : contractTypeListItemVo.getTypeName();
			contractTypeListItemVo.setTypeName(typeName);
		}
		if (ObjectUtil.isNotEmpty(contractTypeListItemVo)) {
			contractTypeListItemVos.add(contractTypeListItemVo);
		}
		//2.0->2.5历史正式套餐合同处理
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractTypeEnum.getCode()) && contractTypeListItemVo != null
			&& ContractShowEnum.CREATED.getCode().equals(contractTypeListItemVo.getState())
			&& formalReSignService.newFormalContractCanLaunch(contractProcessModeChangeInfo)) {
			initContractCreateState(contractTypeListItemVo, onlineContractTypeMap, contractTypeEnum, offlineContractType);
		}
	}
	vo.setContractTypeListItemVos(contractTypeListItemVos);
	vo.setFormalReSignInfo(formalReSignService.getFormalReSignInfo(contractProcessModeChangeInfo));
	return vo;
}

