private List<ContractCityCompanyInfo> getCreatableContractList(String projectOrderId, Integer gbCode, String companyCode, Byte businessType) {
	companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectOrderId, gbCode, companyCode, ContractTypeEnum.PACKAGE_FORMAL.getCode());
	List<ContractCityCompanyInfo> companyConfig = contractCityCompanyConfigService.getConfig(projectOrderId, gbCode, companyCode, businessType);
	// 兼容北京1.0设计合同
	if (CityEnum.BEIJING.getGbCode() == gbCode) {
		List<ProjectVersionDTO> projectVersionDTOS = projectInfoReadService.batchProjectVersion(Collections.singletonList(projectOrderId));
		boolean isBeijingDesignContract = projectVersionDTOS.stream().anyMatch(version -> ProjectVersionEnum.V1.getVersion().equals(version.getProjectVersion()));
		if (isBeijingDesignContract) {
			companyConfig = companyConfig.stream()
				.filter(config -> ContractTypeEnum.DESIGN.getCode().intValue() == config.getContractType()).collect(Collectors.toList());
		}
	}

	return companyConfig;
}

private List<Byte> getContractTypeSupportSignChannelList(Byte contractType, List<Integer> offlineContractType, Map<Integer, List<Byte>> onlineContractTypeMap) {
	List<Byte> channelList = new LinkedList<>();
	if (onlineContractTypeMap.containsKey(contractType.intValue())) {
		channelList.add(SignChannelTypeEnum.ONLINE.getCode());
	}
	if (offlineContractType.contains(contractType.intValue())) {
		channelList.add(SignChannelTypeEnum.OFFLINE.getCode());
	}
	return channelList;
}

public Map<String, Object> contractFormField(String contractCode, String projectOrderId, Byte type, Byte signChannelType, Byte userSignType, String sourceType) {
	//处理线下模式的case
	if (signChannelType.equals(SignChannelTypeEnum.OFFLINE.getCode())) {
		userSignType = UserSignTypeEnum.DEFAULT.getCode();
	}
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
	if (Objects.isNull(projectInfoDTO)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取合同类型列表失败,查询不到项目信息-[签约]");
	}
	LOGGER.info("获取项目信息：{}", projectInfoDTO);
	int gbCode = projectInfoDTO.getCustomerHouse().getGbCode();
	String companyCode = projectInfoDTO.getCustomerCommission().getCompanyCode();
	byte businessType = commonContractService.getBusinessType(projectInfoDTO);

	if (StringUtils.isBlank(companyCode)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目缺少分公司信息信息-[签约]");
	}

	//获取到该版本合同字段
	ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfig(
		projectOrderId,
		gbCode,
		companyCode,
		businessType,
		type,
		signChannelType,
		userSignType
	);

	if (Objects.isNull(config)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同缺少配置信息");
	}

	List<FieldsMapDTO> fieldList = JsonUtil.toObject(config.getFieldsMap(), new TypeReference<List<FieldsMapDTO>>() {
	});
	if (Objects.isNull(fieldList) || fieldList.isEmpty()) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同缺少字段配置");
	}
	List<String> fieldsKey = fieldList.stream().map(FieldsMapDTO::getFields).collect(Collectors.toList());

	//填充默认值
	ServiceProviderDTO designer = fieldsKey.contains("designerUcId") || fieldsKey.contains("designerName") ? commonContractService.getDesignerInfo(projectOrderId) : null;
	if ((fieldsKey.contains("designerUcId") || fieldsKey.contains("designerName")) && designer == null) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "服务团队缺少设计师信息，请先分配设计师");
	}

	Map<String, Object> fieldMap = getDefaultValue(projectInfoDTO, fieldList, designer);

	//新建的情况下给默认值
	if (StringUtils.isBlank(contractCode)) {
		BaseContractDto baseContractDto = BaseContractDto.builder()
			.projectOrderId(projectOrderId)
			.type(type)
			.userSignType(userSignType)
			.signChannelType(signChannelType)
			.build();
		ContractHandlerInterface contractHandler = contractHandlerFactory.getHandler(baseContractDto);
		contractHandler.fillDefaultValue(projectOrderId, fieldMap);
	}

	//如果存在该合同，用数据库覆盖默认数据，回填
	if (StringUtils.isNotBlank(contractCode)) {
		Contract dbContract = contractService.getByContractCode(contractCode);
		//校验companyCode是否一致
		if (StringUtils.isNotBlank(dbContract.getCompanyCode()) && !dbContract.getCompanyCode().equals(projectInfoDTO.getCustomerCommission().getCompanyCode())) {
			String errMsg = String.format("合同前后分公司有变化，请作废重新发起，之前:%s, 现在:%s", dbContract.getCompanyCode(), projectInfoDTO.getCustomerCommission().getCompanyCode());
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, errMsg);
		}
		BaseContractDto baseContractDto = contractHandlerFactory.parseDbField(type, contractFieldService.getListByContractCode(contractCode));
		ObjectMapper objectMapper = new ObjectMapper();
		Map<String, Object> formatFieldMap = objectMapper.convertValue(baseContractDto, Map.class);

		//db数据覆盖默认数据
		for (String dbKey : formatFieldMap.keySet()) {
			if (fieldMap.containsKey(dbKey)) {
				fieldMap.put(dbKey, formatFieldMap.get(dbKey));
			}
		}

		//补充金额
		if (fieldMap.containsKey("amount")) {
			fieldMap.put("amount", dbContract.getAmount());
		}

		//补充线下图片
		if (fieldMap.containsKey(FieldEnum.ATTACH.getKey())) {
			fieldMap.put(FieldEnum.ATTACH.getKey(), contractAttachService.getListByContractCode(contractCode, AttachTypeEnum.OFFLINE_CONTRACT.getCode()).stream().map(ContractAttach::getUrl).collect(Collectors.toList()));
		}
	}

	// 加解密
	if ("edit".equals(sourceType) || "add".equals(sourceType)) {
		if (fieldMap.containsKey(FieldEnum.IDNO.getKey())) {
			fieldMap.put(FieldEnum.IDNO.getKey(), cipherService.decrypt((String) fieldMap.get(FieldEnum.IDNO.getKey())));
		}
		if (fieldMap.containsKey(FieldEnum.PHONE.getKey())) {
			fieldMap.put(FieldEnum.PHONE.getKey(), cipherService.decrypt((String) fieldMap.get(FieldEnum.PHONE.getKey())));
		}

	}

	//返回一些前端埋点用到的信息
	Map<String, Object> projectInfo = new HashMap<>();
	projectInfo.put(FieldEnum.COMPANY_CODE.getKey(), companyCode);
	projectInfo.put(FieldEnum.GBCODE.getKey(), projectInfoDTO.getCustomerHouse().getGbCode());
	projectInfo.put(FieldEnum.BUSINESS_TYPE.getKey(), businessType);
	fieldMap.put("projectInfo", projectInfo);
	return fieldMap;
}

	private Map<String, Object> getDefaultValue(ProjectInfoDTO projectInfoDTO, List<FieldsMapDTO> fieldList, ServiceProviderDTO designer) {
		//客户信息
		ProjectCustomerDTO customerSourceDataDTO = projectInfoDTO.getCustomer();
		//房屋信息
		ProjectCustomerHouseDTO customerHouseSourceDataDTO = projectInfoDTO.getCustomerHouse();
		ProjectCustomerCommissionDTO commissionDTO = projectInfoDTO.getCustomerCommission();


		Map<String, Object> map = new HashMap<>();
		for (FieldsMapDTO fieldsMapItemDto : fieldList) {
			String field = fieldsMapItemDto.getFields();
			map.put(field, null);
			switch (field) {
				case "name":
					map.put(field, customerSourceDataDTO.getName());
					break;
				case "phone":
//					map.put(field, customerSourceDataDTO.getPhone());
					break;
				case "gbCode":
					map.put(field, customerHouseSourceDataDTO.getGbCode());
					break;
				case "gbName":
					map.put(field, CityEnum.getNameByCode(customerHouseSourceDataDTO.getGbCode()));
					break;
				case "resblockId":
					map.put(field, customerHouseSourceDataDTO.getResblockId());
					break;
				case "resblockName":
					map.put(field, customerHouseSourceDataDTO.getResblockName());
					break;
				case "buildingId":
					map.put(field, customerHouseSourceDataDTO.getBuildingId());
					break;
				case "buildingName":
					map.put(field, customerHouseSourceDataDTO.getBuildingName());
					break;
				case "unitId":
					map.put(field, customerHouseSourceDataDTO.getUnitId());
					break;
				case "unitName":
					map.put(field, customerHouseSourceDataDTO.getUnitName());
					break;
				case "floorId":
					map.put(field, customerHouseSourceDataDTO.getFloorId());
					break;
				case "floorName":
					map.put(field, customerHouseSourceDataDTO.getFloorName());
					break;
				case "houseId":
					map.put(field, customerHouseSourceDataDTO.getHouseId());
					break;
				case "houseName":
					map.put(field, customerHouseSourceDataDTO.getHouseName());
					break;
				case "parlorCnt":
					map.put(field, customerHouseSourceDataDTO.getParlorCnt());
					break;
				case "roomCnt":
					map.put(field, customerHouseSourceDataDTO.getRoomCnt());
					break;
				case "cookroomCnt":
					map.put(field, customerHouseSourceDataDTO.getCookroomCnt());
					break;
				case "toiletCnt":
					map.put(field, customerHouseSourceDataDTO.getToiletCnt());
					break;
				case "area":
					map.put(field, customerHouseSourceDataDTO.getArea());
					break;
				case "designerUcId":
					map.put(field, designer.getUcId() % 100000000);
					break;
				case "designerName":
					map.put(field, designer.getName());
					break;
				case "houseType":
					map.put(field, customerHouseSourceDataDTO.getHouseType());
					break;
				case "houseTypeDesc":
					map.put(field, customerHouseSourceDataDTO.getHouseTypeDesc());
					break;
				case "houseBuildType":
					map.put(field, customerHouseSourceDataDTO.getHouseBuildType());
					break;
				case "houseBuildTypeDesc":
					map.put(field, customerHouseSourceDataDTO.getHouseBuildTypeDesc());
					break;
				case "decorateForm":
//					map.put(field, customerHouseSourceDataDTO.getDecorateType());
					map.put("decorateFormLevel1", commissionDTO.getDecorateType());
					map.put("decorateFormLevel1Text", commissionDTO.getDecorateTypeDesc());
					map.put("decorateFormLevel2", commissionDTO.getDecorateId());
					map.put("decorateFormLevel2Text", commissionDTO.getDecorateIdDesc());
					break;
				case "decorateFormDesc":
					map.put(field, customerHouseSourceDataDTO.getDecorateTypeDesc());
					break;
				default:
					break;

			}

		}
		return map;
	}

