public Boolean applyStamp(String contractCode, String customerName, Byte certificateType, String certificateNo) {

	//签约人身份证号有x，小写转大写
	if (CertificateTypeEnum.ID.getCode().equals(certificateType)) {
		certificateNo = certificateNo.toUpperCase();
	}
	Contract contract = contractService.getByContractCode(contractCode);
	if (Objects.isNull(contract)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "申请用章，合同不存在-[签约]");
	}
	if (!contract.getStatus().equals(ContractStatusEnum.USER_CONFIRMED.getCode())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "非待业主确认下，不可以申请用章-[签约]");
	}

	//校验信息一致性 - 只有身份证才去校验一致性
	if (CertificateTypeEnum.ID.getCode().equals(certificateType)) {
		if (!authFeignService.authTwo(certificateNo, customerName)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "姓名与身份证号不一致，请核对后重试");
		}
	}
	//判断当前类型是否支持盖章
	ContractCityCompanyInfo signConfig = contractCityCompanyConfigService.getConfig(
		contract.getProjectOrderId(),
		contract.getGbCode(),
		contract.getCompanyCode(),
		contract.getBusinessType(),
		contract.getType(),
		SignChannelTypeEnum.ONLINE.getCode(),
		UserSignTypeEnum.SIGN.getCode());
	if (Objects.isNull(signConfig)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "申请用章失败，当前合同类型不支持申请用章");
	}

	//更新签约人姓名、证件类型、证件号
	ContractUser signer = contractUserService.getSignerByContractCode(contractCode);
	if (Objects.isNull(signer)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "申请用章失败，缺少签约人信息-[签约]");
	}

	//校验跟之前信息的一致性
	if (!customerName.equals(signer.getName())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "申请用章失败，本次姓名跟之前姓名不一致-[签约]");
	}

	//更新证件信息
	signer.setCertificateNo(certificateNo);
	signer.setCertificateType(certificateType);

	//更新合同信息
	contract.setUserSignType(UserSignTypeEnum.SIGN.getCode());
	contract.setStatus(ContractStatusEnum.PENDING_USER_SIGN.getCode());

	//更新合同字段表，覆盖姓名&身份证号
	contractFieldService.updateOrCreateFieldValue(contractCode, "name", customerName);
	contractFieldService.updateOrCreateFieldValue(contractCode, FieldEnum.CERTIFICATE_TYPE.getKey(), certificateType.toString());

	ContractField idNoField = ContractField.builder()
		.contractCode(contractCode)
		.fieldKey("idNo")
		.fieldValue(cipherService.encrypt(certificateNo))
		.build();
	contractFieldService.save(idNoField);

	contractService.update(contract);
	contractUserService.update(signer);

	//记录日志&发送事件
	Map<String, String> logContent = new HashMap<>();
	logContent.put("customerName", customerName);
	logContent.put("certificateNo", certificateNo);
	logContent.put("certificateType", certificateType.toString());
	contractLogService.createLog(contractCode, LogTypeEnum.APPLY_SEAL.getCode(), LogTypeEnum.APPLY_SEAL.getName(), logContent.toString());
	contractLogService.createLog(contractCode, LogTypeEnum.STATUS_CHANGE.getCode(), LogTypeEnum.STATUS_CHANGE.getName(), contract.getStatus().toString());
	eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_APPLY_SEAL, contractCode);

	return true;
}

