public SubmitResultVo submit(Map<String, Object> contractFieldMap, Long createUserId) {
	SubmitResultVo result = new SubmitResultVo();
	BaseContractDto baseContractDto = commonContractService.convert(contractFieldMap);
	baseContractDto.setCreateUserId(createUserId.toString());

	String lockKey = "";
	if (StringUtils.isNotBlank(baseContractDto.getContractCode())) {
		lockKey = baseContractDto.getContractCode();
	} else if (StringUtils.isNotBlank(baseContractDto.getProjectOrderId())) {
		lockKey = baseContractDto.getProjectOrderId() + "_" + baseContractDto.getType();
	}

	//抢占锁，防止多次提交
	RLock lock = redissonClient.getLock("submit_contract:" + lockKey);
	try {
		if (!lock.tryLock(0L, 60L, TimeUnit.SECONDS)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请勿短时间内多次提交");
		}
	} catch (Exception e) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请勿短时间内多次提交");
	}

	try {
		ContractHandlerInterface contractHandler = contractHandlerFactory.getHandler(baseContractDto);
		String contractCode = contractHandler.submit(baseContractDto);
		result.setContractCode(contractCode);
	} catch (Exception e) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, e.getMessage());
	} finally {
		lock.unlock();
	}

	return result;
}

public ContractDetailVo contractDetail(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (Objects.isNull(contract)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同不存在，请检查合同编号或联系客服");
	}
	Boolean standardGroupDecorate = commonBusinessService.isPROCESS_V2_0_GROUP(contract.getProjectOrderId()) && miniGDFlag;
	List<String> attachUrl = homeAndPcCommonService.getAttachUrl(contract);

	// 获取主体类型
	ContractField contractObjectTypeField = contractFieldService.getByContractCodeAndKey(contractCode, "contractObjectType");
	Byte contractObjectType = null;
	if (contractObjectTypeField != null) {
		contractObjectType = Byte.valueOf(contractObjectTypeField.getFieldValue());
	}

	// 获取合同用户信息
	List<ContractUser> contractUserList = contractUserService.getListByContractCode(contractCode);
	// 签约人
	ContractUser signatoryUser = contractUserList.stream().filter(user -> user.getIsSign().equals(CommonEnum.YES.getCode())).findFirst().orElse(null);
	// 法定代表人
	ContractUser legalUser = contractUserList.stream().filter(user -> user.getRoleType().equals(RoleTypeEnum.LEGAL.getCode())).findFirst().orElse(null);
	// 认证授权状态
	Integer authStatus = homeAndPcCommonService.getAuthStatus(contract.getRelateContractCode());
	Contract authAgentContract = queryAuthAgentContract(contract.getContractCode());

	ContractDetailVo contractDetailVo = ContractDetailVo.builder().contractCode(contractCode)
		.projectOrderId(contract.getProjectOrderId())
		.contractUrl(homeAndPcCommonService.getContractUrl(contract))
		.businessType(contract.getBusinessType())
		.attachUrl(attachUrl)
		.attachFileType(contractBusinessService.getAttachFileKey(attachUrl))
		.type(contract.getType())
		.typeText(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
		.status(contract.getStatus())
		.statusText(ContractStatusEnum.getNameByCode(contract.getStatus()))
		.userSignType(contract.getUserSignType())
		.userConfirmStatus(contract.getUserConfirmStatus())
		.userSignStatus(contract.getUserSignStatus())
		.signChannelType(contract.getSignChannelType())
		.contractObjectType(contractObjectType)
		.bpmNo(contract.getBmpNo())
		.amount(contract.getAmount())
		.coverImage(ContractTypeEnum.getCoverImageByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
		.shareImage(ContractTypeEnum.getShareImageByCode(contract.getType()))
		.companyCode(contract.getCompanyCode())
		.gbCode(contract.getGbCode())
		.userQueryStatus(contract.getUserQueryStatus())
		.standardGroupDecorate(standardGroupDecorate)
		.buttonList(getPreviewButtonList(contract, authAgentContract))
		.authStatus(authStatus)
		.operateTips(getOperateTips(contract, authAgentContract, authStatus))
		.signatoryPhone(Optional.ofNullable(signatoryUser).map(ContractUser::getPhone).orElse(null))
		.signatoryName(Optional.ofNullable(signatoryUser).map(ContractUser::getName).orElse(null))
		.legalPhone(Optional.ofNullable(legalUser).map(ContractUser::getPhone).orElse(null))
		.legalName(Optional.ofNullable(legalUser).map(ContractUser::getName).orElse(null))
		.contractMode(commonContractService.getContractModeByContractCode(contract.getContractCode()))
		.prompt(getContractPrompt(contract))
		.relateAgentAuthContractCode(Optional.ofNullable(authAgentContract).map(Contract::getContractCode).orElse(null))
		.contractAgentOpen(commonContractService.contractAgentOpen(contract.getProjectOrderId()))
		.build();

	if (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType) && SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(contract.getProjectOrderId());
		contractDetailVo.setAddress(homeAndPcCommonService.getSafeAddress(projectInfoDTO));
	}

	// 2.5正签、个性化合同：盖公司章过程中需要展示分享按钮
	if (ContractTypeEnum.getRelateContractTypes().contains(contract.getType())) {
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
		if (processV25) {
			List<Byte> contractTypeList = new ArrayList<>(ContractTypeEnum.getRelateContractTypes());
			//获取线上合同url信息&关联合同线上url信息
			contractDetailVo.setContractUrlList(homeAndPcCommonService.getContractOnlineUrl(contract, contractTypeList));
			//获取线下合同url信息&关联合同线下url信息
			contractDetailVo.setAttachUrlList(homeAndPcCommonService.getContractOfflineUrl(contract, contractTypeList));
			//合并发起常驻分享按钮
			contractDetailVo.setUserQueryStatus(UserQueryStatusEnum.VALID.getCode());
		}
	}

	//个性化合同需要返回关联的零售订单信息
	if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
		contractDetailVo.setRelateRetailInfo(getRetailOrderInfo(contract));
	}

	//观看状态 (1未观看 2已观看)
	//获取合同，如果存在关联合同则获取主合同
	ContractRelation byRelateContractCode = contractRelationService.getByRelateContractCode(contractCode);
	if (byRelateContractCode != null) {
		contract = contractService.getByContractCode(byRelateContractCode.getContractCode());
	}
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
	if (contractVideoService.needWatchVideo(contract, processV25)) {

		String signPhone = cipherService.decrypt(signatoryUser.getPhone());


		// 手机号注销获取不到ucId降级
		MemberDetailDTO memberDetailDTO = null;
		try {
			memberDetailDTO = memberRpc.getClientUcIdByPhone(Long.parseLong(signPhone));
		} catch (Exception e) {
			LOGGER.info("手机号请求member获取ucId失败", e);
		}
		if (memberDetailDTO == null) {
			//手机号注销或者没有注册,判断为没看过视频
			contractDetailVo.setWatchStatus(WatchStatusEnum.NOT_FINISH.getCode());
		} else {
			Integer watchStatus = contractVideoService.getWatchStatusNew(contract, memberDetailDTO.getId().toString());
			contractDetailVo.setWatchStatus(watchStatus);
		}

	} else {
		contractDetailVo.setWatchStatus(WatchStatusEnum.FINISH.getCode());//不是首期或B合同，不需要观看
	}

	if (BusinessTypeEnum.PART_DECORATE.getCode().equals(contract.getBusinessType())
		|| BusinessTypeEnum.REFORM_ALL.getCode().equals(contract.getBusinessType())
		|| (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType()) && !processV25)) {
		contractDetailVo.setIsSupportWatchVideo(false);
	} else {
		contractDetailVo.setIsSupportWatchVideo(contractApolloConfig.isSupportWatchVideo(contract.getBusinessType(), contract.getGbCode()));
	}
	return contractDetailVo;
}

private Contract queryAuthAgentContract(String contractCode) {
	Contract authAgentContract = null;
	List<ContractRelation> relationList = contractRelationService.getRelationList(contractCode);
	if (!org.springframework.util.CollectionUtils.isEmpty(relationList)) {
		List<String> contractCodes = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
		List<Contract> relationContractList = contractService.getListByContractCodes(contractCodes, false);
		authAgentContract = relationContractList.stream().filter(relationContract -> ContractTypeEnum.AUTH_AGENT.getCode().equals(relationContract.getType()))
			.findFirst().orElse(null);
	}

	return authAgentContract;
}

private ContractDetailVo.OperateInfo getOperateTips(Contract mainContract, Contract authAgentContract, Integer authStatus) {
	if (ContractStatusEnum.SIGNED_STATUS_LIST.contains(mainContract.getStatus())) {
		return null;
	}

	// 对公合同&线上签署才返回认证信息
	Byte contractObjectType = contractFieldService.getContractObjectType(mainContract.getContractCode());
	boolean companyOnlineSign = ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType) && SignChannelTypeEnum.ONLINE.getCode().equals(mainContract.getSignChannelType());
	if (companyOnlineSign) {
		// 获取授权协议关联的主合同的签约人
		List<ContractUser> contractUserList = contractUserService.getListByContractCode(mainContract.getContractCode());
		ContractUser legalUser = contractUserList.stream().filter(user -> user.getRoleType().equals(RoleTypeEnum.LEGAL.getCode())).findFirst().orElse(null);
		ContractUser signerUser = contractUserList.stream().filter(user -> user.getIsSign().equals(CommonEnum.YES.getCode())).findFirst().orElse(null);
		String legalName = Optional.ofNullable(legalUser).map(ContractUser::getName).orElse("");
		String legalPhone = Optional.ofNullable(legalUser).map(ContractUser::getPhone).orElse("");
		String signerName = Optional.ofNullable(signerUser).map(ContractUser::getName).orElse("");
		String signerPhone = Optional.ofNullable(signerUser).map(ContractUser::getPhone).orElse("");
		if (StringUtils.isBlank(legalName) || StringUtils.isBlank(signerPhone)) {
			LOGGER.error("主合同[{}]的签约人姓名{}/手机号{}为空", mainContract.getContractCode(), legalName, signerPhone);
		}
		return ContractDetailVo.OperateInfo.builder()
			.title("公对公线上签署需要您:")
			.message(ContractAuthStatusEnum.getMessageByCode(authStatus, legalName, DesensitizeUtil.phoneLast4No(legalPhone), signerName, DesensitizeUtil.phoneLast4No(signerPhone)))
			.build();
	}

	List<ContractUser> contractUserList = contractUserService.getListByContractCode(mainContract.getContractCode());
	ContractUser ownerUser = contractUserList.stream().filter(user -> RoleTypeEnum.OWNER.getCode().equals(user.getRoleType())).findFirst()
		.orElse(null);
	ContractUser agentUser = contractUserList.stream().filter(user -> RoleTypeEnum.AGENT.getCode().equals(user.getRoleType())).findFirst()
		.orElse(null);
	ContractUser signUser = contractUserList.stream().filter(user -> CommonEnum.YES.getCode().equals(user.getIsSign())).findFirst()
		.orElse(null);

	List<Byte> contractTypeList = new ArrayList<>(ContractTypeEnum.getRelateContractTypes());
	List<Contract> relateContractList = homeAndPcCommonService.getAllRelateContract(mainContract, contractTypeList);

	// 代理人授权提示
	if (authAgentContract != null && ContractStatusEnum.allowSignStatus.contains(authAgentContract.getStatus())) {
		if (ownerUser == null || agentUser == null) {
			return null;
		}

		String ownerMaskPhone = StrUtil.hide(ownerUser.getPhone(), 0, ownerUser.getPhone().length() - 4);
		String agentMaskPhone = StrUtil.hide(agentUser.getPhone(), 0, agentUser.getPhone().length() - 4);

		relateContractList = relateContractList.stream().filter(c -> !ContractTypeEnum.AUTH_AGENT.getCode().equals(c.getType())).collect(Collectors.toList());
		if (CollectionUtils.isEmpty(relateContractList)) {
			// 单独发起签约
			return ContractDetailVo.OperateInfo.builder()
				.title("代理人签署协议需要您：")
				.message(String.format("第一步：邀请产权人【%s 尾号%s】确认委托书\n第二步：邀请代理人【%s 尾号%s】签署%s", ownerUser.getName(), ownerMaskPhone,
					agentUser.getName(), agentMaskPhone, ContractTypeEnum.getNameByCode(mainContract.getType())))
				.build();
		} else {
			// 合并发起签约
			return ContractDetailVo.OperateInfo.builder()
				.title("发起多份合同，请提醒客户按序签约：")
				.message(String.format("第一步是邀请产权人【%s 产权人尾号%s】确认委托书\n第二步是提醒代理人按照【%s】依次签署;若签一份合同未签完，不可签约下一份合同", ownerUser.getName(), ownerMaskPhone,
					relateContractList.stream().map(Contract::getType).map(ContractTypeEnum::getNameByCode).collect(Collectors.joining("、"))))
				.build();
		}
	}

	if (CollectionUtils.isNotEmpty(relateContractList)) {
		if (signUser == null) {
			return null;
		}

		String signMaskPhone = StrUtil.hide(signUser.getPhone(), 0, signUser.getPhone().length() - 4);
		return ContractDetailVo.OperateInfo.builder()
			.title("发起多份合同，请提醒客户按序签约：")
			.message(String.format("第一步:分享合同给签约人【%s 签约人尾号%s】签署\n第二步：提醒客户按照【%s】依次签署;若签一份合同未签完，不可签约下一份合同", signUser.getName(), signMaskPhone,
				relateContractList.stream().map(Contract::getType).map(ContractTypeEnum::getNameByCode).collect(Collectors.joining("、"))))
			.build();
	}

	return null;
}

public ContractDetailVo.RelateRetailInfo getRetailOrderInfo(Contract contract) {
	ContractDetailVo.RelateRetailInfo relateRetailInfo = new ContractDetailVo.RelateRetailInfo();
	try {
		//根据DE查询对应的DF
		CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(contract.getProjectOrderId());
		List<String> customerCommissionCodeList;
		if (HomeWorkflowTypeEnum.RETAIL.getType().equals(coordinationProjectOrder.getHomeWorkflowType())) {
			customerCommissionCodeList = Collections.singletonList(coordinationProjectOrder.getRetailProjectOrder().getCustomerCommissionCode());
		} else {
			//团装2.5给DE
			if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType()) && commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId())) {
				customerCommissionCodeList = Collections.singletonList(coordinationProjectOrder.getDecorateProjectOrder().getCustomerCommissionCode());
			} else {
				customerCommissionCodeList = projectReadService.getRetailCustomerCommissionCodesByDecorProjectOrderId(contract.getProjectOrderId());
			}
		}
		if (!CollectionUtils.isEmpty(customerCommissionCodeList)) {
			relateRetailInfo.setCustomerCommissionCode(customerCommissionCodeList.get(0));
		}
		//根据C合同查contract_field表关联的报价单列表
		ContractField contractField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), "billCodeList");
		if (contractField == null || StringUtils.isBlank(contractField.getFieldValue())) {
			return relateRetailInfo;
		}
		List<String> personContractBillCodeList = JSON.parseArray(contractField.getFieldValue(), String.class);
		//根据报价单号查询原始报价单列表
		Map<String, String> billCodeMap = atomBudgetRpc.queryRelaBillCode(personContractBillCodeList);
		//根据原始报价单列表查询零售订单列表
		List<String> relaBillCodeList = new ArrayList<>(billCodeMap.values());
		if (CollectionUtils.isEmpty(relaBillCodeList)) {
			return relateRetailInfo;
		}
		List<ProjectInfo> retailProjectList = projectInfoService.getRetailProjectListByBillCodes(relaBillCodeList);
		//获取OrderNo,如果为空不添加到数组中
		List<String> retailProjectOrderIdList = retailProjectList.stream().map(ProjectInfo::getOrderNo).filter(StringUtils::isNotBlank).collect(Collectors.toList());
		if (!CollectionUtils.isEmpty(retailProjectOrderIdList)) {
			relateRetailInfo.setReOrderNoList(retailProjectOrderIdList);
			return relateRetailInfo;
		}

		List<ProjectOrderRelation> projectOrderRelationList = projectOrderRelationService.selectByBillCodeList(relaBillCodeList);
		if (CollectionUtils.isEmpty(projectOrderRelationList)) {
			return relateRetailInfo;
		}
		relateRetailInfo.setReOrderNoList(projectOrderRelationList.stream().map(ProjectOrderRelation::getOrderNo).filter(StringUtils::isNotBlank).collect(Collectors.toList()));
		return relateRetailInfo;
	} catch (Exception e) {
		LOGGER.error("合同详情获取关联定软电订单信息失败,contractCode:{}", contract.getContractCode(), e);
		return null;
	}
}

public String getContractPrompt(Contract contract) {
	//申请用章节点
	List<ContractNode> applySealNode = contractNodeService.getByContractCodeAndType(contract.getContractCode(), NodeTypeEnum.APPLY_SEAL.getCode());
	if (ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())) {
		return "合同已作废";
	}
	if (ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus()) && CollectionUtils.isNotEmpty(applySealNode)) {
		return "客户已通过协议确认方式确认合同，申请用章需重新签署";
	}
	if (ContractStatusEnum.inEndStatus(contract.getStatus())) {
		return "客户已确认/签署";
	}
	if (ContractStatusEnum.allowSignStatus.contains(contract.getStatus())) {
		return "协议未确认/签署，请先微信转发给业主确认/签署";
	}
	return "";
}

public ContractButtonVo contractButtonList(String contractCode) {
	try {
		ContractButtonVo contractButtonVo = new ContractButtonVo();
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.nonNull(contract)) {
			List<String> attachUrlList = commonService.getAttachUrl(contract);
			//用户确认节点列表
			List<ContractNode> userConfirmNodeList = contractNodeService.getListByContractCodesAndType(Collections.singletonList(contract.getContractCode()), Collections.singletonList(NodeTypeEnum.USER_CONFIRM.getCode()));
			List<CancelOrderBaseInfoDTO> cancelOrderBaseInfoDTOS = cancelOrderRecordService.getListByProjectOrderId(contract.getProjectOrderId());
			Set<String> terminalContractCode = cancelOrderBaseInfoDTOS.stream().map(CancelOrderBaseInfoDTO::getContractCode).collect(Collectors.toSet());
			List<ButtonItemVo> buttonItemVos = getButtonList(contract, attachUrlList, null, userConfirmNodeList, terminalContractCode);

			ButtonItemVo undoButton = buttonItemVos.stream().filter(button -> ContractButtonEnum.UNDO.getType().equals(button.getType())).findFirst().orElse(null);
			if (undoButton != null) {
				//如果有撤销按钮，判断是否有权限
				String roleId = HeaderContext.getContext().getRoleId();
				Map<String, Object> perms = permissionRpc.getPerms(roleId);
				//如果没有撤销合同权限，则不显示撤销按钮
				if (perms == null || !perms.containsKey(ContractPermissionKeyEnum.APP_CREATE_EDIT.getKey())) {
					LOGGER.info("用户没有撤销合同权限，contractCode:{}", contractCode);
					buttonItemVos = buttonItemVos.stream().filter(button -> !ContractButtonEnum.UNDO.getType().equals(button.getType())).collect(Collectors.toList());
				}
			}

			if (CollectionUtils.isNotEmpty(buttonItemVos)) {
				List<ButtonItemVo> buttons = buttonItemVos.stream().filter(
						button -> ContractButtonEnum.getContractDetailButtonTypes().containsKey(button.getType()))
					.collect(Collectors.toList());
				contractButtonVo.setButtonList(buttons);
				if (!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
					// 设计费审核和通用审核url目前没区别，如果后续设计费审核url有区别再区分
					contractButtonVo.setBpmUrl(pcContractService.getBpmUrl(contract.getBmpNo()));
					contractButtonVo.setContractUrl(commonService.getContractUrl(contract));
				}
				if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
					contractButtonVo.setAttachUrl(commonService.getAttachUrl(contract));
				}

			}
			return contractButtonVo;
		}
	} catch (Exception e) {
		LOGGER.error("获取合同详情按钮失败 contractCode:{} e:{}", contractCode, e);
	}
	return null;

}

