	public ContractTypeListVo getContractTypeList(String projectOrderId, Integer sceneType) {
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		if (Objects.isNull(projectInfoDTO)) {
			LOGGER.warn("获取合同类型列表失败,查询不到项目信息 projectOrderId:{}", projectOrderId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取合同类型列表失败,查询不到项目信息-[签约]");
		}

		ContractTypeListVo vo = new ContractTypeListVo();
		byte businessType = commonContractService.getBusinessType(projectInfoDTO);
		vo.setAddress(homeAndPcCommonService.getSafeAddress(projectInfoDTO));
		vo.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));
		vo.setCompanyCode(projectInfoDTO.getCustomerCommission().getCompanyCode());
		vo.setGbCode(projectInfoDTO.getCustomerHouse().getGbCode());
		vo.setBusinessType(businessType);
		vo.setSupportFullServiceSign(commonContractService.supportFullServiceSign(projectInfoDTO.getCustomerHouse().getGbCode(), businessType));
		List<ContractTypeListVo.ContractTypeListItemVo> contractTypeListItemVos = new LinkedList<>();

		//读取分公司配置
		String companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(),
			projectInfoDTO.getCustomerCommission().getCompanyCode(), ContractTypeEnum.PACKAGE_FORMAL.getCode());
		LOGGER.info("获取合同类型列表,companyCode:{}", companyCode);
		List<ContractCityCompanyInfo> companyConfig = contractCityCompanyConfigService.getConfig(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), companyCode, commonContractService.getBusinessType(projectInfoDTO));
		LOGGER.info("获取合同类型列表,companyConfig:{}", JSON.toJSONString(companyConfig));
		//是否2.5模式
		CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectOrderId);
		CoordinationProjectRelationInfo decorateProjectOrder = coordinationProjectOrder.getDecorateProjectOrder();
		String convertProjectOrderId = ObjectUtil.isEmpty(decorateProjectOrder) ? coordinationProjectOrder.getRetailProjectOrder().getProjectOrderId() : decorateProjectOrder.getProjectOrderId();
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(convertProjectOrderId);
		vo.setProcessV25(processV25);
		vo.setFormalUseNewProcess(contractBusinessService.formalUseNewProcess(businessType, processV25, projectInfoDTO.getCustomerHouse().getGbCode()));
		//支持的合同类型
		List<Integer> contractTypes = companyConfig.stream().map(ContractCityCompanyInfo::getContractType).collect(Collectors.toList());
		//根据场景类型获取支持的合同类型
		contractTypes = getContractTypeList(coordinationProjectOrder, contractTypes, sceneType);

		// 全量合同列表
		List<Contract> allContractList = contractService.getContractList(projectOrderId);
		// 获取上一个订单的合同列表
		List<Contract> previousOrderContractList = commonContractService.getPreviousOrderContractList(projectOrderId);
		allContractList.addAll(previousOrderContractList);
		//用户确认节点列表
		List<ContractNode> userConfirmNodeList = new ArrayList<>();
		if (CollectionUtils.isNotEmpty(allContractList)) {
			List<String> contractCodes = allContractList.stream().map(Contract::getContractCode).collect(Collectors.toList());
			userConfirmNodeList = contractNodeService.getListByContractCodesAndType(contractCodes, Collections.singletonList(NodeTypeEnum.USER_CONFIRM.getCode()));
		}

		ProjectConfigSnap configByProjectOrderId = projectConfigSnapService.getConfigByProjectOrderId(convertProjectOrderId);
		List<FundCategoryDTO> fundCategoryDTOS = fundBaseService.fundCategoryQuery(QueryFundCategoryParam.builder()
			.mdmCode(companyCode)
			.categoryQueryType(CategoryQueryTypeEnum.BY_VERSION.getCode())
			.categoryType(FundTypeSourceTypeEnum.ALL.getCode())
			.version(configByProjectOrderId == null ? null : configByProjectOrderId.getFundVersion())
			.build());
		//个性化首期款 -> 按照版本款项类型 过滤合同
		List<Integer> offsetFundTypes = fundCategoryDTOS.stream().map(FundCategoryDTO::getOffSetType).distinct().collect(Collectors.toList());
		Set<Byte> personalContractTypes = offsetFundTypes.stream().map(FundRelateContractMapping::obtainContractTypeByFundType).collect(Collectors.toSet());
		contractTypes = contractTypes.stream()
			//过滤掉 当前版本不包含的首期款协议 类型
			.filter(contract -> !(!personalContractTypes.contains(contract.byteValue()) && ContractTypeEnum.belongToPersonalizedContract(contract.byteValue())))
			.collect(Collectors.toList());
		ContractProcessModeChangeInfo contractProcessModeChangeInfo = formalReSignService.getContractProcessModeChangeInfo(projectOrderId);


		ParallelTasksContext parallelQueryAuditProcessInfoTask = parallelTaskService.newParallelTasks();
		for (ContractTypeEnum contractTypeEnum : ContractTypeEnum.values()) {
			//施工图纸没单独处理入口
			if (!contractTypes.contains(contractTypeEnum.getCode().intValue()) || ContractTypeEnum.getNoVisibleContractTypes().contains(contractTypeEnum.getCode())) {
				continue;
			}

			ContractTypeListVo.ContractTypeListItemVo contractTypeListItemVo = null;
			List<Contract> contractList = null;

			contractTypeListItemVo = new ContractTypeListVo.ContractTypeListItemVo(contractTypeEnum, businessType);
			contractList = allContractList.stream().filter(c -> c.getType().equals(contractTypeEnum.getCode())).sorted(Comparator.comparing(Contract::getId).reversed()).collect(Collectors.toList());

			//正签、变更展示创建、编辑；设计认购有合同的话，只展示预览
			if (CollectionUtils.isNotEmpty(contractList)) {
				Contract contract = contractList.get(0);
				contractTypeListItemVo.setState(1);
				contractTypeListItemVo.setStateText("已创建");
				Contract firstContract = contractList.get(0);
				contractTypeListItemVo.setStatus(firstContract.getStatus());
				contractTypeListItemVo.setStatusText(ContractStatusEnum.getShowNameByCode(contract.getStatus()));
				contractTypeListItemVo.setErrorMessage(homeAndPcCommonService.getContractErrorMessage(firstContract));
				contractTypeListItemVo.setEstimatedLaunchTime(ContractTypeEnum.getEnumByCode(contract.getType()).getEstimatedLaunchTime());
				ContractStatusVo contractStatusVo = convertStatusVo(firstContract.getStatus());
				if (Objects.nonNull(contractStatusVo)) {
					contractTypeListItemVo.setContractStatus(contractStatusVo.getStatus());
					contractTypeListItemVo.setContractStatusText(contractStatusVo.getName());
				}
				contractTypeListItemVo.setContractUrl(commonService.getContractUrl(contract));
				contractTypeListItemVo.setAttachUrl(commonService.getAttachUrl(contract));
				contractTypeListItemVo.setAttachFileType(contractBusinessService.getAttachFileKey(contractTypeListItemVo.getAttachUrl()));
				contractTypeListItemVo.setContractCode(contract.getContractCode());
				contractTypeListItemVo.setSignChannelType(contract.getSignChannelType());
				contractTypeListItemVo.setWaitAuth(homeAndPcCommonService.isWaitAuth(contract));
				Integer authStatus = homeAndPcCommonService.getAuthStatus(contract.getRelateContractCode());
				contractTypeListItemVo.setAuthStatus(authStatus);
				contractTypeListItemVo.setContractInfoText(getContractInfoText(contractList, contractTypeEnum, authStatus));
				contractTypeListItemVo.setTipsInfo(getContractTipsInfo(contractList, contractTypeEnum));
			}
			//正签
			if (contractTypeEnum.equals(ContractTypeEnum.PACKAGE_FORMAL)) {
				//支持线上or线下，先写死，pc没有去读取配置
				contractTypeListItemVo.setSupportSignChannelType(Arrays.asList(SignChannelTypeEnum.ONLINE.getCode(), SignChannelTypeEnum.OFFLINE.getCode()));
				contractTypeListItemVo.setSupportUserSignType(Collections.singletonList(UserSignTypeEnum.SIGN.getCode()));
				if (vo.isProcessV25() && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
					contractTypeListItemVo.setTypeName(contractTypeListItemVo.getTypeName().concat("及图纸"));
				}
				if (vo.isProcessV25() && BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
					boolean hasUploadFormalDrawing = contractBusinessService.hasUploadFormalDrawing(true, businessType, projectOrderId);
					String typeName = hasUploadFormalDrawing ? contractTypeListItemVo.getTypeName().concat("及图纸") : contractTypeListItemVo.getTypeName();
					contractTypeListItemVo.setTypeName(typeName);
				}
				if (CollectionUtils.isNotEmpty(contractList)) {
					Contract packageFormalContract = contractList.get(0);
					Integer contractMode = commonContractService.getContractModeByContractCode(packageFormalContract.getContractCode());
					contractTypeListItemVo.setUploadStatus(checkAttach(packageFormalContract.getContractCode()));
					contractTypeListItemVo.setAuditStatus(getLastAuditInfo(packageFormalContract.getContractCode()) == null ? null : getLastAuditInfo(packageFormalContract.getContractCode()).getAuditStatus());
					contractTypeListItemVo.setUserSignStatus(packageFormalContract.getUserSignStatus());
					ContractStatusVo contractStatusVo = convertStatusVo(packageFormalContract.getStatus());
					if (ContractModeEnum.FULL_SERVICE.getCode().equals(contractMode)) {
						contractTypeListItemVo.setTypeName("正式套餐合同图纸及附件");
					}
					if (Objects.nonNull(contractStatusVo)) {
						contractTypeListItemVo.setContractStatus(contractStatusVo.getStatus());
						contractTypeListItemVo.setContractStatusText(contractStatusVo.getName());
					}
					if (ContractStatusEnum.DRAFT.getCode().equals(packageFormalContract.getStatus())) {
						String centerControlType = homeAndPcCommonService.getCenterControlType(projectOrderId);
						if ("NEW".equals(centerControlType)) {
							if (OrderStatusEnum.QUOTING.getCode().equals(projectInfoDTO.getProjectOrderStatus())) {
								//报价中
								contractTypeListItemVo.setState(2);
								contractTypeListItemVo.setStateText("待预算员提交正式报价后，再次发起签约");
							}
						}
					}
					contractTypeListItemVo.setContractCode(packageFormalContract.getContractCode());
					contractTypeListItemVo.setSignChannelType(packageFormalContract.getSignChannelType());
					//不在起草中，并且bpmNo不为空，拼装审核链接
					if ((!ContractStatusEnum.DRAFT.getCode().equals(packageFormalContract.getStatus())) && StringUtils.isNotBlank(packageFormalContract.getBmpNo())) {
						contractTypeListItemVo.setBpmUrl(getBpmUrl(packageFormalContract.getBmpNo()));
					}
					//合并发起模式的需要返回关联合同&是否有个性化报价
					if (processV25) {
						List<RelateContract> relateContractList = homeAndPcCommonService.getRelateContractList(packageFormalContract);
						contractTypeListItemVo.setRelateContracts(relateContractList);
						ContractRelation contractRelation = contractRelationService.getByRelateContractCode(packageFormalContract.getContractCode());
						contractTypeListItemVo.setPrimaryRelatedContractCode(contractRelation != null ? contractRelation.getContractCode() : null);
						contractTypeListItemVo.setProjectChangeNo(homeAndPcCommonService.getProjectChangeNo(projectOrderId));
						contractTypeListItemVo.setContractMode(commonContractService.getContractModeByContractCode(packageFormalContract.getContractCode()));

						ContractTypeListVo.ContractTypeListItemVo finalContractTypeListItemVo = contractTypeListItemVo;
						parallelTaskService.addNewTask(parallelQueryAuditProcessInfoTask, () ->
							finalContractTypeListItemVo.setProcessInfo(contractDetailService.buildProcessInfoDetail(packageFormalContract)));
						parallelTaskService.execTasks(parallelQueryAuditProcessInfoTask);
					}
				}

			}

			//变更
			if (contractTypeEnum.getCode().equals(ContractTypeEnum.PACKAGE_CHANGE.getCode())) {
				contractTypeListItemVo.setButtonList(getChangeContractButtonList(projectOrderId, businessType));
				//支持线上or线下，先写死，pc没有去读取配置
				contractTypeListItemVo.setSupportSignChannelType(Arrays.asList(SignChannelTypeEnum.ONLINE.getCode(), SignChannelTypeEnum.OFFLINE.getCode()));
				contractTypeListItemVo.setSupportUserSignType(Arrays.asList(UserSignTypeEnum.SIGN.getCode(), UserSignTypeEnum.CONFIRM.getCode()));
				contractTypeListItemVo.setTypeName(ContractTypeEnum.getNameByContractTypeAndBusinessType(ContractTypeEnum.PACKAGE_CHANGE.getCode(), businessType));
			}
			//解约协议按钮是多级列表
			if (contractTypeEnum.getCode().equals(ContractTypeEnum.TERMINAL.getCode())
				|| contractTypeEnum.getCode().equals(ContractTypeEnum.DESIGN_CHANGE.getCode())
				|| (ContractTypeEnum.PERSONAL.getCode().equals(contractTypeListItemVo.getType()) && contractApolloConfig.getCheckPersonalContract())) {
				contractTypeListItemVo.setButtonList(buildMultiLevelButtonList(contractTypeEnum, contractList));
			}
			// 补充协议也是多级列表
			if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractTypeEnum.getCode())) {
				// 如果是补充协议未开城，则不添加补充协议的卡片
				if (!contractUnifyService.supplementIsOpen(projectOrderId)) {
					continue;
				}
				List<ButtonItemVo> buttonItemVos = new ArrayList<>();
				// 开城后，恒展示去创建按钮
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.CREATE));
				// 多级卡片按钮
				buttonItemVos.addAll(buildMultiLevelButtonList(contractTypeEnum, contractList));
				// 构建补充协议的多级卡片
				contractTypeListItemVo.setButtonList(buttonItemVos);
			}
			// 和解协议也是多级列表
			if (ContractTypeEnum.SETTLEMENT.getCode().equals(contractTypeEnum.getCode())) {
				// 如果是和解协议未开城，则不添加补充协议的卡片
				if (!contractUnifyService.settlementIsOpen(projectOrderId)) {
					continue;
				}
				List<ButtonItemVo> buttonItemVos = new ArrayList<>();
				// 开城后，恒展示去创建按钮
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.CREATE));
				// 多级卡片按钮
				buttonItemVos.addAll(buildMultiLevelButtonList(contractTypeEnum, contractList));
				// 构建和解协议的多级卡片
				contractTypeListItemVo.setButtonList(buttonItemVos);
			}

			//个性化主材合同
			if (contractTypeEnum.getCode().equals(ContractTypeEnum.PERSONAL.getCode())) {
				if (CollectionUtils.isEmpty(contractList)) {
					contractTypeListItemVo.setExtraDesc("");
				} else {
					Contract contract = contractList.get(0);
					List<RelateContract> relateContractList = homeAndPcCommonService.getRelateContractList(contract);
					contractTypeListItemVo.setRelateContracts(relateContractList);
					ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
					contractTypeListItemVo.setPrimaryRelatedContractCode(contractRelation != null ? contractRelation.getContractCode() : null);
					//不在起草中，并且bpmNo不为空，拼装审核链接
					if ((!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) && StringUtils.isNotBlank(contract.getBmpNo())) {
						contractTypeListItemVo.setBpmUrl(getBpmUrl(contract.getBmpNo()));
					}
				}

			}
			// 设计合同
			if (ContractTypeEnum.DESIGN.getCode().equals(contractTypeEnum.getCode()) && ObjectUtil.isNotEmpty(contractList)) {
				Contract contract = contractList.get(0);
				List<RelateContract> relateContractList = homeAndPcCommonService.getRelateContractList(contract);
				contractTypeListItemVo.setRelateContracts(relateContractList);
				ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
				contractTypeListItemVo.setPrimaryRelatedContractCode(contractRelation != null ? contractRelation.getContractCode() : null);
			}
			contractTypeListItemVo.setType(contractTypeEnum.getCode());
			contractTypeListItemVo.setIcon(contractTypeEnum.getPcImage());
			if (!CollectionUtils.isEmpty(contractList) && contractList.get(0) != null) {
				BindOrderInfoGroup group = quotationRelationCommonService.getBindOrderInfoGroupByContractCode(contractList.get(0).getContractCode());
				contractTypeListItemVo.setBillCodeList(BillCodeInfo.getBillCodeList(group.getBillCodeInfos()));
				contractTypeListItemVo.setBillCodeInfoList(group.getBillCodeInfos());
				contractTypeListItemVo.setSubOrderInfoList(group.getSubOrderInfos());
				contractTypeListItemVo.setChangeOrderInfoList(group.getChangeOrderInfos());
			}

			// 设计合同超底场景，下发设计费专项审核链接
			if (designFeeAuditService.isDesignScene(contractTypeEnum.getCode())) {
				Contract contract = allContractList.stream()
					.filter(item -> item.getType().equals(contractTypeEnum.getCode())
						&& StringUtils.isNotBlank(item.getBmpNo()))
					.findFirst().orElse(null);
				// 必须是整装+流程2.5+超底
				if (Objects.nonNull(contract) && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)
					&& processV25 && designFeeAuditService.isDesignFeeExceedBottom(contract)) {
					contractTypeListItemVo.setBpmUrl(getBpmUrl(contract.getBmpNo()));
				}
			}
			contractTypeListItemVos.add(contractTypeListItemVo);
		}

		//按钮配置下发
		for (ContractTypeListVo.ContractTypeListItemVo contractTypeListItemVo : contractTypeListItemVos) {
			Contract contract = allContractList.stream().filter(item -> item.getContractCode().equals(contractTypeListItemVo.getContractCode())).findFirst().orElse(null);
			List<String> attachUrlList = contract == null ? new ArrayList<>() : commonService.getAttachUrl(contract);
			if (contract == null) {
				contract = Contract.builder()
					.type(contractTypeListItemVo.getType())
					.projectOrderId(projectOrderId)
					.contractCode("")
					.platformInstanceId(0L)
					.build();
			}
			// 这几类合同支持同时多个是组合按钮，按钮特殊判断
			if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractTypeListItemVo.getType()) ||
				ContractTypeEnum.TERMINAL.getCode().equals(contractTypeListItemVo.getType()) ||
				ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contractTypeListItemVo.getType()) ||
				(ContractTypeEnum.PERSONAL.getCode().equals(contractTypeListItemVo.getType()) && contractApolloConfig.getCheckPersonalContract())
				|| ContractTypeEnum.SUPPLEMENT.getCode().equals(contractTypeListItemVo.getType())
				|| ContractTypeEnum.SETTLEMENT.getCode().equals(contractTypeListItemVo.getType())
			) {
				continue;
			}
			List<ButtonItemVo> buttonListByConfig = getButtonListByConfig(contract, attachUrlList, allContractList, userConfirmNodeList);
			contractTypeListItemVo.setButtonList(buttonListByConfig);
		}
		vo.setContractTypeListItemVos(contractTypeListItemVos);
		vo.setFormalReSignInfo(formalReSignService.getFormalReSignInfo(contractProcessModeChangeInfo));

		// 等待风控审核
		parallelTaskService.awaitTasksResult(parallelQueryAuditProcessInfoTask);

		return vo;
	}

	private ContractListVo.TipsInfo getContractTipsInfo(List<Contract> contractList, ContractTypeEnum contractTypeEnum) {
		if (ContractTypeEnum.HAVE_AGENT_AUTH_CONTRACT_TYPES.contains(contractTypeEnum.getCode())) {
			// 产权人授权状态
			Contract contract = contractList.stream().filter(c -> ContractStatusEnum.allValidStatus.contains(c.getStatus()))
				.findFirst().orElse(null);
			if (contract != null) {
				Contract authAgentContract = homeAndPcCommonService.getRelateContractByType(contract, ContractTypeEnum.AUTH_AGENT.getCode());
				if (authAgentContract != null && ContractStatusEnum.allowSignStatus.contains(authAgentContract.getStatus())) {
					return ContractListVo.TipsInfo.builder()
						.tipsType(TipsTypeEnum.JUMP.getType())
						.text("请先邀请产权人完成《装修授权委托书》签署")
						.btnText("邀请授权")
						.build();
				}
			}
		}

		return null;
	}

	/**
	 * @param contractTypes
	 * @param sceneType
	 * @return
	 * @Description: 根据场景类型获取合同类型列表
	 */
	public List<Integer> getContractTypeList(CoordinationProjectInfo coordinationProjectOrder, List<Integer> contractTypes, Integer sceneType) {
		if (sceneType == null || ContractShowSceneTypeEnum.ALL_AND_RETAIL.getCode().equals(sceneType) || ContractShowSceneTypeEnum.ALL.getCode().equals(sceneType)) {
			if (coordinationProjectOrder.hasDecorateProjectOrder()) {
				return contractTypes;
			} else {
				return contractTypes.stream().filter(item -> ContractTypeEnum.getPersonalizedRelevantContractList().contains(item.byteValue())).collect(Collectors.toList());
			}
		}
		if (ContractShowSceneTypeEnum.WHOLE.getCode().equals(sceneType)) {
			if (coordinationProjectOrder.hasDecorateProjectOrder()) {
				return contractTypes.stream().filter(item -> ContractTypeEnum.WHOLE_CONTRACT.contains(item.byteValue())).collect(Collectors.toList());
			} else {
				return new ArrayList<>();
			}
		} else if (ContractShowSceneTypeEnum.RETAIL.getCode().equals(sceneType)) {
			contractTypes = contractTypes.stream().filter(item -> ContractTypeEnum.getPersonalizedRelevantContractList().contains(item.byteValue())).collect(Collectors.toList());
		}
		return contractTypes;
	}

	/**
	 * 获取二级合同列表
	 *
	 * @param projectOrderId
	 * @param contractType
	 * @return
	 */
	public ContractTypeListVo getSecondContractTypeList(String projectOrderId, Byte contractType) {
		ContractTypeListVo vo = new ContractTypeListVo();
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		if (Objects.isNull(projectInfoDTO)) {
			LOGGER.warn("获取合同类型列表失败,查询不到项目信息 projectOrderId:{}", projectOrderId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取合同类型列表失败,查询不到项目信息-[签约]");
		}
		byte businessType = commonContractService.getBusinessType(projectInfoDTO);
		vo.setAddress(homeAndPcCommonService.getAddress(projectInfoDTO));
		vo.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));
		vo.setCompanyCode(projectInfoDTO.getCustomerCommission().getCompanyCode());
		vo.setGbCode(projectInfoDTO.getCustomerHouse().getGbCode());
		vo.setBusinessType(businessType);
		List<ContractTypeListVo.ContractTypeListItemVo> contractTypeListItemVos = new LinkedList<>();

		List<Contract> contractList = contractService.getContractList(projectOrderId, contractType);
		if (ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
			List<Contract> previousOrderContractList = commonContractService.getPreviousOrderContractList(projectOrderId);
			contractList.addAll(previousOrderContractList);
		}
		//只允许的按钮类型
		List<Integer> canShowButtonList = new ArrayList<>();
		if (ContractTypeEnum.TERMINAL.getCode().equals(contractType) || ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contractType)) {
			canShowButtonList = Collections.singletonList(PcButtonEnum.PREVIEW.getType());
		} else if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)) {
			canShowButtonList = Arrays.asList(PcButtonEnum.PREVIEW.getType(), PcButtonEnum.VIEW.getType());
		}
		for (Contract contract : contractList) {
			ContractField goodsInfo = null;
			if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
				if (ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())) {
					continue;
				}
				goodsInfo = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), "goodsInfo");
			}
			BindOrderInfoGroup group = quotationRelationCommonService.getBindOrderInfoGroupByContractCode(contract.getContractCode());
			ContractTypeListVo.ContractTypeListItemVo contractTypeListItemVo = ContractTypeListVo.ContractTypeListItemVo
				.builder()
				.type(contract.getType())
				.typeName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
				.contractCode(contract.getContractCode())
				.contractStatus(contract.getStatus())
				.contractUrl(commonService.getContractUrl(contract))
				.secondLevelShowTitle(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
				.signChannelType(contract.getSignChannelType())
				.type(contract.getType())
				.icon(ContractTypeEnum.getPcImageByCode(contractType))
				.status(contract.getStatus())
				.statusText(ContractStatusEnum.getNameByCode(contract.getStatus()))
				.goodsInfo(goodsInfo != null ? goodsInfo.getFieldValue() : null)
				.billCodeList(BillCodeInfo.getBillCodeList(group.getBillCodeInfos()))
				.billCodeInfoList(group.getBillCodeInfos())
				.subOrderInfoList(group.getSubOrderInfos())
				.changeOrderInfoList(group.getChangeOrderInfos())
					.build();
			//原服务解约协议名称需特殊展示
			if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType()) && !projectOrderId.equals(contract.getProjectOrderId())) {
				contractTypeListItemVo.setTypeName("原服务解约协议");
			}
			List<String> attachUrl = commonService.getAttachUrl(contract);
			List<ContractNode> nodeList = contractNodeService.getListByContractCode(contract.getContractCode());
			List<ButtonItemVo> buttonItemVos = new ArrayList<>();
			if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
				List<RelateContract> relateContractList = homeAndPcCommonService.getRelateContractList(contract);
				contractTypeListItemVo.setRelateContracts(relateContractList);
				ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
				contractTypeListItemVo.setPrimaryRelatedContractCode(contractRelation != null ? contractRelation.getContractCode() : null);
				//不在起草中，并且bpmNo不为空，拼装审核链接
				if ((!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) && StringUtils.isNotBlank(contract.getBmpNo())) {
					contractTypeListItemVo.setBpmUrl(getBpmUrl(contract.getBmpNo()));
				}
				buttonItemVos = getButtonListByConfig(contract, attachUrl, contractList, null);
			} else if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractType) || ContractTypeEnum.SETTLEMENT.getCode().equals(contractType)) {
				List<ContractNode> userConfirmNodeList = nodeList.stream().filter(node -> NodeTypeEnum.USER_CONFIRM.getCode().equals(node.getNodeType())).collect(Collectors.toList());
				// 补充协议或和解协议，基于配置能力获取按钮
				buttonItemVos = getButtonListByConfig(contract, attachUrl, contractList, userConfirmNodeList);
				// 不在起草中，并且bpmNo不为空，拼装审核链接
				if ((!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) && StringUtils.isNotBlank(contract.getBmpNo())) {
					contractTypeListItemVo.setBpmUrl(getBpmUrl(contract.getBmpNo()));
				}
			} else {
				buttonItemVos = filterButtonList(getButtonList(contract), canShowButtonList);
			}

			if (!Arrays.asList(ContractStatusEnum.DRAFT.getCode(), ContractStatusEnum.CANCEL.getCode()).contains(contract.getStatus()) && !ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
				//解约协议仅已签署已确认或待签署(申请用章可分享)
				if (ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
					if (ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus())
						|| (ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus()) && CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus()))) {
						if (buttonItemVos.stream().noneMatch(e -> e.getType().equals(PcButtonEnum.SHARE_CONTRACT.getType()))) {
							buttonItemVos.add(new ButtonItemVo(PcButtonEnum.SHARE_CONTRACT));
						}
					}
					if (ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus())) {
						if (buttonItemVos.stream().noneMatch(e -> e.getType().equals(PcButtonEnum.PREVIEW.getType()))) {
							buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
						}
					}
				} else {
					if (buttonItemVos.stream().noneMatch(e -> e.getType().equals(PcButtonEnum.SHARE_CONTRACT.getType()))) {
						buttonItemVos.add(new ButtonItemVo(PcButtonEnum.SHARE_CONTRACT));
					}
				}
			}
			contractTypeListItemVo.setAttachUrl(attachUrl);
			contractTypeListItemVo.setAttachFileType(contractBusinessService.getAttachFileKey(attachUrl));
			contractTypeListItemVo.setButtonList(buttonItemVos);
			contractTypeListItemVo.setContractInfoText(commonContractService.getContractShowListItem(contract, nodeList));
			contractTypeListItemVos.add(contractTypeListItemVo);
		}

		vo.setContractTypeListItemVos(contractTypeListItemVos);
		return vo;
	}

	private List<ButtonItemVo> getButtonList(Contract contract) {
		List<ButtonItemVo> buttonItemVos = new ArrayList<>();
		boolean canPreview = !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()) && contract.getPlatformInstanceId() > 0;

		if (Objects.isNull(contract)) {
			buttonItemVos.add(new ButtonItemVo(PcButtonEnum.CREATE));
		} else {
			int status = contract.getStatus();
			switch (ContractStatusEnum.getContractStatusEnumByCode(status)) {
				case DRAFT:
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.EDIT));

					break;
				case PENDING_USER_SIGN:
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.VIEW));
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.UNDO));
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
					break;
				case PENDING_SUBMIT_AUDIT:
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.VIEW));
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.UNDO));
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
					break;
				case AUDITING:
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.VIEW));
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.UNDO));
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.AUDIT_DETAIL));
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
					break;
				case PENDING_COMPANY_SIGN:
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.VIEW));
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
					break;
				case FINISH:
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.VIEW));
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
					break;
				case CANCEL:
					if (canPreview) {
						buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
					}
					break;
				default:
					break;
			}
		}
		return buttonItemVos;
	}

