	public String saveContractDraft(ZqContractReq body, Integer step, Boolean needCheck, Long createUserId) {
		//抢占锁，防止多次提交
		String lockKey = "";
		if (StringUtils.isNotBlank(body.getContractCode())) {
			Contract contract = contractService.getByContractCode(body.getContractCode());
			if (contract == null) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "未找到对应的合同信息");
			}
			lockKey = LockService.CONTRACT_ORDER_NO_TYPE + contract.getProjectOrderId() + "_" + contract.getType();
		} else if (StringUtils.isNotBlank(body.getProjectOrderId()) && Objects.nonNull(body.getType())) {
			lockKey = LockService.CONTRACT_ORDER_NO_TYPE + body.getProjectOrderId() + "_" + body.getType();
		}
		if (StringUtils.isBlank(lockKey)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "保存草稿失败，非法提交，主键不齐全");
		}

		RLock lock = redissonClient.getLock(lockKey);
		try {
			if (!lock.tryLock(0L, 60L, TimeUnit.SECONDS)) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请勿短时间内多次提交");
			}
		} catch (Exception e) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请勿短时间内多次提交");
		}

		try {
			return saveContractDraftDetail(body, step, needCheck, createUserId);
		} catch (Exception e) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, e.getMessage());
		} finally {
			lock.unlock();
		}
	}

	/**
	 * 保存正签草稿 - pc&home通用 ： pc一次性提交 | home是分步提交
	 *
	 * @param body
	 * @param createUserId
	 * @return
	 */
	public String saveContractDraftDetail(ZqContractReq body, Integer step, Boolean needCheck, Long createUserId) {
		Contract contract = null;
		//兼容home编辑保存的时，只传了contractCode的场景，补齐projectOrderId,type,userSignType
		if (StringUtils.isNotBlank(body.getContractCode())) {
			contract = contractService.getByContractCode(body.getContractCode());
			if (Objects.isNull(contract)) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同不存在，请检查合同编号或联系客服");
			}
			body.setProjectOrderId(contract.getProjectOrderId());
			body.setType(contract.getType());
			body.setUserSignType(contract.getUserSignType());
		} else {
			//没有contractCode，有两种可能 - pc第一次提交 or home第一次编辑(需要找到之前分步提交的草稿)
			List<Contract> contractList = contractService.getContractList(body.getProjectOrderId(), body.getType());
			if (Objects.nonNull(contractList) && !contractList.isEmpty()) {
				contract = contractList.get(0);
			}
		}

		if (Objects.nonNull(contract)) {
			body.setContractCode(contract.getContractCode());
			body.setProjectOrderId(contract.getProjectOrderId());
			body.setType(contract.getType());
			body.setContractCode(contract.getContractCode());

			if (Objects.nonNull(contract.getStatus()) && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同状态不处于草稿中，不允许保存草稿");
			}
		}

		//校验唯一性
		homeAndPcCommonService.checkUnique(body.getProjectOrderId(), body.getChangeOrderId(), body.getContractCode(), body.getType());

		//保存收款计划
		if (Objects.nonNull(body.getCollectionPlanInfo())) {
			fundBaseService.saveCollectionPlan(body.getCollectionPlanInfo());
		}

		//确定当前步骤所涉及的数据范围
		List<ZqContractPartEnum> partEnumList = ZqContractPartEnum.getPartEnumByStep(step);
		//校验数据必填
		if (needCheck) {
			submitCheck(body, partEnumList);
		}

		String contractCode = body.getContractCode();
		String userName = homeAndPcCommonService.getOperatorName(createUserId);

		//删除之前的数据
		if (StringUtils.isNotBlank(contractCode)) {
			//不是分步提交，需要把之前的数据都清空
			if (ZqStepEnum.ALL.getCode().equals(step)) {
				deleteContractInfo(contractCode, false);
			} else {
				//分步提交需要只删除当前步骤下的数据
				deletePartZqData(contractCode, partEnumList);
			}
		}

		contract = queryOrBuildContract(body, createUserId, userName);
		PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(body.getProjectOrderId(), body.getChangeOrderId());
		contract.setAmount(planAllDTO.getPlanInfo().getContractPriceTotal());
		contract.setStatus(ContractStatusEnum.DRAFT.getCode());

		//保存contract
		saveOrUpdateContract(contract);
		contractCode = contract.getContractCode();
		saveContractUser(contractCode, body, createUserId, userName);
		saveContractField(contractCode, body, createUserId, userName);
		saveContractAttach(contractCode, body, createUserId, userName);
		saveContractMaterial(contractCode, body, createUserId, userName);
		saveAttachUser(contractCode, body);
		updateOrSaveContractNode(contractCode, body);

		//保存收款计划快照到【合同收款计划记录表】
		if (Objects.nonNull(body.getCollectionPlanInfo())) {
			contractCollectionPlanRecordService.insertOrUpdate(ContractCollectionPlanRecord.builder()
				.collectionPlan(JSON.toJSONString(body.getCollectionPlanInfo()))
				.contractCode(contractCode)
				.build());
		}
		return contract.getContractCode();
	}

	/**
	 * 删除部分正签数据
	 *
	 * @param contractCode
	 * @param partEnumList
	 */
	private void deletePartZqData(String contractCode, List<ZqContractPartEnum> partEnumList) {
		//签约主体&签约信息
		List<String> deleteFieldKeys = new LinkedList<>();
		if (partEnumList.contains(ZqContractPartEnum.SIGN_OBJECT_INFO)) {
			deleteFieldKeys.addAll(getFieldNames(ZqSignTypeDTO.class));
			//删除线下合同
			contractAttachService.softDeleteByContractCodeAndType(contractCode, AttachTypeEnum.OFFLINE_CONTRACT.getCode());
		}
		if (partEnumList.contains(ZqContractPartEnum.SIGN_INFO)) {
			deleteFieldKeys.addAll(getFieldNames(ZqSignInfoDTO.class));
			//删除user
			contractUserService.deleteByContractCode(contractCode, false);
		}
		if (partEnumList.contains(ZqContractPartEnum.PROJECT_INFO)) {
			deleteFieldKeys.addAll(getFieldNames(ZqContractProjectDTO.class));
			deleteFieldKeys.addAll(getFieldNames(ConstructScheduleVo.class));
		}
		if (partEnumList.contains(ZqContractPartEnum.PROMISE_INFO)) {
			deleteFieldKeys.addAll(getFieldNames(ZqPromiseInfoDTO.class));
			//删除甲供材料清单
			contractMaterialService.delByContractCode(contractCode);
		}
		if (partEnumList.contains(ZqContractPartEnum.GUARANTEE_INFO)) {
			deleteFieldKeys.addAll(getFieldNames(ZqGuaranteeDTO.class));
		}
		if (partEnumList.contains(ZqContractPartEnum.ATTACH)) {
			contractAttachService.softDeleteByContractCodeExcludeType(contractCode, AttachTypeEnum.OFFLINE_CONTRACT.getCode());
		}

		contractFieldService.deleteByContractCodeAndKeys(contractCode, deleteFieldKeys);
	}

	private List<String> getFieldNames(Class cla) {
		List<String> result = new LinkedList<>();

		Field[] fields = cla.getDeclaredFields();
		for (int i = 0; i < fields.length; i++) {
			fields[i].setAccessible(true);
			result.add(fields[i].getName());
		}
		return result;
	}

	public Contract queryOrBuildContract(ZqContractReq body, Long createUserId, String userName) {
		Contract contract = null;
		String contractCode = body.getContractCode();
		//业务类型&分公司，每次都去更新一下
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(body.getProjectOrderId());

		if (Strings.isBlank(contractCode)) {
			//先用projectOrderId+type找一下之前的记录
			if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(body.getType())) {
				contract = findContractByProjectOrderIdAndType(body.getProjectOrderId(), body.getType());
			}
			//新建
			if (Objects.isNull(contract)) {
				contract = buildContract(body, createUserId, userName);
			}
		} else {
			//原有更新
			contract = contractService.getByContractCode(contractCode);
			contract.setGbCode(projectInfoDTO.getCustomerHouse().getGbCode());
			contract.setUserSignType(body.getUserSignType());
			contract.setModifyUserId(String.valueOf(createUserId));
			contract.setModifyUserName(userName);
			if (Objects.nonNull(body.getSignTypeInfo()) && Objects.nonNull(body.getSignTypeInfo().getSignChannelType())) {
				contract.setSignChannelType(body.getSignTypeInfo().getSignChannelType());
			}
			if (Objects.nonNull(body.getSignTypeInfo()) && Objects.nonNull(body.getSignTypeInfo().getSignChannelType())) {
				contract.setUserSignStatus(SignChannelTypeEnum.OFFLINE.getCode().equals(body.getSignTypeInfo().getSignChannelType()) ? CommonEnum.YES.getCode() : CommonEnum.NO.getCode());
			}
		}

		contract.setBusinessType(commonContractService.getBusinessType(projectInfoDTO));
		contract.setCompanyCode(projectInfoDTO.getCustomerCommission().getCompanyCode());

		return contract;
	}

	private Contract findContractByProjectOrderIdAndType(String projectOrderId, Byte type) {
		if (StringUtils.isBlank(projectOrderId) || Objects.isNull(type)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "根据订单号+合同类型查找合同失败, 该参数不能为空" + projectOrderId + ":" + type);
		}
		List<Contract> contractList = contractService.getContractList(projectOrderId, type);
		if (!contractList.isEmpty()) {
			return contractList.get(0);
		}
		return null;
	}

