	public void addSignUser(String contractCode, String projectOrderId, Byte type, Byte haveAgent, Byte contractObjectType) {
		//正签合同/首期款合同--有代理人 代理人是签约人 无代理人客户是签约人
		//变更合同--代理人变化，客户是签约人；代理人没有变化，代理人是签约人
		//变更合同--有代理人，代理人不变，代理人是签约人，代理人变化，客户是签约人；无代理人，客户是签约人
		Byte roleType = null;
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(type)
			|| ContractTypeEnum.DRAWING.getCode().equals(type)
			|| ContractTypeEnum.PERSONAL.getCode().equals(type)
			|| ContractTypeEnum.ADVANCE.getCode().equals(type)) {
			if (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
				roleType = RoleTypeEnum.COMPANY_AGENT.getCode();
			} else {
				roleType = HaveAgentEnum.NO.getCode().equals(haveAgent) ? RoleTypeEnum.OWNER.getCode() : RoleTypeEnum.AGENT.getCode();
			}
		} else if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(type)) {
			if (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
				roleType = RoleTypeEnum.COMPANY_AGENT.getCode();
			} else {
				roleType = HaveAgentEnum.NO.getCode().equals(haveAgent) ? RoleTypeEnum.OWNER.getCode() : (changeContractService.isChangeAgent(contractCode, projectOrderId) ? RoleTypeEnum.OWNER.getCode() : RoleTypeEnum.AGENT.getCode());
			}
		} else {
			roleType = RoleTypeEnum.OWNER.getCode();
		}
		if (Objects.nonNull(roleType)) {
			contractUserService.updateSigner(contractCode, roleType);
		}
	}

	public void addSignUserV2(String contractCode, String projectOrderId, Byte type, ContractSignInfoReq signInfo, Byte agentSign) {
		Byte roleType = contractUnifyService.getSignatoryRoleType(projectOrderId, type, signInfo, agentSign);
		LOGGER.info("{}新增签约人角色：{}", contractCode, roleType);
		contractUserService.updateSigner(contractCode, roleType);
