	 * @param body
	 * @return
	 */
	public List<ContractUser> buildAttachUser(String contractCode, ZqContractReq body) {
		List<ContractUser> contractUserList = contractUserService.getListByContractCode(contractCode);
		List<ContractUser> updateUserList = new LinkedList<>();
		if (CollectionUtils.isNotEmpty(body.getContractAttachList())) {
			List<ZqContractAttachDTO> zqContractAttachDTOList = body.getContractAttachList().stream().filter(Objects::nonNull).collect(Collectors.toList());
			Map<Byte, ContractUser> userMap = contractUserList.stream().collect(Collectors.toMap(ContractUser::getRoleType, e -> e, (v1, v2) -> v2));

			//证件类型映射 -> 用户角色
			Map<Byte, Byte> attachTypeRoleMap = new HashMap<>();
			attachTypeRoleMap.put(ZqAttachTypeEnum.USER_ID.getCode(), UserTypeEnum.OWNER.getCode());
			attachTypeRoleMap.put(ZqAttachTypeEnum.USER_PASSPORT.getCode(), UserTypeEnum.OWNER.getCode());
			attachTypeRoleMap.put(ZqAttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode(), UserTypeEnum.OWNER.getCode());
			attachTypeRoleMap.put(ZqAttachTypeEnum.AGENT_ID.getCode(), UserTypeEnum.AGENT.getCode());
			attachTypeRoleMap.put(ZqAttachTypeEnum.AGENT_PASSPORT.getCode(), UserTypeEnum.AGENT.getCode());
			attachTypeRoleMap.put(ZqAttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode(), UserTypeEnum.AGENT.getCode());
			attachTypeRoleMap.put(ZqAttachTypeEnum.COMPANY_AGENT_ID.getCode(), UserTypeEnum.COMPANY_AGENT.getCode());
			attachTypeRoleMap.put(ZqAttachTypeEnum.COMPANY_AGENT_PASSPORT.getCode(), UserTypeEnum.COMPANY_AGENT.getCode());
			attachTypeRoleMap.put(ZqAttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode(), UserTypeEnum.COMPANY_AGENT.getCode());

			for (ZqContractAttachDTO attachDTO : zqContractAttachDTOList) {
				//不属于用户的证件 || 没有对应的用户
				if (!attachTypeRoleMap.containsKey(attachDTO.getAttachType()) || !userMap.containsKey(attachTypeRoleMap.get(attachDTO.getAttachType()))) {
					continue;
				}

				if (CollectionUtils.isEmpty(attachDTO.getUrls())) {
					continue;
				}

				ContractUser contractUser = userMap.get(attachTypeRoleMap.get(attachDTO.getAttachType()));
				contractUser.setCertificateImg1(attachDTO.getUrls().get(0));
				if (attachDTO.getUrls().size() > 1) {
					contractUser.setCertificateImg2(attachDTO.getUrls().get(1));
				}
				updateUserList.add(contractUser);
			}
		}

		return updateUserList;
	}

	private List<ContractNode> buildContractNode(String contractCode, ZqContractReq body) {
		List<ContractNode> nodeList = new LinkedList<>();
		if (Objects.nonNull(body.getUserSignTime())) {
			nodeList.add(ContractNode.builder()
				.contractCode(contractCode)
				.nodeType(NodeTypeEnum.USER_SIGN.getCode())
				.fireTime(DateUtils.stringToTimeStamp(body.getUserSignTime()))
				.build());
		}
		if (Objects.nonNull(body.getCompanySignTime())) {
			nodeList.add(ContractNode.builder()
				.contractCode(contractCode)
				.nodeType(NodeTypeEnum.COMPANY_SIGN.getCode())
				.fireTime(DateUtils.stringToTimeStamp(body.getCompanySignTime()))
				.build());
		}

		return nodeList;
	}

	private List<ContractField> buildContractField(String contractCode, ZqContractReq body) {
		List<ContractField> list = new ArrayList<>();
		ZqContractProjectDTO zqContractProjectDto = body.getProjectInfo();
		if (Objects.nonNull(zqContractProjectDto)) {
			LOGGER.info("saveContractField contractCode:{} zqContractProjectInfo:{}", contractCode, JsonUtil.toJsonString(zqContractProjectDto));
			Map<String, Object> map = JsonUtil.toObject(JsonUtil.toJsonString(zqContractProjectDto), Map.class);
			for (Map.Entry<String, Object> entry : map.entrySet()) {
				if (Objects.nonNull(entry.getValue())) {
					ContractField field = ContractField.builder().contractCode(contractCode)
						.fieldKey(entry.getKey()).fieldValue(String.valueOf(entry.getValue())).build();
					list.add(field);
				}
			}
		}

		ZqPromiseInfoDTO zqPromiseInfoDTO = body.getPromiseInfo();
		if (Objects.nonNull(zqPromiseInfoDTO)) {
			Map<String, Object> promiseInfoMap = JsonUtil.toObject(JsonUtil.toJsonString(zqPromiseInfoDTO), Map.class);
			for (Map.Entry<String, Object> entry : promiseInfoMap.entrySet()) {
				//甲供材料清单不放在这个里面
				if ("materialList".equals(entry.getKey())) {
					continue;
				}
				if (Objects.nonNull(entry.getValue())) {
					ContractField field = ContractField.builder().contractCode(contractCode)
						.fieldKey(entry.getKey()).fieldValue(String.valueOf(entry.getValue())).build();
					list.add(field);
				}
			}
		}

		//保修
		ZqGuaranteeDTO zqGuaranteeDTO = body.getGuaranteeInfo();
		if (Objects.nonNull(zqGuaranteeDTO)) {
			Map<String, Object> promiseInfoMap = JsonUtil.toObject(JsonUtil.toJsonString(zqGuaranteeDTO), Map.class);
			for (Map.Entry<String, Object> entry : promiseInfoMap.entrySet()) {
				if (Objects.nonNull(entry.getValue())) {
					ContractField field = ContractField.builder().contractCode(contractCode)
						.fieldKey(entry.getKey()).fieldValue(String.valueOf(entry.getValue())).build();
					list.add(field);
				}
			}
		}

		if (Objects.nonNull(body.getSignTypeInfo())) {
			if (Objects.nonNull(body.getSignTypeInfo().getContractObjectType())) {
				ContractField contractObjectTypeField = ContractField.builder().contractCode(contractCode)
					.fieldKey("contractObjectType").fieldValue(String.valueOf(body.getSignTypeInfo().getContractObjectType())).build();
				list.add(contractObjectTypeField);

			}
		}

		if (Objects.nonNull(body.getSignInfo())) {
			if (Objects.nonNull(body.getSignInfo().getHaveAgent())) {
				ContractField haveAgentField = ContractField.builder().contractCode(contractCode)
					.fieldKey("haveAgent").fieldValue(String.valueOf(body.getSignInfo().getHaveAgent())).build();
				list.add(haveAgentField);

			}
			if (Objects.nonNull(body.getSignInfo().getCompanyCreditCode())) {
				ContractField companyCreditCodeField = ContractField.builder().contractCode(contractCode)
					.fieldKey("companyCreditCode").fieldValue(body.getSignInfo().getCompanyCreditCode()).build();
				list.add(companyCreditCodeField);

			}
			if (Objects.nonNull(body.getSignInfo().getCompanyName())) {
				ContractField companyNameField = ContractField.builder().contractCode(contractCode)
					.fieldKey("companyName").fieldValue(body.getSignInfo().getCompanyName()).build();
				list.add(companyNameField);

			}
			if (Objects.nonNull(body.getSignInfo().getOwnerAddress())) {
				ContractField ownerAddressField = ContractField.builder().contractCode(contractCode)
					.fieldKey("ownerAddress").fieldValue(body.getSignInfo().getOwnerAddress()).build();
				list.add(ownerAddressField);
			}
		}

		//保存工期
		if (Objects.nonNull(body.getConstructSchedule())) {
			Map<String, Object> schedule = JsonUtil.toObject(JsonUtil.toJsonString(body.getConstructSchedule()), Map.class);
			schedule.forEach((fieldKey, fieldValue) -> {
				list.add(ContractField.builder()
					.contractCode(contractCode)
					.fieldKey(fieldKey)
					.fieldValue(JsonUtil.toJsonString(fieldValue))
					.build());
			});
		}
		//时间信息
		if (Objects.nonNull(body.getUserSignTime())) {
			list.add(ContractField.builder()
				.contractCode(contractCode)
				.fieldKey(FieldEnum.USER_SIGN_TIME.getKey())
				.fieldValue(body.getUserSignTime())
				.build());
		}
		if (Objects.nonNull(body.getCompanySignTime())) {
			list.add(ContractField.builder()
				.contractCode(contractCode)
				.fieldKey(FieldEnum.COMPANY_SIGN_TIME.getKey())
				.fieldValue(body.getCompanySignTime())
				.build());
		}
		return list;

	}

	private List<ContractMaterial> buildContractMaterial(String contractCode, ZqContractReq body) {
		List<ContractMaterial> materialList = new LinkedList<>();
		if (Objects.nonNull(body.getPromiseInfo()) && Objects.nonNull(body.getPromiseInfo().getMaterialList())) {
			for (MaterialItemVo materialItemVo : body.getPromiseInfo().getMaterialList()) {
				Integer value = materialItemVo.getValue() == null ? 0 : materialItemVo.getValue();
				String unit = StringUtils.isBlank(materialItemVo.getUnit()) ? "" : materialItemVo.getUnit();
				materialList.add(ContractMaterial.builder()
					.contractCode(contractCode)
					.description(materialItemVo.getDescription())
					.value(value)
					.count(Objects.isNull(materialItemVo.getCount()) ? 0 : materialItemVo.getCount())
					.unit(unit)
					.build());
			}
		}

		return materialList;
	}

	private List<ContractUser> buildContractUser(String contractCode, ZqContractReq body) {
		List<ContractUser> list = new ArrayList<>();
		List<ZqContractAttachDTO> zqContractAttachDTOList = body.getContractAttachList();
		Map<Byte, ZqContractAttachDTO> zqContractAttachMap = new HashMap<>();
		if (Objects.nonNull(zqContractAttachDTOList)) {
			zqContractAttachMap = zqContractAttachDTOList.stream().filter(Objects::nonNull).collect(Collectors.toMap(ZqContractAttachDTO::getAttachType,
				Function.identity(), (key1, key2) -> key2));
		}
		ZqSignInfoDTO signInfo = body.getSignInfo();
		ZqSignTypeDTO zqSignTypeDto = body.getSignTypeInfo();

		if (Objects.isNull(zqSignTypeDto) || Objects.isNull(signInfo)) {
			return list;
		}
		//如果是个人合同， 合同人员有业主 或 业主&代理人
		if (ContractObjectTypeEnum.PERSON.getCode().equals(zqSignTypeDto.getContractObjectType())) {
			//业主
			ContractUser owner = new ContractUser();
			owner.setContractCode(contractCode);
			owner.setCertificateType(signInfo.getOwnerCertificateType());
			owner.setName(StringUtils.trim(signInfo.getOwnerName()));
			owner.setRoleType(UserTypeEnum.OWNER.getCode());
			owner.setPhone(signInfo.getOwnerPhone());
			owner.setCertificateNo(signInfo.getOwnerCertificateNo());
			Byte ownerCertificateType = signInfo.getOwnerCertificateType();
			if (Objects.nonNull(ownerCertificateType) && ownerCertificateType.equals(CertificateTypeEnum.ID.getCode())) {
				ZqContractAttachDTO dto = zqContractAttachMap.get(ZqAttachTypeEnum.USER_ID.getCode());
				if (Objects.nonNull(dto) && CollectionUtils.isNotEmpty(dto.getUrls())) {
					owner.setCertificateImg1(dto.getUrls().get(0));
					if (dto.getUrls().size() > 1) {
						owner.setCertificateImg2(dto.getUrls().get(1));
					}
				}
			} else if (Objects.nonNull(ownerCertificateType) && ownerCertificateType.equals(CertificateTypeEnum.PASSPORT.getCode())) {
				ZqContractAttachDTO dto = zqContractAttachMap.get(ZqAttachTypeEnum.USER_PASSPORT.getCode());
				if (Objects.nonNull(dto) && CollectionUtils.isNotEmpty(dto.getUrls())) {
					owner.setCertificateImg1(dto.getUrls().get(0));
				}
			}
			list.add(owner);
			//有代理人
			if (HaveAgentEnum.YES.getCode().equals(signInfo.getHaveAgent())) {
				ContractUser agent = new ContractUser();
				agent.setContractCode(contractCode);
				agent.setCertificateType(signInfo.getAgentCertificateType());
				agent.setName(StringUtils.trim(signInfo.getAgentName()));
				agent.setRoleType(UserTypeEnum.AGENT.getCode());
				agent.setPhone(signInfo.getAgentPhone());
				agent.setCertificateNo(signInfo.getAgentCertificateNo());
				Byte agentCertificateType = signInfo.getAgentCertificateType();
				if (Objects.nonNull(agentCertificateType) && agentCertificateType.equals(CertificateTypeEnum.ID.getCode())) {
					ZqContractAttachDTO dto = zqContractAttachMap.get(ZqAttachTypeEnum.AGENT_ID.getCode());
					if (Objects.nonNull(dto) && CollectionUtils.isNotEmpty(dto.getUrls())) {
						agent.setCertificateImg1(dto.getUrls().get(0));
						if (dto.getUrls().size() > 1) {
							agent.setCertificateImg2(dto.getUrls().get(1));
						}
					}
				} else if (Objects.nonNull(agentCertificateType) && agentCertificateType.equals(CertificateTypeEnum.PASSPORT.getCode())) {
					ZqContractAttachDTO dto = zqContractAttachMap.get(ZqAttachTypeEnum.AGENT_PASSPORT.getCode());
					if (Objects.nonNull(dto) && CollectionUtils.isNotEmpty(dto.getUrls())) {
						agent.setCertificateImg1(dto.getUrls().get(0));
					}
				}
				list.add(agent);
			}

		}

		//公司经办人
		if (ContractObjectTypeEnum.COMPANY.getCode().equals(zqSignTypeDto.getContractObjectType())) {
			ContractUser companyAgent = new ContractUser();
			companyAgent.setContractCode(contractCode);
			companyAgent.setCertificateType(signInfo.getCompanyAgentCertificateType());
			companyAgent.setName(StringUtils.trim(signInfo.getCompanyAgentName()));

			companyAgent.setRoleType(UserTypeEnum.COMPANY_AGENT.getCode());
			companyAgent.setPhone(signInfo.getCompanyAgentPhone());
			companyAgent.setCertificateNo(signInfo.getCompanyAgentCertificateNo());
			Byte companyAgentCertificateType = signInfo.getCompanyAgentCertificateType();
			if (Objects.nonNull(companyAgentCertificateType) && companyAgentCertificateType.equals(CertificateTypeEnum.ID.getCode())) {
				ZqContractAttachDTO dto = zqContractAttachMap.get(ZqAttachTypeEnum.COMPANY_AGENT_ID.getCode());
				if (Objects.nonNull(dto) && CollectionUtils.isNotEmpty(dto.getUrls())) {
					companyAgent.setCertificateImg1(dto.getUrls().get(0));
					if (dto.getUrls().size() > 1) {
						companyAgent.setCertificateImg2(dto.getUrls().get(1));
					}
				}
			} else if (Objects.nonNull(companyAgentCertificateType) && companyAgentCertificateType.equals(CertificateTypeEnum.PASSPORT.getCode())) {
				ZqContractAttachDTO dto = zqContractAttachMap.get(ZqAttachTypeEnum.COMPANY_AGENT_PASSPORT.getCode());
				if (Objects.nonNull(dto) && CollectionUtils.isNotEmpty(dto.getUrls())) {
					companyAgent.setCertificateImg1(dto.getUrls().get(0));
				}
			}
			list.add(companyAgent);
		}
		return list;
	}

	private Contract buildContract(ZqContractReq body, Long createUserId, String createUserName) {
		String projectOrderId = body.getProjectOrderId();
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		if (Objects.isNull(projectInfoDTO) || Objects.isNull(projectInfoDTO.getCustomerCommission())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目缺少分公司信息");
		}
		String companyCode = contractBusinessService.getCompanyCode(projectOrderId);
		//pc的只有一个配置，需要读取列表
		List<ContractCityCompanyInfo> configList = contractCityCompanyConfigService.getConfig(
			projectOrderId,
			projectInfoDTO.getCustomerHouse().getGbCode(),
			companyCode,
			commonContractService.getBusinessType(projectInfoDTO),
			body.getType()
		);
		if (CollectionUtils.isEmpty(configList)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少合同配置信息");
		}
		ContractCityCompanyInfo config = configList.get(0);
		return Contract.builder()
			.contractCode(RandomCodeUtils.generateContractCode())
			.contractNo(RandomCodeUtils.generateContractNo())
			.userSignType(body.getUserSignType())
			.type(body.getType())
			.changeOrderId(body.getChangeOrderId())
			.gbCode(projectInfoDTO.getCustomerHouse().getGbCode())
			.signChannelType(body.getSignTypeInfo().getSignChannelType())
			.projectOrderId(projectOrderId)
			.businessType(commonContractService.getBusinessType(projectInfoDTO))
			.auditType(config.getAuditType().byteValue())
			.companyCode(companyCode)
			.userSignStatus(SignChannelTypeEnum.OFFLINE.getCode().equals(body.getSignTypeInfo().getSignChannelType()) ? CommonEnum.YES.getCode() : CommonEnum.NO.getCode())
			.createUserId(createUserId.toString())
			.createUserName(createUserName)
			.modifyUserId(createUserId.toString())
			.modifyUserName(createUserName)
			.build();

	}

	/**
	 * 一次性提交 - PC
	 *
	 * @param body
	 * @param createUserId
	 * @return
	 */
	public SubmitResultVo submit(ZqContractReq body, Long createUserId) {
		// 项目单号转换
		//根据合同类型获取项目单号
		ContractCreateBaseInfo canCreateContract = commonBusinessService.getCanCreateContract(body.getProjectOrderId(), body.getType(), null);
		if (ObjectUtil.isNotEmpty(canCreateContract)) {
			body.setProjectOrderId(canCreateContract.getProjectOrderId());
			body.setType(canCreateContract.getContractType());
		}
		//抢占锁，防止多次提交
		String lockKey = LockService.CONTRACT_ORDER_NO_TYPE + body.getProjectOrderId() + "_" + body.getType();
		RLock lock = redissonClient.getLock(lockKey);
		try {
			if (!lock.tryLock(0L, 60L, TimeUnit.SECONDS)) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请勿短时间内多次提交");
			}
		} catch (Exception e) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请勿短时间内多次提交");
		}

		try {
			return submitDetail(body, createUserId);
		} catch (Exception e) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, e.getMessage());
		} finally {
			lock.unlock();
		}
	}

	/**
	 * 真正的处理提交
	 *
	 * @param body
	 * @param createUserId
	 * @return
	 */
	private SubmitResultVo submitDetail(ZqContractReq body, Long createUserId) {
		LOGGER.info("合同提交 body:{} createUserId:{}", JSONObject.toJSONString(body), createUserId);
		//收款计划保存
		fundBaseService.saveCollectionPlan(body.getCollectionPlanInfo());

		String projectOrderId = body.getProjectOrderId();
		Contract contract;

		//唯一性校验
		homeAndPcCommonService.checkUnique(body.getProjectOrderId(), body.getChangeOrderId(), body.getContractCode(), body.getType());
		//判断是否可创建
		homeAndPcCommonService.checkCanCreate(body.getProjectOrderId(), body.getType(), body.getUserSignType());
		//判断字段是否合法
		submitCheck(body, ZqContractPartEnum.getPartEnumByStep(ZqStepEnum.ALL.getCode()));
		SubmitResultVo result = new SubmitResultVo();
		result.setResult(ResultStatusEnum.SUCCESS.getCode().intValue());

		//合同构造
		String userName = homeAndPcCommonService.getOperatorName(createUserId);
		contract = queryOrBuildContract(body, createUserId, userName);

		//校验状态
		if (Objects.nonNull(contract.getStatus()) && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同状态非草稿中，不能提交");
		}

		contract.setStatus(homeAndPcCommonService.getContractSubmitStatus(contract));
		String contractCode = contract.getContractCode();
		ZqContractProjectDTO projectDto = body.getProjectInfo();

		// 修改优惠信息，增加判断是否走中控
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		if (Objects.isNull(projectInfoDTO) || StringUtils.isBlank(projectInfoDTO.getCenterControlFlag())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取项目是否走中控失败");
		}

		//获取工期计算-非阻塞性，调用失败，允许继续走-只有家装的才走
		if (BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType())) {
			ConstructScheduleVo constructScheduleVo = calculateSchedule(projectOrderId, body.getType(), projectDto.getArea(),
				projectDto.getPlanStartTime(), projectDto.getToiletCnt(),
				projectDto.getHouseType(), projectDto.getHouseBuildType());

			if (constructScheduleVo != null && constructScheduleVo.getTotalPeriod() != null && constructScheduleVo.getTotalPeriod() <= 0) {
				LOGGER.error("发起签约获取到总工期<=0，projectOrderId:{},constructScheduleVo:{}", projectOrderId, constructScheduleVo);
			}

			if (constructScheduleVo != null && constructScheduleVo.getTotalPeriod() != null && constructScheduleVo.getTotalPeriod() > 0) {
				LOGGER.info("设置工期，projectOrderId：{},总工期：{}", projectOrderId, constructScheduleVo.getTotalPeriod().intValue());
				body.getProjectInfo().setTotalDuration(constructScheduleVo.getTotalPeriod().intValue());
			}
			body.setConstructSchedule(constructScheduleVo);
			if (body.getProjectInfo().getTotalDuration() == null) {
				body.getProjectInfo().setTotalDuration(0);
			}
		}

		//生成pdf
		PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(body.getProjectOrderId(), body.getChangeOrderId());//保存优惠后获取当前报价信息
		String pdfUrl = "";
		if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
			String companyCode = contractBusinessService.getCompanyCode(contract.getProjectOrderId());
			FormalPackageContractFreeformDTO formalPackageContractFreeformDTO =
				buildFormalPackageContractFreeformDTO(companyCode, createUserId, body,
					contract.getContractNo(), planAllDTO, contract.getBusinessType());
			ObjectMapper objectMapper = new ObjectMapper();
			Map<String, Object> map = objectMapper.convertValue(formalPackageContractFreeformDTO, Map.class);

			pdfUrl = contractBusinessService.generatePdf(contract, map);
		}


		//扣减产能
		String address = getProjectInfoAddress(projectDto.getDistrictName(), projectDto.getResblockName(), projectDto.getBuildingName(),
			projectDto.getUnitName(), projectDto.getFloorName(), projectDto.getHouseName());
		Long designerUcId = null;
		ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
		if (Objects.nonNull(designer)) {
			designerUcId = designer.getUcId();
		}
		LocalDate date = LocalDate.parse(body.getProjectInfo().getPlanStartTime(), DateTimeFormatter.ofPattern("yyyy-MM-dd"));

		DecrQuotaParam decrQuotaParam = new DecrQuotaParam(Long.valueOf(projectOrderId), date, SOURCE_TYPE,
			null, String.valueOf(body.getProjectInfo().getGbCode()), body.getProjectInfo().getMarketingCode(),
			designerUcId, body.getProjectInfo().getResblockId(), address);

		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(commonContractService.getBusinessType(projectInfoDTO))) {
			quotaCalenderFeignService.decrQuotaWithRollbackV2(decrQuotaParam);
		}

		//客源回写信息
		rewriteCustomer(body);
		if (StringUtils.isNotBlank(contractCode)) {
			deleteContractInfo(contractCode, true); //删除合同信息
		}

		contract.setAmount(planAllDTO.getPlanInfo().getContractPriceTotal());

		//设置对用户可见
		boolean userCanSee = SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType()) || !AuditTypeEnum.BEFORE_SIGN.getCode().equals(contract.getAuditType());
		contract.setUserQueryStatus(userCanSee ? UserQueryStatusEnum.VALID.getCode() : UserQueryStatusEnum.INVALID.getCode());

		//保存contract
		saveOrUpdateContract(contract);
		saveContractUser(contractCode, body, createUserId, userName);
		saveContractField(contractCode, body, createUserId, userName);
		saveContractAttach(contractCode, body, createUserId, userName);
		saveContractMaterial(contractCode, body, createUserId, userName);
		updateOrSaveContractNode(contractCode, body);

		//保存收款计划快照到【合同收款计划记录表】
		contractCollectionPlanRecordService.insertOrUpdate(ContractCollectionPlanRecord.builder()
			.collectionPlan(JSON.toJSONString(body.getCollectionPlanInfo()))
			.contractCode(contractCode)
			.build());

		//日志&消息
		doAfterSubmit(contract);
		result.setContractUrl(pdfUrl);
		result.setContractCode(contractCode);
		return result;
	}

	/**
	 * 分步提交 - Home
	 *
	 * @param body
	 * @param createUserId
	 * @return
	 */
	public SubmitResultVo stepSubmit(ZqContractReq body, Long createUserId) {
		if (Objects.isNull(body.getContractCode()) && (Objects.isNull(body.getProjectOrderId()) || Objects.isNull(body.getType()))) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "订单号和合同类型不能为空");
		}

		Contract contract = null;
		if (StringUtils.isBlank(body.getContractCode())) {
			List<Contract> contractList = contractService.getContractList(body.getProjectOrderId(), body.getType());
			if (!contractList.isEmpty()) {
				contract = contractList.get(0);
			}
		} else {
			contract = contractService.getByContractCode(body.getContractCode());
		}
		//分步提交，一定会存在之前提交的合同数据
		if (Objects.isNull(contract)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "提交失败，合同数据不存在");
		}
		if (!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "已有其他在途合同,不可重复创建-[签约]");
		}

		//获取详情
		ZqContractDetailResp detailResp = getZqContractDetail(contract.getProjectOrderId(), contract.getType(), contract.getContractCode(), false);

		ZqContractReq zqContractReq = ZqContractReq.builder()
			.projectOrderId(contract.getProjectOrderId())
			.contractCode(contract.getContractCode())
			.type(contract.getType())
			.changeOrderId(contract.getChangeOrderId())
			.userSignType(contract.getUserSignType())
			.projectInfo(detailResp.getProjectInfo())
			.signTypeInfo(detailResp.getSignTypeInfo())
			.signInfo(detailResp.getSignInfo())
			.contractAttachList(detailResp.getContractAttachList())
			.promiseInfo(detailResp.getPromiseInfo())
			.guaranteeInfo(detailResp.getGuaranteeInfo())
			.collectionPlanInfo(detailResp.getCollectionPlanConfigInfo())
			.constructSchedule(detailResp.getConstructSchedule())
			.userSignTime(detailResp.getUserSignTime())
			.companySignTime(detailResp.getCompanySignTime())
			.build();

		return submit(zqContractReq, createUserId);
	}

	public void doAfterSubmit(Contract contract) {
		//日志&消息
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.SUBMIT.getCode(), LogTypeEnum.SUBMIT.getName(), "", contract.getModifyUserId(), contract.getModifyUserName());
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.STATUS_CHANGE.getCode(), LogTypeEnum.STATUS_CHANGE.getName(), contract.getStatus().toString());
		contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.SUBMIT.getCode());

		//记录附件齐全
		boolean uploadStatus = checkAttach(contract.getContractCode());
		if (uploadStatus) {//提交合同如果附件齐全，也需要记录日志和节点
			//附件上传完毕，如果附件齐全，侧添加日志信息
			contractBusinessService.remarkSupplementLog(contract);
			//添加合同节点
			contractBusinessService.remarkSupplementNode(contract.getContractCode());
		}

		eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_SUBMIT, contract.getContractCode());
	}

	public ConstructScheduleVo calculateSchedule(String projectOrderId, Byte contractType, String area, String planStartTime, Integer toiletCnt,
												 Integer houseType, Integer houseBuildType) {
		boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode())
			&& BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(commonBusinessService.getBusinessType(projectOrderId));
		//2.5系统单子房屋类型为别墅等依旧请求工期系统
		if (!commonContractService.needPeriodByHouseBuildType(houseBuildType) && !houseProcessV25) {
			return new ConstructScheduleVo();
		}
		if (StringUtils.isNotBlank(projectOrderId)
			&& Objects.nonNull(contractType)
			&& StringUtils.isNotBlank(area)
			&& StringUtils.isNotBlank(planStartTime)
			&& Objects.nonNull(toiletCnt)
			&& Objects.nonNull(houseType)
			&& houseType > 0
			&& Objects.nonNull(houseBuildType)
			&& houseBuildType > 0
		) {
			try {
				Integer signingStatus = ContractTypeEnum.PACKAGE_CHANGE.equals(contractType) ? 2 : 1;
				ScheduleCalculateDTO schedule = constructScheduleFeignService.calculateSchedule(
					projectOrderId,
					signingStatus,
					BigDecimal.valueOf(Double.parseDouble(area)),
					planStartTime,
					houseType,
					toiletCnt,
					houseBuildType);
				ConstructScheduleVo scheduleVo = new ConstructScheduleVo();
				BeanUtils.copyProperties(schedule, scheduleVo);
				return scheduleVo;
			} catch (Exception e) {
				LOGGER.info("获取工期失败, e: {}", e.getMessage());
			}
		}
		return null;
	}

	private String getProjectInfoAddress(String districtName, String resblockName, String buildingName, String unitName, String floorName, String houseName) {

		districtName = StringUtils.isBlank(districtName) ? "" : districtName;
		resblockName = StringUtils.isBlank(resblockName) ? "" : resblockName;
		buildingName = StringUtils.isBlank(buildingName) ? "" : buildingName;
		unitName = StringUtils.isBlank(unitName) ? "" : unitName;
		floorName = StringUtils.isBlank(floorName) ? "" : floorName;
		houseName = StringUtils.isBlank(houseName) ? "" : houseName;
		return districtName + resblockName + buildingName + unitName + floorName + houseName;
	}

	private FormalPackageContractFreeformDTO buildFormalPackageContractFreeformDTO(String companyCode, Long createUserId, ZqContractReq body, String contractNo,
																				   PlanAllDTO planAllDTO, Byte businessType) {
		String projectOrderId = body.getProjectOrderId();
		CompanyInfoDTO companyInfoDTO = commonContractService.getCompanyInfo(companyCode);

		String firstPayAmountText = "";
		String secondPayAmountText = "";
		String thirdPayAmountText = "";
		String firstPayAmount = "";
		String secondPayAmount = "";
		String thirdPayAmount = "";

		//收款计划
		CollectionPlanConfigInfo configInfo = body.getCollectionPlanInfo();
		String payPlan = "";
		//合同金额
		BigDecimal contractAmount = planAllDTO.getPlanInfo().getContractPriceTotal();
		if (Objects.nonNull(configInfo)) {
			StringBuilder payPlanBuffer = new StringBuilder();
			List<CollectionPlanItem> content = configInfo.getContent();

			for (int i = 0; i < content.size(); i++) {
				CollectionPlanItem item = content.get(i);
				BigDecimal itemAmount = Objects.nonNull(item.getPrice()) && BigDecimal.ZERO.compareTo(item.getPrice()) != 0 ? item.getPrice() : contractAmount.multiply(item.getRate()).setScale(2, RoundingMode.HALF_UP);
				payPlanBuffer.append(MessageFormat.format(PAY_PLAN_FORMAT
					, item.getCollectionName(),
					item.getLastPayNode(),
					item.getRate().multiply(new BigDecimal(100)).toString(),
					(new MoneyConvertUtil(itemAmount.toString())).convert(),
					itemAmount.toString()
				));

				if (Objects.nonNull(item.getPrice())) {
					if (i == 0) {
						firstPayAmount = item.getPrice().toString();
						firstPayAmountText = (new MoneyConvertUtil(item.getPrice().toString())).convert();
					} else if (i == 1) {
						secondPayAmount = item.getPrice().toString();
						secondPayAmountText = (new MoneyConvertUtil(item.getPrice().toString())).convert();
					} else if (i == 2) {
						thirdPayAmount = item.getPrice().toString();
						thirdPayAmountText = (new MoneyConvertUtil(item.getPrice().toString())).convert();
					}
				}
			}

			payPlan = payPlanBuffer.toString();
		}

		//报价
		List<PlanAttachmentDTO> list = planAllDTO.getPlanAttachmentList();
		String budgetUrl = "";
		String internalConfigurationsUrl = "";
		String extraConfigurationsUrl = "";
		String personalQuotionUrl = "";
		String baseConstructionDrawUrl = "";
		if (CollectionUtils.isNotEmpty(list)) {
			for (PlanAttachmentDTO planAttachmentDTO : list) {
				List<String> srcs = pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl());
				String signDate = DateUtils.getDateStr(new Date());
				List<FormalPackageContractFreeformDTO.Photo> photos;
				switch (planAttachmentDTO.getFileType()) {
					case PlanAttachment.报价单:
						photos = srcs.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
						budgetUrl = JsonUtil.toJsonString(photos);
						break;
					case PlanAttachment.套餐套内配置清单:
						photos = srcs.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
						internalConfigurationsUrl = JsonUtil.toJsonString(photos);
						break;
					case PlanAttachment.加载配置清单:
						srcs = pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl());
						photos = srcs.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
						extraConfigurationsUrl = JsonUtil.toJsonString(photos);
						break;
					case PlanAttachment.套外个性化报价单:
						srcs = pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl());
						photos = srcs.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
						personalQuotionUrl = JsonUtil.toJsonString(photos);
						break;
					case PlanAttachment.基础图纸:
						srcs = pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl());
						photos = srcs.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
						baseConstructionDrawUrl = JsonUtil.toJsonString(photos);
						break;
					default:
				}
			}
		}

		//兼容团装历史数据
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && StrUtil.isBlank(internalConfigurationsUrl)) {
			internalConfigurationsUrl = budgetUrl;
		}

		//整装必须要有报价单，团装必须要有套餐套内配置清单
		if (!BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && Objects.isNull(budgetUrl)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "中控模式下，缺少报价单PDF文件，请联系预算员在报价中生成PDF");
		}

		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && Objects.isNull(internalConfigurationsUrl)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "中控模式下，缺少套餐套内配置清单PDF文件，请联系预算员在报价中生成PDF");
		}

		//精装细则
		String urls = "";
		if (Objects.nonNull(planAllDTO.getPlanInfo())) {
			//旧逻辑，无使用
		  List<String> ruleUrls = comboInfoService.getAllUrls(body.getProjectOrderId(), body.getType(), planAllDTO.getPlanInfo().getComboCode());
		  String signDate = DateUtils.getDateStr(new Date());
		  List<FormalPackageContractFreeformDTO.Photo> photos = ruleUrls.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
		  urls = JsonUtil.toJsonString(photos);
	  }

		String clearDay = "";
		String projectContractMode = "";
		String constructionDrawMode = "";
		String afterDiscountDesignerAmount = "/";

		if (Objects.nonNull(body.getPromiseInfo())) {
			ZqPromiseInfoDTO promiseInfoDTO = body.getPromiseInfo();
			clearDay = Objects.nonNull(promiseInfoDTO.getClearDay()) ? String.valueOf(promiseInfoDTO.getClearDay()) : "";
			projectContractMode = Objects.nonNull(ProjectContractModeEnum.getNameByCode(promiseInfoDTO.getProjectContractModeCode())) ? String.valueOf(promiseInfoDTO.getProjectContractModeCode()) : "";
			constructionDrawMode = Objects.nonNull(ConstructionDrawModeEnum.getNameByCode(promiseInfoDTO.getConstructionDrawMode())) ? String.valueOf(promiseInfoDTO.getConstructionDrawMode()) : "";
			afterDiscountDesignerAmount = Objects.nonNull(promiseInfoDTO.getAfterDiscountDesignerAmount()) ? String.valueOf(promiseInfoDTO.getAfterDiscountDesignerAmount()) : "/";
		}

		String couponAmount = "";
		String couponRemark = "";
		List<String> couponRemarkList = contractBusinessService.getCouponRemarkList(planAllDTO);
		if (CollectionUtils.isNotEmpty(planAllDTO.getCouponList())) {
			for (CouponDTO couponDTO : planAllDTO.getCouponList()) {
				if (CouponTypeEnum.DIRECT_COUPON.getCode().equals(couponDTO.getCouponType())) {
					couponAmount = couponDTO.getLapseAmount().toString();
				}
			}
		}

		couponRemark = StringUtils.join(couponRemarkList.toArray(), "\n");
		String designerName = "/";

		ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
		if (Objects.nonNull(designer) && StringUtils.isNotBlank(designer.getName())) {
			designerName = designer.getName();
		}

		String secondDrawModeName = designerName;
		ZqPromiseInfoDTO zqPromiseInfoDTO = body.getPromiseInfo();
		if (Objects.nonNull(zqPromiseInfoDTO) && ConstructionDrawModeEnum.ATTACH.getCode().equals(zqPromiseInfoDTO.getConstructionDrawMode())) {
			secondDrawModeName = "/";
		}

		String budgeter = "";
		ProjectServerInfoDTO projectOrderData = projectOrderFeignService.queryProjectServerInfo(projectOrderId, ServerTypeEnum.BUDGETER);
		if (Objects.nonNull(projectOrderData)) {
			budgeter = projectOrderData.getName();
		}
		ZqContractProjectDTO projectInfo = body.getProjectInfo();
		ZqSignInfoDTO signInfo = body.getSignInfo();
		String address = projectInfo.getCertificateAddress();

		String ownerAddress = StringUtils.isBlank(signInfo.getOwnerAddress()) ? "" : signInfo.getOwnerAddress();
		String agentName = StringUtils.isBlank(signInfo.getAgentName()) ? "/" : signInfo.getAgentName();
		String agentIdNo = "/";
		String agentPhone = StringUtils.isBlank(signInfo.getAgentPhone()) ? "/" : signInfo.getAgentPhone();
		String customerIdNo = "/";
		if (Objects.nonNull(signInfo.getAgentCertificateNo())) {
			agentIdNo = StringUtils.isBlank(signInfo.getAgentCertificateNo()) ? "/" : signInfo.getAgentCertificateNo();
		}

		if (Objects.nonNull(signInfo.getOwnerCertificateNo())) {
			customerIdNo = signInfo.getOwnerCertificateNo();
		}

		String beforeDeliveryDaysToWork = Objects.isNull(body.getPromiseInfo().getBeforeDeliveryDaysToWork()) ? "" : body.getPromiseInfo().getBeforeDeliveryDaysToWork().toString();
		String otherGuaranteeYear = Objects.isNull(body.getGuaranteeInfo()) || Objects.isNull(body.getGuaranteeInfo().getOtherGuaranteeYear())
			? "" : body.getGuaranteeInfo().getOtherGuaranteeYear().toString();
		String waterElectricGuaranteeYear = Objects.isNull(body.getGuaranteeInfo()) || Objects.isNull(body.getGuaranteeInfo().getWaterElectricGuaranteeYear())
			? "" : body.getGuaranteeInfo().getWaterElectricGuaranteeYear().toString();
		String waterProofGuaranteeYear = Objects.isNull(body.getGuaranteeInfo()) || Objects.isNull(body.getGuaranteeInfo().getWaterProofGuaranteeYear())
			? "" : body.getGuaranteeInfo().getWaterProofGuaranteeYear().toString();
		//兼容枚举的情况

		if (Objects.nonNull(body.getGuaranteeInfo()) && Objects.nonNull(body.getGuaranteeInfo().getWaterProofGuaranteeYearEnum())) {
			waterProofGuaranteeYear = body.getGuaranteeInfo().getWaterProofGuaranteeYearEnum().toString();
		}
		if (Objects.nonNull(body.getGuaranteeInfo()) && Objects.nonNull(body.getGuaranteeInfo().getOtherGuaranteeYearEnum())) {
