		List<ContractAttach> originContractAttachList = contractAttachService.getListByContractCode(contractCode);

		List<ContractUser> contractUserList = contractUserService.getListByContractCode(contractCode);
		List<ContractMaterial> materialList = contractMaterialService.getListByContractCode(contractCode);

		// 2.合同字段信息
		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contractCode);

		Map<String, String> map = Maps.newHashMap();
		contractFieldList.forEach(contractField -> map.put(contractField.getFieldKey(), contractField.getFieldValue()));

		// 1.签约主体信息
		ZqSignInfoDTO zqSignInfoDto = getZqSignInfoDTO(isDetail, contractCode, map, zqCustomerPhoneVoList);


		Byte haveAgent = StringUtils.isBlank(map.get("haveAgent")) ? null : Byte.valueOf(map.get("haveAgent"));

		Byte contractObjectType = StringUtils.isBlank(map.get("contractObjectType")) ? null : Byte.valueOf(map.get("contractObjectType"));

		ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
		Long designerId = null;
		String designerName = "";
		if (Objects.nonNull(designer)) {
			designerId = designer.getUcId();
			designerName = designer.getName();
		}
		ZqContractProjectDTO zqContractProjectDto = commonContractService.recordConvert2ZqContractDto(contractFieldList);
		zqContractProjectDto.setAddress(homeAndPcCommonService.getAddress(projectInfoReadService.getByProjectOrderIdWithoutCache(contract.getProjectOrderId())));
		zqContractProjectDto.setDesignerUcId(designerId);
		zqContractProjectDto.setDesignerName(designerName);
		zqContractProjectDto.setDecorateFormLevel1(Objects.nonNull(projectInfoDTO.getCustomerCommission().getDecorateType()) ? projectInfoDTO.getCustomerCommission().getDecorateType().intValue() : null);
		zqContractProjectDto.setDecorateFormLevel1Text(projectInfoDTO.getCustomerCommission().getDecorateTypeDesc());
		zqContractProjectDto.setDecorateFormLevel2(Objects.nonNull(projectInfoDTO.getCustomerCommission().getDecorateId()) ? projectInfoDTO.getCustomerCommission().getDecorateId().intValue() : null);
		zqContractProjectDto.setDecorateFormLevel2Text(projectInfoDTO.getCustomerCommission().getDecorateIdDesc());
		ZqPromiseInfoDTO zqPromiseInfoDTO = ZqPromiseInfoDTO.builder().build();
		Integer projectContractModeCode = map.containsKey("projectContractModeCode") ? Integer.valueOf(map.get("projectContractModeCode")) : null;
		Integer clearDay = map.containsKey("clearDay") ? Integer.valueOf(map.get("clearDay")) : null;
		Integer taxRate = map.containsKey("taxRate") ? Integer.valueOf(map.get("taxRate")) : null;
		Integer disputeDealMode = map.containsKey("disputeDealMode") ? Integer.valueOf(map.get("disputeDealMode")) : null;
		List<MaterialItemVo> materialItemVoList = new LinkedList<>();
		zqPromiseInfoDTO.setProjectContractModeCode(projectContractModeCode);
		zqPromiseInfoDTO.setProjectContractModeName(ProjectContractModeEnum.getNameByCode(projectContractModeCode));
		zqPromiseInfoDTO.setClearDay(clearDay);
		zqPromiseInfoDTO.setTaxRate(taxRate);
		zqPromiseInfoDTO.setDisputeDealMode(disputeDealMode);
		zqPromiseInfoDTO.setDisputeDealModeText(DisputeDealModeEnum.getNameByCode(disputeDealMode));
		for (ContractMaterial contractMaterial : materialList) {
			List<Integer> materialTypeValues = contractApolloConfig.getMaterialTypes().stream().map(OptionVo::getValue).collect(Collectors.toList());
			//起草中合同不返回自定义的材料信息;起草中合同不返回已删除的材料类型的材料信息
			if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()) && (0 == contractMaterial.getValue() || !materialTypeValues.contains(
				contractMaterial.getValue()))) {
				continue;
			}
			materialItemVoList.add(MaterialItemVo.builder()
				.description(contractMaterial.getDescription())
				.count(contractMaterial.getCount())
				.value(contractMaterial.getValue())
				.unit(contractMaterial.getUnit())
				.build());
		}
		zqPromiseInfoDTO.setMaterialList(materialItemVoList);

		Integer constructionDrawMode = map.containsKey("constructionDrawMode") ? Integer.parseInt(map.get("constructionDrawMode")) : 0;
		Integer needDesignerAmount = map.containsKey("needDesignerAmount") ? Integer.valueOf(map.get("needDesignerAmount")) : 0;
		Double afterDiscountDesignerAmount = map.containsKey("afterDiscountDesignerAmount") ? Double.valueOf(map.get("afterDiscountDesignerAmount")) : null;
		Integer beforeDeliveryDaysToWork = map.containsKey("beforeDeliveryDaysToWork") ? Integer.parseInt(map.get("beforeDeliveryDaysToWork")) : null;
		zqPromiseInfoDTO.setConstructionDrawMode(constructionDrawMode);
		zqPromiseInfoDTO.setNeedDesignerAmount(needDesignerAmount);
		zqPromiseInfoDTO.setAfterDiscountDesignerAmount(afterDiscountDesignerAmount);
		zqPromiseInfoDTO.setBeforeDeliveryDaysToWork(beforeDeliveryDaysToWork);

		//保修
		ZqGuaranteeDTO zqGuaranteeDTO = new ZqGuaranteeDTO();
		Integer otherGuaranteeYear = map.containsKey("otherGuaranteeYear") ? Integer.parseInt(map.get("otherGuaranteeYear")) : null;
		Integer waterProofGuaranteeYear = map.containsKey("waterProofGuaranteeYear") ? Integer.parseInt(map.get("waterProofGuaranteeYear")) : null;
		Integer waterElectricGuaranteeYear = map.containsKey("waterElectricGuaranteeYear") ? Integer.parseInt(map.get("waterElectricGuaranteeYear")) : null;
		Integer waterProofGuaranteeYearEnum = map.containsKey("waterProofGuaranteeYearEnum") ? Integer.parseInt(map.get("waterProofGuaranteeYearEnum")) : null;
		Integer otherGuaranteeYearEnum = map.containsKey("otherGuaranteeYearEnum") ? Integer.parseInt(map.get("otherGuaranteeYearEnum")) : null;
		zqGuaranteeDTO.setOtherGuaranteeYear(otherGuaranteeYear);
		zqGuaranteeDTO.setWaterProofGuaranteeYear(waterProofGuaranteeYear);
		zqGuaranteeDTO.setWaterElectricGuaranteeYear(waterElectricGuaranteeYear);
		zqGuaranteeDTO.setWaterProofGuaranteeYearEnum(waterProofGuaranteeYearEnum);
		zqGuaranteeDTO.setWaterProofGuaranteeYearEnumText(WaterProofGuaranteeYearEnum.getNameByCode(waterProofGuaranteeYearEnum));
		zqGuaranteeDTO.setOtherGuaranteeYearEnum(otherGuaranteeYearEnum);
		zqGuaranteeDTO.setOtherGuaranteeYearEnumText(OtherGuaranteeYearEnum.getNameByCode(otherGuaranteeYearEnum));

		// 3.正签类型

		ZqSignTypeDTO zqSignTypeDto = getZqSignTypeDTO(contract, originContractAttachList, contractObjectType);
		// 4.备件信息
		List<ZqContractAttachDTO> zqContractAttachList = getZqContractAttachDTOS(projectOrderId, originContractAttachList, contractUserList);

		PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(contract.getProjectOrderId(), contract.getChangeOrderId());

		// 组装报价方案信息
		ContractPlanAllDTO contractPlanAllDTO = new ContractPlanAllDTO(planAllDTO);

		BigDecimal contractPrice = null;
		BigDecimal quotePrice = null;
		if (Objects.nonNull(planAllDTO) && Objects.nonNull(planAllDTO.getPlanInfo())) {
			contractPrice = planAllDTO.getPlanInfo().getContractPriceTotal();
			quotePrice = planAllDTO.getPlanInfo().getQuotePrice();
		}

		//6报价信息
		QuotationInfoVo quotationInfoVo = getQuotationInfo(projectOrderId, null, contractCode, contract.getBusinessType());
		// 6.工期
		ConstructScheduleVo scheduleVo = new ConstructScheduleVo();
		if (commonContractService.needPeriodByHouseBuildType(zqContractProjectDto.getHouseBuildType()) && map.containsKey("totalPeriod")) {
			scheduleVo.setTotalPeriod(JsonUtil.toObject(map.getOrDefault("totalPeriod", "0"), new TypeReference<Long>() {
			}));
			scheduleVo.setFixTotalPeriod(JsonUtil.toObject(map.getOrDefault("fixTotalPeriod", "0"), new TypeReference<Long>() {
			}));
			scheduleVo.setAddTotalPeriod(JsonUtil.toObject(map.getOrDefault("addTotalPeriod", "0"), new TypeReference<Long>() {
			}));
			scheduleVo.setPersonalCraftAddPeriod(JsonUtil.toObject(map.getOrDefault("personalCraftAddPeriod", "0"), new TypeReference<Long>() {
			}));
			scheduleVo.setConstructionStageDetailDTO(JsonUtil.toObject(map.getOrDefault("constructionStageDetailDTO", null), new TypeReference<List<ConstructScheduleVo.ConstructionStageDetailDTO>>() {
			}));

			if (map.containsKey("personalCrafts") && Objects.nonNull(map.get("personalCrafts"))) {
				scheduleVo.setPersonalCrafts(JsonUtil.toObject(map.get("personalCrafts"), new TypeReference<List<String>>() {
				}));
			}
		}

		int status = contract.getStatus();

		//草稿以后
		String contractUrl = "";
		ContractAttachTipsVo attachTips = null;
		if (status > ContractStatusEnum.DRAFT.getCode()) {
			contractUrl = homeAndPcCommonService.getContractUrl(contract);
		}
		//草稿以后-完毕之前
		if (status > ContractStatusEnum.DRAFT.getCode() && status < ContractStatusEnum.FINISH.getCode()) {
			//检查备件信息
			attachTips = checkAttach(contractObjectType, haveAgent, haveAgent, zqContractAttachList, null);
		}

		//审核中及以后
		String bpmUrl = "";
		if (status >= ContractStatusEnum.AUDITING.getCode()) {
			if (StringUtils.isNotBlank(contract.getBmpNo())) {
				bpmUrl = getBpmUrl(contract.getBmpNo());
			}
		}

		Integer contractStatus = null;
		String contractStatusText = "";
		ContractStatusVo contractStatusVo = convertStatusVo(contract.getStatus());
		if (Objects.nonNull(contractStatusVo)) {
			contractStatus = contractStatusVo.getStatus();
			contractStatusText = contractStatusVo.getName();

		}

		//工期模式
		Integer scheduleSwitch = map.containsKey("scheduleSwitch") ? Integer.parseInt(map.get("scheduleSwitch")) : ScheduleSwitchEnum.AUTO.getCode();
		zqContractProjectDto.setScheduleSwitch(scheduleSwitch);

		CollectionPlanConfigInfo collectionPlanConfigInfo = null;
		try {
			collectionPlanConfigInfo = commonContractService.queryCollectionPlanByContract(contract);
			if (collectionPlanConfigInfo != null) {
				//获取最新的合同款金额
				BigDecimal contractPriceNow = athenaRpc.queryPlanInfo(projectOrderId).getPlanInfo().getContractPriceTotal();
				collectionPlanConfigInfo = fundBaseService.calculateCollectionPlan(collectionPlanConfigInfo, contractPriceNow);
			}
		} catch (Exception e) {
			LOGGER.info("查询合同详情时获取收款计划出错,contractCode:{}", contract.getContractCode(), e);
		}

		ZqContractDetailResp result = ZqContractDetailResp.builder().contractCode(contractCode)
			.address(address)
			.customerName(customerName)
			.status(contract.getStatus())
			.contractStatus(contractStatus)
			.contractStatusText(contractStatusText)
			.type(contract.getType())
			.auditType(contract.getAuditType())
			.signTypeInfo(zqSignTypeDto)
			.signInfo(zqSignInfoDto)
			.projectInfo(zqContractProjectDto)
			.promiseInfo(zqPromiseInfoDTO)
			.planAllInfo(contractPlanAllDTO)
			.quotation(quotationInfoVo)
			.contractPrice(contractPrice)
			.quotePrice(quotePrice)
			.contractAttachList(zqContractAttachList)
			.bpmUrl(bpmUrl)
			.contractUrl(contractUrl)
			.attachTips(attachTips)
			.centerControlType(homeAndPcCommonService.getCenterControlType(projectOrderId))
			.userConfirmStatus(contract.getUserConfirmStatus())
			.userSignStatus(contract.getUserSignStatus())
			.userSignType(contract.getUserSignType())
			.constructSchedule(scheduleVo)
			.userSignTime(map.getOrDefault(FieldEnum.USER_SIGN_TIME.getKey(), ""))
			.companySignTime(map.getOrDefault(FieldEnum.COMPANY_SIGN_TIME.getKey(), ""))
			.companyCode(contract.getCompanyCode())
			.businessType(contract.getBusinessType())
			.guaranteeInfo(zqGuaranteeDTO)
			.collectionPlanConfigInfo(collectionPlanConfigInfo)
			.build();

		//编辑条件下, 部分字段需要用初始值
		if (!isDetail) {
			fillInitData(result, initDetail);
			result.setBusinessType(commonContractService.getBusinessType(projectInfoDTO));
		}

		return result;
	}

	private void fillInitData(ZqContractDetailResp result, ZqContractDetailResp initData) {
		ZqContractProjectDTO resultProjectInfo = result.getProjectInfo();
		ZqContractProjectDTO initProjectInfo = initData.getProjectInfo();

		//没有gbCode的话，那就需要填充project
		if (Objects.isNull(resultProjectInfo.getGbCode())) {
			BeanUtils.copyProperties(initProjectInfo, resultProjectInfo);
		}
	}

