	public ContractPreviewVo preview(ZqContractReq body, Long userId) {
		//根据合同类型获取项目单号
		ContractCreateBaseInfo canCreateContract = commonBusinessService.getCanCreateContract(body.getProjectOrderId(), body.getType(), null);
		if (ObjectUtil.isNotEmpty(canCreateContract)) {
			body.setProjectOrderId(canCreateContract.getProjectOrderId());
			body.setType(canCreateContract.getContractType());
		}
		Byte signChannelType = body.getSignTypeInfo().getSignChannelType();
		if (Objects.nonNull(signChannelType) && SignChannelTypeEnum.OFFLINE.getCode().equals(signChannelType)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "线下合同不生成pdf文件-[签约]");
		}
		String contractCode = body.getContractCode();
		String contractNo = "";

		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(body.getProjectOrderId());
		if (Objects.isNull(projectInfoDTO) || Objects.isNull(projectInfoDTO.getCustomerCommission())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目缺少分公司信息");
		}
		String companyCode = projectInfoDTO.getCustomerCommission().getCompanyCode();
		if (Objects.isNull(body.getProjectInfo()) || Objects.isNull(body.getProjectInfo().getGbCode())) {
			LOGGER.warn("合同预览,没有城市信息 body:{} userId:{}", JSONObject.toJSONString(body), userId);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "预览失败，没有城市信息");
		}
		//pc的只有一个配置，需要读取列表
		Byte businessType = commonContractService.getBusinessType(projectInfoDTO);
		List<ContractCityCompanyInfo> configList = contractCityCompanyConfigService.getConfig(
			body.getProjectOrderId(),
			projectInfoDTO.getCustomerHouse().getGbCode(),
			companyCode,
			businessType,
			body.getType()
		);
		if (configList.isEmpty()) {
			LOGGER.warn("合同预览,缺少合同配置信息 gbCode:{} companyCode:{} type:{} userSignType:{}",
				body.getProjectInfo().getGbCode(), companyCode, body.getType(), body.getUserSignType());
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少合同配置信息");
		}
		ContractCityCompanyInfo config = configList.get(0);

		//预览直接查最新的报价
		PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(body.getProjectOrderId(), body.getChangeOrderId());
		FormalPackageContractFreeformDTO dto = buildFormalPackageContractFreeformDTO(companyCode, userId,
			body, contractNo, planAllDTO, businessType);
		ObjectMapper objectMapper = new ObjectMapper();
		Map<String, Object> map = objectMapper.convertValue(dto, Map.class);
		Contract contract = new Contract();
		contract.setBusinessType(commonContractService.getBusinessType(projectInfoDTO));
		contract.setGbCode(body.getProjectInfo().getGbCode());
		contract.setProjectOrderId(body.getProjectOrderId());
		contract.setUserSignType(body.getUserSignType());
		contract.setType(body.getType());
		contract.setAuditType(config.getAuditType().byteValue());
		contract.setCreateUserId(String.valueOf(userId));
		String pdfUrl = contractBusinessService.generatePdf(contract, map);
		ContractPreviewVo contractPreviewVo = ContractPreviewVo.builder()
			.contractUrl(pdfUrl).contractCode(contractCode).build();

		LOGGER.info("预览接口结果为: {}", pdfUrl);
		return contractPreviewVo;
	}

