	public ScheduleCalculateDTO getConstructSchedule(String projectOrderId, String changeOrderId, BigDecimal area, String planStartTime, Integer houseType, Integer toiletCnt, Integer houseBuildType) {
		try {
			boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, ContractTypeEnum.PACKAGE_CHANGE.getCode())
				&& BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(commonBusinessService.getBusinessType(projectOrderId));
			//2.5系统单子房屋类型为别墅等依旧请求工期系统
			if (!commonContractService.needPeriodByHouseBuildType(houseBuildType) && !houseProcessV25) {
				return new ScheduleCalculateDTO();
			}
			Integer signingStatus = StringUtils.isBlank(changeOrderId) ? 1 : 2;
			return constructScheduleFeignService.calculateSchedule(projectOrderId, signingStatus, area, planStartTime, houseType, toiletCnt, houseBuildType);
		} catch (Exception e) {
			LOGGER.error("获取工期失败:{}", e);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取工期失败，请选择手动输入工期方式:" + e.getMessage());
		}
	}


