public List<Integer> getContractTypeList(CoordinationProjectInfo coordinationProjectOrder, List<Integer> contractTypes, Integer sceneType) {
	if (sceneType == null || ContractShowSceneTypeEnum.ALL_AND_RETAIL.getCode().equals(sceneType) || ContractShowSceneTypeEnum.ALL.getCode().equals(sceneType)) {
		if (coordinationProjectOrder.hasDecorateProjectOrder()) {
			return contractTypes;
		} else {
			return contractTypes.stream().filter(item -> ContractTypeEnum.getPersonalizedRelevantContractList().contains(item.byteValue())).collect(Collectors.toList());
		}
	}
	if (ContractShowSceneTypeEnum.WHOLE.getCode().equals(sceneType)) {
		if (coordinationProjectOrder.hasDecorateProjectOrder()) {
			return contractTypes.stream().filter(item -> ContractTypeEnum.WHOLE_CONTRACT.contains(item.byteValue())).collect(Collectors.toList());
		} else {
			return new ArrayList<>();
		}
	} else if (ContractShowSceneTypeEnum.RETAIL.getCode().equals(sceneType)) {
		contractTypes = contractTypes.stream().filter(item -> ContractTypeEnum.getPersonalizedRelevantContractList().contains(item.byteValue())).collect(Collectors.toList());
	}
	return contractTypes;
}

