public ContractTypeListVo getSecondContractTypeList(String projectOrderId, Byte contractType) {
	ContractTypeListVo vo = new ContractTypeListVo();
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
	if (Objects.isNull(projectInfoDTO)) {
		LOGGER.warn("获取合同类型列表失败,查询不到项目信息 projectOrderId:{}", projectOrderId);
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取合同类型列表失败,查询不到项目信息-[签约]");
	}
	byte businessType = commonContractService.getBusinessType(projectInfoDTO);
	vo.setAddress(homeAndPcCommonService.getAddress(projectInfoDTO));
	vo.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));
	vo.setCompanyCode(projectInfoDTO.getCustomerCommission().getCompanyCode());
	vo.setGbCode(projectInfoDTO.getCustomerHouse().getGbCode());
	vo.setBusinessType(businessType);
	List<ContractTypeListVo.ContractTypeListItemVo> contractTypeListItemVos = new LinkedList<>();

	List<Contract> contractList = contractService.getContractList(projectOrderId, contractType);
	if (ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
		List<Contract> previousOrderContractList = commonContractService.getPreviousOrderContractList(projectOrderId);
		contractList.addAll(previousOrderContractList);
	}
	//只允许的按钮类型
	List<Integer> canShowButtonList = new ArrayList<>();
	if (ContractTypeEnum.TERMINAL.getCode().equals(contractType) || ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contractType)) {
		canShowButtonList = Collections.singletonList(PcButtonEnum.PREVIEW.getType());
	} else if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)) {
		canShowButtonList = Arrays.asList(PcButtonEnum.PREVIEW.getType(), PcButtonEnum.VIEW.getType());
	}
	for (Contract contract : contractList) {
		ContractField goodsInfo = null;
		if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			if (ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())) {
				continue;
			}
			goodsInfo = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), "goodsInfo");
		}
		BindOrderInfoGroup group = quotationRelationCommonService.getBindOrderInfoGroupByContractCode(contract.getContractCode());
		ContractTypeListVo.ContractTypeListItemVo contractTypeListItemVo = ContractTypeListVo.ContractTypeListItemVo
			.builder()
			.type(contract.getType())
			.typeName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
			.contractCode(contract.getContractCode())
			.contractStatus(contract.getStatus())
			.contractUrl(commonService.getContractUrl(contract))
			.secondLevelShowTitle(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()))
			.signChannelType(contract.getSignChannelType())
			.type(contract.getType())
			.icon(ContractTypeEnum.getPcImageByCode(contractType))
			.status(contract.getStatus())
			.statusText(ContractStatusEnum.getNameByCode(contract.getStatus()))
			.goodsInfo(goodsInfo != null ? goodsInfo.getFieldValue() : null)
			.billCodeList(BillCodeInfo.getBillCodeList(group.getBillCodeInfos()))
			.billCodeInfoList(group.getBillCodeInfos())
			.subOrderInfoList(group.getSubOrderInfos())
			.changeOrderInfoList(group.getChangeOrderInfos())
				.build();
		//原服务解约协议名称需特殊展示
		if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType()) && !projectOrderId.equals(contract.getProjectOrderId())) {
			contractTypeListItemVo.setTypeName("原服务解约协议");
		}
		List<String> attachUrl = commonService.getAttachUrl(contract);
		List<ContractNode> nodeList = contractNodeService.getListByContractCode(contract.getContractCode());
		List<ButtonItemVo> buttonItemVos = new ArrayList<>();
		if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			List<RelateContract> relateContractList = homeAndPcCommonService.getRelateContractList(contract);
			contractTypeListItemVo.setRelateContracts(relateContractList);
			ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
			contractTypeListItemVo.setPrimaryRelatedContractCode(contractRelation != null ? contractRelation.getContractCode() : null);
			//不在起草中，并且bpmNo不为空，拼装审核链接
			if ((!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) && StringUtils.isNotBlank(contract.getBmpNo())) {
				contractTypeListItemVo.setBpmUrl(getBpmUrl(contract.getBmpNo()));
			}
			buttonItemVos = getButtonListByConfig(contract, attachUrl, contractList, null);
		} else if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractType) || ContractTypeEnum.SETTLEMENT.getCode().equals(contractType)) {
			List<ContractNode> userConfirmNodeList = nodeList.stream().filter(node -> NodeTypeEnum.USER_CONFIRM.getCode().equals(node.getNodeType())).collect(Collectors.toList());
			// 补充协议或和解协议，基于配置能力获取按钮
			buttonItemVos = getButtonListByConfig(contract, attachUrl, contractList, userConfirmNodeList);
			// 不在起草中，并且bpmNo不为空，拼装审核链接
			if ((!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) && StringUtils.isNotBlank(contract.getBmpNo())) {
				contractTypeListItemVo.setBpmUrl(getBpmUrl(contract.getBmpNo()));
			}
		} else {
			buttonItemVos = filterButtonList(getButtonList(contract), canShowButtonList);
		}

		if (!Arrays.asList(ContractStatusEnum.DRAFT.getCode(), ContractStatusEnum.CANCEL.getCode()).contains(contract.getStatus()) && !ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			//解约协议仅已签署已确认或待签署(申请用章可分享)
			if (ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
				if (ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus())
					|| (ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus()) && CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus()))) {
					if (buttonItemVos.stream().noneMatch(e -> e.getType().equals(PcButtonEnum.SHARE_CONTRACT.getType()))) {
						buttonItemVos.add(new ButtonItemVo(PcButtonEnum.SHARE_CONTRACT));
					}
				}
				if (ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus())) {
					if (buttonItemVos.stream().noneMatch(e -> e.getType().equals(PcButtonEnum.PREVIEW.getType()))) {
						buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
					}
				}
			} else {
				if (buttonItemVos.stream().noneMatch(e -> e.getType().equals(PcButtonEnum.SHARE_CONTRACT.getType()))) {
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.SHARE_CONTRACT));
				}
			}
		}
		contractTypeListItemVo.setAttachUrl(attachUrl);
		contractTypeListItemVo.setAttachFileType(contractBusinessService.getAttachFileKey(attachUrl));
		contractTypeListItemVo.setButtonList(buttonItemVos);
		contractTypeListItemVo.setContractInfoText(commonContractService.getContractShowListItem(contract, nodeList));
		contractTypeListItemVos.add(contractTypeListItemVo);
	}

	vo.setContractTypeListItemVos(contractTypeListItemVos);
	return vo;
}

