private List<ButtonItemVo> getButtonList(Contract contract) {
	List<ButtonItemVo> buttonItemVos = new ArrayList<>();
	boolean canPreview = !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()) && contract.getPlatformInstanceId() > 0;

	if (Objects.isNull(contract)) {
		buttonItemVos.add(new ButtonItemVo(PcButtonEnum.CREATE));
	} else {
		int status = contract.getStatus();
		switch (ContractStatusEnum.getContractStatusEnumByCode(status)) {
			case DRAFT:
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.EDIT));

				break;
			case PENDING_USER_SIGN:
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.VIEW));
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.UNDO));
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
				break;
			case PENDING_SUBMIT_AUDIT:
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.VIEW));
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.UNDO));
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
				break;
			case AUDITING:
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.VIEW));
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.UNDO));
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.AUDIT_DETAIL));
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
				break;
			case PENDING_COMPANY_SIGN:
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.VIEW));
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
				break;
			case FINISH:
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.VIEW));
				buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
				break;
			case CANCEL:
				if (canPreview) {
					buttonItemVos.add(new ButtonItemVo(PcButtonEnum.PREVIEW));
				}
				break;
			default:
				break;
		}
	}
	return buttonItemVos;
}

private List<ButtonItemVo> filterButtonList(List<ButtonItemVo> buttonItemVoList, List<Integer> canShowButtonList) {
	return buttonItemVoList.stream().filter(e -> canShowButtonList.contains(e.getType())).collect(Collectors.toList());
}

