public String saveContractDraft(ZqContractReq body, Integer step, Boolean needCheck, Long createUserId) {
	//抢占锁，防止多次提交
	String lockKey = "";
	if (StringUtils.isNotBlank(body.getContractCode())) {
		Contract contract = contractService.getByContractCode(body.getContractCode());
		if (contract == null) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "未找到对应的合同信息");
		}
		lockKey = LockService.CONTRACT_ORDER_NO_TYPE + contract.getProjectOrderId() + "_" + contract.getType();
	} else if (StringUtils.isNotBlank(body.getProjectOrderId()) && Objects.nonNull(body.getType())) {
		lockKey = LockService.CONTRACT_ORDER_NO_TYPE + body.getProjectOrderId() + "_" + body.getType();
	}
	if (StringUtils.isBlank(lockKey)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "保存草稿失败，非法提交，主键不齐全");
	}

	RLock lock = redissonClient.getLock(lockKey);
	try {
		if (!lock.tryLock(0L, 60L, TimeUnit.SECONDS)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请勿短时间内多次提交");
		}
	} catch (Exception e) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请勿短时间内多次提交");
	}

	try {
		return saveContractDraftDetail(body, step, needCheck, createUserId);
	} catch (Exception e) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, e.getMessage());
	} finally {
		lock.unlock();
	}
}

public String saveContractDraftDetail(ZqContractReq body, Integer step, Boolean needCheck, Long createUserId) {
	Contract contract = null;
	//兼容home编辑保存的时，只传了contractCode的场景，补齐projectOrderId,type,userSignType
	if (StringUtils.isNotBlank(body.getContractCode())) {
		contract = contractService.getByContractCode(body.getContractCode());
		if (Objects.isNull(contract)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同不存在，请检查合同编号或联系客服");
		}
		body.setProjectOrderId(contract.getProjectOrderId());
		body.setType(contract.getType());
		body.setUserSignType(contract.getUserSignType());
	} else {
		//没有contractCode，有两种可能 - pc第一次提交 or home第一次编辑(需要找到之前分步提交的草稿)
		List<Contract> contractList = contractService.getContractList(body.getProjectOrderId(), body.getType());
		if (Objects.nonNull(contractList) && !contractList.isEmpty()) {
			contract = contractList.get(0);
		}
	}

	if (Objects.nonNull(contract)) {
		body.setContractCode(contract.getContractCode());
		body.setProjectOrderId(contract.getProjectOrderId());
		body.setType(contract.getType());
		body.setContractCode(contract.getContractCode());

		if (Objects.nonNull(contract.getStatus()) && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同状态不处于草稿中，不允许保存草稿");
		}
	}

	//校验唯一性
	homeAndPcCommonService.checkUnique(body.getProjectOrderId(), body.getChangeOrderId(), body.getContractCode(), body.getType());

	//保存收款计划
	if (Objects.nonNull(body.getCollectionPlanInfo())) {
		fundBaseService.saveCollectionPlan(body.getCollectionPlanInfo());
	}

	//确定当前步骤所涉及的数据范围
	List<ZqContractPartEnum> partEnumList = ZqContractPartEnum.getPartEnumByStep(step);
	//校验数据必填
	if (needCheck) {
		submitCheck(body, partEnumList);
	}

	String contractCode = body.getContractCode();
	String userName = homeAndPcCommonService.getOperatorName(createUserId);

	//删除之前的数据
	if (StringUtils.isNotBlank(contractCode)) {
		//不是分步提交，需要把之前的数据都清空
		if (ZqStepEnum.ALL.getCode().equals(step)) {
			deleteContractInfo(contractCode, false);
		} else {
			//分步提交需要只删除当前步骤下的数据
			deletePartZqData(contractCode, partEnumList);
		}
	}

	contract = queryOrBuildContract(body, createUserId, userName);
	PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(body.getProjectOrderId(), body.getChangeOrderId());
	contract.setAmount(planAllDTO.getPlanInfo().getContractPriceTotal());
	contract.setStatus(ContractStatusEnum.DRAFT.getCode());

	//保存contract
	saveOrUpdateContract(contract);
	contractCode = contract.getContractCode();
	saveContractUser(contractCode, body, createUserId, userName);
	saveContractField(contractCode, body, createUserId, userName);
	saveContractAttach(contractCode, body, createUserId, userName);
	saveContractMaterial(contractCode, body, createUserId, userName);
	saveAttachUser(contractCode, body);
	updateOrSaveContractNode(contractCode, body);

	//保存收款计划快照到【合同收款计划记录表】
	if (Objects.nonNull(body.getCollectionPlanInfo())) {
		contractCollectionPlanRecordService.insertOrUpdate(ContractCollectionPlanRecord.builder()
			.collectionPlan(JSON.toJSONString(body.getCollectionPlanInfo()))
			.contractCode(contractCode)
			.build());
	}
	return contract.getContractCode();
}

