private List<String> getFieldNames(Class cla) {
	List<String> result = new LinkedList<>();

	Field[] fields = cla.getDeclaredFields();
	for (int i = 0; i < fields.length; i++) {
		fields[i].setAccessible(true);
		result.add(fields[i].getName());
	}
	return result;
}

public Contract queryOrBuildContract(ZqContractReq body, Long createUserId, String userName) {
	Contract contract = null;
	String contractCode = body.getContractCode();
	//业务类型&分公司，每次都去更新一下
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(body.getProjectOrderId());

	if (Strings.isBlank(contractCode)) {
		//先用projectOrderId+type找一下之前的记录
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(body.getType())) {
			contract = findContractByProjectOrderIdAndType(body.getProjectOrderId(), body.getType());
		}
		//新建
		if (Objects.isNull(contract)) {
			contract = buildContract(body, createUserId, userName);
		}
	} else {
		//原有更新
		contract = contractService.getByContractCode(contractCode);
		contract.setGbCode(projectInfoDTO.getCustomerHouse().getGbCode());
		contract.setUserSignType(body.getUserSignType());
		contract.setModifyUserId(String.valueOf(createUserId));
		contract.setModifyUserName(userName);
		if (Objects.nonNull(body.getSignTypeInfo()) && Objects.nonNull(body.getSignTypeInfo().getSignChannelType())) {
			contract.setSignChannelType(body.getSignTypeInfo().getSignChannelType());
		}
		if (Objects.nonNull(body.getSignTypeInfo()) && Objects.nonNull(body.getSignTypeInfo().getSignChannelType())) {
			contract.setUserSignStatus(SignChannelTypeEnum.OFFLINE.getCode().equals(body.getSignTypeInfo().getSignChannelType()) ? CommonEnum.YES.getCode() : CommonEnum.NO.getCode());
		}
	}

	contract.setBusinessType(commonContractService.getBusinessType(projectInfoDTO));
	contract.setCompanyCode(projectInfoDTO.getCustomerCommission().getCompanyCode());

	return contract;
}

private Contract findContractByProjectOrderIdAndType(String projectOrderId, Byte type) {
	if (StringUtils.isBlank(projectOrderId) || Objects.isNull(type)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "根据订单号+合同类型查找合同失败, 该参数不能为空" + projectOrderId + ":" + type);
	}
	List<Contract> contractList = contractService.getContractList(projectOrderId, type);
	if (!contractList.isEmpty()) {
		return contractList.get(0);
	}
	return null;
}

public void saveOrUpdateContract(Contract contract) {
	LOGGER.info("saveOrUpdateContract contract:{} ", JSONObject.toJSONString(contract));
