public void deleteContractInfo(String contractCode, Boolean isSoft) {
	LOGGER.info("删除合同信息 contractCode:{} isSoft:{}", contractCode, isSoft);
	if (isSoft) {
		contractFieldService.deleteByContractCode(contractCode);
		//删除人员
		contractUserService.softDeleteByContractCode(contractCode);
		//删除附件
		contractAttachService.softDeleteByContractCode(contractCode);
		//删除材料清单
		contractMaterialService.softDeleteByContractCode(contractCode);
	} else {
		contractFieldService.deleteByContractCode(contractCode);
		//删除人员
		contractUserService.delByContractCode(contractCode);
		//删除附件
		contractAttachService.delByContractCode(contractCode);
		//删除材料清单
		contractMaterialService.delByContractCode(contractCode);
	}

}

