public void updateOrSaveContractNode(String contractCode, ZqContractReq body) {
	//把页面上录入的时间给干掉
	if (Objects.nonNull(body.getSignTypeInfo())) {
		contractNodeService.softDeleteByContractCode(contractCode, Arrays.asList(NodeTypeEnum.USER_SIGN.getCode(), NodeTypeEnum.COMPANY_SIGN.getCode()));
		if (SignChannelTypeEnum.OFFLINE.getCode().equals(body.getSignTypeInfo().getSignChannelType())) {
			List<ContractNode> nodeList = buildContractNode(contractCode, body);
			for (ContractNode contractNode : nodeList) {
				contractNodeService.updateOrCreate(contractCode, contractNode.getNodeType(), contractNode.getFireTime());
			}
		}
	}
}

private List<ContractAttach> buildContractAttach(String contractCode, ZqContractReq body) {
	List<ContractAttach> contractAttachList = new ArrayList<>();
	//房本 营业执照  委托代理人证明
	if (CollectionUtils.isNotEmpty(body.getContractAttachList())) {
		List<ZqContractAttachDTO> zqContractAttachDTOList = body.getContractAttachList().stream().filter(Objects::nonNull).collect(Collectors.toList());
		for (ZqContractAttachDTO zqContractAttachDto : zqContractAttachDTOList) {
			byte zqContractAttachType = zqContractAttachDto.getAttachType();
			AttachTypeEnum attachTypeEnum = ZqAttachTypeEnum.convertToAttachTypeEnum(zqContractAttachType);
			if (Objects.nonNull(attachTypeEnum) && CollectionUtils.isNotEmpty(zqContractAttachDto.getUrls())) {
				for (String url : zqContractAttachDto.getUrls()) {
					ContractAttach attach = new ContractAttach();
					attach.setAttachType(attachTypeEnum.getCode());
					attach.setUrl(url);
					attach.setContractCode(contractCode);
					contractAttachList.add(attach);
				}
			}
		}
	}

	//线下合同
	if (Objects.nonNull(body.getSignTypeInfo())) {
		List<String> offlineContactUrlList = body.getSignTypeInfo().getAttachUrl();
		if (CollectionUtils.isNotEmpty(offlineContactUrlList)) {
			for (String url : offlineContactUrlList) {
				ContractAttach attach = new ContractAttach();
				attach.setAttachType(AttachTypeEnum.OFFLINE_CONTRACT.getCode());
				attach.setUrl(url);
				attach.setContractCode(contractCode);
				contractAttachList.add(attach);
			}
		}
	}

	return contractAttachList;
}

