public void doAfterSubmit(Contract contract) {
	//日志&消息
	contractLogService.createLog(contract.getContractCode(), LogTypeEnum.SUBMIT.getCode(), LogTypeEnum.SUBMIT.getName(), "", contract.getModifyUserId(), contract.getModifyUserName());
	contractLogService.createLog(contract.getContractCode(), LogTypeEnum.STATUS_CHANGE.getCode(), LogTypeEnum.STATUS_CHANGE.getName(), contract.getStatus().toString());
	contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.SUBMIT.getCode());

	//记录附件齐全
	boolean uploadStatus = checkAttach(contract.getContractCode());
	if (uploadStatus) {//提交合同如果附件齐全，也需要记录日志和节点
		//附件上传完毕，如果附件齐全，侧添加日志信息
		contractBusinessService.remarkSupplementLog(contract);
		//添加合同节点
		contractBusinessService.remarkSupplementNode(contract.getContractCode());
	}

	eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_SUBMIT, contract.getContractCode());
}

public ConstructScheduleVo calculateSchedule(String projectOrderId, Byte contractType, String area, String planStartTime, Integer toiletCnt,
											 Integer houseType, Integer houseBuildType) {
	boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode())
		&& BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(commonBusinessService.getBusinessType(projectOrderId));
	//2.5系统单子房屋类型为别墅等依旧请求工期系统
	if (!commonContractService.needPeriodByHouseBuildType(houseBuildType) && !houseProcessV25) {
		return new ConstructScheduleVo();
	}
	if (StringUtils.isNotBlank(projectOrderId)
		&& Objects.nonNull(contractType)
		&& StringUtils.isNotBlank(area)
		&& StringUtils.isNotBlank(planStartTime)
		&& Objects.nonNull(toiletCnt)
		&& Objects.nonNull(houseType)
		&& houseType > 0
		&& Objects.nonNull(houseBuildType)
		&& houseBuildType > 0
	) {
		try {
			Integer signingStatus = ContractTypeEnum.PACKAGE_CHANGE.equals(contractType) ? 2 : 1;
			ScheduleCalculateDTO schedule = constructScheduleFeignService.calculateSchedule(
				projectOrderId,
				signingStatus,
				BigDecimal.valueOf(Double.parseDouble(area)),
				planStartTime,
				houseType,
				toiletCnt,
				houseBuildType);
			ConstructScheduleVo scheduleVo = new ConstructScheduleVo();
			BeanUtils.copyProperties(schedule, scheduleVo);
			return scheduleVo;
		} catch (Exception e) {
			LOGGER.info("获取工期失败, e: {}", e.getMessage());
		}
	}
	return null;
}

private String getProjectInfoAddress(String districtName, String resblockName, String buildingName, String unitName, String floorName, String houseName) {

	districtName = StringUtils.isBlank(districtName) ? "" : districtName;
	resblockName = StringUtils.isBlank(resblockName) ? "" : resblockName;
	buildingName = StringUtils.isBlank(buildingName) ? "" : buildingName;
	unitName = StringUtils.isBlank(unitName) ? "" : unitName;
	floorName = StringUtils.isBlank(floorName) ? "" : floorName;
	houseName = StringUtils.isBlank(houseName) ? "" : houseName;
	return districtName + resblockName + buildingName + unitName + floorName + houseName;
}

private FormalPackageContractFreeformDTO buildFormalPackageContractFreeformDTO(String companyCode, Long createUserId, ZqContractReq body, String contractNo,
																			   PlanAllDTO planAllDTO, Byte businessType) {
	String projectOrderId = body.getProjectOrderId();
	CompanyInfoDTO companyInfoDTO = commonContractService.getCompanyInfo(companyCode);

	String firstPayAmountText = "";
	String secondPayAmountText = "";
	String thirdPayAmountText = "";
	String firstPayAmount = "";
	String secondPayAmount = "";
	String thirdPayAmount = "";

	//收款计划
	CollectionPlanConfigInfo configInfo = body.getCollectionPlanInfo();
	String payPlan = "";
	//合同金额
	BigDecimal contractAmount = planAllDTO.getPlanInfo().getContractPriceTotal();
	if (Objects.nonNull(configInfo)) {
		StringBuilder payPlanBuffer = new StringBuilder();
		List<CollectionPlanItem> content = configInfo.getContent();

		for (int i = 0; i < content.size(); i++) {
			CollectionPlanItem item = content.get(i);
			BigDecimal itemAmount = Objects.nonNull(item.getPrice()) && BigDecimal.ZERO.compareTo(item.getPrice()) != 0 ? item.getPrice() : contractAmount.multiply(item.getRate()).setScale(2, RoundingMode.HALF_UP);
			payPlanBuffer.append(MessageFormat.format(PAY_PLAN_FORMAT
				, item.getCollectionName(),
				item.getLastPayNode(),
				item.getRate().multiply(new BigDecimal(100)).toString(),
				(new MoneyConvertUtil(itemAmount.toString())).convert(),
				itemAmount.toString()
			));

			if (Objects.nonNull(item.getPrice())) {
				if (i == 0) {
					firstPayAmount = item.getPrice().toString();
					firstPayAmountText = (new MoneyConvertUtil(item.getPrice().toString())).convert();
				} else if (i == 1) {
					secondPayAmount = item.getPrice().toString();
					secondPayAmountText = (new MoneyConvertUtil(item.getPrice().toString())).convert();
				} else if (i == 2) {
					thirdPayAmount = item.getPrice().toString();
					thirdPayAmountText = (new MoneyConvertUtil(item.getPrice().toString())).convert();
				}
			}
		}

		payPlan = payPlanBuffer.toString();
	}

	//报价
	List<PlanAttachmentDTO> list = planAllDTO.getPlanAttachmentList();
	String budgetUrl = "";
	String internalConfigurationsUrl = "";
	String extraConfigurationsUrl = "";
	String personalQuotionUrl = "";
	String baseConstructionDrawUrl = "";
	if (CollectionUtils.isNotEmpty(list)) {
		for (PlanAttachmentDTO planAttachmentDTO : list) {
			List<String> srcs = pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl());
			String signDate = DateUtils.getDateStr(new Date());
			List<FormalPackageContractFreeformDTO.Photo> photos;
			switch (planAttachmentDTO.getFileType()) {
				case PlanAttachment.报价单:
					photos = srcs.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
					budgetUrl = JsonUtil.toJsonString(photos);
					break;
				case PlanAttachment.套餐套内配置清单:
					photos = srcs.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
					internalConfigurationsUrl = JsonUtil.toJsonString(photos);
					break;
				case PlanAttachment.加载配置清单:
					srcs = pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl());
					photos = srcs.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
					extraConfigurationsUrl = JsonUtil.toJsonString(photos);
					break;
				case PlanAttachment.套外个性化报价单:
					srcs = pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl());
					photos = srcs.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
					personalQuotionUrl = JsonUtil.toJsonString(photos);
					break;
				case PlanAttachment.基础图纸:
					srcs = pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl());
					photos = srcs.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
					baseConstructionDrawUrl = JsonUtil.toJsonString(photos);
					break;
				default:
			}
		}
	}

	//兼容团装历史数据
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && StrUtil.isBlank(internalConfigurationsUrl)) {
		internalConfigurationsUrl = budgetUrl;
	}

	//整装必须要有报价单，团装必须要有套餐套内配置清单
	if (!BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && Objects.isNull(budgetUrl)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "中控模式下，缺少报价单PDF文件，请联系预算员在报价中生成PDF");
	}

	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && Objects.isNull(internalConfigurationsUrl)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "中控模式下，缺少套餐套内配置清单PDF文件，请联系预算员在报价中生成PDF");
	}

	//精装细则
	String urls = "";
	if (Objects.nonNull(planAllDTO.getPlanInfo())) {
		//旧逻辑，无使用
	  List<String> ruleUrls = comboInfoService.getAllUrls(body.getProjectOrderId(), body.getType(), planAllDTO.getPlanInfo().getComboCode());
	  String signDate = DateUtils.getDateStr(new Date());
	  List<FormalPackageContractFreeformDTO.Photo> photos = ruleUrls.stream().map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
	  urls = JsonUtil.toJsonString(photos);
  }

	String clearDay = "";
	String projectContractMode = "";
	String constructionDrawMode = "";
	String afterDiscountDesignerAmount = "/";

	if (Objects.nonNull(body.getPromiseInfo())) {
		ZqPromiseInfoDTO promiseInfoDTO = body.getPromiseInfo();
		clearDay = Objects.nonNull(promiseInfoDTO.getClearDay()) ? String.valueOf(promiseInfoDTO.getClearDay()) : "";
		projectContractMode = Objects.nonNull(ProjectContractModeEnum.getNameByCode(promiseInfoDTO.getProjectContractModeCode())) ? String.valueOf(promiseInfoDTO.getProjectContractModeCode()) : "";
		constructionDrawMode = Objects.nonNull(ConstructionDrawModeEnum.getNameByCode(promiseInfoDTO.getConstructionDrawMode())) ? String.valueOf(promiseInfoDTO.getConstructionDrawMode()) : "";
		afterDiscountDesignerAmount = Objects.nonNull(promiseInfoDTO.getAfterDiscountDesignerAmount()) ? String.valueOf(promiseInfoDTO.getAfterDiscountDesignerAmount()) : "/";
	}

	String couponAmount = "";
	String couponRemark = "";
	List<String> couponRemarkList = contractBusinessService.getCouponRemarkList(planAllDTO);
	if (CollectionUtils.isNotEmpty(planAllDTO.getCouponList())) {
		for (CouponDTO couponDTO : planAllDTO.getCouponList()) {
			if (CouponTypeEnum.DIRECT_COUPON.getCode().equals(couponDTO.getCouponType())) {
				couponAmount = couponDTO.getLapseAmount().toString();
			}
		}
	}

	couponRemark = StringUtils.join(couponRemarkList.toArray(), "\n");
	String designerName = "/";

	ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
	if (Objects.nonNull(designer) && StringUtils.isNotBlank(designer.getName())) {
		designerName = designer.getName();
	}

	String secondDrawModeName = designerName;
	ZqPromiseInfoDTO zqPromiseInfoDTO = body.getPromiseInfo();
	if (Objects.nonNull(zqPromiseInfoDTO) && ConstructionDrawModeEnum.ATTACH.getCode().equals(zqPromiseInfoDTO.getConstructionDrawMode())) {
		secondDrawModeName = "/";
	}

	String budgeter = "";
	ProjectServerInfoDTO projectOrderData = projectOrderFeignService.queryProjectServerInfo(projectOrderId, ServerTypeEnum.BUDGETER);
	if (Objects.nonNull(projectOrderData)) {
		budgeter = projectOrderData.getName();
	}
	ZqContractProjectDTO projectInfo = body.getProjectInfo();
	ZqSignInfoDTO signInfo = body.getSignInfo();
	String address = projectInfo.getCertificateAddress();

	String ownerAddress = StringUtils.isBlank(signInfo.getOwnerAddress()) ? "" : signInfo.getOwnerAddress();
	String agentName = StringUtils.isBlank(signInfo.getAgentName()) ? "/" : signInfo.getAgentName();
	String agentIdNo = "/";
	String agentPhone = StringUtils.isBlank(signInfo.getAgentPhone()) ? "/" : signInfo.getAgentPhone();
	String customerIdNo = "/";
	if (Objects.nonNull(signInfo.getAgentCertificateNo())) {
		agentIdNo = StringUtils.isBlank(signInfo.getAgentCertificateNo()) ? "/" : signInfo.getAgentCertificateNo();
	}

	if (Objects.nonNull(signInfo.getOwnerCertificateNo())) {
		customerIdNo = signInfo.getOwnerCertificateNo();
	}

	String beforeDeliveryDaysToWork = Objects.isNull(body.getPromiseInfo().getBeforeDeliveryDaysToWork()) ? "" : body.getPromiseInfo().getBeforeDeliveryDaysToWork().toString();
	String otherGuaranteeYear = Objects.isNull(body.getGuaranteeInfo()) || Objects.isNull(body.getGuaranteeInfo().getOtherGuaranteeYear())
		? "" : body.getGuaranteeInfo().getOtherGuaranteeYear().toString();
	String waterElectricGuaranteeYear = Objects.isNull(body.getGuaranteeInfo()) || Objects.isNull(body.getGuaranteeInfo().getWaterElectricGuaranteeYear())
		? "" : body.getGuaranteeInfo().getWaterElectricGuaranteeYear().toString();
	String waterProofGuaranteeYear = Objects.isNull(body.getGuaranteeInfo()) || Objects.isNull(body.getGuaranteeInfo().getWaterProofGuaranteeYear())
		? "" : body.getGuaranteeInfo().getWaterProofGuaranteeYear().toString();
	//兼容枚举的情况

	if (Objects.nonNull(body.getGuaranteeInfo()) && Objects.nonNull(body.getGuaranteeInfo().getWaterProofGuaranteeYearEnum())) {
		waterProofGuaranteeYear = body.getGuaranteeInfo().getWaterProofGuaranteeYearEnum().toString();
	}
	if (Objects.nonNull(body.getGuaranteeInfo()) && Objects.nonNull(body.getGuaranteeInfo().getOtherGuaranteeYearEnum())) {
		otherGuaranteeYear = body.getGuaranteeInfo().getOtherGuaranteeYearEnum().toString();
	}

	//总工期
	String totalDuration = Objects.isNull(projectInfo.getTotalDuration())
		? Objects.isNull(projectInfo.getTotalDurationEnum()) ? "" : TotalDurationEnum.getNameByCode(projectInfo.getTotalDurationEnum())
		: projectInfo.getTotalDuration().toString();
	//整装的工期，如果是<50 or >150显示成/
	if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
		if (Objects.isNull(projectInfo.getTotalDuration()) || projectInfo.getTotalDuration() < 50 || projectInfo.getTotalDuration() > 150
			|| !commonContractService.needPeriodByHouseBuildType(projectInfo.getHouseBuildType())) {
			totalDuration = "/";
		}
	}
	//税率
	String taxRate = Objects.isNull(body.getPromiseInfo().getTaxRate()) ? "" : body.getPromiseInfo().getTaxRate().toString();
	taxRate += "%";
	//纠纷处理方式
	String disputeDealMode = Objects.isNull(body.getPromiseInfo().getDisputeDealMode()) ? "" : body.getPromiseInfo().getDisputeDealMode().toString();
	String partRoomRange = body.getProjectInfo().getPartRoomRange();

	//材料清单
	List<FormalPackageContractFreeformDTO.MaterialItem> materialItemList = new LinkedList<>();
	if (Objects.nonNull(body.getPromiseInfo().getMaterialList())) {
		for (MaterialItemVo materialItemVo : body.getPromiseInfo().getMaterialList()) {
			String unit = StringUtils.isBlank(materialItemVo.getUnit()) ? "" : "（".concat(materialItemVo.getUnit()).concat("）");
			String description = StringUtils.isBlank(materialItemVo.getDescription()) ? "" : materialItemVo.getDescription();
			materialItemList.add(
				FormalPackageContractFreeformDTO.MaterialItem.builder()
					.description(description.concat(unit))
					.count(materialItemVo.getCount())
					.build()
			);
		}
	}

	FormalPackageContractFreeformDTO formalPackageContractFreeformDTO = FormalPackageContractFreeformDTO.builder()
		.contractNo(contractNo)
		.jiafangXingming(body.getSignInfo().getOwnerName())
		.projectContractAddress(address)
		.firstPartyConnectPhone(cipherService.decrypt(signInfo.getOwnerPhone()))
		.structure(Optional.ofNullable(StructureEnum.getNameByCode(projectInfo.getStructure())).orElse(""))
		.roomCnt(String.valueOf(projectInfo.getRoomCnt()))
		.parlorCnt(String.valueOf(projectInfo.getParlorCnt()))
		.cookroomCnt(String.valueOf(projectInfo.getCookroomCnt()))
		.toiletCnt(String.valueOf(projectInfo.getToiletCnt()))
		.balconyCnt(String.valueOf(projectInfo.getBalconyCnt()))
		.area(projectInfo.getArea())
		//工程承包方式
		.projectContractMode(projectContractMode)
		.projectDay(totalDuration)
		.planOpenDate(projectInfo.getPlanStartTime())
		.designerName(designerName)
		.budgeter(budgeter)
		.agentName(agentName)
		//开工X天，提供施工条件
		.openWorkDayToConstruct(clearDay)
		//收款计划
		.payPlan(payPlan)
		.couponAmount(couponAmount)
		.couponRemark(couponRemark)
		.applyDate(DateUtils.getDateStr(new Date()))
		.budgetUrl(budgetUrl)
		.internalConfigurationsUrl(internalConfigurationsUrl)
		.extraConfigurationsUrl(extraConfigurationsUrl)
		.personalQuotionUrl(personalQuotionUrl)
		.baseConstructionDrawUrl(baseConstructionDrawUrl)
		.decorateRuleUrl(urls)
		.ownerAddress(ownerAddress)
		.constructionDrawMode(constructionDrawMode)
		.secondDrawModeName(secondDrawModeName)
		.afterDiscountDesignerAmount(afterDiscountDesignerAmount)
		.agentIdNo(cipherService.decrypt(agentIdNo))
		.agentPhone(cipherService.decrypt(agentPhone))
		.customerIdNo(cipherService.decrypt(customerIdNo))
		.companyName(companyInfoDTO.getCompanyName())
		.companyAddress(companyInfoDTO.getCompanyAddress())
		.companyPhone(companyInfoDTO.getCompanyPhone())
		.companySealCode(companyInfoDTO.getCompanySealCode())
		.companyBank(companyInfoDTO.getCompanyBank())
		.companyAccount(companyInfoDTO.getCompanyAccount())
		.beforeDeliveryDaysToWork(beforeDeliveryDaysToWork)
		.otherGuaranteeYear(otherGuaranteeYear)
		.waterElectricGuaranteeYear(waterElectricGuaranteeYear)
		.waterProofGuaranteeYear(waterProofGuaranteeYear)
		.firstPayAmountText(firstPayAmountText)
		.secondPayAmountText(secondPayAmountText)
		.thirdPayAmountText(thirdPayAmountText)
		.firstPayAmount(firstPayAmount)
		.secondPayAmount(secondPayAmount)
		.thirdPayAmount(thirdPayAmount)
		.taxRate(taxRate)
		.disputeDealMode(disputeDealMode)
		.materialList(JsonUtil.toJsonString(materialItemList))
		.partRoomRange(partRoomRange)
		.build();


	if (Objects.nonNull(planAllDTO) && Objects.nonNull(planAllDTO.getPlanInfo())) {
		formalPackageContractFreeformDTO.setContractAmount(String.valueOf(planAllDTO.getPlanInfo().getContractPriceTotal()));
		formalPackageContractFreeformDTO.setContractAmountText(new MoneyConvertUtil(String.valueOf(planAllDTO.getPlanInfo().getContractPriceTotal())).convert());
		formalPackageContractFreeformDTO.setQuotationTotalAmount(String.valueOf(planAllDTO.getPlanInfo().getQuotePrice()));
		formalPackageContractFreeformDTO.setPackageName(planAllDTO.getPlanInfo().getComboName());

	}
	LOGGER.info("formalPackageContractFreeformDTO:{}", JsonUtil.toJsonString(formalPackageContractFreeformDTO));
	return formalPackageContractFreeformDTO;
}

public void submitCheck(ZqContractReq body, List<ZqContractPartEnum> partEnumList) {
	Byte type = body.getType();
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(body.getProjectOrderId());
	byte businessType = commonContractService.getBusinessType(projectInfoDTO);

	if (Objects.isNull(type) || !ContractTypeEnum.getMap().containsKey(type)) {
		//1.认购合同 2.设计合同 3.套餐正式合同 4.套餐变更协议
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，合同类型参数校验失败-[签约]");
	}

	//签约主体
	if (partEnumList.contains(ZqContractPartEnum.SIGN_OBJECT_INFO)) {
		if (Objects.isNull(body.getSignTypeInfo())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "缺少签约方式模块 - 参数校验失败");
		}
		if (Objects.isNull(body.getSignTypeInfo().getContractObjectType())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "主体类型不能为空 - 参数校验失败");
		}
		if (!ContractObjectTypeEnum.getCodes().contains(body.getSignTypeInfo().getContractObjectType())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "主体类型: 值非法 - 参数校验失败");
		}
		if (Objects.isNull(body.getSignTypeInfo().getSignChannelType())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "主体形式不能为空 - 参数校验失败");
		}
		if (!SignChannelTypeEnum.getCodes().contains(body.getSignTypeInfo().getContractObjectType())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "主体形式: 值非法 - 参数校验失败");
		}
		//对公签约，只能选线下
		if (ContractObjectTypeEnum.COMPANY.getCode().equals(body.getSignTypeInfo().getContractObjectType())
			&& !SignChannelTypeEnum.OFFLINE.getCode().equals(body.getSignTypeInfo().getSignChannelType())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "对公签约，只能选择线下签署 - 参数校验失败");
		}
		//线下校验 实际客户签署时间 && 实际盖公司章时间
		if (SignChannelTypeEnum.OFFLINE.getCode().equals(body.getSignTypeInfo().getSignChannelType())) {
			if (StringUtils.isBlank(body.getCompanySignTime())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "实际盖公司章时间不能为空 - 参数校验失败");
			}
			if (StringUtils.isBlank(body.getUserSignTime())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "实际客户签署时间不能为空 - 参数校验失败");
			}
		}
	}

	//签约信息
	if (partEnumList.contains(ZqContractPartEnum.SIGN_INFO)) {
		if (Objects.isNull(body.getSignInfo())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "缺少签约人模块信息 - 参数校验失败");
		}
		//个人签约
		if (ContractObjectTypeEnum.PERSON.getCode().equals(body.getSignTypeInfo().getContractObjectType())) {
			//业主
			if (Objects.isNull(body.getSignInfo().getOwnerName())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "业主姓名不能为空 - 参数校验失败");
			}
			if (Objects.isNull(body.getSignInfo().getOwnerPhone())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "业主手机号不能为空 - 参数校验失败");
			}
			if (Objects.isNull(body.getSignInfo().getOwnerCertificateType())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "业主证件类型不能为空 - 参数校验失败");
			}
			if (!CertificateTypeEnum.getCodes().contains(body.getSignInfo().getOwnerCertificateType())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "业主证件类型: 值非法 - 参数校验失败");
			}
			if (StringUtils.isBlank(body.getSignInfo().getOwnerCertificateNo())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "业主证件号不能为空 - 参数校验失败");
			}
			//校验信息一致性
			if (CertificateTypeEnum.ID.getCode().equals(body.getSignInfo().getOwnerCertificateType())) {
				if (!commonContractService.checkIdName(body.getSignInfo().getOwnerCertificateNo(), body.getSignInfo().getOwnerName())) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "客户姓名与身份证号不一致，请核对后重试");
				}
			}
			//代理人
			if (Objects.isNull(body.getSignInfo().getHaveAgent())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "是否包含代理人不能为空 - 参数校验失败");
			}
			if (!CommonEnum.getCodes().contains(body.getSignInfo().getHaveAgent())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "是否包含代理人：值非法 - 参数校验失败");
			}
			if (CommonEnum.YES.getCode().equals(body.getSignInfo().getHaveAgent())) {
				if (Objects.isNull(body.getSignInfo().getAgentName())) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "代理人姓名不能为空 - 参数校验失败");
				}
				if (Objects.isNull(body.getSignInfo().getAgentPhone())) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "代理人手机号不能为空 - 参数校验失败");
				}
				if (Objects.isNull(body.getSignInfo().getAgentCertificateType())) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "代理人证件类型不能为空 - 参数校验失败");
				}
				if (!CertificateTypeEnum.getCodes().contains(body.getSignInfo().getAgentCertificateType())) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "代理人证件类型: 值非法 - 参数校验失败");
				}
				if (StringUtils.isBlank(body.getSignInfo().getAgentCertificateNo())) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "代理人证件号不能为空 - 参数校验失败");
				}
				//校验信息一致性
				if (CertificateTypeEnum.ID.getCode().equals(body.getSignInfo().getAgentCertificateType())) {
					if (!commonContractService.checkIdName(body.getSignInfo().getAgentCertificateNo(), body.getSignInfo().getAgentName())) {
						throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "客户姓名与身份证号不一致，请核对后重试");
					}
				}
			}
		}
		//公司
		if (ContractObjectTypeEnum.COMPANY.getCode().equals(body.getSignTypeInfo().getContractObjectType())) {
			if (Objects.isNull(body.getSignInfo().getCompanyName())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "企业名称不能为空 - 参数校验失败");
			}
			if (Objects.isNull(body.getSignInfo().getCompanyCreditCode())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "统一社会信用代码不能为空 - 参数校验失败");
			}
			if (Objects.isNull(body.getSignInfo().getCompanyAgentName())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "经办人姓名不能为空 - 参数校验失败");
			}
			if (!CertificateTypeEnum.getCodes().contains(body.getSignInfo().getCompanyAgentCertificateType())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "经办人证件类型: 值非法 - 参数校验失败");
			}
			if (StringUtils.isBlank(body.getSignInfo().getCompanyAgentCertificateNo())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "经办人证件号不能为空 - 参数校验失败");
			}
			//校验信息一致性
			if (CertificateTypeEnum.ID.getCode().equals(body.getSignInfo().getCompanyAgentCertificateType())) {
				if (!commonContractService.checkIdName(body.getSignInfo().getCompanyAgentCertificateNo(), body.getSignInfo().getCompanyAgentName())) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "客户姓名与身份证号不一致，请核对后重试");
				}
			}
		}
	}

	//项目信息
	if (partEnumList.contains(ZqContractPartEnum.PROJECT_INFO)) {
		ZqContractProjectDTO projectInfo = body.getProjectInfo();
		if (Objects.isNull(projectInfo)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "缺少项目模块信息 - 参数校验失败");
		}
		if (Objects.isNull(projectInfo.getGbCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "gbCode不能为空 - 参数校验失败");
		}
		if (Objects.isNull(projectInfo.getHouseBuildType())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "户型结构不能为空 - 参数校验失败");
		}
		if (Objects.isNull(HouseBuildTypeEnum.getEnumByCode(projectInfo.getHouseType()))) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "户型结构: 值非法 - 参数校验失败");
		}
		if (Objects.isNull(projectInfo.getDistrictId()) || StringUtils.isBlank(projectInfo.getDistrictName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "行政区id&名称不能为空 - 参数校验失败");
		}
		if (StringUtils.isBlank(projectInfo.getResblockName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "小区名称不能为空 - 参数校验失败");
		}
		if (StringUtils.isBlank(projectInfo.getBuildingName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "楼栋名称不能为空 - 参数校验失败");
		}
		if (StringUtils.isBlank(projectInfo.getUnitName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "单元名称不能为空 - 参数校验失败");
		}
		if (StringUtils.isBlank(projectInfo.getFloorName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "楼层名称不能为空 - 参数校验失败");
		}
		if (StringUtils.isBlank(projectInfo.getHouseName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "房间名称不能为空 - 参数校验失败");
		}

		if (BusinessTypeEnum.getHouseCertificate25ModeList().contains(businessType)) {
			if (Objects.isNull(projectInfo.getArea())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "建筑面积不能为空 - 参数校验失败");
			}
		}

		if (StringUtils.isEmpty(projectInfo.getPlanStartTime())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，计划开工日期不完整，校验失败-[签约]");
		}
		Integer houseType = projectInfo.getHouseType();
		if (Objects.isNull(houseType) || Objects.isNull(HouseTypeEnum.getEnumByCode(houseType))) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，房屋类型信息不完整，校验失败-[签约]");
		}
		Integer houseBuildType = projectInfo.getHouseBuildType();
		if (Objects.isNull(houseBuildType) || Objects.isNull(HouseBuildTypeEnum.getEnumByCode(houseBuildType))) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，房屋结构信息不完整，校验失败-[签约]");
		}
		//只有家装校验
		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			if (commonContractService.needPeriodByHouseBuildType(houseBuildType) && Objects.isNull(projectInfo.getTotalDuration())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，总工期信息不完整，校验失败-[签约]");
			}
			if (Objects.isNull(projectInfo.getParlorCnt()) || Objects.isNull(projectInfo.getRoomCnt()) || Objects.isNull(projectInfo.getCookroomCnt()) || Objects.isNull(projectInfo.getToiletCnt()) || Objects.isNull(projectInfo.getBalconyCnt()) || Objects.isNull(projectInfo.getStorageCnt())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，户型信息不完整，校验失败-[签约]");
			}
			if (StringUtils.isEmpty(projectInfo.getArea())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，面积信息不完整，校验失败-[签约]");
			}

			//承包约定
			ZqPromiseInfoDTO zqPromiseInfoDTO = body.getPromiseInfo();
			if (Objects.isNull(zqPromiseInfoDTO.getClearDay()) || Objects.isNull(zqPromiseInfoDTO.getProjectContractModeCode())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，承包约定信息不完整，校验失败-[签约]");
			}
			if (Objects.isNull(zqPromiseInfoDTO.getConstructionDrawMode())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，承包约定双方商定施工图纸采取方式信息不完整，校验失败-[签约]");
			}
			if (Objects.isNull(zqPromiseInfoDTO.getNeedDesignerAmount())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，承包约定是否约定设计服务费信息不完整，校验失败-[签约]");
			}
			if (1 == zqPromiseInfoDTO.getNeedDesignerAmount() && Objects.isNull(zqPromiseInfoDTO.getAfterDiscountDesignerAmount())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，承包约定设计服务费（优惠后信息不完整，校验失败-[签约]");
			}
		} else if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			if (Objects.isNull(projectInfo.getTotalDurationEnum())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，总工期信息不完整，校验失败-[签约]");
			}
			if (Objects.isNull(projectInfo.getParlorCnt()) || Objects.isNull(projectInfo.getRoomCnt()) || Objects.isNull(projectInfo.getCookroomCnt()) || Objects.isNull(projectInfo.getToiletCnt()) || Objects.isNull(projectInfo.getBalconyCnt()) || Objects.isNull(projectInfo.getStorageCnt())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，户型信息不完整，校验失败-[签约]");
			}
			if (StringUtils.isEmpty(projectInfo.getArea())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，面积信息不完整，校验失败-[签约]");
			}
			//工程保修约定
			ZqGuaranteeDTO zqGuaranteeDTO = body.getGuaranteeInfo();
			if (Objects.isNull(zqGuaranteeDTO.getOtherGuaranteeYear())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，其他装修部位的保修期限不能为空，校验失败-[签约]");
			}
			if (Objects.isNull(zqGuaranteeDTO.getWaterProofGuaranteeYear())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，有防水要求的卫生间防渗漏工程保修期限不能为空，校验失败-[签约]");
			}
			if (Objects.isNull(zqGuaranteeDTO.getWaterElectricGuaranteeYear())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，对埋设在墙体、地面内的电气网络管线和给排水管道保修期限不能为空，校验失败-[签约]");
			}
			//承包约定
			ZqPromiseInfoDTO zqPromiseInfoDTO = body.getPromiseInfo();
			if (Objects.isNull(zqPromiseInfoDTO.getBeforeDeliveryDaysToWork())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，甲方须在开发商统一交房通知开工不能为空，校验失败-[签约]");
			}
		}
	}

	//承包约定
	if (partEnumList.contains(ZqContractPartEnum.PROMISE_INFO)) {
		//只有家装校验
		if (BusinessTypeEnum.getHouseCertificate25ModeList().contains(businessType)) {
			//承包约定
			ZqPromiseInfoDTO zqPromiseInfoDTO = body.getPromiseInfo();
			if (Objects.isNull(zqPromiseInfoDTO.getClearDay()) || Objects.isNull(zqPromiseInfoDTO.getProjectContractModeCode())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，承包约定信息不完整，校验失败-[签约]");
			}
			if (Objects.isNull(zqPromiseInfoDTO.getConstructionDrawMode())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，承包约定双方商定施工图纸采取方式信息不完整，校验失败-[签约]");
			}
			if (Objects.isNull(zqPromiseInfoDTO.getNeedDesignerAmount())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，承包约定是否约定设计服务费信息不完整，校验失败-[签约]");
			}
			if (1 == zqPromiseInfoDTO.getNeedDesignerAmount() && Objects.isNull(zqPromiseInfoDTO.getAfterDiscountDesignerAmount())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，承包约定设计服务费（优惠后信息不完整，校验失败-[签约]");
			}
		}
	}

	//保修
	if (partEnumList.contains(ZqContractPartEnum.PROMISE_INFO)) {
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			//工程保修约定
			ZqGuaranteeDTO zqGuaranteeDTO = body.getGuaranteeInfo();
			if (Objects.isNull(zqGuaranteeDTO.getOtherGuaranteeYear())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，其他装修部位的保修期限不能为空，校验失败-[签约]");
			}
			if (Objects.isNull(zqGuaranteeDTO.getWaterProofGuaranteeYear())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，有防水要求的卫生间防渗漏工程保修期限不能为空，校验失败-[签约]");
			}
			if (Objects.isNull(zqGuaranteeDTO.getWaterElectricGuaranteeYear())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，对埋设在墙体、地面内的电气网络管线和给排水管道保修期限不能为空，校验失败-[签约]");
			}
			//承包约定
			ZqPromiseInfoDTO zqPromiseInfoDTO = body.getPromiseInfo();
			if (Objects.isNull(zqPromiseInfoDTO.getBeforeDeliveryDaysToWork())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "提交合同，甲方须在开发商统一交房通知开工不能为空，校验失败-[签约]");
			}
		}
	}
}

public StartQuotaDTO getCalendar(String projectOrderId, Integer gbCode, Long resblockId, String address, Byte contractType) {
	Long designerUcId = null;

	ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
	if (Objects.nonNull(designer)) {
		designerUcId = designer.getUcId();
	}

	StartQuotaDTO startQuotaDTO = null;
	LOGGER.info("获取产能日历：projectOrderId {} gbCode:{} designerUcId:{} resblockId:{} address:{}", projectOrderId,
		gbCode, designerUcId, resblockId, address);
	startQuotaDTO = quotaCalenderFeignService.listStartWorkQuota(projectOrderId,
		String.valueOf(gbCode), designerUcId, resblockId, address, CapacitySourceTypeEnum.contractTypeMapSourceType(contractType));
	if (Objects.isNull(startQuotaDTO) || CollectionUtils.isEmpty((startQuotaDTO.getStartsQuotaCalendarDTOS()))) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "调取产能数据失败，可先任选开工时间进行签约！");
	}
	return startQuotaDTO;
}

@Deprecated
public ZqContractDetailResp getZqContractDetail(String projectOrderId, Byte type, String contractCode, Boolean isDetail) {
	Contract contract = null;
	if (StringUtils.isNotBlank(contractCode)) {
		contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同信息不存在");
		}
	} else {
		//兼容处理home分步提交，只有订单号的情况
		List<Contract> contractList = contractService.getContractList(projectOrderId, type);
		if (!contractList.isEmpty()) {
			contract = contractList.get(0);
		}
	}

	//由于home是分步提交，即使有了草稿数据，某一部分也需要用init数据填充
	ZqContractDetailResp initDetail = initContractDetail(projectOrderId, null, type);
	if (Objects.isNull(contract)) {
		return initDetail;
	}

	projectOrderId = contract.getProjectOrderId();
	contractCode = contract.getContractCode();
	type = contract.getType();
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
	if (Objects.isNull(projectInfoDTO)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取合同详情失败,查询不到项目信息-[签约]");
	}

	String address = homeAndPcCommonService.getAddress(projectInfoDTO);
	String customerName = homeAndPcCommonService.getName(projectInfoDTO);
	//方法无使用
	List<ZqCustomerPhoneVo> zqCustomerPhoneVoList = homeAndPcCommonService.getPhoneList(projectInfoDTO);

	List<ContractAttach> originContractAttachList = contractAttachService.getListByContractCode(contractCode);

	List<ContractUser> contractUserList = contractUserService.getListByContractCode(contractCode);
	List<ContractMaterial> materialList = contractMaterialService.getListByContractCode(contractCode);

	// 2.合同字段信息
	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contractCode);

	Map<String, String> map = Maps.newHashMap();
	contractFieldList.forEach(contractField -> map.put(contractField.getFieldKey(), contractField.getFieldValue()));

	// 1.签约主体信息
	ZqSignInfoDTO zqSignInfoDto = getZqSignInfoDTO(isDetail, contractCode, map, zqCustomerPhoneVoList);


	Byte haveAgent = StringUtils.isBlank(map.get("haveAgent")) ? null : Byte.valueOf(map.get("haveAgent"));

	Byte contractObjectType = StringUtils.isBlank(map.get("contractObjectType")) ? null : Byte.valueOf(map.get("contractObjectType"));

	ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
	Long designerId = null;
	String designerName = "";
	if (Objects.nonNull(designer)) {
		designerId = designer.getUcId();
		designerName = designer.getName();
	}
	ZqContractProjectDTO zqContractProjectDto = commonContractService.recordConvert2ZqContractDto(contractFieldList);
	zqContractProjectDto.setAddress(homeAndPcCommonService.getAddress(projectInfoReadService.getByProjectOrderIdWithoutCache(contract.getProjectOrderId())));
	zqContractProjectDto.setDesignerUcId(designerId);
	zqContractProjectDto.setDesignerName(designerName);
	zqContractProjectDto.setDecorateFormLevel1(Objects.nonNull(projectInfoDTO.getCustomerCommission().getDecorateType()) ? projectInfoDTO.getCustomerCommission().getDecorateType().intValue() : null);
	zqContractProjectDto.setDecorateFormLevel1Text(projectInfoDTO.getCustomerCommission().getDecorateTypeDesc());
	zqContractProjectDto.setDecorateFormLevel2(Objects.nonNull(projectInfoDTO.getCustomerCommission().getDecorateId()) ? projectInfoDTO.getCustomerCommission().getDecorateId().intValue() : null);
	zqContractProjectDto.setDecorateFormLevel2Text(projectInfoDTO.getCustomerCommission().getDecorateIdDesc());
	ZqPromiseInfoDTO zqPromiseInfoDTO = ZqPromiseInfoDTO.builder().build();
	Integer projectContractModeCode = map.containsKey("projectContractModeCode") ? Integer.valueOf(map.get("projectContractModeCode")) : null;
	Integer clearDay = map.containsKey("clearDay") ? Integer.valueOf(map.get("clearDay")) : null;
	Integer taxRate = map.containsKey("taxRate") ? Integer.valueOf(map.get("taxRate")) : null;
	Integer disputeDealMode = map.containsKey("disputeDealMode") ? Integer.valueOf(map.get("disputeDealMode")) : null;
	List<MaterialItemVo> materialItemVoList = new LinkedList<>();
	zqPromiseInfoDTO.setProjectContractModeCode(projectContractModeCode);
	zqPromiseInfoDTO.setProjectContractModeName(ProjectContractModeEnum.getNameByCode(projectContractModeCode));
	zqPromiseInfoDTO.setClearDay(clearDay);
	zqPromiseInfoDTO.setTaxRate(taxRate);
	zqPromiseInfoDTO.setDisputeDealMode(disputeDealMode);
	zqPromiseInfoDTO.setDisputeDealModeText(DisputeDealModeEnum.getNameByCode(disputeDealMode));
	for (ContractMaterial contractMaterial : materialList) {
		List<Integer> materialTypeValues = contractApolloConfig.getMaterialTypes().stream().map(OptionVo::getValue).collect(Collectors.toList());
		//起草中合同不返回自定义的材料信息;起草中合同不返回已删除的材料类型的材料信息
		if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()) && (0 == contractMaterial.getValue() || !materialTypeValues.contains(
			contractMaterial.getValue()))) {
			continue;
		}
		materialItemVoList.add(MaterialItemVo.builder()
			.description(contractMaterial.getDescription())
			.count(contractMaterial.getCount())
			.value(contractMaterial.getValue())
			.unit(contractMaterial.getUnit())
			.build());
	}
	zqPromiseInfoDTO.setMaterialList(materialItemVoList);

	Integer constructionDrawMode = map.containsKey("constructionDrawMode") ? Integer.parseInt(map.get("constructionDrawMode")) : 0;
	Integer needDesignerAmount = map.containsKey("needDesignerAmount") ? Integer.valueOf(map.get("needDesignerAmount")) : 0;
	Double afterDiscountDesignerAmount = map.containsKey("afterDiscountDesignerAmount") ? Double.valueOf(map.get("afterDiscountDesignerAmount")) : null;
	Integer beforeDeliveryDaysToWork = map.containsKey("beforeDeliveryDaysToWork") ? Integer.parseInt(map.get("beforeDeliveryDaysToWork")) : null;
	zqPromiseInfoDTO.setConstructionDrawMode(constructionDrawMode);
	zqPromiseInfoDTO.setNeedDesignerAmount(needDesignerAmount);
	zqPromiseInfoDTO.setAfterDiscountDesignerAmount(afterDiscountDesignerAmount);
	zqPromiseInfoDTO.setBeforeDeliveryDaysToWork(beforeDeliveryDaysToWork);

	//保修
	ZqGuaranteeDTO zqGuaranteeDTO = new ZqGuaranteeDTO();
	Integer otherGuaranteeYear = map.containsKey("otherGuaranteeYear") ? Integer.parseInt(map.get("otherGuaranteeYear")) : null;
	Integer waterProofGuaranteeYear = map.containsKey("waterProofGuaranteeYear") ? Integer.parseInt(map.get("waterProofGuaranteeYear")) : null;
	Integer waterElectricGuaranteeYear = map.containsKey("waterElectricGuaranteeYear") ? Integer.parseInt(map.get("waterElectricGuaranteeYear")) : null;
	Integer waterProofGuaranteeYearEnum = map.containsKey("waterProofGuaranteeYearEnum") ? Integer.parseInt(map.get("waterProofGuaranteeYearEnum")) : null;
	Integer otherGuaranteeYearEnum = map.containsKey("otherGuaranteeYearEnum") ? Integer.parseInt(map.get("otherGuaranteeYearEnum")) : null;
	zqGuaranteeDTO.setOtherGuaranteeYear(otherGuaranteeYear);
	zqGuaranteeDTO.setWaterProofGuaranteeYear(waterProofGuaranteeYear);
	zqGuaranteeDTO.setWaterElectricGuaranteeYear(waterElectricGuaranteeYear);
	zqGuaranteeDTO.setWaterProofGuaranteeYearEnum(waterProofGuaranteeYearEnum);
	zqGuaranteeDTO.setWaterProofGuaranteeYearEnumText(WaterProofGuaranteeYearEnum.getNameByCode(waterProofGuaranteeYearEnum));
	zqGuaranteeDTO.setOtherGuaranteeYearEnum(otherGuaranteeYearEnum);
	zqGuaranteeDTO.setOtherGuaranteeYearEnumText(OtherGuaranteeYearEnum.getNameByCode(otherGuaranteeYearEnum));

	// 3.正签类型

	ZqSignTypeDTO zqSignTypeDto = getZqSignTypeDTO(contract, originContractAttachList, contractObjectType);
	// 4.备件信息
	List<ZqContractAttachDTO> zqContractAttachList = getZqContractAttachDTOS(projectOrderId, originContractAttachList, contractUserList);

	PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(contract.getProjectOrderId(), contract.getChangeOrderId());

	// 组装报价方案信息
	ContractPlanAllDTO contractPlanAllDTO = new ContractPlanAllDTO(planAllDTO);

	BigDecimal contractPrice = null;
	BigDecimal quotePrice = null;
	if (Objects.nonNull(planAllDTO) && Objects.nonNull(planAllDTO.getPlanInfo())) {
		contractPrice = planAllDTO.getPlanInfo().getContractPriceTotal();
		quotePrice = planAllDTO.getPlanInfo().getQuotePrice();
	}

	//6报价信息
	QuotationInfoVo quotationInfoVo = getQuotationInfo(projectOrderId, null, contractCode, contract.getBusinessType());
	// 6.工期
	ConstructScheduleVo scheduleVo = new ConstructScheduleVo();
	if (commonContractService.needPeriodByHouseBuildType(zqContractProjectDto.getHouseBuildType()) && map.containsKey("totalPeriod")) {
		scheduleVo.setTotalPeriod(JsonUtil.toObject(map.getOrDefault("totalPeriod", "0"), new TypeReference<Long>() {
		}));
		scheduleVo.setFixTotalPeriod(JsonUtil.toObject(map.getOrDefault("fixTotalPeriod", "0"), new TypeReference<Long>() {
		}));
		scheduleVo.setAddTotalPeriod(JsonUtil.toObject(map.getOrDefault("addTotalPeriod", "0"), new TypeReference<Long>() {
		}));
		scheduleVo.setPersonalCraftAddPeriod(JsonUtil.toObject(map.getOrDefault("personalCraftAddPeriod", "0"), new TypeReference<Long>() {
		}));
		scheduleVo.setConstructionStageDetailDTO(JsonUtil.toObject(map.getOrDefault("constructionStageDetailDTO", null), new TypeReference<List<ConstructScheduleVo.ConstructionStageDetailDTO>>() {
		}));

		if (map.containsKey("personalCrafts") && Objects.nonNull(map.get("personalCrafts"))) {
			scheduleVo.setPersonalCrafts(JsonUtil.toObject(map.get("personalCrafts"), new TypeReference<List<String>>() {
			}));
		}
	}

	int status = contract.getStatus();

	//草稿以后
	String contractUrl = "";
	ContractAttachTipsVo attachTips = null;
	if (status > ContractStatusEnum.DRAFT.getCode()) {
		contractUrl = homeAndPcCommonService.getContractUrl(contract);
	}
	//草稿以后-完毕之前
	if (status > ContractStatusEnum.DRAFT.getCode() && status < ContractStatusEnum.FINISH.getCode()) {
		//检查备件信息
		attachTips = checkAttach(contractObjectType, haveAgent, haveAgent, zqContractAttachList, null);
	}

	//审核中及以后
	String bpmUrl = "";
	if (status >= ContractStatusEnum.AUDITING.getCode()) {
		if (StringUtils.isNotBlank(contract.getBmpNo())) {
			bpmUrl = getBpmUrl(contract.getBmpNo());
		}
	}

	Integer contractStatus = null;
	String contractStatusText = "";
	ContractStatusVo contractStatusVo = convertStatusVo(contract.getStatus());
	if (Objects.nonNull(contractStatusVo)) {
		contractStatus = contractStatusVo.getStatus();
		contractStatusText = contractStatusVo.getName();

	}

	//工期模式
	Integer scheduleSwitch = map.containsKey("scheduleSwitch") ? Integer.parseInt(map.get("scheduleSwitch")) : ScheduleSwitchEnum.AUTO.getCode();
	zqContractProjectDto.setScheduleSwitch(scheduleSwitch);

	CollectionPlanConfigInfo collectionPlanConfigInfo = null;
	try {
		collectionPlanConfigInfo = commonContractService.queryCollectionPlanByContract(contract);
		if (collectionPlanConfigInfo != null) {
			//获取最新的合同款金额
			BigDecimal contractPriceNow = athenaRpc.queryPlanInfo(projectOrderId).getPlanInfo().getContractPriceTotal();
			collectionPlanConfigInfo = fundBaseService.calculateCollectionPlan(collectionPlanConfigInfo, contractPriceNow);
		}
	} catch (Exception e) {
		LOGGER.info("查询合同详情时获取收款计划出错,contractCode:{}", contract.getContractCode(), e);
	}

	ZqContractDetailResp result = ZqContractDetailResp.builder().contractCode(contractCode)
		.address(address)
		.customerName(customerName)
		.status(contract.getStatus())
		.contractStatus(contractStatus)
		.contractStatusText(contractStatusText)
		.type(contract.getType())
		.auditType(contract.getAuditType())
		.signTypeInfo(zqSignTypeDto)
		.signInfo(zqSignInfoDto)
		.projectInfo(zqContractProjectDto)
		.promiseInfo(zqPromiseInfoDTO)
		.planAllInfo(contractPlanAllDTO)
		.quotation(quotationInfoVo)
		.contractPrice(contractPrice)
		.quotePrice(quotePrice)
		.contractAttachList(zqContractAttachList)
		.bpmUrl(bpmUrl)
		.contractUrl(contractUrl)
		.attachTips(attachTips)
		.centerControlType(homeAndPcCommonService.getCenterControlType(projectOrderId))
		.userConfirmStatus(contract.getUserConfirmStatus())
		.userSignStatus(contract.getUserSignStatus())
		.userSignType(contract.getUserSignType())
		.constructSchedule(scheduleVo)
		.userSignTime(map.getOrDefault(FieldEnum.USER_SIGN_TIME.getKey(), ""))
		.companySignTime(map.getOrDefault(FieldEnum.COMPANY_SIGN_TIME.getKey(), ""))
		.companyCode(contract.getCompanyCode())
		.businessType(contract.getBusinessType())
		.guaranteeInfo(zqGuaranteeDTO)
		.collectionPlanConfigInfo(collectionPlanConfigInfo)
		.build();

	//编辑条件下, 部分字段需要用初始值
	if (!isDetail) {
		fillInitData(result, initDetail);
		result.setBusinessType(commonContractService.getBusinessType(projectInfoDTO));
	}

	return result;
}

private void fillInitData(ZqContractDetailResp result, ZqContractDetailResp initData) {
	ZqContractProjectDTO resultProjectInfo = result.getProjectInfo();
	ZqContractProjectDTO initProjectInfo = initData.getProjectInfo();

	//没有gbCode的话，那就需要填充project
	if (Objects.isNull(resultProjectInfo.getGbCode())) {
		BeanUtils.copyProperties(initProjectInfo, resultProjectInfo);
	}
}

