public List<ZqContractAttachDTO> getZqContractAttachDTOS(String projectOrderId, List<ContractAttach> originContractAttachList, List<ContractUser> contractUserList) {
	List<ZqContractAttachDTO> zqContractAttachList = Lists.newArrayList();
	List<ContractAttach> contractAttachList = originContractAttachList.stream().filter(contractAttach -> AttachTypeEnum.OFFLINE_CONTRACT.getCode().byteValue() != contractAttach.getAttachType())
		.collect(Collectors.toList());

	//处理contractAttachList，根据备件id获取对应的备件url
	attachCommonService.getUrlFromContractAttachList(projectOrderId, contractAttachList);
	//2023-03-23用户相关的附件attach表也存了一份，为了兼容之前的逻辑，user表的附件在拼接的时候，需要先判断一下attach表里有没有
	Map<Byte, List<ContractAttach>> contractAttachMap = contractAttachList.stream().collect(Collectors.groupingBy(ContractAttach::getAttachType));
	List<Byte> zqAttachTypeList = new LinkedList<>();
	for (Map.Entry<Byte, List<ContractAttach>> entry : contractAttachMap.entrySet()) {
		if (Objects.nonNull(entry.getValue()) && Objects.nonNull(AttachTypeEnum.getAttachTypeEnumByCode(entry.getKey()))) {
			List<String> urls = entry.getValue().stream().map(ContractAttach::getUrl).collect(Collectors.toList());
			Byte zqAttachType = ZqAttachTypeEnum.getZqAttachType(AttachTypeEnum.getAttachTypeEnumByCode(entry.getKey()));
			zqContractAttachList.add(ZqContractAttachDTO.builder().attachType(zqAttachType).urls(urls).build());
			zqAttachTypeList.add(zqAttachType);
		}
	}

	contractUserList.forEach(contractUser -> {
		Byte attachType = null;
		List<String> urls = Lists.newArrayList();
		if (contractUser.getRoleType().equals(UserTypeEnum.OWNER.getCode())) {
			attachType = ZqAttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode();
			if (StringUtils.isNotBlank(contractUser.getCertificateImg1())) {
				urls.add(contractUser.getCertificateImg1());
			}
			if (StringUtils.isNotBlank(contractUser.getCertificateImg2())) {
				urls.add(contractUser.getCertificateImg2());
			}
		}
		if (contractUser.getRoleType().equals(UserTypeEnum.AGENT.getCode())) {
			attachType = ZqAttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode();
			if (StringUtils.isNotBlank(contractUser.getCertificateImg1())) {
				urls.add(contractUser.getCertificateImg1());
			}
			if (StringUtils.isNotBlank(contractUser.getCertificateImg2())) {
				urls.add(contractUser.getCertificateImg2());
			}
		}

		if (contractUser.getRoleType().equals(UserTypeEnum.COMPANY_AGENT.getCode())) {
			attachType = ZqAttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode();
			if (StringUtils.isNotBlank(contractUser.getCertificateImg1())) {
				urls.add(contractUser.getCertificateImg1());
			}
			if (StringUtils.isNotBlank(contractUser.getCertificateImg2())) {
				urls.add(contractUser.getCertificateImg2());
			}
		}

		if (!zqAttachTypeList.contains(attachType)) {
			zqContractAttachList.add(ZqContractAttachDTO.builder().attachType(attachType).urls(urls).build());
		}
	});
	return zqContractAttachList;
}

public ContractAttachTipsVo checkAttach(Byte contractObjectType, Byte haveAgent, Byte agentSign, List<ZqContractAttachDTO> zqContractAttachList, Byte haveHouseProve) {
	Map<Byte, List<String>> zqAttachMap = zqContractAttachList.stream()
		.collect(Collectors.toMap(ZqContractAttachDTO::getAttachType, ZqContractAttachDTO::getUrls, (v1, v2) -> v2));

	//房本都需要
	List<String> houseCertificate = zqAttachMap.get(ZqAttachTypeEnum.HOUSE_CERTIFICATE.getCode());
	if (CollectionUtils.isEmpty(houseCertificate)) {
		if (CommonEnum.YES.getCode().equals(haveHouseProve) || haveHouseProve == null) {
			return new ContractAttachTipsVo(CommonEnum.NO.getCode(), "相关备件不全");
		}
	}

	//公对公需要 经办人证件 公司营业执照
	if (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
		//营业执照
		List<String> companyLicense = zqAttachMap.get(ZqAttachTypeEnum.COMPANY_LICENSE.getCode());
		List<String> companyAgentCertificates = zqAttachMap.get(ZqAttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode());
		if (CollectionUtils.isEmpty(companyLicense) || CollectionUtils.isEmpty(companyAgentCertificates)) {
			return new ContractAttachTipsVo(CommonEnum.NO.getCode(), "相关备件不全");
		}
	} else {
		List<String> ownerCertificates = zqAttachMap.get(ZqAttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode());
		if (CollectionUtils.isEmpty(ownerCertificates)) {
			return new ContractAttachTipsVo(CommonEnum.NO.getCode(), "相关备件不全");
		}
		//有代理人，代理人统一证件不能为空
		if (HaveAgentEnum.YES.getCode().equals(haveAgent)) {
			List<String> agentCertificateUnifyList = zqAttachMap.get(ZqAttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode());
			if (CollectionUtils.isEmpty(agentCertificateUnifyList)) {
				return new ContractAttachTipsVo(CommonEnum.NO.getCode(), "相关备件不全");
			}
		}
		//有代理人委托证明，代理人委托证明不能为空
		if (HaveAgentEnum.YES.getCode().equals(agentSign)) {
			List<String> agentCertificate = zqAttachMap.get(ZqAttachTypeEnum.AGENT_CERTIFICATE.getCode());
			if (CollectionUtils.isEmpty(agentCertificate)) {
				return new ContractAttachTipsVo(CommonEnum.NO.getCode(), "相关备件不全");
			}
		}

	}
	return new ContractAttachTipsVo(CommonEnum.YES.getCode(), "相关备件上传完毕");
}

