private ZqContractDetailResp initContractDetail(String projectOrderId, String changeOrderId, Byte type) {
	ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
	Long designerId = null;
	String designerName = "";
	if (Objects.nonNull(designer)) {
		designerId = designer.getUcId();
		designerName = designer.getName();
	}

	ZqSignTypeDTO signTypeInfo = ZqSignTypeDTO.builder()
		.contractObjectType(ContractObjectTypeEnum.PERSON.getCode())
		.signChannelType(SignChannelTypeEnum.ONLINE.getCode()).build();
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
	if (Objects.isNull(projectInfoDTO) || Objects.isNull(projectInfoDTO.getCustomerCommission())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "查询项目信息为空");
	}
	String address = homeAndPcCommonService.getAddress(projectInfoDTO);
	String customerName = homeAndPcCommonService.getName(projectInfoDTO);
	//方法无使用
	List<ZqCustomerPhoneVo> zqCustomerPhoneVoList = homeAndPcCommonService.getPhoneList(projectInfoDTO);
	ZqSignInfoDTO signInfo = ZqSignInfoDTO.builder()
		.haveAgent(HaveAgentEnum.NO.getCode())
		.ownerName(homeAndPcCommonService.getName(projectInfoDTO))
		.ownerPhone(cipherService.decrypt(homeAndPcCommonService.getPhone(projectInfoDTO)))
		.ownerCertificateType(CertificateTypeEnum.ID.getCode())
		.zqCustomerPhoneVoList(zqCustomerPhoneVoList)
		.build();
	ZqContractProjectDTO contractProjectInfo = null;
	String centerControlType = homeAndPcCommonService.getCenterControlType(projectOrderId);
	if (Objects.nonNull(projectInfoDTO) && Objects.nonNull(projectInfoDTO.getCustomerHouse())) {
		ProjectCustomerHouseDTO houseDTO = projectInfoDTO.getCustomerHouse();
		//初始化时，如果房产类型是未知，则处理为null,否则前端校验有问题
		Integer houseType = houseDTO.getHouseType() == null || houseDTO.getHouseType() == 0 ? null : houseDTO.getHouseType();
		contractProjectInfo = ZqContractProjectDTO.builder()
			.certificateAddress(address)
			.address(address)
			.gbCode(houseDTO.getGbCode()).resblockId(houseDTO.getResblockId()).resblockName(houseDTO.getResblockName())
			.districtId(Objects.isNull(houseDTO.getDistrictId()) ? null : houseDTO.getDistrictId().toString()).districtName(houseDTO.getDistrictName())
			.buildingId(houseDTO.getBuildingId()).buildingName(houseDTO.getBuildingName())
			.unitId(houseDTO.getUnitId()).unitName(houseDTO.getUnitName())
			.floorId(houseDTO.getFloorId()).floorName(houseDTO.getFloorName())
			.houseId(houseDTO.getHouseId()).houseName(houseDTO.getHouseName())
			.designerUcId(designerId)
			.designerName(designerName)
			.area(houseDTO.getArea())
			.parlorCnt(houseDTO.getParlorCnt()).roomCnt(houseDTO.getRoomCnt())
			.cookroomCnt(houseDTO.getCookroomCnt()).toiletCnt(houseDTO.getToiletCnt())
			.balconyCnt(houseDTO.getBalconyCnt()).storageCnt(houseDTO.getStorageCnt())
			.houseType(houseType).houseTypeDesc(houseDTO.getHouseTypeDesc())
			.houseBuildType(houseDTO.getHouseBuildType().equals(0) ? null : houseDTO.getHouseBuildType()).houseBuildTypeDesc(houseDTO.getHouseBuildTypeDesc())
			.decorateForm(houseDTO.getDecorateType()).decorateFormDesc(houseDTO.getDecorateTypeDesc())
			.decorateFormLevel1(Objects.nonNull(projectInfoDTO.getCustomerCommission().getDecorateType()) ? projectInfoDTO.getCustomerCommission().getDecorateType().intValue() : null)
			.decorateFormLevel1Text(projectInfoDTO.getCustomerCommission().getDecorateTypeDesc())
			.decorateFormLevel2(Objects.nonNull(projectInfoDTO.getCustomerCommission().getDecorateId()) ? projectInfoDTO.getCustomerCommission().getDecorateId().intValue() : null)
			.decorateFormLevel2Text(projectInfoDTO.getCustomerCommission().getDecorateIdDesc())
			.build();
	}

	ContractPlanAllDTO contractPlanAllDTO = new ContractPlanAllDTO(quotationFeignService.querySnapshotPlan(projectOrderId, changeOrderId));


	// 5.优惠信息
	QuotationInfoVo quotationInfoVo = getQuotationInfo(projectOrderId, changeOrderId, null, commonContractService.getBusinessType(projectInfoDTO));
	ZqContractDetailResp zqContractDetailResp = ZqContractDetailResp.builder()
		.status(ContractStatusEnum.DRAFT.getCode())
		.address(address)
		.customerName(customerName)
		.type(type)
		.signTypeInfo(signTypeInfo)
		.signInfo(signInfo)
		.planAllInfo(contractPlanAllDTO)
		.centerControlType(centerControlType)
		.quotation(quotationInfoVo)
		.projectInfo(contractProjectInfo)
		.companyCode(projectInfoDTO.getCustomerCommission().getCompanyCode())
		.businessType(commonContractService.getBusinessType(projectInfoDTO))
		.build();

	return zqContractDetailResp;
}

public ContractPreviewVo preview(ZqContractReq body, Long userId) {
	//根据合同类型获取项目单号
	ContractCreateBaseInfo canCreateContract = commonBusinessService.getCanCreateContract(body.getProjectOrderId(), body.getType(), null);
	if (ObjectUtil.isNotEmpty(canCreateContract)) {
		body.setProjectOrderId(canCreateContract.getProjectOrderId());
		body.setType(canCreateContract.getContractType());
	}
	Byte signChannelType = body.getSignTypeInfo().getSignChannelType();
	if (Objects.nonNull(signChannelType) && SignChannelTypeEnum.OFFLINE.getCode().equals(signChannelType)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "线下合同不生成pdf文件-[签约]");
	}
	String contractCode = body.getContractCode();
	String contractNo = "";

	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(body.getProjectOrderId());
	if (Objects.isNull(projectInfoDTO) || Objects.isNull(projectInfoDTO.getCustomerCommission())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目缺少分公司信息");
	}
	String companyCode = projectInfoDTO.getCustomerCommission().getCompanyCode();
	if (Objects.isNull(body.getProjectInfo()) || Objects.isNull(body.getProjectInfo().getGbCode())) {
		LOGGER.warn("合同预览,没有城市信息 body:{} userId:{}", JSONObject.toJSONString(body), userId);
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "预览失败，没有城市信息");
	}
	//pc的只有一个配置，需要读取列表
	Byte businessType = commonContractService.getBusinessType(projectInfoDTO);
	List<ContractCityCompanyInfo> configList = contractCityCompanyConfigService.getConfig(
		body.getProjectOrderId(),
		projectInfoDTO.getCustomerHouse().getGbCode(),
		companyCode,
		businessType,
		body.getType()
	);
	if (configList.isEmpty()) {
		LOGGER.warn("合同预览,缺少合同配置信息 gbCode:{} companyCode:{} type:{} userSignType:{}",
			body.getProjectInfo().getGbCode(), companyCode, body.getType(), body.getUserSignType());
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少合同配置信息");
	}
	ContractCityCompanyInfo config = configList.get(0);

	//预览直接查最新的报价
	PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(body.getProjectOrderId(), body.getChangeOrderId());
	FormalPackageContractFreeformDTO dto = buildFormalPackageContractFreeformDTO(companyCode, userId,
		body, contractNo, planAllDTO, businessType);
	ObjectMapper objectMapper = new ObjectMapper();
	Map<String, Object> map = objectMapper.convertValue(dto, Map.class);
	Contract contract = new Contract();
	contract.setBusinessType(commonContractService.getBusinessType(projectInfoDTO));
	contract.setGbCode(body.getProjectInfo().getGbCode());
	contract.setProjectOrderId(body.getProjectOrderId());
	contract.setUserSignType(body.getUserSignType());
	contract.setType(body.getType());
	contract.setAuditType(config.getAuditType().byteValue());
	contract.setCreateUserId(String.valueOf(userId));
	String pdfUrl = contractBusinessService.generatePdf(contract, map);
	ContractPreviewVo contractPreviewVo = ContractPreviewVo.builder()
		.contractUrl(pdfUrl).contractCode(contractCode).build();

	LOGGER.info("预览接口结果为: {}", pdfUrl);
	return contractPreviewVo;
}

