public Boolean addAttachment(ZqAddAttachReq body, Long userId) {
	LOGGER.info("编辑附件 body:{} userId:{}", JSONObject.toJSONString(body), userId);
	String contractCode = body.getContractCode();
	if (StringUtils.isBlank(contractCode)) {
		LOGGER.warn("编辑附件，contractCode为空");
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "编辑附件，contractCode为空-[签约]");
	}
	Contract dbContract = contractService.getByContractCode(contractCode);
	if (Objects.isNull(dbContract) || (dbContract.getStatus().equals(ContractStatusEnum.FINISH.getCode()))) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "已完成的合同，不可编辑附件-[签约]");
	}

	Map<Byte, List<String>> contractAttachMap = body.getContractAttachList()
		.stream().filter(x -> x != null)
		.collect(Collectors.toMap(ZqContractAttachDTO::getAttachType, ZqContractAttachDTO::getUrls));

	//是否需要校验备件齐全
	boolean needCheckComplete = AttachActionEnum.SUBMIT.getCode().equals(body.getActionType());

	//角色对应的证件类型、护照 attachType
	Map<Byte, Byte> attachFieldMap = new HashMap<>();
	attachFieldMap.put(RoleTypeEnum.OWNER.getCode(), ZqAttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode());
	attachFieldMap.put(RoleTypeEnum.AGENT.getCode(), ZqAttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode());
	attachFieldMap.put(RoleTypeEnum.COMPANY_AGENT.getCode(), ZqAttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode());

	List<ContractUser> userList = contractUserService.getListByContractCode(contractCode);
	for (ContractUser user : userList) {
		if (!attachFieldMap.containsKey(user.getRoleType())) {
			continue;
		}
		byte zqAttachTypeEnum = attachFieldMap.get(user.getRoleType());
		List<String> urls = contractAttachMap.get(zqAttachTypeEnum);

		if (CollectionUtils.isEmpty(urls)) {
			if (needCheckComplete) {
				//需要校验的话，报错
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, RoleTypeEnum.getNameByCode(user.getRoleType()) + "证件信息不全，请补充完整");
			}
		}
	}
	//删除附件
	LOGGER.info("编辑附件,删除附件 delByContractCode contractCode:{} body:{} userId:{}", contractCode, JSONObject.toJSONString(body), userId);
	//如果是线下签约，别删线下合同
	if (dbContract.getSignChannelType().equals(SignChannelTypeEnum.OFFLINE.getCode())) {
		contractAttachService.softDeleteByContractCodeExcludeType(contractCode, AttachTypeEnum.OFFLINE_CONTRACT.getCode());
	} else {
		contractAttachService.softDeleteByContractCode(contractCode);
	}


	List<ContractAttach> contractAttachList = new ArrayList<>();
	//保存contract_attach
	for (ZqContractAttachDTO zqContractAttachDto : body.getContractAttachList()) {
		if (Objects.isNull(zqContractAttachDto)) {
			continue;
		}
		byte zqContractAttachType = zqContractAttachDto.getAttachType();
		AttachTypeEnum attachTypeEnum = ZqAttachTypeEnum.convertToAttachTypeEnum(zqContractAttachType);
		if (Objects.nonNull(attachTypeEnum) && CollectionUtils.isNotEmpty(zqContractAttachDto.getUrls())) {
			for (String url : zqContractAttachDto.getUrls()) {
				ContractAttach attach = new ContractAttach();
				attach.setAttachType(attachTypeEnum.getCode());
				attach.setUrl(url);
				attach.setContractCode(body.getContractCode());
				attach.setCreateUserId(String.valueOf(userId));
				attach.setModifyUserId(String.valueOf(userId));
				contractAttachList.add(attach);
			}
		}
	}
	for (ContractAttach contractAttach : contractAttachList) {
		contractAttachService.insert(contractAttach);
	}

	if (AttachActionEnum.SUBMIT.getCode().equals(body.getActionType())) {
		//附件上传完毕，添加日志信息
		contractBusinessService.remarkSupplementLog(dbContract);
		//添加合同节点
		contractBusinessService.remarkSupplementNode(dbContract.getContractCode());

		eventService.publish(commonContractService.getContractEvent(dbContract), EventType.CONTRACT_ATTACH_COMPLETE, dbContract.getContractCode());
	}
	return true;
}

public Boolean addAttachmentV2(ZqAddAttachReq body, Long userId) {
	LOGGER.info("编辑附件V2 body:{} userId:{}", JSONObject.toJSONString(body), userId);
	String contractCode = body.getContractCode();
	if (StringUtils.isBlank(contractCode)) {
		LOGGER.warn("编辑附件V2，contractCode为空");
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "编辑附件，contractCode为空-[签约]");
	}
	Contract dbContract = contractService.getByContractCode(contractCode);
	if (Objects.isNull(dbContract) || (dbContract.getStatus().equals(ContractStatusEnum.FINISH.getCode()))) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "已完成的合同，不可编辑附件-[签约]");
	}

	Map<Byte, List<File>> contractAttachMap = body.getContractAttachList()
		.stream().filter(x -> x != null)
		.collect(Collectors.toMap(ZqContractAttachDTO::getAttachType, ZqContractAttachDTO::getFileList));

	//是否需要校验备件齐全
	boolean needCheckComplete = AttachActionEnum.SUBMIT.getCode().equals(body.getActionType());

	//角色对应的证件类型、护照 attachType
	Map<Byte, Byte> attachFieldMap = new HashMap<>();
	attachFieldMap.put(RoleTypeEnum.OWNER.getCode(), ZqAttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode());
	attachFieldMap.put(RoleTypeEnum.AGENT.getCode(), ZqAttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode());
	attachFieldMap.put(RoleTypeEnum.COMPANY_AGENT.getCode(), ZqAttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode());
	attachFieldMap.put(RoleTypeEnum.LEGAL.getCode(), ZqAttachTypeEnum.LEGAL_CERTIFICATE_UNIFY.getCode());

	String signRole = contractFieldService.getFieldValueByContractCodeAndKey(contractCode, "signRole");

	List<ContractUser> userList = contractUserService.getListByContractCode(contractCode);
	for (ContractUser user : userList) {
		if (!attachFieldMap.containsKey(user.getRoleType())) {
			continue;
		}
		if (RoleTypeEnum.LEGAL.getCode().toString().equals(signRole) && RoleTypeEnum.COMPANY_AGENT.getCode().equals(user.getRoleType())) {
			continue;
		}
		byte zqAttachTypeEnum = attachFieldMap.get(user.getRoleType());
		List<File> urls = contractAttachMap.get(zqAttachTypeEnum);

		if (CollectionUtils.isEmpty(urls)) {
			if (needCheckComplete) {
				//需要校验的话，报错
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, RoleTypeEnum.getNameByCode(user.getRoleType()) + "证件信息不全，请补充完整");
			}
		}
	}
	//删除附件
	LOGGER.info("编辑附件V2,删除附件 delByContractCode contractCode:{} body:{} userId:{}", contractCode, JSONObject.toJSONString(body), userId);
	//如果是线下签约，别删线下合同
	if (dbContract.getSignChannelType().equals(SignChannelTypeEnum.OFFLINE.getCode())) {
		contractAttachService.softDeleteByContractCodeExcludeType(contractCode, AttachTypeEnum.OFFLINE_CONTRACT.getCode());
	} else {
		contractAttachService.softDeleteByContractCode(contractCode);
	}


	ContractAttachInfo contractAttachInfo = new ContractAttachInfo();
	for (ZqContractAttachDTO zqContractAttachDto : body.getContractAttachList()) {
		if (Objects.isNull(zqContractAttachDto)) {
			continue;
		}
		byte zqContractAttachType = zqContractAttachDto.getAttachType();
		AttachTypeEnum attachTypeEnum = ZqAttachTypeEnum.convertToAttachTypeEnum(zqContractAttachType);
		if (Objects.nonNull(attachTypeEnum) && CollectionUtils.isNotEmpty(zqContractAttachDto.getFileList())) {
			if (AttachTypeEnum.USER_CERTIFICATE_UNIFY.equals(attachTypeEnum)) {
				contractAttachInfo.getUserCertificateUnify().addAll(zqContractAttachDto.getFileList());
			}
			if (AttachTypeEnum.HOUSE_CERTIFICATE.equals(attachTypeEnum)) {
				contractAttachInfo.getHouseCertificate().addAll(zqContractAttachDto.getFileList());
			}
			if (AttachTypeEnum.OTHER_OWNER_SHIP.equals(attachTypeEnum)) {
				contractAttachInfo.getOtherOwnerShip().addAll(zqContractAttachDto.getFileList());
			}
			if (AttachTypeEnum.AGENT_CERTIFICATE_UNIFY.equals(attachTypeEnum)) {
				contractAttachInfo.getAgentCertificateUnify().addAll(zqContractAttachDto.getFileList());
			}
			if (AttachTypeEnum.AGENT_CERTIFICATE.equals(attachTypeEnum)) {
				contractAttachInfo.getAgentCertificate().addAll(zqContractAttachDto.getFileList());
			}
			if (AttachTypeEnum.OTHER.equals(attachTypeEnum)) {
				contractAttachInfo.getOther().addAll(zqContractAttachDto.getFileList());
			}
			if (AttachTypeEnum.COMPANY_LICENSE.equals(attachTypeEnum)) {
				contractAttachInfo.getCompanyLicense().addAll(zqContractAttachDto.getFileList());
			}
			if (AttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.equals(attachTypeEnum)) {
				contractAttachInfo.getCompanyAgentCertificateUnify().addAll(zqContractAttachDto.getFileList());
			}
			if (AttachTypeEnum.LEGAL_CERTIFICATE_UNIFY.equals(attachTypeEnum)) {
				contractAttachInfo.getLegalCertificateUnify().addAll(zqContractAttachDto.getFileList());
			}
		}
	}
	//校验合同备件url是否合法
	contractUnifyService.checkContractAttachUrl(contractAttachInfo);
	ContractSignInfoDetail contractSignInfo = getContractSignInfo(dbContract);
	List<CertificateDTO> certificateDTOList = contractUnifyService.saveFileToMiddleGround(contractAttachInfo, contractSignInfo, dbContract.getProjectOrderId());

	List<ContractAttach> contractAttachList = new ArrayList<>();
	for (CertificateDTO certificateDTO : certificateDTOList) {
		ContractAttach attach = new ContractAttach();
		attach.setAttachType(certificateDTO.getCertificateCode().byteValue());
		attach.setUrl("");
		attach.setCertificateId(certificateDTO.getCertificateId());
		attach.setContractCode(contractCode);
		attach.setDocumentCode("");
		attach.setFileKey("");
		attach.setVeracity(ContractAttachVeracityEnum.NONE.getCode());
		attach.setSyncType(AttachSyncTypeEnum.NO_SYNC.getCode());
		attach.setCtime(new Date());
		attach.setMtime(new Date());
		attach.setCreateUserId(String.valueOf(HeaderContext.getUserId()));
		attach.setCreateUserName(HeaderContext.getContext().getOperatorName());
		attach.setModifyUserId(String.valueOf(HeaderContext.getUserId()));
		attach.setModifyUserName(HeaderContext.getContext().getOperatorName());
		attach.setDelStatus(CommonEnum.NO.getCode());
		contractAttachList.add(attach);
	}
	if (!CollectionUtils.isEmpty(contractAttachList)) {
		contractAttachService.insertBatch(contractAttachList);
	}
	if (AttachActionEnum.SUBMIT.getCode().equals(body.getActionType())) {
		//附件上传完毕，添加日志信息
		contractBusinessService.remarkSupplementLog(dbContract);
		//添加合同节点
		contractBusinessService.remarkSupplementNode(dbContract.getContractCode());

		eventService.publish(commonContractService.getContractEvent(dbContract), EventType.CONTRACT_ATTACH_COMPLETE, dbContract.getContractCode());
	}
	return true;
}

