public QuotationInfoVo getQuotationInfo(String projectOrderId, String changeOrderId, String contractCode, Byte businessType) {

	PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(projectOrderId, changeOrderId);
	PlanInfoDTO planInfoDTO = planAllDTO.getPlanInfo();
	String filePrevUrl = "";
	String fileUrl = "";
	String internalConfigurationsFileUrl = "";
	String internalConfigurationsFilePrevUrl = "";
	String extraConfigurationsFileUrl = "";
	String extraConfigurationsFilePrevUrl = "";
	String personalQuotionFileUrl = "";
	String personalQuotionFilePrevUrl = "";
	String baseConstructionDrawFileUrl = "";
	String baseConstructionDrawPrevFileUrl = "";
	if (CollectionUtils.isNotEmpty(planAllDTO.getPlanAttachmentList())) {
		for (PlanAttachmentDTO planAttachmentDTO : planAllDTO.getPlanAttachmentList()) {
			switch (planAttachmentDTO.getFileType()) {
				case PlanAttachment.报价单:
					filePrevUrl = planAttachmentDTO.getPrevUrl();
					fileUrl = planAttachmentDTO.getFileUrl();
					break;
				case PlanAttachment.套餐套内配置清单:
					internalConfigurationsFilePrevUrl = planAttachmentDTO.getPrevUrl();
					internalConfigurationsFileUrl = planAttachmentDTO.getFileUrl();
					break;
				case PlanAttachment.加载配置清单:
					extraConfigurationsFilePrevUrl = planAttachmentDTO.getPrevUrl();
					extraConfigurationsFileUrl = planAttachmentDTO.getFileUrl();
					break;
				case PlanAttachment.套外个性化报价单:
					personalQuotionFilePrevUrl = planAttachmentDTO.getPrevUrl();
					personalQuotionFileUrl = planAttachmentDTO.getFileUrl();
					break;
				case PlanAttachment.基础图纸:
					baseConstructionDrawPrevFileUrl = planAttachmentDTO.getPrevUrl();
					baseConstructionDrawFileUrl = planAttachmentDTO.getFileUrl();
					break;
				default:
			}
		}
	}
	BigDecimal comboPrice = planInfoDTO.getComboPrice();
	BigDecimal personalTotalPrice = planInfoDTO.getPersonalTotalPrice();
	//兼容团装历史数据
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && StrUtil.isBlank(internalConfigurationsFileUrl)
		&& StrUtil.isBlank(internalConfigurationsFilePrevUrl)) {
		internalConfigurationsFileUrl = fileUrl;
		internalConfigurationsFilePrevUrl = filePrevUrl;
		comboPrice = planInfoDTO.getQuotePrice();
	}

	String houseLayoutInfoStr = "";
	HouseLayoutInfoDTO houseLayoutInfoDTO = planAllDTO.getReconstructionHouseLayout();
	if (Objects.nonNull(houseLayoutInfoDTO)) {
		Integer livingRoomNum = Objects.isNull(houseLayoutInfoDTO.getLivingRoomNum()) ? 0 : houseLayoutInfoDTO.getLivingRoomNum();
		Integer bedroomNum = Objects.isNull(houseLayoutInfoDTO.getBedroomNum()) ? 0 : houseLayoutInfoDTO.getBedroomNum();
		Integer kitchenNum = Objects.isNull(houseLayoutInfoDTO.getKitchenNum()) ? 0 : houseLayoutInfoDTO.getKitchenNum();
		Integer toiletNum = Objects.isNull(houseLayoutInfoDTO.getToiletNum()) ? 0 : houseLayoutInfoDTO.getToiletNum();
		Integer balconyNum = Objects.isNull(houseLayoutInfoDTO.getBalconyNum()) ? 0 : houseLayoutInfoDTO.getBalconyNum();
		Integer storeroomNum = Objects.isNull(houseLayoutInfoDTO.getStoreroomNum()) ? 0 : houseLayoutInfoDTO.getStoreroomNum();
		houseLayoutInfoStr = MessageFormat.format("{0}室{1}厅{2}厨{3}卫{4}阳台{5}储物间", bedroomNum, livingRoomNum,
			kitchenNum, toiletNum, balconyNum, storeroomNum);
	}


	BigDecimal discountAmount = null;
	if (CollectionUtils.isNotEmpty(planAllDTO.getCouponList())) {
		for (CouponDTO couponDTO : planAllDTO.getCouponList()) {
			if (CouponTypeEnum.DIRECT_COUPON.getCode().equals(couponDTO.getCouponType())) {
				discountAmount = couponDTO.getLapseAmount();
			}
		}
	}
	return QuotationInfoVo.builder()
		//旧逻辑，无使用
		.comboCode(planInfoDTO.getComboCode())
		.comboName(planInfoDTO.getComboName())
		.contractPrice(planInfoDTO.getContractPriceTotal())
		.planTotalPrice(planInfoDTO.getNewestPlanPriceTotal())
		.pricingArea(planInfoDTO.getPricingArea())
		.remark(planInfoDTO.getRemark())
		.quotePrice(planInfoDTO.getQuotePrice())
		.comboPrice(comboPrice)
		.containsPersonal(planInfoDTO.getContainsPersonal())
		.personalTotalPrice(personalTotalPrice)
		.filePrevUrl(filePrevUrl)
		.fileUrl(fileUrl)
		.internalConfigurationsFilePrevUrl(internalConfigurationsFilePrevUrl)
		.internalConfigurationsFileUrl(internalConfigurationsFileUrl)
		.extraConfigurationsFilePrevUrl(extraConfigurationsFilePrevUrl)
		.extraConfigurationsFileUrl(extraConfigurationsFileUrl)
		.personalQuotionFilePrevUrl(personalQuotionFilePrevUrl)
		.personalQuotionFileUrl(personalQuotionFileUrl)
		.baseConstructionDrawPrevFileUrl(baseConstructionDrawPrevFileUrl)
		.baseConstructionDrawFileUrl(baseConstructionDrawFileUrl)
		.houseLayout(houseLayoutInfoStr)
		.discountAmount(discountAmount)
		.build();

}

public List<ZqOperationLogVo> getOperationLog(String contractCode) {
	List<ContractLog> contractLogList = contractLogService.searchLog(contractCode);
	List<ZqOperationLogVo> zqOperationLogVoList = Lists.newArrayList();
	if (CollectionUtils.isEmpty(contractLogList)) {
		return zqOperationLogVoList;
	}
	Map<String, String> contractMap = new HashMap<>();
	Contract contract = contractService.getByContractCode(contractCode);
	contractMap.put(contract.getContractCode(), ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType()));
	//合并发起模式的需要获取图纸合同的操作记录
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());

	if (processV25 && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
		List<Contract> contractList = contractService.getContractList(contract.getProjectOrderId(), ContractTypeEnum.DRAWING.getCode());
		if (CollectionUtils.isNotEmpty(contractList)) {
			List<ContractLog> drawingLogs = contractLogService.searchLog(contractList.get(0).getContractCode());
			if (CollectionUtils.isNotEmpty(drawingLogs)) {
				contractLogList.addAll(drawingLogs);
			}
			contractMap.put(contractList.get(0).getContractCode(), ContractTypeEnum.getNameByContractTypeAndBusinessType(contractList.get(0).getType(), contractList.get(0).getBusinessType()));
		}
	}
	contractLogList = contractLogList.stream()
		.filter(log -> !LogTypeEnum.noShowLogTypeList().contains(log.getType()))
		.sorted((contractLog1, contractLog2) -> contractLog2.getCtime().compareTo(contractLog1.getCtime()))
		.collect(Collectors.toList());
	contractLogList.forEach(contractLog -> {
		Byte contractLogType = contractLog.getType();
		ZqOperationLogVo zqOperationLogVo = ZqOperationLogVo.builder().build();
		zqOperationLogVo.setBpmUrl("");
		if (LogTypeEnum.FINISH.getCode().equals(contractLogType) || LogTypeEnum.SUBMIT_AUDIT.getCode().equals(contractLogType) ||
			LogTypeEnum.AUDIT_REJECT.getCode().equals(contractLogType) || LogTypeEnum.AUDIT_PASS.getCode().equals(contractLogType)) {
			ContractLogRemarkDto remarkArrayInfo = contractBusinessService.getRemarkInfo(contractLog.getRemark());
			String bpmNo = remarkArrayInfo.getBpmNo();
			String remark = remarkArrayInfo.getRemark();
			if (StringUtils.isNotEmpty(bpmNo)) {
				if (processV25 && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(contract.getBusinessType()) && ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType())) {
					zqOperationLogVo.setBpmUrl(getBpmStagingUrl(bpmNo));
				} else {
					// 目前设计费审核和通用审核url没区别，如果后续设计费审核url有区别再区分
					zqOperationLogVo.setBpmUrl(getBpmUrl(bpmNo));
				}
			} else if (StringUtils.isNotBlank(remark)) {
				zqOperationLogVo.setLogContent(remark);
			} else {
				//历史数据保持不变
				zqOperationLogVo.setBpmUrl(getBpmUrl(contract.getBmpNo()));
			}
		}
		zqOperationLogVo.setTypeContent(processV25
			? contractMap.get(contractLog.getContractCode()).concat(":").concat(contractLog.getContent())
			: contractLog.getContent());
		zqOperationLogVo.setCtime(DateUtils.getDateTimeStr(contractLog.getCtime()));
		zqOperationLogVo.setCreateUserName(contractLog.getCreateUserName());
		zqOperationLogVo.setCreateUserId(contractLog.getCreateUserId());
		zqOperationLogVoList.add(zqOperationLogVo);
	});

	// 操作人ucid转系统号
	userIdConvertSystemCode(zqOperationLogVoList);

	return zqOperationLogVoList;
}

private void userIdConvertSystemCode(List<ZqOperationLogVo> zqOperationLogVoList) {
	if (CollectionUtils.isEmpty(zqOperationLogVoList)) {
		return;
	}

	List<String> userIdList = zqOperationLogVoList.stream().map(ZqOperationLogVo::getCreateUserId).collect(Collectors.toList());
	Map<String, String> userSystemCodeMap = memberRpc.getUserSystemCodeMap(userIdList);
	for (ZqOperationLogVo zqOperationLogVo : zqOperationLogVoList) {
		String createUserId = zqOperationLogVo.getCreateUserId();
		zqOperationLogVo.setCreateUserId(userSystemCodeMap.get(createUserId));
	}
}

