private ContractStatusVo convertStatusVo(int status) {
	if (status == ContractStatusEnum.DRAFT.getCode().intValue()) {
		return new ContractStatusVo(1, ContractStatusEnum.DRAFT.getName());
	}
	if (status == ContractStatusEnum.PENDING_USER_SIGN.getCode().intValue()) {
		return new ContractStatusVo(2, ContractStatusEnum.PENDING_USER_SIGN.getName());
	}

	if (status == ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode().intValue() || status == ContractStatusEnum.AUDITING.getCode().intValue()
		|| status == ContractStatusEnum.PENDING_COMPANY_SIGN.getCode().intValue()) {
		return new ContractStatusVo(3, ContractStatusEnum.AUDITING.getName());
	}

	if (status == ContractStatusEnum.FINISH.getCode().intValue()) {
		return new ContractStatusVo(4, ContractStatusEnum.FINISH.getName());
	}
	return null;

}

