private List<ContractTypeListVo.ContractShowListItem> getContractInfoText(List<Contract> contractList, ContractTypeEnum contractTypeEnum, Integer authStatus) {
	List<ContractTypeListVo.ContractShowListItem> showListItems = new ArrayList<>();

	if (ContractTypeEnum.HAVE_AGENT_AUTH_CONTRACT_TYPES.contains(contractTypeEnum.getCode())) {
		// 产权人授权状态
		Contract contract = contractList.stream().filter(c -> ContractStatusEnum.allValidStatus.contains(c.getStatus()))
			.findFirst().orElse(null);
		if (contract != null) {
			Contract authAgentContract = homeAndPcCommonService.getRelateContractByType(contract, ContractTypeEnum.AUTH_AGENT.getCode());
			if (authAgentContract != null) {
				showListItems.add(ContractTypeListVo.ContractShowListItem.builder()
					.key("产权人授权状态")
					.value(ContractStatusEnum.SIGNED_STATUS_LIST.contains(authAgentContract.getStatus()) ? "已授权" : "未授权")
					.build());
			}
		}
	}

	// 认证状态、授权状态
	if (!ContractAuthStatusEnum.getNeedAuthStatus().contains(authStatus)) {
		return showListItems;
	}
	showListItems.add(ContractTypeListVo.ContractShowListItem.builder()
		.key("认证状态")
		.value(Boolean.TRUE.equals(ContractAuthStatusEnum.isAuthentication(authStatus)) ? "已认证" : "未认证")
		.build());
	showListItems.add(ContractTypeListVo.ContractShowListItem.builder()
		.key("授权状态")
		.value(Boolean.TRUE.equals(ContractAuthStatusEnum.isAuthorized(authStatus)) ? "已授权" : "未授权")
		.build());


	return showListItems;
}

private List<ButtonItemVo> getButtonListByConfig(Contract contract, List<String> attachUrlList, @Nullable List<Contract> contractList, List<ContractNode> userConfirmNodeList) {
	boolean hasContractAgreement = contract.getPlatformInstanceId() > 0 || !attachUrlList.isEmpty();
	// 补充协议单独发起
	boolean supplementSubmitAlone = homeAndPcCommonService.supplementSubmitAlone(contract);
	// 设计合同单独发起
	boolean designContractSubmitAlone = homeAndPcCommonService.designContractSubmitAlone(contract);
	// 匹配参数
	ContractListButtonExecParam execParams = ContractListButtonExecParam.builder()
		.contractCode(contract.getContractCode())
		.contractType(contract.getType())
		.contractStatus(contract.getStatus())
		.contractList(contractList)
		.userConfirmNodeList(userConfirmNodeList)
		.bpmNo(contract.getBmpNo())
		.changeOrderId(contract.getChangeOrderId())
		.beijingOldOrder(false)
		.multipleQuotePersonalContract(null)
		.hasContractAgreement(hasContractAgreement)
		.supplementSubmitAlone(supplementSubmitAlone)
		.designContractSubmitAlone(designContractSubmitAlone)
		.build();
	List<ButtonItemVo> homeContractListButton = buttonConfigService.getPcContractListButton(execParams);
	//生成中的合同不展示按钮
	if (!contractApolloConfig.getContractSubmitSync() && ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())
		&& lockService.isLocked(LockConstant.getContractLaunchingKey(contract.getProjectOrderId(), contract.getType()))) {
		return new ArrayList<>();
	}
	return homeContractListButton;
}

