public ContractButtonVo contractButtonList(String contractCode) {
	try {
		ContractButtonVo contractButtonVo = new ContractButtonVo();
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.nonNull(contract)) {
			List<String> attachUrlList = commonService.getAttachUrl(contract);
			//用户确认节点列表
			List<ContractNode> userConfirmNodeList = contractNodeService.getListByContractCodesAndType(Collections.singletonList(contractCode), Collections.singletonList(NodeTypeEnum.USER_CONFIRM.getCode()));
			List<ButtonItemVo> buttonItemVos = getButtonListByConfig(contract, attachUrlList, null, userConfirmNodeList);
			if (CollectionUtils.isNotEmpty(buttonItemVos)) {
				List<ButtonItemVo> buttons = buttonItemVos.stream().filter(
						button -> PcButtonEnum.getContractDetailButtonTypes().containsKey(button.getType()))
					.collect(Collectors.toList());
				contractButtonVo.setButtonList(buttons);
				if (!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
					// 设计费审核和通用审核url目前没区别，如果后续设计费审核url有区别再区分
					contractButtonVo.setBpmUrl(getBpmUrl(contract.getBmpNo()));
					contractButtonVo.setContractUrl(commonService.getContractUrl(contract));
				}
				if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
					contractButtonVo.setAttachUrl(commonService.getAttachUrl(contract));
				}

			}
			return contractButtonVo;
		}
	} catch (Exception e) {
		LOGGER.error("获取合同详情按钮失败 contractCode:{} e:{}", contractCode, e);
	}
	return null;

}

