    //使用：合同pdf转图片,新增收据，需验证收据功能
	//S3类型：私有
	public List<String> pdf2ImageOptimized(String fileUrl) {
		if (!checkParameter(fileUrl)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "pdf转图片错误，域名校验失败");
		}

		if (contractApolloConfig.getPdfToImageUseNrsSignContract()) {
			try {
				long startTimeMillis = System.currentTimeMillis();
				List<String> imageKeys = convertPdfToPrivateImageKeysAndGetImages(fileUrl);
				LOGGER.info("调用工具服务[private]pdf转图片成功，fileUrl:{}，耗时:{}ms", fileUrl, System.currentTimeMillis() - startTimeMillis);
				return imageKeys;
			} catch (Exception e) {
				LOGGER.error("pdf转图片失败(pdf2ImageOptimized)，使用兜底逻辑处理，fileUrl:{}", fileUrl, e);
			}
		}
		List<String> resultList = new ArrayList<>();

		try {
			long startTimeMillis = System.currentTimeMillis();
			LOGGER.info("pdf转图片开始-new fileUrl:{}", fileUrl);

			String[] urlString = fileUrl.split("\\?");
			String[] strings = urlString[0].split("/");
			String baseFileName = org.springframework.util.StringUtils.stripFilenameExtension(strings[strings.length - 1]);

			byte[] fileContent = read(fileUrl); // 只读一次 PDF 数据

			// 使用磁盘缓存，避免大文件占用内存
			try (InputStream inputStream = new ByteArrayInputStream(fileContent);
				 PDDocument document = PDDocument.load(inputStream, MemoryUsageSetting.setupTempFileOnly())) {
				PDFRenderer renderer = new PDFRenderer(document);
				int numberOfPages = document.getNumberOfPages();
				AtomicInteger successPage = new AtomicInteger();
				CompletableFuture<?>[] futures = new CompletableFuture[numberOfPages];
				String[] s3Urls = new String[numberOfPages];
				for (int i = 0; i < numberOfPages; i++) {
					int pageIndex = i;
					// 渲染图像（主线程）
					BufferedImage image = renderer.renderImageWithDPI(pageIndex, dpi, ImageType.RGB);

					CompletableFuture<Void> uploadFuture = CompletableFuture.runAsync(RunnableWrapper.of(new Runnable() {
						@SneakyThrows
						@Override
						public void run() {
							File tempImageFile = null;
							try {
								// 写入临时文件，降低内存占用
								tempImageFile = File.createTempFile(UUID.randomUUID()+"pdf_" + pageIndex + "_", "." + imageType);
								try (OutputStream out = new FileOutputStream(tempImageFile)) {
									ImageIO.write(image, imageType, out);
								}
								image.flush(); // 显式释放图像内存
								byte[] imageBytes = Files.readAllBytes(tempImageFile.toPath());
								String objectKey = s3Service.md5FileName(baseFileName)
									+ "(" + pageIndex + ")." + imageType;
								s3Service.upload(imageBytes, objectKey);
								LOGGER.info("第{}页上传完成", pageIndex + 1);
								s3Urls[pageIndex] = objectKey;
							} catch (Exception e) {
								LOGGER.info("第{}页上传失败,{}", pageIndex + 1, e.getMessage());
							} finally {
								// 删除临时文件
								if (tempImageFile != null && !tempImageFile.delete()) {
									LOGGER.warn("临时文件删除失败：{}", tempImageFile.getAbsolutePath());
								}
							}
						}
					}), parallelRequestExecutor).thenRun(RunnableWrapper.of(successPage::getAndIncrement));
					futures[pageIndex] = uploadFuture;
				}
				CompletableFuture<Void> allOf = CompletableFuture.allOf(futures);
                allOf.join(); // 等待所有上传完成
				if (successPage.get() != numberOfPages) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "pdf转图片错误");
				}
				resultList = new ArrayList<>(Arrays.asList(s3Urls));
				LOGGER.info("pdf转图片结束-new fileUrl:{}, cost:{}ms", fileUrl, System.currentTimeMillis() - startTimeMillis);
