	}

	/**
	 * 通用触发 PDF 转图片并轮询结果
	 *
	 * @param pdfUrl PDF 文件地址
	 * @param isPublic 是否生成公开图片
	 * @return 图片 URL 列表或 key 列表
	 */
	public List<String> convertPdfAndWait(String pdfUrl, boolean isPublic) {
		// 1. 发起任务
		String taskId = isPublic
			? utilsToolRpc.convertToPublicImageUrls(pdfUrl, false).getTaskId()
			: utilsToolRpc.convertToPrivateImageKeys(pdfUrl, false).getTaskId();

		if (taskId == null) {
			throw new IllegalStateException("启动 PDF 转图片失败：未返回 taskId");
		}

		// 2. 轮询获取结果
		for (int i = 1; i <= contractApolloConfig.getPdfToImageMaxAttempts(); i++) {
			sleepSafely(INTERVAL_MS);

			AsyncPdfToImageResult result = utilsToolRpc.getAsyncPdfToImageResult(taskId);
			Integer status = result.getStatus();

			if (PdfToImageStatusEnum.SUCCESS.getCode().equals(status)) {
				if (CollectionUtils.isEmpty(result.getImageList())) {
					throw new RuntimeException(String.format("PDF 转图片失败，taskId=%s，原因=转换结果为空", taskId));
				}
				return result.getImageList();
			}
			if (PdfToImageStatusEnum.FAIL.getCode().equals(status)) {
				throw new RuntimeException(String.format("PDF 转图片失败，taskId=%s，原因=%s",
					taskId, result.getErrorMessage()));
			}

			if (i % 10 == 0) { // 每10次打印一次日志，防止刷屏
				LOGGER.info("PDF 转图片进行中... taskId={}，已轮询 {} 次", taskId, i);
			}
		}

		throw new RuntimeException("PDF 转图片超时未完成，taskId=" + taskId);
	}

	private void sleepSafely(int ms) {
		try {
			Thread.sleep(ms);
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new RuntimeException("线程中断", e);
		}
	}




}

public List<String> pdf2ImagePublicParallel(String fileUrl) {
	if (StringUtils.isBlank(fileUrl)) {
		return new ArrayList<>();
	}

	if (!checkParameter(fileUrl)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "pdf转图片错误，域名校验失败");
	}

	if (contractApolloConfig.getPdfToImageUseNrsSignContract()) {
		try {
			long startTimeMillis = System.currentTimeMillis();
			List<String> imageUrlList = convertToPublicImageUrlsAndGetImages(fileUrl);
			LOGGER.info("调用工具服务[public]pdf转图片成功--，fileUrl:{}，耗时:{}ms", fileUrl, System.currentTimeMillis() - startTimeMillis);
			return imageUrlList;
		} catch (Exception e) {
			LOGGER.error("pdf转图片失败(pdf2ImagePublicParallel)，使用兜底逻辑处理，fileUrl:{}", fileUrl, e);
		}
	}

	PDDocument document = null;
	List<String> list;

	try {
		long startTimeMillis = System.currentTimeMillis();
		LOGGER.info("pdf转图片开始 fileUrl:{}", fileUrl);
		String[] urlString = fileUrl.split("\\?");
		String[] strings = urlString[0].split("/");
		byte[] fileContent = read(fileUrl);

		document = PDDocument.load(fileContent);
		PDFRenderer renderer = new PDFRenderer(document);
		int numberOfPages = document.getNumberOfPages();
		if (numberOfPages > limitPages) {
			throw new NrsBusinessException(ResponseCodeEnum.PDF_PAGES_LIMIT.getCode(), String.format(ResponseCodeEnum.PDF_PAGES_LIMIT.getMsg(), limitPages), Level.WARN);
		}
		AtomicInteger successPage = new AtomicInteger();
		CompletableFuture<?>[] futures = new CompletableFuture[numberOfPages];
		String[] s3Urls = new String[numberOfPages];
		for (int i = 0; i < numberOfPages; i++) {
			String fileObjectKey = s3Service.md5FileName(org.springframework.util.StringUtils.stripFilenameExtension(strings[strings.length-1]))
				+ "(" + i + ")." + imageType;
			BufferedImage bufferedImage = renderer.renderImageWithDPI(i, dpi);

			// 异步执行任务 RunnableWrapper 传递traceId到异步线程
			int finalI = i;
			Runnable task = RunnableWrapper.of(new Runnable() {
				@SneakyThrows
				@Override
				public void run() {
					try {
						ByteArrayOutputStream out = new ByteArrayOutputStream();
						ImageIO.write(bufferedImage, imageType, out);
						s3Urls[finalI] = s3Service.uploadPublic(out.toByteArray(), fileObjectKey);
					} catch (Exception e) {
						LOGGER.warn("pdf转图片错误", e);
					}
				}
			});

			CompletableFuture<Void> future = CompletableFuture.runAsync(task, taskExecutor)
				.thenRun(RunnableWrapper.of(successPage::getAndIncrement));
			futures[i] = future;
		}

		// 等待所有线程执行完成
		CompletableFuture<Void> allOf = CompletableFuture.allOf(futures);
		allOf.join();
		if (successPage.get() != numberOfPages) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "pdf转图片错误");
		}

		list = new ArrayList<>(Arrays.asList(s3Urls));
		LOGGER.info("pdf转图片结束 fileUrl:{}, cost:{}", fileUrl, System.currentTimeMillis() - startTimeMillis);
	} catch (NrsBusinessException e) {
		throw e;
	} catch (IOException e) {
		throw new NrsBusinessException(ResponseCodeEnum.PDF_URL_ERROR.getCode(), ResponseCodeEnum.PDF_URL_ERROR.getMsg(), Level.WARN);
	} catch (Exception e) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "pdf转图片错误:"+ e.getMessage());
	} finally {
		if(Objects.nonNull(document)){
			try {
				document.close();
			} catch (IOException e) {
				LOGGER.warn("pdf转图片错误", e);
			}
		}
	}

	return CollectionUtils.isEmpty(list) ? new ArrayList<>() : list;
}

