@Service
@Slf4j
public class QuoteContractService {

	@Resource
	CommonContractService commonContractService;

	@Resource
	ProjectInfoService projectInfoService;

	/**
	 * 获取报价单合同信息
	 * 查询逻辑：根据整装项目查询B&C合同，优先C合同，没有的话再取B合同
	 * 业务规则：先B合同签约，再C合同签约
	 * 1.B合同签署后，可能会创建零售CT订单；
	 * 2.C合同签署后，可能会创建零售CT订单
	 *
	 */
	public ContractBaseDTO getRetailRelateOrderInfo(SubmitQuotationOrderBo orderSubmitBo) {
		BudgetBillDTO.BillDTO billDTO = orderSubmitBo.getBillDTO();

		//正签场景校验跟报价单签约状态一致，变更场景不校验报价单状态（变更报价单流转到已完成/签约的时机会后置到变更单完成，目前变更确认下单是客户确认完成，报价单还没签约）
		if (orderSubmitBo.getIsSignQuote() && !GeneralBillStatusEnum.SIGNED.getCode().equals(billDTO.getStatus())) {
			LOGGER.warn("getRetailRelateOrderInfo--正签场景,报价单状态还未签约,无需查询合同信息");
			return null;
		} else if (!orderSubmitBo.getIsSignQuote() && !Objects.isNull(orderSubmitBo.getChangeCreateScene()) && OrderCreateSceneEnum.CHANGE_QUOTE_SUBMIT.getCode().equals(orderSubmitBo.getChangeCreateScene())) {
			LOGGER.warn("getRetailRelateOrderInfo--变更场景,变更报价单提交,还未完成确认,无需查询合同信息");
			return null;
		}

		BusinessTypeEnum businessTypeEnum = BusinessTypeEnum.getEnumByDecorateType(CommissionDecorateTypeEnum.getEnumByCode(orderSubmitBo.getDecorationDecorateType()));
		if (Objects.isNull(businessTypeEnum)) {
			LOGGER.error("getRetailRelateOrderInfo--未找到对应的业务类型,decorateType:{}", orderSubmitBo.getDecorationDecorateType());
			return null;
		}
		// TODO: 2025/4/16 业务类型有问题（整装、纯零售传1，团装传3）
		List<ContractBaseDTO> contractBaseDTOList = commonContractService.getBaseContractInfo(businessTypeEnum.getCode(), billDTO.getProjectOrderId(), (byte) -1);

		//找到签约完成的合同
		contractBaseDTOList = contractBaseDTOList.stream().filter(contractBaseDTO -> ContractStatusEnum.FINISH.getCode().equals(contractBaseDTO.getStatus()) ||
			ContractStatusEnum.USER_CONFIRMED.getCode().equals(contractBaseDTO.getStatus())).collect(Collectors.toList());
		//找到其中的销售合同和套餐合同
		contractBaseDTOList = contractBaseDTOList.stream().filter(contractBaseDTO -> ContractTypeEnum.PERSONAL.getCode().equals(contractBaseDTO.getType()) || ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractBaseDTO.getType())).collect(Collectors.toList());

		if (CollectionUtils.isEmpty(contractBaseDTOList)) {
			LOGGER.info("getRetailRelateOrderInfo--合同列表为空,billCode:{},projectOrderId:{}", billDTO.getBillCode(), billDTO.getProjectOrderId());
			return null;
		}

		//如果已经有过套餐合同关联的零售项目，需要确保新的项目也关联同样的合同号
		//这里查询合同已经关联的项目来判断是否已经有过套餐关联的项目
		Map<Byte, ContractBaseDTO> contractTypeMap = contractBaseDTOList.stream().collect(Collectors.toMap(ContractBaseDTO::getType, Function.identity(), (key1, key2) -> key2));
		if (contractTypeMap.containsKey(ContractTypeEnum.PACKAGE_FORMAL.getCode())) {
			ContractBaseDTO packageFormalContract = contractTypeMap.get(ContractTypeEnum.PACKAGE_FORMAL.getCode());
			List<ProjectInfo> existContractRelateProjectList = projectInfoService.getRetailProjectByContractCode(contractTypeMap.get(ContractTypeEnum.PACKAGE_FORMAL.getCode()).getContractCode());
			if (!CollectionUtils.isEmpty(existContractRelateProjectList)) {
				LOGGER.info("getRetailRelateOrderInfo--返回报价单关联正式套餐合同合同{}", JSONObject.toJSONString(packageFormalContract));
				return packageFormalContract;
			}
		}

		contractBaseDTOList = contractBaseDTOList.stream().filter(contractBaseDTO -> ContractTypeEnum.PERSONAL.getCode().equals(contractBaseDTO.getType())).collect(Collectors.toList());
		LOGGER.info("getRetailRelateOrderInfo--销售合同列表,contractBaseDTOList:{}", JSONObject.toJSONString(contractBaseDTOList));

		Optional<ContractBaseDTO> billSameCompanyContract = contractBaseDTOList.stream().filter(contractBaseDTO -> !CollectionUtils.isEmpty(contractBaseDTO.getBillCodeList()) && contractBaseDTO.getBillCodeList().contains(billDTO.getBillCode())).findFirst();
		if (billSameCompanyContract.isPresent()) {
			LOGGER.info("getRetailRelateOrderInfo--返回报价单签署的销售合同{}", JSONObject.toJSONString(billSameCompanyContract.get()));
			return billSameCompanyContract.get();
		}

		Optional<ContractBaseDTO> billRelateSameContract = contractBaseDTOList.stream().filter(contractBaseDTO -> orderSubmitBo.getOrganizationCodeList().contains(contractBaseDTO.getCompanyCode())).findFirst();
		if (billRelateSameContract.isPresent()) {
			LOGGER.info("getRetailRelateOrderInfo--返回报价单关联的同主体销售合同{}", JSONObject.toJSONString(billRelateSameContract.get()));
			return billRelateSameContract.get();
		}
		if (!CollectionUtils.isEmpty(contractBaseDTOList)) {
			LOGGER.info("getRetailRelateOrderInfo--返回第一份已签署的主体销售合同，兼容线上逻辑{}", JSONObject.toJSONString(contractBaseDTOList.get(0)));
			return contractBaseDTOList.get(0);
		}
		return null;

	}

}

public ContractBaseDTO getRetailRelateOrderInfo(SubmitQuotationOrderBo orderSubmitBo) {
	BudgetBillDTO.BillDTO billDTO = orderSubmitBo.getBillDTO();

	//正签场景校验跟报价单签约状态一致，变更场景不校验报价单状态（变更报价单流转到已完成/签约的时机会后置到变更单完成，目前变更确认下单是客户确认完成，报价单还没签约）
	if (orderSubmitBo.getIsSignQuote() && !GeneralBillStatusEnum.SIGNED.getCode().equals(billDTO.getStatus())) {
		LOGGER.warn("getRetailRelateOrderInfo--正签场景,报价单状态还未签约,无需查询合同信息");
		return null;
	} else if (!orderSubmitBo.getIsSignQuote() && !Objects.isNull(orderSubmitBo.getChangeCreateScene()) && OrderCreateSceneEnum.CHANGE_QUOTE_SUBMIT.getCode().equals(orderSubmitBo.getChangeCreateScene())) {
		LOGGER.warn("getRetailRelateOrderInfo--变更场景,变更报价单提交,还未完成确认,无需查询合同信息");
		return null;
	}

	BusinessTypeEnum businessTypeEnum = BusinessTypeEnum.getEnumByDecorateType(CommissionDecorateTypeEnum.getEnumByCode(orderSubmitBo.getDecorationDecorateType()));
	if (Objects.isNull(businessTypeEnum)) {
		LOGGER.error("getRetailRelateOrderInfo--未找到对应的业务类型,decorateType:{}", orderSubmitBo.getDecorationDecorateType());
		return null;
	}
	// TODO: 2025/4/16 业务类型有问题（整装、纯零售传1，团装传3）
	List<ContractBaseDTO> contractBaseDTOList = commonContractService.getBaseContractInfo(businessTypeEnum.getCode(), billDTO.getProjectOrderId(), (byte) -1);

	//找到签约完成的合同
	contractBaseDTOList = contractBaseDTOList.stream().filter(contractBaseDTO -> ContractStatusEnum.FINISH.getCode().equals(contractBaseDTO.getStatus()) ||
		ContractStatusEnum.USER_CONFIRMED.getCode().equals(contractBaseDTO.getStatus())).collect(Collectors.toList());
	//找到其中的销售合同和套餐合同
	contractBaseDTOList = contractBaseDTOList.stream().filter(contractBaseDTO -> ContractTypeEnum.PERSONAL.getCode().equals(contractBaseDTO.getType()) || ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractBaseDTO.getType())).collect(Collectors.toList());

	if (CollectionUtils.isEmpty(contractBaseDTOList)) {
		LOGGER.info("getRetailRelateOrderInfo--合同列表为空,billCode:{},projectOrderId:{}", billDTO.getBillCode(), billDTO.getProjectOrderId());
		return null;
	}

	//如果已经有过套餐合同关联的零售项目，需要确保新的项目也关联同样的合同号
	//这里查询合同已经关联的项目来判断是否已经有过套餐关联的项目
	Map<Byte, ContractBaseDTO> contractTypeMap = contractBaseDTOList.stream().collect(Collectors.toMap(ContractBaseDTO::getType, Function.identity(), (key1, key2) -> key2));
	if (contractTypeMap.containsKey(ContractTypeEnum.PACKAGE_FORMAL.getCode())) {
		ContractBaseDTO packageFormalContract = contractTypeMap.get(ContractTypeEnum.PACKAGE_FORMAL.getCode());
		List<ProjectInfo> existContractRelateProjectList = projectInfoService.getRetailProjectByContractCode(contractTypeMap.get(ContractTypeEnum.PACKAGE_FORMAL.getCode()).getContractCode());
		if (!CollectionUtils.isEmpty(existContractRelateProjectList)) {
			LOGGER.info("getRetailRelateOrderInfo--返回报价单关联正式套餐合同合同{}", JSONObject.toJSONString(packageFormalContract));
			return packageFormalContract;
		}
	}

	contractBaseDTOList = contractBaseDTOList.stream().filter(contractBaseDTO -> ContractTypeEnum.PERSONAL.getCode().equals(contractBaseDTO.getType())).collect(Collectors.toList());
	LOGGER.info("getRetailRelateOrderInfo--销售合同列表,contractBaseDTOList:{}", JSONObject.toJSONString(contractBaseDTOList));

	Optional<ContractBaseDTO> billSameCompanyContract = contractBaseDTOList.stream().filter(contractBaseDTO -> !CollectionUtils.isEmpty(contractBaseDTO.getBillCodeList()) && contractBaseDTO.getBillCodeList().contains(billDTO.getBillCode())).findFirst();
	if (billSameCompanyContract.isPresent()) {
		LOGGER.info("getRetailRelateOrderInfo--返回报价单签署的销售合同{}", JSONObject.toJSONString(billSameCompanyContract.get()));
		return billSameCompanyContract.get();
	}

	Optional<ContractBaseDTO> billRelateSameContract = contractBaseDTOList.stream().filter(contractBaseDTO -> orderSubmitBo.getOrganizationCodeList().contains(contractBaseDTO.getCompanyCode())).findFirst();
	if (billRelateSameContract.isPresent()) {
		LOGGER.info("getRetailRelateOrderInfo--返回报价单关联的同主体销售合同{}", JSONObject.toJSONString(billRelateSameContract.get()));
		return billRelateSameContract.get();
	}
	if (!CollectionUtils.isEmpty(contractBaseDTOList)) {
		LOGGER.info("getRetailRelateOrderInfo--返回第一份已签署的主体销售合同，兼容线上逻辑{}", JSONObject.toJSONString(contractBaseDTOList.get(0)));
		return contractBaseDTOList.get(0);
	}
	return null;

}

SmsService.java::SmsService.source_code:
@Service
@Slf4j
public class SmsService {

	@Resource
	ContractService contractService;

	@Resource
	ContractSmsFlowMapper contractSmsFlowMapper;

	@Resource
	ContractApolloConfig contractApolloConfig;

	@Resource
	RedisTemplate<String, String> redisTemplate;

	@Resource
	ContractUserService contractUserService;

	@Resource
	ContractBusinessService contractBusinessService;

	@Resource
	SmsAPI smsAPI;
	@Resource
	CipherService cipherService;
	/**
	 * @desc 发送短信验证码
	 * @param smsServiceSendReq
	 * @return
	 */
	public Boolean sendSmsCode(SmsServiceSendReq smsServiceSendReq) {

		Contract contractInfo = contractService.getByContractCode(smsServiceSendReq.getContractCode());
		if (Objects.isNull(contractInfo)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PERMISSION_DENIED,"该合同编号不存在");
		}

		//待业主确认状态才可发送
		if (!contractInfo.getStatus().equals(ContractStatusEnum.PENDING_USER_CONFIRM.getCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PERMISSION_DENIED,"只有待业主确认状态可发送短信");
		}

		ContractUser contractUser = contractUserService.getSignerByContractCode(contractInfo.getContractCode());
		if (Objects.isNull(contractUser) || contractUser.getPhone().isEmpty()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人联系方式-[phone]");
		}
		// 加解密
		String contractUserPhone = cipherService.decrypt(contractUser.getPhone());
		Boolean isLoginSignSelf = contractBusinessService.isLoginSignSelf(smsServiceSendReq.getUserId(), contractUserPhone);
		if (!isLoginSignSelf) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前登入人和签约人不一致，不允许发送短信");
		}
		// 加解密
		return sendPhoneSmsCode(contractUserPhone, smsServiceSendReq.getContractCode());
	}

	public Boolean sendPhoneSmsCode(String phone, String smsFlowId){
		String smsCodeTemplateNo = contractApolloConfig.getSmsTemplateNo();
		if (StringUtil.isEmpty(smsCodeTemplateNo)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS,"短信模板不存在");
		}

		return sendVcode(phone, smsFlowId, smsCodeTemplateNo);
	}

	public Boolean sendVcode(String phone,String smsFlowId,String templateNo){
		//生成验证码
		String vCode = generateSmsCode();
		//保存验证码到redis中
		saveVcodeToRedis(vCode, phone);

		SmsParams smsParamsContent = getSmsContentParams(phone, templateNo, vCode);

		return sendAndSave(ContractSmsFlow.builder()
			.smsStatus(ContractSmsFlowEnum.SMS_SEND.getCode().byteValue())
			.phone(phone)
			.contractCode(smsFlowId)
			.content(JSON.toJSONString(smsParamsContent))
			.build(), smsParamsContent);
	}

	private SmsParams getSmsContentParams(String phone,String template, String vCode){
		SmsParams smsParams = new SmsParams();
		smsParams.setBatch_id(IdGenerator.getContractGeneratorId());
		smsParams.setTemplate(template);
		smsParams.setTargets(Collections.singletonList(SmsParams.PhoneItemDto.builder()
			.phone(phone)
			.nationcode("86")
			.build()));
		Long smsExpireMinute = contractApolloConfig.getSmsExpireMinute();
		smsParams.setVar(ImmutableMap.<String,String>builder().put("vcode", vCode).put("minute", smsExpireMinute + "").build());

		return smsParams;
	}

	private Boolean sendAndSave(ContractSmsFlow contractSmsFlow, SmsParams smsParamsContent){
		send(contractSmsFlow, smsParamsContent);
		// 加解密
		save(contractSmsFlow);
//		contractSmsFlowMapper.insertSelective(contractSmsFlow);
		return true;
	}

	private void save(ContractSmsFlow contractSmsFlow) {
		if(StringUtils.isNotBlank(contractSmsFlow.getPhone())){
			contractSmsFlow.setPhone(cipherService.encrypt(contractSmsFlow.getPhone()));

		}
		if(StringUtils.isNotBlank(contractSmsFlow.getContent())){
			SmsParams smsParamsContent = JSON.parseObject(contractSmsFlow.getContent(), SmsParams.class);
			if(CollectionUtils.isNotEmpty(smsParamsContent.getTargets())){
				smsParamsContent.getTargets().forEach(item -> {
					if(StringUtils.isNotBlank(item.getPhone())){
						item.setPhone(cipherService.encrypt(item.getPhone()));
					}
				});
			}
			contractSmsFlow.setContent(JSON.toJSONString(smsParamsContent));

		}
		contractSmsFlowMapper.insertSelective(contractSmsFlow);
	}

	public void send(ContractSmsFlow contractSmsFlow, SmsParams smsParamsContent){
		if (smsParamsContent.getTemplate().isEmpty()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "短信内容不存在");
		}
		String smsMsgGroup = contractApolloConfig.getSmsMsgGroup();
		String smsMsgAuth = contractApolloConfig.getSmsMsgAuth();

		SmsResultDto sendSmsResult = null;
		try {
			LOGGER.info("短信发送内容："+ JSON.toJSONString(smsParamsContent));
			sendSmsResult = smsAPI.sendSms(smsMsgGroup,smsMsgAuth, smsParamsContent);
			LOGGER.info("短信返回结果："+ JSON.toJSONString(sendSmsResult));
		} catch (Exception e) {
			LOGGER.error("短信发送异常：",e);
		}

		if(sendSmsResult.getErrno().equals(0)){
			contractSmsFlow.setSmsStatus(ContractSmsFlowEnum.SMS_SEND_SUCCESS.getCode().byteValue());
		}else{
			contractSmsFlow.setSmsStatus(ContractSmsFlowEnum.SMS_SEND_FAIL.getCode().byteValue());
		}
	}

	private void saveVcodeToRedis(String vCode, String phone){
		String key = Constant.VCODE_PREFIX + phone;
		Long smsExpireMinute = contractApolloConfig.getSmsExpireMinute();
		Long expire = smsExpireMinute * 60;

		redisTemplate.opsForValue().set(key, vCode, expire, TimeUnit.SECONDS);
	}

	/**
	 * @desc 生成短信验证码
	 * @return
	 */
	private String generateSmsCode() {
		// 发送新生成的值
		return String.valueOf(new Random().nextInt(899999) + 100000);
	}
}

