@Service
@Slf4j
public class SupplementBpmService {

	@Resource
	private CeresRpc ceresRpc;

	@Resource
	private ProjectConfigService projectConfigService;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Resource
	private MemberRpc memberRpc;

	@Resource
	private BpmService bpmService;

	@Resource
	private BaseAuditChannel baseAuditChannel;

	@Resource
	private ContractService contractService;

	@Resource
	private ContractFieldService contractFieldService;

	@Resource
	private ContractNodeServiceImpl contractNodeService;

	@Resource
	private S3Service s3Service;

	@Resource
	private ContractBusinessService contractBusinessService;

	@Resource
	private CommonBusinessService commonBusinessService;

	@Resource
	private CommonContractService commonContractService;

	@Resource
	private ContractAttachService contractAttachService;

	private static Map<Integer, String> roleMap = new HashMap<>();
	private static List<Integer> fixedNodeList = new ArrayList<>();


	static {
//		roleMap.put(0, "【店总】");
//		roleMap.put(1, "【财务】");
		fixedNodeList = new ArrayList<>(roleMap.keySet());
	}

	/**
	 * 补充协议发起 bpm 审批
	 */
	public ProcessInstanceDetailResponse applySupplementBpm(Contract contract) {
		// 1、构建 bpm 审批人信息
		ApproverInfo approverInfo = buildApproverInfo(contract.getProjectOrderId(), StringUtils.isEmpty(contract.getModifyUserId()) ? contract.getCreateUserId() : contract.getModifyUserId(), contract.getType());
		LOGGER.info("补充协议 bpm 审批人信息，contractCode={}, approverInfo={}", contract.getContractCode(), JSONObject.toJSONString(approverInfo));

		// 2、校验审批人信息（必填校验、在职校验）
		ApproverInfoCheckDTO checkDTO = check(approverInfo);
		if (!checkDTO.isConfig()) {
			String msg = checkDTO.getTips() + "，请联系配置人员操作";
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), msg, msg, Level.WARN);
		}

		// 3、构建 bpm 审批发起请求参数
		BpmRequestDTO<Object, Object> requestDTO = buildBpmApplyRequest(contract, approverInfo);

		// 与 bpm 交互，打印请求参数
		LOGGER.info("补充协议 bpm 审批发起请求参数，contractCode={}, requestDTO={}", contract.getContractCode(), JSONObject.toJSONString(requestDTO));
		// 4、发起 bpm 审批流
		return bpmService.applyBpm(requestDTO);
	}

	/**
	 * 补充协议审批人获取规则
	 * （1）店总（必填，从服务者中心取）
	 * （2）固定人（必填，法务）
	 * （3）固定人
	 * （4）固定人
	 * （5）固定人
	 * （6）固定人
	 * （7）固定人
	 * （8）固定人
	 *  @param createUserId 提单人 userId，取值有 2 种情况：
	 *                      1、发起签约前校验，userId 从 Header 里取
	 *                      2、发起签约后进行 bpm 审批，此时从 contract 表的 modifyUserId/createUserId 里取
	 */
	public ApproverInfo buildApproverInfo(String projectOrderId, String createUserId, Byte contractType) {
		ProjectConfigTypeEnum projectConfigTypeEnum;
		// 仅支持补充协议、和解协议的审批人构建
		if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractType)) {
			projectConfigTypeEnum = ProjectConfigTypeEnum.SUPPLEMENT_APPLY_BPM;
		} else if (ContractTypeEnum.SETTLEMENT.getCode().equals(contractType)) {
			projectConfigTypeEnum = ProjectConfigTypeEnum.SETTLEMENT_APPLY_BPM;
		} else {
			throw new NrsBusinessException("不支持的合同类型，projectOrderId=" + projectOrderId + ", contractType=" + contractType);
		}
		// 备注：不用要用这里的分公司。（如果未正签，分公司是从客源取的，而正签是从报价取的，可能不一致）
		ConfigCoreDTO configCore = commonBusinessService.getCompanyCodeConfigCore(projectOrderId);
		Integer gbcode = configCore.getGbcode();
		Byte businessType = configCore.getBusinessType();
		ProjectConfig projectConfig = projectConfigService.selectConfigWithoutCompanyCode(projectConfigTypeEnum.getConfigType(), gbcode, businessType);
		if (ObjectUtil.isEmpty(projectConfig)) {
			LOGGER.error("补充协议 bpm 审批人未配置，gbCode={}, businessType={}", gbcode, businessType);
			String errorMeg = projectConfigTypeEnum.getDesc() + "bpm审批人未配置，请联系配置人员操作";
			throw new NrsBusinessException(errorMeg, Level.WARN);
		}
		SupplementApplyBpmConfigData supplementApplyBpmConfigData = (SupplementApplyBpmConfigData) JSON.parseObject(projectConfig.getConfigData(), projectConfigTypeEnum.getRequestClazz());
		if(CollectionUtil.isEmpty(supplementApplyBpmConfigData.queryAuditUserIdList())){
			String errorMeg = projectConfigTypeEnum.getDesc() + "审批人未配置，请联系配置人员操作";
			throw new NrsBusinessException(errorMeg, Level.WARN);
		}
		List<String> workTypeList = Arrays.asList(WorkTypeEnum.GROUP_LEADER.getCode(), WorkTypeEnum.SHOP_LEADER.getCode());
		SuperiorWorkTypeQueryRequest request = new SuperiorWorkTypeQueryRequest();
		request.setUcId(Long.valueOf(createUserId));
		request.setStatus((short) 1);  // 0离岗，1在岗，不传查全部
		request.setTargetWorkTypeList(workTypeList);
		// 从服务者中心获取经营部经理、店总
		List<PersonPositionSimpleDTO> personPositionSimpleDTOS = ceresRpc.querySuperiorByWorkType(request);
		// 一级审批人为经营部经理
		String groupLeader = personPositionSimpleDTOS.stream()
			.filter(person -> WorkTypeEnum.GROUP_LEADER.getCode().equals(person.getWorkTypeCode()))
			.findFirst().map(PersonPositionSimpleDTO::getUserCode).orElse("");
		// 二级审批人为店总
		String shopLeader = personPositionSimpleDTOS.stream()
			.filter(person -> WorkTypeEnum.SHOP_LEADER.getCode().equals(person.getWorkTypeCode()))
			.findFirst().map(PersonPositionSimpleDTO::getUserCode).orElse("");

		return ApproverInfo.builder()
			// 一级审批人经营部经理
			.fixedNodes1(groupLeader)
			// 二级审批人为店总
			.fixedNodes2(shopLeader)
			.fixedNodes3(supplementApplyBpmConfigData.getFixedNodes3())
			.fixedNodes4(supplementApplyBpmConfigData.getFixedNodes4())
			.fixedNodes5(supplementApplyBpmConfigData.getFixedNodes5())
			.fixedNodes6(supplementApplyBpmConfigData.getFixedNodes6())
			.fixedNodes7(supplementApplyBpmConfigData.getFixedNodes7())
			.fixedNodes8(supplementApplyBpmConfigData.getFixedNodes8())
			.build();
	}

	/**
	 * 审批人信息校验必填校验
	 */
	public ApproverInfoCheckDTO check(ApproverInfo approverInfo) {
		boolean checkedUserState = baseAuditChannel.checkUserState(approverInfo);
		return ApproverInfoCheckDTO.builder()
			.isConfig(checkedUserState)
			.tips(baseAuditChannel.getApproverInfoTips(approverInfo, fixedNodeList, roleMap))
			.build();
	}

	/**
	 * 构建 bpm 审批发起请求参数
	 */
	private BpmRequestDTO<Object, Object> buildBpmApplyRequest(Contract contract, ApproverInfo approverInfo) {
		// 构建 bpm 表单项内容
		JSONObject record = buildRecordData(contract);

		BpmProcessVars vars = BpmProcessVars.builder()
			.fixedNodes1(approverInfo.getFixedNodes1())
			.fixedNodes2(approverInfo.getFixedNodes2())
			.fixedNodes3(approverInfo.getFixedNodes3())
			.fixedNodes4(approverInfo.getFixedNodes4())
			.fixedNodes5(approverInfo.getFixedNodes5())
			.fixedNodes6(approverInfo.getFixedNodes6())
			.fixedNodes7(approverInfo.getFixedNodes7())
			.fixedNodes8(approverInfo.getFixedNodes8())
			.build();
		String createUserId = org.apache.commons.lang.StringUtils.isEmpty(contract.getModifyUserId()) ? contract.getCreateUserId() : contract.getModifyUserId();
		String applyUserCode = memberRpc.getUserSystemCode(createUserId);

		// 构建 bpm 请求参数
		BpmBaseConfigDTO bpmBaseConfigDTO = buildSupplementBpmBaseConfig();
		return BpmRequestDTO.builder()
			.processDefId(bpmBaseConfigDTO.getProcessDefId())
			.userSystemCode(applyUserCode)
			.boName(bpmBaseConfigDTO.getBoName())
			.processBusinessKey(IdGenerator.getContractBpmGeneratorId())
			.vars(vars)
			.recordData(record)
			.build();
	}

	private JSONObject buildRecordData(Contract supplementContract) {
		JSONObject record = new JSONObject();

		String projectOrderId = supplementContract.getProjectOrderId();
		// 单独发起的补充协议，正签合同编号取最新已签署的正签
		Contract latestSignedFormal = contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode())
				.stream()
				// 这里直接获取最新的正签合同（合并发起时，正签还未签署会导致拿不到正签合同编号）
//				.filter(item -> Objects.equals(ContractStatusEnum.FINISH.getCode(), item.getStatus()))
				.findFirst()
				.orElse(new Contract());

		// 正签的合同字段
		Map<String, String> formalFieldMap = contractFieldService.getFieldMap(latestSignedFormal.getContractCode());
		// 正签合同发起时间
		String applyDate = contractNodeService.getLatestFireTimeByNodeType(latestSignedFormal.getContractCode(), NodeTypeEnum.SUBMIT.getCode());
		// 补充协议发起时间
		String supplementApplyDate = contractNodeService.getLatestFireTimeByNodeType(supplementContract.getContractCode(), NodeTypeEnum.SUBMIT.getCode());
		List<String> contractLink = new ArrayList<>();
		// 如果是线上签约，则根据获取对应 pdf 链接
		if (SignChannelTypeEnum.ONLINE.getCode().equals(supplementContract.getSignChannelType())) {
			contractLink.add(s3Service.getMediaUrl(contractBusinessService.getContractLatestPdfKey(supplementContract), 15 * 24 * 60 * 60));
		} else {
			// 如果是线下补录，则从附件获取线下合同
			List<ContractAttach> contractAttachList = contractAttachService.getListByContractCode(supplementContract.getContractCode());
			contractLink.addAll(contractAttachList.stream()
				.filter(contractAttach -> AttachTypeEnum.OFFLINE_CONTRACT.getCode().equals(contractAttach.getAttachType()))
				.map(ContractAttach::getUrl)
				.collect(Collectors.toList()));
		}

		String partAName = "";
		Byte contractObjectType = contractFieldService.getContractObjectType(supplementContract.getContractCode());
		if (ContractObjectTypeEnum.PERSON.getCode().equals(contractObjectType)) {
			// 个人合同，取 ownerName 字段
			partAName = formalFieldMap.get(ContractSignInfoReq.Fields.ownerName);
		} else if (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
			// 公对公合同，取 legalName 字段
			partAName = formalFieldMap.get(ContractSignInfoReq.Fields.legalName);
		}
		// 甲方姓名
		record.put("ownerName", partAName);
		// 乙方名称（补充协议的甲乙方与正签一致，直接从补充协议获取 companyCode 即可）
		record.put("companyName", commonContractService.getCompanyInfo(supplementContract.getCompanyCode()).getCompanyName());
		// 正签合同发起时间
		record.put("applyDate", applyDate);
		// 正签合同编号
		record.put("contractNo", latestSignedFormal.getContractNo());
		// 施工地址
		record.put("projectContractAddress", getCertificateAddress(formalFieldMap));
		// 补充协议发起时间
		record.put("supplementApplyDate", supplementApplyDate);
		// 补充协议链接，需要转为数组形式，在 bpm 中通过 js 脚本处理成超链接
		record.put("contractLink", contractLink);


		return record;
	}

	private BpmBaseConfigDTO buildSupplementBpmBaseConfig() {
		return contractApolloConfig.getSupplementBpmBaseConfigDTO();
	}
}

public ProcessInstanceDetailResponse applySupplementBpm(Contract contract) {
	// 1、构建 bpm 审批人信息
	ApproverInfo approverInfo = buildApproverInfo(contract.getProjectOrderId(), StringUtils.isEmpty(contract.getModifyUserId()) ? contract.getCreateUserId() : contract.getModifyUserId(), contract.getType());
	LOGGER.info("补充协议 bpm 审批人信息，contractCode={}, approverInfo={}", contract.getContractCode(), JSONObject.toJSONString(approverInfo));

	// 2、校验审批人信息（必填校验、在职校验）
	ApproverInfoCheckDTO checkDTO = check(approverInfo);
	if (!checkDTO.isConfig()) {
		String msg = checkDTO.getTips() + "，请联系配置人员操作";
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), msg, msg, Level.WARN);
	}

	// 3、构建 bpm 审批发起请求参数
	BpmRequestDTO<Object, Object> requestDTO = buildBpmApplyRequest(contract, approverInfo);

	// 与 bpm 交互，打印请求参数
	LOGGER.info("补充协议 bpm 审批发起请求参数，contractCode={}, requestDTO={}", contract.getContractCode(), JSONObject.toJSONString(requestDTO));
	// 4、发起 bpm 审批流
	return bpmService.applyBpm(requestDTO);
}

public ApproverInfo buildApproverInfo(String projectOrderId, String createUserId, Byte contractType) {
	ProjectConfigTypeEnum projectConfigTypeEnum;
	// 仅支持补充协议、和解协议的审批人构建
	if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractType)) {
		projectConfigTypeEnum = ProjectConfigTypeEnum.SUPPLEMENT_APPLY_BPM;
	} else if (ContractTypeEnum.SETTLEMENT.getCode().equals(contractType)) {
		projectConfigTypeEnum = ProjectConfigTypeEnum.SETTLEMENT_APPLY_BPM;
	} else {
		throw new NrsBusinessException("不支持的合同类型，projectOrderId=" + projectOrderId + ", contractType=" + contractType);
	}
	// 备注：不用要用这里的分公司。（如果未正签，分公司是从客源取的，而正签是从报价取的，可能不一致）
	ConfigCoreDTO configCore = commonBusinessService.getCompanyCodeConfigCore(projectOrderId);
