	Byte businessType = configCore.getBusinessType();
	ProjectConfig projectConfig = projectConfigService.selectConfigWithoutCompanyCode(projectConfigTypeEnum.getConfigType(), gbcode, businessType);
	if (ObjectUtil.isEmpty(projectConfig)) {
		LOGGER.error("补充协议 bpm 审批人未配置，gbCode={}, businessType={}", gbcode, businessType);
		String errorMeg = projectConfigTypeEnum.getDesc() + "bpm审批人未配置，请联系配置人员操作";
