	}
	SupplementApplyBpmConfigData supplementApplyBpmConfigData = (SupplementApplyBpmConfigData) JSON.parseObject(projectConfig.getConfigData(), projectConfigTypeEnum.getRequestClazz());
	if(CollectionUtil.isEmpty(supplementApplyBpmConfigData.queryAuditUserIdList())){
		String errorMeg = projectConfigTypeEnum.getDesc() + "审批人未配置，请联系配置人员操作";
		throw new NrsBusinessException(errorMeg, Level.WARN);
	}
	List<String> workTypeList = Arrays.asList(WorkTypeEnum.GROUP_LEADER.getCode(), WorkTypeEnum.SHOP_LEADER.getCode());
	SuperiorWorkTypeQueryRequest request = new SuperiorWorkTypeQueryRequest();
	request.setUcId(Long.valueOf(createUserId));
	request.setStatus((short) 1);  // 0离岗，1在岗，不传查全部
	request.setTargetWorkTypeList(workTypeList);
	// 从服务者中心获取经营部经理、店总
	List<PersonPositionSimpleDTO> personPositionSimpleDTOS = ceresRpc.querySuperiorByWorkType(request);
	// 一级审批人为经营部经理
	String groupLeader = personPositionSimpleDTOS.stream()
		.filter(person -> WorkTypeEnum.GROUP_LEADER.getCode().equals(person.getWorkTypeCode()))
		.findFirst().map(PersonPositionSimpleDTO::getUserCode).orElse("");
	// 二级审批人为店总
	String shopLeader = personPositionSimpleDTOS.stream()
		.filter(person -> WorkTypeEnum.SHOP_LEADER.getCode().equals(person.getWorkTypeCode()))
		.findFirst().map(PersonPositionSimpleDTO::getUserCode).orElse("");

	return ApproverInfo.builder()
		// 一级审批人经营部经理
		.fixedNodes1(groupLeader)
		// 二级审批人为店总
		.fixedNodes2(shopLeader)
		.fixedNodes3(supplementApplyBpmConfigData.getFixedNodes3())
		.fixedNodes4(supplementApplyBpmConfigData.getFixedNodes4())
		.fixedNodes5(supplementApplyBpmConfigData.getFixedNodes5())
		.fixedNodes6(supplementApplyBpmConfigData.getFixedNodes6())
		.fixedNodes7(supplementApplyBpmConfigData.getFixedNodes7())
		.fixedNodes8(supplementApplyBpmConfigData.getFixedNodes8())
		.build();
}

