        LOGGER.info("开始处理报价单拆分协同单消息，消息内容：{}", JSON.toJSONString(payloadData));
        if (ObjectUtil.isEmpty(payloadData)) {
            return;
        }
        BudgetBillDTO.BillSplitDTO billSplitDTO = payloadData.getPayloadData();
        String projectOrderId = billSplitDTO.getProjectOrderId();
//		homeOrderOperationService.recordSplitQuoteNode(projectOrderId, billSplitDTO.getOriginalBillCode(), billSplitDTO.getBillList().stream().map(BudgetBillDTO.Simple::getBillCode).collect(Collectors.toList()));


		String originalBillCode = billSplitDTO.getOriginalBillCode();
		List<String> billCodeList = billSplitDTO.getBillList().stream().map(BudgetBillDTO.Simple::getBillCode).collect(Collectors.toList());
		budgetBillSplitHandlerV2.dealBudgetBillSplit(originalBillCode, billCodeList, projectOrderId);
	}



}

