public void dealBudgetBillSplit(String originalBillCode,List<String> cooperBillCodes,String projectOrderId){
	if (CollectionUtil.isEmpty(cooperBillCodes)) {
		LOGGER.info("拆分协同报价单为空");
		return;
	}

	LOGGER.info("基础报价单拆分协同报价单, originalBillCode: {}, billCodeList: {}", originalBillCode, cooperBillCodes);
	// 已发起的销售合同：主体 -> 销售合同
	Map<String, Contract> personalContractByCompany = buildPersonalContractsByCompany(projectOrderId);

	// 获取已发起销售合同的主体对应的报价单号
	Map<String, List<String>> billCodesByCompany = buildPersonalDataByCompany(projectOrderId, cooperBillCodes, personalContractByCompany);

	// 针对已发起销售合同的主体，绑定对应的协同报价单的解绑与绑定
	billCodesByCompany.forEach((companyCode, billCodes) -> {
		// 获取主体对应的合同号
		Contract personalContract = personalContractByCompany.get(companyCode);
		// 将合同与该主体对应的协同报价单号绑定
		quotationRelationCommonService.bindCodeRelation(personalContract.getContractCode(), companyCode, billCodes, BindTypeEnum.BILL_CODE.getCode());
		// 记录换绑日志：基础报价单绑定协同报价单
		contractBindLogService.recordBindChangeLog(
			personalContract.getContractCode(),
			"基础套餐协同报价单拆分-绑定协同报价单",
			originalBillCode,
			billCodes
		);
		// 尝试将协同报价单换绑至 S 单
		quotationRelationCommonService.convertCooperBillToSubOrderByContract(personalContract);
	});
	LOGGER.info("基础套餐协同报价单拆分处理器，处理完成，projectOrderId={}", projectOrderId);
}

private Map<String, List<String>> buildPersonalDataByCompany(String projectOrderId, List<String> billCodeList, Map<String, Contract> personalContractsByCompany) {
	PersonalContractDataParam param = PersonalContractDataParam.builder()
		.projectOrderId(projectOrderId)
		.billCodeList(billCodeList)
		.build();
	ContractSourceDataBO contractSourceDataBO = QueryHelper.unwrap(p -> homeOrderDataConversionService.contractPersonalDataV2(p), param, "contractPersonalDataV2");
	if (contractSourceDataBO == null || CollectionUtil.isEmpty(contractSourceDataBO.getPersonalContractDataList())) {
		LOGGER.info("订单{}，个性化报价数据查询为空", projectOrderId);
		return Collections.emptyMap();
	}
	// 个性化报价数据按照公司主体分组
	Map<String, List<String>> res = new HashMap<>();
	for (ContractSourceDataBO.PersonalContractData personalContractData : contractSourceDataBO.getPersonalContractDataList()) {
		String companyCode = personalContractData.getOrganizationCode();
		String billCode = personalContractData.getBillCode();
		// 过滤掉未发起销售合同的主体
		if (!personalContractsByCompany.containsKey(companyCode)) {
			continue;
		}
		res.computeIfAbsent(companyCode, k -> new ArrayList<>()).add(billCode);
	}
	return res;
}

private Map<String, Contract> buildPersonalContractsByCompany(String projectOrderId) {
	// 1. 获取正签合同
	Contract formalContract = contractService.getLatestContract(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode());
	if (ObjectUtil.isEmpty(formalContract)) {
		LOGGER.info("项目{}没有正签合同", projectOrderId);
		return Collections.emptyMap();
	}

	// 2. 获取关联的销售合同
	List<Contract> personalContracts = getRelatedPersonalContracts(formalContract);
	if (CollectionUtil.isEmpty(personalContracts)) {
		LOGGER.info("订单{}不存在已发起的销售合同", projectOrderId);
		return Collections.emptyMap();
	}

	return personalContracts.stream().collect(Collectors.toMap(
			Contract::getCompanyCode,
			contract -> contract
	));
}

private List<Contract> getRelatedPersonalContracts(Contract formalContract) {
	List<ContractRelation> relations = contractRelationService.getRelationList(formalContract.getContractCode());
	if (ObjectUtil.isEmpty(relations)) {
		LOGGER.info("合同{}没有关联合同", formalContract.getContractCode());
		return new ArrayList<>();
	}

	List<String> relatedContractCodes = relations.stream()
		.map(ContractRelation::getRelateContractCode)
		.collect(Collectors.toList());
	List<Contract> relatedContracts = contractService.getListByContractCodes(relatedContractCodes, Boolean.FALSE);
	if (ObjectUtil.isEmpty(relatedContracts)) {
		LOGGER.info("合同{}关联合同为空", formalContract.getContractCode());
		return new ArrayList<>();
	}

	List<Contract> validPersonalContracts = relatedContracts.stream()
		.filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))
		.filter(contract -> ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus()))
		.collect(Collectors.toList());

	if (CollectionUtil.isEmpty(validPersonalContracts)) {
		LOGGER.info("关联合同{}没有个性化合同", formalContract.getContractCode());
	}
	return validPersonalContracts;
}

