@LianjiaSchedule
@Slf4j
public class ChangePersonalContractFieldSchedule {

    @Resource
    private ChangeContractUnifyService changeContractUnifyService;

    @Resource
    private ContractService contractService;

    @Assignment(key = "syncChangePersonalContractField", cn = "补充历史个性化合同字段表")
    public AssignmentResult syncChangePersonalContractField(AssignmentContext context) throws InterruptedException {
        LOGGER.info("syncChangePersonalContractField开始");
        long startId = Long.parseLong(context.getParam().getOrDefault("startId", "1"));
        long endId = Long.parseLong(context.getParam().getOrDefault("endId", "1"));
        Integer gbcode = Integer.valueOf(context.getParam().getOrDefault("gbcode", "666666"));
        final int limit = 100;
        long startTime = System.nanoTime();
        while (startId <= endId) {
            PageInfo<Contract> contractPageInfo = contractService.selectPageByExample(Example.builder(Contract.class)
                    .andWhere(Sqls.custom().andGreaterThanOrEqualTo(BaseModel.Fields.id, startId)
                            .andLessThanOrEqualTo(BaseModel.Fields.id, endId)
                            .andEqualTo(Contract.Fields.gbCode, gbcode)
						    .andEqualTo(Contract.Fields.type, ContractTypeEnum.PERSONAL.getCode())
                            .andIn(Contract.Fields.status, ContractStatusEnum.inProgressStatusWithoutDraft)
                            .andIsNotNull(Contract.Fields.changeOrderId)
                            .andNotEqualTo(Contract.Fields.changeOrderId, "")
						    .andEqualTo(Contract.Fields.delStatus, CommonEnum.NO.getCode())
                    )
                    .build(), 1, limit);
            if (contractPageInfo == null || contractPageInfo.getList().isEmpty()) {
                break;
            }
            List<Contract> contractList = contractPageInfo.getList();
			LOGGER.info("补充历史个性化合同字段表, contractList.size:{}", contractList.size());
            for (Contract personalContract : contractList) {
                //获取上一份已完成（已签署、已确认）变更/B合同
                Contract lastContract = contractService.getChangePrevEffectContractByPid(personalContract.getProjectOrderId());
                if (ObjectUtil.isEmpty(lastContract)) {
					LOGGER.error("上一份已完成（已签署、已确认）变更/B合同不存在, contractId:{}", personalContract.getId());
                    continue;
                }
				try {
					changeContractUnifyService.savePersonalContractField(personalContract, lastContract);
				} catch (Exception e) {
					LOGGER.info("补充历史个性化合同字段表失败, contractId:{}", personalContract.getId());
				}
				TimeUnit.MILLISECONDS.sleep(50L);
                LOGGER.info("syncChangePersonalContractField, contractId:{}", personalContract.getId());
            }
            startId = contractList.get(contractList.size() - 1).getId() + 1L;
        }
        LOGGER.info("syncCollectionPlanToSubFundInfo结束");
        // 记录结束时间
        long endTime = System.nanoTime();
        // 计算并打印运行时间
        long duration = (endTime - startTime);  // 单位：纳秒
        LOGGER.info("运行时间（毫秒）：" + duration / 1000000);
        return new AssignmentResult(ResultMode.EXECUTE_SUCCESS);
    }
}

    @Assignment(key = "syncChangePersonalContractField", cn = "补充历史个性化合同字段表")
    public AssignmentResult syncChangePersonalContractField(AssignmentContext context) throws InterruptedException {
        LOGGER.info("syncChangePersonalContractField开始");
        long startId = Long.parseLong(context.getParam().getOrDefault("startId", "1"));
        long endId = Long.parseLong(context.getParam().getOrDefault("endId", "1"));
        Integer gbcode = Integer.valueOf(context.getParam().getOrDefault("gbcode", "666666"));
        final int limit = 100;
        long startTime = System.nanoTime();
        while (startId <= endId) {
            PageInfo<Contract> contractPageInfo = contractService.selectPageByExample(Example.builder(Contract.class)
                    .andWhere(Sqls.custom().andGreaterThanOrEqualTo(BaseModel.Fields.id, startId)
                            .andLessThanOrEqualTo(BaseModel.Fields.id, endId)
                            .andEqualTo(Contract.Fields.gbCode, gbcode)
						    .andEqualTo(Contract.Fields.type, ContractTypeEnum.PERSONAL.getCode())
                            .andIn(Contract.Fields.status, ContractStatusEnum.inProgressStatusWithoutDraft)
                            .andIsNotNull(Contract.Fields.changeOrderId)
                            .andNotEqualTo(Contract.Fields.changeOrderId, "")
						    .andEqualTo(Contract.Fields.delStatus, CommonEnum.NO.getCode())
                    )
                    .build(), 1, limit);
            if (contractPageInfo == null || contractPageInfo.getList().isEmpty()) {
                break;
            }
            List<Contract> contractList = contractPageInfo.getList();
			LOGGER.info("补充历史个性化合同字段表, contractList.size:{}", contractList.size());
            for (Contract personalContract : contractList) {
                //获取上一份已完成（已签署、已确认）变更/B合同
                Contract lastContract = contractService.getChangePrevEffectContractByPid(personalContract.getProjectOrderId());
                if (ObjectUtil.isEmpty(lastContract)) {
					LOGGER.error("上一份已完成（已签署、已确认）变更/B合同不存在, contractId:{}", personalContract.getId());
                    continue;
                }
				try {
					changeContractUnifyService.savePersonalContractField(personalContract, lastContract);
				} catch (Exception e) {
					LOGGER.info("补充历史个性化合同字段表失败, contractId:{}", personalContract.getId());
				}
				TimeUnit.MILLISECONDS.sleep(50L);
                LOGGER.info("syncChangePersonalContractField, contractId:{}", personalContract.getId());
            }
            startId = contractList.get(contractList.size() - 1).getId() + 1L;
        }
        LOGGER.info("syncCollectionPlanToSubFundInfo结束");
        // 记录结束时间
        long endTime = System.nanoTime();
        // 计算并打印运行时间
        long duration = (endTime - startTime);  // 单位：纳秒
        LOGGER.info("运行时间（毫秒）：" + duration / 1000000);
        return new AssignmentResult(ResultMode.EXECUTE_SUCCESS);
    }

