@LianjiaSchedule
@Slf4j
@Service
public class PrivacyAccessWarnSchedule {

    @Resource
    private SensitiveInformationAccessRecordService sensitiveInformationAccessRecordService;

    @Resource
    private PrivacyCommonService privacyCommonService;

    @Resource
    private ContractApolloConfig contractApolloConfig;

    @Assignment(key = "privacyAccessWarnSchedule", cn = "隐私数据访问预警脚本")
    public AssignmentResult privacyAccessWarnSchedule(AssignmentContext context) {
        LOGGER.info("privacyAccessWarnSchedule start");
        //阈值时间： time分钟
        int time = Integer.parseInt(context.getParam().getOrDefault("time", "100"));
        //阈值次数：count次
        Integer count = Integer.valueOf(context.getParam().getOrDefault("count", "10"));
        //时间范围： 当前时间-range*time分钟 ~ 当前时间
        int range = Integer.parseInt(context.getParam().getOrDefault("range", "2"));
        for (int i = 0; i < range; i++) {
            //获取当前时间
            long currentTime = System.currentTimeMillis();
            //起始和终止时间范围
            // 格式化日期为数据库接受的格式
            SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
            String startTime = dateFormat.format(new Date(currentTime - (long) (i + 1) * time * 60 * 1000));
            String endTime = dateFormat.format(new Date(currentTime - (long) i * time * 60 * 1000));
            //获取时间范围内的访问记录:时间范围： 当前时间-(range+1)*time分钟 ~ 当前时间-range*time分钟,ctime是访问时间，为Date类型
            List<SensitiveInformationAccessRecord> sensitiveInformationAccessRecords = sensitiveInformationAccessRecordService.selectWarnRecord(startTime, endTime);
            //基于操作人ucid统计访问次数
            Map<String, Integer> viewContractCccessCountMap = new HashMap<>();
            Map<String, Integer> copyPhoneCccessCountMap = new HashMap<>();
            Map<String, String> ucidNameMap = new HashMap<>();
            for (SensitiveInformationAccessRecord sensitiveInformationAccessRecord : sensitiveInformationAccessRecords) {
                //获取操作人ucid
                String ucid = sensitiveInformationAccessRecord.getOperatorUcid();
                String operatorName = sensitiveInformationAccessRecord.getOperatorName();
                ucidNameMap.put(ucid, operatorName);
                //统计访问次数
                if (PrivacyOperateTypeEnum.VIEW_CONTRACT_PDF.getCode().equals(sensitiveInformationAccessRecord.getOperationType())) {
                    viewContractCccessCountMap.put(ucid, viewContractCccessCountMap.getOrDefault(ucid, 0) + 1);
                } else if (PrivacyOperateTypeEnum.COPY_CUSTOMER_PHONE.getCode().equals(sensitiveInformationAccessRecord.getOperationType())) {
                    copyPhoneCccessCountMap.put(ucid, copyPhoneCccessCountMap.getOrDefault(ucid, 0) + 1);
                }
            }
            //获取合同预览访问次数超过阈值的操作人ucid
            for (Map.Entry<String, Integer> entry : viewContractCccessCountMap.entrySet()) {
                if (entry.getValue() > count) {
                    String ucid = entry.getKey();
                    String operatorName = ucidNameMap.get(ucid);
                    if (!contractApolloConfig.getWarnWhiteList().contains(ucid)) {
                        //企微预警
                        String warnContent = String.format("【高频预览合同】「%s%s」，近%s分钟预览合同数%s份", operatorName, ucid, time, entry.getValue());
                        privacyCommonService.overFrequencyWarn(ucid, operatorName, warnContent);
                    }
                }
            }
            //获取复制客户电话访问次数超过阈值的操作人ucid
            for (Map.Entry<String, Integer> entry : copyPhoneCccessCountMap.entrySet()) {
                if (entry.getValue() > count) {
                    String ucid = entry.getKey();
                    String operatorName = ucidNameMap.get(ucid);
                    if (!contractApolloConfig.getWarnWhiteList().contains(ucid)) {
                        //企微预警
                        String warnContent = String.format("【高频查看手机号】「%s%s」，近%s分钟查看了%s个项目的签约手机号", operatorName, ucid, time, entry.getValue());
                        LOGGER.info(warnContent);
                        privacyCommonService.overFrequencyWarn(ucid, operatorName, warnContent);
                    }
                }
            }
        }
        return new AssignmentResult(ResultMode.EXECUTE_SUCCESS);
    }
}

