@Service(value = TempUpdateContractCollectionRecordSchedule.PUSHER_ID)
public class TempUpdateContractCollectionRecordSchedule extends AbstractPusher<ProjectInfo, Integer> {

	public static final String PUSHER_ID = "TempUpdateContractCollectionRecordSchedule";

	@Resource
	private FundInfoService fundInfoService;

	@Resource
	private FundBaseService fundBaseService;

	@Resource
	private AthenaRpc athenaRpc;

	@Resource
	private ContractService contractService;

	@Resource
	private ContractCollectionPlanRecordService contractCollectionPlanRecordService;

	@Override
	protected Example condition(PusherRequest request) {
		Example example = new Example(ProjectInfo.class);
		example.createCriteria()
			.andNotEqualTo("companyCode","")
		;
		return example;
	}

	@Override
	protected ProjectInfo formatParams(ProjectInfo projectInfo) {
		return projectInfo;
	}

	@Override
	protected Integer doPush(String projectOrderId, ProjectInfo data) {
		if (Objects.isNull(data)) {
			return 0;
		}
		//获取工程款款项
		FundInfo fundInfo = fundInfoService.getFundByOrderIdAndFundType(projectOrderId, FundTypeEnum.PROJECT_CHARGE.getValue());
		//没有工程款/没有收款计划不用处理
		if (fundInfo == null) {
			return 0;
		}
		if (StringUtils.isEmpty(fundInfo.getCollectionPlan())) {
			return 0;
		}
		//获取项目下所有的正签和变更合同
		List<Contract> contractList = contractService.getBatchBaseContractInfo(new ArrayList<>(),
			Collections.singletonList(projectOrderId),
			Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PACKAGE_CHANGE.getCode()), true);

		CollectionPlanConfigInfo configInfo = JSON.parseObject(fundInfo.getCollectionPlan(), CollectionPlanConfigInfo.class);
		PlanAllDTO planAllDTO = athenaRpc.querySinglePlanInfo(fundInfo.getProjectOrderId());
		//合同款
		BigDecimal contractAmount = planAllDTO.getPlanInfo().getContractPriceTotal();
		CollectionPlanConfigInfo contractCollectionPlan = fundBaseService.calculateCollectionPlan(configInfo, contractAmount);
		String collectionPlan = JSON.toJSONString(contractCollectionPlan);

		List<ContractCollectionPlanRecord> insertContractCollectionPlanRecordList = new ArrayList<>();
		for (Contract contract : contractList) {
			ContractCollectionPlanRecord collectionPlanRecord = ContractCollectionPlanRecord.builder()
				.collectionPlan(collectionPlan)
				.contractCode(contract.getContractCode())
				.delStatus(CommonEnum.NO.getCode())
				.ctime(new Date())
				.mtime(new Date())
				.build();
			insertContractCollectionPlanRecordList.add(collectionPlanRecord);
		}

		//先删除再插入，脚本可以重复执行
		contractCollectionPlanRecordService.delByContractCodeList(insertContractCollectionPlanRecordList.stream()
			.map(ContractCollectionPlanRecord::getContractCode).collect(Collectors.toList()));
		contractCollectionPlanRecordService.insertBatch(insertContractCollectionPlanRecordList);

		return 1;
	}

	@Override
	protected boolean pushSwitchOff() {
		return false;
	}
}

