	public Map<String, ChangeKeyConfig> getChangKeyConfigByCityAndBusinessType(Byte businessType, Byte contractType, Integer gbCode) {
		String key = "";
		if (CityEnum.BEIJING.getGbCode() == gbCode) {
			key = mergeLaunchCity + "_" + businessType.toString() + "_" + contractType.toString();
		} else {
			key = defaultCity + "_" + businessType.toString() + "_" + contractType.toString();
		}
		return configMap.get(key);
	}


}

public Map<String, ChangeKeyConfig> getChangKeyConfigByCityAndBusinessType(Byte businessType, Byte contractType, Integer gbCode) {
