	public List<BrandConfigInfo> getBrandInfoList(Integer contractType, String companyCode, String brandCode) {
		// rpc 查询售后服务，获取合同品牌配置
		HashMap<String, String> bizData = new HashMap<>();
		bizData.put("contractType", contractType == null ? "" : String.valueOf(contractType));
		bizData.put("mdmCode", StringUtils.isEmpty(companyCode) ? "" : companyCode);
		bizData.put("brandCode", StringUtils.isEmpty(brandCode) ? "" : brandCode);
		BpmQueryParamV2 param = BpmQueryParamV2.builder()
			.bpmNameKey(BpmNameKeyEnum.CONTRACT_BUSINESS_BRAND_CONFIG.getCode())
			.bizData(bizData)
			.build();
		List<BpmConfigDTOV2> bpmConfigDTOV2s = bpmConfigRpc.getList(param);
		List<BrandConfigInfo> brandConfigInfos = new ArrayList<>();
		if (bpmConfigDTOV2s == null || bpmConfigDTOV2s.isEmpty()) {
			LOGGER.warn("初始化合同品牌查询为空");
			return brandConfigInfos;
		}
		for (BpmConfigDTOV2 bpmConfigDTOV2 : bpmConfigDTOV2s) {
			BrandConfigInfo brandConfigInfo = new BrandConfigInfo();
			CopyUtils.INSTANT.copy(bpmConfigDTOV2.getBizData(), brandConfigInfo);
			brandConfigInfos.add(brandConfigInfo);
		}
		return brandConfigInfos;
	}

