	/**
	 * 给定的工期，是否超出对应业态的上下限
	 * 如果超出，则返回 true；如果不超出，返回 false
	 */
	public boolean isExceedLimitation(Byte businessType, Integer duration) {
		List<Byte> reformAndHouse = Arrays.asList(BusinessTypeEnum.REFORM_ALL.getCode(), BusinessTypeEnum.HOUSE_CERTIFICATE.getCode());
		if (!reformAndHouse.contains(businessType)) {
			return false;
		}



		// 如果工期为空，则直接返回 true，在 pdf 中将工期数据展示为 "/"
		if (Objects.isNull(duration)) {
			return true;
		}

		DurationLimitationConfig durationLimitationConfig = durationLimitationConfigs.stream()
			.filter(config -> config.getBusinessType().equals(businessType))
			.findFirst().orElse(null);

		// 如果不配置，就认为没有上下限，不超出
		if (durationLimitationConfig == null) return false;

		int minDuration = durationLimitationConfig.getMinDuration();
		int maxDuration = durationLimitationConfig.getMaxDuration();

		return duration < minDuration || duration > maxDuration;
	}

