	/**
	 * 功能：基于城市code获取开放日的描述
	 * 异常处理：返回默认描述
	 * @param gbCode 城市code
	 * @return 开放日描述
	 * 逻辑：
	 * 1. 遍历配置的城市code列表，判断传入的城市code是否在列表中
	 * 2. 如果在列表中，返回对应的描述
	 * 3. 如果配置了通配符*，则返回对应的描述
	 * 4. 如果都不匹配，返回默认描述
	 */
	public String getGroupOpenDayDesc(Integer gbCode) {
		if (CollectionUtil.isEmpty(groupOpenDayCityDescMap)) {
			return "/";
		}
		for (Map.Entry<String, String> entry : groupOpenDayCityDescMap.entrySet()) {
			String cityCodesStr = entry.getKey();
			String desc = entry.getValue();
			if (StringUtils.isEmpty(cityCodesStr)) {
				continue;
			}
			if (cityCodesStr.equals("*")) {
				return desc;
			}
			//拆分后去掉收尾空格
			List<String> cityCodes = Arrays.stream(cityCodesStr.split(","))
				.map(String::trim)
				.collect(Collectors.toList());
			if (cityCodes.contains(gbCode.toString())) {
				return desc;
			}
		}
		return groupOpenDayCityDescMap.getOrDefault("default", "");
	}

