public List<Byte> createContractList(String projectOrderId, Byte businessType, String appId,Integer gbCode) {
	List<ProjectVersionDTO> projectVersionDTOS = projectInfoReadService.batchProjectVersion(Collections.singletonList(projectOrderId));
	if (CollectionUtils.isEmpty(projectVersionDTOS)) {
		throw new NrsBusinessException("该项目不支持创建合同");
	}
	if (ProjectVersionEnum.V1.getVersion().equals(projectVersionDTOS.get(0).getProjectVersion())) {
		return Collections.singletonList(ContractTypeEnum.DESIGN.getCode());
	}
	//获取配置路由
	//默认路由key
	String defaultRouteKey = "";
	//城市配置路由key
	String gbCodeRouteKey = "";
	if (commonBusinessService.isPROCESS_V2_5(projectOrderId)) {
		defaultRouteKey = "25".concat("_").concat(businessType.toString()).concat("_").concat(appId);
		gbCodeRouteKey = gbCode + "_" + defaultRouteKey;
	} else {
		defaultRouteKey = "20".concat("_").concat(businessType.toString()).concat("_").concat(appId);
		gbCodeRouteKey = gbCode + "_" + defaultRouteKey;
	}
	//如果有城市配置路由，则使用城市配置路由
	if (contractConfigMap.containsKey(gbCodeRouteKey)) {
		ContractConfig contractConfig = contractConfigMap.get(gbCodeRouteKey);
		if (ObjectUtil.isNotEmpty(contractConfig)) {
			return contractConfig.getCreateContractList();
		}
	}
	ContractConfig contractConfig = contractConfigMap.get(defaultRouteKey);
	if (ObjectUtil.isNotEmpty(contractConfig)) {
		return contractConfig.getCreateContractList();
	}
	return new ArrayList<>();
}

public List<Byte> cannotCreateContractList(String projectOrderId, Byte businessType, String appId, Integer gbCode) {
	List<ProjectVersionDTO> projectVersionDTOS = projectInfoReadService.batchProjectVersion(Collections.singletonList(projectOrderId));
	if (CollectionUtils.isEmpty(projectVersionDTOS)) {
		throw new NrsBusinessException("该项目不支持创建合同");
	}
	if (ProjectVersionEnum.V1.getVersion().equals(projectVersionDTOS.get(0).getProjectVersion())) {
		return new ArrayList<>();
	}
	//获取配置路由
	String defaultRouteKey = "";
	//城市配置路由key
	String gbCodeRouteKey = "";
	String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(projectOrderId);
	if (commonBusinessService.isPROCESS_V2_5(convertProjectOrderId)) {
		defaultRouteKey = "25".concat("_").concat(businessType.toString()).concat("_").concat(appId);
		gbCodeRouteKey = gbCode + "_" + defaultRouteKey;
	} else {
		defaultRouteKey = "20".concat("_").concat(businessType.toString()).concat("_").concat(appId);
		gbCodeRouteKey = gbCode + "_" + defaultRouteKey;
	}
	//如果有城市配置路由，则使用城市配置路由
	if (contractConfigMap.containsKey(gbCodeRouteKey)) {
		ContractConfig contractConfig = contractConfigMap.get(gbCodeRouteKey);
		if (ObjectUtil.isNotEmpty(contractConfig)) {
			return contractConfig.getCannotCreateContractList();
		}
	}
	ContractConfig contractConfig = contractConfigMap.get(defaultRouteKey);
	if (ObjectUtil.isNotEmpty(contractConfig)) {
		return contractConfig.getCannotCreateContractList();
	}
	return new ArrayList<>();
}

