		planInfoDTO.setContractPrice(quoteChangePreviewDTO.getHardTotalPriceAfterCoupon());
		planInfoDTO.setContractPriceTotal(quoteChangePreviewDTO.getHardTotalPriceAfterCoupon());
		planInfoDTO.setPersonalTotalPrice(quoteChangePreviewDTO.getPersonalTotalPriceAfterCoupon());


