//				return false;
//			}
			//是否有基础施工图,2.5施工图纸直接返回的图片，2.0是pdf
			boolean isHaveBaseConstructionDraw = CollectionUtils.isNotEmpty(dynamicChangeContentDTO.getBaseConstructionDrawUrl()) || StringUtils.isNotBlank(dynamicChangeContentDTO.getBaseConstructionDrawPdfUrl());
			return !Boolean.FALSE.equals(dynamicChangeContentDTO.getIsChangeDiscount()) ||
				!CollectionUtils.isEmpty(dynamicChangeContentDTO.getChangeData()) ||
				!StringUtils.isBlank(dynamicChangeContentDTO.getBudgetPdfUrl()) ||
				!CollectionUtils.isEmpty(dynamicChangeContentDTO.getDecorateRuleUrl()) ||
				!StringUtils.isBlank(dynamicChangeContentDTO.getInternalConfigurationsPdfUrl()) ||
				!StringUtils.isBlank(dynamicChangeContentDTO.getExtraConfigurationsPdfUrl()) ||
				!StringUtils.isBlank(dynamicChangeContentDTO.getPersonalQuotionPdfUrl()) ||
				isHaveBaseConstructionDraw ||
				!CollectionUtils.isEmpty(dynamicChangeContentDTO.getMaterialList());
		}

		return true;
