	/**
	 * 获取变单内容
	 *
	 * @param currentContract
	 * @param projectOrderId
	 * @param changeOrderId
	 * @return
	 */
	public List<ModelDiffDTO> getChangeData(Contract currentContract, String projectOrderId, String changeOrderId) {
		List<ContractFieldChangeRecord> list = calculateDiff(currentContract.getContractCode());
		ChangeContractSubmitRes changeContractSubmitRes = new ChangeContractSubmitRes();
		changeContractSubmitRes.setContractCode(currentContract.getContractCode());
		List<ModuleInfoDTO> moduleInfoDTOS = contractUnifyService.fieldDelivery(FieldDeliveryReq.builder()
			.projectOrderId(currentContract.getProjectOrderId())
			.changeOrderId(currentContract.getChangeOrderId())
			.contractType(currentContract.getType())
			.build());

		for (ModuleInfoDTO moduleInfo : moduleInfoDTOS) {
			if (ContractModuleEnum.CONTRACT_PROJECT_INFO.getKey().equals(moduleInfo.getDataIndex())) {
				moduleInfo.getChildren().add(FieldInfoDTO.builder()
					.dataIndex("certificateAddress")
					.formLabel("房本地址")
					.build());
			}
		}

		List<ModelDiffDTO> modelDiffDTOS = buildModelDiff(moduleInfoDTOS, list);
		//报价模块
		List<FieldDiffDTOV2> quotationModelDiff = buildQuotationModelDiff(projectOrderId,
			currentContract.getContractCode(),
			currentContract.getType(),
			changeOrderId,
			currentContract.getBusinessType());
		if (CollectionUtils.isNotEmpty(quotationModelDiff)) {
			modelDiffDTOS.add(ModelDiffDTO.builder()
				.modelName("套餐方案报价")
				.modelKey("quotation")
				.fieldDiff(quotationModelDiff)
				.build());
		}
		//施工图纸模块
		List<FieldDiffDTOV2> drawingDiff = buildDrawingDiff(projectOrderId,
			currentContract.getType(),
			changeOrderId,
			currentContract.getBusinessType());
		if (CollectionUtils.isNotEmpty(drawingDiff)) {
			modelDiffDTOS.add(ModelDiffDTO.builder()
				.modelName("施工图纸")
				.fieldDiff(drawingDiff)
				.build());
		}
		//备件模块字段变更信息
		String attachModelName = "相关审核备件";
		ModelDiffDTO contractAttachInfoModel = modelDiffDTOS.stream().filter(item -> item.getModelName().equals(attachModelName)).findFirst().orElse(null);
		modelDiffDTOS = modelDiffDTOS.stream().filter(item -> !item.getModelName().equals(attachModelName)).collect(Collectors.toList());
		//备件模块
		List<FieldDiffDTOV2> attachModelDiff = buildAttachModelDiff(currentContract.getProjectOrderId(), currentContract.getContractCode(), currentContract.getBusinessType());
		if (contractAttachInfoModel != null) {
			attachModelDiff.addAll(0, contractAttachInfoModel.getFieldDiff());
		}
		if (CollectionUtils.isNotEmpty(attachModelDiff)) {
			modelDiffDTOS.add(ModelDiffDTO.builder()
				.modelName(attachModelName)
				.modelKey("contractAttachInfo")
				.fieldDiff(attachModelDiff)
				.build());
		}
		return modelDiffDTOS;
	}

