	/**
	 * 继承最新正签/变更合同部分字段信息
	 *
	 * @param contract     个性化合同
	 * @param lastContract 最新正签/变更合同
	 */
	public void savePersonalContractField(Contract contract, Contract lastContract) {
		Map<String, Object> fieldMap = new HashMap<>();
		String convertProjectOrderId = commonBusinessService.convertProjectOrderId(lastContract.getProjectOrderId(), lastContract.getType());
		ContractVersionConfig contractConfigAllVersion = contractConfigVersionService.getContractConfigAllVersion(convertProjectOrderId);
		List<String> baseInheritKeys = Arrays.asList("contractObjectType", "companyName", "companyCreditCode", "registeredAddress", "gbCode", "gbName", "districtName", "resblockName", "buildingName", "unitName", "floorName", "houseName");
		String companyCodeActual = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(lastContract.getProjectOrderId(), lastContract.getGbCode(), lastContract.getCompanyCode(), contract.getType());
		//字段配置信息
		List<ContractFieldConfig> fieldConfigs = contractUnifyService.getFieldConfigAdapt(contract.getProjectOrderId(), lastContract.getGbCode(), companyCodeActual, lastContract.getBusinessType(), contract.getType(), contractConfigAllVersion.getFieldConfigVersion());
		List<String> inheritKeys = fieldConfigs.stream().map(ContractFieldConfig::getFieldKey).collect(Collectors.toList());
		inheritKeys.addAll(baseInheritKeys);
		Map<String, String> lastContractFieldMap = contractFieldService.getFieldMap(lastContract.getContractCode());
		for (String inheritKey : inheritKeys) {
			String fieldValue = lastContractFieldMap.get(inheritKey);
			if (StringUtils.isNotBlank(fieldValue)) {
				fieldMap.put(inheritKey, fieldValue);
			}
		}
		//默认为线上签约
		fieldMap.put("signChannelType", SignChannelTypeEnum.ONLINE.getCode());
		fieldMap.put("haveAgent", HaveAgentEnum.NO.getCode());
		//查询分公司信息
		ContractCompanyInfo contractCompanyInfo = contractCompanyInfoService.getByCompanyCode(contract.getCompanyCode());
		fieldMap.put("salesCompanyName", contractCompanyInfo.getCompanyName());
		LOGGER.info("个性化合同继承上一份有效合同部分字段信息:{}", JSON.toJSONString(fieldMap));
		//删除合同字段信息
		List<String> moduleKeyList = contractUnifyService.getModuleInfo(contract.getProjectOrderId(),
				contract.getType(), null, null).stream()
			.map(ContractModuleAndFieldInfoDTO::getModuleKey).collect(Collectors.toList());
		contractUnifyService.deleteContractFieldKeys(contract, moduleKeyList);
		// 插入需要保存的字段
		List<ContractField> fieldList = fieldMap.entrySet().stream().map(entry -> ContractField.builder()
				.contractCode(contract.getContractCode())
				.fieldKey(entry.getKey())
				.fieldValue(entry.getValue() instanceof String ? entry.getValue().toString() : JSON.toJSONString(entry.getValue()))
				.ctime(new Date())
				.mtime(new Date())
				.createUserId("")
				.createUserName("")
				.modifyUserId("")
				.modifyUserName("")
				.delStatus(CommonEnum.NO.getCode())
				.build())
			.collect(Collectors.toList());
		//批量插入数据
		if (CollectionUtil.isNotEmpty(fieldList)) {
			contractFieldService.saveBatch(fieldList);
		}
	}

