	@Retryable(value = Exception.class, maxAttempts = 3, backoff = @Backoff(value = 2000, multiplier = 1))
	public List<Contract> generatePersonalContractV3(ChangePersonalContractReqDTO changePersonalContractReqDTO) {
		LOGGER.info("生成个性化首期合同V3请求参数:{}", JSON.toJSONString(changePersonalContractReqDTO));
		paramCheck(changePersonalContractReqDTO);
		ContractReqDTO contractReq = buildChangePersonalContractReq(changePersonalContractReqDTO);
		String lockKey = LockService.CONTRACT_ORDER_NO_TYPE + contractReq.getContractBaseInfo().getProjectOrderId() + contractReq.getContractBaseInfo().getContractType();
		String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		//设置header值
		try {
			HeaderContext.setContext(HeaderParam.builder()
				.operatorUcId(String.valueOf(changePersonalContractReqDTO.getOperatorUcid()))
				.build());
		} catch (Exception e) {
			throw new IllegalStateException("设置 HeaderContext 失败", e);
		}

		ContractSubmitResDTO contractSubmitResDTO = lockService.lockElseThrow(lockKey, () -> {
			//校验合同是否正在生成中
			contractUnifyService.checkContractLaunching(projectOrderId, contractType);
			//校验合同状态
			List<Contract> contractList = contractService.getContractList(projectOrderId, contractType);
			contractUnifyService.checkContractUnique(projectOrderId, contractType, contractList);
			//校验必填
			contractUnifyService.checkContractRequired(contractReq);
			//合同互斥校验
			contractUnifyService.checkContractMutex(contractReq);
			//校验合同字段一致性
			contractUnifyService.checkContractFieldConsistency(contractReq);
			//个性化首期合同校验分公司信息
			contractUnifyService.checkSignCompanyInfo(contractReq);
			//风控策略校验
			contractUnifyService.checkRisk(contractReq);
			//C合同校验逻辑
			BindOrderInfoGroup group = BindOrderInfoGroup.convert(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getBusinessInfo());
			ContractSecondaryCheckRes contractSecondaryCheckRes = contractUnifyService.checkPersonalListV2(contractReq.getContractBaseInfo().getContractType(), contractReq.getContractBaseInfo().getContractCode(), group);
			if (Boolean.FALSE.equals(contractSecondaryCheckRes.getCheckRes()) && contractApolloConfig.getCheckPersonalContract()) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), contractSecondaryCheckRes.getToast(), Level.WARN);
			}
			//C合同补贴单正式签署校验，补贴单只支持正式签署
			// 2026-03-03 注释：bsu 需求切为变更单交互，国补相关还未使用，因此先注释
//			boolean isSubsidyGoods = subsidyOrderService.isSubsidyGoods(changePersonalContractReqDTO.getBillCode());
//			if (isSubsidyGoods && !UserSignTypeEnum.SIGN.getCode().equals(contractReq.getSignInfo().getUserSignType())) {
//				LOGGER.info("国补单签署方式非正式签署情况下，仅保存草稿，用户自行发起，req:{}", JSON.toJSONString(changePersonalContractReqDTO));
//				contractReq.getSignInfo().setUserSignType(UserSignTypeEnum.SIGN.getCode());
//				return contractSaveDraftService.saveDraft(contractReq);
//			}
			return contractSubmitService.submit(contractReq);
		});

		return Arrays.stream(contractSubmitResDTO.getContractCode().split(","))
			.map(contractService::getByContractCode)
			.collect(Collectors.toList());
	}

	/**
	 * 当重试 3 次后依然失败时，会进入这里
	 */
	@Recover
	public List<Contract> recover(Exception e, ChangePersonalContractReqDTO changePersonalContractReqDTO) {
		LOGGER.error("生成个性化首期合同V3重试3次仍失败，请检查参数或下游服务！请求参数：{}，异常：{}",
			JSON.toJSONString(changePersonalContractReqDTO), e.getMessage(), e);
		// 可以选择返回一个默认值，或者继续抛出异常
		return Collections.emptyList();
	}


	private void paramCheck(ChangePersonalContractReqDTO changePersonalContractReqDTO) {
		if (changePersonalContractReqDTO == null) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "请求参数不能为空", Level.WARN);
		}
		if (StringUtils.isBlank(changePersonalContractReqDTO.getProjectOrderId())) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "项目订单号不能为空", Level.WARN);
		}
		if (StringUtils.isBlank(changePersonalContractReqDTO.getChangeOrderId())) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "变更单号不能为空", Level.WARN);
		}
		if (CollectionUtils.isEmpty(changePersonalContractReqDTO.getCompanyCodeList())) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "需要生成合同的主体列表不能为空", Level.WARN);
		}
		if (changePersonalContractReqDTO.getOperatorUcid() == null) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "操作人ucid不能为空", Level.WARN);
		}
	}


	private ContractReqDTO buildChangePersonalContractReq(ChangePersonalContractReqDTO changePersonalContractReqDTO) {
		Contract latestContract = getChangePrevEffectContractByPid(changePersonalContractReqDTO.getProjectOrderId());
		if (Objects.isNull(latestContract)) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "生成变更销售合同失败，缺少上一份有效的正签/变更", Level.WARN);
		}
		byte userSignType = UserSignTypeEnum.SIGN.getCode();
		if (UserSignTypeEnum.CONFIRM.getCode().equals(latestContract.getUserSignType()) || SignChannelTypeEnum.OFFLINE.getCode().equals(latestContract.getSignChannelType())) {
			userSignType = UserSignTypeEnum.CONFIRM.getCode();
		}
		Map<String, String> fieldMap = contractFieldService
			.getListByContractCode(latestContract.getContractCode())
			.stream()
			.collect(Collectors.toMap(
				ContractField::getFieldKey,
				ContractField::getFieldValue,
				(oldValue, newValue) -> newValue, // 处理重复 key
				HashMap::new
			));

		ContractBaseInfoReq contractBaseInfo = ContractBaseInfoReq.builder()
			.projectOrderId(changePersonalContractReqDTO.getProjectOrderId())
			.contractType(ContractTypeEnum.PERSONAL.getCode())
			.changeOrderId(changePersonalContractReqDTO.getChangeOrderId())
			.build();

		ContractSignInfoReq signInfo = new ContractSignInfoReq();
		BeanUtil.fillBeanWithMap(fieldMap, signInfo, true);
		signInfo.setUserSignType(userSignType);
		signInfo.setSignChannelType(SignChannelTypeEnum.ONLINE.getCode());

		ContractProjectInfoReq projectInfo = new ContractProjectInfoReq();
		BeanUtil.fillBeanWithMap(fieldMap, projectInfo, true);

		PromiseInfoReq promiseInfoReq = new PromiseInfoReq();
		BeanUtil.fillBeanWithMap(fieldMap, promiseInfoReq, true);

		List<ChangeOrderInfo> changeOrderInfoList = changePersonalContractReqDTO.getCompanyCodeList().stream()
			.map(companyCode -> ChangeOrderInfo.builder()
				.companyCode(companyCode)
				.changeOrderId(changePersonalContractReqDTO.getChangeOrderId())
				.build())
			.collect(Collectors.toList());

		List<String> companyCodeList = changePersonalContractReqDTO.getCompanyCodeList();
		List<MdmDTO> mdmDTOS = mdmRpc.obtainMdmMerchantByMdmCodes(companyCodeList);

		return ContractReqDTO.builder()
			.contractBaseInfo(contractBaseInfo)
			.signInfo(signInfo)
			.projectInfo(projectInfo)
			.businessInfo(BusinessInfoDetail.builder()
				.changeOrderInfoList(changeOrderInfoList)
				.build())
			.promiseInfo(promiseInfoReq)
			.personalQuotation(PersonalQuotation.builder()
				.salesCompanyName(mdmDTOS.stream().map(MdmDTO::getCompanyName).collect(Collectors.joining(",")))
				.build())
			.build();
	}

	private List<FieldDiffDTO> compareContractQuote(String projectOrderId, String changeOrderId, FormalContractExpandInfoDTO prevExpandInfo, FormalContractExpandInfoDTO currentExpandInfo) {
		List<FieldDiffDTO> result = new LinkedList<>();

		boolean processV25New = commonBusinessService.isProcessV25New(projectOrderId);
		if (!processV25New) {
			return result;
		}

		ChangeApplyInfoDTO changeApplyInfoDTO = atomChangeRpc.getChangeApplyInfo(changeOrderId);
		List<Integer> changeScopeList = changeApplyInfoDTO.getChangeScopeList();
		if (CollectionUtils.isEmpty(changeScopeList) || !changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode())) {
			// 变更范围不包含报价，直接返回
			return result;
		}

		QuoteChangeDiffBO quoteBillDiff = getQuoteBillDiff(projectOrderId, changeOrderId);
		QuoteChangePreviewDTO preQuoteBill = quoteBillDiff.getPreQuoteBill();
		QuoteChangePreviewDTO quoteBill = quoteBillDiff.getQuoteBill();
		// 套餐
		if (CollectionUtils.isNotEmpty(CollUtil.subtract(preQuoteBill.getComboNameList(), quoteBill.getComboNameList()))
			|| CollectionUtils.isNotEmpty(CollUtil.subtract(quoteBill.getComboNameList(), preQuoteBill.getComboNameList()))) {
			result.add(FieldDiffDTO.builder()
				.fieldKey(ChangeKeyEnum.COMBO.getKey())
				.fieldName("所选套餐")
				.oldValue(String.join(",", preQuoteBill.getComboCodeList()))
				.newValue(String.join(",", quoteBill.getComboCodeList()))
				.build());
		}

		return result;
	}

