public List<ButtonItemVo> buildCHangeContractDiffButtonList(Contract contract) {
	List<ButtonItemVo> buttonItemList = new ArrayList<>();
	Integer status = contract.getStatus();
	switch (ContractStatusEnum.getContractStatusEnumByCode(status)) {
		case DRAFT:
			buttonItemList.add(new ButtonItemVo(HomeButtonEnum.INITIATE_SIGN));
			break;
		case PENDING_USER_SIGN:
		case PENDING_USER_CONFIRM:
			buttonItemList.add(new ButtonItemVo(HomeButtonEnum.UNDO));
			buttonItemList.add(new ButtonItemVo(HomeButtonEnum.PREVIEW));
			break;
		case AUDITING:
			buttonItemList.add(new ButtonItemVo(HomeButtonEnum.CANCEL_AUDIT));
			buttonItemList.add(new ButtonItemVo(HomeButtonEnum.PREVIEW));
			break;
		case FINISH:
		case USER_CONFIRMED:
			buttonItemList.add(new ButtonItemVo(HomeButtonEnum.PREVIEW));
			break;
		default:
	}
	return buttonItemList;

}

public ChangeContractVO getChangeContractVO(String projectOrderId, String changeOrderId) {
	ChangeContractVO changeContractVO = null;
	Contract changeContract = contractService.getChangeContract(projectOrderId, changeOrderId);
	if (ObjectUtil.isNotEmpty(changeContract)) {
		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(changeContract.getContractCode());
		Map<String, String> map = Maps.newHashMap();
		contractFieldList.forEach(contractField -> map.put(contractField.getFieldKey(), contractField.getFieldValue()));
		//把字符串转化为时间date格式
		List<ContractNode> contractNodeList = contractNodeService.getByContractCodeAndType(changeContract.getContractCode(), NodeTypeEnum.USER_SIGN.getCode());
		Date signTime = null;
		if (ObjectUtil.isNotEmpty(contractNodeList)) {
			ContractNode contractNode = contractNodeList.get(0);
			signTime = DateUtil.date(contractNode.getFireTime());
		}

		if (ObjectUtil.isNotEmpty(changeContract)) {
			changeContractVO = ChangeContractVO.builder()
				.contractNo(changeContract.getContractNo())
				.contractCode(changeContract.getContractCode())
				.changeContractAmount(changeContract.getAmount())
				.createTime(changeContract.getCtime())
				.signTime(signTime)
				.signChannelType(changeContract.getSignChannelType())
				.signChannelTypeLabel(SignChannelTypeEnum.getNameByCode(changeContract.getSignChannelType()))
				.status(changeContract.getStatus())
				.statusDesc(homeAndPcCommonService.getContractStateText(changeContract))
				.errorMessage(homeAndPcCommonService.getContractErrorMessage(changeContract))
				.estimatedLaunchTime(ContractTypeEnum.PACKAGE_CHANGE.getEstimatedLaunchTime())
				.build();
		}
	}
	return changeContractVO;
}

