	public ChangeContractFreeformDTO buildChangeContractFreeformDTO(String contractCode, String projectOrderId, String changeOrderId, boolean isTransferPicture) {
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
		@Nullable Contract contract = StringUtils.isNotBlank(contractCode) ? contractService.getByContractCode(contractCode) : null;
		Contract formalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode()).get(0);
		Map<String, String> fieldsMap = pcContractService.getContractFieldKeyValueMap(contractCode);

		List<ContractFieldChangeRecord> changeRecordList = getContractDiff(contractCode);
		Map<String, String> changeMap = new HashMap<>();
		Map<String, String> oldValueMap = new HashMap<>();
		for (ContractFieldChangeRecord changeRecord : changeRecordList) {
			oldValueMap.put(changeRecord.getFieldKey(), changeRecord.getOldValue());
			changeMap.put(changeRecord.getFieldKey(), changeRecord.getNewValue());
		}
		// 公司名称（甲方）
		String firstPartCompanyName = null;

		ContractUser owner;
		ContractUser agent;
		ContractUser companyAgent;
		ContractUser legal;

		// 兼容下载模板合同未保存草稿的情况
		if (contract == null) {
			contract = Contract.builder()
				.type(ContractTypeEnum.PACKAGE_CHANGE.getCode())
				.businessType(formalContract.getBusinessType())
				.companyCode(formalContract.getCompanyCode())
				.gbCode(formalContract.getGbCode())
				.changeOrderId(changeOrderId)
				.projectOrderId(projectOrderId)
				.build();

			ContractReqDTO contractReq = ContractContextHandler.getContractReq();

			// 由于没有diff没有落库，导致changeMap为空，所以需要重新计算diff
			List<ContractFieldChangeRecord> contractFieldChangeRecords = calculateDiffByReq();
			changeMap = contractFieldChangeRecords.stream().collect(Collectors.toMap(ContractFieldChangeRecord::getFieldKey, ContractFieldChangeRecord::getNewValue, (v1, v2) -> v2));

			ContractSignInfoReq signInfo = contractReq.getSignInfo();
			owner = StringUtils.isNotBlank(signInfo.getOwnerCertificateNo()) ?
				ContractUser.builder().name(signInfo.getOwnerName()).phone(signInfo.getOwnerPhone()).certificateNo(signInfo.getOwnerCertificateNo()).certificateType(signInfo.getOwnerCertificateType()).build() : null;
			agent = StringUtils.isNotBlank(signInfo.getAgentCertificateNo()) ?
				ContractUser.builder().name(signInfo.getAgentName()).phone(signInfo.getAgentPhone()).certificateNo(signInfo.getAgentCertificateNo()).certificateType(signInfo.getAgentCertificateType()).build() : null;
			companyAgent = StringUtils.isNotBlank(signInfo.getCompanyAgentCertificateNo()) ?
				ContractUser.builder().name(signInfo.getCompanyAgentName()).phone(signInfo.getCompanyAgentPhone()).certificateNo(signInfo.getCompanyAgentCertificateNo()).certificateType(signInfo.getCompanyAgentCertificateType()).build() : null;
			legal = StringUtils.isNotBlank(signInfo.getLegalCertificateNo()) ?
				ContractUser.builder().name(signInfo.getLegalName()).phone(signInfo.getLegalPhone()).certificateNo(signInfo.getLegalCertificateNo()).certificateType(signInfo.getLegalCertificateType()).build() : null;
//			collectionPlanConfigInfo = contractReq.getCollectionPlanConfigInfo();

			firstPartCompanyName = signInfo.getCompanyName();
			fieldsMap.put("contractObjectType", String.valueOf(signInfo.getContractObjectType()));
			fieldsMap.put("companyAgentName", signInfo.getCompanyAgentName());
			fieldsMap.put("companyAgentPhone", signInfo.getCompanyAgentPhone());
			fieldsMap.put("companyAgentCertificateNo", signInfo.getCompanyAgentCertificateNo());
			fieldsMap.put("ownerAddress", signInfo.getOwnerAddress());
			fieldsMap.put("registeredAddress", signInfo.getRegisteredAddress());
			fieldsMap.put("companyName", signInfo.getCompanyName());
			fieldsMap.put("companyCreditCode", signInfo.getCompanyCreditCode());

			ContractProjectInfoReq projectInfo = contractReq.getProjectInfo();
			fieldsMap.put("structure", String.valueOf(projectInfo.getStructure()));
			fieldsMap.put("parlorCnt", String.valueOf(projectInfo.getParlorCnt()));
			fieldsMap.put("roomCnt", String.valueOf(projectInfo.getRoomCnt()));
			fieldsMap.put("cookroomCnt", String.valueOf(projectInfo.getCookroomCnt()));
			fieldsMap.put("toiletCnt", String.valueOf(projectInfo.getToiletCnt()));
			fieldsMap.put("balconyCnt", String.valueOf(projectInfo.getBalconyCnt()));
			fieldsMap.put("storageCnt", String.valueOf(projectInfo.getStorageCnt()));
			fieldsMap.put("area", String.valueOf(projectInfo.getArea()));

			List<String> moduleKeyList = contractUnifyService.getModuleKeyList(projectOrderId, ContractTypeEnum.PACKAGE_CHANGE.getCode());
			if (moduleKeyList.contains(ContractModuleEnum.PROMISE_INFO.getKey())) {
				PromiseInfoReq promiseInfo = contractReq.getPromiseInfo();
				fieldsMap.put("disputeDealMode", String.valueOf(promiseInfo.getDisputeDealMode()));
				fieldsMap.put("taxRate", String.valueOf(promiseInfo.getTaxRate()));
				fieldsMap.put("afterDiscountDesignerAmount", String.valueOf(promiseInfo.getAfterDiscountDesignerAmount()));
			}
		} else {
			owner = contractUserService.getUserByContractCodeAndType(contractCode, UserTypeEnum.OWNER.getCode());
			agent = contractUserService.getUserByContractCodeAndType(contractCode, UserTypeEnum.AGENT.getCode());
			companyAgent = contractUserService.getUserByContractCodeAndType(contractCode, UserTypeEnum.COMPANY_AGENT.getCode());
			legal = contractUserService.getUserByContractCodeAndType(contractCode, UserTypeEnum.LEGAL.getCode());
		}
		// 签约人
		ContractUser signatoryUser = owner != null ? owner : legal != null ? legal : companyAgent;

		LOGGER.info("changeMap:{}", JSON.toJSONString(changeMap));
		List<ContractNode> contractNodes = contractNodeService.getByContractCodeAndType(formalContract.getContractCode(), NodeTypeEnum.FINISH.getCode());
		String signDate = CollectionUtils.isNotEmpty(contractNodes) ? DateUtils.getDateStr(new Date(contractNodes.get(0).getFireTime())) : "/";
		ChangeContractFreeformDTO.DynamicChangeContent changeContent = new ChangeContractFreeformDTO.DynamicChangeContent();
		CompanyInfoDTO companyInfoDTO = commonContractService.getCompanyInfo(formalContract.getCompanyCode());

		Boolean isChangeQuotation = false;
		Boolean isChangeDrawing = false;
		Boolean isChangeDiscount = false;
		Boolean isDecorateRuleUrl = false;
		Boolean isMaterialList = false;

		List<String> budgetUrl = null;
		List<String> internalConfigurationsUrl = null;
		List<String> extraConfigurationsUrl = null;
		List<String> personalQuotionUrl = null;
		List<String> baseConstructionDrawUrl = null;


		String budgetPdfUrl = "";
		String internalConfigurationsPdfUrl = "";
		String extraConfigurationsPdfUrl = "";
		String personalQuotionPdfUrl = "";
		String baseConstructionDrawPdfUrl = "";

		ChangeContractFreeformDTO.Coupon couponDto = new ChangeContractFreeformDTO.Coupon();
		List<ChangeContractFreeformDTO.Photo> decorateRuleUrl = null;
		CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectOrderId);
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
		if (processV25) {
			ChangeApplyInfoDTO changeApplyInfoDTO = atomChangeRpc.getChangeApplyInfo(changeOrderId);
			List<Integer> changeScopeList = changeApplyInfoDTO.getChangeScopeList();

			isChangeQuotation = changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode());
			isChangeDrawing = changeScopeList.contains(ChangeScopeEnum.DRAWING.getCode());
			Map<String, Object> tempMap = new HashMap<>();
			ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();
			parallelTaskService.addNewTask(parallelTasksContext, () -> {
				// 报价单
				if (Boolean.TRUE.equals(changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode()))) {
					PlanAttachmentDTO planAttachmentDTO = homeOrderDataConversionService.changeHardDecorationFileData(changeOrderId);
					String baseChangePdf = planAttachmentDTO != null ? planAttachmentDTO.getFileUrl() : "";
					// 变更范围包含报价并且有查询到报价单pdf才放到合同中
					tempMap.put("isChangeQuotation", StringUtils.isNotBlank(baseChangePdf));
					tempMap.put("budgetPdfUrl", baseChangePdf);
					tempMap.put("budgetUrl", isTransferPicture ? pdfToImageService.pdf2ImagePublicParallel(baseChangePdf) : Lists.emptyList());
				}
			});

			parallelTaskService.addNewTask(parallelTasksContext, () -> {
				// 图纸
				if (Boolean.TRUE.equals(changeScopeList.contains(ChangeScopeEnum.DRAWING.getCode()))) {
					tempMap.put("baseConstructionDrawUrl", atomDrawingRpc.getBaseChangeDrawingImgList(coordinationProjectOrder.getProjectOrderId(), changeOrderId));
				}
			});
			parallelTaskService.execTasks(parallelTasksContext);
			parallelTaskService.awaitTasksResult(parallelTasksContext);
			budgetPdfUrl = CommonUtil.getStringFromMap(tempMap, "budgetPdfUrl");
			budgetUrl = CommonUtil.getListFromMap(tempMap, "budgetUrl");
			// 变更范围包含报价并且有查询到报价单pdf才放到合同中
			isChangeQuotation = CommonUtil.getBooleanFromMap(tempMap, "isChangeQuotation");
			baseConstructionDrawUrl = CommonUtil.getListFromMap(tempMap, "baseConstructionDrawUrl");

			isDecorateRuleUrl = changeMap.containsKey(ChangeKeyEnum.COMBO.getKey());
			if (isDecorateRuleUrl) {
				String newValue = changeMap.get(ChangeKeyEnum.COMBO.getKey());
				List<String> newComboCodeList = Arrays.asList(newValue.split(","));
				decorateRuleUrl = comboInfoService.getChangeContractAllUrls(projectOrderId, contract.getBusinessType(), newComboCodeList);
			}
		}

		if (!processV25 && changeContractService.changePriceScope(contract.getChangeOrderId())) {
			//报价
			isChangeQuotation = true;
			Map<String, Object> tempMap = new HashMap<>();
			ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();
			parallelTaskService.addNewTask(parallelTasksContext, () -> {
				tempMap.put("planAllDTO", quotationFeignService.querySnapshotPlan(coordinationProjectOrder.getProjectOrderId(), changeOrderId));
			});
			parallelTaskService.addNewTask(parallelTasksContext, () -> {
				tempMap.put("quotationDiffResultDTO", quotationFeignService.queryQuotationDiffResult(coordinationProjectOrder.getProjectOrderId(), changeOrderId));
			});
			parallelTaskService.execTasks(parallelTasksContext);
			parallelTaskService.awaitTasksResult(parallelTasksContext);
			PlanAllDTO planAllDTO = (PlanAllDTO) tempMap.get("planAllDTO");
			QuotationDiffResultDTO quotationDiffResultDTO = (QuotationDiffResultDTO) tempMap.get("quotationDiffResultDTO");
			//获取报价相关信息
			for (PlanAttachmentDTO planAttachmentDTO : planAllDTO.getPlanAttachmentList()) {
				switch (planAttachmentDTO.getFileType()) {
					case PlanAttachment.报价单:
						budgetPdfUrl = planAttachmentDTO.getFileUrl();
						budgetUrl = isTransferPicture ? pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl()) : Lists.emptyList();
						break;
					case PlanAttachment.套餐套内配置清单:
						internalConfigurationsPdfUrl = planAttachmentDTO.getFileUrl();
						internalConfigurationsUrl = isTransferPicture ? pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl()) : Lists.emptyList();
						break;
					case PlanAttachment.加载配置清单:
						extraConfigurationsPdfUrl = planAttachmentDTO.getFileUrl();
						extraConfigurationsUrl = isTransferPicture ? pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl()) : Lists.emptyList();
						break;
					case PlanAttachment.套外个性化报价单:
						personalQuotionPdfUrl = planAttachmentDTO.getFileUrl();
						personalQuotionUrl = isTransferPicture ? pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl()) : Lists.emptyList();
						break;
					case PlanAttachment.基础图纸:
						baseConstructionDrawPdfUrl = planAttachmentDTO.getFileUrl();
						baseConstructionDrawUrl = isTransferPicture ? pdfToImageService.pdf2ImagePublicParallel(planAttachmentDTO.getFileUrl()) : Lists.emptyList();
						break;
					default:
				}
			}
			if (CollectionUtil.isEmpty(internalConfigurationsUrl)) {
				Byte businessType = contract.getBusinessType();
				//兼容团装历史数据
				if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
					internalConfigurationsUrl = budgetUrl;
				}
			}
			if (quotationDiffResultDTO.comboIsDiff()) {
				isDecorateRuleUrl = true;
				List<ChangeContractFreeformDTO.Photo> photoList = new ArrayList<>();
				String dateStr = DateUtils.getDateStr(new Date());
				List<String> allUrls = comboInfoService.getAllUrls(projectOrderId, ContractTypeEnum.PACKAGE_CHANGE.getCode(), planAllDTO.getPlanInfo().getComboCode());
				for (String url : allUrls) {
					ChangeContractFreeformDTO.Photo photo = new ChangeContractFreeformDTO.Photo();
					photo.setSrc(url);
					photo.setSign_date(dateStr);
					photoList.add(photo);
				}
				//仅2.0使用
				decorateRuleUrl = photoList;
			}
		}

		//优惠
		if (!processV25 && changeContractService.changeDiscountScope(contract.getChangeOrderId())) {
			isChangeDiscount = true;
			String couponAmount = "";
			String couponRemark = "";
			PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(coordinationProjectOrder.getProjectOrderId(), contract.getChangeOrderId());
			List<String> couponRemarkList = contractBusinessService.getCouponRemarkList(planAllDTO);
			if (CollectionUtils.isNotEmpty(planAllDTO.getCouponList())) {
				for (CouponDTO couponDTO : planAllDTO.getCouponList()) {
					if (CouponTypeEnum.DIRECT_COUPON.getCode().equals(couponDTO.getCouponType())) {
						couponAmount = couponDTO.getLapseAmount().toString();
					}
				}
			}

			//新中控优惠备注需要拼接
			couponRemark = org.apache.commons.lang3.StringUtils.join(couponRemarkList.toArray(), "/n");

			couponDto.setContractAmount(String.valueOf(planAllDTO.getPlanInfo().getContractPriceTotal()));
			couponDto.setCouponAmount(couponAmount);
			couponDto.setCouponRemark(couponRemark);
			couponDto.setApplyDate(DateUtils.getDateStr(new Date()));
			couponDto.setJiafangXingming(signatoryUser.getName());
			couponDto.setQuotationTotalAmount(String.valueOf(planAllDTO.getPlanInfo().getQuotePrice()));
			couponDto.setProjectContractAddress(getCertificateAddress(fieldsMap));
			couponDto.setContractNo(contract.getContractNo());
			couponDto.setFirstPartyConnectPhone(cipherService.decrypt(signatoryUser.getPhone()));
			changeContent.setCoupon(couponDto);
			LOGGER.info("couponDto:{}", JsonUtil.toJsonString(couponDto));
		}

		/**
		 * 获取城市业务类型对应变更项
		 */
		List<String> changeKeyList = ChangeKeyEnum.getChangeKeyListByBussinessType(contract.getBusinessType(), contract.getType(), processV25, commonContractService.getCityMapping(contract.getGbCode(), contract.getProjectOrderId()));
		if (CollectionUtils.isEmpty(changeKeyList)) {
			throw new NrsBusinessException(String.format("未找到对应的变更项, businessType:%s, gbCode:%s, 合同类型：%s", contract.getBusinessType(), contract.getGbCode(), ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType())));
		}
		Map<String, ChangeKeyConfig> changKeyConfigMap = changeContractKeyConfig.getChangKeyConfigByCityAndBusinessType(contract.getBusinessType(), contract.getType(), commonContractService.getCityMapping(projectInfoDTO.getCustomerHouse().getGbCode(), contract.getProjectOrderId()));
		if (CollectionUtil.isEmpty(changKeyConfigMap)) {
			throw new NrsBusinessException(String.format("未找到对应的变更项条例位置, businessType:%s, gbCode:%s, 合同类型：%s", contract.getBusinessType(), contract.getGbCode(), ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(), contract.getBusinessType())));
		}
		List<ChangeContractFreeformDTO.ChangeDataItem> changeData = new LinkedList<>();
		//代理人 需要控制顺序 局装的在第一个，整装的在最后
		ChangeContractFreeformDTO.ChangeDataItem agentItem = null;
		LOGGER.info("changeKeyList:{}", JSON.toJSONString(changeKeyList));
		if (changeKeyList.contains(ChangeKeyEnum.AGENT.getKey()) && (changeMap.containsKey("agentName") || changeMap.containsKey("agentCertificateType") || changeMap.containsKey("agentCertificateNo"))) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.AGENT.getKey());
			agentItem = new ChangeContractFreeformDTO.ChangeDataItem();
			agentItem.setArticle(changeKeyConfig.getArticle());
			agentItem.setParagraph(changeKeyConfig.getParagraph());
			agentItem.setKey(ChangeKeyEnum.AGENT.getKey());
			agentItem.setAgentName(Objects.isNull(agent) ? "/" : agent.getName());
			agentItem.setAgentPhone(Objects.isNull(agent) ? "/" : cipherService.decrypt(agent.getPhone()));
			agentItem.setAgentIdNo(Objects.isNull(agent) ? "/" : cipherService.decrypt(agent.getCertificateNo()));
			agentItem.setAgentCertificateType(Objects.isNull(agent) ? "/" : CertificateTypeEnum.getNameByCode(agent.getCertificateType()));
		}
		//局装的只有变化后有值才显示,整装均展示，团装不展示
		if (BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType()) && ObjectUtil.isNotEmpty(agentItem)) {
			changeData.add(agentItem);
		} else if (BusinessTypeEnum.PART_DECORATE.getCode().equals(contract.getBusinessType())) {
			if ((changeMap.containsKey("agentName") && StringUtils.isNotBlank(changeMap.get("agentName")))
				|| (changeMap.containsKey("agentCertificateType") && StringUtils.isNotBlank(changeMap.get("agentCertificateType")))
				|| (changeMap.containsKey("agentCertificateNo") && StringUtils.isNotBlank(changeMap.get("agentCertificateNo")))) {
				changeData.add(agentItem);
			}
		}
		//地址
		if (changeKeyList.contains(ChangeKeyEnum.PROJECT_CONTRACT_ADDRESS.getKey()) && changeMap.containsKey("certificateAddress")) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.PROJECT_CONTRACT_ADDRESS.getKey());
			ChangeContractFreeformDTO.ChangeDataItem addressItem = new ChangeContractFreeformDTO.ChangeDataItem();
			addressItem.setArticle(changeKeyConfig.getArticle());
			addressItem.setParagraph(changeKeyConfig.getParagraph());
			addressItem.setKey(ChangeKeyEnum.PROJECT_CONTRACT_ADDRESS.getKey());
			addressItem.setProjectContractAddress(changeMap.getOrDefault("certificateAddress", ""));
			changeData.add(addressItem);
		}
		//房屋结构
		List<String> layoutFields = new ArrayList(Arrays.asList("roomCnt", "parlorCnt", "cookroomCnt", "toiletCnt", "balconyCnt", "structure", "area"));
		List<String> changeKeys = new ArrayList<>(changeMap.keySet());
		layoutFields.retainAll(changeKeys); //取交集
		//局装的没有房屋结构信息
		if (changeKeyList.contains(ChangeKeyEnum.STRUCTURE.getKey()) && CollectionUtils.isNotEmpty(layoutFields)) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.STRUCTURE.getKey());
			ChangeContractFreeformDTO.ChangeDataItem structureItem = new ChangeContractFreeformDTO.ChangeDataItem();
			structureItem.setArticle(changeKeyConfig.getArticle());
			structureItem.setParagraph(changeKeyConfig.getParagraph());
			structureItem.setKey(ChangeKeyEnum.STRUCTURE.getKey());
			String roomCnt = StringUtils.isBlank(changeMap.get("roomCnt")) ? fieldsMap.getOrDefault("roomCnt", "") : changeMap.get("roomCnt");
			String parlorCnt = StringUtils.isBlank(changeMap.get("parlorCnt")) ? fieldsMap.getOrDefault("parlorCnt", "") : changeMap.get("parlorCnt");
			String cookroomCnt = StringUtils.isBlank(changeMap.get("cookroomCnt")) ? fieldsMap.getOrDefault("cookroomCnt", "") : changeMap.get("cookroomCnt");
			String toiletCnt = StringUtils.isBlank(changeMap.get("toiletCnt")) ? fieldsMap.getOrDefault("toiletCnt", "") : changeMap.get("toiletCnt");
			String balconyCnt = StringUtils.isBlank(changeMap.get("balconyCnt")) ? fieldsMap.getOrDefault("balconyCnt", "") : changeMap.get("balconyCnt");
			String storageCnt = StringUtils.isBlank(changeMap.get("storageCnt")) ? fieldsMap.getOrDefault("storageCnt", "") : changeMap.get("storageCnt");
			String layout = MessageFormat.format("{0}室{1}厅{2}厨{3}卫{4}阳台{5}储物间", roomCnt, parlorCnt,
				cookroomCnt, toiletCnt, balconyCnt, storageCnt);
			Integer oldStructureCode = Integer.parseInt(fieldsMap.getOrDefault("structure", "0"));
			String structure = StringUtils.isBlank(changeMap.get("structure")) ? StructureEnum.getNameByCode(oldStructureCode) : changeMap.get("structure");
			if (Objects.isNull(structure)) {
				structure = "";
			}
			structureItem.setStructure(structure);
			structureItem.setLayout(layout);
			structureItem.setRoomCnt(roomCnt);
			structureItem.setParlorCnt(parlorCnt);
			structureItem.setCookroomCnt(cookroomCnt);
			structureItem.setToiletCnt(toiletCnt);
			structureItem.setBalconyCnt(balconyCnt);
			String area = StringUtils.isBlank(changeMap.get("area")) ? fieldsMap.getOrDefault("area", "") : changeMap.get("area");
			structureItem.setArea(StringUtils.isBlank(area) ? "" : area + "平方米");
			changeData.add(structureItem);
		}

		//工程承包方式
		if (changeKeyList.contains(ChangeKeyEnum.PROJECT_CONTRACT_MODEL.getKey()) && changeMap.containsKey("projectContractModeCode")) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.PROJECT_CONTRACT_MODEL.getKey());
			ChangeContractFreeformDTO.ChangeDataItem projectContractModeItem = new ChangeContractFreeformDTO.ChangeDataItem();
			projectContractModeItem.setArticle(changeKeyConfig.getArticle());
			projectContractModeItem.setParagraph(changeKeyConfig.getParagraph());
			projectContractModeItem.setKey(ChangeKeyEnum.PROJECT_CONTRACT_MODEL.getKey());
			Integer projectContractMode = ProjectContractModeEnum.getCodeByName(changeMap.getOrDefault("projectContractModeCode", ""));
			if (ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS_V2.getCode().equals(projectContractMode)) {
				projectContractMode = ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS.getCode();
			}
			projectContractModeItem.setProjectContractMode(Objects.nonNull(projectContractMode) ? String.valueOf(projectContractMode) : "/");
			projectContractModeItem.setTaxRate(fieldsMap.getOrDefault("taxRate", "/"));
			changeData.add(projectContractModeItem);
		}
		//局装-房间范围
		if (changeKeyList.contains(ChangeKeyEnum.PART_ROOM_RANGE.getKey()) && changeMap.containsKey("partRoomRange")) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.PART_ROOM_RANGE.getKey());
			ChangeContractFreeformDTO.ChangeDataItem item = new ChangeContractFreeformDTO.ChangeDataItem();
			item.setArticle(changeKeyConfig.getArticle());
			item.setParagraph(changeKeyConfig.getParagraph());
			item.setKey(ChangeKeyEnum.PART_ROOM_RANGE.getKey());
			item.setPartRoomRange(changeMap.getOrDefault("partRoomRange", "/"));
			changeData.add(item);
		}
		//维修
		if (changeKeyList.contains(ChangeKeyEnum.GUARANTEE_INFO.getKey()) && (changeMap.containsKey("waterProofGuaranteeYearEnum") || changeMap.containsKey("otherGuaranteeYearEnum") || changeMap.containsKey("waterElectricGuaranteeYear") || changeMap.containsKey("waterProofGuaranteeYear") || changeMap.containsKey("otherGuaranteeYear"))) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.GUARANTEE_INFO.getKey());
			ChangeContractFreeformDTO.ChangeDataItem item = new ChangeContractFreeformDTO.ChangeDataItem();
			item.setArticle(changeKeyConfig.getArticle());
			item.setParagraph(changeKeyConfig.getParagraph());
			item.setKey(ChangeKeyEnum.GUARANTEE_INFO.getKey());
			item.setWaterElectricGuaranteeYear(fieldsMap.getOrDefault("waterElectricGuaranteeYear", "/"));
			item.setWaterProofGuaranteeYear(fieldsMap.getOrDefault("waterProofGuaranteeYear", "/"));
			item.setOtherGuaranteeYear(fieldsMap.getOrDefault("otherGuaranteeYear", "/"));
			item.setWaterProofGuaranteeYearEnum(fieldsMap.getOrDefault("waterProofGuaranteeYearEnum", "/"));
			item.setOtherGuaranteeYearEnum(fieldsMap.getOrDefault("otherGuaranteeYearEnum", "/"));
			changeData.add(item);
		}
		//纠纷处理方式
		if (changeKeyList.contains(ChangeKeyEnum.DISPUTE_DEAL_MODE.getKey()) && changeMap.containsKey("disputeDealMode")) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.DISPUTE_DEAL_MODE.getKey());
			ChangeContractFreeformDTO.ChangeDataItem item = new ChangeContractFreeformDTO.ChangeDataItem();
			item.setArticle(changeKeyConfig.getArticle());
			item.setKey(ChangeKeyEnum.DISPUTE_DEAL_MODE.getKey());
			item.setDisputeDealMode(fieldsMap.getOrDefault("disputeDealMode", ""));
			changeData.add(item);
		}
		//合同工期
		if (changeKeyList.contains(ChangeKeyEnum.PROJECT_DAY.getKey()) && (changeMap.containsKey("totalDurationEnum") || changeMap.containsKey("beforeDeliveryDaysToWork"))) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.PROJECT_DAY.getKey());
			ChangeContractFreeformDTO.ChangeDataItem item = new ChangeContractFreeformDTO.ChangeDataItem();
			item.setArticle(changeKeyConfig.getArticle());
			item.setParagraph(changeKeyConfig.getParagraph());
			item.setKey(ChangeKeyEnum.PROJECT_DAY.getKey());
			item.setProjectDay(TotalDurationEnum.getNameByCode(Integer.valueOf(fieldsMap.getOrDefault("totalDurationEnum", "0"))));
			item.setBeforeDeliveryDaysToWork(fieldsMap.getOrDefault("beforeDeliveryDaysToWork", ""));
			changeData.add(item);
		}
		//合同金额
		if (changeKeyList.contains(ChangeKeyEnum.CONTRACT_AMOUNT.getKey()) && changeMap.containsKey("contractAmount")) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.CONTRACT_AMOUNT.getKey());
			String contractAmount = changeMap.getOrDefault("contractAmount", "");
			String oldContractAmount = oldValueMap.getOrDefault("contractAmount", "");
			BigDecimal contractAmountBigDecimal = StrUtil.isBlankIfStr(contractAmount) ? BigDecimal.ZERO : new BigDecimal(contractAmount).setScale(2, RoundingMode.HALF_UP);
			BigDecimal oldContractAmountBigDecimal = StrUtil.isBlankIfStr(oldContractAmount) ? BigDecimal.ZERO : new BigDecimal(oldContractAmount).setScale(2, RoundingMode.HALF_UP);
			//获取新旧合同金额差值的绝对值,保留两位小数点
			BigDecimal contractAmountDiff = contractAmountBigDecimal.subtract(oldContractAmountBigDecimal).abs().setScale(2, RoundingMode.HALF_UP);
			ChangeContractFreeformDTO.ChangeDataItem item = new ChangeContractFreeformDTO.ChangeDataItem();
			item.setArticle(changeKeyConfig.getArticle());
			item.setParagraph(changeKeyConfig.getParagraph());
			item.setKey(ChangeKeyEnum.CONTRACT_AMOUNT.getKey());
			item.setContractAmount(contractAmount);
			item.setContractAmountText(new MoneyConvertUtil(contractAmount).convert());
			item.setChangeAmount(contractAmountDiff.toPlainString());
			changeData.add(item);
		}
		//设计费金额
		if (changeKeyList.contains(ChangeKeyEnum.AFTER_DISCOUNT_DESIGNER_AMOUNT.getKey()) && changeMap.containsKey("afterDiscountDesignerAmount")) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.AFTER_DISCOUNT_DESIGNER_AMOUNT.getKey());
			ChangeContractFreeformDTO.ChangeDataItem item = new ChangeContractFreeformDTO.ChangeDataItem();
			item.setArticle(changeKeyConfig.getArticle());
			item.setParagraph(changeKeyConfig.getParagraph());
			item.setKey(ChangeKeyEnum.AFTER_DISCOUNT_DESIGNER_AMOUNT.getKey());
			//设计费应收
			BigDecimal afterDiscountDesignerAmount = new BigDecimal(changeMap.getOrDefault("afterDiscountDesignerAmount", "0"));
			//获取设计费实收应收
			FundInfo designFundInfo = fundInfoService.getFundByOrderIdAndFundType(projectOrderId, FundTypeEnum.DESIGN_CHARGE.getValue());
			if (ObjectUtil.isNotEmpty(designFundInfo)) {
				//设计费待收和待退金额计算
				BigDecimal tobePaidAmount = afterDiscountDesignerAmount.subtract(designFundInfo.getPaidAmount());
				item.setDesignPaidAmount(designFundInfo.getPaidAmount().toPlainString());
				if (tobePaidAmount.compareTo(BigDecimal.ZERO) <= 0) {
					item.setDesignTobePaidAmount(BigDecimal.ZERO.setScale(2, RoundingMode.HALF_UP).toPlainString());
					item.setDesignTobeRefundAmount(tobePaidAmount.abs().setScale(2, RoundingMode.HALF_UP).toPlainString());
				} else {
					item.setDesignTobePaidAmount(tobePaidAmount.setScale(2, RoundingMode.HALF_UP).toPlainString());
					item.setDesignTobeRefundAmount(BigDecimal.ZERO.setScale(2, RoundingMode.HALF_UP).toPlainString());
				}
			}
			item.setAfterDiscountDesignerAmount(afterDiscountDesignerAmount.toPlainString());
			changeData.add(item);
		}


		//收款计划变更
		if (!processV25 && !BusinessTypeEnum.PART_DECORATE.getCode().equals(contract.getBusinessType()) && changeKeyList.contains(ChangeKeyEnum.COLLECTION_PLAN.getKey())) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.COLLECTION_PLAN.getKey());
			CollectionPlanConfigInfo collectionPlanConfigInfo = commonContractService.queryCollectionPlanByContract(contract);
			List<Contract> contractList = contractService.getContractList(contract.getProjectOrderId());
			List<Contract> changeContractList = contractList.stream()
				.filter(m -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(m.getType()) || ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(m.getType()))
				.filter(m -> ContractStatusEnum.FINISH.getCode().equals(m.getStatus())).collect(Collectors.toList());
			Boolean diff = Boolean.TRUE;
			if (CollectionUtil.isNotEmpty(changeContractList)) {
				CollectionPlanConfigInfo collectionPlanConfigInfoPre = commonContractService.queryCollectionPlanByContract(changeContractList.get(0));
				diff = BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType()) ? collectionPlanConfigInfo.diffAmount(collectionPlanConfigInfoPre) : collectionPlanConfigInfo.diff(collectionPlanConfigInfoPre);
				//历史白名单单子，收款计划默认变更
				if (collectionPlanChangeOrderIds.contains(projectOrderId)) {
					diff = Boolean.FALSE;
				}
			}
			if (Boolean.FALSE.equals(diff)) {
				List<CollectionPlanItem> collectionPlanItems = collectionPlanConfigInfo.getContent();
				List<String> collectionPlanStrList = collectionPlanItems.stream().map(CollectionPlanItem::itemShow).collect(Collectors.toList());
				String article = changeKeyConfig.getArticle();
				String paragraph = changeKeyConfig.getParagraph();
				ChangeContractFreeformDTO.ChangeDataItem item = new ChangeContractFreeformDTO.ChangeDataItem();
				item.setArticle(article);
				item.setParagraph(paragraph);
				item.setKey(ChangeKeyEnum.COLLECTION_PLAN.getKey());
				item.setCollectionPlanInfoStr(String.join("<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;", collectionPlanStrList));
				for (int itemFlag = 0; itemFlag < collectionPlanItems.size(); itemFlag++) {
					CollectionPlanItem collectionPlanItem = collectionPlanItems.get(itemFlag);
					if (ObjectUtil.isNotEmpty(collectionPlanItem)) {
						if (itemFlag == 0) {
							item.setFirstPayAmount(collectionPlanItem.getPrice().toString());
							item.setFirstPayAmountText((new MoneyConvertUtil(collectionPlanItem.getPrice().toString())).convert());
						} else if (itemFlag == 1) {
							item.setSecondPayAmount(collectionPlanItem.getPrice().toString());
							item.setSecondPayAmountText((new MoneyConvertUtil(collectionPlanItem.getPrice().toString())).convert());
						} else if (itemFlag == 2) {
							item.setThirdPayAmount(collectionPlanItem.getPrice().toString());
							item.setThirdPayAmountText((new MoneyConvertUtil(collectionPlanItem.getPrice().toString())).convert());
						}
					}
				}
				changeData.add(item);
			}
		}


		//甲供材料
		List<FormalPackageContractFreeformDTO.MaterialItem> materialItemList = new ArrayList<>();
		if (changeMap.containsKey("materialList")) {
			isMaterialList = true;
			List<ContractMaterial> materialList = contractMaterialService.getListByContractCode(contractCode);
			for (ContractMaterial contractMaterial : materialList) {
				String unit = org.apache.commons.lang3.StringUtils.isBlank(contractMaterial.getUnit()) ? "" : "（".concat(contractMaterial.getUnit()).concat("）");
				String description = org.apache.commons.lang3.StringUtils.isBlank(contractMaterial.getDescription()) ? "" : contractMaterial.getDescription();
				materialItemList.add(
					FormalPackageContractFreeformDTO.MaterialItem.builder()
						.description(description.concat(unit))
						.count(contractMaterial.getCount())
						.build()
				);
			}
		}

		changeContent.setIsChangeQuotation(isChangeQuotation);
		changeContent.setIsChangeDiscount(isChangeDiscount);
		changeContent.setIsDecorateRuleUrl(isDecorateRuleUrl);
		String dateStr = DateUtils.getDateStr(new Date());
		changeContent.setDecorateRuleUrl(CollectionUtils.isNotEmpty(decorateRuleUrl) ? decorateRuleUrl : new ArrayList<>());
		changeContent.setBudgetUrl(CollectionUtils.isNotEmpty(budgetUrl) ? budgetUrl
			.stream().map(item -> new ChangeContractFreeformDTO.Photo(item, dateStr)).collect(Collectors.toList()) : new ArrayList<>());
		changeContent.setInternalConfigurationsUrl(CollectionUtils.isNotEmpty(internalConfigurationsUrl) ? internalConfigurationsUrl
			.stream().map(item -> new ChangeContractFreeformDTO.Photo(item, dateStr)).collect(Collectors.toList()) : new ArrayList<>());
		changeContent.setPersonalQuotionUrl(CollectionUtils.isNotEmpty(personalQuotionUrl) ? personalQuotionUrl
			.stream().map(item -> new ChangeContractFreeformDTO.Photo(item, dateStr)).collect(Collectors.toList()) : new ArrayList<>());
		changeContent.setExtraConfigurationsUrl(CollectionUtils.isNotEmpty(extraConfigurationsUrl) ? extraConfigurationsUrl
			.stream().map(item -> new ChangeContractFreeformDTO.Photo(item, dateStr)).collect(Collectors.toList()) : new ArrayList<>());
		changeContent.setBaseConstructionDrawUrl(CollectionUtils.isNotEmpty(baseConstructionDrawUrl) ? baseConstructionDrawUrl
			.stream().map(item -> new ChangeContractFreeformDTO.Photo(item, dateStr)).collect(Collectors.toList()) : new ArrayList<>());
		changeContent.setCoupon(couponDto);

		changeContent.setBudgetPdfUrl(StringUtils.isNotBlank(budgetPdfUrl) ? budgetPdfUrl : "");
		changeContent.setInternalConfigurationsPdfUrl(StringUtils.isNotBlank(internalConfigurationsPdfUrl) ? internalConfigurationsPdfUrl : "");
		changeContent.setExtraConfigurationsPdfUrl(StringUtils.isNotBlank(extraConfigurationsPdfUrl) ? extraConfigurationsPdfUrl : "");
		changeContent.setPersonalQuotionPdfUrl(StringUtils.isNotBlank(personalQuotionPdfUrl) ? personalQuotionPdfUrl : "");
		changeContent.setBaseConstructionDrawPdfUrl(StringUtils.isNotBlank(baseConstructionDrawPdfUrl) ? baseConstructionDrawPdfUrl : "");

		//changeData按照key来排序，排序顺序按照changeKeyList配置的顺序排序
		List<ChangeContractFreeformDTO.ChangeDataItem> sortChangeData = new ArrayList<>();
		for (String changeKey : changeKeyList) {
			for (ChangeContractFreeformDTO.ChangeDataItem item : changeData) {
				if (changeKey.equals(item.getKey())) {
					sortChangeData.add(item);
				}
			}
		}
		changeContent.setChangeData(sortChangeData);

		changeContent.setIsMaterialList(isMaterialList);
		changeContent.setMaterialList(materialItemList);

		String contractObjectType = fieldsMap.get("contractObjectType");
		CertificateTypeEnum certificateTypeEnum = CertificateTypeEnum.getEnumByCode(signatoryUser.getCertificateType());
		String companyName = StringUtils.isNotBlank(firstPartCompanyName) ? firstPartCompanyName : companyInfoDTO.getCompanyName();

		ChangeContractFreeformDTO freeformDTO = ChangeContractFreeformDTO.builder()
			.contractNo(formalContract.getContractNo())
			.contractObjectType(StringUtils.isBlank(contractObjectType) ? null : Byte.valueOf(contractObjectType))
			.certificateType(certificateTypeEnum == null ? null : certificateTypeEnum.getName())
			.companyName(companyName)
			.companyCreditCode(fieldsMap.get("companyCreditCode"))
			.companyAgentName(fieldsMap.get("companyAgentName"))
			.companyAgentCertificateNo(fieldsMap.get("companyAgentCertificateNo"))
			.companyAgentCertificateType(certificateTypeEnum == null ? null : certificateTypeEnum.getName())
			.companyAgentPhone(fieldsMap.get("companyAgentPhone"))
			.jiafangXingming(signatoryUser.getName())
			.firstPartyConnectPhone(cipherService.decrypt(signatoryUser.getPhone()))
			.customerIdNo(cipherService.decrypt(signatoryUser.getCertificateNo()))
			.ownerAddress(fieldsMap.getOrDefault("ownerAddress", "/"))
			.signDate(signDate)
			.dynamicChangeContent(JsonUtil.toJsonString(changeContent))
			.companyAddress(companyInfoDTO.getCompanyAddress())
			.companyPhone(companyInfoDTO.getCompanyPhone())
			.companySealCode(companyInfoDTO.getCompanySealCode())
			.firstPartInfo(getFirstPartInfo(fieldsMap, signatoryUser, owner))
			.secondPartInfo(getSecondPartInfo(companyInfoDTO))
			.build();
		LOGGER.info("协议平台freeformDTO:{}", JSON.toJSONString(freeformDTO));
		return freeformDTO;
	}

