private List<FieldDiffDTO> compareContract(FormalContractExpandInfoDTO prevExpandInfo, FormalContractExpandInfoDTO currentExpandInfo, String projectOrderId, Byte businessType, String changeOrderId) {
	List<FieldDiffDTO> result = new LinkedList<>();
	// 加解密
	//加密
	changeContractService.encryptExpandInfo(prevExpandInfo);
	changeContractService.encryptExpandInfo(currentExpandInfo);
	//签约主体
	result.addAll(changeContractService.compareContractSignObject(prevExpandInfo, currentExpandInfo));
	//业主信息
	result.addAll(changeContractService.compareContractCustomer(prevExpandInfo, currentExpandInfo));
	//代理人
	result.addAll(changeContractService.compareContractAgent(prevExpandInfo, currentExpandInfo));
	//法人信息
	result.addAll(changeContractService.compareContractLegalUser(prevExpandInfo, currentExpandInfo));
	//户型结构
	if (!BusinessTypeEnum.PART_DECORATE.getCode().equals(businessType)) {
		result.addAll(changeContractService.compareContractCnt(prevExpandInfo, currentExpandInfo));
	}
	//其他 - 房屋类型、装修类型、工期、保修约定等
	result.addAll(compareContractOther(prevExpandInfo, currentExpandInfo));

	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
	Integer gbCode = Optional.ofNullable(projectInfoDTO).map(ProjectInfoDTO::getCustomerHouse).map(ProjectCustomerHouseDTO::getGbCode).orElse(null);
	// 北京不 diff 甲供
	if (!ObjectUtil.equal(CityEnum.BEIJING.getGbCode(), gbCode)) {
		//甲供材料
		result.addAll(changeContractService.compareContractMaterial(prevExpandInfo.getMaterialList(), currentExpandInfo.getMaterialList()));
	}
	//相关备件字段
	result.addAll(changeContractService.compareContractAttachFiled(prevExpandInfo, currentExpandInfo));
	//报价信息
	result.addAll(compareContractQuote(projectOrderId, changeOrderId, prevExpandInfo, currentExpandInfo));
	return result;
}

