	private ContractRelationService contractRelationService;

	private static final String HOME_CONTRACT_BUTTON_CONFIG_MODULE_KEY = "homeContractListButtonConfig";
	private static final String AUTH_LIST_CONTRACT_BUTTON_CONFIG = "authListContractButtonConfig";
	private static final String CONTRACT_PREVIEW_BUTTON_CONFIG = "contractPreviewButtonConfig";
	private static final String PC_CONTRACT_BUTTON_CONFIG_MODULE_KEY = "pcContractListButtonConfig";

	@PostConstruct
	public void init() {
		// 初始化自定义函数
		initFunction();
		// 合同列表按钮配置
		initContractListButtonConfig();
		// 授权列表按钮配置
		initAuthListButtonConfig();
		// 合同预览页按钮配置
		initContractPreviewButtonConfig();
		// PC端合同列表按钮配置
		initPcContractButtonConfig();
	}

	@SneakyThrows
	private void initFunction() {
		AviatorEvaluator.importFunctions(ContractFunction.class);
	}

	/**
	 * 合同home列表按钮配置，类型枚举：ContractButtonEnum
	 */
	private void initContractListButtonConfig() {
		// 维度定义
		configService.dimensionalInit(HOME_CONTRACT_BUTTON_CONFIG_MODULE_KEY, ContractButtonDimensional.class);

		// key: 合同类型_按钮类型 value：表达式
		HashMap<String, String> normalRouteMap = new HashMap<>();
		HashMap<String, String> routeMap = new HashMap<>();

		// 通用合同规则
		normalRouteMap.put("*_1", "contractStatus != 1 && contractStatus != 10 && hasContractAgreement");
		normalRouteMap.put("*_2", "contractStatus == 1");
		normalRouteMap.put("*_3", "include(seq.list(2,4,5,6), contractStatus) && ContractFunction.showUndoButton(contractCode,userConfirmNodeList)");
		normalRouteMap.put("*_4", "contractStatus == 3");
		normalRouteMap.put("*_5", "string.length(bpmNo) > 0 && include(seq.list(6,7,8), contractStatus)");
		normalRouteMap.put("*_6", "contractStatus == 1");
		normalRouteMap.put("*_7", "contractStatus != 1 && contractStatus != 10");
		// 认购、首期款合同有上一份已完成的合同展示去重签按钮
