	/**
	 * 获取合同预览页按钮配置
	 */
	public List<ButtonItemVo> getPreviewButtonList(Contract contract, Contract authAgentContract) {
		// 匹配参数
		Byte contractObjectType = contractFieldService.getContractObjectType(contract.getContractCode());
		Boolean companyOnlineSign = ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType) && SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType());
		Integer relateAccreditContractStatus = null;
		if (!StringUtils.isBlank(contract.getRelateContractCode())) {
			Contract relateAccreditContract = contractService.getByContractCode(contract.getRelateContractCode());
			relateAccreditContractStatus = relateAccreditContract.getStatus();
		}

		ContractPreviewButtonExecParam execParams = ContractPreviewButtonExecParam.builder()
			.contractType(contract.getType())
			.contractStatus(contract.getStatus())
			.companyOnlineSign(companyOnlineSign)
			.relateAccreditContractStatus(relateAccreditContractStatus)
			.relateAuthAgentContractStatus(Optional.ofNullable(authAgentContract).map(Contract::getStatus).orElse(null))
			.build();

		// 遍历所有按钮类型，根据配置判断是否显示
		Map<Integer, String> contractPreviewButtonTypes = ContractButtonEnum.getContractPreviewButtonTypes();
		List<ButtonItemVo> buttonItemVoList = new ArrayList<>();
		for (Map.Entry<Integer, String> entry : contractPreviewButtonTypes.entrySet()) {
			Integer buttonType = entry.getKey();
			String buttonName = entry.getValue();
			ContractButtonDimensional dimensional = ContractButtonDimensional.builder().buttonType(buttonType).build();
			if (Boolean.TRUE.equals(configService.getBooleanResult(CONTRACT_PREVIEW_BUTTON_CONFIG, dimensional, execParams))) {
				ButtonItemVo buttonItemVo = ButtonItemVo.builder()
					.type(buttonType)
					.name(buttonName)
					.build();
				// 填充schema、icon信息
				fillPreviewButtonItemInfo(buttonItemVo, contract.getProjectOrderId(), contract.getType());
				buttonItemVoList.add(buttonItemVo);
			}
		}

		return buttonItemVoList;
	}

	private void fillPreviewButtonItemInfo(ButtonItemVo buttonItemVo, String projectOrderId, Byte contractType) {
		if (buttonItemVo.getType().equals(ContractButtonEnum.UNDO.getType())) {
			String recallSchema = String.format(contractApolloConfig.getRecallSchema(), projectOrderId, contractType);
			buttonItemVo.setSchema(commonApolloConfig.getStewardDomain() + recallSchema);
			buttonItemVo.setIconUrl("https://img.ljcdn.com/utopia-file/b58a9936-b5d7-4e23-bde5-240282a7de5b.png");
		}
	}

	/**
	 * 获取schema
	 *
	 * @param buttonType 按钮类型
	 * @return schema
	 */
	public String getSchema(Integer buttonType, String contractCode) {
		if (buttonType == null) {
			return null;
		}

		if (ContractButtonEnum.VIEW.getType().equals(buttonType)) {
			return getAuthViewSchema(contractCode);
		} else if (ContractButtonEnum.SIGN.getType().equals(buttonType)) {
			return getSignSchema(contractCode);
		} else if (ContractButtonEnum.AUTH.getType().equals(buttonType)) {
			return getAuthSchema(contractCode);
		}

		return null;
	}

