	public void generateAccreditContract(Contract contract) {
		// 不需要生成授权协议书直接返回
		LOGGER.info("--授权协议-->开始生成授权协议:{}", contract.getContractCode());
		if (Boolean.FALSE.equals(needGenerateAccreditContract(contract))) {
			return;
		}
		/**
		 * 一个项目下同一个法人/代理人签约，我方主体不变的情况下，在规定场景下只需要授权一次
		 * 1、根据项目单号查询所有授权协议列表
		 * 2、当前主合同分公司和授权协议分公司对比
		 * 	  主合同的法人与授权协议的法人、主合同的签约人和授权协议对应合同的签约人对比（法人相同 + 法人授权给的签约人也相同）
		 * 3、都相同则只要关联授权协议就可以，否则需要生成授权协议
		 */
		Contract resAccreditContract = null;
		Contract existCanRelatedAcreditContract = getExistCanRelatedAcreditContract(contract);
		LOGGER.info("--授权协议-->是否复用授权协议:{}{}",contract.getContractCode(), existCanRelatedAcreditContract);
		if (existCanRelatedAcreditContract != null) {
			// 不用生成，已存在的授权协议直接使用
			resAccreditContract = existCanRelatedAcreditContract;
		} else {
			// 重新生成新的授权协议书
			ContractReqDTO contractReq = buildContractSubmitReq(contract);
			HeaderContext.getContext().setOperatorUcId(contract.getModifyUserId());
			ContractSubmitResDTO submitResDTO = contractSubmitService.submit(contractReq);
			resAccreditContract = contractService.getByContractCode(submitResDTO.getContractCode());
			//将主合同主体关联到授权协议书主体
			Contract accreditContract = contractService.getByContractCode(submitResDTO.getContractCode());
			accreditContract.setCompanyCode(contract.getCompanyCode());
			contractService.update(accreditContract);
		}

		// 重新查询下关联合同最新状态，如果主合同被撤回到草稿中，不是待签署，无需关联
		contract = contractService.getByContractCode(contract.getContractCode());
		if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			LOGGER.info("{}合同状态为草稿，不需要关联授权协议书", contract.getContractCode());
			return;
		}

		// 主合同关联授权协议, 授权协议：主合同 = 1: n
		contractService.update(Contract.builder().id(contract.getId()).relateContractCode(resAccreditContract.getContractCode()).build());
		// 如果有关联合同，关联合同都同时关联该授权协议
		List<ContractRelation> relatedContracts = contractRelationService.getRelationList(contract.getContractCode());
		if (CollectionUtils.isNotEmpty(relatedContracts)) {
			contractService.updateRelatedContractCode(relatedContracts.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList()),
				resAccreditContract.getContractCode());
		}
		// 授权协议关联主合同 todo 确定其他使用到的地方是否需要改 @xinmingquan
		//contractService.update(Contract.builder().id(resAccreditContract.getId()).relateContractCode(contract.getContractCode()).build());

		try {
			//如果重新生成新的授权协议书需要发送短信
			if (existCanRelatedAcreditContract == null) {
				sendMessage(resAccreditContract.getContractCode());
			}
		} catch (Exception e) {
			LOGGER.error("授权协议书发起之后发送短信给法人发生异常,contractCode:{},contractType:{}", contract.getContractCode(), contract.getType(), e);
		}
	}

	/**
	 * 判断是否需要生成授权协议书
	 * @param contract
	 * @return
	 */
	private Boolean needGenerateAccreditContract(Contract contract) {
		if (contract == null) {
			return false;
		}
		//线上签约&对公才需要生成授权协议书
		if (!SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
			return false;
		}
		// 只有需要单独生成授权协议的主合同类型：正签合同、个性化合同、首期款合同、变更合同、设计合同、设计变更合同，图纸合同是协同发起外层单独走协同发起逻辑
		if(!ContractTypeEnum.needRelateAccreditContractTypes().contains(contract.getType())) {
			return false;
		}
		// C合同需要判断是单独发起，还是协同发起，如果协同发起返回false，外层走单独协同发起逻辑
		ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
		if (contractRelation != null) {
			return false;
		}
		Byte contractObjectType = contractFieldService.getContractObjectType(contract.getContractCode());
		if (!ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
			return false;
		}
		// 无协议变更无需生成授权协议书
		if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType()) && contract.getPlatformInstanceId() == 0) {
			LOGGER.info("无协议变更无需生成授权协议书");
			return false;
		}
		return true;
	}

	/**
	 * 当前主合同分公司和授权协议分公司对比
	 * 主合同的法人与授权协议的法人、主合同的法人和授权协议的法人对比（法人相同 + 法人授权给的签约人也相同，授权协议的contractUser等于主合同的contractUser）
	 * 都相同才认为不用再生成，可直接关联授权协议
	 * @param mainContract
	 * @return
	 */
	private Contract getExistCanRelatedAcreditContract(Contract mainContract) {
		// 获取主合同信息: 法人、代理人、甲方分公司、乙方分公司
		if (mainContract == null) {
			return null;
		}
		List<ContractUser> mainContractUserList = contractUserService.getListByContractCode(mainContract.getContractCode());
		ContractUser mainLegalUser = mainContractUserList.stream().filter(item -> item.getRoleType().equals(RoleTypeEnum.LEGAL.getCode())).findFirst()
			.orElseThrow(() -> new NrsBusinessException("对公合同法人为空" + mainContract.getContractCode()));
		ContractUser mainCompanyAgentUser = mainContractUserList.stream().filter(item -> item.getRoleType().equals(RoleTypeEnum.COMPANY_AGENT.getCode())).findFirst().orElseThrow(null);
		ContractField contractObjectTypeField = contractFieldService.getByContractCodeAndKey(mainContract.getContractCode(), "companyCreditCode");
		String companyCreditCode = Objects.isNull(contractObjectTypeField) ? "" : contractObjectTypeField.getFieldValue();

		// 获取项目下所有授权协议： 法人、代理人、甲方分公司、乙方分公司
		List<Contract> accreditContractList = contractService.getContractList(mainContract.getProjectOrderId(), ContractTypeEnum.ACCREDIT.getCode());
		accreditContractList = accreditContractList.stream()
			.filter(item -> ContractStatusEnum.inPositiveStatus.contains(item.getStatus()))
			.collect(Collectors.toList());
		if (CollectionUtils.isEmpty(accreditContractList)) {
			return null;
		}
		List<ContractUser> accrediteUserList = contractUserService.getListByContractCodes(accreditContractList.stream().map(Contract::getContractCode).collect(Collectors.toList()));
		Map<String, Contract> accreditContractMap = accreditContractList.stream().collect(Collectors.toMap(Contract::getContractCode, Function.identity()));
		Map<String, List<ContractUser>> accreditContractUserMap = accrediteUserList.stream().collect(Collectors.groupingBy(ContractUser::getContractCode));

		List<String> accreditCodeList = accreditContractList.stream().map(Contract::getContractCode).collect(Collectors.toList());
		List<ContractField> accreditContractFields = contractFieldService.getValueByContractCodeAndFieldKey(accreditCodeList, "companyCreditCode");
		Map<String, String> accreditCompanyCreditCodeMap = accreditContractFields.stream().collect(Collectors.toMap(ContractField::getContractCode, ContractField::getFieldValue, (k1, k2) -> k2));

		// 主合同的法人与授权协议的法人、主合同的法人和授权协议的法人都相同，则可以直接关联已有的授权协议
		for (Map.Entry<String, List<ContractUser>> entry : accreditContractUserMap.entrySet()) {
			Contract accreditContract = accreditContractMap.get(entry.getKey());
			LOGGER.info("主合同code：{},主合同分公司：{}, 主合同对公分公司名称：{}, 授权协议code：{}, 授权协议分公司：{}, 授权协议对公分公司名称：{}",
				mainContract.getContractCode(), mainContract.getCompanyCode(), companyCreditCode,
				accreditContract.getContractCode(), accreditContract.getCompanyCode(), accreditCompanyCreditCodeMap.get(accreditContract.getContractCode()));
			//主合同和授权协议的乙方分公司不相同，不能关联
			if (!mainContract.getCompanyCode().equals(accreditContract.getCompanyCode())) {
				continue;
			}
			//主合同和授权协议的甲方分公司不相同，不能关联
			if (!StringUtils.deleteWhitespace(companyCreditCode).equals(StringUtils.deleteWhitespace(accreditCompanyCreditCodeMap.get(accreditContract.getContractCode())))) {
				continue;
			}
			//主合同和授权合同的roleType相同&&证件号都相同，则返回该授权协议
			ContractUser accreditLegalUser = entry.getValue().stream().filter(item -> item.getRoleType().equals(RoleTypeEnum.LEGAL.getCode()))
				.findFirst().orElseThrow(() -> new NrsBusinessException("对公合同法人为空" + accreditContract.getContractCode()));
			ContractUser accreditCompanyAgentUser = entry.getValue().stream().filter(item -> item.getRoleType().equals(RoleTypeEnum.COMPANY_AGENT.getCode())).findFirst().orElseThrow(null);

			LOGGER.info("--授权协议-->主合同法人信息：{}主合同代理人信息{}, 授权协议法人{},授权协议代理人{}", mainLegalUser, mainCompanyAgentUser, accreditLegalUser, accreditCompanyAgentUser);

			// 法人不同：不能复用
			if (!StringUtils.deleteWhitespace(mainLegalUser.getCertificateNo()).equals(StringUtils.deleteWhitespace(accreditLegalUser.getCertificateNo()))) {
				continue;
			}
			// 法人相同&&没有代理人可以复用授权协议
			if (mainCompanyAgentUser == null && accreditCompanyAgentUser == null) {
				return accreditContract;
			}
			// 存在代理人并且两者代理人都相同可以复用授权协议
			if (mainCompanyAgentUser != null && accreditCompanyAgentUser != null &&
				StringUtils.deleteWhitespace(mainCompanyAgentUser.getCertificateNo()).equals(StringUtils.deleteWhitespace(accreditCompanyAgentUser.getCertificateNo()))) {
				return accreditContract;
			}
		}
		return null;
	}

	/**
	 * 构造授权协议书请求参数
	 */
	private ContractReqDTO buildContractSubmitReq(Contract contract) {
		ContractUser legalUser = contractUserService.getLatestUserByRole(contract.getContractCode(), RoleTypeEnum.LEGAL.getCode());
		ContractUser companyAgentUser = contractUserService.getLatestUserByRole(contract.getContractCode(), RoleTypeEnum.COMPANY_AGENT.getCode());
		Map<String, String> contractFieldMap = contractFieldService.getFieldMap(contract.getContractCode());

		return ContractReqDTO.builder()
			.contractBaseInfo(ContractBaseInfoReq.builder()
				.projectOrderId(contract.getProjectOrderId())
				.contractType(ContractTypeEnum.ACCREDIT.getCode())
				.submitCompanyCode(contract.getCompanyCode())
				.build())
			.signInfo(ContractSignInfoReq.builder()
				.contractObjectType(ContractObjectTypeEnum.COMPANY.getCode())
				.signChannelType(SignChannelTypeEnum.ONLINE.getCode())
				.userSignType(UserSignTypeEnum.SIGN.getCode())
				.companyName(contractFieldMap.get("companyName"))
				.companyCreditCode(contractFieldMap.get("companyCreditCode"))
				.registeredAddress(contractFieldMap.get("registeredAddress"))
				.signCompanyCode(contract.getCompanyCode())
				.signRole(RoleTypeEnum.LEGAL.getCode())
				.legalName(legalUser.getName())
				.legalPhone(legalUser.getPhone())
				.legalCertificateType(legalUser.getCertificateType())
				.legalCertificateNo(legalUser.getCertificateNo())
				.companyAgentName(Optional.ofNullable(companyAgentUser).map(ContractUser::getName).orElse(null))
				.companyAgentPhone(Optional.ofNullable(companyAgentUser).map(ContractUser::getPhone).orElse(null))
				.companyAgentCertificateType(Optional.ofNullable(companyAgentUser).map(ContractUser::getCertificateType).orElse(null))
				.companyAgentCertificateNo(Optional.ofNullable(companyAgentUser).map(ContractUser::getCertificateNo).orElse(null))
				.build())
			.projectInfo(ContractProjectInfoReq.builder()
				.businessType(contract.getBusinessType())
				.gbCode(Integer.valueOf(contractFieldMap.get("gbCode")))
				.gbName(contractFieldMap.get("gbName"))
				.districtName(contractFieldMap.get("districtName"))
				.resblockName(contractFieldMap.get("resblockName"))
				.buildingName(contractFieldMap.get("buildingName"))
				.unitName(contractFieldMap.get("unitName"))
				.floorName(contractFieldMap.get("floorName"))
				.houseName(contractFieldMap.get("houseName"))
				.build())
			.businessInfo(BusinessInfoDetail.builder()
				.decorateType(contract.getBusinessType().toString())
				.build())
			.build();
	}

	/**
	 * 获取授权列表
	 */
	@Deprecated
	public ContractAuthListResDTO getContractAuthList(String projectOrderId) {
		// 合同列表
		List<Contract> contractList = contractService.getContractList(projectOrderId)
			.stream().filter(contract -> !ContractTypeEnum.ACCREDIT.getCode().equals(contract.getType()))
			.filter(contract -> !ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus()))
			.filter(contract -> StringUtils.isNoneBlank(contract.getRelateContractCode())).collect(Collectors.toList());

		// 授权合同列表
		Map<String, Contract> relateContractCodeMap = contractList.stream().collect(Collectors.toMap(Contract::getRelateContractCode, Function.identity(), (k1, k2) -> k2));
		List<Contract> accreditContractList = contractService.getContractList(projectOrderId, ContractTypeEnum.ACCREDIT.getCode());
		accreditContractList = accreditContractList.stream()
			.filter(contract -> relateContractCodeMap.containsKey(contract.getContractCode())).collect(Collectors.toList());

		// 提示无合同 返回项目地址
		if (CollectionUtils.isEmpty(contractList) || CollectionUtils.isEmpty(accreditContractList)) {
			ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
			if (Objects.isNull(projectInfoDTO)) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "项目单号不存在", Level.WARN);
			}
			String address = homeAndPcCommonService.getSafeAddress(projectInfoDTO);
			return ContractAuthListResDTO.builder()
				.projectOrderId(projectOrderId)
				.address(address)
				.build();
		}

		// 获取用户信息
		CUserDTO userDTO = userFeignService.getUserInfo(HeaderContext.getUserId().toString());
		String loginPhone = cipherService.encrypt(userDTO.getPhone());

		List<ContractUser> contractUserList = contractUserService.getListByContractCodes(new ArrayList<>(relateContractCodeMap.keySet()));
		Map<String, List<ContractUser>> contractUserMap = contractUserList.stream().collect(Collectors.groupingBy(ContractUser::getContractCode));
		// 过滤仅登录人可见的合同
		List<Contract> visibleContractList = accreditContractList.stream().filter(contract -> {
			List<ContractUser> userList = contractUserMap.get(contract.getContractCode());
			if (CollectionUtils.isEmpty(userList)) {
				return false;
			}
			return userList.stream().anyMatch(user -> RoleTypeEnum.LEGAL.getCode().equals(user.getRoleType()) && user.getPhone().equals(loginPhone));
		}).collect(Collectors.toList());

		// 可查看的合同为空，返回有权限查看的手机号，请尝试用以下手机号打开：*******5176、*******5888
		if (CollectionUtils.isEmpty(visibleContractList)) {
			String phones = contractUserList.stream().filter(user -> RoleTypeEnum.LEGAL.getCode().equals(user.getRoleType()))
				.map(ContractUser::getPhone)
				.map(DesensitizationUtils::getDesensitizedPhone)
				.distinct().collect(Collectors.joining("、"));
			throw new NrsBusinessException(ResponseCodeEnum.USER_AUTH_ERROR.getCode(), "请尝试用以下手机号打开：" + phones, Level.WARN);
		}

		// 登录手机号作为签约人的合同code列表
		List<String> contractCodeListBySignerPhone = contractUserService.getContractCodeListBySignerPhone(loginPhone);
		List<ContractNode> accreditContractNodes = contractNodeService.getListByContractCodesAndType(visibleContractList.stream().map(Contract::getContractCode).collect(Collectors.toList()),
			Collections.singletonList(NodeTypeEnum.FINISH.getCode()));
		Map<String, Long> contractAuthTimeMap = accreditContractNodes.stream().collect(Collectors.toMap(ContractNode::getContractCode, ContractNode::getFireTime, (k1, k2) -> k2));

		List<ContractAuthListResDTO.ContractItemVo> contractItemVoList = new ArrayList<>();
		for (Contract accreditContract : visibleContractList) {
			Contract contract = relateContractCodeMap.get(accreditContract.getContractCode());
			String contractName = ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(),contract.getBusinessType());
			ContractAuthListResDTO.ContractItemVo contractItemVo = ContractAuthListResDTO.ContractItemVo.builder()
				.contractName(contractName)
				.contractCode(accreditContract.getContractCode())
				.status(accreditContract.getStatus())
				.statusText(ContractStatusEnum.getAccreditStatusText(accreditContract.getStatus()))
				// 是否为签约人
				.buttonList(contractButtonConfigService.getAuthListContractButtonList(accreditContract.getContractCode(), contract.getContractCode(),
					accreditContract.getStatus(), contractCodeListBySignerPhone.contains(contract.getContractCode())))
				.fieldList(Collections.singletonList(ContractAuthListResDTO.FieldItemVo.builder()
					.fieldName("授权完成时间")
					.fieldValue(contractAuthTimeMap.containsKey(accreditContract.getContractCode()) ? DateUtils.getDateTimeStr(new Date(contractAuthTimeMap.get(accreditContract.getContractCode()))) : "-")
					.build()))
				.build();
			contractItemVoList.add(contractItemVo);
		}

		return ContractAuthListResDTO.builder()
			.projectOrderId(projectOrderId)
			.contractList(contractItemVoList)
			.build();
	}

	/**
	 * 手机号查contract_user = 登录人 & 合同类型=授权协议
	 * @param projectOrderId
	 * @param ucId
	 * @return
	 */
	public ContractAuthListResDTO getAccreditContractList(String projectOrderId, Long ucId) {
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		if (Objects.isNull(projectInfoDTO)) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "项目单号不存在", Level.WARN);
		}
		String address = homeAndPcCommonService.getSafeAddress(projectInfoDTO);
		ContractAuthListResDTO authList = ContractAuthListResDTO.builder()
			.address(address)
			.projectOrderId(projectOrderId)
			.build();
		// 获取所有非取消的授权协议
		List<Contract> accreditContractList = contractService.getContractList(projectOrderId, ContractTypeEnum.ACCREDIT.getCode());
		accreditContractList = accreditContractList.stream()
			.filter(item -> ContractStatusEnum.inPositiveStatus.contains(item.getStatus()))
			.collect(Collectors.toList());
		if (CollectionUtils.isEmpty(accreditContractList)) {
			return authList;
		}
		// 获取登陆人作为签署人的授权协议
		CUserDTO userDTO = userFeignService.getUserInfo(ucId.toString());
		String loginPhone = cipherService.encrypt(userDTO.getPhone());
		List<ContractUser> signUserList = contractUserService.getContractListBySignerPhone(loginPhone);
		if (CollectionUtils.isEmpty(signUserList)) {
			return authList;
		}
		accreditContractList = accreditContractList.stream().filter(contract -> signUserList.stream().anyMatch(user -> user.getContractCode().equals(contract.getContractCode()))).collect(Collectors.toList());
		if (CollectionUtils.isEmpty(accreditContractList)) {
			return authList;
		}
		// 组装授权协议的信息
		List<ContractAuthListResDTO.ContractItemVo> contractItemVoList = new ArrayList<>();
		for (Contract contract : accreditContractList) {
			ContractCompanyInfo companyInfo = contractCompanyInfoService.getByCompanyCode(contract.getCompanyCode());
			String salesCompanyName = Optional.ofNullable(companyInfo).map(ContractCompanyInfo::getCompanyName).orElse("");
			if (StringUtils.isBlank(salesCompanyName)) {
				LOGGER.error("授权协议[{}]的乙方公司名称为空", contract.getContractCode());
			}
			ContractAuthListResDTO.ContractItemVo contractItemVo = ContractAuthListResDTO.ContractItemVo.builder()
				.contractName("公对公签约认证授权")
				.contractCode(contract.getContractCode())
				.status(contract.getStatus())
				.statusText(ContractStatusEnum.getAccreditStatusTextCustomerList(contract.getStatus()))
				.companyCode(contract.getCompanyCode())
				.companyName(salesCompanyName)
				.fieldList(getAccreditFieldList(contract))
				.buttonList(getAccreditCustomerListButtonList(contract.getContractCode(), contract.getStatus()))
				.build();
			contractItemVoList.add(contractItemVo);
		}
		authList.setContractList(contractItemVoList);
		return authList;
	}

	/**
	 * C端授权列表：展示标题下的字段信息，以key value的形式展示，前端直接渲染
	 * @param accreditContract
	 * @return
	 */
	private List<ContractAuthListResDTO.FieldItemVo> getAccreditFieldList(Contract accreditContract) {
		List<ContractAuthListResDTO.FieldItemVo> fieldList = new ArrayList<>();
		Integer authStatus = homeAndPcCommonService.getAuthStatus(accreditContract.getContractCode());
		if (!ContractAuthStatusEnum.getNeedAuthStatus().contains(authStatus)) {
			return fieldList;
		}
		// 获取授权协议关联的主合同的签约人
		Contract mainContract = contractService.getRelContractByAccreditContractCode(accreditContract.getContractCode());
		if (Objects.isNull(mainContract)) {
			LOGGER.error("授权协议[{}]未关联主合同", accreditContract.getContractCode());
			return fieldList;
		}
		ContractUser signer = contractUserService.getSignerByContractCode(mainContract.getContractCode());
		String signerName = Optional.ofNullable(signer).map(ContractUser::getName).orElse("");
		if (StringUtils.isBlank(signerName)) {
			LOGGER.error("主合同[{}]的签约人为空", mainContract.getContractCode());
		}
		fieldList.add(ContractAuthListResDTO.FieldItemVo.builder()
			.fieldName("企业实名认证")
			.fieldValue(Boolean.TRUE.equals(ContractAuthStatusEnum.isAuthentication(authStatus)) ? "已认证" : "未认证")
			.build());
		fieldList.add(ContractAuthListResDTO.FieldItemVo.builder()
			.fieldName(String.format("授权给签约人%s", signerName))
			.fieldValue(Boolean.TRUE.equals(ContractAuthStatusEnum.isAuthorized(authStatus)) ? "已授权" : "未授权")
			.build());
		return fieldList;
	}

	/**
	 * 只有一个按钮逻辑，后续如果增多走配置化 contractButtonConfigService
	 */
	private List<ButtonItemVo> getAccreditCustomerListButtonList(String accreditCode, Integer accreditStatus) {
		List<ButtonItemVo> buttonList = new ArrayList<>();
		if (ContractStatusEnum.FINISH.getCode().equals(accreditStatus)) {
			buttonList.add(ButtonItemVo.builder()
				.type(ContractButtonEnum.VIEW.getType())
				.name(ContractButtonEnum.VIEW.getName())
				.schema(contractButtonConfigService.getSchema(ContractButtonEnum.VIEW.getType(), accreditCode))
				.build());
			return buttonList;
		} else {
			buttonList.add(ButtonItemVo.builder()
				.type(ContractButtonEnum.AUTH.getType())
				.name("去认证授权")
				.schema(contractButtonConfigService.getSchema(ContractButtonEnum.AUTH.getType(), accreditCode))
				.build());
		}
		return buttonList;
	}

	/**
	 * 获取授权信息
	 */
	public ContractAuthResDTO getContractAuthInfo(String contractCode) {
		Contract accreditContract = contractService.getByContractCode(contractCode);

		if (accreditContract == null || !ContractTypeEnum.ACCREDIT.getCode().equals(accreditContract.getType())) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "合同不存在，请检查合同编号或联系客服", Level.WARN);
		}

		// 查询项目地址信息
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(accreditContract.getProjectOrderId());
		if (Objects.isNull(projectInfoDTO)) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "项目单号不存在", Level.ERROR);
		}
		String address = homeAndPcCommonService.getAddress(projectInfoDTO);

		// 查询签约用户信息
		Contract contract = contractService.getRelContractByAccreditContractCode(contractCode);
		if (contract == null) {
			LOGGER.error("授权协议书关联合同查询失败，contractCode:{}", contractCode);
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "合同不存在，请检查合同编号或联系客服", Level.WARN);
		}

		ContractUser contractUser = contractUserService.getSignerByContractCode(contract.getContractCode());
		if (contractUser == null) {
			LOGGER.error("授权协议书关联合同查询签约人信息失败，contractCode:{}", contract.getContractCode());
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "合同签约人不存在", Level.WARN);
		}

		// 获取用户信息
		CUserDTO userDTO = userFeignService.getUserInfo(HeaderContext.getUserId().toString());
		String loginPhone = cipherService.encrypt(userDTO.getPhone());
		Boolean isSignatory = Objects.equals(cipherService.decrypt(contractUser.getPhone()), loginPhone);

		// 越权校验 只能看自己的合同
		ContractUser accreditUser = contractUserService.getSignerByContractCode(contractCode);
		String contractUserPhone = cipherService.encrypt(accreditUser.getPhone());
		if (!loginPhone.equals(accreditUser.getPhone())) {
			throw new NrsBusinessException(ResponseCodeEnum.USER_AUTH_ERROR.getCode(), "请尝试用以下手机号打开：" + DesensitizationUtils.getDesensitizedPhone(contractUserPhone), Level.WARN);
		}

		return ContractAuthResDTO.builder()
			.projectOrderId(accreditContract.getProjectOrderId())
			.address(address)
			.authPass(ContractStatusEnum.FINISH.getCode().equals(accreditContract.getStatus()))
			.contractUrl(homeAndPcCommonService.getContractUrl(accreditContract))
			.signatoryName(contractUser.getName())
			.signatoryPhone(DesensitizationUtils.getDesensitizedPhone(contractUser.getPhone()))
			.isSignatory(isSignatory)
			.relateContractCode(contract.getContractCode())
			.relateContractTypeName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(),contract.getBusinessType()))
			.relateContractSignUrl(contractButtonConfigService.getSignSchema(contract.getContractCode()))
			.build();
	}


	/**
	 * 发送短信
	 * @param accreditContractCode 授权协议书合同code
	 */
	private void sendMessage(String accreditContractCode) {
		LOGGER.info("【短信提醒】授权协议书发起之后发送短信给法人，开始发送短信,accreditContractCode：{}", accreditContractCode);
		Contract contract = contractService.getByContractCode(accreditContractCode);
		Contract relContract = contractService.getRelContractByAccreditContractCode(contract.getContractCode());
		if (relContract == null) {
			LOGGER.error("授权协议书发起之后发送短信给法人失败，未找到关联合同,contractCode：{}", contract.getContractCode());
			return;
		}
		if (ContractTypeEnum.DRAWING.getCode().equals(relContract.getType())) {
			//施工套餐合同单独发送短信
			return;
		}
		if (ContractTypeEnum.PERSONAL.getCode().equals(relContract.getType())) {
			//只有【变更发起的公对公个性化合同】or【单独发起的个性化合同】发送短信
			if ((StringUtils.isBlank(relContract.getChangeOrderId()) && !homeAndPcCommonService.isMultipleQuotePersonalContract(relContract))) {
				LOGGER.info("【短信提醒】授权协议书发起之后发送短信给法人，当前个性化合同授权协议书不需要发送短信,contractCode：{}", contract.getContractCode());
				return;
			}
		}
		MiniPayChannelAppNameEnum miniPayChannelAppNameEnum = commonBusinessService.getMiniProgramType(contract.getProjectOrderId());
		//获取项目信息
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(contract.getProjectOrderId());
		//获取手机号信息
		List<ContractUser> contractUsers = contractUserService.getListByContractCode(contract.getContractCode());
		ContractUser contractUser = contractUsers.stream().filter(m -> RoleTypeEnum.LEGAL.getCode().equals(m.getRoleType())).findFirst().orElse(null);
		if (ObjectUtil.isNull(contractUser)) {
			LOGGER.error("【短信提醒】授权协议书发起之后发送短信给法人失败，原因：获取法人信息失败,contractCode：{}", contract.getContractCode());
			return;
		}
		String phone = cipherService.decrypt(contractUser.getPhone());
		if (ObjectUtil.isEmpty(phone)) {
			LOGGER.error("【短信提醒】授权协议书发起之后发送短信给法人失败，原因：获取签约人信息失败,contractCode：{}", contract.getContractCode());
			return;
		}
		//获取短信模板
		String invitationAuthorizeSMSTemplate = apolloConfigService.getInvitationAuthorizeSMSTemplate(miniPayChannelAppNameEnum);
		//获取短链
		String urlLink = payServiceRpc.getUrlLink(ReminderScenarioTypeEnum.INVITATION_AUTHORIZE.getValue(), miniPayChannelAppNameEnum.getMiniProgramType(), contract.getProjectOrderId());
		//获取短信动态字段
		Map<String, String> content = getContent(relContract, projectInfoDTO, urlLink);
		//构建短信内容
		ReminderContextDTO reminderContextDTO = ReminderContextDTO.builder()
			.phone(phone)
			.content(content)
			.template(invitationAuthorizeSMSTemplate)
			.source(Constant.DOMAIN_EVENT_SERVER_NAME)
			.build();
		//获取发送短信时项目快照信息
		BusinessSnapshotDTO businessSnapshotDTO = getBusinessSnapshotDTO(contract, projectInfoDTO);
		//发送短信
		PaySignReminderCreateReqDTO paySignReminderCreateReqDTO = PaySignReminderCreateReqDTO.builder()
			.projectOrderId(contract.getProjectOrderId())
			.reminderType(ReminderTypeEnum.SMS.getValue())
			.scenarioType(ReminderScenarioTypeEnum.INVITATION_AUTHORIZE.getValue())
			.reminderContext(JSON.toJSONString(reminderContextDTO))
			.businessSnapshot(JSON.toJSONString(businessSnapshotDTO))
			.reminderTime(new Date())
			.build();
		LOGGER.info("【短信提醒】授权协议书发起之后发送短信给法人，请求参数：{}", JSON.toJSONString(paySignReminderCreateReqDTO));
		payServiceRpc.sendSmsMessage(paySignReminderCreateReqDTO);
		LOGGER.info("【短信提醒】授权协议书发起之后发送短信给法人成功");
	}


	/**
	 * 获取要发送短信的合同名称列表
	 *
	 * @param contract 授权协议书关联的合同
	 * @return
	 */
	private List<String> getSentContractTypeNameList(Contract contract) {
		List<String> sentContractTypeNameList = new ArrayList<>();
		if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
			sentContractTypeNameList.add(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(),contract.getBusinessType()));
			return sentContractTypeNameList;
		}
		ContractCityCompanyInfo config =contractCityCompanyConfigService.getConfig(contract);
		 // todo 改为查关联合同
		if (StringUtils.isBlank(config.getMergeLaunchType())) {
			sentContractTypeNameList.add(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(),contract.getBusinessType()));
			return sentContractTypeNameList;
		}
		//从配置获取与当前合同合并发起的合同类型
		List<String> contractTypeList = new ArrayList<>(Arrays.asList(config.getMergeLaunchType().split(",")));
		Contract personalContractInfo = contractService.getContractInfo(contract.getProjectOrderId(), ContractTypeEnum.PERSONAL.getCode());
		if (personalContractInfo == null || homeAndPcCommonService.isMultipleQuotePersonalContract(personalContractInfo)) {
			contractTypeList = contractTypeList.stream().filter(contractType -> !contractType.equals(ContractTypeEnum.PERSONAL.getCode().toString()))
				.collect(Collectors.toList());
		}
		sentContractTypeNameList.add(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(),contract.getBusinessType()));
		for (String contractType : contractTypeList) {
			sentContractTypeNameList.add(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(),contract.getBusinessType()));
		}
		return sentContractTypeNameList;
	}

	private Map<String, String> getContent(Contract relContract, ProjectInfoDTO projectInfoDTO, String urlLink) {
		//要发送短信的合同名称
		List<String> sentContractTypeNameList = getSentContractTypeNameList(relContract);
		Map<String, String> content = new HashMap<>();
		content.put("contractName", String.join("+", sentContractTypeNameList));
		content.put("address", homeAndPcCommonService.getEncryptedAddress(projectInfoDTO));
		content.put("jumpLink", urlLink);
		return content;
	}

	public BusinessSnapshotDTO getBusinessSnapshotDTO(Contract contract, ProjectInfoDTO projectInfoDTO) {
		return BusinessSnapshotDTO.builder()
			.projectOrderId(projectInfoDTO.getProjectOrderId())
			.projectAddress(homeAndPcCommonService.getResblockAddress(projectInfoDTO))
			.scenarioType(ReminderScenarioTypeEnum.INVITATION_AUTHORIZE.getValue())
			.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(),contract.getBusinessType()))
			.reminderTime(new Date())
			.build();

	}


