	private void dealPlanAllDTO(ContractReqDTO contractReqDTO, ContractContext context) {
		LOGGER.info("合同数据准备【报价信息】准备开始");
		Byte contractType = contractReqDTO.getContractBaseInfo().getContractType();
		String projectOrderId = contractReqDTO.getContractBaseInfo().getProjectOrderId();
		List<BillCodeInfo> billCodeInfoList = new ArrayList<>();
		List<SubOrderInfo> subOrderInfoList = Optional.of(contractReqDTO).map(ContractReqDTO::getBusinessInfo).map(BusinessInfoDetail::getSubOrderInfoList).orElse(Collections.emptyList());
		List<ChangeOrderInfo> changeOrderInfoList = Optional.of(contractReqDTO).map(ContractReqDTO::getBusinessInfo).map(BusinessInfoDetail::getChangeOrderInfoList).orElse(Collections.emptyList());
		if (ObjectUtil.isNotEmpty(contractReqDTO) && ObjectUtil.isNotEmpty(contractReqDTO.getBusinessInfo()) && ObjectUtil.isNotEmpty(contractReqDTO.getBusinessInfo().getBillCodeInfoList())) {
			billCodeInfoList = contractReqDTO.getBusinessInfo().getBillCodeInfoList();
		}
		Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
		boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType)
			&& BusinessTypeEnum.getHouseCertificate25ModeList().contains(businessType);
		if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
			// 翻新全案首期款不需要实时查询报价获取
			if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
				return;
			}
			HeaderContext.getContext().setOperatorUcId("10000000000000");
			//准备预估合同额信息,如果是新的版本需要请求报价单获取
			if (contractUnifyService.advanceSupportPreQuotation(contractReqDTO.getContractBaseInfo().getProjectOrderId(), ContractTypeEnum.ADVANCE.getCode())) {
				dealAdvancePreQuotation(contractReqDTO, context);
				return;
			}
			ContractProjectInfoReq projectInfo = contractReqDTO.getProjectInfo();
			ComboPriceInfo comboPriceInfo = homeAndPcCommonService.getExpectContractAmount(contractReqDTO.getContractBaseInfo().getProjectOrderId(), projectInfo.getPackageId(),
				projectInfo.getHouseType(), projectInfo.getArea(), projectInfo.getValuationArea(), projectInfo.getAdvanceRate());
			BigDecimal expectContractAmount = comboPriceInfo == null ? BigDecimal.ZERO : comboPriceInfo.getMinDiscountAmount();


			//查询合同配置字段信息
			String convertProjectOrderId = commonBusinessService.convertProjectOrderId(projectOrderId, contractReqDTO.getContractBaseInfo().getContractType());
			ContractVersionConfig contractConfigAllVersion = contractConfigVersionService.getContractConfigAllVersion(convertProjectOrderId);
			ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
			String companyCode = ObjectUtil.isEmpty(projectInfoDTO) || ObjectUtil.isEmpty(projectInfoDTO.getCustomerCommission()) ? null : projectInfoDTO.getCustomerCommission().getCompanyCode();

			String companyCodeActual = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectOrderId, projectInfo.getGbCode(), companyCode, contractType);
			//字段配置信息
			List<ContractFieldConfig> fieldConfigs = contractUnifyService.getFieldConfigAdapt(projectOrderId,projectInfo.getGbCode(), companyCodeActual, projectInfo.getBusinessType(), contractType, contractConfigAllVersion.getFieldConfigVersion());
			//是否包含预估合同额字段
			Boolean isExpectContractAmount = fieldConfigs.stream().anyMatch(fieldConfig -> "expectContractAmount".equals(fieldConfig.getFieldKey()));
			if (!isExpectContractAmount) {
				projectInfo.setExpectContractAmount(expectContractAmount);
			}
			projectInfo.setQuoteExpectContractAmount(expectContractAmount);
			Integer organizationMode = commonBusinessService.isPROCESS_V2_5(contractReqDTO.getContractBaseInfo().getProjectOrderId(), contractType) ? OrganizationModeEnum.模式25.getMode() : null;
			//准备套餐信息
			ComboBaseDTO packageByCombCode = quotationFeignService.getPackageByCombCode(contractReqDTO.getProjectInfo().getPackageId(), organizationMode);
			if (packageByCombCode != null) {
				projectInfo.setPackageName(packageByCombCode.getComboName());
				projectInfo.setPurchaseType(packageByCombCode.getPurchaseType());
			}
			// B支付预估合同金额
			if (comboPriceInfo != null && comboPriceInfo.getAdvanceToBAmount() != null) {
				projectInfo.setAdvanceToBAmount(comboPriceInfo.getAdvanceToBAmount());
			}
		}

		if (!planAllContractTypes.contains(contractType)) {
			return;
		}

		String changeOrderId = contractReqDTO.getContractBaseInfo().getChangeOrderId();
		PlanAllDTO planAllDTO = null;
		if (StringUtils.isNotBlank(changeOrderId) && houseProcessV25 && ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)) {
			//2.5变更跟其他不同，请求中控报价的接口不同:如果是变更协议&协同签约模式，需要请求中控报价的接口
			planAllDTO = buildAtomChangeQuotation(changeOrderId, projectOrderId, context);
			ContractSourceDataBO contractSourceDataBO = ContractSourceDataBO.builder().planAllDTO(planAllDTO).build();
			context.setContractSourceDataBO(contractSourceDataBO);
		} else if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			BindOrderInfo bindOrderInfo = BindOrderInfo.convert(projectOrderId, subOrderInfoList, billCodeInfoList, changeOrderInfoList);
			List<ContractSourceDataBO.PersonalContractData> personalContractData = contractDependentDataService.queryPersonalQuoteInfoV2(bindOrderInfo);
			ContractSourceDataBO contractSourceDataBO = ContractSourceDataBO.builder().personalContractDataList(personalContractData).build();
			context.setContractSourceDataBO(contractSourceDataBO);
		} else {
			//通用准备报价信息
			ContractSourceDataBO contractSourceDataBO = homeOrderDataConversionService.contractSourceDate(projectOrderId,changeOrderId);
			planAllDTO = contractSourceDataBO.getPlanAllDTO();
			//获取&组装正签对应C报价信息
			contractSourceDataBO.setPersonalContractDataList(contractDependentDataService.buildPersonalContractData(contractSourceDataBO, projectOrderId, billCodeInfoList, subOrderInfoList));
			context.setContractSourceDataBO(contractSourceDataBO);
			DesignFeeInfo designFeeInfo = contractSourceDataBO.getDesignFeeInfo();
			if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && ObjectUtil.isNotEmpty(designFeeInfo)) {
				DesignQuoteFeeDTO designQuoteFeeDTO = DesignQuoteFeeDTO.builder()
					.haveDesignQuote(DesignFeeSourceEnum.报价.getCode().equals(designFeeInfo.getSource()) && BigDecimal.ZERO.compareTo(designFeeInfo.getAfterDiscountDesignAmount()) != 0)
					.preDiscountDesignerAmount(designFeeInfo.getPreDiscountDesignAmount())
					.afterDiscountDesignerAmount(designFeeInfo.getAfterDiscountDesignAmount())
					.houseBuildType(designFeeInfo.getHouseType())
					.valuationArea(ObjectUtil.isNotEmpty(designFeeInfo.getDesignPricingArea()) ? designFeeInfo.getDesignPricingArea().toString() : "")
					.psLevelName(designFeeInfo.getDesignerRank())
					.build();
				context.setDesignQuoteFeeDTO(designQuoteFeeDTO);
			}
		}
		context.setPlanAllDTO(planAllDTO);
		LOGGER.info("合同数据准备【报价信息】准备完成");
	}

	public PlanAllDTO buildAtomChangeQuotation(String changeOrderId, String projectOrderId, ContractContext context) {
		ChangeApplyInfoDTO changeApplyInfoDTO = atomChangeRpc.getChangeApplyInfo(changeOrderId);
		List<Integer> changeScopeList = changeApplyInfoDTO.getChangeScopeList();
		QuoteChangePreviewDTO budgetPreviewDTO = null;
		PlanAttachmentDTO baseChangePdf = null;
		if (changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode())) {
			Map<String, Object> tempMap = new HashMap<>();
			ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();
			parallelTaskService.addNewTask(parallelTasksContext, () -> {
				QuoteChangeDiffBO quoteBillStandardDiff = changeContractUnifyService.getQuoteBillDiff(projectOrderId, changeOrderId);
				tempMap.put("budgetPreviewDTO", quoteBillStandardDiff.getQuoteBill());
			});
			parallelTaskService.addNewTask(parallelTasksContext, () -> {
				tempMap.put("baseChangePdf", homeOrderDataConversionService.changeHardDecorationFileData(changeOrderId));
			});
			parallelTaskService.execTasks(parallelTasksContext);
			parallelTaskService.awaitTasksResult(parallelTasksContext);
			budgetPreviewDTO = (QuoteChangePreviewDTO) tempMap.get("budgetPreviewDTO");
			baseChangePdf = (PlanAttachmentDTO) tempMap.get("baseChangePdf");
		} else {
			QuoteChangeDiffBO quoteBillStandardDiff = changeContractUnifyService.getQuoteBillDiff(projectOrderId, changeOrderId);
			budgetPreviewDTO = quoteBillStandardDiff.getPreQuoteBill();
		}
		return changeContractUnifyService.atomChangeQuotationConvertToPlanAllDTO(budgetPreviewDTO, baseChangePdf);
	}


	/**
	 * 获取套餐信息
	 */
	private void dealComboInfo(ContractReqDTO contractReqDTO, ContractContext context) {
		if (!context.isProcessV25()) {
			return;
		}

		Byte businessType = context.getBusinessType();
		if (!BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			return;
		}

		Byte contractType = contractReqDTO.getContractBaseInfo().getContractType();
		if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			return;
		}

		StopWatch stopWatch = new StopWatch();
		stopWatch.start();

		String projectOrderId = contractReqDTO.getContractBaseInfo().getProjectOrderId();

		Map<String, String> comboParams = new HashMap<>(4);
		comboParams.put("homeOrderNo", projectOrderId);
		comboParams.put(HomeModelSupportParamEnum.comboTypeList.name(), "1");
		comboParams.put(HomeModelSupportParamEnum.previewTimeCode.name(), "1");

		Map<String, Map<String, String>> moduleParams =
			Collections.singletonMap(HomeModelDefEnum.COST_CONTROL_BUDGET_STANDARD_COMBO.name(), comboParams);

		HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(projectOrderId, moduleParams);

		List<ComboDTO> comboDTOS = Optional.ofNullable(homeProject)
			.map(HomeProject::getMainOrder)
			.map(MainOrder::getCostControl)
			.map(MainOrderModel.CostControl::getBudgetStandardComboModule)
			.map(BudgetStandardComboModule::getComboDTOList)
			.orElse(Collections.emptyList());

		context.setComboDTOList(comboDTOS);

		stopWatch.stop();
		LOGGER.info("合同详情查询数据准备【套餐信息】准备完成,耗时：{}", stopWatch.getTotalTimeMillis());
	}


	/**
	 * 获取图纸信息
	 */
	private void dealDrawingDTO(ContractReqDTO contractReqDTO, ContractContext context) {
		Byte contractType = contractReqDTO.getContractBaseInfo().getContractType();
		List<BillCodeInfo> billCodeInfoList = contractReqDTO.getBusinessInfo().getBillCodeInfoList();
		List<SubOrderInfo> subOrderInfoList = contractReqDTO.getBusinessInfo().getSubOrderInfoList();
		List<ChangeOrderInfo> changeOrderInfoList = contractReqDTO.getBusinessInfo().getChangeOrderInfoList();
		String projectOrderId = contractReqDTO.getContractBaseInfo().getProjectOrderId();
		if (!drawingContractTypes.contains(contractType)) {
			return;
		}
		//只有2.5订单调用图纸接口
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractReqDTO.getContractBaseInfo().getContractType());
		if (!processV25) {
			return;
		}
		Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
		// 是否需要软装配置清单
		Boolean softConfigList = Arrays.asList(BusinessTypeEnum.HOUSE_CERTIFICATE.getCode(), BusinessTypeEnum.GROUP_DECORATE.getCode()).contains(businessType) ? Boolean.TRUE : Boolean.FALSE;
		DrawingDTO.DeliverDrawingDTO deliverDrawingDTO;
		//团装2.5正签图纸走单独获取方法
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			deliverDrawingDTO = contractBusinessService.getGroupDrawingDTO(projectOrderId);
			context.setDrawingDTO(deliverDrawingDTO);
			LOGGER.info("合同数据准备【图纸信息】准备完成");
			LOGGER.info("图纸&附件数据，团装2.5数据：{}", JSON.toJSONString(deliverDrawingDTO));
			return;
		}
		if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)) {
			deliverDrawingDTO = atomDrawingRpc.getChangeListDrawings(projectOrderId, contractReqDTO.getContractBaseInfo().getChangeOrderId(), softConfigList);
		} else if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			BindOrderInfo bindOrderInfo = BindOrderInfo.convert(projectOrderId, subOrderInfoList, billCodeInfoList, changeOrderInfoList);
			deliverDrawingDTO = contractSigningSourceRouter.route(bindOrderInfo.getBindType()).buildPersonalDrawing(bindOrderInfo, softConfigList, false);
			LOGGER.info("图纸&附件数据，销售查询图纸：{}", JSON.toJSONString(deliverDrawingDTO));
		} else {
			deliverDrawingDTO = atomDrawingRpc.listDrawings(projectOrderId, softConfigList);
			LOGGER.info("图纸&附件数据，正签查询图纸：{}", JSON.toJSONString(deliverDrawingDTO));
		}
		context.setDrawingDTO(deliverDrawingDTO);
		LOGGER.info("合同数据准备【图纸信息】准备完成");
	}

