	/**
	 * 参数预处理
	 */
	public void preHandleParam(ContractReqDTO contractReq) {
		// contractSubmit参数处理
		boolean isContractSubmit = isContractSubmitRequest();
		contractReq.setContractSubmit(isContractSubmit);

		//代理人参数预处理
		if (contractReq.getSignInfo() != null) {
			preHandleSignInfoParam(contractReq);
		}

		PromiseInfoReq promiseInfo = contractReq.getPromiseInfo();
		if (promiseInfo != null) {
			Integer needDesignerAmount = promiseInfo.getNeedDesignerAmount();
			//未约定设计费，清空设计费金额
			if (needDesignerAmount == null || CommonEnum.NO.getCode().equals(needDesignerAmount.byteValue())) {
				promiseInfo.setAfterDiscountDesignerAmount(null);
			} else {
				BigDecimal afterDiscountDesignerAmount = promiseInfo.getAfterDiscountDesignerAmount();
				ContractProjectInfoReq projectInfo = contractReq.getProjectInfo();
				if (projectInfo != null && afterDiscountDesignerAmount != null) {
					projectInfo.setAfterDiscountDesignerAmount(afterDiscountDesignerAmount);
				}
			}
			Integer projectContractModeCode = promiseInfo.getProjectContractModeCode();
			//甲供材料
			if (ProjectContractModeEnum.B_LABOR_MATERIALS.getCode().equals(projectContractModeCode)) {
				promiseInfo.setMaterialList(null);
			}
		}
		//参数项目信息处理
		preHandleProjectParam(contractReq);
		LOGGER.info("合同数据准备【参数预处理】完成, 处理结果为：{}", JSON.toJSONString(contractReq));
	}

	@SneakyThrows
	private void preHandleSignInfoParam(ContractReqDTO contractReq) {
		ContractSignInfoReq signInfo = contractReq.getSignInfo();
		ContractAttachInfo contractAttachInfo = contractReq.getContractAttachInfo() == null ? new ContractAttachInfo() : contractReq.getContractAttachInfo();
		Byte contractObjectType = signInfo.getContractObjectType();
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		Byte signChannelType = signInfo.getSignChannelType();

		// 设计变更和正签变更默认报价来源为合同
		if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)
			|| ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contractType)) {
			signInfo.setDesignContractAmountSource(DesignFeeSourceEnum.合同.getCode());
		}
		boolean attachOcrOpenCity  = attachCommonService.attachOcrOpenCity(contractReq.getContractBaseInfo().getProjectOrderId());
		if (attachOcrOpenCity) {
			contractAttachInfo.setHaveHouseProve(signInfo.getHaveHouseProve());
			contractAttachInfo.setAgentSign(signInfo.getHaveAgent());
		}
		//签约形式是公对公清空个人签约数据，清除客户证件、代理人信息、代理人委托
		if (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
			signInfo.setAgentName("");
			signInfo.setAgentPhone("");
			signInfo.setAgentCertificateType((byte) 1);
			signInfo.setOwnerCertificateNo("");
			signInfo.setOwnerName("");
			signInfo.setOwnerPhone("");
			signInfo.setOwnerCertificateType((byte) 1);
			signInfo.setOwnerCertificateNo("");
			signInfo.setOwnerAddress("");
			signInfo.setUserCertificateUnify(new ArrayList<>());
			signInfo.setUserCertificateUnifyDocumentCode(null);
			signInfo.setAgentCertificateUnify(new ArrayList<>());
			signInfo.setAgentCertificateUnifyDocumentCode(null);
			signInfo.setAgentCertificate(new ArrayList<>());
			signInfo.setAgentCertificateDocumentCode(null);
			//如果是公对公线上签约，签约人选择法人，公对公代理人信息清空
			if (RoleTypeEnum.LEGAL.getCode().equals(signInfo.getSignRole()) && !ContractTypeEnum.ACCREDIT.getCode().equals(contractReq.getContractBaseInfo().getContractType())) {
				signInfo.setCompanyAgentName("");
				signInfo.setCompanyAgentPhone("");
				signInfo.setCompanyAgentCertificateType(null);
				signInfo.setCompanyAgentCertificateNo("");
				signInfo.setCompanyAgentCertificateUnify(new ArrayList<>());
				signInfo.setCompanyAgentCertificateUnifyDocumentCode(null);
			}
		}
		//签约形式是个人签约清空公对公数据，清除公司代理人信息、公司营业执照
		if (ContractObjectTypeEnum.PERSON.getCode().equals(contractObjectType)) {
			signInfo.setCompanyName("");
			signInfo.setCompanyCreditCode("");
			signInfo.setCompanyAgentName("");
			signInfo.setCompanyAgentPhone("");
			signInfo.setCompanyAgentCertificateType((byte) 1);
			signInfo.setCompanyAgentCertificateNo("");
			signInfo.setSignRole(null);
			signInfo.setLegalName("");
			signInfo.setLegalPhone("");
			signInfo.setLegalCertificateType((byte) 1);
			signInfo.setLegalCertificateNo("");
			contractAttachInfo.setLegalCertificateUnify(new ArrayList<>());
			contractAttachInfo.setCompanyAgentCertificateUnify(new ArrayList<>());
			signInfo.setLegalCertificateUnify(new ArrayList<>());
			signInfo.setCompanyAgentCertificateUnify(new ArrayList<>());
			signInfo.setLegalCertificateUnifyDocumentCode(null);
			signInfo.setCompanyAgentCertificateUnifyDocumentCode(null);
			signInfo.setCompanyLicense(new ArrayList<>());
			signInfo.setCompanyLicenseDocumentCode(null);
		}

		//没有代理人，清空代理人数据和公司信息，清除公司代理人信息、公司营业执照
		if (HaveAgentEnum.NO.getCode().equals(signInfo.getHaveAgent())) {
			signInfo.setAgentName("");
			signInfo.setAgentPhone("");
			signInfo.setAgentCertificateType((byte) 1);
			signInfo.setAgentCertificateNo("");
			contractAttachInfo.setAgentSign(null);
			contractAttachInfo.setAgentCertificate(new ArrayList<>());
			signInfo.setAgentCertificate(new ArrayList<>());
			signInfo.setAgentCertificateDocumentCode(null);
			signInfo.setAgentCertificateUnify(new ArrayList<>());
			signInfo.setAgentCertificateUnifyDocumentCode(null);
		}

		//没有代理人委托证明，清空代理人委托证明
		if (!CommonEnum.YES.getCode().equals(contractAttachInfo.getAgentSign()) && contractAttachInfo.getAgentSign() != null) {
			contractAttachInfo.setAgentCertificate(new ArrayList<>());
			signInfo.setAgentCertificate(new ArrayList<>());
			signInfo.setAgentCertificateDocumentCode(null);
		}

		// C端授权，等同于有代理人委托证明
		if (EntrustSignTypeEnum.ONLINE.getCode().equals(signInfo.getEntrustSignType()) && CommonEnum.YES.getCode().equals(signInfo.getHaveAgent())) {
			contractAttachInfo.setAgentSign(CommonEnum.YES.getCode());
		}

		//线上签约清空【线下合同】相关字段
		if (SignChannelTypeEnum.ONLINE.getCode().equals(signInfo.getSignChannelType())) {
			signInfo.setAttachFileType("");
			signInfo.setAttachUrl(new ArrayList<>());
			signInfo.setUserSignTime("");
			signInfo.setCompanySignTime("");
		}

		//房产证、其他权属证明清空
		if (HaveHouseProveEnum.HOUSE_PROVE.getCode().equals(contractAttachInfo.getHaveHouseProve())) {
			contractAttachInfo.setOtherOwnerShip(new ArrayList<>());
			signInfo.setHouseTradeContract(new ArrayList<>());
			signInfo.setHouseTradeContractDocumentCode(null);
			signInfo.setHouseSubscribeContract(new ArrayList<>());
			signInfo.setHouseSubscribeContractDocumentCode(null);
			signInfo.setDeedTicket(new ArrayList<>());
			signInfo.setDeedTicketDocumentCode(null);
			signInfo.setSpecialHouse(new ArrayList<>());
			signInfo.setSpecialHouseDocumentCode(null);
		} else if (HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode().equals(contractAttachInfo.getHaveHouseProve())) {
			contractAttachInfo.setHouseCertificate(new ArrayList<>());
			signInfo.setHouseTradeContract(new ArrayList<>());
			signInfo.setHouseTradeContractDocumentCode(null);
			signInfo.setHouseSubscribeContract(new ArrayList<>());
			signInfo.setHouseSubscribeContractDocumentCode(null);
			signInfo.setDeedTicket(new ArrayList<>());
			signInfo.setDeedTicketDocumentCode(null);
			signInfo.setHouseCertificate(new ArrayList<>());
			signInfo.setHouseCertificateDocumentCode(null);
			signInfo.setSpecialHouse(new ArrayList<>());
			signInfo.setSpecialHouseDocumentCode(null);
		} else if (HaveHouseProveEnum.HOUSE_TRADE_CONTRACT.getCode().equals(contractAttachInfo.getHaveHouseProve())) {
			signInfo.setHouseSubscribeContract(new ArrayList<>());
			signInfo.setHouseSubscribeContractDocumentCode(null);
			signInfo.setDeedTicket(new ArrayList<>());
			signInfo.setDeedTicketDocumentCode(null);
			signInfo.setHouseCertificate(new ArrayList<>());
			signInfo.setHouseCertificateDocumentCode(null);
			signInfo.setSpecialHouse(new ArrayList<>());
			signInfo.setSpecialHouseDocumentCode(null);
		} else if (HaveHouseProveEnum.HOUSE_SUBSCRIBE_CONTRACT.getCode().equals(contractAttachInfo.getHaveHouseProve())) {
			signInfo.setHouseTradeContract(new ArrayList<>());
			signInfo.setHouseTradeContractDocumentCode(null);
			signInfo.setDeedTicket(new ArrayList<>());
			signInfo.setDeedTicketDocumentCode(null);
			signInfo.setHouseCertificate(new ArrayList<>());
			signInfo.setHouseCertificateDocumentCode(null);
			signInfo.setSpecialHouse(new ArrayList<>());
			signInfo.setSpecialHouseDocumentCode(null);
		} else if (HaveHouseProveEnum.DEED_TICKET.getCode().equals(contractAttachInfo.getHaveHouseProve())) {
			signInfo.setHouseTradeContract(new ArrayList<>());
			signInfo.setHouseTradeContractDocumentCode(null);
			signInfo.setHouseSubscribeContract(new ArrayList<>());
			signInfo.setHouseSubscribeContractDocumentCode(null);
			signInfo.setHouseCertificate(new ArrayList<>());
			signInfo.setHouseCertificateDocumentCode(null);
			signInfo.setSpecialHouse(new ArrayList<>());
			signInfo.setSpecialHouseDocumentCode(null);
		} else if (HaveHouseProveEnum.SPECIAL_HOUSE_PROVE.getCode().equals(contractAttachInfo.getHaveHouseProve())) {
			signInfo.setHouseTradeContract(new ArrayList<>());
			signInfo.setHouseTradeContractDocumentCode(null);
			signInfo.setHouseSubscribeContract(new ArrayList<>());
			signInfo.setHouseSubscribeContractDocumentCode(null);
			signInfo.setHouseCertificate(new ArrayList<>());
			signInfo.setHouseCertificateDocumentCode(null);
			signInfo.setDeedTicket(new ArrayList<>());
			signInfo.setDeedTicketDocumentCode(null);
		}
		//解约协议线下签署，由于页面直接填的解约人，未标明当前角色，取合同详情返回的正签合同的签约人信息
		if (ContractTypeEnum.TERMINAL.getCode().equals(contractType) && SignChannelTypeEnum.OFFLINE.getCode().equals(signChannelType)) {
			if (ContractObjectTypeEnum.PERSON.getCode().equals(contractObjectType) && HaveAgentEnum.NO.getCode().equals(signInfo.getHaveAgent())) {
				//个人签约&无代理人
				signInfo.setOwnerName(signInfo.getTerminalName());
				signInfo.setOwnerPhone(signInfo.getTerminalPhone());
				signInfo.setOwnerCertificateNo("");
			} else if (ContractObjectTypeEnum.PERSON.getCode().equals(contractObjectType) && HaveAgentEnum.YES.getCode().equals(signInfo.getHaveAgent())) {
				//个人签约&有代理人
				signInfo.setAgentName(signInfo.getTerminalName());
				signInfo.setAgentPhone(signInfo.getTerminalPhone());
				signInfo.setAgentCertificateNo("");
			} else if (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType) && RoleTypeEnum.LEGAL.getCode().equals(signInfo.getSignRole())) {
				//对公&法人签约
				signInfo.setLegalName(signInfo.getTerminalName());
				signInfo.setLegalPhone(signInfo.getTerminalPhone());
				signInfo.setLegalCertificateNo("");
			} else if (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType) && RoleTypeEnum.COMPANY_AGENT.getCode().equals(signInfo.getSignRole())) {
				//对公&代理人签约
				signInfo.setCompanyAgentName(signInfo.getTerminalName());
				signInfo.setCompanyAgentPhone(signInfo.getTerminalPhone());
				signInfo.setCompanyAgentCertificateNo("");
			}
		}

		// 团转非团变更协议详情会下发团装解约协议，但是变更没有该字段需要清空
		if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)) {
			signInfo.setGroupTerminalCertificateDocumentCode(null);
			signInfo.setGroupTerminalCertificate(new ArrayList<>());
		}

		// 从 attachReadyResponseMap 兜底获取身份证正面和反面
		if (signInfo.getUserCertificateUnifyDocumentCode() != null) {
			if (StringUtils.isBlank(signInfo.getUserCertificateUnifyDocumentCode().getIdentityCardFrontDocumentCode())) {
				String frontKey = ContractSignInfoReq.Fields.userCertificateUnifyDocumentCode + "." + IdentityCardInfo.Fields.identityCardFrontDocumentCode;
				String frontDocumentCode = contractReq.getAttachReadyResponseMap().get(frontKey);
				if (StringUtils.isNotBlank(frontDocumentCode)) {
					signInfo.getUserCertificateUnifyDocumentCode().setIdentityCardFrontDocumentCode(frontDocumentCode);
					LOGGER.info("从attachReadyResponseMap补充身份证正面, key:{}, documentCode:{}", frontKey, frontDocumentCode);
				}
			}
			if (StringUtils.isBlank(signInfo.getUserCertificateUnifyDocumentCode().getIdentityCardOppositeDocumentCode())) {
				String oppositeKey = ContractSignInfoReq.Fields.userCertificateUnifyDocumentCode + "." + IdentityCardInfo.Fields.identityCardOppositeDocumentCode;
				String oppositeDocumentCode = contractReq.getAttachReadyResponseMap().get(oppositeKey);
				if (StringUtils.isNotBlank(oppositeDocumentCode)) {
					signInfo.getUserCertificateUnifyDocumentCode().setIdentityCardOppositeDocumentCode(oppositeDocumentCode);
					LOGGER.info("从attachReadyResponseMap补充身份证反面, key:{}, documentCode:{}", oppositeKey, oppositeDocumentCode);
				}
			}
		}

		// 兼容由于前端组件加载顺序导致传入永久code问题
		String errMessage = "页面初始化失败，请刷新页面重试";
		for (Map.Entry<String, String> entry : signInfo.fetchDocumentCodeMap().entrySet()) {
			String key = entry.getKey();
			String documentCode = entry.getValue();
			if (StringUtils.isNotBlank(documentCode) && documentCode.startsWith("SDOCUMENT")) {
				String tempDocumentCode = contractReq.getAttachReadyResponseMap().get(key);
				if (StringUtils.isBlank(tempDocumentCode)) {
					throw new NrsBusinessException(errMessage, Level.WARN);
				}
				ReflectionUtil.setNestedFieldValue(signInfo, key, tempDocumentCode);
				LOGGER.info("备件组件传入永久code，进行兼容处理,key:{},documentCode:{}, 处理后dto:{}", key, documentCode, JSON.toJSONString(signInfo));
			}
		}

	}

	private void preHandleProjectParam(ContractReqDTO contractReq) {
		String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		String changeOrderId = contractReq.getContractBaseInfo().getChangeOrderId();
		ContractProjectInfoReq projectInfo = contractReq.getProjectInfo();
		List<ContractModuleAndFieldInfoDTO> moduleInfos = contractUnifyService.getModuleInfo(projectOrderId, contractType, null, changeOrderId);
		List<String> fieldKeys = moduleInfos.stream()
			.filter(moduleInfo -> CollectionUtils.isNotEmpty(moduleInfo.getChildren()))
			.flatMap(moduleInfo -> moduleInfo.getChildren().stream()
				.map(ContractFieldConfig::getFieldKey))
			.collect(Collectors.toList());
		//小区
		if (fieldKeys.contains("resblockObj")) {
			//小区id
			Long resblockId = projectInfo.getResblockId();
			if (resblockId == null) {
				projectInfo.setResblockId(0L);
			}
		}
		if (fieldKeys.contains("addressObj")) {
			//楼栋id
			Long buildingId = projectInfo.getBuildingId();
			//单元id
			Long unitId = projectInfo.getUnitId();
			//门牌号id
			Long houseId = projectInfo.getHouseId();
			//楼层id
			Long floorId = projectInfo.getFloorId();
			if (buildingId == null) {
				projectInfo.setBuildingId(0L);
			}
			if (unitId == null) {
				projectInfo.setUnitId(0L);
			}
			if (houseId == null) {
				projectInfo.setHouseId(0L);
			}
			if (floorId == null) {
				projectInfo.setFloorId(0L);
			}
		}
	}

	private void dealStandardDesignAmountDTO(ContractReqDTO contractReqDTO, ContractContext context) {
		if (!ContractTypeEnum.DESIGN.getCode().equals(contractReqDTO.getContractBaseInfo().getContractType())) {
			return;
		}
		// 如果设计费计算全国开城，则根据新接口计算优惠前金额、设计师职级，在 preFillReqData() 内部初始化
		if (contractUnifyService.designFeeCalculateIsOpen(contractReqDTO.getContractBaseInfo().getProjectOrderId())) {
			return;
		}
		if (!contractApolloConfig.getStandardDesignFeeCityCodes().contains(contractReqDTO.getProjectInfo().getGbCode())) {
			return;
		}

		String area = contractReqDTO.getProjectInfo().getArea();
		if (StringUtils.isBlank(area)) {
			return;
		}

		DesignSignPriceInfo designSignPriceInfo = homeAndPcCommonService.getStandardDesignFee(contractReqDTO.getContractBaseInfo().getProjectOrderId(), new BigDecimal(area));
		ContractProjectInfoReq projectInfo = context.getContractReq().getProjectInfo();
		projectInfo.setPreDiscountDesignerAmount(designSignPriceInfo.getStandardDesignFeeAmount());
		projectInfo.setDesignerPsLevelName(designSignPriceInfo.getPsLevelName());
	}

	private void dealMultiCompanyInfo(ContractReqDTO contractReqDTO, ContractContext context) {
		if (!ContractTypeEnum.FUND_ESCROW.getCode().equals(contractReqDTO.getContractBaseInfo().getContractType())) {
			return;
		}

		String projectOrderId = contractReqDTO.getContractBaseInfo().getProjectOrderId();
		FundEscrowInfoDTO fundEscrowInfoDTO = fundEscrowService.getFundEscrowEntryInfoByProjectOrderId(projectOrderId);
		LOGGER.info("saveContractCompany fundEscrowInfoDTO:{}", JSON.toJSONString(fundEscrowInfoDTO));
		if (fundEscrowInfoDTO == null) {
			return;
		}

		List<FundEscrowRangeDTO> escrowRangeList = fundEscrowInfoDTO.getEscrowRangeList();
		if (org.springframework.util.CollectionUtils.isEmpty(escrowRangeList)) {
			return;
		}

		FundEscrowRangeDTO decorateRangeDTO = escrowRangeList.stream()
			.filter(fundEscrowRangeDTO -> ProjectDecorateBusinessTypeEnum.HOME_DECORATE.getCode().equals(fundEscrowRangeDTO.getBusinessType()))
			.findFirst().orElse(null);
		FundEscrowRangeDTO retailRangeDTO = escrowRangeList.stream()
			.filter(fundEscrowRangeDTO -> ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(fundEscrowRangeDTO.getBusinessType()))
			.findFirst().orElse(null);

		if (decorateRangeDTO == null) {
			throw new NrsBusinessException("存管生成协议获取分公司code为空");
		}

		EscrowAccountBasicInfoDTO escrowAccountBasicInfoDTO = escrowRpc.queryFundEscrowAccountBasicInfo(projectOrderId, FundEscrowBusinessTypeEnum.DECORATE_PROJECT.getCode());
		Map<String, CompanyDetailInfoDto> merchantNoToCompanyMap = mdmDataRpc.getInfoByMerchantNos(escrowAccountBasicInfoDTO.getMerchantNoList());

		Map<String, MdmDTO> mdmDTOMap = new HashMap<>();
		if (org.springframework.util.CollectionUtils.isEmpty(merchantNoToCompanyMap)) {
			mdmDTOMap = mdmRpc.obtainMdmMapByMdmCodes(escrowRangeList.stream().map(FundEscrowRangeDTO::getCompanyCode).distinct().collect(Collectors.toList()));
		}
		String decorateCompanyCode = commonBusinessService.getCompanyCodeForEscrow(projectOrderId, decorateRangeDTO.getCompanyCode(), escrowAccountBasicInfoDTO.getMerchantNoList(),
			escrowAccountBasicInfoDTO.getMerchantNoList().get(0), merchantNoToCompanyMap, mdmDTOMap);

		if (StringUtils.isBlank(decorateCompanyCode)) {
			throw new NrsBusinessException("存管生成协议获取整装分公司code为空");
		}

		List<ContractCompanyAspectInfo> contractCompanyAspectInfoList = new ArrayList<>();
		contractCompanyAspectInfoList.add(ContractCompanyAspectInfo.builder()
			.companyCode(decorateCompanyCode)
			.decorateBusinessType(decorateRangeDTO.getBusinessType())
			.build());

		if (retailRangeDTO != null) {
			String retailMerchantNo = escrowAccountBasicInfoDTO.getMerchantNoList().size() > 1 ? escrowAccountBasicInfoDTO.getMerchantNoList().get(1) : escrowAccountBasicInfoDTO.getMerchantNoList().get(0);
			String retailCompanyCode = commonBusinessService.getCompanyCodeForEscrow(projectOrderId, retailRangeDTO.getCompanyCode(), escrowAccountBasicInfoDTO.getMerchantNoList(), retailMerchantNo, merchantNoToCompanyMap, mdmDTOMap);

			contractCompanyAspectInfoList.add(ContractCompanyAspectInfo.builder()
				.companyCode(retailCompanyCode)
				.decorateBusinessType(retailRangeDTO.getBusinessType())
				.build());
		}

		context.setContractCompanyList(contractCompanyAspectInfoList);
	}

	private boolean isContractSubmitRequest() {
		String requestUri = getRequestUri();
		return StringUtils.isNotBlank(requestUri) && contractSubmitUriList.contains(requestUri);
	}

	/**
	 * 获取uri
	 */
	private String getRequestUri() {
		ServletRequestAttributes attributes = (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();
		return Optional.ofNullable(attributes).map(ServletRequestAttributes::getRequest)
			.map(HttpServletRequest::getRequestURI).orElse("");
	}

}

@Pointcut(value = "@annotation(com.ke.utopia.nrs.salesproject.service.contract.annotation.ContractDataPrepare)")
public void pointCut() {

}

@Before("pointCut()")
public void beforeHandle(JoinPoint joinPoint) {
	ContractContextHandler.initContext();
	Object[] args = joinPoint.getArgs();
	ContractReqDTO contractReqDTO = (ContractReqDTO) args[0];
	LOGGER.info("合同数据准备开始，当前数据:{},threadId:{},projectOrderId:{},contractType:{}",
		JSON.toJSONString(ContractContextHandler.getContext()), Thread.currentThread().getId(),
		contractReqDTO.getContractBaseInfo().getProjectOrderId(),
		contractReqDTO.getContractBaseInfo().getContractType());
	//参数预处理
	preHandleParam(contractReqDTO);
	LOGGER.info("参数预处理完成：{}", JSON.toJSONString(contractReqDTO));
	//处理可重复发起合同的前置撤销操作
	contractUnifyService.dealReContractLaunch(contractReqDTO.getContractBaseInfo().getProjectOrderId(),contractReqDTO.getContractBaseInfo().getContractType());
	//入参设置到context
	ContractContextHandler.setContractReq(contractReqDTO);
	//设置协同项目
	ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();

	ContractContext context = ContractContextHandler.getContext();

	String projectOrderId = contractReqDTO.getContractBaseInfo().getProjectOrderId();
	Byte contractType = contractReqDTO.getContractBaseInfo().getContractType();
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId,contractType);
	Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
	context.setProcessV25(processV25);
	context.setBusinessType(businessType);

	//获取合同基础信息
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		dealBaseInfo(contractReqDTO, context);
	});

	//获取报价信息
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		dealPlanAllDTO(contractReqDTO, context);
	});


	//获取套餐信息
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		dealComboInfo(contractReqDTO, context);
	});


	//项目信息获取
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		dealProjectInfo(contractReqDTO, context);
	});

	//操作人姓名
	Long userId = HeaderContext.getUserId();
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		String operatorName = homeAndPcCommonService.getOperatorName(userId);
		context.setOperatorName(operatorName);
	});

	//获取图纸信息
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		dealDrawingDTO(contractReqDTO, context);
	});

	//获取存管账户开户信息
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		dealEscrowDTO(contractReqDTO, context);
	});

	//获取标准设计费金额信息
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		dealStandardDesignAmountDTO(contractReqDTO, context);
	});

	//获取合同主体信息
	parallelTaskService.addNewTask(parallelTasksContext, () -> {
		dealMultiCompanyInfo(contractReqDTO, context);
	});

	parallelTaskService.execTasks(parallelTasksContext);

	parallelTaskService.awaitTasksResult(parallelTasksContext);

	//合同城市分公司配置信息
	ContractCityCompanyInfo contractCityCompanyInfo = contractUnifyService.getContractCityCompanyInfo(contractReqDTO);
	context.setContractCityCompanyInfo(contractCityCompanyInfo);

	//计算当前合同模式
	context.getContractReq().getContractBaseInfo().setContractMode(commonContractService.computeFormalContractMode());
	// 设计费预处理：合并发起设计费信息需要试试从报价获取
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && contractUnifyService.designFeeFromQuote(projectOrderId)) {
		ContractProjectInfoReq projectInfo = contractReqDTO.getProjectInfo();
		PromiseInfoReq promiseInfo = contractReqDTO.getPromiseInfo();
		//线下签约需要将线下合同信息设置到signinfo参数中
		DesignQuoteFeeDTO designQuoteFeeDTO = ContractContextHandler.getContext().getDesignQuoteFeeDTO();
		if (ObjectUtil.isNotEmpty(designQuoteFeeDTO) && designQuoteFeeDTO.isHaveDesignQuote()) {
			projectInfo.setPreDiscountDesignerAmount(designQuoteFeeDTO.getPreDiscountDesignerAmount());
			projectInfo.setAfterDiscountDesignerAmount(designQuoteFeeDTO.getAfterDiscountDesignerAmount());
			projectInfo.setArea(designQuoteFeeDTO.getValuationArea());
			projectInfo.setValuationArea(designQuoteFeeDTO.getValuationArea());
			projectInfo.setDesignerPsLevelName(designQuoteFeeDTO.getPsLevelName());
			String designerLevelName = contractDetailService.getDesignerLevelName(projectInfo.getGbCode(), designQuoteFeeDTO.getPsLevelName());
			projectInfo.setDesignerLevelName(designerLevelName);

			promiseInfo.setNeedDesignerAmount(designQuoteFeeDTO.isHaveDesignQuote() ? 1 : 0);
			promiseInfo.setDesignerLevelName(designerLevelName);
			promiseInfo.setDesignerPsLevelName(designQuoteFeeDTO.getPsLevelName());
			promiseInfo.setPreDiscountDesignerAmount(designQuoteFeeDTO.getPreDiscountDesignerAmount());
			promiseInfo.setAfterDiscountDesignerAmount(designQuoteFeeDTO.getAfterDiscountDesignerAmount());
			context.getContractReq().getSignInfo().setDesignContractAmountSource(context.getDesignQuoteFeeDTO().isHaveDesignQuote() ? DesignFeeSourceEnum.报价.getCode() : DesignFeeSourceEnum.合同.getCode());
		}

	}


	LOGGER.info("合同数据准备结束：{}", contractReqDTO.getContractBaseInfo().getProjectOrderId());
}

