private void dealProjectInfo(ContractReqDTO contractReqDTO, ContractContext context) {
	//获取对应的项目单号
	String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(contractReqDTO.getContractBaseInfo().getProjectOrderId());
	ProjectInfoDTO projectInfo = projectInfoReadService.getByProjectOrderIdWithoutCache(convertProjectOrderId);
	context.setProjectInfoDTO(projectInfo);
	if (projectInfo == null) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取项目信息失败");
	}
	if (StringUtils.isBlank(projectInfo.getCustomerCommission().getCompanyCode())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目缺少分公司信息");
	}
	LOGGER.info("合同数据准备【项目信息】准备完成");
}

private void dealAdvancePreQuotation(ContractReqDTO contractReqDTO, ContractContext context) {
	List<String> billCodeList = contractReqDTO.getBusinessInfo().getBillCodeList();
	if (CollectionUtils.isEmpty(billCodeList) || StringUtils.isBlank(billCodeList.get(0))) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "首期款合同缺少报价单单号", Level.ERROR);
	}
	String billCode = billCodeList.get(0);
	// 实时查一下报价单信息，比较前端的参数和报价单是否一致，不一致异常提醒，一致的话使用报价单信息
	LightQuotationDTO.LightQuotationItem rpcQuotation = atomBudgetRpc.getPreQuotationByBillCode(billCode);
	if (rpcQuotation == null) {
		throw new NrsBusinessException(ResponseCodeEnum.ADVANCE_QUOTATION_STATUS_CHANGE_TOAST.getCode(),
			ResponseCodeEnum.ADVANCE_QUOTATION_STATUS_CHANGE_TOAST.getMsg(), Level.WARN);
	}
	QuotationInfo requestQuotation = contractReqDTO.getQuotation();
	if (StringUtils.isBlank(rpcQuotation.getDecoratePdfFile()) ||
		StringUtils.isBlank(requestQuotation.getPricingArea()) ||
		rpcQuotation.getPricingArea().compareTo(new BigDecimal(requestQuotation.getPricingArea())) != 0 ||
		rpcQuotation.getHardTotalPrice().compareTo(requestQuotation.getExpectContractAmount()) != 0 ||
		!rpcQuotation.getComboBaseInfo().getComboCode().equals(requestQuotation.getComboCode()) ||
		!rpcQuotation.getComboBaseInfo().getComboName().equals(requestQuotation.getComboName())
	) {
		throw new NrsBusinessException(ResponseCodeEnum.ADVANCE_QUOTATION_FIELD_CHANGE_TOAST.getCode(),
			ResponseCodeEnum.ADVANCE_QUOTATION_FIELD_CHANGE_TOAST.getMsg(), Level.WARN);
	}
}

