	 * 构造子单的个性化报价数据
	 */
	public List<ContractSourceDataBO.PersonalContractData> buildPersonalContractDataBySubOrderInfo(List<SubOrderInfo> subOrderInfoList, String projectOrderId) {
		if (CollectionUtils.isEmpty(subOrderInfoList)) {
			return Collections.emptyList();
