		BindOrderInfo bindOrderInfo = BindOrderInfo.convert(projectOrderId, subOrderInfoList, null, null);
		return contractSigningSourceRouter.route(bindOrderInfo.getBindType()).queryPersonalQuoteInfo(bindOrderInfo);
	}


	/**
	 * 团装正签场景是否返回个性化数据
	 * 未发起正签&已发起销售合同：不返回
	 * 未发起正签&未发起销售合同：返回
	 * 已发起正签&销售合同未发起：不返回
	 * 已发起正签&已发起销售合同&销售合同不是合并发起：不返回
	 * 已发起正签&已发起销售合同&销售合同是合并发起：返回
	 *
	 * @return
	 */
	public boolean groupPersonalForFormal(String projectOrderId) {
		Contract contractInfo = contractService.getContractInfo(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		String personalContractCode = contractService.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode())
			.stream().filter(item -> ContractStatusEnum.validStatusWithoutDraft.contains(item.getStatus()))
			.map(Contract::getContractCode)
			.findFirst().orElse(null);
		if (contractInfo == null || ContractStatusEnum.DRAFT.getCode().equals(contractInfo.getStatus())) {
			return StringUtils.isBlank(personalContractCode);
		}
		if (ContractStatusEnum.validStatusWithoutDraft.contains(contractInfo.getStatus())) {
			if (StringUtils.isBlank(personalContractCode)) {
				return true;
			}
			List<ContractRelation> relationList = contractRelationService.getRelationList(contractInfo.getContractCode());
			List<String> relationContractCodes = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
			return relationContractCodes.contains(personalContractCode);
		}
		return false;
	}

	/**
	 * 获取基础套餐正签报价单号列表
	 *
	 * @return
	 */
	public List<String> getFormalBillCodeList(String projectOrderId) {
		return atomBudgetRpc.queryBillsByBillTypeList(projectOrderId, Collections.singletonList(GeneralBillTypeEnum.BUDGET_STANDARD.getCode()))
			.stream()
			.map(BudgetBillDTO.BaseInfo::getBillCode)
			.filter(Objects::nonNull)
			.collect(Collectors.toList());

	}


}

