public List<ContractSourceDataBO.PersonalContractData> buildPersonalContractData(ContractSourceDataBO contractSourceDataBO, String projectOrderId, List<BillCodeInfo> billCodeInfoList, List<SubOrderInfo> subOrderInfoList) {
	if (!commonBusinessService.isProcessV25New(projectOrderId) || contractSourceDataBO.getPlanAllDTO() == null) {
		return Collections.emptyList();
	}
	//团装无需再次组装
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(commonBusinessService.getBusinessType(projectOrderId))) {
		if (contractApolloConfig.getSubOrderSignIsOpen()) {
			LOGGER.info("合同详情个性化数据构建参数【团装】, projectOrderId: {}, subOrderInfoList: {}", projectOrderId, JSON.toJSONString(subOrderInfoList));
			// 构建 S 单报价数据
			List<ContractSourceDataBO.PersonalContractData> subOrderPersonalContractData = buildPersonalContractDataBySubOrderInfo(subOrderInfoList, projectOrderId);
			LOGGER.info("合同详情个性化数据构建结果【团装】, projectOrderId: {}, subOrderPersonalContractData: {}", projectOrderId, JSON.toJSONString(subOrderPersonalContractData));
			return subOrderPersonalContractData;
		} else {
			if (groupPersonalForFormal(projectOrderId)) {
				return contractSourceDataBO.getPersonalContractDataList();
			} else {
				return Collections.emptyList();
			}
		}
	}
	String standardBillCode = contractSourceDataBO.getPlanAllDTO().getBudgetBillDTO().getBillCode();
	// 过滤掉基础报价单
	List<BillCodeInfo> cooperBillCodeList = billCodeInfoList.stream()
		.filter(item -> !ObjectUtil.equal(item.getBillCode(), standardBillCode))
		.collect(Collectors.toList());
	LOGGER.info("合同详情个性化数据构建参数, projectOrderId: {}, standardBillCode: {}, cooperBillCodeList: {}, subOrderInfoList: {}", projectOrderId, standardBillCode, JSON.toJSONString(cooperBillCodeList), JSON.toJSONString(subOrderInfoList));
	// 构建正签 C 报价单数据
	List<ContractSourceDataBO.PersonalContractData> formalPersonalContractData = buildFormalPersonalContractData(contractSourceDataBO, projectOrderId);
	// 构建协同 C 报价数据
	List<ContractSourceDataBO.PersonalContractData> cooperPersonalContractData = buildCooperPersonalContractDataByBillCodeInfo(cooperBillCodeList, projectOrderId);
	// 构建 S 单报价数据
	List<ContractSourceDataBO.PersonalContractData> subOrderPersonalContractData = buildPersonalContractDataBySubOrderInfo(subOrderInfoList, projectOrderId);
	LOGGER.info("合同详情个性化数据构建结果, formalPersonalContractData: {}, cooperPersonalContractData: {}, subOrderPersonalContractData: {}", JSON.toJSONString(formalPersonalContractData), JSON.toJSONString(cooperPersonalContractData), JSON.toJSONString(subOrderPersonalContractData));

	return Stream.concat(formalPersonalContractData.stream(), Stream.concat(
		cooperPersonalContractData.stream(),
		subOrderPersonalContractData.stream()
	)).collect(Collectors.toList());
}

private List<ContractSourceDataBO.PersonalContractData> buildFormalPersonalContractData(ContractSourceDataBO contractSourceDataBO, String projectOrderId) {
	if (CollectionUtil.isNotEmpty(contractSourceDataBO.getPersonalContractDataList())) {
		return contractSourceDataBO.getPersonalContractDataList();
	}
	PlanAllDTO planAllDTO = contractSourceDataBO.getPlanAllDTO();
	PlanAttachmentDTO attachmentDTO = planAllDTO.getPlanAttachmentList().stream().filter(planAttachmentDTO -> planAttachmentDTO.getFileType().equals(PlanAttachment.套外个性化报价单))
		.findFirst()
		.orElse(null);
	//如果没有套外个性化报价单，则不需要组装C报价单信息
	if (attachmentDTO == null) {
		return Collections.emptyList();
	}
	//如果合并到正签的协同C报价已发起过C合同，则不需要组装C报价单信息
	List<String> cooperBillCodes = planAllDTO.getCooperBillCodes();
	List<ContractQuotationRelation> relationListByBillCodeList = quotationRelationCommonService.getRelationListByBillCodeList(cooperBillCodes);
	List<String> relationContractCodes = new ArrayList<>();
	Contract contractInfo = contractService.getContractInfo(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode());
	if (contractInfo != null) {
		List<ContractRelation> relationList = contractRelationService.getRelationList(contractInfo.getContractCode());
		relationContractCodes = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
	}
	for (ContractQuotationRelation contractQuotationRelation : relationListByBillCodeList) {
		Contract contract = contractService.getByContractCode(contractQuotationRelation.getContractCode());
		if (contract != null && !relationContractCodes.contains(contract.getContractCode()) && ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus())) {
			LOGGER.info("合并到正签报价的协同C报价单已发起过C合同, billCode:{}, contractCode:{}, status:{}",
				contractQuotationRelation.getBillCode(), contractQuotationRelation.getContractCode(), contract.getStatus());
			return Collections.emptyList();
		}
	}
	return Collections.singletonList(ContractSourceDataBO.PersonalContractData.builder()
		.billCode(planAllDTO.getBudgetBillDTO().getBillCode())
		.personalContractPrice(planAllDTO.getPlanInfo().getPersonalTotalPrice())
		.comboCode("")
		.comboName("")
		.organizationCode(planAllDTO.getPlanInfo().getOrganizationCode())
		.organizationName(planAllDTO.getPlanInfo().getOrganizationName())
		.createTime(planAllDTO.getBudgetBillDTO().getCtimeStr())
		.quoteInfo(ContractSourceDataBO.QuoteInfo.builder()
			.fileUrl(attachmentDTO.getFileUrl())
			.prevUrl(attachmentDTO.getPrevUrl())
			.build())
		.build());
}

public List<ContractSourceDataBO.PersonalContractData> buildCooperPersonalContractData(List<String> billCodeList, String projectOrderId) {
	if (CollectionUtils.isEmpty(billCodeList)) {
		return new ArrayList<>();
	}
	ContractSourceDataBO contractSourceDataBO = homeOrderDataConversionService.contractPersonalData(projectOrderId, billCodeList, null, null);
