	/**
	 * 获取风控审核信息
	 */
	private void dealAuditInfo(String projectOrderId, Byte contractType, ContractDetailContext context) {
		LOGGER.info("单号：{} 合同类型：{}，获取风控审核信息", projectOrderId, contractType);

		// 合并发起正签合同才需要获取
		if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			return;
		}

		Contract contract = contractService.getLatestContractByStatus(projectOrderId, contractType, Collections.singletonList(ContractStatusEnum.FINISH.getCode()));
		LOGGER.info("获取风控审核信息,合同信息：{}", JSON.toJSONString(contract));
		if (contract == null) {
			return;
		}

		// 如果不是合并发起正签合同，不需要获取
		boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType)
			&& BusinessTypeEnum.getHouseCertificate25ModeList().contains(commonBusinessService.getBusinessType(projectOrderId));
		if (!houseProcessV25) {
			return;
		}

		try {
			LOGGER.info("单号：{}，获取风控审核信息", projectOrderId);
			CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectOrderId);
			AuditDetailDto auditInfo = auditRpc.getAuditInfo(coordinationProjectOrder.getProjectOrderId());
			List<ChangeListDTO> changeList = atomChangeRpc.getChangeList(coordinationProjectOrder.getProjectOrderId());
			context.setAuditDetailDTO(auditInfo);
			context.setChangeOrderList(changeList);
		} catch (Exception e) {
			LOGGER.error("单号：{}，获取风控审核信息失败，合同详情不展示审核信息", projectOrderId, e);
		}
	}

