	@Before("pointCut()")
	public void beforeHandle(JoinPoint joinPoint) {
		ContractDetailContextHandler.initContext();
		Object[] args = joinPoint.getArgs();
		String projectOrderId = (String) args[1];
		Byte contractType = (Byte) args[2];
		String changeOrderId = (String) args[3];
		boolean isFirstScreen = (boolean) args[4];
		List<BillCodeInfo> billCodeInfoList = (List<BillCodeInfo>) args[5];
		List<SubOrderInfo> subOrderInfoList = (List<SubOrderInfo>) args[6];
		List<ChangeOrderInfo> changeOrderInfoList = (List<ChangeOrderInfo>) args[7];

		LOGGER.info("合同详情查询数据准备,当前数据:{},threadId:{},projectOrderId:{},contractType:{},changeOrderId:{}",
			JSON.toJSONString(ContractDetailContextHandler.getContext()), Thread.currentThread().getId(),
			projectOrderId,
			contractType, changeOrderId);

		ContractDetailContext context = ContractDetailContextHandler.getContext();
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType);
		Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
		context.setProcessV25(processV25);
		context.setBusinessType(businessType);
		ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();

		//是否是首屏
		context.setFirstScreen(isFirstScreen);
		String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(projectOrderId);
		//准备项目信息数据
		parallelTaskService.addNewTask(parallelTasksContext, () -> dealProjectInfo(convertProjectOrderId, context));

		//合同备件信息
		parallelTaskService.addNewTask(parallelTasksContext, () -> dealAttachInfo(projectOrderId, contractType, context));

		//设计费金额获取
		parallelTaskService.addNewTask(parallelTasksContext, () -> dealStandardDesignAmountDTO(projectOrderId, contractType, context));
        //非首屏再加载其他信息
        if(!isFirstScreen) {
            //报价信息获取
            parallelTaskService.addNewTask(parallelTasksContext, () -> dealPlanAllDTO(contractType, projectOrderId, changeOrderId, billCodeInfoList, context, subOrderInfoList, changeOrderInfoList));
 		 	//套餐信息获取
            parallelTaskService.addNewTask(parallelTasksContext, () -> dealComboInfo(contractType, projectOrderId, changeOrderId, context));
            //获取款项实收金额
            parallelTaskService.addNewTask(parallelTasksContext, () -> dealRelateFundInfo(projectOrderId, contractType, context));
			//图纸信息
			parallelTaskService.addNewTask(parallelTasksContext, () -> dealDrawingDTO(projectOrderId, contractType, changeOrderId, billCodeInfoList, context, subOrderInfoList, changeOrderInfoList));
			//风控审核信息获取
			parallelTaskService.addNewTask(parallelTasksContext, () -> dealAuditInfo(projectOrderId, contractType, context));
        }
		parallelTaskService.execTasks(parallelTasksContext);
		parallelTaskService.awaitTasksResult(parallelTasksContext);
	}

@After("pointCut()")
public void afterHandle() {
	ContractDetailContextHandler.clearContext();
	LOGGER.info("合同详情查询数据准备context清除完成，threadId:{}", Thread.currentThread().getId());
}

@AfterThrowing("pointCut()")
public void afterThrowing() {
	ContractDetailContextHandler.clearContext();
	LOGGER.info("合同详情查询数据准备context清除完成，threadId:{}", Thread.currentThread().getId());
}

