}

	private void dealPlanAllDTO(Byte contractType, String projectOrderId, String changeOrderId, List<BillCodeInfo> billCodeInfoList, ContractDetailContext context, List<SubOrderInfo> subOrderInfoList, List<ChangeOrderInfo> changeOrderInfoList) {
		if (!planAllContractTypes.contains(contractType)) {
			return;
		}
		Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
		//翻新全案合同报价不从中控获取，页面上传
		if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType) && ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
			return;
		}
		StopWatch stopWatch = new StopWatch();
		stopWatch.start();
		PlanAllDTO planAllDTO;
		LightQuotationDTO.LightQuotationItem preQuotation;
		boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType)
			&& BusinessTypeEnum.getHouseCertificate25ModeList().contains(businessType);
		if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
			List<String> billCodeList = billCodeInfoList.stream().map(BillCodeInfo::getBillCode).distinct().collect(Collectors.toList());
			preQuotation = contractDetailService.getAdvanceQuote(projectOrderId, billCodeList);
			context.setPreQuotationDTO(preQuotation);
		} else if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			BindOrderInfo bindOrderInfo = BindOrderInfo.convert(projectOrderId, subOrderInfoList, billCodeInfoList, changeOrderInfoList);
			List<ContractSourceDataBO.PersonalContractData> personalContractData = contractDependentDataService.queryPersonalQuoteInfoV2(bindOrderInfo);
//			planAllDTO = queryPersonalQuote(projectOrderId, changeOrderId, billCodeList);
			ContractSourceDataBO contractSourceDataBO = ContractSourceDataBO.builder().personalContractDataList(personalContractData).build();
			context.setContractSourceDataBO(contractSourceDataBO);
		} else if (StringUtils.isNotBlank(changeOrderId) && houseProcessV25) {
			//2.5变更跟其他不同，请求中控报价的接口不同:如果是变更协议&协同签约模式，需要请求中控报价的接口
			planAllDTO = buildAtomChangeQuotation(changeOrderId, projectOrderId, context);
			context.setPlanAllDTO(planAllDTO);
			ContractSourceDataBO contractSourceDataBO = ContractSourceDataBO.builder().planAllDTO(planAllDTO).build();
			context.setContractSourceDataBO(contractSourceDataBO);
		} else {
			//通用准备报价信息
			ContractSourceDataBO contractSourceDataBO = homeOrderDataConversionService.contractSourceDate(projectOrderId, changeOrderId);
			planAllDTO = contractSourceDataBO.getPlanAllDTO();
			context.setPlanAllDTO(planAllDTO);
			DesignFeeInfo designFeeInfo = contractSourceDataBO.getDesignFeeInfo();
			if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && ObjectUtil.isNotEmpty(designFeeInfo)) {
				DesignQuoteFeeDTO designQuoteFeeDTO = DesignQuoteFeeDTO.builder()
					.haveDesignQuote(DesignFeeSourceEnum.报价.getCode().equals(designFeeInfo.getSource()) && BigDecimal.ZERO.compareTo(designFeeInfo.getAfterDiscountDesignAmount()) != 0 )
					.preDiscountDesignerAmount(designFeeInfo.getPreDiscountDesignAmount())
					.afterDiscountDesignerAmount(designFeeInfo.getAfterDiscountDesignAmount())
					.houseBuildType(designFeeInfo.getHouseType())
					.valuationArea(ObjectUtil.isNotEmpty(designFeeInfo.getDesignPricingArea()) ? designFeeInfo.getDesignPricingArea().toString() : "")
					.psLevelName(designFeeInfo.getDesignerRank())
					.build();
				context.setDesignQuoteFeeDTO(designQuoteFeeDTO);
			}
			//获取&组装正签对应C报价信息
			contractSourceDataBO.setPersonalContractDataList(contractDependentDataService.buildPersonalContractData(contractSourceDataBO, projectOrderId, billCodeInfoList, subOrderInfoList));
			context.setContractSourceDataBO(contractSourceDataBO);
		}
		stopWatch.stop();
		LOGGER.info("合同详情查询数据准备【报价信息】准备完成,耗时：{}", stopWatch.getTotalTimeMillis());
	}

private void dealComboInfo(Byte contractType, String projectOrderId, String changeOrderId, ContractDetailContext context) {
	Byte businessType = context.getBusinessType();
	boolean processV25 = context.isProcessV25();
	List<Byte> comboContractTypeList = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PACKAGE_CHANGE.getCode());
	if (!comboContractTypeList.contains(contractType)) {
		return;
	}
	if (!commonContractService.querySnapPlanInfoFromMainOrder(businessType, processV25)) {
		return;
	}

	if (StringUtils.isNotBlank(changeOrderId)) {
		ChangeApplyInfoDTO changeApplyInfo = atomChangeRpc.getChangeApplyInfo(changeOrderId);
		List<Integer> changeScopeList = changeApplyInfo.getChangeScopeList();

		StopWatch stopWatch = new StopWatch();
		stopWatch.start();
		Map<String, Map<String, String>> moduleParams = new HashMap<>();
		//查询变更套餐信息
		Map<String, String> comboParams = new HashMap<>();
		comboParams.put(HomeModelSupportParamEnum.projectChangeNo.name(), changeOrderId);
		moduleParams.put(HomeModelDefEnum.COST_CONTROL_BUDGET_STANDARD_CHANGE_COMBO.name(), comboParams);
		HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(projectOrderId, moduleParams);
		stopWatch.stop();
		List<ComboDTO> comboDTOS = Optional.ofNullable(homeProject)
			.map(HomeProject::getMainOrder)
			.map(MainOrder::getCostControl)
			.map(MainOrderModel.CostControl::getBudgetStandardChangeComboModule)
			.map(module -> changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode()) ? module.getAfterChangeComboList() : module.getBeforeChangeComboList())
			.orElse(new ArrayList<>());
		context.setComboDTOList(comboDTOS);
		LOGGER.info("合同详情查询数据准备【套餐信息】准备完成,耗时：{}", stopWatch.getTotalTimeMillis());
		return;
	}

	StopWatch stopWatch = new StopWatch();
	stopWatch.start();
	Map<String, Map<String, String>> moduleParams = new HashMap<>();
	//查询正签套餐信息
	Map<String, String> comboParams = new HashMap<>();
	comboParams.put("homeOrderNo", projectOrderId);
	comboParams.put(HomeModelSupportParamEnum.comboTypeList.name(), String.join(",", Lists.newArrayList("1")));
	comboParams.put(HomeModelSupportParamEnum.previewTimeCode.name(), "1");
	moduleParams.put(HomeModelDefEnum.COST_CONTROL_BUDGET_STANDARD_COMBO.name(), comboParams);
	HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(projectOrderId, moduleParams);
	stopWatch.stop();
	List<ComboDTO> comboDTOS = Optional.ofNullable(homeProject)
		.map(HomeProject::getMainOrder)
		.map(MainOrder::getCostControl)
		.map(MainOrderModel.CostControl::getBudgetStandardComboModule)
		.map(BudgetStandardComboModule::getComboDTOList)
		.orElse(new ArrayList<>());
	context.setComboDTOList(comboDTOS);
	LOGGER.info("合同详情查询数据准备【套餐信息】准备完成,耗时：{}", stopWatch.getTotalTimeMillis());
}

private PlanAllDTO buildAtomChangeQuotation(String changeOrderId, String projectOrderId, ContractDetailContext context) {
	ChangeApplyInfoDTO changeApplyInfoDTO = atomChangeRpc.getChangeApplyInfo(changeOrderId);
	List<Integer> changeScopeList = changeApplyInfoDTO.getChangeScopeList();
	QuoteChangePreviewDTO quoteChangePreviewDTO;
	PlanAttachmentDTO baseChangePdf = null;
	CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectOrderId);
	QuoteChangeDiffBO quoteBillDiff = changeContractUnifyService.getQuoteBillDiff(projectOrderId, changeOrderId);
	if (changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode())) {
		quoteChangePreviewDTO = quoteBillDiff.getQuoteBill();
		baseChangePdf = homeOrderDataConversionService.changeHardDecorationFileData(changeOrderId);
	} else {
		quoteChangePreviewDTO = quoteBillDiff.getPreQuoteBill();
	}
	if (changeScopeList.contains(ChangeScopeEnum.DRAWING.getCode())) {
		String drawingUrl = drawingRpc.getBaseChangeDrawing(coordinationProjectOrder.getProjectOrderId(), changeOrderId);
		context.setDrawingUrl(drawingUrl);
	}
	context.setAtomChangeScopeList(changeScopeList);
	return changeContractUnifyService.atomChangeQuotationConvertToPlanAllDTO(quoteChangePreviewDTO, baseChangePdf);
}

private void dealRelateFundInfo(String projectOrderId, Byte contractType, ContractDetailContext context) {
	Integer relateFundType = FundRelateContractMapping.obtainFundTypeByContractType(contractType);
	if (relateFundType == null) {
		return;
	}

	FundInfo relateFundInfo = fundInfoService.getFundByOrderIdAndFundType(projectOrderId, relateFundType);
	context.setRelateFundInfo(relateFundInfo);
}

private void dealAuditInfo(String projectOrderId, Byte contractType, ContractDetailContext context) {
	LOGGER.info("单号：{} 合同类型：{}，获取风控审核信息", projectOrderId, contractType);

	// 合并发起正签合同才需要获取
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return;
	}

	Contract contract = contractService.getLatestContractByStatus(projectOrderId, contractType, Collections.singletonList(ContractStatusEnum.FINISH.getCode()));
	LOGGER.info("获取风控审核信息,合同信息：{}", JSON.toJSONString(contract));
	if (contract == null) {
		return;
	}

	// 如果不是合并发起正签合同，不需要获取
	boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType)
		&& BusinessTypeEnum.getHouseCertificate25ModeList().contains(commonBusinessService.getBusinessType(projectOrderId));
	if (!houseProcessV25) {
		return;
	}

	try {
		LOGGER.info("单号：{}，获取风控审核信息", projectOrderId);
		CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectOrderId);
		AuditDetailDto auditInfo = auditRpc.getAuditInfo(coordinationProjectOrder.getProjectOrderId());
		List<ChangeListDTO> changeList = atomChangeRpc.getChangeList(coordinationProjectOrder.getProjectOrderId());
		context.setAuditDetailDTO(auditInfo);
		context.setChangeOrderList(changeList);
	} catch (Exception e) {
		LOGGER.error("单号：{}，获取风控审核信息失败，合同详情不展示审核信息", projectOrderId, e);
	}
}

private void dealAttachInfo(String projectOrderId, Byte contractType, ContractDetailContext context) {
	if (!Objects.equals(ContractTypeEnum.PACKAGE_FORMAL.getCode(), contractType)) {
		return;
	}
	AttachInfoDetail attachInfoDetail = attachCommonService.getProjectAttachInfoDetail(projectOrderId, false);
	context.setAttachInfoDetail(attachInfoDetail);
}

private void dealStandardDesignAmountDTO(String projectOrderId, Byte contractType, ContractDetailContext context) {
	if (!ContractTypeEnum.DESIGN.getCode().equals(contractType)) {
		return;
	}

	// 如果全国设计费计算开城，则详情不下发计算的设计费
	if (contractUnifyService.designFeeCalculateIsOpen(projectOrderId)) {
		return;
	}

	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
	Integer gbCode = projectInfoDTO.getCustomerHouse().getGbCode();
	if (!contractApolloConfig.getStandardDesignFeeCityCodes().contains(gbCode)) {
		return;
	}

	// 查看最新一份合同
	Contract contractInfo = contractService.getContractInfo(projectOrderId, ContractTypeEnum.DESIGN.getCode());
	if (contractInfo == null || ContractStatusEnum.DRAFT.getCode().equals(contractInfo.getStatus())) {
		// 1、根据项目单号查询客源获取设计师ucId
		Long designerUcId = baseAuditChannel.queryProjectDesignerUcId(projectOrderId);

		// 2、根据设计师ucId请求服务者中心查询人员信息
		MidPersonBaseInfoDTO midPersonBaseInfoDTO = ceresRpc.getPersonInfo(designerUcId);

		String psLevelName = midPersonBaseInfoDTO.getPsLevelName();

		BigDecimal standardDesignFeeAmount = null;
		if (contractInfo != null) {
			ContractField areaField = contractFieldService.getByContractCodeAndKey(contractInfo.getContractCode(), "area");
			String area = Optional.ofNullable(areaField).map(ContractField::getFieldValue).orElse(null);
			if (StringUtils.isNotBlank(area)) {
				// 3、根据职级和面积查询中控配置获取设计服务费金额
				BudgetDesignFee designFeeConfig = quotationFeignService.getDesignFeeConfig(psLevelName, new BigDecimal(area));
				standardDesignFeeAmount = designFeeConfig.getDesignFee();
			}
		}

		context.setDesignSignPriceInfo(DesignSignPriceInfo.builder()
			.standardDesignFeeAmount(standardDesignFeeAmount)
			.designerUcId(designerUcId)
			.designerUserCode(midPersonBaseInfoDTO.getUserCode())
			.designerName(midPersonBaseInfoDTO.getName())
			.psLevelName(psLevelName)
			.build());
	}

}

private void dealDrawingDTO(String projectOrderId, Byte contractType, String changeOrderId, List<BillCodeInfo> billCodeInfoList, ContractDetailContext context, List<SubOrderInfo> subOrderInfoList, List<ChangeOrderInfo> changeOrderInfoList) {
	List<Byte> contractTypeList = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PERSONAL.getCode());
	if (!contractTypeList.contains(contractType)) {
		return;
	}
	long start = System.currentTimeMillis();
	if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
		BindOrderInfo bindOrderInfo = BindOrderInfo.convert(projectOrderId, subOrderInfoList, billCodeInfoList, changeOrderInfoList);
		DrawingDTO.DeliverDrawingDTO personalDrawing = contractSigningSourceRouter.route(bindOrderInfo.getBindType()).buildPersonalDrawing(bindOrderInfo, null, false);
		context.setDrawingDTO(personalDrawing);
		LOGGER.info("合同详情数据准备【图纸信息】准备完成,耗时：{}", System.currentTimeMillis() - start);
		return;
	}
	Byte businessType = context.getBusinessType();
	boolean processV25 = context.isProcessV25();
	if (processV25 && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = contractBusinessService.getGroupDrawingDTO(projectOrderId);
		context.setDrawingDTO(deliverDrawingDTO);
		LOGGER.info("合同详情数据准备【图纸信息】准备完成,耗时：{}", System.currentTimeMillis() - start);
	}
}

