	/**
	 * 构建合同附件信息详情
	 */
	public ContractAttachInfoDetail buildContractAttachInfo(List<String> moduleKeyList, Contract contract, List<ContractAttach> contractAttachList, ContractSignInfoDetail signInfoDetail, Map<String, String> fieldMap, String projectOrderId, Byte contractType) {
		if (!moduleKeyList.contains(ContractModuleEnum.CONTRACT_ATTACH_INFO.getKey())) {
			return null;
		}
		if (CollectionUtils.isEmpty(contractAttachList)) {
			contractAttachList = new ArrayList<>();
		}
		boolean attachOcrOpenCity = attachCommonService.attachOcrOpenCity(projectOrderId);
		contractAttachList = contractAttachList.stream().filter(contractAttach -> !AttachTypeEnum.OFFLINE_CONTRACT.getCode().equals(contractAttach.getAttachType())).collect(Collectors.toList());
		ContractAttachInfoDetail contractAttachInfo = new ContractAttachInfoDetail();
		if (contract == null) {
			//附件是否上传完成
			contractAttachInfo.setUploadStatus(false);
			//根据备件信息初始化合同备件信息
			dealContractAttachFromAttachInfo(contractAttachInfo, contractAttachList);
			contractAttachInfo.setHaveHouseProve(contractAttachInfo.getHaveHouseProve() == null ? HaveHouseProveEnum.HOUSE_PROVE.getCode() : contractAttachInfo.getHaveHouseProve());
			//设置默认值
			contractAttachInfo.setAgentSign(contractAttachInfo.getAgentSign() == null ? CommonEnum.YES.getCode() : contractAttachInfo.getAgentSign());
			//团装2.5房屋权属证明类型为【其他权属证明】
			if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(ContractDetailContextHandler.getContext().getBusinessType())
				&& ContractDetailContextHandler.getContext().isProcessV25()) {
				contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
			}
			//从前一下个项目获取合同备件信息
			dealContractAttachFromPreProject(contractAttachInfo, projectOrderId, contractType);
			return contractAttachInfo;
		}
		//根据备件信息初始化合同备件信息
		dealContractAttachFromAttachInfo(contractAttachInfo, contractAttachList);
		BeanUtil.fillBeanWithMap(fieldMap, contractAttachInfo, true);

		//处理contractAttachList，根据备件id获取对应的备件url
		attachCommonService.getUrlFromContractAttachList(contract.getProjectOrderId(), contractAttachList);
		for (ContractAttach contractAttach : contractAttachList) {
			Byte attachType = contractAttach.getAttachType();
			if (AttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
				contractAttachInfo.getUserCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.HOUSE_CERTIFICATE.getCode().equals(attachType)) {
				contractAttachInfo.getHouseCertificate().add(File.builder().certificateId(contractAttach.getCertificateId())
					.documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
				contractAttachInfo.getAgentCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.AGENT_CERTIFICATE.getCode().equals(attachType)) {
				contractAttachInfo.getAgentCertificate().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.OTHER.getCode().equals(attachType)) {
				contractAttachInfo.getOther().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.TERMINAL_CERTIFICATE.getCode().equals(attachType)) {
				contractAttachInfo.getGroupTerminalCertificate().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.COMPANY_LICENSE.getCode().equals(attachType)) {
				contractAttachInfo.getCompanyLicense().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
				contractAttachInfo.getCompanyAgentCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.LEGAL_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
				contractAttachInfo.getLegalCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.OTHER_OWNER_SHIP.getCode().equals(attachType)) {
				if (attachOcrOpenCity) {
					//备件ocr开城后，其他权属证明放到房产证
					contractAttachInfo.getHouseCertificate().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
				}
				contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.HOUSE_TRADE_CONTRACT.getCode().equals(attachType)) {
				if (!attachOcrOpenCity) {
					contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
					contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
				}
				contractAttachInfo.getHouseTradeContract().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.HOUSE_SUBSCRIBE_CONTRACT.getCode().equals(attachType)) {
				if (!attachOcrOpenCity) {
					contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
					contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
				}
				contractAttachInfo.getHouseSubscribeContract().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.DEED_TICKET.getCode().equals(attachType)) {
				if (!attachOcrOpenCity) {
					contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
					contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
				}
				contractAttachInfo.getDeedTicket().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.SPECIAL_HOUSE_PROVE.getCode().equals(attachType)) {
				if (!attachOcrOpenCity) {
					contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
					contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
				}
				contractAttachInfo.getSpecialHouse().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
		}
		//由于历史数据（2023-03-23之前）中存在证件信息只存放在contract_user表中，所以如果attach表中不存在证件信息时需要从contract_user表中获取证件信息
		List<ContractUser> contractUserList = contractUserService.getListByContractCode(contract.getContractCode());
		for (ContractUser contractUser : contractUserList) {
			if (contractAttachInfo.getUserCertificateUnify().isEmpty() && contractUser.getRoleType().equals(UserTypeEnum.OWNER.getCode())) {
				if (StringUtils.isNotBlank(contractUser.getCertificateImg1())) {
					contractAttachInfo.getUserCertificateUnify().add(File.builder().url(contractUser.getCertificateImg1()).build());
					contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode())
						.url(contractUser.getCertificateImg1()).build());
				}
				if (StringUtils.isNotBlank(contractUser.getCertificateImg2())) {
					contractAttachInfo.getUserCertificateUnify().add(File.builder().url(contractUser.getCertificateImg2()).build());
					contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode())
						.url(contractUser.getCertificateImg2()).build());
				}
			}
			if (contractAttachInfo.getAgentCertificateUnify().isEmpty() && contractUser.getRoleType().equals(UserTypeEnum.AGENT.getCode())) {
				if (StringUtils.isNotBlank(contractUser.getCertificateImg1())) {
					contractAttachInfo.getAgentCertificateUnify().add(File.builder().url(contractUser.getCertificateImg1()).build());
					contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode())
						.url(contractUser.getCertificateImg1()).build());
				}
				if (StringUtils.isNotBlank(contractUser.getCertificateImg2())) {
					contractAttachInfo.getAgentCertificateUnify().add(File.builder().url(contractUser.getCertificateImg2()).build());
					contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode())
						.url(contractUser.getCertificateImg2()).build());
				}
			}
			if (contractAttachInfo.getCompanyAgentCertificateUnify().isEmpty() && contractUser.getRoleType()
				.equals(UserTypeEnum.COMPANY_AGENT.getCode())) {
				if (StringUtils.isNotBlank(contractUser.getCertificateImg1())) {
					contractAttachInfo.getCompanyAgentCertificateUnify().add(File.builder().url(contractUser.getCertificateImg1()).build());
					contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode())
						.url(contractUser.getCertificateImg1()).build());
				}
				if (StringUtils.isNotBlank(contractUser.getCertificateImg2())) {
					contractAttachInfo.getCompanyAgentCertificateUnify().add(File.builder().url(contractUser.getCertificateImg2()).build());
					contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode())
						.url(contractUser.getCertificateImg2()).build());
				}
			}
		}
		Byte haveHouseProve = Objects.isNull(fieldMap.get("haveHouseProve")) ? null : Byte.valueOf(String.valueOf(fieldMap.get("haveHouseProve")));
		Byte signRole = Objects.isNull(fieldMap.get("signRole")) ? null : Byte.valueOf(String.valueOf(fieldMap.get("signRole")));
		Byte signChannelType = Objects.isNull(fieldMap.get("signChannelType")) ? null : Byte.valueOf(String.valueOf(fieldMap.get("signChannelType")));
		CheckAttachUploadStatusParam checkAttachUploadStatusParam = CheckAttachUploadStatusParam.builder()
			.projectOrderId(projectOrderId)
			.contractObjectType(signInfoDetail.getContractObjectType())
			.haveAgent(signInfoDetail.getHaveAgent())
			.contractAttachList(contractAttachList)
			.agentSign(contractAttachInfo.getAgentSign())
			.haveHouseProve(haveHouseProve)
			.signRole(signRole)
			.signChannelType(signChannelType)
			.supportCompanyOnlineSign(commonContractService.openCompanySignOnline(contract.getProjectOrderId()))
			.build();
		//附件是否上传完成
		contractAttachInfo.setUploadStatus(contractUnifyService.checkAttach(checkAttachUploadStatusParam));
		contractAttachInfo.setHaveHouseProve(contractAttachInfo.getHaveHouseProve() == null ? HaveHouseProveEnum.HOUSE_PROVE.getCode() : contractAttachInfo.getHaveHouseProve());
		if (contractAttachInfo.getAgentSign() == null) {
			contractAttachInfo.setAgentSign(signInfoDetail.getHaveAgent());
		}
		//团装2.5房屋权属证明类型为【其他权属证明】
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(ContractDetailContextHandler.getContext().getBusinessType())
			&& ContractDetailContextHandler.getContext().isProcessV25()) {
			contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
		}
		contractAttachInfo.setFirstLaneSyncAttachMap(buildFirstLaneSyncAttachMap(projectOrderId, null, contractAttachList, fieldMap,contractType));
		return contractAttachInfo;
	}

	public PersonalCollectionPlanInfo buildPersonalCollectionPlanInfo(List<String> moduleKeyList) {
		if (!moduleKeyList.contains(ContractModuleEnum.PERSONAL_COLLECTION_PLAN_INFO.getKey())) {
			return null;
		}
		ContractSourceDataBO contractSourceDataBO = ContractDetailContextHandler.getContractSourceDataBO();
		List<ContractSourceDataBO.PersonalContractData> personalContractDataList = contractSourceDataBO.getPersonalContractDataList();
		if (CollectionUtils.isEmpty(personalContractDataList)) {
			return null;
		}
		BigDecimal personalTotalPrice = personalContractDataList.stream()
			.map(data -> data.getPersonalContractPrice() == null ? BigDecimal.ZERO : data.getPersonalContractPrice())
			.reduce(BigDecimal.ZERO, BigDecimal::add);
		return PersonalCollectionPlanInfo.builder()
			.lastPayNode("合同签订当天")
			.rate("100%")
			.price(personalTotalPrice)
			.build();
	}


	/**
	 * 详情页phone不展示明文，脱敏展示
	 *
	 * @param signInfo
	 * @param isDetail
	 * @return
	 */
	public List<ZqCustomerPhoneVo> getCustomerPhoneVoList(ContractSignInfoDetail signInfo, Boolean isDetail) {
		if (signInfo == null || CollectionUtils.isEmpty(signInfo.getCustomerPhoneVoList())) {
			return new ArrayList<>();
		}
		List<ZqCustomerPhoneVo> list = signInfo.getCustomerPhoneVoList();
		if (isDetail) {
			list.forEach(zqCustomerPhoneVo -> zqCustomerPhoneVo.setPhone(DesensitizeUtil.desensitizedPhoneNoKeepLast4No(zqCustomerPhoneVo.getPhone())));
		}
		return list;
	}


	/**
	 * 构建合同签约信息详情
	 */
	public ContractSignInfoDetail buildContractSignInfoDetail(Contract contract, Byte contractType, ContractProjectInfoDetail contractProjectInfoDetail,
															  Map<String, String> fieldMap, List<ContractAttach> contractAttachList, String changeOrderId) {
		ContractSignInfoDetail signInfoDetail = new ContractSignInfoDetail();
		signInfoDetail.setCustomerPhoneVoList(contractProjectInfoDetail == null ? new ArrayList<>() : contractProjectInfoDetail.getCustomerPhoneVoList());
		String decorateType = ObjectUtil.isEmpty(contractProjectInfoDetail) ? "" : StrUtil.join("-",
			// 允许 level1 为空
			StrUtil.blankToDefault(contractProjectInfoDetail.getDecorateFormLevel1Text(), null),
			StrUtil.blankToDefault(contractProjectInfoDetail.getDecorateFormLevel2Text(), null)
		).trim();
		signInfoDetail.setDecorateType(decorateType);
		ProjectInfoDTO projectInfo = Optional.ofNullable(ContractDetailContextHandler.getContext()).map(ContractDetailContext::getProjectInfoDTO).orElse(null);

		/**
		 * 正签合同，下发是否同步发起补充协议的默认值（如果补充协议开成）
		 * - 如果contract == null，表示新建合同，则设置默认值为无补充协议
		 * - 如果contract != null，表示编辑合同，为了兼容开城前创建的合同草稿中无该值，先下发默认值，如果草稿中有该值，则会覆盖掉默认值
		 */
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && projectInfo != null && contractUnifyService.supplementIsOpen(projectInfo.getProjectOrderId())) {
			// 默认设置为无补充协议
			signInfoDetail.setLaunchSupplementType(LaunchSupplementTypeEnum.NO_SUPPLEMENT.getCode());
		}
		if (contract == null) {
			signInfoDetail.setContractObjectType(ContractObjectTypeEnum.PERSON.getCode());
			signInfoDetail.setSignChannelType(SignChannelTypeEnum.ONLINE.getCode());
			signInfoDetail.setHaveAgent(HaveAgentEnum.NO.getCode());
			signInfoDetail.setOwnerName("");
			boolean processV25 = ContractDetailContextHandler.getContext().isProcessV25();
			Byte businessType = ContractDetailContextHandler.getContext().getBusinessType();
			// 团装 2.5 的(正签||销售合同)，默认带出拼好的客源地址
			if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25 && (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) || ContractTypeEnum.PERSONAL.getCode().equals(contractType))) {
				// 默认带出拼好的客源地址
				signInfoDetail.setOwnerAddress(contractProjectInfoDetail == null ? "" : contractProjectInfoDetail.queryCertificateAddressWithoutException());
			}
			signInfoDetail.setOwnerCertificateType(CertificateTypeEnum.ID.getCode());
			signInfoDetail.setUserSignType(ContractTypeEnum.DEFAULT_SIGN_CONTRACT_TYPE_LIST.contains(contractType)
				? UserSignTypeEnum.SIGN.getCode()
				: UserSignTypeEnum.CONFIRM.getCode());
			signInfoDetail.setAttachFileType(FileTypeEnum.IMAGE.getKey());
			signInfoDetail.setAgentCertificateType(CertificateTypeEnum.ID.getCode());
			signInfoDetail.setCompanyAgentCertificateType(CertificateTypeEnum.ID.getCode());
			//客户备件信息获取，设置为签约信息
			dealSignInfoFromAttachInfo(signInfoDetail);
			//如果是公对公签约&&开放公对公线上签约
			if (ContractObjectTypeEnum.COMPANY.getCode().equals(signInfoDetail.getContractObjectType()) && projectInfo != null
				&& commonContractService.openCompanySignOnline(projectInfo)) {
				signInfoDetail.setSignChannelType(SignChannelTypeEnum.ONLINE.getCode());
			}
			// 个性化合同默认带出20正签已确认/已签约信息
			if (ContractTypeEnum.PERSONAL.getCode().equals(contractType) && projectInfo != null) {
				contractDetailService.fillAdvanceContractSignInfoDetail(signInfoDetail, projectInfo.getProjectOrderId(), ContractTypeEnum.ADVANCE.getCode());
			}
			if (ContractTypeEnum.TERMINAL.getCode().equals(contractType) && projectInfo != null) {
				Contract terminalUseContractInfo = contractBusinessService.getTerminalUseContractInfo(projectInfo.getProjectOrderId(), true);
				if (terminalUseContractInfo != null) {
					List<ContractField> contractFieldList = contractFieldService.getListByContractCode(terminalUseContractInfo.getContractCode())
						.stream().filter(item -> StringUtils.isNotBlank(item.getFieldValue())).collect(Collectors.toList());
					Map<String, String> fieldMapTemp = Maps.newHashMap();
					contractFieldList.forEach(contractField -> fieldMapTemp.put(contractField.getFieldKey(), contractField.getFieldValue()));
					fieldMapTemp.remove("companySignTime");
					fieldMapTemp.remove("userSignTime");
					BeanUtil.fillBeanWithMap(fieldMapTemp, signInfoDetail, true);
				}
			}
			// 单独发起时，signInfo 信息需要从正签中带出的合同类型
			if (ContractTypeEnum.SIGN_INFO_EXTEND_FROM_FORMAL.contains(contractType) && projectInfo != null) {
				dealSignInfoFromLatestFormal(projectInfo.getProjectOrderId(), signInfoDetail);
			}
			if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && projectInfo != null) {
				//团转非团，家装带出团装正签合同信息
				dealFormalContractDetail(contractType, projectInfo, signInfoDetail);
			}
		} else {
			BeanUtil.fillBeanWithMap(fieldMap, signInfoDetail, true);
			//变更才会有这个字段,默认不变更
			signInfoDetail.setContractObjectChange(signInfoDetail.getContractObjectChange() == null ? ContractObjectChangeEnum.CHANGE_NO.getCode() : signInfoDetail.getContractObjectChange());
			signInfoDetail.setSignChannelType(contract.getSignChannelType());
			List<File> attachUrl = contractAttachList.stream()
				.filter(contractAttach -> AttachTypeEnum.OFFLINE_CONTRACT.getCode().byteValue() == contractAttach.getAttachType())
				.map(contractAttach -> File.builder()
					.url(contractAttach.getUrl())
					.build())
				.collect(Collectors.toList());
			signInfoDetail.setAttachUrl(attachUrl);
			signInfoDetail.setAttachFileType(contractBusinessService.getAttachFileKey(signInfoDetail.getAttachUrl().stream().map(File::getUrl).collect(Collectors.toList())));
			signInfoDetail.setUserSignStatus(contract.getUserSignStatus());
			signInfoDetail.setUserSignType(contract.getUserSignType());
			signInfoDetail.setAuditType(contract.getAuditType());
			signInfoDetail.setUserConfirmStatus(contract.getUserConfirmStatus());
			signInfoDetail.setFirstLaneSyncAttachMap(buildFirstLaneSyncAttachMap(contract.getProjectOrderId(), changeOrderId, contractAttachList, fieldMap,contractType));
			//合同审核状态
			ContractAudit lastAuditInfo = pcContractService.getLastAuditInfo(contract.getContractCode());
			signInfoDetail.setAuditStatus(lastAuditInfo == null || Objects.equals(contract.getStatus(), ContractStatusEnum.DRAFT.getCode())
				? null
				: lastAuditInfo.getAuditStatus());
			//草稿以后有合同url
			signInfoDetail.setContractUrl(
				contract.getStatus() > ContractStatusEnum.DRAFT.getCode() ? homeAndPcCommonService.getContractUrl(contract) : "");
			// 设计费审核和通用审核url目前没区别，如果后续设计费审核url有区别再区分
			signInfoDetail.setBpmUrl(
				contract.getStatus() >= ContractStatusEnum.AUDITING.getCode() ? pcContractService.getBpmUrl(contract.getBmpNo()) : "");
			List<ContractUser> contractUserList = contractUserService.getListByContractCode(contract.getContractCode());
			for (ContractUser contractUser : contractUserList) {
				//非草稿态合同，从签约人获取证件信息
				if (!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
					if (contractUser.getRoleType().equals(UserTypeEnum.OWNER.getCode())) {
						signInfoDetail.setOwnerName(contractUser.getName());
						signInfoDetail.setOwnerPhone(contractUser.getPhone());
						signInfoDetail.setOwnerCertificateNo(contractUser.getCertificateNo());
						signInfoDetail.setOwnerCertificateType(contractUser.getCertificateType());
					}
					if (contractUser.getRoleType().equals(UserTypeEnum.AGENT.getCode())) {
						signInfoDetail.setHaveAgent(HaveAgentEnum.YES.getCode());
						signInfoDetail.setAgentName(contractUser.getName());
						signInfoDetail.setAgentPhone(contractUser.getPhone());
						signInfoDetail.setAgentCertificateNo(contractUser.getCertificateNo());
						signInfoDetail.setAgentCertificateType(contractUser.getCertificateType());
					}
					if (UserTypeEnum.COMPANY_AGENT.getCode().equals(contractUser.getRoleType())) {
						signInfoDetail.setCompanyAgentName(contractUser.getName());
						signInfoDetail.setCompanyAgentPhone(contractUser.getPhone());
						signInfoDetail.setCompanyAgentCertificateNo(contractUser.getCertificateNo());
						signInfoDetail.setCompanyAgentCertificateType(contractUser.getCertificateType());
					}
					if (UserTypeEnum.LEGAL.getCode().equals(contractUser.getRoleType())) {
						signInfoDetail.setLegalName(contractUser.getName());
						signInfoDetail.setLegalPhone(contractUser.getPhone());
						signInfoDetail.setLegalCertificateNo(contractUser.getCertificateNo());
						signInfoDetail.setLegalCertificateType(contractUser.getCertificateType());
					}
				}
				if (CommonEnum.YES.getCode().equals(contractUser.getIsSign())) {
					signInfoDetail.setSignatoryRoleType(contractUser.getRoleType());
					signInfoDetail.setSignatoryName(contractUser.getName());
					signInfoDetail.setSignatoryPhone(contractUser.getPhone());
				}
			}

			//合同是正式套餐&线下签约的&为合并发起模式的，需要获取关联施工图纸合同和个性化合同的附件
			if (contract.getType().equals(ContractTypeEnum.PACKAGE_FORMAL.getCode()) && contract.getSignChannelType()
				.equals(SignChannelTypeEnum.OFFLINE.getCode())) {
				boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
				if (processV25) {
					List<String> relationContractList = contractRelationService.getRelationList(contract.getContractCode())
						.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
					List<Contract> contractList = contractService.getListByContractCodes(relationContractList, false);
					Contract drawingContract = contractList.stream().filter(item -> item.getType().equals(ContractTypeEnum.DRAWING.getCode()))
						.findFirst()
						.orElse(null);
					Contract personalContract = contractList.stream().filter(item -> item.getType().equals(ContractTypeEnum.PERSONAL.getCode()))
						.findFirst()
						.orElse(null);
					Contract terminalContract = contractList.stream().filter(item -> item.getType().equals(ContractTypeEnum.TERMINAL.getCode()))
						.findFirst()
						.orElse(null);
					Contract designContract = contractList.stream().filter(item -> item.getType().equals(ContractTypeEnum.DESIGN.getCode()))
						.findFirst()
						.orElse(null);
					if (drawingContract != null) {
						signInfoDetail.setDrawingAttachUrl(contractBusinessService.getOfflineContractByCode(drawingContract.getContractCode()));
					}
					if (personalContract != null) {
						signInfoDetail.setPersonalAttachUrl(contractBusinessService.getOfflineContractByCode(personalContract.getContractCode()));
					}
					if (terminalContract != null) {
						signInfoDetail.setTerminalAttachUrl(contractBusinessService.getOfflineContractByCode(terminalContract.getContractCode()));
					}
					if (designContract != null) {
						signInfoDetail.setDesignAttachUrl(contractBusinessService.getOfflineContractByCode(designContract.getContractCode()));
					}
				}
			}

			signInfoDetail.setAgentAuthFileUrls(buildRelationAgentAuthUrl(contract));
		}
		if (ObjectUtil.isNotEmpty(changeOrderId) && !ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			ChangeOrderBaseInfoDTO changeOrderBaseInfoDTO = changeOrderService.getByChangeOrderId(changeOrderId);
			if (ObjectUtil.isNotEmpty(changeOrderBaseInfoDTO)) {
				if (ChangeOrderTypeEnum.SECOND_ADD_SALES.getCode().equals(changeOrderBaseInfoDTO.getChangeOrderType().getCode())) {
					signInfoDetail.setContractObjectChange(ContractObjectChangeEnum.CHANGE_NO.getCode());
				}
			}
		}
		//公对公只能是线下签约
		if (ContractObjectTypeEnum.COMPANY.getCode().equals(signInfoDetail.getContractObjectType()) && projectInfo != null
			&& !commonContractService.openCompanySignOnline(projectInfo)) {
			signInfoDetail.setSignChannelType(SignChannelTypeEnum.OFFLINE.getCode());
			signInfoDetail.setHaveAgent(HaveAgentEnum.NO.getCode());
		}
		if (signInfoDetail.getOwnerCertificateType() == null) {
			signInfoDetail.setOwnerCertificateType(CertificateTypeEnum.ID.getCode());
		}
		if (signInfoDetail.getLegalCertificateType() == null) {
			signInfoDetail.setLegalCertificateType(CertificateTypeEnum.ID.getCode());
		}
		if (signInfoDetail.getCompanyAgentCertificateType() == null) {
			signInfoDetail.setCompanyAgentCertificateType(CertificateTypeEnum.ID.getCode());
		}
		if (signInfoDetail.getAgentCertificateType() == null) {
			signInfoDetail.setAgentCertificateType(CertificateTypeEnum.ID.getCode());
		}
		if (signInfoDetail.getLegalCertificateType() == null) {
			signInfoDetail.setLegalCertificateType(CertificateTypeEnum.ID.getCode());
		}
		if (signInfoDetail.getHaveAgent() == null) {
			signInfoDetail.setHaveAgent(HaveAgentEnum.NO.getCode());
		}
		if (signInfoDetail.getSignRole() == null && projectInfo != null && commonContractService.openCompanySignOnline(projectInfo)) {
			signInfoDetail.setSignRole(RoleTypeEnum.LEGAL.getCode());
		}
		signInfoDetail.setAgentAuthCertificateUrl(commonApolloConfig.getAgentAuthCertificateUrl());
		signInfoDetail.setGroupTerminalTemplateUrl(commonApolloConfig.getGroupTerminalTemplateUrl());

		if (projectInfo != null) {
			boolean attachCustomerAuthStatus = attachCommonService.getAttachCustomerAuthStatus(projectInfo.getProjectOrderId());
			signInfoDetail.setAgentAuthCertificateUrl(attachCustomerAuthStatus ? commonApolloConfig.getAgentAuthCertificateByCustomerUrl() : commonApolloConfig.getAgentAuthCertificateUrl());

			List<ContractUser> contractUserList = commonContractService.queryAuthedAgentInfoList(projectInfo.getProjectOrderId());
			signInfoDetail.setAuthedAgentCertificateNoList(contractUserList.stream().map(ContractUser::getCertificateNo).collect(Collectors.toList()));

			// 代理人信息带入
			if (contract == null && !CollectionUtils.isEmpty(contractUserList)) {
				// contractUserList 排序取最新的
				contractUserList.sort((cu1, cu2) -> {
					return cu2.getMtime().compareTo(cu1.getMtime()); // 倒序排序
				});
				ContractUser authedAgentUser = contractUserList.get(0);

				signInfoDetail.setAgentName(authedAgentUser.getName());
				signInfoDetail.setAgentPhone(authedAgentUser.getPhone());
				signInfoDetail.setAgentCertificateType(authedAgentUser.getCertificateType());
				signInfoDetail.setAgentCertificateNo(authedAgentUser.getCertificateNo());

			}
		}

		return signInfoDetail;
	}

	private Map<String, Boolean> buildFirstLaneSyncAttachMap(String projectOrderId, String changeOrderId, List<ContractAttach> contractAttachList, Map<String, String> fieldMap,Byte contractType) {
		//仅处理正签&变更合同
		List<Byte> dealContractTypeList = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PACKAGE_CHANGE.getCode());
		if (!dealContractTypeList.contains(contractType)) {
			return Collections.emptyMap();
		}
		List<ContractAttach> contractAttaches = contractAttachList;
		if (StringUtils.isNotBlank(changeOrderId)) {
			Contract contract = contractService.getPrevEffectContractByPid(projectOrderId);
			contractAttaches = contractAttachService.getListByContractCode(contract.getContractCode());
		}

		Map<String, Boolean> firstLaneSyncAttachMap = Maps.newHashMap();
		for (ContractAttach attachFile : contractAttaches) {
			Byte attachType = attachFile.getAttachType();
			if (AttachSyncTypeEnum.FIRST_LANE_SYNC.getCode().equals(attachFile.getSyncType())) {
				String ownerCertificateType = fieldMap.get("ownerCertificateType");
				if (StringUtils.isNotBlank(ownerCertificateType)) {
					String documentKey = AttachTypeEnum.getDocumentKey(attachType, Byte.valueOf(ownerCertificateType));
					firstLaneSyncAttachMap.put(documentKey, true);
				}
			}
		}
		return firstLaneSyncAttachMap;
	}

	private List<File> buildRelationAgentAuthUrl(Contract contract) {
		if (contract == null) {
			return null;
		}

		if (!ContractTypeEnum.HAVE_AGENT_AUTH_CONTRACT_TYPES.contains(contract.getType())) {
			return null;
		}

		Contract relateContractByType = homeAndPcCommonService.getRelateContractByType(contract, ContractTypeEnum.AUTH_AGENT.getCode());
		if (relateContractByType == null) {
			return null;
		}
		if (!ContractStatusEnum.validStatusWithoutDraft.contains(relateContractByType.getStatus())) {
			return null;
		}
		String fileUrl = s3Service.generateUrl(contractBusinessService.getContractLatestPdfKey(relateContractByType), 1800);

		return Collections.singletonList(
			File.builder()
				.url(fileUrl)
				.previewUrl(fileUrl)
				.build()
		);
	}

