		contractAttachInfo.setAgentCertificateUnify(CollectionUtils.isEmpty(agentCertificateUnify) ? Lists.emptyList() : agentCertificateUnify);
		contractAttachInfo.setAgentCertificate(CollectionUtils.isEmpty(agentCertificate) ? Lists.emptyList() : agentCertificate);
		contractAttachInfo.setCompanyAgentCertificateUnify(CollectionUtils.isEmpty(companyAgentCertificateUnify) ? Lists.emptyList() : companyAgentCertificateUnify);
		contractAttachInfo.setCompanyLicense(CollectionUtils.isEmpty(companyLicense) ? Lists.emptyList() : companyLicense);
		contractAttachInfo.setHouseCertificate(CollectionUtils.isEmpty(houseCertificate) ? Lists.emptyList() : houseCertificate);
		contractAttachInfo.setLegalCertificateUnify(CollectionUtils.isEmpty(legalCertificateUnify) ? Lists.emptyList() : legalCertificateUnify);

		CopyOptions copyOptions = CopyOptions.create().ignoreNullValue();
		BeanUtil.copyProperties(attachInfoDetail.getIdentityInfo(), contractAttachInfo, copyOptions);
		BeanUtil.copyProperties(attachInfoDetail.getHouseInfo(), contractAttachInfo, copyOptions);
