	/**
	 * 处理团转非团合同数据，如果关联的上一个订单有正签，则将上一个订单的正签合同信息填充到当前合同签约信息中
	 *
	 * @param contractType
	 * @param projectInfoDTO
	 * @param signInfoDetail
	 */
	private void dealFormalContractDetail(Byte contractType, ProjectInfoDTO projectInfoDTO, ContractSignInfoDetail signInfoDetail) {
		if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) || projectInfoDTO == null) {
			return;
		}
		String previousOrderNo = commonBusinessService.getPreviousOrderNo(projectInfoDTO.getProjectOrderId());
		if (StringUtils.isBlank(previousOrderNo)) {
			return;
		}
		Contract latestContract = contractService.getLatestContract(previousOrderNo, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		if (latestContract == null || !ContractStatusEnum.inEndStatus(latestContract.getStatus())) {
			return;
		}
		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(latestContract.getContractCode());
		Map<String, String> fieldMap = Maps.newHashMap();
		contractFieldList
			.forEach(contractField -> {
				if (StringUtils.isNotBlank(contractField.getFieldValue())) {
					fieldMap.put(contractField.getFieldKey(), contractField.getFieldValue());
				}
			});
		BeanUtil.fillBeanWithMap(fieldMap, signInfoDetail, true);
	}

	/**
	 * 详情接口-公对公线上签约是否开放
	 *
	 * @param projectOrderId
	 * @return
	 */
	public boolean openCompanySignOnlineForDetail(String projectOrderId, Boolean isFirstScreen, Byte contractType) {
		String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(projectOrderId);
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(convertProjectOrderId);
		if (Objects.isNull(projectInfoDTO)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目信息不存在");
		}
		boolean openCompanySignOnline = commonContractService.openCompanySignOnline(projectInfoDTO);
		if (isFirstScreen) {
			return openCompanySignOnline;
		}
		if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			return openCompanySignOnline;
		}
		//正签&非首屏
		ContractSourceDataBO contractSourceDataBO = ContractDetailContextHandler.getContext().getContractSourceDataBO();
		if (contractSourceDataBO == null || CollectionUtils.isEmpty(contractSourceDataBO.getPersonalContractDataList()) || contractSourceDataBO.getPlanAllDTO() == null) {
			return openCompanySignOnline;
		}
		//正签分公司code
		String organizationCode = contractSourceDataBO.getPlanAllDTO().getPlanInfo().getOrganizationCode();
		List<String> organizationCodeList = Optional.ofNullable(contractSourceDataBO.getPersonalContractDataList())
			.orElse(Collections.emptyList())
			.stream()
			.map(ContractSourceDataBO.PersonalContractData::getOrganizationCode)
			.filter(Objects::nonNull)
			.collect(Collectors.toList());
		organizationCodeList.add(organizationCode);
		organizationCodeList = organizationCodeList.stream().distinct().collect(Collectors.toList());
		if (organizationCodeList.size() > 1) {
			return false;
		}
		return openCompanySignOnline;
	}

	/**
	 * 从最新的正签合同中获取 SignInfo 信息，覆盖到当前合同的 SignInfo 模块
	 */
	private void dealSignInfoFromLatestFormal(String projectOrderId, ContractSignInfoDetail signInfoDetail) {
		Contract latestFormalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode())
			.stream()
			.filter(item -> Objects.equals(ContractStatusEnum.FINISH.getCode(), item.getStatus()))
			.findFirst().orElse(null);

		if (latestFormalContract == null) {
			throw new NrsBusinessException("未获取到最新已签署的正签合同，无法发起补充协议或和解协议");
		}

		String contractCode = latestFormalContract.getContractCode();

		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contractCode)
			.stream().filter(item -> StringUtils.isNotBlank(item.getFieldValue())).collect(Collectors.toList());
		Map<String, String> fieldMapTemp = Maps.newHashMap();
		contractFieldList.forEach(contractField -> fieldMapTemp.put(contractField.getFieldKey(), contractField.getFieldValue()));
		fieldMapTemp.remove("companySignTime");
		fieldMapTemp.remove("userSignTime");
		fieldMapTemp.remove("launchSupplementType");
		BeanUtil.fillBeanWithMap(fieldMapTemp, signInfoDetail, true);
	}

	/**
	 * 补充协议信息构建
	 * 1、正签合并发起 detail 信息下发
	 * 2、单独发起 detail 信息下发
	 */
	public SupplementItemInfo buildSupplementItemInfo(Contract contract, Map<String, String> fieldMap) {
		SupplementItemInfo supplementItemInfo = new SupplementItemInfo();
		if (contract != null) {
			// 取出已保存数据进行回填
			BeanUtil.fillBeanWithMap(fieldMap, supplementItemInfo, true);

			//合同是正式套餐&线下签约的&为合并发起模式的，需要获取补充协议的附件
			if (contract.getType().equals(ContractTypeEnum.PACKAGE_FORMAL.getCode()) && contract.getSignChannelType()
				.equals(SignChannelTypeEnum.OFFLINE.getCode())) {
				List<String> relationContractList = contractRelationService.getRelationList(contract.getContractCode())
					.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
				List<Contract> contractList = contractService.getListByContractCodes(relationContractList, false);
				Contract supplementContract = contractList.stream().filter(item -> item.getType().equals(ContractTypeEnum.SUPPLEMENT.getCode()))
					.findFirst()
					.orElse(null);
				if (supplementContract != null) {
					supplementItemInfo.setSupplementAttachUrl(contractBusinessService.getOfflineContractByCode(supplementContract.getContractCode()));
				}
			}
		}
		return supplementItemInfo;
	}

	/**
	 * 和解协议信息构建
	 */
	public SettlementItemInfo buildSettlementItemInfo(Contract contract, Map<String, String> fieldMap) {
		SettlementItemInfo settlementItemInfo = new SettlementItemInfo();
		if (contract != null) {
			// 取出已保存数据进行回填
			BeanUtil.fillBeanWithMap(fieldMap, settlementItemInfo, true);
		}
		return settlementItemInfo;
	}
}

public ContractDetailResp initContractDetail(String projectOrderId, Byte contractType, List<String> moduleKeyList, String changeOrderId, List<BillCodeInfo> billCodeInfoList, List<SubOrderInfo> subOrderInfoList, List<ChangeOrderInfo> changeOrderInfoList) {

	ContractProjectInfoDetail projectInfoDetail = buildContractProjectInfoDetail(null, contractType, projectOrderId, null);
	Integer relateFundType = FundRelateContractMapping.obtainFundTypeByContractType(contractType);
	String fundName = relateFundType != null ? FundTypeEnum.getFundNameByType(relateFundType) : "";
	ContractSignInfoDetail signInfoDetail = buildContractSignInfoDetail(null, contractType, projectInfoDetail, null, null, changeOrderId);
	//合同附件信息
	ContractAttachInfoDetail contractAttachInfo = contractDetailService.buildContractAttachInfo(moduleKeyList, null, null, signInfoDetail, new HashMap<>(), projectOrderId, contractType);
	//合并附件信息到签约信息
	contractDetailService.mergeContractAttachInfoTOSignInfo(projectOrderId, contractType, contractAttachInfo, signInfoDetail);
	//首屏只加载signInfo、contractBaseInfo、businessInfo、projectInfo 4个对象,且不保证houseType、havePersonalQuote、contractMode、salesCompanyName、billCodeList这五个字段的准确性(请求中控了)
	String decorateType = ObjectUtil.isEmpty(projectInfoDetail) ? "" : StrUtil.join("-",
		// 允许 level1 为空
		StrUtil.blankToDefault(projectInfoDetail.getDecorateFormLevel1Text(), null),
		StrUtil.blankToDefault(projectInfoDetail.getDecorateFormLevel2Text(), null)
	).trim();
	List<String> billCodeList = CollectionUtil.isEmpty(billCodeInfoList) ? new ArrayList<>() : billCodeInfoList.stream().map(BillCodeInfo::getBillCode).distinct().collect(Collectors.toList());
	if (ContractDetailContextHandler.isFirstScreen()) {
		return ContractDetailResp.builder()
			.businessInfo(BusinessInfoDetail.builder()
				.decorateType((decorateType))
				.fundName(fundName).brandList(Collections.emptyList())
				.billCodeList(billCodeList)
				.billCodeInfoList(billCodeInfoList)
				.subOrderInfoList(subOrderInfoList)
				.changeOrderInfoList(changeOrderInfoList)
				.build())
			.contractBaseInfo(buildContractBaseInfoDetail(null, projectOrderId, contractType, changeOrderId,
				new HashMap<>(), ContractDetailContextHandler.isFirstScreen()))
			.projectInfo(projectInfoDetail).signInfo(signInfoDetail)
			.build();
	}

	ContractAttachInfoDetail contractAttachInfoDetail = buildContractAttachInfo(moduleKeyList, null, Lists.emptyList(), signInfoDetail, null, projectOrderId, contractType);
	mergeContractAttachInfoTOSignInfo(projectOrderId, contractType, contractAttachInfoDetail, signInfoDetail);
	QuotationInfo quotationInfo = buildQuotationDetail(moduleKeyList, projectOrderId, changeOrderId, projectInfoDetail.getBusinessType(), contractType, null);
	PersonalQuotation personalQuotation = buildPersonalQuotationDetail(null, moduleKeyList, quotationInfo, contractType, null);
	// 定软电收款计划
	PersonalCollectionPlanInfo personalCollectionPlanInfo = contractDetailService.buildPersonalCollectionPlanInfo(moduleKeyList);
	SupplementItemInfo supplementItemInfo = buildSupplementItemInfo(null, null);
	SettlementItemInfo settlementItemInfo = buildSettlementItemInfo(null, null);
	return ContractDetailResp.builder()
		.businessInfo(BusinessInfoDetail.builder()
			.decorateType(decorateType)
			.fundName(fundName)
			.brandList(Collections.emptyList())
			.billCodeInfoList(billCodeInfoList)
			.billCodeList(billCodeList)
			.subOrderInfoList(subOrderInfoList)
			.changeOrderInfoList(changeOrderInfoList)
			.build())
		.contractBaseInfo(buildContractBaseInfoDetail(null, projectOrderId, contractType, changeOrderId, new HashMap<>(), ContractDetailContextHandler.isFirstScreen()))
		.projectInfo(projectInfoDetail)
		.activityInfo(buildActivityInfoDetail(moduleKeyList, projectOrderId, changeOrderId))
		.quotation(quotationInfo)
		.contractPrice(quotationInfo == null ? null : ContractPrice.builder().contractPriceTotal(quotationInfo.getContractPrice()).build())
		.signInfo(signInfoDetail)
		.promiseInfo(buildPromiseInfoDetail(null, new HashMap<>(), projectOrderId, contractType))
		.personalQuotation(personalQuotation)
		.amountInfo(AmountInfo.builder()
			.quoteTotalAmount(BigDecimal.ZERO)
			.dueTotalAmount(BigDecimal.ZERO)
			.build())
		.processInfo(buildProcessInfoDetail(null))
		.contractAttachInfo(contractAttachInfoDetail)
		.personalCollectionPlanInfo(personalCollectionPlanInfo)
		.supplementItemInfo(supplementItemInfo)
		.settlementItemInfo(settlementItemInfo)
		.build();
}

public void mergeContractAttachInfoTOSignInfo(String projectOrderId, Byte contractType, ContractAttachInfoDetail contractAttachInfoDetail, ContractSignInfoDetail signInfoDetail) {
	if (contractAttachInfoDetail == null || signInfoDetail == null) {
		return;
	}
	boolean attachOcrOpenCity = attachCommonService.attachOcrOpenCity(projectOrderId);
	if (!attachOcrOpenCity) {
		return;
	}

	signInfoDetail.setFirstLaneSyncAttachMap(contractAttachInfoDetail.getFirstLaneSyncAttachMap());
	if (CollectionUtils.isEmpty(contractAttachInfoDetail.fetchAllDocumentCodes())) {
		signInfoDetail.setHouseCertificate(contractAttachInfoDetail.getHouseCertificate());
