private List<ChangeListDTO> getAuditRejectChangeOrder(List<ChangeListDTO> changeOrderList) {
	return changeOrderList.stream()
		.filter(m -> !ChangeBusinessStatusEnum.CANCEL.getCode().equals(m.getStatus()))
		.filter(m -> FirstChangeReasonEnum.正签方案变更.getReasonId().equals(m.getFirstChangeReason()))
		.filter(m -> SecondChangeReasonEnum.风控审核驳回.getReasonId().equals(m.getSecondChangeReason()))
		.collect(Collectors.toList());
}

private boolean changeOrderIsAudit(ChangeListDTO changeOrderDTO) {
	if (ChangeBusinessStatusEnum.LAUNCHED.getCode().equals(changeOrderDTO.getStatus()) ||
		ChangeBusinessStatusEnum.WAIT_AUDIT.getCode().equals(changeOrderDTO.getStatus())) {
		return true;
	}

	for (ChangeBusinessStatusEnum changeBusinessStatusEnum : ChangeBusinessStatusEnum.audit()) {
		if (changeBusinessStatusEnum.getCode().equals(changeOrderDTO.getStatus())) {
			return true;
		}
	}
	return false;
}

public ContractProjectInfoDetail buildContractProjectInfoDetail(Contract contract, Byte contractType, String projectOrderId, Map<String, String> fieldMap) {
	ContractProjectInfoDetail projectInfoDetail = new ContractProjectInfoDetail();
	ProjectInfoDTO projectInfoDTO = ContractDetailContextHandler.getProjectInfo();
	//翻新全案工期单位开关设置
	projectInfoDetail.setReformDurationUnitSwitch(getReformDurationUnitSwitch());
	// 零售项目信息
	if (!ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(projectInfoDTO.getDecorateBusinessType())) {
		// 构建整装设计师信息
		ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
		projectInfoDetail.setDesignerUcId(designer == null ? 0 : designer.getUcId());
		projectInfoDetail.setDesignerName(designer == null ? "" : designer.getName());
		projectInfoDetail.setDesigner(projectInfoDetail.getDesignerName().concat("(").concat(String.valueOf(projectInfoDetail.getDesignerUcId() % 100000000).concat(")")));
	}
	ProjectCustomerHouseDTO houseDTO = projectInfoDTO.getCustomerHouse();
	String address = homeAndPcCommonService.getSafeAddress(projectInfoDTO);
	String centerControlType = homeAndPcCommonService.getCenterControlType(projectOrderId);
	Byte businessType = commonContractService.getBusinessType(projectInfoDTO);
	List<ZqCustomerPhoneVo> customerPhoneVoList = homeAndPcCommonService.getPhoneList(projectInfoDTO);
	projectInfoDetail.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));
	projectInfoDetail.setCustomerPhone(homeAndPcCommonService.getPhone(projectInfoDTO));
	projectInfoDetail.setCustomerCommissionCode(projectInfoDTO.getCustomerCommission().getCustomerCommissionCode());
	projectInfoDetail.setCustomerPhoneVoList(CollectionUtils.isEmpty(customerPhoneVoList) ? null : customerPhoneVoList);
	projectInfoDetail.setAddress(address);
	projectInfoDetail.setBusinessType(businessType);
	projectInfoDetail.setCompanyCode(projectInfoDTO.getCustomerCommission().getCompanyCode());
	projectInfoDetail.setDecorateFormLevel1(
		Objects.nonNull(projectInfoDTO.getCustomerCommission().getDecorateType()) ? projectInfoDTO.getCustomerCommission().getDecorateType()
			.intValue() : null);
	projectInfoDetail.setDecorateFormLevel1Text(projectInfoDTO.getCustomerCommission().getDecorateTypeDesc());
	projectInfoDetail.setDecorateFormLevel2(
		Objects.nonNull(projectInfoDTO.getCustomerCommission().getDecorateId()) ? projectInfoDTO.getCustomerCommission().getDecorateId()
			.intValue() : null);
	projectInfoDetail.setDecorateFormLevel2Text(projectInfoDTO.getCustomerCommission().getDecorateIdDesc());
	projectInfoDetail.setCenterControlType(centerControlType);
	BeanUtils.copyProperties(houseDTO, projectInfoDetail);

	//房屋类型如果是未知，返回给前端处理为null
	Integer houseType = (projectInfoDetail.getHouseType() == null || Objects.equals(projectInfoDetail.getHouseType(),
		HouseTypeEnum.UNKONWN.getCode())) ? null : projectInfoDetail.getHouseType();
	projectInfoDetail.setHouseType(houseType);
	//户型结构如果是未知，返回给前端处理为null
	Integer houseBuildType = (projectInfoDetail.getHouseBuildType() == null || HouseBuildTypeEnum.UNKNOWN.getCode()
		.equals(projectInfoDetail.getHouseBuildType())) ? null : projectInfoDetail.getHouseBuildType();
	projectInfoDetail.setHouseBuildType(houseBuildType);
	projectInfoDetail.setCancelOrderAmount(getCancelOrderAmount(projectOrderId));

	ProjectInfoRealTimeQueryInfo projectInfoRealTimeQueryInfo = new ProjectInfoRealTimeQueryInfo();
	ApartmentInfo apartmentInfo = new ApartmentInfo();
	BeanUtils.copyProperties(projectInfoDetail, projectInfoRealTimeQueryInfo);
	BeanUtils.copyProperties(projectInfoDetail, apartmentInfo);
	List<OptionsVo> advanceRates = null;
	// 「整装首期款合同」从收款计划获取首期款比例
	if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
		advanceRates = getAdvanceRates(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), projectInfoDTO.getCustomerCommission().getCompanyCode());
	}
	if (contract == null) {
		dealProjectInfoFromAttachInfo(projectInfoDetail);
		// 设计合同特殊处理
		fillDesignContractInfo(projectOrderId, projectInfoDetail, contract, contractType);
		// 如果是整装首期款合同，则 advanceRates != null
		if (advanceRates != null) {
			// 如果没有草稿合同，则为 advanceRate 设置默认值
			projectInfoDetail.setAdvanceRate((BigDecimal) advanceRates.get(0).getValue());
		}
	} else {
		BeanUtil.fillBeanWithMap(fieldMap, projectInfoDetail, true);
		// 整装需要工期，零售不需要
		if (!ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(projectInfoDTO.getDecorateBusinessType())) {
			ConstructScheduleVo constructScheduleVo = new ConstructScheduleVo();
			BeanUtil.fillBeanWithMap(fieldMap, constructScheduleVo, true);
			if (StringUtils.isNotBlank(fieldMap.get("constructionStageDetailDTO"))) {
				constructScheduleVo.setConstructionStageDetailDTO(JsonUtil.toObject(fieldMap.get("constructionStageDetailDTO"),
					new TypeReference<List<ConstructScheduleVo.ConstructionStageDetailDTO>>() {
					}));
			}
			if (StringUtils.isNotBlank(fieldMap.get("personalCrafts"))) {
				constructScheduleVo.setPersonalCrafts(JsonUtil.toObject(fieldMap.get("personalCrafts"), new TypeReference<List<String>>() {
				}));
			}
			projectInfoDetail.setConstructSchedule(constructScheduleVo);

			// 如果合同是草稿态，则实时获取最新的设计师信息
			if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
				// 构建整装设计师信息
				ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
				projectInfoDetail.setDesignerUcId(designer == null ? 0 : designer.getUcId());
				projectInfoDetail.setDesignerName(designer == null ? "" : designer.getName());
				projectInfoDetail.setDesigner(projectInfoDetail.getDesignerName().concat("(").concat(String.valueOf(projectInfoDetail.getDesignerUcId() % 100000000).concat(")")));
			}

		}
		projectInfoDetail.setAmount(contract.getAmount());

		// 设计合同特殊处理
		fillDesignContractInfo(projectOrderId, projectInfoDetail, contract, fieldMap);

		//正签合同草稿阶段，设计师姓名&系统号、城市、字段始终从客源获取
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType()) && ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			BeanUtils.copyProperties(projectInfoRealTimeQueryInfo, projectInfoDetail);
		}
	}
	//如果为合并发起模式，房屋类型从报价获取
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType);
		Integer houseTypeFromPlanAllDto = ContractDetailContextHandler.getPlanAllDTO() == null ? null
			: ContractDetailContextHandler.getPlanAllDTO().getReconstructionHouseLayout().getHouseType();
		//报价返回的房屋类型为有效时才使用
		if (processV25 && !HouseTypeEnum.UNKONWN.getCode().equals(houseTypeFromPlanAllDto)) {
			projectInfoDetail.setHouseType(houseTypeFromPlanAllDto);
		}
		if (HouseTypeEnum.UNKONWN.getCode().equals(projectInfoDetail.getHouseType())) {
			projectInfoDetail.setHouseType(null);
		}
		//2.5正签合同草稿阶段，原始户型字段始终从客源获取
		if (contract != null && ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()) && processV25) {
			//2.5建筑面积实时从客源取，不从草稿取
			projectInfoDetail.setArea(houseDTO.getArea());
			Integer gbCode = commonContractService.getCityMapping(projectInfoDTO.getCustomerHouse().getGbCode(), projectOrderId);
			if (CityEnum.BEIJING.getGbCode() == gbCode) {
				//原始户型字段草稿态始终从客源获取
				BeanUtils.copyProperties(apartmentInfo, projectInfoDetail);
			}
		}
	}
	//首期款合同需要返回预估合同额使用的面积类型
	if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
		projectInfoDetail.setUserAreaType(commonContractService.getExpectAmountUseAreaType(projectOrderId));
		projectInfoDetail.setAdvanceRates(advanceRates);

	}
	// 草稿态正签合同，设计费信息实时从报价获取
	if (contractUnifyService.designFeeFromQuote(projectOrderId) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && (ObjectUtil.isEmpty(contract) || ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()))) {
		DesignQuoteFeeDTO designQuoteFeeDTO = ContractDetailContextHandler.getContext().getDesignQuoteFeeDTO();
		if (ObjectUtil.isNotEmpty(designQuoteFeeDTO) && designQuoteFeeDTO.isHaveDesignQuote()) {
			projectInfoDetail.setPreDiscountDesignerAmount(designQuoteFeeDTO.getPreDiscountDesignerAmount());
			projectInfoDetail.setAfterDiscountDesignerAmount(designQuoteFeeDTO.getAfterDiscountDesignerAmount());
			projectInfoDetail.setDesignerPsLevelName(designQuoteFeeDTO.getPsLevelName());
			projectInfoDetail.setDesignerLevelName(getDesignerLevelName(projectInfoDetail.getGbCode(), designQuoteFeeDTO.getPsLevelName()));
			projectInfoDetail.setValuationArea(designQuoteFeeDTO.getValuationArea());
			projectInfoDetail.setHouseBuildType(designQuoteFeeDTO.getHouseBuildType());
			projectInfoDetail.setHouseBuildTypeDesc(ObjectUtil.isEmpty(designQuoteFeeDTO.getHouseBuildType()) ? null : HouseBuildTypeEnum.getEnumByCode(designQuoteFeeDTO.getHouseBuildType()).getDesc());
		}
	}
	if (ContractDetailContextHandler.getContext().isProcessV25() && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(ContractDetailContextHandler.getContext().getBusinessType())
		&& (contract == null || ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		//总工期从apollo获取
		projectInfoDetail.setTotalDuration(contractApolloConfig.getTotalDurationByGbCode(projectInfoDetail.getGbCode()));
		//原始户型从报价获取
		if (ContractDetailContextHandler.getPlanAllDTO() != null) {
			HouseLayoutInfoDTO reconstructionHouseLayout = ContractDetailContextHandler.getPlanAllDTO().getReconstructionHouseLayout();
			projectInfoDetail.setParlorCnt(reconstructionHouseLayout.getLivingRoomNum());
			projectInfoDetail.setRoomCnt(reconstructionHouseLayout.getBedroomNum());
			projectInfoDetail.setCookroomCnt(reconstructionHouseLayout.getKitchenNum());
			projectInfoDetail.setToiletCnt(reconstructionHouseLayout.getToiletNum());
			projectInfoDetail.setBalconyCnt(reconstructionHouseLayout.getBalconyNum());
			projectInfoDetail.setStorageCnt(reconstructionHouseLayout.getStoreroomNum());
		}
	}
	return projectInfoDetail;
}

private boolean getReformDurationUnitSwitch() {
	LocalDateTime targetTime = null;
	LocalDateTime now = null;
	try {
		String reformDurationUnitSwitchTime = contractApolloConfig.getReformDurationUnitSwitchTime();
		DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
		targetTime = LocalDateTime.parse(reformDurationUnitSwitchTime, formatter);
		now = LocalDateTime.now();
	} catch (Exception e) {
		LOGGER.error("获取合同翻新工期单位开关时间异常", e);
		return false;
	}
	return now.isAfter(targetTime);
}

private List<OptionsVo> getAdvanceRates(String projectOrderId, Integer gbCode, String companyCode) {
	// 北京特殊处理，返回首期款比例为 0.2 和 0.6
	if (CityEnum.BEIJING.getGbCode() == gbCode) {
		LOGGER.info("「首期款比例调整」北京特殊处理，返回 20%，60%");
		return Arrays.asList(new OptionsVo(CollectionRateEnum.ZERO_TWO), new OptionsVo(CollectionRateEnum.ZERO_SIX));
	} else if (contractApolloConfig.isAdvanceRateOpenCity(gbCode)) {
		// 对于其他城市：如果开城，则获取「收款计划」的首期款比例
		// 首期款比例默认设置为 20%
		List<OptionsVo> advanceRates = Collections.singletonList(new OptionsVo(CollectionRateEnum.ZERO_TWO));
		List<CollectionPlanConfigInfo> collectionProgressConfigList;
		try {
			Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
			// 获取收款计划
			collectionProgressConfigList = payConfigService.getProjectCollectionProgressConfig(projectOrderId, companyCode, businessType);
		} catch (NrsBusinessException e) {
			LOGGER.info("「首期款比例调整」查询收款计划抛出异常，返回默认值 20%");
			return advanceRates;
		}
		// 判空
		if (collectionProgressConfigList.isEmpty() || collectionProgressConfigList.get(0) == null || collectionProgressConfigList.get(0).getContent().isEmpty()) {
			LOGGER.info("「首期款比例调整」未查询到首期款比例，返回默认值 20%");
			// 未查询到首期款比例，设置为默认比例 20%
			return advanceRates;
		}
		// 从收款计划中获取「首开尾」的首期款比例
		BigDecimal rate = collectionProgressConfigList.get(0).getContent().get(0).getRate();
		LOGGER.info("「首期款比例调整」从收款计划获取:{}", rate);
		return Collections.singletonList(OptionsVo.getByValue(rate));
	} else {
		// 未开城，设置为默认比例 20%
		LOGGER.info("「首期款比例调整」首期款比例功能未开城，返回默认值 20%");
		return Collections.singletonList(new OptionsVo(CollectionRateEnum.ZERO_TWO));
	}
}

public void fillDesignContractInfo(String projectOrderId, ContractProjectInfoDetail projectInfoDetail, @Nullable Contract contract, Byte contractType) {
	// 如果是草稿状态的设计合同，需要实时带出设计师职级信息&标准设计服务费
	if (contract != null && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
		return;
	}

	// 全国设计费计算开城
	if (ContractTypeEnum.DESIGN_FEE_DESIGN_TYPES.contains(contractType) && contractUnifyService.designFeeCalculateIsOpen(projectOrderId)) {
		// 1、根据项目单号查询客源获取设计师ucId
		Long designerUcId = baseAuditChannel.queryProjectDesignerUcId(projectOrderId);

		// 2、根据设计师ucId请求服务者中心查询人员信息
		MidPersonBaseInfoDTO midPersonBaseInfoDTO = ceresRpc.getPersonInfo(designerUcId);

		String psLevelName = midPersonBaseInfoDTO.getPsLevelName();
		String designerLevelName = getDesignerLevelName(projectInfoDetail.getGbCode(), psLevelName);
		projectInfoDetail.setDesignerLevelName(designerLevelName);
		projectInfoDetail.setDesignerPsLevelName(psLevelName);
		// 设计服务费不再 detail 下发，前端手动查询
		return;
	}


	if ((ContractTypeEnum.DESIGN_FEE_DESIGN_TYPES.contains(contractType) && contractApolloConfig.getStandardDesignFeeCityCodes().contains(projectInfoDetail.getGbCode()))) {
		DesignSignPriceInfo designSignPriceInfo = ContractDetailContextHandler.getContext().getDesignSignPriceInfo();
		if (designSignPriceInfo == null) {
			throw new NrsBusinessException(ResponseCodeEnum.DESIGN_CONTRACT_LEVEL_TOAST.getCode(), ResponseCodeEnum.DESIGN_CONTRACT_LEVEL_TOAST.getMsg(), Level.WARN);
		}

		String psLevelName = designSignPriceInfo.getPsLevelName();
		String designerLevelName = contractApolloConfig.getDesignerLevelNameMap().get(psLevelName);
		if (StringUtils.isBlank(designerLevelName)) {
			throw new NrsBusinessException(ResponseCodeEnum.DESIGN_CONTRACT_LEVEL_TOAST.getCode(), ResponseCodeEnum.DESIGN_CONTRACT_LEVEL_TOAST.getMsg(), Level.WARN);
		}

		// 设计师职级名称
		projectInfoDetail.setDesigner(String.format("%s(%s)", designSignPriceInfo.getDesignerName(), designSignPriceInfo.getDesignerUserCode()));
		projectInfoDetail.setDesignerLevelName(designerLevelName);
		projectInfoDetail.setDesignerPsLevelName(psLevelName);

		// 上下文中没有获取到金额，但是有职级信息，说明从客源带入了面积，需要重新计算设计服务费
		if (!StringUtils.isBlank(projectInfoDetail.getArea())) {
			if (designSignPriceInfo.getStandardDesignFeeAmount() == null) {
				BudgetDesignFee designFeeConfig = quotationFeignService.getDesignFeeConfig(psLevelName, new BigDecimal(projectInfoDetail.getArea()));
				designSignPriceInfo.setStandardDesignFeeAmount(designFeeConfig.getDesignFee());
			}

			// 标准设计服务费
			projectInfoDetail.setPreDiscountDesignerAmount(designSignPriceInfo.getStandardDesignFeeAmount());
		}
	}
}

public String getDesignerLevelName(Integer gbCode, String psLevelName) {
	if (CityEnum.BEIJING.getGbCode() == gbCode) {
		// 北京中文职级配置
		return contractApolloConfig.getDesignerLevelNameMap().get(psLevelName);
	} else {
		// 圣都中文职级配置
		return contractApolloConfig.getSdDesignerLevelNameMap().get(psLevelName);
	}
}

public PromiseInfoDetail buildPromiseInfoDetail(Contract contract, Map<String, String> fieldMap, String projectOrderId, Byte contractType) {
	PromiseInfoDetail promiseInfoDetail = new PromiseInfoDetail();
	promiseInfoDetail.setConstructionDrawMode(
		StringUtils.isNotBlank(fieldMap.get("constructionDrawMode")) ? Integer.parseInt(fieldMap.get("constructionDrawMode")) : ConstructionDrawModeEnum.DELEGATE.getCode());
	promiseInfoDetail.setProjectContractModeCode(
		StringUtils.isNotBlank(fieldMap.get("projectContractModeCode")) ? Integer.parseInt(fieldMap.get("projectContractModeCode")) : ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS_V2.getCode());
	promiseInfoDetail.setBeforeDeliveryDaysToWork(
		StringUtils.isNotBlank(fieldMap.get("beforeDeliveryDaysToWork")) ? Integer.parseInt(fieldMap.get("beforeDeliveryDaysToWork")) : BeforeDeliveryDaysToWorkEnum.THIRTY.getCode());
	if (Objects.equals(promiseInfoDetail.getProjectContractModeCode(), ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS_V2.getCode())) {
		promiseInfoDetail.setTaxRate(9);
	}
	//获取有效的设计合同
	List<Contract> validContractList = contractService.getContractList(projectOrderId, ContractTypeEnum.DESIGN.getCode(), ContractStatusEnum.validStatusWithoutDraft);
	promiseInfoDetail.setNeedDesignerAmount(StringUtils.isNotBlank(fieldMap.get("needDesignerAmount")) ? Integer.parseInt(fieldMap.get("needDesignerAmount")) : CommonEnum.NO.getCode().intValue());
	if (CollectionUtil.isNotEmpty(validContractList)) {
		promiseInfoDetail.setNeedDesignerAmount(CommonEnum.NO.getCode().intValue());
	} else {
		promiseInfoDetail.setAfterDiscountDesignerAmount(StringUtils.isNotBlank(fieldMap.get("afterDiscountDesignerAmount")) ? new BigDecimal(fieldMap.get("afterDiscountDesignerAmount")) : BigDecimal.ZERO);
	}
	boolean processV25 = ContractDetailContextHandler.getContext().isProcessV25();
	Byte businessType = ContractDetailContextHandler.getContext().getBusinessType();
	// 团装2.5销售合同默认下发非杭州处理方式
	if (processV25 && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
		promiseInfoDetail.setDisputeDealMode(DisputeDealModeEnum.COMMON.getCode());
	} else {
		promiseInfoDetail.setDisputeDealMode(DisputeDealModeEnum.HANGZHOU.getCode());
	}

	List<MaterialItemVo> materialItemVoList = new LinkedList<>();
	Map<Integer, MaterialOptionsVo> materialOptionsMap = contractApolloConfig.getMaterialOptionsMap();
	DesignQuoteFeeDTO designQuoteFeeDTO = ContractDetailContextHandler.getContext().getDesignQuoteFeeDTO();
	if (contract == null) {
		//todo 甲供材料清单枚举放代码中 @崔玉宝
		materialItemVoList.add(MaterialItemVo.builder().description("动力-电费（元）").value(1).categoryCode("basicFee").categoryName("基础费用").build());
		materialItemVoList.add(MaterialItemVo.builder().description("动力-水费（元）").value(2).categoryCode("basicFee").categoryName("基础费用").build());
		promiseInfoDetail.setMaterialList(materialItemVoList);
		if (contractUnifyService.designFeeFromQuote(projectOrderId) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			if (ObjectUtil.isNotEmpty(designQuoteFeeDTO) && designQuoteFeeDTO.isHaveDesignQuote()) {
				promiseInfoDetail.setNeedDesignerAmount(1);
				promiseInfoDetail.setAfterDiscountDesignerAmount(designQuoteFeeDTO.getAfterDiscountDesignerAmount());
				promiseInfoDetail.setPreDiscountDesignerAmount(designQuoteFeeDTO.getPreDiscountDesignerAmount());
				promiseInfoDetail.setDesignerPsLevelName(designQuoteFeeDTO.getPsLevelName());
				ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
				promiseInfoDetail.setDesignerLevelName(getDesignerLevelName(projectInfoDTO.getCustomerHouse().getGbCode(), designQuoteFeeDTO.getPsLevelName()));
			} else {
				promiseInfoDetail.setNeedDesignerAmount(0);
			}
		}
		return promiseInfoDetail;
	}
	BeanUtil.fillBeanWithMap(fieldMap, promiseInfoDetail, true);
	if (contractUnifyService.designFeeFromQuote(projectOrderId) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
		if (ObjectUtil.isNotEmpty(designQuoteFeeDTO) && designQuoteFeeDTO.isHaveDesignQuote()) {
			promiseInfoDetail.setNeedDesignerAmount(1);
			promiseInfoDetail.setAfterDiscountDesignerAmount(designQuoteFeeDTO.getAfterDiscountDesignerAmount());
			promiseInfoDetail.setPreDiscountDesignerAmount(designQuoteFeeDTO.getPreDiscountDesignerAmount());
			promiseInfoDetail.setDesignerPsLevelName(designQuoteFeeDTO.getPsLevelName());
			ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
			promiseInfoDetail.setDesignerLevelName(getDesignerLevelName(projectInfoDTO.getCustomerHouse().getGbCode(), designQuoteFeeDTO.getPsLevelName()));
		} else {
			promiseInfoDetail.setNeedDesignerAmount(0);
		}

	}
	List<ContractMaterial> materialList = contractMaterialService.getListByContractCode(contract.getContractCode());
	for (ContractMaterial contractMaterial : materialList) {
		//起草中合同不返回自定义的材料信息;起草中合同不返回已删除的材料类型的材料信息
		if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()) && (0 == contractMaterial.getValue() || !materialOptionsMap.containsKey(
			contractMaterial.getValue()))) {
			continue;
		}
		materialItemVoList.add(MaterialItemVo.builder()
			.description(contractMaterial.getDescription())
			.count(contractMaterial.getCount())
			.value(contractMaterial.getValue())
			.unit(contractMaterial.getUnit())
			.categoryName(materialOptionsMap.get(contractMaterial.getValue()) == null ? null : materialOptionsMap.get(contractMaterial.getValue()).getCategoryName())
			.categoryCode(materialOptionsMap.get(contractMaterial.getValue()) == null ? null : materialOptionsMap.get(contractMaterial.getValue()).getCategoryCode())
			.build());
	}
	if (CollectionUtils.isEmpty(materialItemVoList)) {
		materialItemVoList.add(MaterialItemVo.builder().description("动力-电费（元）").value(1).categoryCode("basicFee").categoryName("基础费用").build());
		materialItemVoList.add(MaterialItemVo.builder().description("动力-水费（元）").value(2).categoryCode("basicFee").categoryName("基础费用").build());
	}
	promiseInfoDetail.setMaterialList(materialItemVoList);
	return promiseInfoDetail;
}

