	if (ContractObjectTypeEnum.COMPANY.getCode().equals(signInfoDetail.getContractObjectType())) {
		signInfoDetail.setSignChannelType(SignChannelTypeEnum.OFFLINE.getCode());
		signInfoDetail.setHaveAgent(HaveAgentEnum.NO.getCode());
	}
}

public List<ContractPreQuotationDTO> getPreQuotationList(String projectOrderId) {
	List<ContractPreQuotationDTO> preQuotationList = Lists.emptyList();
	List<LightQuotationDTO.LightQuotationItem> quotationItemList = atomBudgetRpc.getPreQuotationListByProject(projectOrderId);
	if (CollectionUtils.isEmpty(quotationItemList)) {
		return preQuotationList;
	}
	preQuotationList = quotationItemList.stream().map(item -> ContractPreQuotationDTO.builder()
		.billCode(item.getBillCode())
		.comboName(item.getComboBaseInfo().getComboName())
		.cuName(item.getCuName())
		.mtime(DateUtils.asDate(item.getMtime()))
		.remark(item.getRemark())
		.status(item.getStatus())
		.statusDesc(item.getStatusDesc())
