public LightQuotationDTO.LightQuotationItem getAdvanceQuote(String projectOrderId, List<String> billCodeList) {
	//未开城，不用从预报价获取
	if (Boolean.FALSE.equals(contractUnifyService.advanceSupportPreQuotation(projectOrderId, ContractTypeEnum.ADVANCE.getCode()))) {
		return null;
	}
	if (CollectionUtils.isEmpty(billCodeList) || StringUtils.isBlank(billCodeList.get(0))) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "参数异常，预报价单号为空", Level.ERROR);
	}
	//校验预报价单是否有效
	LightQuotationDTO.LightQuotationItem preQuotation = atomBudgetRpc.getPreQuotationByBillCode(billCodeList.get(0));
	if (preQuotation == null) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_INVOKE.getCode(), "所选预报价不是已提交/正式版状态，请回到合同列表重新选择", Level.WARN);
	}
	if (
		preQuotation.getPricingArea() == null ||
			preQuotation.getComboBaseInfo() == null || StringUtils.isBlank(preQuotation.getComboBaseInfo().getComboCode()) || StringUtils.isBlank(preQuotation.getComboBaseInfo().getComboName()) ||
			preQuotation.getHardTotalPrice() == null) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_INVOKE.getCode(), "所选预报价信息不完整，请回到合同列表重新选择", Level.ERROR);
	}
	return preQuotation;
}

