public boolean openCompanySignOnlineForDetail(String projectOrderId, Boolean isFirstScreen, Byte contractType) {
	String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(projectOrderId);
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(convertProjectOrderId);
	if (Objects.isNull(projectInfoDTO)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目信息不存在");
	}
	boolean openCompanySignOnline = commonContractService.openCompanySignOnline(projectInfoDTO);
	if (isFirstScreen) {
		return openCompanySignOnline;
	}
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return openCompanySignOnline;
	}
	//正签&非首屏
	ContractSourceDataBO contractSourceDataBO = ContractDetailContextHandler.getContext().getContractSourceDataBO();
	if (contractSourceDataBO == null || CollectionUtils.isEmpty(contractSourceDataBO.getPersonalContractDataList()) || contractSourceDataBO.getPlanAllDTO() == null) {
		return openCompanySignOnline;
	}
	//正签分公司code
	String organizationCode = contractSourceDataBO.getPlanAllDTO().getPlanInfo().getOrganizationCode();
	List<String> organizationCodeList = Optional.ofNullable(contractSourceDataBO.getPersonalContractDataList())
		.orElse(Collections.emptyList())
		.stream()
		.map(ContractSourceDataBO.PersonalContractData::getOrganizationCode)
		.filter(Objects::nonNull)
		.collect(Collectors.toList());
	organizationCodeList.add(organizationCode);
	organizationCodeList = organizationCodeList.stream().distinct().collect(Collectors.toList());
	if (organizationCodeList.size() > 1) {
		return false;
	}
	return openCompanySignOnline;
}

