private void dealSignInfoFromLatestFormal(String projectOrderId, ContractSignInfoDetail signInfoDetail) {
	Contract latestFormalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode())
		.stream()
		.filter(item -> Objects.equals(ContractStatusEnum.FINISH.getCode(), item.getStatus()))
		.findFirst().orElse(null);

	if (latestFormalContract == null) {
		throw new NrsBusinessException("未获取到最新已签署的正签合同，无法发起补充协议或和解协议");
	}

	String contractCode = latestFormalContract.getContractCode();

	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contractCode)
		.stream().filter(item -> StringUtils.isNotBlank(item.getFieldValue())).collect(Collectors.toList());
	Map<String, String> fieldMapTemp = Maps.newHashMap();
	contractFieldList.forEach(contractField -> fieldMapTemp.put(contractField.getFieldKey(), contractField.getFieldValue()));
	fieldMapTemp.remove("companySignTime");
	fieldMapTemp.remove("userSignTime");
	fieldMapTemp.remove("launchSupplementType");
	BeanUtil.fillBeanWithMap(fieldMapTemp, signInfoDetail, true);
}

public SupplementItemInfo buildSupplementItemInfo(Contract contract, Map<String, String> fieldMap) {
	SupplementItemInfo supplementItemInfo = new SupplementItemInfo();
	if (contract != null) {
		// 取出已保存数据进行回填
		BeanUtil.fillBeanWithMap(fieldMap, supplementItemInfo, true);

		//合同是正式套餐&线下签约的&为合并发起模式的，需要获取补充协议的附件
		if (contract.getType().equals(ContractTypeEnum.PACKAGE_FORMAL.getCode()) && contract.getSignChannelType()
			.equals(SignChannelTypeEnum.OFFLINE.getCode())) {
			List<String> relationContractList = contractRelationService.getRelationList(contract.getContractCode())
				.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
			List<Contract> contractList = contractService.getListByContractCodes(relationContractList, false);
			Contract supplementContract = contractList.stream().filter(item -> item.getType().equals(ContractTypeEnum.SUPPLEMENT.getCode()))
				.findFirst()
				.orElse(null);
			if (supplementContract != null) {
				supplementItemInfo.setSupplementAttachUrl(contractBusinessService.getOfflineContractByCode(supplementContract.getContractCode()));
			}
		}
	}
	return supplementItemInfo;
}

public SettlementItemInfo buildSettlementItemInfo(Contract contract, Map<String, String> fieldMap) {
	SettlementItemInfo settlementItemInfo = new SettlementItemInfo();
	if (contract != null) {
		// 取出已保存数据进行回填
		BeanUtil.fillBeanWithMap(fieldMap, settlementItemInfo, true);
	}
	return settlementItemInfo;
}

