	/**
	 * 生成资金存管合同
	 * @param escrowContractSubmitReq
	 * @return
	 */
	public ContractSubmitBaseResDTO generateEscrowContract(EscrowContractSubmitReq escrowContractSubmitReq, Boolean boolSystemGenerate) {
		if (boolSystemGenerate) {
			HeaderContext.getContext().setOperatorUcId(SYSTEM_CREATE_UCID);
			HeaderContext.getContext().setOperatorName(SYSTEM_CREATE_NAME);
		}
		String projectOrderId = escrowContractSubmitReq.getProjectOrderId();
		//幂等,如果合同已经生成,则直接返回
		Contract contract = contractService.getContractInfo(projectOrderId, ContractTypeEnum.FUND_ESCROW.getCode());
		if (contract != null && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			//如果是待签署和签署完成直接跳转到去签署页
			if (ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus())) {
				return ContractSubmitBaseResDTO.builder()
					.contractCode(contract.getContractCode())
					.build();
			} else if (ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
				throw new NrsBusinessException("合同已签署,请刷新重试", Level.WARN);
			} else if (ContractStatusEnum.PENDING_COMPANY_SIGN.getCode().equals(contract.getStatus())) {
				throw new NrsBusinessException("签约完成，合同盖章中,请稍候... ", Level.WARN);
			} else if (ContractStatusEnum.PENDING_THIRD_PARTY_SEAL.getCode().equals(contract.getStatus())) {
				throw new NrsBusinessException("签约完成，银行盖章中，请稍候... ", Level.WARN);
			} else {
				throw new NrsBusinessException("合同状态异常,请刷新重试" + projectOrderId, Level.ERROR);
			}
		}
		//如果合同不存在,则生成合同
		//1.组装合同生成参数
		ContractReqDTO contractReq = buildEscrowContractSubmitReq(projectOrderId);
		//2.调用通用方法生成合同
		ContractSubmitResDTO resDTO = contractSubmitService.submit(contractReq);
		return ContractSubmitBaseResDTO.builder()
			.contractCode(resDTO.getContractCode())
			.build();
	}

	/**
	 * 存管协议参数组装
	 * @param projectOrderId
	 * @return
	 */
	private ContractReqDTO buildEscrowContractSubmitReq(String projectOrderId) {
		//查询存管账户信息
		EscrowAccountDetailDTO escrowDetail = escrowRpc.queryEscrowAccountInfo(projectOrderId, FundEscrowBusinessTypeEnum.DECORATE_PROJECT.getCode());
		if (StringUtils.isAnyBlank(escrowDetail.getEscrowAccountName(), escrowDetail.getUserInfo().getPhone(), escrowDetail.getUserInfo().getIdNubmer(), escrowDetail.getUserInfo().getIdType())) {
			throw new NrsBusinessException("存管账户信息不全,无法生成合同" + projectOrderId);
		}
		//证件号和手机号解密
		Map<String, String> encryptMap = cipherService.decrypt(Arrays.asList(escrowDetail.getUserInfo().getPhone(), escrowDetail.getUserInfo().getIdNubmer()));
		if (StringUtils.isAnyBlank(encryptMap.get(escrowDetail.getUserInfo().getPhone()), encryptMap.get(escrowDetail.getUserInfo().getIdNubmer()))) {
			throw new NrsBusinessException("存管账户信息解密失败,无法生成合同" + projectOrderId);
		}
		return ContractReqDTO.builder()
			.contractBaseInfo(ContractBaseInfoReq.builder()
				.projectOrderId(projectOrderId)
				.contractType(ContractTypeEnum.FUND_ESCROW.getCode())
				.build())
			.projectInfo(ContractProjectInfoReq.builder().build())
				.businessInfo(BusinessInfoDetail.builder().build())
			.signInfo(ContractSignInfoReq.builder()
				.contractObjectType(ContractObjectTypeEnum.PERSON.getCode())
				.signChannelType(SignChannelTypeEnum.ONLINE.getCode())
				.userSignType(UserSignTypeEnum.SIGN.getCode())
				.ownerName(escrowDetail.getEscrowAccountName())
				.ownerPhone(encryptMap.get(escrowDetail.getUserInfo().getPhone()))
				.ownerCertificateNo(encryptMap.get(escrowDetail.getUserInfo().getIdNubmer()))
				.ownerCertificateType(CertificateTypeEnum.lftToContractCertificateType(escrowDetail.getUserInfo().getIdType()))
				.build())
			.build();
	}
}

