public boolean checkContractField(ContractReqDTO contractReq, String functionName) {
	if (StringUtils.isBlank(functionName)) {
		return true;
	}

	Method method = ReflectionUtils.findMethod(this.getClass(), functionName, ContractReqDTO.class);
	if (method == null) {
		LOGGER.error("ContractFieldCheckService.checkContractField method not found, functionName:{}", functionName);
		return true;
	}

	Object result = ReflectionUtils.invokeMethod(method, this, contractReq);
	return result instanceof Boolean && Boolean.TRUE.equals(result);
}

public boolean checkBrandList(ContractReqDTO contractReq) {
	List<BrandInfo> brandList = contractReq.getBusinessInfo().getBrandList();
	if (brandList == null || brandList.isEmpty()) {
		return false;
	}
	ContractCityCompanyInfo contractCityCompanyInfo = ContractContextHandler.getContractCityCompanyInfo();
	String companyCode = Objects.requireNonNull(contractCityCompanyInfo).getCompanyCode();

	BigDecimal dueTotalAmount = BigDecimal.ZERO;
	BigDecimal quoteTotalAmount = BigDecimal.ZERO;
	Set<String> errorBrandSet = new HashSet<>();
	BigDecimal percent = contractApolloConfig.getAdvanceBrandDueAmountPercent();
	for (BrandInfo brandInfo : brandList) {
		String brandName = contractApolloConfig.getBrandNameByCode(brandInfo.getBrandCode(), companyCode);
		// 品类编号不在枚举中
		if (StringUtils.isBlank(brandName)) {
			return false;
		}
		if (brandInfo.getDueAmount() == null || brandInfo.getQuoteAmount() == null) {
			return false;
		}
		BigDecimal dueAmount = brandInfo.getDueAmount();
		BigDecimal quoteAmount = brandInfo.getQuoteAmount();

		if (BigDecimalFormatUtils.multiply(quoteAmount, percent).compareTo(dueAmount) > 0 ){
			errorBrandSet.add(brandName);
		}
		dueTotalAmount = dueTotalAmount.add(dueAmount);
		quoteTotalAmount = quoteTotalAmount.add(quoteAmount);
	}

	if (!CollectionUtils.isEmpty(errorBrandSet)) {
		String errorBrandString = String.join("、", errorBrandSet);
		String formattedPercent = percent.multiply(BigDecimal.valueOf(100)).setScale(0, RoundingMode.UP) + "%";
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), errorBrandString + "的预收金额小于报价金额的" + formattedPercent + "，请重新输入", Level.WARN);
	}

	// 预收金额总计不正确
	if (dueTotalAmount.compareTo(contractReq.getAmountInfo().getDueTotalAmount()) != 0) {
		return false;
	}

	// 报价金额总计不正确
	if (quoteTotalAmount.compareTo(contractReq.getAmountInfo().getQuoteTotalAmount()) != 0) {
		return false;
	}

	return true;
}

public boolean checkBrandTotalAmount(ContractReqDTO contractReq) {
	String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	Integer relateFundType = FundRelateContractMapping.obtainFundTypeByContractType(contractType);
	if (relateFundType == null) {
		return true;
	}

	FundInfo relateFundInfo = fundInfoService.getFundByOrderIdAndFundType(projectOrderId, relateFundType);
	if (relateFundInfo == null) {
		return true;
	}

	return contractReq.getAmountInfo().getDueTotalAmount().compareTo(relateFundInfo.getPaidAmount()) >= 0;
}

public boolean checkAdvanceAmount(ContractReqDTO contractReq) {
	BigDecimal expectContractAmount = contractReq.getProjectInfo().getExpectContractAmount();
	BigDecimal quoteExpectContractAmount = contractReq.getProjectInfo().getQuoteExpectContractAmount();
	BigDecimal advanceAmount = contractReq.getProjectInfo().getAdvanceAmount();
	Byte businessType = contractReq.getProjectInfo().getBusinessType();
	// 先从 projectInfo 获取 advanceRate
	BigDecimal advanceRate = contractReq.getProjectInfo().getAdvanceRate();
	if (contractUnifyService.getAdvanceFromQuotation(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getContractBaseInfo().getContractType(), businessType)) {
		expectContractAmount = contractReq.getQuotation().getExpectContractAmount();
		quoteExpectContractAmount = contractReq.getQuotation().getExpectContractAmount();
		advanceAmount = contractReq.getQuotation().getAdvanceAmount();
		// 如果开启了预报价，则从预报价模块获取
		advanceRate = contractReq.getQuotation().getAdvanceRate();
	}

	if (expectContractAmount != null) {
		if (expectContractAmount.compareTo(BigDecimal.ZERO) <= 0) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "预估合同额必须大于0");
		}

		//预估合同额不能小于报价预估合同额(仅整装校验)
		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			if (expectContractAmount.compareTo(quoteExpectContractAmount) < 0) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, String.format("预估合同额不可小于%s，请调整后重试", quoteExpectContractAmount.toPlainString()));
			}
		} else if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
			if (expectContractAmount.compareTo(contractApolloConfig.getAdvanceReformMinAmount()) < 0 || expectContractAmount.compareTo(contractApolloConfig.getAdvanceReformMaxAmount()) > 0) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, String.format("预估合同额范围为%s~%s，请调整后重试",
						contractApolloConfig.getAdvanceReformMinAmount().toPlainString(), contractApolloConfig.getAdvanceReformMaxAmount().toPlainString()));
			}
		}

		// 如果请求传入的「首期款比例」为空，则取默认比例 20%
		BigDecimal minAdvanceAmount = expectContractAmount.multiply(advanceRate != null ? advanceRate : FundTaskTypeEnum.ADVANCE_COLLECTION_PROGRESS.getRate());
		// zqy 测试用
		LOGGER.info("「首期款比例调整」，请求传入比例为: {}, minAdvanceAmount: {}", advanceRate, minAdvanceAmount);
		// 首期款金额最大不可超过预估合同金额的70%
		BigDecimal maxAdvanceAmount = expectContractAmount
			.multiply(new BigDecimal("0.7")).setScale(2, RoundingMode.UP);
		if (minAdvanceAmount.compareTo(advanceAmount) > 0 || advanceAmount.compareTo(maxAdvanceAmount) > 0) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS,
					String.format("%s<=首期款金额<=%s,", AmountUtil.getShowAmount(minAdvanceAmount).toPlainString(), AmountUtil.getShowAmount(maxAdvanceAmount).toPlainString())+"首期款金额必须在预估合同金额的20%~70%范围内");
		}
	}

	return true;
}

public boolean checkAdvanceFileSize(ContractReqDTO contractReq) {
	//获取上传报价单文件
	List<File> preQuotationFileUrl = contractReq.getQuotation().getPreQuotationFileUrl();
	if (CollectionUtils.isEmpty(preQuotationFileUrl)) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "首期合同报价单不能为空");
