@Service
@Slf4j
public class ContractFieldHandler {

	@Resource
	private ContractFieldService contractFieldService;

	public static <T> List<T> parseFieldToList(ContractField field, Class<T> clazz) {
		if (field == null || StringUtils.isBlank(field.getFieldValue())) {
			return Collections.emptyList();
		}

		try {
			Type listType = TypeToken.getParameterized(List.class, clazz).getType();
			return new Gson().fromJson(field.getFieldValue(), listType);
		} catch (Exception e) {
			LOGGER.error("解析字段失败, fieldKey: {}, fieldValue: {}",
				field.getFieldKey(), field.getFieldValue(), e);
			return Collections.emptyList();
		}
	}

	/**
	 * 从正签草稿中移除报价单
	 */
	public void removeBillCodeFromContractField(ContractRelation formalContract, String billCode) {
		removeFromListField(formalContract.getContractCode(), "billCodeInfoList", BillCodeInfo.class,
			billCodeInfo -> ObjectUtil.equal(billCodeInfo.getBillCode(), billCode));
		removeFromListField(formalContract.getContractCode(), "billCodeList", String.class,
			code -> ObjectUtil.equal(code, billCode));

	}

	/**
	 * 从正签草稿中移除协同报价单对应的 S 单
	 */
	public void removeSubOrderNoFromContractField(ContractRelation formalContract, List<String> subOrderNos) {
		removeFromListField(formalContract.getContractCode(), "subOrderInfoList", SubOrderInfo.class,
			subOrderInfo -> subOrderNos.contains(subOrderInfo.getSubOrderNo()));
	}

	/**
	 * 从正签草稿中移除变更单
	 */
	public void removeChangeOrderIdFromContractField(ContractRelation formalContract, String changeOrderId) {
		removeFromListField(formalContract.getContractCode(), "changeOrderInfoList", ChangeOrderInfo.class,
			changeOrderInfo -> ObjectUtil.equal(changeOrderInfo.getChangeOrderId(), changeOrderId));
	}

	/**
	 * 从合同字段的 JSON 列表中移除满足条件的元素，并持久化
	 *
	 * @param contractCode 合同编号
	 * @param fieldKey     字段 key
	 * @param clazz        列表元素类型
	 * @param removeIf     移除条件
	 */
	private <T> void removeFromListField(String contractCode, String fieldKey, Class<T> clazz, Predicate<T> removeIf) {
		ContractField field = contractFieldService.getByContractCodeAndKey(contractCode, fieldKey);
		List<T> list = parseFieldToList(field, clazz);
		if (list.isEmpty()) {
			return;
		}
		list.removeIf(removeIf);
		field.setFieldValue(JSON.toJSONString(list));
		contractFieldService.updateContractField(field.getContractCode(), field.getFieldKey(), field.getFieldValue());
	}

}

public static <T> List<T> parseFieldToList(ContractField field, Class<T> clazz) {
	if (field == null || StringUtils.isBlank(field.getFieldValue())) {
		return Collections.emptyList();
	}

	try {
		Type listType = TypeToken.getParameterized(List.class, clazz).getType();
		return new Gson().fromJson(field.getFieldValue(), listType);
	} catch (Exception e) {
		LOGGER.error("解析字段失败, fieldKey: {}, fieldValue: {}",
			field.getFieldKey(), field.getFieldValue(), e);
		return Collections.emptyList();
	}
}

public void removeBillCodeFromContractField(ContractRelation formalContract, String billCode) {
	removeFromListField(formalContract.getContractCode(), "billCodeInfoList", BillCodeInfo.class,
		billCodeInfo -> ObjectUtil.equal(billCodeInfo.getBillCode(), billCode));
	removeFromListField(formalContract.getContractCode(), "billCodeList", String.class,
		code -> ObjectUtil.equal(code, billCode));

}

public void removeSubOrderNoFromContractField(ContractRelation formalContract, List<String> subOrderNos) {
	removeFromListField(formalContract.getContractCode(), "subOrderInfoList", SubOrderInfo.class,
		subOrderInfo -> subOrderNos.contains(subOrderInfo.getSubOrderNo()));
}

public void removeChangeOrderIdFromContractField(ContractRelation formalContract, String changeOrderId) {
	removeFromListField(formalContract.getContractCode(), "changeOrderInfoList", ChangeOrderInfo.class,
		changeOrderInfo -> ObjectUtil.equal(changeOrderInfo.getChangeOrderId(), changeOrderId));
}

private <T> void removeFromListField(String contractCode, String fieldKey, Class<T> clazz, Predicate<T> removeIf) {
	ContractField field = contractFieldService.getByContractCodeAndKey(contractCode, fieldKey);
	List<T> list = parseFieldToList(field, clazz);
	if (list.isEmpty()) {
		return;
	}
	list.removeIf(removeIf);
	field.setFieldValue(JSON.toJSONString(list));
	contractFieldService.updateContractField(field.getContractCode(), field.getFieldKey(), field.getFieldValue());
}

