@Component
@Slf4j
public class ContractHomeOrderNoChangeService {

    @Resource
    private ContractService contractService;

    /**
     * 主订单号变更
     */
    @Transactional
    public ChangeResultDTO doChange(String sourceMainOrderNo, String targetMainOrderNo, Integer changeType) {
        if (!Objects.equals(HomeOrderChangeTypeEnum.BIND_DECORATE_COMMISSION.getChangeType(), changeType)) {
            return ChangeResultDTO.builder()
                    .result(Boolean.FALSE)
                    .build();
        }
        ContractHomeOrderNoChangeResultDTO resultDTO = new ContractHomeOrderNoChangeResultDTO();
        //查询协同原主订单下合同信息
        //作废原主订单下协议项目，个性化首期合同
        List<String> deleteContractCodeList = new ArrayList<>();
        List<Contract> personalAdvanceContractList = contractService.getContractList(targetMainOrderNo, ContractTypeEnum.PERSONALIZED_CONTRACT);
        for (Contract contract : personalAdvanceContractList) {
            deleteContractCodeList.add(contract.getContractCode());
        }
        if (CollectionUtil.isNotEmpty(deleteContractCodeList)) {
            contractService.deleteSoftByContractCodes(deleteContractCodeList);
        }
        // 销售合同换单号
        List<String> updateContractCodeList = new ArrayList<>();
        List<Contract> personalContractList = contractService.getContractList(sourceMainOrderNo, ContractTypeEnum.getPersonalizedRelevantContractList());
        for (Contract contract : personalContractList) {
            contract.setProjectOrderId(targetMainOrderNo);
            updateContractCodeList.add(contract.getContractCode());
            contractService.update(contract);
        }


        resultDTO.setUpdateContractCodeList(updateContractCodeList);
        resultDTO.setDeleteContractCodeList(deleteContractCodeList);
        return ChangeResultDTO.builder()
                .result(Boolean.TRUE)
                .serviceId(Constant.DOMAIN_EVENT_SERVER_NAME)
                .handleResultStr(JSON.toJSONString(resultDTO))
                .build();
    }

    @Transactional
    public ChangeResultDTO doRevert(String sourceHomeOrderNo, String targetHomeOrderNo, Integer changeType, String changeResultStr) {
        if (!Objects.equals(HomeOrderChangeTypeEnum.BIND_DECORATE_COMMISSION.getChangeType(), changeType)) {
            return ChangeResultDTO.builder()
                    .result(Boolean.FALSE)
                    .build();
        }
        ContractHomeOrderNoChangeResultDTO resultDTO = JSON.parseObject(changeResultStr, ContractHomeOrderNoChangeResultDTO.class);
        //回滚销售合同换单号
        if (CollectionUtil.isNotEmpty(resultDTO.getUpdateContractCodeList())) {
            List<Contract> contractList = contractService.getListByContractCodesAndStatus(resultDTO.getUpdateContractCodeList(), ContractStatusEnum.ALL_STATUS_LIST);
            for (Contract contract : contractList) {
                if (!targetHomeOrderNo.equals(contract.getProjectOrderId())) {
                    continue;
                }
                contract.setProjectOrderId(sourceHomeOrderNo);
                contractService.update(contract);
            }
        }
        //回滚作废原主订单下协议项目，个性化首期合同
        if (CollectionUtil.isNotEmpty(resultDTO.getDeleteContractCodeList())) {
            for (String contractCode : resultDTO.getDeleteContractCodeList()) {
                contractService.recoverContractByContractCode(contractCode);
            }
        }
        return ChangeResultDTO.builder()
                .result(Boolean.TRUE)
                .serviceId(Constant.DOMAIN_EVENT_SERVER_NAME)
                .build();
    }


}

