@Service
@Slf4j
public class ContractMergeLaunchComputer {

	@Resource
	private ContractService contractService;

	@Resource
	private QuotationFeignService quotationFeignService;

	@Resource
	private CommonBusinessService commonBusinessService;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Resource
	private ContractMergeLaunchComputer contractMergeLaunchComputer;

	@Resource
	private CommonContractService commonContractService;
	@Resource
	private ContractBusinessService contractBusinessService;

	@Resource
	private AttachCommonService attachCommonService;
	@Autowired
	private ContractUnifyService contractUnifyService;

	/**
	 * 计算与当前合同需要一起合并发起合同类型
	 */
	public List<Byte> computeContractType(Byte contractType){
//		Map<Byte, List<MergeLaunchRule>> mergeLaunchConfig = contractApolloConfig.getMergeLaunchConfig();
		Map<Byte, List<MergeLaunchRule>> mergeLaunchConfig = contractApolloConfig.getMergeLaunchConfigV2();
		List<MergeLaunchRule> mergeLaunchRules = mergeLaunchConfig.get(contractType);
		if (mergeLaunchRules == null || CollectionUtils.isEmpty(mergeLaunchRules)) {
			return new ArrayList<>();
		}
		List<Byte> contractTypes = new ArrayList<>();
		for (MergeLaunchRule mergeLaunchRule : mergeLaunchRules) {
			String ruleStr = mergeLaunchRule.getRule();
			if (StringUtils.isBlank(ruleStr)) {
				contractTypes.add(mergeLaunchRule.getContractType());
				continue;
			}
			List<String> ruleList = Arrays.asList(ruleStr.split("&"));
			boolean machRule = dealMachRule(ruleList);
			if(machRule){
				contractTypes.add(mergeLaunchRule.getContractType());
			}
		}
		LOGGER.info("合并发起合同类型计算，订单号：{},合同类型：{},contractTypes：{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId(), contractType, contractTypes);
		return contractTypes;
	}

	/**
	 * 计算规则匹配结果
	 */
	private boolean dealMachRule(List<String> ruleList) {
		boolean mach = true;
		for (String rule : ruleList) {
			try {
				Method method = contractMergeLaunchComputer.getClass().getMethod(rule, null);
				Boolean invokeResult = (Boolean) method.invoke(contractMergeLaunchComputer, null);
				if (!invokeResult) {
					return false;
				}
			} catch (NoSuchMethodException e) {
				LOGGER.error("计算规则匹配结果时，调用方法不存在,方法名：{},threadId:{}", rule, Thread.currentThread().getId(), e);
				if (!KeUtils.isEnvironmentActive("test")) {
					throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), e.getMessage());
				}
				return false;
			} catch (Exception e) {
				LOGGER.error("计算规则匹配结果异常,projectOrderId:{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId(), e);
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "计算合并发起合同类型出错", Level.WARN);
			}
		}
		return mach;
	}

	/**
	 * 是否为全案
	 */
	public boolean fullService() {
		Integer contractMode = ContractContextHandler.getContractReq().getContractBaseInfo().getContractMode();
		return ContractModeEnum.FULL_SERVICE.getCode().equals(contractMode);
	}

	/**
	 * 是否为非全案
	 */
	public boolean noFullService(){
		return !fullService();
	}

	/**
	 * 是否为2.5订单
	 */
	public boolean process_v2_5() {
		String projectOrderId = ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId();
		Byte contractType = ContractContextHandler.getContractReq().getContractBaseInfo().getContractType();
		return commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType);
	}

	/**
	 * 是否有个性化报价单
	 */
	public boolean havePersonalQuote() {
		ContractSourceDataBO contractSourceDataBO = ContractContextHandler.getContractSourceDataBO();
		if (contractSourceDataBO == null) {
			return false;
		}
		return !CollectionUtils.isEmpty(contractSourceDataBO.getPersonalContractDataList());
	}

	/**
	 * 是否存在非草稿有效合同状态的个性合同
	 */
	public boolean noSignPersonalContract() {
		String projectOrderId = ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId();
		//获取报价单主体
		String companyCode = ContractContextHandler.getPlanAllDTO().getPlanInfo().getOrganizationCode();
		boolean processV25 = ContractContextHandler.getContext().isProcessV25();
		Byte businessType = ContractContextHandler.getContext().getBusinessType();
		//2.5团装C报价主体取值不同
		if (processV25 && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			List<ContractSourceDataBO.PersonalContractData> personalContractDataList = ContractContextHandler.getContractSourceDataBO().getPersonalContractDataList();
			if (!CollectionUtils.isEmpty(personalContractDataList)) {
				companyCode = personalContractDataList.get(0).getOrganizationCode();
			}
		}
		final String finalCompanyCode = companyCode;
		//获取非草稿有效合同状态的个性合同
		Contract personalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode()).stream().filter(item -> ContractStatusEnum.validStatusWithoutDraft.contains(item.getStatus())).filter(m -> m.getCompanyCode().equals(finalCompanyCode)).findFirst().orElse(null);
		return personalContract == null;
	}
	public boolean defaultFalse() {
		return false;
	}

	/**
	 * 是否为整装
	 */
	public boolean houseBusinessType() {
		Byte businessType = ContractContextHandler.getContext().getBusinessType();
		return BusinessTypeEnum.getHouseCertificate25ModeList().contains(businessType);
	}

	/**
	 * 判断是否需要发起关联订单的解约协议
	 */
	public boolean launchTerminal(){
		try {
			String projectOrderId = ContractContextHandler.getContext().getContractReq().getContractBaseInfo().getProjectOrderId();
			return contractBusinessService.needLaunchRelationTerminalContract(projectOrderId);
		} catch (Exception e) {
			LOGGER.error("判断是否需要发起关联订单的解约协议异常,projectOrderId:{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId(), e);
			return false;
		}
	}
	/**
	 * 是否有代理人授权
	 */
	public boolean hasAuthAgent() {
		ContractReqDTO contractReq = ContractContextHandler.getContext().getContractReq();
		ContractSignInfoReq signInfo = contractReq.getSignInfo();
		if (signInfo == null) {
			return false;
		}

		if (!SignChannelTypeEnum.ONLINE.getCode().equals(signInfo.getSignChannelType())) {
			return false;
		}

		if (!EntrustSignTypeEnum.ONLINE.getCode().equals(signInfo.getEntrustSignType())) {
			return false;
		}

		ContractBaseInfoReq contractBaseInfo = contractReq.getContractBaseInfo();
		if (!ContractTypeEnum.HAVE_AGENT_AUTH_CONTRACT_TYPES.contains(contractBaseInfo.getContractType())) {
			return false;
		}

		Byte haveAgent = signInfo.getHaveAgent();
		Byte contractObjectType = signInfo.getContractObjectType();
		if (!ContractObjectTypeEnum.PERSON.getCode().equals(contractObjectType)) {
			return false;
		}

		String projectOrderId = contractBaseInfo.getProjectOrderId();
		boolean attachOcrOpenCity = attachCommonService.attachOcrOpenCity(projectOrderId);
		if (!attachOcrOpenCity) {
			return false;
		}


		if (CommonEnum.YES.getCode().equals(haveAgent)) {
			// 存在代理人
			List<ContractUser> contractUserList = commonContractService.queryAuthedAgentInfoList(contractBaseInfo.getProjectOrderId());

			String agentCertificateNo = signInfo.getAgentCertificateNo();
			return contractUserList.stream().noneMatch(user -> StringUtils.equals(user.getCertificateNo(), agentCertificateNo));
		}

		return false;
	}

	/**
	 * 是否有上传正签图纸
	 *
	 * @return
	 */
	public boolean hasUploadFormalDrawing() {
		boolean processV25 = ContractContextHandler.getContext().isProcessV25();
		Byte businessType = ContractContextHandler.getContext().getBusinessType();
		if (!processV25) {
			return false;
		}
		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			//2.5整装正签图纸必定上传
			return true;
		}
		//翻新全案场景，如果线下签约且有图纸附件，则认为有上传正签图纸
		Byte signChannelType = ContractContextHandler.getContext().getContractReq().getSignInfo().getSignChannelType();
		List<File> drawingAttachUrl = ContractContextHandler.getContext().getContractReq().getSignInfo().getDrawingAttachUrl();
		if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)
			&& SignChannelTypeEnum.OFFLINE.getCode().equals(signChannelType)) {
			if (CollectionUtils.isEmpty(drawingAttachUrl)) {
				LOGGER.info("翻新全案场线下签约场景，无上传图纸合同，订单号：{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId());
				return false;
			} else {
				LOGGER.info("翻新全案场线下签约场景，有上传图纸合同，订单号：{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId());
				return true;
			}
		}

		DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = ContractContextHandler.getContext().getDrawingDTO();
		if (deliverDrawingDTO == null || CollectionUtils.isEmpty(deliverDrawingDTO.getDrawingDetailDTOList())) {
			return false;
		}
		List<String> drawingPdfUrl = deliverDrawingDTO.getDrawingDetailDTOList().stream()
			.filter(item -> ObjectUtil.equals(item.getBillType(), PlanAttachment.基础图纸))
			.filter(item -> DrawingEnum.ConstructionFileExtensionEnum.PDF.getCode().equals(item.getExtensionType()))
			.map(DrawingDTO.DrawingDetailDTO::getUrl)
			.collect(Collectors.toList());
		boolean isEmpty = !CollectionUtils.isEmpty(drawingPdfUrl);
		LOGGER.info("是否有上传正签图纸，订单号：{},isEmpty：{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId(), isEmpty);
		return isEmpty;
	}

	/**
	 * 是否选择了同步发起补充协议
	 */
	public boolean mergeLaunchSupplement() {
		ContractReqDTO contractReq = ContractContextHandler.getContext().getContractReq();
		ContractSignInfoReq signInfo = contractReq.getSignInfo();

		if (signInfo == null) {
			return false;
		}

		return LaunchSupplementTypeEnum.MERGE_LAUNCH_SUPPLEMENT.getCode().equals(signInfo.getLaunchSupplementType());
	}

	/**
	 * 是否合并发起设计合同
	 * 被窝整装+正签报价单报设计费
	 */
	public boolean mergeLaunchDesign() {
		// 设计费报价未开城
		ContractReqDTO contractReq = ContractContextHandler.getContext().getContractReq();
		DesignQuoteFeeDTO designQuoteFeeDTO = ContractContextHandler.getContext().getDesignQuoteFeeDTO();
		if (!contractUnifyService.designFeeFromQuote(contractReq.getContractBaseInfo().getProjectOrderId())) {
			return false;
		}
		MiniPayChannelAppNameEnum miniProgramType = commonBusinessService.getMiniProgramType(contractReq.getContractBaseInfo().getProjectOrderId());
		return ObjectUtil.isNotEmpty(designQuoteFeeDTO) && designQuoteFeeDTO.isHaveDesignQuote() && MiniPayChannelAppNameEnum.被窝.equals(miniProgramType);
	}

}

