public boolean hasAuthAgent() {
	ContractReqDTO contractReq = ContractContextHandler.getContext().getContractReq();
	ContractSignInfoReq signInfo = contractReq.getSignInfo();
	if (signInfo == null) {
		return false;
	}

	if (!SignChannelTypeEnum.ONLINE.getCode().equals(signInfo.getSignChannelType())) {
		return false;
	}

	if (!EntrustSignTypeEnum.ONLINE.getCode().equals(signInfo.getEntrustSignType())) {
		return false;
	}

	ContractBaseInfoReq contractBaseInfo = contractReq.getContractBaseInfo();
	if (!ContractTypeEnum.HAVE_AGENT_AUTH_CONTRACT_TYPES.contains(contractBaseInfo.getContractType())) {
		return false;
	}

	Byte haveAgent = signInfo.getHaveAgent();
	Byte contractObjectType = signInfo.getContractObjectType();
	if (!ContractObjectTypeEnum.PERSON.getCode().equals(contractObjectType)) {
		return false;
	}

	String projectOrderId = contractBaseInfo.getProjectOrderId();
	boolean attachOcrOpenCity = attachCommonService.attachOcrOpenCity(projectOrderId);
	if (!attachOcrOpenCity) {
		return false;
	}


	if (CommonEnum.YES.getCode().equals(haveAgent)) {
		// 存在代理人
		List<ContractUser> contractUserList = commonContractService.queryAuthedAgentInfoList(contractBaseInfo.getProjectOrderId());

		String agentCertificateNo = signInfo.getAgentCertificateNo();
		return contractUserList.stream().noneMatch(user -> StringUtils.equals(user.getCertificateNo(), agentCertificateNo));
	}

	return false;
}

public boolean hasUploadFormalDrawing() {
	boolean processV25 = ContractContextHandler.getContext().isProcessV25();
	Byte businessType = ContractContextHandler.getContext().getBusinessType();
	if (!processV25) {
		return false;
	}
	if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
		//2.5整装正签图纸必定上传
		return true;
	}
	//翻新全案场景，如果线下签约且有图纸附件，则认为有上传正签图纸
	Byte signChannelType = ContractContextHandler.getContext().getContractReq().getSignInfo().getSignChannelType();
	List<File> drawingAttachUrl = ContractContextHandler.getContext().getContractReq().getSignInfo().getDrawingAttachUrl();
	if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)
		&& SignChannelTypeEnum.OFFLINE.getCode().equals(signChannelType)) {
		if (CollectionUtils.isEmpty(drawingAttachUrl)) {
			LOGGER.info("翻新全案场线下签约场景，无上传图纸合同，订单号：{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId());
			return false;
		} else {
			LOGGER.info("翻新全案场线下签约场景，有上传图纸合同，订单号：{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId());
			return true;
		}
	}

	DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = ContractContextHandler.getContext().getDrawingDTO();
	if (deliverDrawingDTO == null || CollectionUtils.isEmpty(deliverDrawingDTO.getDrawingDetailDTOList())) {
		return false;
	}
	List<String> drawingPdfUrl = deliverDrawingDTO.getDrawingDetailDTOList().stream()
		.filter(item -> ObjectUtil.equals(item.getBillType(), PlanAttachment.基础图纸))
		.filter(item -> DrawingEnum.ConstructionFileExtensionEnum.PDF.getCode().equals(item.getExtensionType()))
		.map(DrawingDTO.DrawingDetailDTO::getUrl)
		.collect(Collectors.toList());
	boolean isEmpty = !CollectionUtils.isEmpty(drawingPdfUrl);
	LOGGER.info("是否有上传正签图纸，订单号：{},isEmpty：{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId(), isEmpty);
	return isEmpty;
}

public boolean mergeLaunchSupplement() {
	ContractReqDTO contractReq = ContractContextHandler.getContext().getContractReq();
	ContractSignInfoReq signInfo = contractReq.getSignInfo();

	if (signInfo == null) {
		return false;
	}

	return LaunchSupplementTypeEnum.MERGE_LAUNCH_SUPPLEMENT.getCode().equals(signInfo.getLaunchSupplementType());
}

public boolean mergeLaunchDesign() {
	// 设计费报价未开城
	ContractReqDTO contractReq = ContractContextHandler.getContext().getContractReq();
	DesignQuoteFeeDTO designQuoteFeeDTO = ContractContextHandler.getContext().getDesignQuoteFeeDTO();
	if (!contractUnifyService.designFeeFromQuote(contractReq.getContractBaseInfo().getProjectOrderId())) {
		return false;
	}
	MiniPayChannelAppNameEnum miniProgramType = commonBusinessService.getMiniProgramType(contractReq.getContractBaseInfo().getProjectOrderId());
	return ObjectUtil.isNotEmpty(designQuoteFeeDTO) && designQuoteFeeDTO.isHaveDesignQuote() && MiniPayChannelAppNameEnum.被窝.equals(miniProgramType);
}

