		result.put("firstPartyConnectPhone", decryptMap.getOrDefault(signInfo.getOwnerPhone(), signInfo.getOwnerPhone()));
		//客户证件号
		result.put("customerIdNo", decryptMap.getOrDefault(customerIdNo, customerIdNo));

		Byte haveAgent = signInfo.getHaveAgent();
		if (HaveAgentEnum.NO.getCode().equals(haveAgent)) {
			//无代理人
			result.put("agentName", "/");
			result.put("agentIdNo", "/");
			result.put("agentPhone", "/");
		} else {
			//代理人身份证号
			result.put("agentIdNo", decryptMap.getOrDefault(agentIdNo, agentIdNo));
			//代理人手机
			result.put("agentPhone", decryptMap.getOrDefault(agentPhone, agentPhone));
			//代理人姓名 没有的话 用 /
			result.put("agentName", agentName);
		}

		if (ContractObjectTypeEnum.COMPANY.getCode().equals(signInfo.getContractObjectType())) {
			//客户姓名
			result.put("jiafangXingming", signInfo.getCompanyName());
			//客户手机
			result.put("firstPartyConnectPhone", "/");
			//客户证件号
			result.put("customerIdNo", signInfo.getCompanyCreditCode());
			if (RoleTypeEnum.COMPANY_AGENT.getCode().equals(signInfo.getSignRole())) {
				//代理人身份证号
				result.put("agentIdNo", decryptMap.getOrDefault(companyAgentCertificateNo, companyAgentCertificateNo));
				//代理人手机
				result.put("agentPhone", decryptMap.getOrDefault(companyAgentPhone, companyAgentPhone));
				//代理人姓名 没有的话用 /
				result.put("agentName", signInfo.getCompanyAgentName());
			}
		}
		return result;
	}

	/**
	 * 收款计划
	 */
	public Map<String, Object> getCollectionPlanInfo() {
		HashMap<String, Object> result = new HashMap<>();
		Byte businessType = ContractContextHandler.getContext().getBusinessType();
		boolean processV25 = ContractContextHandler.getContext().isProcessV25();
		CollectionPlanConfigInfo configInfo = ContractContextHandler.getContractReq().getCollectionPlanConfigInfo();
		if (configInfo == null || CollectionUtils.isEmpty(configInfo.getContent())) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "请检查收款计划是否选择", Level.WARN);
		}
		String firstPayAmountText = "";
		String secondPayAmountText = "";
		String thirdPayAmountText = "";
		String firstPayAmount = "";
		String secondPayAmount = "";
		String thirdPayAmount = "";
		String payPlan = "";
		//合同金额
		BigDecimal contractAmount = ContractContextHandler.getPlanAllDTO().getPlanInfo().getContractPriceTotal();
		StringBuilder payPlanBuffer = new StringBuilder();
		StringBuilder payPlanBufferNew = new StringBuilder();
		List<CollectionPlanItem> content = configInfo.getContent();

		for (int i = 0; i < content.size(); i++) {
			CollectionPlanItem item = content.get(i);
			BigDecimal itemAmount = Objects.nonNull(item.getPrice()) && BigDecimal.ZERO.compareTo(item.getPrice()) != 0
				? item.getPrice()
				: contractAmount.multiply(item.getRate()).setScale(2, RoundingMode.HALF_UP);
			payPlanBuffer.append(MessageFormat.format(PAY_PLAN_FORMAT
				, item.getCollectionName(),
				item.getLastPayNode(),
				item.getRate().multiply(new BigDecimal(100)).toString(),
				(new MoneyConvertUtil(itemAmount.toString())).convert(),
				itemAmount.toString()
			));

			if (i == 0 && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25) {
				payPlanBufferNew.append(MessageFormat.format(PAY_PLAN_FORMAT_NEW
					, item.getLastPayNode(),
					item.getRate().multiply(new BigDecimal(100)).toString(),
					(new MoneyConvertUtil(itemAmount.toString())).convert().concat("（¥:").concat(itemAmount.toString()).concat("）")
				)).append("其中合同总金额的20%部分作为定金").append("\n");
			} else {
				payPlanBufferNew.append(MessageFormat.format(PAY_PLAN_FORMAT_NEW
					, item.getLastPayNode(),
					item.getRate().multiply(new BigDecimal(100)).toString(),
					(new MoneyConvertUtil(itemAmount.toString())).convert().concat("（¥:").concat(itemAmount.toString()).concat("）")
				)).append("\n");
			}

			if (Objects.nonNull(item.getPrice())) {
				if (i == 0) {
					firstPayAmount = item.getPrice().toString();
					firstPayAmountText = (new MoneyConvertUtil(item.getPrice().toString())).convert();
				} else if (i == 1) {
					secondPayAmount = item.getPrice().toString();
					secondPayAmountText = (new MoneyConvertUtil(item.getPrice().toString())).convert();
				} else if (i == 2) {
					thirdPayAmount = item.getPrice().toString();
					thirdPayAmountText = (new MoneyConvertUtil(item.getPrice().toString())).convert();
				}
			}
		}
		payPlan = payPlanBuffer.toString();
		//收款计划
		result.put("payPlan", payPlan);
		result.put("payPlanNew", payPlanBufferNew.toString());
		//一期支付金额大写
		result.put("firstPayAmountText", firstPayAmountText);
		//二期支付金额大写
		result.put("secondPayAmountText", secondPayAmountText);
		//三期支付金额大写
		result.put("thirdPayAmountText", thirdPayAmountText);
		//一期支付金额小写
		result.put("firstPayAmount", firstPayAmount);
		//二期支付金额小写
		result.put("secondPayAmount", secondPayAmount);
		//三期支付金额小写
		result.put("thirdPayAmount", thirdPayAmount);
		return result;
	}

	public Map<String, Object> getCoupon() {
		HashMap<String, Object> result = new HashMap<>();
		String couponAmount = "";
