	/**
	 * 材料清单
	 */
	public Map<String, Object> getMaterialList() {
		HashMap<String, Object> result = new HashMap<>();
		Integer projectContractModeCode = ContractContextHandler.getContractReq().getPromiseInfo().getProjectContractModeCode();
		if (!ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS.getCode().equals(projectContractModeCode)
			&& !ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS_V2.getCode().equals(projectContractModeCode) ) {
			return result;
		}
		List<FormalPackageContractFreeformDTO.MaterialItem> materialItemList = new LinkedList<>();
		List<MaterialItemVo> materialList = ContractContextHandler.getContractReq().getPromiseInfo().getMaterialList();
		Map<Integer, MaterialOptionsVo> materialOptionsMap = contractApolloConfig.getMaterialOptionsMap();
		for (MaterialItemVo materialItemVo : materialList) {
			if (!materialOptionsMap.containsKey(materialItemVo.getValue())) {
				LOGGER.error("材料类型不存在:{},projectOrderId:{}", materialItemVo.getValue(),
					ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId());
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "材料类型不存在");
			}
			String unit = (StringUtils.isBlank(materialItemVo.getUnit()) || !materialItemVo.getValue().equals(9999))
				? ""
				: "（".concat(materialItemVo.getUnit()).concat("）");
			//如果是自定义的物料类型，取用户填写的描述
			String description = materialItemVo.getValue().equals(9999) ? materialItemVo.getDescription() : materialOptionsMap.get(materialItemVo.getValue()).getLabel();
			materialItemList.add(
				FormalPackageContractFreeformDTO.MaterialItem.builder()
					.description(description.concat(unit))
					.count(materialItemVo.getCount())
					.build()
			);
		}
		result.put("materialList", JsonUtil.toJsonString(materialItemList));
		return result;
	}

