	public ContractBusinessConfig getContractBusinessConfig(Byte businessType, Integer gbCode, Boolean developerChannel) {
		ContractBusinessConfig contractBusinessConfig;
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			contractBusinessConfig = contractApolloConfig.getGroupContractBusinessConfig().get(gbCode);
		} else {
			/**
			 * 【保修年限修改 1】上层调用方都是 PdfBuilder，可以直接从数据域取出是否开渠的值
			 * 这里 else 分支是其他所有业务类型，逻辑改动的话，
			 */
			contractBusinessConfig = contractApolloConfig.getContractBusinessConfigByGbCodeAndDeveloperChannel(gbCode, developerChannel);
			/**
			 * 【兜底逻辑修改 7】如果没获取到，兜底尝试获取一次非开渠的
			 */
			if (contractBusinessConfig == null) {
				contractBusinessConfig = contractApolloConfig.getContractBusinessConfigByGbCodeAndDeveloperChannel(gbCode, Boolean.FALSE);
			}
		}
		return contractBusinessConfig;
	}

