	 * 设计合同里，优惠前和优惠后金额，如果金额一致的情况下，就不显示优惠后金额的描述。
	 */
	public Map<String, Object> getDesignContractAmountInfo() {
		HashMap<String, Object> result = new HashMap<>();
		String designerLevel = MapUtils.getString(getDesignerLevel(), "designerLevel");
		//设计服务费（优惠前）
		String preDiscountDesignerAmount = MapUtils.getString(getPreDiscountDesignerAmount(), "preDiscountDesignerAmount");
		//设计服务费（优惠后）
		String afterDiscountDesignerAmount = MapUtils.getString(getAfterDiscountDesignerAmount(), "afterDiscountDesignerAmount");
		if (StringUtils.isAnyBlank(designerLevel, preDiscountDesignerAmount, afterDiscountDesignerAmount)) {
			LOGGER.error("参数异常，请检查填写数据(设计师级别、设计服务费（优惠前）、设计服务费（优惠后）)是否完整，designerLevel:{},preDiscountDesignerAmount:{},afterDiscountDesignerAmount:{}", designerLevel, preDiscountDesignerAmount, afterDiscountDesignerAmount);
			throw new NrsBusinessException("参数异常，请检查填写数据(设计师级别、设计服务费（优惠前）、设计服务费（优惠后）)是否完整");
		}
		if (preDiscountDesignerAmount.equals(afterDiscountDesignerAmount)) {
			String template = "本项目提供服务的设计师级别为【%s】，设计服务费总额为：【%s】元（含税价格）。";
			result.put("designContractAmountInfo", String.format(template, designerLevel, preDiscountDesignerAmount));
		} else {
			String template = "本项目提供服务的设计师级别为【%s】，设计服务费总额为：【%s】元（含税价格），优惠后的设计服务费金额为【%s】元（含税价格）。";
			result.put("designContractAmountInfo", String.format(template, designerLevel, preDiscountDesignerAmount, afterDiscountDesignerAmount));
		}
		return result;
	}

	/**
	 * 获取首期款收款比例
	 */
	public Map<String, Object> getAdvanceRate() {
		HashMap<String, Object> result = new HashMap<>();
		ContractReqDTO contractReq = ContractContextHandler.getContext().getContractReq();
		// 先从 projectInfo 获取 advanceRate
		BigDecimal advanceRate = contractReq.getProjectInfo().getAdvanceRate();
		Byte businessType = contractReq.getProjectInfo().getBusinessType();
		// 如果开启了预报价，则从预报价模块获取 advanceRate
		if (contractUnifyService.getAdvanceFromQuotation(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getContractBaseInfo().getContractType(), businessType)) {
			advanceRate = contractReq.getQuotation().getAdvanceRate();
		}
		// zqy 测试用
		LOGGER.info("「首期款比例调整」，请求传入比例为: {}", advanceRate);
		// 如果请求传入的首期款比例为 null，则取默认 20%
		if (advanceRate == null) {
			advanceRate = FundTaskTypeEnum.ADVANCE_COLLECTION_PROGRESS.getRate();
		}
		// 在合同展示，需要将小数转为百分比，比如 0.1 -> 10%。（保留两位小数、四舍五入）
		String advanceRateLabel = String.format("%.0f%%", advanceRate.multiply(new BigDecimal("100")).setScale(2, RoundingMode.HALF_UP));  // %.0f表示不保留小数位
		// 首期款收款比例
		result.put("advanceRate", advanceRateLabel);
		return result;

	}

