	/**
	 * 获取 B 承担部分材料清单
	 *
	 * @return
	 */
	public Map<String, Object> getMaterialForB() {
		HashMap<String, Object> result = new HashMap<>();
		DrawingDTO.DeliverDrawingDTO drawingDTO = ContractContextHandler.getContext().getDrawingDTO();
		Byte contractType = ContractContextHandler.getContext().getContract().getType();
		Byte businessType = ContractContextHandler.getContext().getBusinessType();
		String projectOrderId = ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId();
		// 新房项目上是否为 B 或 BC 付款方式
		boolean bOrBCPaymentType = commonBusinessService.isBOrBCPaymentType(projectOrderId);
		List<String> materialForB = new ArrayList<>();
		if (drawingDTO == null) {
			return result;
		}
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && bOrBCPaymentType) {
				// 正签合同筛选出来基础套餐的配置清单
				List<String> list = drawingDTO.getDrawingDetailDTOList().stream()
					.filter(item -> ObjectUtil.equal(item.getEncodeType(), PlanAttachment.商品清单))
					.map(DrawingDTO.DrawingDetailDTO::getUrl)
					.collect(Collectors.toList());
				materialForB.addAll(list);
				LOGGER.info("团装B承担部分材料清单，正签合同：{}", JSON.toJSONString(list));
			} else if (ContractTypeEnum.PERSONAL.getCode().equals(contractType) && bOrBCPaymentType) {
				// 销售合同筛选出来定软电的配置清单
				List<String> list = drawingDTO.getDrawingDetailDTOList().stream()
					.filter(item -> ObjectUtil.equal(item.getEncodeType(), PlanAttachment.软装配置清单))
					.map(DrawingDTO.DrawingDetailDTO::getUrl)
					.collect(Collectors.toList());
				materialForB.addAll(list);
				LOGGER.info("团装B承担部分材料清单，销售合同：{}", JSON.toJSONString(list));
			}
		} else if(BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)){
			if(ContractTypeEnum.PERSONAL.getCode().equals(contractType) && bOrBCPaymentType)  {
				// 销售合同筛选出来定软电的配置清单
				List<String> list = drawingDTO.getDrawingDetailDTOList().stream()
					.filter(item -> ObjectUtil.equal(item.getEncodeType(), PlanAttachment.软装配置清单))
					.map(DrawingDTO.DrawingDetailDTO::getUrl)
					.collect(Collectors.toList());
				materialForB.addAll(list);
				LOGGER.info("整装B承担部分材料清单，销售合同：{}", JSON.toJSONString(list));
			}
		}
		List<String> imageUrls = new ArrayList<>();
		for (String fileUrl : materialForB) {
			imageUrls.addAll(pdfToImageService.pdf2ImagePublicParallel(fileUrl));
		}
		String signDate = DateUtils.getDateStr(new Date());
		List<FormalPackageContractFreeformDTO.PhotoInfo> photos = imageUrls.stream()
			.map(src -> new FormalPackageContractFreeformDTO.PhotoInfo(src, signDate, false))
			.collect(Collectors.toList());

		if (CollectionUtil.isNotEmpty(photos)) {
			// 设置photos最后一页盖章
			photos.get(photos.size() - 1).setSign(true);
		}
		result.put("materialForB", JsonUtil.toJsonString(photos));
		return result;
	}

	// 获取订单总金额百分比
	public Map<String, Object> getPercentageOfTotalOrderAmount() {
		HashMap<String, Object> result = new HashMap<>();
		Integer gbCode = ContractContextHandler.getContractReq().getProjectInfo().getGbCode();
		Contract contract = ContractContextHandler.getContext().getContract();
		PercentageOfTotalOrderAmountConfig percentageConfigByGbCode = contractApolloConfig.getPercentageConfigByGbCode(gbCode);
		if (percentageConfigByGbCode == null || percentageConfigByGbCode.getPercentageOfTotalOrderAmount() == null) {
			LOGGER.error("参数异常，请检查 Apollo 订单总金额百分比配置, gbCode: {}", gbCode);
			throw new NrsBusinessException("参数异常，请检查 Apollo 订单总金额百分比是否配置");
		}
		// 将 0.2 转为 20%
		result.put("percentageOfTotalOrderAmount", String.format("%.0f%%", percentageConfigByGbCode.getPercentageOfTotalOrderAmount() * 100));
		BigDecimal contractAmount = contract.getAmount();
		BigDecimal firstInstallmentAmountByPercentage = contractAmount.multiply(BigDecimal.valueOf(percentageConfigByGbCode.getPercentageOfTotalOrderAmount()));
		// 销售合同一期收款金额
		result.put("firstInstallmentAmountByPercentage", firstInstallmentAmountByPercentage);
		// 销售合同一期收款金额（大写）
		result.put("firstInstallmentAmountByPercentageText", ChineseMoneyConverter.numberToChineseMoney(firstInstallmentAmountByPercentage));
		return result;
	}

