	/**
	 * 获取最新的已签署的正签合同编号
	 */
	public Map<String, Object> getLatestSignedFormalContractNo() {
		HashMap<String, Object> result = new HashMap<>();
		String projectOrderId = ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId();
		Byte launchSupplementType = ContractContextHandler.getContractReq().getSignInfo().getLaunchSupplementType();
		String contractNo = "";
		// 正签合并发起的补充协议，正签合同编号从 ThreadLocal 里拿
		if (LaunchSupplementTypeEnum.MERGE_LAUNCH_SUPPLEMENT.getCode().equals(launchSupplementType)) {
			List<ContractSubmitCore> contractSubmitCoreList = ContractContextHandler.getContext().getContractSubmitCoreList();
			contractNo = contractSubmitCoreList.stream().filter(item -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(item.getContract().getType()))
				.findFirst().orElseThrow(() -> new NrsBusinessException("获取合并发起的正签合同编号失败, projectOrderId: " + projectOrderId))
				.getContract().getContractNo();
		} else {
			// 单独发起的补充协议，正签合同编号取最新已签署的正签
			contractNo = contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode())
				.stream()
				.filter(item -> Objects.equals(ContractStatusEnum.FINISH.getCode(), item.getStatus()))
				.map(Contract::getContractNo)
				.findFirst()
				.orElse("");
		}

		if (StringUtils.isBlank(contractNo)) {
			LOGGER.error("获取最新已签署的正签合同编号失败, projectOrderId: {}", projectOrderId);
			throw new NrsBusinessException("获取最新已签署的正签合同编号失败");
		}
		result.put("latestSignedFormalContractNo", contractNo);
		return result;
	}

