	public Map<String, Object> getSupplementItemHiddenFlag() {
		HashMap<String, Object> result = new HashMap<>();
		// 获取补充协议信息
		SupplementItemInfo supplementItemInfo = ContractContextHandler.getContractReq().getSupplementItemInfo();
		// 补充协议模块为空的场景处理
		if (supplementItemInfo == null) {
			throw new NrsBusinessException("补充协议条款信息不能为空", Level.WARN);
		}

		// 默认所有段落全部隐藏
		result.put("houseTransactionFailedTerminationHidden", CommonEnum.YES.getCode());
		result.put("constructionRiskCustomerBearHidden", CommonEnum.YES.getCode());
		result.put("generalScenarioHidden", CommonEnum.YES.getCode());
		List<Byte> selectedSupplementItem = supplementItemInfo.getSelectedSupplementItem();
		// 如果未选择条款，则默认所有条款均隐藏
		if (CollectionUtil.isEmpty(selectedSupplementItem)) {
			throw new NrsBusinessException("未选择条款内容，不能发起补充协议", Level.WARN);
		}
		for (Byte item : selectedSupplementItem) {
			if (SupplementItemTypeEnum.HOUSE_TRANSACTION_FAILED_TERMINATION.getCode().equals(item)) {
				result.put("houseTransactionFailedTerminationHidden", CommonEnum.NO.getCode());
			} else if (SupplementItemTypeEnum.CONSTRUCTION_RISK_CUSTOMER_BEAR.getCode().equals(item)) {
				result.put("constructionRiskCustomerBearHidden", CommonEnum.NO.getCode());
			} else if (SupplementItemTypeEnum.GENERAL_SCENARIO.getCode().equals(item)) {
				result.put("generalScenarioHidden", CommonEnum.NO.getCode());
			}
		}
		LOGGER.info("补充协议条款内容隐藏标识，projectOrderId: {}, result:{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId(), JSON.toJSONString(result));
		return result;
	}

