public Map<String, Object> getPromiseInfo() {
	HashMap<String, Object> result = new HashMap<>();
	PromiseInfoReq promiseInfo = ContractContextHandler.getContractReq().getPromiseInfo();
	if (promiseInfo == null) {
		return result;
	}
	String projectContractMode = Objects.nonNull(ProjectContractModeEnum.getNameByCode(promiseInfo.getProjectContractModeCode()))
		? String.valueOf(promiseInfo.getProjectContractModeCode()) : "";
	String projectContractModeName = Objects.nonNull(ProjectContractModeEnum.getNameByCode(promiseInfo.getProjectContractModeCode()))
		? ProjectContractModeEnum.getNameByCode(promiseInfo.getProjectContractModeCode()) : "";
	String clearDay = Objects.nonNull(promiseInfo.getClearDay()) ? String.valueOf(promiseInfo.getClearDay()) : "";
	String constructionDrawMode = Objects.nonNull(ConstructionDrawModeEnum.getNameByCode(promiseInfo.getConstructionDrawMode())) ? String.valueOf(
		promiseInfo.getConstructionDrawMode()) : "";
	String afterDiscountDesignerAmount =
		(Objects.equals(promiseInfo.getNeedDesignerAmount(), CommonEnum.YES.getCode().intValue())
			&& Objects.nonNull(promiseInfo.getAfterDiscountDesignerAmount()))
			? String.valueOf(
			promiseInfo.getAfterDiscountDesignerAmount())
			: "/";
	String beforeDeliveryDaysToWork = Objects.isNull(promiseInfo.getBeforeDeliveryDaysToWork())
		? ""
		: promiseInfo.getBeforeDeliveryDaysToWork().toString();
	String taxRate = Objects.isNull(promiseInfo.getTaxRate()) ? "" : promiseInfo.getTaxRate().toString();
	String disputeDealMode = Objects.isNull(promiseInfo.getDisputeDealMode()) ? "" : promiseInfo.getDisputeDealMode().toString();
	//工程承包方式
	if (ObjectUtil.isNotEmpty(projectContractMode)
		&& ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS_V2.getCode().equals(Integer.valueOf(projectContractMode))) {
		projectContractMode = String.valueOf(ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS.getCode());
	}
	result.put("ProjectContractMode", projectContractMode);
	//工程承包方式名称
	result.put("ProjectContractModeName", projectContractModeName);
	//开工X天，提供施工条件
	result.put("openWorkDayToConstruct", clearDay);
	//双方商定施工图纸采取下列第种方式
	result.put("constructionDrawMode", constructionDrawMode);
	//设计服务费（优惠后）
	result.put("afterDiscountDesignerAmount", afterDiscountDesignerAmount);
	//甲方须在开发商统一交房【】天内，通知乙方开工
	result.put("beforeDeliveryDaysToWork", beforeDeliveryDaysToWork);
	//税率
	result.put("taxRate", taxRate + "%");
	//纠纷处理方式
	result.put("disputeDealMode", disputeDealMode);
	return result;
}

	public Map<String, Object> getProjectDay() {
		HashMap<String, Object> result = new HashMap<>();
		ContractProjectInfoReq projectInfo = ContractContextHandler.getContractReq().getProjectInfo();
		Contract contract = ContractContextHandler.getContext().getContract();
		String totalDuration = Objects.isNull(projectInfo.getTotalDuration())
			? Objects.isNull(projectInfo.getTotalDurationEnum()) ? "" : TotalDurationEnum.getNameByCode(projectInfo.getTotalDurationEnum())
			: projectInfo.getTotalDuration().toString();
		//整装的工期，如果是<50 or >150显示成/
//		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(contract.getBusinessType())) {
//			if (Objects.isNull(projectInfo.getTotalDuration()) || projectInfo.getTotalDuration() < 50 || projectInfo.getTotalDuration() > 150) {
//				totalDuration = "/";
//			}
//		}
		// 判断工期是否超过上下限，不同业务类型对应上下限不同
		if (contractApolloConfig.isExceedLimitation(contract.getBusinessType(), projectInfo.getTotalDuration())) {
			totalDuration = "/";
		}

		//团装2.5工期从apollo中获取
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType()) && ContractContextHandler.getContext().isProcessV25()) {
			Integer totalDurationByGbCode = contractApolloConfig.getTotalDurationByGbCode(contract.getGbCode());
			if (totalDurationByGbCode == null) {
				throw new NrsBusinessException("团装2.5工期配置为空,请联系客服配置");
			}
			totalDuration = totalDurationByGbCode.toString();
		}
		//工期
		result.put("projectDay", totalDuration);
		return result;
	}

public Map<String, Object> getPlanOpenDate() {
	HashMap<String, Object> result = new HashMap<>();
