public Map<String, Object> getDecorateRuleUrl() {
	HashMap<String, Object> result = new HashMap<>();
	PlanAllDTO planAllDTO = ContractContextHandler.getPlanAllDTO();
	ContractReqDTO contractReq = ContractContextHandler.getContractReq();
	String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	//如果合同是无版式模式，则不需要返回附件图片数据，采用pdf拼接方式
	if (PdfGenerationModeEnum.UNFORMATTED.getCode().equals(ContractContextHandler.getContext().getContract().getPdfGenerationMode())) {
		return result;
	}

	String urls;
	List<String> comboCodesByPlanAllDTO = commonContractService.getComboCodesByPlanAllDTO(planAllDTO);
	if (CollectionUtils.isEmpty(comboCodesByPlanAllDTO)) {
		return result;
	}

	List<FormalPackageContractFreeformDTO.Photo> photos = new ArrayList<>();
	List<FormalPackageContractFreeformDTO.PhotoInfo> photoInfos = new ArrayList<>();
	for (String comboCode : comboCodesByPlanAllDTO) {
		List<String> ruleUrls = comboInfoService.getDecorateRule(projectOrderId, contractType, comboCode).getImgUrls();
		String signDate = DateUtils.getDateStr(new Date());
		List<FormalPackageContractFreeformDTO.Photo> singleComboPhotos = ruleUrls.stream()
			.map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
		photos.addAll(singleComboPhotos);

		List<FormalPackageContractFreeformDTO.PhotoInfo> singleComboPhotoInfos = ruleUrls.stream()
			.map(src -> new FormalPackageContractFreeformDTO.PhotoInfo(src, signDate, false)).collect(Collectors.toList());
		photoInfos.addAll(singleComboPhotoInfos);
	}

	urls = JsonUtil.toJsonString(photos);
	//精装细则url
	result.put("decorateRuleUrl", urls);
	if (CollectionUtils.isNotEmpty(photoInfos)) {
		//设置photos最后一页盖章
		photoInfos.get(photos.size() - 1).setSign(true);
	}
	//精装细则url
	result.put("decorateRuleUrlV2", JsonUtil.toJsonString(photos));
	return result;
}

