public Map<String, Object> getBudgetUrlV2() {
	HashMap<String, Object> result = new HashMap<>();
	PlanAllDTO planAllDTO = ContractContextHandler.getPlanAllDTO();
	Byte contractType = ContractContextHandler.getContractReq().getContractBaseInfo().getContractType();
	Integer contractMode = ContractContextHandler.getContractReq().getContractBaseInfo().getContractMode();
	Byte businessType = ContractContextHandler.getContractReq().getProjectInfo().getBusinessType();
	//如果合同是无版式模式，则不需要返回附件图片数据，采用pdf拼接方式
	if (PdfGenerationModeEnum.UNFORMATTED.getCode().equals(ContractContextHandler.getContext().getContract().getPdfGenerationMode())) {
		return result;
	}
	//正签合同并且是全案模式，报价单不需要附带到正签合同中
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && ContractModeEnum.FULL_SERVICE.getCode().equals(contractMode)) {
		return result;
	}
	String fileUrl = "";
	if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
		if (contractUnifyService.getAdvanceFromQuotation(ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId(), ContractTypeEnum.ADVANCE.getCode(), businessType)) {
			fileUrl = ContractContextHandler.getContractReq().getQuotation().getPreQuotationFileUrl().get(0).getUrl();
		} else {
			return result;
		}
	} else {
		List<PlanAttachmentDTO> list = planAllDTO.getPlanAttachmentList();
		if (CollectionUtils.isEmpty(list)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "中控模式下,缺少报价单PDF文件，请联系预算员在报价中生成PDF");
		}
		PlanAttachmentDTO attachmentDTO = list.stream().filter(planAttachmentDTO -> planAttachmentDTO.getFileType().equals(PlanAttachment.报价单))
			.findFirst()
			.orElse(null);
		if (attachmentDTO == null) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "中控模式下，缺少报价单PDF文件,请联系预算员在报价中生成PDF");
		}
		fileUrl = attachmentDTO.getFileUrl();
	}
	if (StringUtils.isBlank(fileUrl)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "报价单为空无法生成PDF");
	}

	List<String> imageUrls = new ArrayList<>();
	try {
		imageUrls = pdfToImageService.pdf2ImagePublicParallel(fileUrl);
	} catch (NrsBusinessException e) {
		if (e.getCode() == ResponseCodeEnum.PDF_PAGES_LIMIT.getCode()) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(),
				String.format("%s数过多，请检查%s样式并调整控制在%s页及以内", "报价单", "报价单", limitPages),
				Level.WARN);
		}
	}
	if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType) && ContractTypeEnum.ADVANCE.getCode().equals(contractType) && contractApolloConfig.getAdvanceReformMaxPage().compareTo(imageUrls.size()) < 0) {
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(),
			String.format("%s数过多，请检查%s样式并调整控制在%s页及以内", "报价单", "报价单", contractApolloConfig.getAdvanceReformMaxPage()),
			Level.WARN);
	}
	String signDate = DateUtils.getDateStr(new Date());
	List<FormalPackageContractFreeformDTO.PhotoInfo> photos = imageUrls.stream()
		.map(src -> new FormalPackageContractFreeformDTO.PhotoInfo(src, signDate, false)).collect(
			Collectors.toList());
	if (CollectionUtils.isEmpty(photos)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "报价单内容为空，请检查");
	}
	//设置photos最后一页盖章
	photos.get(photos.size() - 1).setSign(true);
	//报价单url
	result.put("budgetUrlV2", JsonUtil.toJsonString(photos));
	return result;
}

