	String companyAgentCertificateNo = cipherService.decrypt(signInfo.getCompanyAgentCertificateNo());
	String companyAgentPhone = cipherService.decrypt(signInfo.getCompanyAgentPhone());

	result.put("agentName", signInfo.getCompanyAgentName());
	result.put("agentPhone", companyAgentPhone);
	result.put("agentIdNoType", CertificateTypeEnum.getNameByCode(signInfo.getCompanyAgentCertificateType()));
	result.put("agentIdNo", companyAgentCertificateNo);
