public Map<String, Object> getSignatoryUserInfo() {
	HashMap<String, Object> result = new HashMap<>();
	ContractSignInfoReq signInfo = ContractContextHandler.getContractReq().getSignInfo();
	ContractBaseInfoReq contractBaseInfo = ContractContextHandler.getContractReq().getContractBaseInfo();
	Byte agentSign = ContractContextHandler.getContractReq().getContractAttachInfo() == null ? null :
		ContractContextHandler.getContractReq().getContractAttachInfo().getAgentSign();

	Byte signatoryRoleType = contractUnifyService.getSignatoryRoleType(contractBaseInfo.getProjectOrderId(), contractBaseInfo.getContractType(), signInfo, agentSign);
	String signatoryName = null;
	String signatoryCertificateType = null;
	String signatoryCertificateNo = null;
	String signatoryPhone = null;
	if (RoleTypeEnum.OWNER.getCode().equals(signatoryRoleType)) {
		signatoryName = signInfo.getOwnerName();
		signatoryCertificateType = CertificateTypeEnum.getNameByCode(signInfo.getOwnerCertificateType());
		signatoryCertificateNo = signInfo.getOwnerCertificateNo();
		signatoryPhone = signInfo.getOwnerPhone();
	} else if (RoleTypeEnum.AGENT.getCode().equals(signatoryRoleType)) {
		signatoryName = signInfo.getAgentName();
		signatoryCertificateType = CertificateTypeEnum.getNameByCode(signInfo.getAgentCertificateType());
		signatoryCertificateNo = signInfo.getAgentCertificateNo();
		signatoryPhone = signInfo.getAgentPhone();
	} else if (RoleTypeEnum.COMPANY_AGENT.getCode().equals(signatoryRoleType)) {
		signatoryName = signInfo.getCompanyAgentName();
		signatoryCertificateType = CertificateTypeEnum.getNameByCode(signInfo.getCompanyAgentCertificateType());
		signatoryCertificateNo = signInfo.getCompanyAgentCertificateNo();
		signatoryPhone = signInfo.getCompanyAgentPhone();
	} else if (RoleTypeEnum.LEGAL.getCode().equals(signatoryRoleType)) {
		signatoryName = signInfo.getLegalName();
		signatoryCertificateType = CertificateTypeEnum.getNameByCode(signInfo.getLegalCertificateType());
		signatoryCertificateNo = signInfo.getLegalCertificateNo();
		signatoryPhone = signInfo.getLegalPhone();
	}

	result.put("signatoryName", signatoryName);
	result.put("signatoryCertificateType", signatoryCertificateType);
	result.put("signatoryCertificateNo", cipherService.decrypt(signatoryCertificateNo));
	result.put("signatoryPhone", cipherService.decrypt(signatoryPhone));
	return result;
}

