public Map<String, Object> getEscrowAccountInfo() {
	HashMap<String, Object> result = new HashMap<>();
	ContractContextEscrowInfo escrowInfo = ContractContextHandler.getContext().getEscrowInfo();
	if (escrowInfo == null || StringUtils.isBlank(escrowInfo.getOpenAccountTime())) {
		return result;
	}

	String phone = escrowInfo.getPhone();
	String name = escrowInfo.getName();
	String idNo = escrowInfo.getIdNumber();
	String idType = escrowInfo.getIdType();
	if (StringUtils.isAnyBlank(phone, name, idNo, idType)) {
		throw new NrsBusinessException("获取存管账户开户信息异常，存管账户信息有误");
	}

	Byte certificateType = CertificateTypeEnum.lftToContractCertificateType(idType);
	String certificateTypeName = CertificateTypeEnum.getNameByCode(certificateType);

	Map<String, String> decrypt = cipherService.decrypt(Arrays.asList(phone, idNo));
	String decryptPhone = decrypt.get(phone);
	String decryptIdNo = decrypt.get(idNo);

	Map<String, Object> signatoryUserInfo = getSignatoryUserInfo();
	Object signatoryPhone = signatoryUserInfo.get("signatoryPhone");

	if (!signatoryPhone.equals(decryptPhone)) {
		result.put("escrowAccountUserName", name);
		result.put("escrowAccountUserPhone", decryptPhone);
		result.put("escrowAccountUserIdNo", decryptIdNo);
		result.put("escrowAccountUserIdType", certificateTypeName);
	}
	return result;
}

