public Map<String, Object> getCustomAttach() {
	HashMap<String, Object> result = new HashMap<>();
	Contract contract = ContractContextHandler.getContext().getContract();

	//如果合同是无版式模式，则不需要返回附件图片数据，采用pdf拼接方式
	if (PdfGenerationModeEnum.UNFORMATTED.getCode().equals(contract.getPdfGenerationMode())) {
		return result;
	}

	// 如果合同既不是首期款合同，也不是正签合同，也不是销售合同，就直接返回
	if (!CUSTOM_ATTACH_TYPES.contains(contract.getType())) {
		return Collections.emptyMap();
	}

	// 获取合同模式
	Byte contractFormType = ContractFormTypeEnum.getCodeByDeveloperChannel(ContractContextHandler.getContext().getDeveloperChannel());

	ContractCustomAttachConfig queryParam = ContractCustomAttachConfig.builder()
		.gbCode(contract.getGbCode())
		.businessType(contract.getBusinessType())
		.companyCode(contract.getCompanyCode())
		.contractFormType(contractFormType)
		.build();

	List<ContractCustomAttachConfig> configList = contractCustomAttachConfigService.getContractCustomAttachWithDefault(queryParam);

	if (CollectionUtils.isEmpty(configList)) {
		return Collections.emptyMap();
	}

	if (configList.size() > 1) {
		LOGGER.error("获取个性化附件配置数量不唯一，projectOrderId:{},gbCode:{},companyCode:{},businessType:{},contractFormType:{}",
			contract.getProjectOrderId(), contract.getGbCode(), contract.getCompanyCode(), contract.getBusinessType(), contractFormType);
	}
	ContractCustomAttachConfig attachConfig = configList.get(0);
	String imageUrl = resolveCustomAttachImageUrl(contract.getType(), attachConfig);

	LOGGER.info("获取个性化附件配置，projectOrderId:{},gbCode:{},contractType:{},个性化附件imageUrl:{}",
		contract.getProjectOrderId(), contract.getGbCode(), contract.getType(), imageUrl);

	if (StringUtils.isBlank(imageUrl)) {
		return Collections.emptyMap();
	}

	String signDate = DateUtils.getDateStr(new Date());
	List<FormalPackageContractFreeformDTO.PhotoInfo> photos = Arrays.stream(imageUrl.split(","))
		.map(StringUtils::trimToNull)
		.filter(Objects::nonNull)
		.map(src -> new FormalPackageContractFreeformDTO.PhotoInfo(src, signDate, false))
		.collect(Collectors.toList());

	result.put("contractCustomAttach", JsonUtil.toJsonString(photos));
	return result;
}

private String resolveCustomAttachImageUrl(Byte contractType, ContractCustomAttachConfig attachConfig){
	if(Objects.equals(ContractTypeEnum.ADVANCE.getCode(),contractType)){
		return attachConfig.getAdvanceImageUrl();
	}
	if(Objects.equals(ContractTypeEnum.PACKAGE_FORMAL.getCode(),contractType)){
		return attachConfig.getPackageFormalImageUrl();
	}
	if(Objects.equals(ContractTypeEnum.PERSONAL.getCode(),contractType)){
		return attachConfig.getPersonalImageUrl();
	}
	return null;

}

