@Component
@Slf4j
public class ContractScriptCreateService {


	@Resource
	private ContractScriptBuildService contractScriptBuildService;

	@Resource(name = "scriptDynamicFieldExecutor")
	private Executor scriptDynamicFieldExecutor;

	/**
	 * 根据函数名和合同code批量获取脚本动态字段（并行版）
	 *
	 * @param contractCode 合同编号（非空）
	 * @param methodNames  方法名集合（非空且元素非空）
	 * @return 合并后的动态字段映射
	 */
	public Map<String, Object> getScriptDynamicFieldBs(String contractCode, Set<String> methodNames) {
		// 使用线程安全的Map存储结果
		Map<String, Object> formData = new ConcurrentHashMap<>(16);

		// 参数校验
		if (StringUtils.isBlank(contractCode)) {
			LOGGER.error("获取脚本动态字段失败：合同编号为空");
			return formData;
		}
		if (CollectionUtil.isEmpty(methodNames)) {
			LOGGER.error("获取脚本动态字段失败：方法名集合为空，contractCode={}", contractCode);
			return formData;
		}

		Class<?> serviceClass = contractScriptBuildService.getClass();
		// 存储所有异步任务
		List<CompletableFuture<Void>> futures = new ArrayList<>();

		for (String methodName : methodNames) {
			if (StringUtils.isBlank(methodName)) {
				LOGGER.warn("跳过空方法名，contractCode={}", contractCode);
				continue;
			}

			// 提交并行任务
			CompletableFuture<Void> future = CompletableFuture.runAsync(RunnableWrapper.of(() -> {
				try {
					// 获取方法（因Set去重，无需缓存）
					Method method = serviceClass.getMethod(methodName, String.class);
					// 调用并处理返回值
					Map invokeResult = (Map) method.invoke(contractScriptBuildService, contractCode);
					// 线程安全地合并结果
					formData.putAll(invokeResult);
					LOGGER.info("pdf生成时，调用方法{}返回结果：{}, threadId:{}",
						methodName, invokeResult, Thread.currentThread().getId());
				} catch (NoSuchMethodException e) {
					LOGGER.error("方法不存在：methodName={}, contractCode={}",
						methodName, contractCode, e);
				} catch (InvocationTargetException e) {
					// 区分方法内部抛出的异常
					Throwable targetEx = e.getTargetException();
					LOGGER.error("方法{}执行抛出异常：{}, contractCode={}, 异常详情:{}",
						methodName, targetEx.getMessage(), contractCode, targetEx.toString());
				} catch (Exception e) {
					LOGGER.error("调用方法{}失败，contractCode={}, 错误信息:{}",
						methodName, contractCode, e.getMessage(), e);
				}
			}), scriptDynamicFieldExecutor); // 使用自定义线程池

			futures.add(future);
		}

		// 等待所有并行任务完成
		try {
			CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
		} catch (CompletionException e) {
			LOGGER.error("并行获取动态字段时发生异常，contractCode={}", contractCode, e.getCause());
		}

		return formData;
	}


}

