@Service
@Slf4j
public class ContractSelfSealService {

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Resource
	private SelfSealRecordService selfSealRecordService;

	@Resource
	private PdfToImageService pdfToImageService;

	@Resource
	private FreeformService freeformService;

	@Resource
	private S3Service s3Service;

	/**
	 * 获取盖章主体分公司信息
	 */
	public List<SelfSealCompanyInfoDTO> getSelfSealCompanyInfos() {
		List<SelfSealCompanyInfoDTO> companyDTOList = contractApolloConfig.getSelfSealCompanyInfoConfig();
		//获取当前登录人系统号
		String systemCode = String.valueOf(CommonUtil.ucIdToSystemCode(HeaderContext.getUserId()));
		//获取支持的分公司
		List<String> supportCompanyCodeList = contractApolloConfig.getSelfSealCompanyInfoConfig().stream().filter(item -> Arrays.asList(item.getSystemCodes().split(",")).contains(systemCode)).map(SelfSealCompanyInfoDTO::getCompanyCode).collect(Collectors.toList());
		companyDTOList = companyDTOList.stream().filter(item -> supportCompanyCodeList.contains(item.getCompanyCode())).collect(Collectors.toList());
		return companyDTOList;
	}

	/**
	 * 提交盖电子章信息
	 */
	public void submitSelfSeal(SelfSealSubmitDTO selfSealSubmitDTO){
		//提交盖章信息校验
		checkSubmitInfo(selfSealSubmitDTO);
		List<SelfSealSubmitDTO.SelfSeal> selfSealReqList = selfSealSubmitDTO.getSelfSealReqList();
		//构建盖章任务
		List<SelfSealRecord> selfSealTask = selfSealReqList.stream().map(this::buildSelfSealTask).flatMap(List::stream).collect(Collectors.toList());
		selfSealRecordService.insertBatch(selfSealTask);
		//异步处理盖章任务
		dealSealTask(selfSealTask);
	}

	public Page<SelfSealTaskInfoDTO> getSelfSealList(String timeRange, Integer pageNo, Integer pageSize) {
		//获取当前登录人系统号
		String systemCode = String.valueOf(CommonUtil.ucIdToSystemCode(HeaderContext.getUserId()));
		//获取支持的分公司
		List<String>  supportCompanyCodeList= contractApolloConfig.getSelfSealCompanyInfoConfig().stream().filter(item -> Arrays.asList(item.getSystemCodes().split(",")).contains(systemCode)).map(SelfSealCompanyInfoDTO::getCompanyCode).collect(Collectors.toList());
        if (CollectionUtils.isEmpty(supportCompanyCodeList)) {
			return new Page<>(pageNo, pageSize, 0L, Collections.emptyList());
		}
		Date startTime = null;
		Date endTime = null;
		if (StringUtils.isNotBlank(timeRange)) {
			String[] timeArr = timeRange.split(",");
			if (timeArr.length == 2) {
				startTime = new Date(Long.parseLong(timeArr[0]) * 1000L);
				endTime = new Date(Long.parseLong(timeArr[1]) * 1000L);
			} else {
				LOGGER.error("获取自主盖章列表时间范围参数错误");
			}
		}
		PageInfo<SelfSealRecord> selfSealRecordPageInfoList = selfSealRecordService.selectByApplyTimeAndCompanyCodeList(startTime, endTime, supportCompanyCodeList, pageNo, pageSize);

		List<SelfSealTaskInfoDTO> taskInfoDTOS = selfSealRecordPageInfoList.getList().stream().map(item ->
				SelfSealTaskInfoDTO.builder()
					.id(item.getId())
					.companyCode(item.getCompanyCode())
					.companyName(item.getCompanyName())
					.fileName(item.getFileName())
					.sealStatus(item.getSealStatus())
					.sealStatusText(SelfSealStatusEnum.getNameByCode(item.getSealStatus()))
					.fileUrl(StringUtils.isNotBlank(item.getPreviewKey()) ? s3Service.generateUrl(item.getPreviewKey(), 36000) : "")
					.createTime(item.getCreateTime())
					.applyUserId(item.getApplyUserId())
					.build())
			.collect(Collectors.toList());
		return new Page<>(pageNo, pageSize, selfSealRecordPageInfoList.getTotal(), taskInfoDTOS);
	}

	/**
	 * 提交盖章信息校验
	 */
	private void checkSubmitInfo(SelfSealSubmitDTO selfSealSubmitDTO){
		List<SelfSealSubmitDTO.SelfSeal> selfSealInfoList = selfSealSubmitDTO.getSelfSealReqList().stream().filter(item -> CollectionUtils.isNotEmpty(item.getFileInfoList())).collect(Collectors.toList());
		if (CollectionUtils.isEmpty(selfSealInfoList)) {
			throw new NrsBusinessException("上传文件列表不能为空，请检查",Level.WARN);
		}
		//获取当前登录人系统号
		String systemCode = String.valueOf(CommonUtil.ucIdToSystemCode(HeaderContext.getUserId()));
		//获取支持的分公司
		List<String> supportCompanyCodeList = contractApolloConfig.getSelfSealCompanyInfoConfig().stream().filter(item -> Arrays.asList(item.getSystemCodes().split(",")).contains(systemCode)).map(SelfSealCompanyInfoDTO::getCompanyCode).collect(Collectors.toList());

		for (SelfSealSubmitDTO.SelfSeal selfSeal : selfSealInfoList) {
			if (StringUtils.isBlank(selfSeal.getCompanyCode())){
				throw new NrsBusinessException("盖章主体不能为空，请检查是否选择",Level.WARN);
			}
			if (selfSeal.getType() == null) {
				throw new NrsBusinessException("盖章主体不能为空，请检查是否选择", Level.WARN);
			}
			if (CollectionUtils.isEmpty(supportCompanyCodeList) || !supportCompanyCodeList.contains(selfSeal.getCompanyCode())) {
				throw new NrsBusinessException("无权限", Level.WARN);
			}
		}
	}


	private void dealSealTask(List<SelfSealRecord> selfSealTask) {
		for (SelfSealRecord selfSealRecord : selfSealTask) {
			LOGGER.info("异步开始处理盖章任务,id:{}", selfSealRecord.getId());
			CompletableFuture.runAsync(RunnableWrapper.of(() -> {
				try {
					dealSingleSealTask(selfSealRecord);
				} catch (Exception e) {
					LOGGER.warn("处理自主盖章任务失败,id:{},原因：{}", selfSealRecord.getId(), e.getMessage(), e);
					selfSealRecordService.updateStatus(selfSealRecord.getId(), SelfSealStatusEnum.SEAL_FAIL.getCode());
				}
			}));
		}
	}


	private List<SelfSealRecord> buildSelfSealTask(SelfSealSubmitDTO.SelfSeal selfSeal) {
		List<SelfSealRecord> result = new ArrayList<>();
		Map<String, String> companyInfoMap = contractApolloConfig.getSelfSealCompanyInfoConfig().stream().collect(Collectors.toMap(SelfSealCompanyInfoDTO::getCompanyCode, SelfSealCompanyInfoDTO::getCompanyName));
		Integer fileType = selfSeal.getType();
		if (FileTypeEnum.PDF.getType().equals(fileType) && CollectionUtils.isNotEmpty(selfSeal.getFileInfoList())) {
			for (SelfSealSubmitDTO.FileInfoDTO fileInfo : selfSeal.getFileInfoList()) {
				SelfSealRecord selfSealRecord = SelfSealRecord.builder()
					.companyCode(selfSeal.getCompanyCode())
					.companyName(companyInfoMap.get(selfSeal.getCompanyCode()))
					.sourceFileUrl(fileInfo.getFilePrevUrl())
					.sourceFileType(Byte.valueOf(fileType.toString()))
					.platformInstanceId(0L)
					.previewKey("")
					.fileName(fileInfo.getFileName())
					.sealStatus(SelfSealStatusEnum.SEAL_ING.getCode())
					.applyUserId(HeaderContext.getUserId().toString())
					.createTime(new Date())
					.updateTime(new Date())
					.delStatus((byte) 0)
					.build();
				result.add(selfSealRecord);
			}
		}
		if (FileTypeEnum.IMAGE.getType().equals(fileType) && CollectionUtils.isNotEmpty(selfSeal.getFileInfoList())) {
			String sourceFileUrl = selfSeal.getFileInfoList().stream().map(SelfSealSubmitDTO.FileInfoDTO::getFilePrevUrl).collect(Collectors.joining(","));
			String fileName = DateUtil.format(DateUtil.date(), DatePattern.PURE_DATE_PATTERN) + "_"+new Random().nextInt(90) + ".pdf";
			SelfSealRecord selfSealRecord = SelfSealRecord.builder()
				.companyCode(selfSeal.getCompanyCode())
				.companyName(companyInfoMap.get(selfSeal.getCompanyCode()))
				.sourceFileUrl(sourceFileUrl)
				.sourceFileType(Byte.valueOf(fileType.toString()))
				.platformInstanceId(0L)
				.previewKey("")
				.fileName(fileName)
				.sealStatus(SelfSealStatusEnum.SEAL_ING.getCode())
				.applyUserId(HeaderContext.getUserId().toString())
				.createTime(new Date())
				.updateTime(new Date())
				.delStatus((byte) 0)
				.build();
			result.add(selfSealRecord);
		}
		return result;
	}


	/**
	 * 处理盖章任务
	 */
	private void dealSingleSealTask(SelfSealRecord selfSealRecord){
		List<String> imageList;
		if (FileTypeEnum.PDF.getType().equals(selfSealRecord.getSourceFileType().intValue())) {
			//pdf需要将pdf转为图片
			imageList = pdfToImageService.pdf2ImagePublicParallel(selfSealRecord.getSourceFileUrl());
		}else{
			imageList = Arrays.asList(selfSealRecord.getSourceFileUrl().split(","));
		}
		//构建合同参数
		Map<String, Object> fromData = buildFromData(imageList);
		//生成合同pdf
		generatePdf(fromData, selfSealRecord);
		//合同盖章
		contractSeal(selfSealRecord);
		selfSealRecordService.update(selfSealRecord);

	}

	/**
	 * 构建合同参数
	 */
	private Map<String, Object> buildFromData(List<String> imageList){
		String signDate = DateUtils.getDateStr(new Date());
		List<FormalPackageContractFreeformDTO.PhotoInfo> photos = imageList.stream()
			.map(src -> new FormalPackageContractFreeformDTO.PhotoInfo(src, signDate, false)).collect(Collectors.toList());
		if (CollectionUtils.isNotEmpty(photos)) {
			//设置photos最后一页盖章
			photos.get(photos.size() - 1).setSign(true);
		}
		String urls = JsonUtil.toJsonString(photos);
		SelfSealFreeformDTO contractFreeformDTO = SelfSealFreeformDTO.builder()
			.imageUrl(urls)
			.build();
		ObjectMapper objectMapper = new ObjectMapper();
		LOGGER.info("自主盖章合同参数构建完成：{}", contractFreeformDTO);
		return objectMapper.convertValue(contractFreeformDTO, Map.class);
	}

    /**
	 * 生成pdf
	 */
	private void generatePdf(Map<String,Object> formData, SelfSealRecord selfSealRecord){
		FormInfo selfSealFormInfo = contractApolloConfig.getSelfSealFormInfo();
		if (selfSealFormInfo == null || StringUtils.isBlank(selfSealFormInfo.getFormKey()) || selfSealFormInfo.getFormId() == null) {
			throw new NrsBusinessException("自主盖章协议平台板式配置缺失", Level.ERROR);
		}
		String formKey = selfSealFormInfo.getFormKey();
		Integer formId = selfSealFormInfo.getFormId();
		Long createUserId = Long.valueOf(selfSealRecord.getApplyUserId());
		//创建实例
		Long instanceId = freeformService.createInstance(formKey, createUserId);
		selfSealRecord.setPlatformInstanceId(instanceId);
		//提交表单
		freeformService.submit(selfSealRecord.getPlatformInstanceId(), String.valueOf(selfSealRecord.getId()), createUserId, formData);
		Boolean addWaterMark = false;
		String markText = "";
		//生成pdf
		AttachmentInfo pdfInfo = freeformService.createPdf(selfSealRecord.getPlatformInstanceId(), createUserId, formId.longValue(), formData, addWaterMark, markText);
		LOGGER.info("异步处理盖章任务生成pdf完成，id:{},结果:{}", selfSealRecord.getId(), pdfInfo.getUrl());
	}

	/**
	 * 合同盖章
	 */
	private void contractSeal(SelfSealRecord selfSealRecord) {
		Map<String, String> companyInfoMap = contractApolloConfig.getSelfSealCompanyInfoConfig().stream().collect(Collectors.toMap(SelfSealCompanyInfoDTO::getCompanyCode, SelfSealCompanyInfoDTO::getSealCode));
		String selaCode = companyInfoMap.get(selfSealRecord.getCompanyCode());
		String pdfUrl = freeformService.companySeal(selfSealRecord.getPlatformInstanceId(), selaCode, Long.valueOf(selfSealRecord.getApplyUserId()), false, SignatureTypeEnum.CONTRACT.getType());
		String fileKey = s3Service.upload(pdfUrl);
		selfSealRecord.setPreviewKey(fileKey);
		selfSealRecord.setSealStatus(SelfSealStatusEnum.SEAL_SUCCESS.getCode());
		LOGGER.info("异步处理盖章任务盖章完成,id:{}", selfSealRecord.getId());
	}

	public void reSeal(Long id) {
		SelfSealRecord selfSealRecord = selfSealRecordService.selectByPk(id);
		if (selfSealRecord == null) {
			throw new NrsBusinessException("盖章任务不存在", Level.WARN);
		}
		dealSealTask(Lists.newArrayList(selfSealRecord));
	}

}

