	/**
	 * 解约协议金额校验
	 */
	private void terminalFundAmountCheck(String projectOrderId, Byte contractType) {
		if (!ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
			return;
		}
		CancelOrderBaseInfoDTO lastRecordInfo = cancelOrderRecordService.getLastRecordByProjectOrderId(projectOrderId);
		if (lastRecordInfo == null) {
			throw new NrsBusinessException(NrsBusinessException.DEFAULT_ERROR_CODE, "未找到退单信息", Level.ERROR);
		}
		if (!CancelOrderStatusEnum.AWAIT_SIGN_LAUNCH.getStatus().equals(lastRecordInfo.getStatus())) {
			throw new NrsBusinessException(NrsBusinessException.DEFAULT_ERROR_CODE, "当前退单状态不是待发起签约，请检查", Level.ERROR);
		}
		List<FundAmountDTO> fundAmountList = lastRecordInfo.getFundAmountList();
		List<FundInfo> allFundInfo = fundInfoService.getAllFundInfoByProjectOrderId(lastRecordInfo.getProjectOrderId());
		for (FundAmountDTO fundAmountDTO : fundAmountList) {
			FundInfo fundInfo = allFundInfo.stream().filter(info -> info.getFundType().equals(fundAmountDTO.getFundType())).findFirst().orElse(null);
			if (fundInfo == null) {
				continue;
			}
			if (fundInfo.getPaidAmount().compareTo(fundAmountDTO.getPaidAmount()) != 0) {
				String errorMessage = "款项实际支付金额与退单款项发起页的支付金额不一致,款项类型：" + fundInfo.getFundName() + ";可撤销退单重新发起";
				LOGGER.info("款项实际支付金额与退单款项发起页的支付金额不一致,款项id:{},实际支付金额：{},退单发起页金额：{}", fundInfo.getFundId(), fundInfo.getPaidAmount(), fundAmountDTO.getPaidAmount());
				throw new NrsBusinessException(errorMessage, Level.WARN);
			}
			if (fundInfo.getFundType().equals(FundTypeEnum.DEPOSIT.getValue())) {
				BigDecimal usableAmount = fundInfo.getPaidAmount().subtract(fundInfo.getDeductedAmount());
				if (usableAmount.compareTo(fundAmountDTO.getDeductibleAmount()) != 0) {
					String errorMessage = "定金实际支付金额与退单款项发起页的可抵扣金额不一致" + ";可撤销退单重新发起";
					LOGGER.info("定金实际支付金额与退单款项发起页的可抵扣金额不一致,款项id:{},实际支付金额：{},退单发起页金额：{}", fundInfo.getFundId(), usableAmount, fundAmountDTO.getDeductibleAmount());
					throw new NrsBusinessException(errorMessage, Level.WARN);
				}
			}
		}
	}

