public Integer getContractSubmitStatus(Contract contract) {
	// 设计合同、设计变更场景：设计费超底时，提交后状态流转到「待提交审核」
	if (designFeeAuditService.isDesignFeeExceedBottomOnSubmit(contract)) {
		return ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode();
	}

	if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType())) {
		//合并发起模式发起流转到待用户签署
		if (ContractContextHandler.getContext().isMergeLaunch()) {
			boolean offline = SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType());
			return offline ? ContractStatusEnum.FINISH.getCode() : ContractStatusEnum.PENDING_USER_SIGN.getCode();
		}
		//退单流程中解约协议发起后流转到审批中，退单审批通过后合同流转到已签署
		return ContractStatusEnum.AUDITING.getCode();
	}


	//线上or线下
	if (contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode())) {
		List<Byte> companySignAfterSubmitType = ContractTypeEnum.companySignAfterSubmitType();
		boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType()) && BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType());
		if (houseProcessV25 && companySignAfterSubmitType.contains(contract.getType()) && UserSignTypeEnum.SIGN.getCode().equals(contract.getUserSignType())) {
			return ContractStatusEnum.PENDING_COMPANY_SIGN.getCode();
		}
		if (contract.getAuditType().equals(AuditTypeEnum.BEFORE_SIGN.getCode())) {
			return ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode();
		} else {
			//签署方式
			if (contract.getUserSignType().equals(UserSignTypeEnum.SIGN.getCode())) {
				return ContractStatusEnum.PENDING_USER_SIGN.getCode();
			} else {
				return ContractStatusEnum.PENDING_USER_CONFIRM.getCode();
			}
		}
	} else {
		//线下
		if (contract.getAuditType().equals(AuditTypeEnum.NONE.getCode())) {
			return ContractStatusEnum.FINISH.getCode();
		} else {
			return ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode();
		}
	}
}

