private void deleteNoRelationContract(Contract mainContract) {
	List<ContractRelation> relationList = contractRelationService.getRelationList(mainContract.getContractCode());
	List<String> relationContractCodeList = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
	List<Contract> relationContract = contractService.getListByContractCodes(relationContractCodeList, false);
	List<String> relationDraftContractCodes = relationContract.stream()
		.filter(contract -> ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()))
		.map(Contract::getContractCode)
		.collect(Collectors.toList());
	if (!CollectionUtils.isEmpty(relationDraftContractCodes)) {
		//删除合同
		contractService.deleteSoftByContractCodes(relationDraftContractCodes);
		//合同关联关系删除
		contractRelationService.deleteRelationByContractCodes(relationDraftContractCodes);
		//删除合同关联报价单
		for (String contractCode : relationDraftContractCodes) {
			contractQuotationRelationService.deleteRelationsByContractCode(contractCode);
		}
		LOGGER.info("删除不属于当前合同的关联关系的合同,主合同code：{},删除合同编号:{}", mainContract.getContractCode(), relationDraftContractCodes);
	}
}

private void deletePersonalHistoryRelation(List<Contract> mainContractList) {
	for (Contract contract : mainContractList) {
		if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			ContractRelation byRelateContractCode = contractRelationService.getByRelateContractCode(contract.getContractCode());
			if (byRelateContractCode != null) {
				contractRelationService.deleteRelationByContractCodes(Collections.singletonList(contract.getContractCode()));
				LOGGER.info("删除历史与正签关联关系,删除关联合同编号:{}", contract.getContractCode());
			}
		}
	}
}

public void bindContractRelation(Contract mainContract, List<String> relationContractCode, ContractRelationEnum relationEnum) {
	if (CollectionUtils.isEmpty(relationContractCode)) {
		return;
	}
	//获取主合同已经存在的有关联关系的合同（如，草稿中绑定的），发起签约时，已绑定的合同如果已经不需要再合并发起，需要将关联关系删除，如果合同为草稿态，需要删除对应关联合同
	List<ContractRelation> relationList = contractRelationService.getRelationList(mainContract.getContractCode());
	//库中已有的关联合同编号
	Set<String> relationContractCodeSet = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toSet());
	for (String hasRelationContractCode : relationContractCodeSet) {
		if (!relationContractCode.contains(hasRelationContractCode)) {
			Contract contract = contractService.getByContractCode(hasRelationContractCode);
			if (contract != null && ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
				homeAndPcCommonService.deleteContract(hasRelationContractCode, Long.valueOf(Constant.SYSTEM_CREATE_UCID));
			}
			// 解除关联关系
			contractRelationService.deleteRelationByContractCodes(Collections.singletonList(hasRelationContractCode));
			LOGGER.info("删除不属于当前合同的关联关系的合同,删除关联合同编号:{}", hasRelationContractCode);
		}
	}
	List<ContractRelation> batchInsertList = new ArrayList<>();
	for (String relaContractCode : relationContractCode) {
		if (relationContractCodeSet.contains(relaContractCode)) {
			continue;
		}
		batchInsertList.add(ContractRelation.builder()
			.contractCode(mainContract.getContractCode())
			.relateContractCode(relaContractCode)
			.relationType(relationEnum.getCode())
			.ctime(new Date())
			.mtime(new Date())
			.delStatus(CommonEnum.NO.getCode())
			.build());
	}
	if (!CollectionUtils.isEmpty(batchInsertList)) {
		contractRelationService.insertList(batchInsertList);
	}
}

private void recordMainContractRelation(List<Contract> mainContractList) {
	if (mainContractList.size() <= 1 || !ContractTypeEnum.PERSONAL.getCode().equals(mainContractList.get(0).getType())) {
		return;
	}
	String contractCodesStr = mainContractList.stream().map(Contract::getContractCode).collect(Collectors.joining(","));
	for (Contract contract : mainContractList) {
		String groupDetailKey = Constant.CONTRACT_GROUP_RELATION_DETAIL + contract.getContractCode();
		stringRedisTemplate.opsForValue().set(groupDetailKey, contractCodesStr, 100, TimeUnit.SECONDS);
	}
	LOGGER.info("记录主合同关系，合同编号:{}", contractCodesStr);
}

private void terminalFundAmountCheck(String projectOrderId, Byte contractType) {
	if (!ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
		return;
	}
	CancelOrderBaseInfoDTO lastRecordInfo = cancelOrderRecordService.getLastRecordByProjectOrderId(projectOrderId);
	if (lastRecordInfo == null) {
		throw new NrsBusinessException(NrsBusinessException.DEFAULT_ERROR_CODE, "未找到退单信息", Level.ERROR);
	}
	if (!CancelOrderStatusEnum.AWAIT_SIGN_LAUNCH.getStatus().equals(lastRecordInfo.getStatus())) {
		throw new NrsBusinessException(NrsBusinessException.DEFAULT_ERROR_CODE, "当前退单状态不是待发起签约，请检查", Level.ERROR);
	}
	List<FundAmountDTO> fundAmountList = lastRecordInfo.getFundAmountList();
	List<FundInfo> allFundInfo = fundInfoService.getAllFundInfoByProjectOrderId(lastRecordInfo.getProjectOrderId());
	for (FundAmountDTO fundAmountDTO : fundAmountList) {
		FundInfo fundInfo = allFundInfo.stream().filter(info -> info.getFundType().equals(fundAmountDTO.getFundType())).findFirst().orElse(null);
		if (fundInfo == null) {
			continue;
		}
		if (fundInfo.getPaidAmount().compareTo(fundAmountDTO.getPaidAmount()) != 0) {
			String errorMessage = "款项实际支付金额与退单款项发起页的支付金额不一致,款项类型：" + fundInfo.getFundName() + ";可撤销退单重新发起";
			LOGGER.info("款项实际支付金额与退单款项发起页的支付金额不一致,款项id:{},实际支付金额：{},退单发起页金额：{}", fundInfo.getFundId(), fundInfo.getPaidAmount(), fundAmountDTO.getPaidAmount());
			throw new NrsBusinessException(errorMessage, Level.WARN);
		}
		if (fundInfo.getFundType().equals(FundTypeEnum.DEPOSIT.getValue())) {
			BigDecimal usableAmount = fundInfo.getPaidAmount().subtract(fundInfo.getDeductedAmount());
			if (usableAmount.compareTo(fundAmountDTO.getDeductibleAmount()) != 0) {
				String errorMessage = "定金实际支付金额与退单款项发起页的可抵扣金额不一致" + ";可撤销退单重新发起";
