	/**
	 * 签约重构当前城市是否开城
	 */
	public boolean isOpenCity(String projectOrderId, String customerCommissionCode) {
		// 如果没有传入项目id，只传入了客源code代表是零售详情页进入，返回开城标识
		if (StringUtils.isBlank(projectOrderId) && StringUtils.isNotBlank(customerCommissionCode)) {
			return true;
		}
		//获取该单对应gbCode
		ProjectInfo projectInfo = projectDetailService.getProjectInfo(projectOrderId);
		if (Objects.isNull(projectInfo)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目信息不存在");
		}

		// 兼容北京1.0设计合同
		if (CityEnum.BEIJING.getGbCode() == projectInfo.getGbcode()) {
			String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(projectOrderId);
			List<ProjectVersionDTO> projectVersionDTOS = projectInfoReadService.batchProjectVersion(Collections.singletonList(convertProjectOrderId));
			boolean isBeijingDesignContract = projectVersionDTOS.stream().anyMatch(version -> ProjectVersionEnum.V1.getVersion().equals(version.getProjectVersion()));
			if (isBeijingDesignContract) {
				return false;
			}
		}

		if (Boolean.TRUE.equals(contractApolloConfig.getAllOpenCity())) {
			return true;
		}

		List<String> cityOpenList = Arrays.stream(contractApolloConfig.getCityOpenList().split(",")).collect(Collectors.toList());
		return cityOpenList.contains(String.valueOf(projectInfo.getGbcode()));
	}


	/**
	 * 校验合同是否可以创建
	 */
	public ContractCheckNodeRes checkCanCreate(String projectOrderId, Byte contractType) {
		ContractCreateBaseInfo contractCreateBaseInfo = commonBusinessService.getCanCreateContract(projectOrderId, contractType, null);
		projectOrderId = contractCreateBaseInfo.getProjectOrderId();
		contractType = contractCreateBaseInfo.getContractType();
		List<Contract> contractList = contractService.getContractList(projectOrderId, contractType);
		//校验老团装项目
		boolean limitOrderSignPay = commonBusinessService.isLimitOrderSignPay(projectOrderId);
		if (limitOrderSignPay && !ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
			//老团装项目不允许签约
			throw new NrsBusinessException("已转新团装，请通过新客源继续签约收款", Level.WARN);
		}
		//关联订单退单流程校验处理
		checkAndDealWithCancelOrder(projectOrderId, contractType);
		//合同唯一性校验
		checkContractUnique(projectOrderId, contractType, contractList);
		ProjectInfoDTO projectInfo = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		ContractCheckNodeRes contractCheckNodeRes = preSignCheck(contractType, projectInfo, Boolean.FALSE, new ContractPreCheckBo());
		Byte businessType = commonContractService.getBusinessType(projectInfo);
		Boolean subjectNotSame = preSignCheckPlanAllDTO(businessType, projectOrderId, contractType);
		contractCheckNodeRes.setSubjectNotSame(subjectNotSame);
		if (contractUnifyServiceSelf.designFeeFromQuote(projectOrderId)
			&& (ContractTypeEnum.DESIGN.getCode().equals(contractType) || ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType))) {
			// 查询报价信息
			ContractSourceDataBO contractSourceDataBO = homeOrderDataConversionService.contractSourceDateNoThrow(projectOrderId, null);
			boolean haveDesignQuote = ObjectUtil.isNotEmpty(contractSourceDataBO)
				&& ObjectUtil.isNotEmpty(contractSourceDataBO.getDesignFeeInfo())
				&& DesignFeeSourceEnum.报价.getCode().equals(contractSourceDataBO.getDesignFeeInfo().getSource())
				&& BigDecimal.ZERO.compareTo(contractSourceDataBO.getDesignFeeInfo().getAfterDiscountDesignAmount()) != 0;
			if (ContractTypeEnum.DESIGN.getCode().equals(contractType) && haveDesignQuote) {
				throw new NrsBusinessException("正签报价已包含设计费，请直接发起正式套餐合同", Level.WARN);
			}
			if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && haveDesignQuote) {
				Contract contractInfo = contractService.getLatestUserSignContract(projectOrderId, ContractTypeEnum.DESIGN.getCode());
				if (ObjectUtil.isNotEmpty(contractInfo)) {
					throw new NrsBusinessException("已有有效设计合同，正签报价不应包含设计费，请撤销正签报价单后修改设计费", Level.WARN);
				}
			}
		}
		return contractCheckNodeRes;
	}

	/**
	 * 校验合同是否可以创建
	 *
	 * @param req
	 * @return
	 */
	public ContractSecondaryCheckRes secondaryCheckCanCreate(ContractSecondaryCheckReq req) {
		List<BillCodeInfo> billCodeInfos = contractBusinessService.converBillCodeListToBillCodeInfoList(req.getBillCodeList(), req.getBillCodeInfoList(), req.getProjectOrderId(), req.getContractType());
		req.setBillCodeInfoList(billCodeInfos);
		//默认不需要校验的直接返回true
		ContractSecondaryCheckRes checkRes = ContractSecondaryCheckRes.builder()
			.checkRes(Boolean.TRUE)
			.build();
		//首期合同二次校验是否需要选择预报价单
		if (req.getContractType().equals(ContractTypeEnum.ADVANCE.getCode())) {
			//如果首期合同支持预报价没开城呢，不需要校验
			if (Boolean.FALSE.equals(advanceSupportPreQuotation(req.getProjectOrderId(), ContractTypeEnum.ADVANCE.getCode()))) {
				return checkRes;
			}
			//没有选择报价单，返回false，需要用户弹窗选择
			if (CollectionUtils.isEmpty(req.getBillCodeList()) || StringUtils.isBlank(req.getBillCodeList().get(0))) {
				checkRes.setCheckRes(Boolean.FALSE);
				return checkRes;
			}
			//如果已经选择了报价单：1、报价单无效了需要toast提示&弹窗重新选择
			LightQuotationDTO.LightQuotationItem preQuotation = atomBudgetRpc.getPreQuotationByBillCode(req.getBillCodeList().get(0));
			if (preQuotation == null || preQuotation.getStatus() == null || !AtomBudgetRpc.CAN_SIGN_PRE_QUOTATION_STATUS.contains(preQuotation.getStatus())) {
				checkRes.setCheckRes(Boolean.FALSE);
				checkRes.setToast("所选预报价不是「已提交、正式版、已签约」状态，请重新选择");
				return checkRes;
			}
		} else if (ContractTypeEnum.PERSONAL.getCode().equals(req.getContractType())) {
			if (!contractApolloConfig.getCheckPersonalContract()) {
				return checkRes;
			}
			BindOrderInfoGroup group = BindOrderInfoGroup.convert(req.getProjectOrderId(), req.getSubOrderInfoList(), req.getBillCodeInfoList(), null);
			checkRes = checkPersonalListV2(req.getContractType(), req.getContractCode(), group);
		} else if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(req.getContractType())) {
			BindOrderInfoGroup group = BindOrderInfoGroup.convert(req.getProjectOrderId(), req.getSubOrderInfoList(), req.getBillCodeInfoList(), null);
			checkRes = checkFormalListV2(req.getContractType(), req.getContractCode(), group);
		}
		//C合同需要二次校验是否选择了协同报价单列表
		return checkRes;
	}

	/**
	 * 和解协议签前校验
	 */
	private void settlementCheckList(String projectOrderId) {
		if (!hasSignedPackageFormal(projectOrderId)) {
			throw new NrsBusinessException("正签未签署完成，不允许签署和解协议", Level.WARN);
		} else if (!hasNoProgressingSettlement(projectOrderId)) {
			throw new NrsBusinessException("存在在途和解协议，不允许重复发起和解协议", Level.WARN);
		} else if (!projectNoCompletion(projectOrderId)) {
			throw new NrsBusinessException("项目已竣工，不允许签署和解协议", Level.WARN);
		} else if (!settlementIsOpen(projectOrderId)) {
			// 正常情况下，未开城不展示卡片，不会走到这里
			throw new NrsBusinessException("和解协议未开城，不允许创建", Level.WARN);
		}
	}

	/**
	 * 补充协议签前校验
	 */
	private void supplementCheckList(String projectOrderId) {
		// 正签已签署 && 无在途补充协议 && 项目未竣工 && (整装 2.5 && Apollo 开城)
		if (!hasSignedPackageFormal(projectOrderId)) {
			throw new NrsBusinessException("正签未签署完成，不允许签署补充协议", Level.WARN);
		} else if (!hasNoProgressingSupplement(projectOrderId)) {
			throw new NrsBusinessException("存在在途补充协议，不允许重复发起补充协议", Level.WARN);
		} else if (!projectNoCompletion(projectOrderId)) {
			throw new NrsBusinessException("项目已竣工，不允许签署补充协议", Level.WARN);
		} else if (!supplementIsOpen(projectOrderId)) {
			// 正常情况下，未开城不展示卡片，不会走到这里
			throw new NrsBusinessException("补充协议未开城，不允许创建", Level.WARN);
		}
	}

	/**
	 * 首期合同是否支持打通预报价单：开城 & 配置了预报价单
