	public Boolean advanceSupportPreQuotation(String projectOrderId, Byte contractType) {
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
		Integer gbCode = projectInfoDTO.getCustomerHouse().getGbCode();
		String sourceCompanyCode = projectInfoDTO.getCustomerCommission().getCompanyCode();
		String companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectOrderId, gbCode, sourceCompanyCode, contractType);
		Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
