		List<ContractFieldConfig> fieldConfigs = getFieldConfigAdapt(projectOrderId, gbCode, companyCode, businessType, contractType, fieldConfigVersion);
		return !CollectionUtils.isEmpty(fieldConfigs) && fieldConfigs.stream().anyMatch(field -> "preQuotationFileUrl".equals(field.getFieldKey()));
	}


	/**
	 * 销售合同发起签约，关联的报价单列表校验
	 */
	@Deprecated
	public ContractSecondaryCheckRes checkPersonalList(String projectOrderId, Byte contractType, List<BillCodeInfo> billCodeInfoList, String contractCode, String changeOrderId) {
		if (!ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			return ContractSecondaryCheckRes.builder()
				.checkRes(Boolean.TRUE)
				.build();
		}
		//变更场景不校验
		if (StringUtils.isNotBlank(changeOrderId)) {
			return ContractSecondaryCheckRes.builder()
				.checkRes(Boolean.TRUE)
				.build();
		}
		List<String> billCodeList = billCodeInfoList.stream().map(BillCodeInfo::getBillCode).distinct().collect(Collectors.toList());
		ContractSecondaryCheckRes checkRes = ContractSecondaryCheckRes.builder()
			.checkRes(Boolean.TRUE)
			.build();
		if (CollectionUtil.isEmpty(billCodeInfoList)) {
			//校验是否选择了报价单
			checkRes.setCheckRes(Boolean.FALSE);
			return checkRes;
		}
		if (billCodeInfoList.size() > 10) {
			checkRes.setCheckRes(Boolean.FALSE);
			checkRes.setToast("最多选择10个报价单");
			return checkRes;
		}
		List<String> paramBillInfoList = billCodeInfoList.stream().map(item -> item.getBillCode() + '_' + item.getCompanyCode()).collect(Collectors.toList());
		if (StringUtils.isBlank(contractCode)) {
			List<String> relationInfoList = quotationRelationCommonService.getRelationListByBillCodeList(billCodeList)
				.stream().map(item -> item.getBillCode() + '_' + item.getCompanyCode()).collect(Collectors.toList());
			// 发起签约的报价单号已经关联过合同，则拦截
			if (CollectionUtil.isNotEmpty(CollectionUtil.intersection(paramBillInfoList, relationInfoList))) {
				checkRes.setCheckRes(Boolean.FALSE);
				checkRes.setToast("所选报价单已关联合同，请重新选择");
				return checkRes;
			}
		} else {
			//如果是编辑C合同的场景，校验所选报价单是否已经关联了除当前合同外的其他合同
			Contract contract = contractService.getByContractCode(contractCode);
			List<ContractQuotationRelation> relationListByBillCodeList = quotationRelationCommonService.getRelationListByBillCodeList(billCodeList);
			for (ContractQuotationRelation relationInfo : relationListByBillCodeList) {
				String relation = relationInfo.getBillCode() + "_" + relationInfo.getCompanyCode();
				// 如果是编辑合同的场景，当前报价单号已绑定合同 && 绑定的合同不是当前合同 && 当前合同不是变更合同，则拦截。（含义：如果当前合同是变更合同，则允许当前报价单绑定其他合同）
				// StringUtils.isBlank(contract.getChangeOrderId()) 含义：变更发起的销售合同，撤回之后重新编辑时，不校验对应的报价单是否已绑定合同。
				if (paramBillInfoList.contains(relation) && !relationInfo.getContractCode().equals(contractCode) && StringUtils.isBlank(contract.getChangeOrderId())) {
					checkRes.setCheckRes(Boolean.FALSE);
					checkRes.setToast("所选报价单已关联合同，请重新选择");
					return checkRes;
				}
			}
		}
		//校验报价单是否存在
		BudgetParams.QueryBillsCondition budgetParams = BudgetParams.QueryBillsCondition.builder()
			.projectOrderId(projectOrderId)
			.billCodes(billCodeList)
			.build();
		List<com.ke.utopia.atom.api.budget.dto.BudgetBillDTO.BillDTO> billDTOS = atomBudgetRpc.queryBillsByCondition(budgetParams);
		if (CollectionUtil.isEmpty(billDTOS)) {
			checkRes.setCheckRes(Boolean.FALSE);
			checkRes.setToast("所选报价单不存在，请重新选择");
			return checkRes;
		}
		for (com.ke.utopia.atom.api.budget.dto.BudgetBillDTO.BillDTO billDTO : billDTOS) {
			//所选组合单关联报价单状态无法发起签约，请重新选择
			if (GeneralBillStatusEnum.IN_ADJUST.getCode().equals(billDTO.getStatus())
				|| GeneralBillStatusEnum.DELETED.getCode().equals(billDTO.getStatus())
				|| GeneralBillStatusEnum.CANCELED.getCode().equals(billDTO.getStatus())) {
				checkRes.setCheckRes(Boolean.FALSE);
				checkRes.setToast("所选组合单关联报价单状态无法发起签约，请重新选择");
				return checkRes;
			}
		}
		return checkRes;
	}

	public ContractSecondaryCheckRes checkPersonalListV2(Byte contractType, String contractCode, BindOrderInfoGroup group) {
		// 仅销售合同发起需要校验
		if (!ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			return ContractSecondaryCheckRes.success();
		}

		LOGGER.info("checkPersonalListV2 入参 contractCode: {}, bindOrderInfoGroup: {}", contractCode, JSON.toJSONString(group));

		// 变更场景不校验
		if (CollectionUtil.isNotEmpty(group.getChangeOrderInfos())) {
			return ContractSecondaryCheckRes.success();
		}

		if (CollectionUtil.isEmpty(group.getBindOrderInfos())) {
			return ContractSecondaryCheckRes.fail("");
		}

		if (StringUtils.isBlank(contractCode)) {
			// 创建合同场景：如果要绑定的单据已绑过合同，则拦截
			if (quotationRelationCommonService.hasBoundOtherPositiveContractInPersonal(group, null)) {
				return ContractSecondaryCheckRes.fail("所选单据已关联合同，请重新选择");
			}
		} else {
			// 编辑合同场景
			Contract contract = contractService.getByContractCode(contractCode);
			// 当编辑普通合同时才校验单据是否已被绑定（变更合同，不校验单据已绑定）
			if (StringUtils.isBlank(contract.getChangeOrderId())
				&& quotationRelationCommonService.hasBoundOtherPositiveContractInPersonal(group, contractCode)) {
				return ContractSecondaryCheckRes.fail("所选单据已关联合同，请重新选择");
			}
		}

		boolean hasInvalidOrders = group.getBindOrderInfos().stream().anyMatch(bindOrderInfo -> contractSigningSourceRouter.route(bindOrderInfo.getBindType()).hasInvalidStatusOrders(bindOrderInfo));
		if (hasInvalidOrders) {
			return ContractSecondaryCheckRes.fail("所选单据状态无法发起签约，请重新选择");
		}

		return ContractSecondaryCheckRes.success();
	}

	/**
	 * 获取报价单对应的 S 单
