	private BindOrderInfoGroup buildSubOrderGroupOfBill(BindOrderInfoGroup group) {
		List<String> billCodes = group.getBillCodeInfos().stream().map(BillCodeInfo::getBillCode).collect(Collectors.toList());
		List<SubOrderInfo> subOrderInfos = new ArrayList<>();
		for (String billCode: billCodes) {
			List<SubOrderBaseInfoDTO> subOrderBaseInfoDTOS = subOrderFeignService.queryValidBaseInfoByHomeOrderNo(group.getProjectOrderId(), billCode, null);
			subOrderInfos.addAll(subOrderBaseInfoDTOS.stream().map(subOrderInfo -> SubOrderInfo.builder().subOrderNo(subOrderInfo.getOrderNo()).companyCode(subOrderInfo.getMdmCode()).build()).collect(Collectors.toList()));
		}
		return BindOrderInfoGroup.convert(group.getProjectOrderId(), subOrderInfos, null, null);
	}

	/**
