			businessType,
			contractReq.getContractBaseInfo().getContractType(),
			contractReq.getSignInfo().getSignChannelType()
		);
		if (org.apache.commons.collections4.CollectionUtils.isEmpty(configList)) {
			LOGGER.error("构建合同缺少合同配置信息，{},{},{},{},{}",
				gbCode,
				companyCode,
				businessType,
				contractReq.getContractBaseInfo().getContractType(),
				contractReq.getSignInfo().getSignChannelType()
			);
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "缺少合同配置信息，请完善合同配置", Level.WARN);
		}
		return configList.get(0);
	}


