	public ContractDetailResp detail(ContractDetailReq req, Byte contractType) {
		String contractCode = req.getContractCode();
		String projectOrderId = req.getProjectOrderId();
		Boolean isDetail = req.getIsDetail();
		Boolean isFirstScreen = req.getIsFirstScreen();
		List<BillCodeInfo> billCodeInfoList = req.getBillCodeInfoList();
		String changeOrderId = req.getChangeOrderId();
		List<SubOrderInfo> subOrderInfoList = req.getSubOrderInfoList();
		List<ChangeOrderInfo> changeOrderInfoList = req.getChangeOrderInfoList();
		Contract contract = null;
		if (StringUtils.isNotBlank(contractCode)) {
			contract = contractService.getByContractCode(contractCode);
			if (contract == null) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "合同不存在，请检查合同编号或联系客服", Level.WARN);
			}
		}
		BindOrderInfoGroup group = BindOrderInfoGroup.convert(projectOrderId, subOrderInfoList, billCodeInfoList, changeOrderInfoList);
		/**
		 * 兼容逻辑：正签特殊场景，前端无法传入，需要兼容前端未传入的场景
		 */
		group = buildGroupFromPackageContractField(projectOrderId, contractCode, contractType, group, isDetail);

		subOrderInfoList = group.getSubOrderInfos();
		changeOrderInfoList = group.getChangeOrderInfos();
		billCodeInfoList = group.getBillCodeInfos();

		if (!isFirstScreen && contractApolloConfig.getCheckPersonalContract() && ContractTypeEnum.PERSONAL.getCode().equals(contractType) && CollectionUtils.isEmpty(group.getBindOrderInfos())) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "个性化合同必须传入报价单列表", Level.WARN);
		}
		if (contract == null) {
			if (!ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
				//如果没有合同code，查询草稿状态的合同
				contract = contractService.getContractList(projectOrderId, contractType).stream()
					.filter(item -> ContractStatusEnum.DRAFT.getCode().equals(item.getStatus())).findFirst().orElse(null);
			}
		}

		ContractDetailResp detail = null;
		//如果是重签的合同并且当前没有合同草稿，带入上份合同信息
		if (contract == null) {
			detail = reSignFieldInfoFill(projectOrderId, contractType, isFirstScreen, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
		}

		// 如果没有上一份合同信息，则初始化合同详情信息
		if (detail == null) {
			changeOrderId = contract != null ? contract.getChangeOrderId() : changeOrderId;
			detail = contractUnifyServiceSelf.baseDetail(contract, projectOrderId, contractType, changeOrderId, isFirstScreen, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
		}
		ContractSignInfoDetail signInfo = detail.getSignInfo();
		if (!isDetail) {
			//不是详情页，不加密，进行对字段数据进行解密
			Map<String, String> decryptMap = cipherService.decrypt(
				Stream.of(
						signInfo.getOwnerCertificateNo(),
						signInfo.getAgentCertificateNo(),
						signInfo.getCompanyAgentCertificateNo(),
						signInfo.getLegalCertificateNo())
					.filter(StringUtils::isNotBlank)
					.distinct()
					.collect(Collectors.toList())
			);

			signInfo.setOwnerCertificateNo(decryptMap.getOrDefault(signInfo.getOwnerCertificateNo(), signInfo.getOwnerCertificateNo()));
			signInfo.setAgentCertificateNo(decryptMap.getOrDefault(signInfo.getAgentCertificateNo(), signInfo.getAgentCertificateNo()));
			signInfo.setCompanyAgentCertificateNo(decryptMap.getOrDefault(signInfo.getCompanyAgentCertificateNo(), signInfo.getCompanyAgentCertificateNo()));
			signInfo.setLegalCertificateNo(decryptMap.getOrDefault(signInfo.getLegalCertificateNo(), signInfo.getLegalCertificateNo()));
			detail.getContractBaseInfo().setIsDetail(Boolean.FALSE);
		}
		signInfo.setOwnerPhone(cipherService.encrypt(signInfo.getOwnerPhone()));
		signInfo.setAgentPhone(cipherService.encrypt(signInfo.getAgentPhone()));
		signInfo.setCompanyAgentPhone(cipherService.encrypt(signInfo.getCompanyAgentPhone()));
		signInfo.setSignatoryPhone(cipherService.encrypt(signInfo.getSignatoryPhone()));
		signInfo.setLegalPhone(cipherService.encrypt(signInfo.getLegalPhone()));
		detail.getSignInfo().setCustomerPhoneVoList(contractDetailService.getCustomerPhoneVoList(detail.getSignInfo(), isDetail));
		return detail;
	}

	/**
	 * 如果允许多份合同，代表是重签的合同，带入上份合同信息
	 */
	private ContractDetailResp reSignFieldInfoFill(String projectOrderId, Byte contractType, boolean isFirstScreen, List<BillCodeInfo> billCodeInfoList, List<SubOrderInfo> subOrderInfoList, List<ChangeOrderInfo> changeOrderInfoList) {
		boolean allowedFillHistoryContractInfo = ContractTypeEnum.allowedFillHistoryContractInfo(contractType);
		if (!allowedFillHistoryContractInfo) {
			return null;
		}

		Contract latestContract = contractService.getLatestContract(projectOrderId, contractType);
		if (latestContract == null) {
			return null;
		}
		ContractDetailResp contractDetailResp = contractUnifyServiceSelf.baseDetail(latestContract, latestContract.getProjectOrderId(), latestContract.getType(), null, isFirstScreen, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
		if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			//C合同重签不带入合同url相关的信息
			ContractSignInfoDetail signInfo = contractDetailResp.getSignInfo();
			signInfo.setAttachUrl(null);
			signInfo.setPersonalAttachUrl(null);
			signInfo.setUserSignTime(null);
			signInfo.setCompanySignTime(null);
			signInfo.setPersonalCompanySignTime(null);
			signInfo.setPersonalUserSignTime(null);
			// C 合同不下发上一份的 contractCode
			ContractBaseInfoDetail contractBaseInfo = contractDetailResp.getContractBaseInfo();
			contractBaseInfo.setContractCode(null);
		}
		return contractDetailResp;
	}

