	/**
	 * 合同详情
	 *
	 * @param contract
	 * @param projectOrderId
	 * @param contractType
	 * @return
	 */
	@ContractDetailDataPrepare
	public ContractDetailResp baseDetail(Contract contract, String projectOrderId, Byte contractType, String changeOrderId, Boolean isFirstScreen, List<BillCodeInfo> billCodeInfoList, List<SubOrderInfo> subOrderInfoList, List<ChangeOrderInfo> changeOrderInfoList) {
		//从核心域中获取billCodeInfoList
		List<String> moduleKeyList = getModuleInfo(projectOrderId,
			contractType, null, null).stream().map(ContractModuleAndFieldInfoDTO::getModuleKey).collect(Collectors.toList());
		//合同不存在，返回初始化数据
		if (contract == null) {
			return contractDetailService.initContractDetail(projectOrderId, contractType, moduleKeyList, changeOrderId, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
		}
		projectOrderId = contract.getProjectOrderId();
		contractType = contract.getType();
		//合同字段信息
		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contract.getContractCode());
		Map<String, String> fieldMap = Maps.newHashMap();
		contractFieldList.forEach(contractField -> fieldMap.put(contractField.getFieldKey(), contractField.getFieldValue()));
		List<ContractAttach> contractAttachList = contractAttachService.getListByContractCode(contract.getContractCode());

		//首屏只加载signInfo、contractBaseInfo、businessInfo、projectInfo4个对象，且涉及中控的字段不保证准确性
		if (isFirstScreen) {
			//项目信息 houseType使用中控接口，首屏不保证准确
			ContractProjectInfoDetail projectInfoDetail = contractDetailService.buildContractProjectInfoDetail(contract, contractType, projectOrderId, fieldMap);
			//合同基础信息  havePersonalQuote、contractMode使用中控接口，首屏不保证准确
			ContractBaseInfoDetail baseInfoDetail = contractDetailService.buildContractBaseInfoDetail(contract, projectOrderId, contractType, changeOrderId, fieldMap, false);
			//合同签约信息 salesCompanyName 使用中控接口，首屏不保证准确
			ContractSignInfoDetail signInfoDetail = contractDetailService.buildContractSignInfoDetail(contract, contractType, projectInfoDetail, fieldMap, contractAttachList, changeOrderId);
			//合同附件信息
			ContractAttachInfoDetail contractAttachInfo = contractDetailService.buildContractAttachInfo(moduleKeyList, contract, contractAttachList, signInfoDetail, fieldMap, projectOrderId, contractType);
			//合并附件信息到签约信息
			contractDetailService.mergeContractAttachInfoTOSignInfo(projectOrderId, contractType, contractAttachInfo, signInfoDetail);
			//业务信息 billCodeList 使用中控接口，首屏不保证准确
			BusinessInfoDetail businessInfo = contractDetailService.buildBusinessInfoDetail(contract, projectInfoDetail, fieldMap, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
			// 补充协议信息
			SupplementItemInfo supplementItemInfo = contractDetailService.buildSupplementItemInfo(contract, fieldMap);
			return ContractDetailResp.builder().signInfo(signInfoDetail).contractBaseInfo(baseInfoDetail)
				.businessInfo(businessInfo).projectInfo(projectInfoDetail).supplementItemInfo(supplementItemInfo).build();
		}

		ContractProjectInfoDetail projectInfoDetail = contractDetailService.buildContractProjectInfoDetail(contract, contractType, projectOrderId, fieldMap);
		//合同基础信息
		ContractBaseInfoDetail baseInfoDetail = contractDetailService.buildContractBaseInfoDetail(contract, projectOrderId, contractType, changeOrderId, fieldMap, false);
		//合同签约信息
		ContractSignInfoDetail signInfoDetail = contractDetailService.buildContractSignInfoDetail(contract, contractType, projectInfoDetail, fieldMap, contractAttachList, changeOrderId);

		//承包约定
		PromiseInfoDetail promiseInfoDetail = contractDetailService.buildPromiseInfoDetail(contract, fieldMap, projectOrderId, contractType);
		//保修信息
		GuaranteeDetail guaranteeDetail = contractDetailService.buildGuaranteeDetail(moduleKeyList, fieldMap);
		//优惠信息
		ActivityInfo activityInfo = contractDetailService.buildActivityInfoDetail(moduleKeyList, projectOrderId, changeOrderId);
		//报价信息
		QuotationInfo quotationInfo = contractDetailService.buildQuotationDetail(moduleKeyList, projectOrderId, changeOrderId, projectInfoDetail.getBusinessType(), contractType, fieldMap);
		//图纸信息
		DrawingInfo drawing = contractDetailService.buildDrawingDetail(moduleKeyList, changeOrderId, contractType);
		//收款计划信息
		CollectionPlanConfigInfo collectionPlanConfigInfo = contractDetailService.buildCollectionPlanConfigInfo(moduleKeyList, contract, changeOrderId);
		//合同附件信息
		ContractAttachInfoDetail contractAttachInfo = contractDetailService.buildContractAttachInfo(moduleKeyList, contract, contractAttachList, signInfoDetail, fieldMap, projectOrderId, contractType);
		//个性化报价
		PersonalQuotation personalQuotation = contractDetailService.buildPersonalQuotationDetail(contract, moduleKeyList, quotationInfo, contractType, fieldMap);
		//业务信息
		BusinessInfoDetail businessInfo = contractDetailService.buildBusinessInfoDetail(contract, projectInfoDetail, fieldMap, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
		//金额信息
		AmountInfo amountInfo = contractDetailService.buildAmountInfoDetail(fieldMap);
		// 流程信息
		ProcessInfo processInfo = contractDetailService.buildProcessInfoDetail(contract);
		// 定软电收款计划
		PersonalCollectionPlanInfo personalCollectionPlanInfo = contractDetailService.buildPersonalCollectionPlanInfo(moduleKeyList);
		// 备件ocr开城将备件信息返回到签约信息模块
		contractDetailService.mergeContractAttachInfoTOSignInfo(projectOrderId, contractType, contractAttachInfo, signInfoDetail);
		// 补充协议信息
		SupplementItemInfo supplementItemInfo = contractDetailService.buildSupplementItemInfo(contract, fieldMap);
		// 和解协议信息
		SettlementItemInfo settlementItemInfo = contractDetailService.buildSettlementItemInfo(contract, fieldMap);
		return ContractDetailResp.builder()
			.businessInfo(businessInfo)
			.contractBaseInfo(baseInfoDetail)
			.projectInfo(projectInfoDetail)
			.signInfo(signInfoDetail)
			.promiseInfo(promiseInfoDetail)
			.guaranteeInfo(guaranteeDetail)
			.activityInfo(activityInfo)
			.quotation(quotationInfo)
			.drawing(drawing)
			.contractPrice(quotationInfo == null ? null : ContractPrice.builder().contractPriceTotal(quotationInfo.getContractPrice()).build())
			.collectionPlanConfigInfo(collectionPlanConfigInfo)
			.contractAttachInfo(contractAttachInfo)
			.personalQuotation(personalQuotation)
			.amountInfo(amountInfo)
			.processInfo(processInfo)
			.personalCollectionPlanInfo(personalCollectionPlanInfo)
			.supplementItemInfo(supplementItemInfo)
			.settlementItemInfo(settlementItemInfo)
			.build();
	}

