	/**
	 * 获取变更合同详情
	 */
	public ContractDetailResp changeDetail(String contractCode, String projectOrderId, String changeOrderId, boolean isDetail, Byte contractType, boolean isFirstScreen) {
		ContractDetailResp contractDetailResp;
		//如果有contractCode直接查询详情
		if (StringUtils.isNotBlank(contractCode)) {
			Contract contract = contractService.getByContractCode(contractCode);
			//上一份有效合同
			Contract prevContract = contractService.getChangePrevEffectContract(contract.getId(), contract.getProjectOrderId());
			if (prevContract == null) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少上一份有效的合同");
			}
			contractDetailResp = contractUnifyServiceSelf.baseDetail(contract, contract.getProjectOrderId(), contract.getType(), changeOrderId, isFirstScreen, null, null, null);
			contractDetailResp.setLastSignInfo(buildLastSignInfo(prevContract));
		} else {
			//如果没有contractCode：在变更合同编辑页,可能已经保存草稿，也可能第一次进入
			//查询草稿态的变更合同,一个变更单只会对应一份草稿中的合同
			List<Contract> changeContractList = contractService.getChangeContractList(projectOrderId, changeOrderId)
				.stream().filter(contract -> ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())).collect(Collectors.toList());
			if (!CollectionUtils.isEmpty(changeContractList)) {
				//当前变更有草稿中的合同,合同详情为当前草稿中合同的详情
				Contract currentContract = changeContractList.get(0);
				contractDetailResp = contractUnifyServiceSelf.baseDetail(currentContract, currentContract.getProjectOrderId(), currentContract.getType(), changeOrderId, isFirstScreen, null, null, null);
				//上一份合同信息
				Contract prevContract = contractService.getChangePrevEffectContract(currentContract.getId(), currentContract.getProjectOrderId());
				if (prevContract == null) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少上一份有效的合同");
				}
				contractDetailResp.setLastSignInfo(buildLastSignInfo(prevContract));
			} else {
				//当前变更没有草稿中的合同,合同详情为上一份(正签/变更)合同详情
				Contract prevContract = contractService.getChangePrevEffectContractByPid(projectOrderId);
				if (prevContract == null) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少上一份有效的合同");
				}
				contractDetailResp = contractUnifyServiceSelf.baseDetail(prevContract, prevContract.getProjectOrderId(), prevContract.getType(), changeOrderId, isFirstScreen, null, null, null);
				contractDetailResp.setLastSignInfo(buildLastSignInfo(prevContract));
				//重置变更合同信息为默认初始化信息
				contractDetailResp.setContractBaseInfo(ContractBaseInfoDetail.builder()
					.projectOrderId(projectOrderId)
					.changeOrderId(changeOrderId)
					.havePersonalQuote(contractDetailResp.getContractBaseInfo().isHavePersonalQuote())
					.changeOrderType(contractDetailResp.getContractBaseInfo().getChangeOrderType())
					.contractType(ContractTypeEnum.PACKAGE_CHANGE.getCode())
					.formalMergeLaunch(contractDetailResp.getContractBaseInfo().isFormalMergeLaunch())
					.processV25(contractDetailResp.getContractBaseInfo().isProcessV25())
					.useAddressFromDictionary(contractDetailResp.getContractBaseInfo().getUseAddressFromDictionary())
					.needRealNameVerifyInConfirm(contractDetailResp.getContractBaseInfo().getNeedRealNameVerifyInConfirm())
					.standardDesignFeeOpen(contractDetailResp.getContractBaseInfo().getStandardDesignFeeOpen())
					.build());
				// 不默认带出上一份合同的「实际客户签署时间」、「盖公司章时间」
				ContractSignInfoDetail signInfo = contractDetailResp.getSignInfo();
				signInfo.setUserSignTime(null);
				signInfo.setCompanySignTime(null);

				signInfo.setAttachUrl(Collections.emptyList());
				boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType)
					&& BusinessTypeEnum.getHouseCertificate25ModeList().contains(commonBusinessService.getBusinessType(projectOrderId));
				//只有2.5走这块逻辑
				if (houseProcessV25) {
					//有报价变更，原始户型需要取客源的
					ContractProjectInfoDetail projectInfo = contractDetailResp.getProjectInfo();
					ChangeApplyInfoDTO changeApplyInfoDTO = atomChangeRpc.getChangeApplyInfo(changeOrderId);
					List<Integer> changeScopeList = changeApplyInfoDTO.getChangeScopeList();
					if (changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode())) {
						ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
						projectInfo.setRoomCnt(projectInfoDTO.getCustomerHouse().getRoomCnt());
						projectInfo.setParlorCnt(projectInfoDTO.getCustomerHouse().getParlorCnt());
						projectInfo.setCookroomCnt(projectInfoDTO.getCustomerHouse().getCookroomCnt());
						projectInfo.setToiletCnt(projectInfoDTO.getCustomerHouse().getToiletCnt());
						projectInfo.setBalconyCnt(projectInfoDTO.getCustomerHouse().getBalconyCnt());
						projectInfo.setStorageCnt(projectInfoDTO.getCustomerHouse().getStorageCnt());
					}
				}
			}
		}
		ContractSignInfoDetail signInfo = contractDetailResp.getSignInfo();
		LastSignInfo lastSignInfo = contractDetailResp.getLastSignInfo();
		if (!isDetail) {
			//不是详情页，不加密，进行对字段数据进行解密
			//todo 优化
			signInfo.setOwnerCertificateNo(cipherService.decrypt(signInfo.getOwnerCertificateNo()));
			signInfo.setAgentCertificateNo(cipherService.decrypt(signInfo.getAgentCertificateNo()));
			signInfo.setCompanyAgentCertificateNo(cipherService.decrypt(signInfo.getCompanyAgentCertificateNo()));
			signInfo.setLegalCertificateNo(cipherService.decrypt(signInfo.getLegalCertificateNo()));
			lastSignInfo.setOwnerCertificateNo(cipherService.decrypt(lastSignInfo.getOwnerCertificateNo()));
			lastSignInfo.setAgentCertificateNo(cipherService.decrypt(lastSignInfo.getAgentCertificateNo()));
			lastSignInfo.setCompanyAgentCertificateNo(cipherService.decrypt(lastSignInfo.getCompanyAgentCertificateNo()));
			lastSignInfo.setLegalCertificateNo(cipherService.decrypt(lastSignInfo.getLegalCertificateNo()));
			contractDetailResp.getContractBaseInfo().setIsDetail(Boolean.FALSE);
		}
		//手机号统一加密返回
		signInfo.setOwnerPhone(cipherService.encrypt(signInfo.getOwnerPhone()));
		signInfo.setAgentPhone(cipherService.encrypt(signInfo.getAgentPhone()));
		signInfo.setCompanyAgentPhone(cipherService.encrypt(signInfo.getCompanyAgentPhone()));
		signInfo.setLegalPhone(cipherService.encrypt(signInfo.getLegalPhone()));
		signInfo.setSignatoryPhone(cipherService.encrypt(signInfo.getSignatoryPhone()));
		lastSignInfo.setOwnerPhone(cipherService.encrypt(lastSignInfo.getOwnerPhone()));
		lastSignInfo.setAgentPhone(cipherService.encrypt(lastSignInfo.getAgentPhone()));
		lastSignInfo.setCompanyAgentPhone(cipherService.encrypt(lastSignInfo.getCompanyAgentPhone()));
		lastSignInfo.setLegalPhone(cipherService.encrypt(lastSignInfo.getLegalPhone()));

		contractDetailResp.getSignInfo().setCustomerPhoneVoList(contractDetailService.getCustomerPhoneVoList(contractDetailResp.getSignInfo(), isDetail));
		//是否支持公对公线上签约
		contractDetailResp.getContractBaseInfo().setSupportCompanyOnlineSign(commonContractService.openCompanySignOnline(projectOrderId));

		return contractDetailResp;
	}

	/**
	 * 当前合同是否是重签
	 */
	private boolean reSign(String projectOrderId, Byte contractType) {
		List<Contract> contractList = contractService.getContractList(projectOrderId, contractType);
		if (CollectionUtils.isEmpty(contractList)) {
			return false;
		}
		List<Integer> finalContractStatus = Arrays.asList(ContractStatusEnum.USER_CONFIRMED.getCode(), ContractStatusEnum.FINISH.getCode());
		List<Contract> contractListFilter = contractList.stream().filter(item -> finalContractStatus.contains(item.getStatus()))
			.collect(Collectors.toList());
		return !CollectionUtils.isEmpty(contractListFilter);
	}


	/**
	 * 构建上一次合同签约信息
	 */
	private LastSignInfo buildLastSignInfo(Contract preContract) {
		List<ContractAttach> contractAttachList = contractAttachService.getListByContractCode(preContract.getContractCode());
		List<String> attachUrl = contractAttachList.stream()
			.filter(contractAttach -> AttachTypeEnum.OFFLINE_CONTRACT.getCode().byteValue() == contractAttach.getAttachType())
			.map(ContractAttach::getUrl).collect(Collectors.toList());
		//合同字段信息
		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(preContract.getContractCode());
		Map<String, String> fieldMap = contractFieldList.stream().collect(Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue));
		LastSignInfo lastSignInfo = new LastSignInfo();
		//组装和主体相关的信息：客户姓名、客户手机号、客户证件类型、客户身份证、客户住所地址、企业名称、统一社会信用代码、代理人姓名、代理人手机号、代理人证件类型、代理人证件
		ContractSignInfoDetail signInfoDetail = contractDetailService.buildContractSignInfoDetail(preContract, preContract.getType(), null, fieldMap, contractAttachList, preContract.getChangeOrderId());
		BeanUtils.copyProperties(signInfoDetail, lastSignInfo);
		//组装上一次合同模块展示字段
		String contractObjectType = fieldMap.get("contractObjectType");
		lastSignInfo.setLastAttachUrl(attachUrl.stream().map(url -> File.builder().url(url).build()).collect(Collectors.toList()));
		lastSignInfo.setLastAttachFileType(contractBusinessService.getAttachFileKey(attachUrl));
		lastSignInfo.setLastContractObjectTypeName(contractObjectType == null ? "" : ContractObjectTypeEnum.getLabelByCode(Byte.valueOf(contractObjectType)));
		lastSignInfo.setLastSignChannelTypeName(SignChannelTypeEnum.getLabelByCode(preContract.getSignChannelType()));
		return lastSignInfo;
	}


