	/**
	 * 个性化首期合同校验分公司信息
	 */
	public void checkSignCompanyInfo(ContractReqDTO contractReq) {
		ContractSignInfoReq signInfo = contractReq.getSignInfo();
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();
		if (!ContractTypeEnum.PERSONALIZED_CONTRACT.contains(contractType)) {
			return;
		}
		if (ObjectUtil.isEmpty(signInfo)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "签约主体信息不能为空");
		}
		List<FullCompanyInfoDTO> companyList = getSignCompanyByProjectOrderIdAndContractType(projectOrderId, contractType);
		if (companyList == null || companyList.isEmpty()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "未配置签约主体，请提交工单反馈");
		}

		//校验签约主体变更是否允许
		List<String> projectIdWhiteList = StringUtils.isEmpty(advanceContractModifyMdmWhiteList) ? new ArrayList<>() : Arrays.asList(advanceContractModifyMdmWhiteList.split(","));
		if (projectIdWhiteList.contains(projectOrderId)) {
			return;
		}

		Contract contract = contractService.getLatestUserSignContract(projectOrderId, contractType);
		boolean needCheckPaidAmount = contract != null && !contract.getCompanyCode().equals(signInfo.getSignCompanyCode());
		if (!needCheckPaidAmount) {
			return;
		}
		Integer fundType = FundRelateContractMapping.obtainFundTypeByContractType(contract.getType());
		if (projectInfoReadService.isDownPaymentOldVersionForRead(projectOrderId)) {
			FundInfo fundInfo = fundInfoService.getFundByOrderIdAndFundType(projectOrderId, fundType);
			if (fundInfo == null) return;
			PageInfo<FundSerial> fundSerialPageInfo = fundSerialService.getFundSerialListPageAndCountByFundIdAndFlowTypeAndStatus(fundInfo.getFundId(), FlowTypeEnum.FUND_PAID, FundSerialStatusEnum.PAID_AMOUNT_LIST, 1, 1);
			if (fundSerialPageInfo.getSize() > 0) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当首期款支付过，不允许修改签约主体");
			}
		} else {
			//订单模式
			List<String> orderNos = projectInfoReadService.getAdvancePaymentOrderNoListFilterFundTypes(projectOrderId, Collections.singletonList(fundType));
			if (orderNos.isEmpty()) return;
			List<CompositPaidDTO> compositPaidDTOList = orderCenterRpc.batchQueryPaid(orderNos);
			boolean isPaid = compositPaidDTOList.stream().anyMatch(CompositPaidDTO::getIsPaid);
			if (isPaid) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当首期款支付过，不允许修改签约主体");
			}
		}
	}

