	private void checkFieldValue(ContractFieldConfig fieldInfo, Object moduleValue, ContractReqDTO contractReq) {
		//自定义字段的key
		List<String> fieldKeyCustom = Arrays.asList("cityObj", "districtObj", "resblockObj", "addressObj", "apartmentObj", "signObject");
		if (fieldKeyCustom.contains(fieldInfo.getFieldKey())) {
			checkFieldKeyCustom(contractReq, fieldInfo);
			return;
		}
		Object keyValue = CommonUtil.getObjectFieldData(fieldInfo.getFieldKey(), moduleValue);
		if (keyValue == null) {
			String errorMsg = String.format("%s字段不能为空，请输入%s", fieldInfo.getFieldName(), fieldInfo.getFieldName());
			throw new NrsBusinessException(errorMsg, Level.WARN);
		}
		String keyValueStr = String.valueOf(keyValue);
		if (StringUtils.isBlank(keyValueStr)) {
			String errorMsg = String.format("%s字段不能为空，请输入%s", fieldInfo.getFieldName(), fieldInfo.getFieldName());
			throw new NrsBusinessException(errorMsg, Level.WARN);
		}
	}


	/**
	 * 条件校验, true：通过，false：不通过
	 *
	 * @param condition   如：contractBaseInfo.contractType=1
	 * @param contractReq
	 * @return
	 */
	private boolean conditionCheck(String condition, ContractReqDTO contractReq) {
		if (StringUtils.isBlank(condition)) {
			return true;
		}
		String[] split = condition.split("==");
		String moduleNameAndKeyName = split[0];
		String[] moduleNameAndKeyNameSplit = moduleNameAndKeyName.split("\\.");
		String keyValueFromConfig = split[1];
		String moduleName = moduleNameAndKeyNameSplit[0];
		String keyName = moduleNameAndKeyNameSplit[1];
		Object moduleValue = CommonUtil.getObjectFieldData(moduleName, contractReq);
		//模块值为空，不需要校验
		if (moduleValue == null) {
			return true;
		}
		Object keyValueFromParam = CommonUtil.getObjectFieldData(keyName, moduleValue);
		//条件中字段值为空，不需要校验
		if (keyValueFromParam == null) {
			return true;
		}
		return keyValueFromParam.equals(keyValueFromConfig);
	}

