	public List<ContractModuleConfig> getModuleConfigAdapt(Integer gbcode, String companyCode, Byte businessType, Byte contractType, Integer moduleConfigVersion) {
		List<ContractModuleConfig> moduleConfig = contractModuleConfigService.getModuleConfig(gbcode, companyCode, businessType, contractType, moduleConfigVersion);
		if (CollectionUtils.isEmpty(moduleConfig)) {
			moduleConfig = contractModuleConfigService.getModuleConfig(gbcode, businessType, contractType, moduleConfigVersion);
		}
		if (CollectionUtils.isEmpty(moduleConfig)) {
			moduleConfig = contractModuleConfigService.getModuleConfig(businessType, contractType, moduleConfigVersion);
		}
		if (CollectionUtils.isEmpty(moduleConfig)) {
			throw new NrsBusinessException(String.format("城市:%s 分公司:%s 业务类型:%s 合同类型:%s,配置版本:%s 对应合同模块配置缺失,请联系运营配置",
				gbcode, companyCode, BusinessTypeEnum.getNameByCode(businessType), ContractTypeEnum.getNameByContractTypeAndBusinessType(contractType, businessType), moduleConfigVersion), Level.ERROR);
		}
		// 将promiseInfo模块调整到projectInfo模块后面，枚举为ContractModuleEnum
		adjustModuleOrder(moduleConfig);

		return moduleConfig;
	}

	/**
	 * 调整模块顺序，将promiseInfo模块调整到projectInfo模块紧邻后面
	 *
	 * @param moduleConfigs 模块配置列表
	 */
	private void adjustModuleOrder(List<ContractModuleConfig> moduleConfigs) {
		if (CollectionUtils.isEmpty(moduleConfigs)) {
			return;
		}

		// 查找projectInfo和promiseInfo模块的索引
		int projectInfoIndex = -1;
		int promiseInfoIndex = -1;

		for (int i = 0; i < moduleConfigs.size(); i++) {
			ContractModuleConfig config = moduleConfigs.get(i);
			if (ContractModuleEnum.CONTRACT_PROJECT_INFO.getKey().equals(config.getModuleKey())) {
				projectInfoIndex = i;
			} else if (ContractModuleEnum.PROMISE_INFO.getKey().equals(config.getModuleKey())) {
				promiseInfoIndex = i;
			}
		}

		// 如果两个模块都存在，且promiseInfo不是紧邻在projectInfo后面，则调整顺序
		if (projectInfoIndex != -1 && promiseInfoIndex != -1 && promiseInfoIndex != projectInfoIndex + 1) {
			// 先移除promiseInfo模块
			ContractModuleConfig promiseInfo = moduleConfigs.remove(promiseInfoIndex);
			// 重新计算projectInfo的索引（如果promiseInfo在projectInfo前面，移除后索引会减1）
			if (promiseInfoIndex < projectInfoIndex) {
				projectInfoIndex--;
			}
			// 将promiseInfo插入到projectInfo的紧邻后面
			moduleConfigs.add(projectInfoIndex + 1, promiseInfo);
		}
	}

	/**
	 * 获取字段配置，逐层找配置信息，先(城市+分公司+业务类型)找，找不到再以(城市+业务类型)找，再找不到以(业务类型)找
	 *
	 * @param gbcode
	 * @param companyCode
	 * @param businessType
	 * @return
	 */
	public List<ContractFieldConfig> getFieldConfigAdapt(String projectOrderId, Integer gbcode, String companyCode, Byte businessType, Byte contractType, Integer fieldConfigVersion) {
		List<ContractFieldConfig> fieldConfig = contractFieldConfigService.getFieldConfig(gbcode, companyCode, businessType, contractType, fieldConfigVersion);
		if (CollectionUtils.isEmpty(fieldConfig)) {
			fieldConfig = contractFieldConfigService.getFieldConfig(gbcode, businessType, contractType, fieldConfigVersion);
		}
		if (CollectionUtils.isEmpty(fieldConfig)) {
			fieldConfig = contractFieldConfigService.getFieldConfig(businessType, contractType, fieldConfigVersion);
		}
		if (CollectionUtils.isEmpty(fieldConfig)) {
			throw new NrsBusinessException(String.format("城市:%s 分公司:%s 业务类型:%s 合同类型:%s 配置版本:%s 对应合同字段配置缺失,请联系运营配置",
				gbcode, companyCode, BusinessTypeEnum.getNameByCode(businessType), ContractTypeEnum.getNameByContractTypeAndBusinessType(contractType, businessType), fieldConfigVersion), Level.ERROR);
		}

		//对公签约，未开城的场景，法人相关字段不下发;对公全部开城后这段逻辑删除
		if (!commonContractService.openCompanySignOnline(projectOrderId, gbcode)) {
			List<String> legalFields = Arrays.asList("signRole", "legalName", "legalPhone", "legalCertificateType", "legalCertificateNo", "legalCertificateUnify");
			fieldConfig = fieldConfig.stream().filter(field -> !legalFields.contains(field.getFieldKey())).collect(Collectors.toList());
		}
		if (ContractTypeEnum.DESIGN_FEE_DESIGN_TYPES.contains(contractType) || ContractTypeEnum.DESIGN_FEE_PACKAGE_TYPES.contains(contractType)) {
			if (contractUnifyServiceSelf.designFeeCalculateIsOpen(projectOrderId)) {
				// 设计师职级名称字段，开城后只读展示
				fieldConfig = fieldConfig.stream().filter(field -> !"designerLevel".equals(field.getFieldKey())).collect(Collectors.toList());

				// 设计服务费【优惠前】：开城后，根据开城配置，已开城下发不可编辑
				fieldConfig.stream()
					.filter(field -> "preDiscountDesignerAmount".equals(field.getFieldKey()))
					.forEach(field -> field.setDisabled(CommonEnum.YES.getCode()));
			} else {
				// 设计师职级名称字段，开城前选择下拉框
				fieldConfig = fieldConfig.stream().filter(field -> !"designerLevelName".equals(field.getFieldKey())).collect(Collectors.toList());
			}
		}
		return fieldConfig;
	}

	/**
	 * pdf生成：只生成线上的合同，线下合同只有图片从附件中获取
	 */
	public String createOnlinePdf(Contract contract, Boolean finalVersion) {
		// 变更合同需要
		if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType())) {
			ChangeContractFreeformDTO freeformDTO = changeContractUnifyService.buildChangeContractFreeformDTO(contract.getContractCode(), contract.getProjectOrderId(), contract.getChangeOrderId(), true);
			//校验合同pdf是否需要更新
			checkChangeContractPdf(freeformDTO);
			ObjectMapper objectMapper = new ObjectMapper();
			Map<String, Object> map = objectMapper.convertValue(freeformDTO, Map.class);
			return contractBusinessService.generatePdf(contract, map);
		}

		if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
			return null;
		}

		ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfigByContractType(contract);

		if (config == null) {
			throw new NrsBusinessException("合同模版配置缺失", Level.ERROR);
		}
		//获取协议平台字段配置
		List<ContractProtocolConfig> contractProtocolConfigs = contractProtocolConfigService.getContractProtocolConfig(config.getFormKey(),
			config.getFormId());
		if (CollectionUtils.isEmpty(contractProtocolConfigs)) {
			throw new NrsBusinessException("协议平台模板字段配置缺失", Level.ERROR);
		}
		ContractContextHandler.getContext().setContract(contract);

		if (PdfGenerationModeEnum.UNFORMATTED.getCode().equals(contract.getPdfGenerationMode())) {
			return contractPdfCreateService.createPdfBySelfGeneration(contract, config, finalVersion);
		} else {
			return contractPdfCreateService.createPdfByFreeform(contract, config, finalVersion);
		}
	}

