	/**
	 * 合同已经生成，合同最终提交之前获取预览的链接
	 * 线上合同：获取合同PDF
	 * 线下合同：获取附件中的IMAGE	 * @param contractCode
	 *
	 * @return
	 */
	public ContractSubmitResDTO previewByCode(String contractCode) {
		Contract contract = contractService.getByContractCode(contractCode);
		if (contract == null) {
			throw new NrsBusinessException("未查询到合同,合同编码:" + contractCode);
		}
		String contractPollKey = getContractPollKey(contract.getProjectOrderId(), contract.getType());
		List<FileInfo> contractUrl = new ArrayList<>();
		CompletableFuture<Void> launchFuture = CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				LOGGER.info("异步发起合同预览开始，contractCode:{}，threadId:{}", contractCode, Thread.currentThread().getId());
				if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
					//线下签约
					List<ContractAttach> offlineAttachList = contractAttachService.getListByContractCode(contractCode, AttachTypeEnum.OFFLINE_CONTRACT.getCode());
					for (ContractAttach attach : offlineAttachList) {
						contractUrl.add(FileInfo.builder()
							.type(contractBusinessService.getAttachFileKey(Collections.singletonList(attach.getUrl())))
							.contractType(contract.getType())
							.url(attach.getUrl()).build());
					}
				} else {
					ChangeContractFreeformDTO freeformDTO = changeContractUnifyService.buildChangeContractFreeformDTO(contract.getContractCode(), contract.getProjectOrderId(), contract.getChangeOrderId(), true);
					LOGGER.info("previewByCode freeformDTO:{}", freeformDTO);
					//校验合同pdf是否需要更新
					checkChangeContractPdf(freeformDTO);
					ObjectMapper objectMapper = new ObjectMapper();
					Map<String, Object> map = objectMapper.convertValue(freeformDTO, Map.class);
					String pdfUrl = contractBusinessService.generatePdf(contract, map);
					contractUrl.add(FileInfo.builder()
						.type(FileTypeEnum.PDF.getKey())
						.contractType(contract.getType())
						.url(pdfUrl).build());
				}
				ContractSubmitResDTO contractSubmitResDTO = ContractSubmitResDTO.builder()
					.contractCode(contractCode)
					.contractUrl(contractUrl)
					.build();
				previewContractAfter(contractSubmitResDTO, contractPollKey);
				LOGGER.info("异步发起合同预览结束，contractCode:{}，threadId:{}", contractCode, Thread.currentThread().getId());
			} catch (Exception e) {
				LOGGER.info("异步发起合同预览异常，contractCode:{}，threadId:{}", contractCode, Thread.currentThread().getId());
				previewContractException(e, contractPollKey);
			}
		}), contractSubmitExternalExecutor);
		if (contractSubmitSync(contract.getType())) {
			try {
				launchFuture.get();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			} catch (Exception e) {
				Throwable cause = e.getCause();
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), cause == null ? e.getMessage() : cause.getMessage());
			}
		}
		return ContractSubmitResDTO.builder()
			.contractCode(contractCode)
			.contractUrl(contractUrl)
			.estimatedLaunchTime(ContractTypeEnum.getEnumByCode(contract.getType()).getEstimatedLaunchTime())
			.contractResultPollingKey(contractPollKey)
			.build();
	}

