	/**
	 * 保存合同发起结果保存到redis
	 *
	 * @param contractList             发起的合同
	 * @param contractSubmitStatusEnum 发起状态
	 * @param contractPollKey          合同轮询key
	 * @param errorMessage             错误信息
	 */
	public void saveContractSubmitToRedis(List<Contract> contractList, ContractSubmitStatusEnum contractSubmitStatusEnum, String contractPollKey, String errorMessage, boolean retrySubmit) {
		ContractSubmitResDTO contractSubmitResDTO = ContractSubmitResDTO.builder()
			.contractCode(CollectionUtils.isEmpty(contractList) ? null : contractList.get(0).getContractCode())
			.contractUrl(contractList.stream().map(core -> FileInfo.builder()
				.type(FileTypeEnum.PDF.getKey())
				.contractType(core.getType())
				.url(homeAndPcCommonService.getContractUrl(core))
				.build()).collect(Collectors.toList()))
			.build();
		ContractSubmitResult contractSubmitResult = ContractSubmitResult.builder()
			.status(contractSubmitStatusEnum.getCode())
			.errorMessage(errorMessage)
			.contractSubmitResDTO(contractSubmitResDTO)
			.retrySubmit(retrySubmit)
			.build();
		LOGGER.info("合同发起结果：{}", contractSubmitResult);
		stringRedisTemplate.opsForValue().set(contractPollKey, JSON.toJSONString(contractSubmitResult), 10L, TimeUnit.MINUTES);
	}

