	public boolean settlementIsOpen(String projectOrderId) {
		projectOrderId = commonBusinessService.obtainProjectRelationId(projectOrderId);
		boolean v25 = commonBusinessService.isProcessV25New(projectOrderId);
		boolean house = ObjectUtil.equal(BusinessTypeEnum.HOUSE_CERTIFICATE.getCode(), commonBusinessService.getBusinessType(projectOrderId));
