@Deprecated
public ContractSecondaryCheckRes checkPersonalList(String projectOrderId, Byte contractType, List<BillCodeInfo> billCodeInfoList, String contractCode, String changeOrderId) {
	if (!ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
		return ContractSecondaryCheckRes.builder()
			.checkRes(Boolean.TRUE)
			.build();
	}
	//变更场景不校验
	if (StringUtils.isNotBlank(changeOrderId)) {
		return ContractSecondaryCheckRes.builder()
			.checkRes(Boolean.TRUE)
			.build();
	}
	List<String> billCodeList = billCodeInfoList.stream().map(BillCodeInfo::getBillCode).distinct().collect(Collectors.toList());
	ContractSecondaryCheckRes checkRes = ContractSecondaryCheckRes.builder()
		.checkRes(Boolean.TRUE)
		.build();
	if (CollectionUtil.isEmpty(billCodeInfoList)) {
		//校验是否选择了报价单
		checkRes.setCheckRes(Boolean.FALSE);
		return checkRes;
	}
	if (billCodeInfoList.size() > 10) {
		checkRes.setCheckRes(Boolean.FALSE);
		checkRes.setToast("最多选择10个报价单");
		return checkRes;
	}
	List<String> paramBillInfoList = billCodeInfoList.stream().map(item -> item.getBillCode() + '_' + item.getCompanyCode()).collect(Collectors.toList());
	if (StringUtils.isBlank(contractCode)) {
		List<String> relationInfoList = quotationRelationCommonService.getRelationListByBillCodeList(billCodeList)
			.stream().map(item -> item.getBillCode() + '_' + item.getCompanyCode()).collect(Collectors.toList());
		// 发起签约的报价单号已经关联过合同，则拦截
		if (CollectionUtil.isNotEmpty(CollectionUtil.intersection(paramBillInfoList, relationInfoList))) {
			checkRes.setCheckRes(Boolean.FALSE);
			checkRes.setToast("所选报价单已关联合同，请重新选择");
			return checkRes;
		}
	} else {
		//如果是编辑C合同的场景，校验所选报价单是否已经关联了除当前合同外的其他合同
		Contract contract = contractService.getByContractCode(contractCode);
		List<ContractQuotationRelation> relationListByBillCodeList = quotationRelationCommonService.getRelationListByBillCodeList(billCodeList);
		for (ContractQuotationRelation relationInfo : relationListByBillCodeList) {
			String relation = relationInfo.getBillCode() + "_" + relationInfo.getCompanyCode();
			// 如果是编辑合同的场景，当前报价单号已绑定合同 && 绑定的合同不是当前合同 && 当前合同不是变更合同，则拦截。（含义：如果当前合同是变更合同，则允许当前报价单绑定其他合同）
			// StringUtils.isBlank(contract.getChangeOrderId()) 含义：变更发起的销售合同，撤回之后重新编辑时，不校验对应的报价单是否已绑定合同。
			if (paramBillInfoList.contains(relation) && !relationInfo.getContractCode().equals(contractCode) && StringUtils.isBlank(contract.getChangeOrderId())) {
				checkRes.setCheckRes(Boolean.FALSE);
				checkRes.setToast("所选报价单已关联合同，请重新选择");
				return checkRes;
			}
		}
	}
	//校验报价单是否存在
	BudgetParams.QueryBillsCondition budgetParams = BudgetParams.QueryBillsCondition.builder()
		.projectOrderId(projectOrderId)
		.billCodes(billCodeList)
		.build();
	List<com.ke.utopia.atom.api.budget.dto.BudgetBillDTO.BillDTO> billDTOS = atomBudgetRpc.queryBillsByCondition(budgetParams);
	if (CollectionUtil.isEmpty(billDTOS)) {
		checkRes.setCheckRes(Boolean.FALSE);
		checkRes.setToast("所选报价单不存在，请重新选择");
		return checkRes;
	}
	for (com.ke.utopia.atom.api.budget.dto.BudgetBillDTO.BillDTO billDTO : billDTOS) {
		//所选组合单关联报价单状态无法发起签约，请重新选择
		if (GeneralBillStatusEnum.IN_ADJUST.getCode().equals(billDTO.getStatus())
			|| GeneralBillStatusEnum.DELETED.getCode().equals(billDTO.getStatus())
			|| GeneralBillStatusEnum.CANCELED.getCode().equals(billDTO.getStatus())) {
			checkRes.setCheckRes(Boolean.FALSE);
			checkRes.setToast("所选组合单关联报价单状态无法发起签约，请重新选择");
			return checkRes;
		}
	}
	return checkRes;
}

public ContractSecondaryCheckRes checkPersonalListV2(Byte contractType, String contractCode, BindOrderInfoGroup group) {
	// 仅销售合同发起需要校验
	if (!ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
		return ContractSecondaryCheckRes.success();
	}

	LOGGER.info("checkPersonalListV2 入参 contractCode: {}, bindOrderInfoGroup: {}", contractCode, JSON.toJSONString(group));

	// 变更场景不校验
	if (CollectionUtil.isNotEmpty(group.getChangeOrderInfos())) {
		return ContractSecondaryCheckRes.success();
	}

	if (CollectionUtil.isEmpty(group.getBindOrderInfos())) {
		return ContractSecondaryCheckRes.fail("");
	}

	if (StringUtils.isBlank(contractCode)) {
		// 创建合同场景：如果要绑定的单据已绑过合同，则拦截
		if (quotationRelationCommonService.hasBoundOtherPositiveContractInPersonal(group, null)) {
			return ContractSecondaryCheckRes.fail("所选单据已关联合同，请重新选择");
		}
	} else {
		// 编辑合同场景
		Contract contract = contractService.getByContractCode(contractCode);
		// 当编辑普通合同时才校验单据是否已被绑定（变更合同，不校验单据已绑定）
		if (StringUtils.isBlank(contract.getChangeOrderId())
			&& quotationRelationCommonService.hasBoundOtherPositiveContractInPersonal(group, contractCode)) {
			return ContractSecondaryCheckRes.fail("所选单据已关联合同，请重新选择");
		}
	}

	boolean hasInvalidOrders = group.getBindOrderInfos().stream().anyMatch(bindOrderInfo -> contractSigningSourceRouter.route(bindOrderInfo.getBindType()).hasInvalidStatusOrders(bindOrderInfo));
	if (hasInvalidOrders) {
		return ContractSecondaryCheckRes.fail("所选单据状态无法发起签约，请重新选择");
	}

	return ContractSecondaryCheckRes.success();
}

private BindOrderInfoGroup buildSubOrderGroupOfBill(BindOrderInfoGroup group) {
	List<String> billCodes = group.getBillCodeInfos().stream().map(BillCodeInfo::getBillCode).collect(Collectors.toList());
	List<SubOrderInfo> subOrderInfos = new ArrayList<>();
	for (String billCode: billCodes) {
		List<SubOrderBaseInfoDTO> subOrderBaseInfoDTOS = subOrderFeignService.queryValidBaseInfoByHomeOrderNo(group.getProjectOrderId(), billCode, null);
		subOrderInfos.addAll(subOrderBaseInfoDTOS.stream().map(subOrderInfo -> SubOrderInfo.builder().subOrderNo(subOrderInfo.getOrderNo()).companyCode(subOrderInfo.getMdmCode()).build()).collect(Collectors.toList()));
	}
	return BindOrderInfoGroup.convert(group.getProjectOrderId(), subOrderInfos, null, null);
}

@Deprecated
public ContractSecondaryCheckRes checkFormalList(String projectOrderId, Byte contractType, List<BillCodeInfo> billCodeInfoList, String contractCode) {
	//开关处理
	Boolean openFormalMultiple = contractApolloConfig.getOpenFormalMultiple();
	if (!openFormalMultiple) {
		return ContractSecondaryCheckRes.builder()
			.checkRes(Boolean.TRUE)
			.build();
	}
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return ContractSecondaryCheckRes.builder()
			.checkRes(Boolean.TRUE)
			.build();
	}
	if (CollectionUtils.isEmpty(billCodeInfoList)) {
		List<ContractFormalQuotationDTO.FormalSealInfo> formalQuotationList = formalMultipleCompanyService.getFormalQuotationList(projectOrderId);
		if (CollectionUtils.isEmpty(formalQuotationList)) {
			//正签发起，没有可选择的C报价单，返回true，直接进入合同发起页面
			return ContractSecondaryCheckRes.builder()
				.checkRes(Boolean.TRUE)
				.build();
		}
		//正签发起，有可选择的C报价单，返回false，跳弹窗页，选择要发起的C报价单
		return ContractSecondaryCheckRes.builder()
			.checkRes(Boolean.FALSE)
			.build();
	}
	//获取正签报价
	ContractSourceDataBO contractSourceDataBO = homeOrderDataConversionService.contractSourceDateNoThrow(projectOrderId, null);
	PlanAllDTO planAllDTO = contractSourceDataBO.getPlanAllDTO();
	//协同报价单号列表
	List<String> cooperBillCodes = planAllDTO.getCooperBillCodes();
	//正签报价单号
	String billCode = planAllDTO.getBudgetBillDTO().getBillCode();
	//参数中的billCode去除正签报价单号&合并到正签报价的协同报价单号
	LOGGER.info("checkFormalList billCodeInfoList,移除正签报价单前:{}", JSON.toJSONString(billCodeInfoList));
	billCodeInfoList = billCodeInfoList.stream().filter(item -> !billCode.equals(item.getBillCode())).collect(Collectors.toList());
	billCodeInfoList = billCodeInfoList.stream().filter(item -> !cooperBillCodes.contains(item.getBillCode())).collect(Collectors.toList());
	LOGGER.info("checkFormalList billCodeList,移除正签报价单后:{}", JSON.toJSONString(billCodeInfoList));
	if (billCodeInfoList.size() > 10) {
		return ContractSecondaryCheckRes.builder()
			.checkRes(Boolean.FALSE)
			.toast("最多选择10个报价单")
			.build();
	}

	if (CollectionUtil.isNotEmpty(billCodeInfoList)) {
		List<String> billCodeList = billCodeInfoList.stream().map(BillCodeInfo::getBillCode).distinct().collect(Collectors.toList());
		//校验报价单是否存在
		BudgetParams.QueryBillsCondition budgetParams = BudgetParams.QueryBillsCondition.builder()
			.projectOrderId(projectOrderId)
			.billCodes(billCodeList)
			.build();
		List<com.ke.utopia.atom.api.budget.dto.BudgetBillDTO.BillDTO> billDTOS = atomBudgetRpc.queryBillsByCondition(budgetParams);
		if (CollectionUtil.isEmpty(billDTOS)) {
			return ContractSecondaryCheckRes.builder()
				.checkRes(Boolean.FALSE)
				.toast("所选报价单不存在，请重新选择")
				.build();
		}
		for (com.ke.utopia.atom.api.budget.dto.BudgetBillDTO.BillDTO billDTO : billDTOS) {
			//所选组合单关联报价单状态无法发起签约，请重新选择
			if (GeneralBillStatusEnum.IN_ADJUST.getCode().equals(billDTO.getStatus())
				|| GeneralBillStatusEnum.DELETED.getCode().equals(billDTO.getStatus())
				|| GeneralBillStatusEnum.CANCELED.getCode().equals(billDTO.getStatus())) {
				return ContractSecondaryCheckRes.builder()
					.checkRes(Boolean.FALSE)
					.toast("所选组合单关联报价单状态无法发起签约，请重新选择")
					.build();
			}
		}
	}

	//获取主合同所有关联C合同绑定的报价单列表a
	//获取参数传入的报价单列表b
	//用列表b-列表a=报价的列表c
	//获取报价单列表c关联的合同列表，如果列表不为空，则说明选择的报价单已经关联了C合同，无法发起签约
	List<String> a = new ArrayList<>();
	List<String> b = billCodeInfoList.stream().map(item -> item.getBillCode() + "_" + item.getCompanyCode()).collect(Collectors.toList());
	List<String> c = new ArrayList<>();
	if (StringUtils.isNotBlank(contractCode)) {
		List<ContractRelation> relationList = contractRelationService.getRelationList(contractCode);
		if (CollectionUtil.isNotEmpty(relationList)) {
			List<String> relationContractCodeList = relationList.stream().map(ContractRelation::getRelateContractCode)
				.collect(Collectors.toList());
			List<Contract> relationContractList = contractService.getListByContractCodes(relationContractCodeList, false);
			List<Contract> relationPersonalContractList = relationContractList.stream().filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))
				.filter(contract -> ContractStatusEnum.inPositiveStatus.contains(contract.getStatus()))
				.collect(Collectors.toList());
			for (Contract contract : relationPersonalContractList) {
				//查询合同关联的报价单
				List<BillCodeInfo> billCodeInfoListByContractCode = quotationRelationCommonService.getBindOrderInfoGroupByContractCode(contract.getContractCode()).getBillCodeInfos();

				List<String> billCodeInfoStrList = billCodeInfoListByContractCode.stream()
					.map(item -> item.getBillCode() + "_" + item.getCompanyCode())
					.collect(Collectors.toList());
				a.addAll(billCodeInfoStrList);
			}
		}
	}
	LOGGER.info("checkFormalList billCodeList,列表a:{}，列表b:{}", JSON.toJSONString(a), JSON.toJSONString(b));
	//列表b-列表a，剩下的是需要新绑定的
	c = b.stream()
		.filter(e -> !a.contains(e))
		.collect(Collectors.toList());
	LOGGER.info("checkFormalList billCodeList,需要新绑定的报价单列表c:{}", JSON.toJSONString(c));
	if (CollectionUtil.isNotEmpty(c)) {
		//将c转为List<BillCodeInfo>
		List<BillCodeInfo> billCodeInfoListC = c.stream()
			.map(item -> {
				String[] split = item.split("_");
				return BillCodeInfo.builder()
					.billCode(split[0])
					.companyCode(split[1])
					.build();
			})
			.collect(Collectors.toList());
		List<String> billCodeListC = billCodeInfoListC.stream().map(BillCodeInfo::getBillCode).collect(Collectors.toList());
		List<String> relationListByBillCodeList = quotationRelationCommonService.getRelationListByBillCodeList(billCodeListC)
			.stream().map(item -> item.getBillCode() + "_" + item.getCompanyCode()).collect(Collectors.toList());
		//如果有交集，说明所选报价单已经关联了其他合同
		if (CollectionUtil.isNotEmpty(CollectionUtil.intersection(c, relationListByBillCodeList))) {
			LOGGER.info("checkFormalList,所选报价单已关联合同，请重新选择,列表b：{}，列表c：{}，列表c已绑定的合同：{}", JSON.toJSONString(b), JSON.toJSONString(c), JSON.toJSONString(relationListByBillCodeList));
			return ContractSecondaryCheckRes.builder()
				.checkRes(Boolean.FALSE)
				.toast("所选报价单已关联合同,请重新选择")
				.build();
		}
	}
	return ContractSecondaryCheckRes.builder()
		.checkRes(Boolean.TRUE)
		.build();
}

public ContractSecondaryCheckRes checkFormalListV2(Byte contractType, String contractCode, BindOrderInfoGroup group) {
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return ContractSecondaryCheckRes.success();
	}

	if (CollectionUtils.isEmpty(group.getBindOrderInfos())) {
		List<SignableOrderInfoGroup> signableOrderInfos = formalMultipleCompanyService.getFormalQuotationListV2(group.getProjectOrderId());
		if (CollectionUtils.isEmpty(signableOrderInfos)) {
			//正签发起，没有可选择的C报价单，返回true，直接进入合同发起页面
			return ContractSecondaryCheckRes.builder()
				.checkRes(Boolean.TRUE)
				.build();
		}
		//正签发起，有可选择的C报价单，返回false，跳弹窗页，选择要发起的C报价单
		return ContractSecondaryCheckRes.builder()
			.checkRes(Boolean.FALSE)
			.build();
	}

	// 校验绑定单据状态
	boolean hasInvalidStatusOrder = group.getBindOrderInfos().stream().anyMatch(bindOrderInfo -> contractSigningSourceRouter.route(bindOrderInfo.getBindType()).hasInvalidStatusOrders(bindOrderInfo));
	if (hasInvalidStatusOrder) {
		return ContractSecondaryCheckRes.fail("所选组合单关联报价单状态无法发起签约，请重新选择");
	}

	// 正签发起场景，判断报价单是否已被其他合同绑定
	if (quotationRelationCommonService.hasBoundOtherPositiveContractInFormal(group, contractCode))
		return ContractSecondaryCheckRes.fail("所选报价单已关联合同,请重新选择");
	return ContractSecondaryCheckRes.success();
}

public void checkSubsidyOrderWithUserConfirm(ContractReqDTO contractReq) {
	if (!ContractTypeEnum.PERSONAL.getCode().equals(contractReq.getContractBaseInfo().getContractType())) {
		return;
	}
	//主单号
	String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();
	// todo zqy bsu 国补单的功能暂时不做
	List<String> billCodeList = contractReq.getBusinessInfo().getBillCodeInfoList().stream()
		.map(BillCodeInfo::getBillCode)
		.collect(Collectors.toList());
	Byte userSignType = contractReq.getSignInfo().getUserSignType();
	Byte signChannelType = contractReq.getSignInfo().getSignChannelType();
	if (CollectionUtil.isEmpty(billCodeList)) {
		return;
	}
	boolean isSubsidyHomeOrder = subsidyOrderService.isSubsidyHomeOrder(projectOrderId, billCodeList);
	if ((!UserSignTypeEnum.SIGN.getCode().equals(userSignType) || SignChannelTypeEnum.OFFLINE.getCode().equals(signChannelType))
		&& isSubsidyHomeOrder) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "国补银联单签署方式请选择正式签署");
	}
}

public void checkProjectContractModeCode(ContractReqDTO contractReq) {
	// 圣都模式 整装、局装、翻新全案校验工程承包方式不能为2
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	Byte businessType = contractReq.getProjectInfo().getBusinessType();
	Integer gbCode = contractReq.getProjectInfo().getGbCode();
	if (!BusinessTypeEnum.getNonGroupDecorateModeList().contains(businessType) || !ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return;
	}
	MiniPayChannelAppNameEnum miniProgramType = commonBusinessService.getMiniProgramType(gbCode);
	if (!MiniPayChannelAppNameEnum.圣都.getAppName().equals(miniProgramType.getAppName())) {
		return;
	}
	Integer projectContractModeCode = contractReq.getPromiseInfo().getProjectContractModeCode();
	if (ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS.getCode().equals(projectContractModeCode)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前项目承包方式对应税率不支持，请调整后提交");
	}
}

	public ContractCheckNodeRes preSignCheck(Byte contractType, ProjectInfoDTO projectInfo, Boolean allToast, ContractPreCheckBo contractPreCheckBo) {
		LOGGER.info("preSignCheck签前校验开始");
		Byte businessType = commonContractService.getBusinessType(projectInfo);
		//合同没有配置，提示配置合同信息
		String companyCode = projectInfo.getCustomerCommission().getCompanyCode();
		List<ContractCityCompanyInfo> config = contractCityCompanyConfigService.getConfig(projectInfo.getProjectOrderId(), projectInfo.getCustomerHouse().getGbCode(), companyCode, businessType, contractType);
		if (CollectionUtils.isEmpty(config)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, String.format("城市:%s,分公司:%s缺少合同配置", projectInfo.getCustomerHouse().getGbCode(), companyCode));
		}
		//项目信息转换为协同项目单号
		CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectInfo.getProjectOrderId());
		List<Contract> contractList = contractService.getContractList(coordinationProjectOrder.getProjectOrderId());
		// 首期款合同
		// 需要校验是否有正签套餐合同：有进行中/已完成的整装正式套餐合同，无法进行创建
		if (ContractTypeEnum.ADVANCE.getCode().equals(contractType) && contractList.stream().anyMatch(contract -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType()))) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "已有进行中/已完成的整装正式套餐合同，无法进行创建", Level.WARN);
		}
		//整装合同校验是否存在在途结算单
		if (ContractTypeEnum.WHOLE_FUND_LIST.contains(contractType)) {
			//校验是否有在途的结算单：有进行中的整装结算单，请先完成当前结算单再进行创建
			CompletionBillInfoResp completionBillInfoResp = octopusRpc.allowFundChange(projectInfo.getProjectOrderId());
			if (!completionBillInfoResp.getCanChange()) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), completionBillInfoResp.getMessage(), Level.WARN);
			}
		}

		// 补充协议 & 和解协议需要进行签前校验
		if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractType)) {
			supplementCheckList(projectInfo.getProjectOrderId());
		} else if (ContractTypeEnum.SETTLEMENT.getCode().equals(contractType)) {
			settlementCheckList(projectInfo.getProjectOrderId());
		}

		// 翻新全案 & 正签，需要校验预堪任务状态是否已经完成
		if (contractApolloConfig.preSurveyCheckIsOpen(projectInfo.getCustomerHouse().getGbCode()) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
			HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(projectInfo.getProjectOrderId(), Collections.singletonList(HomeModelDefEnum.CONSTRUCTION_PRE_SURVEY.name()));
			Integer preSurveyStatus = Optional.ofNullable(homeProject)
				.map(HomeProject::getMainOrder)
				.map(MainOrder::getConstruction)
				.map(MainOrderModel.Construction::getPreSurveyModule)
				.map(PreSurveyModule::getPreSurveyBaseInfoList)
				.filter(list -> !list.isEmpty())
				.map(list -> list.get(0))
				.map(PreSurveyModule.IPreSurveyBaseInfo::getStatus)
				.orElse(null);
			LOGGER.info("projectOrderId: {}, 预堪任务状态: {}", projectInfo.getProjectOrderId(), preSurveyStatus);
			// 如果预堪任务状态未完成，需要拦截
			if (!PreSurveyStatusEnum.SKIPPED_COMPLETED.getCode().equals(preSurveyStatus) && !PreSurveyStatusEnum.COMPLETED.getCode().equals(preSurveyStatus)) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "请先完成预堪", Level.WARN);
			}
		}

		// 正签套餐合同
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			//校验是否有在途的首期款合同：有进行中的整装首期款合同，请先完成当前合同再进行创建
			if (contractList.stream().anyMatch(contract -> ContractTypeEnum.ADVANCE.getCode().equals(contract.getType()) && ContractStatusEnum.isInProgressStatus(contract.getStatus()))) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "有进行中的硬装首期款合同，请先完成当前合同再进行创建", Level.WARN);
			}
			//正签合同校验装修类型是不是【其他】
			if (CommissionDecorateTypeEnum.OTHERS.getCode().equals(projectInfo.getCustomerCommission().getDecorateType())) {
				throw new NrsBusinessException(ResponseCodeEnum.DECORATE_TYPE_OTHER.getCode(), "装修类型不能为其他");
			}
		}
		//设计合同
		// 需要检验正签合同是否约定设计费：如果约定设计费，则提示
		if (ContractTypeEnum.DESIGN.getCode().equals(contractType)) {
			designContractCheck(contractList);
		}
		List<String> userList = new ArrayList<>();
		// 纯零售项目不校验人员信息
		if (!ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(projectInfo.getDecorateBusinessType())) {
			//人员依赖校验
			ProjectServerParam param = ProjectServerParam.builder().projectOrderId(Long.valueOf(projectInfo.getProjectOrderId())).build();
			List<ProjectServerInfoDTO> projectServerInfoList = shuttleOrderRpc.queryProjectServerInfo(param);
			if (CollectionUtils.isEmpty(projectServerInfoList)) {
				//todo cuiyubao 后续增加
//				throw new NrsBusinessException("项目人员信息为空，请添加相关信息", Level.WARN);
			}
			userList = projectServerInfoList.stream().map(ProjectServerInfoDTO::getType).collect(Collectors.toList());
			//团装单独校验，不走弹窗展示节点信息
			if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
				if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
					boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectInfo.getProjectOrderId());
					homeAndPcCommonService.groupDecorateCheck(config.get(0), userList);
					if (processV25) {
						//团装2.5正签判断B合同报价的是否已生成
						//过滤出B报价单
						List<HomeOrderAttachmentEntity> orderAttachmentEntityList = homeOrderOperationCheckService.queryOrderAttachmentByHomeOrderNo(projectInfo.getProjectOrderId());
						List<HomeOrderAttachmentEntity> formalOrderAttachmentList = orderAttachmentEntityList.stream().filter(item -> Integer.valueOf(item.getAttachmentType()).equals(PlanAttachment.报价单)).collect(Collectors.toList());
						if (CollectionUtil.isNotEmpty(orderAttachmentEntityList) && CollectionUtils.isEmpty(formalOrderAttachmentList)) {
							throw new NrsBusinessException("正签报价单还未生成，无法发起签约", Level.WARN);
						}
					} else {
						if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && !OrderStatusEnum.WAITING_SIGN.getCode().equals(projectInfo.getProjectOrderStatus())) {
							throw new NrsBusinessException("项目还没有报价，请先完成报价", Level.WARN);
						}
						return ContractCheckNodeRes.builder()
							.projectOrderId(coordinationProjectOrder.getProjectOrderId())
							.contractType(contractType)
							.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contractType, businessType))
							.checkNodeList(new ArrayList<>())
							.checkRes(Boolean.TRUE)
							.build();
					}
				}
			} else {
				//需要toast校验设计师
				List<Byte> needCheckDesignerContractTypeToast = new ArrayList<>(Arrays.asList(ContractTypeEnum.PACKAGE_CHANGE.getCode(), ContractTypeEnum.TERMINAL.getCode(), ContractTypeEnum.DRAWING.getCode(),
					ContractTypeEnum.DESIGN_CHANGE.getCode()));
				if (needCheckDesignerContractTypeToast.contains(contractType) && !userList.contains(ServerTypeEnum.DESIGNER.getType())) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请先完成设计师分配");
				}
			}
		}

		/**
		 * 签前校验：展示校验节点状态和展示信息
		 */
		ContractCheckNodeRes checkNodeRes = preSignCheckShowNode(contractType, projectInfo, userList, contractPreCheckBo.getChangeOrderId(), businessType, contractPreCheckBo, coordinationProjectOrder);
		List<Node> unCompleteNodeList = checkNodeRes.getCheckNodeList().stream().filter(node -> ConfigStatusEnum.TO_COMPLETE.getCode().equals(node.getStatus())).collect(Collectors.toList());
		if (Boolean.TRUE.equals(allToast) && !CollectionUtils.isEmpty(unCompleteNodeList)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请先" + unCompleteNodeList.get(0).getNodeDesc());
		}
		LOGGER.info("preSignCheck签前校验结束");
		return checkNodeRes;
	}

