	Map<String, NodeFillInfo> preSignCheckSecondNodeFillInfo = new HashMap<>();
	preSignCheckSecondNodeFillInfo.put(PreSignCheckSubNode.RETAIL_CONTRACT_AMOUNT_AND_RATIO_ONE.getSecondNodeKey(), new NodeFillInfo());
	preSignCheckSecondNodeFillInfo.put(PreSignCheckSubNode.RETAIL_CONTRACT_AMOUNT_RATIO_ONE.getSecondNodeKey(), new NodeFillInfo());
	preSignCheckSecondNodeFillInfo.put(PreSignCheckSubNode.SUM_OF_REFORM_AND_RETAIL_CONTRACT_AMOUNT_ONE.getSecondNodeKey(), new NodeFillInfo());
	preSignCheckSecondNodeFillInfo.put(PreSignCheckSubNode.RETAIL_CONTRACT_AMOUNT_AND_RATIO_TWO.getSecondNodeKey(), new NodeFillInfo());
	preSignCheckSecondNodeFillInfo.put(PreSignCheckSubNode.RETAIL_CONTRACT_AMOUNT_RATIO_TWO.getSecondNodeKey(), new NodeFillInfo());
	preSignCheckSecondNodeFillInfo.put(PreSignCheckSubNode.SUM_OF_REFORM_AND_RETAIL_CONTRACT_AMOUNT_TWO.getSecondNodeKey(), new NodeFillInfo());
	return preSignCheckSecondNodeFillInfo;
}

