private NodeFillInfo checkRetailContractAmountExceedingConfiguredRatio(BigDecimal retailAmountRatio, BigDecimal planContractAmount, BigDecimal orderAmount) {
	NodeFillInfo nodeFillInfo = new NodeFillInfo();
	nodeFillInfo.setStatus(Boolean.FALSE);
	nodeFillInfo.setRetailContractAmount(orderAmount);
	nodeFillInfo.setContractTotalAmount(planContractAmount.add(orderAmount));
	nodeFillInfo.setRetailContractAmountRatio(nodeFillInfo.getRetailContractAmount().multiply(new BigDecimal(100)).divide(nodeFillInfo.getContractTotalAmount(), 2, RoundingMode.DOWN));
	if (orderAmount.multiply(new BigDecimal(100)).compareTo((planContractAmount.add(orderAmount)).multiply(retailAmountRatio)) >= 0) {
		nodeFillInfo.setStatus(Boolean.TRUE);
	}
	LOGGER.info("checkRetailContractAmountExceedingConfiguredRatio nodeFillInfo:{}", JSON.toJSONString(nodeFillInfo));
	return nodeFillInfo;
}

