public void saveAndSubmitPreCheck(String projectOrderId, Byte contractType, ContractReqDTO contractReq) {
	//装修类型变换不影响C合同
	if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
		return;
	}
	//装修类型businessType发生变化:则需要删除合同中的字段&给用户toast提示&前端回到合同列表页
	Contract draftContract = contractService.getLatestContractByStatus(projectOrderId, contractType, Collections.singletonList(ContractStatusEnum.DRAFT.getCode()));
	//如果合同不存在则直接返回
	if (draftContract == null) {
		return;
	}
	//前端传用户看到的businessType和数据库里存的不一致，刷新页面
	if (!draftContract.getBusinessType().equals(contractReq.getProjectInfo().getBusinessType()) && !ContractTypeEnum.getPersonalizedRelevantContractList().contains(contractType)) {
		throw new NrsBusinessException(ResponseCodeEnum.DECORATE_TYPE_CHANGE_REFRESH.getCode(), ResponseCodeEnum.DECORATE_TYPE_CHANGE_REFRESH.getMsg(), Level.WARN);
	}
	//数据库里存的businessType和客源的不一致，清空字段，回到合同列表页
	if (Boolean.TRUE.equals(businessTypeChangeDeleteField(draftContract))) {
		throw new NrsBusinessException(ResponseCodeEnum.DECORATE_TYPE_CHANGE_TOAST.getCode(), "检测到您的装修类型发生变化，不再适用当前模板，正在退出以便您重新发起正确合同", Level.WARN);
	}
}

public void checkPersonalContractStatus(ContractReqDTO contractReq) {
	if (!ContractTypeEnum.PERSONAL.getCode().equals(contractReq.getContractBaseInfo().getContractType())) {
		return;
	}
	BindOrderInfoGroup group = BindOrderInfoGroup.convert(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getBusinessInfo());
	List<BindOrderInfo> bindOrderInfos = group.getBindOrderInfos();
	if (CollectionUtil.isEmpty(bindOrderInfos)) {
		return;
	}
	checkStatus(BillCodeInfo.groupByCompanyCode(group.getBillCodeInfos()), BindTypeEnum.BILL_CODE.getCode());
	checkStatus(SubOrderInfo.groupByCompanyCode(group.getSubOrderInfos()), BindTypeEnum.SUB_ORDER.getCode());
	checkStatus(ChangeOrderInfo.groupByCompanyCode(group.getChangeOrderInfos()), BindTypeEnum.CHANGE_ORDER.getCode());
}

private void checkStatus(Map<String, List<String>> bindCodesByCompanyCode, Integer bindType) {
	bindCodesByCompanyCode.forEach((companyCode, bindCodes) -> {
		Contract contract = quotationRelationCommonService.getUniqueContractByBindCodes(bindCodes, companyCode, bindType);
		if (ObjectUtil.isNotEmpty(contract) && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "合同状态不为草稿中，不允许保存合同草稿，请刷新页面后重试", Level.WARN);
		}
	});
}

public void comboTypePreCheck(ContractReqDTO contractReq) {
	String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	Contract draftContract = contractService.getLatestContractByStatus(projectOrderId, contractType, Collections.singletonList(ContractStatusEnum.DRAFT.getCode()));
	//如果合同不存在则直接返回
	if (draftContract == null) {
		return;
	}
	//合同类型为整装且套餐类型为局改，阻断后续流程但是保存草稿信息
	if (Boolean.TRUE.equals(comboTypeChangeCheck(draftContract))) {
		//保存草稿信息并报错提示
		((ContractUnifyService) AopContext.currentProxy()).saveDraftContract(contractReq);
		throw new NrsBusinessException(ResponseCodeEnum.COMBO_TYPE_NOT_MATCH_TOAST.getCode(), ResponseCodeEnum.COMBO_TYPE_NOT_MATCH_TOAST.getMsg(), Level.WARN);
	}
}

public void checkCompanySignMultipleCompany(ContractReqDTO contractReq) {
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	Byte signChannelType = contractReq.getSignInfo().getSignChannelType();
	Byte contractObjectType = contractReq.getSignInfo().getContractObjectType();
	List<Byte> checkContractTypeList = Collections.singletonList(ContractTypeEnum.PACKAGE_FORMAL.getCode());
	if (!checkContractTypeList.contains(contractType)) {
		return;
	}
	if (!ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
		return;
	}
	if (!SignChannelTypeEnum.ONLINE.getCode().equals(signChannelType)) {
		return;
	}
	ContractSourceDataBO contractSourceDataBO = ContractContextHandler.getContractSourceDataBO();
	if (contractSourceDataBO == null || CollectionUtils.isEmpty(contractSourceDataBO.getPersonalContractDataList()) || contractSourceDataBO.getPlanAllDTO() == null) {
		return;
	}
	List<String> organizationCodeList = Optional.of(contractSourceDataBO.getPersonalContractDataList())
		.orElse(Collections.emptyList())
		.stream()
		.map(ContractSourceDataBO.PersonalContractData::getOrganizationCode)
		.filter(Objects::nonNull)
		.collect(Collectors.toList());
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		//正签分公司code
		String organizationCode = contractSourceDataBO.getPlanAllDTO().getPlanInfo().getOrganizationCode();
		organizationCodeList.add(organizationCode);
	}
	organizationCodeList = organizationCodeList.stream().distinct().collect(Collectors.toList());
	if (organizationCodeList.size() > 1) {
		throw new NrsBusinessException("当前发起下存在多个分公司签约主体，请重新选择分公司签约主体", Level.WARN);
	}
}

public Boolean comboTypeChangeCheck(Contract draftContract) {
	//只有正签合同需要校验
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(draftContract.getType()) || !BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(draftContract.getBusinessType())) {
		return false;
	}
	//从上下文中获取报价信息
	PlanAllDTO planAllDTO = ContractContextHandler.getPlanAllDTO();
	if (Objects.isNull(planAllDTO) || Objects.isNull(planAllDTO.getPlanInfo()) || Objects.isNull(planAllDTO.getPlanInfo().getComboCode())) {
		throw new NrsBusinessException("报价套餐信息不存在-[签约]");
	}
	Integer organizationMode = commonBusinessService.isPROCESS_V2_5(draftContract.getProjectOrderId(), draftContract.getType()) ? OrganizationModeEnum.模式25.getMode() : null;
	//查询报价套餐信息
	ComboBaseDTO packageByCombCode = quotationFeignService.getPackageByCombCode(planAllDTO.getPlanInfo().getComboCode(), organizationMode);
	return BusinessTypeEnum.getHouseCertificate25ModeList().contains(draftContract.getBusinessType()) && Constant.PART_COMBO_TYPE.equals(packageByCombCode.getComboCategoryCode());
}

public List<ModuleInfoDTO> fieldDelivery(FieldDeliveryReq fieldDeliveryReq) {
	//根据项目单号和合同获取项目信息
	ContractCreateBaseInfo canCreateContract = commonBusinessService.getCanCreateContract(fieldDeliveryReq.getProjectOrderId(), fieldDeliveryReq.getContractType(), null);
	fieldDeliveryReq.setProjectOrderId(canCreateContract.getProjectOrderId());
	//适配项目信息(查询项目信息需要准确查询整装、纯零售)
	String projectRelationId = commonBusinessService.obtainProjectRelationId(canCreateContract.getProjectOrderId());
	ProjectOrganizationDTO projectInfo = projectReadService.getProjectOrganizationByProjectOrderId(projectRelationId);
	Byte businessType = commonBusinessService.getBusinessType(canCreateContract.getProjectOrderId());
	Integer gbCode = projectInfo.getGbCode();
	String companyCode = projectInfo.getCompanyCode();
	companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(fieldDeliveryReq.getProjectOrderId(), gbCode, companyCode, fieldDeliveryReq.getContractType());
	//查询版本需要根据合同类型区分整装和零售项目单号
	String convertProjectOrderId = commonBusinessService.convertProjectOrderId(fieldDeliveryReq.getProjectOrderId(), fieldDeliveryReq.getContractType());
	ContractVersionConfig contractConfigAllVersion = contractConfigVersionService.getContractConfigAllVersion(convertProjectOrderId);
	//模块配置信息
	List<ContractModuleConfig> moduleConfigs = getModuleConfigAdapt(gbCode, companyCode, businessType, fieldDeliveryReq.getContractType(), contractConfigAllVersion.getModuleConfigVersion());
	//字段配置信息
	List<ContractFieldConfig> fieldConfigs = getFieldConfigAdapt(fieldDeliveryReq.getProjectOrderId(), gbCode, companyCode, businessType, fieldDeliveryReq.getContractType(), contractConfigAllVersion.getFieldConfigVersion());
	// 将后端数据转换为前端展示配置
	Map<String, List<ContractFieldConfig>> fieldConfigMap = fieldConfigs.stream()
		.collect(Collectors.groupingBy(ContractFieldConfig::getModuleKey));
	List<ModuleInfoDTO> moduleInfoDTOS = new ArrayList<>();
	String projectOrderId = fieldDeliveryReq.getProjectOrderId();
	boolean attachOcrOpenCity = attachCommonService.attachOcrOpenCity(projectOrderId);
	for (ContractModuleConfig moduleConfig : moduleConfigs) {
		//前端传了step && 当前模块配置和step不相等，则跳过当前模块
		if (fieldDeliveryReq.getStep() != null && !fieldDeliveryReq.getStep().equals(moduleConfig.getStep())) {
			continue;
		}
		if (attachOcrOpenCity && ContractModuleEnum.CONTRACT_ATTACH_INFO.getKey().equals(moduleConfig.getModuleKey())) {
			continue;
		}
		// 如果补充协议未开城，则不下发 supplementItemInfo 模块
		if (ContractReqDTO.Fields.supplementItemInfo.equals(moduleConfig.getModuleKey()) && !supplementIsOpen(projectOrderId)) {
			continue;
		}
		// 设计费报价未开城：被窝不下发优惠模块，圣都不下发优惠前金额字段
		if ((MiniPayChannelAppNameEnum.被窝.equals(commonBusinessService.getMiniProgramType(projectOrderId)) && !designFeeFromQuote(projectOrderId))
			&& ContractModuleEnum.PROMISE_INFO.getKey().equals(moduleConfig.getModuleKey())
			&& ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(fieldDeliveryReq.getContractType())) {
			continue;
		}

		ModuleInfoDTO moduleInfoDTO = ModuleInfoDTO.builder()
			.description(moduleConfig.getDescription())
			.tips(moduleConfig.getTips())
			.step(moduleConfig.getStep())
			//下面需要转换给前端
			.event(StringUtils.isBlank(moduleConfig.getEvent()) ? null : JsonUtil.toObject(moduleConfig.getEvent(), Event.class))
			.dataIndex(moduleConfig.getModuleKey())
			.formLabel(moduleConfig.getModuleName())
			.disabled(DisabledEnum.getBoolStatusByCode(moduleConfig.getDisabled()))
			.children(convertToFieldDTO(fieldConfigMap.get(moduleConfig.getModuleKey()), fieldDeliveryReq, companyCode, moduleConfig.getModuleKey(), attachOcrOpenCity, businessType, gbCode, fieldDeliveryReq.getContractType(), projectOrderId))
			.build();
		//如果模块下没有字段，则不返回
		if (CollectionUtils.isEmpty(moduleInfoDTO.getChildren())) {
			continue;
		}

		moduleInfoDTOS.add(moduleInfoDTO);
	}
	return moduleInfoDTOS;
}

