public List<String> mergeLaunchSaveContract(ContractReqDTO contractReq, List<Byte> mergeLaunchTypeList) {
	List<String> relationContractCodeList = new ArrayList<>();
	if (!mergeLaunchTypeList.isEmpty()) {
		//设置合并发起标识
		ContractContextHandler.getContext().setMergeLaunch(true);
	}
	//与当前合同合并一起发起的合同数据保存
	List<ContractReqDTO> contractReqTempList = new ArrayList<>();
	List<ContractReqDTO> personalContractReqTempList = new ArrayList<>();
	for (Byte contractType : mergeLaunchTypeList) {
		ContractReqDTO contractReqTemp = CommonUtil.deepCopy(contractReq, ContractReqDTO.class);
		contractReqTemp.getContractBaseInfo().setContractType(contractType);
		if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.TERMINAL.getCode())) {
			contractReqTemp = commonContractService.buildMergeTerminalContractReq(contractReqTemp);
		}
		// 构建合并发起补充协议参数
		if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.SUPPLEMENT.getCode())) {
			contractReqTemp = commonContractService.buildMergeSupplementContractReq(contractReqTemp);
		}
		if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.DRAWING.getCode())) {
			contractReqTemp.getSignInfo().setAttachUrl(contractReq.getSignInfo().getDrawingAttachUrl());
		}
		if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.DESIGN.getCode())) {
			contractReqTemp = commonContractService.buildMergeDesignContractReq(contractReqTemp);
		}
		if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.PERSONAL.getCode())) {
			personalContractReqTempList = buildPersonalContractReqList(contractReq);
		}
		if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			contractReqTempList.addAll(personalContractReqTempList);
		} else {
			contractReqTempList.add(contractReqTemp);
		}
	}

	for (ContractReqDTO contractReqDTOTemp : contractReqTempList) {
		Contract contractTemp = buildDraftContract(contractReqDTOTemp);
		saveCoreContractDb(contractTemp, contractReqDTOTemp);
		relationContractCodeList.add(contractTemp.getContractCode());
		BindOrderInfoGroup group = BindOrderInfoGroup.convert(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getBusinessInfo());
		quotationRelationCommonService.bindCodeRelationWithClear(contractTemp, group);
	}
	return relationContractCodeList;
}

public List<ContractReqDTO> buildPersonalContractReqList(ContractReqDTO sourceContractReq) {
	List<ContractReqDTO> personalContractReqTempListResult = new ArrayList<>();
	//构建需要生成的合同个数
	List<ContractSourceDataBO.PersonalContractData> personalContractDataList = ContractContextHandler.getContext().getContractSourceDataBO().getPersonalContractDataList();
	//按主体分组
	Map<String, List<ContractSourceDataBO.PersonalContractData>> personalContractDataMap = personalContractDataList.stream()
		.collect(Collectors.groupingBy(ContractSourceDataBO.PersonalContractData::getOrganizationCode));

	/**
	 * 正签合并发起场景，数据域会将基础报价单 + S 单对应的数据都放入到 List<ContractSourceDataBO.PersonalContractData>
	 * 按照主体分组后，同一主体下的 PersonalContractData 既可能是报价单的，也可能是 S 单，所以在 convert BindOrderInfo 时，不能以优先级 convert
	 */
	personalContractDataMap.forEach((organizationCode, personalContractDataListByOrg) -> {
		ContractReqDTO personalContractReqTemp = CommonUtil.deepCopy(sourceContractReq, ContractReqDTO.class);
		personalContractReqTemp.getContractBaseInfo().setContractType(ContractTypeEnum.PERSONAL.getCode());
		personalContractReqTemp.getSignInfo().setAttachUrl(sourceContractReq.getSignInfo().getPersonalAttachUrl());
		personalContractReqTemp.getSignInfo().setUserSignTime(sourceContractReq.getSignInfo().getPersonalUserSignTime());
		personalContractReqTemp.getSignInfo().setCompanySignTime(sourceContractReq.getSignInfo().getPersonalUserSignTime());
		personalContractReqTemp.getContractBaseInfo().setSubmitCompanyCode(organizationCode);
		BindOrderInfoGroup group = BindOrderInfo.convert(sourceContractReq.getContractBaseInfo().getProjectOrderId(), personalContractDataListByOrg);
		personalContractReqTemp.getBusinessInfo().setBillCodeList(group.getBillCodeInfos().stream().map(BillCodeInfo::getBillCode).collect(Collectors.toList()));
		personalContractReqTemp.getBusinessInfo().setBillCodeInfoList(group.getBillCodeInfos());
		personalContractReqTemp.getBusinessInfo().setSubOrderInfoList(group.getSubOrderInfos());
		personalContractReqTemp.getBusinessInfo().setChangeOrderInfoList(group.getChangeOrderInfos());
		// 构造商品信息
		List<BindOrderInfo> bindOrderInfos = group.getBindOrderInfos();
		Map<String, String> goodsInfoByOrderNo = bindOrderInfos.stream()
			.map(bindOrderInfo -> contractSigningSourceRouter.route(bindOrderInfo.getBindType()).buildGoodsInfo(bindOrderInfo))
			.flatMap(map -> map.entrySet().stream())
			.collect(Collectors.toMap(
				Map.Entry::getKey,
				Map.Entry::getValue,
				(v1, v2) -> v2
			));

		personalContractReqTemp.getBusinessInfo().setGoodsInfo(String.join(",", goodsInfoByOrderNo.values()));

		personalContractReqTempListResult.add(personalContractReqTemp);
	});
	return personalContractReqTempListResult;
}

