public ContractDetailResp detail(ContractDetailReq req, Byte contractType) {
	String contractCode = req.getContractCode();
	String projectOrderId = req.getProjectOrderId();
	Boolean isDetail = req.getIsDetail();
	Boolean isFirstScreen = req.getIsFirstScreen();
	List<BillCodeInfo> billCodeInfoList = req.getBillCodeInfoList();
	String changeOrderId = req.getChangeOrderId();
	List<SubOrderInfo> subOrderInfoList = req.getSubOrderInfoList();
	List<ChangeOrderInfo> changeOrderInfoList = req.getChangeOrderInfoList();
	Contract contract = null;
	if (StringUtils.isNotBlank(contractCode)) {
		contract = contractService.getByContractCode(contractCode);
		if (contract == null) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "合同不存在，请检查合同编号或联系客服", Level.WARN);
		}
	}
	BindOrderInfoGroup group = BindOrderInfoGroup.convert(projectOrderId, subOrderInfoList, billCodeInfoList, changeOrderInfoList);
	/**
	 * 兼容逻辑：正签特殊场景，前端无法传入，需要兼容前端未传入的场景
	 */
	group = buildGroupFromPackageContractField(projectOrderId, contractCode, contractType, group, isDetail);

	subOrderInfoList = group.getSubOrderInfos();
	changeOrderInfoList = group.getChangeOrderInfos();
	billCodeInfoList = group.getBillCodeInfos();

	if (!isFirstScreen && contractApolloConfig.getCheckPersonalContract() && ContractTypeEnum.PERSONAL.getCode().equals(contractType) && CollectionUtils.isEmpty(group.getBindOrderInfos())) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "个性化合同必须传入报价单列表", Level.WARN);
	}
	if (contract == null) {
		if (!ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			//如果没有合同code，查询草稿状态的合同
			contract = contractService.getContractList(projectOrderId, contractType).stream()
				.filter(item -> ContractStatusEnum.DRAFT.getCode().equals(item.getStatus())).findFirst().orElse(null);
		}
	}

	ContractDetailResp detail = null;
	//如果是重签的合同并且当前没有合同草稿，带入上份合同信息
	if (contract == null) {
		detail = reSignFieldInfoFill(projectOrderId, contractType, isFirstScreen, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
	}

	// 如果没有上一份合同信息，则初始化合同详情信息
	if (detail == null) {
		changeOrderId = contract != null ? contract.getChangeOrderId() : changeOrderId;
		detail = contractUnifyServiceSelf.baseDetail(contract, projectOrderId, contractType, changeOrderId, isFirstScreen, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
	}
	ContractSignInfoDetail signInfo = detail.getSignInfo();
	if (!isDetail) {
		//不是详情页，不加密，进行对字段数据进行解密
		Map<String, String> decryptMap = cipherService.decrypt(
			Stream.of(
					signInfo.getOwnerCertificateNo(),
					signInfo.getAgentCertificateNo(),
					signInfo.getCompanyAgentCertificateNo(),
					signInfo.getLegalCertificateNo())
				.filter(StringUtils::isNotBlank)
				.distinct()
				.collect(Collectors.toList())
		);

		signInfo.setOwnerCertificateNo(decryptMap.getOrDefault(signInfo.getOwnerCertificateNo(), signInfo.getOwnerCertificateNo()));
		signInfo.setAgentCertificateNo(decryptMap.getOrDefault(signInfo.getAgentCertificateNo(), signInfo.getAgentCertificateNo()));
		signInfo.setCompanyAgentCertificateNo(decryptMap.getOrDefault(signInfo.getCompanyAgentCertificateNo(), signInfo.getCompanyAgentCertificateNo()));
		signInfo.setLegalCertificateNo(decryptMap.getOrDefault(signInfo.getLegalCertificateNo(), signInfo.getLegalCertificateNo()));
		detail.getContractBaseInfo().setIsDetail(Boolean.FALSE);
	}
	signInfo.setOwnerPhone(cipherService.encrypt(signInfo.getOwnerPhone()));
	signInfo.setAgentPhone(cipherService.encrypt(signInfo.getAgentPhone()));
	signInfo.setCompanyAgentPhone(cipherService.encrypt(signInfo.getCompanyAgentPhone()));
	signInfo.setSignatoryPhone(cipherService.encrypt(signInfo.getSignatoryPhone()));
	signInfo.setLegalPhone(cipherService.encrypt(signInfo.getLegalPhone()));
	detail.getSignInfo().setCustomerPhoneVoList(contractDetailService.getCustomerPhoneVoList(detail.getSignInfo(), isDetail));
	return detail;
}

private ContractDetailResp reSignFieldInfoFill(String projectOrderId, Byte contractType, boolean isFirstScreen, List<BillCodeInfo> billCodeInfoList, List<SubOrderInfo> subOrderInfoList, List<ChangeOrderInfo> changeOrderInfoList) {
	boolean allowedFillHistoryContractInfo = ContractTypeEnum.allowedFillHistoryContractInfo(contractType);
	if (!allowedFillHistoryContractInfo) {
		return null;
	}

	Contract latestContract = contractService.getLatestContract(projectOrderId, contractType);
	if (latestContract == null) {
		return null;
	}
	ContractDetailResp contractDetailResp = contractUnifyServiceSelf.baseDetail(latestContract, latestContract.getProjectOrderId(), latestContract.getType(), null, isFirstScreen, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
	if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
		//C合同重签不带入合同url相关的信息
		ContractSignInfoDetail signInfo = contractDetailResp.getSignInfo();
		signInfo.setAttachUrl(null);
		signInfo.setPersonalAttachUrl(null);
		signInfo.setUserSignTime(null);
		signInfo.setCompanySignTime(null);
		signInfo.setPersonalCompanySignTime(null);
		signInfo.setPersonalUserSignTime(null);
		// C 合同不下发上一份的 contractCode
		ContractBaseInfoDetail contractBaseInfo = contractDetailResp.getContractBaseInfo();
		contractBaseInfo.setContractCode(null);
	}
	return contractDetailResp;
}

private BindOrderInfoGroup buildGroupFromPackageContractField(String projectOrderId, String contractCode, Byte contractType, BindOrderInfoGroup group, Boolean isDetail) {
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) || Boolean.FALSE.equals(isDetail) || StringUtils.isBlank(contractCode)) {
		return group;
	}
	ContractField subOrderInfoListField = contractFieldService.getByContractCodeAndKey(contractCode, "subOrderInfoList");
	ContractField billCodeInfoListField = contractFieldService.getByContractCodeAndKey(contractCode, "billCodeInfoList");
	ContractField changeOrderInfoListField = contractFieldService.getByContractCodeAndKey(contractCode, "changeOrderInfoList");
	return BindOrderInfoGroup.convert(projectOrderId, subOrderInfoListField, billCodeInfoListField, changeOrderInfoListField);
}

@ContractDetailDataPrepare
public ContractDetailResp baseDetail(Contract contract, String projectOrderId, Byte contractType, String changeOrderId, Boolean isFirstScreen, List<BillCodeInfo> billCodeInfoList, List<SubOrderInfo> subOrderInfoList, List<ChangeOrderInfo> changeOrderInfoList) {
	//从核心域中获取billCodeInfoList
	List<String> moduleKeyList = getModuleInfo(projectOrderId,
		contractType, null, null).stream().map(ContractModuleAndFieldInfoDTO::getModuleKey).collect(Collectors.toList());
	//合同不存在，返回初始化数据
	if (contract == null) {
		return contractDetailService.initContractDetail(projectOrderId, contractType, moduleKeyList, changeOrderId, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
	}
	projectOrderId = contract.getProjectOrderId();
	contractType = contract.getType();
	//合同字段信息
	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contract.getContractCode());
	Map<String, String> fieldMap = Maps.newHashMap();
	contractFieldList.forEach(contractField -> fieldMap.put(contractField.getFieldKey(), contractField.getFieldValue()));
	List<ContractAttach> contractAttachList = contractAttachService.getListByContractCode(contract.getContractCode());

	//首屏只加载signInfo、contractBaseInfo、businessInfo、projectInfo4个对象，且涉及中控的字段不保证准确性
	if (isFirstScreen) {
		//项目信息 houseType使用中控接口，首屏不保证准确
		ContractProjectInfoDetail projectInfoDetail = contractDetailService.buildContractProjectInfoDetail(contract, contractType, projectOrderId, fieldMap);
		//合同基础信息  havePersonalQuote、contractMode使用中控接口，首屏不保证准确
		ContractBaseInfoDetail baseInfoDetail = contractDetailService.buildContractBaseInfoDetail(contract, projectOrderId, contractType, changeOrderId, fieldMap, false);
		//合同签约信息 salesCompanyName 使用中控接口，首屏不保证准确
		ContractSignInfoDetail signInfoDetail = contractDetailService.buildContractSignInfoDetail(contract, contractType, projectInfoDetail, fieldMap, contractAttachList, changeOrderId);
		//合同附件信息
		ContractAttachInfoDetail contractAttachInfo = contractDetailService.buildContractAttachInfo(moduleKeyList, contract, contractAttachList, signInfoDetail, fieldMap, projectOrderId, contractType);
		//合并附件信息到签约信息
		contractDetailService.mergeContractAttachInfoTOSignInfo(projectOrderId, contractType, contractAttachInfo, signInfoDetail);
		//业务信息 billCodeList 使用中控接口，首屏不保证准确
		BusinessInfoDetail businessInfo = contractDetailService.buildBusinessInfoDetail(contract, projectInfoDetail, fieldMap, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
		// 补充协议信息
		SupplementItemInfo supplementItemInfo = contractDetailService.buildSupplementItemInfo(contract, fieldMap);
		return ContractDetailResp.builder().signInfo(signInfoDetail).contractBaseInfo(baseInfoDetail)
			.businessInfo(businessInfo).projectInfo(projectInfoDetail).supplementItemInfo(supplementItemInfo).build();
	}

	ContractProjectInfoDetail projectInfoDetail = contractDetailService.buildContractProjectInfoDetail(contract, contractType, projectOrderId, fieldMap);
	//合同基础信息
	ContractBaseInfoDetail baseInfoDetail = contractDetailService.buildContractBaseInfoDetail(contract, projectOrderId, contractType, changeOrderId, fieldMap, false);
	//合同签约信息
	ContractSignInfoDetail signInfoDetail = contractDetailService.buildContractSignInfoDetail(contract, contractType, projectInfoDetail, fieldMap, contractAttachList, changeOrderId);

	//承包约定
	PromiseInfoDetail promiseInfoDetail = contractDetailService.buildPromiseInfoDetail(contract, fieldMap, projectOrderId, contractType);
	//保修信息
	GuaranteeDetail guaranteeDetail = contractDetailService.buildGuaranteeDetail(moduleKeyList, fieldMap);
	//优惠信息
	ActivityInfo activityInfo = contractDetailService.buildActivityInfoDetail(moduleKeyList, projectOrderId, changeOrderId);
	//报价信息
	QuotationInfo quotationInfo = contractDetailService.buildQuotationDetail(moduleKeyList, projectOrderId, changeOrderId, projectInfoDetail.getBusinessType(), contractType, fieldMap);
	//图纸信息
	DrawingInfo drawing = contractDetailService.buildDrawingDetail(moduleKeyList, changeOrderId, contractType);
	//收款计划信息
	CollectionPlanConfigInfo collectionPlanConfigInfo = contractDetailService.buildCollectionPlanConfigInfo(moduleKeyList, contract, changeOrderId);
	//合同附件信息
	ContractAttachInfoDetail contractAttachInfo = contractDetailService.buildContractAttachInfo(moduleKeyList, contract, contractAttachList, signInfoDetail, fieldMap, projectOrderId, contractType);
	//个性化报价
	PersonalQuotation personalQuotation = contractDetailService.buildPersonalQuotationDetail(contract, moduleKeyList, quotationInfo, contractType, fieldMap);
	//业务信息
	BusinessInfoDetail businessInfo = contractDetailService.buildBusinessInfoDetail(contract, projectInfoDetail, fieldMap, billCodeInfoList, subOrderInfoList, changeOrderInfoList);
	//金额信息
	AmountInfo amountInfo = contractDetailService.buildAmountInfoDetail(fieldMap);
	// 流程信息
	ProcessInfo processInfo = contractDetailService.buildProcessInfoDetail(contract);
	// 定软电收款计划
	PersonalCollectionPlanInfo personalCollectionPlanInfo = contractDetailService.buildPersonalCollectionPlanInfo(moduleKeyList);
	// 备件ocr开城将备件信息返回到签约信息模块
	contractDetailService.mergeContractAttachInfoTOSignInfo(projectOrderId, contractType, contractAttachInfo, signInfoDetail);
	// 补充协议信息
	SupplementItemInfo supplementItemInfo = contractDetailService.buildSupplementItemInfo(contract, fieldMap);
	// 和解协议信息
	SettlementItemInfo settlementItemInfo = contractDetailService.buildSettlementItemInfo(contract, fieldMap);
	return ContractDetailResp.builder()
		.businessInfo(businessInfo)
		.contractBaseInfo(baseInfoDetail)
		.projectInfo(projectInfoDetail)
		.signInfo(signInfoDetail)
		.promiseInfo(promiseInfoDetail)
		.guaranteeInfo(guaranteeDetail)
		.activityInfo(activityInfo)
		.quotation(quotationInfo)
		.drawing(drawing)
		.contractPrice(quotationInfo == null ? null : ContractPrice.builder().contractPriceTotal(quotationInfo.getContractPrice()).build())
		.collectionPlanConfigInfo(collectionPlanConfigInfo)
		.contractAttachInfo(contractAttachInfo)
		.personalQuotation(personalQuotation)
		.amountInfo(amountInfo)
		.processInfo(processInfo)
		.personalCollectionPlanInfo(personalCollectionPlanInfo)
		.supplementItemInfo(supplementItemInfo)
		.settlementItemInfo(settlementItemInfo)
		.build();
}

public List<ContractCityCompanyInfo> getCityCompanyInfos(String projectOrderId, Byte contractType) {
	ProjectInfo projectInfo = projectInfoService.getByProjectOrderId(projectOrderId);
	if (projectInfo == null) {
		throw new NrsBusinessException("当前项目缺少分公司信息");
	}

	Integer gbCode = projectInfo.getGbcode();
	String companyCode = projectInfo.getCompanyCode();
	Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
	List<ContractCityCompanyInfo> config = contractCityCompanyConfigService.getConfig(
		projectOrderId,
		gbCode,
		companyCode,
		businessType,
		contractType
	);
	if (CollectionUtils.isEmpty(config)) {
		String errorMsg = String.format("城市:%s,分公司:%s缺少合同配置", gbCode, companyCode);
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, errorMsg);
	}
	return config;
}

public ContractDetailResp changeDetail(String contractCode, String projectOrderId, String changeOrderId, boolean isDetail, Byte contractType, boolean isFirstScreen) {
	ContractDetailResp contractDetailResp;
	//如果有contractCode直接查询详情
	if (StringUtils.isNotBlank(contractCode)) {
		Contract contract = contractService.getByContractCode(contractCode);
		//上一份有效合同
		Contract prevContract = contractService.getChangePrevEffectContract(contract.getId(), contract.getProjectOrderId());
		if (prevContract == null) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少上一份有效的合同");
		}
		contractDetailResp = contractUnifyServiceSelf.baseDetail(contract, contract.getProjectOrderId(), contract.getType(), changeOrderId, isFirstScreen, null, null, null);
		contractDetailResp.setLastSignInfo(buildLastSignInfo(prevContract));
	} else {
		//如果没有contractCode：在变更合同编辑页,可能已经保存草稿，也可能第一次进入
		//查询草稿态的变更合同,一个变更单只会对应一份草稿中的合同
		List<Contract> changeContractList = contractService.getChangeContractList(projectOrderId, changeOrderId)
			.stream().filter(contract -> ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())).collect(Collectors.toList());
		if (!CollectionUtils.isEmpty(changeContractList)) {
			//当前变更有草稿中的合同,合同详情为当前草稿中合同的详情
			Contract currentContract = changeContractList.get(0);
			contractDetailResp = contractUnifyServiceSelf.baseDetail(currentContract, currentContract.getProjectOrderId(), currentContract.getType(), changeOrderId, isFirstScreen, null, null, null);
			//上一份合同信息
			Contract prevContract = contractService.getChangePrevEffectContract(currentContract.getId(), currentContract.getProjectOrderId());
			if (prevContract == null) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少上一份有效的合同");
			}
			contractDetailResp.setLastSignInfo(buildLastSignInfo(prevContract));
		} else {
			//当前变更没有草稿中的合同,合同详情为上一份(正签/变更)合同详情
			Contract prevContract = contractService.getChangePrevEffectContractByPid(projectOrderId);
			if (prevContract == null) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少上一份有效的合同");
			}
			contractDetailResp = contractUnifyServiceSelf.baseDetail(prevContract, prevContract.getProjectOrderId(), prevContract.getType(), changeOrderId, isFirstScreen, null, null, null);
			contractDetailResp.setLastSignInfo(buildLastSignInfo(prevContract));
			//重置变更合同信息为默认初始化信息
			contractDetailResp.setContractBaseInfo(ContractBaseInfoDetail.builder()
				.projectOrderId(projectOrderId)
				.changeOrderId(changeOrderId)
				.havePersonalQuote(contractDetailResp.getContractBaseInfo().isHavePersonalQuote())
				.changeOrderType(contractDetailResp.getContractBaseInfo().getChangeOrderType())
				.contractType(ContractTypeEnum.PACKAGE_CHANGE.getCode())
				.formalMergeLaunch(contractDetailResp.getContractBaseInfo().isFormalMergeLaunch())
				.processV25(contractDetailResp.getContractBaseInfo().isProcessV25())
				.useAddressFromDictionary(contractDetailResp.getContractBaseInfo().getUseAddressFromDictionary())
				.needRealNameVerifyInConfirm(contractDetailResp.getContractBaseInfo().getNeedRealNameVerifyInConfirm())
				.standardDesignFeeOpen(contractDetailResp.getContractBaseInfo().getStandardDesignFeeOpen())
				.build());
			// 不默认带出上一份合同的「实际客户签署时间」、「盖公司章时间」
			ContractSignInfoDetail signInfo = contractDetailResp.getSignInfo();
			signInfo.setUserSignTime(null);
			signInfo.setCompanySignTime(null);

			signInfo.setAttachUrl(Collections.emptyList());
			boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType)
				&& BusinessTypeEnum.getHouseCertificate25ModeList().contains(commonBusinessService.getBusinessType(projectOrderId));
			//只有2.5走这块逻辑
			if (houseProcessV25) {
				//有报价变更，原始户型需要取客源的
				ContractProjectInfoDetail projectInfo = contractDetailResp.getProjectInfo();
				ChangeApplyInfoDTO changeApplyInfoDTO = atomChangeRpc.getChangeApplyInfo(changeOrderId);
				List<Integer> changeScopeList = changeApplyInfoDTO.getChangeScopeList();
				if (changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode())) {
					ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
					projectInfo.setRoomCnt(projectInfoDTO.getCustomerHouse().getRoomCnt());
					projectInfo.setParlorCnt(projectInfoDTO.getCustomerHouse().getParlorCnt());
					projectInfo.setCookroomCnt(projectInfoDTO.getCustomerHouse().getCookroomCnt());
					projectInfo.setToiletCnt(projectInfoDTO.getCustomerHouse().getToiletCnt());
					projectInfo.setBalconyCnt(projectInfoDTO.getCustomerHouse().getBalconyCnt());
					projectInfo.setStorageCnt(projectInfoDTO.getCustomerHouse().getStorageCnt());
				}
			}
		}
	}
	ContractSignInfoDetail signInfo = contractDetailResp.getSignInfo();
	LastSignInfo lastSignInfo = contractDetailResp.getLastSignInfo();
	if (!isDetail) {
		//不是详情页，不加密，进行对字段数据进行解密
		//todo 优化
		signInfo.setOwnerCertificateNo(cipherService.decrypt(signInfo.getOwnerCertificateNo()));
		signInfo.setAgentCertificateNo(cipherService.decrypt(signInfo.getAgentCertificateNo()));
		signInfo.setCompanyAgentCertificateNo(cipherService.decrypt(signInfo.getCompanyAgentCertificateNo()));
		signInfo.setLegalCertificateNo(cipherService.decrypt(signInfo.getLegalCertificateNo()));
		lastSignInfo.setOwnerCertificateNo(cipherService.decrypt(lastSignInfo.getOwnerCertificateNo()));
		lastSignInfo.setAgentCertificateNo(cipherService.decrypt(lastSignInfo.getAgentCertificateNo()));
		lastSignInfo.setCompanyAgentCertificateNo(cipherService.decrypt(lastSignInfo.getCompanyAgentCertificateNo()));
		lastSignInfo.setLegalCertificateNo(cipherService.decrypt(lastSignInfo.getLegalCertificateNo()));
		contractDetailResp.getContractBaseInfo().setIsDetail(Boolean.FALSE);
	}
	//手机号统一加密返回
	signInfo.setOwnerPhone(cipherService.encrypt(signInfo.getOwnerPhone()));
	signInfo.setAgentPhone(cipherService.encrypt(signInfo.getAgentPhone()));
	signInfo.setCompanyAgentPhone(cipherService.encrypt(signInfo.getCompanyAgentPhone()));
	signInfo.setLegalPhone(cipherService.encrypt(signInfo.getLegalPhone()));
	signInfo.setSignatoryPhone(cipherService.encrypt(signInfo.getSignatoryPhone()));
	lastSignInfo.setOwnerPhone(cipherService.encrypt(lastSignInfo.getOwnerPhone()));
	lastSignInfo.setAgentPhone(cipherService.encrypt(lastSignInfo.getAgentPhone()));
	lastSignInfo.setCompanyAgentPhone(cipherService.encrypt(lastSignInfo.getCompanyAgentPhone()));
	lastSignInfo.setLegalPhone(cipherService.encrypt(lastSignInfo.getLegalPhone()));

	contractDetailResp.getSignInfo().setCustomerPhoneVoList(contractDetailService.getCustomerPhoneVoList(contractDetailResp.getSignInfo(), isDetail));
	//是否支持公对公线上签约
	contractDetailResp.getContractBaseInfo().setSupportCompanyOnlineSign(commonContractService.openCompanySignOnline(projectOrderId));

	return contractDetailResp;
}

private boolean reSign(String projectOrderId, Byte contractType) {
	List<Contract> contractList = contractService.getContractList(projectOrderId, contractType);
	if (CollectionUtils.isEmpty(contractList)) {
		return false;
	}
	List<Integer> finalContractStatus = Arrays.asList(ContractStatusEnum.USER_CONFIRMED.getCode(), ContractStatusEnum.FINISH.getCode());
	List<Contract> contractListFilter = contractList.stream().filter(item -> finalContractStatus.contains(item.getStatus()))
		.collect(Collectors.toList());
	return !CollectionUtils.isEmpty(contractListFilter);
}

private LastSignInfo buildLastSignInfo(Contract preContract) {
	List<ContractAttach> contractAttachList = contractAttachService.getListByContractCode(preContract.getContractCode());
	List<String> attachUrl = contractAttachList.stream()
		.filter(contractAttach -> AttachTypeEnum.OFFLINE_CONTRACT.getCode().byteValue() == contractAttach.getAttachType())
		.map(ContractAttach::getUrl).collect(Collectors.toList());
	//合同字段信息
	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(preContract.getContractCode());
	Map<String, String> fieldMap = contractFieldList.stream().collect(Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue));
	LastSignInfo lastSignInfo = new LastSignInfo();
	//组装和主体相关的信息：客户姓名、客户手机号、客户证件类型、客户身份证、客户住所地址、企业名称、统一社会信用代码、代理人姓名、代理人手机号、代理人证件类型、代理人证件
	ContractSignInfoDetail signInfoDetail = contractDetailService.buildContractSignInfoDetail(preContract, preContract.getType(), null, fieldMap, contractAttachList, preContract.getChangeOrderId());
	BeanUtils.copyProperties(signInfoDetail, lastSignInfo);
	//组装上一次合同模块展示字段
	String contractObjectType = fieldMap.get("contractObjectType");
	lastSignInfo.setLastAttachUrl(attachUrl.stream().map(url -> File.builder().url(url).build()).collect(Collectors.toList()));
	lastSignInfo.setLastAttachFileType(contractBusinessService.getAttachFileKey(attachUrl));
	lastSignInfo.setLastContractObjectTypeName(contractObjectType == null ? "" : ContractObjectTypeEnum.getLabelByCode(Byte.valueOf(contractObjectType)));
	lastSignInfo.setLastSignChannelTypeName(SignChannelTypeEnum.getLabelByCode(preContract.getSignChannelType()));
	return lastSignInfo;
}

