	}
	return fileList.stream().map(item -> CertificateDTO.builder()
		.certificateType(certificateType)
		.certificateId(item.getCertificateId())
		.certificateCode(certificateCode)
		.ocrField(Lists.emptyList())
		.certificateFileList(Lists.newArrayList(CertificateFile.builder()
			.fileType("image/".concat(CommonUtil.getImageTypeByUrl(item.getUrl())))
			.fileKey(item.getUrl())
			.imageUrl(item.getUrl())
			.build()))
		.build()).collect(Collectors.toList());
}

