public void packageFormalContractCheck(ContractReqDTO contractReq) {
	Integer needDesignerAmount = contractReq.getPromiseInfo().getNeedDesignerAmount();
	if (ObjectUtil.isNotEmpty(needDesignerAmount) && needDesignerAmount.equals(CommonEnum.YES.getCode().intValue())) {
		List<Contract> contractList = contractService.getContractList(contractReq.getContractBaseInfo().getProjectOrderId(), ContractTypeEnum.DESIGN.getCode());
		Contract contract = contractList.stream().filter(m -> ContractStatusEnum.validStatusWithoutDraft.contains(m.getStatus())).findFirst().orElse(null);
		if (ObjectUtil.isNotEmpty(contract)) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "已在设计合同中约定设计费，不支持再在正式套餐合同中约定设计费。若已完成设计合同签约，请发起设计变更协议修改设计费。", Level.WARN);
		}
	}
}

private void designContractCheck(List<Contract> contractList) {
	//有效非草稿的合同
	Contract contract = contractList.stream().filter(m -> ContractStatusEnum.validStatusWithoutDraft.contains(m.getStatus())).filter(m -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(m.getType())).findFirst().orElse(null);
	if (ObjectUtil.isNotEmpty(contract)) {
		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contract.getContractCode());
		ContractField contractField = contractFieldList.stream().filter(m -> "needDesignerAmount".equals(m.getFieldKey())).findFirst().orElse(null);
		boolean mergeLaunchDesignContract = isMergeLaunchDesignContract(contract.getProjectOrderId());
		if (!mergeLaunchDesignContract && ObjectUtil.isNotEmpty(contractField) && CommonEnum.YES.getCode().equals(Byte.valueOf(contractField.getFieldValue()))) {
			throw new NrsBusinessException(ResponseCodeEnum.DESIGN_CONTRACT_CREATE_CHECK_TOAST.getCode(), ResponseCodeEnum.DESIGN_CONTRACT_CREATE_CHECK_TOAST.getMsg(), Level.WARN);
		}
	}
}

public void checkConstructSchedule(ContractReqDTO contractReq) {
	//非正签合同无需校验
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return;
	}
	ProjectInfoDTO projectInfo = projectInfoReadService.getByProjectOrderIdWithoutCache(contractReq.getContractBaseInfo().getProjectOrderId());
	Integer gbCode = projectInfo.getCustomerHouse().getGbCode();
	String companyCode = projectInfo.getCustomerCommission().getCompanyCode();
	List<ContractCityCompanyInfo> configList = contractCityCompanyConfigService.getConfig(
		projectInfo.getProjectOrderId(),
		gbCode,
		companyCode,
		commonContractService.getBusinessType(projectInfo),
		contractType,
		contractReq.getSignInfo().getSignChannelType()
	);
	if (CollectionUtils.isEmpty(configList)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "缺少合同配置信息");
	}
	boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectInfo.getProjectOrderId(), contractType)
		&& BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(commonBusinessService.getBusinessType(projectInfo.getProjectOrderId()));
	if (!houseProcessV25) {
		return;
	}
	ConstructScheduleVo constructScheduleVo = pcContractService.calculateSchedule(projectInfo.getProjectOrderId(),
		contractReq.getContractBaseInfo().getContractType(), contractReq.getProjectInfo().getArea(),
		contractReq.getProjectInfo().getPlanStartTime(), contractReq.getProjectInfo().getToiletCnt(),
		contractReq.getProjectInfo().getHouseType(), contractReq.getProjectInfo().getHouseBuildType());
	//2.5合并发起模式的，工期未获取成功的不允许下载合同模板
	if ((constructScheduleVo == null || constructScheduleVo.getTotalPeriod() == null || constructScheduleVo.getTotalPeriod() <= 0)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "工期异常，请联系工期系统运营");
	}
}

public void checkIdCardInfo(ContractReqDTO contractReq) {
	ContractSignInfoReq signInfo = contractReq.getSignInfo();
	if (ContractObjectTypeEnum.PERSON.getCode().equals(signInfo.getContractObjectType()) && isIdCertificate(signInfo.getOwnerCertificateType())
		&& !StringUtils.isEmpty(signInfo.getOwnerCertificateNo()) && !StringUtils.isEmpty(signInfo.getOwnerName())
	) {
		if (!commonContractService.checkIdName(cipherService.decrypt(signInfo.getOwnerCertificateNo()), signInfo.getOwnerName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "客户姓名与身份证号不一致，请核对后重试");
		}
	}
	if (CommonEnum.YES.getCode().equals(signInfo.getHaveAgent()) && isIdCertificate(signInfo.getAgentCertificateType())
		&& !StringUtils.isEmpty(signInfo.getAgentCertificateNo()) && !StringUtils.isEmpty(signInfo.getAgentName())) {
		if (!commonContractService.checkIdName(cipherService.decrypt(signInfo.getAgentCertificateNo()), signInfo.getAgentName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "代理人姓名&身份证号不一致");
		}
	}
	if (ContractObjectTypeEnum.COMPANY.getCode().equals(signInfo.getContractObjectType())) {
		if (isIdCertificate(signInfo.getCompanyAgentCertificateType()) && !commonContractService.checkIdName(cipherService.decrypt(signInfo.getCompanyAgentCertificateNo()), signInfo.getCompanyAgentName())
			&& !StringUtils.isEmpty(signInfo.getCompanyAgentCertificateNo()) && !StringUtils.isEmpty(signInfo.getCompanyAgentName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "公司代理人姓名&身份证号不一致");
		}
		if (isIdCertificate(signInfo.getLegalCertificateType()) && !commonContractService.checkIdName(cipherService.decrypt(signInfo.getLegalCertificateNo()), signInfo.getLegalName())
			&& !StringUtils.isEmpty(signInfo.getLegalCertificateNo()) && !StringUtils.isEmpty(signInfo.getLegalName())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "法人姓名&身份证号不一致");
		}
	}
}

