private void dataValueCheck(ContractReqDTO contractReq, ContractFieldConfig fieldInfo, ContractModuleAndFieldInfoDTO moduleInfo) {
	//如果是不可编辑的字段或者非必填字段，则不需要校验
	if (fieldInfo.getDisabled().equals(CommonEnum.YES.getCode()) || CommonEnum.NO.getCode().equals(fieldInfo.getRequired())) {
		return;
	}
	Object moduleValue = CommonUtil.getObjectFieldData(fieldInfo.getModuleKey(), contractReq);
	if (Objects.isNull(moduleValue)) {
		String errorMsg = String.format("%s模块信息不能为空", moduleInfo.getModuleKey());
		throw new NrsBusinessException(errorMsg, Level.WARN);
	}
	String displayCondition = fieldInfo.getDisplayCondition();
	if (StringUtils.isBlank(displayCondition)) {
		//没有配置条件，直接校验字段
		try {
			checkFieldValue(fieldInfo, moduleValue, contractReq);
		} catch (Exception e) {
			LOGGER.info("数据校验未通过，字段key：{},字段名称：{}", fieldInfo.getFieldKey(), fieldInfo.getFieldName());
			throw e;
		}
		return;
	}
	//条件计算结果，true为当前字段需要校验非空，false为当前字段不需要校验非空
	boolean displayConditionCompute = true;
	String[] conditions = displayCondition.split("&&");
	for (String condition : conditions) {
		//配置的多个条件，只要有一个不通过则不需要校验
		if (!conditionCheck(condition, contractReq)) {
			displayConditionCompute = false;
			break;
		}
	}
	//配置的条件解析结果为true需要校验字段
	if (displayConditionCompute) {
		try {
			checkFieldValue(fieldInfo, moduleValue, contractReq);
		} catch (Exception e) {
			LOGGER.info("数据校验未通过，字段key：{},字段名称：{},displayCondition:{}", fieldInfo.getFieldKey(), fieldInfo.getFieldName(), displayCondition);
			throw e;
		}
	}
}

private void checkFieldKeyCustom(ContractReqDTO contractReq, ContractFieldConfig fieldInfo) {
	CommonUtil.checkNull(contractReq.getProjectInfo(), "缺少项目模块信息 - 参数校验失败");
	ContractProjectInfoReq projectInfo = contractReq.getProjectInfo();
	if (fieldInfo.getFieldKey().equals("cityObj")) {
		CommonUtil.checkNull(projectInfo.getGbCode(), "gbCode不能为空 - 参数校验失败");
	}
	if (fieldInfo.getFieldKey().equals("districtObj")) {
		CommonUtil.checkNull(projectInfo.getDistrictId(), "行政区id&名称不能为空 - 参数校验失败");
		CommonUtil.checkBlank(projectInfo.getDistrictName(), "行政区id&名称不能为空 - 参数校验失败");
	}
	if (fieldInfo.getFieldKey().equals("resblockObj")) {
		CommonUtil.checkBlank(projectInfo.getResblockName(), "小区名称不能为空 - 参数校验失败");
	}
	//楼栋门牌
	if (fieldInfo.getFieldKey().equals("addressObj")) {
		CommonUtil.checkBlank(projectInfo.getBuildingName(), "楼栋名称不能为空 - 参数校验失败");
		CommonUtil.checkBlank(projectInfo.getUnitName(), "单元名称不能为空 - 参数校验失败");
		CommonUtil.checkBlank(projectInfo.getFloorName(), "楼层名称不能为空 - 参数校验失败");
		CommonUtil.checkBlank(projectInfo.getHouseName(), "房间名称不能为空 - 参数校验失败");
	}
	//原始户型
	if (fieldInfo.getFieldKey().equals("apartmentObj")) {
		CommonUtil.checkNull(projectInfo.getRoomCnt(), "原始户型室不能为空 - 参数校验失败");
		CommonUtil.checkNull(projectInfo.getParlorCnt(), "原始户型厅不能为空 - 参数校验失败");
		CommonUtil.checkNull(projectInfo.getCookroomCnt(), "原始户型厨不能为空 - 参数校验失败");
		CommonUtil.checkNull(projectInfo.getToiletCnt(), "原始户型卫不能为空 - 参数校验失败");
		CommonUtil.checkNull(projectInfo.getBalconyCnt(), "原始户型阳台不能为空 - 参数校验失败");
		CommonUtil.checkNull(projectInfo.getStorageCnt(), "原始户型储物间数不能为空 - 参数校验失败");
	}
	//签约主体
	if (fieldInfo.getFieldKey().equals("signObject")) {
		CommonUtil.checkBlank(contractReq.getSignInfo().getSignCompanyCode(), "签约主体不能为空 - 参数校验失败");
		CommonUtil.checkBlank(contractReq.getSignInfo().getSignCompanyName(), "签约主体不能为空 - 参数校验失败");

	}
}

private void checkFieldValue(ContractFieldConfig fieldInfo, Object moduleValue, ContractReqDTO contractReq) {
	//自定义字段的key
	List<String> fieldKeyCustom = Arrays.asList("cityObj", "districtObj", "resblockObj", "addressObj", "apartmentObj", "signObject");
	if (fieldKeyCustom.contains(fieldInfo.getFieldKey())) {
		checkFieldKeyCustom(contractReq, fieldInfo);
		return;
	}
	Object keyValue = CommonUtil.getObjectFieldData(fieldInfo.getFieldKey(), moduleValue);
	if (keyValue == null) {
		String errorMsg = String.format("%s字段不能为空，请输入%s", fieldInfo.getFieldName(), fieldInfo.getFieldName());
		throw new NrsBusinessException(errorMsg, Level.WARN);
	}
	String keyValueStr = String.valueOf(keyValue);
	if (StringUtils.isBlank(keyValueStr)) {
		String errorMsg = String.format("%s字段不能为空，请输入%s", fieldInfo.getFieldName(), fieldInfo.getFieldName());
		throw new NrsBusinessException(errorMsg, Level.WARN);
	}
}

private boolean conditionCheck(String condition, ContractReqDTO contractReq) {
	if (StringUtils.isBlank(condition)) {
		return true;
	}
	String[] split = condition.split("==");
	String moduleNameAndKeyName = split[0];
	String[] moduleNameAndKeyNameSplit = moduleNameAndKeyName.split("\\.");
	String keyValueFromConfig = split[1];
	String moduleName = moduleNameAndKeyNameSplit[0];
	String keyName = moduleNameAndKeyNameSplit[1];
	Object moduleValue = CommonUtil.getObjectFieldData(moduleName, contractReq);
	//模块值为空，不需要校验
	if (moduleValue == null) {
		return true;
	}
	Object keyValueFromParam = CommonUtil.getObjectFieldData(keyName, moduleValue);
	//条件中字段值为空，不需要校验
	if (keyValueFromParam == null) {
		return true;
	}
	return keyValueFromParam.equals(keyValueFromConfig);
}

