		}
	}
}

public void checkCanSign(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (contract == null) {
		//紧急移除校验
		LOGGER.error("合同不存在,合同编码:{}", contractCode);
		return;
	}
	if (StringUtils.isNotBlank(contract.getRelateContractCode())) {
		//授权协议书签署完成，才能签署相关合同
		Contract accreditContract = contractService.getByContractCode(contract.getRelateContractCode());
		if (!accreditContract.getStatus().equals(ContractStatusEnum.FINISH.getCode())) {
			String msg = "请先提醒企业法定代表人完成认证授权";
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, msg);
		}
	}

	if (!contract.getType().equals(ContractTypeEnum.AUTH_AGENT.getCode())) {
		List<Contract> allRelateContract = homeAndPcCommonService.getAllRelateContract(contract, Collections.emptyList());
		Contract authAgentContract = allRelateContract.stream()
			.filter(c -> ContractTypeEnum.AUTH_AGENT.getCode().equals(c.getType())).findFirst().orElse(null);
		if (authAgentContract != null && !ContractStatusEnum.SIGNED_STATUS_LIST.contains(authAgentContract.getStatus())) {
			throw new NrsBusinessException("请先邀请产权人完成代理人授权", Level.WARN);
		}
	}

	boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
	//如果不是合并发起的合同，不需要校验是否有其他合同签署情况
	if (!processV25) {
		return;
	}

	//获取前置必须签署完成的合同类型
	String preContractSign = ContractTypeEnum.getEnumByCode(contract.getType()).getPreContractSign();
	if (StringUtils.isBlank(preContractSign)) {
		return;
	}
	//前置必须签署完成的合同类型
	List<Byte> preContractSignTypes = Arrays.stream(preContractSign.split(",")).map(Byte::valueOf).collect(Collectors.toList());
	List<Contract> contractList = contractService.getContractList(contract.getProjectOrderId());
	contractList = contractList.stream().filter(item -> ContractStatusEnum.validStatusWithoutDraft.contains(item.getStatus())).collect(Collectors.toList());
	for (Contract item : contractList) {
		if (!preContractSignTypes.contains(item.getType())) {
			continue;
		}
		if (!item.getStatus().equals(ContractStatusEnum.FINISH.getCode())) {
			String msg = "请先完成" + ContractTypeEnum.getEnumByCode(item.getType()).getName() + "签署";
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, msg);
		}
	}
}

public SignCheckDTO checkCanSignV2(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (contract == null) {
		//紧急移除校验
		LOGGER.error("合同不存在,合同编码:{}", contractCode);
		return SignCheckDTO.builder()
			.canSign(Boolean.TRUE)
			.build();
	}
	if (StringUtils.isNotBlank(contract.getRelateContractCode())) {
		//授权协议书签署完成，才能签署相关合同
		Contract accreditContract = contractService.getByContractCode(contract.getRelateContractCode());
		if (!accreditContract.getStatus().equals(ContractStatusEnum.FINISH.getCode())) {
			return SignCheckDTO.builder()
				.canSign(Boolean.FALSE)
				.message("请先提醒企业法定代表人完成认证授权")
				.contractCode(contract.getContractCode())
				.schema(contractBusinessService.buildAuthUrl(contract.getProjectOrderId()))
				.needAuth(Boolean.TRUE)
				.build();
		}
	}

	if (!contract.getType().equals(ContractTypeEnum.AUTH_AGENT.getCode())) {
		List<Contract> allRelateContract = homeAndPcCommonService.getAllRelateContract(contract, Collections.emptyList());
		Contract authAgentContract = allRelateContract.stream()
			.filter(c -> ContractTypeEnum.AUTH_AGENT.getCode().equals(c.getType())).findFirst().orElse(null);
		if (authAgentContract != null && !ContractStatusEnum.SIGNED_STATUS_LIST.contains(authAgentContract.getStatus())) {
			throw new NrsBusinessException("请先邀请产权人完成代理人授权", Level.WARN);
		}
	}

	boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
	//如果不是合并发起的合同，不需要校验是否有其他合同签署情况
	if (!processV25) {
		return SignCheckDTO.builder()
			.canSign(Boolean.TRUE)
			.build();
	}

	//获取前置必须签署完成的合同类型
	String preContractSign = ContractTypeEnum.getEnumByCode(contract.getType()).getPreContractSign();
	if (StringUtils.isBlank(preContractSign)) {
		return SignCheckDTO.builder()
			.canSign(Boolean.TRUE)
			.build();
	}
	//前置必须签署完成的合同类型
	List<Byte> preContractSignTypes = Arrays.stream(preContractSign.split(",")).map(Byte::valueOf).collect(Collectors.toList());
	List<Contract> contractList = contractService.getContractList(contract.getProjectOrderId()).stream().filter(item -> ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(item.getStatus())).collect(Collectors.toList());
	//当前合同的关联合同code
	List<String> relationContractCodeList = contractBusinessService.getRelationContract(contractCode).stream().map(Contract::getContractCode).collect(Collectors.toList());
	//只校验和当前合同存在关联关系的合同
	contractList = contractList.stream().filter(item -> relationContractCodeList.contains(item.getContractCode())).collect(Collectors.toList());
	for (Contract item : contractList) {
		if (!preContractSignTypes.contains(item.getType())) {
			continue;
		}
		if (!item.getStatus().equals(ContractStatusEnum.FINISH.getCode())) {
			return SignCheckDTO.builder()
				.canSign(Boolean.FALSE)
				.message("请先完成" + ContractTypeEnum.getEnumByCode(item.getType()).getName() + "签署")
				.contractCode(item.getContractCode())
				.schema(contractBusinessService.buildDetailUrl(item.getContractCode()))
				.build();
		}
	}
	return SignCheckDTO.builder()
		.canSign(Boolean.TRUE)
		.build();
}

public void checkCanShare(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (contract == null) {
		throw new NrsBusinessException("未查询到合同,合同编码:" + contractCode);
	}
	if (contract.getStatus().equals(ContractStatusEnum.CANCEL.getCode())) {
		String msg = "合同已作废，无法查看";
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, msg);
	}

	if (contract.getStatus().equals(ContractStatusEnum.DRAFT.getCode())) {
		String msg = "当前合同还未发起，请先发起后再分享";
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, msg);
	}
	// 如果不是2.5模式发起的合同，不需要校验是否有其他合同签署情况
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
	if (!processV25) {
		LOGGER.info("不是2.5模式");
		return;
	}

	List<Contract> relationContractList = contractBusinessService.getRelationContract(contractCode);
	for (Contract contractInfo : relationContractList) {
		if (contractInfo.getStatus().equals(ContractStatusEnum.PENDING_COMPANY_SIGN.getCode())) {
			String msg = "盖章中，预计1分钟后可分享给客户签约";
			List<ContractLog> contractLogList = contractLogService.getLogByCodeAndType(contractInfo.getContractCode(), LogTypeEnum.COMPANY_SIGN_FAIL.getCode());
			if (org.apache.commons.collections4.CollectionUtils.isNotEmpty(contractLogList) && contractLogList.size() > 2) {
				msg = "合同文件较大，盖章中，预计5-10分钟后可分享给客户签约";
			}
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, msg);
		}
		if (contractInfo.getStatus().equals(ContractStatusEnum.DRAFT.getCode())) {
			String msg = "关联合同还未发起，请先发起后再分享";
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, msg);
		}
	}
}

public Byte getSignatoryRoleType(String projectOrderId, Byte type, ContractSignInfoReq signInfo, Byte agentSign) {
	Byte contractObjectType = signInfo.getContractObjectType();
	// 公对公签约
	if (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
		return RoleTypeEnum.LEGAL.getCode().equals(signInfo.getSignRole()) ? RoleTypeEnum.LEGAL.getCode() : RoleTypeEnum.COMPANY_AGENT.getCode();
	}

	if (ContractTypeEnum.AUTH_AGENT.getCode().equals(type)) {
		return RoleTypeEnum.OWNER.getCode();
	}

	if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(type)) {
		return changeContractIsAgentSign(projectOrderId, signInfo, agentSign) ? RoleTypeEnum.AGENT.getCode() : RoleTypeEnum.OWNER.getCode();
	} else {
		//代理人直接签约的代理人签，其他的都是业主签
		return CommonEnum.YES.getCode().equals(agentSign) ? RoleTypeEnum.AGENT.getCode() : RoleTypeEnum.OWNER.getCode();
	}
}

