private boolean changeContractIsAgentSign(String projectOrderId, ContractSignInfoReq signInfo, Byte agentSign) {
	if (agentSign == null && signInfo.getHaveAgent() != null) {
		LOGGER.info("获取变更合同是否代理人签约，agentSign为空，haveAgent不为空，haveAgent:{}", signInfo.getHaveAgent());
		agentSign = signInfo.getHaveAgent();
	}
	//无代理人，客户签约
	if (HaveAgentEnum.NO.getCode().equals(signInfo.getHaveAgent())) {
		return false;
	}
	//有代理人，有代理人委托证明的，代理人签约
	if (CommonEnum.YES.getCode().equals(agentSign)) {
		return true;
	}
	//有代理人，无代理人委托证明的，如果代理人姓名、证件类型、证件号码与客源备件记录的代理人一致，代理人签约
	IdentityInfo identityInfo = attachCommonService.getProjectAttachInfoDetail(projectOrderId, false).getIdentityInfo();
	return Objects.equals(signInfo.getAgentName(), identityInfo.getAgentName())
		&& Objects.equals(signInfo.getAgentCertificateType(), identityInfo.getAgentCertificateType())
		&& Objects.equals(cipherService.decrypt(signInfo.getAgentCertificateNo()), identityInfo.getAgentCertificateNo());
}

