public void dealReContractLaunch(String projectOrderId, Byte contractType) {
	if (!ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
		return;
	}
	if (contractApolloConfig.getCheckPersonalContract()) {
		//支持签约多份C合同，去除作废逻辑
		return;
	}
	List<Contract> contractList = contractService.getContractList(projectOrderId, contractType);
	List<Contract> personalContract = contractList.stream()
		.filter(contract -> ContractStatusEnum.allowSignStatus.contains(contract.getStatus())).collect(Collectors.toList());
	if (CollectionUtils.isEmpty(personalContract)) {
		return;
	}
	//获取当前已发起C的关联合同，判断是否是B+C发起，B+C发起不支持进行撤销操作
	ContractRelation relateContract = contractRelationService.getByRelateContractCode(personalContract.get(0).getContractCode());
	if (relateContract != null) {
		Contract relateContractInfo = contractService.getByContractCode(relateContract.getContractCode());
		if (ContractStatusEnum.validStatusWithoutDraft.contains(relateContractInfo.getStatus())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "销售合同已通过基础套餐合同发起，不支持重复发起签约");
		}
	}
	homeAndPcCommonService.undoContract(personalContract.get(0).getContractCode(), Long.valueOf(HeaderContext.getContext().getOperatorUcId()));
	LOGGER.info("【发起签约/保存草稿】撤销之前【待签署/待确认】的合同完成,contractCode:{}", personalContract.get(0).getContractCode());
