public boolean isMergeLaunchDesignContract(String projectOrderId) {
	List<Contract> packageFormalContracts =  contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractStatusEnum.inPositiveStatus);
	if (CollectionUtil.isEmpty(packageFormalContracts)) {
		return false;
	}
	List<ContractRelation> relationList = contractRelationService.getRelationList(packageFormalContracts.get(0).getContractCode());
	Boolean mergeDesignContract = Boolean.FALSE;
	if (CollectionUtil.isNotEmpty(relationList)) {
		List<String> collect = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
		List<Contract> contractList = contractService.getListByContractCodes(collect, Boolean.TRUE);
		mergeDesignContract = contractList.stream().anyMatch(contract1 -> ContractTypeEnum.DESIGN.getCode().equals(contract1.getType()));
	}
	return mergeDesignContract;

}

