	/**
	 * 初始化时，绑定合同与单据的关联关系
	 */
	public void bindCodeRelationWithClear(Contract contract, BindOrderInfoGroup group) {
		// 不存在需要绑定的单据，则返回
		if (CollectionUtil.isEmpty(group.getBindOrderInfos()) || (!ContractTypeEnum.ADVANCE.getCode().equals(contract.getType()) && !ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))) {
			return;
		}

		lockService.lockElseThrow(LockService.CONTRACT_BIND_BILL_CODE + contract.getContractCode(), () -> {
			// 事务处理
			transactionTemplate.execute(status -> {
				// 清除合同下的所有关联关系
				contractQuotationRelationService.deleteRelationsByContractCode(contract.getContractCode());
				for (BindOrderInfo bindOrderInfo : group.getBindOrderInfos()) {
					// 绑定新的关联关系
					bindCodeRelation(contract.getContractCode(), contract.getCompanyCode(), bindOrderInfo.getBindOrderNoList(), bindOrderInfo.getBindType());
				}
				return null;
			});
			return null;
		});

	}

	/**
	 * 基础绑定方法
	 */
	public void bindCodeRelation(String contractCode, String companyCode, List<String> bindOrderNos, Integer bindType) {
		LOGGER.info("合同关联关系绑定, contractCode: {}, companyCode: {}, bindOrderNos: {}, bindType: {}", contractCode, companyCode, JSON.toJSONString(bindOrderNos), bindType);
		lockService.lockElseThrow(LockService.CONTRACT_BIND_BILL_CODE + contractCode, () -> {
			List<String> toBindOrderNosTmp = new ArrayList<>(bindOrderNos);

			// 查询合同关联的单据
			List<ContractQuotationRelation> relations = contractQuotationRelationService.getByContractCode(contractCode, RelationStatusEnum.RELATED.getCode(), bindType);
			if (CollectionUtil.isNotEmpty(relations)) {
				for (ContractQuotationRelation relation : relations) {
					// 已经绑定过，本次不需要重复绑定
					toBindOrderNosTmp.remove(relation.getBillCode());
				}
			}
			// 均绑定过则不需要再绑定
			if (CollectionUtil.isEmpty(toBindOrderNosTmp)) {
				return null;
			}
			List<ContractQuotationRelation> toBindRelations = new ArrayList<>();
			for (String bindCode : toBindOrderNosTmp) {
				ContractQuotationRelation relation = new ContractQuotationRelation();
				relation.setContractCode(contractCode);
				relation.setBillCode(bindCode);
				relation.setBindType(bindType);
				relation.setCompanyCode(companyCode);
				relation.setStatus(RelationStatusEnum.RELATED.getCode());
				relation.setDelStatus(CommonEnum.NO.getCode());
				relation.setCtime(new Date());
				relation.setMtime(new Date());
				toBindRelations.add(relation);
			}
			contractQuotationRelationService.insertBatch(toBindRelations);
			return null;
		});

	}

	/**
	 * 取消合同关联的所有单据
	 * 上层调用方太多，暂时不替换
	 */
	public void cancelContractRelations(String contractCode) {
		contractQuotationRelationService.cancelRelationsByContractCode(contractCode);
	}

	/**
	 * 获取报价单号获取关联合同列表
	 * todo zqy bsu 上层 CommonContractService 已不使用, 仅 PersonalRelationHandlerImpl 调用
	 */
	public List<Contract> getContractByBillCode(String billCode) {
		if (StringUtils.isBlank(billCode)) {
			return null;
		}
		List<ContractQuotationRelation> contractQuotationRelationList = contractQuotationRelationService.getByBillCodesAndStatus(Collections.singletonList(billCode), RelationStatusEnum.RELATED.getCode(), BindTypeEnum.BILL_CODE.getCode());
		//获取关联的合同
		if (CollectionUtil.isEmpty(contractQuotationRelationList)) {
			return new ArrayList<>();
		}
		//获取合同编号
		List<String> contractCodeList = contractQuotationRelationList.stream().map(ContractQuotationRelation::getContractCode).distinct().collect(Collectors.toList());
		//获取合同信息
		return contractService.getListByContractCodes(contractCodeList, false);
	}

	/**
	 * 获取绑定单据号关联的唯一合同信息
	 */
	public Contract getUniqueContractByBindCodes(List<String> bindCodes, String companyCode, Integer bindType) {
		if (CollectionUtil.isEmpty(bindCodes)) {
			return null;
		}
		List<ContractQuotationRelation> contractQuotationRelationList = contractQuotationRelationService.getByBillCodesAndStatus(bindCodes, RelationStatusEnum.RELATED.getCode(), bindType);
		contractQuotationRelationList = contractQuotationRelationList.stream().filter(item -> ObjectUtil.equal(item.getCompanyCode(), companyCode)).collect(Collectors.toList());
		//获取关联的合同
		if (CollectionUtil.isEmpty(contractQuotationRelationList)) {
			return null;
		}
		//获取合同编号
		List<String> contractCOdeList = contractQuotationRelationList.stream().map(ContractQuotationRelation::getContractCode).distinct().collect(Collectors.toList());
		if (contractCOdeList.size() > 1) {
			throw new NrsBusinessException("报价单关联的合同不唯一", Level.ERROR);
		}
		//获取合同信息
		return contractService.getByContractCode(contractCOdeList.get(0));
	}

	/**
	 * 获取报价单列表绑定的C合同
	 */
	public Contract getContractByBindCodes(List<String> bindCodes, String companyCode, String changeOrderId) {
		if (CollectionUtil.isEmpty(bindCodes)) {
			return null;
		}
		List<ContractQuotationRelation> contractQuotationRelationList = contractQuotationRelationService.getByBindCodesAndStatus(bindCodes, RelationStatusEnum.RELATED.getCode());
		contractQuotationRelationList = contractQuotationRelationList.stream().filter(item -> ObjectUtil.equal(item.getCompanyCode(), companyCode)).collect(Collectors.toList());
		//获取关联的合同
		if (CollectionUtil.isEmpty(contractQuotationRelationList)) {
			return null;
		}
		//如果绑定了多份C合同，删除原有合同，重新创建
		List<String> contractCodes = contractQuotationRelationList.stream().map(ContractQuotationRelation::getContractCode).distinct().collect(Collectors.toList());
		List<Contract> contractList = contractService.getListByContractCodesAndStatus(contractCodes, ContractStatusEnum.inPositiveStatus);
		contractList = contractList.stream().filter(item -> ObjectUtil.equal(item.getChangeOrderId(), changeOrderId)).collect(Collectors.toList());
		if (CollectionUtil.isEmpty(contractList)){
			return null;
		}
		if (contractList.size() > 1) {
			for (Contract contract : contractList) {
				if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()) && !ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus())) {
					//删除原有合同
					commonContractService.cancelCurrentContract(contract, HeaderContext.getUserId(), true);
				}
			}
			return null;
		} else {
			//如果合同已完结，不能重复创建
			if (StringUtils.isNotBlank(changeOrderId) && ContractStatusEnum.inEndStatus((contractList.get(0).getStatus()))) {
				throw new NrsBusinessException("报价单对应合同已签署完成，无需重复创建", Level.ERROR);
			}
			if (!ContractStatusEnum.DRAFT.getCode().equals(contractList.get(0).getStatus())) {
				throw new NrsBusinessException("单据对应合同已发起，无需重复创建");
			}
			return contractList.get(0);
		}
	}

