			if (billCodeInfoListField != null && StringUtils.isNotBlank(billCodeInfoListField.getFieldValue())) {
				Gson gson = new Gson();
				Type listType = new TypeToken<List<BillCodeInfo>>() {
				}.getType();
				List<BillCodeInfo> billCodeInfoList = gson.fromJson(billCodeInfoListField.getFieldValue(), listType);
				return billCodeInfoList.stream().map(BillCodeInfo::getBillCode).filter(StringUtils::isNotBlank).distinct().collect(Collectors.toList());
			} else if (billCodeListField != null && StringUtils.isNotBlank(billCodeListField.getFieldValue())) {
				Gson gson = new Gson();
				Type listType = new TypeToken<List<String>>() {
				}.getType();
				return gson.fromJson(billCodeListField.getFieldValue(), listType);
			} else {
				return new ArrayList<>();
			}
		}
		List<ContractQuotationRelation> contractQuotationRelationList = contractQuotationRelationService.getByContractCode(contractCode, RelationStatusEnum.RELATED.getCode());
