	}

	/**
	 * 获取合同关联的单据列表（正签不关联单据，需要从字段表拿；销售合同直接从关联表拿即可）
	 */
	public BindOrderInfoGroup getBindOrderInfoGroupByContractCode(String contractCode) {
		BindOrderInfoGroup group = new BindOrderInfoGroup();

		Contract contract = contractService.getByContractCode(contractCode);
		if (contract == null) {
			return group;
		}

		// 正签合同的关联的报价单列表从合同字段中获取
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
			ContractField subOrderInfoListField = contractFieldService.getByContractCodeAndKey(contractCode, "subOrderInfoList");
			ContractField billCodeInfoListField = contractFieldService.getByContractCodeAndKey(contractCode, "billCodeInfoList");
			ContractField changeOrderInfoListField = contractFieldService.getByContractCodeAndKey(contractCode, "changeOrderInfoList");
			return BindOrderInfoGroup.convert(contract.getProjectOrderId(), subOrderInfoListField, billCodeInfoListField, changeOrderInfoListField);
		}

		// 销售合同从关联表查绑定的单据号
		List<ContractQuotationRelation> contractQuotationRelations = contractQuotationRelationService.getByContractCode(contractCode, RelationStatusEnum.RELATED.getCode(), null);
		if (CollectionUtil.isEmpty(contractQuotationRelations)) {
			return group;
		}
		return BindOrderInfoGroup.convert(contract.getProjectOrderId(), contractQuotationRelations);
	}

	/**
	 * 协同报价单换绑至 S 单：发起合同时，销售合同关联的协同报价单/团装报价单可能已经完成下单，尝试换绑，如果未下单完成，则不换绑
	 */
	public void convertCooperBillToSubOrderByContract(Contract contract) {
		// 仅处理销售合同
		if (!ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			return;
		}

		LOGGER.info("协同报价单换绑 S 单开始, contractCode: {}", contract.getContractCode());
		// 仅处理协同报价单和团装报价单
		List<Integer> cooperBillTypes = Arrays.asList(GeneralBillTypeEnum.BUDGET_COOPER.getCode(), GeneralBillTypeEnum.BUDGET_GROUP.getCode());

		// 1. 查询销售合同关联的报价单据
		List<String> hasBoundBillCodes = contractQuotationRelationService.getByContractCode(contract.getContractCode(), RelationStatusEnum.RELATED.getCode(), BindTypeEnum.BILL_CODE.getCode())
			.stream()
			.filter(relation -> BindTypeEnum.BILL_CODE.getCode().equals(relation.getBindType()))
			.map(ContractQuotationRelation::getBillCode)
			.collect(Collectors.toList());

		if (CollectionUtil.isEmpty(hasBoundBillCodes)) {
			LOGGER.info("合同{}关联的报价单据为空", contract.getContractCode());
			return;
		}

		// 2. 过滤出协同报价单号
		List<String> cooperBillCodes = atomBudgetRpc.queryBillsByBillCodes(hasBoundBillCodes).stream()
			.filter(billDTO -> cooperBillTypes.contains(billDTO.getBillType()))
			.map(BudgetBillDTO.BaseInfo::getBillCode)
			.collect(Collectors.toList());

		if (CollectionUtil.isEmpty(cooperBillCodes)) {
			LOGGER.info("合同{}关联的协同报价单/团装报价单为空", contract.getContractCode());
		}

		// 逐个协同单号换绑
		for (String cooperBillCode : cooperBillCodes) {
			try {
				lockService.lockElseThrow(LockService.CONTRACT_RELATION_BILL_CODE + cooperBillCode, () -> {
					convertCooperBillToSubOrderByContract(contract, cooperBillCode);
					return null;
				}, 10000);
			} catch (Exception e) {
				LOGGER.error("协同报价单换绑 S 单失败, projectOrderId: {}, contractCode: {}, cooperBillCode: {}", contract.getProjectOrderId(), contract.getContractCode(), cooperBillCode);
			}
		}
	}

	private void convertCooperBillToSubOrderByContract(Contract contract, String cooperBillCode) {
		// 3. 获取 s 单号
		List<String> toBindSubOrderNos = subOrderFeignService.queryValidBaseInfoByHomeOrderNo(contract.getProjectOrderId(), cooperBillCode, null)
			.stream()
			// 获取当前合同主体对应的 S 单
			.filter(subOrderBaseInfoDTO -> ObjectUtil.equal(contract.getCompanyCode(), subOrderBaseInfoDTO.getMdmCode()))
			.map(SubOrderBaseInfoDTO::getOrderNo)
			.collect(Collectors.toList());



		// 4. 解绑协同报价单号 + 绑定 S 单
		bindSubOrderNos(contract.getContractCode(), contract.getCompanyCode(), cooperBillCode, toBindSubOrderNos);

		// 触发 S 单生成
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				if (CollectionUtil.isNotEmpty(toBindSubOrderNos)) {
					homeOrderPdfService.generatePdf(contract.getProjectOrderId(), null, 100000000000000L, null, toBindSubOrderNos, false);
				}
			} catch (Exception e) {
				LOGGER.error("换绑 S 单后，重新触发 S 单的 pdf 生成, projectOrderId: {}, oldBindOrders: {}, newBindOrders: {}", contract.getProjectOrderId(), cooperBillCode, toBindSubOrderNos);
			}
		}));
	}

	/**
	 * 基础报价单换绑 S 单：将基础报价单下单后对应的 S 单绑定至销售合同，不解绑基础报价单
	 */
	public void convertStandardBillToSubOrder(Contract contract, String billCode) {
		// 仅处理销售合同
		if (!ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			return;
		}
		// 1. 检查该销售合同是否绑定了当前基础报价单
		boolean isBound = contractQuotationRelationService
			.getByContractCode(contract.getContractCode(), RelationStatusEnum.RELATED.getCode(), BindTypeEnum.BILL_CODE.getCode())
			.stream()
			.anyMatch(r -> billCode.equals(r.getBillCode()));
		if (!isBound) {
			return;
		}

		// 2. 查询基础报价单对应的 S 单
		List<String> toBindSubOrderNos = subOrderFeignService.queryValidBaseInfoByHomeOrderNo(
				contract.getProjectOrderId(), billCode, null)
			.stream()
			.filter(subOrderBaseInfoDTO -> ObjectUtil.equal(contract.getCompanyCode(), subOrderBaseInfoDTO.getMdmCode()))
			.map(SubOrderBaseInfoDTO::getOrderNo)
			.collect(Collectors.toList());

		if (CollectionUtil.isEmpty(toBindSubOrderNos)) {
			LOGGER.info("基础报价单 {} 暂无对应 S 单，跳过绑定", billCode);
			return;
		}
		// 3. 仅绑定 S 单，不解绑基础报价单
		bindCodeRelation(contract.getContractCode(), contract.getCompanyCode(), toBindSubOrderNos, BindTypeEnum.SUB_ORDER.getCode());
		// 记录换绑日志：基础报价单 -> S 单
		contractBindLogService.recordBindChangeLog(
			contract.getContractCode(),
			"基础报价单换绑S单",
			billCode,
			toBindSubOrderNos
		);
	}

