	Contract terminalUseContractInfo = contractBusinessService.getTerminalUseContractInfo(projectOrderId, true);
	if (terminalUseContractInfo == null) {
		LOGGER.error("获取解约协议的房屋地址信息失败，正向合同信息为空");
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "获取解约协议的房屋地址信息失败", Level.WARN);
	}
	Map<String, String> fieldInfoMap = contractFieldService.getListByContractCode(terminalUseContractInfo.getContractCode()).stream()
		.collect(Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue, (a, b) -> a));
	String gbName = CityEnum.getNameByCode(Integer.valueOf(fieldInfoMap.get("gbCode"))) == null ? "" : CityEnum.getNameByCode(Integer.valueOf(fieldInfoMap.get("gbCode")));
