	return result;
}

public Map<String, Object> getTerminalDetailFundInfo() {
	HashMap<String, Object> result = new HashMap<>();
	// 获取项目ID和最新退单数据
	String projectOrderId = ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId();
	CancelOrderBaseInfoDTO cancelOrderBaseInfoDTO = buildCancelOrderBaseInfo();
	Byte businessType = commonBusinessService.getBusinessType(projectOrderId);

	// 获取资金数据
	List<FundAmountDTO> fundAmountList = cancelOrderBaseInfoDTO.getFundAmountList();
	Map<Integer, FundAmountDTO> fundAmountMap = fundAmountList.stream()
		.collect(Collectors.toMap(FundAmountDTO::getFundType, Function.identity()));

	// 获取不同类型的资金数据
	FundAmountDTO designFund = fundAmountMap.get(FundTypeEnum.DESIGN_CHARGE.getValue());
	FundAmountDTO projectFund = fundAmountMap.get(FundTypeEnum.PROJECT_CHARGE.getValue());
	FundAmountDTO liquidatedFund = fundAmountMap.get(FundTypeEnum.LIQUIDATED_DAMAGES.getValue());

	// 使用通用方法来处理金额文本和大写转换
	String designPaidAmount = formatAmount(designFund, FundAmountDTO::getPaidAmount);
	String designPaidAmountText = formatAmountText(designFund, FundAmountDTO::getPaidAmount);
	String projectPaidAmount = formatAmount(projectFund, FundAmountDTO::getPaidAmount);
	String projectPaidAmountText = formatAmountText(projectFund, FundAmountDTO::getPaidAmount);
	String liquidatedFundAmount = formatAmount(liquidatedFund, FundAmountDTO::getDueAmount);
	String liquidatedFundAmountText = formatAmountText(liquidatedFund, FundAmountDTO::getDueAmount);
	String projectActuallyUsedAmount = formatAmount(projectFund, FundAmountDTO::getDueAmount);
	String projectActuallyUsedAmountText = formatAmountText(projectFund, FundAmountDTO::getDueAmount);
	String designActuallyUsedAmount = formatAmount(designFund, FundAmountDTO::getDueAmount);
	String designActuallyUsedAmountText = formatAmountText(designFund, FundAmountDTO::getDueAmount);

	String terminalDetailFundInfo;
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
		String templateTemp = "原协议项下，甲方已向乙方支付合同款【%s】元（大写：人民币【%s】）。按照原协议相关约定和甲乙双方协商结果，" +
			"甲方需向乙方支付违约金/定金【%s】元（大写：人民币 【%s】）" +
			"及实际已发生施工费、礼品等相关费用【%s】元 （大写：人民币【%s】）";
		terminalDetailFundInfo = String.format(templateTemp, projectPaidAmount, projectPaidAmountText,
			liquidatedFundAmount, liquidatedFundAmountText, projectActuallyUsedAmount, projectActuallyUsedAmountText);
	} else {
		String templateTemp = "原协议项下，甲方已向乙方支付设计服务费【%s】元（大写：人民币【%s】）、工程款（含已支付定金抵扣工程款部分，如有）【%s】元（大写：人民币【%s】）。" +
			"甲方应按照原协议相关约定向乙方支付违约金【%s】元（大写：人民币 【%s】）、实际已发生施工费【%s】元 （大写：人民币【%s】）、" +
			"设计服务费等相关费用【%s】元 （大写：人民币【%s】）。";
		terminalDetailFundInfo = String.format(templateTemp, designPaidAmount, designPaidAmountText, projectPaidAmount, projectPaidAmountText,
			liquidatedFundAmount, liquidatedFundAmountText, projectActuallyUsedAmount, projectActuallyUsedAmountText,
			designActuallyUsedAmount, designActuallyUsedAmountText);
	}
	result.put("terminalDetailFundInfo", terminalDetailFundInfo);
	return result;
}

public Map<String, Object> getTerminalTotalFundInfo() {
	HashMap<String, Object> result = new HashMap<>();
	CancelOrderBaseInfoDTO cancelOrderBaseInfoDTO = buildCancelOrderBaseInfo();
	//解约协议需要不体现定金的金额信息
	BigDecimal cancelOrderAmount = cancelOrderBaseInfoDTO.getCancelOrderAmount();
	FundAmountDTO depositAmountDTO = cancelOrderBaseInfoDTO.getFundAmountList().stream().filter(item -> FundTypeEnum.DEPOSIT.getValue().equals(item.getFundType())).findFirst().orElse(null);
	if (depositAmountDTO != null) {
		cancelOrderAmount = cancelOrderAmount.subtract(depositAmountDTO.getTobePaidAmount());
	}
	if (cancelOrderAmount.compareTo(BigDecimal.ZERO) > 0) {
		String collectionTemplate = "3、根据上述费用明细，甲方应于本协议生效后【10】个工作日内，向乙方支付剩余应支付款项共计【%s】元（大写：人民币【%s】）。";
		String needPayAmount = getAmount(cancelOrderAmount);
		String needPayAmountText = getAmountText(cancelOrderAmount);
		result.put("terminalTotalFundInfo", String.format(collectionTemplate, needPayAmount, needPayAmountText));
	} else {
		String needRefundAmount = getAmount(cancelOrderAmount.abs());
		String needRefundAmountText = getAmountText(cancelOrderAmount.abs());
		BankCardInfoDTO bankCardInfo = null;
		LaunchRefundReqDTO launchRefundReqDTO = JSON.parseObject(cancelOrderBaseInfoDTO.getRefundInfo(), LaunchRefundReqDTO.class);
		if (launchRefundReqDTO != null) {
			bankCardInfo = launchRefundReqDTO.getBankCardInfo();
		}
		String bankName = Optional.ofNullable(bankCardInfo)
			.map(BankCardInfoDTO::getBankName)
			.filter(StringUtils::isNotBlank)
			.orElse("/");
		String accountName = Optional.ofNullable(bankCardInfo)
			.map(BankCardInfoDTO::getAccountName)
			.filter(StringUtils::isNotBlank)
			.orElse("/");
		String bankCardNo = Optional.ofNullable(bankCardInfo)
			.map(BankCardInfoDTO::getBankCardNo)
			.filter(StringUtils::isNotBlank)
			.map(cipherService::decrypt)
			.orElse("/");

		Integer refundChannel = Optional.ofNullable(launchRefundReqDTO)
			.map(LaunchRefundReqDTO::getRefundChannel)
			.orElse(null);
		String refundChannelText = getRefundChannelText(refundChannel, cancelOrderAmount);
		String refundTemplate = getRefundTemplate();
		result.put("terminalTotalFundInfo", String.format(refundTemplate, needRefundAmount, needRefundAmountText, refundChannelText, bankName, accountName, bankCardNo));
	}
	return result;
}

