private String getRefundChannelText(Integer refundChannel, BigDecimal cancelOrderAmount) {
	String refundChannelText = "/";
	if (cancelOrderAmount.compareTo(BigDecimal.ZERO) < 0) {
		if (RefundChannelEnum.BACKTRACK.getCode().equals(refundChannel)) {
			//如果是原路退回，退款方式选择第1种，退回到原支付账户
			refundChannelText = "1";
		} else if (RefundChannelEnum.BANK.getCode().equals(refundChannel)) {
			//如果是银行渠道，退款方式选择第2种，退回到指定账户
			refundChannelText = "2";
		} else if (RefundChannelEnum.REFUND_TO_WALLET.getCode().equals(refundChannel)) {
			//其他渠道，退款方式选择第3种，退回到甲方客户端账户余额
			refundChannelText = "3";
		}
	}
	return refundChannelText;
}

private String getAmount(BigDecimal amount) {
	if (amount.compareTo(BigDecimal.ZERO) == 0) {
		return "/";
	}
	return amount.toString();
}

private String getAmountText(BigDecimal amount) {
	if (amount.compareTo(BigDecimal.ZERO) == 0) {
		return "/";
	}
	return (new MoneyConvertUtil(amount.toString())).convert();
}

private String getMainAndChangeContractText(Map<Byte, List<Contract>> signedContractNoMap, ProjectInfoDTO projectInfo) {
	String template = "《%s》（合同编号【%s】）及配套附件、补充协议（合同编号【%s】，如有）等其他相关协议（以下统称“原协议”）。";
	String mainContractName = "/";
	String mainContractNoForMerge = "/";
	String changeContractNoForMerge = "/";

	Byte businessType = commonBusinessService.getBusinessType(projectInfo.getProjectOrderId());
	// 获取小程序类型
	MiniPayChannelAppNameEnum miniProgramType = commonBusinessService.getMiniProgramType(projectInfo.getCustomerHouse().getGbCode());
	String advanceContractNo = signedContractNoMap.getOrDefault(ContractTypeEnum.ADVANCE.getCode(), new ArrayList<>()).stream().map(Contract::getContractNo).collect(Collectors.joining(","));
	String formalContractNo = signedContractNoMap.getOrDefault(ContractTypeEnum.PACKAGE_FORMAL.getCode(), new ArrayList<>()).stream().map(Contract::getContractNo).collect(Collectors.joining(","));
	String changeContractNo = signedContractNoMap.getOrDefault(ContractTypeEnum.PACKAGE_CHANGE.getCode(), new ArrayList<>()).stream().map(Contract::getContractNo).collect(Collectors.joining(","));
	//前置校验
	if (StringUtils.isBlank(advanceContractNo) && StringUtils.isBlank(formalContractNo)) {
		LOGGER.error("生成解约协议，构建合同pdf失败，正签&首期款合同信息都为空，projectOrderId={}", projectInfo.getProjectOrderId());
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "生成解约协议，构建合同pdf失败，正签&首期款合同信息都为空", Level.WARN);
	}
	if (StringUtils.isNotBlank(changeContractNo)) {
		changeContractNoForMerge = changeContractNo;
	}
	//团装处理
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
		mainContractNoForMerge = formalContractNo;
		mainContractName = "家庭居室团体装饰装修合同";
		return String.format(template, mainContractName, mainContractNoForMerge, changeContractNoForMerge);
	}
	//整装局装处理
	if (StringUtils.isNotBlank(formalContractNo)) {
		mainContractNoForMerge = formalContractNo;
		if (MiniPayChannelAppNameEnum.被窝.equals(miniProgramType)) {
			mainContractName = "室内装饰装修工程施工合同";
		} else {
			//圣都模式，整装与局装的正签合同名字不同
			if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
				mainContractName = "家庭居室装饰装修施工合同";
			} else if (BusinessTypeEnum.PART_DECORATE.getCode().equals(businessType)) {
				mainContractName = "住宅局部改造装修施工合同";
			} else if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
				mainContractName = "住宅局部翻新装修施工合同";
			}
		}
	} else {
		mainContractNoForMerge = advanceContractNo;
		if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
			mainContractName = "硬装首期款合同";
		} else {
			mainContractName = "施工首期工程款合同";
		}
	}
	return String.format(template, mainContractName, mainContractNoForMerge, changeContractNoForMerge);
}

private String getDesignContractText(Map<Byte, List<Contract>> signedContractNoMap) {
	String template = "《设计服务协议》（合同编号【%s】）及配套附件、补充协议（合同编号【%s】，如有）";
