	String designChangeContractNo = signedContractNoMap.getOrDefault(ContractTypeEnum.DESIGN_CHANGE.getCode(), new ArrayList<>()).stream().map(Contract::getContractNo).collect(Collectors.joining(","));
	//设计合同和设计变更合同都为空,则不需要拼接设计合同的文本信息
	if (StringUtils.isBlank(designContractNo) && StringUtils.isBlank(designChangeContractNo)) {
