	}
	if (StringUtils.isNotBlank(designContractNo)) {
		designContractNoForMerge = designContractNo;
	}
	if (StringUtils.isNotBlank(designChangeContractNo)) {
		designChangeContractNoForMerge = designChangeContractNo;
