@Service
@Slf4j
public class ProductQueryService {

	@Resource
	private OrderStandardQueryRpc orderStandardQueryRpc;

	/**
	 * 根据变更单号获取报价商品集合
	 */
	public List<ChangeQuotationProductDTO> getChangeQuotationProductDTOS(String projectOrderId, String changeOrderId) {
		// 1. 通过变更单查询商品信息
		HomeProject homeProject = orderStandardQueryRpc.queryHomeProjectAndChangeQuotationSkuList(projectOrderId, changeOrderId);
		ChangeComboQuotationListDTO personalQuotation = Optional.ofNullable(homeProject)
			.map(HomeProject::getMainOrder)
			.map(MainOrder::getCostControl)
			.map(MainOrderModel.CostControl::getChangeQuotationModule)
			.map(ChangeQuotationModule::getPersonalQuotation)
			.orElseThrow(() -> new NrsBusinessException("通过主订单查询商品信息失败"));

		// 2. 获取变更套餐和单品对应的所有的商品
		Stream<ChangeQuotationProductDTO> fromCombos = personalQuotation.getComboList().stream()
			.flatMap(
				combo -> Optional.ofNullable(combo.getQuotationProductList()).orElse(Collections.emptyList()).stream()
			);
		Stream<ChangeQuotationProductDTO> fromQuotationList = personalQuotation.getQuotationList().stream();

		return Stream.concat(fromCombos, fromQuotationList)
			.filter(Objects::nonNull).collect(Collectors.toList());
	}

	/**
	 * 根据主单号 + 报价单号获取报价商品集合
	 */
	public List<QuotationProductDTO> getQuotationProductDTOS(String projectOrderId, List<String> billCodeList) {
		List<QuotationProductDTO> res = new ArrayList<>();
		if (CollectionUtils.isEmpty(billCodeList)) {
			return res;
		}
		for (String billCode : billCodeList) {
			// 1. 通过报价单查询商品信息
			HomeProject homeProject = orderStandardQueryRpc.queryHomeProjectAndQuotationSkuList(projectOrderId, billCode);
			ComboQuotationListDTO personalQuotation = Optional.ofNullable(homeProject)
				.map(HomeProject::getMainOrder)
				.map(MainOrder::getCostControl)
				.map(MainOrderModel.CostControl::getQuotationModule)
				.map(QuotationModule::getPersonalQuotation)
				.orElseThrow(() -> new NrsBusinessException("通过主订单查询商品信息失败"));

			// 2. 获取套餐和单品对应的所有的商品
			Stream<QuotationProductDTO> fromCombos = personalQuotation.getComboList().stream()
				.flatMap(
					combo -> Optional.ofNullable(combo.getQuotationProductList()).orElse(Collections.emptyList()).stream()
				);
			Stream<QuotationProductDTO> fromQuotationList = personalQuotation.getQuotationList().stream();

			res.addAll(Stream.concat(fromCombos, fromQuotationList)
				.filter(Objects::nonNull).collect(Collectors.toList()));
		}
		return res;
	}

}

