public interface ContractSigningSource {

	Integer bindType();

	/**
	 * 从主订单获取个性化报价
	 */
	List<ContractSourceDataBO.PersonalContractData> queryPersonalQuoteInfo(BindOrderInfo bindOrderInfo);

	/**
	 * 判断是否包含无效状态的单据
	 */
	boolean hasInvalidStatusOrders(BindOrderInfo bindOrderInfo);

	/**
	 * 构造商品信息
	 */
	Map<String, String> buildGoodsInfo(BindOrderInfo bindOrderInfo);

	/**
	 * 单独发起销售合同弹窗：构造可签约单据（仅供选择基础报价单+S单）
	 */
	List<SignableOrderInfo> buildSignableOrderInfos(String projectOrderId);

	/**
	 * 销售合同发起前校验：创建/编辑销售合同时，会校验是否存在可签约的 S 单。
	 */
	boolean checkPersonalCanCreate(String projectOrderId);

	/**
	 * 构建个性化图纸 List
	 * 原逻辑：com.ke.utopia.nrs.salesproject.rpc.atom.AtomDrawingRpc#getPersonalDrawingImgList
	 */
	List<String> buildPersonalDrawingImgList(BindOrderInfo bindOrderInfo);

	/**
	 * 构建个性化图纸
	 * 原逻辑：com.ke.utopia.nrs.salesproject.rpc.atom.AtomDrawingRpc#getPersonalDrawing(java.lang.String, java.lang.String, java.util.List)
	 */
	DrawingDTO.DeliverDrawingDTO buildPersonalDrawing(BindOrderInfo bindOrderInfo, Boolean softConfigList, Boolean needMergePdf);

	/**
	 * 是否包含 C 部分的品
	 */
	boolean hasCPart(BindOrderInfo bindOrderInfo);

	/**
	 * 是否包含 B 部分的品
	 */
	boolean hasBPart(BindOrderInfo bindOrderInfo);
}

