@Component
@Slf4j
public class BaseContractPdfCreateService {

	@Resource
	private ContractFileInfoService contractFileInfoService;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Resource
	private FreeformService freeformService;

	@Resource
	private ContractPdfFileHandleService contractPdfFileHandleService;

	@Resource
	private ContractPdfCreateService contractPdfCreateService;

	@Resource
	private ContractCustomAttachConfigRepository contractCustomAttachConfigService;

	/**
	 * 获取文本部分合同pdf，返回值pdf链接为本地链接
	 */
	public String getTextPdfUrl(Contract contract, ContractCityCompanyInfo config, boolean finalVersion) throws IOException {
		//正签文本部分合同pdf
		String formalTextPdfUrl = contractPdfCreateService.createPdfByFreeformOnlyGetPdfUrl(contract, config,finalVersion);
		LOGGER.info("contractCode:{},正签文本部分合同pdf链接：{}", contract.getContractCode(),formalTextPdfUrl);
		String tempPath= contract.getProjectOrderId()+"formalText"+ UUID.randomUUID()+".pdf";
		contractPdfFileHandleService.downloadFileFromUrl(formalTextPdfUrl, tempPath);
		return tempPath;
	}

	/**
	 * 获取正签报价单pdf链接，返回值pdf链接为本地链接
	 */
	public String getFormalBudgetUrlPdf(Contract contract, String jiaFangSealKeyword, String yiFangSealKeyword,String jiaFangAgentSealKeyword) throws IOException {
		//获取正签报价单
		String sourceBudgetPdfUrl = getSourceBudget();
		LOGGER.info("contractCode:{},报价单pdf链接：{}", contract.getContractCode(),sourceBudgetPdfUrl);
		String tempPath = UUID.randomUUID() + ".pdf";
		contractPdfFileHandleService.downloadFileFromUrl(sourceBudgetPdfUrl, tempPath);
		//文件大小 单位MB
		BigDecimal budgetPdfSizeMB = IOUtils.getFileSizeMByFilePath(tempPath);
		//报价单pdf文件大小大于5MB需要进行报价单压缩
		if (budgetPdfSizeMB.compareTo(BigDecimal.valueOf(contractApolloConfig.getFormalLaunchConfig().getCompressSize())) > 0) {
			//压缩后的文件路径
			String tempPathAfterCompress = UUID.randomUUID() + ".pdf";
			try {
				LOGGER.info("contractCode:{},报价单pdf文件大小大于5MB，开始进行压缩处理", contract.getContractCode());
				contractPdfFileHandleService.compressPDF(tempPath, tempPathAfterCompress, 120);
				LOGGER.info("contractCode:{},报价单pdf文件大小大于5MB，压缩处理完成", contract.getContractCode());
				//记录报价单pdf文件大小(压缩前压缩后)
				contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.FORMAL_QUOTE.getCode(), IOUtils.getFileSizeKBByFilePath(tempPath), IOUtils.getFileSizeKBByFilePath(tempPathAfterCompress));
				//写盖章关键字
				return addFooter(tempPathAfterCompress, jiaFangSealKeyword, yiFangSealKeyword, jiaFangAgentSealKeyword,"报价单",false);
			}  finally {
				// 删除临时文件
				ContractPdfFileHandleService.cleanUp(Collections.singletonList(tempPath));
			}
		} else {
			//记录报价单pdf文件大小
			contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.FORMAL_QUOTE.getCode(),IOUtils.getFileSizeKBByFilePath(tempPath),null);
			//写盖章关键字
			return addFooter(tempPath, jiaFangSealKeyword, yiFangSealKeyword, jiaFangAgentSealKeyword, "报价单", false);
		}
	}


	/**
	 * 发起签约获取正签报价单
	 */
	private String getSourceBudget() {
		List<PlanAttachmentDTO> list = ContractContextHandler.getPlanAllDTO().getPlanAttachmentList();
		if (CollectionUtils.isEmpty(list)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "报价单生成失败，无法发起签约，请先工单联系运营");
		}
		PlanAttachmentDTO attachmentDTO = list.stream().filter(planAttachmentDTO -> planAttachmentDTO.getFileType().equals(PlanAttachment.报价单))
			.findFirst()
			.orElse(null);
		if (attachmentDTO == null || StringUtils.isBlank(attachmentDTO.getFileUrl())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "报价单生成失败，无法发起签约，请先工单联系运营~");
		}
		return attachmentDTO.getFileUrl();
	}


	/**
	 * pdf文件最后一页写入关键字
	 * @param sourceFilePath 原始pdf文件路径
	 * @param keyWordJiaFang 甲方关键字
	 * @param keyWordYiFang 乙方关键字
	 * @param keyWordJiaFangAgent 甲方代理人关键字
	 * @param fileTypeName 文件类型名称
	 * @param addToAllPages 是否添加到所有页
	 * @return 返回写入关键字后的pdf文件路径
	 */
	public String addFooter(String sourceFilePath, String keyWordJiaFang,  String keyWordYiFang, String keyWordJiaFangAgent,String fileTypeName, boolean addToAllPages) {
		FormalLaunchConfig formalLaunchConfig = contractApolloConfig.getFormalLaunchConfig();
		List<AddFooterTextInfo> addFooterTextInfoList = new ArrayList<>();
		addFooterTextInfoList.add(AddFooterTextInfo.builder()
			.text(keyWordJiaFang)
			.positionXRatio(formalLaunchConfig.getPositionXRatioJiaFang())
			.positionYRatio(formalLaunchConfig.getPositionYRatioJiaFang())
			.build());
		addFooterTextInfoList.add(AddFooterTextInfo.builder()
			.text(keyWordYiFang)
			.positionXRatio(formalLaunchConfig.getPositionXRatioYiFang())
			.positionYRatio(formalLaunchConfig.getPositionYRatioYiFang())
			.build());
		if (StringUtils.isNotBlank(keyWordJiaFangAgent)) {
			addFooterTextInfoList.add(AddFooterTextInfo.builder()
				.text(keyWordJiaFangAgent)
				.positionXRatio(formalLaunchConfig.getPositionXRatioJiaFangAgent())
				.positionYRatio(formalLaunchConfig.getPositionYRatioJiaFangAgent())
				.build());
		}
		String tempPathAfterAddFooter = UUID.randomUUID() + ".pdf";
		try {
			ContractPdfFileHandleService.addFooter(sourceFilePath, tempPathAfterAddFooter, addFooterTextInfoList, addToAllPages);
		} catch (Exception e) {
			LOGGER.info("{},添加文字失败,原因:{}", fileTypeName, e.getMessage());
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "正签合同附件添加文字失败", Level.WARN);
		} finally {
			// 删除临时文件
			ContractPdfFileHandleService.cleanUp(Collections.singletonList(sourceFilePath));
		}
		return tempPathAfterAddFooter;
	}

	/**
	 * 获取甲方签章关键字
	 */
	public String getJiaFangSealKeyword(List<SealNewRuleParam> sealNewRuleParams, Long formId) {
		//签章关键字获取，由于个人签约&对公签约的关键字一样，这里取个人签约配置的关键字
		SealNewRuleParam sealNewRuleParam = sealNewRuleParams.stream().filter(item -> FreeFormRoleTypeEnum.SIGN_USER.getCode().equals(item.getRoleType()))
			.filter(item -> FreeFormSignTypeEnum.PERSON.getCode().equals(item.getSignType())).findFirst().orElse(null);
		if (sealNewRuleParam == null || org.springframework.util.CollectionUtils.isEmpty(sealNewRuleParam.getRuleList())) {
			LOGGER.error("合同生成pdf，获取甲方签章关键字失败，formId：{},签章规则：{}", formId, JSON.toJSONString(sealNewRuleParam));
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "合同生成pdf，获取甲方关键字失败", Level.WARN);
		}
		return sealNewRuleParam.getRuleList().get(0).getKeyword();
