	/**
	 * 获取甲方代理人签章关键字
	 */
	public String getJiaFangAgentSealKeyword(List<SealNewRuleParam> sealNewRuleParams, Long formId) {
		SealNewRuleParam sealNewRuleParam = sealNewRuleParams.stream().filter(item -> FreeFormRoleTypeEnum.SIGN_AGENT.getCode().equals(item.getRoleType()))
			.filter(item -> FreeFormSignTypeEnum.PERSON.getCode().equals(item.getSignType())).findFirst().orElse(null);
		if (sealNewRuleParam == null || org.springframework.util.CollectionUtils.isEmpty(sealNewRuleParam.getRuleList())) {
