	/**
	 * 获取乙方签章关键字
	 */
	public String getYiFangSealKeyword(List<SealNewRuleParam> sealNewRuleParams, Long formId) {
		//乙方签章关键字获取
		SealNewRuleParam sealNewRuleParam = sealNewRuleParams.stream().filter(item -> FreeFormRoleTypeEnum.DECORATION_COMPANY.getCode().equals(item.getRoleType()))
			.filter(item -> FreeFormSignTypeEnum.COMPANY.getCode().equals(item.getSignType())).findFirst().orElse(null);
		if (sealNewRuleParam == null || org.springframework.util.CollectionUtils.isEmpty(sealNewRuleParam.getRuleList())) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "合同生成pdf，获取乙方签章关键字失败", Level.WARN);
		}
		return sealNewRuleParam.getRuleList().get(0).getKeyword();
