@Component
@Slf4j
public class GroupFormalContractPdfBySelfStrategy extends BaseContractPdfCreateService implements CreateContractPdfBySelfStrategy {
	@Resource
	private S3Service s3Service;

	@Resource
	private ContractBusinessService contractBusinessService;

	@Resource
	private ContractFileInfoService contractFileInfoService;


	@Resource
	private FreeformService freeformService;

	@Resource
	private  ContractPdfFileHandleService contractPdfFileHandleService;


	@Override
	public String createPdf(Contract contract, ContractCityCompanyInfo config, boolean finalVersion) throws IOException {
		return groupFormalContractCreate(contract, config, finalVersion);
	}

	/**
	 * 团装正式合同生成
	 *
	 * 团装2.5正签合同附件拼接顺序
	 * 1、正签文本部分合同pdf
	 * 2、报价单(需要写关键字，最后一页)
	 * 3、精装细则(需要写关键字，最后一页)【去除，2025年05月09日】
	 * 4、基础图纸(每一页)
	 *
	 */
	private String groupFormalContractCreate(Contract contract, ContractCityCompanyInfo config, boolean finalVersion) throws IOException{
		StopWatch stopWatch = new StopWatch();
		stopWatch.start();//计时开始
		//合并后pdf路径
		String formalLocalContractPdf = "formalContract_" + UUID.randomUUID() + ".pdf";
		List<SealNewRuleParam> sealNewRule = freeformService.queryNewSealConfigs(Long.valueOf(config.getFormId()));
		String jiaFangSealKeyword = getJiaFangSealKeyword(sealNewRule, Long.valueOf(config.getFormId()));
		String yiFangSealKeyword = getYiFangSealKeyword(sealNewRule, Long.valueOf(config.getFormId()));

		String formalTextPdf = getTextPdfUrl(contract, config,finalVersion);
		LOGGER.info("团装-正式套餐合同自定义生成合同pdf,正签文本部分合同pdf处理完成，contractCode：{}", contract.getContractCode());

		String budgetUrlPdf = getFormalBudgetUrlPdf(contract,jiaFangSealKeyword, yiFangSealKeyword,null);
		LOGGER.info("团装-正式套餐合同自定义生成合同pdf,报价单处理完成，contractCode：{}", contract.getContractCode());

		String groupDrawingPdf = getGroupDrawing(contract,jiaFangSealKeyword, yiFangSealKeyword);
		LOGGER.info("团装-正式套餐合同自定义生成合同pdf,图纸处理完成，contractCode：{}", contract.getContractCode());

		String customAttachPdf = getCustomAttach(contract);
		LOGGER.info("正式套餐合同自定义生成合同pdf, 个性化附件处理完成, contractCode:{}, customeAttachPdf: {}", contract.getContractCode(), customAttachPdf);

		List<String> comporessPdfList = new ArrayList<>();
		//临时文件目录记录，删除时使用
		List<String> tempFiles = new ArrayList<>();
		tempFiles.add(formalLocalContractPdf);
		addFileToLists(formalTextPdf, comporessPdfList, tempFiles);
		addFileToLists(budgetUrlPdf, comporessPdfList, tempFiles);
		addFileToLists(groupDrawingPdf, comporessPdfList, tempFiles);
		if (StringUtils.isNotBlank(customAttachPdf)) {
			addFileToLists(customAttachPdf, comporessPdfList, tempFiles);
		}
		try {
			//pdf合并
			ContractPdfFileHandleService.mergePdfs(comporessPdfList, formalLocalContractPdf);
			File file = new File(formalLocalContractPdf);
			String fileObjectKey = s3Service.md5FileName(file.getName()) + ".pdf";
			LOGGER.info("团装-正式套餐合同自定义生成合同pdf,上传s3开始，contractCode：{}", contract.getContractCode());
			//pdf文件上传到s3
			s3Service.uploadByFile(file, fileObjectKey, false);
			String formalS3PdfUrl = s3Service.generateUrl(fileObjectKey, 604800);
			LOGGER.info("团装-正式套餐合同自定义生成合同pdf,上传s3完成，contractCode：{}", contract.getContractCode());
			//pdf文件上传到协议平台，与协议平台实例关联
			LOGGER.info("团装-正式套餐合同自定义生成合同pdf,上传协议平台开始，contractCode：{}", contract.getContractCode());
			Long instanceId = contractBusinessService.uploadPdfToFreeForm(contract, formalS3PdfUrl, config.getFormKey());
			LOGGER.info("团装-正式套餐合同自定义生成合同pdf,上传协议平台完成，contractCode：{}", contract.getContractCode());
			contract.setPreviewKey(fileObjectKey);
			contract.setPdfPageCount(ContractPdfFileHandleService.getPdfCount(formalLocalContractPdf));
			contract.setPlatformInstanceId(instanceId);
			contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.PACKAGE_FORMAL_CONTRACT.getCode(),IOUtils.getFileSizeKBByFilePath(formalLocalContractPdf),null);
			stopWatch.stop(); // 停止计时
			LOGGER.info("团装-合同pdf生成-正式套餐合同自定义生成合同pdf,生成正式套餐合同pdf完成，contractCode：{},耗时：{}", contract.getContractCode(), stopWatch.getTotalTimeSeconds());
			return formalS3PdfUrl;
		} finally {
			// 删除临时文件
			ContractPdfFileHandleService.cleanUp(tempFiles);
		}
	}

	// 添加文件到两个列表的方法
	private void addFileToLists(String filePath, List<String> comporessList, List<String> tempList) {
		if (StringUtils.isNotBlank(filePath)) {
			comporessList.add(filePath);
			tempList.add(filePath);
		}
	}


	/**
	 * 团装图纸pdf获取
	 *
	 * @return
	 */
	private String getGroupDrawing(Contract contract,String jiaFangSealKeyword,String yiFangSealKeyword) throws IOException {
		DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = ContractContextHandler.getDrawingDTO();
		if (deliverDrawingDTO == null || org.springframework.util.CollectionUtils.isEmpty(deliverDrawingDTO.getDrawingDetailDTOList())) {
			return "";
		}
		//图纸合同机器pdf路径
		String drawingLocalContractPdf = "drawingContract_" + UUID.randomUUID() + ".pdf";
		List<String> drawingList = deliverDrawingDTO.getDrawingDetailDTOList().stream()
			.filter(item -> DrawingEnum.ConstructionFileExtensionEnum.PDF.getCode().equals(item.getExtensionType()))
			.filter(item -> ObjectUtil.equals(PlanAttachment.全屋图纸, item.getFileBizType()))
			.map(DrawingDTO.DrawingDetailDTO::getUrl)
			.collect(Collectors.toList());
		double spaceSizeMB = (double) IOUtils.calculateTotalFileSizeByUrl(drawingList) / 1024;
		// 如果文件大于5MB，进行压缩
		if (spaceSizeMB < 5) {
			LOGGER.info("图纸合同pdf文件大小小于5MB，不进行压缩处理,文件大小：{}MB", spaceSizeMB);
			List<String> tempPathList = new ArrayList<>();
			for (String pdfUrl : drawingList) {
				String tempPath = UUID.randomUUID() + ".pdf";
				// 下载文件到本地
				contractPdfFileHandleService.downloadFileFromUrl(pdfUrl, tempPath);
				tempPathList.add(tempPath);
			}
			// 输出最终合并文件
			ContractPdfFileHandleService.mergePdfs(tempPathList, drawingLocalContractPdf);
			contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.BASE_DRAWING.getCode(), IOUtils.getFileSizeKBByFilePath(drawingLocalContractPdf),null);
		} else {
			List<String> compressPdfList = contractPdfFileHandleService.batchCompressPdf(drawingList, 90);
			// 输出最终合并文件
			ContractPdfFileHandleService.mergePdfs(compressPdfList, drawingLocalContractPdf);
			contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.BASE_DRAWING.getCode(), new BigDecimal(String.valueOf(spaceSizeMB)).multiply(new BigDecimal(1024)).setScale(2, RoundingMode.HALF_UP),
				IOUtils.getFileSizeKBByFilePath(drawingLocalContractPdf));
			LOGGER.info("图纸合同pdf文件大小大于5MB，进行压缩处理,原始文件大小：{}MB，压缩后文件大小：{}MB", spaceSizeMB, IOUtils.getFileSizeMByFilePath(drawingLocalContractPdf));
		}
		//写盖章关键字
		return addFooter(drawingLocalContractPdf, jiaFangSealKeyword, yiFangSealKeyword, null, "团装基础图纸", true);
	}




}

