@AiDoc(
    summary = "整装正签合同PDF自生成策略",
    description = "不走协议平台生成PDF，由系统内部自行拼接。拼接顺序：正签文本部分→精装细则→预算编制说明→材料配送清单→报价单。与翻新全案(ReformAll)的区别是本类处理整装业务。"
)
@Component
@Slf4j
public class HouseFormalContractPdfBySelfStrategy extends BaseContractPdfCreateService  implements CreateContractPdfBySelfStrategy{

	@Resource
	private ComboInfoService comboInfoService;
	@Resource
	private S3Service s3Service;

	@Resource
	private ContractBusinessService contractBusinessService;

	@Resource
	private ContractFileInfoService contractFileInfoService;

	@Resource
	private FreeformService freeformService;

	@Resource
	private  ContractPdfFileHandleService contractPdfFileHandleService;

	@Resource
	private CommonContractService commonContractService;


	@Override
	public String createPdf(Contract contract, ContractCityCompanyInfo config, boolean finalVersion) throws IOException {
		return houseFormalContractCreate(contract, config, finalVersion);
	}

	/**
	 * 整装正签合同pdf生成
	 * 	 整装正签合同附件拼接顺序
	 * 	 1、正签文本部分合同pdf
	 * 	 2、精装细则(需要写关键字，最后一页)
	 * 	 3、预算编制说明(不需要写关键字)
	 * 	 4、材料配送清单(不需要写关键字)
	 * 	 5、报价单 (需要写关键字，最后一页)
	 */
	private String houseFormalContractCreate(Contract contract, ContractCityCompanyInfo config, boolean finalVersion)throws IOException{
		StopWatch stopWatch = new StopWatch();
		stopWatch.start();//计时开始
		//合并后pdf路径
		String formalLocalContractPdf = "formalContract_" + UUID.randomUUID() + ".pdf";
		List<SealNewRuleParam> sealNewRule = freeformService.queryNewSealConfigs(Long.valueOf(config.getFormId()));
		String jiaFangSealKeyword = getJiaFangSealKeyword(sealNewRule, Long.valueOf(config.getFormId()));
		String yiFangSealKeyword = getYiFangSealKeyword(sealNewRule, Long.valueOf(config.getFormId()));
		String jiaFangAgentSealKeyword = getJiaFangAgentSealKeyword(sealNewRule, Long.valueOf(config.getFormId()));
		LOGGER.info("正式套餐合同自定义生成合同pdf,开始生成正式套餐合同pdf，contractCode：{}", contract.getContractCode());
		String formalTextPdf = getTextPdfUrl(contract, config,finalVersion);
		LOGGER.info("正式套餐合同自定义生成合同pdf,正签文本部分合同pdf处理完成，contractCode：{}", contract.getContractCode());
		List<String> comboCodesByPlanAllDTO = commonContractService.getComboCodesByPlanAllDTO(ContractContextHandler.getPlanAllDTO());
		List<String> decorateRulePdfs = new ArrayList<>();
		for (int i = 0; i < comboCodesByPlanAllDTO.size(); i++) {
			String comboCode = comboCodesByPlanAllDTO.get(i);
			String decorateRulePdf = getDecorateRulePdf(contract, jiaFangSealKeyword, yiFangSealKeyword, jiaFangAgentSealKeyword, comboCode, i == comboCodesByPlanAllDTO.size() - 1);
			decorateRulePdfs.add(decorateRulePdf);
		}
		LOGGER.info("正式套餐合同自定义生成合同pdf,精装细则处理完成，contractCode：{}", contract.getContractCode());
		List<String> budgetDescPdfs = new ArrayList<>();
		for (String comboCode : comboCodesByPlanAllDTO) {
			String budgetRulePdf = getBudgetRulePdf(contract, comboCode);
			budgetDescPdfs.add(budgetRulePdf);
		}
		LOGGER.info("正式套餐合同自定义生成合同pdf,预算编制说明处理完成，contractCode：{}", contract.getContractCode());
		List<String> materialPdfs = new ArrayList<>();
		for (String comboCode : comboCodesByPlanAllDTO) {
			String materialPdf = getMaterialPdf(contract, comboCode);
			materialPdfs.add(materialPdf);
		}
		LOGGER.info("正式套餐合同自定义生成合同pdf,材料配送清单处理完成，contractCode：{}", contract.getContractCode());
		String budgetUrlPdf = getFormalBudgetUrlPdf(contract, jiaFangSealKeyword, yiFangSealKeyword, jiaFangAgentSealKeyword);
		LOGGER.info("正式套餐合同自定义生成合同pdf,报价单处理完成，contractCode：{}", contract.getContractCode());
		String customAttachPdf = getCustomAttach(contract);
		LOGGER.info("正式套餐合同自定义生成合同pdf, 个性化附件处理完成, contractCode:{}, customeAttachPdf: {}", contract.getContractCode(), customAttachPdf);
		List<String> comporessPdfList = new ArrayList<>();
		//临时文件目录记录，删除时使用
		List<String> tempFiles = new ArrayList<>();
		tempFiles.add(formalLocalContractPdf);
		addFileToLists(formalTextPdf, comporessPdfList, tempFiles);
		for (String decorateRulePdf : decorateRulePdfs) {
			addFileToLists(decorateRulePdf, comporessPdfList, tempFiles);
		}
		for (String budgetDescPdf : budgetDescPdfs) {
			addFileToLists(budgetDescPdf, comporessPdfList, tempFiles);
		}
		for (String materialPdf : materialPdfs) {
			addFileToLists(materialPdf, comporessPdfList, tempFiles);
		}
		addFileToLists(budgetUrlPdf, comporessPdfList, tempFiles);
		if (StringUtils.isNotBlank(customAttachPdf)) {
			addFileToLists(customAttachPdf, comporessPdfList, tempFiles);
		}
		try {
			//pdf合并
			ContractPdfFileHandleService.mergePdfs(comporessPdfList, formalLocalContractPdf);
			File file = new File(formalLocalContractPdf);
			String fileObjectKey = s3Service.md5FileName(file.getName()) + ".pdf";
			LOGGER.info("正式套餐合同自定义生成合同pdf,上传s3开始，contractCode：{}", contract.getContractCode());
			//pdf文件上传到s3
			s3Service.uploadByFile(file, fileObjectKey, false);
			String formalS3PdfUrl = s3Service.generateUrl(fileObjectKey, 604800);
			LOGGER.info("正式套餐合同自定义生成合同pdf,上传s3完成，contractCode：{}", contract.getContractCode());
			//pdf文件上传到协议平台，与协议平台实例关联
			LOGGER.info("正式套餐合同自定义生成合同pdf,上传协议平台开始，contractCode：{}", contract.getContractCode());
			Long instanceId = contractBusinessService.uploadPdfToFreeForm(contract, formalS3PdfUrl, config.getFormKey());
			LOGGER.info("正式套餐合同自定义生成合同pdf,上传协议平台完成，contractCode：{}", contract.getContractCode());
			contract.setPreviewKey(fileObjectKey);
			contract.setPdfPageCount(ContractPdfFileHandleService.getPdfCount(formalLocalContractPdf));
			contract.setPlatformInstanceId(instanceId);
			contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.PACKAGE_FORMAL_CONTRACT.getCode(),IOUtils.getFileSizeKBByFilePath(formalLocalContractPdf),null);
			stopWatch.stop(); // 停止计时
			LOGGER.info("合同pdf生成-正式套餐合同自定义生成合同pdf,生成正式套餐合同pdf完成，contractCode：{},耗时：{}", contract.getContractCode(), stopWatch.getTotalTimeSeconds());
			return formalS3PdfUrl;
		} finally {
			// 删除临时文件
			ContractPdfFileHandleService.cleanUp(tempFiles);
		}
	}


	/**
	 * 获取精装细则pdf链接，返回值pdf链接为本地链接
	 */
	public String getDecorateRulePdf(Contract contract, String jiaFangSealKeyword, String yiFangSealKeyword,String jiaFangAgentSealKeyword, String comboCode, boolean addFooter) throws IOException {
