	}
	String tempPath = contract.getProjectOrderId()+"budgetRule" + UUID.randomUUID() + ".pdf";
	contractPdfFileHandleService.downloadFileFromUrl(pdfUrl, tempPath);
	//记录预算编制说明文件大小
	contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.BUDGET_DESC.getCode(),IOUtils.getFileSizeKBByFilePath(tempPath),null);
	return tempPath;
}

public String getMaterialPdf(Contract contract, String comboCode) throws IOException {
	ContractComboFileInfoDTO materialInfo = comboInfoService.getMaterialList(contract.getProjectOrderId(), contract.getType(), comboCode);
	if (CollectionUtils.isEmpty(materialInfo.getImgUrls())) {
		return "";
	}
	String pdfUrl = materialInfo.getPdfUrl();
	LOGGER.info("contractCode:{},材料配送清单pdf链接：{}", contract.getContractCode(),pdfUrl);
	if (StringUtils.isBlank(pdfUrl)) {
		LOGGER.error("签约-生成正式套餐合同获取到材料配送清单pdf链接为空");
		throw new NrsBusinessException("签约-生成正式套餐合同获取到材料配送清单pdf链接为空", Level.WARN);
