	String tempPath = contract.getProjectOrderId()+"material" + UUID.randomUUID() + ".pdf";
	contractPdfFileHandleService.downloadFileFromUrl(pdfUrl, tempPath);
	//记录材料配送清单文件大小
	contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.MATERIAL_LIST.getCode(),IOUtils.getFileSizeKBByFilePath(tempPath),null);
	return tempPath;
}

private void addFileToLists(String filePath, List<String> comporessList, List<String> tempList) {
