@Slf4j
@Service
public class ComboInfoService {
	@Resource
	private ContractComboInfoService contractComboInfoService;

	@Resource
	private ContractService contractService;

	@Resource
	private ContractNodeService contractNodeService;

	@Resource
	private ContractFieldService contractFieldService;

	@Resource
	private ContractApolloConfig contractApolloConfig;
	@Autowired
	private ContractUnifyService contractUnifyService;

	@Resource
	private ContractFileInfoRecordService contractFileInfoRecordService;


	/**
	 * 根据时间和套餐code获取当时最新的套餐配置（异常场景：不存在则返回最新一份）
	 *
	 * @param signDate  首期款合同签约时间
	 * @param comboCode 套餐code
	 */
	public ContractComboInfo getContractComboInfoBySignDate(Date signDate, String comboCode, Byte contractFormType) {
		List<ContractComboInfo> contractComboInfoList = contractComboInfoService.getContractComboInfoWithDefaultConfig(comboCode, contractFormType);
		if (CollectionUtils.isEmpty(contractComboInfoList)) {
			throw new NrsBusinessException(String.format("套餐【%s】【%s】配置不存在", comboCode, contractFormType));
		}
		//获取第一个小于等于date的配置
		ContractComboInfo contractComboInfo = contractComboInfoList.stream().filter(contractComboInfo1 -> contractComboInfo1.getCtime().before(signDate)).max(Comparator.comparing(ContractComboInfo::getCtime)).orElse(null);
		if (ObjectUtil.isEmpty(contractComboInfo)) {
			//获取最新的配置
			return contractComboInfoList.stream().max(Comparator.comparing(ContractComboInfo::getCtime)).orElse(null);
		} else {
			return contractComboInfo;
		}
	}

	/**
	 * 根据时间和套餐code获取当时最新的套餐配置（异常场景：不存在则返回最新一份）
	 *
	 * @param signDate  首期款合同签约时间
	 * @param comboCode 套餐code
	 */
	public ContractComboInfo getContractComboInfoBySignDateNullable(Date signDate, String comboCode, Byte contractFormType) {
		List<ContractComboInfo> contractComboInfoList = contractComboInfoService.getContractComboInfoWithDefaultConfig(comboCode, contractFormType);
		if (CollectionUtils.isEmpty(contractComboInfoList)) {
			return null;
		}
		//获取第一个小于等于date的配置
		ContractComboInfo contractComboInfo = contractComboInfoList.stream().filter(contractComboInfo1 -> contractComboInfo1.getCtime().before(signDate)).max(Comparator.comparing(ContractComboInfo::getCtime)).orElse(null);
		if (ObjectUtil.isEmpty(contractComboInfo)) {
			//获取最新的配置
			return contractComboInfoList.stream().max(Comparator.comparing(ContractComboInfo::getCtime)).orElse(null);
		} else {
			return contractComboInfo;
		}
	}

	/**
	 * 获取套餐最新的配置版本
	 *
	 * @param comboCode
	 * @return
	 */
	public ContractComboInfo getLatestContractComboInfo(String comboCode, Byte contractFormType) {
		return contractComboInfoService.getLatestContractComboInfoWithDefaultConfig(comboCode, contractFormType);
	}

	/**
	 * 根据项目单号、合同类型、套餐code获取套餐配置信息
	 */
	public ContractComboInfo getContractComboInfo(String projectOrderId, Byte contractType, String comboCode, Byte contractFormType) {
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)||ContractTypeEnum.OTHER_ATTACH.getCode().equals(contractType)) {
			//查询是否存在首期款合同
			Contract latestContract = contractService.getLatestContract(projectOrderId, ContractTypeEnum.ADVANCE.getCode());
			if (ObjectUtil.isEmpty(latestContract)) {
				return contractComboInfoService.getLatestContractComboInfoWithDefaultConfig(comboCode, contractFormType);
			}
			//获取合同最新一次签约时间节点
			List<ContractNode> listByContractCodesAndType = contractNodeService.getListByContractCodesAndType(Arrays.asList(latestContract.getContractCode()), NodeTypeEnum.SIGNED_NODE_LIST);
			//获取id最大的节点
			if (CollectionUtils.isEmpty(listByContractCodesAndType)) {
				throw new NrsBusinessException(String.format("项目【%s】首期款签约完成合同节点不存在", projectOrderId));
			}
			ContractNode contractNode = listByContractCodesAndType.stream().min(Comparator.comparing(ContractNode::getId)).get();
			LocalDateTime date = LocalDateTimeUtil.of(contractNode.getFireTime(), TimeZone.getTimeZone("Asia/Shanghai"));
			// 将LocalDateTime转换为Date
			Date signDate = Date.from(date.atZone(ZoneId.systemDefault()).toInstant());
			//根据首期款签约时间获取当时的正签套餐版本
			return getContractComboInfoBySignDate(signDate, comboCode, contractFormType);

		} else if (ContractTypeEnum.ADVANCE.getCode().equals(contractType) || ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)) {
			return contractComboInfoService.getLatestContractComboInfoWithDefaultConfig(comboCode, contractFormType);
		}
		return null;
	}


	/**
	 * 基于项目单号和套餐code获取对应的url
	 * 精装细则取对应版本、材料配送清单和预算编制说明取最新版本
	 *
	 * @param projectOrderId
	 * @param comboCode
	 * @return
	 */
	public List<String> getAllUrls(String projectOrderId, Byte contractType, String comboCode) {
		Byte contractFormType = getContractFormTypeByProjectOrderId(projectOrderId);
		//获取当时的精装细则
		ContractComboInfo contractComboInfo = getContractComboInfo(projectOrderId, contractType, comboCode, contractFormType);
		LOGGER.info("获取到的套餐精装细则信息为：{}, 项目单号：{}, 合同类型：{}, 套餐code：{}, 合同模式：{}", JSON.toJSONString(contractComboInfo), projectOrderId, contractType, comboCode, contractFormType);
		//获取最新的材料配送清单和预算编制说明
		ContractComboInfo latestContractComboInfo = getLatestContractComboInfo(comboCode, contractFormType);
		LOGGER.info("获取到的套餐最新配置信息为：{}, 项目单号：{}, 合同类型：{}, 套餐code：{}, 合同模式：{}", JSON.toJSONString(latestContractComboInfo), projectOrderId, contractType, comboCode, contractFormType);
		List<String> urls = new ArrayList<>();
		if (Objects.nonNull(contractComboInfo)) {
			if (StringUtils.isNotBlank(contractComboInfo.getDecorateRule())) {
				urls.addAll(getDecorateRule(contractComboInfo).getImgUrls());
			}
			if (StringUtils.isNotBlank(latestContractComboInfo.getBudgetDesc())) {
				urls.addAll(getBudgetDesc(latestContractComboInfo).getImgUrls());
			}
			if (StringUtils.isNotBlank(latestContractComboInfo.getMaterialList())) {
				urls.addAll(getMaterialList(latestContractComboInfo).getImgUrls());
			}
		}
		return urls;
	}

	/**
	 * 获取变更合同对应的url
	 */
	public List<ChangeContractFreeformDTO.Photo> getChangeContractAllUrls(String projectOrderId, Byte businessType, List<String> afterComboCodes) {
		Byte contractFormType = getContractFormTypeByProjectOrderId(projectOrderId);
		// 判断当前正签合同模板内是否包含套餐相关附件（精装细则、预算编制说明书、材料清单配置信息）
		List<ContractFileInfoRecord> fileInfoRecords = contractFileInfoRecordService.getByFileTypes(projectOrderId,
			Arrays.asList(ContractFileTypeEnum.DECORATE_RULE.getCode(), ContractFileTypeEnum.MATERIAL_LIST.getCode(), ContractFileTypeEnum.BUDGET_DESC.getCode()));

		Contract packageFormalContract = contractService.getLatestContract(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		if (packageFormalContract == null) {
			return Collections.emptyList();
		}

		if (SignChannelTypeEnum.ONLINE.getCode().equals(packageFormalContract.getSignChannelType()) && CollectionUtils.isEmpty(fileInfoRecords) && !BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			return Collections.emptyList();
		}

		if (CollectionUtils.isEmpty(afterComboCodes)) {
			return Collections.emptyList();
		}

		List<ContractComboInfo> contractComboInfoList = new ArrayList<>();
		for (String comboCode : afterComboCodes) {
			ContractComboInfo latestContractComboInfo = getLatestContractComboInfo(comboCode, contractFormType);
			contractComboInfoList.add(latestContractComboInfo);
		}

		List<ChangeContractFreeformDTO.Photo> urls = new ArrayList<>();
		String dateStr = DateUtils.getDateStr(new Date());
		// 精装细则
		for (ContractComboInfo contractComboInfo : contractComboInfoList) {
			List<String> imgUrls = getDecorateRule(contractComboInfo).getImgUrls();
			imgUrls.forEach(imgUrl -> urls.add(new ChangeContractFreeformDTO.Photo(imgUrl, dateStr)));
		}
		// 精装细则最后一页签字+盖章
		for (int i = 0; i < urls.size(); i++) {
			if (i == urls.size() - 1) {
				urls.get(i).setApplyStampFlag(Boolean.TRUE);
			}
		}

		// 预算编制说明
		for (ContractComboInfo contractComboInfo : contractComboInfoList) {
			List<String> imgUrls = getBudgetDesc(contractComboInfo).getImgUrls();
			imgUrls.forEach(imgUrl -> urls.add(new ChangeContractFreeformDTO.Photo(imgUrl, dateStr)));
		}
		// 材料配送清单
		for (ContractComboInfo contractComboInfo : contractComboInfoList) {
			List<String> imgUrls = getMaterialList(contractComboInfo).getImgUrls();
			imgUrls.forEach(imgUrl -> urls.add(new ChangeContractFreeformDTO.Photo(imgUrl, dateStr)));
		}

		return urls;
	}

	public ContractComboFileInfoDTO getDecorateRule(String projectOrderId, Byte contractType, String comboCode){
		Byte contractFormType = getContractFormTypeByProjectOrderId(projectOrderId);
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) || ContractTypeEnum.OTHER_ATTACH.getCode().equals(contractType)) {
			//查询是否存在首期款合同
			Contract latestContract = contractService.getLatestContract(projectOrderId, ContractTypeEnum.ADVANCE.getCode());
			//没签署首期款合同带出最新版本精装细则
			if (ObjectUtil.isEmpty(latestContract)) {
				return getDecorateRule(contractComboInfoService.getLatestContractComboInfoWithDefaultConfig(comboCode, contractFormType));
			}

			// 使用旧规则：没签首期款取最新配置，签署首期款取签约时刻之前最新版本配置
			if (contractApolloConfig.getGetDecorateRuleOldRuleCity().contains(latestContract.getGbCode())) {
				ContractComboInfo contractComboInfo = getContractComboInfo(projectOrderId, contractType, comboCode, contractFormType);
				return getDecorateRule(contractComboInfo);
			}

			//获取合同最新一次签约时间节点
			Date signDate = contractNodeService.getListByContractCodesAndType(Collections.singletonList(latestContract.getContractCode()), NodeTypeEnum.SIGNED_NODE_LIST)
				.stream().max(Comparator.comparing(ContractNode::getFireTime))
				.map(node -> LocalDateTimeUtil.of(node.getFireTime(), TimeZone.getTimeZone("Asia/Shanghai")))
				.map(localDateTime -> Date.from(localDateTime.atZone(ZoneId.systemDefault()).toInstant()))
				.orElseThrow(() -> new NrsBusinessException(String.format("项目【%s】首期款签约完成合同节点不存在", projectOrderId)));

			String advanceContractComboCode = getAdvanceComboCode(latestContract.getContractCode());
			ContractComboInfo advanceContractComboInfoBySignDate = getContractComboInfoBySignDateNullable(signDate, advanceContractComboCode, contractFormType);
			// 判断签约时版本有无带出
			boolean isDisplay = SignChannelTypeEnum.ONLINE.getCode().equals(latestContract.getSignChannelType()) && decorateRuleComboConfigContainsType(advanceContractComboInfoBySignDate, ContractTypeEnum.ADVANCE.getCode());
			if (!isDisplay) {
				return getDecorateRule(contractComboInfoService.getLatestContractComboInfoWithDefaultConfig(comboCode, contractFormType));
			}

			//首期款套餐id
			if (StringUtils.equals(comboCode, advanceContractComboCode)) {
				return ContractComboFileInfoDTO.builder().imgUrls(new ArrayList<>()).build();
			}

			//带出20签约时刻前最新版本
			ContractComboInfo contractComboInfoBySignDate = getContractComboInfoBySignDate(signDate, comboCode, contractFormType);
			if (contractComboInfoBySignDate != null) {
				return getDecorateRule(contractComboInfoBySignDate);
			}
			return getDecorateRule(contractComboInfoService.getLatestContractComboInfoWithDefaultConfig(comboCode, contractFormType));

		} else if (ContractTypeEnum.ADVANCE.getCode().equals(contractType) || ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)) {
			ContractComboInfo latestContractComboInfo = contractComboInfoService.getLatestContractComboInfoWithDefaultConfig(comboCode, contractFormType);
			// 配置带出
			if (decorateRuleComboConfigContainsType(latestContractComboInfo, contractType)) {
				return getDecorateRule(latestContractComboInfo);
			}
		}

		return ContractComboFileInfoDTO.builder().imgUrls(new ArrayList<>()).build();
	}

