public ContractComboInfo getContractComboInfo(String projectOrderId, Byte contractType, String comboCode, Byte contractFormType) {
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)||ContractTypeEnum.OTHER_ATTACH.getCode().equals(contractType)) {
		//查询是否存在首期款合同
		Contract latestContract = contractService.getLatestContract(projectOrderId, ContractTypeEnum.ADVANCE.getCode());
		if (ObjectUtil.isEmpty(latestContract)) {
			return contractComboInfoService.getLatestContractComboInfoWithDefaultConfig(comboCode, contractFormType);
		}
		//获取合同最新一次签约时间节点
		List<ContractNode> listByContractCodesAndType = contractNodeService.getListByContractCodesAndType(Arrays.asList(latestContract.getContractCode()), NodeTypeEnum.SIGNED_NODE_LIST);
		//获取id最大的节点
		if (CollectionUtils.isEmpty(listByContractCodesAndType)) {
			throw new NrsBusinessException(String.format("项目【%s】首期款签约完成合同节点不存在", projectOrderId));
		}
		ContractNode contractNode = listByContractCodesAndType.stream().min(Comparator.comparing(ContractNode::getId)).get();
		LocalDateTime date = LocalDateTimeUtil.of(contractNode.getFireTime(), TimeZone.getTimeZone("Asia/Shanghai"));
		// 将LocalDateTime转换为Date
		Date signDate = Date.from(date.atZone(ZoneId.systemDefault()).toInstant());
		//根据首期款签约时间获取当时的正签套餐版本
		return getContractComboInfoBySignDate(signDate, comboCode, contractFormType);

	} else if (ContractTypeEnum.ADVANCE.getCode().equals(contractType) || ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)) {
		return contractComboInfoService.getLatestContractComboInfoWithDefaultConfig(comboCode, contractFormType);
	}
	return null;
}

