@Slf4j
@Service
public class ComboInfoMaterialGenerator {

	@Resource
	private MaterialSelectionQueryService materialSelectionQueryService;

	@Resource
	private MaterialPdfGenerator materialPdfGenerator;

	@Resource
	private ContractComboInfoService contractComboInfoService;

	@Resource
	private AdminService adminService;

	@Resource
	private ComboInfoMaterialGenerator comboInfoMaterialGeneratorSelf;

	@Resource
	private ContractMaterialPdfDataRepository contractMaterialPdfDataRepository;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	/**
	 * 根据传入的 comboCodes 查询实时数据，生成材料清单并插入数据库
	 */
	public Map<String, MaterialPdfData> generateAndReplaceMaterialList(List<String> comboCodes) {
		if (CollectionUtils.isEmpty(comboCodes)) {
			LOGGER.info("生成材料清单-comboCodes为空");
			return Collections.emptyMap();
		}

		LOGGER.info("生成材料清单-开始处理, comboCodes: {}", JSON.toJSONString(comboCodes));

		// 1. 实时查询套餐最新的数据
		ComboSkuQueryParam queryParam = new ComboSkuQueryParam();
		queryParam.setComboIdList(comboCodes);
		List<ComboSkuGroupDTO> comboSkuGroupList = materialSelectionQueryService.queryMaterialComboSkuList(queryParam);

		// 2. 生成材料配送清单 pdf, 返回结果: comboCode -> MaterialPdfData
		Map<String, MaterialPdfData> materialPdfMap = materialPdfGenerator.generateMaterialPdf(comboSkuGroupList);

		LOGGER.info("系统自动生成材料配送清单, apollo 总开关状态: {}", contractApolloConfig.getMaterialListPdfGenerationEnabled());

		// 3. 如果总开关开启，则更新套餐的材料配送清单
		if (contractApolloConfig.getMaterialListPdfGenerationEnabled()) {
			// 4. 更新套餐的材料配送清单
			materialPdfMap.forEach((comboCode, materialPdfData) -> {
				LOGGER.info("更新材料配送清单 - comboCode: {}, materialPdfData: {}", materialPdfData.getComboCode(), materialPdfData);
				comboInfoMaterialGeneratorSelf.updateComboMaterialList(materialPdfData);
			});
			LOGGER.info("生成材料清单-处理完成, 总数量: {}, pdf: {}", materialPdfMap.size(), JSON.toJSONString(materialPdfMap));
		}
		return materialPdfMap;
	}

	/**
	 * 更新套餐的材料配送清单：由于套餐表都是快照数据，“更新”操作实际是“插入”
	 * 同时，将 pdf 对应的数据存储进数据库，用于生成合同时与最新数据进行 diff
	 */
	@Transactional
	public void updateComboMaterialList(MaterialPdfData materialPdfData) {
		// 1. 查询 comboCode 的最新一条数据
		String comboCode = materialPdfData.getComboCode();
		ContractComboInfo normalComboInfo = contractComboInfoService.getLatestContractComboInfo(comboCode, ContractFormTypeEnum.NORMAL_HOUSE.getCode());
		ContractComboInfo developerComboInfo = contractComboInfoService.getLatestContractComboInfo(comboCode, ContractFormTypeEnum.DEVELOPER_CHANNEL.getCode());

		String materialPdfUrl = materialPdfData.getMaterialPdfUrl();
		String materialImageUrls = materialPdfData.getMaterialImageUrls();

		// 3. 插入最新的材料配送清单
		List<ContractComboInfo> toSaveData = new ArrayList<>();

		// 4. 更新材料配送清单的 pdf 和图片
		if (normalComboInfo != null) {
			updateSingleComboMaterialList(normalComboInfo, materialImageUrls, materialPdfUrl);
			toSaveData.add(normalComboInfo);
		}
		if (developerComboInfo != null) {
			updateSingleComboMaterialList(developerComboInfo, materialImageUrls, materialPdfUrl);
			toSaveData.add(developerComboInfo);
		}

		LOGGER.info("系统生成材料配送清单, 待保存套餐配置: {}", JSON.toJSONString(toSaveData));

		// 如果对应套餐在河图未配置，则直接 return，不保存 ContractComboInfo 和 ContractMaterialPdfData
		if (CollectionUtils.isEmpty(toSaveData)) {
			return;
		}

		contractComboInfoService.insertBatch(toSaveData);
		LOGGER.info("系统生成材料配送清单成功, contractComboInfos: {}", JSON.toJSONString(toSaveData));

		// 5. 存储 pdf 的数据
		List<ContractMaterialPdfData> contractMaterialPdfData = buildMaterialPdfData(comboCode, materialPdfData.getMaterialSkus());
		if (CollectionUtils.isNotEmpty(contractMaterialPdfData)) {
			contractMaterialPdfDataRepository.deleteByComboCode(comboCode);
			contractMaterialPdfDataRepository.insertBatch(contractMaterialPdfData);
		}
		LOGGER.info("系统生成材料配送清单成功, contractMaterialPdfData: {}", JSON.toJSONString(contractMaterialPdfData));
	}

	private List<ContractMaterialPdfData> buildMaterialPdfData(String comboCode, List<ComboSkuVO> materialSkus) {
		List<ContractMaterialPdfData> result = new ArrayList<>();

		for (ComboSkuVO sku : materialSkus) {
			result.add(
				ContractMaterialPdfData.builder()
					.comboCode(comboCode)
					.categoryLevel3Code(sku.getCategoryLevel3Code())
					.categoryLevel3Name(sku.getCategoryLevel3Name())
					.brandCode(sku.getBrandCode())
					.brandName(sku.getBrandName())
					.createUserId("1000000030973949")
					.updateUserId("1000000030973949")
					.ctime(new Date())
					.mtime(new Date())
					.delStatus(CommonEnum.NO.getCode())
					.build()
			);
		}

		return result;
	}

	private void updateSingleComboMaterialList(ContractComboInfo comboInfo, String materialImages, String materialPdf) {
		comboInfo.setId(null);
		comboInfo.setMaterialList(materialImages);
		comboInfo.setMaterialListPdfUrl(materialPdf);
		comboInfo.setMaterialListPdfSize(StringUtils.isNotBlank(materialPdf) ? adminService.getPdfSize(materialPdf) : BigDecimal.ZERO);
		comboInfo.setCtime(new Date());
		comboInfo.setMtime(new Date());
		comboInfo.setCreateUserId("1000000099999999");
		comboInfo.setDelStatus(CommonEnum.NO.getCode());
	}

}

