	EventService eventService;
	@Resource
	ContractService contractService;
	@Resource
	ContractBusinessService contractBusinessService;
	@Resource
	ContractUserService contractUserService;
	@Resource
	ContractFieldService contractFieldService;
	@Resource
	S3Service s3Service;
	@Resource
	CustomerFeignService customerFeignService;
	@Resource
	AuthFeignService authFeignService;
	@Resource
	ContractCityCompanyInfoService contractCityCompanyInfoService;
	@Resource
	ContractAttachService contractAttachService;
	@Resource
	CommonContractService commonContractService;
	@Resource
	CommonBusinessService commonBusinessService;
	@Resource
	private ContractCityCompanyConfigService contractCityCompanyConfigService;

	@Resource
	CipherService cipherService;

	@Resource
	FreeformService freeformService;

	@Resource
	ContractApolloConfig contractApolloConfig;

	//不用存储在fields表的字段
	protected List<String> notSaveField = Arrays.asList(FieldEnum.ATTACH.getKey(), FieldEnum.AMOUNT.getKey());

	protected List<String> encryptField = Arrays.asList(FieldEnum.IDNO.getKey(), FieldEnum.PHONE.getKey());

	/**
	 * 校验字段必填
	 */
	public Boolean check(BaseContractDto baseContractDto, ContractCityCompanyInfo config) {
		if (Objects.isNull(SignChannelTypeEnum.getNameByCode(baseContractDto.getSignChannelType()))) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "签约类型(线上/线下)不能为空");
		}
		if (SignChannelTypeEnum.ONLINE.getCode().equals(baseContractDto.getSignChannelType()) && Objects.isNull(baseContractDto.getUserSignType())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "用户签署方式(确认/签字)不能为空");
		}
		return true;
	}

	/**
	 * 唯一性校验
	 */
	public void checkUnique(Byte businessType, String projectOrderId, Byte type, Long excludeId) {
		List<Contract> contractList = contractService.getBaseContractInfo(businessType, projectOrderId, type);
		if (contractList.isEmpty()) {
			return;
		}
		for (Contract contract : contractList) {
			if (!contract.getId().equals(excludeId)) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同类型已经存在，不能创建多份");
			}
		}
	}

	public void checkCompanyCode(String oldCompanyCode, String newCompanyCode) {
		if (!Objects.equals(oldCompanyCode, newCompanyCode)) {
			String errMsg = String.format("合同前后分公司有变化，请作废重新发起，之前:%s, 现在:%s", oldCompanyCode, newCompanyCode);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, errMsg);
		}
	}

	/**
	 * 保存草稿
	 */
	public void saveDraft(BaseContractDto baseContractDto) {
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(baseContractDto.getProjectOrderId());
		//校验分公司&城市信息
		if (Objects.isNull(projectInfoDTO.getCustomerCommission().getCompanyCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前项目缺少分公司信息");
		}
		if (Objects.isNull(projectInfoDTO.getCustomerHouse().getGbCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前项目缺少城市信息");
		}
		String companyCode = projectInfoDTO.getCustomerCommission().getCompanyCode();
		Integer gbCode = projectInfoDTO.getCustomerHouse().getGbCode();
		Byte contractType = baseContractDto.getType();
		Byte userSignType = baseContractDto.getUserSignType();
		Byte signChannelType = baseContractDto.getSignChannelType();
		Byte businessType = commonContractService.getBusinessType(projectInfoDTO);
		//gbCode以查询为准，前端只读
		baseContractDto.setGbCode(gbCode);
		baseContractDto.setGbName(CityEnum.getNameByCode(gbCode));
		//校验合同类型是否配置
		ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfig(projectInfoDTO.getProjectOrderId(),gbCode, companyCode, businessType, contractType, signChannelType, userSignType);
		if (Objects.isNull(config)) {
			String error = String.format("当前合同城市:%d,分公司:%s,合同类型:%d,用户签署方式:%d,签署渠道形式:%d未配置", gbCode, companyCode, contractType, userSignType, signChannelType);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, error);
		}

		//查询or构建contract
		Contract contract = queryOrBuildContract(baseContractDto, companyCode, config, businessType);
		if (Objects.nonNull(contract.getStatus()) && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同状态非草稿，不能保存草稿");
		}

		//校验唯一性
		checkUnique(contract.getBusinessType(), baseContractDto.getProjectOrderId(), baseContractDto.getType(), contract.getId());

		deleteOldFieldList(contract.getContractCode());
		List<ContractField> contractFieldList = buildFieldList(contract.getContractCode(), baseContractDto, config);

		deleteOldAttach(contract.getContractCode());
		List<ContractAttach> attachList = buildAttachList(contract.getContractCode(), baseContractDto);

		contract.setStatus(ContractStatusEnum.DRAFT.getCode());
		updateContractAmount(contract, baseContractDto);

		saveOrUpdateContract(contract);
		saveFieldList(contractFieldList);
		saveAttachList(attachList);
	}

	/**
	 * 保存表单字段
	 */
	public void saveFieldList(List<ContractField> fieldList) {
		if (Objects.nonNull(fieldList)) {
			for(ContractField field : fieldList) {
				contractFieldService.save(field);
			}
		}
	}

	public void saveAttachList(List<ContractAttach> attachList) {
		if (Objects.nonNull(attachList)) {
			for (ContractAttach contractAttach : attachList) {
				contractAttachService.insert(contractAttach);
			}
		}
	}

	public void updateOrCreateNodeList(List<ContractNode> nodeList) {
		if (Objects.isNull(nodeList)) {
			return;
		}

		for (ContractNode contractNode : nodeList) {
			contractNodeService.updateOrCreate(contractNode.getContractCode(), contractNode.getNodeType(), contractNode.getFireTime());
		}
	}

	/**
	 * 删除旧的表单字段
	 */
	public void deleteOldFieldList(String contractCode) {
		contractFieldService.deleteByContractCode(contractCode);
	}

	public void deleteOldUser(String contractCode) {
		contractUserService.deleteByContractCode(contractCode, false);
	}

	private void deleteOldAttach(String contractCode) {
		contractAttachService.delByContractCode(contractCode);
	}

	/**
	 * 保存用户信息
	 */
	public void saveUserList(List<ContractUser> userList) {
		if (Objects.nonNull(userList)) {
			for(ContractUser user : userList) {
				contractUserService.insert(user);
			}
		}
	}

	/**
	 * 查询or构造合同
	 */
	public Contract queryOrBuildContract(BaseContractDto baseContractDto, String companyCode, ContractCityCompanyInfo config, Byte businessType) {
		Contract contract = null;
		if (Strings.isEmpty(baseContractDto.getContractCode())) {
			List<Contract> contractList = contractService.getContractList(baseContractDto.getProjectOrderId(), baseContractDto.getType(), Arrays.asList(ContractStatusEnum.DRAFT.getCode()));
			if (contractList.isEmpty()) {
				contract = buildContract(baseContractDto, companyCode, config, businessType);
			} else {
				contract = contractList.get(0);
			}
		} else {
			contract = contractService.getByContractCode(baseContractDto.getContractCode());
		}

		//每次都更新分公司
		contract.setCompanyCode(companyCode);
		return contract;
	}

	/**
	 * 保存or更新合同
	 */
	public void saveOrUpdateContract(Contract contract) {
		if (Objects.isNull(contract.getId())) {
			contractService.insert(contract);
		} else {
			contractService.update(contract);
		}
	}

	/**
	 * 提交
	 * @return
	 */
	@Override
	public String submit(BaseContractDto baseContractDto) {
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(baseContractDto.getProjectOrderId());
		//校验分公司&城市信息
		if (Objects.isNull(projectInfoDTO.getCustomerCommission().getCompanyCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前项目缺少分公司信息");
		}
		if (Objects.isNull(projectInfoDTO.getCustomerHouse().getGbCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前项目缺少城市信息");
		}
		String projectOrderId = baseContractDto.getProjectOrderId();
		String companyCode = projectInfoDTO.getCustomerCommission().getCompanyCode();
		Integer gbCode = projectInfoDTO.getCustomerHouse().getGbCode();
		Byte contractType = baseContractDto.getType();
		Byte userSignType = baseContractDto.getUserSignType();
		Byte signChannelType = baseContractDto.getSignChannelType();
		Byte businessType = commonContractService.getBusinessType(projectInfoDTO);
		//gbCode以查询为准，前端只读
		baseContractDto.setGbCode(gbCode);
		baseContractDto.setGbName(CityEnum.getNameByCode(gbCode));
		//校验合同类型是否配置
		ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfig(projectOrderId,gbCode, companyCode, commonContractService.getBusinessType(projectInfoDTO), contractType, signChannelType, userSignType);
		if (Objects.isNull(config)) {
			String error = String.format("当前合同城市:{},分公司:{},合同类型:{},签署方式:{}未配置", gbCode, companyCode, contractType, userSignType);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, error);
		}

		//查询or构建contract
		Contract contract = queryOrBuildContract(baseContractDto, companyCode, config, businessType);

		if (Objects.nonNull(contract.getStatus()) && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同状态非草稿，不能提交");
		}

		//字段校验
		check(baseContractDto, config);

		//检查姓名证件一致性
		checkUserIdName(baseContractDto);

		//检查唯一性
		checkUnique(contract.getBusinessType(), projectOrderId, contractType, contract.getId());

		//校验分公司前后一致
		checkCompanyCode(contract.getCompanyCode(), companyCode);

		//回写客源信息
		rewriteCustomer(baseContractDto);

		//构造用户字段
		List<ContractUser> userList = buildUserList(contract.getContractCode(), baseContractDto);

		//构造合同表单字段
		List<ContractField> fieldList = buildFieldList(contract.getContractCode(), baseContractDto, config);

		//构造附件
		List<ContractAttach> attachList = buildAttachList(contract.getContractCode(), baseContractDto);

		//构造节点
		List<ContractNode> nodeList = buildNodeList(contract.getContractCode(), baseContractDto);

		//处理更新合同内容
		updateContractAmount(contract, baseContractDto);
		dealContract(contract, baseContractDto, userList);

		contract.setStatus(getContractSubmitStatus(contract));

		//设置对用户可见
		boolean userCanSee = SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType()) || !AuditTypeEnum.BEFORE_SIGN.getCode().equals(contract.getAuditType());
		contract.setUserQueryStatus(userCanSee ? UserQueryStatusEnum.VALID.getCode() : UserQueryStatusEnum.INVALID.getCode());

		deleteOldFieldList(contract.getContractCode());

		deleteOldUser(contract.getContractCode());
		deleteOldAttach(contract.getContractCode());

		//保存contract
		saveOrUpdateContract(contract);

		//保存user
		saveUserList(userList);

		//保存field
		saveFieldList(fieldList);

		saveAttachList(attachList);

		//不需要审核的话，需要记录finish时间
		if (ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
			nodeList.add(ContractNode.builder().contractCode(contract.getContractCode()).nodeType(NodeTypeEnum.FINISH.getCode()).fireTime(System.currentTimeMillis()).build());
		}
		updateOrCreateNodeList(nodeList);

		//处理提交之后的动作 记录时间、日志、发送消息
		doAfterSubmit(contract);

		return contract.getContractCode();
	}

	public void doAfterSubmit(Contract contract) {
		//日志&消息
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.SUBMIT.getCode(), LogTypeEnum.SUBMIT.getName(), "",contract.getCreateUserId(), contract.getCreateUserName());
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.STATUS_CHANGE.getCode(), LogTypeEnum.STATUS_CHANGE.getName(), contract.getStatus().toString());
		contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.SUBMIT.getCode());
		eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_SUBMIT, contract.getContractCode());
		//线下的直接完成，发送完成消息
		if (ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
			eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_FINISH, contract.getContractCode());
		}
	}

