		List<Contract> contractList = contractService.getContractList(baseContractDto.getProjectOrderId(), baseContractDto.getType(), Arrays.asList(ContractStatusEnum.DRAFT.getCode()));
		if (contractList.isEmpty()) {
			contract = buildContract(baseContractDto, companyCode, config, businessType);
		} else {
			contract = contractList.get(0);
		}
	} else {
		contract = contractService.getByContractCode(baseContractDto.getContractCode());
	}

	//每次都更新分公司
	contract.setCompanyCode(companyCode);
	return contract;
}

