@Override
public String submit(BaseContractDto baseContractDto) {
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(baseContractDto.getProjectOrderId());
	//校验分公司&城市信息
	if (Objects.isNull(projectInfoDTO.getCustomerCommission().getCompanyCode())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前项目缺少分公司信息");
	}
	if (Objects.isNull(projectInfoDTO.getCustomerHouse().getGbCode())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前项目缺少城市信息");
	}
	String projectOrderId = baseContractDto.getProjectOrderId();
	String companyCode = projectInfoDTO.getCustomerCommission().getCompanyCode();
	Integer gbCode = projectInfoDTO.getCustomerHouse().getGbCode();
	Byte contractType = baseContractDto.getType();
	Byte userSignType = baseContractDto.getUserSignType();
	Byte signChannelType = baseContractDto.getSignChannelType();
	Byte businessType = commonContractService.getBusinessType(projectInfoDTO);
	//gbCode以查询为准，前端只读
	baseContractDto.setGbCode(gbCode);
	baseContractDto.setGbName(CityEnum.getNameByCode(gbCode));
	//校验合同类型是否配置
	ContractCityCompanyInfo config = contractCityCompanyConfigService.getConfig(projectOrderId,gbCode, companyCode, commonContractService.getBusinessType(projectInfoDTO), contractType, signChannelType, userSignType);
	if (Objects.isNull(config)) {
		String error = String.format("当前合同城市:{},分公司:{},合同类型:{},签署方式:{}未配置", gbCode, companyCode, contractType, userSignType);
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, error);
	}

	//查询or构建contract
	Contract contract = queryOrBuildContract(baseContractDto, companyCode, config, businessType);

	if (Objects.nonNull(contract.getStatus()) && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同状态非草稿，不能提交");
	}

	//字段校验
	check(baseContractDto, config);

	//检查姓名证件一致性
	checkUserIdName(baseContractDto);

	//检查唯一性
	checkUnique(contract.getBusinessType(), projectOrderId, contractType, contract.getId());

	//校验分公司前后一致
	checkCompanyCode(contract.getCompanyCode(), companyCode);

	//回写客源信息
	rewriteCustomer(baseContractDto);

	//构造用户字段
	List<ContractUser> userList = buildUserList(contract.getContractCode(), baseContractDto);

	//构造合同表单字段
	List<ContractField> fieldList = buildFieldList(contract.getContractCode(), baseContractDto, config);

	//构造附件
	List<ContractAttach> attachList = buildAttachList(contract.getContractCode(), baseContractDto);

	//构造节点
	List<ContractNode> nodeList = buildNodeList(contract.getContractCode(), baseContractDto);

	//处理更新合同内容
	updateContractAmount(contract, baseContractDto);
	dealContract(contract, baseContractDto, userList);

	contract.setStatus(getContractSubmitStatus(contract));

	//设置对用户可见
	boolean userCanSee = SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType()) || !AuditTypeEnum.BEFORE_SIGN.getCode().equals(contract.getAuditType());
	contract.setUserQueryStatus(userCanSee ? UserQueryStatusEnum.VALID.getCode() : UserQueryStatusEnum.INVALID.getCode());

	deleteOldFieldList(contract.getContractCode());

	deleteOldUser(contract.getContractCode());
	deleteOldAttach(contract.getContractCode());

	//保存contract
	saveOrUpdateContract(contract);

	//保存user
	saveUserList(userList);

	//保存field
	saveFieldList(fieldList);

	saveAttachList(attachList);

	//不需要审核的话，需要记录finish时间
	if (ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
		nodeList.add(ContractNode.builder().contractCode(contract.getContractCode()).nodeType(NodeTypeEnum.FINISH.getCode()).fireTime(System.currentTimeMillis()).build());
	}
	updateOrCreateNodeList(nodeList);

	//处理提交之后的动作 记录时间、日志、发送消息
	doAfterSubmit(contract);

	return contract.getContractCode();
}

public void doAfterSubmit(Contract contract) {
	//日志&消息
	contractLogService.createLog(contract.getContractCode(), LogTypeEnum.SUBMIT.getCode(), LogTypeEnum.SUBMIT.getName(), "",contract.getCreateUserId(), contract.getCreateUserName());
	contractLogService.createLog(contract.getContractCode(), LogTypeEnum.STATUS_CHANGE.getCode(), LogTypeEnum.STATUS_CHANGE.getName(), contract.getStatus().toString());
	contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.SUBMIT.getCode());
	eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_SUBMIT, contract.getContractCode());
	//线下的直接完成，发送完成消息
	if (ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
		eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_FINISH, contract.getContractCode());
	}
}

