	/**
	 * 转换成协议平台formData
	 * @return
	 */
	@Override
	public Map<String, Object> convertToFormData(Contract contract, BaseContractDto baseContractDto, List<ContractUser> userList) {
		CompanyInfoDTO companyInfoDTO = commonContractService.getCompanyInfo(contract.getCompanyCode());
		DesignerContractDto contractData = (DesignerContractDto)baseContractDto;
		ContractUser owner = userList.get(0);
		String address = String.format("%s-%s-%s-%s-%s-%s",
			contractData.getGbName(),
			contractData.getDistrictName(),
			contractData.getResblockName(),
			contractData.getBuildingName(),
			contractData.getUnitName(),
			contractData.getHouseName());
		String designServiceAllStatus = "0";
		String designServiceCustomStatus = "0";
		if (Objects.nonNull(contractData.getDesignServiceCustomStatus())) {
			designServiceAllStatus = contractData.getDesignServiceCustomStatus().contains(DesignServiceCustomStatusEnum.ALL_HOUSE.getCode()) ? "1" : "0";
			designServiceCustomStatus = contractData.getDesignServiceCustomStatus().contains(DesignServiceCustomStatusEnum.CUSTOM.getCode()) ? "1" : "0";
		}
		String packageName = "";
		if (Objects.nonNull(contractData.getPackageId())) {
			Integer organizationMode = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType()) ? OrganizationModeEnum.模式25.getMode() : null;
			List<ComboBaseDTO> packageList = quotationFeignService.getPackageList(contract.getCompanyCode(),organizationMode);
			Map<String, String> packageMap = packageList.stream().collect(Collectors.toMap(ComboBaseDTO::getComboCode, ComboBaseDTO::getComboName));
			if (!packageMap.containsKey(contractData.getPackageId())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取套餐名称失败");
			}
			packageName = packageMap.get(contractData.getPackageId());
		}

		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(contract.getProjectOrderId());
		String decorateForm = projectInfoDTO.getCustomerCommission().getDecorateTypeDesc() + "-"+projectInfoDTO.getCustomerCommission().getDecorateIdDesc();

		String preDiscountDesignerAmountText = "";
		if (Objects.nonNull(contractData.getPreDiscountDesignerAmount())) {
			MoneyConvertUtil moneyConvertUtil = new MoneyConvertUtil(contractData.getPreDiscountDesignerAmount().toString());
			preDiscountDesignerAmountText = moneyConvertUtil.convert();
		}
		String roomCnt = Objects.isNull(contractData.getRoomCnt()) ? "" : contractData.getRoomCnt().toString();
		String parlorCnt = Objects.isNull(contractData.getParlorCnt()) ? "" : contractData.getParlorCnt().toString();
		String area = Objects.isNull(contractData.getArea()) ? "" : contractData.getArea().toString();
		String designerLevel = Objects.isNull(contractData.getDesignerLevel()) ? "" : DesignerLevelEnum.getNameByCode(contractData.getDesignerLevel());
		String preDiscountDesignerAmount = Objects.isNull(contractData.getPreDiscountDesignerAmount()) ? "" : contractData.getPreDiscountDesignerAmount().toString();
		String afterDiscountDesignerAmount = Objects.isNull(contractData.getAfterDiscountDesignerAmount()) ? "" : contractData.getAfterDiscountDesignerAmount().toString();
		String structure = Objects.isNull(contractData.getStructure()) ? "" : StructureEnum.getNameByCode(contractData.getStructure());

		DesignContractFreeformDTO dto = DesignContractFreeformDTO.builder()
			.jiafangXingming(owner.getName())
			.projectContractAddress(address)
			.packageName(packageName)
			.floorName(contractData.getFloorName())
			.roomCnt(roomCnt)
			.parlorCnt(parlorCnt)
			.area(area)
			.designServiceAllStatus(designServiceAllStatus)
			.designServiceCustomStatus(designServiceCustomStatus)
			.designerName(contractData.getDesignerName())
			.designerLevel(designerLevel)
			.preDiscountDesignerAmount(preDiscountDesignerAmount)
			.preDiscountDesignerAmountText(preDiscountDesignerAmountText)
			.afterDiscountDesignerAmount(afterDiscountDesignerAmount)
			.decorateForm(decorateForm)
			.customCabinetDecorate(contractData.getCustomCabinetDecorate())
			.structure(structure)
			.contractNo(contract.getContractNo())
			.companyName(companyInfoDTO.getCompanyName())
			.companyAddress(companyInfoDTO.getCompanyAddress())
			.companyPhone(companyInfoDTO.getCompanyPhone())
			.companySealCode(companyInfoDTO.getCompanySealCode())
			.build();

		ObjectMapper objectMapper = new ObjectMapper();
		Map<String, Object> result = objectMapper.convertValue(dto, Map.class);
		return result;
	}

