@Override
public List<ContractField> buildFieldList(String contractCode, BaseContractDto baseContractDto, ContractCityCompanyInfo config) {
	DesignerContractDto contractData = (DesignerContractDto)baseContractDto;
	// 获取配置中的合同字段（草稿不需要必填项都填）
	List<CityCompanyApolloDto.FieldsMapItemDto> fieldList = formatFieldMap(config.getFieldsMap());
	List<String> configFields = fieldList.stream().map(CityCompanyApolloDto.FieldsMapItemDto::getFields).collect(Collectors.toList());
	// 构造合同字段结果，过滤非配置字段
	List<ContractField> currentContractFields = Lists.newArrayList();
	Field[] childFields = contractData.getClass().getDeclaredFields();
	Field[] parentFields = contractData.getClass().getSuperclass().getDeclaredFields();
	Field[] fields = (Field[]) ArrayUtils.addAll(childFields, parentFields);

	for (int i=0;i<fields.length;i++) {
		fields[i].setAccessible(true);
		if (!configFields.contains(fields[i].getName())) {
			continue;
		}

		//过滤非存储字段
		if (notSaveField.contains((fields[i].getName()))) {
			continue;
		}
		try {
			// 加解密
			if(encryptField.contains((fields[i].getName())) && Objects.nonNull(fields[i].get(contractData))) {
				fields[i].set(contractData, cipherService.encrypt(fields[i].get(contractData).toString()));
			}
			ContractField contractField = ContractField.builder()
				.contractCode(contractCode)
				.fieldKey(fields[i].getName())
				.fieldValue(fields[i].get(contractData).toString())
				.build();
			currentContractFields.add(contractField);
		} catch (Exception ignored) {

		}
	}
	return currentContractFields;
}

