@Override
public Boolean check(BaseContractDto baseContractDto, ContractCityCompanyInfo config) {
	super.check(baseContractDto, config);
	SubscribeContractDto contractData = (SubscribeContractDto)baseContractDto;
	List<CityCompanyApolloDto.FieldsMapItemDto> fieldsMap = formatFieldMap(config.getFieldsMap());
	for (CityCompanyApolloDto.FieldsMapItemDto itemDto : fieldsMap) {
		if (Integer.valueOf(CommonEnum.YES.getCode()).equals(itemDto.getRequired())) {
			checkDetailField(itemDto.getFields(), contractData);
		}
	}

	return true;
}

private Boolean checkDetailField(String fieldKey, SubscribeContractDto contractData) {
	if (fieldKey.equals("name") && Strings.isEmpty(contractData.getName())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "姓名不能为空");
	}
	if (fieldKey.equals("phone") && Strings.isEmpty(contractData.getPhone())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "手机号不能为空");
	}
	if (fieldKey.equals("gbName") && Strings.isEmpty(contractData.getGbName())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "城市不能为空");
	}
	if (fieldKey.equals("districtName") && Strings.isEmpty(contractData.getDistrictName())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "行政区不能为空");
	}
	if (fieldKey.equals("resblockName") && Strings.isEmpty(contractData.getResblockName())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "小区不能为空");
	}
	if (fieldKey.equals("buildingName") && Strings.isEmpty(contractData.getBuildingName())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "楼栋不能为空");
	}
	if (fieldKey.equals("unitName") && Strings.isEmpty(contractData.getUnitName())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "单元不能为空");
	}
	if (fieldKey.equals("floorName") && Strings.isEmpty(contractData.getFloorName())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "楼层不能为空");
	}
	if (fieldKey.equals("houseName") && Strings.isEmpty(contractData.getHouseName())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "房间不能为空");
	}
	if (fieldKey.equals("parlorCnt") && Objects.isNull(contractData.getParlorCnt())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "厅不能为空");
	}
	if (fieldKey.equals("roomCnt") && Objects.isNull(contractData.getRoomCnt())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "室不能为空");
	}
	if (fieldKey.equals("cookroomCnt") && Objects.isNull(contractData.getCookroomCnt())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "厨不能为空");
	}
	if (fieldKey.equals("toiletCnt") && Objects.isNull(contractData.getToiletCnt())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "卫不能为空");
	}
	if (fieldKey.equals("area") && Objects.isNull(contractData.getArea())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "面积不能为空");
	}
	if (fieldKey.equals("amount") && Objects.isNull(contractData.getAmount())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "面积不能为空");
	}
	if (fieldKey.equals("effectiveDate") && Objects.isNull(contractData.getEffectiveDate())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "面积不能为空");
	}
	if (fieldKey.equals("idNo") && Objects.isNull(contractData.getIdNo())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "身份证件号不能为空");
	}
	if (fieldKey.equals("certificateType") && Objects.isNull(contractData.getCertificateType())) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "证件类型不能为空");
	}
	return true;
}

	@Override
	public Map<String, Object> convertToFormData(Contract contract, BaseContractDto baseContractDto, List<ContractUser> userList) {
		CompanyInfoDTO companyInfoDTO = commonContractService.getCompanyInfo(contract.getCompanyCode());
		SubscribeContractDto contractData = (SubscribeContractDto)baseContractDto;
		ContractUser owner = userList.get(0);
		String address = String.format("%s-%s-%s-%s-%s-%s",
			contractData.getGbName(),
			contractData.getDistrictName(),
			contractData.getResblockName(),
			contractData.getBuildingName(),
			contractData.getUnitName(),
			contractData.getHouseName());
		String customCabinetBrand = "";
		if (StringUtils.isNotBlank(contractData.getCustomCabinetBrand())) {
			customCabinetBrand = contractData.getCustomCabinetBrand();
		}

		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(contract.getProjectOrderId());
		String decorateForm = projectInfoDTO.getCustomerCommission().getDecorateTypeDesc() + "-"+projectInfoDTO.getCustomerCommission().getDecorateIdDesc();
		String packageName = "";
		if (Objects.nonNull(contractData.getPackageId())) {
			Integer organizationMode = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType()) ? OrganizationModeEnum.模式25.getMode() : null;
			List<ComboBaseDTO> packageList = quotationFeignService.getPackageList(contract.getCompanyCode(),organizationMode);
			Map<String, String> packageMap = packageList.stream().collect(Collectors.toMap(ComboBaseDTO::getComboCode, ComboBaseDTO::getComboName));
			if (!packageMap.containsKey(contractData.getPackageId())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "获取套餐名称失败");
			}
			packageName = packageMap.get(contractData.getPackageId());
		}
/*		String softElectricStatus = "";
		if (Objects.nonNull(contractData.getSoftElectricStatus())) {
			softElectricStatus = contractData.getSoftElectricStatus().toString();
		}*/

		SubscribeContractFreeformDTO dto = SubscribeContractFreeformDTO.builder()
			.jiafangXingming(owner.getName())
			.contractAmount(contract.getAmount().toString())
			.projectContractAddress(address)
			.packageName(packageName)
			.decorateForm(decorateForm)
			.floorName(contractData.getFloorName())
			.roomCnt(contractData.getRoomCnt().toString())
			.parlorCnt(contractData.getParlorCnt().toString())
			.customCabinetBrand(customCabinetBrand)
//			.softElectricStatus(softElectricStatus)
			.area(contractData.getArea().toString())
			.effectiveDate(contractData.getEffectiveDate().toString())
			.firstPartySignDate(DateUtils.getFormatDateStr(new Date(), DateUtils.DATE))
			.customCabinetBrand(contractData.getCustomCabinetBrand())
			.resblockCustomDecorate(contractData.getResblockCustomDecorate())
			.retailBrand(contractData.getRetailBrand())
			.companyName(companyInfoDTO.getCompanyName())
			.companyAddress(companyInfoDTO.getCompanyAddress())
			.companyPhone(companyInfoDTO.getCompanyPhone())
			.companySealCode(companyInfoDTO.getCompanySealCode())
			.build();

		ObjectMapper objectMapper = new ObjectMapper();
		Map<String, Object> result = objectMapper.convertValue(dto, Map.class);
		return result;
	}

