	public void checkUnique(Byte businessType, String projectOrderId, Byte type, Long excludeId) {
		List<Contract> contractList = contractService.getBaseContractInfo(businessType, projectOrderId, type);
		if (contractList.isEmpty()) {
			return;
		}
		for (Contract contract : contractList) {
			if (!contract.getId().equals(excludeId) && !ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同类型已经存在，不能创建多份");
			}
		}
	}

	/**
