	 * @return
	 */
	@Override
	public Map<String, Object> convertToFormData(Contract contract, BaseContractDto baseContractDto, List<ContractUser> userList) {
		TerminalContractDto terminalContractDto = (TerminalContractDto) baseContractDto;
		if (Objects.isNull(terminalContractDto.getAttachUrl())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同附件不能为空");
		}

		//线下合同附件，只能为pdf/图片中的一个
		boolean containPdf = false;
		boolean containImage = false;
		for (String url : terminalContractDto.getAttachUrl()) {
			if (StringUtils.containsIgnoreCase(url, ".pdf")) {
				containPdf = true;
			} else {
				containImage = true;
			}
			if (containPdf && containImage) {
				throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "合同附件类型只能是图片/PDF中的一个");
			}
		}

		//pdf转换成图片
		List<String> attachImageUrls = new LinkedList<>();
		if (containPdf) {
			try {
				for (String pdfUrls : terminalContractDto.getAttachUrl()) {
					attachImageUrls.addAll(pdfToImageService.pdf2ImagePublicParallel(pdfUrls));
				}
			} catch (NrsBusinessException e) {
				if (e.getCode() == ResponseCodeEnum.PDF_PAGES_LIMIT.getCode()) {
					throw new NrsBusinessException(String.format("线下合同页数过多，请检查线下合同样式并调整控制在%s页及以内", limitPages), Level.WARN);
				}
			}

		} else {
			attachImageUrls.addAll(terminalContractDto.getAttachUrl());
		}

		String signDate = DateUtils.getDateStr(new Date());
		List<TerminalContractFreeformDTO.Photo> photos = attachImageUrls.stream().map(src->new TerminalContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
		String urls = JsonUtil.toJsonString(photos);

		TerminalContractFreeformDTO contractFreeformDTO = TerminalContractFreeformDTO.builder()
			.imageUrl(urls)
			.build();

		ObjectMapper objectMapper = new ObjectMapper();
		return objectMapper.convertValue(contractFreeformDTO, Map.class);
	}

