		ContractUser signer = contractUserService.getSignerByContractCode(lastContract.getContractCode());

		fieldList.forEach((key, value) -> {
			switch (key) {
				case "name": fieldList.put(key, signer.getName());break;
				case "phone": fieldList.put(key, signer.getPhone());break;
				case "certificateType": fieldList.put(key, signer.getCertificateType());break;
