	fieldList.forEach((key, value) -> {
		switch (key) {
			case "name": fieldList.put(key, signer.getName());break;
			case "phone": fieldList.put(key, signer.getPhone());break;
			case "certificateType": fieldList.put(key, signer.getCertificateType());break;
			case "idNo": fieldList.put(key, signer.getCertificateNo());break;
			default: break;
		}
	});
}

private CancelOrderBaseInfoDTO getValidCancelOrder(String projectOrderId) {
	List<CancelOrderBaseInfoDTO> cancelOrderRecordList = cancelOrderRecordService.getListByProjectOrderId(projectOrderId).stream().filter(t->t.getStatus().equals(CancelOrderStatusEnum.WAIT_CUSTOMER_CONFIRM.getStatus())).collect(Collectors.toList());
	if (cancelOrderRecordList.isEmpty()) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "没有处于待用户确认中的退单");
	}
	return cancelOrderRecordList.get(0);
}

