    private static boolean cellIsMerged(Cell cell) {
        Sheet sheet = cell.getSheet();
        int mergedRegions = sheet.getNumMergedRegions();

        for (int i = 0; i < mergedRegions; i++) {
            CellRangeAddress range = sheet.getMergedRegion(i);
            if(range.isInRange(cell.getRowIndex(), cell.getColumnIndex())) {
                return true;
            }
        }

        return false;
    }

    private static String getMergedCellValue(Sheet sheet, Cell cell) {
        int mergedRegions = sheet.getNumMergedRegions();

        for (int i = 0; i < mergedRegions; i++) {
            CellRangeAddress range = sheet.getMergedRegion(i);
            if(range.isInRange(cell.getRowIndex(), cell.getColumnIndex())) {
                Row mergedRow = sheet.getRow(range.getFirstRow());
                Cell mergedCell = mergedRow.getCell(range.getFirstColumn());
                return getCellValue(mergedCell);
            }
        }
        return "";
    }

    private static String getCellValue(Cell cell) {
        if(cell == null) {
            return "";
        }

        switch (cell.getCellType()) {
        case STRING:
            return cell.getStringCellValue();
        case NUMERIC:
            return String.valueOf(cell.getNumericCellValue());
        case BOOLEAN:
            return String.valueOf(cell.getBooleanCellValue());
        case FORMULA:
            return String.valueOf(cell.getCellFormula());
        default:
            return "";
        }
    }

    private static String getCellValue(Sheet sheet, Cell cell) {
        String str = cellIsMerged(cell) ? getMergedCellValue(sheet, cell) : getCellValue(cell);
        str = str.replace("'", "\\'");
        return str;
    }




