            String 城市value  = getCellValue(sheet, row.getCell(ExcelFieldEnum.城市.getIndex()));
            String 分公司value  = getCellValue(sheet, row.getCell(ExcelFieldEnum.分公司.getIndex()));
            if(moduleKeySet.contains(字段所属模块value) || StringUtils.isEmpty(字段所属模块value)) {
                continue;
            }
            //非正签合同，step统一设置为1
            List<Byte> contractTypes = Arrays.asList((byte)3, (byte)4);
            Byte contractType = SheetEnum.getContractType(sheetIndex);
            Integer businessType = SheetEnum.getBusinessType(sheetIndex);
            if(!contractTypes.contains(contractType)) {
                模块stepValue = "1";
            }
            ContractModuleConfig build = ContractModuleConfig.builder()
                    .businessType(businessType)
                    .contractType(Integer.valueOf(contractType))
                    .moduleKey(字段所属模块value)
                    .moduleName(字段所属模块名称value)
                    .description(模块描述value)
                    .tips(模块问号点击内容value)
                    .event(模块事件类型value)
                    .step(StringUtils.isEmpty(模块stepValue) ? 1 : Byte.valueOf((byte) Double.parseDouble(模块stepValue)))
                    .disabled(模块是否禁用value.equals("是") ? (byte) 1 : (byte) 0)
                    .gbcode(StringUtils.isEmpty(城市value)?0:Integer.valueOf(城市value))
                    .companyCode(StringUtils.isEmpty(分公司value)?"":分公司value)
                    .build();
            contractModuleConfigs.add(build);
            moduleKeySet.add(字段所属模块value);
        }
        for (ContractModuleConfig contractModuleConfig : contractModuleConfigs) {
            String insertSql = "INSERT INTO `contract_module_config` (`business_type`, `contract_type`, `module_key`, `module_name`, `description`, `tips`, `step`, `disabled`, `event`,`gbcode`,`company_code`) VALUES ";
            insertSql += "(" + contractModuleConfig.getBusinessType() + ", " + contractModuleConfig.getContractType() + ", '"
                    + contractModuleConfig.getModuleKey() + "', '" + contractModuleConfig.getModuleName() + "', '"
                    + contractModuleConfig.getDescription() + "', '" + contractModuleConfig.getTips() + "', " + contractModuleConfig.getStep()
                    + ", " + contractModuleConfig.getDisabled() + ", '" + contractModuleConfig.getEvent() + "'," + contractModuleConfig.getGbcode() + ",'" + contractModuleConfig.getCompanyCode()
                    +  "');";
            System.out.println(insertSql);
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
}

private static void contractFiledConfigCreate(Integer sheetIndex) {
