                    .companyCode(StringUtils.isEmpty(分公司value)?"":分公司value)
                    .build();
            contractFieldConfigList.add(build);
        }
        for (ContractFieldConfig contractFieldConfig : contractFieldConfigList) {
            //将上面填充的信息，转换为插入sql
