                    + ", " + contractFieldConfig.getDisabled() + ", '" + contractFieldConfig.getFormTypeH5() + "', '"
                    + contractFieldConfig.getFormTypePc() + "', '" + contractFieldConfig.getDisplayCondition() + "', '"
                    + contractFieldConfig.getEvent() + "', '" + contractFieldConfig.getDefaultSupportChange() + "', "
                    + contractFieldConfig.getFieldOrder() + ",'" + contractFieldConfig.getGbcode() + "','" + contractFieldConfig.getCompanyCode()
                    + "'" + ");";
            System.out.println(insertSql);
        }
