public static void protocolConfigInsertSqlCreate(){
    //通过指定sheetIndex来生成测试或线上的的sql
    //sheetIndex:0-测试;  1-线上
    int sheetIndex = 0;
    try (FileInputStream fileInputStream = new FileInputStream(FILE_PATH);
            Workbook workbook = WorkbookFactory.create(fileInputStream)) {
        //协议平台配置默认第一个sheet
        Sheet sheet = workbook.getSheetAt(sheetIndex);
        List<ContractProtocolConfig> contractProtocolConfigs = new ArrayList<>();
        for (Row row : sheet) {
            int rowNum = row.getRowNum();
               if(rowNum <2){
                    continue;
                }
            String form_id = getCellValue(sheet, row.getCell(ExcelFieldEnum.协议模板_form_id.getIndex()));
            String form_key = getCellValue(sheet, row.getCell(ExcelFieldEnum.协议模板_form_key.getIndex()));
