            String deal_function = getCellValue(sheet, row.getCell(ExcelFieldEnum.协议模板_deal_function.getIndex()));
            String allow_blank = getCellValue(sheet, row.getCell(ExcelFieldEnum.协议模板_allow_blank.getIndex()));
