public class ContractEvent {
	@ApiModelProperty(value = "业务类型 1家装")
	private Byte businessType;

	@ApiModelProperty(value = "项目订单")
	private String projectOrderId;

	@ApiModelProperty(value = "合同编号")
	private String contractCode;

	@ApiModelProperty(value = "合同类型 1.认购合同 2.设计合同 3.正签 4.套餐变更协议")
	private Byte type;

	@ApiModelProperty(value = "事件类型")
	private Map<String, Object> extra;

	@ApiModelProperty(value = "报价版本")
	private String quotationVersion;

	@ApiModelProperty(value = "合同关联的报价单号")
	private List<String> billCodeList;

	@ApiModelProperty(value = "签署方式 1.线上 2.线下")
	private Byte signChannelType;

	@ApiModelProperty(value = "bmp审核单号")
	private String bmpNo;

	@ApiModelProperty(value = "变更单号")
	private String changeOrderId;

	@ApiModelProperty(value = "创建人userId")
	private String createUserId;

	@ApiModelProperty(value = "创建人userName")
	private String createUserName;

	@ApiModelProperty(value = "创建人角色code")
	private String createUserRoleId;

	@ApiModelProperty(value = "创建人角色")
	private String createUserRoleName;

	@ApiModelProperty(value = "更新人ucid")
	private String modifyUserId;

	@ApiModelProperty(value = "更新人姓名")
	private String modifyUserName;

	@ApiModelProperty(value = "消息发送时间")
	@JsonFormat(pattern = "yyyy-MM-dd HH:mm:ss", timezone = "GMT+8")
	private Date triggerTime;


	@ApiModelProperty(value = "业务单号")
	private String businessId;


	public ContractEvent(Contract contract) {
		this.setContractCode(contract.getContractCode());
		this.setBusinessType(contract.getBusinessType());
		this.setType(contract.getType());
		this.setProjectOrderId(contract.getProjectOrderId());
		this.setQuotationVersion(contract.getQuotationVersion());
		this.setSignChannelType(contract.getSignChannelType());
		this.setBmpNo(contract.getBmpNo());
		this.setChangeOrderId(contract.getChangeOrderId());
		this.setCreateUserId(HeaderContext.getContext().getOperatorUcId());
		this.setCreateUserName(HeaderContext.getContext().getOperatorName());
		this.setCreateUserRoleId(HeaderContext.getContext().getRoleId());
		this.setCreateUserRoleName(RoleIdEnum.getDescById(HeaderContext.getContext().getRoleId()));
		this.setModifyUserId(contract.getModifyUserId());
		this.setModifyUserName(contract.getModifyUserName());
		this.setTriggerTime(new Date());
	}

	public ContractEvent(Contract contract, List<String> billCodeList) {
		this(contract);
		this.setBillCodeList(billCodeList);
	}


	public ContractEvent(Contract contract, ContractExtendInfo extendInfo) {
		this(contract);
		this.setBmpNo(extendInfo.getBmpNo());
		this.setCreateUserId(contract.getCreateUserId());
		this.setCreateUserName(contract.getCreateUserName());
	}

	public ContractEvent(Contract contract, String operatorUcId, String operatorName) {
		this(contract);
		this.setCreateUserId(operatorUcId);
		this.setCreateUserName(operatorName);

	}

	@Setter
	@Getter
	@Builder
	@NoArgsConstructor
	@AllArgsConstructor
	public static class ContractExtendInfo{
		private String bmpNo;
	}
