@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_SUBMIT, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class CancelOrderLaunchAfterSubmitListener implements DomainEventHandler<ContractEvent> {
	@Resource
	ContractService contractService;
	@Resource
	CancelOrderService cancelOrderService;
	@Resource
	CancelOrderRecordService cancelOrderRecordService;
	@Resource
	ContractRelationService contractRelationService;

	@Override
	public void handleBiz(ContractEvent payloadData, String eventContextKey) {
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				LOGGER.info("解约协议合同发起后触发退单发起处理开始，contractCode:{}", payloadData.getContractCode());
				Contract contract = contractService.getByContractCode(payloadData.getContractCode());
				if (!ContractTypeEnum.TERMINAL.getCode().equals(contract.getType())) {
					return;
				}
				CancelOrderRecord cancelOrderRecord = cancelOrderRecordService.getLastCancelRecordByProjectOrderId(contract.getProjectOrderId());
				if (cancelOrderRecord == null || CancelOrderVersionEnum.ONE.getValue().equals(cancelOrderRecord.getFlowVersion())) {
					return;
				}
				ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
				if (contractRelation != null) {
					LOGGER.info("解约协议合同为通过合并发起方式发起，无需进行退单流程处理，projectOrderId:{}", contract.getProjectOrderId());
					return;
				}

				if (!CancelOrderStatusEnum.AWAIT_SIGN_LAUNCH.getStatus().equals(cancelOrderRecord.getStatus())) {
					LOGGER.error("解约协议合同发起后触发退单发起,退单状态校验异常,当前退单状态不是[待发起签约]，projectOrderId:{},cancelOrderStatus:{}", contract.getProjectOrderId(), cancelOrderRecord.getStatus());
					return;
				}
				// 退单发起
				cancelOrderRecord.setStatus(CancelOrderStatusEnum.CANCEL_ORDER_APPROVING.getStatus());
				cancelOrderRecord.setContractCode(contract.getContractCode());
				cancelOrderService.launchCancelOrderV2(cancelOrderRecord);
				LOGGER.info("解约协议合同发起后触发退单发起处理完成，contractCode:{}", payloadData.getContractCode());
			} catch (Exception e) {
				LOGGER.error("解约协议合同发起后触发退单发起处理异常", e);
			}
		}));
	}

}

