@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.CANCEL_ORDER_STATUS_CHANGE, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class CancerOrderCancelListener implements DomainEventHandler<CancelOrderStatusChangePayloadDTO> {
	@Resource
	ContractService contractService;
	@Resource
	ContractLogService contractLogService;
	@Resource
	ContractNodeService contractNodeService;
	@Resource
	EventService eventService;
	@Resource
	CommonContractService commonContractService;
	@Resource
	ContractRelationService contractRelationService;

	@Override
	public void handleBiz(CancelOrderStatusChangePayloadDTO payloadData, String eventContextKey) {
		if (Objects.isNull(payloadData.getProjectOrderId()) || Objects.isNull(payloadData.getTargetStatus())) {
			return;
		}

		//退单取消后，如果有合同，需要置为已取消
		if (!CancelOrderStatusEnum.REVOKE_CANCEL_ORDER.getStatus().equals(payloadData.getTargetStatus())) {
			return;
		}

		LOGGER.info("【签约】-收到退单取消消息"+ JsonUtil.toJsonString(payloadData));

		//取消对应合同
		List<Contract> contractList = contractService.getContractList(payloadData.getProjectOrderId(), ContractTypeEnum.TERMINAL.getCode());
		for (Contract contract : contractList) {
			if (ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())) {
				continue;
			}
			//如果解约协议存在关联关系，说明解约协议是通过合并发起方式发起，退单撤销对应的这个解约协议不能撤销
			ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
			if (contractRelation != null) {
				LOGGER.info("【签约】-收到退单取消消息，合同已存在关联关系，不能撤销,contractCode:{}", contract.getContractCode());
				continue;
			}
			contractLogService.createLog(contract.getContractCode(), LogTypeEnum.CANCEL.getCode(), "退单终止，取消合同");
			contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.CANCEL.getCode());
			contractService.updateContractStatus(contract.getContractCode(), ContractStatusEnum.CANCEL.getCode());
			eventService.publish(commonContractService.getContractEvent(contract), com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_CANCEL);
		}
	}
}

