@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.CHANGE_ORDER_NODE_EVENT, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class ChangeContractCancelLister implements DomainEventHandler<ChangeOrderNodeEventPayloadDTO> {

	@Resource
	ContractService contractService;

	@Resource
	private ContractCollectionPlanRecordService contractCollectionPlanRecordService;

	@Resource
	private FundBaseService fundBaseService;

	@Resource
	private AthenaRpc athenaRpc;

	@Resource
	private ChangeContractCancelLister changeContractCancelListerSelf;

	@Resource
	private CommonContractService commonContractService;

	@Override
	public void handleBiz(ChangeOrderNodeEventPayloadDTO payloadData, String eventContextKey) {
		Contract changeContract = contractService.getChangeContract(payloadData.getProjectOrderId(), payloadData.getChangeOrderId());

		LOGGER.info("[change_contract_status_listener]-收到变更事件:{}", JsonUtil.toJsonString(payloadData));
		//仅仅监听删除消息
		if (!payloadData.getNodeId().equals(ChangeOrderEventEnum.CHANGE_CANCEL.getCode())) {
			LOGGER.info("[change_contract_status_listener]-非变更取消事件， changeOrderId:{}，projectOrderId:{}", payloadData.getChangeOrderId(), payloadData.getProjectOrderId());
			return;
		}

		if (Objects.isNull(changeContract) || !ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(changeContract.getType())) {
			LOGGER.info("[change_contract_status_listener]-无相关合同信息， changeOrderId:{}，projectOrderId:{}", payloadData.getChangeOrderId(), payloadData.getProjectOrderId());
			return;
		}
		List<Contract> contractList = contractService.getContractList(payloadData.getProjectOrderId());
		List<Contract> changeContractList = contractList.stream().filter(m -> ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(m.getType()) || ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(m.getType()))
			.filter(m -> ContractStatusEnum.FINISH.getCode().equals(m.getStatus()))
			.collect(Collectors.toList());
		if (CollectionUtil.isEmpty(changeContractList)) {
			return;
		}
		ContractCollectionPlanRecord contractCollectionPlanRecord = contractCollectionPlanRecordService.selectOne(ContractCollectionPlanRecord.builder().contractCode(changeContractList.get(0).getContractCode()).build());
		if (contractCollectionPlanRecord == null) {
			return;
		}
		CollectionPlanConfigInfo collectionPlanConfigInfo = JSON.parseObject(contractCollectionPlanRecord.getCollectionPlan(), CollectionPlanConfigInfo.class);
		CompletableFuture.runAsync(() -> {
			try {
				changeContractCancelListerSelf.saveCollectionPlan(collectionPlanConfigInfo, changeContractList.get(0));
			} catch (Exception e) {
				LOGGER.error("收到变更合同取消,保存收款计划重试后依然失败,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		});
		LOGGER.info("收到变更合同取消,处理完毕，contractCode:{}", changeContractList.get(0).getContractCode());


	}

	@Retryable(value = Exception.class, maxAttempts = 4, backoff = @Backoff(value = 1000, multiplier = 1))
	public void saveCollectionPlan(CollectionPlanConfigInfo collectionPlanConfigInfo, Contract contract) {
		try {
			LOGGER.info("变更合同取消,回退收款计划开始,contractCode:{}", contract.getContractCode());
			BigDecimal contractPrice = athenaRpc.queryPlanInfo(contract.getProjectOrderId()).getPlanInfo().getContractPriceTotal();
			fundBaseService.saveCollectionPlan(fundBaseService.calculateCollectionPlan(collectionPlanConfigInfo, contractPrice));
			LOGGER.info("变更合同取消,回退收款计划完成,contractCode:{}", contract.getContractCode());
		} catch (Exception e) {
			LOGGER.info("变更合同取消,回退收款计划失败,contractCode:{},收款计划:{}", contract.getContractCode(), JSON.toJSONString(collectionPlanConfigInfo), e);
			throw e;
		}
	}

}

@Override
public void handleBiz(ChangeOrderNodeEventPayloadDTO payloadData, String eventContextKey) {
	Contract changeContract = contractService.getChangeContract(payloadData.getProjectOrderId(), payloadData.getChangeOrderId());

	LOGGER.info("[change_contract_status_listener]-收到变更事件:{}", JsonUtil.toJsonString(payloadData));
