	public void handleBiz(ChangeOrderNodeEventPayloadDTO payloadData, String eventContextKey) {
		Contract changeContract = contractService.getChangeContract(payloadData.getProjectOrderId(), payloadData.getChangeOrderId());

		LOGGER.info("[change_contract_status_listener]-收到变更事件:{}", JsonUtil.toJsonString(payloadData));
		//仅仅监听删除消息
		if (!payloadData.getNodeId().equals(ChangeOrderEventEnum.CHANGE_CANCEL.getCode())) {
			LOGGER.info("[change_contract_status_listener]-非變更取消事件， changeOrderId:{}，projectOrderId:{}", payloadData.getChangeOrderId(), payloadData.getProjectOrderId());
			return;
		}

		if (Objects.isNull(changeContract) || !ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(changeContract.getType())) {
			LOGGER.info("[change_contract_status_listener]-无相关合同信息， changeOrderId:{}，projectOrderId:{}", payloadData.getChangeOrderId(), payloadData.getProjectOrderId());
			return;
		}

		//已取消、已确认、已签署，不可取消（区分整装和团装）
		if (!BusinessTypeEnum.GROUP_DECORATE.getCode().equals(changeContract.getBusinessType()) && (changeContract.getStatus().equals(ContractStatusEnum.CANCEL.getCode())
			|| changeContract.getStatus().equals(ContractStatusEnum.USER_CONFIRMED.getCode())
			|| changeContract.getStatus().equals(ContractStatusEnum.FINISH.getCode()))) {
			LOGGER.info("[change_contract_status_listener]-整装合同已取消、已确认、已签署，无法取消， changeOrderId:{}，projectOrderId:{}", payloadData.getChangeOrderId(), payloadData.getProjectOrderId());
			return;
		} else if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(changeContract.getBusinessType()) && changeContract.getStatus().equals(ContractStatusEnum.CANCEL.getCode())) {
			LOGGER.info("[change_contract_status_listener]-团装合同已取消，无法取消， changeOrderId:{}，projectOrderId:{}", payloadData.getChangeOrderId(), payloadData.getProjectOrderId());
			return;
		}

		//軟刪除合同
		//contractService.softDeleteById(changeContract.getId());
		//合同更新成取消状态
		int updateResult = contractService.updateContractStatus(
			changeContract.getContractCode(),
			ContractStatusEnum.CANCEL.getCode()
		);
		//撤销合同报价单关联关系
		quotationRelationCommonService.cancelContractRelations(changeContract.getContractCode());

		if (updateResult != 1) {
			LOGGER.info("[change_contract_status_listener]-更新合同为取消状态失败， changeOrderId:{}，projectOrderId:{}", payloadData.getChangeOrderId(), payloadData.getProjectOrderId());
			return;
		}

		//存一下前一个，状态
		contractStatusLogService.insertContractStatusLog(
			changeContract.getContractCode(),
			changeContract.getStatus(),
			ContractStatusEnum.CANCEL.getCode()
		);

		if (!changeContract.getBmpNo().isEmpty()) {//有审核信息
			//撤回BPM流程
			List<ContractAudit> auditInfo = contractAuditService.getLastAuditInfo(changeContract.getContractCode());
			Boolean isFinish = false;
			for (ContractAudit contractAudit : auditInfo) {
				if (!contractAudit.getBmpNo().equals(changeContract.getBmpNo())) {
					continue;
				}
				if (contractAudit.getAuditStatus().equals(ContractAuditStatusEnum.CONTRACT_AUDIT_PASS.getCode()) ||
					contractAudit.getAuditStatus().equals(ContractAuditStatusEnum.CONTRACT_AUDIT_REJECT.getCode())) {
					isFinish = true;
				}
			}
			if (!isFinish) {//完成后，不再不能取消
				String userSystemCode = contractBusinessService.getUserSystemCode(String.valueOf(payloadData.getOperatorUcid()));
				try {
					bpmService.processCancel(changeContract.getBmpNo(), userSystemCode);
				} catch (Exception e) {
					LOGGER.info("[change_contract_status_listener]-变更单取消变更, 取消BPM流程，BPM_NO:{}，异常{}", changeContract.getBmpNo(), e.getMessage());
				}
			}
		}

        //合同日志
		contractLogService.createLog(changeContract.getContractCode(),
			LogTypeEnum.CANCEL.getCode(),
			LogTypeEnum.CANCEL.getName(),
			contractBusinessService.assembleRemarkInfo(changeContract.getBmpNo()),
			String.valueOf(payloadData.getOperatorUcid()),
			""
			);
		//合同节点日志
		contractNodeService.updateOrCreate(changeContract.getContractCode(), NodeTypeEnum.CANCEL.getCode());
	}

