@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_USER_CONFIRM, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class ChangeContractUserConfirmListener implements DomainEventHandler<ContractEvent> {

	@Resource
	ContractService contractService;

	@Resource
	private ContractCollectionPlanRecordService contractCollectionPlanRecordService;

	@Resource
	private FundBaseService fundBaseService;

	@Resource
	private AthenaRpc athenaRpc;

	@Resource
	private ChangeContractUserConfirmListener changeContractUserConfirmListenerSelf;

	@Override
	public void handleBiz(ContractEvent payloadData, String eventContextKey) {
		if (payloadData.getContractCode() == null) {
			return;
		}
		LOGGER.info("变更合同用户确认,收到合同事件:{}", payloadData);
		Contract contract = contractService.getByContractCode(payloadData.getContractCode());
		if (Objects.isNull(contract)) {
			LOGGER.error("变更合同用户确认，不存在的合同:{}-[签约]", payloadData.getContractCode());
			return;
		}
		if (!ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType())) {
			return;
		}
		LOGGER.info("收到变更合同用户确认，开始处理，contractCode:{}", contract.getContractCode());
		ContractCollectionPlanRecord contractCollectionPlanRecord = contractCollectionPlanRecordService.selectOne(ContractCollectionPlanRecord.builder().contractCode(contract.getContractCode()).build());
		if (contractCollectionPlanRecord == null) {
			LOGGER.info("收到变更合同用户确认，未找到合同收款计划记录信息，不处理，contractCode:{}", contract.getContractCode());
			return;
		}
		CollectionPlanConfigInfo collectionPlanConfigInfo = JSON.parseObject(contractCollectionPlanRecord.getCollectionPlan(), CollectionPlanConfigInfo.class);
		CompletableFuture.runAsync(()-> {
			try {
				changeContractUserConfirmListenerSelf.saveCollectionPlan(collectionPlanConfigInfo,contract);
			} catch (Exception e) {
				LOGGER.error("变更合同用户确认,保存收款计划重试后依然失败,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		});
		LOGGER.info("变更合同用户确认,处理完毕，contractCode:{}", contract.getContractCode());
	}

	@Retryable(value = Exception.class, maxAttempts = 4, backoff = @Backoff(value = 1000, multiplier = 1))
	public void saveCollectionPlan(CollectionPlanConfigInfo collectionPlanConfigInfo, Contract contract) {
		try {
			LOGGER.info("变更合同用户确认,保存收款计划开始,contractCode:{}", contract.getContractCode());
			BigDecimal contractPrice = athenaRpc.queryPlanInfo(contract.getProjectOrderId()).getPlanInfo().getContractPriceTotal();
			fundBaseService.saveCollectionPlan(fundBaseService.calculateCollectionPlan(collectionPlanConfigInfo, contractPrice));
			LOGGER.info("变更合同用户确认,保存收款计划完成,contractCode:{}", contract.getContractCode());
		} catch (Exception e) {
			LOGGER.info("变更合同用户确认,保存收款计划失败,contractCode:{},收款计划:{}", contract.getContractCode(), JSON.toJSONString(collectionPlanConfigInfo), e);
			throw e;
		}
	}



}

