@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_COMPANY_SIGN, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class ContractCompanySealListener implements DomainEventHandler<ContractEvent> {

	@Resource
	private ContractService contractService;
	@Resource
	private LockService lockService;
	@Resource
	private EscrowRpc escrowRpc;
	@Resource
	private S3Service s3Service;
	@Resource
	private ContractConfigVersionService contractConfigVersionService;
	@Resource
	private ContractLogService contractLogService;
	@Resource
	private CommonBusinessService commonBusinessService;

	@Override
	public void handleBiz(ContractEvent payloadData, String eventContextKey) {
		String contractCode = payloadData.getContractCode();
		if (StringUtils.isBlank(contractCode)) {
			return;
		}
		Contract contract = contractService.getByContractCode(contractCode);
		if (Objects.isNull(contract)) {
			LOGGER.error("盖第三方章，不存在的合同:{}-[签约]", contractCode);
			return;
		}
		//不用第三方盖章的合同直接返回
		if (!ContractTypeEnum.NEED_THIRD_PARTY_SEAL_LIST.contains(contract.getType())) {
			return;
		}
		lockService.lockElseThrow(LockService.CONTRACT_THIRD_PART_SEAL_TYPE + contractCode, () -> {
			applyThirdPartSeal(contract);
			return null;
		});
	}

	/**
	 * 盖第三方章
	 * @param contract
	 */
	private void applyThirdPartSeal(Contract contract) {
		if (StringUtils.isBlank(contract.getBothSignedKey())) {
			LOGGER.error("盖第三方章, 合同未签署&盖章：{}", contract.getContractCode());
			return;
		}
		String convertProjectOrderId = commonBusinessService.convertProjectOrderId(contract.getProjectOrderId(), contract.getType());
		ContractVersionConfig contractVersion = contractConfigVersionService.queryContractConfigAllVersion(convertProjectOrderId);
		EscrowSignSealReqDTO escrowSignSealReqDTO = EscrowSignSealReqDTO.builder()
			.businessNo(contract.getProjectOrderId())
			.businessType(FundEscrowBusinessTypeEnum.DECORATE_PROJECT.getCode())
			.contractCode(contract.getContractCode())
			.fileUrl(s3Service.generateUrl(contract.getBothSignedKey(), 1800))
			.protocolVersion((contractVersion.getCityCompanyInfoConfigVersion() + String.valueOf(contractVersion.getModuleConfigVersion()) + contractVersion.getFieldConfigVersion()))
			.build();
		EscrowSignSealResDTO signSealResDTO = escrowRpc.escrowApplySeal(escrowSignSealReqDTO);
		if (signSealResDTO == null || !EscrowMsgStatusEnum.SEAL_SUCCESS.getCode().equals(signSealResDTO.getStatus())) {
			LOGGER.error("盖第三方章，调用存管盖章接口失败：{}", contract.getContractCode());
		}
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.THIRD_PART_SEAL.getCode(), LogTypeEnum.THIRD_PART_SEAL.getName());

	}

}

@Override
public void handleBiz(ContractEvent payloadData, String eventContextKey) {
