@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_USER_CONFIRM, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class ContractConfirmListener implements DomainEventHandler<ContractEvent> {

	@Resource
	CommonContractService commonContractService;

	@Resource
	HomeOrderOperationService homeOrderOperationService;

	@Resource
	ContractBusinessService contractBusinessService;

	@Override
	public void handleBiz(ContractEvent payloadData, String eventContextKey) {
		if (Objects.isNull(payloadData.getContractCode())) {
			return;
		}
		// 合同完结处理
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				commonContractService.contractFinishHandler(payloadData.getContractCode());
			} catch (Exception e) {
				LOGGER.error("合同完结处理发生异常,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		}));

		// 发送短信
		CompletableFuture.runAsync(() -> {
			try {
				commonContractService.sendContractSmsRemind(payloadData.getContractCode());
			} catch (Exception e) {
				LOGGER.error("合同签约完成发送短信发生异常,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		});

		// 正签&变更合同推送大表数据
		CompletableFuture.runAsync(RunnableWrapper.of(()-> {
			try {
				commonContractService.contractDataPushBigTable(payloadData.getContractCode());
			} catch (Exception e) {
				LOGGER.error("正签&变更合同推送大表数据发生异常,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		}));

		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				homeOrderOperationService.recordContractSignFinishNode(payloadData.getProjectOrderId(), payloadData.getContractCode());
			} catch (Exception e) {
				LOGGER.error("记录合同签署完成节点发生异常,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		}));

		//触发收款提醒延时消息
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				commonContractService.triggerContractRemindPayDelayMessage(payloadData.getContractCode());
			} catch (Exception e) {
				LOGGER.error("触发合同收款提醒延时消息发生异常,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		}));

		//触发设计费变化通知
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				contractBusinessService.recordDesignFeeChangeNode(payloadData.getContractCode(), payloadData.getTriggerTime());
			} catch (Exception e) {
				LOGGER.error("触发设计费变更通知节点发生异常", e);
			}
		}));

		//插入正式合同以及关联设计费合同均签署节点
		if (ContractTypeEnum.FORMAL_AND_DESIGN_CONTRACT_LIST.contains(payloadData.getType())) {
			CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				contractBusinessService.recordFormalBudgetDesignNode(payloadData.getProjectOrderId());
