@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_SUBMIT, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class ContractSubmitListener implements DomainEventHandler<ContractEvent> {

	@Resource
	private CommonContractService commonContractService;

	@Resource
	private ContractService contractService;

	@Resource
	private ContractCompanySignService contractCompanySignService;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Resource
	private LockService lockService;

	@Resource
	private RiskService riskService;

	@Resource
	private RiskBusinessReportService riskBusinessReportService;

	@Resource
	private AttachCommonService attachCommonService;
	@Resource
	private QuotationRelationCommonService quotationRelationCommonService;

	@Override
	public void handleBiz(ContractEvent payloadData, String eventContextKey) {
		if (Objects.isNull(payloadData.getContractCode())) {
			return;
		}
		// 合同完结处理
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				commonContractService.contractFinishHandler(payloadData.getContractCode());
			} catch (Exception e) {
				LOGGER.error("合同完结处理发生异常,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		}));

		// 团装2.5变更生成正签合同/销售合同触发风控
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				commonContractService.groupChangeToRiskAudit(payloadData.getContractCode());
			} catch (Exception e) {
				LOGGER.error("团装2.5变更生成正签合同/销售合同触发风控异常,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		}));

		Contract contract = contractService.getByContractCode(payloadData.getContractCode());

		// 销售合同发起时，尝试将协同报价单换绑至 S 单
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				quotationRelationCommonService.convertChangeToSubOrder(contract, contract.getChangeOrderId());
			} catch (Exception e) {
				LOGGER.error("销售合同关联关系绑定[合同发起时] ,ContractEvent: {}", JSON.toJSONString(payloadData), e);
			}
		}));

		// 销售合同发起时，尝试将变更单换绑至 S 单
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				quotationRelationCommonService.convertCooperBillToSubOrderByContract(contract);
			} catch (Exception e) {
				LOGGER.error("销售合同关联关系绑定[合同发起时] ,ContractEvent: {}", JSON.toJSONString(payloadData), e);
			}
		}));

		// 用户首次签署正签合同时间同步订单模型
		if (SignChannelTypeEnum.OFFLINE.getCode().equals(payloadData.getSignChannelType())) {
			commonContractService.userSignKeyTimeSyncNerveCenter(contract);
		}

		// 发起C合同如果原来的合同未签署需要作废原来的合同，开城后不作废合同
		if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()) && !contractApolloConfig.getCheckPersonalContract()) {
			cancelPersonalContracts(contract);
		}
		// 对公线上签署生成授权协议书
		String lockKey = "generate_accredit:" + LockService.PROJECT_ORDER_ID + contract.getProjectOrderId();
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				lockService.lockElseThrow(lockKey, () -> {
					contractCompanySignService.generateAccreditContract(contract);
					return null;
				}, 10000);
			} catch (Exception e) {
				LOGGER.error("对公线上签署生成授权协议书发生异常,合同信息:{}", JSON.toJSONString(contract), e);
			}
		}));

		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				commonContractService.verifyContractAttach(contract);
			} catch (Exception e) {
				LOGGER.error("异步计算备件准确性异常,合同信息:{}", JSON.toJSONString(contract), e);
			}
		}));

		// 风控策略
		if (ContractTypeEnum.NEED_RISK_TYPE_LIST.contains(payloadData.getType())) {
			String operatorUcId = contract.getModifyUserId();
			String contractName = ContractTypeEnum.getNameByCode(contract.getType());

			CompletableFuture.runAsync(RunnableWrapper.of(() -> {
				try {
					riskService.triggerRisk(RiskSceneEnum.CONTRACT_SUBMIT.getCode(), RiskTypeEnum.OFFLINE.getCode(), payloadData.getProjectOrderId(), payloadData, payloadData.getCreateUserId());

					AttachOcrResultExt attachOcrResultExt = attachCommonService.buildContractAttachOcrResult(contract.getProjectOrderId(), contract.getContractCode(), operatorUcId);
					if (attachOcrResultExt != null) {
						attachOcrResultExt.setScene(contractName);
						riskBusinessReportService.commonReport(CommonReportReqDTO.builder()
							.projectOrderId(contract.getProjectOrderId())
							.reportBusinessNo(contract.getContractCode())
							.reportType(RiskReportTypeEnum.ATTACH_OCR_RESULT.getCode())
							.reportData(attachOcrResultExt)
							.build());
					}
				} catch (Exception e) {
