@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_FINISH, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class SendMessageAfterAccreditFinish implements DomainEventHandler<ContractEvent> {

	@Resource
	ContractService contractService;
	@Resource
	ContractCompanySignService contractCompanySignService;
	@Resource
	CommonBusinessService commonBusinessService;
	@Resource
	private ContractUserService contractUserService;
	@Resource
	private ProjectInfoReadService projectInfoReadService;
	@Resource
	private CipherService cipherService;
	@Resource
	private ApolloConfigService apolloConfigService;
	@Resource
	private PayServiceRpc payServiceRpc;
	@Resource
	private HomeAndPcCommonService homeAndPcCommonService;


	@Override
	public void handleBiz(ContractEvent payloadData, String eventContextKey) {
		Contract accreditContract = contractService.getByContractCode(payloadData.getContractCode());
		if (!ContractTypeEnum.ACCREDIT.getCode().equals(accreditContract.getType())) {
			return;
		}
		Contract relContract = contractService.getRelContractByAccreditContractCode(accreditContract.getContractCode());
		if (relContract == null) {
			LOGGER.info("法人授权协议书签署完成，发送短信邀请签约人签署，关联合同不存在，ContractEvent:{}", JSON.toJSONString(payloadData));
			return;
		}
		CompletableFuture.runAsync(() -> {
			try {
				sendMessage(relContract);
			} catch (Exception e) {
				LOGGER.error("法人授权协议书签署完成，发送短信邀请签约人签署发生异常,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		});
	}

	private void sendMessage(Contract contract){
		LOGGER.info("【短信提醒】法人授权协议书签署完成，发送短信邀请签约人签署，开始发送短信,contract:{}", contract);
		MiniPayChannelAppNameEnum miniPayChannelAppNameEnum = commonBusinessService.getMiniProgramType(contract.getProjectOrderId());
		//获取项目信息
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(contract.getProjectOrderId());
		//获取手机号信息
		List<ContractUser> contractUsers = contractUserService.getListByContractCode(contract.getContractCode());
		ContractUser contractUser = contractUsers.stream().filter(m -> IsSignEnum.YES.getCode().equals(m.getIsSign())).findFirst().orElseThrow(() -> new RuntimeException("签约人不存在"));
		String phone = cipherService.decrypt(contractUser.getPhone());
		//获取短信模板
		String invitationToSignSMSTemplate = apolloConfigService.getInvitationToSignSMSTemplate(miniPayChannelAppNameEnum);
		//获取短链
		String urlLink = payServiceRpc.getUrlLink(ReminderScenarioTypeEnum.INVITATION_TO_SIGN.getValue(), miniPayChannelAppNameEnum.getMiniProgramType(), contract.getProjectOrderId());
		//获取短信动态字段
		Map<String, String> content = getContent(contract, projectInfoDTO, urlLink);
		//构建短信内容
		ReminderContextDTO reminderContextDTO = ReminderContextDTO.builder()
			.phone(phone)
			.content(content)
			.template(invitationToSignSMSTemplate)
			.source(Constant.DOMAIN_EVENT_SERVER_NAME)
			.build();
		//获取发送短信时项目快照信息
		BusinessSnapshotDTO businessSnapshotDTO = contractCompanySignService.getBusinessSnapshotDTO(contract, projectInfoDTO);
		//发送短信
		PaySignReminderCreateReqDTO paySignReminderCreateReqDTO = PaySignReminderCreateReqDTO.builder()
			.projectOrderId(contract.getProjectOrderId())
			.reminderType(ReminderTypeEnum.SMS.getValue())
			.scenarioType(ReminderScenarioTypeEnum.INVITATION_TO_SIGN.getValue())
			.reminderContext(JSON.toJSONString(reminderContextDTO))
			.businessSnapshot(JSON.toJSONString(businessSnapshotDTO))
			.reminderTime(new Date())
			.build();
		LOGGER.info("【短信提醒】法人授权协议书签署完成，发送短信邀请签约人签署，请求参数：{}", JSON.toJSONString(paySignReminderCreateReqDTO));
		payServiceRpc.sendSmsMessage(paySignReminderCreateReqDTO);
		LOGGER.info("【短信提醒】法人授权协议书签署完成，发送短信邀请签约人签署成功");
	}

	private Map<String, String> getContent(Contract relContract, ProjectInfoDTO projectInfoDTO, String urlLink) {
		Map<String, String> content = new HashMap<>();
		content.put("contractName", ContractTypeEnum.getNameByContractTypeAndBusinessType(relContract.getType(),relContract.getBusinessType()));
		content.put("address", homeAndPcCommonService.getEncryptedAddress(projectInfoDTO));
		content.put("jumpLink", urlLink);
		return content;
	}


}

