@Component
@Slf4j
@EventType(bizType = "utopia-athena-domain-entity-bizType", serverName = "utopia-athena")
public class ChangeBillSubmitListener implements DomainEventHandler<DomainEventDTO<KafkaMessageAthenaDomainEntityEventDTO>> {

	@Resource
	private PersonalRelationHandler personalRelationHandler;

	@Resource
	private ProductQueryService productQueryService;

	/**
	 * 监听变更报价单提交消息处理，处理逻辑：
	 * 1. 查询变更单对应的原始报价单，以及原始报价单对应的 S 单。
	 * 2. 解除原始报价单/原始报价单对应的 S 单与合同的关联。
	 * 解除关联目的：历史兼容逻辑，不清楚具体要兼容哪个场景。
	 * （可以排除一种场景：不是为了将涉及到变更的单据与合同解绑，以带出最新 pdf 数据。原因是协同报价单变更时，该协同报价单对应的合同一定是已经签约完成的，而这里撤回时只会处理未签约完成的合同）
	 */
	@Override
	public void handleBiz(DomainEventDTO<KafkaMessageAthenaDomainEntityEventDTO> payloadData, String eventContextKey) {
		KafkaMessageAthenaDomainEntityEventDTO event = payloadData.getPayloadData();
		// 仅处理变更报价单提交动作
		if (!isChangeBillSubmitAction(event)) return;
		LOGGER.info("处理变更报价单提交消息开始, payLoad: {}, eventContextKey: {}", JSON.toJSONString(payloadData), eventContextKey);

		String projectOrderId = event.getProjectOrderId();
		String projectChangeNo = event.getProjectChangeNo();

		// 1. 查询变更单对应原始报价单
		List<ChangeQuotationProductDTO> changeQuotationProductDTOS = productQueryService.getChangeQuotationProductDTOS(projectOrderId, projectChangeNo);
		if (CollectionUtil.isEmpty(changeQuotationProductDTOS)) {
			LOGGER.info("变更单对应商品信息为空，无需处理");
			return;
		}
		List<String> oldCooperBillCodes = changeQuotationProductDTOS.stream().map(ChangeQuotationProductDTO::getBillCode).collect(Collectors.toList());

		LOGGER.info("处理变更报价单提交消息, changeOrderId: {}, oldCooperBillCodes: {}", projectChangeNo, JSON.toJSONString(oldCooperBillCodes));
		// 2. 撤回原始报价单对应的合同
		if (CollectionUtil.isEmpty(oldCooperBillCodes)) {
			LOGGER.info("变更单对应原始报价单为空，无需处理");
			return;
		}
		for (String billCode : oldCooperBillCodes) {
			personalRelationHandler.revokeCooperQuotation(projectOrderId, billCode, event.getOperatorUcid());
		}

		LOGGER.info("处理变更报价单提交消息结束, payLoad: {}, eventContextKey: {}", JSON.toJSONString(payloadData), eventContextKey);
	}

	private boolean isChangeBillSubmitAction(KafkaMessageAthenaDomainEntityEventDTO event) {
		List<Integer> processableBillTypes = Arrays.asList(GeneralBillTypeEnum.CHANGE_STANDARD.getCode(), GeneralBillTypeEnum.CHANGE_COOPER.getCode());
		if (!processableBillTypes.contains(event.getGeneralBillType())) {
			return false;
		}
		if (!ObjectUtil.equal(GeneralBillStatusEnum.SUBMITTED.getCode(), event.getEntityStatus())) {
			return false;
		}
		return true;
	}


}

@Override
public void handleBiz(DomainEventDTO<KafkaMessageAthenaDomainEntityEventDTO> payloadData, String eventContextKey) {
	KafkaMessageAthenaDomainEntityEventDTO event = payloadData.getPayloadData();
	// 仅处理变更报价单提交动作
	if (!isChangeBillSubmitAction(event)) return;
	LOGGER.info("处理变更报价单提交消息开始, payLoad: {}, eventContextKey: {}", JSON.toJSONString(payloadData), eventContextKey);

	String projectOrderId = event.getProjectOrderId();
	String projectChangeNo = event.getProjectChangeNo();

	// 1. 查询变更单对应原始报价单
	List<ChangeQuotationProductDTO> changeQuotationProductDTOS = productQueryService.getChangeQuotationProductDTOS(projectOrderId, projectChangeNo);
	if (CollectionUtil.isEmpty(changeQuotationProductDTOS)) {
		LOGGER.info("变更单对应商品信息为空，无需处理");
		return;
	}
	List<String> oldCooperBillCodes = changeQuotationProductDTOS.stream().map(ChangeQuotationProductDTO::getBillCode).collect(Collectors.toList());

	LOGGER.info("处理变更报价单提交消息, changeOrderId: {}, oldCooperBillCodes: {}", projectChangeNo, JSON.toJSONString(oldCooperBillCodes));
	// 2. 撤回原始报价单对应的合同
	if (CollectionUtil.isEmpty(oldCooperBillCodes)) {
		LOGGER.info("变更单对应原始报价单为空，无需处理");
		return;
	}
	for (String billCode : oldCooperBillCodes) {
		personalRelationHandler.revokeCooperQuotation(projectOrderId, billCode, event.getOperatorUcid());
	}

	LOGGER.info("处理变更报价单提交消息结束, payLoad: {}, eventContextKey: {}", JSON.toJSONString(payloadData), eventContextKey);
}

private boolean isChangeBillSubmitAction(KafkaMessageAthenaDomainEntityEventDTO event) {
	List<Integer> processableBillTypes = Arrays.asList(GeneralBillTypeEnum.CHANGE_STANDARD.getCode(), GeneralBillTypeEnum.CHANGE_COOPER.getCode());
	if (!processableBillTypes.contains(event.getGeneralBillType())) {
		return false;
	}
	if (!ObjectUtil.equal(GeneralBillStatusEnum.SUBMITTED.getCode(), event.getEntityStatus())) {
		return false;
	}
	return true;
}

