@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.QUOTATION_CREATE_ORDER, serverName = DOMAIN_NRS_ORDER_SERVICE)
@Component
@Slf4j
public class BillToSubOrderListener implements DomainEventHandler<KafkaCommonPayload<KafkaExtDto>> {

	@Resource
	private AtomBudgetRpc atomBudgetRpc;
	@Resource
	private QuotationRelationCommonService quotationRelationCommonService;
	@Resource
	private ContractService contractService;

	/**
	 * 报价单换绑至 S 单
	 */
	@Override
	public void handleBiz(KafkaCommonPayload<KafkaExtDto> payloadData, String eventContextKey) {
		// 主单号
		String homeOrderNo = payloadData.getBody().getExt().getHomeOrderNo();
		// 报价单号
		String billCode = payloadData.getBody().getExt().getQuotationOrderNo();
		LOGGER.info("报价单换绑 S 单，开始处理，homeOrderNo={}, billCode={}", homeOrderNo, billCode);

		List<BudgetBillDTO.BillDTO> bills = atomBudgetRpc.queryBillsByBillCodes(Collections.singletonList(billCode));
		if (CollectionUtils.isEmpty(bills) || bills.size() != 1) {
			throw new NrsBusinessException(String.format("查询报价单结果异常, billCode: %s, bills: %s", billCode, JSON.toJSONString(bills)));
		}
		BudgetBillDTO.BillDTO toProcessBill = bills.get(0);

		List<Integer> cooperBillTypes = Arrays.asList(GeneralBillTypeEnum.BUDGET_COOPER.getCode(), GeneralBillTypeEnum.BUDGET_GROUP.getCode());

		List<Contract> validPersonalContracts = getValidPersonalContracts(homeOrderNo);
		if (CollectionUtil.isEmpty(validPersonalContracts)) {
			LOGGER.info("订单{}不存在已发起的销售合同", homeOrderNo);
			return;
		}

		if (cooperBillTypes.contains(toProcessBill.getBillType())) {
			// 协同报价单/团装报价单：尝试将协同报价单/团装报价单换绑至 S 单
			for (Contract contract : validPersonalContracts) {
				quotationRelationCommonService.convertCooperBillToSubOrderByContract(contract);
			}
		} else if (GeneralBillTypeEnum.BUDGET_STANDARD.getCode().equals(toProcessBill.getBillType())) {
			// 正签基础报价单：将基础报价单对应 S 单绑定至关联的销售合同
			for (Contract contract : validPersonalContracts) {
				quotationRelationCommonService.convertStandardBillToSubOrder(contract, billCode);
			}
		}
		LOGGER.info("报价单换绑 S 单，处理完成，homeOrderNo={}, billCode={}", homeOrderNo, billCode);
	}

	private List<Contract> getValidPersonalContracts(String homeOrderNo) {
		return contractService.getContractList(homeOrderNo).stream()
			.filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))
			.filter(contract -> ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus()))
			.collect(Collectors.toList());
	}
}

