bo/BindOrderInfo.java::BindOrderInfo.source_code:
@Getter
@AllArgsConstructor
@NoArgsConstructor
@Builder
@Slf4j
public class BindOrderInfo {

	// 主单号
	@NotBlank
	private String projectOrderId;

	// 要绑定的单据号 + 主体
	private Set<String> bindOrderNosWithCompany;

	// 要绑定的单据号
	@NotEmpty
	private List<String> bindOrderNoList;

	// 要绑定的单据类型
	@NotNull
	private Integer bindType;

	public static void main(String[] args) {
		BindOrderInfo build = BindOrderInfo.builder().build();
		System.out.println(JSON.toJSONString(build));
	}
	/**
	 * 一个流程内部变更单号只有一个，但是主体可能有多个（获取变更单号直接去第一条数据即可）
	 */
	public String getChangeOrderId() {
		if (CollectionUtil.isEmpty(bindOrderNoList) || bindOrderNoList.size() != 1) {
			LOGGER.info("bindOrderNoList: {}", JSON.toJSONString(bindOrderNoList));
			return "";
		}
		return bindOrderNoList.get(0);
	}

	/**
	 * 将报价单、S 单转换为 BindOrderInfo 统一处理
	 * 该方法目前上层调用的场景如下：
	 * 1. 销售合同发起/详情场景：入参只可能存在一种单据类型（报价单/S单/变更单）
	 * 2. 入参仅有子单号场景
	 * 需注意：正签合同 detail/submit 流程中，会同时基于基础报价单+S单签约，两种单据类型会同时存在，此时需要调用 BindOrderInfoGroup.convert() 方法转换为 List<BindOrderInfo>
	 */
	public static BindOrderInfo convert(String projectOrderId, List<SubOrderInfo> subOrderInfoList, List<BillCodeInfo> billCodeInfoList, List<ChangeOrderInfo> changeOrderInfoList) {
		// 要绑定的单据号 + 主体
		Set<String> toBindOrderWithCompany = new HashSet<>();
		// 要绑定的单据号
		List<String> toBindOrderList = new ArrayList<>();
		Integer bindType = -1;
		// 如果 S 单不为空，则合同与 S 单绑定
		if (CollectionUtil.isNotEmpty(subOrderInfoList)) {
			toBindOrderWithCompany = SubOrderInfo.concatOrderNoAndCompany(subOrderInfoList);
			toBindOrderList = SubOrderInfo.getSubOrderNos(subOrderInfoList);
			bindType = BindTypeEnum.SUB_ORDER.getCode();
		}

		else if (CollectionUtil.isNotEmpty(changeOrderInfoList)) { // 如果 S 单为空，则合同与变更单绑定
			toBindOrderWithCompany = ChangeOrderInfo.concatOrderNoAndCompany(changeOrderInfoList);
			toBindOrderList = ChangeOrderInfo.getChangeOrderNos(changeOrderInfoList);
			bindType = BindTypeEnum.CHANGE_ORDER.getCode();
		}

		else if (CollectionUtil.isNotEmpty(billCodeInfoList)) { // 如果 S 单和变更单都为空，则合同与报价单绑定
			toBindOrderWithCompany = BillCodeInfo.concatOrderNoAndCompany(billCodeInfoList);
			toBindOrderList = BillCodeInfo.getBillCodeList(billCodeInfoList);
			bindType = BindTypeEnum.BILL_CODE.getCode();
		}
		return BindOrderInfo.builder()
			.projectOrderId(projectOrderId)
			.bindOrderNosWithCompany(toBindOrderWithCompany)
			.bindOrderNoList(toBindOrderList)
			.bindType(bindType)
			.build();
	}

	/**
	 * 将报价单、S 单转换为 BindOrderInfo 统一处理
	 */
	public static BindOrderInfo convertWithoutCompanyCode(String projectOrderId, List<String> subOrderNoList, List<String> billCodeList, List<String> changeOrderIdList) {
		// 要绑定的单据号
		List<String> toBindOrderList = new ArrayList<>();
		Integer bindType = -1;
		// 如果 S 单不为空，则合同与 S 单绑定
		if (CollectionUtil.isNotEmpty(subOrderNoList)) {
			toBindOrderList = subOrderNoList;
			bindType = BindTypeEnum.SUB_ORDER.getCode();
		}

		else if (CollectionUtil.isNotEmpty(changeOrderIdList)) { // 如果 S 单为空，则合同与变更单绑定
			toBindOrderList = changeOrderIdList;
			bindType = BindTypeEnum.CHANGE_ORDER.getCode();
		}

		else if (CollectionUtil.isNotEmpty(billCodeList)) { // 如果 S 单和变更单都为空，则合同与报价单绑定
			toBindOrderList = billCodeList;
			bindType = BindTypeEnum.BILL_CODE.getCode();
		}

		toBindOrderList = toBindOrderList.stream().distinct().collect(Collectors.toList());

		return BindOrderInfo.builder()
			.projectOrderId(projectOrderId)
			.bindOrderNoList(toBindOrderList)
			.bindType(bindType)
			.build();
	}

	/**
	 * 正签发起场景，如果勾选了基础报价单 + S 单，则 List<ContractSourceDataBO.PersonalContractData> 会包含基础报价单的数据 + S 单的数据，这里需要转为 group
	 */
	public static BindOrderInfoGroup convert(String projectOrderId, List<ContractSourceDataBO.PersonalContractData> personalContractDataList) {
		List<SubOrderInfo> subOrderInfos = new ArrayList<>();
		List<BillCodeInfo> billCodeInfos = new ArrayList<>();
		List<ChangeOrderInfo> changeOrderInfos = new ArrayList<>();

		Optional.ofNullable(personalContractDataList).orElse(Collections.emptyList()).forEach(
			personalContractData ->  {
				BindOrderInfo bindOrderInfo = convert(projectOrderId, personalContractData);
				subOrderInfos.addAll(bindOrderInfo.getSubOrderInfoList());
				billCodeInfos.addAll(bindOrderInfo.getBillCodeInfoList());
				changeOrderInfos.addAll(bindOrderInfo.getChangeOrderInfoList());
			}
		);
		return BindOrderInfoGroup.builder()
				.projectOrderId(projectOrderId)
				.subOrderInfos(subOrderInfos)
				.billCodeInfos(billCodeInfos)
				.changeOrderInfos(changeOrderInfos)
				.build();
	}

	public static BindOrderInfo convert(String projectOrderId, ContractSourceDataBO.PersonalContractData personalContractData) {
		List<SubOrderInfo> subOrderInfos = new ArrayList<>();
		List<BillCodeInfo> billCodeInfos = new ArrayList<>();
		List<ChangeOrderInfo> changeOrderInfos = new ArrayList<>();

		String companyCode = personalContractData.getOrganizationCode();
		if (CollectionUtil.isNotEmpty(personalContractData.getSubOrderNoList())) {
			personalContractData.getSubOrderNoList().forEach(
				subOrderNo -> subOrderInfos.add(SubOrderInfo.builder().subOrderNo(subOrderNo).companyCode(companyCode).build())
			);
		}
		if (StringUtils.isNotBlank(personalContractData.getBillCode())) {
			billCodeInfos.add(BillCodeInfo.builder().billCode(personalContractData.getBillCode()).companyCode(companyCode).build());
		}
		if (StringUtils.isNotBlank(personalContractData.getChangeOrderId())) {
			changeOrderInfos.add(StringUtils.isNotBlank(personalContractData.getChangeOrderId()) ? ChangeOrderInfo.builder().changeOrderId(personalContractData.getChangeOrderId()).companyCode(companyCode).build() : null);
		}
		return convert(projectOrderId, subOrderInfos, billCodeInfos, changeOrderInfos);
	}

	/**
	 * 获取报价单信息列表
	 */
	public List<BillCodeInfo> getBillCodeInfoList() {
		if (!BindTypeEnum.BILL_CODE.getCode().equals(bindType)) {
			return Collections.emptyList();
		}

		if (CollectionUtil.isEmpty(bindOrderNosWithCompany)) {
			return Collections.emptyList();
		}

		return bindOrderNosWithCompany.stream()
				.map(orderNo -> {
					String[] parts = orderNo.split("_");
					return BillCodeInfo.builder()
							.billCode(parts[0])
							.companyCode(parts[1])
							.build();
				})
				.collect(Collectors.toList());
	}

	/**
	 * 获取变更单信息列表
	 */
	public List<ChangeOrderInfo> getChangeOrderInfoList() {
		if (!BindTypeEnum.CHANGE_ORDER.getCode().equals(bindType)) {
			return Collections.emptyList();
		}

		if (CollectionUtil.isEmpty(bindOrderNosWithCompany)) {
			return Collections.emptyList();
		}

		return bindOrderNosWithCompany.stream()
				.map(orderNo -> {
					String[] parts = orderNo.split("_");
					return ChangeOrderInfo.builder()
							.changeOrderId(parts[0])
							.companyCode(parts[1])
							.build();
				})
				.collect(Collectors.toList());
	}

	/**
	 * 获取子单信息列表
	 */
	public List<SubOrderInfo> getSubOrderInfoList() {
		if (!BindTypeEnum.SUB_ORDER.getCode().equals(bindType)) {
			return Collections.emptyList();
		}

		if (CollectionUtil.isEmpty(bindOrderNosWithCompany)) {
			return Collections.emptyList();
		}

		return bindOrderNosWithCompany.stream()
				.map(orderNo -> {
					String[] parts = orderNo.split("_");
					return SubOrderInfo.builder()
							.subOrderNo(parts[0])
							.companyCode(parts[1])
							.build();
				})
				.collect(Collectors.toList());
	}

}

