bo/BindOrderInfoGroup.java::BindOrderInf.source_code:
@Getter
@AllArgsConstructor
@NoArgsConstructor
@Builder
public class BindOrderInfoGroup {

	private String projectOrderId;

	private List<BillCodeInfo> billCodeInfos = new ArrayList<>();

	private List<SubOrderInfo> subOrderInfos = new ArrayList<>();

	private List<ChangeOrderInfo> changeOrderInfos = new ArrayList<>();

	/**
	 * 默认空对象
	 */
	private static final BindOrderInfoGroup EMPTY = BindOrderInfoGroup.builder()
			.billCodeInfos(Collections.emptyList())
			.subOrderInfos(Collections.emptyList())
			.changeOrderInfos(Collections.emptyList())
			.build();

	public List<BindOrderInfo> getBindOrderInfos() {
		BindOrderInfo subBindOrderInfo = BindOrderInfo.convert(projectOrderId, subOrderInfos, null, null);
		BindOrderInfo billBindOrderInfo = BindOrderInfo.convert(projectOrderId, null, billCodeInfos, null);
		BindOrderInfo changeBindOrderInfo = BindOrderInfo.convert(projectOrderId, null, null, changeOrderInfos);
		return Stream.of(subBindOrderInfo, billBindOrderInfo, changeBindOrderInfo).filter(bindOrderInfo -> -1 != bindOrderInfo.getBindType()).collect(Collectors.toList());
	}

	public List<String> getTotalBindOrderNos() {
		return getBindOrderInfos().stream().flatMap(bindOrderInfo -> bindOrderInfo.getBindOrderNoList().stream()).collect(Collectors.toList());
	}

	public static BindOrderInfoGroup convert(String projectOrderId, List<SubOrderInfo> subOrderInfos, List<BillCodeInfo> billCodeInfos, List<ChangeOrderInfo> changeOrderInfos) {
		return BindOrderInfoGroup.builder().projectOrderId(projectOrderId).billCodeInfos(billCodeInfos).subOrderInfos(subOrderInfos).changeOrderInfos(changeOrderInfos).build();
	}

	public static BindOrderInfoGroup convert(String projectOrderId, List<ContractQuotationRelation> contractQuotationRelations) {
		if (CollectionUtils.isEmpty(contractQuotationRelations)) {
			return EMPTY;
		}
		List<BillCodeInfo> billCodeInfos = new ArrayList<>();
		List<SubOrderInfo> subOrderInfos = new ArrayList<>();
		List<ChangeOrderInfo> changeOrderInfos = new ArrayList<>();
 		for (ContractQuotationRelation relation : contractQuotationRelations) {
			String bindOrderNo = relation.getBillCode();
			Integer bindType = relation.getBindType();
			String companyCode = relation.getCompanyCode();
			if (BindTypeEnum.BILL_CODE.getCode().equals(bindType)) {
				billCodeInfos.add(BillCodeInfo.builder().billCode(bindOrderNo).companyCode(companyCode).build());
			} else if (BindTypeEnum.CHANGE_ORDER.getCode().equals(bindType)) {
				changeOrderInfos.add(ChangeOrderInfo.builder().changeOrderId(bindOrderNo).companyCode(companyCode).build());
			} else if (BindTypeEnum.SUB_ORDER.getCode().equals(bindType)) {
				subOrderInfos.add(SubOrderInfo.builder().subOrderNo(bindOrderNo).companyCode(companyCode).build());
			}
		}
		return convert(projectOrderId, subOrderInfos, billCodeInfos, changeOrderInfos);
	}

	public static BindOrderInfoGroup convert(String projectOrderId, BusinessInfoDetail businessInfo) {
		List<BillCodeInfo> billCodeInfos = Optional.ofNullable(businessInfo).map(BusinessInfoDetail::getBillCodeInfoList).orElse(Collections.emptyList());
		List<SubOrderInfo> subOrderInfos = Optional.ofNullable(businessInfo).map(BusinessInfoDetail::getSubOrderInfoList).orElse(Collections.emptyList());
		List<ChangeOrderInfo> changeOrderInfos = Optional.ofNullable(businessInfo).map(BusinessInfoDetail::getChangeOrderInfoList).orElse(Collections.emptyList());
		return convert(projectOrderId, subOrderInfos, billCodeInfos, changeOrderInfos);
	}

	public static BindOrderInfoGroup convert(String projectOrderId, ContractField subOrderInfoListField, ContractField billCodeInfoListField, ContractField changeOrderInfoListField) {
		List<BillCodeInfo> billCodeInfos = ContractFieldHandler.parseFieldToList(billCodeInfoListField, BillCodeInfo.class);
		List<SubOrderInfo> subOrderInfos = ContractFieldHandler.parseFieldToList(subOrderInfoListField, SubOrderInfo.class);
		List<ChangeOrderInfo> changeOrderInfos = ContractFieldHandler.parseFieldToList(changeOrderInfoListField, ChangeOrderInfo.class);
		return BindOrderInfoGroup.convert(projectOrderId, subOrderInfos, billCodeInfos, changeOrderInfos);
	}
}

public List<BindOrderInfo> getBindOrderInfos() {
	BindOrderInfo subBindOrderInfo = BindOrderInfo.convert(projectOrderId, subOrderInfos, null, null);
	BindOrderInfo billBindOrderInfo = BindOrderInfo.convert(projectOrderId, null, billCodeInfos, null);
	BindOrderInfo changeBindOrderInfo = BindOrderInfo.convert(projectOrderId, null, null, changeOrderInfos);
	return Stream.of(subBindOrderInfo, billBindOrderInfo, changeBindOrderInfo).filter(bindOrderInfo -> -1 != bindOrderInfo.getBindType()).collect(Collectors.toList());
}

public static BindOrderInfoGroup convert(String projectOrderId, ContractField subOrderInfoListField, ContractField billCodeInfoListField, ContractField changeOrderInfoListField) {
	List<BillCodeInfo> billCodeInfos = ContractFieldHandler.parseFieldToList(billCodeInfoListField, BillCodeInfo.class);
	List<SubOrderInfo> subOrderInfos = ContractFieldHandler.parseFieldToList(subOrderInfoListField, SubOrderInfo.class);
	List<ChangeOrderInfo> changeOrderInfos = ContractFieldHandler.parseFieldToList(changeOrderInfoListField, ChangeOrderInfo.class);
	return BindOrderInfoGroup.convert(projectOrderId, subOrderInfos, billCodeInfos, changeOrderInfos);
}

