public static List<SignableOrderInfo> buildSignableSubOrderInfo(List<SubOrderBaseInfoDTO> signableSubOrderBaseInfos, PrerequisitesData prerequisitesData) {
	// 组装返回信息
	Map<String, List<SignableOrderInfo>> groupedByPackage = new LinkedHashMap<>();
	// 是否是团装2.5，如果是团装2.5的S单全部必选，mustSelect设为true
	Boolean isProcessV25Group = prerequisitesData.getGroupV25();
	// 分离空值和非空值
	List<SignableOrderInfo> emptyPackageOrders = new ArrayList<>();
	for (SubOrderBaseInfoDTO subOrderBaseInfo : signableSubOrderBaseInfos) {
		String subOrderNo = subOrderBaseInfo.getOrderNo();
		String companyCode = subOrderBaseInfo.getMdmCode();
		String companyName = Optional.ofNullable(prerequisitesData.getCompanyInfoMapByCompanyCode().get(companyCode)).map(MdmDTO::getCompanyName).orElse("");
		String goodsInfo = prerequisitesData.getGoodsInfoByOrderNo().get(subOrderBaseInfo.getOrderNo());
		String packageInstanceName = prerequisitesData.getPackageNameByOrderNo().get(subOrderNo);

		SignableOrderInfo orderInfo = SignableOrderInfo.builder()
			.companyCode(companyCode)
			.companyName(companyName)
			.bindCode(subOrderNo)
			.bindType(BindTypeEnum.SUB_ORDER.getCode())
			.orderAmount(subOrderBaseInfo.getDueAmount())
			.orderCreateTime(DateUtil.format(subOrderBaseInfo.getOrderCreateTime(), "yyyy-MM-dd HH:mm:ss"))
			.goodsInfo(goodsInfo)
			.packageInstanceName(packageInstanceName)
			.mustSelect(isProcessV25Group)
			.build();

		// 空值单独存储，非空值按 packageInstanceName 分组
		if (StringUtils.isBlank(packageInstanceName)) {
			emptyPackageOrders.add(orderInfo);
		} else {
			groupedByPackage.computeIfAbsent(packageInstanceName, k -> new ArrayList<>()).add(orderInfo);
		}

	}

	// 聚合非空数据
	List<SignableOrderInfo> result = new ArrayList<>();
	groupedByPackage.forEach((packageName, orderList) -> {
		if (orderList.size() == 1) {
			result.add(orderList.get(0));
		} else {
			orderList.sort(Comparator.comparing(SignableOrderInfo::getOrderCreateTime));
			SignableOrderInfo first = orderList.get(0);

			BigDecimal totalAmount = orderList.stream()
				.map(SignableOrderInfo::getOrderAmount)
				.reduce(BigDecimal.ZERO, BigDecimal::add);

			String combinedBindCode = orderList.stream()
				.map(SignableOrderInfo::getBindCode)
				.collect(Collectors.joining(","));

			result.add(SignableOrderInfo.builder()
				.companyCode(first.getCompanyCode())
				.companyName(first.getCompanyName())
				.bindCode(combinedBindCode)
				.bindType(first.getBindType())
				.orderAmount(totalAmount)
				.orderCreateTime(first.getOrderCreateTime())
				.goodsInfo(packageName)
				.packageInstanceName(packageName)
				.mustSelect(isProcessV25Group)
				.build());
		}
	});

	// 添加空值数据
	result.addAll(emptyPackageOrders);

	return result;
}

public static SignableOrderInfo buildSignableBillOrderInfo(ContractSourceDataBO.PersonalContractData personalContractData, PrerequisitesData prerequisitesData) {
	String goodsInfo = prerequisitesData.getGoodsInfoByOrderNo().get(personalContractData.getBillCode());
	return SignableOrderInfo.builder()
		.companyName(personalContractData.getOrganizationName())
		.companyCode(personalContractData.getOrganizationCode())
		.mustSelect(true)
		.bindCode(personalContractData.getBillCode())
		.bindType(BindTypeEnum.BILL_CODE.getCode())
		.goodsInfo(goodsInfo)
		.orderAmount(personalContractData.getPersonalContractPrice())
		.orderCreateTime(personalContractData.getCreateTime())
		.build();
}

